INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göç-eren hepsi', 'goc-eren-hepsi-akin-akca-3bap0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '‘Göç-eren duvar’ 

hayaloldu: 

Daha ne istiyor gerçeklik? 

: Bir hayalle başladı, 

Jules; 

Ay''a seyahatine! 

A Voyage. 

just a voyage... 

but reality''s, always 

in a cottage! ! ! 

Tuğla oldu 

kırmızı 

kiremitler 

ve kah; 

kırmızı kiremitler, 

tuğlalar... 

buğralar, 

iki hörgüçlü erkek develer! 

tuğralar! ! 

Uçuveren! 

Dalan! 

Göç-eren... 

yerleşiyorken, 

tarım yaparken... 

Bu duvar, 

göçeriyorken 

hep inşa etti. 

Her şeyin aslı 

aynı: Güneş''in, 

beyazı-sarısı... 

fazlasından:

ışın yağmuru,

sokak lambaları altındaki

ve onun huzmesi

.. Bulmak arayı, 

geçmek dereyi, 

deredeki çayı … 

İkisinin 

arası … 

İncik ile boncuk 

güzel süslüyor 

kolyeyi! 

değil mi... 

Yılmayışında 

kendi kaybetti. 

Ve hep 

kendi kazandı; 

Duvar yıktığında kendini, 

yeniden inşa etti; 

inşa! ! 

… Tütsü 

ve ökseotu; 

korunumu yasası 

sevginin 

gereği...', '‘Göç-eren duvar’  hayaloldu:  Daha ne istiyor gerçeklik?  : Bir hayalle başladı,  Jules;  Ay''a seyahatine!  A Voyage.  just a voyage...  but...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/goc-eren-hepsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıymetini Bil', 'kiymetini-bil-tayyip-sag-dvy3n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dost olmak, can olmak çok kolay değil,

Ben sana dost dedim kıymetini bil,

Dostluk deryasında sahte bir sahil,

Olursan uğramam kıymetini bil.

Yalanlar bozmasın dostluk sihrini,

Kara günde göster dosta sevgini,

Dosta yardım için uzat elini,

Dostluk vefa ister kıymetini bil.

Menfaatsiz olur dostun sevgisi,

Gönüle vurulur dost kelepçesi,

Yıkılmaz bir taşla dostun kalesi,

Kale gibi dost ol kıymetini bil.

Tayyip der ki dost bir sırdır bilinmez,

Nerde vardır nerde yoktur görünmez,

Dostun pahasına kıymet biçilmez,

Dost demişsem sana kıymetini bil.

          17.05.2004', 'Dost olmak, can olmak çok kolay değil, Ben sana dost dedim kıymetini bil, Dostluk deryasında sahte bir sahil, Olursan uğramam kıymetini bil....', ARRAY['Türk Edebiyatı','Şiir','Tayyip Sağ']::text[], 8.5, '{"poet":"Tayyip Sağ","poet_slug":"tayyip-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kiymetini-bil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Bülbül', 'gul-bulbul-aynur-baydar-u1255', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bülbül güle yandı

Gül bülbüle

Tanımadan bülbül  gülünü

Aşık oldu diğer çiçeklere

Aşık oldu şakıdı

Yoktu dikenleri, 

Canı yanmadı

Gülü gördü, dikenli

Başı döndü, dikeni battı

Meğer 

Diken gerçeklermiş

Diğer çiçekler 

Boş hayalmiş

Güzellikleri 

Gelip geçiciymiş

Solsa bile 

Gülü hep güzelmiş

O gül ki 

Ümmetini...

Tüm anaların şaekatinden

Çok sevenmiş

Gülün dikenleri

Bülbülün... 

Günahlarını simgelermiş

Gül dikenleriyle 

Bülbülü gerçek sevenmiş

Bir sürü dikenimize rağmen

Çokça günahlarımıza 

Devam ederken

Yaramazıs

Şefkatine sığınanız

Topal karınca olup, 

Yarım yamalak

Sözlerine uymaya çalışanız

Arsızca şefaatini umarız

Geriden gelsek de 

Sakın dönme gül yüzünü bize

Biliriz senden gayrı 

Aşk yar, yok bize

Kime gideriz söyle

Feryat figan bizde

Söyle gülüm söyle

Şefaat edeceğim de', 'Bülbül güle yandı Gül bülbüle Tanımadan bülbül  gülünü Aşık oldu diğer çiçeklere Aşık oldu şakıdı Yoktu dikenleri,  Canı yanmadı Gülü gördü,...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/gul-bulbul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Eski günler*', 'eski-gunler-i-lkgul-celebioglu-isjyk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eskileri andım bugün

aklıma geldi tebessümlere karıştı yüzüm

ne günlerdi eskiler dedim kendi kendime

Eski ramazanları da hatırladım birden

ve bayramları

Eskiden; Bayram günleri babannemlerde olurduk

Amcamlar bayram namazından sonra gelirlerdi de

Biz çocuklar el öper bayram harçlıklarımızı alırdık

sonra; 

Hep beraber bayram kahvaltısı yapılırdı

Şimdi yok o eski günler; 

Dedem rahmetlik olduktan sonra değişti düzen

Eskiden dedem akşamları bizi erkenten uyuturdu

Sabah erkenden kaldırır dı da birlikte bahçeye giderdik

Dedem ekinleri ile uğraşır

bize de iki ağaç arasında kalın urgan dan salıncak yapardı

Kuş cıvıltıları arasında uyurdum

Annemin hadi yemeğe gelin sesi ile uyandırırdı dedem beni

Sırtına alırdı giderdik eve.....

Babannemin bahçeden topladığı mısırları 

közde kızartırda yerdik

şimdi kokusu tütüyor burnumda

Kışlık odun için ormana giderdik 

Hayvanlara kışlık  için

ormandan yaprak süpürürdük

Çay kırar fındık toplardık

Ne günlerdi eski günler

Şimdi eski günlerde yok

Dedem de.......', 'Eskileri andım bugün aklıma geldi tebessümlere karıştı yüzüm ne günlerdi eskiler dedim kendi kendime Eski ramazanları da hatırladım birden v...', ARRAY['Türk Edebiyatı','Şiir','İlkgül Çelebioğlu']::text[], 8.5, '{"poet":"İlkgül Çelebioğlu","poet_slug":"i-lkgul-celebioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/eski-gunler-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nişancı İle Tengiz', 'nisanci-i-le-tengiz-hakki-hakan-kaya-gcf6j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vakt-i zamanın birinde

kadı olmuş bizim hoca

önünde kalın bir kitap

up uzun beyaz sakalı

önüne geçermiş hocanın

cümle davacı davalı

nişancı ile tengiz de

ayrı düşmüşler bir konuda

anlaşamayınca çıkmışlar kürsüye

vardır elbet çaresi hocada

davalı nişancı anlatmış derdini

hoca sakalını sıvazlamış

şöyle bir gerinmiş yerinde

''''Haklısın'''' demiş,

davacı tengiz atılmış hemen

hocam nasıl olur

birde beni dinleyin 

sonra tekrar karar verin

davacı tengiz anlatmış derdini

hoca sakalını sıvazlamış

şöyle bir gerinmiş yerinde

''''sende haklısın'''' demiş

hemen atılmış Arif efendi

bu iş nasıldır

hocam bir davada

sadece bir haklı olur

hoca kaşlarını kaldırmış

beyaz sakalını sıvazlamış

Arif efendiye dönüp

''''valla sende haklısın'''' demiş...

 :)   :)   :)   :)   :)   :)   :)   :)   :)   :)   :)', 'Vakt-i zamanın birinde kadı olmuş bizim hoca önünde kalın bir kitap up uzun beyaz sakalı önüne geçermiş hocanın cümle davacı davalı nişancı ...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/nisanci-ile-tengiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kınalı Yapıncak', 'kinali-yapincak-ahmet-turan-altunsu-qo3pg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ah be kınalı yapıncak,

ne yapacağım seni ben? 

nasıl kurtulacağım bu tuhaf görüntüden? 

yapabilseydim eğer; 

…..gemileri yakardım,

aramızdaki 

…..bütün 

……….köprüleri 

…………...yıkardım! 

fakat, olmaz yapıncak:

böyle güzel bağları, 

…..despotlar koparır ancak! 

ben duygu insanıyım; 

duygularım salıncak! ..

salın salınabildiğince,

sallan sallanabildiğince,

kullan kullanabildiğince; 

yeter ki olmayalım elaleme oyuncak! ..

he mi gurban, 

…..he mi kınalı yapıncak, 

……….he mi nevo,

he mi ho? 

                                

                                 18.08.2004 / Ankara', 'ah be kınalı yapıncak, ne yapacağım seni ben?  nasıl kurtulacağım bu tuhaf görüntüden?  yapabilseydim eğer;  …..gemileri yakardım, aramızdak...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kinali-yapincak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temennim', 'temennim-bayram-tunca-7dq2m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ya bekleyen, ya da beklenen olmak isterdim

Bekler veya beklenirken, hep onu düşlerdim

Katiyen beklenmeyen biri olmak istemezdim

İstenmeyen biri olmaktansa, ölmek isterdim

25.10.2004-10.25', 'Ya bekleyen, ya da beklenen olmak isterdim Bekler veya beklenirken, hep onu düşlerdim Katiyen beklenmeyen biri olmak istemezdim İstenmeyen b...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/temennim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorduğumda...', 'sordugumda-selim-bayrak-5ibam', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sorduğumda (!) 

Yoktun yanımda

Daha ilk cümlede susuverdi

Kırık ayna

İlkleri değil 

Sonları yaşadım

Her nefesini duyuşumda

Titreyen bedenimi geremedim

O ötelenmiş bakışlarında

Gördüğünü görmek istemedim

Sorduğunda (!) 

Yoktum yanında

Başladığım bitiremediğim...', 'Sorduğumda (!)  Yoktun yanımda Daha ilk cümlede susuverdi Kırık ayna İlkleri değil  Sonları yaşadım Her nefesini duyuşumda Titreyen bedenimi...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sordugumda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Viran Olur', 'gun-viran-olur-huseyin-sigirtmac-0wnjc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duyguma matemdir ayrılık hissi.

Yüreğe işledi çekerim yası.

Gönlümün feryadı kesmeden sesi.

Dünyadan geçerim han viran olur.

Bülbülün nağmesi gülün aşkına.

Dost hayali kondu gönül köşküne.

Sevgine güvenip düştüm peşine.

Sensiz ruhum söner can viran olur.

Umutlar kurudu yeşermez artık.

Yaşamı sürmeye gam oldu ortak.

Deryanın bağrında Sığırtmaç kurak.

Kararan duygumla gün viran olur.', 'Duyguma matemdir ayrılık hissi. Yüreğe işledi çekerim yası. Gönlümün feryadı kesmeden sesi. Dünyadan geçerim han viran olur. Bülbülün nağmes...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gun-viran-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anacığım', 'anacigim-adulera-ayza-rvgl6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu çiçekler sana

Anacığım

Her biri farklı bir

Anlatım

Bu çiçekler senin

Sarı beni her zaman 

Affettiğin için

Kırmızı beni her zaman

Sevdiğin için

Pembe beni her zaman

Kokladığın için

Beyaz beni her zaman

Düşündüğün için

Bu çiçekler sana anacığım

Her biri farlı bir 

Anlatım

Bu çiçekler senin anacığım

Bana bir dünya yarattığın

İçin', 'Bu çiçekler sana Anacığım Her biri farklı bir Anlatım Bu çiçekler senin Sarı beni her zaman  Affettiğin için Kırmızı beni her zaman Sevdiğin...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/anacigim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fahriye Abla', 'fahriye-abla-adulera-ayza-4v4oy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Erzincanda mısın  bilemem ama

Hakikaten unutamadım seni

Fahriye abla

Ben seni severek büyüdüm

Aşıktım her zaman sana

İlk seni gördüm

Adını bilmediğim şiir kitaplarında

Cam silişin yürüyüşün  endamın

Silinmedi hala hafızamda

Her nere de isen

Bir haber yolla

Ne şirin komşumuzdun sen 

Fahriye abla', 'Erzincanda mısın  bilemem ama Hakikaten unutamadım seni Fahriye abla Ben seni severek büyüdüm Aşıktım her zaman sana İlk seni gördüm Adını b...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/fahriye-abla-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ar Mahkemede', 'ar-mahkemede-aynur-baydar-6npnc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hakim gürlemiş

Suçlu ar 

Ayağa kalk

Görevini yapmamışsın

İnsanları bırakmışsın

Toplum senin yüzünden

Ne halde

Rüşvet, soygun, tecavüz, yalan

Kol geziyor her yerde

Bunlar olurken sen nerede

Ar boynunu bükmüş

Efendim, çocukları tanıştırmadılar benimle

Bilmedikleri arı niye dinlesinler 

Tanıyan gençleri bile utanmasınlar

Toplumda ezilmesinler

Yüzleri kızarmasın diye

Aileleri götürdüler terapiye

Haksızken, haklı çıkmak için

Daha çok bağıracaksın

Her şeyi mübah görecek ve alacaksın

Gerekiyorsa yalan söyleyecek

Olmazsa acımadan ezeceksin

İnsanlar beni tanımıyor

Egolarına tapıyor 

Arı yanlarına yaklaştırmıyor

İtilip kakılmaktan 

Ben bile, beni unuttum

Tanıdıklarıma gelince

Kimisi tımarhane de

Kimisi hastahane de

Şanslı olanları yaşarken hep ezilmekte

İşte hakim bey böyle 

İdamımı istiyorum

Yoldaşım insanların çektiklerinden

Utanıyorum

Yok olursam hiç olmazsa iyiler rahat eder

Hakim 

Ar ağzından çıkanı kulağın duyuyor mu 

Sen olmadan iyi olur mu

Yaz kızım 

Arın suçsuz olduğuna

Arsızın tutuklanmasına ve müebbetine

Karar verilmiştir', 'Hakim gürlemiş Suçlu ar  Ayağa kalk Görevini yapmamışsın İnsanları bırakmışsın Toplum senin yüzünden Ne halde Rüşvet, soygun, tecavüz, yalan...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/ar-mahkemede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynadaki Yabancı', 'aynadaki-yabanci-mehmet-salim-erdal-dxpgg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aynadaki yabancı söyle bana bu ben miyim

Nerde o neşeli çocuk,

Nerde şefkatli anne..

Okyanuslar kurumuş,

Bir damla su bile yok

Gökyüzü yıldızlarını

Karanlıklar basmış..... 

Ben yaşamın kölesi,

Yaşam benim kölem,

Sendeleyip giderken zararsız,

Köhne bir bar köşesinde

2 duble rakıya satılmışım habersiz... 

Keşke tacir olsaydı satan…

Elim, kolum,bacağım,

beynim, canım, ciğerim, 

benim herşeyim  olmasaydı...

Mahkum etseydi idama.

Derdim vur cellat bitir işi..

Yaşamaya cesaret gerek,

Atmak istemiyor bu yürek...', 'Aynadaki yabancı söyle bana bu ben miyim Nerde o neşeli çocuk, Nerde şefkatli anne.. Okyanuslar kurumuş, Bir damla su bile yok Gökyüzü yıldı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Salim Erdal']::text[], 8.5, '{"poet":"Mehmet Salim Erdal","poet_slug":"mehmet-salim-erdal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aynadaki-yabanci-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Ektim', 'hasret-ektim-ahmet-kurt-4spy5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu gönlümün çorağına

Hasret ektim gurbet biçtim.

Hanlarına, durağına,

Hasret ektim gurbet biçtim.

Yürek, yüzden ayrı düştü,

Gözden yere yaşlar düştü,

El yoruldu, ayak şişti,

Hasret ektim gurbet biçtim.

Tarla güzel, bostan güzel,

Yar yolunda yollar güzel,

Saçlarıma düşsün gazel,

Hasret ektim gurbet biçtim.

Kurdoğlu bir garip yolcu,

Elde değnek, sırtta hurcu,

Sıla tüter burcu burcu,

Hasret ektim gurbet biçtim.', 'Şu gönlümün çorağına Hasret ektim gurbet biçtim. Hanlarına, durağına, Hasret ektim gurbet biçtim. Yürek, yüzden ayrı düştü, Gözden yere yaşl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hasret-ektim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '- A k r e p...v e...Y e l k o v a n....(7)', 'a-k-r-e-p-v-e-y-e-l-k-o-v-a-n-7-metin-eser-llhi8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biraz korku sarmıştı, kimsesiz bedenini, 

Ya kime soracaktı, bunların nedenini, 

Etrafında bir duvar, aşılmaz dağa dönmüş, 

Hayat yolu denilen, gidilmesi zor yönmüş. 

Öyle bir durumda ki, karar vermek imkânsız, 

Ve dahi bir evi yok, ikâmeti mekânsız, 

Aklında düşünceler, kolkola verir amma, 

Doğru karar hangisi, işte bu da muamma. 

Gecenin tik takları, birbirini izliyor, 

Yarının esrarını, sarmalayıp gizliyor, 

Uyku zaten firarî, heyecanı tetikte, 

Bilinmeyen çareyle, mahzun efkâr yitikte. 

Karanlığın körlüğü, geceye sinmiş idi, 

El ayak çekilince, tüm asvat dinmiş idi, 

Odanın kapısını, bir el usulca açtı, 

Bizimki ihtiyatla, öbür köşeye kaçtı. 

Az sonra anladı ki, hemşire imiş meğer, 

Akla bir fikir düştü, denemeye de değer, 

Ve telaşla dedi ki, ''lütfen biraz kalınız'', 

''Olabilirse eğer, beni burdan alınız.'' 

Kadın önce dinledi, sonra kabul etmedi, 

Adam ne söylediyse, iknaya da yetmedi, 

Kötü birşey değildi, kelâmında sözleri, 

Yalvardı neredeyse, yaş damlayan gözleri. 

Hemşire kıyamadı, adamın bu haline, 

Yardım istiyordu ya, inandı tüm kâline, 

Adam binler teşekkür, dizerken sözlerine, 

Bir an takılıp kaldı, kadının gözlerine. 

Hemşire: 

..........''Haydi giyin o zaman, biraz da acele et'', 

..........''Herşeyi bana bırak, çıkana kadar sabret'', 

..........''Bu hastane korunur, nöbetçiler çakmasın'', 

..........''Şüpheli davranma da, kimse bize bakmasın''. 

..........''Ayrı ayrı çıkalım, otoparka inelim'', 

..........''Bordo renkli Corvette''e, çaktırmadan binelim'', 

..........''Sonra sen başını eğ, çıkarken görmesinler'', 

..........''Başımıza şimdiden, bir çorap örmesinler''. 

..........''Araba durana dek, yattığın yerden çıkma'', 

..........''Sözümü dinlemeyip, sonra canımı sıkma'', 

..........''Evim yakındır benim, çok yakında inmeyiz'', 

..........''Belki birkaç gün kadar, arabaya binmeyiz''. 

Herşeye ''he'' diyerek, ''ok'' i de verince, 

Adam kadına karşı, yelkenleri serince, 

Çıktılar yavaş yavaş, beş dakika arayla, 

Ve bindiler Corvette''e, kadın adam sırayla. 

24.Haziran / Los Angeles

*** ''Akrep ve Yelkovan'' Şiir Roman 8. bölümüyle 28.Ekim.Perşembe günü devam edecek.

*** ''Akrep ve Yelkovan'' ın okuyamadığınız ilk bölümleri ve daha fazlası aşağıdaki link ile ulaşabileceğiniz Akrep ve Yelkovan grubunda.

Akrep ve Yelkovan Grubu>>>', 'Biraz korku sarmıştı, kimsesiz bedenini,  Ya kime soracaktı, bunların nedenini,  Etrafında bir duvar, aşılmaz dağa dönmüş,  Hayat yolu denil...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/a-k-r-e-p-v-e-y-e-l-k-o-v-a-n-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerisi Ölümden Pay', 'gerisi-olumden-pay-necmi-unsal-j94i7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu sabah güneş parlak doğdu  yeniden.

Ne yıldız kaldı elimde, ne dolunay.

Bana ne gönül avutan beğeniden! 

Bir ömür geçmiş, gerisi ölümden pay.

Beni anlatan bir lisan bulamadım.

Yabancıydım bu köhne, yitik illerde.

Çatladı kurak toprağım, sulamadım

Garip heceydim gönlü tutuk dillerde.

2 Haziran 2004 Çarşamba, Danimarka-Køge 23.42

5+7', 'Bu sabah güneş parlak doğdu  yeniden. Ne yıldız kaldı elimde, ne dolunay. Bana ne gönül avutan beğeniden!  Bir ömür geçmiş, gerisi ölümden p...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gerisi-olumden-pay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Xxx Ölgün Şiir', 'xxx-olgun-siir-zeki-ergin-dygi5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sabah yıldızlarının ezikliğidir

içimde duyup da 

anlatamadığım

sorumsuzluğunu umursamazlığını

sırtlamış bir küfe yükü

uzanamadığım meyvelerce

ağaç kabuklarının dökülmüşlüğünde

tükenmişliğim

kelebeğin yazı göremeyişinde

yitikliğim

bitikliğim

_istanbul 1974', 'sabah yıldızlarının ezikliğidir içimde duyup da  anlatamadığım sorumsuzluğunu umursamazlığını sırtlamış bir küfe yükü uzanamadığım meyvelerc...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olgun-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annemi Özledim', 'annemi-ozledim-yavuz-agir-fzrw5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah anam, vah anam! ..Düşüp yollara 

Yüzümü yüzüne sürmeye geldim 

Çile rüzgârları eser dallarda 

Dallardan çiçekler dermeye geldim. 

Türküne, ninnine hasret kalmışım 

Anlattığın o masalda kalmışım 

Zalim gurbet elde çok bunalmışım 

Işıklı yüzünü görmeye geldim. 

Oğlun diyar diyar gezer dolaşır 

Maziden koparır bugüne taşır 

Saçı beyazlamış elleri nasır 

Anam ellerini öpmeye geldim. 

Sensiz bütün cihan vallahi gurbet 

Diz çöküp sedire edelim sohbet 

İhmali var ise oğlunu affet 

Ana, hatırını sormaya geldim. 

Ah anam! Mevsimler kış ayazı, buz 

Uğruna fedayız, kurban oluruz 

Bak işte bu gelen oğulun Yavuz 

Saatleri yeniden kurmaya geldim.', 'Ah anam, vah anam! ..Düşüp yollara  Yüzümü yüzüne sürmeye geldim  Çile rüzgârları eser dallarda  Dallardan çiçekler dermeye geldim.  Türküne...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/annemi-ozledim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buğulursun...', 'bugulursun-selim-bayrak-1ih3u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Buğulursun dememiştin

Karanlık odalarda

Nem işler iliklerine

Göz kapakların komalarda 

Yarınında ben yokum

Yarınında umudun

Demiştin dedin varsaydım ben korkakça

Gözler konuşurmuş sadece

İnanmadım değil

Sözler unuturmuş

Kör adım sefil

İki mavi okyanus

İki seyir

İki adım iki kulaç

Geri çekil

İki mavi okyanus

İki nehir 

İki adım iki kurak 

Geri çekil

2002 - İstanbul', 'Buğulursun dememiştin Karanlık odalarda Nem işler iliklerine Göz kapakların komalarda  Yarınında ben yokum Yarınında umudun Demiştin dedin v...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bugulursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birini Bekler', 'birini-bekler-mehmet-selim-togluk-7sxq4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Deniz kıyısında, yüksekçe yerde

Gözleri ufukta, birini bekler

Saçları dağılmış, esen yellerde

Oturmuş bir taşa birini bekler

Saçlar biraz uzun, altın sarısı

Belli ki karadır alın yazısı

Derinden ah çeker, gece yarısı

Oturmuş bir taşa birini bekler

Yağan yağmurlarda, esen rüzgarda

Kar, tipi, fırtına ve boranlarda

Damlalar süzülür yanaklarında

Belki gelir diye birini bekler

Gözyaşlarından  ıslanmış teni

Kaybetmiş yarini, belki de yeni

Kimlerin var böyle, bir bekleyeni

Gözünde bin ümit, birini bekler

Ayaz bir gecede, hava bulutsuz

Rüzgarda çatlamış, dudaklar susuz

Sabahlara kadar böyle uykusuz

Oturup bir taşa birini bekler

	(Batman - 25.10.2004)', 'Deniz kıyısında, yüksekçe yerde Gözleri ufukta, birini bekler Saçları dağılmış, esen yellerde Oturmuş bir taşa birini bekler Saçlar biraz uz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Toğluk']::text[], 8.5, '{"poet":"Mehmet Selim Toğluk","poet_slug":"mehmet-selim-togluk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/birini-bekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben, Seni Dolaşıyorum Her gün', 'ben-seni-dolasiyorum-her-gun-selim-bayrak-03f0u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bensizlik gelirse aklına

Bir de dön bak kendine

Ben seni dolaşıyorum her gün

Sen bana gelmesen de

Gel desen de

Acımın terisin

Gönlümün seferi

Ölümün tehirisin

Umudun seheri

Yalanlar hiç bu kadar 

Avutmazken ‘ben’imi

En büyük yalan aşkım

Sarmalarken tenimi

Unuturken geçmişi

Yarına ben aşığım

2002 - İstanbul', 'Bensizlik gelirse aklına Bir de dön bak kendine Ben seni dolaşıyorum her gün Sen bana gelmesen de Gel desen de Acımın terisin Gönlümün sefer...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-seni-dolasiyorum-her-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korsan', 'korsan-cigdem-bir-genc-6q7bn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sular çekildi...

Senden umut yok...

Kağıttan gemilerimi yağmaladı korsanlar...

Yıldızı bol bir gecenin orta yerinde yağmura şiirler karalıyorum...

Yalnızlık gibi bir şey kaçıyor gözüme 

Ağlamıyorum...', 'Sular çekildi... Senden umut yok... Kağıttan gemilerimi yağmaladı korsanlar... Yıldızı bol bir gecenin orta yerinde yağmura şiirler karalıyo...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/korsan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanmazın Biriyim (33)', 'utanmazin-biriyim-33-i-brahim-arslan-9ezk6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünyaya arkamı döndüm yine,

Duvarların içinden geçtim...

Sağır,kör,başsız insanların içinden...

Aldırmam hiçbirşeye,

Ben hasret ateşinde büyüdüm...

Cehennemdim söndüm yine,

Senin için cennetten geçtim,

Ve ben hep sensizliğe yürüdüm...

Yine görmüyor gözüm,

Senden başkasından medet ummuyorum...

Senin gölgene bile imrendim ben,

Döktüğün gözündeki yaşa imrendim...

Al beni yanına,işte sana canımı

Sunuyorum...

Geldim

Her sevgiyi tepip

Sana döndüm yine,

Utanmazın biriyim...

Binkere kovsan,milyon kere

Yanına geleceğim...

Dünyaya arkamı döndüm yine,

Denizlerin,okyonusların içinden geçtim...

Ölülerin ve yaşayanların içinden...

Aldırmam hiçbirşeye,

Ben hasret ateşinde büyüdüm...

2004', 'Dünyaya arkamı döndüm yine, Duvarların içinden geçtim... Sağır,kör,başsız insanların içinden... Aldırmam hiçbirşeye, Ben hasret ateşinde büy...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/utanmazin-biriyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalgalar 4 (34)', 'dalgalar-4-34-i-brahim-arslan-emkv4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dalgalar,

Var, sen yoksun  Ereğli sahillerinde

Rüzgar kulaklarımın dibinde esiyor,

Bekliyorum,ne olur gel,seni gönlümün sahilinde,

Utandır beni,bir tarafım bekleme gelmez diyor,

Ve kalp yok diyor sevgilinde...

Bende sensizliğe doğru çeker giderim,

Bir zaman elini tuttuğum,şimdi unuttuğun yere,

Gel,umutsuzum,ama yine seni beklerim,

Gel,güneşin batımını seyredelim yine,

Gelirsen eğer işte o an,sevgine sevgi derim...

Herşey anlamsız,anlamıyorsun sensiz bana,

Terkedip gittin,beni niye? zamansız

Anlamıyormusun muhtacım sana,

Anlamıyormusun seviyorum seni be vicdansız,

Gel,gel inan tak etti cana....

Sevgi var,sen yoksun Ereğli sahillerinde,

Ve her yanımda hayalin var, kahretsin

Sen yoksan ne işim var  sevgi ilinde...

Rüzgar essin ve ismini kaybetsin,

Buradan da gönlümde,dalgalar...

2004', 'Dalgalar, Var, sen yoksun  Ereğli sahillerinde Rüzgar kulaklarımın dibinde esiyor, Bekliyorum,ne olur gel,seni gönlümün sahilinde, Utandır b...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dalgalar-4-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'III/Düşler', 'iii-dusler-ali-gencay-9pnhl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yeni uyandım kan ter içinde 

gel otur yanıma 

düşümü anlatmalıyım,dinle; 

gözlerim kapandı 

kara kapıdan girdim içeri 

uçsuz bucaksız tarlada buldum kendimi 

korktum geri döndüm 

kapanmıştı dünyanın kapıları

karşıladı beni

peri kılığına girmiş korkuluklar

dişlerinden kan sızan bal kabaklar 

ucu ucuna eklenen şeytan merdivenleri 

gördüm! ! 

onlara tırmanan insanları 

kenarında durduğum uçurumlar 

ayaklarımın altından kayanları 

bana doğrulan namlular

ucundan,dibine dökülür kurşunlar 

korkumdan sıktım yumruklarım

kaçtım! ! 

koşmaktan kırıldı bacaklarım

ben uzaklaştıkça yaklaştı canavarlar

somya da bağdaş kurmuş babam

elini öpmek için uzandığımda 

paçamdan yapışıp gitme! diyen anam

babamın yerin dibine sokan bakışları 

okşadığında saçlarımı anam

başıma değer bulutlar

gölde yüzen akbabalar

takım elbiseli yamyamlar 

kulağımda zonklayan tamtamlar

kapatıldığım camdan tabutlar

beni omzunda taşıyanlar 

mahşer,kalabalık 

uzanan kollar 

ve uyandım 

uyandırdı beni

üzerime atılan topraklar 

dişilerimde ki gıcırtılar

şimdi tut ellerimi 

korkuyorum düşlerden

ama sakın! ! 

gözlerime geceymiş gibi bakma', 'yeni uyandım kan ter içinde  gel otur yanıma  düşümü anlatmalıyım,dinle;  gözlerim kapandı  kara kapıdan girdim içeri  uçsuz bucaksız tarlad...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/iii-dusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin (35)', 'gozlerin-35-i-brahim-arslan-aieal', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gözlerin çok güzeldi

ama ne ağlamasını biliyordu

ne de  manalı bakmasını...

Kandırıyordu sadece

Karanlığı andırıyordu

kalleşliği ve ihaneti

zamanında vazgeçemedim senden

uzaklaşamadım bu şehirden

''keşke''ler fayda etmiyor 

''keşke'' desem

şimdi kafam ellerimin içinde

hayatımın muhasebesini yapıyorum

ve ilk hatam senle birlikte başlamış...

gözlerin çok güzeldi senin

ama ne ağlamasını biliyordu

ne de manalı bakmasını...

2004', 'gözlerin çok güzeldi ama ne ağlamasını biliyordu ne de  manalı bakmasını... Kandırıyordu sadece Karanlığı andırıyordu kalleşliği ve ihaneti ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gozlerin-124-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttuğum Şehir 2 (36)', 'unuttugum-sehir-2-36-i-brahim-arslan-93c3c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kendimi onda unuttuğum şehir,

Yalanmıydı ellerini tuttuğum,

Gözlerinde kaybolduğum yalan mı? 

Bu üzerime gelen felaketler nedir...

Hep sen varsın gözlerimin önünde,

Yalanmıydı yaşananların hepsi,

Sözlerin ve yazdıkların yalan mı? 

Sen hiç durmazmısın sözünde...

Kendimi onda unuttuğum şehir,

Şimdi beni sende yalnız bıraktın,

Yalanmıydı cehennemde  yandığım,

Yaşananların hepsi bir rüyaymıydı? 

Elveda bende gidiyorum/bende gidiyorum...

2004', 'Kendimi onda unuttuğum şehir, Yalanmıydı ellerini tuttuğum, Gözlerinde kaybolduğum yalan mı?  Bu üzerime gelen felaketler nedir... Hep sen v...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/unuttugum-sehir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokağa Atılan Bebeğin Şiiri', 'sokaga-atilan-bebegin-siiri-umit-kilislioglu-ozger-1vxw4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben,

Doğurur doğurmaz

Yüzüne bile bakmadan

Atmaya hazırlandığın bebek.

Sıkı sar beni,

İyice doyur karnımı 

Çıkma evden alelacele

Bir de bez koy, yedek.

Şöyle kuytu bir yer olsun anne

Polis amcalar buluncaya dek

Direnebileyim ecele.

Belki bana son moda bir ad seçerler,

Belki de “Kader” deyip geçerler.

Birileri bakar, büyütür nasılsa...

Sevilme ihtimalim bile var

Biliyor musun? 

Bense...

Hep seni merak eder dururum.

Sesini duymak isterim

Nerede olursa olsun yerim.

Hayal gücümle sana çeşit çeşit yüzler yaparım

Gözümü kaparım,

İçlerinden en güzelini seçerim.

Anne! Babam şimdi nerde? 

Kötü mü oldu aşkınızın sonu? 

Ona mutluluk diliyor musun? 

Hâla seviyor musun onu? 

Sahi, kim olduğunu biliyor musun? 

İleride belki tezgâhtar olurum

Sana bir gün bir etek giydirir, 

Çok yakıştığını söylerim,

İndirim yaparım “Sizi çok sevdim” derim.

Belki hemşire olur, 

Sen ameliyata girerken saçını okşarım.

“Hiç merak etmeyin” derim “yanınızda ben varım”.

Karşılaşır mıyız bir daha

Bilinmez anne...

Boynuma bir künye as; 

Ne olur, gitmeden,

Bir defacık,

Bir defacık yüzüme bak,

Bağrına bas.

26.10.2004', 'Ben, Doğurur doğurmaz Yüzüne bile bakmadan Atmaya hazırlandığın bebek. Sıkı sar beni, İyice doyur karnımı  Çıkma evden alelacele Bir de bez ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/sokaga-atilan-bebegin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaptığınız yakıştımı bana', 'yaptiginiz-yakistimi-bana-ceylan-yarar-pjasc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'karanlığa gebe izlerde

tir tir titredim ben

güya mertliğin sesi vardı

asi esen poyrazda

adını dostluk koymuşlar

menfaat kurşunlarının

utanmadn yağmur demişler

her vurduğunda damlaların

hedef tahtası olmuşum ben

gelen vurmuş giden vurmuş

hemde acımasızca

korkmuyorum aslında

doyasıya sevdim ben

yufka ammaaaa

acıların nasırlaştırdığı yüreğimle

kim vurmadı ki bana

eş,dost,akraba

ama en acısıda

en dayanılmazıda

kardeşinki oldu aslında

eğer parçalanacaksa,dağlanacaksa

bu dayanılmaz acılar,

ebedi unutulmazım olacaksa

razıyım ben kurşunlara

darma dağılmış bir

bir yürek sahibi olmaya

yakıştımı bana

dinleyin vijdanınızın sesi

sahte sevgi canavarları

menfaat tutsakları

yalanların kurbanları

offf of beeeee

geçmiyor bu gece

nazlı gelin gibi zaman

ne karanlık gece bitti

nede içimi aydınlatacak

sabah geldi

birde en zoru

nedenlerime,niçinlerime cevap

ama gururum yine önde

kahrolmamamı emretti

ilk darbe değlki aldığım

o, o bir başka oluyor

sonsakilerde yıkılmıyorsun

sendelesende,yığılsanda

kalkacağını biliyorsun

yaptığınız sadece şu

ezilmiş bu yüreği

tekrar,tekrar çökeltmek

çok istediniz celledım olmak

ama nafile,yanıldınız

korkum yok sahte dostlar

beklemekteydim sizden

gelecek her darbeyi

ilkinden sonra,

yufka,ama acıların nasırlaştırdığı

bu yüreğimle

dayanırım ben daha

bir çok kahpe tuzaklara

ancak dinleyin vijdanınızın sesini

yaptığınız yakıştımı bana.

24.ağustos.2004

03.45.pazartesi

avşa', 'karanlığa gebe izlerde tir tir titredim ben güya mertliğin sesi vardı asi esen poyrazda adını dostluk koymuşlar menfaat kurşunlarının utanma...', ARRAY['Türk Edebiyatı','Şiir','Ceylan Yarar']::text[], 8.5, '{"poet":"Ceylan Yarar","poet_slug":"ceylan-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/yaptiginiz-yakistimi-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birbirimize Yazılmışız', 'birbirimize-yazilmisiz-olgun-ekinci-hbb3g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gemi güvertesinde aynı yolcuyduk seninle 

Sahilde aynı kıyıya oltalar sallardık.. 

Aynı ormanda yanyana iki büyük ağaç 

Kumsalda iki farklı ve çok renkte 

Çakıl taşlarıydık yanyana 

Aynı gök yüzünün iki yıldızıydık seninle 

Çıralı''da bir gece vakti 

Aşıklar el uzatsa dokunacaklar ışığımıza 

Onlara yakın, biz bize uzak ve habersiz… 

Yüreklerimiz aynı dili konuşuyordu 

Dillerimiz hiç konuşmasa hep sussa bile 

Güverte de, kumsal da karşılaşmadık.. 

Ormanda aynı havaya soluklanırken, 

Kumsal da aynı denizin dalgaları, 

Köpükleriyle örteyken renklerimizi karşılaşmadık 

Aşıkların el uzattığı 

dokunacağı yakınlıktaki uzak yıldızlardık 

Altmış yaşınada gelsek, karşılaşmasak 

Birbirimize yazılmıştık….biz…. 

Güvertede, kıyıda, ormanda 

Kumsal da, ormanlar da, yıldızlar da buluşmasakta 

Birbirimize yazılmıştık… 

26.10.2004 - Adana', 'Bir gemi güvertesinde aynı yolcuyduk seninle  Sahilde aynı kıyıya oltalar sallardık..  Aynı ormanda yanyana iki büyük ağaç  Kumsalda iki far...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/birbirimize-yazilmisiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birliğe Çağrı', 'birlige-cagri-murat-al-08g0b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hedefsiz çıktık yola

Her dakika verdik mola

Çaremiz yok girip kol kola

Artık çıkmalıyız medeniyet yoluna

Sağcılıkla solculukla gitmez bu işler 

Uyanın artık yıllardır misyonerler ülkemizi dişler

Gruplara düşdükçe bizi daha çok kişi fişler

Hükümeti,askeri,öğrencisi verip kol kola 

Artık çıkmalıyız mevlanaların yunusların yoluna

Tesettürlü tesettürsüz diye ayırmayın

Laik Cumhuriyetçi ya da dindar diye insanları kayırmayın

Dünyanın en zengin ülkesinde insanları yoksul yaşatmayın

Hamalı,garsonu,gazetecisi verip kol kola 

Artık çıkmalıyız Mustafa Kemallerin yoluna', 'Hedefsiz çıktık yola Her dakika verdik mola Çaremiz yok girip kol kola Artık çıkmalıyız medeniyet yoluna Sağcılıkla solculukla gitmez bu işl...', ARRAY['Türk Edebiyatı','Şiir','Murat Al']::text[], 8.5, '{"poet":"Murat Al","poet_slug":"murat-al","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/birlige-cagri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Saçlı Kadın', 'kirmizi-sacli-kadin-nalan-kazazoglu-l7zjq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hızlı geçer yaşam sinsice,

Bakıpta görememecesine..

Hırlı, hırsız hepsi aynı trende,

Uğurlar olsun her binene...

Gece yüklü gidiyor gün batmaya,

Mükemmel rengiyle köprünün ardında..

Çırpınıyor vurmuş karaya,

Atlas yelkenlim güzelim İstanbul''da..

İçindekini tam yazamamak,

Olanlara yaban bakmak..

Kırmızı saçlı çirkin kadının cilveli gülüşü şen şakrak

Aslında feryat..

Kara günler çoktur içimdeki takvimde,

Görür ay buluştuğumda kalemimle..

Karakışlar, hüzünler yol alır bende,

Bitmez ayla yüzleşme...', 'Hızlı geçer yaşam sinsice, Bakıpta görememecesine.. Hırlı, hırsız hepsi aynı trende, Uğurlar olsun her binene... Gece yüklü gidiyor gün batm...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kirmizi-sacli-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susun', 'susun-oguzkan-bolukbasi-xt9dd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Acıtan kıymıklar battı ellerime

Yüreğime değmesin diye

Siper ederken bedenimi 

Bir bilinmez kargaşanın önüne

Sendin ey güzelliğini parayla satan fahişe

Aklımı karıştıran

Bir plastik sevişmede 

İçimi acıtan ne varsa dışa çıktı

Bedenim doyarken

Ruhum sonsuz acıktı

Bana söyleyeceğiniz bir söz kalmadı

Susun', 'Acıtan kıymıklar battı ellerime Yüreğime değmesin diye Siper ederken bedenimi  Bir bilinmez kargaşanın önüne Sendin ey güzelliğini parayla s...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/susun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Tyatrosu''ndan', 'hayat-tyatrosu-ndan-gullu-alemdar-qszhb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sevda treni daha kalktı,yetişemedim

Gönlümün boş istasyonlarından

Son durak olmalıydı oysa

Son sevda  yaşanmalıydı sende

Dileğim son oluşundu,gittin! 

Ve eller sallanıyor isyanla ardından

Siren sesi duyuluyor uzaktan

Geliyor hissediyorum,

Ve biliyorum büyük aşıkların

Kavuşamadan ayrılığını

Yenisi geliyor gönül sızımın

Daha izlerini silemeden

Bu acı kendini yineliyor

Hayat buluyor her bitişte

Ne sevdalar yaşandı ve bitti

Son perde bu...

Hayat tiyatrosunun; 

Mühürlendi dudaklar,

Kilitlendi eller,

Sinede yareler,

Tükendi çareler,

Yetmedi ümitler...

(Gülnida)  (I.Perde)', 'Bir sevda treni daha kalktı,yetişemedim Gönlümün boş istasyonlarından Son durak olmalıydı oysa Son sevda  yaşanmalıydı sende Dileğim son olu...', ARRAY['Türk Edebiyatı','Şiir','Güllü Alemdar']::text[], 8.5, '{"poet":"Güllü Alemdar","poet_slug":"gullu-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hayat-tyatrosu-ndan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın Kendisi', 'hayatin-kendisi-hasan-can-90lbo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık yaşadıklarımdan sonra,

Sadece hayal görüyorum,

Tutulmayan gerçeği,

Yani hayatın ta kendisini...', 'Artık yaşadıklarımdan sonra, Sadece hayal görüyorum, Tutulmayan gerçeği, Yani hayatın ta kendisini......', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hayatin-kendisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soramadım', 'soramadim-hasan-can-iv37j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Daldım uykuya bir gece,

Göremedim deli yağmuru,

Uzun uzun esen rüzgarı,

Deli gibi susayan denizi,

Duyamadım karıncanın ayak sesini,

Bilemedim sensizliğin acısını,

Geleceğini geçmişini soramadım.

Saramadım seni yorulana dek,

Bedenimde biritene dek...', 'Daldım uykuya bir gece, Göremedim deli yağmuru, Uzun uzun esen rüzgarı, Deli gibi susayan denizi, Duyamadım karıncanın ayak sesini, Bilemedi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/soramadim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Bedenim...', 'ya-bedenim-tugba-gurelli-rwviu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkın kaynaştırma harfleriyle

İçimin duvarlarını sıvar gibi...

Yarım kalan imgelemlerin

Tamlarında savrulur gibi...

Her lirik şiirde

Yeni bir beden arar gibi...

Licralı sözcüklerde

Sonsuzluk kadar durağan olmayı özler gibi...

İçimin kabuklarında 

İçten içe,usuldan,kimse-s-siz kanar gibi...

Günün turuncu saatlerinde

Hep bir karaltı bulmak ister gibi...

Ellerimin tekerlekli sandalyelerinde

Aşkın geç gidip erken gelmeleri gibi...

Ah işte bu yangınlarda savrulmuştum ben

Şimdiyse; 

Parmakuçlarımdan kan damlıyor....', 'Aşkın kaynaştırma harfleriyle İçimin duvarlarını sıvar gibi... Yarım kalan imgelemlerin Tamlarında savrulur gibi... Her lirik şiirde Yeni bi...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Gürelli']::text[], 8.5, '{"poet":"Tuğba Gürelli","poet_slug":"tugba-gurelli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ya-bedenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımın Başkenti', 'askimin-baskenti-hasan-can-7t8qz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sırrımın tek şahidi,

Gözlerimin en gerçeği,

kalbimin değişmezi,

Aşkımın başkenti.

Sensin tek hayalim,

Sensin içimde büyüyen,

Senden sonra da sen,

Sensin hiç değişmeyen.

Ellerim boş olsada,

gözlerim yokluğuna baksada,

Alevler yolumuzu kapatsada,

Bitmeyecek olan sensin hala.

Bu rüzgar hiç dinmeyecek,

Durmadan deli gibi esecek,

Eğer ölürsem birgün,

bedenim olmasa ruhum gelecek.', 'Sırrımın tek şahidi, Gözlerimin en gerçeği, kalbimin değişmezi, Aşkımın başkenti. Sensin tek hayalim, Sensin içimde büyüyen, Senden sonra da...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askimin-baskenti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '~Vur Telime Telime Çal Gitsin~', 'vur-telime-telime-cal-gitsin-burcu-alpaslan-guvenli-m8c8y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eğlen bulmuşken neşemi

Bu terbiye edilmeyecek gece de

Vur telime telime çal gitsin

Bu gece aitliğini

unut

bırak 

bak 

duy meyillerin sesini

Serseri ol bu gece 

aksın varsın 

kırmızısı beyazı

aslanların sütü

seki sulusu buzlusu

dök telime telime çal gitsin

Al bu gece gevezeliğimi

susma 

konuş 

bağır

dünyanın verandasından şarkımızı

vur telime telime çal gitsin 

26-10-2004 Bursa', 'Eğlen bulmuşken neşemi Bu terbiye edilmeyecek gece de Vur telime telime çal gitsin Bu gece aitliğini unut bırak  bak  duy meyillerin sesini ...', ARRAY['Türk Edebiyatı','Şiir','Burcu Alpaslan Güvenli']::text[], 8.5, '{"poet":"Burcu Alpaslan Güvenli","poet_slug":"burcu-alpaslan-guvenli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/vur-telime-telime-cal-gitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solmayan Çiçeğimsin', 'solmayan-cicegimsin-huseyin-erdogan-l66fq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hayallerim sensin düşlerim sensin

bitmeyecek aşkım şiirlerimsin

mevsimlerim sensin nefesim sensin

sen benim baharım solmayan çiçeğimsin

bahar bizim olsun gelmesin hazan

gel otur yanıma bakma uzaktan

güneşli havada çimlere uzan

sakın çekip gitme akşam olmadan

Eylül''de bekledim gelmedin neden? 

mevsim hazan oldu haber yok senden

Dönüp gel bir sabah Ekim bitmeden

istersen çıkıp gel haber vermeden', 'hayallerim sensin düşlerim sensin bitmeyecek aşkım şiirlerimsin mevsimlerim sensin nefesim sensin sen benim baharım solmayan çiçeğimsin baha...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/solmayan-cicegimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dost Tanıdım', 'bir-dost-tanidim-behzat-ozdemir-yvds1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sarmaşıkların dudaklar dolusu gözyaşlarına büründüğü,

yola çıkmış gözlerin geri dönüş parolası gezdiği

ve sevda dağlarında güneşin yol gezdiği

bir dostum var, sadaka kadar az görülür...

görkemli zamanı hapis ettiği sevgilisi sayan

geri dönen gözlerin uzaklardan gelmişliği,

bir iğne birde iplik ile

bir dostum var, dönmez diye diker kalleş sevgilileri

hayat yüze benzerdi önceleri dostum

sadece yanlışlıktı...

ve sevgili yüzünden

dostlardan olmaktı...

kurtulmak, yalnızca ağlamak

ve yalnızca dostunun omzunda ağlamaktır.

----sevgilerimle

-----bekir topçu''ya', 'sarmaşıkların dudaklar dolusu gözyaşlarına büründüğü, yola çıkmış gözlerin geri dönüş parolası gezdiği ve sevda dağlarında güneşin yol gezdi...', ARRAY['Türk Edebiyatı','Şiir','Behzat Özdemir']::text[], 8.5, '{"poet":"Behzat Özdemir","poet_slug":"behzat-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-dost-tanidim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-hasan-can-wrh0k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özlüyorum seni unutamıyorum,

Her an gözümün önünde yaşananlar,

İstesemde bitmiyor bütkenmiyor sensizlik...

Terkedemiyorum düşlerimde seni.

Gökyüzüne her baktığımda,

Her yıldız kaydığında,

Seni izletiyor bana geceler.

Aydınlıkta güneş vuruyor seni yüzüme,

Boşlkuklar sarıyor etrafımı,

Yağmurlar siliyor bütün sokakları.

Sensizliği kabullenemiyorum,

Avutamıyorum bu gönlümü,

Bu acıyı dindiremiyorum.

Yaşayacak derman yok artık,

Bitmiyor bu sensizlik,

Ve bitmiyor bu çaresizlik...', 'Özlüyorum seni unutamıyorum, Her an gözümün önünde yaşananlar, İstesemde bitmiyor bütkenmiyor sensizlik... Terkedemiyorum düşlerimde seni. G...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensizlik-142-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünüyorum', 'seni-dusunuyorum-hasan-can-mcgwm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum,

Gecenin sessiz ve sakin derinliğin de,

Ay vuruyor yüzüme.

Her çarpışında kalbim,

Senden bir hatıra kalıyor bana.

Ve her döküldüğün de yaşlar,

Sele tutsak oluyor gözlerim.

Anlatması zor bir duygu sarıyor etrafımı.

Yıldızlar yanıp sönerken,

Aklım akıp giden zamanı sorguluyor.

İşte o an bir yıldız kayıyor,

Aklım o zaman sorusunun yanıtını buluyor.

Zaman akıp giderken,

Götürdüklerini bize unutturuyor.

Ve aynı zaman geldiğinde,

Unutturduklarını anımsatıyor.

Bir gecenin daha sonuna gelindiğin de,

Gündüzü boş kılan zaman,

Gecede yine akmaya devam edecek...', 'Seni düşünüyorum, Gecenin sessiz ve sakin derinliğin de, Ay vuruyor yüzüme. Her çarpışında kalbim, Senden bir hatıra kalıyor bana. Ve her dö...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-dusunuyorum-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut Gitsin', 'unut-gitsin-tulay-sustam-ee44y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu yüreğin senin için can attığını

dudaklarımın seni sayıkladığını

bu gözlerin senin için açıldığını

bilipte bilmemezlikten gel BİLME gitsin

uğruna her şeyi göze alacağını

sözünden hiçbir zaman çıkmayacağını

canına can katıp hep yol alacağını

görüpte görmemezlikten gel GÖRME gitsin

bu can güzelden yana şaşmayacağını

yâr senden başkasına bakmayacağını

sensiz bir gün bile yaşamayacağını 

artık bilme, görme, unut ve UNUT gitsin', 'bu yüreğin senin için can attığını dudaklarımın seni sayıkladığını bu gözlerin senin için açıldığını bilipte bilmemezlikten gel BİLME gitsin...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unut-gitsin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız', 'zamansiz-edim-ahmet-jdzty', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çözümsüz denklemler,

Tarifsiz elem,

Tasnifsiz arzular,

Nafile arayış,

Dermansızım,

Zamansız…

Tükenirken; 

Tükenirken çıldıran,

 Kaç sigara oldu içtiğim,

Kaç bekleşi,

Sabırsızım,

Zamansız…

Gönlümce yaşamak,

Yarım yamalak,

Yarı uykulu,

Korkusuz,

Zamansız....

Benli – bensiz,

Sorgusuz sualsiz,

Çat kapı geliver,

Durmaksızın, duraksız,

Zamansızım…

Böyle olmaz,

Umarsız,

Duyarsız,

Zaman durmaz,

Zamansız…

Beri bak,

Umutsuzum, mutsuzum,

Kaç sebep söyleyeyim,

Kaçmama dair,

Bunca inat,

İnsaf,

Gam tutarım imdat,

Amanım yok, amansız,

Zamansız…

Mekansızım,

Eşkalsizim,

Zamansızım,

Zamansız…

                         13.10.2004 - Çankırı

                               Edim Ahmet', 'Çözümsüz denklemler, Tarifsiz elem, Tasnifsiz arzular, Nafile arayış, Dermansızım, Zamansız… Tükenirken;  Tükenirken çıldıran,  Kaç sigara o...', ARRAY['Türk Edebiyatı','Şiir','Edim Ahmet']::text[], 8.5, '{"poet":"Edim Ahmet","poet_slug":"edim-ahmet","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/zamansiz-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgârın Oğlu, Güneş''in Kızı', 'ruzg-rin-oglu-gunes-in-kizi-tulay-sustam-rgsdk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Rüzgârın oğlu, Güneş''in kızı

Ayrı dünyaların insanları

Yağmur bilerek ayırdı onları

Yarım kaldı sevdaları...

.

.

.

o yüzden hiç sevmedim yağmurları...', 'Rüzgârın oğlu, Güneş''in kızı Ayrı dünyaların insanları Yağmur bilerek ayırdı onları Yarım kaldı sevdaları... . . . o yüzden hiç sevmedim yağ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruzgarin-oglu-gunes-in-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlık Koymasam Olmaz mı?', 'baslik-koymasam-olmaz-mi-tugba-gurelli-k69qr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sol yanım acıyor içimin karalama defterlerinde...

Bekaretini kaybediyor içimde herkes bu gece

Sayamıyorum sesimdeki sessiz harfleri artık

Ellerimi daha az yıkamalıyım belki de

-Elki kırılmadır kendi göğsüne.-

Ellerimin kağıt mendillerini buruşturup savuruyorum günlere.

Avuçlarıma sıkıştırıyorum yüzünün çizgilerini

Gidip gelip bir imge çukuruna düşüyor kalemim

Sol omzuma koy senden en uzak yerini

Kaçarken sadece beni koy iç ceplerine.

Seni hep ben-lerde çoğaltmışım anladım

Şiirle boyandığımı sanarken tepeden tırnağa

Ellerimle sevişirken geceler boyu sen diye

Sevmelerimi hep tenlerde bitirmişim meğer.

İçimde sirenler çalıyor ömrümün en yokuş düzlüğünde...', 'Sol yanım acıyor içimin karalama defterlerinde... Bekaretini kaybediyor içimde herkes bu gece Sayamıyorum sesimdeki sessiz harfleri artık El...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Gürelli']::text[], 8.5, '{"poet":"Tuğba Gürelli","poet_slug":"tugba-gurelli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/baslik-koymasam-olmaz-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatlı Yalan', 'tatli-yalan-ahmet-ozdemir-z4yzz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bakınma yollara sesler bekleme,

Sevda kervanında artık değiliz.

Bitmez umutlara umut ekleme

Silindi kalplerden kalmadı bir iz.

Korkma ateş düştü diye içine

Ateşi ateşle söndürürlermiş.

Çekerler bir nurun albenisine; 

Pervaneler gibi döndürürlermiş.

Göreceksin belki hayal, belki de; 

Yadına düşecek puslu bir anı.

Gerçekse, yok artık aşk da, sevgi de; 

Sürdürmek nafile tatlı yalanı.', 'Bakınma yollara sesler bekleme, Sevda kervanında artık değiliz. Bitmez umutlara umut ekleme Silindi kalplerden kalmadı bir iz. Korkma ateş d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özdemir']::text[], 8.5, '{"poet":"Ahmet Özdemir","poet_slug":"ahmet-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tatli-yalan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabülümsün', 'kabulumsun-behzat-ozdemir-hv9do', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sırt sırtaydık yaşam boyu

esir ettik kendimizi sabahlara

belalıydık esen lodosa

sürgün ettik kendimizi başı boş limanlara,

hiç kin tutmadık öfkeyle yanan dünyaya

ve hiç yüzümüz gülmedi bir temmuz gecesi sicağında

oysa görkemsi hayellerimiz vardı hayatla 

çarpıp çıkmasaydı kapıdan hayat

ne sana ne bana yağmadı yağmur

hep acı hep sancı yataktan kalkınca,

bir öpücükle döküldük 

ve bir öpücük kadar küçüldük 

bu dahi hayatta

yoksa üzerimizi mi örttüler 

en sevdiklerimiz aynı anda...

kabül etsekte 

etmesekte

sevdiklerimizdir. canimizi yakan

aynı zamanda...', 'sırt sırtaydık yaşam boyu esir ettik kendimizi sabahlara belalıydık esen lodosa sürgün ettik kendimizi başı boş limanlara, hiç kin tutmadık ...', ARRAY['Türk Edebiyatı','Şiir','Behzat Özdemir']::text[], 8.5, '{"poet":"Behzat Özdemir","poet_slug":"behzat-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kabulumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yürek Oldum Şu Bedenler İçinde', 'bir-yurek-oldum-su-bedenler-i-cinde-ahmet-ercan-apalak-evd0j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Balıkları andırır suskunluğum

Mercanlara benzer yalnızlığım

Demir atmış gemi gibi yorgunluğum

Bir sandal oldum şu ummanın içinde

Yollar gibi umut bekçisiyim

Sokaklar gibi yalnızlık sinesiyim

Kaldırımlara işlenen ayak izleriyim

Bir mecnun oldum şu şehrin içinde

Dalından koparılan gonca gül gibi

Gülsüz diyarlarda öten bülbül gibi

Özlemlerle sonsuza sürgün gibi

Bir hazan oldum şu mevsimler içinde

Sevdim ölesiye yürekten sevdim

Yandım aşkına alev alev yandım

Şu gönül yarama çare bulamadım

Bir yürek oldum şu bedenler içinde', 'Balıkları andırır suskunluğum Mercanlara benzer yalnızlığım Demir atmış gemi gibi yorgunluğum Bir sandal oldum şu ummanın içinde Yollar gibi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ercan Apalak']::text[], 8.5, '{"poet":"Ahmet Ercan Apalak","poet_slug":"ahmet-ercan-apalak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-yurek-oldum-su-bedenler-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Öte Yaşıyorum Seni', 'benden-ote-yasiyorum-seni-muammer-celik-6uyce', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ölmek dirilmenin başlangıcıdır

ben senin için her gün ölüyorum

ve yeniden senin için diriliyorum…

o yüzdendir sevgimin ölümsüzlüğü

o yüzdendir aşkımın sürekli tazeliği

o yüzdendir seni ölümüne sevişim

o yüzdendir sana her defasında gelişim...

tutamasam da

dokunamasam da

okşayıp koklayamasam da

o yüzdendir hayalinle yaşarım

yaşadıkca ölüyorum 

öldükce  yaşıyorum… 

………..seni! ... 

BirDeli

26.10.2004', 'ölmek dirilmenin başlangıcıdır ben senin için her gün ölüyorum ve yeniden senin için diriliyorum… o yüzdendir sevgimin ölümsüzlüğü o yüzdend...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benden-ote-yasiyorum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Duman', 'kara-duman-mustafa-karamelek-ulk9o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu duman

Mor dağların 

Derman dumanı değil.

Bu duman

Bir yerlerdeki yangının dumanı

Ağır ağır 

Sine sine

Sinsice gelişinden belli.

Bu duman 

Yeşil umutların 

Bereket dumanı değil

Bu duman tükenişlerin

Karanlıkların kara dumanı

Bu duman bir yerlerdeki

Yanan yüreklerin

Feryadını sancısını yüklemiş

Dertlerin dumanıdır.

Şimdi dört gözle

Bu dumanı dağıtacak

Bir sevda rüzgârı bekliyoruz..', 'Bu duman Mor dağların  Derman dumanı değil. Bu duman Bir yerlerdeki yangının dumanı Ağır ağır  Sine sine Sinsice gelişinden belli. Bu duman ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Karamelek']::text[], 8.5, '{"poet":"Mustafa Karamelek","poet_slug":"mustafa-karamelek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kara-duman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Anlayacaksın', 'beni-anlayacaksin-mustafa-karamelek-nu48d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bırakıp gidersen beni yüzüstü

Senden sonra tufanım olur

Kıyamet kopar sanırdım

Gönlümü kör kuyulara atacaktım

Aşkının ateşinde yanacaktım

Kendimi boşa harcayacaktım boşa

Dünya tek sen değilmişsin anladım

Senden güzelini bulacağım göreceksin...

Sen, çok ta güzel değildin

Seni  güzel gören benim

Sen çok ta özel değildin

Seni  özel benim

Yaşamak tek sen değilmişsin 

Anladım

Senden özelini bulacağım duyacaksın...

Benden başkasına gidersen

Ağustos’ta üşürüm sanırdım

Düz yollarda düşer

Ayağa kalkamam sanırdım

Sevda tek sen değilmişsin

Anladım

Senden iyisini bulacağım göreceksin.

Gittiğine bin pişman olacak; 

Maziye baktığında beni anlayacaksın

Beni çok arayacaksın çoook.....', 'Bırakıp gidersen beni yüzüstü Senden sonra tufanım olur Kıyamet kopar sanırdım Gönlümü kör kuyulara atacaktım Aşkının ateşinde yanacaktım Ke...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Karamelek']::text[], 8.5, '{"poet":"Mustafa Karamelek","poet_slug":"mustafa-karamelek","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/beni-anlayacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'REŞİDE (Akrostiş)', 'resi-de-akrostis-muzaffer-erdogan-h0cta', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'R icası bile minnettir bu işin

E lveda demek kolay:dönüşü olmalı gidişin

Ş akası olmaz sevdanın,sev sevebildiğin kadar

İ nan bana sende hala onun sevdası var

D inle bu sözlerimi darılmazsan eger

E vet:seviyorum diye bilmek dünyalara değer', 'R icası bile minnettir bu işin E lveda demek kolay:dönüşü olmalı gidişin Ş akası olmaz sevdanın,sev sevebildiğin kadar İ nan bana sende hala...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Erdoğan']::text[], 8.5, '{"poet":"Muzaffer Erdoğan","poet_slug":"muzaffer-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/reside-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
