INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskunlugum..', 'suskunlugum-berguzar-mettah-1ryz8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anlatmak isteyipte

                                Anlatamadigim

Söylemek isteyipte

                                Söyliyemedigim

Duygularimin cirpinisi

Ruhumdaki firtinalarin

Kasirgaya dönüsü

