INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An - Vl', 'an-vl-mehmet-akif-baltutan-4xtib', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-yangın-

bitti yangın ateş söndü

hayat birden küle döndü

savurdu bir rüzgar külü

zaman yoktu an bir ölü

ışık sızdı aralıktan

sıyrılarak karanlıktan', '-yangın- bitti yangın ateş söndü hayat birden küle döndü savurdu bir rüzgar külü zaman yoktu an bir ölü ışık sızdı aralıktan sıyrılarak kara...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Baltutan']::text[], 8.5, '{"poet":"Mehmet Akif Baltutan","poet_slug":"mehmet-akif-baltutan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/an-vl-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-mehmet-akif-baltutan-zay5x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'acıyı tatmalısın bir günah gibi

duymalısın acizliği iliklerinde 

hissetmelisin sancıyı kemiklerinde

bilgelik budur bununla gurur duy

kekremsi bir tadı var hamlığın

boynuna asılı yafta yaşamak

çıkar at bu etiketi kendinden

gereği yok boş yere hamallığın

kopar yüreğinden nefs bağını

olgun meyve gibi düş dibine

yaşıyorum sandığın dünyanın

 21.11.2003/Maraş', 'acıyı tatmalısın bir günah gibi duymalısın acizliği iliklerinde  hissetmelisin sancıyı kemiklerinde bilgelik budur bununla gurur duy kekrems...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Baltutan']::text[], 8.5, '{"poet":"Mehmet Akif Baltutan","poet_slug":"mehmet-akif-baltutan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dus-98-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An - Vll', 'an-vll-mehmet-akif-baltutan-973oi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '…zaman

zaman asla yürümez

yürüten insanlardır…

yaşayan tek bir andır

ölüp giden zamandır

''Ellerinden tutamadım,titrek bir 

öfkeyle kabarıp gitti.Seviştiğimiz 

yatağın sıcaklığı henüz dururken 

