INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Uzaklara', 'git-uzaklara-sirma-mersin-9x8eh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Git uzaklara gidebildiğin

En uzak yere

Yeter ki! Beni bana bırak

Yokluğunda yok olmak için

Yaşıyorum artık

Sus ne olursun

Söylenecek hiçbirşey kalmadı artık

Arkanda yüreği kırık bi kalp

Bıraksan da düşünme

Nasılsa yalnızlığa alışkınım

Düşünme düşünüp de üzülme

Tesellisi olsun yaşadığımız geçmiş günler

Hatırlanacak bir güzel söz dahi

Beni sana getirmeyecek artık

Hadi git uzaklara

Benden uzaklara git

Gözüm seni görmek istemiyor

Yüreğimde sevgine yer yok

Aklımdan çoktan silmiştim seni! ...

Git uzaklara



28.10.04

Kaydeden RGB74', 'Git uzaklara gidebildiğin En uzak yere Yeter ki! Beni bana bırak Yokluğunda yok olmak için Yaşıyorum artık Sus ne olursun Söylenecek hiçbirş...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/git-uzaklara-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalimdeki Gerçek Tad! ''Hayat''', 'hayalimdeki-gercek-tad-hayat-hurrem-yalcin-8p1ls', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Unuttum tüm ton grileri

Yüreğimi sardı

Hayalimdeki miniğin

Mavice güzelliği

Sesi dünyanın en güzel ezgisi

Açıldı dünyaya minik elleri

Yemyeşil şefkat isteyen gözleri

Sapsarı lüle lüle saçları

Masum süt kokan düğme ağzı

Narin mi narin

Şirin mi şirin

Bir kız çocuğu

Hayatımın anlamı

...

Adı ''Hayat''

Hayalimdeki

Gerçek tad! ...

31 Ekim 2004

''Hayali Kızım ''Hayat''a gönderi...''', 'Unuttum tüm ton grileri Yüreğimi sardı Hayalimdeki miniğin Mavice güzelliği Sesi dünyanın en güzel ezgisi Açıldı dünyaya minik elleri Yemyeş...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hayalimdeki-gercek-tad-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamaya başladım, anlamaya, kendimde aramaya', 'anlamaya-basladim-anlamaya-kendimde-aramaya-lzcramcil-ceyhun-erdem-6z94q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben,

ben yazdım seni okuduğum kitapların köşelerine

kenarlarına papatyalar çizdim,

ismini saksı saksı çiçeklere verdim

kendimde seni aradım hepsine senin adını verirken.

Ben,

ben kayboldum çarkları arasında,

kendimi araken çarkları arasında,

yüzünü ararken, yüzünü hayal ederken.

Ben, 

ben kayboldum karanlığı içinde ormanların,

kokusunu duyamadan kızılağaçların,

sessizliğe gömülerek içimdeki konuşmalarım,

ruhumun peşinden giderken.

Ben,

yalnız ben vardım,

züğürtlüğüm ve yalnızlığım vardı,

hiçbir şeye denk değildim 

ve hiçbir şey benim dengim değildim.

ne aşağısındaydım, ne yukarısında

hep yanındaydım onların, onları ararken.

Anlamaya başladım...', 'Ben, ben yazdım seni okuduğum kitapların köşelerine kenarlarına papatyalar çizdim, ismini saksı saksı çiçeklere verdim kendimde seni aradım ...', ARRAY['Türk Edebiyatı','Şiir','Lzcramcil Ceyhun Erdem']::text[], 8.5, '{"poet":"Lzcramcil Ceyhun Erdem","poet_slug":"lzcramcil-ceyhun-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/anlamaya-basladim-anlamaya-kendimde-aramaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşikar', 'asikar-yasin-mortas-v5sox', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'l

izin verde

bakış tutanağı sırlanmış

buğusuz aynalardan

akışına karşı tutulmuş nehirlerden

ince köprülerden

çekim alanına

bir su olup ineyim

ılık bir akışla döneyim

ruhumun steplerine

ruhuma girdin de

neden

bilge ozanını çağırdın

sükût eden kuşlarımın

bak çırpınarak

deldi çıktı canımı

canı çekilmiş

bir şiiri

akıttın şimdi zamana

sessizliğe

bir dil ver ki

genç ozanın uykusuna

denizler taşsın

mısraları içinde kabaran

kımıltılara bıraksın

derin mağmalar aksın

yüreğinin çorağına

ll

sesini dağıtmak için tufan kuşanıyor şehri

diyetsiz yüzünün

görüntüsü bozuluyor

elvedanın ve hüznün

büyüttüğü yollar

uzuyor kıvrılarak

lll

artık sırlanmış sözleri

alacakaranlık sonunda ki

gülderen sevgilinin

dudağından çözüyorum

lV

yalın sesin

yalnız ve sözsüzlüğü

kelimenin sahiline çekilir

kulağa itilen

dilin tortusu

bir yığın kuşkuyla gelir

V

bilinsin ki

kahırlar aşka yanaşıp

kısık sesle çağrıldığında

içimizin okyanusuna açılan

bir geminin dönmeyeceği

aşikârdır

(kış''96)', 'l izin verde bakış tutanağı sırlanmış buğusuz aynalardan akışına karşı tutulmuş nehirlerden ince köprülerden çekim alanına bir su olup ineyi...', ARRAY['Türk Edebiyatı','Şiir','Yasin Mortaş']::text[], 8.5, '{"poet":"Yasin Mortaş","poet_slug":"yasin-mortas","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/asikar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazırlık', 'hazirlik-ozel-arabul-wx5js', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bıraktım bahar rüzgarlarını

Yaz güllerini, kuytularda sarmaşığı

Yüreğimin çalkantısını 

Sonbahar yağmurlarını

Nerdeydim ben, neresindeydi yerim

O yüzden bıraktım

Ölüleri ve aşkları

Şimdi tekbaşına, sizden daha ötede

Yeni bir güne hazırlanıyor kalbim', 'Bıraktım bahar rüzgarlarını Yaz güllerini, kuytularda sarmaşığı Yüreğimin çalkantısını  Sonbahar yağmurlarını Nerdeydim ben, neresindeydi ye...', ARRAY['Türk Edebiyatı','Şiir','Özel Arabul']::text[], 8.5, '{"poet":"Özel Arabul","poet_slug":"ozel-arabul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hazirlik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sancı Şiirleri/1* Bir Aşkın Otopsisi', 'sanci-siirleri-1-bir-askin-otopsisi-nermin-altindag-d7wyq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '... bahar vurgunu...

-kara talihimden bu yıl da

baharı görmeden yaz geldi geçti...-

		-Türkü-

Mutlu papatyalar alacağım bu bahar dostlarıma

Gümüş dişli mercan balıkları

Yosun tutmuş midye kabukları armağan edeceğim akvaryumlarına

Şarkılar besteleyeceğim kırmızı gözlü japon balıklarına

Muhabbet kuşlarına ninniler

Gel ey yar gözlerim çiğ bulutlarıyla kaplı

Yüzüm baharın alaz yangınlığında

Güneşim parlamalı yağmurların ardından

Gel ey yar şimdi sevmenin tam zamanı

İsterik bir aşkın esiri oldum

Özgürlüklerim gönlümün prangalarında

Dilimde hiç bilmediğim aşk şarkıları

Kullanmak istiyorum sevmek hakkımı

Nazım bir baharlık yanmalara meyilli

Hayallerim kelebek kanatlarında

Duy ey yar dudaklarımda eski bir sevda türküsü

Ellerin ruhumun taç yapraklarında

Baharın boynuma dolanmış hanımeli

Duy ey yar şimdi sevmenin tam zamanı

İstemem sönmesin yangınlarım

Bu bahar 

En mutlu sarhoşuyum bu diyarın

Kurşunlarım menzilsiz

Mutlu sabahlara ağyarlığımı 

Eski defterlerimde sakladım...

Deniz dibi vurgunlarıdır baharlarımı çalan

Şikayetim sadece hercai yanımdan

Gülümsemelerim gizli saklı değil artık

Güneşindir ruhumun aşk çanlarını çaldıran

Duydun ise gel ey yar 

Şimdi sevmenin tam zamanı

Tam zamanı...

Temmuz 2004 Bor/Niğde', '... bahar vurgunu... -kara talihimden bu yıl da baharı görmeden yaz geldi geçti...- 		-Türkü- Mutlu papatyalar alacağım bu bahar dostlarıma ...', ARRAY['Türk Edebiyatı','Şiir','Nermin Altındağ']::text[], 8.5, '{"poet":"Nermin Altındağ","poet_slug":"nermin-altindag","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sanci-siirleri-1-bir-askin-otopsisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin', 'hosgeldin-asuman-durbin-dqpup', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hoş geldin 

bir kere geldin ya

kolay değil hemen gitmek

önce yüreğime hayatıma dünyama girdin 

yüreğimin kapılarını acıp 

sorgusuz sualsiz geldin 

öyle sakin sessizce geldin ki 

sınırlarımı zorlamadan 

sessizce bir ateş yaktın

buyursun gelsin dedirttin yüreğime

geldiğinde gök gürledi

yağmurlar yağdı farkettin mi

aslında korunamazmıydım yağmurlarından

bulamazmıydım bir şemsiye

ama özlemişim ıslanmayı 

yüreğimin yangınını serinletti

yağan yağmurlar esen rüzgarlar

geldin ya 

artık ne yağmur ne dolu yağsa da

umursamam hiç bir şeyi

bir kez girdin mi hayatımdan içeri

tehlıkelidir benimle ben olmak

benimle yağmurda ıslanmak

geldın demek göze almak demek 

ben de ben olmayı 

yağmurlar da ıslanmayı

hoşgeldin hayatıma

hoşgeldin sınırlarıma

hoşgeldin yüreğime

canıma can katan 

hoşgeldin

31-10-2004', 'Hoş geldin  bir kere geldin ya kolay değil hemen gitmek önce yüreğime hayatıma dünyama girdin  yüreğimin kapılarını acıp  sorgusuz sualsiz g...', ARRAY['Türk Edebiyatı','Şiir','Asuman Durbin']::text[], 8.5, '{"poet":"Asuman Durbin","poet_slug":"asuman-durbin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/hosgeldin-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayâline dalmalı', 'hay-line-dalmali-sair-ahrazi-iy5vh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne gâibin denizinden ne de sırlı nehirden,

Seni dilediğim kadar dilemedim kendimi.

Ahh.çektiren bir üzüntü ele verir ya birden,

İsmine öyle giderim ben,dilde can tükendimi.

Umulan bir ufuktur bu,sabâhı tek ve nurlu,

Vatan gibi hayâlin var baş ucumda kalmalı.

Hicretteki meydan gibi yolcu kadar onurlu,

Yummalı bu gözleri de hayâline dalmalı…

 (ﺀ &#65152 ;)', 'Ne gâibin denizinden ne de sırlı nehirden, Seni dilediğim kadar dilemedim kendimi. Ahh.çektiren bir üzüntü ele verir ya birden, İsmine öyle ...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hayaline-dalmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sancı Şiirleri/2* Bir Aşkın Otopsisi', 'sanci-siirleri-2-bir-askin-otopsisi-nermin-altindag-korkq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '...yaz sanrıları...

-başındaki yazmayı da sarıya mı boyadın

neden sararıp soldun da sevdaya mı uğradın...-

-Türkü-

Yitik özlemlerimin kanatlarında saklı bahar

Bir kuş olup uçar her göç mevsiminde

Gidişinde yaşadığım kış soğukluğu

Gelişinde yağmur bereketi

Baharımın en alacasında 

Özlemlerim bir daha kanat çırptı

Renkli yaz akşamlarına

Yaz sıcağında kaynar çaydır hararetimi alan

Yanında bir de dumanını uzun uzun çektiğim bir sigara

Demirkazık yol olur zihnimi bulandıran dumana

Demirkazık keser yollarımı

Gidemem sana

Gelmezsin bana

bütün sarhoşluklarımın sebebi bahar

akşam sefalarının kokusunda saklı hazlarım

Kesildi yağmurlar

Bedenimi gevşeten yaz sıcağında 

Gözlerimi kapatıp kurduğum hayallerin tatlı yanısın

Gitmesem de sana 

Gelmesen de bana

Sen hep kalbimin sağ yanındasın...

Aşk sancısıdır üç beş zamandır çektiğim

Belki yazlarım bu yüzden bu kadar yangın

Dönüp ardıma baktığımda

Baharıma denk düşen bir mevsimdir yaşadığım

Yazlarım karıncalara yoldaş

Kış hazırlığı yapsam

Ambarımdaki heyecanlarım

Soğuk zamanların kefili olur mu diyedir merakım

Yaşadığım bir serapsa eğer

Ben susuzluktan yanmaya razıyım

Ağustos 2004 Bor/Niğde', '...yaz sanrıları... -başındaki yazmayı da sarıya mı boyadın neden sararıp soldun da sevdaya mı uğradın...- -Türkü- Yitik özlemlerimin kanatl...', ARRAY['Türk Edebiyatı','Şiir','Nermin Altındağ']::text[], 8.5, '{"poet":"Nermin Altındağ","poet_slug":"nermin-altindag","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sanci-siirleri-2-bir-askin-otopsisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açalya', 'acalya-cemal-ekren-fz2c9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ay yüzlüm açalyam,

Bozkırların gizemli kızı,gözlerin gözlerimde,

Bakışların firari kuşların kanat çırpışıydı

Bin efkar dağıtırdı gülüşlerin

  sıcaklığın keskin dağların karlarını eritirdi

kan dökülürdü köyün orta yerinde

orta yerinde yeni canlar gençleşir açalya

buğday sarısı saçlarını her taradığında

gökkuşağında isyanlar başlardı

bereketli yağmurlar yüreğimizdeki yangını söndüremezdi

gülücüklerin efkar dağıtırken bin kez ölürdük açalya

adını; 

dağlara taşarla yazardık

biz seni severdik sen kimi açalya

herkes saçlarını sana doğru tarardı

sen aynaya bakmazdın

bir tek ben ölürdüm sana

sana uzanan her kurşuna

ondandır gözlerin gözlerimde

her uyandığımda sen doğarsın gözlerimde açalya.

Sen konuşunca kuşlar susardı,

Sular  sessizliğe gömülürdü

Yangınlar başlardı yüreklerde

Bir ben  yanardım sana açalya

Sonrası yüreğime gömdüğüm yokluğundur.', 'Ay yüzlüm açalyam, Bozkırların gizemli kızı,gözlerin gözlerimde, Bakışların firari kuşların kanat çırpışıydı Bin efkar dağıtırdı gülüşlerin ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ekren']::text[], 8.5, '{"poet":"Cemal Ekren","poet_slug":"cemal-ekren","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/acalya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıyı Yar Ettik', 'aciyi-yar-ettik-sadik-softa-4qz09', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Açtık gönlü yiğitliğin serine,

Bir yara sardı ki,düştü derine,

Acıyı yar ettik, sevda yerine

Yaralarım azar oldu dinmedi.

Açıldıkça gönül açıldı O’na; 

Candan da öteye geçildi O’na; 

En güzel duygular seçildi O’na; 

Yürek alev alev yandı sönmedi.

Dilde bayrak ettik astık adını,

Gönle haval’ettik her an yadını,

Aşamasın diye “ben” maksadını; 

Çileden, acıdan geri dönmedi.

Bu yürekte sevda O’nunla vardır; 

Hüküm giydi gönül O’nunla yardır; 

Dönüşü yok, karar, kesin karardır; 

Sevdaya susadı, henüz kanmadı.

Tek O’nun yolunu gözlüyor gözüm; 

Tek O’nunla beni sözlüyor sözüm; 

Tek O’nun adını özlüyor özüm,

O’ndan başkasının adın anmadı.

Gerçek sevda ile bağlandı O’na; 

Gönül gizli gizli dağlandı O’na,

Gizliden gizliye ağlandı O’na; 

O’ndan başkasına böyle yanmadı.

Çankırı-19.09.2004', 'Açtık gönlü yiğitliğin serine, Bir yara sardı ki,düştü derine, Acıyı yar ettik, sevda yerine Yaralarım azar oldu dinmedi. Açıldıkça gönül aç...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/aciyi-yar-ettik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bildin Mi?', 'bildin-mi-sadik-softa-s490y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen, elim, ayağım, bakan gözlerim,

Sen, dilim, mısraım, akan sözlerim,

Sen, ateş  saçanım,  küllü közlerim,

Sen gönlümün gurbetisin bildin mi? 

Sen, gurbette baca, tüten dumanım,

Yürek  yenilgisi,  sen  tek amanım,

Beni sürükleyen  gerçek zamanım,

Sen gönlümün elbetisin bildin mi? 

Benim  yüreğimin  sahibi  belli,

Sevgiler  insanda  etmiş  tecelli,

Gönüller  umutla  bilmiş  teselli,

Sen gönlümün şerbetisin bildin mi? 

Gönlüm sende,gözüm sende,beklerim.

Yoğum sana, varım sende beklerim,

Sensizlikte, tüm kalbimde beklerim,

Sen gönlümün servetisin bildin mi? 

Çankırı-19.06.2004', 'Sen, elim, ayağım, bakan gözlerim, Sen, dilim, mısraım, akan sözlerim, Sen, ateş  saçanım,  küllü közlerim, Sen gönlümün gurbetisin bildin m...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bildin-mi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akik VII', 'akik-vii-ahmet-aksoy-9p8mm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '..........................................''üç noktalı bir şiir''

şimdi ya da asla, göğsüne batırılmış bir hançer gibi

çek çıkar beni ya da bırak içine saklanayım

öyle ki yıkılsın yıllar geçmişin kıllı omuzlarına

öyle ki kaldırılsın tüm ölüler tuluata

öyle ki bir ben ve bir sen olsun dağlar

sarmallanmış umutlar kaybolsun ve eski hayaller

ama unutma

.......ben seversem cennet olurum

bak yerle birdir aşka düşen yürekler

her şey yeşeren bir iklimdir doğaya

kan kusar sevenler sevgiye açsa açıksa

habersizdir ruhlar güneşe yağmur yağar aya kar

yüzler asılır belki kimi zaman duygu ağacına

eller krıırlı belki kimi zaman içten sözlere

ama unutma

.......ben seversem cennet olurum

şimdi ya da asla yazgına düşürülülmüş bir ayraç gibi

aç beni sonsuza, tanrı kadar olsun sevgim

ya da reddet inançsız içtiğim tüm antlara ve

bil ki biliyorum her şey gibi bir gün bu şiirler de biter

belki ben bin kez daha ölürüm uğuruna

işte fark tam burada eskiler hayat bir seçimdir derler

sen de unutma

.......ben seversem cennet olurum', '..........................................''üç noktalı bir şiir'' şimdi ya da asla, göğsüne batırılmış bir hançer gibi çek çıkar beni ya da bı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/akik-vii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne acı', 'ne-aci-mustafa-tugrul-kosar-mj2pe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aslında beni çok çok seviyorsun

Fakat ben bunu bilmiyorum

Biliyor musun? 

Bunu bilmemek ne acı...', 'Aslında beni çok çok seviyorsun Fakat ben bunu bilmiyorum Biliyor musun?  Bunu bilmemek ne acı......', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tuğrul Koşar']::text[], 8.5, '{"poet":"Mustafa Tuğrul Koşar","poet_slug":"mustafa-tugrul-kosar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ne-aci-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sancı Şiirleri/3* Bir Aşkın Otopsisi', 'sanci-siirleri-3-bir-askin-otopsisi-nermin-altindag-rg8tz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '...sonbahar...

-biz bu sonbaharda buluşacaktık

bahar geldi geçti sen gelmez oldun... -

-Azeri türkü-

Ah yok mu bu seni sevmeler

İçimi donduruyor,

Bir kış akşamı gibi seni sevmek

Erkenden bastırıveren

Uzun bir gece çöker ruhuma

Hiç bitmeyen bir karanlık

Hem de soğuk

Ah yok mu bu seni sevmeler

Savrulur yapraklar

Rüzgar soğuk eser

Gelenin kış olduğunu bilir 

Aldırmam yağmura

Sanırsın ki aşkın ısıtır ruhumu

Koyu

Siyah bir bulut çöker gözlerime

Kayıptır güneş

Hem de karanlık

Ah yok mu bu seni sevmeler

Ölüm gibidir sensizlik

Adım yazılıdır soğuk mermerlerin alnında

Ömrümü harcadığım bu kavganın ardında

Yaşamak ağır gelir omuzlarıma

Aldırmam diyemem, rüyalarımdır eriyen

Sıcaklığın ısıtır ruhumun üşüyen yanlarını

Senin sevgindir beni buralarda tutan

Gelen kış

Hem de ölüm...

Eylül 2004 Bor/Niğde', '...sonbahar... -biz bu sonbaharda buluşacaktık bahar geldi geçti sen gelmez oldun... - -Azeri türkü- Ah yok mu bu seni sevmeler İçimi dondur...', ARRAY['Türk Edebiyatı','Şiir','Nermin Altındağ']::text[], 8.5, '{"poet":"Nermin Altındağ","poet_slug":"nermin-altindag","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sanci-siirleri-3-bir-askin-otopsisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oy Karadeniz', 'oy-karadeniz-i-smail-ersin-dalgic-4dpo8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Temmuz ayı.

Düşüncelisin.

İzmir’e gözyaşı mı olacaksın,

Nafile.

Hiişt hiişt dedim, hadi gel.

Yalnızsın. 

Gece gündüz beraberdik,

O bana güldü, ben ona el salladım.

	Üstünden kalkmayan bulutlar,

	Hemen kaynaştılar.

Yaz yağmuru denecek şekilde,

Doğanın bin bir rengine, Karadeniz’e

	İnce giysilerle,

	Sudan çıkmış balık gibiyim.

Katıksız insanımızın,

Cömertliğine benzer.

	Bulut,

	Yağmur,

	Kısa pantolonla ben,

	Deniz,

	Bahtiyarız.

			İsmail Ersin Dalgıç

				30 Temmuz,2004', 'Temmuz ayı. Düşüncelisin. İzmir’e gözyaşı mı olacaksın, Nafile. Hiişt hiişt dedim, hadi gel. Yalnızsın.  Gece gündüz beraberdik, O bana güld...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/oy-karadeniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmasın', 'olmasin-i-smail-ersin-dalgic-0cxmh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yontula yontula, 

Neyim kaldı ki? 

 	Çocukken de! ...

Devletlerin dinlerin,

İtaat et emri.

	Okulda, meslek eğitiminde, 

	Askerlikte, memurlukta,

	Ve de 

	Din eğitiminde

	İtaat et.

Empati kuramayanlar,

Statükocular size sesleniyorum.

Bana ölünce mi, 

Söz vereceksiniz,

Hani benim özgüvenim.

	Yontula yontula, 

Neyim kaldı ki? 

Dayanılması çok güçtür,

S

U

S

M

A

K.

İsterseniz yaramaz,

Yasalara uymaz deyin.

Duygularımla, vicdanımla,

Özgüvenimin isyanıyla.

	Uygarlıksa adı kültürse,

	Hadiyin oradan be,

	Böyle itaat olmasın

		İsmail Ersin Dalgıç

			27 Ekim,2004', 'Yontula yontula,  Neyim kaldı ki?   	Çocukken de! ... Devletlerin dinlerin, İtaat et emri. 	Okulda, meslek eğitiminde,  	Askerlikte, memurlu...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/olmasin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şöhretlisin', 'sohretlisin-i-smail-ersin-dalgic-e7x6z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk nedir? 

Medresede ibadet,

Kilisede haç çıkarma mı? 

Havrada mum mu yakma? 

Nedir! 

	Evrensel orospu,

	Para! 

	Beğenmediğin çirkin kadının,

	Veya kıllı erkeğin,

	Koynunda mı yatmadır? 

	Nedir! 

Tabi ki senin hakkın,

Sevdiğin kadın yoksa,

Ve sevdiğin erkek.

Tüm canlara sövmek mi? 

Nedir! 

	Çocuğum ya şaşarak,

	Bulutlara bakarak,

	Doyasıya oyun oynamak gibi,

	Derin bir denize dalmak mıdır? 

Tün insanları özümseyerek,

Evet.

Ayrım yapmadan anlamak mıdır? 

Nedir! 

	Hayır canım,

	Sen ki,

	Dünyanın en kutsal varlığı,

	Ne medrese,

	Ne kilise,

	Ne havra,

	Ne para,

	Ne de küstahsın.

	Sen çocuk kadar,

Berrak,

Güneş kadar parlak,

Satın alınmayacak kadar şöhretlisin,

İnsansın insan.

		İsmail Ersin Dalgıç

			

 			18 Eylül,2004', 'Aşk nedir?  Medresede ibadet, Kilisede haç çıkarma mı?  Havrada mum mu yakma?  Nedir!  	Evrensel orospu, 	Para!  	Beğenmediğin çirkin kadını...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sohretlisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Şakağında', 'gunesin-sakaginda-i-smail-ersin-dalgic-lgo5u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben neden diğerleri gibi değilim,

Neden! 

Soyut ve somutu algıladığımdan mıdır? 

	Benim ibadetim insan,

	Cenneti cehennemi kahinatta aradım ben.

Bilsem ki tanrım,

Canımı aldın,

Doğumdan önceki,

Ölümden sonraki senin,

Geri kalan benim.

İstesen de alamazsın ki.

	

	Çılgın gönlümü bilenler,

	Bizi merak ediyorsan,

	Güneşin şakağından,

	Yıldızları görenlerdir.

			İsmail Ersin Dalgıç

				1 Ekim, 2004', 'Ben neden diğerleri gibi değilim, Neden!  Soyut ve somutu algıladığımdan mıdır?  	Benim ibadetim insan, 	Cenneti cehennemi kahinatta aradım ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gunesin-sakaginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oturduğun Yerde Uyuyorsun', 'oturdugun-yerde-uyuyorsun-i-smail-ersin-dalgic-g7r2s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Musa, 

Davut,

İsa,

Muhammet,

Muhabbet etmek istiyorum,

		    muhabbet.

Hanginizden başlasam,

Aranızda pek fark yok,

Hep aynı konu, cennet cehennem,

Aynı korku her zaman.

	Hanginize el atsan,

	Biyoloji, kimya ne de bilim,

	Bu mu felsefe hani eşitlik? 

	Hiçbiriyle ilgisi yok.

Din adına adam öldürme,

Ganimet ve zulüm.

Bu yolda mağluptur galip olan.

	Sıkıldım pencereyi açmak,

	Kaçmak istiyorum kaçmak.

	Çoğalmak istiyorum,

	Düşüme diken battı,

	Çıkartmak istiyorum,

		      çıkartmak.

Hegel,

Maks,

Engels,

Mantığına uymayandan vazgeç,

Usuma sesleniyorum, usuma er geç.

	

	Pek uzak değil,

	Mevlana,

	Yunus,

	Pir sultan,

	Bedrettin,

	Hümanist  toplumcu değerler.

Hemen yanımda,

Aydınlanma rönesansı yakalayan,

Nazınım Hikmet,

Yaşar Kemal,

Aziz Nesin,

Ataol Behramoğlu,

Gibi aydınlar.

Boşluktayken,

Üzerine ayaklarım bastırdılar.

	

	Sımsıkı insana sarıl,

	Sar,

	ma,

	lan,

	sakın bırakma.

Bağırmak istiyorum,

Çoğalmak istiyorum çoğalmak.

Dünya pazarında,

Para karşılığında olanla olmayan,

Ayan beyan, düşünden,usundan,

Gelin hep beraber paylaşalım.

Kardeş olalım,

K

A

R

D

E

E

Ş.

	İsmail Ersin Dalgıç

		11 Ağustos, 2004', 'Musa,  Davut, İsa, Muhammet, Muhabbet etmek istiyorum, 		    muhabbet. Hanginizden başlasam, Aranızda pek fark yok, Hep aynı konu, cennet ce...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/oturdugun-yerde-uyuyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemin', 'yemin-i-smail-ersin-dalgic-9g9kp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sayın Nazım Hikmet Ran,

Saygıyla eğilmem lazım önünde ah,

Seni okudukça beni tanıdım.

	Sanki yeni insan, yeni biri oluyorum,

	Seni her keşfettikçe, dünyayı kucaklıyorum. 

Sanki evren bana küçük geliyor.

Sanki usumda ışık yeni bir gün doğumuyum.

	Öyle anladım ki seni tanımasaydım,

	Kalmış olacaktım karanlıkta.

Nasıl bir dünya görüşü,

Nasıl bir evrensel bakış,

Çektiğin eziyet cezaevi ve sürgün.

	Yinede gülerek hiç yaşamamış gibi,

	Eşitlikten paylaşmadan yana olman.

	Kaç tane insanda vardır sendeki bu cevher.

İyi ki doğmuşsun  erken öldün,

Senden çok yaşayan çoğu insandan,

Daha çok ömürlü daha çok çoğalacaksın.

	Ah benim talihsiz başım,

	Sıralarında tanısaydım seni ilk okul.

	Benim elimde mi ki şartların gözü kör olsun.

Ikına sıkıla yazdığım dizeler için üzgünüm,

Doyurucu olmadı biliyorum,

Bağışla beni ne olursun.

	Sen ki insanlık kardeşlik bayrağını,

	Son nefesine kadar taşıdın,

	En zor koşullarda da olsa.

Ben ki bu düşünceyi,

Ölünceye kadar taşımazsam yeminler olsun.

		İsmail Ersin Dalgıç

			9 Haziran, 2004', 'Sayın Nazım Hikmet Ran, Saygıyla eğilmem lazım önünde ah, Seni okudukça beni tanıdım. 	Sanki yeni insan, yeni biri oluyorum, 	Seni her keşfe...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yemin-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizzat büyüyüverdim.', 'bizzat-buyuyuverdim-lzcramcil-ceyhun-erdem-s1kiw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dönem dönem terk ettim kendimi,

bizzat ağlamaklı oldum bu durumdan,

zamanın yaşlandırmasıyla, uzak bir başka zamanda

bana ait olmayan bir dünyada,

bizzat büyüyüverdim

o varlık acıları sardı dört bir yanımı,

üzülmekten alamadım gözlerimi,

ve ellerimi, nasırlı, kirli, hayat işçisi ellerimi

Dönem dönem takılıp kaldım kelimelere

kadınlara takılıp kalmış gibi

aklımdan çıkaramadım seslerini,

yüzleri girdi, sözleri girdi uykularıma

hep taze bir anı kaldılar yüreğimde

...', 'Dönem dönem terk ettim kendimi, bizzat ağlamaklı oldum bu durumdan, zamanın yaşlandırmasıyla, uzak bir başka zamanda bana ait olmayan bir dü...', ARRAY['Türk Edebiyatı','Şiir','Lzcramcil Ceyhun Erdem']::text[], 8.5, '{"poet":"Lzcramcil Ceyhun Erdem","poet_slug":"lzcramcil-ceyhun-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bizzat-buyuyuverdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakma Aynaya', 'bakma-aynaya-mustafa-ceylan-cjijy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşam oldu, bakma sakın, bu yalancı aynaya

Pas tutmuş çivilerle asan asmış duvara 

Kaç göz ağlamıştır karşısında kim bilir? 

Dön sırtını, boş ver gitsin, aldırma sen! 

Görüyorsun ters dönüyor değirmen …

Bir aynalı çarşı bekler seni, senin içinde

Aşkının boy boy görüntüsü orada gülüm

Eksilmesin dilindeki güzel türküler

Anılar var, yüreğinde çiğdemleşen

İyi bak değirmene, nasıl da şen…

Akşam oldu, bakma sakın, bu yalancı aynaya

Kendine çağırmıştı doğduğun gün, bu toprak

Ebediyen kalamazdı dalda bir yaprak…

Yaşa, yaşat sevdanı hiç düşünmeden! 

Nasıl döner biliyorsun değirmen…', 'Akşam oldu, bakma sakın, bu yalancı aynaya Pas tutmuş çivilerle asan asmış duvara  Kaç göz ağlamıştır karşısında kim bilir?  Dön sırtını, bo...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bakma-aynaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunma Duyusu', 'dokunma-duyusu-mustafa-ceylan-gi4xn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'DOKUNMA DUYUSU

Ne nefes, ne dil,

………………Ne burun, ne kulak

Bırak ey gözlerim, onları bırak

Gel şu dokunmanın sihrine bak…

Bir aynadır her hücrede duyarga

“Tık! Tık” eder parmaklarım kapıya

Mavi güller açar yüreğinde zamanın 

Kesilir ağıtları ana göğsünde

Başı okşanan çocukların…

Ve hasret biter…

*

Hıçkır,

………….Esne

…………...............Uyu

Züleyha’nın yüreğidir bunu bil

…………………………….Yusuf’a kuyu…

Elma bıçağından kanayan parmak değil…

Nar çiçeği ağzında su damlası neyse

O’ dur çöllerde Mecnun’un Leyla’sı…

Su okşar, yel üfürür, gül dokunur gülüm

Ozan sazının tellerinden yürek okunur:

	“Çağır Karacaoğlan çağır

	Taş düştüğü yerde ağır

	Yiğit sevdiğinden soğur

	Sarılmayı sarılmayı…”

Bu özlem haykırışı, söyle niçin? 

Bunca çile, bu öldüren kara sevda

Dokunmak için…

*

Ara, bak, gör, 

………………Bil, bul, ol… 

Eritmeli sıfatları oğul, sıfatların içinde… 

İçinin dehlizinde nice şehir ışıkları yanıp söner

Ağrıları dindiren bir İstanbul toprağı mı

Dokunmayı beklediğin

Veysel’in sadık dostu mu özlediğin o yer? 

Ölmeden evvel ölmeli insan dediğin…

Dokunduğunda bana, yıkarım dağları

Süslerim masmavi yangınlarla düşlerimi

Bir anda barışa dönüşür ruhumdaki kavga

Günahlardan temizlenir defter

Kelebek nabzı avuçlarımda gayri sıla

Ve gurbet biter…

Her müzede, taş heykeller önünde 

Aynı levha:-“Lütfen dokunmayın! ”

Şaşırır kalırım…

“Hacer-ül Esved” giderir ancak damar damar

Parmağımın sancısını, yüreğimin acısını

Sevinçten ağlar, ağlarım…

Bin aşk taşır her hücrede duyarga…

Ve sohbet başlar…

…', 'DOKUNMA DUYUSU Ne nefes, ne dil, ………………Ne burun, ne kulak Bırak ey gözlerim, onları bırak Gel şu dokunmanın sihrine bak… Bir aynadır her hüc...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/dokunma-duyusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'III/Resim', 'iii-resim-ali-gencay-2wbg4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bembeyazdı saçları

briyantinle geriye taralı

oturmuş koltuğuna

göbeği ikiye katlı

kulakları arkasından bağladığı

kemik çerçeveli gözlüğü,kalın camlı 	

inceliyordu eskilerden kalmışları

okşadı simsiyah saçlarını çocuğun

meraklı gözlerle

baktığı fotoğraftaki tüm yüzlerde

Mithat beyi aradı

takıldı sayfada ihtiyar

burnun ucunda gözlük

ha düştü,ha düşecek 

iyice gözüne yaklaştırdı

bakışları buğulandı 

çocuk sordu kim bunlar? 

önce derin bir çekti

anlattı; 

aylardan nisan

gelinlik giymiş kiraz ağaçları 

giyilmiş mintan 

pantolonu omuzdan askılı

güzeldi kız

saçları ortadan ayrı

sırtını vermiş ağaca 

sevgilinin başı göğsüne yaslı

gözler kilitlenmiş uzaklara 

son gündü

doldu askerlik pusulası

yürekte ayrılık acısı

ihtiyar suskunlaştı

sordu çocuk,ya! sonra; 

koltuk gıcırdadı

yavaşça kapadı kapağanı albümün 

pencereye yaklaştı

görsün istemedi,ağlayacaktı

titrek sesle anlatmaya başladı tekrar 

uğurladık davullarla zurnalarla

son kez eller sallandı

uzun zaman sonra

askerliğinin on dördüncü ayı

izine yollandı

istasyona geldiğinde 

onu aradı gözleri

yoktu! 

oysa mektupta yazmıştı

onu karşılayan çocukluk arkadaşı Mithat’tı

dayanamadı sordu

nerde,neden gelmedi

yutkundu Mithat gözleri yere baktı

uzun zaman önce

göğsünü öksürük sardı

ince hastalıkmış

doktorlar çaresiz kaldı

çok istedi son kez görmeyi seni

sana haber etmememiz için yalvardı

ecel onu bizden zamansız aldı

dizleri üzerine düştü

inanamadı,inanmadı

yıkılmıştı,perişandı

uzun sürmedi ecel  onu da  aldı

işte dedi ihtiyar

onlardan geriye sadece bu kaldı', 'bembeyazdı saçları briyantinle geriye taralı oturmuş koltuğuna göbeği ikiye katlı kulakları arkasından bağladığı kemik çerçeveli gözlüğü,kal...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/iii-resim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük', 'dortluk-i-smail-ersin-dalgic-x91fg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Takip ettin, tahrik ettin,

Kırık dökük sevgiyle,

Gönül boşluğumu keşfettin.

Karşıma çıktın,

Ben sormadım,

Elimden tuttun,

Yüz vermedim,

Yüzüme güldün,

Sır vermedim.

Yanağından öptüm,

İz kalmadı,

Sana söyleyecek,

Söz kalmadı.

Seninle gidilecek, 

Yol kalmadı.

Bu nasıl sevda? 

İsmail Ersin Dalgıç

			12 Eylül, 2004', 'Takip ettin, tahrik ettin, Kırık dökük sevgiyle, Gönül boşluğumu keşfettin. Karşıma çıktın, Ben sormadım, Elimden tuttun, Yüz vermedim, Yüzü...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dortluk-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sönmesin', 'sonmesin-i-smail-ersin-dalgic-guwk1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep onu bekledim,

Ama hiç usanmadım,

Hiçbir şey de yok,

Bu nasıl bir duygu? 

İçimdeki fırtınalar,

Sevdiğimi hatırlar,

Hayal mi gördüm,

Yoksa düş mü bu.

Güneş kadar parlak,

Yıldızlar kadar gösterişli,

Hanımeli,

Ebruli kadınım.

Sevdin mi çocuk gibi seveceksin,

Tertemiz duygularla,

Hiçbir karşılık beklemeden,

Tüm benliğinle katılacaksın,

Emeğinle bedeninle.

Uyan be aymaz,

Yine rüya görüyorsun,

Vurgun yemiş dalgıç gibi,

Sönmesin,

Dur be düşüm,

Ümit ışığım.

	İsmail Ersin Dalgıç

		28 Şubat, 2004', 'Hep onu bekledim, Ama hiç usanmadım, Hiçbir şey de yok, Bu nasıl bir duygu?  İçimdeki fırtınalar, Sevdiğimi hatırlar, Hayal mi gördüm, Yoksa...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sonmesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Taşım Hakkı', 'bir-tasim-hakki-ahmet-hakan-yilmazturk-e45j6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Cezve içinde, bir taşım hakkı şu ömrüm

Kuş kadar canı, çırpınır durur şu gönlüm

Dört duvar kalmış virane köşkdür şu ömrüm

Toy kanadında savrulan tüydür şu gönlüm

Cüzdandan düşmüş, soluk fotoğraf şu ömrüm

Defterden kopmuş, dertli paragraf şu gönlüm

Güneşe doymuş, olgun günaşık şu ömrüm

Ateşe uçmuş, şaşkın pervane şu gönlüm

Boynunun borcu, sen de ödersin be ömrüm

Aşığın zulmü, sen de çekersin be gönlüm

01.11.2004

***Samanyolu Grubunun 2K1Ş ''İki Kelime Bir Şiir'' Aktivitesine katılmıştır. Kelimeler: FOTOĞRAF ve KUŞ', 'Cezve içinde, bir taşım hakkı şu ömrüm Kuş kadar canı, çırpınır durur şu gönlüm Dört duvar kalmış virane köşkdür şu ömrüm Toy kanadında savr...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-tasim-hakki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüce Kudret', 'yuce-kudret-ali-kilic-kakiz-qoutn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kulak ver, bir damla sudan, yaratan Rabbine.

İlk tecelli  hira nur dağında indi Resûlün kalbine.

Vahyi getiren, kaza  kaderi yazan melekler.

O melekler, beyaz elbiseler içinde geldiler.

Her uzva işaret vurulmuş,kemiklere  giydirilmiş et.

Rızkını ecelini onaylamış, sonsuz yüce  kudret.

Liege / 1985', 'Kulak ver, bir damla sudan, yaratan Rabbine. İlk tecelli  hira nur dağında indi Resûlün kalbine. Vahyi getiren, kaza  kaderi yazan melekler....', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yuce-kudret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim Seni Arıyor.', 'gozlerim-seni-ariyor-ali-osman-yilmaz-4m9l1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Penceremin camından,

Parıldayan yıldızlara,

Ay dedeye bakıyorum,

Usulca sahile iniyorum.

Sabah güneşinin sıcaklığı,

Isıtıyor tenimi.

Gözlerim seni arıyor,

Göremiyorum.

Sen olmayınca yanımda

Bir isyan patlıyor içimde.

İstemiyorum hiç birini,,

Güneş’i,Ay’ı,Yıldızları,

Sahilde de yürümeyeceğim artık,

Al denizi ve her şeyi,

Yaşadığın yere götür,

Bana yalnız senin,

Yastığımda kalan,

Sarı saçının tek teli,

Teninin kokusu yeter.

Gerisi mi? 

Al senin olsun.', 'Penceremin camından, Parıldayan yıldızlara, Ay dedeye bakıyorum, Usulca sahile iniyorum. Sabah güneşinin sıcaklığı, Isıtıyor tenimi. Gözleri...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gozlerim-seni-ariyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martılar Şahit.', 'martilar-sahit-ali-osman-yilmaz-msilf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani o geceler,

Geceler boyu sahilde,

El ele birlikte yürürken,

Yıldızları seyreder,

Denizin hışıltısını,

Dinlerdik birlikte.

Bir kayanın üstüne oturur,

Geleceğin düşlerini kurardık.

Ellerimizi semaya açıp,

Tanrıya dualar ederdik.

Yine gece,ve ben,

Sahilde yürüyorum,

Sen yoksun yanımda,

Bir başıma yalnız,

Yıldızları bakıp,

Dalgaların sesini dinliyorum.

Bir kayanın üstüne oturup,

Gelecek günleri değil,

Sana kavuşmayı düşlüyorum.

Ellerim semaya açık,

Martılar şahit,

Tanrıdan beni sana,

Kavuşturmasını diliyorum.', 'Hani o geceler, Geceler boyu sahilde, El ele birlikte yürürken, Yıldızları seyreder, Denizin hışıltısını, Dinlerdik birlikte. Bir kayanın üs...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/martilar-sahit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsaf iki işareti', 'i-nsaf-iki-isareti-akin-akca-3bwqs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'alien forehead; go ahead, whata grace kick your acne kick your ace 

benim kendimi çirkinleştiren ve doğrultan yine kendini …

- 

Bu işaret, 

Tilki bir 

duruşu... 

Tutku silsin senin gözyaşlarını 

ama kendin çıksın samimi duyguları! 

Yin ve Yang’daki, Lao Tzu … 

İki insaf işareti, 

Bunlar her şeyin gizi 

başta birisi, diğeri sonda …

Bir kubbe örtüyor 

bunların ikisini, 

bir çember … 

İki insaf işareti, 

boğazdan geçen 

her lokmanın 

ve/ ama dirayeti … 

Kini, 

ve yavaştan 

belli oluyor 

süründürdüğü … 

Ve bu kuş, 

kubbeye yapışık sürünen: 

Elin avuç içlerinde aslında; 

farkında, her şeyin gizi … 

Kanatlarını çırpıştırıyor 

uçmadığında; 

Yöneltiyor doğru 

sana, 

kanatlarını..

havalandığında! …', 'alien forehead; go ahead, whata grace kick your acne kick your ace  benim kendimi çirkinleştiren ve doğrultan yine kendini … -  Bu işaret,  ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/insaf-iki-isareti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne oldu?', 'ne-oldu-kadir-soyturk-h4l38', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne var, ne oldu  diye  tarih  sual  ederse:

-Evlatlar  kurban  oldu  ve    analar  ağladı; 

Adalet  dağıtmadı  hukuk  terazileri

Zulmü  alkışlamaktan  eller  nasır  bağladı...', 'Ne var, ne oldu  diye  tarih  sual  ederse: -Evlatlar  kurban  oldu  ve    analar  ağladı;  Adalet  dağıtmadı  hukuk  terazileri Zulmü  alkı...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ne-oldu-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağlık', 'saglik-ekrem-sama-mov2l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sağlığın alternatifidir, hastalık,

Ölüm ikisine de yakın; bir anlık.

(İstanbul:31.10.2004)', 'Sağlığın alternatifidir, hastalık, Ölüm ikisine de yakın; bir anlık. (İstanbul:31.10.2004)...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/saglik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Ulusa Davet', 'ulusa-davet-ahmet-turan-altunsu-vi74x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Millet olmuş koyun gibi, 			

Nerde onca Kangal iti,			

Koyunların yok sahibi; 			

Takmıyor çoban Ahmet'' i! ...			

			

Aç kurtlar sarar sürüyü,			

Millet çalar düttürüyü,			

İktisadî ''''götürü'''' yü,			

Uygular, yerler devleti! ..			

			

Siz hâlâ ''''hoşgörü'''' deyin,			

Büyük ümitler besleyin,			

Hâttâ daha da süsleyin; 			

Semirtin mel''un illeti! ..			

			

Cumhuriyet, mumhuriyet…			

Bırakın uyusun millet! 			

Tasalanma; böl, böl hallet,			

Kemik senin, senin eti! ...			

			

Verdikleri gün sayılı,			

Sayıverin onca yılı,			

Vaat nah böyle kayılı; 			

Mutlu edin sadareti(!)  			

			

Turan der ki uyan halkım,			

Talkı bırak, işte salkım! 			

Seni bekler Büyük Ülkü''m; 			

Kaçırmayın bu daveti! ..			

			

	31.10.2004 / Ankara', 'Millet olmuş koyun gibi, 			 Nerde onca Kangal iti,			 Koyunların yok sahibi; 			 Takmıyor çoban Ahmet'' i! ...			 			 Aç kurtlar sarar sürüy...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ulusa-davet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Aşık', 'yalanci-asik-ahmet-turan-altunsu-ew7ct', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'artık bana sevgilim desen, canım desen ne yazar? 	

sanma ki yüreğim pır pır eder,				

canlanır gözlerimdeki ışıltılar! ..				

				

sende bir çakmak haresi,				

bende şimşek şeraresi! ..				

yutar vallahi seni; 				

şiddeti, volkan patlaması kadar! ..				

				

hayhuyları unuttum,				

varsayımlarını da düşünmüyorum; 				

biliyorum ki artık,				

yaşanacak başka aşklar da var! ..				

madem ki seçtin yolunu; 				

var, git; uğurlar ola! 				

elbet konacak bir gönül bulunur; 				

geçmesin yeter ki son bahar! ..				

				

		31.10.2004 / Ankara', 'artık bana sevgilim desen, canım desen ne yazar? 	 sanma ki yüreğim pır pır eder,				 canlanır gözlerimdeki ışıltılar! ..				 				 sende bir...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalanci-asik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ser’e Naat', 'ser-e-naat-ahmet-ferit-cosan-m6q3j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beyazlı bir vapurun bacasına kazınmış, 

tomurcuğa durmuş güldür 	hasretin….

Gözlerinle ezilmiş

Bir avuç dokudur bu yürek,

Ahenkli darbelerinden,

Lime lime kızıl özlemin sızdığı.

Maviş safirim! 

Özlediğim kadınım,

Sevda ile nehir olup,

Sana akmaktadır her anı zamanın…

Hayalin ve anılarla 

Her bir demimdesin.

Ceylan gözlerinle mühürlüdür

Mutluluğa dair tüm hayatım.

Ey ete kemiğe bürünüp

Yücelerden nurlu kanatlarla süzülmüş 

Hacer-ül Esved’im; 

Maşukun olmak,

Göz dahi kırpmadan,

Seksen bin aleme meydan okumaktır…

Sen ki,

Sen olunca 

Dimağımın yegane mevzusu,

Yağ olur kayar sarfedilen yekün kelimeler…

Sesin içimde çağıldayan şelaledir, 

Ulu sularla bir olup, 

“Bir”e koşan... 

Ki birlik hem ummanda hem çiğdedir, 

İçinde senli güzellikleri 

Vedahi rahmeti taşıyan..

Sen ki ey sahra-i kebir; 

Kıtaları ev yapmışsın,

İçerisinde uyurken usul usul seyrine daldığım. 

Didarının coşkusu ile kendi dizelerimde, 

Dizin üstüne başım koyup,

Senli güzelliklere varmışım....

----------------------

“Kuş olmak ve uçmak sana” dileğinin kabul görmesi,

Bir nota olabilmek kadar uzak

Ve sevebilmek kadar olası.

Hasretin beter odu ki kahrolası…

----------------------', 'Beyazlı bir vapurun bacasına kazınmış,  tomurcuğa durmuş güldür 	hasretin…. Gözlerinle ezilmiş Bir avuç dokudur bu yürek, Ahenkli darbelerin...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/ser-e-naat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemek', 'yemek-i-smet-barlioglu-jpdfe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hödük bir aşçının eline düştüm,

Pilavımı çorba etti etlice.

Kaşıkla çorbaya girdim, giriştim,

Çorbam vernellenmiş, hem de sütlüce.

Tavaya yapışmış çıkmaz omletler,

İçinde oynuyor sarı meretler,

Meğer civciv imiş işbu veletler,

Biri çatalımda biraz götlüce.

Tabak getirdiler bin takla tukla,

Tabağın içinde yemek bir okka,

Çorap gibi bir şey, güya musakka; 

Patlıcan fazla kart, hem de köklüce.

Reddettim, yerine geldi fasulye,

Demirden diş gerek bunu yemeye,

Tanen,n her biri bir çelik bilye,

Kırıldı üç dişim biraz derince.

Dedim ki; ‘Al bunu, bir güveç getir,

Bari ziftleneyim ben lüpür lüpür.’

Güveçte bir şeyler ediyor tir tir; 

Meğer çekirgeymiş, hem de evlice.

Bir rosto istedim dana etinden,

Bir dana geldi ki; savuş önünden,

Kalmışmış da geçen bayram gününden,

Bıçağın ağzından daha keskince.

Övülüp masama konuldu börek,

Çiğnerken ağzımda dil oldu kürek,

Fırlattım ağzımdam yelemyelpirdek,

Manda derisinden daha dirice.

Pilavsız bir döner istedi gönlüm,

Geldi bir tabakta eti ölünün,

Döneri mi olur katır gönünün? 

İnattan taşlaşmış, öyle sertlice.

Zordan razı oldum sulu köfteye,

Yersin mum yakarsan ancak dedeye,

Ne yutmaya gelir, ne çiğnemeye,

Şab katmış ol inek ete, pirince.

Domates dolması dilime battı,

Çatalla, bıçakla pek çabalattı,

Dolmalar tabakta epey kıç attı,

Bir lokma zor aldım, az efendice.

Sığındım sütlaca kaşıkla güya,

Kasenin içinde avuçla boya,

İstersen çal oğlum, istersen oyna,

Ne kıvrak, ne oynak, az-çok delice.

Sütlaca çorbayı bir güzel kattım,

Masanın üstüne döktüm, boşalttım,

Garsonun başına rosto fırlattım

Karşımda saygıyla biraz gülünce.

Dışarı çıktım ki yaylanıyorum,

Gördüğüm şeşleri beş sanıyorum,

Habire konuşup sazlanıyorum,

Görenler sandı ki içmiş bu gece.

(DAT DARA LİLLİM isimli Şiirsel Gülmeceler ''inden > 54-56/100)', 'Hödük bir aşçının eline düştüm, Pilavımı çorba etti etlice. Kaşıkla çorbaya girdim, giriştim, Çorbam vernellenmiş, hem de sütlüce. Tavaya ya...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/yemek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eteği Sağlam Kadın', 'etegi-saglam-kadin-bekir-gedikoglu-yyjpu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eteği sağlam mı? 

Alacaksın o kızı

Başına koyacaksın 

Sevginin bir tacını

Sağa sola baktın mı? 

Eteği zil çaldı mı? 

Müjde geliyor sana 

Aş kalbinin kapsını

Gözündeki aynayı

Yıldızlar kapladı mı? 

Odur şu anda senin

Hayatının kadını

Hayatında azabı

Artık tatmadığını

Şimdi anlıyor musun 

Odur bir hak kadını

Ateşin yaktığını

Kötünün nazarını

Sen ondan öğrenecen

Erdemlinin hayrını

Bilirsin yaradanı

Kalbindeki duranı

Gedikoğlu diyor ki

Sakla sevdiğin kızı

Kolla sevdiğin kızı

Hoş et sevdiğin kızı

Ankara 1 Kasım 2004', 'Eteği sağlam mı?  Alacaksın o kızı Başına koyacaksın  Sevginin bir tacını Sağa sola baktın mı?  Eteği zil çaldı mı?  Müjde geliyor sana  Aş ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/etegi-saglam-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '- - A k r e p...v e...Y e l k o v a n....(10)', 'a-k-r-e-p-v-e-y-e-l-k-o-v-a-n-10-metin-eser-h8w2l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ve kadınla elele, koltuğa yürüdüler,

Bunla beraber bir de, niyeti sürüdüler,

Oturdular koltuğun, yakın bir kenarına,

Bakışlar dokunmuştu, yüreklerin nârına.

Önce kısa bir süre, sessizce bakıştılar,

Sanki yürekte açan, en güzel nakıştılar,

Ne kadar diretse de, içteki ''hayır'' sesi,

Yine galip gelmişti, dudakların busesi.

Önce hafifçe değdi, nefesleri sıcaktı,

Heyecan içte alev, yüreği yakacaktı,

Sonra adam elini, yanağına değdirdi,

Kadın bakışlarını, hafif yere eğdirdi.

Masum bir hali vardı, ''üzme beni'' der gibi,

Ve halindeki mana, ''çözme beni'' der gibi,

Ama vücut yanıyor, bedenler tutuşuyor,

Bülbül gibi şakıyan, o diller susuşuyor.

Ve adam girdi söze, ''hoşlanıyorum senden'',

''İlk gördüğümden beri, aklımı aldın benden'',

''Hafızam zaten kayıp, hayal sana takıldı'',

''Ahh bir bilsen içimde, ne ateşler yakıldı''.

''Fakat inan ki bana, seni üzmek istemem''

''Eğer varsam içinde, herşey olur tastamam'',

''Varsın şehvani istek, arzumuz tutsak olsun''

''Ama kalbinde yerim, her an lebaleb dolsun''.

Ve kadının gözleri, tekrar adama baktı,

Nemli göz pınarından, sıcak bir damla aktı,

Yanağından süzülüp, ordan göğsüne değdi,

Az önceki bakışı, tekrardan yere eğdi,

Gözyaşı damla damla, yürekten sökülmüştü, 

Şu iç yakan sözleri, dilinden dökülmüştü,

''Çok hassastır yüreğim, kırılmaya gelemez'',

''Ve saftır hep niyetim, yalan dolan bilemez'',

''Ben de senden hoşlandım, hastane de ilk gece'',

''Ama sustum sabırla, kalbimdeydi her hece'',

''Sen komada yatarken, gelip seni seyrettim'',

''Elimde değil inan, ben de sana meylettim''.

''Ve şimdi tut kalbimi, duy içteki halimi'',

''Hatıramda bırakma, insafsız bir zalimi'',

''Eğer emin değilsen, geçiciyse hislerin'',

''Bırak yerinde kalsın, bir anlık heveslerin''.

Adam mutlu bir halde, onu sıkıca sardı,

Çünkü saf yüreğinde, bambaşka hisler vardı,

Dedi ''inanki bana, seni ağlatmak haram'',

''Şu kurşun yarasından daha derindir yaram''.

25.Haziran / Los Angeles

*** ''Akrep ve Yelkovan'' Şiir Roman 11. bölümüyle 2.Kasım.Salı günü devam edecek.

