INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karga ile Kılavuz', 'karga-ile-kilavuz-osman-erdogmus-8ox2c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'KARGA İLE KILAVUZ

Arkadaşına dikkat 

Etmelisin ey insan.

Kılavuzun kargaysa

Çıkmazsın bataklıktan.

Neleri geldi geçti

Nelerini gördük biz.

Arkadan hançerlenmek

Nasıldır bilirsiniz.

Kargaların gıdası 

Nasıl pislik ve leşse.

Hamuduyla götürür

Onun değil beleşse.

Fare gibi kemirir

İnsanı hayırsız dost.

Dayanılmaz hal alır

Çelikten olsa da post.

Kırk yıl taşı sırtında 

Yine yaranamazsın

İyi gün dostlarını

Asla doyuramazsın.', 'KARGA İLE KILAVUZ Arkadaşına dikkat  Etmelisin ey insan. Kılavuzun kargaysa Çıkmazsın bataklıktan. Neleri geldi geçti Nelerini gördük biz. A...', ARRAY['Türk Edebiyatı','Şiir','Osman Erdoğmuş']::text[], 8.5, '{"poet":"Osman Erdoğmuş","poet_slug":"osman-erdogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/karga-ile-kilavuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Orucu+', 'ask-orucu-bayram-tunca-ghmxr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ancak yıllar sonra aşkınla bozdum aşk orucumu

Aşkınla ödüyorum kalbime olan şükran borcumu

Bilmem nasıl öderim, sana olan minnet borcumu

Hep razı etsem, ödemiş olur muyum ki borcumu

01.11.2004-11:01

''Aşk Ateşten Gömlek''', 'Ancak yıllar sonra aşkınla bozdum aşk orucumu Aşkınla ödüyorum kalbime olan şükran borcumu Bilmem nasıl öderim, sana olan minnet borcumu Hep...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ask-orucu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sekizinci Düzlem', 'sekizinci-duzlem-sule-aydemir-n0t6h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '__________________cevap veriyorum

hakaret ediyorsun

ağlıyorum

aslında

hıçkırıksın

nasıl da saçma

yarışmak zamanla

durdurabilsem

sanatçı da değilim ki -ah

hissettigim

birini asmışlar gözyaşlarına

asarken kopmuş bağlar

boğulmuş zamanda

arkasına alayı dizilmiş

becerinin alkışları tabutlar

boyutlar açılmış

birden yediye kadar

madritler kuşatmış

kaldığım 

ATeşTEN dört duvar', '__________________cevap veriyorum hakaret ediyorsun ağlıyorum aslında hıçkırıksın nasıl da saçma yarışmak zamanla durdurabilsem sanatçı da d...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sekizinci-duzlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adalı', 'adali-feride-omur-xe13h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Heyyyy

Arkada gözü yaşlı bıraktığım sevgili

Neden ağlıyorsun? 

Birlikte kurduğumuz hayallere ne oldu? 

Sevgimiz biz yaşadıkça yaşayacak

Hiç bitmeyecekti

Akşamları gün batımını seyredecektik birlikte

Yıldızlar aşkımıza şahitlik yapacaktı

Her sabah uyandığımda

Kırmızı bir gül, bir buse verecektin

Aşkımızı ölümsüzleştirecektin

Yağan yağmurda el ele yürüyüp

Toprağın kokusunu içimize çekecektik

Hani bir de mimozalar açacaktı ya

Salkım salkım

Sevgi güvercinleri uçuyordu yüreğimde

Seni dinlerken

Sevmek bu diyordum

Ölesiye seviyordum seni ADALI

Tüm bunlar hayallerimizdi

Ama...

Ne yağmur yağdı

Ne mimozalar açtı

Ne yıldızlar aşkımıza şahitlik yaptı

Ne de biz el ele yürüdük

O hayal yolunda ADALI...', 'Heyyyy Arkada gözü yaşlı bıraktığım sevgili Neden ağlıyorsun?  Birlikte kurduğumuz hayallere ne oldu?  Sevgimiz biz yaşadıkça yaşayacak Hiç ...', ARRAY['Türk Edebiyatı','Şiir','Feride Ömür']::text[], 8.5, '{"poet":"Feride Ömür","poet_slug":"feride-omur","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/adali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Örtü', 'ortu-burhan-kucuk-iayrz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Örtü

Yüzümde,bir kamyon yükü

Sevi sakladım

Olmadı,yeni sevdalara örtü

Dağıldı hayallerim

Düştüğü yerde çürüdü

Döküldüğün de yapraklarım

Burhan KÜÇÜK

Kdz.Ereğli-31.10.2004', 'Örtü Yüzümde,bir kamyon yükü Sevi sakladım Olmadı,yeni sevdalara örtü Dağıldı hayallerim Düştüğü yerde çürüdü Döküldüğün de yapraklarım Burh...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ortu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayacaksın', 'anlayacaksin-feride-omur-qqofx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün 

Ne sevecek 

Ne de sevileceksin 

Sadece 

Izdırap çekeceksin 

Beni hayallerinde yaşatıp 

Hayatın boyunca 

Hiç gülmeyeceksin 

Çünkü 

Sen bir daha 

Asla sevmeyeceksin 

Yemeden içmeden kesileceksin 

Gururun kırılacak 

Derin bir ah çekeceksin 

Gözlerin çevrende 

Hep beni arayacak 

Ama göremeyeceksin 

İhaneti 

Başına geldiğinde anlayacaksın 

Hani hatırlarmısın 

Sana 

Seni seviyorum dediğimde 

Gülümserdin sadece 

Alay edercesine 

Dökülen her damla göz yaşında 

Boşver ağlama değmez derdin 

Şimdi 

Sıra sende 

Çok acı çekeceksin 

Sevildiğini sanıp aldanacaksın 

Ben ne yaptım diye ağlayacaksın 

Başını alıp 

Çok uzaklara gideceksin 

İşte o zaman 

Anlayacaksın 

Çünkü sen var ya sen 

Tek başına öleceksin...', 'Bir gün  Ne sevecek  Ne de sevileceksin  Sadece  Izdırap çekeceksin  Beni hayallerinde yaşatıp  Hayatın boyunca  Hiç gülmeyeceksin  Çünkü  S...', ARRAY['Türk Edebiyatı','Şiir','Feride Ömür']::text[], 8.5, '{"poet":"Feride Ömür","poet_slug":"feride-omur","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/anlayacaksin-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-burhan-kucuk-ntwdq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elveda

Bir sen vardın

Bu kıyıda 

Bir de martılar

Gemiler kalkardı

Sessizce limanda

Hala asılı kulağımda

Son sözün “Elveda”

Burhan KÜÇÜK

Kdz.Ereğli-301.10.2004', 'Elveda Bir sen vardın Bu kıyıda  Bir de martılar Gemiler kalkardı Sessizce limanda Hala asılı kulağımda Son sözün “Elveda” Burhan KÜÇÜK Kdz....', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/elveda-118-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sustum! ! ..', 'sustum-yildiz-yildiz-m82x0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bulut topluyor gri şehrin semaları

Şimşeklerden kırılıp çatlıyor 

Kararmış gök kubbe

Ve

Sözzz! ! ! ...

Yıldırım olup düşüyor gönül kafesine

En zayıf yerinden kırılıp

Darmadağın oluveriyor yürek..

Bozguna uğramış ve yenik görünüyor 

Gri şehre çökmüş hüzünlü kızıl bir sonbahar

Anlam derin bir çizikten incecik kanıyor

Bu yüzden sarı değil

Bu yüzden kızıl

Bu yüzden son

Bu yüzden bahar değil 

Bu yüzden sustum! ! ...

Ruhumu yırtan çığlığı

Boğazıma düğümledim,

Dudaklarımda kendi diş izlerim..

Bu yüzden gri şehrin üzerinde sonbahar

Kızıl alevlerle yanıyor

Dudaklarım kendi diş izlerimden kanıyor

Sustum! ! ! ! ! ...

Ve bu yüzden gönül kubbesi yağmur toplar

Yürür göz pınarlarına zaptedilmez sular 

Daha fazla bent tutmaz

Yakındır yürekleri sel basmalar

Yağmur yüklü bütün bulutlar

Hava ha yağdı ha yağacak! ! ! ! ...

(Gri şehir Ankara''nın son sonbaharından)', 'Bulut topluyor gri şehrin semaları Şimşeklerden kırılıp çatlıyor  Kararmış gök kubbe Ve Sözzz! ! ! ... Yıldırım olup düşüyor gönül kafesine ...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Yıldız']::text[], 8.5, '{"poet":"Yıldız Yıldız","poet_slug":"yildiz-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sustum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zafere Doğru', 'zafere-dogru-yavuz-agir-zcse8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sanki bir rüyadır gördüklerimiz 

Yer yerinden oynuyor

Yigitlerianki; kana kan cana can

Sanki bir mahşerdir gördüklerim..

Kılıç kalkan,top,tüfek

Bir acayıp gürültüdür işittiklerim 

Ne getirir ne götürür bilinmez.

Ölüme meydan okuyor gördüklerim.

Kahramanlık destanıdır yaşadıklarım

Anadolunun aslanlarıdır övdüklerim

Alpaslanlar.Atatürkler,Mehmetcikler

Hepsi bir vatandır saydıklarım.

          Ruhları şad olsun.', 'Sanki bir rüyadır gördüklerimiz  Yer yerinden oynuyor Yigitlerianki; kana kan cana can Sanki bir mahşerdir gördüklerim.. Kılıç kalkan,top,tü...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zafere-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sık sık', 'sik-sik-burhan-kucuk-wkg2i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sık sık

Dönmesinde anlıyorum dünyanın

Çıkarken nefesim hayat bacasından

Ne gemiler batıyor,limana varmadan

Sık sık nefes alışım hep bundan

Dönse olmuyor,dönmese olmuyor

Yutuyor bir çırpıda her şeyi zaman

Sabah olmadan,ne güneşler batıyor

Geceleri sık sık uyanışım hep bundan

Burhan KÜÇÜK

Kdz.Ereğli-01.11.2004: 03:50', 'Sık sık Dönmesinde anlıyorum dünyanın Çıkarken nefesim hayat bacasından Ne gemiler batıyor,limana varmadan Sık sık nefes alışım hep bundan D...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sik-sik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delil', 'delil-mehmet-isikoglu-8zcnv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'DELİL

Uzanır yatar doğada

İzler gelip geçenleri

Çetele tutar sahada

Hesap eder göçenleri 

Çok şey söyler anlayana

Yerden biten taş dilleri

Adem Havva`dan bu yana

Gerçek tarih delilleri

İbret vermeye çalışır

Mazideki geçenlerden

Mutlak toprakta buluşur

Haykırırlar sinlerinden.

Mehmet Işıkoğlu

Almany/Köln', 'DELİL Uzanır yatar doğada İzler gelip geçenleri Çetele tutar sahada Hesap eder göçenleri  Çok şey söyler anlayana Yerden biten taş dilleri A...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/delil-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ha bugün, Ha yarın', 'ha-bugun-ha-yarin-i-brahim-ethem-bingul-uovsn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneş solgunlaştı, rüzgâr esiyor

Dallar dalgalandı yaprak esiyor

Buluttan nem kaptı, toprak esiyor

Bekliyorum, yâr bana eseceksin

Bekliyorum,sen bana geleceksin...

Gece koyulaştı, sevda esiyor

Gözlerden gönüle sevda esiyor

Kalpten kalbe bak heyecan esiyor

Bekliyorum,yâr bana eseceksin

Ha şimdi,ha yarın sen geleceksin...

www.iebingul.com', 'Güneş solgunlaştı, rüzgâr esiyor Dallar dalgalandı yaprak esiyor Buluttan nem kaptı, toprak esiyor Bekliyorum, yâr bana eseceksin Bekliyorum...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ha-bugun-ha-yarin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Tutarken Ellerimi', 'sen-tutarken-ellerimi-banu-aka-u17j9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen tutarken ellerimi

Ağlayabilirim kana kana 

Bilirim ki

Silersin gözyaşlarımı

Tek kelime etmeden.

Başım ağır gelmez 

Omuzlarına.

Bildik şehirlerde 

Yanlızlıktan ölebileceğimi

Bir tek sen bilirsin

Yüreğimi gören gözlerinle 

Gülüşüme bakıp aldanmadan

Mutsuzluktan delirebileceğimi

Bir tek sen anlarsın.

Sesin titrer adımı söylerken

             -  son harfi belki de o yüzden hep uzatırsın-

Beni seversin

Beni düşünürsün uzaklardan

Yanıbaşımdaymışsın gibi

Adın kadar zor aşkım

Endişelenme 

Adın kadar cesurdur 

Sevdiğin...', 'Sen tutarken ellerimi Ağlayabilirim kana kana  Bilirim ki Silersin gözyaşlarımı Tek kelime etmeden. Başım ağır gelmez  Omuzlarına. Bildik şe...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sen-tutarken-ellerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arama Boşuna', 'arama-bosuna-selim-bayrak-8q0sn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Baktığın gibidir güneş rengim

Bıraktığın gibidir sana sevgim

Olduğun gibidir seven ‘ben’ ''im

Olduğum gibidir aşka kinim

Çabaladım boş yere yad ellerde

Sevgiyi salmışlar dağ sellerde

Arama boşuna bu solgun caddelerde

Arama boşuna düşlerini

Kim görmüş ki yarını bugünden daha açık

Kim görmüş ki yarını dün gibi

Anlamsız duvarlar rüzgarlar estiğinde

Çökerlerse üstüne dur kaçma

Umudu işte o an bırak sen bir yana

Ruhunu işte o an sakın kaçırma', 'Baktığın gibidir güneş rengim Bıraktığın gibidir sana sevgim Olduğun gibidir seven ‘ben’ ''im Olduğum gibidir aşka kinim Çabaladım boş yere y...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/arama-bosuna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MaRKeTİnG DePaRTMeNT,', 'marketi-ng-department-mine-ozdemirtas-cgnle', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İki adım öne çıkmış bir adam

hiç aldırmadan

uzayıp giden kuyruklara

elindeki bonus kartı

uzatırsa kasaya

Sanırım,

önce........................

bir sessizlik çöker ortaya

ardından ise,

koskoca bir yaygara

yerleştirir kendini

gecikmeden raflara

bilirsiniz işte! 

.................mandalina,

kabuğunun altında

ekşi/tatlı-Mı bilinmeyen tadıyla

iç geçirten bir koku

yayar ya etrafına

işte.......öyle bir rayiha

sinerken marketing departmana

kehkeşandan bir cüzdan

dokunacaksa hesaplara

bence..........

öpüşmese de olur

market merdivenlerinde sevda.

yeter ki,............. Kurt

ulusun..................... 

..................dolunayda.

...................... :)) 

01/11/2004.... çamlıca', 'İki adım öne çıkmış bir adam hiç aldırmadan uzayıp giden kuyruklara elindeki bonus kartı uzatırsa kasaya Sanırım, önce.........................', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/marketing-department-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hala Yoksun', 'hala-yoksun-murat-demir-m9zfx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bunca inanmışken senin sözüne

Söyle külmü çöktü sevda közüne

Bu kaçıncı sabah elin düzüne

Güneş konakladı sen hala yoksun

Gecelerim hasret kaldı şafağa

Yüreğim dönüştü bir yanardağa

İnadıma gibi hep başka bağa

Güller konakladı sen hala yoksun

Hasret katran olmuş içimde yara

Hep senden bekledim gelipte sara

Bizden gayri dön bak butün aşklara

Eller konakladı sen hala yoksun

Gözlerim görmüyor önüm zifiri

Olmuşum sevdanın garip sefili

Gel bak bedenime gel diri diri

Ecel konakladı sen hala yoksun', 'Bunca inanmışken senin sözüne Söyle külmü çöktü sevda közüne Bu kaçıncı sabah elin düzüne Güneş konakladı sen hala yoksun Gecelerim hasret k...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hala-yoksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümün Gavuru', 'gonlumun-gavuru-murat-demir-44972', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne gönül yollarını

Tükettim adım adım

Ellere taç oldum da

Sana yar olamadım

Anlaşılmaz havadan

Çaldın durdun davulu

Beni perişan ettin

Sen gönlümün gavuru

Dolaştım gece gündüz

Bir yerde kalamadım

Kaleler fethettimde

Tek seni alamadım

Anlaşılmaz yerlerin

Gittin oldun safiri

Beni tarumar ettin

Sen gönlümün kafiri

Kendime yeterince

Git artık bre dedim

Neyleyimki yanına

Varmayı bilemedim

Anlaşılmaz ellerin

Gittin oldun hamuru

Beni derde gark ettin

Sen gönlümün çamuru!', 'Ne gönül yollarını Tükettim adım adım Ellere taç oldum da Sana yar olamadım Anlaşılmaz havadan Çaldın durdun davulu Beni perişan ettin Sen g...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gonlumun-gavuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Irak''tan İnsan Manzaraları', 'irak-tan-i-nsan-manzaralari-can-ceylan-qafva', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Merhem yok tuz basılmış kan ağlıyor  yarası

Canevinden vuruyor kör şarapnel parçası

Kalkan olsa ne çare mecal yok bedeninde

İnsanın insanlara  yaptığı yüz karası

Çaresizlik çarkında çırpınan kahroluşlar

Yürekleri dağlıyor kan revan yokoluşlar

Uykuya hasret kalmış yarı açık gözlerle

Bir baskın korkusuyla diken üstü bakışlar

Bir tarafta silahlar soluksuz roket atar

İnsanlar aç bir lokma ekmeğe kurşun atar 

Çoluk çocuk tanımaz vicdansız mermilere

Süt kokan göğüsleri siper olmuş kadınlar

İnsanın sinek kadar kıymeti yok gözlerde

Katledilen sivil halk geçmiyor haberlerde 

Süper gücün keyfine diyecek yok şahane

Kitle imha silahlar, demokrasi bahane

Per perişan çocuklar, korku dolmuş gözleri

Şiddeti kaldırmıyor, küçücük yürekleri

İnsan hakları için kesilenler havari 

Katliamdan bihaber duyulmuyor sözleri', 'Merhem yok tuz basılmış kan ağlıyor  yarası Canevinden vuruyor kör şarapnel parçası Kalkan olsa ne çare mecal yok bedeninde İnsanın insanlar...', ARRAY['Türk Edebiyatı','Şiir','Can Ceylan']::text[], 8.5, '{"poet":"Can Ceylan","poet_slug":"can-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/irak-tan-insan-manzaralari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı Kent', 'sakli-kent-oguzkan-bolukbasi-kjpah', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saklı bir kentte oturuyorsun

Hangi yoldan gidersem gideyim

Sana çıkarmıyor

Yol dediğin ne ki bitmiyor

Lakin yürümeden bir yere varılmıyor

Hareket bu küre üzerinde

Nereye gidersen git aynı yere çıkıyor sonuçta

Sonucun adı ne olursa olsun

Hayat gibidir küre üzerinde yuvarlanmak

Yol almak

Yoksun

Varsın

Yoksun yani

Binlerce kelleye hükmetmiş sultanlar hani

Ya da bilinmeyen 

Bilinmez

Yoksul Mehmet efendi hani

Bu manayı anlamayan için

Ne trajikomiktir  yaşamın felsefesi

Kim kimin efendisi

Kim kimin kölesi

Ben o saklı kenti bulacağım bir gün

Belki öldüğüm gün

Belki yaşarken

Bir düğün içerisindeyken

Aniden

Yol haritalarını getirecekler

Yüreğime sular serpecekler

Temiz bir hava

Bereketli bir toprak üzerinde kurulmuş

O saklı kente beni götürecekler

Bakalım kimler orada olacak

Veya kimler orada

Beni bekliyor

Keşke seni görsem', 'Saklı bir kentte oturuyorsun Hangi yoldan gidersem gideyim Sana çıkarmıyor Yol dediğin ne ki bitmiyor Lakin yürümeden bir yere varılmıyor Ha...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sakli-kent-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepsi Hayal Olacak!', 'hepsi-hayal-olacak-canan-palabiyik-ezo7b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dost kalacaktık, aynı yolda yol alacaktık, 

Saçlarımız ağarmış bahçemizde kahve içerken, 

Gençliğimizi anıp el ele tutuşacaktık, 

Yoksun artık hepsi hayal olacak! 

Aşkımızın meyvesi çocuklarımız olacaktı, 

Sararmış eski fotoğraflara gülümsemeyle bakacaktık, 

Sadece birbirimize sığınacaktık, 

Yoksun artık hepsi hayal olacak! 

Yaşadıklarımız bir efsane olacaktı, 

Kaf dağları ardından, 

Zümrüt-ü Anka kuşları seni bana getirecekti, 

Hiçbir şey aramıza giremeyecekti, 

Yaşanmamış bu hayatı birlikte yaşayacaktık, 

Yoksun artık hepsi hayal olacak! 

(01 Kasım 2004 / İstanbul)

Samanyolu Grubunun 2K1Ş ''İki Kelime Bir Şiir'' Aktivitesi için kaleme alınmıştır. Kelimeler: ''''FOTOĞRAF'''' ve ''''KUŞLAR''''', 'Dost kalacaktık, aynı yolda yol alacaktık,  Saçlarımız ağarmış bahçemizde kahve içerken,  Gençliğimizi anıp el ele tutuşacaktık,  Yoksun art...', ARRAY['Türk Edebiyatı','Şiir','Canan Palabıyık']::text[], 8.5, '{"poet":"Canan Palabıyık","poet_slug":"canan-palabiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hepsi-hayal-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk Sineması', 'turk-sinemasi-mustafa-toga-ps6n0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben 1958 kuşağıyım

Onlarsa, bir sürü dalı olan

Ulu çınar ağaçları

Hani sonbahar gelince yaprakları dökülenlerden.

Köklerini derinlere salmış bu koca ağaçlar

Delikanlılık çağım, paylaştığım

Artistler, aktrisler, sinema sanatçıları 

Şimdi şapır şapır dökülüyorlar.

Kimler gitmedi ki; 

Ayhan Işık, Yılmaz Güney, Zeki Müren’ler mi? 

Yoksa,

Erol Taş, Kazım Kartal, Barış Manço’lar mı ? 

Beş kuruş beş kuruş harçlık biriktirip

Adile Naşit, Neriman Köksal''ın  filmlerine koşardık.

Dakikalarca sıra beklerdik sinema gişelerinin önünde.

Baba oyunculardı Kadir Savun, Nubar Terziyan, Ali Şen

Kalbimizde taht kurmuşlardı jönler gibi kötü karakterler de,

Danyal Topatan, Hüseyin Peyda, Yadigâr Ejder.

Güldürü ustaları Kemâl Sunal, Sadri Alışık, Öztürk Serengil

Her role uyan Tugay Toksöz, Hüseyin Kutman, Turgut Boralı 

Ve de Tanju Okan, Íhsan Yüce, Sami Hazinses, Turgut Özatay.

Bir de tonton fabrikatör dede Hulusi Kentmen,

Bu devri alemden göçtüler.

Her yıl devrimin sanatçılarından yıldızlar kayıyor

Her yıl bir şeyler götürüyor benden

Her yıl kendimi onlarsız biraz daha yalnız hissediyorum.

Dünya hancı, bizler yolcu

Bir sinema şeridi gibi geçiyorlar gözlerimin önünden,

Ínsan unutamıyor gönlünün starlarını

Bugün onlara yarın bize

Ruhları şad olsun yıldızların.

Eylül 2005', 'Ben 1958 kuşağıyım Onlarsa, bir sürü dalı olan Ulu çınar ağaçları Hani sonbahar gelince yaprakları dökülenlerden. Köklerini derinlere salmış...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Toga']::text[], 8.5, '{"poet":"Mustafa Toga","poet_slug":"mustafa-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/turk-sinemas-953-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin 2', 'senin-i-cin-2-husnu-celebi-dbf7v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu başka şiir senin için

Gönülden gelen, kalemimden dökülen

Tariflendin birden içimdeki sen

Dünyanın yedi harikasına, bir ilavesin sanki 

Güzelim İstanbul’dan daha bir güzel

Hırçın Karadeniz’den daha bir coşkulu

Mavi Akdeniz’den daha bir sıcak

Gül gibi sevgi dolu, gelin çiçeği kadar mutlu

Kamelya gibi kusursuz, yasemin kadar çekici

Söylediğim şarkısın dilimden düşmeyen

Yazdığım şiirsin kalemimde tükenmeyen

Seni anlatabilmek kolay olsaydı

Senin diğerlerinden farkın olmazdı

Duygular var ki anlatılamaz

Sevgiler var ki yaşanmadan bilinmez

Güzellikler var ki asla sahip olunamaz

Ve SEN varsın ki ölene kadar

Vazgeçilemez 

Bu vazgeçilmez aşkın sürekli dudaklarımda

O kıskandıran güzelliğin her an aklımda

Elin elimde, tenin bedenimde 

İşte yine bir Ekim’de

Sadece bu gün değil

Son Ekim’e kadar her gün sürecek

Gördüğümde seni mevsim sonbahardı

Bende heyecan sende korku vardı

Başlarken bu aşk

Mevsim yine sonbahardı

O sonbahardan bu sonbahara

Sen benim için,

Geceleri seni düşünerek 

Uyku tutmadığım,

Uykulu gecelerimde 

Rüyalarından uyanmak istemediğim

Sabah uyandığımda

En çok görmek istediğim

Acıktığımda 

Yemeğim yanında bir yudum suyum

Ben o sonbahardan bu sonbahara

Hep seni yazdım.

Bu sonbahardan 

Benim Son Baharıma

Hep seni hep seni...

Yazacağım.

Bu şiirde sadece sana yazıldı,

Sadece seni anlatıyor.

01.11.2004  /  İstanbul', 'Bu başka şiir senin için Gönülden gelen, kalemimden dökülen Tariflendin birden içimdeki sen Dünyanın yedi harikasına, bir ilavesin sanki  Gü...', ARRAY['Türk Edebiyatı','Şiir','Hüsnü Çelebi']::text[], 8.5, '{"poet":"Hüsnü Çelebi","poet_slug":"husnu-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/senin-icin-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim', 'sevdim-erdem-yalcin-p2gvu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben güneşin doğuşunu sevdim gözlerinde 

Karanlıkların ulaşmasını aydınlığa

Narin yüzünü seyretmeyi sevdim

Akşamın loş ışıklarında

Gülüşünde gençliğini sevdim 

Kaygılardan uzak oluşunu

Seninle barışmayı sevdim

İhtiras doluydu her kavganın sonu

Dört mevsimi sevdim seninle

Her mevsim seninle bir bahardı

Saçlarında çiçeklerin kokusunu sevdim

Kışın saçlarında uçuşan karları 

Yılların izini görmeyi sevdim

Yüzündeki ince belirsiz çizgilerde

Sızlanmanı hırçınlığını sevdim

Yaşlanma korkusu vardı içinde

Yaşadığım zamanı sevdim

Varlığınla katlandım türlü hüzünlere

Yüreğimi sevdim 

İçinde yalnızca sen varsın diye....', 'Ben güneşin doğuşunu sevdim gözlerinde  Karanlıkların ulaşmasını aydınlığa Narin yüzünü seyretmeyi sevdim Akşamın loş ışıklarında Gülüşünde ...', ARRAY['Türk Edebiyatı','Şiir','Erdem Yalçın']::text[], 8.5, '{"poet":"Erdem Yalçın","poet_slug":"erdem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevdim-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili', 'sevgili-zuhal-aksulu-tgs0m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerinde bulutlar var

Sevgili

Söyle ne''n var? 

Bende dinmeyen yağmurlar

Kalbimde kırıklar

Yoksa senden gizlediğim birşey mi var? 

Sözlerin keskin bıçak

Delik deşik etti ruhumu

Sevgim o deliklerden uçtu uçtu

Peki şimdi ne olacak? 

Bir gülüşün yamar delikleri

Belki bir öpüşün...

Nedir olanlardan kalan sevgi

Ey sevgili bir düşün! 

Hayatın anlamı sendin

Hayatıma en umulmadık yerde geldin

Geldin, hoşgeldin de...

Üzüntüden, kırıklardan başka ne verdin? 

Kolay mı sence unutmak

Olanların hepsini yok saymak

Çok sabırsızsın sevgili

Kolay mı iki günde eskisi gibi olmak...', 'Gözlerinde bulutlar var Sevgili Söyle ne''n var?  Bende dinmeyen yağmurlar Kalbimde kırıklar Yoksa senden gizlediğim birşey mi var?  Sözlerin...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevgili-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak', 'aglamak-zuhal-aksulu-2n4hc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hala biraz daha var

Ağlamalıyım...

Ağlamalı, bu soğuk geceyi

Gözyaşlarımla yıkamalıyım

Şeffaf geceye yıldızlarımı bırakmalıyım.

Her gözyaşımda binlerce yıldız

Senden geliyor sana gidiyorlar

Sen tut onları tut

Yıldızlar beni bitiriyorlar

Kalbimden kopuyor

Boğazımda düğümleniyorlar

Beni öldürmek istercesine

Nefesimi kesiyorlar...

Ağlamalıyım

Ağlamalı, nefes almalıyım

Şeffaf geceye yıldızlarımı salmalıyım.

Binlerce yıldız parlıyor her damlada

Bİr ay parçası düşmüş gönlüme

Sen de bir yıldız tut kendine

Gecede buluşalım...', 'Hala biraz daha var Ağlamalıyım... Ağlamalı, bu soğuk geceyi Gözyaşlarımla yıkamalıyım Şeffaf geceye yıldızlarımı bırakmalıyım. Her gözyaşım...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aglamak-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader', 'kader-hifzi-ozbekmez-8e774', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu benim kaderim niye hiç gülmez

Bir güzele aşık olalı kader

Kimseler düşenin halini bilmez

Yalan dünya dünya olalı kader

Benimde hayalim rüyam var idi

Koskoca bu alem bana dar idi

Gözünüm pınarı aktı kurudu

Böyle boynu8bükük kalalı kader

Gönlümde yangına sular yetmiyor

Yarin gül hayali gözden gitmiyor

Çektiğim çileler artık bitmiyor

Bu ayrılık miras kalalı kader

Latifim almasam kalsa da ahım

O benim sultanım gönlümde şahım

Kimselere yoktur hiç eyvallahım

Sevda beni derde salalı kader

19 EYLÜL 2004 SAAT: 09:00', 'Bu benim kaderim niye hiç gülmez Bir güzele aşık olalı kader Kimseler düşenin halini bilmez Yalan dünya dünya olalı kader Benimde hayalim rü...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kader-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Gelin', 'sari-gelin-hifzi-ozbekmez-n7y9u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerine baktım yeni ağlamış

Ciğerini aşk ateşi dağlamış

Hayattan ahını bir gün almamış

Oturup ağlamış vay sarı gelin

Yıllarca beklemiş sevda yolunu

Anlayan çıkmamış garip halini

Ayrılıklar bükmüş ince belini

Boşuna ağlamış oy sarı gelin

Zalimlere vermiş gönül tahtını

Kara eylemişler güzel bahtını

Mevla koymaz kimselerde ahtını

Bir gün sende gülen ey sarı gelin

Latif böyle gördü senin ahvalin

Tükenmiş dermanın bitmiş mecalin

Dileğimdir gerçek olsun hayalin

Kıymet bilene ol bey sarı gelin

20 EYLÜL 2004 SAAT: 08:00', 'Gözlerine baktım yeni ağlamış Ciğerini aşk ateşi dağlamış Hayattan ahını bir gün almamış Oturup ağlamış vay sarı gelin Yıllarca beklemiş sev...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sari-gelin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ustam', 'ustam-ahmet-kurt-1g9ub', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağlamazsam gözüm pınarı kurur,

Ahvalimi bir sen bilirsin ustam.

Kainat saklanmış pusuya durur,

Ahvalimi bir sen bilirsin ustam.

Saya saya geldim, öteden beri,

Şimdi adımlarım gitmez ileri,

Koşuyor ardımdan hançerli çeri,

Ahvalimi bir sen bilirsin ustam.

Mesajını aldım, yüreğim kalktı,

Anlamadım şaştım, bu nasıl çarktı,

Hani bugün dünden daha berraktı,

Ahvalimi bir sen bilirsin ustam.

Kuytular karanlık, mağara isli,

Yürekler yorulmuş, ufuklar sisli,

Baktıkça ürkerim gözlerim puslu,

Ahvalimi bir sen bilirsin ustam.

Yandıkça güneşin, şavkına hasret,

Büyüdü güçlendi, gelişti haset,

Bundan daha büyük olur mu kasvet,

Ahvalimi bir sen bilirsin ustam.

Çaresiz çareye kanıyor gönlüm,

Volkanlara düşmüş yanıyor gönlüm,

Bir küçük ışığı arıyor gönlüm,

Ahvalimi bir sen bilirsin ustam.

Kurdoğlu hasretin adıdır kalan,

Zihnimde savaş var, ruhumda talan,

Çıkmış ta ayyuka, gülüyor yalan,

Ahvalimi bir sen bilirsin ustam.', 'Ağlamazsam gözüm pınarı kurur, Ahvalimi bir sen bilirsin ustam. Kainat saklanmış pusuya durur, Ahvalimi bir sen bilirsin ustam. Saya saya ge...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ustam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tökezlerim', 'tokezlerim-burhan-kucuk-kyxsr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tökezlerim

Yok mu bu şehrin kaldırımları

Gece sessiz sedasız yol verir

Araba farları,sokak lambaları

Alır götürür beni başka diyarlara

Beynimdeki yalnızlık şarkıları

Kaç kez tökezlerim kim bilir

Hayalime düştükçe

Yarin yarı açık dudakları

Burhan KÜÇÜK

Kdz.Ereğli-27.10.2004', 'Tökezlerim Yok mu bu şehrin kaldırımları Gece sessiz sedasız yol verir Araba farları,sokak lambaları Alır götürür beni başka diyarlara Beyni...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tokezlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Düşün', 'beni-dusun-serdal-gocmen-b9mh9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmur çiselerken pencerende

Beni düşün kırgın yüreğinle

Şafağın sancısını hissedersen benliğinde

Beni düşün yorgun gözlerinle

Geceleri uykuların bölünüyorsa

Yüzün gülüp gözlerin ağlıyorsa

Kalbin başka sevgilere açılmıyorsa

Beni düşün,

Beni düşün

Düşün ki yanında olayım

Düşün ki huzuru bulayım

Ağlayan yalnızlığımı hayalinle paylaşayım.', 'Yağmur çiselerken pencerende Beni düşün kırgın yüreğinle Şafağın sancısını hissedersen benliğinde Beni düşün yorgun gözlerinle Geceleri uyku...', ARRAY['Türk Edebiyatı','Şiir','Serdal Göçmen']::text[], 8.5, '{"poet":"Serdal Göçmen","poet_slug":"serdal-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beni-dusun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-husamettin-gunacti-u3gtq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'uykuya dalınca dün gece,

yine kursağımda kaldı sevincim.

kanatlarını çırparak gizlice,

yine rüyama girdi o ak Güvercin.

                *      *

kaçıp gidecektim şafak sökünce,

aslında hiç uyumayacaktım.

ağladığını görmeseydim sessizce,

aslında ona hiç uymayacaktım.

                *      *

bembeyaz tüylerini taramıştı güzelce,

ama sis perdesi ardında bir tuhaftı yüzü.

yüzüme bakamadı göz göze gelince,

sanki dar gelmişti yıldız yıldız gökyüzü.

               *      *

yığılıp kaldı önüme öylece,

o narin kanatlarından biri kırıktı.

Kargaydı arkadaşım diyebildi sadece,

yüreğini gördüm,geceden bile karanlıktı.

               *      *

uyarmalıydım Kargaya görünmeden sinsice,

çünkü Kargayla Güvercinin sonu ayrılıktı.

aşk artık lügatta yasak bir tümce,

ve içinde düğüm düğüm hıçkırıktı.

               *      *

keşke hiç uyumasaydım,

kaçıp gitseydim şafak sökünce.

keşke ona hiç uymasaydım,

ilk rüyada âşık olmasaydım delice..

               *      *

01-11-2004', 'uykuya dalınca dün gece, yine kursağımda kaldı sevincim. kanatlarını çırparak gizlice, yine rüyama girdi o ak Güvercin.                 *   ...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ruya-667-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeler...', 'sevmeler-baris-pinar-tumer-3pz9r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ah....

Bu sevmelerin

bir haritası yok mu? ....

her gün

milyonlarca yürek rotası

eskiyor....

eskitiliyor...

ah...

bu sevmelerin bir haritası

yok mu? ....', 'Ah.... Bu sevmelerin bir haritası yok mu? .... her gün milyonlarca yürek rotası eskiyor.... eskitiliyor... ah... bu sevmelerin bir haritası ...', ARRAY['Türk Edebiyatı','Şiir','Barış Pınar Tümer']::text[], 8.5, '{"poet":"Barış Pınar Tümer","poet_slug":"baris-pinar-tumer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevmeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunalmış adam', 'bunalmis-adam-serdal-gocmen-62hvy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kuma saplamış cigarasını

Ucu hâlâ yanıyor

Birikmiş umutlara meydan okur gibi

Kim kapattı bahtımızı? 

Bu surat

Bu endâm 

Bu bunalmış bir adam

Bana adam

Size idam

Gel sil gözyaşlarını

Kıyma tuzlu suyuna

Şimdi kaldır başını bana dik dik bak

Haydi bir cigara daha yak

Şimdi dön arkana bak.', 'Kuma saplamış cigarasını Ucu hâlâ yanıyor Birikmiş umutlara meydan okur gibi Kim kapattı bahtımızı?  Bu surat Bu endâm  Bu bunalmış bir adam...', ARRAY['Türk Edebiyatı','Şiir','Serdal Göçmen']::text[], 8.5, '{"poet":"Serdal Göçmen","poet_slug":"serdal-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bunalmis-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Ayrılık', 'zor-ayrilik-cafer-petek-0qoc8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'saçlarımın beyazına astım

çoğalmana karşın

hergün aynalarda

en tenha yerinde dağların

ağladım acılar koşturup

şiirler yarıştırdım

üşümesin diye çocuklar

şarkılar düşürdüm geceye

gölgemin gözleri yakmasından korkmasaydım

kolay olacaktı ayrılık

ayrılık kolay olacaktı

çizmeseydi yağmurlar gökyüzünde resmini', 'saçlarımın beyazına astım çoğalmana karşın hergün aynalarda en tenha yerinde dağların ağladım acılar koşturup şiirler yarıştırdım üşümesin d...', ARRAY['Türk Edebiyatı','Şiir','Cafer Petek']::text[], 8.5, '{"poet":"Cafer Petek","poet_slug":"cafer-petek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zor-ayrilik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm Sen', 'gulum-sen-i-smail-sahin-fvwyn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'koşup gelsen yuvana çırpınarak

gülüm sen de benim gibi

sen de baharına çiçekler gibi

kuşlar kırlangıçlar gibi

baksan gözlerime sıcak sıcak

dokunsan kirli saçlarıma

ellerime dokunsan

yokluğunu yere çarparak

TESLİM olsam varlığına

yorulmuş nefer gibi

kıvır kıvır saçlarınla beni sarsan

aman vermeyen sarmaşıklar gibi

gel-sen

Cerciş'' e koşan Cebrail gibi

kuyuya yetişen kervan gibi

Şiraz'' dan beni çıkarmasan

gülüm sen beni...', 'koşup gelsen yuvana çırpınarak gülüm sen de benim gibi sen de baharına çiçekler gibi kuşlar kırlangıçlar gibi baksan gözlerime sıcak sıcak d...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gulum-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağımda Yaşam Solumda Ölüm', 'sagimda-yasam-solumda-olum-osman-i-nci-qyqmp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayat gösterdi yine, iki yüzlülüğünü, 

Yaşatmadı hiç, kuşların özgürlüğünü, 

Anlayamadım, sevginin büyüklüğünü, 

Sağımda mutluluk var, solumda keder... 

Saat saati tutmuyor, duygular dalgalı, 

Kafalar darmadağın, bilekler prangalı, 

Kör talih dedikleri, sanırım bu olmalı, 

Sağımda gülücük var, solumda hüzün... 

İyilik yaptıkça, kötülük buluyor beni, 

İncitir darbeler, bu duygusal bedeni, 

Bu perişan kalbimin, yok bir seveni, 

Sağımda hoşgörü var, solumda sitem... 

Oynamak ne kolaymış, asil duygularla, 

Boğuşmaktan usandım, bu fırtınalarla, 

Yürümüyor, bıçak sırtındaki umutlarla,

Sağımda yaşamak var, solumda ölüm...', 'Hayat gösterdi yine, iki yüzlülüğünü,  Yaşatmadı hiç, kuşların özgürlüğünü,  Anlayamadım, sevginin büyüklüğünü,  Sağımda mutluluk var, solum...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sagimda-yasam-solumda-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdama Dair', 'sevdama-dair-volkan-yoruc-9jq15', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ucu hayata 

Diğer ucu sana varır sevgilerimin

Hiçbir söz anlatılamaz

Yaşanan günlere denktir ümitlerim

Acılar içinde mutluluk arar

Aşkın içinden geçerim

Senin için yaşarım

Dağ kırlangıcımsın

Uçsuz bucaksız dağlarımda

Yol vermez nehirimsin

Acılarla örülmüş bağrımda

Aşkımsın

Sana gönül verdiğim şu hazan mevsimimde

Sabahları güneyden doğan yıldızımsın

Herkesin uyuduğu ayaz sabahlarda

Yanarımda kor ateşlere dönerim

Erirde süzülür yüreğine düşerim

Bir seni bilirim sevdiğim

Hüzünleri bıraktığım sonbahar akşamlarında', 'Bir ucu hayata  Diğer ucu sana varır sevgilerimin Hiçbir söz anlatılamaz Yaşanan günlere denktir ümitlerim Acılar içinde mutluluk arar Aşkın...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevdama-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalımı Kesip Terkettin Sen(denemeler-1)', 'dalimi-kesip-terkettin-sen-denemeler-1-mehmet-asim-x47rp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Oysa ben tutunduğum dalları hiç kırmadım.hep yeşertmeye calıştım,büyütmeye uğraştım.Mavi bir gökyüzü düşledim,dallarımın ulaştığı....

    Düşme korkusuyla yaşadım uçurumları içime çektiğim günlerde...uzun siyah saçlarına tutunabilirdim oysa....

    Onları kesmeseydin...

    Şimdi pusatlandıysa kelimelerim; bilesin sevdam üzre öfkedeler.sen hep maviyi siyaha boyadınve uzun saçlarını kestin.biliyordun onlar benim utunduğum dallarımdı hayat uçurumlarında...

    Yasaklanmış yolları severdin sen.Hep koşmak isterdin çıkmazlarda.İşte başardın.benim çıkmazlığıma doğru koşuyorsun(ters yöne) .Sen koşarken ben duruyorum,düşüyor ve boğuluyorum çıkmazlığımda...

    Dallarımı kestin attın sen,yakıp ihanetini,küllerimi savurdun sen...

    Oysa ben tutunduğum hiç bir dalı kesmedim...

    Mavi gökyüzüne ulaşsın diye.....

                                              

                                                        28/10/04

                                                         istanbul', 'Oysa ben tutunduğum dalları hiç kırmadım.hep yeşertmeye calıştım,büyütmeye uğraştım.Mavi bir gökyüzü düşledim,dallarımın ulaştığı....     Dü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Asım']::text[], 8.5, '{"poet":"Mehmet Asım","poet_slug":"mehmet-asim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dalimi-kesip-terkettin-sen-denemeler-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuplen*', 'kuplen-nigin-nevaderezi-68w71', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir zaman,yuvasi genişdi

Indi ''miyoo''lardan yalniza

Tökülmeyir bu qalibler

Kübiklenmiş meşeliklerde

Aslan baqirtilarina

Qoyub-qaçmiş şeyhelerin**

Yeri boş...! 

Ah

Kiçikden böyüye

Acizimiş

Delik-deşik negativler

Her yönden baxinilacaqlarsa

Baöirti ignelere saplanacaq! 

''Lele var yurdu yok''

***               ***               ***

Dayanaklarimiza sancaklanacaq***

Hepsi

Yere düşkün şeyheler

Qalxib yürümüş ''miyoo''lar

''Miyoo''...

*Önceden nakişlari tor kumaş üzere çizilmiş ve tikilmeye hazirlanmiş olan bir Tür nakişlama sanati.

**Kişnerti

***Kiskac

Tebriz-30.10.2004', 'Bir zaman,yuvasi genişdi Indi ''miyoo''lardan yalniza Tökülmeyir bu qalibler Kübiklenmiş meşeliklerde Aslan baqirtilarina Qoyub-qaçmiş şeyhele...', ARRAY['Türk Edebiyatı','Şiir','Nigin Nevaderezi']::text[], 8.5, '{"poet":"Nigin Nevaderezi","poet_slug":"nigin-nevaderezi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kuplen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin Evine', 'hosgeldin-evine-yasar-pullu-n2z4j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdiğime...

Yaşama benzeyen bir şey var sende

Çığlığın 

ayrılık makamında susmuş Yurduma

üzerinde tırnak izleri bulunan bir hayat 

Dağlara küsmüş 

Başı dık dağlara

Sitemkar bir merhaba olmuş sesin 

Bende ise  durum aynı 

İntihar çökmüş damarlarıma

Kerem’i çok abartmışlar

Sevdim bende 

Bir insana  kaç sevda sığarsa

Beni doğduğum gün yakmışlar

Bu yüzden tenim  yanık kokmakta

Ve yürek kendini kanatan yara

Ve mavi kusan

Ölümede merhaba der bu adam

Gençliğinin alazında

Nasıl doldurdum ki bu yükü kendine 

Çok yakınım ölüme

Bir daha gitme.

Boş bir yerdeyim

Hiçbir yerde

Elektriksiz bir iskemledeyim

Senden sonra

Suların balıkları öldürdüğü yerdeyim

Protesto ediyorum kendimi

Her sabah bir eylemdeyim

Ayrılığın rengi aynıymış ölümle

Sen gidince Susmayı öğrendim.

Kendi kendime

Kendi tenime küsmeyi

Ve kanatmayı kendi yüzümü

Hedefi ıskalamış ellerim

Oysa ben hep tetikteyim

Öyle ağırki hava

Güneş tutulmuş

Gençliğim vurulmuş sırtından

Sonrası 

Yapraklar  düşmüş dalımdan

Sonrası çekip gözlerinin derinliğinden kendimi

Varoşlara dağıtmışım sesimi

Nereye ölsem

Gölgen düşüyor  içime

Kendime öldüm

Kendime gömdüm kendimi

hoş geldin gülüm

kendi evine.', 'Sevdiğime... Yaşama benzeyen bir şey var sende Çığlığın  ayrılık makamında susmuş Yurduma üzerinde tırnak izleri bulunan bir hayat  Dağlara ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Püllü']::text[], 8.5, '{"poet":"Yaşar Püllü","poet_slug":"yasar-pullu","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/hosgeldin-evine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Noktadan Türeyen Seda..', 'noktadan-tureyen-seda-mehmet-asim-18isd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen hayatımda bir noktanın başladığı yersin.her yöne uzantısı olan..ve çekebildikçe çektiğim.Yaşamın içine,benliğimin içine.her anıma,mekenıma paralellik kurabildiğimsin.Beyazlığın içinde seçilesi olan bir noktadan türedin hayatımda.ruhum bütün boyutlarına muhtaçtı ve tanımalıydı.yaşamıma düşmüş,çözülesi bir işlemdin sen.ve seni her çözüşümde yepyeni sonuçlar keşfediyordum.hayatta daha önce hiç ulaşmadığım sonuçlar.Sen! o noktadan sayamadığım uzantısı olan sen! her şeyinle ömrümün yaşanılası bir yanı oluyordun.seninle anladım bir noktanın boyutlarını.bir noktanın bir yaşamı dolduracak haçmini ve genişliğini seninle anladım.tüm hesaplar çok farklıydı bu zamana kadar öğretilenden.yüreklerimiz biribirinde ayrışmalıydı,yeni yöntemler bulmalıydı hayata uzanan.aynı zamanlarda farklı karelerde oluyorduk.seninle herşeyden herkesden...

     Sen yollara yeni heyacanla girmenin ümidisin.çünkü sen hayatımda bir noktanın başladığı bir yersin.ve seninle anladım bir noktanın asıl boyutunu.....

                                                               Zeyneb Günay

                                                                 2208/03

                                                                 istanbul', 'Sen hayatımda bir noktanın başladığı yersin.her yöne uzantısı olan..ve çekebildikçe çektiğim.Yaşamın içine,benliğimin içine.her anıma,mekenı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Asım']::text[], 8.5, '{"poet":"Mehmet Asım","poet_slug":"mehmet-asim","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/noktadan-tureyen-seda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Çiçekleri', 'gece-cicekleri-goktu-kara-efdlq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gariplerin geçtiği yoldur benim yolum

yaşam savaşıyla dolu

serin havalar yaklaşmakta ruha

gece çiçekleri açıyor

bekleyelim', 'gariplerin geçtiği yoldur benim yolum yaşam savaşıyla dolu serin havalar yaklaşmakta ruha gece çiçekleri açıyor bekleyelim...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gece-cicekleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülün İntiharı', 'gulun-i-ntihari-cafer-petek-35aja', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'boğazımda

aksak kelimelerin düğümü

tuz tadı dilimde

içim deniz

hışmında dalgaların

diyebilseydim

saçlarına asılarak ölmek varken

dalında solmak zor gelir güle

zor gelir gülüm güle

diyebilseydim bilirdim

bilseydim diyebilirdim', 'boğazımda aksak kelimelerin düğümü tuz tadı dilimde içim deniz hışmında dalgaların diyebilseydim saçlarına asılarak ölmek varken dalında sol...', ARRAY['Türk Edebiyatı','Şiir','Cafer Petek']::text[], 8.5, '{"poet":"Cafer Petek","poet_slug":"cafer-petek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gulun-intihari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'M a n i l e r (1)', 'm-a-n-i-l-e-r-1-abdullah-atay-ltbtx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bugün günlerden salı 

altına serdim halı 

yar yanımda olunca 

ne yapayım ki balı. 

bugün günlerden cuma 

yine geldin aklıma 

gece sana gelecem 

sevdiceğim uyuma. 

bugün günlerden pazar 

sevdiğim mani yazar 

öyle gülüp kırıtma 

vallahi değer nazar. 

evinin önü meşe 

elimde dolu şişe 

gonca gülün derince 

gönlümde olur neşe. 

yollarını gözlerim 

seni her an özlerim 

hasretinden ölürsem 

kapanmasın gözlerim. 

bahçede var lahana 

kaymak koydum sahana 

meramım kaymak değil 

seni görmek bahana. 

nazlı yarim ağlıyor 

ciğerimi dağlıyor 

gurbete gittiğimde 

karaları bağlıyor. 

sanadır bu sözlerim 

kan döker hep gözlerim 

bende ki senden bile 

sevdiğimi gizlerim. 

maniler derman ola 

yürekler sevgi dola 

siz vefalı dostlarım 

hatam varsa affola 

abdullah atay der ki; 

sözüm sevenleredir 

sevdikleri uğruna 

canın verenleredir. 

3 1 Ekim 2004 -Mudurnu', 'bugün günlerden salı  altına serdim halı  yar yanımda olunca  ne yapayım ki balı.  bugün günlerden cuma  yine geldin aklıma  gece sana gelec...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/m-a-n-i-l-e-r-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cezayir Menekşeleri', 'cezayir-menekseleri-feride-omur-08p17', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu son şiiri sana yazıyorum

Son bulan duygularımla

Son bulan umutlarımla birlikte

Artık ne anılacak

Ne de hatırlanacaksın

Belki unutamadıklarımdan olacak

Belki de hiç anılmayacaksın

Sarmaşık gülleri açtığında

Hep beni hatırlayıp özleyeceksin

Denize her bakışında

Gözlerimin rengini göreceksin

Gözlerinden iki damla yaş dökülüp

Dudakların adımı fısıldayacak

Denizden esen hafif bir meltem

Yanağını okşayacak

Ellerin ateş gibi yanacak

Sıcaklığımı hissedeceksin

Bahçende cezayir menekşelerini görüp

Anılar tazelenecek beyninde

Kendine kahredip ağlayacak

İsyan edeceksin

Ve

Ben seni sevdiğim

Tek bir mevsimde anacağım

Cezayir menekşeleri açtığında

Onları gördüğümde seni anacağım

Hüzünler çökecek üstüme

Derin bir ahhhh dökülecek dudaklarımdan

Anılara dalacağım

Yaprakları tenini anımsatacak bana

Kokusu kokunu

Rüzgar onun kokusunu değil

Senin kokunu taşıyacak

Rengi gözlerini anımsatacak

İşte 

Ben seni sadece

Bir tek o zaman hatırlayacağım

Cezayir menekşeleri açtığında', 'Bu son şiiri sana yazıyorum Son bulan duygularımla Son bulan umutlarımla birlikte Artık ne anılacak Ne de hatırlanacaksın Belki unutamadıkla...', ARRAY['Türk Edebiyatı','Şiir','Feride Ömür']::text[], 8.5, '{"poet":"Feride Ömür","poet_slug":"feride-omur","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/cezayir-menekseleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak Kolay Değil', 'unutmak-kolay-degil-feride-omur-k7don', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni unutmalı

Söküp atmalıyım şu yüreğimden

Unutmalıyım ama nasıl? 

Kolaymı her şeyi bir anda silmek

Kolaymı her şeyi unutmak

Yaşanmış o anıları

Bir anda silmek

İçki kadehimde

Sigaramın dumanında

Baktığım her yerde 

SEN! 

Yürüdüğüm sahilde

Kanat çırpan martılarda

SEN! 

Hep sen...

Belki sen bunları unutursun

Ya ben? 

Ben bu yaralı yüreğimle unutamam

Sen ben de kalırsın

Belki

Ben ağlarken sen güleceksin

Sıcaklığımı başka ellerde arayacaksın

Bazen umutsuzluğa kapılacak

Beni arayacaksın

Yaşanmış anıları bir bir düşünecek

Bazen hafif bir tebessüm

Bazen de

Bir damla gözyaşı dökeceksin

Ve bir avuç kara toprakta

Hep beni arayacaksın

Kolaymı zannetmiştin yaşananları unutmayı

Kolaymı zannetmiştin

Yüreğinden sevgiyi söküp atmayı

Kolaymı zannetmiştin ellerimi unutmayı

Değil

Unutmak kolay değil', 'Seni unutmalı Söküp atmalıyım şu yüreğimden Unutmalıyım ama nasıl?  Kolaymı her şeyi bir anda silmek Kolaymı her şeyi unutmak Yaşanmış o anı...', ARRAY['Türk Edebiyatı','Şiir','Feride Ömür']::text[], 8.5, '{"poet":"Feride Ömür","poet_slug":"feride-omur","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/unutmak-kolay-degil-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Budak', 'budak-baykal-kaanalp-z5cq3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sersem kabalığımıza bakmayın

nezaket kurallarını atlayın

bir ağaç ki kolay yetişmez

budaklarına bakıp atmayın', 'sersem kabalığımıza bakmayın nezaket kurallarını atlayın bir ağaç ki kolay yetişmez budaklarına bakıp atmayın...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/budak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünme git', 'dusunme-git-bir-gariban-r8lti', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Garibanlığımı bağışla

Hayvanlığımı hoşgör

Güzel bir gün görmedin benimle

Arsızca geçen zamanın içinde

Arsız ağlayışlarım saklı

Senin gözlerinde saklı

Düşünme bunları git

Benide unut artık.', 'Garibanlığımı bağışla Hayvanlığımı hoşgör Güzel bir gün görmedin benimle Arsızca geçen zamanın içinde Arsız ağlayışlarım saklı Senin gözleri...', ARRAY['Türk Edebiyatı','Şiir','Bir Gariban']::text[], 8.5, '{"poet":"Bir Gariban","poet_slug":"bir-gariban","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dusunme-git-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresiz', 'caresiz-baykal-kaanalp-ufa4k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'aynı buzdağının eteklerinde

otlamalı mıyım sebepsiz

görünen yanılsamlarıma

uyarı almadan gereksiz

yeşil ışık yaktığında

deniz fenerim çaresiz

şüphelenmeli miyim kızıllığından

bütün ışıklar haresiz', 'aynı buzdağının eteklerinde otlamalı mıyım sebepsiz görünen yanılsamlarıma uyarı almadan gereksiz yeşil ışık yaktığında deniz fenerim çaresi...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/caresiz-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göl', 'gol-baykal-kaanalp-sjwa9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ne zaman ki

bir taş atıyorum göle

hareket olur

canlanır su diye

selam vermiyor bana

üstelik attığım taşı da

yutuyor gözüme baka baka

boğazına dursun emi', 'ne zaman ki bir taş atıyorum göle hareket olur canlanır su diye selam vermiyor bana üstelik attığım taşı da yutuyor gözüme baka baka boğazın...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gol-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai', 'rubai-bir-gariban-ktfok', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Allah bizi yoktan var etmiş

İsrafil surhu üfleyince dünyanın kapıları çekilmiş

Bu güzel dünyada insanın ilk görevi

Canını kırıp dökmeden allaha teslim etmekmiş.', 'Allah bizi yoktan var etmiş İsrafil surhu üfleyince dünyanın kapıları çekilmiş Bu güzel dünyada insanın ilk görevi Canını kırıp dökmeden all...', ARRAY['Türk Edebiyatı','Şiir','Bir Gariban']::text[], 8.5, '{"poet":"Bir Gariban","poet_slug":"bir-gariban","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''ım geçmişimi sil benim...!', 'allah-im-gecmisimi-sil-benim-omer-faruk-girgin-j3ulm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Allah’ım bana huzur ver

geçmişimi sil benim

taş gibi inatçı eller sıkmasın artık boğazımı

ve tut saçlarımdan kaldır beni ayağa 

yıldız tozları serp karanlık yokuşuma

ve çıkayım bu çıkmazdan

kuş yuvalarına dokunayım artık

tüm arzularım, hayallerim kaymasınlar 

tırmandığım bir gece yarısı çakıllığında…! 

Allah’ım bana huzur ver

geçmişimi sil benim 

al alacaklarını ve beni azat et

istersen bana dağ başlarında rüzgar güllerini solut

istersen kemik  tozlarına bula tutsak gömleğimi

öğütsün diye daha doymamış köpeklerin inatçı mideleri

sadece bana geceleri sarınabileceğim

sevdiğimin rüzgarında dokunmuş 

bir gömlek meltemi ver yeter…!', 'Allah’ım bana huzur ver geçmişimi sil benim taş gibi inatçı eller sıkmasın artık boğazımı ve tut saçlarımdan kaldır beni ayağa  yıldız tozla...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Girgin']::text[], 8.5, '{"poet":"Ömer Faruk Girgin","poet_slug":"omer-faruk-girgin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/allah-im-gecmisimi-sil-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Densiz', 'densiz-baykal-kaanalp-6l5wx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'esirgemediğin sözler

benimle ya da bensiz

yüreğimde ki közler

içimi yakan densiz

yalnız bir kalbi özler', 'esirgemediğin sözler benimle ya da bensiz yüreğimde ki közler içimi yakan densiz yalnız bir kalbi özler...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/densiz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-nilgun-i-nan-st5lx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerimi sende açtım,

ömrümü sana adadım,

Allah''tan sonra sana taptım,

sensin artık tek muradım,

hem derdimsin hem dermanım,

al Mehmedi sürükle,

senindir bu canım..

                                

                                        MEHMET''TEN BİRİCİK ESMERİNE', 'Gözlerimi sende açtım, ömrümü sana adadım, Allah''tan sonra sana taptım, sensin artık tek muradım, hem derdimsin hem dermanım, al Mehmedi sür...', ARRAY['Türk Edebiyatı','Şiir','Nilgün İnan']::text[], 8.5, '{"poet":"Nilgün İnan","poet_slug":"nilgun-i-nan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-seviyorum-215-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Depremi', 'yurek-depremi-yasin-mortas-zcn9v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hüznün uzak toprağı

tutamadım uykunu

serin ırmaklara

bu toprak

sancılı yüreğine yaktı ateşini

günah ödüllü çanlar

çalar çalar yakar ateşini

bir ses doğdu

roketten mermiden

uçtu minare gözlerimizden

kirli düş birikintisi

kilise tütsüsü

sonra savaşın bakracından akan

bakiye çocukların gözünde

Endülüs türküsü

şu şarapnelle düşen

barut kokulu takıları

hangi sevincinin boynuna dizdin

söylesene toprak ana

ağlama yine yalnız kalmışlar gibi

ufka demletme gözlerimizi

suskun damarında uçsuz için cenk mi

yüreğinde patlayan

atom bombasına eş mi

kanın değil mi Mostar’la akan

uzletin reva mı

ah Bosna ar güneşim

cesur bir yıldız

daha çekiliyor kabuğuna

karanlığında Avrupa’nın

aydınlığında Endülüs’ün

fesleğen akşamları çivilenen

oy uykusuz Bosna içimde yanan

atom yağmuru altında

kendi gözleriyle yağan

uyan içim

uyan

yetiş içim

ellerim yandı toprağın sıcağında

içine aktı ateşi Bosna’nın

yetiş içim

(yaz’93)', 'hüznün uzak toprağı tutamadım uykunu serin ırmaklara bu toprak sancılı yüreğine yaktı ateşini günah ödüllü çanlar çalar çalar yakar ateşini ...', ARRAY['Türk Edebiyatı','Şiir','Yasin Mortaş']::text[], 8.5, '{"poet":"Yasin Mortaş","poet_slug":"yasin-mortas","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/yurek-depremi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duru', 'duru-yasin-mortas-jxg0u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu 

sabah

rüzgarı

değdirmedi

gözlerinin 

kirpiğini

hilal

kaşına

kuytuluğu

seven

sabahın

şebnem

zamanı

gözlerini

üşütmedi

hiçbir

kırağı

bu

sabahın

akşamında

sonsuz

bir gecenin

uykusuna

kirpiklerin

yumulur

her

zaman

yıkanık

sabahın

hüseyni

makamında

gözlerin

her dem

çözülür

durulanır

93’yaz', 'bu  sabah rüzgarı değdirmedi gözlerinin  kirpiğini hilal kaşına kuytuluğu seven sabahın şebnem zamanı gözlerini üşütmedi hiçbir kırağı bu sa...', ARRAY['Türk Edebiyatı','Şiir','Yasin Mortaş']::text[], 8.5, '{"poet":"Yasin Mortaş","poet_slug":"yasin-mortas","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/duru-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhumun İncelen Uykusu', 'ruhumun-i-ncelen-uykusu-yasin-mortas-gosj7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dilin hangi mevsimde dinlenip de

babanın kulağını çınlatırsın uzun boylu/oğul

içimde özlemlere hazırlanan

bir kanat çırpınır gün boyu/kesintisiz

yorgun sular köprümde dinlenir de

hafif kokunuz çalar burnuma/esintisiz

canıma yaslanırsınız oğul

ruhuma kokarsınız

gönlümün her teli

çırpındıkça göğsümün yarılı yerinde

acı bir beste gibi sararır

sıkıntısı yağmur toplar topraklarımın

ben neyle gelirim yanınıza

damarlarıma yüklenen bu yük oğul

hangi fırtınalardan yalnızlık kaldı

ruhumun incelen uykusu

gecenin sessizliğine kalkar da

içimde elenirsiniz oğul

kuş imdadı gibi seslenirsiniz

yuvasızlığıma 

yalnızlığıma

güz’96', 'dilin hangi mevsimde dinlenip de babanın kulağını çınlatırsın uzun boylu/oğul içimde özlemlere hazırlanan bir kanat çırpınır gün boyu/kesint...', ARRAY['Türk Edebiyatı','Şiir','Yasin Mortaş']::text[], 8.5, '{"poet":"Yasin Mortaş","poet_slug":"yasin-mortas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ruhumun-incelen-uykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun Yağış', 'suskun-yagis-yasin-mortas-01w05', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ıslı hasret

yılların ağzından aktı

çok büyülü günahlar

çoğaldı kaldı uykumuzda

çocuklar uyandırın geceyi

sabah baharın önünde gelir

gelir durur sınırlı akşamlara

seğirir gözü ay gözlerin

dua kanatır bulutlar

yağar güneşe ağlayarak

göçlerin vakti yanar

ağıt getirir uzayarak

sarar etrafını cümlesinin

gönül düşünün sıcaklığı

daralır çemberi azgınlığın

ey ufkun önünde gelen

kızıl gözlü süvari

heybelerine doldur

dolunay getir gecemize

gölün durgunluğu kadar manalı

ve derinliğini aşmış

kimler var sarhoş dimağında

sonsuz gök yüzünü açtı

şifresiz ve daha açık

duygusuna sahip çıkanlar için

iç zenginliği bulanlar için

ve kafa yıldıranlar/çıkmazla

az yumru gözlerini

bir dil çukurunun

altına ittiler

ne kadar sevecen suskun

deniz arksına

uzayan şiir

hangi dağın

koğuğuna sığındı

bu sağnak yağış

güz’93', 'ıslı hasret yılların ağzından aktı çok büyülü günahlar çoğaldı kaldı uykumuzda çocuklar uyandırın geceyi sabah baharın önünde gelir gelir du...', ARRAY['Türk Edebiyatı','Şiir','Yasin Mortaş']::text[], 8.5, '{"poet":"Yasin Mortaş","poet_slug":"yasin-mortas","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/suskun-yagis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülen bir yüzdü', 'gulen-bir-yuzdu-gencay-coskun-3wvz8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Belli belirsiz bir anı 

Sayılara hapseden 

Gülen bir yüzdü 

Hazır olda bekleyen 

Hüzün değmemişti ona 

Hayata bakan yerlerine

Dert sandığı şeyler 

Fındık kabuğu masallardı 

Bizimkisi ise

Kelle koltukta gidilen arabalardı 

Asfalt yollardaki tümseklerden geçerken

Yanına düşerdim

Düşen yerlerim 

Fena halde acırdı

Her iç kesişmesinde 

Çarpışırdı düşünceler

Çekirdek çitlerdim

Göllere yakın koruluklarda 

Bir rüzgar eserdi 

Sessiz ve kimsesiz bu rüzgarda 

Tanıdık dost görmüş gibi sevinirdim 

Yolla uslanmayan 

Derde doymayan 

Bin kerede bin daha bölünen 

Belalı bir başım vardı 

Bu başla bu ayaklar 

Daha çok yorulacaktı 

Gülen bir yüzdü

Gözler birbirine süslenirdi

Dokunası duygularda

Ellerim terlerdi

Tutamazdım kayıp düşerdi hislerim 

Gülerdim dışımdan 

İçimi sakın sormayın 

Bende bilemezdim ne yaptığını 

Mecburiyetler zinciri boynunda 

Attığın adım olay olurdu 

Attığın adım sonum olurdu

Hiçbir son asla benim değildi

Aslında bu yaşatılan ben 

Ben değildi......', 'Belli belirsiz bir anı  Sayılara hapseden  Gülen bir yüzdü  Hazır olda bekleyen  Hüzün değmemişti ona  Hayata bakan yerlerine Dert sandığı ş...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/gulen-bir-yuzdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yosun Rengi Gözlerin Masallar Anlatıyor', 'yosun-rengi-gozlerin-masallar-anlatiyor-murat-nail-guney-z6ho8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yosun rengi gözlerin masallar anlatıyor,

Yolda kaldı gözlerim, gelmedin, gün batıyor.

Anılar öyle derin yara ki yüreğimde,

Ağlarken güldürüyor, gülerken ağlatıyor...

Sen sevgiyi şarkı gibi dinlemiştin dilimden,

Mısra mısra geçiyorsun gözlerimin önünden

Senden önce coşkun sel, fırtınalar gibiydim,

Sen kalbime gireli korkar oldum ölümden...

Şu gönülden ne macera, ne serüvenler geçti,

Bu şair küstü sevdaya, özgürlüğünü seçti,

Fotoğraflarda kaldı en güzel gençliğimiz,

Ömür su gibi akıp, kuş gibi uçup geçti...

Şimdi kuşlar da dalıyor en uzun uykulara,

Gölgeler eğri büğrü düşüyor kuytulara,

Bir zamanlar sevdalı gönlümün durağıydı,

Şimdi martılar arkadaş körfezdeki sulara...

Muradım ermezmiş hızlı koşanlar hedefine,

İhanet eken aşka, ihanet biçer yine,

Bodrum falezlerinde şimdi sessizlik hakim,

Sabah güneşi doğuyor uykusuz gözlerime...

Samanyolu yıldızları parlıyor gecelerde,

Şarkısı kulaklarda, sevgisi yüreklerde,

Hepinizin imzası var ey şiir yürekliler,

Dostluk ve sevgi adına kazanılan zaferde...

murat nail güney-Bodrum.  01/11/2004

''2K 1Ş ŞİİR AKTİVİTESİ İÇİN KALEME ALINMIŞTIR. KELİMELER ''FOTOĞRAF VE KUŞLAR''', 'Yosun rengi gözlerin masallar anlatıyor, Yolda kaldı gözlerim, gelmedin, gün batıyor. Anılar öyle derin yara ki yüreğimde, Ağlarken güldürüy...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yosun-rengi-gozlerin-masallar-anlatiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık döküktüm', 'kirik-dokuktum-gencay-coskun-4lsb3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Belli belirsiz bir anı 

Sayılara hapseden 

Gülen bir yüzdü 

Hazır olda bekleyen 

Hüzün değmemişti ona 

Hayata bakan yerlerine

Dert sandığı şeyler 

Fındık kabuğu masallardı 

Bizimkisi ise

Kelle koltukta gidilen arabalardı 

Asfalt yollardaki tümseklerden geçerken

Yanına düşerdim

Düşen yerlerim 

Fena halde acırdı

Her iç kesişmesinde 

Çarpışırdı düşünceler

Çekirdek çitlerdim

Göllere yakın koruluklarda 

Bir rüzgar eserdi 

Sessiz ve kimsesiz bu rüzgarda 

Tanıdık dost görmüş gibi sevinirdim 

Yolla uslanmayan 

Derde doymayan 

Bin kerede bin daha bölünen 

Belalı bir başım vardı 

Bu başla bu ayaklar 

Daha çok yorulacaktı 

Gülen bir yüzdü

Gözler birbirine süslenirdi

Dokunası duygularda

Ellerim terlerdi

Tutamazdım kayıp düşerdi hislerim 

Gülerdim dışımdan 

İçimi sakın sormayın 

Bende bilemezdim ne yaptığını 

Mecburiyetler zinciri boynunda 

Attığın adım olay olurdu 

Attığın adım sonum olurdu

Hiçbir son asla benim değildi

Aslında bu yaşatılan ben 

Ben değildi......', 'Belli belirsiz bir anı  Sayılara hapseden  Gülen bir yüzdü  Hazır olda bekleyen  Hüzün değmemişti ona  Hayata bakan yerlerine Dert sandığı ş...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/kirik-dokuktum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanma...Gelme', 'sanma-gelme-ahmet-kose-wpoeh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sanma

bu yangın 

bir daha olacak.

Kaç kez geleceksin bu dünyaya..! 

bıraktığın ateş

için için...

seni ben hangi kapılara sorayım

ışıksız

sessiz.

Gelme

daha henüz düşmeden yapraklarım

yakın değilsen bu yüreğin dallarına

sabah öpücüğü olmazsan eğer.

Belki de azı kaldı çoğu gitti

bu sevginin

sırf az kalanı içindi bu usulluğum

düştün yine gözüme 

sabah uyanmalarımda

kokulu.

Cennet cehennem gidip geliyorum.

27/10/04/bitez', 'Sanma bu yangın  bir daha olacak. Kaç kez geleceksin bu dünyaya..!  bıraktığın ateş için için... seni ben hangi kapılara sorayım ışıksız ses...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sanma-gelme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son mısrâya kadar', 'son-misr-ya-kadar-sair-ahrazi-zd38y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün,dirilsem diyorum,yeniden uyansam,

Ve yeniden öğrensem bir çocuğun hayâlini,

İlk güneşin doğması gibi şu pencereden,

Açsa diyorum bir ümit,açılmayan gözlerimi.

Bugün,uyansam diyorum,uyumasam bir daha,

Uzanmasam hani,yarın kalkacağım yerlere,

Ölüm de var diyen olmasa hiç,ve hatta,

Yaşamak bu deseler,ölüm başka sefere.

Bugün,vazgeçsem diyorum,vazgeçsem her şeyden,

Hiç anmasam adını,bir an bile duymasam,

İşte böyle bir insanım.(!) .diyenlerin ülkesinden,

Çoktan giderdim ben,yaşıyor olmasam…

* * *', 'Bugün,dirilsem diyorum,yeniden uyansam, Ve yeniden öğrensem bir çocuğun hayâlini, İlk güneşin doğması gibi şu pencereden, Açsa diyorum bir ü...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/son-misraya-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçici Ayrılıklar Üstüne Satır Başları', 'gecici-ayriliklar-ustune-satir-baslari-meltem-kaya-j5qbb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1.

Sarı bir hüzünle ve gizli yalnızlıklarla titredi...

Kelebeğin kanadı tortulu bir kuytulukta...

Sanki acı; maviliğe açılan bir uçurumun ortasında

Çağıldayan ama  sonu gelmez bir gökyüzü gibiydi...

Dokunamadı O, gösteremedi acısını

Yapraklarını keskin bir yağmur budamıştı...

Dalgalar tüm uzak kıyıları birbirine bağlasa da

Kızıl bir hasretin koyulaşan denizinden 

Damla damla ışıklarla yüreğine dökülen yakamozlar

Sessizliğin tiz çığlıklarla söylediği

Kuytudaki nazlı bir kır çiçeğinden yükselen

İçli ve hazin bir sevda şarkısı gibiydi...

Yağmur sadece kirpiklerinden içeri yağarken

Hazin şarkısını söyledi O da hafiften hafiften...

Kimseler duymadı...

2.

Sabahın ilk ışıkları pervasızca doldu içeri

O’nun yüreği hep, O’nun gözleri hala beyaza sevdalıydı...

Kanatları uçmayı yeniden öğrenmeliydi...

Zulmün dikenlerinde solmuşsa bile nice gülleri

Kuşlar uçurup yeni sevdalar üstünde

Yağmamış yağmurlar, iklimsiz açan dostluklar için

Paramparça olmuş yüreğini böyle bal acısı hüzünlerle

Bulutla gökyüzü gibi yoğurmamalıydı...

Hasreti bir kelebek rüzgarıyla usulca eserken yüreğinde

Hazin sevda şarkısına gülümseyip kaldı öylece...

Yaşam deli bir nehrin kanadına takılmış gidiyordu...

Nehrin seyircisi oldu...

3.

Geçici ayrılıkların buğulanan o ipince sızısı

Madem ki “ilk yaz çiçeğine gebeydi! ”

O zaman umudun rengi sadece beyaz olmamalıydı...

Hasreti bunca güzel taşıyorsa bir papatyanın beyazı 

Papatyanın güneşe değen sarısı da sevdalanmalıydı...

Gül kokulu selamlar taşıdı mektup kuşları

Uçurum özlemi değil..yıldızdan bir sevdaydı...

O deli nehir O’ndan ayrı akmıyordu artık

Yarına gülümseyen sadece o hazin şarkıydı...

Nehrin notası oldu...

4.

Bahardı, çok bahardı, baştan sona bahardı...

Kuru bir dalda hayat buldu uçuşan çiçek tozları

Bir gül kanar gibi usuldan usuldan kanasa da gözleri

Kırmızı bir bulut oldu, bir nisan yağmuru kadar dolu

Kelebeğin ömrü serçenin kıpırtısına karıştı

O aslında hep bulutlarla yarıştı...

Kol kanat gerdi uçurum bildiği maviliğin üstünde

Çağlayan gibi mavi, öyle coşkun ve özgürdü sevdası

O hazin şarkı bir bütünün parçası oldu, bir elmanın yarısı...

Sevdası al bir elmaydı...

Dalından hiç koparmadı...', '1. Sarı bir hüzünle ve gizli yalnızlıklarla titredi... Kelebeğin kanadı tortulu bir kuytulukta... Sanki acı; maviliğe açılan bir uçurumun or...', ARRAY['Türk Edebiyatı','Şiir','Meltem Kaya']::text[], 8.5, '{"poet":"Meltem Kaya","poet_slug":"meltem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/gecici-ayriliklar-ustune-satir-baslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Yağmurları', 'huzun-yagmurlari-mehmet-sogut-cibe9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hüzün yağmurları

fırdolayı kahpelik

vurulan sürülen öldürülen

biz

tarih arsız bir oruspu öğrendim

biz de tarihin kasıkları arasından

düşen piçleriz.', 'Hüzün yağmurları fırdolayı kahpelik vurulan sürülen öldürülen biz tarih arsız bir oruspu öğrendim biz de tarihin kasıkları arasından düşen p...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Söğüt']::text[], 8.5, '{"poet":"Mehmet Söğüt","poet_slug":"mehmet-sogut","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/huzun-yagmurlari-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzim kalmasın isterdim', 'i-zim-kalmasin-isterdim-gencay-coskun-dwqh2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İzim kalmasın isterdim 

Bastığım kaldırımlarda

Koştuğum oynadığım sokaklarda 

Sessiz bir ışık gibi 

Görünmeden bilinmeden 

Geçip gitmek isterdim 

Karla kaplı dağlardan 

Kum dolu çöllerden 

Taştan evlerim vardı 

Kapısında adlarım yazılı 

Damları toprak doluydu

Derken günler geçerdi 

Otlar biterdi 

Köklerim derindeydi 

Mevsimler geçerdi 

Köklerim kandaydı

Sessizdi evlerim 

Bir gece bile uyumamıştım 

Çatılarımın altında 

Yolları kaybolmuştu 

Yolları dikendi 

İçim yalnızdı

Çok yalnızdı 

Esip geçmek isterdim 

Hiç değmeden 

Yeryüzüne 

Sonsuzlukta kaybolmak 

Kuyruklu yıldızların peşine takılmak 

Yangınlarda deliksiz uyumak isterdim 

Eski kavimlerin 

Güne uzanan anıtlarında

Asla okunamayacak yazılardım

Bin bir duyguyu 

Bin bir günahı anlatan 

Taştan kalıntıların 

Hep iç taşıydım 

Acıyla örülen duvarlarım

Sevgiyle yıkılırdı 

Asla gün görmeyecek

İçlerim olurdu 

Şifremi yaratana verip

Geçip gitmek isterdim 

Hiç adım atmadığım ormanlarda 

En vahşi hayvanlarla oyun oynamak isterdim 

Adilere, kalleşlere, ömür törpüleyenlere inat 

İzim kalmasın isterdim hayatta 

Günü gören gözlerime 

Eziyet edilirdi 

Griliğin dünyası gösterilerek

Gözlerim akı kararırken 

Bir sabah çiğ düştüğünde 

Günle beraber uçup gitmek isterdim 

Gidebildiğim kadar.....

İzim kalmasın isterdim 

İzimden gelen olmasın diye...', 'İzim kalmasın isterdim  Bastığım kaldırımlarda Koştuğum oynadığım sokaklarda  Sessiz bir ışık gibi  Görünmeden bilinmeden  Geçip gitmek iste...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/izim-kalmasin-isterdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Semada-57', 'semada-57-ahmet-kose-qwxfm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '...kalıbımı basarım nidaları

ara nağmeler,

...yapmazsam ne olsun..! 

akord sesleri.

Seni ben..! 

...işte bu yüzden  seçtim.

...ama sen...

her gamda

her isyanda

her hüzünde

bana ara taksim geçtin yaşam...! 

04/bitez', '...kalıbımı basarım nidaları ara nağmeler, ...yapmazsam ne olsun..!  akord sesleri. Seni ben..!  ...işte bu yüzden  seçtim. ...ama sen... he...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/semada-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırıncının Küreği', 'firincinin-kuregi-ahmet-kose-tcnax', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '...yarın gidiyorum

maviye,

en ben yere...

İki el

iki göz

bir yürek

bir ruh

diğerleride bir kaç adet

harmanladığında

bir insan çıkıyor 

hayat fırınından.

Kiminin kulağı kesik

kiminin burnu kırık

kiminin sol ayağı aksar

kimi bir gözü ile gülümser

kıskıs

kimi yarım ağızlı

tıstıs

kimi omuz silker

kimi karnından konuşur

kimi veremdir doğuştan

kimi kimseyi göremez

kimi kimsesizdir

kimi ruhsuz çıkar

fırıncının küreğinden.

ekim/04/bitez', '...yarın gidiyorum maviye, en ben yere... İki el iki göz bir yürek bir ruh diğerleride bir kaç adet harmanladığında bir insan çıkıyor  hayat...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/firincinin-kuregi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Semada-58', 'semada-58-ahmet-kose-jn8ys', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yukarısı aşağısı yok bu yaşamın

düştün sen...! 

Hangi kalçanı oynatsanda

çıktığın yaşam belli artık

zorlama yüreğini

bu tiyatroya hoşgeldin

kılın dönsede

tüyün kopsada

oynayacaksın,

eğer değilsen bu kapının önünde

yoksa ben seni 

niye düşüneyim ki..! 

ekim/04/bitez', 'Yukarısı aşağısı yok bu yaşamın düştün sen...!  Hangi kalçanı oynatsanda çıktığın yaşam belli artık zorlama yüreğini bu tiyatroya hoşgeldin ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/semada-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Aşkı Satın Aldım', 'ben-aski-satin-aldim-tunahan-ermihan-zplii', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben aşkı satın aldım sevdiğim senin haberin yok. Bir gece yarısıydı sözler batmıştı ufukta gözlerde bir garip hale parlıyordu, ben sokakları aydınlatan aşk kalıntılarının arasında dolanırken bir dilenci kızın gözlerinde buldum aşkı. Adını sordum gülümsedi sararmış dişlerini sergileyerek. 

Ayşe Fatma her neyse bir isim verdi bana bir de kolundaki çizikleri gösterdi sonra gözlerini dikti sonu belli olmayan karanlık sokağa. Gelebilirmisin dedi benimle bu sokağa. Açıkçası korktum gitmekten ama kalmayı da istemedim olduğum yerde. Hem ne kalmıştı ki kaybedecek hayatta. Elimi tuttu ve yürümeye başladı. Adı her neyse olan bu kız her adımda büyüyordu sanki yanımda. Yolun ortasında durdu. Bak işte aradığın şey tam burada dedi. Ama ben ne arıyordum ki veya benim ne aradığımı o nereden biliyordu. Birbirinin kardeşi binlerce soru örümceği beynimin en ücra köşelerini parselleyip satışa sunmaya başladığı anda etrafına bak dedi her neyse... Baktım ve baktığım her noktada yazamadığım şiirler gibi gömüldüğüm karanlıklar çakıldı gözlerime sonra gözlerimin feri söndü sonra dilim lal oldu sonra adın hafızamdan silindi sonra ben hayattan koptum sonra ben... Sonralara mahkûm oldum. 

Şimdi sesi de gelmiyor her neysenin. Düşünceler... Karınca misali beynimin içinde örümcek ağlarından kalan yerlerde dolaşan ve askeri bir nizam ile birbirlerine asla temas etmeyen düşünceler geziniyor beynimde. Ben ise içlerinden bir tanesine tutunup gülmek istedim sadece oda gidişinin timsali kara karınca çıktı. Şimdi gidişinin ardından sokakları aydınlatan bir aşk kalıntısı olacak beklide gözyaşlarım. Ben aşkı satın aldım sevdiğim senin haberin yok. Ben bu gece sadece senden değil tüm yaşayan her şeyden aşkı satın aldım. Önce senden sonra kendimden sonra hayattan sonra gelecekten sonra... Sonra ile başlayan her şeyden vazgeçerek ödedim bedelini. Ama ban aşkı satın aldım.', 'Ben aşkı satın aldım sevdiğim senin haberin yok. Bir gece yarısıydı sözler batmıştı ufukta gözlerde bir garip hale parlıyordu, ben sokakları...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ben-aski-satin-aldim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atalarımdı', 'atalarimdi-gencay-coskun-59ftr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Atalarımdı

Hep delikanlıydılar

Hep cesurdular 

Namerde bile

Hep merhametliydiler 

Aslan gibi çarpışarak 

Kaçmadan delikanlı gibi ölmüşlerdi 

İçlerim alev alev yanardı 

Çiğnenen her karış topraklarda 

Mezarları bile belli olmayan 

Sessiz atalarım, dedelerim, 

Boncuk gözlü ninelerim 

Yağmur olup kanlarıyla yağdılar 

Bu topraklara

İzleri vardı yüreğimde 

İzleri vardı kuruyan topraklarda 

İzleri vardı kanımın her damlasında 

İçimin yandığı yerdir 

Kanlarınızın aktığı yerler

İçimin yandığı yerdir 

Etlerinizi kemiğe döndüğü yerler 

Ne altındı nede paraydı istedikleri 

İstedikleri 

Başımızın dimdik yürüdüğü

Rüzgarın bile özgürce estiği 

Özgür Vatan topraklarıydı

Canlar mermiden hızlı verilirdi 

Azrail’e yetişirlerdi 

Al götür bizi 

Vatanımız kalsın yalnız burada yeter ki 

Kanlardan göllere basarlardı 

Kandaşları, arkadaşları 

Karışıp giderlerdi zamana

Ardımızdan gelenler bizi hatırlasın diye 

Ansızın gelen kahpe demirlerle

Çam gibi düşerlerdi gövdelerine 

Ardımızdan gelenler üstümüzü örtsünler 

Bizi unutmasınlar diye 

Dedelerini asla hayat gözüyle görmeyen 

Her adınız geçtiğinde 

Yetim torunlarınız var şimdi 

Can verdiğiniz coğrafyanızda 

Sizleri özleyen 

Sizlere özenen 

Sizi görmeyen gözlerinden 

Yaşlar akan torunlarınız var

Ölen her atama 

Binlerce öpücük gönderebilsem 

Ellerine, yüzlerine 

Hiç beyazlaşmaya

Ölmekten  fırsat bulamayan sakallarına 

Dokunasım gelirdi 

Ağlardım içli içli 

Ellerim titrerdi 

Kızardım içimizdeki kahpelere

Atalarıma söylemeye dilim varmazdı 

Soyumuza köpeklerin karıştığını

Atalarımdı 

İçlerimin özlediği 

Yarınlarımdı

Uğruna öleceğim 

Topraklarımdı

Kanımın çektiği

Kahpeler size yar etme geleceği...', 'Atalarımdı Hep delikanlıydılar Hep cesurdular  Namerde bile Hep merhametliydiler  Aslan gibi çarpışarak  Kaçmadan delikanlı gibi ölmüşlerdi ...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/atalarimdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bilemezsin', 'sen-bilemezsin-nazim-yildiz-yx2jb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen beni bilmezsin

Sabahsız gecelerde avunurum ben

Mutluluğu özlemlerimle yaşarım

Tüm tedirginliği davet ederim çağrımla

Ben mutluluğu elemle yaşarım

Sen beni bilmezsin

Yağmurlu günleri severim ben

Upuzun ürküten karanlıkları severim

Bazen kadehlerde ararım teselliyi

Ben mutluluğu hüzünle yaşarım

Sen beni bilmezsin

Kalabalık caddelerde hüzünlenirim ben

Mutlu insanları görünce kahrederim

Ben tenhalarda yalnızlığı severim

Öylesine yaşarımki sensiz sen bilemezsin', 'Sen beni bilmezsin Sabahsız gecelerde avunurum ben Mutluluğu özlemlerimle yaşarım Tüm tedirginliği davet ederim çağrımla Ben mutluluğu eleml...', ARRAY['Türk Edebiyatı','Şiir','Nazım Yıldız']::text[], 8.5, '{"poet":"Nazım Yıldız","poet_slug":"nazim-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-bilemezsin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkıma', 'askima-cem-han-96gay', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçini hoş eden benmiyim

Gönlüne seslenen şarkı,şiirmiyim

Ansızın karşına çıkan aşkınmıyım

Kalbini sevgiyle dolduran bakışınmıyım

Yalnızlığın yalnızlığım oldu

Yeşil gözlerim hergün seni arar oldu

Nil yeşili gözlerim yolunda solsun

Kalbin benim aşkımla dolsun

Aşk melodim senin için bitmeyen serenat olsun

Ay ışığın sanki karanlık dünyamı delen güneşti

Bu sevgiden yıldızlarda titreşti', 'İçini hoş eden benmiyim Gönlüne seslenen şarkı,şiirmiyim Ansızın karşına çıkan aşkınmıyım Kalbini sevgiyle dolduran bakışınmıyım Yalnızlığın...', ARRAY['Türk Edebiyatı','Şiir','Cem Han']::text[], 8.5, '{"poet":"Cem Han","poet_slug":"cem-han","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/askima-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi lekesi', 'sevgi-lekesi-esra-oskay-9d6b9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SEVGİ LEKESİ

Acıtan kar beyaz   elbislerimi,

Renkli puantiyeli eteklerimi,

Ne varsa topladım...

Beyazlatıcı deterjanlarla yıkadım.

Yine çıkmadı izin! 

Güneşinin lekesi..

.

Kurşun geçirmez yelek giydim,

O Rh + kanımı değiştirdim.

Damarlarda pıhtılaştı izin...

Anjio ile açılmayan yüreğimin

Çarpıntısında; 

Son şişendeki, şarap ın lekesi..

Kalbini okşadığım ellerimi; 

Saatlerce buz gibi sularda..

Lavanta kokulu sabunlarla yıkadım..

Geçmedi elimdeki kokun,

Parfümün şeftali lekesi! 

Meyveleri dalından kopardım,

Krımızı dudaklarımdan süzüldü,

Tenime yayıldı vişne,kiraz,bögürtlen..

Kalbime  işledi,

Yanaklarım; 

Nar kızarıklığı...

Belleğimden  çıkmadı, nar ın _ lekesi! ! 

                           A.Esra OSKAY', 'SEVGİ LEKESİ Acıtan kar beyaz   elbislerimi, Renkli puantiyeli eteklerimi, Ne varsa topladım... Beyazlatıcı deterjanlarla yıkadım. Yine çıkm...', ARRAY['Türk Edebiyatı','Şiir','Esra Oskay']::text[], 8.5, '{"poet":"Esra Oskay","poet_slug":"esra-oskay","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sevgi-lekesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellinci yaş', 'ellinci-yas-cem-han-zwkez', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ömür böyle geçti

Sanki kaydıraktan kayar gibi

Her bir basamak,on yıldı

Beş basamakta bu ömür doldu

İşte bir ömür böyle geçti aniden.

Bir gün güldü,bir gün güldürdü

Ağlayan da oldu,yasla doldurdu

Bazen acılarla yoğurdu...

Seni seven seviyor,yeren yeriyor

Aşk sevgi saygı para hepsi boşmuş

Sizler gönlünüzce yaşayın

Hayat çok hoşmuş...', 'Bir ömür böyle geçti Sanki kaydıraktan kayar gibi Her bir basamak,on yıldı Beş basamakta bu ömür doldu İşte bir ömür böyle geçti aniden. Bir...', ARRAY['Türk Edebiyatı','Şiir','Cem Han']::text[], 8.5, '{"poet":"Cem Han","poet_slug":"cem-han","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ellinci-yas-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktaki Adam', 'uzaktaki-adam-esra-oskay-hhszr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecelerden süzdüm sancıları

 Gündüzüme aldım seni..

 Seni aldım yaşamıma; _

 Uzaktaki adam! 

 Şiirlerim susadı, 

 Damıttım kalbimin içinde

 Döktüm avuçlarına..

 Tütün kokusu bulaşırken parmaklarıma,

Biterken geleceğin ısısı,

Dibi görünen erik rakısının şişesinde..

Tükendi uzakta ki adamım, izlerin..

Güneş küstü, gece oldu,

Yağmur ihanetini vurdu gamzeli sakallarına..

 Açık alnında çizgilerin,

 İri sürmeli gözlerinde hüznünle..

Esen ayazda ellerin üşüyorken,

Çektin yine son yudumu şişenin dibinden..

Doğumla ölüm arasındaki çelişen yaşamdan,

Sıkıştırılan duyguların ısrarından..

Bir damla göz yaşı döktün..

Sevdiğin kadına bakan dostlarınla dövüştün.

Tenha o sokakta ıslık dudağına dokunamadan, 

Düşündün bir bir yitirdiklerini..

Kutsal kavganın kaderinde..

Kırmızı kelimeler  o yalancı tende kaldı.

Yasak cümleler de dehşetle; 

Yazamadın duvarlara,karanlık gecelerde,

Ay ışığında...

Yazamadın, telefon tuşlarında mesajlara; 

‘’seni seviyorum’’

sanki yasaktı sana bu cümle..

sanki yakışmayacak sandın ağaç gölgelerinde,

Bugulanmış pencerenin camında yasaklarla..

Yaşam ve ölüm arasında iniş çıkışlarında..

Vazgeçtin tüm gerceklerden..

Gerceğe dönmek istedİğinde; ,hayata döndün..

Şiirlere döndün.. 

Yasak olmayan ellerinle yüreğini,

Yüreğimi ısıttın.üşüyen yüreğimizi,

ısıtırken ilme ilme belleğinde..

Ve sen çok pişman iken; 

Şiirlerin bana mirasta,

Emanet edemedin sayfaca dolu dizelerini

Hayatın meleklerine..

Kırmızı damlaların artarken yanağında,

 Bir kız çocuğu; 

 Kömür gözleriyle yaklaştı sana..

 ‘’Hadi tut elimi,gidelim...’’

‘’Bırak acı geceleri..’’

‘’Beyaz düşlerindeki şiirlerini topla gidelim..’’

Minik elin sevincinde; 

Kayboldun sen! Uzaktaki adamım! 

                              A.Esra OSKAY', 'Gecelerden süzdüm sancıları  Gündüzüme aldım seni..  Seni aldım yaşamıma; _  Uzaktaki adam!   Şiirlerim susadı,   Damıttım kalbimin içinde  ...', ARRAY['Türk Edebiyatı','Şiir','Esra Oskay']::text[], 8.5, '{"poet":"Esra Oskay","poet_slug":"esra-oskay","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/uzaktaki-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangisi Zor Acaba', 'hangisi-zor-acaba-esra-oskay-qhufi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dip yüreklere yerleşmek mi? 

Molekül tanelerinde kaybolmak mı? 

Uzaktan sevmek mi? 

Yanında olup ulaşamamak mı? 

Yoksa görülmeyen bulut sirüs gibi mi? ..

Düşündükçe yaşama kahretmek mi? 

Şimdi bir gerçek var bildiğim; 

 Şurada! 

Zor olan kendimde; 

Türkü renklerini karaya bağladım.

Belleğin dürtülerini sildim. 

Gökyüzüne ulaşamadım.

Gülerken ağlamak,

Severken düşünmek mi? 

Hangisi zor acaba! 

Sevmek mi? 

Sevilmemek mi? 

Bildiğim bir şey var; orada 

Ve sen! 

Sensizim..

Kimbilir kaç göze umut vermiş; 

Ardından kasılmış,kaybolmuşsundur.

Kaç imkansızlık ülkesinde ayağını suya dokundurmamışsındır.

Kimbilir, ben kaç düşünceleri çürütmüşümdür! 

Gercek olan bir şey var burada..

VE,Sensizim.

Sevmek için ne yapmalıyım? 

Sevdiğimi belli etmek için kendimden mi vazgeçmeliyim? 

Yoksa çığlıkları beyaz düşlerimden,saçlarımın arasındaki yıldızlardan  mı toplamalımıyım? 

Hangisi zor? 

Severken acı çekmek mi? Sevmeyip lanet etmek mi? 

Bilemiyorum; bildiğim gercek şurada..

Ve ben sensizim..

Bir şarkıya fal tutmuşum,

Bir paket sıgara da cigerlerimi perişan etmişim

Biliyormusun şu an; 

Ne diliyorum Tanrı dan,

Tüm zamanlar silinsin.

Ayrılmış moleküller toplansın,

 İçinden kocaman ‘’sevgi’’çıksın.

 Hangisi zor diye sormayı erteleyeyim, 

Ya da, hiç o soruya yaklaşmamayım.

                       A.Esra OSKAY', 'Dip yüreklere yerleşmek mi?  Molekül tanelerinde kaybolmak mı?  Uzaktan sevmek mi?  Yanında olup ulaşamamak mı?  Yoksa görülmeyen bulut sirü...', ARRAY['Türk Edebiyatı','Şiir','Esra Oskay']::text[], 8.5, '{"poet":"Esra Oskay","poet_slug":"esra-oskay","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/hangisi-zor-acaba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senle yazıyorum', 'senle-yaziyorum-esra-oskay-qu5dj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şiir bu dersi olmaz.

Efsane aşklarını yazsam da; 

Şiir bu! 

Biliyorum karın doyurmaz! 

Kalem tutan elime,parmaklarıma nasırlaşatıran güç te; 

Sen varsın, bunu da biliyorum.

Dünde yazıyordum, bugün de yazıyorum.

Ama dün, yalnız acıdan; 

Bugün aşktan, senin sızından yazabiliyorum.

Yarın ne olur, bilinmez! 

Sen olduğunca; bu yürek yazar! 

Kıyamette yerinden kopar.

Yardımın birkaç şiir ve sevgin! 

İlham perim  sensin bilirmisin? 

Düşünürmüsün sen hiç? 

Ayağına taş gelmeden yanından geçince,

Suratlı otomobilinde; trafik seni sıkıştırdığında kaza yapacakkken, yapamadan kurtuluşuna! 

Hiç şaşırırmısın! 

Düşünürmüsün? 

Bilirmisin? 

Bu yürek sana şiir sözlerinde,

Tanrı huzurunda, ne dualar eder.

Ne şans kokulu çiçekleri yollarına döker...

Bilebilsen sen bunları,

Mutluluk senin peşinde koşar! 

A:', 'Şiir bu dersi olmaz. Efsane aşklarını yazsam da;  Şiir bu!  Biliyorum karın doyurmaz!  Kalem tutan elime,parmaklarıma nasırlaşatıran güç te;...', ARRAY['Türk Edebiyatı','Şiir','Esra Oskay']::text[], 8.5, '{"poet":"Esra Oskay","poet_slug":"esra-oskay","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/senle-yaziyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akik VIII', 'akik-viii-ahmet-aksoy-algs0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '.......................................''M''ye''

.....................................................''Kurdum''

açtım kırık şemsiyemi, bir gülün ayaza vurulması gibi

bir delinin akla sunulması gibi, sırılsıklam yandım

sırasında çatı akıyor dedi yaşlı bir kadın

arasıra konuşan dilsiz bir ölü gibi duymadım

bir seli gösteriyordu oysa her şey kördüm

gözlerim iki firari birbirine şaşkın

bilmem! eğer beni sevmeyeceksen

.....................aynı saksıda ne işimiz vardı', '.......................................''M''ye'' .....................................................''Kurdum'' açtım kırık şemsiyemi, bir gülün...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/akik-viii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-cem-han-mvxqa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen karanlık günlerimin ışığı oldun

Kalbimin sızısının ilacı oldun

Her şey bitti,her yer karanlık derken

Hayatıma doğan güneş oldun

Baharda açan çiçek gibi

Dallarda yuva yapan kuşlar gibi

Yeni doğan bebek gibi

Hayata döndürdün beni

Gel ver elini yeni bir hayata

Sevgimizi yudumluyalım kana kana

Dönmeyelim bir o yana bir bu yana

yaşayalım göz göze baka baka', 'Sen karanlık günlerimin ışığı oldun Kalbimin sızısının ilacı oldun Her şey bitti,her yer karanlık derken Hayatıma doğan güneş oldun Baharda ...', ARRAY['Türk Edebiyatı','Şiir','Cem Han']::text[], 8.5, '{"poet":"Cem Han","poet_slug":"cem-han","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgiliye-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Aşk', 'sessiz-ask-can-ozcan-ozkan-p1cbe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dost kalemim

Sırtını parmaklarıma dayayıp

Kar yağmış kağıtlarda

Çocukça koşarak

Dilleniyordu gözlerimde

Yüreğimden geçenleri

Lapa lapa bırakıyordu

Yağan kar üstüne

Diz boyuna varan dizelerde

Çıkmaya çalışırcasına 

Adımladığım mısralarda

Kömür gözlü

Havuç burunlu

Çocuk emeği

Kardan can bulan

Adam tebessümünde

Bir başlangıçtı 

Soğuk akşamlara karışan 

Nefesler…

Ayaz vakti sis olup 

Çökecekti ufkumuza

Olsun

Görmeden de

Yüreklerin dilinde

Salınan duyguları

Karanfillerden buket yapıp

Şiirlerle anlatacağız

Birbirimize

Yüreklerimizin

Sessiz Aşkını….', 'Dost kalemim Sırtını parmaklarıma dayayıp Kar yağmış kağıtlarda Çocukça koşarak Dilleniyordu gözlerimde Yüreğimden geçenleri Lapa lapa bırak...', ARRAY['Türk Edebiyatı','Şiir','Can Özcan Özkan']::text[], 8.5, '{"poet":"Can Özcan Özkan","poet_slug":"can-ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sessiz-ask-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Gülü', 'sevda-gulu-can-ozcan-ozkan-w6dhm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecenin 

Vurduğu dalgalar

Yıldızlarını bıraktı

Adını yazdığım

Kumsala…

Yürek kokusunda

Açan

Sevda Gülü….', 'Gecenin  Vurduğu dalgalar Yıldızlarını bıraktı Adını yazdığım Kumsala… Yürek kokusunda Açan Sevda Gülü…....', ARRAY['Türk Edebiyatı','Şiir','Can Özcan Özkan']::text[], 8.5, '{"poet":"Can Özcan Özkan","poet_slug":"can-ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevda-gulu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş İzleri', 'dus-i-zleri-tulay-eker-npf82', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gelmeler gidişlerin kokusuymuş 

Sevmelerse özlemlerin. 

Sarılmalar yokuşun başucunda 

Kuşlarsa kanatsızmış Munzur dağında 

Kör pusulaymış düşlerimin izleri 

Gözkırpan aydınlığa inat eden karanlık 

Kafamı kıran soğuk duvarlar 

Aklımı başımdan alansa yaşanmışlık 

Sen sahildin benimse kollarım dalga 

Meltem esintisi ile gelir konardın omuzlarıma 

Kelebek ömrüydu duruşun ve serap olan rüya 

Payıma düşense beklemekti ömrüm boyunca 

Irmaklar dolusu yaşlar biriktirmiştim 

Tohumlar yeşertsin diye toprak ana avuçlarımda 

Mah geceden süzülüp gece gözkırparken güne 

Cılız bir fidanmış açan yüreğimde 

Bastığım her dalda yaprak eziği 

Kendimden bir parça bırakıyorum ardımda 

Yosunlar.. bastıkça kayıyorum üzerimde 

Kanıyor izler aynadaki yüzümde 

Pamuk ipliğine sarılıymış gülümsemelerim 

Yüreğimin kanat çırpışı,sarılışı 

İp koptu..düşüyorum tepe takla 

Dudaklarımda anlamsızlaştı hoşçakal ve merhaba 

Sırtımda bir nokta zemheri ayazında 

Hani sen olacaktın hep yanımda 

Nerdesin..neremdesin? 

Bu da mı rüyaydı yoksa 

^^Yaklaştıkça zamana..Zaman asıyor kendi darağacına ^^', 'Gelmeler gidişlerin kokusuymuş  Sevmelerse özlemlerin.  Sarılmalar yokuşun başucunda  Kuşlarsa kanatsızmış Munzur dağında  Kör pusulaymış dü...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dus-izleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme', 'anneme-murat-ceri-ny28h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beşik gıcırtılarından süzülürken zaman 

Ben göz bebeklerinde büyüyen bir yakuttum

Çullar içinde aslan büyürmüş diyerek sen

Farkında mısın nasıl bir aslanı büyüttün', 'Beşik gıcırtılarından süzülürken zaman  Ben göz bebeklerinde büyüyen bir yakuttum Çullar içinde aslan büyürmüş diyerek sen Farkında mısın na...', ARRAY['Türk Edebiyatı','Şiir','Murat Çeri']::text[], 8.5, '{"poet":"Murat Çeri","poet_slug":"murat-ceri","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/anneme-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gök Kubbe', 'gok-kubbe-guler-ilgaz-vy779', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Alemdir gök kubbe

Sanır ki döner 

Kendi kendine

Alemdir kendi

Döner durur durmaksızın

Her şey gibi kendine

Alemdir işte

Başka bilmem ne denir? 

Ben dönmezsem kendime

Sanır mı ki döner

Gök kubbe

Kendi kendine', 'Alemdir gök kubbe Sanır ki döner  Kendi kendine Alemdir kendi Döner durur durmaksızın Her şey gibi kendine Alemdir işte Başka bilmem ne deni...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gok-kubbe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutsal', 'kutsal-guler-ilgaz-ujkjz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kutsal sözü kulaklarımda

Çın çın çınladığında

Gözlerim ellerimde

Ellerim yoklar duvarları

Zorlar sınırlarımı

Ararım......... nerede?', 'Kutsal sözü kulaklarımda Çın çın çınladığında Gözlerim ellerimde Ellerim yoklar duvarları Zorlar sınırlarımı Ararım......... nerede?...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kutsal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Basmakalıp', 'basmakalip-guler-ilgaz-2eyxy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yılma, yığılma, kalk

Bir an bile şüphe duyma

Basma kalıpların üstüne

Aşma, zıplama zamanı

Tutma bırak

Önce davran kendinden bile

.......................................

Aç yüreğini kendine

Yolun yoldaşın olsun

Pusulan deniz fenerlerin...

Korkma gezin durmaksızın

İçinde

Göreceksin anlatacak ne çok şeyin olacak

Kendine...', 'Yılma, yığılma, kalk Bir an bile şüphe duyma Basma kalıpların üstüne Aşma, zıplama zamanı Tutma bırak Önce davran kendinden bile ..............', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/basmakalip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rızık', 'rizik-ekrem-sama-01tsm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Allah’ın takdiriyle yazıldı sana rızkın,

Sana ayrılan kısmı ararsan bulacaksın...

(İstanbul:31.10.2004)', 'Allah’ın takdiriyle yazıldı sana rızkın, Sana ayrılan kısmı ararsan bulacaksın... (İstanbul:31.10.2004)...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/rizik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kul Hesabı', 'kul-hesabi-ekrem-sama-dqan0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bakiyesiz olmalı, bu hesabın ismi; “kul”,

Mezarına girmeden sıfırlayarak kurtul.

(İstanbul:31.10.2004)', 'Bakiyesiz olmalı, bu hesabın ismi; “kul”, Mezarına girmeden sıfırlayarak kurtul. (İstanbul:31.10.2004)...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/kul-hesabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay ışığı', 'ay-isigi-burhan-kucuk-0xgdz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ay ışığı

Şu esmer gök var ya

Şu kızıl deniz

Ne varsa bizden yana

Buluşurdu düşlerimiz

Kaldırırdım rafa kitapları

Düşünce sevda aklıma

Şiirler yazarım gece yarıları

Ay ışığı vurunca cama

Burhan KÜÇÜK

Kdz.Ereğli-02.11.2004', 'Ay ışığı Şu esmer gök var ya Şu kızıl deniz Ne varsa bizden yana Buluşurdu düşlerimiz Kaldırırdım rafa kitapları Düşünce sevda aklıma Şiirle...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ay-isigi-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', ')))))))))) Ebruli Bakışların ((((((((((', 'ebruli-bakislarin-i-brahim-dikmen-2-mm3rk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Unutmadım ki...! 

Çakmak çakmak yanan

ebruli gözlerini.

Nasıl unuturum, 

Söyle hadi,durma konuş

benimle.

Deniz mavisi,güvercin bakışlarını,

Gözlerindeki o''ebruli ışıkları,

anlat bana,hala aynı saflıkta mı? 

Karanlık gecelerimi aydınlatan,

Renk renk,yakamozlar gibi,

Hayatımdaki gelgitlerimdin,

sen! med-cezirlerimdin.

Birgün...! 

Ardına bakmadan gittiğin de,

O''umarsız, o''naçar kalışım,

Beni, kalbimin sol yanından 

vuran...! 

Şimdi nerdesiniz? 

Sen ve ebruli bakışların...', 'Unutmadım ki...!  Çakmak çakmak yanan ebruli gözlerini. Nasıl unuturum,  Söyle hadi,durma konuş benimle. Deniz mavisi,güvercin bakışlarını, ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ebruli-bakislarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsimler Üreteceğiz', 'mevsimler-uretecegiz-bekir-gedikoglu-olxa6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Denizin üzerine çökmüş

Akşamın alaca karanlığı

Hasretini gideren koca bir aşık gibi

Dudaklarından öpüveriyor denizi

Yanakları kızarmaya başladı deryanın

Ufukta güneş kirpiklerini kapadı

_______________yaktığım on sekiz mum 

havanın karardığını anlarcasına

Yanmağa başladı

Hafif esen meltem altında sallanan mum ışığı

Cananımın gözlerindeki mutluluk parıltılarını

Bir anda olsa yakalıyordu

Gözlerimi gözlerinden alamadığım

Kalbini kalbime çivilediğim

Müstesna güzellik 

…Sanki dünya güzeli gibi

Karşımda oturuyordu

Gülümsemesi var ya…

Dünyayı bana veriyordu

Ya bakışı? 

Beni öldürüyordu…! 

Eli ellerime değdiğinde

Yel görmüş yaprak gibi titriyordum

Bu akşam

Yaş gününe on sekiz mum yaktım

Yılarca sönmemesini diliyorum

Düşünüyorum da? 

Zeytin renkli simsiyah saçlarım var 

Başıma yağacak olan kar

Sessiz ve sedasız olacak

Bihaber kalacağım başımdaki aklardan

Bakışlarına yakalandım ya

Ve gönlümden yaralandım ya

Hem de aşk zıpkınıyla! 

Kurtulup da başka bir cihete bakamayacağım

Başka bir iklime de gidemeyeceğim

Tıpkı onun gibi

Birlikte çizdiğimiz  o kutsal yörüngede

Nice mevsimler üreteceğiz

Ankara 2 Kasım 2004', 'Denizin üzerine çökmüş Akşamın alaca karanlığı Hasretini gideren koca bir aşık gibi Dudaklarından öpüveriyor denizi Yanakları kızarmaya başl...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/mevsimler-uretecegiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yolcu', 'bir-yolcu-sinan-ercan-9jpno', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yolcu bir yolcu ki

Yürüyor

Her ayrılık rayının üstünde bedeni

Ruhu ayrılığa istasyon

Adımlarının ensesinde hâli

Bir yolcu ki

Bakıyor

Ufkunda kervan kervan anılar

Mazinin çentikleri alnında

Bir kendi parmakları var avuçlarında

Bir yolcu ki

Gidiyor

Yolların ardına takılmış adımları

Sokak lambaları düşlerini yakmış

Etini yiyor şehrin kaldırımları

Bir yolcu ki

Ürperiyor

Yüreğinden başkasını bilmemiş bağrı

Dolaşmış omuzlar üstündeki başları

Kıramamış yalnızlık tarağını

Bir yolcu ki

Üşüyor

Kulaklarında çelik sesli rüzgarlar

Gözlerinde kutup soylu bakışlar

Saçlarında bitirim havasında hazan var

Bir yolcu bir yolcu ki

Ayakları çapında izleri

Kalbi kadar elleri

Gözü gönlü kalemi

Gölgesine el sallıyor elleri', 'Bir yolcu bir yolcu ki Yürüyor Her ayrılık rayının üstünde bedeni Ruhu ayrılığa istasyon Adımlarının ensesinde hâli Bir yolcu ki Bakıyor Ufk...', ARRAY['Türk Edebiyatı','Şiir','Sinan Ercan']::text[], 8.5, '{"poet":"Sinan Ercan","poet_slug":"sinan-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bir-yolcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrüm', 'omrum-kamil-boyraz-dto4y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir ömür boyunca boş bir duvara

Hayalini çizip avundu gönlüm.

Geleceksin diye her gün yolara

Baktık ça karardı,karardı ömrüm.

Kurşun gibi delip geçtin içimden

Rüyalarla avunup geçtim kendimden.

Yıllarca şaşmadın bildiğinden

Beklemek den usanıp bitti ömrüm.', 'Bir ömür boyunca boş bir duvara Hayalini çizip avundu gönlüm. Geleceksin diye her gün yolara Baktık ça karardı,karardı ömrüm. Kurşun gibi de...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/omrum-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Sessizliğin Sesi...', 'sessizligin-sesi-abir-zaki-guefn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dikilen yüz döndü güneşe doğru

gözlerim ile, toz dolusu 

kupkuru uzayımın orta yerinde 

bir ses ilişti benim şaşkınlığıma … 

ses, kuyularımdan doğru geldi sessizliğimin 

bu, mevcudiyeti hissetti adımlarımda benim 

hiçbir şey duymadı, hiçbir şey anlamadı 

yüksek bir çoraklık dışında, 

sağır edici sesi sükunetimin … 

onun yankısı, solunmuş benim satırlarımda 

öyle ki, cesaret edebilmiş olmazdım kederlenmeye 

esinti gibi onun meltemi 

sakinliğimin kükreyişleri sessizliği 

ve ben hala hayretler içindeyim 

hayret ediyorum hala ona 

benim sessizliğimin sesini duyarken …

Çeviren:  Akın Akça         1/11/2004

*Sevgili Akin Akçanın benim Tanıtım bölümünden, resme bakarak ve anlatım yazımdan esinlenerek bana ithaf ettiği “A-Bir Cevabı” şiirine “Sound of Silence” ı ithaf etmiştim. Ona ithaf ettiğim şiiri çevirmiş olması beni çok mutlu etti, ve sizlerle paylaşmak istedim.  Sevgiyle daima, Abir

***************************************************************************************

Sound of Silence…* 

standing face turned to the sun 

with my eyes full of dust 

in the middle of my arid space 

a sound reached to my daze… 

the sound came through the wells of my silence 

it felt the presence of my footsteps 

heard nothing, understood nothing 

except the loud dry, 

the deafening sound of my stillness…. 

its echo have breathed through my lines 

that I wouldn’t have dared to distress 

like Zephyr it breezed 

the silence of my roaring quietness 

and I’m still amazed, 

still amazed of him 

“hearing” the sound of my silence…. 

May 10, 2004', 'dikilen yüz döndü güneşe doğru gözlerim ile, toz dolusu  kupkuru uzayımın orta yerinde  bir ses ilişti benim şaşkınlığıma …  ses, kuyularımd...', ARRAY['Türk Edebiyatı','Şiir','Abir Zaki']::text[], 8.5, '{"poet":"Abir Zaki","poet_slug":"abir-zaki","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sessizligin-sesi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cafer Çok Darlandı Bez Mez Getirin', 'cafer-cok-darlandi-bez-mez-getirin-i-smet-barlioglu-j5g0a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gelirler gittikçe kuşa dönüyor,

Cafer çok darlandı bez mez getirin.

O sıcacık yazlar kışa dönüyor,

Cafer çok darlandı bez mez getirin.

Bakkalların burnu artık damlarda,

Elinde kazıkla kasap camlarda,

Fırının önünde aslan ard arda,

Cafer çok darlandı bez mez getirin.

Her neye el atsan elin tutuşur,

Erkeksen ekmeğe para kavuştur,

Katık zannettiğin bir uçan kuştur,

Cafer çok darlandı bez mez getirin.

Gavur olmuş etler, düşman sebzeler,

Sanki günah olur biraz düşseler,

Bari müzelerde seyrettirseler,

Cafer çok darlandı bez mez getirin.

Patates bir rüya, soğan bir serap,

Patlıcan seyretmek en büyük sevap,

Meyvelere bakmak tam bir ızdırap,

Cafer çok darlandı bez mez getirin.

Çorba içebilmek sıkıntılıktır,

Çay may bir başına çarpıntılıktır,

Kahveye el atmak sarkıntılıktır,

Cafer çok darlandı bez mez getirin.

Su içsen binbeşyüz, su döksen beşyüz,

Refah eğer buysa kolay görürüz,

İşeyip durdukça tanır biliriz,

Cafer çok darlandı bez mez getirin.

Su çoktan koyulmuş karton kutuya,

Şimdi sıra geldi artık havaya,

Havayla su bile bir ton paraya,

Cafer çok darlandı bez mez getirin.

(DAT DARA LİLLİM isimli Şiirsel Gülmeceler ''inden > 61-62/100)', 'Gelirler gittikçe kuşa dönüyor, Cafer çok darlandı bez mez getirin. O sıcacık yazlar kışa dönüyor, Cafer çok darlandı bez mez getirin. Bakka...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/cafer-cok-darlandi-bez-mez-getirin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalkıp Yalan Desene', 'kalkip-yalan-desene-i-smet-barlioglu-lf6hc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Serçe fili tavlamış,

Bir tenhada nallamış,

Fil biraz afallamış,

Kalkıp yalan desene.

Eşekler yaylanıyor,

Kuzular paylanıyor,

Aslanlar yalanıyor,

Kalkıp yalan desene.

Balık kavağa çıktı,

Canavarlar acıktı,

Koçlar fazla gecikti,

Kalkıp yalan desene.

Tavuklar oldu sülün,

Kazla ördek tüm elin,

Gelin yağmaya, gelin,

Kalkıp yalan desene.

Belledi atı sinek,

Korkup çekindi inek,

Bizler görek görmeyek,

Kalkıp yalan desene.

(DAT DARA LİLLİM isimli Şiirsel Gülmeceler ''inden > 63-64/100)', 'Serçe fili tavlamış, Bir tenhada nallamış, Fil biraz afallamış, Kalkıp yalan desene. Eşekler yaylanıyor, Kuzular paylanıyor, Aslanlar yalanı...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kalkip-yalan-desene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dam Üstünde Saksağan', 'dam-ustunde-saksagan-i-smet-barlioglu-79wr2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok garip bir dünyada yaşıyoruz nasılsa,

Ne olurdu ters işler az birazcık düz olsa,

Kötüler iyilerden birer birer ayrılsa,

Kim istemez kalkıp da güzel şeyler yazmayı? 

Dam üstünde saksağan, vur beline kazmayı.

Bilettir satılıyor berber dükkanlarında,

Piyangonun işi ne insanın sakalında? 

Milyarı düşünenin saç mı kalır aklında? 

Herkes istiyor oldu servetlerde yüzmeyi,

Dam üstünde saksağan, vur beline kazmayı.

İlaç dışında her şey mevcuddur eczanede,

Oyuncağın her türü vitrini süslemede,

Fotokopi cihazı müşteri beklemede,

Her eczacı satmalı kundurayı, çizmeyi,

Dam üstünde saksağan, vur beline kazmayı.

Su akardı eskiden görkemli pınarlardan

Ve de söz edilmezdi paralardan, pullardan,

Şimdi varsa içilir su karton kutulardan,

Öğrenmeliyiz artık suyu ipe dizmeyi,

Dam üstünde saksağan, vur beline kazmayı.

Kalkıp doktor oluyor şair ruhlu olanlar,

Bakıyorsun yargıçtır cebirden anlayanlar,

Sünnetçi olamaz mı bu gidişle bayanlar? 

Bağlarsa şaşmamalı erkek başa yazmayı,

Dam üstünde saksağan, vur beline kazmayı.

Emekli eski müdür olmuş esnaf pazarda,

O sebze satamaz mı bütün herkes satar da? 

Yanlış düzeltilmez mi her gün göze batar da? 

Durun balık öğretsin bize suda yüzmeyi,

Dam üstünde saksağan, vur beline kazmayı.

Kuyumcunun işini kalkıp aş.ı yapar mı? 

Hak yerini bulursa hiç kıyamet kopar mı? 

Dünyada iyilerden daha üstünü var mı? 

Sarhoş kafa bulunca seyreyle sen sızmayı,

Dam üstünde saksağan, vur beline kazmayı.

(DAT DARA LİLLİM isimli Şiirsel Gülmeceler ''inden > 65-66/100)', 'Çok garip bir dünyada yaşıyoruz nasılsa, Ne olurdu ters işler az birazcık düz olsa, Kötüler iyilerden birer birer ayrılsa, Kim istemez kalkı...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dam-ustunde-saksagan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuyor', 'olmuyor-i-smet-barlioglu-6jasu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ekmek zırh giyinmiş, elinde gürzü,

Unutturdu bize sünneti, farzı,

Peynir uzaklardan göz eden dürzü,

Demesek olmuyor, desek olmuyor.

Zeytin çoktan beri görünmez adam,

Helva hışım gibi kaçtı sofradan,

Reçel rüyamıza girer durmadan,

Sevmesek olmuyor, sevsek olmuyor.

Bal kızgın çöllerde kaybolmuş serap,

Yağın mezarına nur yağdır ya Rab,

Pekmez içimizde kalan ızdırap,

Övmesek olmuyor, övsek olmuyor.

Et büyük savaşta rahmetlik oldu,

Unlar yüz akıyla cennetlik oldu,

Pazara gidenler cinnetlik oldu,

Görmesek olmuyor, görsek olmuyor.

Pastırmaya bakmak dalaksızlıktır,

Salama imrenmek idraksızlıktır,

Sucuğa dokunmak ahlaksızlıktır,

Dövmesek olmuyor, dövsek olmuyor.

Millet fasulyeye uzaktan bakar,

Patlıcan, domates hemen el yakar,

Bamya eve girse mutlak kan çıkar,

Vurmasak olmuyor, vursak olmuyor.

Ispanak şahindir, bezelye kartal,

Patates yiyenden çıkar mı vebal? 

Gücün yetiyorsa git de marul al,

Yermesek olmuyor, yersek olmuyor.

her şeyin fiyatı bindi deveye,

Başladık otları gevelemeye,

Şu geçim derdinden kalbi ikiye

Yarmasak olmuyor, yarsak olmuyor.

(DAT DARA LİLLİM isimli Şiirsel Gülmeceler ''inden > 67-68/100)', 'Ekmek zırh giyinmiş, elinde gürzü, Unutturdu bize sünneti, farzı, Peynir uzaklardan göz eden dürzü, Demesek olmuyor, desek olmuyor. Zeytin ç...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/olmuyor-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Hüznün Gölgesi...', 'huznun-golgesi-naime-erlacin-q1agl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hüznün gölgesini buldum bakışlarında

zeka pırıltılarına sakladığın

karanlık o labirentin içinden 

kanayarak gelmiştin

çıbanlar açmıştı yüreğin sıtmalı gecelere

sıcacıktı sokuluşun analığıma 

alınyazında varsa yaşamak

duvara çarpan kör kuş misali yaşanırdı elbet 

vahşiydi aşk….ayrılık çaresiz

yakışırdı hüzün sana

“hangi aşk mümkündü(r)    aşığı öldürmeden? ”*

sur dibinde özlemlerin 

kıyameti beklerdin

zengindi aşktan artakalan kuyu 

acıdan yana 

örselenmiş kalbinle yürü şimdi 

''nereye kadar''

sorma hiç! 

bırak seninle ağlasınlar

tut yine sen ellerimi

kentlerin yüzü yok

annelerin elleri var

ah çocuk annen olsaydım keşke! 

………….

(*)       Murathan Mungan

(2 Kasım 2004)', 'hüznün gölgesini buldum bakışlarında zeka pırıltılarına sakladığın karanlık o labirentin içinden  kanayarak gelmiştin çıbanlar açmıştı yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/huznun-golgesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ve Şiir', 'ask-ve-siir-naime-erlacin-dhtwi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir tür beyin orgazmı değil mi 

her güzel şiir

dizeden fışkıran lav

sararken bedeni

yıkarken ruhu öylece 

donup kalırız

yok ki firarı şiirin

aşk gibi

yalnızca yanmaktır yazgımız! 

(2 Kasım 2004)', 'bir tür beyin orgazmı değil mi  her güzel şiir dizeden fışkıran lav sararken bedeni yıkarken ruhu öylece  donup kalırız yok ki firarı şiirin...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-ve-siir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolup Gittin Akşamın Karanlığında', 'kaybolup-gittin-aksamin-karanliginda-huseyin-erdogan-9cvpc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yıllar sonra geçen hafta

karlı bir günün akşamında

sana rastlamıştım Moda''da

çok zariftin gene

yakası kürklü kabanınla

sen de beni görecektin son anda

başını çevirmiş olsaydın deniz tarafına

bakakaldım ardından

seslenemedim sana

keşke dönüp bakmış olsaydın arkana

bir defa olsa da

seni seyrettiğimi görmüş olacaktın

hem de hayranlıkla

biraz sonra ne yazık ki biraz sonra

kaybolup gittin akşamın karanlığında

                            Hüseyin Erdoğan', 'yıllar sonra geçen hafta karlı bir günün akşamında sana rastlamıştım Moda''da çok zariftin gene yakası kürklü kabanınla sen de beni görecekti...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kaybolup-gittin-aksamin-karanliginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyeceğim Seni.', 'bekleyecegim-seni-i-nan-alver-12gw1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bekleyeceğim Seni,

Kalbime verdiğin sözlerin,

Gözümde gördüğün düşlerin,

Geleceğimi çizen gözlerinin,

Bir hayal,bir yalan olmadığını göstermen için.

Bekleyeceğim Seni,

Yalnızlığım bittiği yerde,

Sevginin uçsuzluğunda,aşkın bucaksızlığında,

Güneşin doğmadığı uzak şafaklarda,

Umut olup,gün olup doğman için.

Bekleyeceğim Seni,

Kalbime çizdiğin kırmızı sevdanın,

Gecelerime kattığın renkli düşlerin,

Sevda tablomuzun eksik kalan,

Son fırça darbesini vurman için.

Bekleyeceğim Seni,

Tutkuların canlandığı,

Sevginin özgür olduğu büyük aşkını,

Hatıralarda,satırlarda değilde,

Vazgeçilmez bakışlarında bulmak için.', 'Bekleyeceğim Seni, Kalbime verdiğin sözlerin, Gözümde gördüğün düşlerin, Geleceğimi çizen gözlerinin, Bir hayal,bir yalan olmadığını gösterm...', ARRAY['Türk Edebiyatı','Şiir','İnan Alver']::text[], 8.5, '{"poet":"İnan Alver","poet_slug":"i-nan-alver","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bekleyecegim-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öksürük', 'oksuruk-naime-erlacin-q6of5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ben bana 

uzağım ki öyle

beni benimle sınama ey kader! 

aykırı bir ses dinliyorum şimdi

geri dönüşün tamtamları çalıyor 

güneşin rahmine

süngüyü dünden çekti yıldız

yıldızım kayıp

bakmıyorum suyun aynasına 

yol verdim kendime

iyidir ne olsa 

yaşarken buza kesmekten

bilir mi hiç derini 

kıyıda yüzen 

bir öksürük dinliyorum 

kumar oynuyor canım, anlasana! 

birbirine benziyor sus çölleri

aldırma sen 

okka her yerde dört yüz dirhem

son ölümüm olsun bu

öksürüğün koynunda ilk soluklanışım

son seslenişim kendime

sus artık! 

(30 Ekim 2004)', 'ben bana  uzağım ki öyle beni benimle sınama ey kader!  aykırı bir ses dinliyorum şimdi geri dönüşün tamtamları çalıyor  güneşin rahmine sün...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/oksuruk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanıt!', 'yanit-naime-erlacin-cuvqz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'körü körüne dost

körü körüne insan

körü körüne anne olmadım hiç

aslında 

körü körüne emekçisi 

hiçbir şeyin

düşünürüm önce

hak etmek için 

ne yapmalı? 

büyük soru gelir sonra

beni hak ettiler mi? 

ruhsatsız bir koşunun sonunda

yanıt 

olumsuz! 

(31 Ekim 2004)', 'körü körüne dost körü körüne insan körü körüne anne olmadım hiç aslında  körü körüne emekçisi  hiçbir şeyin düşünürüm önce hak etmek için  n...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yanit-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çarem Kalmıyor', 'carem-kalmiyor-murat-demir-qkyco', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seninle sensizlik gider arıma

Derinlerden vurur gönül zarıma

Dünüme baktıkça, yarınlarıma

Ağlamaktan gayri çarem kalmıyor

Ne yapsam önemsiz, ben aşığımya

Gelen giden vurur,halim budurya

Seven yüreğimin patronudurya

Yalvarmaktan gayri çarem kalmıyor

Tutuşupta gezmek nerde el ele

Çırpınan yüreğim muhtaç mecele

Gırgırına bile dese gel hele

Davranmaktan gayri çarem kalmıyor

Gözlerim gözüne  bakamıyorsa

Sevdam sevdasına akamıyorsa

Düştüğü ateşten çıkamıyorsa

Kahrolmaktan gayri çarem kalmıyor

Adım yazılsada liste başına

Başımı vursamda hasret taşına

Sensiz diyarların her karışına

Savrulmaktan gayri çarem kalmıyor', 'Seninle sensizlik gider arıma Derinlerden vurur gönül zarıma Dünüme baktıkça, yarınlarıma Ağlamaktan gayri çarem kalmıyor Ne yapsam önemsiz,...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/carem-kalmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Örtü...', 'ortu-naime-erlacin-s7agb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '- zıddıyla kaimdir her şey -

is kokulu titreyişlere isyandı 

aşkı anlatmak

yadsımak ölüme teslimiyeti

anlaşılmaz bir başkaldırış 

çağlardan akan

bir bebek ağlardı duyardım 

henüz doğmamıştım

sürgülerdim kapıları kendiliğime

ölümü çalardım ebeliğimden

kâbus kahramanı olmayacağım bu kış! 

kuzgunlar inmeyecek omuz başlarıma

meme uçlarında özleyişlerin

tunçtan bir kurs süsleyecek göğü

göz bebeklerimde birikecek ışık

dirilecek aşk 

dizelerin dip köşelerinde 

kızacak Özlü bana 

Pavese somurtacak biliyorum 

üşüteceğim Hades''i

ama böyle susacak “öteki” 

başı önünde ancak 

böyle geri dönecek cehennemine

saçımda saklayacağım gücü

dudağın üşümüşlüğüne can havliyle 

haykıracak içimdeki büyücü

“sevdayı ört üstüme gelinlik gibi

kefenim olsun! ” 

(2 Kasım 2004)', '- zıddıyla kaimdir her şey - is kokulu titreyişlere isyandı  aşkı anlatmak yadsımak ölüme teslimiyeti anlaşılmaz bir başkaldırış  çağlardan ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ortu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Olsun', 'senin-olsun-huseyin-sigirtmac-kk7mr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni benzetirdim aya yıldıza

Bütün ışığıyla al senin olsun.

Seninle rengarenk erdiğim haza.

Kara kuşağıyla al senin olsun.

Yürekte sermayen hasret duygusu.

Beyinde oluşan hayal kurgusu.

Gece gündüz kabus sevda korkusu.

Yorgan döşeğiyle al senin olsun.

Kim gönlünde yarsa bağışla kendin.

Yürekte öfkedir şimdi her rengin.

Sığırtmaç’a lazım değil ahengin.

Gamlı eşiğinle al senin olsun.', 'Seni benzetirdim aya yıldıza Bütün ışığıyla al senin olsun. Seninle rengarenk erdiğim haza. Kara kuşağıyla al senin olsun. Yürekte sermayen ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senin-olsun-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyahımsı Sevda - II -', 'siyahimsi-sevda-ii-gulay-yildiz-vdvov', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzaklaşmak hayallerden 

Tıpkı; 

Geceyi yıldızlarından koparıp aydınlığa vermek gibi 

Sensiz kalan yanlarımı ısıtmak ta bir hayal... 

Bir bebek 

ve 

sütten kesilmiş bir inilti artık adın 

Gitme diye yalvarmak belki çare, 

Ya da beklemek sonsuza kadar aç susuz... 

Gelemeyecek kadar uzaktasın oysa ki... 

________________Adımın yok, ayakların yolsuz 

Kanını akıttığın gözyaşlarına 

Ve sevgine yoldur sevgim 

Ellerim senden kalanlar[da]

Yüreğim minnacık anın[da]

Gidişine sundum tüm acıları, 

Onlar suçlu ki sen masumsun! 

Acını parçalamak ister ellerim, 

Sana kalanlar; benimle bir gün olsun...', 'Uzaklaşmak hayallerden  Tıpkı;  Geceyi yıldızlarından koparıp aydınlığa vermek gibi  Sensiz kalan yanlarımı ısıtmak ta bir hayal...  Bir beb...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/siyahimsi-sevda-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem Taşları', 'sitem-taslari-ahmet-ozdemir-ceyvk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sanırım bir demet gül niyetine,

Sitem taşlarını bana yâr atmış.

Model etmiş ozanların hepsine,

Tanrı şiir diye onu yaratmış.

Bakmayıp saçımın şu aklarına,

Serdim yüreğimi ayaklarına,

Dokundum gül diye yapraklarına,

Gönlüme dikeni batmış kanatmış.

Mahzun bakışına kapıldım diye,

Sevgi yarışına atıldım diye,

Yaman cezbesine tutuldum diye; 

Tutsak sanmış, zindanına kapatmış.

Canların cananı bulduğu yerde,

Özlem çilesinin dolduğu yerde,

Yalnız kendisinin olduğu yerde,

Solsun bütün güller, demiş dayatmış.

Gülistandan kokuş, dilde heves o,

Dudakta dokunuş, kulakta ses o,

Bir kaçamak bakış, canda nefes o,

Duygularımı dört yandan kuşatmış

(Sitem Taşları Kitabından -Avcıol Yayınevi)', 'Sanırım bir demet gül niyetine, Sitem taşlarını bana yâr atmış. Model etmiş ozanların hepsine, Tanrı şiir diye onu yaratmış. Bakmayıp saçımı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özdemir']::text[], 8.5, '{"poet":"Ahmet Özdemir","poet_slug":"ahmet-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sitem-taslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollarını Gözlerim', 'yollarini-gozlerim-i-brahim-ethem-bingul-txocq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sarıdan maviye, aktan karaya

Kırmızıdan alevlenen manaya

Sevdiğim, bakışın aşkıma maya

Ufuklara doğru bakar gözlerim

Bekliyorum, yollarını gözlerim...

Her baharda yeşillenir topraklar

Her sevdada yenilenir yâr, canlar

Sen olmazsan neye yarar saraylar

Yerde gökte seni arar gözlerim

Koş gel bana, yollarını gözlerim...

www.iebingul.com', 'Sarıdan maviye, aktan karaya Kırmızıdan alevlenen manaya Sevdiğim, bakışın aşkıma maya Ufuklara doğru bakar gözlerim Bekliyorum, yollarını g...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yollarini-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim', 'sevdigim-ahmet-ozdemir-wc9ab', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu dağlar, bu bağlar şiir kokarlar,

Esin kaynakları boldur sevdiğim.

Her bir yandan mısra mısra akarlar,

Bahtını buradan doldur sevdiğim.

	

Bir serenattır şu bülbülün sesi,

Dalına konmaktır bütün hevesi.

Sevenin sevene işmar vermesi,

Gelenek, görenek, yoldur sevdiğim.

Sevgiye ilgisiz kalan sen misin? 

Alev alev yürek yakan sen misin? 

Şiir ikliminde sultan sen misin? 

İnsaf et, yaktığın kuldur sevdiğim.

Sana arzu dolu bütün dilekler,

Kelebekler, uğur saçan böcekler,

Sana özenmiş de açmış çiçekler; 

İster güldür, ister soldur sevdiğim.

Aç gönül kapını, sen de sev, sevil,

Sevda bahçesine es efil efil; 

Kavuşamazsa bir aşık bunu bil; 

Ahı zarf, gözyaşı puldur sevdiğim. 

(Sitem Taşları Kitabından- Avcıol Yayınevi)', 'Bu dağlar, bu bağlar şiir kokarlar, Esin kaynakları boldur sevdiğim. Her bir yandan mısra mısra akarlar, Bahtını buradan doldur sevdiğim. 	 ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özdemir']::text[], 8.5, '{"poet":"Ahmet Özdemir","poet_slug":"ahmet-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevdigim-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-aygul-ece-u0je8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bulmadan yitirmek

Görmeden kaybetmek..

Bu olsa gerek..

Bu nasıl bir yazgı

Nasıl bir alınyazısı

Ben mi? 

……..sana geç kaldım. 

Sen mi? 

……..bana uzaktın.

Böyle miydi hayat,

Bir ömür daha mı yaşamalıydım,

Seni tanımak için,

Ben seni tanımaya çalışırken,

Sen kırmızı kartlarını göstermiştin bile..', 'Bulmadan yitirmek Görmeden kaybetmek.. Bu olsa gerek.. Bu nasıl bir yazgı Nasıl bir alınyazısı Ben mi?  ……..sana geç kaldım.  Sen mi?  ……..b...', ARRAY['Türk Edebiyatı','Şiir','Aygül Ece']::text[], 8.5, '{"poet":"Aygül Ece","poet_slug":"aygul-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hayat-165-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '- - A k r e p...v e...Y e l k o v a n....(11)', 'a-k-r-e-p-v-e-y-e-l-k-o-v-a-n-11-metin-eser-fkpva', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saatler geçti gitti, hayallere daldılar,

Aşkın has bahçesine, nasıl hayran kaldılar, 

Ne kahvaltı yapıldı, ne ''acıktık'' dediler,

Aslında her nefeste, aşk meyvesi yediler.

Hâl bu minvâl üzreydi, sessizlik demlenmişti,

Hissiyatın bir kısmı, şimdilik gemlenmişti,

Romantizm zirvesine, birkaç adım kalındı,

Beklenmedik bir anda, evin zili çalındı. 

Yaşanan telaşeyle, bedenler dirileşti, 

Gözlere korku girdi, bakışlar irileşti,

''Ne yapalım'' der gibi, sanki dona kaldılar,

Daha az öncesiydi, dudaklarda baldılar.

İlk önce kadın kalkıp, ''hadi çabuk ol'' dedi,

''Yatak odasına gir, ortadan kaybol'' dedi,

Adam hızla doğruldu, söylenen yere koştu,

Ve saklandığı oda, yeterince de loştu.

Girdi hemen dolaba, en dip köşeye çöktü,

Görmedi karanlıkta, birşeyi kırıp döktü,

Ve sessizce büzülüp, tutmuştu nefesini,

Dengeye getirmişti, düşünce kefesini.

Aynı anda kadın da, koştu önce aynaya,

Düzeltti üst başını, biraz güle oynaya,

Moralsiz olmaktansa, neşeli durmalıydı,

Hayalinde çok güzel birşeyler kurmalıydı.

''Tamam'' dedi sevinçle, telefon elindeydi,

Aklına gelen fikir, gerçekten zekiceydi,

Dostlarından ikisi, geçen haftaydı herhal,

Yeni evlenmişlerdi, aramalıydı derhal.

Ve bir yandan kapıya hızla yöneldi kadın,

''Geliyorum bekleyin, hem söyle nedir adın'',

Telefonu elinde, dostunu arıyordu,

İçinde de bir merak, aklını sarıyordu.

Telefondaki sesten, ''Alo buyrun'' duyunca,

Sonra başladı rolü, oynamaya suyunca,

Önce baktı kapının, dürbünlü pencereden,

Varsaydı ki kurtuldu, sıkıntı cendereden.

Yüzüne bir tebessüm, halini de takınca,

Şüpheli hal görmedi, aynaya da bakınca,

Ve zil tekrar çalındı, ısrarlı bir biçimde,

Kadın kapıyı açtı, tavırlı bir biçimde.

''Geldim işte n''oluyor, patladınız sanırım''

''Sabır da görmüyorum, çatladınız sanırım''

Telefondaki dosta, ''seni tekrar arayım'',

''İki kişi kapımda, dur bir hesap sorayım''.



25.Haziran / Los Angeles

*** ''Akrep ve Yelkovan'' Şiir Roman 12. bölümüyle 3.Kasım.Çarşamba günü devam edecek.

*** ''Akrep ve Yelkovan'' ın okuyamadığınız ilk bölümleri ve daha fazlası aşağıdaki link ile ulaşabileceğiniz Akrep ve Yelkovan grubunda.

Akrep ve Yelkovan Grubu>>>', 'Saatler geçti gitti, hayallere daldılar, Aşkın has bahçesine, nasıl hayran kaldılar,  Ne kahvaltı yapıldı, ne ''acıktık'' dediler, Aslında her...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/a-k-r-e-p-v-e-y-e-l-k-o-v-a-n-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıraç Topraklarda Bile', 'kirac-topraklarda-bile-huseyin-erdogan-kqgyy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'senin olduğun yerdeki

kıraç topraklarda bile

açelyalar begonyalar açar

renk renk

kauçuklar günden güne

yemyeşil uzar gider göklere

aradığın her renk

güller de yerini alır bu bahçede

senin sevginle sulanır

bütün ağaçlar,çiçekler bu alemde

bir gün bile dayanamazlar yokluğuna

hepsi birden isyan ederler sensizliğe

hele hastalığını duyan kuşlar bile

ağlar dururlar sessizce

bir tıkırtı duyarsan çevir başını

istersen bak pencerene

kırlangıçların hıçkırıklarını

sen de hissedeceksin yüreğinde...

                          Hüseyin Erdoğan', 'senin olduğun yerdeki kıraç topraklarda bile açelyalar begonyalar açar renk renk kauçuklar günden güne yemyeşil uzar gider göklere aradığın ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kirac-topraklarda-bile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece', 'sadece-meral-yagcioglu-n6fa6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayal denizindeyim

Yine ben bu gece

Ne bir resmin var

Nede mektubun var elimde

Beyaz güvercinin  getirdiği

Uzanıp yatağıma öpe koklaya

Okumak isterdim

Sayfalar arasında

Sönerdi hasret ateşim

Doyasıya bakmak isterdim 

Siyah beyaz resmine

Ama hayır yapamam

Kirpiklerim birbirine kavuştuğunda

Anılarımın çizdiği

Yedi kat perde arkasından

Seyrettiğim 

Soluk hayalin var

Sadece 

01/11/2004

samanyolu grubunun 2k+1ş aktivitesi için yazılmıştır', 'Hayal denizindeyim Yine ben bu gece Ne bir resmin var Nede mektubun var elimde Beyaz güvercinin  getirdiği Uzanıp yatağıma öpe koklaya Okuma...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sadece-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-ahmet-ozdemir-cq2dn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir tatlı burukluk biraz da umut,

“Eyvah”la, nostalji arasındayım.

Gün be gün çevreyi sarmakta sükût,

Ekim sonlarının Lara’sındayım.

Çatıya tırmanan pembe begonvil,

Bırakmış kendini hoyrat rüzgâra.

Bunlar elvan elvan çiçekler değil,

Hazan yaprakları düşmüş parklara.

Baygın kokusuyla veda etmekte,

Hanımeli, şebboy, ıtır, yaseminler.

Kuşlar da yuvadan artık gitmekte

Sararıp solmakta yeşil zeminler.

Kuşkusuz uyanır bir başka bahar,

Yine börtü böcek, rengarenk çiçek; 

Şimdi içimizi korkular sarar; 

“Gidip de gelmemek, gelip görmemek”', 'Bir tatlı burukluk biraz da umut, “Eyvah”la, nostalji arasındayım. Gün be gün çevreyi sarmakta sükût, Ekim sonlarının Lara’sındayım. Çatıya ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özdemir']::text[], 8.5, '{"poet":"Ahmet Özdemir","poet_slug":"ahmet-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/veda-119-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılsın Ellerim', 'kirilsin-ellerim-huseyin-erdogan-o2q3z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen gönlümde yeşeren baharımsın

yüreğimde hiç sönmeyen narımsın

ben seni bekleyen çorak toprağım

bil ki sen de benim yağmurlarımsın

bir sabah geliver güneş doğmadan

sarılıver bana ömrüm dolmadan

kırılsın ellerim eli tutarsam

kapansın gözlerim ele bakarsam

arada bir olsa da gel yanıma

inan dayanamam sensiz kalırsam

bir sabah geliver güneş doğmadan

sarılıver bana ömrüm dolmadan

                       Hüseyin Erdoğan', 'sen gönlümde yeşeren baharımsın yüreğimde hiç sönmeyen narımsın ben seni bekleyen çorak toprağım bil ki sen de benim yağmurlarımsın bir saba...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kirilsin-ellerim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerime Bakıpta Ağlarmısın', 'gozlerime-bakipta-aglarmisin-galip-sinecikli-q9kmf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'duvarımda asılı duran

takvimin yaprakları da sararmış

tıpkı aylarını gösterdiği

hazan mevsimi gibi

sen yine gelmedin

yağan yağmurlar değil de

beni sensizlik üşütüyor

erguvanlar 

papatyalar kalmadı artık

soldular hepsi birer birer

hadi bana acımadın

bari onlar için gelseydin

gözlerin gözlerimden

daha da uzaklaşıyor gitgide

acaba

şimdi görsen hatırlar mısın? 

sana sorsalar

‘’bu gözler kimin? ’’ deseler,

hatırlar mısın? 

gözlerime bakıp ağlar mısın? 

dün gece

saat yokluğunu kırkbeş geçe

kalbim de seni sordu bana

cevap veremedim

oysa kolay bir soruydu

gücüme gitti cevap verememek

kalbime karşı suskun kalmak

aslında cevap verirdim

keşke

umutlarımı alıp götürmeseydin...', 'duvarımda asılı duran takvimin yaprakları da sararmış tıpkı aylarını gösterdiği hazan mevsimi gibi sen yine gelmedin yağan yağmurlar değil d...', ARRAY['Türk Edebiyatı','Şiir','Galip Sinecikli']::text[], 8.5, '{"poet":"Galip Sinecikli","poet_slug":"galip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gozlerime-bakipta-aglarmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olmayınca', 'sen-olmayinca-huseyin-erdogan-u4khp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yağmurlu bir gecenin sabahında

umudum yok güneş gene doğmayacak

geceleri ay da çıkmıyor artık

yıldızlar da kayboldu birer birer

beni terk edişinle birlikte

mevsimsiz göç eden martılar görüyorum

intihar komandoları gibi

sürüler halinde Akdeniz''e

biliyorum

onlar da dönmeyecek bir daha geriye

ölümümü görmesinler diye

artık çiçekler bile

güzel kokmuyor yokluğunda

demiştim ya

hiçbir şeyin tadı yok sen olmayınca

                            Hüseyin Erdoğan', 'yağmurlu bir gecenin sabahında umudum yok güneş gene doğmayacak geceleri ay da çıkmıyor artık yıldızlar da kayboldu birer birer beni terk ed...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-olmayinca-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-erkan-yanar-e39p3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat yüzümüze gülmekte

Ama hep sırtımızdan vurmakta

Kapımıza dayanmışsa hasret çekmek

Gözlerimizi zorluyorsa ağlamaklı yüreğimiz

Çare yok

Ağlayarak çekeceğiz hasreti

Beklenen gün için, yar için, hayat için,

Yaşam için, kavgamız için

Açacağız kapıyı hasrete

Bağrımıza basacağız

Kokusunu duymasak da 

Ellerini tutmasak da yarin

Çare yok...

Sevgimizi aşkımızı satırlara döküp mektuplaştıracağız

Ve serpiştirip üzerine göz yaşlarımızı

Yâre ulaştıracağız

Hayat yüzümüze gülüp sırtımızdan vursa da

Hasret çekmeyi alnımıza kazısa da tanrı

Biz hep seveceğiz

Ve hayata inat

Hep savaşacağız', 'Hayat yüzümüze gülmekte Ama hep sırtımızdan vurmakta Kapımıza dayanmışsa hasret çekmek Gözlerimizi zorluyorsa ağlamaklı yüreğimiz Çare yok A...', ARRAY['Türk Edebiyatı','Şiir','Erkan Yanar']::text[], 8.5, '{"poet":"Erkan Yanar","poet_slug":"erkan-yanar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hasret-198-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Demirden gemi**', 'demirden-gemi-kubilay-enginol-89e2m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Taşlara sıkı bas,al hıncını

Göğe bak,sonsuz maviliğe

Kavuşacaksın bir gün yitirme inancını

Martılara,vapurlara,denize,yani özgürlüğe

Kuşlara özenme,uçamazsın

Kanadın kırık,yaralısın

Yoksay onları,demirleri görme

Saksı farzet,çiçek farzet pencerende

Taşlara sıkı bas al hıncını

Yanındakine yüzünü dön,gösterme sırtını

Uyanık ol sessiz gecede bile

Geceler gebedir daima süprizlere

Demirlere vuruyor sabah güneşi

Kahrediyor güneşin,demiri kesemeyişi

Birbirine karışırken sesler,düdükler

Sayıma çıkıyor,yılgın hükümlüler', 'Taşlara sıkı bas,al hıncını Göğe bak,sonsuz maviliğe Kavuşacaksın bir gün yitirme inancını Martılara,vapurlara,denize,yani özgürlüğe Kuşlara...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/demirden-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
