INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarılsan Bile Senelerce Bana', 'sarilsan-bile-senelerce-bana-huseyin-erdogan-1cigq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'esiyor sahilde hoyrat rüzgarlar

inan ki kalbimde sıcaklığın var

deniz mevsiminde yağsa da karlar

erir nefesinde o yüksek dağlar

hasretinden yangın çıktı gönlümde

yüreğimi alev sardı bir günde

bil ki bitmeyecek özlemim sana

sarılsan bile senelerce bana

rıhtıma sessizce vurun dalgalar

ne olur kaval çalmayın çobanlar

benim sevdiğimde derin uyku var

hiç uyandırmayın akşama kadar', 'esiyor sahilde hoyrat rüzgarlar inan ki kalbimde sıcaklığın var deniz mevsiminde yağsa da karlar erir nefesinde o yüksek dağlar hasretinden ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sarilsan-bile-senelerce-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur Dönüp Gel', 'ne-olur-donup-gel-huseyin-erdogan-5q2jw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'geçmiyor sevdiğim geçmiyor zaman

sensiz hiçbir şeyin tadı yok inan

açtım kollarımı beklerim her an

ne olur dönüp gel akşam olmadan

İstanbul''a erken geldi son bahar

kalmadı dallarda yeşil yapraklar

durmadan esiyor sahilde rüzgar

sen yoksun diyerek ağlar kayalar

artık sensiz kaldı bütün vapurlar

vuruyor kalbime senli dalgalar

gözlerimde yaşlar yüreğim sızlar

sel oldu akıyor şimdi damlalar

Beste:Mustafa Malay

Makam:Süznak', 'geçmiyor sevdiğim geçmiyor zaman sensiz hiçbir şeyin tadı yok inan açtım kollarımı beklerim her an ne olur dönüp gel akşam olmadan İstanbul''...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ne-olur-donup-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak', 'unutmak-hakan-timur-a99bf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seni unutmak için 

eşyaları çöpe attım

çillerinin göründüğü

son resminide yırttım

kokun sinmiş yastığa

defalarca yıkadım....

sevdiğin şarkıları dinlemiyorum şimdi

mantarlı yumurta yapmıyorum

uzun oturmuyorum evde

ayaklarımı uzatmıyorum pufa

taze nane yemiyorum

mutfağa pek girmiyorum

fazla gülmüyorum

hiç ağlamıyorum

içime atıyorum ne varsa

sessiz çığlıklarımla öldürüyorum içimdekileri...

eğer seni öldürseydim

seni içimde öldürdüğüm kadar zorlanmazdım..

041104', 'seni unutmak için  eşyaları çöpe attım çillerinin göründüğü son resminide yırttım kokun sinmiş yastığa defalarca yıkadım.... sevdiğin şarkıl...', ARRAY['Türk Edebiyatı','Şiir','Hakan Timur']::text[], 8.5, '{"poet":"Hakan Timur","poet_slug":"hakan-timur","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/unutmak-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öksüz Kaldı Liman', 'oksuz-kaldi-liman-huseyin-erdogan-bgrks', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen gittiğin gece soldu çiçekler

ağlatıyor beni sensiz geceler

gönlüm isyan eder hep seni bekler

ne olur geri dön ağladığım yeter

vurmuyor dalgalar esmiyor rüzgar

sen yoksun diyerek inler kayalar

artık yanaşmıyor senli vapurlar

öksüz kaldı liman batsın sandallar

yıldızlar çıkmasın sabah olmasın

istemem sen yoksan güneş doğmasın

ırmaklar yerine göz yaşım akmasın

yaşayamam inan dönmezsen eğer', 'sen gittiğin gece soldu çiçekler ağlatıyor beni sensiz geceler gönlüm isyan eder hep seni bekler ne olur geri dön ağladığım yeter vurmuyor d...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/oksuz-kaldi-liman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yaprak', 'bir-yaprak-necat-necdet-demircan-7hevn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sizler de biliyorsunuz ki; bizler hep aynı sebeplerden dolayı ayrıldık! 

Öyle ki; sevginin yükünü taşıyamayacak kadar tembel, bencilliğimize ''aşık'' olabilecek kadar da aptaldık! 

Ne bir başlangıç var bu koskoca olduğu söylenen evrende

Ne de bir bitiş bu anlamsız karabasanlarla süslü bikes gecelerde

Ve umutsuzluk kucaklamış bütün koltukları çepeçevre

Rüyalar son oyununu sahnelemiş, küf kokan kimsesiz belleklerde

Kesin Hüküm ve hapsedilmiş yüreği, son çırpınışları daracık bir kafeste

Geçmiş seyredildiği kadar kalmış, farkında olunmayan sımsıcak güneşlerde

Kapalı gözleri, bükük boynu, akıl biçare yaşanmamışlıklarda 

Saatlerin sesi yok, saniyeler rötar yapmış, dakikalar anlamsız bir grevde

Gözyaşları çorak bir dere yatağı bırakmış, suyunu çekmiş pınarlar

Gece soğuğunun hükmüdür, ateşler yanar, kor olur yanaklar

Bir uğultu karışır ve bilmem kaç şiddetinde deprem olur ansızın

Sözler yankılanır, küskün seslerin hatırasıyla derdest edilir kulaklar

Çiylerin içinden gelen yorgun sesli  bir kuş konar

Bilinmeyen bir el mecalsiz tüylerini sevgiyle okşar

Son çırpınışını gören olmaz, hissedilmez parmaklar

Gözleri kapanır ve o ince iplik kopar…

Bir yaprak düşer ansızın hazin kokan mevsimin içine, 

sarı, kızıla çalan, son bir yaprak Çınar Ağacından

Aşağılarda bir yer bulur kendine ve alır gider bütün meserretleri 

Yorgun dallar selamlayamaz gökyüzünü

Bulutların arkasına saklanır yıldızlar

Ne göz kırpan kalır

Ne sihirli gülümsemeler

Ne cıvıltılı sesler

‘Gitme’ ‘Dur’ demez hiç kimse

Keder acı bir rüzgar olur eser uzaklardan nuhuset ile

BİTTİ yazar perdede

Zindan kapıları esir alır

Ve nihayete erer sonsuzluk, 

Söndürür kainat ışıklarını aheste

Kırıntıları bile kalmaz sevgilerin, 

Uçup gider uzaklara, kanatsız,  küçücük bir nefeste…', 'Sizler de biliyorsunuz ki; bizler hep aynı sebeplerden dolayı ayrıldık!  Öyle ki; sevginin yükünü taşıyamayacak kadar tembel, bencilliğimize...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bir-yaprak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Şiiri Bunlar...', 'aksam-siiri-bunlar-abdullah-atay-vgsxz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gelin dostlar gelin 

akşam şiiri bunlar... 

sıcak sıcak 

yürek yürek 

buram buram sevgi 

aşk hasret kokuyor. 

el işi gönül işi 

kalem işi bunlar... 

sözcükleri nakış nakış işli 

mısraları motif motif süslü 

hasretlerde dile gelmiş şiirlerim var... 

mayası sevgi 

suyu gözyaşı 

aşk ateşinde pişmiş 

gönül potasından taşmış

sevgi deryası bunlar

sevdalılar bunu  anlar...

anana babana 

bacına balana 

eşine dostuna 

okula giden yavruna 

yavukluna daha nice hediyelerim var. 

her derde deva 

şiir mani rubailerim var.

geçim derdini unutturur 

aşk rüyasında uyutturur 

gurbete düşmüş sevgilinin

hasretliğini avutturur.

daha neler var daha 

sevgiyi bilenlere bedava! .. 

manilere de buyrun; 

şapkası var hasırdan 

yeni gelmiş mısır’dan 

sevgisiz taş kalpli o 

kalbindeki nasırdan... 

yar peçeni aç da gel 

al bohçanı kaç da gel 

yoluna güller döktüm 

gece saat üçde gel... 

tabağımda üzüm yok 

el kızında gözüm yok 

yarim bana darıldı 

barışmaya yüzüm yok...

hadi yanaş abim,ablam

söz söz,dize dize dolu tablam...

değirmenin arkı yok 

hem arkı hem çarkı yok 

şu hercai gönlümün 

kelebekten farkı yok... 

yarim seni sorarım 

esen seher yeline 

şu gönlümü bağlarım 

saçının her teline... 

gergef bezeten güzel 

gönlüm azıtan güzel 

iğnesinin gözünden 

beni gözeten güzel... 

gerdanı allı güzel 

mor donu güllü güzel 

döne döne oynuyor 

her yanı zilli güzel...

hicranlı sevdalardır yürek yakan

gönül  kasırgasından sizlere 

sevgi esintileri getirdim

bahar kokan...

sevgiliye sitem şiirlerim var! .. 

ben allı morlu güller döktüm yollarına 

sense harlı korlu küller döktün kollarıma... 

yakmayın siz ağıtı

dinleyin şu beyiti:

fala bakmaz istersen, iç telveli kahveyi 

dile düşmek istersen, seç cilveli kahpeyi.. 

sevda şiirlerime de bir bakın. 

kınan oldum parmağına yakıldım. 

güzeller içinde sana takıldım 

al gül olup bağlarına dikildim. 

sulayıp koklayıp sevmen mi dilber? 

dağları delerdim tek bir sözünle 

yaşamdan bezdirdin bin bir nazınla. 

yalanın,riyanla,sahte yüzünle 

hicran ateşini sen yakıyorsun. 

sevdiğim bakınca sevda gözüyle 

dalımda açıyor gülüm yaprağım 

dilinden dökülen veda sözüyle 

serpilir üstüme ölüm toprağım... 

gönül deryasından sevgiler damla damla

dolmasın gönlünüz hicranla gamla...

gelinlere de söylenecek sözlerım var:

gergef işleyen gelin 

yari düşleyen gelin 

şu garip yüreğime 

sevda düşüren gelin... 

pınara geldi gelin 

el ettim güldü gelin 

yari beklediğimi 

nasıl da bildi gelin.... 

badeleri iç gelin 

gerdanını aç gelin 

bağımdaki gülümsün 

kokuları saç gelin... 

sevdaya düştü gelin 

dağları aştı gelin 

ne karaymış yazısı 

kötüye düştü gelin... 

bağıma geldi gelin 

gül verdim aldı gelin 

meramı gül değilmiş 

benimle kaldı gelin... 

delikanlılar var sırada

bu arada:

sevdiğine kul oğlan 

çiçeğine dal oğlan 

dağlar geçit vermiyor 

gece bizde kal oğlan... 

bahçası gülsüz oğlan 

parasız pulsuz oğlan 

yarini alamamış 

üst başı çulsuz oğlan... 

dağlarda seken oğlan 

hasretlik çeken oğlan 

gördüğü kurda kuşa 

derdini döken oğlan... 

saçın uzatan oğlan 

bıyık kazıtan oğlan 

saçına boncuk dizip 

işi azıtan oğlan... 

uzaktan bakma teyzecim,amcacığım...

yaşınız ne olursa olsun sizin içinde dörtlüklerim var:

yar saçını taratmış 

mevlam neler yaratmış 

gönül ferman dinlemez 

yaşın olsa da altmış... 

yare bal kaymak gitmiş 

o da yarime yetmiş 

gönüller kocamıyor 

yaşlar olsa da yetmiş... 

yıllar çabuk geçerken 

gül yaprağın dökerken 

hayat yine güzeldir 

yaşın olsa da seksen... 

gönül gözüyle baksan 

kalpten kalbe aksan 

kış kapıya gelirmiş 

yaşlar olunca doksan... 

aşığız biz gül yüze 

bal damlayan her söze 

‘sessiz gemi’ kalkacak 

yaşlar gelince yüze... 

askere gidecek kınalı yiğitlerimi  hiç unutmadım.

alın da astınızı,üstünüzü dostunuzu sevindirin:

davulla zurnayla göreve gider 

ana baba eş dost bayramın eder 

kışlaya varınca dağılır keder 

askerlik andını içer Mehmetçik. 

vatanı için silah alır eline 

yiğitlik türküsü dolar gönlüne 

yurduna göz diken hain zalime 

namludan kurşunu saçar Mehmetçik. 

kimi topçu tankçı kimi piyade 

vatanın sevdası yardan ziyade 

en ileri safı tutar cephede 

çiğneyip düşmanı geçer Mehmetçik. 

dinleyin beni

bakın şu dörtlüklerime bir de

seveceksiniz mutlaka:

gurbet elde olunca 

zulüme ne gerek var 

yardan ayrı kalınca 

ölüme ne gerek var… 

can kuşun nefesiyle 

dirildi bu bedenler 

şimdi selâ sesiyle 

dönmüyor bu gidenler… 

kişi darda kalınca 

yakınları el olur 

aşkı yarda bulunca 

dikenleri gül olur... 

eğleşir tanrı kulu 

‘iki kapılı handa’ 

insanlığın yolu 

barıştır bu cihanda...

kefesi sevgi dolu 

gönüller bir terazi 

her insan tanrı kulu 

tartma kinle garezi… 

gönül denilen kantar 

nice sevgiler tartar 

cömert ol sen sevgide 

sevgi verdikçe artar… 

bu gök bu deniz bu yer 

yaşamda bir sahneymiş 

kürkler kostümler meğer 

bu dünyada sahteymiş…

öğretmen ve öğrenci için söylemlerim var:

barışta güvercin savaşta şahin 

geçit vermez dağda yoldur öğretmen… 

gazimin diktiği ulu çınarda 

yaprağa çiçeğe daldır öğretmen… 

yunus Veysel gibi çalıp söyleyen 

aşığın sazına teldir öğretmen… 

kardeşliğe yürüyün 

sevgi ile büyüyün 

bu günümüzü veren 

atamızla öğünün... 

senin asil kanın var 

şöhretin var şanın var 

dünyada hiç olmayan 

tek çocuk bayramın var...

büyük kurtarıcımız Gazi Mustafa Kemâl Atatürk için ne dense azdır:

sayesinde yükseldi minareden ezanlar 

laikliği bilenler Ata''mı iyi anlar... 

mavi gözü dalgalı derin okyanus gibi… 

O barışa sevdalı Mevlâna Yunus gibi 

namerde aman vermez Ata’mı sen de tanı 

dişiyle tırnağıyla kurtardı bu vatanı… 

bu vatanın uğruna döküldü nice kanlar 

ata''mın değerini yurdunu seven anlar... 

şehit kanıyla dolu her karışı bu yurdun 

düşmana geçit vermez destanlar yazan ordum. 

verdiği ilimlerle karanlığı boğarız 

Ata''mızın izinde bir ölür, bin doğarız…



daha bitmedi gönlü sevgi dolu

yolu Atatürk yolu

dostlarım daha bitmedi

yarin yine beklerim..

abdullah atay diyor ki; 

kalbimde yeriniz var 

dostluğunuz bana kar 

yarın yine beklerim 

bu günlük de bu kadar... 

açma herkese derdini 

sırrını kendine sakla 

dostlar kalın sağlıcakla... 

 Not.Bir simitçi çocuktan esinlenerek yazmağa çalıştığım  şiirimdi.', 'gelin dostlar gelin  akşam şiiri bunlar...  sıcak sıcak  yürek yürek  buram buram sevgi  aşk hasret kokuyor.  el işi gönül işi  kalem işi bu...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":234,"source_url":"https://www.antoloji.com/aksam-siiri-bunlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vay Be', 'vay-be-murat-demir-bxbfa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdayamı düştün canım

Alev alev yanıyorsun

Eğilmeyen dik başını

Bak nasıl da eğiyorsun

Beklede gör bu nedir ki

Daha neler göreceksin

Ben sevdayı bilir isem

Başını çok eğeceksin

Yarım kalmış mısra gibi

Sende yarım kalacaksın

Ah çektiğin her nefeste

Acılarla dolacaksın

Bir gözünden yaş geldikçe

Diğeriyle bakacaksın

Görmedikçe yüreğini

Ateşinle yakacaksın

Dolaştığın sokakları

Yorgan döşek sanacaksın

Feryat dolu gecelerin

Ayazında kalacaksın

Seni duyan eski dostlar

Belki gelip görecekler

Yakın değil uzağından

Vay be deyip dönecekler', 'Sevdayamı düştün canım Alev alev yanıyorsun Eğilmeyen dik başını Bak nasıl da eğiyorsun Beklede gör bu nedir ki Daha neler göreceksin Ben se...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/vay-be-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şafak Vakti', 'safak-vakti-gullu-alemdar-i5m3m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaman beni olgunlaştıracak

Ve ben başka birilerini seveceğim.

Böylesi çektiklerime bir gün,

Tebessüm edeceğim

Neyse ki boşa geçmemiş

Sayacağım senli yılları

Aşkı bana veren yaradan 

Daha güzelini de verecek 

Elbet! 

Bir gün,bu derin ızdırap

Yerini daha güzel bir sevgiye 

Devredecek! 

Ve sen işte; o gün

Gönlümde son yolculuğuna 

Çıkmış olacaksın

Bir sabah uyanınca,ezan vakti

Benim gibi...

Beni kaybettiğini anlayacaksın

İşte bu pişmanlık,

Seni hiç terk etmeyecek

Anlayacaksın bir şafak vakti

Seni ne kadar sevdiğimi

(Gülnida)', 'Zaman beni olgunlaştıracak Ve ben başka birilerini seveceğim. Böylesi çektiklerime bir gün, Tebessüm edeceğim Neyse ki boşa geçmemiş Sayacağ...', ARRAY['Türk Edebiyatı','Şiir','Güllü Alemdar']::text[], 8.5, '{"poet":"Güllü Alemdar","poet_slug":"gullu-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/safak-vakti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müjde', 'mujde-bayram-tunca-1v2nt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duygu Harmanı adında bir balam oldu

Hamileliği ve doğumu oldukça zor oldu

Ama, doğuşuyla beni mutluluğa boğdu

Onu ahbaplar da dört gözle bekliyordu

Bugünleri Bayram çelik halatla çekiyordu

İçindeki sevgi tohumlarını çil çil ekiyordu

Boy vermesi için gözyaşlarıyla suluyordu

Çünkü, ondan çok hayırlı işler umuyordu

İnşallah vatana/millete hayırlı bir evlat olur

Her kim ne ararsa, ondan derdine ilâç bulur

Dostlarının mutluluğu da şairi neşeye boğar

Güneş bundan böyle, bir başka güzel doğar

Ademoğlu, balasını nasıl bulduğunuzu sorar

Nasıl bulduğunuzuysa, yorumunuzdan anlar

Dün olduğu gibi bu gün de desteğinizi umar

Güzelliklerin paylaşımı kulları sevinçe boğar

01.11.2004-11.01

NOT:1

Kitap 1. hamur kitap kağıdına basılmış,

13,5x21 Ebadında, Toplam 256 sayfalı,

275 değişik konularda şiir içermektedir.

Etiket Fiyatı: kdv dahil sekiz milyon TL.', 'Duygu Harmanı adında bir balam oldu Hamileliği ve doğumu oldukça zor oldu Ama, doğuşuyla beni mutluluğa boğdu Onu ahbaplar da dört gözle bek...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mujde-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İrem''in Günlüğü / Bizim İçin', 'i-rem-in-gunlugu-bizim-i-cin-tulay-sustam-klj8y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seni SEVİYORUM...

sen küçüksün, sevgim büyük

BENİ hiç sevme...

ben büyüğüm, sevgin küçük

.

.

.

seni seviyorum

SENİ SEVİYORUM', 'seni SEVİYORUM... sen küçüksün, sevgim büyük BENİ hiç sevme... ben büyüğüm, sevgin küçük . . . seni seviyorum SENİ SEVİYORUM...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/irem-in-gunlugu-bizim-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmir’i gördün mü?', 'i-zmir-i-gordun-mu-oguz-altun-oopev', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İzmir’i gördün mü? 

Saat Kulesini, Asansörü,

Fuarı demiyorum

gördün mü izmir’i? 

yapışmaz nemi

yaz günü ve gecesinde

püfür püfür 

esen yelle

yürürken kordon boyunda.

İzmir’i gördün mü? 

Alsancak, Kemeraltı,

Karşıyaka’yı demiyorum

sahi gördün mü İzmir’i? 

eser yoktur

oğlanında kızında

memurunda esnafında

stresten, kederden

ve de kem gözden

acıdan bağrı yansa da

olmasa da yemek öğününde

gülümser gamzeli yanakları

ışıldar binbir renkte

erguvan gözbebekleri

İzmir’i gördün mü? 

Çeşme’yi, Foça’yı

Ildır’ı demiyorum

gördün mü İzmir’i, İzmirli’yi? 

tek tasası ve düşüncesi

oltasının ucundaki yem

bu yeme gelecek balık

bu balığın tavadaki hali

yanında rokası, rakısı

yani yoktur geçmişi 

ya da geleceği

yaşar bugünü

dün yaptığı gibi

izmir’i gördün mü? 

sahil yolunda

efesin arkasında

sıra sıra palmiyeleri

palmiyelerin yanında

yol alan 

tıkır tıkır 

at arabalarını demiyorum… 

gerçekten gördün mü izmir’i? 

Oğuz Altun, Kasım 2004', 'İzmir’i gördün mü?  Saat Kulesini, Asansörü, Fuarı demiyorum gördün mü izmir’i?  yapışmaz nemi yaz günü ve gecesinde püfür püfür  esen yelle...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Altun']::text[], 8.5, '{"poet":"Oğuz Altun","poet_slug":"oguz-altun","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/izmir-i-gordun-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakmam Bir Daha', 'birakmam-bir-daha-huseyin-erdogan-l4uoh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yıllarca bekledim dönersin diye

bitmiyor dertlerim sen gelmeyince

açardı çiçekler güldüğün gece

sensiz soldu güller haydi gülümse

ötmüyor bülbüller yas var her yerde

kokmuyor nergisler rüzgar esse de

kalmadı kırlarda güzel menekşe

ağlarım her gece duyarsın diye

o kadar acı ki sensiz yaşamak

ne de güzelmiş meğer sana sarılmak

her şeye değermiş ellerini tutmak

bırakmam bir daha dönersen eğer', 'yıllarca bekledim dönersin diye bitmiyor dertlerim sen gelmeyince açardı çiçekler güldüğün gece sensiz soldu güller haydi gülümse ötmüyor bü...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/birakmam-bir-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksulun Rüyası', 'yoksulun-ruyasi-i-smet-barlioglu-c6pi5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün gece rüyamda nasıl mutluydum,

Ne çorbalar gördüm, eyleşti gitti.

Mercimek, tarhana, şehriye, ezo

Kaseler içinde söyleşti gitti.

Çoban salatalar cacık yanında,

Yoğurt durmaktaydı aralarında,

Göbekli marullar ortalarında

Yerini yurdunu bilişti gitti.

Pilav sinilerde dağlar gibiydi,

Börekler tepside ağlar gibiydi,

Şıralar sel olup çağlar gibiydi,

Her şey sırasını bölüştü gitti.

Taskebap yanında Yozgat Kebabı,

Pirzola yanında Ürgüp Şarabı,

O nasıl güveçti aman ya Rabbi,

Midem bayramlarla tanıştı gitti.

Beride kapama, ötede rosto,

Sütlaçla gülüşüp durur kompostu,

Dondurmayla dolu keşkülün üstü,

Ruhum zenginlikle barıştı gitti.

Güya bir yerdeyim; her yanım meyva,

Sağımda armut var, solumda ayva,

Küfeyle üzümler, küfeyle elma,

Meyvalar meyvaya karıştı gitti.

Çıka çıka çıktım çok yükseklere,

O anda rastladım yaprak dönere,

Doldurdum döneri hep pidelere,

Yemekten dişlerim kamaştı gitti.

Bir saray gördüm ki safi kebaptan,

Bir ırmak gördüm ki safi şaraptan,

Bir tepe gördüm ki etten tavuktan,

Gönlüm yanlarına ulaştı gitti.

Aman Tanrı ‘m, aman, o ne piliçti,

Dişlerim etine mıh gibi geçti,

Pilavın pirinci baldo pirinçti,

Yağı lavaşıma bulaştı gitti.

Bir baklava gördüm kaymaklanmıştı,

Kadayıf kaymağa yumaklanmıştı,

Cevizler dövülüp hazırlanmıştı,

Fındık da yanına yanaştı gitti.

Uyandım, yorganın ucu ağzımda,

Çarşaf parçaları ta boğazımda,

Yokluk mızrak gibi alınyazımda,

Felek rüyamda da oynaştı gitti.

(DAT DARA LİLLİM isimli Şiirsel Gülmeceler ''inden > 77-79/100)', 'Dün gece rüyamda nasıl mutluydum, Ne çorbalar gördüm, eyleşti gitti. Mercimek, tarhana, şehriye, ezo Kaseler içinde söyleşti gitti. Çoban sa...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/yoksulun-ruyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytanı Taşlamak', 'seytani-taslamak-i-smet-barlioglu-w48zy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çizmeden yukarı çıkar kiracı,

Şeytanı taşlamak sevap değil mi? 

Canları ateşe yakar kiracı,

Şeytanı taşlamak sevap değil mi? 

Hava parasına hayır diyemez,

Yıllık peşinata isyan edemez,

Dili vardır ama söz söyleyemez,

Şeytanı taşlamak sevap değil mi? 

Mukavele yapsan büker boynunu,

Önünde yerlere sürter burnunu,

Diker kuyruğunu, saklar karnını,

Şeytanı taşlamak sevap değil mi? 

Ev diye göstersen tutar kafesi,

Ne bir sesi çıkar, ne de nefesi,

Ne kadar zam yapsan çeker ensesi,

Şeytanı taşlamak sevap değil mi? 

İtiraz bilmeyen melek gibidir,

Bütçesi yolunmuş leylek gibidir,

Dibi su tutmayan elek gibidir,

Şeytanı taşlamak sevap değil mi? 

Yükselt kirayı ki giyinemesin,

Utançtan ellere görünemesin,

Süründür, kendinden sürünemesin,

Şeytanı taşlamak sevap değil mi? 

Ne kapıya çıksın ne de bacaya,

Varsın muhtaç olsun yala, mancaya,

Bırakma el atsın ota, yoncaya,

Şeytanı taşlamak sevap değil mi? 

Kiracı dediğin köle olmalı,

Sen eğil dedikçe o domalmalı,

Bir ömür boyunca doğrulamamalı,

Şeytanı taşlamak sevap değil mi? 

(DAT DARA LİLLİM isimli Şiirsel Gülmeceler ''inden > 80-81/100)', 'Çizmeden yukarı çıkar kiracı, Şeytanı taşlamak sevap değil mi?  Canları ateşe yakar kiracı, Şeytanı taşlamak sevap değil mi?  Hava parasına ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/seytani-taslamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıl', 'agil-ahmet-kurt-6vmuh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir trendi bindiğimiz menzilsiz,

Makiniste teslim olup yol aldık.

Öyle kampanyalar sunduk emsalsiz,

Bütün köşe bucak muştular saldık.

Hedef birlik güya, tarihi gerçek,

Yok olmaya doğru tarih verecek,

Şimdiden içerde ip gerilecek,

Sanal yolculukta hayale daldık.

Yalana inanıp, koy verdik ipi,

Elimize geçmez baltanın sapı,

Eyvah işte şimdi yutturdu hapı,

Avrupa’ya göre bizler aptaldık.

Yalan da sayılmaz söylenen hani,

Kafiri imam et, teslim et dini,

Öz kardeşine bile işlesin kini,

Bizlerde hülyaya daldıkça daldık.

Sorgusuz, sualsiz kabul edildi,

Köleler, birliğe ırgat verildi,

Bu birliğe beyler nasıl girildi,

Pazara ne koyup, neleri aldık.

Bedeli var mıdır nedir aldığın,

Ortada görünen, cazgır, saldığın,

Doğrudur yeniden dostluk kurduğun,

Ondandır uçaklar, tanklara kaldık.

Şimdi anladım ki sırrı tapuda,

İşlem bitsin hele bekle kapıda,

Vatan da ne imiş bayrak yarıda,

Askersiz, nöbetsiz huzura daldık.

Kurdoğlu bu sofra sizlere değil,

Başını yok sayıp, başlara eğil,

Sizlere versinler bir küçük ağıl,

Bizlerde kuzuyla, kurbana kaldık.', 'Bir trendi bindiğimiz menzilsiz, Makiniste teslim olup yol aldık. Öyle kampanyalar sunduk emsalsiz, Bütün köşe bucak muştular saldık. Hedef ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/agil-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elemtere Süper Fiş', 'elemtere-super-fis-i-smet-barlioglu-xf5eq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Doğdu ki baba zengin, ana servet içinde,

Başına altın yağdı dünyaya geldiğinde,

Tek bir noksanı yoktu, her şey yerli yerinde,

Odlumu tan olmalı bu dünyaya ilk geliş,

Elemtere süper fiş, kem gözlere süper şiş.

Kalkıp okula gitti, öğretmenler kölesi,

Sanki küçük şımarık Serendip Şehzadesi,

Baştan sona pekiyi her verilen karnesi,

Önce böyle başladı o görkemli yükseliş,

Elemtere süper fiş, kem gözlere süper şiş.

Liseye gitti ama gırgırlar olsun diye,

Eller derse çalıştı, o götürdü hediye,

En başta o ulaştı bereketli vadiye,

Okul boyu görmedi tek kimseden serzeniş,

Elemtere süper fiş, kem gözlere süper şiş.

Dayandı fakülteye allem gullem eyleyip,

Bitirdi fakülteyi fakülteye gitmeyip,

Yapıştı diplomaya tek kelime bilmeyip,

El attığı ne varsa oldu altın ve gümüş,

Elemtere süper fiş, kem gözlere süper şiş.

Çok çalışıp uğraşıp yatarak uzman oldu,

Etiketle donanıp büyüdü, azman oldu,

En zorlu engel bile önünde duman oldu,

Görülmedi dünyada öylesine dikiliş,

Elemtere süper fiş, kem gözlere süper şiş.

Geldi askerlik çağı, ödedi bedelini,

Sokmadı sıcak sudan soğuk suya elini,

Oldu bir otorite büyük yerin bilgini,

Aman o nasıl görüş… Aman o ne döktürüş…

Elemtere süper fiş, kem gözlere süper şiş.

Her hatası başarı, her yanlışı bir hüner,

Topluma karanlıkta yol gösteren tek fener,

Her zirveye oturdu yoklayıp birer birer,

Öksürmesi bir irşad, esnemesi bir görüş,

Elemtere süper fiş, kem gözlere süper şiş.

Kimseler bilmedi ki; şapkası var, başı yok,

İş sahibi görünür, tek tezgahta işi yok,

Yırtıcı aslan ama kuyruğu yok, dişi yok,

Varsın varmış görünsün o muhteşem görünüş,

Elemtere süper fiş, kem gözlere süper şiş.

(DAT DARA LİLLİM isimli Şiirsel Gülmeceler ''inden > 82-84/100)', 'Doğdu ki baba zengin, ana servet içinde, Başına altın yağdı dünyaya geldiğinde, Tek bir noksanı yoktu, her şey yerli yerinde, Odlumu tan olm...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/elemtere-super-fis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklerim Sahilde', 'beklerim-sahilde-huseyin-erdogan-y5v55', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'göz yaşım durmuyor inliyor kalbim

sen gittin gideli sızlar yüreğim

bitmeyecek inan sana hasretim

yanımda olsan da canım sevdiğim

istemem sen yoksan olmasın akşam

yıllarca ağlasam sevgisiz kalsam

beklerim sahilde gelirsin diye

bil ki senden başkasını aramam

ne olur güzelim gel sarıl bana

ölünceye değin beni bırakma

şarkılar söylerim senli dağlara

yazarım aşkımı geçtiğin yollara', 'göz yaşım durmuyor inliyor kalbim sen gittin gideli sızlar yüreğim bitmeyecek inan sana hasretim yanımda olsan da canım sevdiğim istemem sen...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beklerim-sahilde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aranan Adam', 'aranan-adam-i-smet-barlioglu-rdz4s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağam gazetede gördüm ilanı,

Adam aramışsın, duyar gibiyim.

İnsan olan hemen tanır insanı,

Ben senin şartına uyar gibiyim.

İhbarda, hiylede, her şeyde varım,

Yerinde dilsizim, körüm, sağırım,

İstediğin yerde taştan ağırım,

Çobanın önünde davar gibiyim.

Üşüdüğün anda olurum nezle,

Yüzüme tükürsen gülerim hazla,

Yağ çekerim sana haddinden fazla,

Langa ‘da yetişmiş hıyar gibiyim.

Her kime kızarsan havlarım ona,

Kuyruklar sallarım sana boyuna,

Halılar döşerim senin yoluna,

Efendi ardında zağar gibiyim.

Ben seni hiç yoktan cevher yaparım,

İstediğin yeri ben kundaklarım,

Sen pisler durursun, ben hep paklarım,

Ben sırrı koruyan duvar gibiyim.

Ne hasta olurum, ne de uyurum,

Her akla, kafaya uygun gelirim,

Her türlü itliği iyi bilirim,

Pislikte tıpatıp Cear gibiyim.

Ağam dekler bende, hiyleler bende,

Hüner sende değil, seni övende,

Heykelin dikilir benim sayemde,

Düzeni sağlayan ayar gibiyim.

Tut beni, çalıştır, çekinme sakın,

Bir çeviren gerek varsa dolabın,

Ne günahın varsa olur sevabın,

Her telden, her sazdan çalar gibiyim.

(DAT DARA LİLLİM isimli Şiirsel Gülmeceler ''inden > 85-86/100)', 'Ağam gazetede gördüm ilanı, Adam aramışsın, duyar gibiyim. İnsan olan hemen tanır insanı, Ben senin şartına uyar gibiyim. İhbarda, hiylede, ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/aranan-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Yürekten Sevmiştim', 'seni-yurekten-sevmistim-huseyin-erdogan-z8y8m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sensizliğe mahkum ettim kendimi dünden beri

düşlerimde yoksun artık sensiz geçirdim geceyi

hayallerim bitti ümit ışığım da sönüp gitti

bende senli hiçbir şey kalmadı her şey tükendi

hasret çeken bendim sızlardı yüreğim

her gün göz yaşlarımla dolardı iliklerim

baktığım her yerde yalnızca seni görürdü gözlerim

bil ki yıllar önce ben seni yürekten sevmiştim

bundan sonra beni hatırlama asla hayatını güzel yaşa

sokakta görsen de beni sakın benimle selamlaşma

zaten bir gün alıp gideceğim başımı uzaklara

yalan söyledim sana 

sen beni hiç arayıp sormasan da

ben seni de alıp götüreceğim yüreğimde 

gittiğim her yere hem de ömrüm boyunca', 'sensizliğe mahkum ettim kendimi dünden beri düşlerimde yoksun artık sensiz geçirdim geceyi hayallerim bitti ümit ışığım da sönüp gitti bende...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seni-yurekten-sevmistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim Emelimsin', 'sen-benim-emelimsin-huseyin-erdogan-mmocc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bu sabah güneş gene doğmadı Maltepe''de

her yer hala zifiri karanlık bu şehirde

sokak lambaları da hiç yanmadı gittiğinden beri

burnumda tütüyorsun inan ki çok özledim seni

çiçek kokusu da gelmiyor artık esen rüzgarlarla birlikte

meğer hepsi kurumuş birdenbire sen gittiğin gece

gittin gideli hüzünlü şarkılar çalıyor radyolarda pikaplarda

dönmeyeceksen bile uzaktan da olsa sakın dokunma sevdama

sen benim şarkılarımın güftesi.şiirlerimin de dizelerisin

mahşerde bile vaz geçemem senden sen benim emelimsin', 'bu sabah güneş gene doğmadı Maltepe''de her yer hala zifiri karanlık bu şehirde sokak lambaları da hiç yanmadı gittiğinden beri burnumda tütü...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-benim-emelimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ada''nın Şiiri', 'ada-nin-siiri-husrev-tabak-mbmt1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ada’nın Şiiri

         I

Akdeniz de

üzerine parmak basılmış bir adayım,

yanağından öper genç bir kızı

sahilimde  dalgalar,

falezlerimden

güneşlin batışını izler Neruda

en güzel yer onun 

güneşi gören,

ayaklarının altında sevişir rüzgarla toprak

toz olur denize akar.

en soğuk sularına sokar ayağını genç kız

Anadolu’dan gelen; 

karpuz kabuğu kokusunda 

işçi teri kokusunda

Çukurova’nın.

kısa saçlı kızları taşır

Antalya sahilinden dalgalar

eli boş gelen giremez

karamela kokusu siner saçlarına

nefesleri, dudakları, yanakları

naftalin kokan kızların.

oltaya gelmez balıkları

yeşil bakışlı suların

zarar vermez yem’e

koklayarak yaşar taşları

kısa saçlıların denize attığı.

her doğan hümanist olur,

güneş dahil.

martılar çekmesin diye 

kısa saçları kızların.

ve ben belki Kıbrıs değilim,

yaşanmadı üzerimde savaşlar

ne de bir silah barındırdım üstümde.

ara sıra Neruda gelir ziyaretime

dizime oturur dertleşiriz,

kısa saçlılar el sallar ona

Rüştü Onuru bekleriz…

        

              II

   Nedamet’e Cevap 

hayıflanma Rüştü Onur

yelkenim de var gemimde limanda,

mercanlı sahiller de benim 

erken  kalktın ama sen

görüşmemiz; 

toprağınla sahilime vurmana kaldı.

30 Ekim – 2 Kasım 2004, Konya', 'Ada’nın Şiiri          I Akdeniz de üzerine parmak basılmış bir adayım, yanağından öper genç bir kızı sahilimde  dalgalar, falezlerimden gün...', ARRAY['Türk Edebiyatı','Şiir','Hüsrev Tabak']::text[], 8.5, '{"poet":"Hüsrev Tabak","poet_slug":"husrev-tabak","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/ada-nin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harcanan Nesil', 'harcanan-nesil-mehmet-isikoglu-a8vqa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yad eller benliği  tümüyle yuttu

Nerde haslet yüklü tacımız hani? 

Kimi kimliğini çoktan unuttu

Saygı değer örnek hacımız hani? 

Akşamları diskotekler doldurduk

Gördüğümüz sarışına saldırdık

Geleneği tüm ortadan kaldırdık

Kültürler aktaran gecemiz hani? 

Cinsiyetler birbirine karıştı

Gece gündüz ananeler yarıştı

Etiğin avazı sınırlar aştı

İffetine sadık bacımız hani? 

İnancın duygusu kitapta kaldı

Dinde hurafeler geniş yer aldı

Uyutuldu insan gaflete daldı 

Bilimle donanmış hocamız hani? 

Yurdumuz yuvamız  hepsi dağıldı

Peteklerden  ballarımız sağıldı

Dimdik duran başlarımız eğildi

Çelik bileklerde  gücümüz hani? 

Bizim nesil döviz için harcandı

Çileler ateşi sırtında yandı

Çocuklar batağa tepeden bandı

Nöbet devralacak gencimiz hani?', 'Yad eller benliği  tümüyle yuttu Nerde haslet yüklü tacımız hani?  Kimi kimliğini çoktan unuttu Saygı değer örnek hacımız hani?  Akşamları d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/harcanan-nesil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Sana Vurgun', 'ay-sana-vurgun-huseyin-erdogan-91jq6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ne akşamım belli ne de sabahım

hiç durmadı inan akan göz yaşım

güneş doğmasa da fark etmez artık

zaten yokluğunda her yer karanlık

yıldızlar düşüyor denizler durgun

geceler üşüyor gündüzler yorgun

şafaklar sökmüyor ay sana vurgun

ansızın çıkıver gel ne olursun

dertlerim bitecek dönersen eğer

rengarenk açacak bahçemde güller

inan ki sensizlik ölümden beter

ne olur bir gece zili çalıver', 'ne akşamım belli ne de sabahım hiç durmadı inan akan göz yaşım güneş doğmasa da fark etmez artık zaten yokluğunda her yer karanlık yıldızlar...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ay-sana-vurgun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Gidiyorum İzmir', 'ben-gidiyorum-i-zmir-can-ozeken-pwggj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben gidiyorum İzmir,

sana teslim herşeyim,

ağladığımı zannettiğim ıslak gözlerimle,

çektiğimi sandığım dipsiz acılarla,

ben gidiyorum İzmir.

Hep ağladımı sanırdım bu güne kadar,

hıçkıra hıçkıra,

derin, derin iç çekerek

ağlamanın gözde değil, 

özde olduğunu

gerçekten ağlayınca anladım.

Ben gidiyorum,

inandığım değerler uğruna

yaşamayı göze aldığım için.

İzmir''im,

dosthane göğsünde uyuduğum,

ıslak sokaklarında yürüdüğüm,

ağladığını zannetme yağmurlu havalarda,

ayazında, baharında, yazında

nefesimi içime çektiğim gerçek dostum,

O son, 

öldürücü ihanetini yapmadan  insanlar bana,

gidiyorum...

Korkma İzmir,

üzülme,

seni terk etmiyorum,

sadece sade bir ben''den

limoni bir ben''e gidiyorum

ağlamaya değmez insanların sokaklarında

ben olarak, ben gibi 

kayboluyorum...', 'Ben gidiyorum İzmir, sana teslim herşeyim, ağladığımı zannettiğim ıslak gözlerimle, çektiğimi sandığım dipsiz acılarla, ben gidiyorum İzmir....', ARRAY['Türk Edebiyatı','Şiir','Can Özeken']::text[], 8.5, '{"poet":"Can Özeken","poet_slug":"can-ozeken","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ben-gidiyorum-izmir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güller Solmadan', 'guller-solmadan-huseyin-erdogan-xlmjd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'esmiyor gönlümde o deli rüzgar

şimdi senden kalan yalnız anılar

gittin gideli kalbimde sızı var

bekliyorum seni gözümde yaşlar

düşlerimde bile yalnız sen varsın

çekiyorum çile vefasız yarsın

senelerce seni bekledim durdum

her geçen yıl beni bin defa vurdun

ah! bir geri dönsen sabah olmadan

göz yaşım silsen güneş doğmadan

sevdiğimi bilsen ömrüm dolmadan

ah! bir geliversen güller solmadan', 'esmiyor gönlümde o deli rüzgar şimdi senden kalan yalnız anılar gittin gideli kalbimde sızı var bekliyorum seni gözümde yaşlar düşlerimde bi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guller-solmadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim Yine Yalnız Seni Sevecek', 'kalbim-yine-yalniz-seni-sevecek-huseyin-erdogan-wkpwj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gündüzler karanlık sen yoksan eğer

sensizlik ölümden betermiş meğer

değmese de elim razıyım buna

uzaktan da olsa beni sev yeter

sen bir gonca gülsün her sabah açan

inan hasretimsin gönlümde yanan

bahar gözlerini özlerim her an

bekliyorum seni güneş batmadan

dönmesen de bana ömrüm boyunca

sana olan aşkım hiç bitmeyecek

silmesen de gözlerimi yaşlar dolunca

kalbim yine yalnız seni sevecek', 'gündüzler karanlık sen yoksan eğer sensizlik ölümden betermiş meğer değmese de elim razıyım buna uzaktan da olsa beni sev yeter sen bir gonc...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kalbim-yine-yalniz-seni-sevecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldanış...(Aktivite)', 'aldanis-aktivite-canan-palabiyik-k8h1c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fotoğraflarını yırttığım o gece, 

Ben seninle vedalaştığımı sanmıştım, 

Durulacaktı içimdeki fırtına, 

Kuşlar gibi özgür olacaktım, 

Yelken açacaktım yeni limanlara, 

Yağmur sonrası çıkan gökkuşağı olacaktım, 

Yedi renkte salınacaktım gökyüzüne... 

Ama kendimi kandırmışım, 

Bir kıyamettir koptu ruhumda, 

Göz yaşlarımı durduramadım, 

Kelimeler düğümlendi azap oldu dudaklarımda, 

Bu güne kadar hiç kimsenin önünde eğilmedim, 

Şimdi af diliyorum itiraf ediyorum sana, 

Aşkım için önünde diz çöküyorum... 

(04 Kasım 2004 / İstanbul) 

Samanyolu Grubunun 2K1Ş ''İki Kelime Bir Şiir'' Aktivitesi için kaleme alınmıştır. Kelimeler: ''''FOTOĞRAF'''' ve ''''KUŞLAR''''', 'Fotoğraflarını yırttığım o gece,  Ben seninle vedalaştığımı sanmıştım,  Durulacaktı içimdeki fırtına,  Kuşlar gibi özgür olacaktım,  Yelken ...', ARRAY['Türk Edebiyatı','Şiir','Canan Palabıyık']::text[], 8.5, '{"poet":"Canan Palabıyık","poet_slug":"canan-palabiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aldanis-aktivite-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taneleri Darı Oldu Yüreğimde Aşkın', 'taneleri-dari-oldu-yuregimde-askin-selim-bayrak-veczt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Taneleri darı oldu yüreğimde  aşkın

Ağacı kök salamadan toprağa

Dalları filiz veremeden yaşama

Hayalleri yara oldu yüreğimde aşkın

Nefesi sesim olamadı kavgamda

Tenim tinime yenik mi düştü

Tutunamadım ayağımın altından kayan toprağa

Uzanamadım her şeyin ve de yarin

Yemyeşil masmavi 

Varlığımın varışı

O bemberrak koynuna

1998 - İstanbul', 'Taneleri darı oldu yüreğimde  aşkın Ağacı kök salamadan toprağa Dalları filiz veremeden yaşama Hayalleri yara oldu yüreğimde aşkın Nefesi se...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/taneleri-dari-oldu-yuregimde-askin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akın Akın', 'akin-akin-hakki-karadeniz-p2l64', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biraz da ciddi.

Ama tamamen insan...', 'Biraz da ciddi. Ama tamamen insan......', ARRAY['Türk Edebiyatı','Şiir','Hakkı Karadeniz']::text[], 8.5, '{"poet":"Hakkı Karadeniz","poet_slug":"hakki-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/akin-akin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım', 'canim-nilgun-i-nan-o0iab', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen benim canım

Damarımdaki kanımsın

Sen benim aşkım

Aşkını unutamayacağım tatlı belamsın

Sen benin nefesimsin

Beni hayata bağlayıp

Ölesiye seven

Ela gözlü sevdiğimsin

                                  Canım aşkım mehmedime', 'Sen benim canım Damarımdaki kanımsın Sen benim aşkım Aşkını unutamayacağım tatlı belamsın Sen benin nefesimsin Beni hayata bağlayıp Ölesiye ...', ARRAY['Türk Edebiyatı','Şiir','Nilgün İnan']::text[], 8.5, '{"poet":"Nilgün İnan","poet_slug":"nilgun-i-nan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/canim-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ye Mehmet Ye', 'ye-mehmet-ye-mehmet-isikoglu-255iz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'YE MEHMET YE! 

Memlekette geze geze yorulsan

Dostlarına birer birer sarılsan

Hele birde hazır sofra bulursan

Otur orada kal ye ye Mehmet ye

Yeşili bol masaları kurulmuş

Acı kebap taş ocağa sürülmüş

Keyif suyu siparişi verilmiş

Eğlen neşeni bul ye ye Mehmet ye

İştah açar yufka ekmek kuş başı

Sıcak buhar solur bak bulgur aşı

Yanında var bir de sirkeli turşu

Zevkine göre dal ye ye Mehmet ye

Ne tatlıdır etli keşkek pilavı 

Burcu burcu kokar gartmelin yağı

Düğün aşı kalmaz ondan aşağı

Daldır kaşığı çal ye ye Mehmet ye

Kaynamış geliyor içli köfteler

Ebelikli toğga türlü yemekler

Köftenin içinde bir sürpriz bekler

Kısmetse çıkar fal ye ye Mehmet ye

Baharatlı bir çiğköfte yoğrulmuş

Ekşi ayran tastan tasa savrulmuş

Kadın budu köfte aslına uymuş

Damak tadını al ye ye Mehmet ye

Sıcak sıcak bir tarhana çorbası

Tadı dillerde o yaprak dolması

Sofranın gülü çoban salatası

Hepsi sana helal  ye ye Mehmet ye 

Sofra dolu yemeklerin alası

Patlıcan lahana biber dolması

Küpeli kazanda tirşik çorbası

Yemedin oldu yıl ye ye Mehmet ye

Türlü türlü sebze baş yemekleri

Tadına doyulmaz hoş sünüberi

Hiçbiri çevrilmez dönemez geri

Sevdiğin yemek bol ye ye Mehmet ye

Kızartılmış gelmiş türlü börekler 

Dayanamaz bunu gören yürekler

Donatılmış sofra bizleri bekler

Bekletme hemen gel ye ye Mehmet ye 

Eşgili çorbayı kazandan yersin

Kısır yemeğine çok güzel dersin 

Yemek üstü bir de künefe gelsin

Kadayıf üstü tel ye ye Mehmet ye 

Çukurova yemeklerin hiç bitmez

Lahmacun mu humus mu pek fark etmez 

Mehmet bunlar yalnız  başına gitmez

Buyur yiyelim gel ye dost sen de ye

Ye Ali sen de ye ye kız sen de ye', 'YE MEHMET YE!  Memlekette geze geze yorulsan Dostlarına birer birer sarılsan Hele birde hazır sofra bulursan Otur orada kal ye ye Mehmet ye ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/ye-mehmet-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollarda', 'yollarda-mustafa-sen-gzyx3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kızıl yapraklarını dökerdi gece 

   koynumuza usulca

      bilirim üşürsün sen... 

         sokulurdun yalnızlığıma...

           uzaklardan şeker kokardı gecelerim 

                dudakların misali

yağmur fısıltısı gelirdi kulaklarıma

  fıstık ağaçları arasında

     sonra gökkuşağı yedi renk ağlardı...

gece ıssızlığını 

  sensizliğe bulamış

      kor  demir gibi

        bir İstanbul vakti

peki ben; 

   neredeyim? 

      kimlerleyim? 

          sen neredesin? 

özlüyordum 

  yaz bitmiş,

    sen çoktan başlamıştın...

ey gidi koca şehir İstanbul aşkolsun! ...

   kadınıma aşk...', 'Kızıl yapraklarını dökerdi gece     koynumuza usulca       bilirim üşürsün sen...           sokulurdun yalnızlığıma...            uzaklardan...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şen']::text[], 8.5, '{"poet":"Mustafa Şen","poet_slug":"mustafa-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yollarda-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Olmaz', 'sensiz-olmaz-hayrettin-orak-fu7wb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karardı dünyam döndüm şaşkına,

Eriyip kül oldum hoş bakışına,

Saldım kendimi hayatın akışına,

Sensiz olmaz, olmaz be yar. 

Dolandım durdum deli divane,

Tesellim olur mahzen meyhane,

Kızgın hançer vurdum yanık sineye,

Sensiz  olmaz, olmaz be yar.

Alır beni benden tatlı diliyle,

Hülyalara daldırır inci gözleriyle,

Semalarda gezdirir güzel sözleriyle,

Sensiz olmaz, olmaz be yar.

Aç kolların gel bana sıcaklığınla,

Mecnuna döndüm senin aşkınla,

Son kez olsun affet Allah aşkına,

Sensiz olmaz, olmaz be yar....! 

4.11.2004', 'Karardı dünyam döndüm şaşkına, Eriyip kül oldum hoş bakışına, Saldım kendimi hayatın akışına, Sensiz olmaz, olmaz be yar.  Dolandım durdum d...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sensiz-olmaz-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur', 'ne-olur-hayrettin-orak-v8mxa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aldım elime kağıt kalem, yazmak için şiir,

Hatıralar canlandı gözümde, bir bir,

Anlatamaz seni ne bir ozan nede şair,

Aç kollarını bana ne olur deme hayır.

Kıskanırım seni cümle alemden,

Sakınırım tüm kem gözlerden,

Yıldıramazlar beni sana olan sevgimden,

Gel ne olur etme beni kendinden.

Har vurur harman savururum,

Ahh demez bağrıma hançer vururum,

Ölürsem bilki senin için ölürüm,

Dön ne olur sonum olmasın uçurum.

Ne kadar anlatsam sonu gelmiyor,

Tükendi kalemim artık yazmıyor,

Seni seven yüreğimi Allah biliyor,

Gel nazlı gülüm bu can SENİ seviyor...! 

4.11.2004', 'Aldım elime kağıt kalem, yazmak için şiir, Hatıralar canlandı gözümde, bir bir, Anlatamaz seni ne bir ozan nede şair, Aç kollarını bana ne o...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-olur-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar Sonra Olsa da', 'yillar-sonra-olsa-da-huseyin-erdogan-ax7iq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kış aylarında güneş rengarenk doğar sabahları

gök yüzünde yağmur bulutları yoksa eğer

kırmızılı yeşilli morlu batar akşamları

dumanlı değilse eğer dağların yamaçları

ne güneş doğar ne de sabah olur bu şehirde 

sen olmayınca

yılın dört mevsiminde de 

hep gece yaşanır buralarda

fırtınalar sürükler götürür beni bilmediğim yerlere

korkar dururum geceler boyunca o ıssız köşelerde

ellerimi siper ederim yüreğime seni üşümesin diye

ne olur gel sil göz yaşlarımı yıllar sonra olsa da

bir daha bırakmamak üzere

sen de beni sıkıca sar kollarınla', 'kış aylarında güneş rengarenk doğar sabahları gök yüzünde yağmur bulutları yoksa eğer kırmızılı yeşilli morlu batar akşamları dumanlı değils...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yillar-sonra-olsa-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can', 'can-hayrettin-orak-rcqih', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Daha minik bir yavruydum can,

Yüzüme bakar tatlı tatlı gülerdi,

Ardından hızla döner çeker giderdi,

Bir sıcaklık hissederdim yüreğimde,

Bilmezdim can bilemezdim acıların beni beklediğini,

Okul sıralarına ismini yazardım en güzel kalemlerimle,

Sonrada zevkle özenerek etrafını süsledim çiçeklerle,

Şiirler yazardım kendimce, duygularımı satırlara dökerek,

Bilmezdim can, bilemezdim kederlerin beni bulacağını,

Tatillerde bomboş okula giderdim, anılarımı tazelemeye,

Sınıfın her köşesine yazıp süslediğim aşk sözcüklerini,

Tekrar tekrar okurdum heyecanla, şevkle,

Hayali belirirdi karşımda,yine tatlı tatlı gülerek,

Güzel sözler söyleyerek,

Ama ansızın kaybolurdu gözümden, çekip giderek,

Birgün bomboş sınıfta birkağıt parçası gördüm,

Her taraf tozluyken,

Üzerine sevgilim yazdığım kağıt, 

Tertemiz lekesiz kalakalmıştı oracıkta,

Aldım elime kağıdı ve defalarca,

Bıkıp usanmadan sevgilimdiye haykırdım,

Sesim boş koridorlarda defalarca yankılanırdı,

Hoşuma giderdi,

Sanki oda bana karşılık verip sevgilim der gibiydi,

Tekrar tekrar haykırdım sevgilimi defalarca,

Ama hepsi hayalmiş can, hepsi yalanmış,

Şakaymış bana yaptıkları,

Bilmezdim can, 

Bilemezdim böyle aldanıp eriyip gideceğimi....! 

4.11.2004', 'Daha minik bir yavruydum can, Yüzüme bakar tatlı tatlı gülerdi, Ardından hızla döner çeker giderdi, Bir sıcaklık hissederdim yüreğimde, Bilm...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/can-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben sende hiç varolmadım ki', 'ben-sende-hic-varolmadim-ki-ceylan-yarar-din1b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben sende hiç varolmadım ki

Sıcak yaz akşamlarında 

Söylediğim, şarkılarım vardı sadece

Baktığında bana,gözlerime

Derya deniz görüyordun bende

Gülüşlerimde, gül bahçelerin vardı

Ben sende hiç varolmadım ki

Bana her baktığında

Yıldızsız gecelerinin yıldızı

Soğuk kış akşamlarının sıcağı

Fırtınalara yakalandığında

Herzaman sığınacağın bir limandım; 

Yanlız akşamlarının kalabalığı

Ben, ben olarak var olmadım ki sende

Duygularım,varlığım,sevgim

Öfkem,nefretim,hıncım

Görmedin ki hiç bunları

Sen istediğini aldın benden

İstediğin gibi gördün hep

Güçtüm karşında her zaman

Bana vurdugun her darbede

Yıkılmadığımı,ayakta kalmamı gördün

Yüreğime sapladığın hançerde

Akmayan kanımı gördün

Seninle her konuşmamda

Susturmayi seçtin hep

Boğazıma ip geçirdin

İdamlık mahkumlar gibi,

Hala nefes alışımı gördün

Ben var olmadım ki hiç sende; 

Gücüm,direncim,inancım vardı

Bir de bitmeyeceğine inandığın sevgim..

Ceylan Yarar

        08.kasım.2003.', 'Ben sende hiç varolmadım ki Sıcak yaz akşamlarında  Söylediğim, şarkılarım vardı sadece Baktığında bana,gözlerime Derya deniz görüyordun ben...', ARRAY['Türk Edebiyatı','Şiir','Ceylan Yarar']::text[], 8.5, '{"poet":"Ceylan Yarar","poet_slug":"ceylan-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ben-sende-hic-varolmadim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim kaderim', 'zalim-kaderim-nilgun-i-nan-rne2g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zalim kader gülmedi yüzümüze

Bir damla mutluluk vermedi ömrümüze 

İsyan ettirip kahretti her gece

günahkar edip çıldırttı günlerce', 'Zalim kader gülmedi yüzümüze Bir damla mutluluk vermedi ömrümüze  İsyan ettirip kahretti her gece günahkar edip çıldırttı günlerce...', ARRAY['Türk Edebiyatı','Şiir','Nilgün İnan']::text[], 8.5, '{"poet":"Nilgün İnan","poet_slug":"nilgun-i-nan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zalim-kaderim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişman Değilim', 'pisman-degilim-hayrettin-orak-992vg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Deymeyin,

Deymeyin yüreğime, bırakın bağrım yansın,

Sevdimde ne oldu 

Dokunmayın bana, dertler kederler bana kalsın,

Sevdiğim vefasızda olsa, acımasızda olsa,

Razıyım sevinçler, mutluluklar hep onun olsun,

Esiyor,

Esiyor üstüme üstüme hırçın, deli poyraz gibi,

Savuruyor beni amansızca,vaktiyle hiç sevmemiş gibi,

Tutunamıyorum karşısında, olmuşumkuru bir yaprak gibi,

Olsun razıyım gurbet ele, yalnızlığa bile sürüklese beni.

Süzülecek yaş kalmadı göz pınarlarımda,

Sarfedecek ne gücüm kaldı nede mecalim,

Feleğin sillesini yemişim ben can evimden,

Yinede seviyorum canlar, pişman değilim sevgimden.

Unutamıyorum, 

Her an hayaliyle irkiliyorum,katlanıyorum tüm acılara,

Uzaktanda olsa ona olan sevgimi içiyorum kana kana,

Suyumla sigaramla,

Seviyorum, yinede çok seviyorum o vefasızı....! 

4.11.2004', 'Deymeyin, Deymeyin yüreğime, bırakın bağrım yansın, Sevdimde ne oldu  Dokunmayın bana, dertler kederler bana kalsın, Sevdiğim vefasızda olsa...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/pisman-degilim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gittin Gideli', 'sen-gittin-gideli-huseyin-erdogan-njqkl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'artık güneş de doğmuyor sabahları

bizim buralara

nedense ay ve yıldızlar da çıkmıyor geceleri

gittiğinden bu yana

rüzgar bile esmiyor

ne gündüzleri ne de geceleri

sen yoksun diye sen gittin gideli

dayanamıyorum sensizliğe

korkuyorum yapayalnızım

gündüzleri güneşim ol

geceleri de ay ve yıldızlarım

gel ısıt yüreğimi aydınlat dünyamı

kaybolsun korkularım

yoksa ölünceye değin

isyankar olarak kalacağım', 'artık güneş de doğmuyor sabahları bizim buralara nedense ay ve yıldızlar da çıkmıyor geceleri gittiğinden bu yana rüzgar bile esmiyor ne gün...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-gittin-gideli-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kararsızlık', 'kararsizlik-dila-lale-a1qsw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nasıl bir dünya olmalı

Nasıl bir hayat sürmeli

Bilinmezlikler, korkular, kararsızlıklar

Çok mu şey istiyorum sanki

Karar vermek bu kadar zor mu ki

Neyi, neyden korktugunu bilmeden

Aklımdan geçen binbir sözden

Kurtulmak için bile sanki

Bir karar vermek zorundayım

Pişmanlık duymak istemiyorum

Yaşadıklarım, benim parçam, hayatım biliyorum

Gelecek bize ne gösterir bilmiyorum

Tanrımdan istediğim sağlık, huzur, mutluluk

Kimse korkmasın olacaklardan

Kimse pişmanlık duymasın yaşantısından

her yaşanan, olanlar bize ait olan hayattan. 

(2003)', 'Nasıl bir dünya olmalı Nasıl bir hayat sürmeli Bilinmezlikler, korkular, kararsızlıklar Çok mu şey istiyorum sanki Karar vermek bu kadar zor...', ARRAY['Türk Edebiyatı','Şiir','Dila Lale']::text[], 8.5, '{"poet":"Dila Lale","poet_slug":"dila-lale","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kararsizlik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam''a', 'babam-a-dila-lale-3a397', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özledim seni

Hemde o kadar cok özledim ki anlayamazlar beni

Rüyamda bile görebilmeyi

Resmine bakıp, öpmeyi

Saçımın tek bir telini çekmeni,

O içtiğin sigaranın dumanını,

Sigaradan oluşan sarı parmaklarını

Gülümsemeni, 

kendine has konuşmanı

Birlikte izlediğimiz filmleri

Her sabah banyoda yaptıgımız kavgaları

Uzun uzun şımarık demeni

Sana doyasıya sarılmayı

Seni doyasıya öpmeyi

O sıcacık sevgiyle bakan iri gözlerini

Hepsini, herşeyini özledim 

en cok da babacım demeyi özledim.

(2003)', 'Özledim seni Hemde o kadar cok özledim ki anlayamazlar beni Rüyamda bile görebilmeyi Resmine bakıp, öpmeyi Saçımın tek bir telini çekmeni, O...', ARRAY['Türk Edebiyatı','Şiir','Dila Lale']::text[], 8.5, '{"poet":"Dila Lale","poet_slug":"dila-lale","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/babam-a-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma', 'unutma-dila-lale-meai5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Durup, düşünüyorum

ama gitmek istiyorum buradan

herşeye yeniden başlayabilmek

mümkün mü bilmiyorum ama

bunu yapmam gerekecek.

Senin hayatında bir problem, sıkıntı isem

bırak git beni o zaman

değmezmiş sevgimize diyelim birlikte

bu kadar sıkıntı problem yaşamak 

istemiyorsan eğer

bırak git beni o zaman

İstese insanın yapamayacagı şey yok 

buna artık inancım cok.

Eğer beni o kadar isteseydin

yapamayagımız hiçbirşey yok.

Ben herşeye hazırdım.

Hiçbirşeyden korkmadan

seninle hayatımızı yaşamaya

karar vermiştim çoktan.

Benim senden istediğim birkaç

kelimeyi duymakdı bunları bile

duyamadıktan sonra 

beklemenin ne anlamı var ki.

Değişecek mi sanki

Kadınlar daha cesaretli nasıl olsa

erkekler ise daha kararsızlar aslında.

Ama olsun herşey güzeldi seninle yaşanan

hayatımın en güzel anlarındandı 

Ömrümün sonuna kadar unutamam

hep ta içimde yaşayacagım 

yaşatacagım sonsuza kadar

senden habersiz olsa da

seni seven her zaman biri var burada

bunu da sakın unutma.

(2004)', 'Durup, düşünüyorum ama gitmek istiyorum buradan herşeye yeniden başlayabilmek mümkün mü bilmiyorum ama bunu yapmam gerekecek. Senin hayatınd...', ARRAY['Türk Edebiyatı','Şiir','Dila Lale']::text[], 8.5, '{"poet":"Dila Lale","poet_slug":"dila-lale","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/unutma-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor mu?', 'zor-mu-dila-lale-hplqe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çok mu zor

insanın yapmak istediklerini yapması

zor değil aslında

yeter ki iste, canı yürekten iste

işte o zaman yapamıyorum deme

istemek yapmanın yarısıdır

gülme bu yazdıklarıma

yapmak istediğim çok şey var ama

korkuyorum hepsinden

ne kadar zor bilir misin

içindekileri, istediklerini yapamamak, korkmak

sakın sen korkma

eğer istiyorsan yapmalısın

korkmak insanı üzüyor, yıpratıyor

pişman olacagım diye yapmamak ise

yine keşke demeni sağlıyor

ve pişman olur muyum derken

yeni bir pişmanlık yaratıyor.

kısır bir döngü içinde oluyorsun

ama günler, haftalar, aylar, yıllar geçiyor

abelki anlıyorsun ama

iş işten çoktan geçmiş oluyor.

(2004)', 'çok mu zor insanın yapmak istediklerini yapması zor değil aslında yeter ki iste, canı yürekten iste işte o zaman yapamıyorum deme istemek ya...', ARRAY['Türk Edebiyatı','Şiir','Dila Lale']::text[], 8.5, '{"poet":"Dila Lale","poet_slug":"dila-lale","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/zor-mu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem', 'bilmem-dila-lale-eis0g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ağlamak istiyorum

nedendir bilmem

cekip gitmek istiyorum

nedendir bilmem

şu anda yanında olmak istiyorum

nedendir bilmem

inanmayın bilmem dediğime

bilmiyorum dediklerime

anlatmak, yapmak korkutuyor beni

işte bu yüzden gizleniyorum bu kelimenin ardına

bilmiyorum neden yapamıyorum istediklerimi

bütün bu sorular yoruyor her geçen gün bedenimi.

(2004)', 'ağlamak istiyorum nedendir bilmem cekip gitmek istiyorum nedendir bilmem şu anda yanında olmak istiyorum nedendir bilmem inanmayın bilmem de...', ARRAY['Türk Edebiyatı','Şiir','Dila Lale']::text[], 8.5, '{"poet":"Dila Lale","poet_slug":"dila-lale","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bilmem-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişen Bir Şey Yok', 'degisen-bir-sey-yok-dila-lale-lnmub', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'değişen bir şey yok sanki

günler geçiyor hızla

çıktım balkona

baktım her yanan ışıga

kimi insan uyuyor 

kimi insan sohbet ediyor

kimi insan aglıyor

kimi insan geceyi yalnız yaşıyor

yaktım bir sigara

çektim dumanı içime

her nefesimde

seni yaşadım gecenin yalnızlıgında

yalnız ve ben

arkadaşız ne de olsa.

(2004)', 'değişen bir şey yok sanki günler geçiyor hızla çıktım balkona baktım her yanan ışıga kimi insan uyuyor  kimi insan sohbet ediyor kimi insan ...', ARRAY['Türk Edebiyatı','Şiir','Dila Lale']::text[], 8.5, '{"poet":"Dila Lale","poet_slug":"dila-lale","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/degisen-bir-sey-yok-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter ki', 'yeter-ki-huseyin-erdogan-zbcok', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen gitmeden önce gün batımlarında

bir kızıllık çökerdi bizim ovalara

ladin ağaçlarının gölgesi düşerdi

yemyeşil akan ırmaklara

sen gülümseyince

kuşlar cıvıl cıvıl öterdi yaylalarda

menekşeler rengarenk açardı kırlarda

yaz havası hissedilirdi kış aylarında

oysa şimdi her şey sükut içinde

ağaçların yaprakları bile

dallarında duruyor sessizce

yokluğunda ağlıyorum her gece

ne olur dön gel buralara

yıllar sonra olsa da

razıyım bana hiç sarılmasan da

yeter ki seni göreyim son bir kez daha

göreceksin ölüm bile vız gelecek bana', 'sen gitmeden önce gün batımlarında bir kızıllık çökerdi bizim ovalara ladin ağaçlarının gölgesi düşerdi yemyeşil akan ırmaklara sen gülümsey...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yeter-ki-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-dila-lale-6rxk8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gözlerinin içine baktıgımda

ellerim elini tuttugunda

dudaklarım dudaklarına değdiğinde

içimdeki kıpırtıyı şimdi hissedemesemde

özlem içinde kavrulsamda

hasret ceksem de

kimin umurunda desem de

kalbimin her atışında

içimdeki aşk daha da hızlanıyor biliyorum

cunki seni seviyorum. 

(2003)', 'gözlerinin içine baktıgımda ellerim elini tuttugunda dudaklarım dudaklarına değdiğinde içimdeki kıpırtıyı şimdi hissedemesemde özlem içinde ...', ARRAY['Türk Edebiyatı','Şiir','Dila Lale']::text[], 8.5, '{"poet":"Dila Lale","poet_slug":"dila-lale","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/seni-seviyorum-216-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkma Gülümse Hayata', 'korkma-gulumse-hayata-dila-lale-e2gvu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırılma, darılma hayata

küsme kimseye

korkma hiçbirşeyden

yaşamaktan, yaşanacaklardan

korkmak neyi değiştirir ki

yaşanması gerekenler ne ise

istesek de istemesek de yaşanacak

yalnız mıyız acaba

bu hayatta.

hata arama artık yaşananlarda

bırak gitsin hayat

ama istediğince, gönlünce yaşa

keşke deme asla

geriye dön bir bak arada

unutma yaşanılacaksa,

yaşanılacak bu hayat

sakın korkma

sadece iste mutlu oldugunca gönlünce yaşa

gülümse hayata

sevgiyle bak dünyaya

geçiyor zaman unutma

bitecek bir gün yaşam her ne kadar kabul etmesekde

(2004)', 'Kırılma, darılma hayata küsme kimseye korkma hiçbirşeyden yaşamaktan, yaşanacaklardan korkmak neyi değiştirir ki yaşanması gerekenler ne ise...', ARRAY['Türk Edebiyatı','Şiir','Dila Lale']::text[], 8.5, '{"poet":"Dila Lale","poet_slug":"dila-lale","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/korkma-gulumse-hayata-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayanamam İnan Sensiz Yıllara', 'dayanamam-i-nan-sensiz-yillara-huseyin-erdogan-rkp0k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kızıl saçlarını savursun rüzgar

doyamam kokuna geçse de yıllar

sakın çekip gitme sen uzaklara

dayanamam inan sensiz yıllara

değmese de elim razıyım buna

seni görsem yeter aşığım sana

uzaktan da olsa gülümse bana

dayanamam inan sensiz yıllara

gonca güller açmaz sen yoksan eğer

gülşenlerde bile ötmez bülbüller

sensizliğin adı ölümmüş meğer

dayanamam inan sensiz yıllar', 'kızıl saçlarını savursun rüzgar doyamam kokuna geçse de yıllar sakın çekip gitme sen uzaklara dayanamam inan sensiz yıllara değmese de elim ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dayanamam-inan-sensiz-yillara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alınyazımsın', 'alinyazimsin-vedat-koseoglu-3o4ih', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Unuttum ben hüznün siyah rengini

Bahçeme seninle geldi ilkbahar,

Kaybolsa da gökyüzünde güneş, 

Ufkumda parlayan yıldızım var...

Sen sözüm, sen şarkım,

Sen gönül sazımsın,

Sen benim silinmez

Alınyazımsın....

Bilmem artık gözyaşını, kederi

İçimde en güzel pınarlar çağlar

Elimi tuttuğun o günden beri

Ufkumda parlayan yıldızım var..

Sen sözüm, sen şarkım,

Sen gönül sazımsın,

Sen benim silinmez

Alınyazımsın....

Not: Muhayyer-kürdi makamında bestelenmiştir', 'Unuttum ben hüznün siyah rengini Bahçeme seninle geldi ilkbahar, Kaybolsa da gökyüzünde güneş,  Ufkumda parlayan yıldızım var... Sen sözüm, ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Köseoğlu']::text[], 8.5, '{"poet":"Vedat Köseoğlu","poet_slug":"vedat-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/alinyazimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamam', 'unutamam-i-brahim-ethem-bingul-z6psm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Siyah saçlım, kara gözlüm nerdesin

Derken seni gördüm, penceredesin

Yüzünü gösterdin, nerede sesin

Sesinle,sözünle sen gönlümdesin...

Ellerin elime tutunmalıydı

Gözlerinden sevdam okunmalıydı

Bizi bize kalpler anlatmalıydı

Dilde şarkı oldu bu aşkın yâdı...

Unutamam konuşurdum,dinlerdin

Ter dökerken bana serin eserdin 

Bakışından anlıyordum,severdin

Mesut günlerimden bana esersin

Siyah saçlım, kara gözlüm nerdesin... 

www.iebingul.com', 'Siyah saçlım, kara gözlüm nerdesin Derken seni gördüm, penceredesin Yüzünü gösterdin, nerede sesin Sesinle,sözünle sen gönlümdesin... Elleri...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/unutamam-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdan 3', 'sevdan-3-zafer-ozkay-w4ovr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Baharıma sen yağdırdın karları,

Sen soldurdun güllerimi henüz açmadan,

Şimdi sen ellerin kolundaysan eğer,

Buna yaşarken ölmek derler.

Senden sonra güneşim doğmadı,

Sendin güneşim, derdimi anlatacak bir dostum olmadı,

Sendin benim tek dostumdun, karşıma senin kadar bir güzel çıkmadı,

Çünkü, gözüm senden başkasını görmedi kader mi derler buna? 

Geceleri gökyüzünde ay yok,

Yıldızlar küstü yüzün sakladı, bakmıyor bana,

Senden sonra kararan yolum bir daha aydınlanmadı,

Düşündüm de nerede hata yaptım,  hata yapmışım.

Baktığım insanlar beni görmüyor,

Seslendiğim kişiler beni duymuyor,

Dokunduğum varlıklar elimde kırılıyor,

Allah’ım kabus mu bu? 

Diktiğim güllerim açmadı,

Ektiğim güller neden diken bitti,

Dost bildiklerim düşmanımmış oysa,

Öyleyse vay anasını be vay anasını.

                          Zafer Özkay (10.04.2003 – Karaman)', 'Baharıma sen yağdırdın karları, Sen soldurdun güllerimi henüz açmadan, Şimdi sen ellerin kolundaysan eğer, Buna yaşarken ölmek derler. Sende...', ARRAY['Türk Edebiyatı','Şiir','Zafer Özkay']::text[], 8.5, '{"poet":"Zafer Özkay","poet_slug":"zafer-ozkay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevdan-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sebep', 'senden-sebep-sirma-mersin-fdy27', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece yalnızlığında

Düş gezgini yüreğimde

Özlem yangını büyütmüşken

Sensizliği soluduğum

Sessiz saatlerde

Zamanı kovalıyorken

Sesinle dağılan

Ruhumu mutluluğa bırakmış...

Yeni güne başlamanın

Küçük bi tebessümle sevinci içindeyim

Senden sebep...

04.11.04', 'Gece yalnızlığında Düş gezgini yüreğimde Özlem yangını büyütmüşken Sensizliği soluduğum Sessiz saatlerde Zamanı kovalıyorken Sesinle dağılan...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senden-sebep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam ve Hayat ve Ölüm', 'adam-ve-hayat-ve-olum-oguzkan-bolukbasi-2euu2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'En yakın sabaha doğru yol alıyorum

İçi sevinç dolu bir mabet bulunduğum yer

Sen benim çocuğumsun hayat

Gözümden bile sakındığım

Ölüm yaşamadığın yerlerde

Hani rengârenk boyalı bir akşam alacasında

Seninle ufka bakarak seni konuşmuştuk

Biraz endişeli

Biraz da gergin

Konumuz geleceğin üzerine hayaller kurmaktı

“Ölüm de benim bir parçam” demiştin

“Ölümü de benden say

Ben sende değil

Sen bende büyüyeceksin” dedin

“Ne muhteşem bir sembiyoz bu

Ne inanılmaz alış veriş

Derin bak

Yüzeyde ışık yansır derinde kırılır

Renklerine ayrışır

Ve renkler 

Bilir misin? 

Aynı hızla yarışır

Ben maviyim”

En yakın sabahlar

Seni benden çalan gecelerde

Derinlerdeyim

Mavinin uzanamadığı zamanlardayım

Gökyüzünde asılı duruyorsun

Bulutlar oyun ediyor

Yaşadığım kadar zamanım olsa

O zaman ölümü senden sayacağım', 'En yakın sabaha doğru yol alıyorum İçi sevinç dolu bir mabet bulunduğum yer Sen benim çocuğumsun hayat Gözümden bile sakındığım Ölüm yaşamad...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/adam-ve-hayat-ve-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garibim Garip', 'garibim-garip-hifzi-ozbekmez-zovmg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'GARİBİM

Felek ayırdı da gonca gülümden

Hasreti beterdir billah ölümden

Kimseler anlamaz benim halimden 

Göçmen kuşlar gibi garibim garip

Fotoğrafın yok ki baksam ağlasam

Gönülden gönüle aksam ağlasam

Hasreti beynime çaksam ağlasam

Kanlı yaşlar gibi garibim garip

Hayalde rüyada ararım seni

Uçan kuşlardan hep sorarım seni

Ne olur sevgilim unutma beni

Bitmez düşler gibi garibim garip

Seni seviyorum delicesine

Canımı yoluna verircesine

Latif aşka geldi haykırdı yine

Aşka açlar gibi garibim garip

04  KASIM  2004 SAAT: 02:30

SAMANYOLU GRUBUNUN 2 KELİME  1 ŞİİR AKTİVİTESİ İÇİN YAZILMIŞTIR 

KELİMELER: FOTOĞRAF /KUŞLAR', 'GARİBİM Felek ayırdı da gonca gülümden Hasreti beterdir billah ölümden Kimseler anlamaz benim halimden  Göçmen kuşlar gibi garibim garip Fot...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/garibim-garip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader Ayırdı', 'kader-ayirdi-hifzi-ozbekmez-du03n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'KADER AYIRDI

Canımın içinde bir can var idi

Şimdi yüzüne de bakamaz oldum

Aşkımız koca dünya dar idi

Şimdi halini de soramaz oldum

Oy beni beni de oy beni beni

Ah kader ayırdı yar seni beni

Güzel saçlarını tarar gezerdim

İnce bellerini sarar gezerdim

Sevdama aklımı yorar gezerdim

Şimdi hayalini  saramaz oldum

Oy beni beni de oy beni beni

Zalimler  ayırdı yar seni beni

Dağları taşları aşar varırdım

Yürümek nedir ki koşar varırdım

Boynuna sarılır murat alırdım

Şimdi yanına da  varamaz oldum

Oy beni beni de oy beni beni

İsterse vursunlar unutmam seni 

29  EYLÜL 2004 SAAT: 08:00', 'KADER AYIRDI Canımın içinde bir can var idi Şimdi yüzüne de bakamaz oldum Aşkımız koca dünya dar idi Şimdi halini de soramaz oldum Oy beni b...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kader-ayirdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölürüm Senin İçin', 'olurum-senin-i-cin-hayrettin-orak-1xnlj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Arıyorum, 

Arıyorum seni gök kubbenin maviliklerinde

Arıyorum seni engin denizlerin derinliklerinde

Arıyorum seni mor dağların eteklerinde

Arıyorum seni Arıyorum.

Bekliyorum, 

Bekliyorum seni suya hasret kurumuş toprak gibi

Bekliyorum seni ana kucağına özlem duyan bir yavru gibi

Bekliyorum seni karanlık dünyamı aydınlatacak ışık gibi

Bekliyorum seni Bekliyorum.

Seviyorum, 

Seviyorum seni leylası için çöllere düşem mecnun gibi,

Seviyorum seni şirini için dağları delen ferhat gibi

Seviyorum seni aslısı için ölen kerem gibi

Seviyorum seni Seviyorum. 

Bitiyorum,

Bitiyorum tutam tutam saçlarına,

Bitiyorum kışımı bahara döndüren sıcaklığına,

Eriyip kül oluyorum ceylan bakışlarına,

Ölürüm senin için Ölürüm....! 

4.11.2004', 'Arıyorum,  Arıyorum seni gök kubbenin maviliklerinde Arıyorum seni engin denizlerin derinliklerinde Arıyorum seni mor dağların eteklerinde A...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olurum-senin-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeşitleme', 'cesitleme-selim-bayrak-mae7o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sokak sokak ser-ser-isi

Dol-aştığın kum-sallara

Solak solak  ger sen ipi 

Bul-aştığın tüm-sekleri

Az ar azar bizimkisi

Öt er öter tesellisi

Su-lamalı yüz-geç çel-tik

Devşir reti, dev şirreti

Kaba hat kabahat

Çala kal em mil-(l) -eti

Top-arlan! Nam-uslu ter-his

Duyar lan! Kes-er-iz...', 'Sokak sokak ser-ser-isi Dol-aştığın kum-sallara Solak solak  ger sen ipi  Bul-aştığın tüm-sekleri Az ar azar bizimkisi Öt er öter tesellisi ...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cesitleme-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yardım Eyle', 'yardim-eyle-hifzi-ozbekmez-0p5zp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'YARDIM EYLE

Azrail pençeyi vurdu

Hayatın gemisi durdu

Unuttum baharı yurdu

Aman Allah yardım eyle

Koydular beni kabir’ e

Sorgular gelir ha bire

Ahretim döner zehir’ e

Aman Allah yardım eyle

Cehennem ateşi yakar

Ruhum bedenimi sıkar

Gözümün yaşları akar

Aman Allah yardım eyle

Latifim yoldan şaşarsam

Haramı seçer koşarsam

Cehenneme de düşersem

Aman Allah yardım eyle

03  EKİM 2004 SAAT: 21:00', 'YARDIM EYLE Azrail pençeyi vurdu Hayatın gemisi durdu Unuttum baharı yurdu Aman Allah yardım eyle Koydular beni kabir’ e Sorgular gelir ha b...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yardim-eyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-sahin-yenilmez-h41mo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bak şu yıldızlara

Şu güzelliğe

Şu harikaya

Hayatın neresinde olursan ol

Görürsün sen istemesen bile.

Sevmek de böyle bir şey

Sen istemesen de

Uçar gider yüreğin herhangi birine

Evet  “Herhangi biri” 

kim olursa olsun.

bu sefer sen açtın gönlümün kapılarını

sen çözdün sevgimin düğümünü

ben böyleyim değişemedim bir türlü,

senin için ölmeye hazırım ama

bir türlü anlatamam bunu sana.

her gelişinde bir şeyler koptu yüreğimden 

gidişini görmezlikten gelip

sanki hiç gitmemişsin sayıp

gelmeni bekledim hep,

her gidişinde bende yok oldum

kanatlanıp uçtu yüreğim ardından.

bir söz değil seni bana yazacak olan

bir söz değil gülüm

bin sözde etsen fayda etmez bazen

ve seni getirecek olan trenin biletleri tükendi şimdiden.

hiç gelmeyeceksin belki bundan sonra

gelme zaten..

ben seni elimde çiçeklerle hep beklerim.

sözümü tutarım bilirsin

bedenimden vazgeçsem de

en güzel çiçekleri sunarım sana

ellerim olmasa bile.

ne kadarını anlatabilirdim ki

seni ne kadar sevdiğimin,

sustuğum her dakika

anlatamadıklarımın aynasıdır aslında.', 'Bak şu yıldızlara Şu güzelliğe Şu harikaya Hayatın neresinde olursan ol Görürsün sen istemesen bile. Sevmek de böyle bir şey Sen istemesen d...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sevgi-145-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durgun', 'durgun-burak-killioglu-zqy82', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlham perisine küstüm.

Ne bir haber getirdi,

Ne fısıldadı seni.

Bundandır 

Sürüp giden suskunluğum...

Aşk acısıyla piştim.

Ne seni hatırlattı,

Ne unutturdu seni.

Sendendir 

Tüm durgunluğum...', 'İlham perisine küstüm. Ne bir haber getirdi, Ne fısıldadı seni. Bundandır  Sürüp giden suskunluğum... Aşk acısıyla piştim. Ne seni hatırlatt...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/durgun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-osman-erdogmus-a0qxg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'DUA

Her mesleğin incedir mahareti,sanatı,

İstemesini bilmek,almanın teminatı.

Ağlamayan çocuğa meme vermez imişler,

Anlatırsan derdini alırsın kainatı.

İsteyin verecektir vadediyor Yaratan,

Almak istemez misin? Sağ elinden beratı.

Duaya kalkan eller geri çevrilir sanma,

Gül bahçesine döner isteyenin hayatı.

Dua aczin simgesi,kulluğun şerefidir,

İstemesini bilen kaldırır mahsulatı.

Müminin silahıdır belaya karşı dua,

İsteyenin daima güzel olur mematı.

Dua yüceltir seni yapan isen ihlasla,

Geçmek istemez misin? Dar günün de sıratı.

Dua etki kararan kalbinde güller açsın,

Komşun olur Muhammed(s.a.v) , karnende şefaatı.

Yalvar yalvar Allah’a eller karıncalansın,

Cemalullahı iste o asıl mükafatı. 

                   Osman Erdoğmuş

                          Aşk İklimi

                kitabından alınmıştır', 'DUA Her mesleğin incedir mahareti,sanatı, İstemesini bilmek,almanın teminatı. Ağlamayan çocuğa meme vermez imişler, Anlatırsan derdini alırs...', ARRAY['Türk Edebiyatı','Şiir','Osman Erdoğmuş']::text[], 8.5, '{"poet":"Osman Erdoğmuş","poet_slug":"osman-erdogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dua-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşuna', 'bosuna-volkan-yoruc-kbp8z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boşuna kurcalama anıları artık

Sevdanı unutulmuş zamanlarda bırak

Atma kendini yerlere işte

Unutulmuş sayılabilirsin

Bir eski defter gibi yırtılıpta atılmış olabilirsin

Unutmaktan başka ne gerekirki

Elden başka ne gelebilirki

Aman bırak işte böylesi acı ümitleri

Dön de bak hayata

Mutluluk gelirde yine bulur seni

Bir tatlı bakışa özlem duyabilirsin

Dokunuşları yine hissedebilirsin

Boşuna kurcalama anıları artık

Elbet gelirde mutlu olursun

Beklemeyi bilmelisin

Gelde unut hadi diyebilirsin

İçinde büyüttüğün çocuğu öksüz kılmamalısın

Sevgi çemberinden dışarı çıkmamalısın

Bilmelisinki hayat devam eder

Döner de gelir yine o ılık mevsimler', 'Boşuna kurcalama anıları artık Sevdanı unutulmuş zamanlarda bırak Atma kendini yerlere işte Unutulmuş sayılabilirsin Bir eski defter gibi yı...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bosuna-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firari sevda', 'firari-sevda-meral-yagcioglu-hbg58', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönlüme bir sevda düştü, kaçıyorum

Gönlümse firari bir sevda peşine, koşuyorum

		11/11/2003', 'Gönlüme bir sevda düştü, kaçıyorum Gönlümse firari bir sevda peşine, koşuyorum 		11/11/2003...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/firari-sevda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte...', 'i-ste-gurcan-talay-tflsa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İşte o gün,

Gittiğinin ardından başladı

Sana dair karabasanlarım.

Acımasız kör delikler,

Karanlık ve yalnızlığım.

İşte o gün,

Sen bende sondun

Ben sende son.

Öyle habersiz

Öyle vedasız.

İşte o günden sonra, 

Sana uyudum gecelerimde,

Sana uyandım sabahlarımda.

Olmadığını bile bile.

Günde bin kez uzandım sana

Bir kez yetişemedim 

Erişemedim senli varlığıma.

İşte o günden sonra, 

Sana akar göz pınarlarım,

Sana söyler duaları dillerim,

Sana bakar aynası kalbimin,

Sensizliktendir özlemlerim.

İşte bu gün,

Sensizlik vurmuşken başıma,

Sen rahat uyu topraklarında.

Yeşiller, renkler sarsın duvarlarını,

Serviler korusun başını

Kızgın güneşlerden.

İşte bu gün,

Sen rahat uyu,

Bil ki özlemler taşsa da  yüreğimden,

İyiyim ben özlemim,

Çok iyiyim.

(Babalar günü 06/2004)', 'İşte o gün, Gittiğinin ardından başladı Sana dair karabasanlarım. Acımasız kör delikler, Karanlık ve yalnızlığım. İşte o gün, Sen bende sond...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Talay']::text[], 8.5, '{"poet":"Gürcan Talay","poet_slug":"gurcan-talay","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/iste-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı dünyaydı', 'adi-dunyaydi-gencay-coskun-xlg4j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeni gelin gibiydi 

Ne kadar süslüydü 

Durduk yerde insanın canı çekerdi 

Dünyaydı 

Beyazdan gelirdi tüm renkleri 

Bittikçe siyaha dönerdi zamanı

Yalanda olsa günleri

Bulaşanları

Hayranları 

Çok olurdu ama

Kalanlarsa

Hep toprak olurdu

Aslında dünya dönmezdi

Dönen sadece bedenlerimizdi', 'Yeni gelin gibiydi  Ne kadar süslüydü  Durduk yerde insanın canı çekerdi  Dünyaydı  Beyazdan gelirdi tüm renkleri  Bittikçe siyaha dönerdi z...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/adi-dunyaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denedim', 'denedim-hasan-can-5v8us', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni sevdimmi acaba? 

Hiç sordunmu bana,

Sevmeye çalıştımmı yada,

İnan alışamadım sana.

Defalarca denedim,

Belki olur dedim,

Sende hep birşeyler aradım,

Denedim inan denedim,

Olmadı yapamadım.

Sevemedim seni.

Keşke aradıklarım sende olsa,

Keşke beni ağlatan sevgin olsa,

Keşke...', 'Seni sevdimmi acaba?  Hiç sordunmu bana, Sevmeye çalıştımmı yada, İnan alışamadım sana. Defalarca denedim, Belki olur dedim, Sende hep birşe...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/denedim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşkın Ördek', 'saskin-ordek-osman-yavuz-i-nal-y861j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırk dört yaşında 

Ve bütün kapıların

dışındayım.

Elimde bir anahtar

Ve önümde

Kırk kapının ipi var.

                 

 (Mart 2004 Ankara)', 'Kırk dört yaşında  Ve bütün kapıların dışındayım. Elimde bir anahtar Ve önümde Kırk kapının ipi var.                    (Mart 2004 Ankara)...', ARRAY['Türk Edebiyatı','Şiir','Osman Yavuz İnal']::text[], 8.5, '{"poet":"Osman Yavuz İnal","poet_slug":"osman-yavuz-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/saskin-ordek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla be iki gözüm', 'anla-be-iki-gozum-sinan-aydindag-sxqsy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün gülmeyecek mi? yüzüm                                              20/06/2003

   Her zaman yaş mı? dökecek iki gözüm

   Bu dert için söylenecek tek sözüm

   Dosttan yara aldım anla be iki gözüm', 'Bir gün gülmeyecek mi? yüzüm                                              20/06/2003    Her zaman yaş mı? dökecek iki gözüm    Bu dert için ...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/anla-be-iki-gozum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demokrasi', 'demokrasi-osman-yavuz-i-nal-flry0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir adım fazla sağa

Olmaz! 

Bir adım fazla sola

Olmaz! 

Bir adım fazla geriye

Hiç olmaz! 

Demokles’in kılıcı gibi

Ne zor şeysin sen DEMOKRASİ.', 'Bir adım fazla sağa Olmaz!  Bir adım fazla sola Olmaz!  Bir adım fazla geriye Hiç olmaz!  Demokles’in kılıcı gibi Ne zor şeysin sen DEMOKRAS...', ARRAY['Türk Edebiyatı','Şiir','Osman Yavuz İnal']::text[], 8.5, '{"poet":"Osman Yavuz İnal","poet_slug":"osman-yavuz-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/demokrasi-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elbet geçecek Sinanım bu zor günler', 'elbet-gececek-sinanim-bu-zor-gunler-sinan-aydindag-91wq6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine isyan günlerinde,yine dertler,yine hüzünler                       20/06/2003

   Benim için açmış yine kanlı güller

   Feryadı figan ötüyor dinle,bülbüller

   Dost ile yar acıyı birlikte verdiler

   Elbet geçecek sinanım bu zor günler.', 'Yine isyan günlerinde,yine dertler,yine hüzünler                       20/06/2003    Benim için açmış yine kanlı güller    Feryadı figan ötü...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/elbet-gececek-sinanim-bu-zor-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapatıyorum artık dünyaya gözlerimi', 'kapatiyorum-artik-dunyaya-gozlerimi-sinan-aydindag-qnuc5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kadere mi? isyan edeyim,yoksa kendime mi?                            21/06/2003

   Hayata mı? küseyim,yoksa kendime mi? 

   Gerçeklere mi? üzületim,yoksa acı sözlere mi? 

   Kaldıramıyorum bunca depremi

   Kapatıyorum artık dünyaya gözlerimi.', 'Kadere mi? isyan edeyim,yoksa kendime mi?                            21/06/2003    Hayata mı? küseyim,yoksa kendime mi?     Gerçeklere mi? ü...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kapatiyorum-artik-dunyaya-gozlerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özür', 'ozur-husnu-celebi-ulu3t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Özür için hata gerekir, 

Suç gerekir, sevdiğini üzmek gerekir. 

Dünya hızlandıkça zaman kısalabilir 

Ama özür dilemek erdemdir.

Sorguladık mı? Kendimizi

Hatalarımızı, suçlarımızı

Ve de sevip de üzdüklerimizi

Her gün yapmıyor muyuz? Bunu

Başkalarını suçlamadığımız bir an

Bir gün olmadığı odlumu? 

Hep suçluyoruz onları

Ya biz, gönülden içten

Kendimizi suçladığımız

Kendimizden özür dilediklerimiz

Oluyor mu? Hiç 

Olmuyor der gibiyim kendime

Nedenini sorguladığım oluyor mu? 

Evet artık sorgulamaktayım

Şimdi artık özür dileme zamanı

Kendimden, sevdiklerimden

Ve tüm üzdüklerimden

Bütün hatalarım için 

Özür diliyorum

Çünkü özür dilemek erdemdir. 

04.11.2004  /  İstanbul', 'Özür için hata gerekir,  Suç gerekir, sevdiğini üzmek gerekir.  Dünya hızlandıkça zaman kısalabilir  Ama özür dilemek erdemdir. Sorguladık m...', ARRAY['Türk Edebiyatı','Şiir','Hüsnü Çelebi']::text[], 8.5, '{"poet":"Hüsnü Çelebi","poet_slug":"husnu-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ozur-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefa', 'vefa-sinan-aydindag-dsi9r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Garip kaldım bir kuş misali dünyada                                        21/06/2003

   Ne arayan var ne de soran öksüzüm buralarda

   Unutulmaması gereken tek şey varsa hayatta

   Vefadır kardeşim oda vefa,vefa.', 'Garip kaldım bir kuş misali dünyada                                        21/06/2003    Ne arayan var ne de soran öksüzüm buralarda    Unut...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vefa-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sir', 'sir-emine-yilmaz-inphp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zaman konussam 

Ne zaman yüregimden geceni dile getirsem 

Aglamak düsüyor payima 

Bombalar yagiyor gecelerime 

Kan ve gözyasi karisiyor avuclarimda 

Bakislarimdaki yangini söndüremiyor yagmur 

Ölümler düsüyor uykuma 

Kiyametler kopuyor icimde 

Hücrelere ayriliyor bedenim 

Anlatilmiyor be gülüm 

''Susma...'' diyorsun 

'' Bu kez izin verme gitmesine! 

Yasamin yarini yok. 

Ne yapacaksan bugün yap! 

Ne diyeceksen simdi de! '' 

Ben bunlari yasamayi istemedim be gülüm 

Sevdadan hep kactim 

Hep kilitledim yüregimi 

Peki niye? 

Niye atesler dolasiyor damarlarimda? 

Neden gerekenler sunuluyor hakkin diye? 

Neden hep yanlis zamanlarda, 

Yanlis sevdalarla yaniyor yürek? 

Bir ben miyim bunun sorumlusu? 

Bir ben miyim aglamasi gereken? 

Ahh be gülüm 

Birde sen gelme üstüme 

Birde sen zorlama 

Belkide benim sabrim bu 

Benim sinavim yüregimdeki mezarlikta sakli! 

Bir sen bil yeter 

Ne olur kimseler duymasin acilarimi 

Agladigimi bilmesinler 

Daha da ötesi kimse acimasin be gülüm 

Bu ikimizin sirri olsun.', 'Ne zaman konussam  Ne zaman yüregimden geceni dile getirsem  Aglamak düsüyor payima  Bombalar yagiyor gecelerime  Kan ve gözyasi karisiyor a...', ARRAY['Türk Edebiyatı','Şiir','Emine Yilmaz']::text[], 8.5, '{"poet":"Emine Yilmaz","poet_slug":"emine-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sir-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başımız hep dik', 'basimiz-hep-dik-sinan-aydindag-euuw4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine yardan geçtik amma dosttan geçemedik                           23/06/2003

   Çok sevmiş olsak ta sevilmedik

   Bir kez olsun doğru insanı seçemedik

   Tek tesellmiz var bu aralar

   Şükürler olsun ki alnımız açık,başımız hep dik.', 'Yine yardan geçtik amma dosttan geçemedik                           23/06/2003    Çok sevmiş olsak ta sevilmedik    Bir kez olsun doğru insa...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/basimiz-hep-dik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Haziran..(şizofren bir yaz)', 'bir-haziran-sizofren-bir-yaz-mehmet-asim-cvrd8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gerçek ve düş arasındaki çizgiyi silmek

Düne doğru yaşamak bir kere daha

Etrafta dönüp duran insanlar

Sabaha kadar düşünülülen bir tek an

Günlerce dilden düşmeyen aynı nakarat

Sarı sayfanın üstünde sarı bir gül yaprağı

Gülümseyen bir yüz

Konuşulmayan zamanları dolduran konuşmalar

Özenle katlanıp sandığa konulan anılar

Beyaz sayfanın üzerinde sarı bir gül yaprağı

''Kızma anne yağmur benimle konuşurken uyuyamazki''', 'Gerçek ve düş arasındaki çizgiyi silmek Düne doğru yaşamak bir kere daha Etrafta dönüp duran insanlar Sabaha kadar düşünülülen bir tek an Gü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Asım']::text[], 8.5, '{"poet":"Mehmet Asım","poet_slug":"mehmet-asim","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-haziran-sizofren-bir-yaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan', 'vatan-erdogan-ergin-q6btj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hikmeti işte toprağın; İçi al üstü yeşil

Anlattılar sana yıllarca, bunlar aslı değil

Çanakkale şahit, Sakarya bunlara delil

Anmadıkça neslini, kalacaksın sefil

Düşen her damlada, binbir acı

Duyulmaz mı Sakarya''nın haykırışı

Kalpler mühürlü, gözler kömür karası

Mehmet''in sesi, duyulmaz gayrı

Titremez namluda eller,Trablus''ta, üşümez

Kalanlara bakarsan, kalbin üzülmez

Seyret ki, asırlık çınar, nasıl devrilmez

Evlat, dedesinden, töresinden vazgeçmez

Unutma, uyutan var oldukça öz vatanında

Sahipsiz kalman, aşikardır Allah yolunda', 'Hikmeti işte toprağın; İçi al üstü yeşil Anlattılar sana yıllarca, bunlar aslı değil Çanakkale şahit, Sakarya bunlara delil Anmadıkça neslin...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/vatan-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sus', 'sus-emine-yilmaz-6x8xa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen yine böyle kal 

Sus 

Kelimeler seni ifade etmez 

Yetmez sevgini anlatmaya… 

Sen sessizligin cocugu 

Yutarsin dilindekileri 

Dilinin ucuna gelenleri 

Yutkunursunda binlerce defa 

Söyleyemezsin sevdigini 

Yada özledigini 

Sen sus 

Hem simdi 

Hem sonsuza kadar 

Cünkü ben gidiyorum 

Sessizlikten siyrilip 

Sevgimi haykirmaya 

Sen yüregine hapsettigin özlemin 

İfade edemedigin sevginle 

Sessiz, mutlu ve bensiz yasa 

Beni bir kez kaybettikten sonra 

Cigliklarinda yetersiz kalacakti nasilsa 

Sen her zamanki gibi yine sus 

Cünkü bu kez ben konusacagim', 'Sen yine böyle kal  Sus  Kelimeler seni ifade etmez  Yetmez sevgini anlatmaya…  Sen sessizligin cocugu  Yutarsin dilindekileri  Dilinin ucun...', ARRAY['Türk Edebiyatı','Şiir','Emine Yilmaz']::text[], 8.5, '{"poet":"Emine Yilmaz","poet_slug":"emine-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sus-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taviz yok güzellere', 'taviz-yok-guzellere-sinan-aydindag-j1ziq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yol çizdim kendime,                                                          28/07/2003

                      İçinde se olmayan

   Bir ben yarattım kendime,

                     Seni hiç düşünmeyen

   Bir de söz verdim kendime,

                     Bundan böyle taviz yok güzellere.', 'Bir yol çizdim kendime,                                                          28/07/2003                       İçinde se olmayan    Bir b...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/taviz-yok-guzellere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı Şehir', 'yabanci-sehir-hasan-can-ugh71', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben bu şehrin yabancısıyım,

Kimsenin tanımadığı bilmediği bir boşluğum,

Sevginin ve güzelliğin gerisine düşmüş bedenim,

Göründüğü halde kör hissi uyandıran misalim.

Hayalleri düştüğü yerden kalkmayan,

Anıların etrafında dans ettiği,

Hatıraların umursamadan silindiği,

Ve beyninin içindeki yalnızlığı,

Hiçbir zaman unutturamayan,

Avutulmamış çocukların avutulmayı bekleyen,

Kuru dudakların anlatmaya çalıştığı gerçeğin,

Sahte ve iki yüzlü menfaatin,

Tuzağına düşmüş kendine arayan kayıbım.

Gerçekleri kimsenin görmediği,

Görmek istemediği gerçeğim.

Sevmek isteyen ancak sevmesine izin verilmeyen,

Aydınlık içinde karanlığa bürünmüş,

Açılmak isteyen fakat açılmayan yelkenim.

Ben bu şehrin yabancısıyım,

Soğuk çok soğuk buz gibi bir alevim,

Başka baharlarda doğmak isteyen güneşim.

İsyan etmeden asi olmadan,

yalnız kalmadan, dalından koparılmadan,

İki yüzlü olmadan, korku salmadan,

Gözleri dolmadan, yaprağı solmadan,

Yalancı yaşamın yalancı dünyanın,

Yalanı olmadan yaşamak isteyen,

Hiçbir zaman duyulmayan,

Duyulsada kimsenin aldırış etmediği bu çığlığı,

Artık duyurmak istiyorum kendimce.

Ama karamsarım korkuyorum.

Yalancı ve sahtekar insanların,

Fısıltıyı çığlığa dönüştürmesi,

Her söylenen yalanın aslında gerçek olması,

Ufacık bir külün aleve dönüşmesi,

Gücüme gidiyor...

Artık bu şehir bana yabancı değil,

Artık bu şehrin bir parçasıyım,

Ama sadece şehir karardığında,

Yaşıyorum ve nefes alıyorum.

Birtek şey istiyorum,

Ufacık küçücük birşey,

Ruhumun bedenimi terketmesini...

06.01.2003', 'Ben bu şehrin yabancısıyım, Kimsenin tanımadığı bilmediği bir boşluğum, Sevginin ve güzelliğin gerisine düşmüş bedenim, Göründüğü halde kör ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/yabanci-sehir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut ki ben hic yasamadim', 'tut-ki-ben-hic-yasamadim-emine-yilmaz-cpzxv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tut ki beni görmedin, sevmedin 

Tut ki ben bir ölüyüm 

Hissedilmeyen, duyulmayan 

Beni yalnizligima birak 

Sokaklarimizi, yemyesil ovalarimizi arama 

Tut ki beni sarmadin, sevmedin 

Tut ki ben bir ölüyüm 

Karanligin ücralarinda 

Buzdan beter olmus bedenim 

Sokak taslarinda 

Tut ki ben hic yasamadim senin dünyanda', 'Tut ki beni görmedin, sevmedin  Tut ki ben bir ölüyüm  Hissedilmeyen, duyulmayan  Beni yalnizligima birak  Sokaklarimizi, yemyesil ovalarimi...', ARRAY['Türk Edebiyatı','Şiir','Emine Yilmaz']::text[], 8.5, '{"poet":"Emine Yilmaz","poet_slug":"emine-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tut-ki-ben-hic-yasamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoklugunda', 'yoklugunda-emine-yilmaz-9es55', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ve senin yoklugunda 

Esi bulunmaz bir izdirap yasiyor su beden 

Bu kör talihimize inat 

İnsan bir veda ederdi gitmeden 

Yikilmis arzularin altinda 

Geceye bekcilik ederken 

Sensin... 

İki damla yas olup gözlerimden süzülen', 'Ve senin yoklugunda  Esi bulunmaz bir izdirap yasiyor su beden  Bu kör talihimize inat  İnsan bir veda ederdi gitmeden  Yikilmis arzularin a...', ARRAY['Türk Edebiyatı','Şiir','Emine Yilmaz']::text[], 8.5, '{"poet":"Emine Yilmaz","poet_slug":"emine-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yoklugunda-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden insanlık yok senin gibi güzellerde', 'neden-insanlik-yok-senin-gibi-guzellerde-sinan-aydindag-ke2b3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıldızlar yine asılı duruyor gökyüzünde                                        28/07/2003

   Güneş yine yok açmıyor gündüzlerime

   Ay ise yine saklanmış karanlıklar içinde

   Bir duygu yükseliyor şu an içimde

   Söylüyorum dinlesende,dinlemesende

   Neden? insanlık yok senin gibi güzellerde.', 'Yıldızlar yine asılı duruyor gökyüzünde                                        28/07/2003    Güneş yine yok açmıyor gündüzlerime    Ay ise y...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/neden-insanlik-yok-senin-gibi-guzellerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görmesin diye', 'gormesin-diye-emine-yilmaz-0squs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kara trene bindirdin beni 

El sallayip yolcu eyledin beni 

Benden gizledin hep o gözlerini 

Yavrum gözyasimi görmesin diye 

Hasret kokan bir kac mektubun geldi 

Buram buram seni bana getirdi 

Karanliktir anam gurbet gecesi 

Kuzular anayi görmesin diye 

Hayalimde gözler hüzünlü nemli 

Gönül her birini öpmek isterdi 

Çekiverin ne olur su perdeleri 

Her gecen halimi görmesin diye', 'Bir kara trene bindirdin beni  El sallayip yolcu eyledin beni  Benden gizledin hep o gözlerini  Yavrum gözyasimi görmesin diye  Hasret kokan...', ARRAY['Türk Edebiyatı','Şiir','Emine Yilmaz']::text[], 8.5, '{"poet":"Emine Yilmaz","poet_slug":"emine-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gormesin-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbini sökmez seni incitmez', 'kalbini-sokmez-seni-incitmez-sinan-aydindag-1a76n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arkadaş güzelliğine kanıpta aldanma                                 28/07/2003

   Baki değildir gelip geçer

   Arkadaş her güzeli insan sanma

   Bir gün bakarsın kalbini söker de gider

   Arkadaş seversenruhu güzeli sev

   Bil ki seni terketmez,hiç olmazsa

   Kalbini sökmez,seni incitmez.', 'Arkadaş güzelliğine kanıpta aldanma                                 28/07/2003    Baki değildir gelip geçer    Arkadaş her güzeli insan sanm...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kalbini-sokmez-seni-incitmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskunluguna dayanamiyorum', 'suskunluguna-dayanamiyorum-emine-yilmaz-ws9o0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Söylenmemis cümleler caldi hayatimi 

Yutulan kelimeler prangaladi ayaklarimi 

Çakilip kaldim 20 sinde bir bataga 

Bende asirlara bedeldi her lahza 

Sende susma gülüm 

Birde sen kelepce takma kollarima 

Sende sürme bir cikmazdan bir diger cikmaza 

Çünkü tahammülüm kalmadi suskunluklara 

Belki ben anlatmada yetersizim 

Belki ben ifade edemiyorum kendimi 

Ama bilki birtenem suskunluguna dayanamiyorum 

Söylenmemis cümleler caldi hayatimi 

Yutulan kelimeler prangaladi ayaklarimi 

Çakilip kaldim 20 sinde bir bataga 

Bende asirlara bedeldi her lahza 

Sende susma gülüm 

Birde sen kelepce takma kollarima 

Sende sürme bir cikmazdan bir diger cikmaza 

Çünkü tahammülüm kalmadi suskunluklara 

Belki ben anlatmada yetersizim 

Belki ben ifade edemiyorum kendimi 

Ama bilki birtenem suskunluguna dayanamiyorum 

Dilinden dökülenlere degil ama 

Yüreginden süzüleceklere ihtiyacim var 

Anliyor musun', 'Söylenmemis cümleler caldi hayatimi  Yutulan kelimeler prangaladi ayaklarimi  Çakilip kaldim 20 sinde bir bataga  Bende asirlara bedeldi her...', ARRAY['Türk Edebiyatı','Şiir','Emine Yilmaz']::text[], 8.5, '{"poet":"Emine Yilmaz","poet_slug":"emine-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/suskunluguna-dayanamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyor musun?', 'biliyor-musun-emine-yilmaz-mtppd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biliyormusun? 

Nefes alamiyorum gittiginden beri 

Düslerim yarim kaliyor 

Arzularim say ki labirent 

Sana ulasamiyorum 

Biliyor musun? 

Günde bin defa ölüyorum yeniden 

Ayriliyor ruhum bedenden 

Acisini bile hissetmiyorum 

Biliyor musun? 

Camlarda ariyorum yüzünü 

Bulutlu gözlerin düsüyor bakislarima 

İki damla yasla 

Uzatiyorum ellerimi sevgili 

Ama silemiyorum', 'Biliyormusun?  Nefes alamiyorum gittiginden beri  Düslerim yarim kaliyor  Arzularim say ki labirent  Sana ulasamiyorum  Biliyor musun?  Günd...', ARRAY['Türk Edebiyatı','Şiir','Emine Yilmaz']::text[], 8.5, '{"poet":"Emine Yilmaz","poet_slug":"emine-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/biliyor-musun-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamaya çabalıyorum', 'yasamaya-cabaliyorum-sinan-aydindag-ypquc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu hayatın bana gülümseyeceği günü bekliyorum                    28/07/2003

   Bir gün olmazsa bir ğün gülecek diyorum

   Şu an bir boşlukta da olsa yaşıyorum

   Ne yediğimden,ne içtiğimden ne de

   Dünyadan zevk almıyorum 

   Elbet bir gün gülümseyeceğini biliyorum

   Onun için,onun için yaşamaya çabalıyorum', 'Bu hayatın bana gülümseyeceği günü bekliyorum                    28/07/2003    Bir gün olmazsa bir ğün gülecek diyorum    Şu an bir boşlukta...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yasamaya-cabaliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani bazen', 'hani-bazen-emine-yilmaz-shcmb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani bazen her soru bir idam sehpasidir 

Sanki son sözlerin sorulur 

Cevaplayacak cesaretin olmaz 

Belki kendini asip söylesen degisecektir cogu sey 

Ama nerde o yürek 

Oysa nasil olsa öleceksin 

Nasil olsa yitecek hersey 

Susma 

Ilk ve son defa 

Bu defa 

Topla cesaretini 

Nasilsa kaybedecek hicbirseyin kalmamis 

Bari pisi pisine gitme 

Bir kez olsun 

Yüregini dök 

Bir kez olsun haykir 

Bir kez olsun yik setlerini 

En azindan yasamim boyunca 

Bir defa 

Gercegi dile getirmis olursun.', 'Hani bazen her soru bir idam sehpasidir  Sanki son sözlerin sorulur  Cevaplayacak cesaretin olmaz  Belki kendini asip söylesen degisecektir ...', ARRAY['Türk Edebiyatı','Şiir','Emine Yilmaz']::text[], 8.5, '{"poet":"Emine Yilmaz","poet_slug":"emine-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hani-bazen-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir beyaz kefenle gideceğiz', 'bir-beyaz-kefenle-gidecegiz-sinan-aydindag-d2o4g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün toprak olup gideceğiz                                                       28/07/2003

   Bu hırs,bu ihanet,bu ikiyüzlülük niye

   Maksat başarılı olmak,

   Maksat para kazanmak ise

   Unutmayın diğer tarafa,bir beyaz kefenle gideceğiz', 'Bir gün toprak olup gideceğiz                                                       28/07/2003    Bu hırs,bu ihanet,bu ikiyüzlülük niye    M...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-beyaz-kefenle-gidecegiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim olduğunu bilmiyorum', 'kim-oldugunu-bilmiyorum-sinan-aydindag-gzal4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine sabahın beşi oldu                                                                02/08/2003

   Hala senin için şiirler yazıyorum

   Yine elimde kağıt kalem senidüşlüyorum

   Yine yüzünün hayali gelmiyor gözlerimin önüne

   Çünkü kim olduğunu bilmiyorum.', 'Yine sabahın beşi oldu                                                                02/08/2003    Hala senin için şiirler yazıyorum    Yin...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kim-oldugunu-bilmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezarıma sarı güller getir', 'mezarima-sari-guller-getir-sinan-aydindag-a76q0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni özlemenin başka bir yolu daha var mı?                       02/08/2003

   Söylesene senin gönlünde de sonbahar mı? 

   Başkalarını da hasretin böyle sarar mı? 

   Söylesene benim olmayan sevgilim.

   Geceleri uykusuz kaldım

   Aç kaldım,susuz kaldım

   Yetmiş milyon içinde öksüz kaldım

   Sayende can evimden yareler aldım

   Bana bunu mu? reva gördün be ellerin olan sevgilim.

   Sensizlikten saçlarım döküldü,

   Dişlerim söküldü

   Yokluğunda gözlerimden hep yaşlar süzüldü

   Ölmeden dudağımdan şu sözler döküldü

   Mezarıma sarı güller getir,yavaş yavaş solan sevgilim', 'Seni özlemenin başka bir yolu daha var mı?                       02/08/2003    Söylesene senin gönlünde de sonbahar mı?     Başkalarını da h...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mezarima-sari-guller-getir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstersen al canımı', 'i-stersen-al-canimi-sinan-aydindag-6bh23', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir telefonunla değiştirdin dünyamı                                    04/08/2003

