INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gıramofon', 'giramofon-i-smet-barlioglu-6s535', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uyan yavrum ta öğlede,

Eşin dostun çayjanede,

İskambiller deste deste,

Hayatın tam gıramofon.

Neyinedir iş güç senin,

Teki sensin şehzadenin,

Baban senin yedirenin,

Hayatın tam gıramofon.

Ne git çalış, ne de kazan,

Evde mangal, gölde sazan,

Çek kafayı bazen bazen,

Hayatın tam gıramofon.

