INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '- A k r e p...v e...Y e l k o v a n....(14)', 'a-k-r-e-p-v-e-y-e-l-k-o-v-a-n-14-metin-eser-wdez3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '..........''Onun için önce ben, çıkıp bir bakınayım'',

..........''Sanki müfettiş gibi, vaziyet takınayım'',

..........''Üç beş dakika sonra, ardım sıra çıkarsın'',

..........''Hee bir de unutmadan, yüzünü de yıkarsın''.

..........''Endişeli bir resim, görüyorum yüzünde'',

..........''Biraz sakinleş derim, şöyle biraz gezinde'',

..........''Gel buraya bak şimdi, caddenin karşısına,

..........''Gördün mü bir iniş var, yeraltı çarşısına''.

..........''Sen arka kapıdan çık, sonra gel ön tarafa'',

..........''Heyy kendine gel artık, at herşeyi bir rafa'',

..........''Vallahi işimiz zor, senin bu hallerinle'',

..........''Vedalaş bence artık, meşhur suallerinle''.

..........''Herşeyin zamanı var, şimdi boş vaktimiz yok'',

..........''Şu durumdan çıkalım, seninle işimiz çok'',

..........''Neyse ne diyordum ben, hee çarşıya inicen'',

..........''Elli metre yürüyüp, bir metroya binicen''.

..........''Buena Park yönüne, gidene binmelisin'',

..........''Ve üçüncü durakta, unutma inmelisin'',

..........''Metrodan çıkar çıkmaz, yolun karşısına geç'',

..........''Seni ordan alırım, birde uygun bir yer seç''.

..........''Meksika sınırında, eski bir dostum vardı'',

..........''Gerçi maddi durumu, son zamanlarda dardı'',

..........''Epeydir görüşmedik, umarım oradadır'',

..........''Belki bir evi vardır, belki de kiradadır''.

..........''Off yine çenem düştü, ayakkabım nerede'',

..........''İnşallah şu polisler, gelmezler bu sürede'',

..........''Hadi canım ben çıktım'' deyip kapıyı açtı,

...........İkisi birbirine, herşeyden çok muhtaçtı,

''Anladım'' dedi adam, ''hadi geç kalmayalım'',

''Üstümüze yeni bir, bela da almayalım'',

Küçük bir öpücükle, dudakları birleşti,

Yine o sıcak duygu, içlerine yerleşti.

İstemeden kesildi, dudakların teması,

Ve kaşlarını çattı, bu sevdanın seması,

Kadın çıktı kapıdan, elde küçük valizle,

Adamsa kalakaldı, bir sürü analizle.

Beklediği sürede, bir bardak su içmişti, 

Sonra saate baktı, beş dakika geçmişti,

Ciddi bir ifadeyle, son kez aynaya baktı,

Ve tanınmamak için, güneş gözlüğü taktı.

Önce bina önüne, camdan bir bakacaktı,

Ve kapıya yönelip, evden de çıkacaktı,

Herşey yolunda derken, zilin sesini duydu,

Hayaline dökülen, bin yılın korkusuydu.

25.Haziran / Los angeles

