INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'B o m b a..! !', 'b-o-m-b-a-seref-yildirim-jjxww', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'etler uçuyor, parçalanıyor,dağılıyor, dökülüyor

ayak.bacak,beyin.kafa,kol demeden….

iniltiler feryatlara, feryatlar can çekişmelere,

can çekişmeler,masum ölümlere dönüşüyor acımasızca

kanlar göllere,denizlere,denizler sellere,

ateşler alevlere,alevler lavlara koşuyor durmaksızın

canlar atomlarına,atomlar moleküllerine ayrıldıkça ayrılıyor

yığın yığın cesetler tanıdık tanımadık dost düşman

toprak ananın bağrında buluşuyor kokmama telaşında, huzurlu…

……………………………..

yanık et kokularının dayanılmazlığında,

sağ kalanlar ağlıyor,feryat figan haykırıyor gökyüzüne

isyanla,çaresizlikle,dehşet dolu gözlerle

yakınlarını arıyor analar,bacılar,dedeler hele de çocuklar…

yaralı yaşadığına,bacağı olan olmayana,gözü gören görmeyene/

acıyor şükrediyor yaratanına kendi varlığında sevinçli…

………………………………

Oysa; 

BOMBA mutlu,vazife aşkında gururlu,/

gürlüyor,patlamalarda coşuyor

hiç bıkmadan emir verenlerine müjdeliyor başarısını..? 

ancak; 

bilseydi eğer; 

insanlık ağlıyor barışın yok oluşuna,

barış ağlıyor savaşın doğuşuna,

atmazdı kendini binlerce masumun üzerine….

06.11.2004

Şeref Yıldırım', 'etler uçuyor, parçalanıyor,dağılıyor, dökülüyor ayak.bacak,beyin.kafa,kol demeden…. iniltiler feryatlara, feryatlar can çekişmelere, can çek...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yıldırım']::text[], 8.5, '{"poet":"Şeref Yıldırım","poet_slug":"seref-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/b-o-m-b-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Kalan Şiirler I', 'yarim-kalan-siirler-i-behcet-gulenay-r4z10', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'VIII

Seni değil 

Seni seveni sevdim

Sana değil

Sana mahkum gözlere yandım

Seni değil

Seni düşleyeni düşledim

Sana değil

Sana çizilen resme ağladım

Seni değil

Seni yazan şairi okudum

Sana değil

Sana gülen gözlere güldüm

Seni değil

Seni uyandıran geceyi dinledim

Sana değil

Sana koklatılan güle dokundum

Seni değil

Seni ele veren ceylan gözleri seyrettim

Gözlerine değil

Alevinde tutuşan yangına düştüm ben

             Mart 2000

Behçet Gülenay', 'VIII Seni değil  Seni seveni sevdim Sana değil Sana mahkum gözlere yandım Seni değil Seni düşleyeni düşledim Sana değil Sana çizilen resme a...', ARRAY['Türk Edebiyatı','Şiir','Behçet Gülenay']::text[], 8.5, '{"poet":"Behçet Gülenay","poet_slug":"behcet-gulenay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yarim-kalan-siirler-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyutulmaz Aşk Şiiri', 'uyutulmaz-ask-siiri-umut-ulbegi-n8puf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Otel odandasın

Geceye sırtını dönmüş uyuyorsun

Şehrin sessizliği örtmüş ışıkları

Rüyandayım

mırıldanıyorsun

Yanında olamadığımdan

uykularına girmek için

uyumuyorum

her gün yeni senaryolar

yazıyorum

yönetiyorum

oynuyorum

Bak bu gece de rüyandayım

gülümsüyorsun

Evimdeyim

Geceyi içimde büyütüyorum

Hiç uyumayan şehrin bulaştırdığı

uykusuzluğu taşıyorum

Bu şehirde nasıl uyuduğunu hatırlamayan

iki sevgili 

başka şehirlerde şimdi

Bak bu gece yapayalnızım

yaşamıyorum.', 'Otel odandasın Geceye sırtını dönmüş uyuyorsun Şehrin sessizliği örtmüş ışıkları Rüyandayım mırıldanıyorsun Yanında olamadığımdan uykularına...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/uyutulmaz-ask-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur, Gece ve Sen', 'yagmur-gece-ve-sen-umut-ulbegi-yjy98', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmur

Gidişlerinin takipçisi

son gidişinden beri

sürükleniyorum

Beni seller alıyor

Gece

kalanın katili

Güneşin her batışında

vuruluyorum

Beni yalnızlık öldürüyor

Aşk

çelik ve pamuk

her sevda sözcüğünde

daha sıkı tutunuyoruz

Bizi aşkı bilmez yollar ayırıyor.', 'Yağmur Gidişlerinin takipçisi son gidişinden beri sürükleniyorum Beni seller alıyor Gece kalanın katili Güneşin her batışında vuruluyorum Be...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yagmur-gece-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökkuşağının Ayak İzi', 'gokkusaginin-ayak-i-zi-umut-ulbegi-828uj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerimi kapattığımda 

ne gördüğümü mü öğrenmek istiyorsun

yoksa

aklımdan geçenlerle

yolumdan geçenlerin

ne kadar uzak olduğunu mu? 

Kalbim bomboş

Gözlerim kanıyor

alacakaranlık

yapraklarım yok oluyor ruhumun bataklığında

Bedenini yollara salıvermek

ne kadar kolay

sevgini boşluğa bırakmak

ne kadar zor

ne kadar acı

Ölüyorum, ölüm dar

nefes alıyorum

gökyüzüne sor

acı çekiyorum

Hatalarımın yüzüme vurulması

takvim yapraklarında

yanlışlarımın yüzüme tükürmesi

gücüme gidiyor.

Şimdi anladın mı? 

Aklımdan geçenlerle

senden geçenlerin

yolumdan çok uzak olduğunu

Anladın mı

gökkuşağının ayak izi.

12 Ocak 1997 İZMİR', 'Gözlerimi kapattığımda  ne gördüğümü mü öğrenmek istiyorsun yoksa aklımdan geçenlerle yolumdan geçenlerin ne kadar uzak olduğunu mu?  Kalbim...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gokkusaginin-ayak-izi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönemsel Ağlamalar...', 'donemsel-aglamalar-i-brahim-ethem-bingul-1q38i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bebek ağlar, ağrısını diyemez

Ağrıları onu ağlatır durur

Bebek ağlar, ağlamadan edemez

Sancılar içinde ağlarken uyur...

Çocuk ağlar, istediği oyundur

Ya da oyuncak çocukça bir tutku

Bir çocuğu basit şeyler ağlatır

Ağlamalar çocuklarda tükenmez...

Gençlik çağı genç fidanı ağlatır

Sevda fırtınası eserken onda

Zaman zaman ümitsizlik ağlatır

Âşıkta ağlama zannımca bitmez...

Gençler, genellikle kalp sancısından

Yaş dökerler karşılıksız duygudan

Uykusu kaçan genç ağlar, sabahlar

Aşk çeşmesi su akıtmaz, o ağlar...

Evlilikte kıskançlıklar ağlatır

Düşüncesiz her davranış ağrıdır

Geçim derdi, duygu farkı ağlatır

Günler gelir geçer, zaman ağlatır...

İhtiyarlık döner dolaşır gelir

Bu çağda pek çok şey ağlar, ağlatır

Geçmişteki yanlışlıklar yakarken

Geleceği hatırlamak ağlatır...

Güç gider, takati kalmaz kişinin

Ne kadar zoru var, basit işinin

Biri, bir söz der de, zahirde şirin

Sızı olur bu söz onu ağlatır...

İhtiyarlık kalbe dertleri yığar

Dertler bu olgunu içten yaralar

Bu çağda ihtiyar kalbiyle ağlar

Her gün bir başka dert ağlatır durur...

Bu dünya ağlamak yeri ki zahir

Bebekler doğarken, insan yaşarken

Her varlık kendince son demlerinde

Ölürken, hayattan giderken ağlar...

Sizler de ağlayın hiç çekinmeyin

Sakız edin ağrıları çiğneyin

Bekleyin, özleyin, kederlenmeyin

Gülmenin de bir zamanı, vakti var...

Kimi odun gibi ne güler, ağlar

Kimileri kalpten ah eder ağlar

Kimi ağlamanın pınarı olur

Kimi benim gibi gülerken ağlar...', 'Bebek ağlar, ağrısını diyemez Ağrıları onu ağlatır durur Bebek ağlar, ağlamadan edemez Sancılar içinde ağlarken uyur... Çocuk ağlar, istediğ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/donemsel-aglamalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençlik!', 'genclik-mustafa-celebi-cetinkaya-qh77f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neler oldu böyle gençlik başıboş

Yirmisini geçmiş hala yaşı boş

Kahve köşelerinde ring atıyoruz

Okeye dönüyor boşa batıyoruz

Birileri kurmuş ya, paslı bu çarklar

Fuhuş yuvası olmuş bahçeler parklar

İşsizlik ayrı bir dert, okumak boşa

Böyle batırıldık; çamura, taşa,...

On Sekizinde Fatih biz değil miydik? 

Korkak Avrupalı önünde eğilir miydik? 

Modern bir silah, kurşunlar çağdaş

Bizim kültürümüze kurdular bağdaş

Şimdi hiç peşindeyiz  gideriz yoka

Kızlar  pantolon giyer, erkekler toka

Kan ağlar coğrafyam, tarih kan ağlar 

Boynu bükük ve mahsun kalır zamanlar

Yürekler sağır olmuş fiikirler ama 

Devirdiler çınarları  kıydılar çam'' a

Değişmeli düzen, değişmeli gün

Töreden,kültürden vermeden ödün

Çelebi''m farklı ol, farkları göster,

Ataların senden bir zafer ister. 

05 Temmuz 2004 16:48

12. Cadde Demetevler', 'Neler oldu böyle gençlik başıboş Yirmisini geçmiş hala yaşı boş Kahve köşelerinde ring atıyoruz Okeye dönüyor boşa batıyoruz Birileri kurmuş...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çelebi Çetinkaya']::text[], 8.5, '{"poet":"Mustafa Çelebi Çetinkaya","poet_slug":"mustafa-celebi-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/genclik-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçsam', 'ucsam-behcet-gulenay-xhyr9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yorulmayan iki kanadım olsa

Mırıldanan şu ağaçlara

Uykudan uyanmayan taşlara

Gülen güle konmadan uçsam

Şarkısını bitirmeyen dereye

Söğüt ağaçlarına aldırmadan

Ormanların cıvıltısını özlemeden

Yükseklere, çok yükseklere uçsam

Hiç uyumadan uçsam

Ninelerin masallarıyla uyuya kalan

Oynayan, dövüşen çocukları

Hep seven, seven çocukları seyretsem

Yuvasız kuşlar gibi

Sükunetim içimde

Lakin yuva derdine düşmeden

Uçsam başka dünyalara

Uçsam mavi denizlerin üzerinden

Uçsam gecelerin karanlığına

Uçsam gökyüzüne, yıldızlara

Uçsam uçsam ve hep uçsam

                                                    1998

Behçet Gülenay', 'Yorulmayan iki kanadım olsa Mırıldanan şu ağaçlara Uykudan uyanmayan taşlara Gülen güle konmadan uçsam Şarkısını bitirmeyen dereye Söğüt ağa...', ARRAY['Türk Edebiyatı','Şiir','Behçet Gülenay']::text[], 8.5, '{"poet":"Behçet Gülenay","poet_slug":"behcet-gulenay","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ucsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokaklara Karıştım', 'sokaklara-karistim-behcet-gulenay-efwcl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üzerimde bir deli gömleği

Cebinde dilencilerden çaldığım parayla

Sokaklara karıştım

Sokaklar sağır, sokaklar dilsiz

Sokaklar çıplak, sokaklar üşüyor

Uykusu kaçan bir hasta gibi kusuyor sokaklar

Sokaklar; bu kadar pervasız

Bu kadar korkutucu olmayın ne olur

Lambalarınızı ben taşlamadım 

Karanlıktır bir kapı açın gözlerime

Ve şarkı yasağı olan bir ülkede

Sokaklara karıştım

Kalabalığında yalnız

Yüzyıl önceden haberler bildiriyor taş duvarlar

Kurşunların gölgesinde

Oğlu kaybolmuş bir annenin

Kilitli bir kapı gibi duran gözlerine sığınıyor

Tüm çocuklar

Ölümlerle örseleniyor yarınları

Kaç kez vurulduğunu kimse bilmiyor

Son bir defa yaşamak için parçalanmış vücutların

Hırsıza alkış tutulurken

Hırsıza malını çaldırmanın suçuyla kırbaçlanıyorlardı

Sırtlarından insanlar

Sokaklara karıştım

Uzatılan eli reddederken

Eller gördüm yardıma muhtaç

Düştükçe güçleniyordu

Umutları uçurumların kenarında

Oyun çocuğu dizlerinde(n)   yaralı*

Bir de vurulmuş gençlikler vardı

Özgürlüğü sırtına vurup özgürlüğü olmayan

Kerpiçten bir evin duvarına iz bırakıyordu

Avuçlarından akan kırmızı mürekkepler

Ben sokaklara tutsak annelerden öğrendim ağlamayı

Her köşe başında tekmelenen

Dudaklarımda her dilden bir türkü

Yürüyorum

Basıldı, kural dışıdır adımlarım

Susuyorum

Kural dışıdır sessizliğim

Tüm sesler duvarların nefesinde

Öfkeden karaya çalıyor bugün

Ve şarkı yasağı olan bir ülkede

Sokaklar sevdalara gebe

Sevdalara aykırı bir duraktır

                                                3-6 Ekim 2000

Behçet Gülenay', 'Üzerimde bir deli gömleği Cebinde dilencilerden çaldığım parayla Sokaklara karıştım Sokaklar sağır, sokaklar dilsiz Sokaklar çıplak, sokakla...', ARRAY['Türk Edebiyatı','Şiir','Behçet Gülenay']::text[], 8.5, '{"poet":"Behçet Gülenay","poet_slug":"behcet-gulenay","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/sokaklara-karistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hediyen Oldu', 'hediyen-oldu-ozgen-topcu-laxyh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gençliğimi feda ettim uğrunda

Uykusuz geceler hediyen oldu

Ömrüm son bulacak senin yolunda

Dinmeyen acılar,hediyen oldu

Seninle tanıdı saçım akları

Yokluğun içimde cam kırıkları

Yaşarken kaderim ayrılıkları

Gözümdeki yaşlar,hediyen oldu

Yaralı gönlüme sevda kattığım

Aşkına düşüpte dibe battığım

Her akşam kapında nöbet tuttuğum

Islak kalşdırımlar,hediyen oldu

İğneli bu sevda hemde köşeli

Kanatır çıkmıyor mayın döşeli

El ele göz göze mutlu neşeli

Siyah beyaz mazi,hediyen oldu', 'Gençliğimi feda ettim uğrunda Uykusuz geceler hediyen oldu Ömrüm son bulacak senin yolunda Dinmeyen acılar,hediyen oldu Seninle tanıdı saçım...', ARRAY['Türk Edebiyatı','Şiir','Özgen Topçu']::text[], 8.5, '{"poet":"Özgen Topçu","poet_slug":"ozgen-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hediyen-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VEDA ZAMANıM', 'veda-zamanim-mustafa-celebi-cetinkaya-cmbf0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 've gidiyorum dostlar

yerime bir can bırakıyorum asi 

veda zamanı gelmişti aslında

ay ekim gün cumartesi...

Allah aşkına kal demeyin bana

yeter: çekeceğimiz acıyı çektik

bir tufan koptu sabahın peşi sıra

ve her güneş batışına bir umut ektik. 

...

bağlasanız durmam gayrı bu diyarda

ne gece geceye benzer; ne gündüzde aydınlık! 

hiç bir türküye yazılmamış yaşananlar

evrene itimat ettik; Aldandık! 

sizlere bir umut bırakıp yıpranmış 

ve umut ki gözyaşımla süzülür

toplar tacımı tarağımı bir hışımla giderim

ve gidişime bir annem üzülür. 

ve gidiyorum....

yerime bir can bırakıyorum asi

veda zamanı çoktan dayanmıştı umutlara

ay ekim gün cumartesi.......

23 Ekim 2004 Cumartesi

_____SEVDAZAN_____', 've gidiyorum dostlar yerime bir can bırakıyorum asi  veda zamanı gelmişti aslında ay ekim gün cumartesi... Allah aşkına kal demeyin bana yet...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çelebi Çetinkaya']::text[], 8.5, '{"poet":"Mustafa Çelebi Çetinkaya","poet_slug":"mustafa-celebi-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/veda-zamanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldim', 'geldim-i-brahim-atilmis-p25b6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'geldim yoktun

belki biraz gec kaldim ama

sen yoktun! 

oysa ne heyecanlar getirmistim yuregimde

oysa ne heyecanlar

sen yoktun

geldim

ve bekledim de seni onca zaman

sen yoktun

dunden kalan anilarla

ve yarinin umutlariyla gelmistim oysa

sen yoktun.

anlamalisin artik beni

muhtacligim sana degil aslinda

askina

askina gelmistim bin bir zorlukla

sen yoktun.

simdi gitme vakti geldi catti

ama gidemedim hic bir yere

seninleyim dolu dolu

seninleyim umarsiz ve ciplak

sen yoktun

cekip gidersemde eger

sakin ola kizma bana

cunki

ben geldim

sen yoktun

sen aslinda hic yoktun...', 'geldim yoktun belki biraz gec kaldim ama sen yoktun!  oysa ne heyecanlar getirmistim yuregimde oysa ne heyecanlar sen yoktun geldim ve bekle...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Atılmış']::text[], 8.5, '{"poet":"İbrahim Atılmış","poet_slug":"i-brahim-atilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/geldim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arıyorum...', 'ariyorum-mesut-cakir-a1szz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'karmakarışık duygularla,

geçmeyen,

geceler boyunca,

beynimi kemiren,

sonsuz bir zaman tünelinde...

düş ışığını yakalamak,umuduyla...

her türlü hilekarlığın,sahtekarlığın,

acıların baş gösterdiği,

çilekeş yaşamda,

yılmadan,çabalayarak...

düştükçe daha hırslı ve azimli,

akan her kan pıhtısının,

vazgeçilmez amacıma vesile olduğu

bu serseri şehirde...

kaybolan benliğimi arıyorum...', 'karmakarışık duygularla, geçmeyen, geceler boyunca, beynimi kemiren, sonsuz bir zaman tünelinde... düş ışığını yakalamak,umuduyla... her tür...', ARRAY['Türk Edebiyatı','Şiir','Mesut Çakır']::text[], 8.5, '{"poet":"Mesut Çakır","poet_slug":"mesut-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ariyorum-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Akşam Çık Gel', 'bu-aksam-cik-gel-ozgen-topcu-1jmv4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayalin yetmiyor,düşün yetmiyor

Nerdesin birtanem,bu akşam çık gel

Bu hayat sensiz hiç iyi gitmiyor

Nerdesin çiçeğim,bu akşam çık gel

Öyle sefilimki,öyle kimsesiz

Bir garip köşede yaşarım sensiz

Gözümde yokluğun damlarken sessiz

Nerdesin sultanım bu akşam çıkgel

Anılar soruyor gittiğin yeri

Şarkılar söylüyor mutlu dünleri

Suskunum gittiğin o günden beri

Nerdesin ceylanım bu akşam çık gel

Şimdi yağmurlarda masum bedenim

Yaşamak için yok hiç bir nedenim

Sen yanımda yoksan ben ne ederim

Nerdesin sevgilim bu akşam çık gel', 'Hayalin yetmiyor,düşün yetmiyor Nerdesin birtanem,bu akşam çık gel Bu hayat sensiz hiç iyi gitmiyor Nerdesin çiçeğim,bu akşam çık gel Öyle s...', ARRAY['Türk Edebiyatı','Şiir','Özgen Topçu']::text[], 8.5, '{"poet":"Özgen Topçu","poet_slug":"ozgen-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-aksam-cik-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk haber...', 'i-lk-haber-mesut-cakir-75p3z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'harap, yıkık bir kentte,

her yerde benim olduğu,

hiç bir yerde benim olmadığı...

sessiz sedasız sokaklarda,

geceler boyu,

seni ararım,biliyormusun? 

dün gece bir ağaç seni görmüş,

gökyüzünde beyaz bir elbise içinde.

kanatlanarak bu kente gelmişsin...', 'harap, yıkık bir kentte, her yerde benim olduğu, hiç bir yerde benim olmadığı... sessiz sedasız sokaklarda, geceler boyu, seni ararım,biliyo...', ARRAY['Türk Edebiyatı','Şiir','Mesut Çakır']::text[], 8.5, '{"poet":"Mesut Çakır","poet_slug":"mesut-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ilk-haber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Yaşıyorum', 'seninle-yasiyorum-ozgen-topcu-1nfbw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uyku girmez gözüme

Girsede sıçrıyorum

Her sabahı uykusuz

Seninle açıyorum

Çöz bu zor bilmeceyi

Bitir bu işkenceyi

Ben her günü geceyi

Seninle yaşıyorum

Bomboş kaldı bak elim

ismine köle dilim

Yoksun ama zır delim

Seninle yaşıyorum

Hayalın gitmiyorki

Beni terketmiyorki

Hasretin bitmiyorki

Seninle yaşıyorum

Sensizken üşüyorum', 'Uyku girmez gözüme Girsede sıçrıyorum Her sabahı uykusuz Seninle açıyorum Çöz bu zor bilmeceyi Bitir bu işkenceyi Ben her günü geceyi Seninl...', ARRAY['Türk Edebiyatı','Şiir','Özgen Topçu']::text[], 8.5, '{"poet":"Özgen Topçu","poet_slug":"ozgen-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seninle-yasiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Balığı', 'ay-baligi-selim-bayrak-pk5kq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ay balığı kadar 

Soğuk ve sıcaktır Karadeniz

Karanlığın usultusunda

Alacalı bulacalı yansısını

Batık gemi sanırlar

Antika sevdası bu güne taşınmaz gelirse

Ya da cevherin batmış olanı

Çıkarılmadığı sürece mühim değilse

Ben gönlünün ufku boyunca 

Gezinmeye başladım

Ne olur bu kadar çabuk

Seyrimden silinme

2001 - İstanbul', 'Bir ay balığı kadar  Soğuk ve sıcaktır Karadeniz Karanlığın usultusunda Alacalı bulacalı yansısını Batık gemi sanırlar Antika sevdası bu gün...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ay-baligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözüne sokacağım', 'gozune-sokacagim-ozgen-topcu-xga87', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu defa dönmeyeciğim

Unutamam yaptığını

Bağrıma basacağım

Sevgini yokluğunu

Kendimi yakacağım

Senide yıkacağım

Doymadığın dünyayı

Gözüne sokacağım

Kendimi atıp yollara

Saklanacağım yıllara,

Nasıl olsa kavuşmak zor

Dalacağım anılara

Belki yanlız yatacağım

Belki resmin yırtacağım

Ama o mektupları

Gözüne sokacağım', 'Bu defa dönmeyeciğim Unutamam yaptığını Bağrıma basacağım Sevgini yokluğunu Kendimi yakacağım Senide yıkacağım Doymadığın dünyayı Gözüne sok...', ARRAY['Türk Edebiyatı','Şiir','Özgen Topçu']::text[], 8.5, '{"poet":"Özgen Topçu","poet_slug":"ozgen-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozune-sokacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tıpış Tıpış Döneceksin', 'tipis-tipis-doneceksin-ozgen-topcu-4ya93', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün sendeki sevgimi

Kapış kapış edeceksin

Bittiğini görüncede

Tıpış tıpış döneceksin

Derin bir boşluk içinde

Uçurumdan düşeceksin

Çıkar yol bu deyipte

Tıpış tıpış döneceksin

Tenin beni arayacak

Yokluğumu göreceksin

Gizli gizli ağlayacak

Tıpış tıpış döneceksin

Dizlerime kapanacak

Ellerimi öpeceksin

Hayat seni korkutacak

Tıpış tıpış döneceksin

Diz çökerek önümde 

Beni affet diyeceksin

Biliyorum en sonunda

Tıpış tıpış döneceksin

Yine beni seveceksin', 'Bir gün sendeki sevgimi Kapış kapış edeceksin Bittiğini görüncede Tıpış tıpış döneceksin Derin bir boşluk içinde Uçurumdan düşeceksin Çıkar ...', ARRAY['Türk Edebiyatı','Şiir','Özgen Topçu']::text[], 8.5, '{"poet":"Özgen Topçu","poet_slug":"ozgen-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tipis-tipis-doneceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey Karanlık', 'hersey-karanlik-hasan-can-5i1dv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayatımı karanlıklarla yaşıyorum,

Karanlıklarla sürdürüyorum.

Etraftaki insanlar karanlık,

Dünya karanlık,

Ben karanlık,

Herşey karanlık.

Göremiyorum hiçbir şeyi,

Ne izini ne cismini.

Tanıyamıyorum kendi sokağımı,

Güle oynaya koştuğum yolları.

Arasam da bulamıyorum eski günleri.

Dert keder diz boyu,

Nereye gitsem peşimde.

Eski sokağımı özledim,

Aydınlık dünyamı özledim.

Şaşkınım nereye gideceğim bilmiyorum.

Uyanmak istiyorum artık.

Karanlık beni boğuyor.

Sityem ediyorum karanlık geçen dakikalara.

Yüreğimi yakacağım artık,

Aydınlığı bulmak için yanacağım,

Sonumu bulacağım,

Sonum aydınlık olacak...', 'Hayatımı karanlıklarla yaşıyorum, Karanlıklarla sürdürüyorum. Etraftaki insanlar karanlık, Dünya karanlık, Ben karanlık, Herşey karanlık. Gö...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hersey-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmedimi', 'yetmedimi-hasan-can-h8a8l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ellerin soğuk,

Gözlerin sağır bakıyor.

Dudakların titrek,

Yüreğin derin yakıyor.

Ateşin kül olmuyor,

Derdim hiç bitmiyor,

Başımda acılar esiyor,

Yokluğun içimde eriyor.

Kula kulluk eder oldum,

Sana düşman gibi sırtımdan vuruldum,

Hergün biraz daha tükendim,

Fırtınalar koptu yerlebir oldum.

Yetmedimi bunca keder,

Bitmedimi bu ızdırap bu dertler,

Neden hep bu kalp acı çeker,

Hasretim dön artık yeter.', 'Ellerin soğuk, Gözlerin sağır bakıyor. Dudakların titrek, Yüreğin derin yakıyor. Ateşin kül olmuyor, Derdim hiç bitmiyor, Başımda acılar esi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yetmedimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzümdeki Tebessüm..', 'yuzumdeki-tebessum-aygul-ece-2bq31', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ses duydum,

Bir nefes gibi

...........Can gibi

Gün görmez düşlerimde 

.......Çıkıp gelen bir umut gibi

Sensiz geceler meşum

Gündüzler cehennem

Senli cennet

Gündüzleri ısıtan güneş

Yolumu aydınlatan ışık,

Gecemin konuğu,

Yalnızlığımın düşmanı

..................Hoş geldin.

Sen geldin.

Hayat çiçek açtı.

Sevdamız yeşillendi.

Yüzüm asiliğini bıraktı, toprağa

.........................Hoş geldin.', 'Bir ses duydum, Bir nefes gibi ...........Can gibi Gün görmez düşlerimde  .......Çıkıp gelen bir umut gibi Sensiz geceler meşum Gündüzler ce...', ARRAY['Türk Edebiyatı','Şiir','Aygül Ece']::text[], 8.5, '{"poet":"Aygül Ece","poet_slug":"aygul-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yuzumdeki-tebessum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misketini Dünya Sanan Çocuk', 'misketini-dunya-sanan-cocuk-orhun-basat-v7jup', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I

yorgun bir gecenin ardından

yüzü kirli bir sabaha uyandım 

duvara bir resim gibi çizdiğim 

- aslinda olmayan - penceremin 

üstünü iyice karaladım 

süpürdüm odamda kalmış ayak izlerini 

gölgeni / gözlerimden usulca kovaladım

yakamoz renkli bir güvercin uçtu 

kaçıp gitmek istedim - kendi - içimden

olmadığın hiç bir şehre ısınamadım 

II

avuçlarımdaydı hep

en ufak soluğunda alaza çalan

bir sevdanın közleri 

ilk kalp krizi değildi bu gecenin 

ne de son ağlaması 

kan çanağıydı yıldız gözleri 

bir adak mumu kadar ömrüm

ergüvan bir şarkı ayrılık

uzatsam denize

bir çölde kaybolur ellerim 

bilir misin 

kaç aşk ödedim sana karşılık

III

söz etme / sevda bir yalan

sen de bir yalansın düpedüz

kapandı sana çıkan yollarım 

gecenin her yanı diken patikalar

her  (y) anım güz

IV

ne gündüzün farkındayım 

ne gecenin / ne saatin 

barışığım karanlığımla

ışığı sevse

bedenin dışında yaşardı tin..

V

kayıp tanrıların kamçıları sevda dediğin 

havai fişek duygular

ya da dinsiz bir tanrıya yapılan kulluk

ben...

gazoz kapağını para 

misketini dünya sanan çocuk...', 'I yorgun bir gecenin ardından yüzü kirli bir sabaha uyandım  duvara bir resim gibi çizdiğim  - aslinda olmayan - penceremin  üstünü iyice ka...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/misketini-dunya-sanan-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Bir Yaşam', 'olu-bir-yasam-hasan-can-t4loi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugünlerde yaşamak ölüm gibi sanki bana,

Ne için yaşıyorum ki şu fani dünya da.

Kurduğum hayaller boş,

Gördüğüm rüyalar yalan,

Sevgi zaten haram.

Aşık olmak bana göre değil,

Dostlar uzakta,

Acılar peşimde.

Güneş doğmaz oldu sabahıma,

Artık kuşlar konmuyor pencereme,

Okuduğum şiirler bile anlamsız geliyor.

Hani derler ya yaşayan ölü,

O misali işte,

Ölü bir yaşam yani,

Nereye kadar gider ki.

Bu misal gerçeğe götürür beni.

Suskunum konuşmuyorum artık,

bekliyorum ne zaman gelirse gelsin,

Alsın götürsün beni,

Götürsün ki kurtulayım bu bekleyişten...', 'Bugünlerde yaşamak ölüm gibi sanki bana, Ne için yaşıyorum ki şu fani dünya da. Kurduğum hayaller boş, Gördüğüm rüyalar yalan, Sevgi zaten h...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olu-bir-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Bedeli', 'sevginin-bedeli-hasan-can-yb1cn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birkez sevmiştim,

Ve bedelini ağır ödedim.

Sadece sevmiştim,

Bedeli ne olabilir ki,

Terkedilmekten başka,

Yalnız kalmaktan başka,

Ne bedel ödeyebilir ki seven.

Çaresizlik bedeninden ter olup akar,

kendini yollara vurur seven,

Gidecek yeri kalmaz.

Bir avuntu bekler,

Çıkar yol bulamaz,

Kimse aradığı şeyi ona veremez.

Bir sevgi nelere maloldu,

Oysa sevmek nekadar güzel,

Ne kadar kutsal bir duygudur.

Kimi sevdin be gönül,

Kime kaptırdın kendini,

Neden bu acı niye,

Sevmek bu kadarmı zor 

Bu kadarmı işkence...', 'Birkez sevmiştim, Ve bedelini ağır ödedim. Sadece sevmiştim, Bedeli ne olabilir ki, Terkedilmekten başka, Yalnız kalmaktan başka, Ne bedel ö...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevginin-bedeli-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Işığı', 'ay-isigi-hasan-can-xulfm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yokluğunda yıldızlar bile,

Ağladı durdu sensizliğe.

Ay ışığıyla beraber,

Gecenin karanlığında,

Bir tebessüm bekledim,

Sabaha kadar...

Ve sabaha kadar,

Seni bekledim,

Ay ışığıyla beraber...', 'Yokluğunda yıldızlar bile, Ağladı durdu sensizliğe. Ay ışığıyla beraber, Gecenin karanlığında, Bir tebessüm bekledim, Sabaha kadar... Ve sab...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ay-isigi-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmasın...', 'olmasin-hasan-can-el583', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dostlarım eksik olmasın,

Aşklarım yarım kalmasın,

Gençliğim duman olmasın,

Kaderim yalnızlık olmasın...', 'Dostlarım eksik olmasın, Aşklarım yarım kalmasın, Gençliğim duman olmasın, Kaderim yalnızlık olmasın......', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olmasin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Kötü Ne Olabilir Ki', 'daha-kotu-ne-olabilir-ki-hasan-can-k8tny', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevilmeden sevilmek kadar,

Hasret kadar,

Yalnızlık kadar,

Yaşamı bilmeden yaşamak kadar,

Kötü ne olabilir ki.

Acı çekmek kadar,

Ömrün tükendiği kadar,

Seven kalbin sustuğu kadar,

Kötü ne olabilir ki.

Sefalet kadar,

Yoksulluk kadar,

Severek ayrılmak kadar,

Kötü ne olabilir ki.

Sensiz geçen günler,

Sensiz sönen umutlar,

Sensiz her dakika kadar,

Daha kötü ne olabilir ki...', 'Sevilmeden sevilmek kadar, Hasret kadar, Yalnızlık kadar, Yaşamı bilmeden yaşamak kadar, Kötü ne olabilir ki. Acı çekmek kadar, Ömrün tükend...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/daha-kotu-ne-olabilir-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-hasan-can-g6bgp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnız kaldığım her dakika,

Ve yaln ız kaldığım her anda,

Düşünüyorum ve kendimi,

Uçurumun kenarında buluyorum.

Hayalinle yaşamak istemiyorum artık,

Sadece gerçeğin bana vereceği,

Mutluluğu bekliyorum,

Seni seviyorum...', 'Yalnız kaldığım her dakika, Ve yaln ız kaldığım her anda, Düşünüyorum ve kendimi, Uçurumun kenarında buluyorum. Hayalinle yaşamak istemiyoru...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-seviyorum-217-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum', 'bilmiyorum-hasan-can-b8rq0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gece yarısıydı,

Sokaklarda ıssız bir sessizlik vardı.

Gece olmasına rağmen,

Ay doğmamıştı.

Neyin peşindeydim bilmiyorum,

Geceyimi sok seviyordum,

Yoksa dalgın bir bakışmıydı.

Aradığım şeyin ne olduğunu bilmiyorum,

Ne yapıyorum gecede bilmiyorum,

Nereye gidiyorum niye,

Neden yaşıyorum bilmiyorum.', 'Bir gece yarısıydı, Sokaklarda ıssız bir sessizlik vardı. Gece olmasına rağmen, Ay doğmamıştı. Neyin peşindeydim bilmiyorum, Geceyimi sok se...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bilmiyorum-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilememek', 'bilememek-faik-genc-fw64m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En zoru seni böyle görmek sevgilim

Dışardan hiç bir şey yapamamanın acısıyla bakmak

İçimdeki özlemi gizlemek

Kalbimdeki fırtnayı bastırmak zorunda olmak

Beklemek belki bile bile,

Söndüreceğini sendeki küllenmiş ateşi

Kaçmak, kendimi kapatmak

Beklemek böylece hiç bir şey yapmadan

Ağlamak belki sadece

Bilememek.

Ekim 2004', 'En zoru seni böyle görmek sevgilim Dışardan hiç bir şey yapamamanın acısıyla bakmak İçimdeki özlemi gizlemek Kalbimdeki fırtnayı bastırmak z...', ARRAY['Türk Edebiyatı','Şiir','Faik Genç']::text[], 8.5, '{"poet":"Faik Genç","poet_slug":"faik-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bilememek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol oğlu!', 'yol-oglu-sair-nadirezheri-6h1ov', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(1) 

Nefeslerim subay*, helede

Ve ellerim ''sibri''tek soyuq

Ve gözlerin sönmüş ''paris''

Adim yol oğludur

GEDIREM.

(2) 

Tükendi röya bulaği

Tükendi röya bulaği

Elimde ''Bandrom''lu aci

Adim yol oğludur

IÇIREM.

(3) 

Ve sevginin yola-yolluğu**yox

Unudmuşam hara getdigimi

Unudmuşam kimi gezdigimi

Adim yol oğludur

ITIREM...

______________________

*Evlenmemiş

**Yolarkadaşliği

Bu şiir Tebrizin Adine hefteliyinde yayinlanmişdir (1380 Güneş yili) 

Erdebil-2001', '(1)  Nefeslerim subay*, helede Ve ellerim ''sibri''tek soyuq Ve gözlerin sönmüş ''paris'' Adim yol oğludur GEDIREM. (2)  Tükendi röya bulaği Tük...', ARRAY['Türk Edebiyatı','Şiir','Şair Nadirezheri']::text[], 8.5, '{"poet":"Şair Nadirezheri","poet_slug":"sair-nadirezheri","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yol-oglu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşluk', 'bosluk-hasan-can-0zplv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hangimiz bu boşlukta yaşamak ister,

Hangimiz yalnızlığı sever.

Yalnızken onsuz hangi dost avutur seni.

hangi şarkı seni anlatır,

Hangi söz yarana derman olur,

Karanlıkken hangi güneş geceni aydınlatır,

Ölüm suskunluğunda,

Hangi rüzgar eser etrafında,

Hangi yağmur korkularını siler,

Söyle hangimiz bu boşluğu ister...

Hangimiz aşk olmadan yaşar,

Hangimiz bu boşluktayken yaşamak ister,

Bu işkenceyle ölmekten kim korkar.

İnan yaşamak çok zor,

Böylesi boşken hayat...', 'Hangimiz bu boşlukta yaşamak ister, Hangimiz yalnızlığı sever. Yalnızken onsuz hangi dost avutur seni. hangi şarkı seni anlatır, Hangi söz y...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bosluk-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buraya Kadar mı?', 'buraya-kadar-mi-hasan-can-e9lml', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yollara düştüm yine,

Seni arıyorum her yerde,

Yine aynı dertle,

Peşindeyim yine izince.

Ne olur benide al yanına,

Seninle olayım her dakika,

Sarılayım sıkı sıkı sana,

İçimi dökeyim kana kana.

Bir deli rüzgarım peşinde,

Savrulurum ordan oraya,

Deli gibi esiyorum her yerinde,

Ne olur benide al yanına.

Buraya kadarmıydı,

Sonu bumuydu,

Sensiz olmakmı vardı,

Yaşananlar rüyamıydı.', 'Yollara düştüm yine, Seni arıyorum her yerde, Yine aynı dertle, Peşindeyim yine izince. Ne olur benide al yanına, Seninle olayım her dakika,...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/buraya-kadar-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Yerde Sen Varsın', 'her-yerde-sen-varsin-faik-genc-un609', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gördüğüm her sarı gülde

İçtiğim her acı yudumda

Kapkara denizlerde

Sımsıcak göklerde

Trakya’da yamaçlarda

Boğazda Hisar’da

Ankara’da evimizde

İstanbul’da şehrimizde

Her yerde sen varsın

Ekim 1998', 'Gördüğüm her sarı gülde İçtiğim her acı yudumda Kapkara denizlerde Sımsıcak göklerde Trakya’da yamaçlarda Boğazda Hisar’da Ankara’da evimizd...', ARRAY['Türk Edebiyatı','Şiir','Faik Genç']::text[], 8.5, '{"poet":"Faik Genç","poet_slug":"faik-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/her-yerde-sen-varsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tebessüm Yeterdi', 'bir-tebessum-yeterdi-hasan-can-v0u26', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir çocuk gördüm,

Gözleri ufuğa bakıyor,

Yaşamaktan bezmiş,

Elleri yokluğu tutuyor,

Ufukta derin bir,

Ahh çekiyor,

Esen rüzgara aldanıyor...

İçindeki hasret gitgide büyüyor,

Alev alev yanıyor yüreği,

Ağlamaklı ama bir tebessüm avutuyor onu,

O sadece seviyordu kendince...

Ağlamak değildi istediği,

Ufacık bir tebessüm,

Aldanacağı bir gülüş,

yeter ki gülsün,

Dert keder onu terketsin,

Ama olmuyor ve olmacayk gibi...', 'Bir çocuk gördüm, Gözleri ufuğa bakıyor, Yaşamaktan bezmiş, Elleri yokluğu tutuyor, Ufukta derin bir, Ahh çekiyor, Esen rüzgara aldanıyor......', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-tebessum-yeterdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece cenablari!', 'gece-cenablari-sair-nadirezheri-b66i4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece cenablarini saymadiğim* saatlardir

Xiyaban**da qatillerimi axtariram! ***

Kasiblar**** can verir

Ve devletliler***** arxayin****** intiharda! 

Bu ''çeyne-tüpür'' hayati

Gece cenablarina ithaf edeceyem

Qatillerimi xefleyeceyem*******

Ve ''dede yandiracağam''******** sesimle

Ekilme********* kelme ekilme! 

Teşrifin olsun

Gece cenablari özümüzdendir!

Göz gözü görmür

Çendi**********

Ve xiyabanda qatillerimi axtariram! 

-------------------------

*Saya salmadiğim

**Cada

***Arayiram

****Yoksullar

*****Zenginler

******Tehlukesiz

*******Geflete düşürdeceyim

********Cezalandirmaqdan kinayedir

*********Kayb olma

**********Sisdir

Tebrizin Adine hefteliginde yayinlanmişdir(yaz 80 güneş yili)

Erdebil-2001', 'Gece cenablarini saymadiğim* saatlardir Xiyaban**da qatillerimi axtariram! *** Kasiblar**** can verir Ve devletliler***** arxayin****** inti...', ARRAY['Türk Edebiyatı','Şiir','Şair Nadirezheri']::text[], 8.5, '{"poet":"Şair Nadirezheri","poet_slug":"sair-nadirezheri","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gece-cenablari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Sevgim Dorukta', 'benim-sevgim-dorukta-atil-kesmen-ynvty', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mutluluk adına 

Çok sözler yazdım çizdim, gönül defterime

Sizler gibi

Bazen

Mutluluğumu avuçlarımdan aldım

Bedenime sürdüm,kokladım

Tenimden akan terde hissettim

Hatta

Resmini çektim,afişlere astım

Ve..bu dünya sevgisini,gönlüme ekran yaptım

Uçan kuşları ise rehber olarak saldım

Mutluluk, sevgi adına çekilen nefesler

Düşüncelerde yerini bulsun diye

Çok uğraştım çok

Ama olmadı, ne yaptıysam

Mutluluklardan çıkar sağlandı

Bir şekilde gönlüm ağladı

Mutluluklarım hep acı olarak, geriye döndü

Bakan gözlerimi,kör etti

Terledim,üşüdüm  gündüz ve gecelerde

Sarmaş dolaş, yatmış olsamda mutluluğumla

Artık,

Yüzüm gülmüyor,mutluluğu temsil etmiyor

Hüzün dolu gözlerim,çukurlarına gömüldü

Ses tellerimde,kopuk bir esinti

Gönlüm delinmiş,kalp seslerim bedenimi titretiyor

Yüz ifadem ise

Tüm gerçekleri gören,bilen

Bir esir görüntüsünde,kendini gösteriyor

Neler oluyor bana

Bu yılgınlık nedendir gönül yollarımda

Yoksa

Gönlüm mutluluğuma havlumu attı

Ya yazdıklarım çizdiklerim,mutluluk adına

Boş ver gönlüm deymez, diyemiyorum

Ben mutluluk adına çok savaşlar verdim

Yaralar aldım,şifalar buldum

Suçum yok olamaz

Gönül defterime attığım imzalarımdan

Kalemim elmas, düşüncelerim safir

Mutluluğum olmasada

Benim sevgim dorukta

Damarlarımdan usanmadan akan kanda.....', 'Mutluluk adına  Çok sözler yazdım çizdim, gönül defterime Sizler gibi Bazen Mutluluğumu avuçlarımdan aldım Bedenime sürdüm,kokladım Tenimden...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/benim-sevgim-dorukta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakma Öyle Abicim...', 'bakma-oyle-abicim-adem-tetik-5en1f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben yalnızım abi bakma öyle ne olur

Bakma kalabalık içinde öylesine durduğuma

Gülen gözlerimdir yalnız aldanma ne olur

Hep hıçkırık saklıdır aslında her gülüçüğüm arkasında

Bakma abi sen benim böyle davrandığıma

Bilmezsin aslında kaç vurgun yemiştir 

Şu zavallı yüreğim hayat kavgasında

Hani abi seversin ya delicesine birini 

Hani ölecek kadar sevmişindir sen o yari

Yada bir dost vardır ya ölümene bağlandığın

Sen ihanetini yaşadınmı sahi abi böyle severken 

Sahi sen bilirmisin abicim ölmek nasıl bir duygu

Yada abicim sen bilirmisin yalnızlık 

Çevrendeki insanlar arasında o kadar çok sevilsende

Nasıl bir acıdır bilirmisin binlerce kişinin içinde  yalnızlık', 'Ben yalnızım abi bakma öyle ne olur Bakma kalabalık içinde öylesine durduğuma Gülen gözlerimdir yalnız aldanma ne olur Hep hıçkırık saklıdır...', ARRAY['Türk Edebiyatı','Şiir','Adem Tetik']::text[], 8.5, '{"poet":"Adem Tetik","poet_slug":"adem-tetik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bakma-oyle-abicim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydın Yaşamak', 'gunaydin-yasamak-osman-i-nci-nd6to', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu sabah neşeliyim, harika bir gün,

Olmasın istiyorum, bir damla hüzün,

Çözün gönlünüzü, özgürlüğe çözün, 

Günaydın çiçekler, günaydın güller...

Hayat çok kısadır, üzülmeye değmez,

Sevdası olmayan kalp, asla sevinmez,

Bırakın aşkı gelsin, sevgiler silinmez,

Günaydın yüzyıllar, günaydın günler...

Tebessümle bak, aynadaki kendine,

Sevdaları kat, çırpınan deli kalbine,

Bir oh çekip, el salla mavi gökyüzüne,

Günaydın bulutlar, günaydın kuşlar...

Güneş seninle doğsun, mehtap seninle,

Yıldızlar dans etsin, bir tek işaretinle,

Aşık et evreni kendine, güzel sözlerinle, 

Günaydın gönüller, günaydın aşklar...', 'Bu sabah neşeliyim, harika bir gün, Olmasın istiyorum, bir damla hüzün, Çözün gönlünüzü, özgürlüğe çözün,  Günaydın çiçekler, günaydın gülle...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gunaydin-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yıl Manisi', 'yeni-yil-manisi-faik-genc-ux9qk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeni yıl yeni bir hayat mı,

Yoksa yeni bir hayat için umut mu getirir bilemiyorum…

Her ne olursa olsun yaşamak güzel,

Umutsuzluk kime iyi gelmiş ki

Bize de gelecek sevgilim,

Bekle,

Umutla, sevinçle, hayat dolu gözlerinle bekle

Hayat bize ihanet etmeyecek sonunda…

Aralık 2000', 'Yeni yıl yeni bir hayat mı, Yoksa yeni bir hayat için umut mu getirir bilemiyorum… Her ne olursa olsun yaşamak güzel, Umutsuzluk kime iyi ge...', ARRAY['Türk Edebiyatı','Şiir','Faik Genç']::text[], 8.5, '{"poet":"Faik Genç","poet_slug":"faik-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yeni-yil-manisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A-b-c-ç-d-...', 'a-b-c-c-d-talip-kaplan-d5zya', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Havalar soğudu şu ar a

Hasta olmadım, düşmedim bita b

Sağlığı yaptım başıma ta c

Diktim toprağa bir iki ağa ç

Fakir değilim ama, olmadım lor d

Sakın dokunmayın bam telim e

Kaldıramazsınız, derim ağır la f

İnsan sarrafıyım, psikolo g

Açık konuşurum, çekmem ya ğ

Çatışmam kendimle, içim fera h

Alırım mızrabı, çalarım saz ı

Yazarım şiiri, şarkı ederim ses i

Delerim kalpleri, yaparım sonda j

Yediğim ekmek alınteri, ha k

İçtiğim su, giydiğim hela l

Yalanı sevmem, atıp sıkma m

Ufkum geniştir, yüreğim harma n

Sırtımda yamalı bir palt o

Ondokuzuncu satırın sonu  ö

Kendimi bildim bileli adım Tali p

Aklıma kırk türlü düşünce geli r

Kalk git der uzaklara, bir se s

Sigarayı yakınca sanırsınız ke ş

Ayaz çıkınca üzerim dokuz ka t

Yazları giyerim kısa kolluy u

Sevmem allıyı, bir de güllüy ü

Yanardağ olsam, püskürsem la v

Unut bu sevdayı, benden ca y

Aşk çekilmez artık, bitti ya z...

(1995)', 'Havalar soğudu şu ar a Hasta olmadım, düşmedim bita b Sağlığı yaptım başıma ta c Diktim toprağa bir iki ağa ç Fakir değilim ama, olmadım lor...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/a-b-c-c-d-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-faik-genc-5dpua', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensiz olmak nasıl bir şey

Keşke sen de bilebilsen

Günler, saatler nasıl geçer

Anlayabilseydin keşke

Senden uzakta seninle yaşarım

Sensiz evde seninle konuşur

Geceleri aynaya bakar

Seni görürüm

Düşünürüm sesin ne der

Gözlerin hangi resimlere bakar

Kimleri dinler, kimlerle konuşursun

Aklından neler geçer

Sensiz olmak nasıl bir şey

Keşke sen de bilebilsen

Kasım 2004', 'Sensiz olmak nasıl bir şey Keşke sen de bilebilsen Günler, saatler nasıl geçer Anlayabilseydin keşke Senden uzakta seninle yaşarım Sensiz ev...', ARRAY['Türk Edebiyatı','Şiir','Faik Genç']::text[], 8.5, '{"poet":"Faik Genç","poet_slug":"faik-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sensizlik-143-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiğin Gün', 'gittigin-gun-hifzi-altumsek-bt38z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiç unutmam bahardı

Gittiğin gün sevgilim

Birden dünyam karardı

Gittiğin gün sevgilim

Sular gibi berraktın

Yanlış yönlere aktın

Bir zavallı bıraktın

Gittiğin gün sevgilim

Yaprak düştü dal kaldı

Ne düş ne hayal kaldı

Ne bende bir hal kaldı

Gittiğin gün sevgilim

Bir pınardım duruldum

Canevimden vuruldum

Erenlerden soruldum

Gittiğin gün sevgilim

Geldi ömrüme kışlar

Hüzün doldu bakışlar

Aktı gözümden yaşlar

Gittiğin gün sevgilim

Kırk gönülden dışlandım

Kırk yıl daha yaşlandım

Deli diye taşlandım

Gittiğin gün sevgilim

Bir rüzgar geldi geçti

Kalbimi deldi geçti

Tabipler ömür biçti

Gittiğin gün sevgilim

Dön gel artık tez elden

Göç başlıyor bu elden

Haber geldi ecelden

Gittiğin gün sevgilim', 'Hiç unutmam bahardı Gittiğin gün sevgilim Birden dünyam karardı Gittiğin gün sevgilim Sular gibi berraktın Yanlış yönlere aktın Bir zavallı ...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Altümsek']::text[], 8.5, '{"poet":"Hıfzı Altümsek","poet_slug":"hifzi-altumsek","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gittigin-gun-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saksıdaki Sardunya', 'saksidaki-sardunya-faik-genc-kmbeu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saksıdaki kırmızı sardunyam

Kırağı ışıltılı, altın saçlı sevgilim.

Hayatıma melek gibi girdin

Dünyama yasemin gibi tüttün

Sensiz bir gece

Saçlarının yayılmadığı yastık

Küçük ayaklarının duyulmayan sesi

Gözlerinin gülmediği bir yuva

Kasım 2004', 'Saksıdaki kırmızı sardunyam Kırağı ışıltılı, altın saçlı sevgilim. Hayatıma melek gibi girdin Dünyama yasemin gibi tüttün Sensiz bir gece Sa...', ARRAY['Türk Edebiyatı','Şiir','Faik Genç']::text[], 8.5, '{"poet":"Faik Genç","poet_slug":"faik-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/saksidaki-sardunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimce Söyleşim 9/ Eşime', 'kendimce-soylesim-9-esime-serap-demirturk-p3b5o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğimdeki bin çığlığı duyan sen...Nerdesin? Neden yanımda yoksun! Sana o kadar ihtiyacım var ki... Oysa, bilmiyorsun  içimdeki fırtınayı. Bu dünyayı bana bırakıp gidemezsin. Bak, hayat ne güzel...Hadi aç gözlerini. Bak bana, gör gözlerimde bıraktığın hüznü. Omuzlarıma bu büyük yükü bırakmaya hakkın yok. Aşağıda ağlayan yavrular, bizim yavrularımız. Senin gözlerinde gördüğüm o paniği hatırlıyorum düşündükçe ve seni istiyorum yuvamızın başında. Her ne yaşamışsak, ne kadar kırmışsak birbirimizi, ne kadar sevmişsek unuttum hepsini. Buraya geldiğimiz gibi dört kişi çıkmak istiyorum buradan. Oysa bilinmez bir duraktasın sen. Doktorun metalik ve umuttan uzak sözlerini hatırlamak istemiyorum, Ben, yanına gelmek istiyorum...Bırakmıyorlar! Ne senin yanına girebiliyorum ne yavruların yanına gidebiliyorum. Karanlık hastane koridorlarında kimsesizliği yaşıyorum...Yalnızım, yapayalnız....Ne olacak şimdi, bile diyemiyorum. Kuş olup içeri girmek ve sana takılan aletlerdeki nabız atışını görmek istiyorum. Lütfen, bunu bize yapma, Gitme! Bak, sabah yeni bir gün başlayacak. Güneş, hepimizin üstüne doğsun. Kolay değil sensiz hayat, canlara. Dayan! Dayan ki umudun varlığına inanalım. Seni bekliyoruz, dön artık.', 'Yüreğimdeki bin çığlığı duyan sen...Nerdesin? Neden yanımda yoksun! Sana o kadar ihtiyacım var ki... Oysa, bilmiyorsun  içimdeki fırtınayı. ...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/kendimce-soylesim-9-esime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol...', 'yol-i-lker-dursun-rpaex', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kendimi  sevdiğim için mi 

Yoksa kendimden bu kadar korktuğum için mi

Yalnızlığım hep hüzne 

Hüznüm de yollara çıkıyor

Kendimle kaldığım zamanlarda 

Ucu bucağı olmayan hüznümle basa çıkmaya çalışırken 

Yollar hüzün mü verir 

Yoksa hüzün mü yola çıkarır.', 'Kendimi  sevdiğim için mi  Yoksa kendimden bu kadar korktuğum için mi Yalnızlığım hep hüzne  Hüznüm de yollara çıkıyor Kendimle kaldığım zam...', ARRAY['Türk Edebiyatı','Şiir','İlker Dursun']::text[], 8.5, '{"poet":"İlker Dursun","poet_slug":"i-lker-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yol-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına', 'firtina-serap-demirturk-4x6t2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Esme rüzgar 

Saçım acıyor... 

Yağma yağmur, 

Yüzüm yanıyor... 

Bükülekaldım 

N''olur 

Vurma artık 

Dayanamıyorum 

Vurma. 

Bilemedim 

Yüreğim kaldırmadı... 

Yalnızlığımı özledim.

serap hoca', 'Esme rüzgar  Saçım acıyor...  Yağma yağmur,  Yüzüm yanıyor...  Bükülekaldım  N''olur  Vurma artık  Dayanamıyorum  Vurma.  Bilemedim  Yüreğim ...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/firtina-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Sevda', 'buyuk-sevda-serap-demirturk-cb9kg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben hayatı bu kadar ciddiye almazdım 

Seni tanımadan önce... 

Sevmenin bu kadar önemli 

Dostluğun bu kadar sıcak olduğunu bilmezdim

Sendeki güveni hissetmeden... 

İnsan... 

Bu kadar mı sever... 

İnsan,bu kadar mı sevgiyle bakar... 

Yüreğine nasıl sığdırır o büyük sevdayı... 

Bilemedim.. 

Hayata..aşka ve insana dair 

Ne biliyorsam unuttum... 

Tek bildiğim gerçek sensin. 

Sen güvensin, 

Sen umutsun, 

Sen bitmeyen gecelerin hazan yıldızısın.', 'Ben hayatı bu kadar ciddiye almazdım  Seni tanımadan önce...  Sevmenin bu kadar önemli  Dostluğun bu kadar sıcak olduğunu bilmezdim Sendeki ...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/buyuk-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelme', 'gelme-serap-demirturk-d2c8q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'img src='' http://www.balcanet.com/javaya/jpg/duygularim10050.jpg''

Bu kaçıncı geleceğim deyişin? 

Beklemek, umudum oldu. 

Hayallerimin ötesinde bir durak var... 

Seni orada bekleyeceğim demiştim... 

Geldiğinde gözlerine bakamazsam 

Bana kızma... 

Susarsam, kelimeleri saklarsam kendime 

Kırılma... 

Nedensiz sevgin beni öyle sardı ki, 

Özlemin rüyalarımdan taştı... 

Ta uzaklarda bir yıldız var, 

Seni ona şikayet ettim dün gece. 

Yüreğimi ağlattı dedim senin için ona... 

Göz kırptı yıldızım bana... 

Korkum,nedensiz sevginin 

Nedenli vedalara dönüşmesi. 

Gel demeyeceğim artık sana... 

Geleceğin zamanda,gülecek gözlerim; 

Göreceğim anda titreyecek ruhum... 

Ellerini tutamam, 

Omzuna yaslanıp uyuyamam, 

Tenini kokusunu bilmem... 

Vazgeçtim, 

Gelme.

BGSOUND SRC='' http://alaeddin.cc.selcuk.edu.tr/mcan/midi/midiler/Kayahan%20-%20Yoksun%20Sen.mid''', 'img src='' http://www.balcanet.com/javaya/jpg/duygularim10050.jpg'' Bu kaçıncı geleceğim deyişin?  Beklemek, umudum oldu.  Hayallerimin ötesin...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gelme-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal', 'hoscakal-serap-demirturk-1d1cv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana merhaba dedigim gün elveda demek isteyecegimi bilir miydim? 

Elveda canim... 

Seni sevdigim kadar senden uzak kalmayi isteyecegimi bilir miydim? 

Elveda canim... 

Beni mutlu etmek isterken mutsuz ettigini bilir miydin? 

Elveda canim... 

Sevmek, degismeden bir olmakmis; sevdin ama degistin! 

Elveda canim... 

Ayri ayriydi düslerimiz, birlestiremedik, 

Elveda canim... 

Nerede olursan ol hep sirti açik kaldi mi diye düsünsem de seni, 

Elveda canim... 

Çatilar degil, canlar birlestirirmis yürekleri, 

Elveda canim... 

Beni unutma demem, unutmandir dilegim, 

Elveda canim.', 'Sana merhaba dedigim gün elveda demek isteyecegimi bilir miydim?  Elveda canim...  Seni sevdigim kadar senden uzak kalmayi isteyecegimi bili...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hoscakal-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Bir Hayal', 'sadece-bir-hayal-serap-demirturk-v4vcp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni hayallerimin içine tutsak ettim, 

Herhangi bir yerde ya da zamandayız artık seninle. 

Başbaşa oluşumuzun bu ilk günü... 

Gözlerim kamaşıyor gözlerinin ışığından... 

Allahım bu ne büyük mutluluk! 

Canımsın diye haykırabilirim... 

Seni özlemenin şarkısını yazmam artık, 

Sesime sevgini katıp da söylerim sevdamı. 

Otur yanıma, 

Bakalım birlikte batan güneşe, 

Doğan aya. 

Yıllardır hasretim sana sanki... 

Ellerim, gözlerim, dudaklarım hasret. 

Sana dair söylenen tüm sözlere düşmanım. 

Seni bir tek ben terennüm etmeliyim. 

Sen bu gece benim hayallerimin 

En kutsal misafirisin. 

Sana bakmaya bile doyamam, 

Korkarım ki dokunursam yok olursun. 

Kal, gitme! 

Ben razıyım seni sadece seyretmeye. 

Gitme!', 'Seni hayallerimin içine tutsak ettim,  Herhangi bir yerde ya da zamandayız artık seninle.  Başbaşa oluşumuzun bu ilk günü...  Gözlerim kamaş...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sadece-bir-hayal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesin', 'sesin-serap-demirturk-kf132', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elimde bir kırık saz, 

Düşmüşüm bir yabancı ele 

Yangını yangınım mı, 

Alevi alevim mi 

Bilinmez. 

Her dağın yamacında 

Bir küçücük zakkum 

Rengi yüreğime eş, 

Aşkı sevdama eş 

Binlercesi değil biri benim. 

Sazıma dedim de derdimi 

Ağladı her bir teli. 

Sevdamın yeli yabancı 

Gülüşü acı 

Bakışı el ki el... 

Bu nasıl acıdır ki 

Yaktığını bilmez. 

Gözü gözüme uzak 

Yüreği bende. 

Sesime ses veren 

Yürek nerede?', 'Elimde bir kırık saz,  Düşmüşüm bir yabancı ele  Yangını yangınım mı,  Alevi alevim mi  Bilinmez.  Her dağın yamacında  Bir küçücük zakkum  ...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sesin-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslatımız', 'vuslatimiz-serap-demirturk-16jqn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-''Seni sevmek bambaşka'' dedin ya...- 

Ey sevilen! 

Ölümsüz sevdalara 

Hoş geldin. 

Vazgeçilmeyen olmak, 

Bir umut olmak, 

Sevdikçe sevilmek, 

Özlendikçe özlenmek... 

Ne güzel. 

Ah,sevda türküm! ... 

Nerelerdesin? 

Her güzellikte hatırlanan 

Hatırlandıkça ağlatansın. 

Gölgesiz gecelerde 

Gölgesini bulduğum, 

Şu yaşlı yüreğimi, 

Bükük boynumu 

Koydum önüne... 

Susma 

Söyle derdini, 

Nedendir gidişin? 

Serab olduğumda da 

Bugün gibi sev beni. 

Vuslatımız, 

O sonsuz uykuda. 

Mecnun gibi, 

Kerem gibi yanmışız... 

Ağlıyorsam, 

Sebebimsin... 

Ey sevilen! 

Yaradan, 

Ne güzel yaratmış seni! 

Uzandım ellerine, 

Yoksun. 

Bundan sonra aşkın adı 

Hayal olsun. 

Acı,özlem ve yangın, 

Aşkla anılır olsun. 

Ey sevilen! 

Aşkın kaynağı! 

Sevenini ardında gezdiren! 

Büyüsü 

Ayrılıktadır aşkın; 

Bilmez misin? 

Elimi yüreğine koysam, 

Yanar ellerim. 

Şunu bil ki: 

Her nerede... 

Hangi ağacın dibinde, 

Hangi evin avlusunda 

Olursan ol... 

Işığınla aydınlatan, 

Özleminle varım diyen 

Sen, 

Özlenmektesin...', '-''Seni sevmek bambaşka'' dedin ya...-  Ey sevilen!  Ölümsüz sevdalara  Hoş geldin.  Vazgeçilmeyen olmak,  Bir umut olmak,  Sevdikçe sevilmek,...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/vuslatimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Kırıntıları', 'zaman-kirintilari-serap-demirturk-ohrx5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dönsen geçmişe,baksan geriye... 

Kimi an bebeksin,annenin kucağında, 

Kimi an çocuksun,elinde çantanla. 

Ağlıyorsun susturuyor annen, 

İstiyorsun, alıyor baban. 

Bir incir çekirdeğinden büyük değilken 

O günden beri birikti de çığ oldu, 

Ezdi, yıktı omuzlarını demek ki 

Seni ağlatan o dertler! 

Bırak o günler, hayallerinin engin 

Bitmeyen denizini süslesin. 

Sen başını kaldırıp da omzun dik, 

Gözlerindeki acıyı silip yeni umutlarla; 

İçindeki o bitmeyen özlemle, gülerek yaşama 

Gitsen ileri,hep ileriye; bakmadan geriye!', 'Dönsen geçmişe,baksan geriye...  Kimi an bebeksin,annenin kucağında,  Kimi an çocuksun,elinde çantanla.  Ağlıyorsun susturuyor annen,  İstiy...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/zaman-kirintilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zormuş', 'zormus-serap-demirturk-4hxn8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayatı neresinden yakaladık? 

Oltaya takılan balık çığlık çığlık... 

Sesi olsa, çıkaracak, tık yok.

Denizin yosununda bin çile, 

Her bir çilede mutluluk kefen. 

Tükenip gidenlerin ardından, 

Umudu gömdük gülerek. 

Hayatı neresinden yakaladık? 

Balığın gözyaşı denizi taşırdı. 

Yosunun yeşili kırmızıya döndü. 

Acıyı ağu ettik, sürdük yaraya. 

Yürekten yüreğe teğet geçti gülüşler. 

Babadan oğula miras kaldı, 

Olmayan gelecek, esmeyen rüzgar. 

Hayatı neresinden yakaladık; 

Biz kovaladıkça durur sandık.

SERAP HOCA

''SIFAT KOCAR AMA GÖNÜL KOCAMAZ'' KARACAOĞLAN

olmuyor...kalınmıyor artık buralarda...gitmeli artık...uğramamalı buralara...19.4.2009

25.8.2005  düzenleme tarihli  kayıt belgesi- düzenleme numarası 2951 7225 4138- elektronik belgeyi imzalayan:antoloji.com site yöneticisi Cengiz Teymur-112904 numaralı site üyesi SERAP DEMİRTÜRK ÖZALTUN adlı şairin şiirlerini SERAP HOCA mahlasını kullanarak kaydettiğini onaylamıştır.', 'Hayatı neresinden yakaladık?  Oltaya takılan balık çığlık çığlık...  Sesi olsa, çıkaracak, tık yok. Denizin yosununda bin çile,  Her bir çil...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zormus-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklugumdan Kuslar Göçerdi', 'cocuklugumdan-kuslar-gocerdi-aytekin-kaya-5zh7w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şehir suskundu şehir sakinleri kadar

siyah beyaz fotograftaki kadar nostaljik

sen ayni kapidan çıkıyordun her sabah

kuşlar her bahar aynı dallara tünüyordu

ve akşamları bozacılar gelirdi... 

çocukluğum ve çocuk arkadaşlarım 

teravih namazından çıkardik

bayramlarda tüm komşuların ellerini öpmeye giderdik

o zamanlar şehir suskundu 

siyah beyaz fotoğraflardaki kadar nostaljikti yasam

sen hep ayni evde oturuyordun 

komşularimiz ortakdı

heyecanlarımız ve hüzünlerimiz

her sonbahar kuşlarsa aynı refleksi gösterirdi

her dal kuşlarla beraber yapraklarini dökerdi

                                   6.11.2004', 'şehir suskundu şehir sakinleri kadar siyah beyaz fotograftaki kadar nostaljik sen ayni kapidan çıkıyordun her sabah kuşlar her bahar aynı da...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Kaya']::text[], 8.5, '{"poet":"Aytekin Kaya","poet_slug":"aytekin-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cocuklugumdan-kuslar-gocerdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muamma', 'muamma-yavuz-sayin-tko1f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Delinin kuyuya bıraktığı taş 

Bulanı olmadı akıllıların

Gizli bir kudretin yaktığı ataş

Söneni olmadı tutuşanların

Bu akrebin gıpta ettiği zehir

Bu balığın dalıp Öldüğü nehir

Tenhasında mecnun büyüten şehir

Döneni olmadı uğrayanların

Bu Kays ın sahrada bıraktığı iz

Ferhatın demire açtığı dehliz

Kaf denilen dağın ardındaki giz

Çözeni olmadı müneccimlerin

Bu çağlar ardından yankılanan ses

Bu kuru toprağa üflenen nefes

Bülbül figan etti kırıldı kafes

Feryadı dinmedi ağlayanların

Bu ölümsüzlüğü fısıldayan su 

Bu gönüle her dem kurulan pusu

Bu Ashab-ı Kehf in uzun uykusu

Miadı dolmadı uyananların

Hallac-ı Mansuru çeken urgana

Yunus biçareyi bürüyen kana

Pervane misali döndü Mevlana

Odu eksilmedi evliyaların

Hira dan alemi kucaklayan nur

Çölleri ''''Hu'''' diye okşayan yağmur

Bir zerresi düştü parçalandı Tur

Kudreti yetmedi enbiyaların

Bu aklı çarmıha geren bilmece 

Bu duraksız bir yol şafaksız gece 

Olmuşu üç harfli bir garip hece 

Hali perişandır okuyanların...', 'Delinin kuyuya bıraktığı taş  Bulanı olmadı akıllıların Gizli bir kudretin yaktığı ataş Söneni olmadı tutuşanların Bu akrebin gıpta ettiği z...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Sayın']::text[], 8.5, '{"poet":"Yavuz Sayın","poet_slug":"yavuz-sayin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/muamma-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olurmu', 'olurmu-hikmet-guner-0tr4w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sorsalar aşksız hayat olurmu

Aşka doymak, onsuz hayat olurmu

Dokunmakmı, hissetmekmi, yaşamadan olurmu

Ne olursa olsun ama hayat sensiz olurmu

Susamakmı, aç kalmakmı ikiside olurmu

Yağmurmu, selmi doğa susuz olurmu

Sonbahar ardından kış, ama kar yağmadan olurmu

Ne olursa olsun ama hayat sensiz olurmu

Gündüzmü, gecemi geceler aysız  olurmu

Bulutmu, güneşmi, güneşsiz hayat olurmu

Hem sıcak hem soğuk, yaşamadan olurmu

Ne olursa olsun ama hayat sensiz olurmu

Rüyamı, gerçekmi hayal kurmadan olurmu

Sevgisiz aşk, sevmeden olurmu

Aşkına susadım, susamadan olurmu

Bahane ne olursa olsun, ama hayat sensiz olurmu', 'Sorsalar aşksız hayat olurmu Aşka doymak, onsuz hayat olurmu Dokunmakmı, hissetmekmi, yaşamadan olurmu Ne olursa olsun ama hayat sensiz olur...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olurmu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ola', 'ola-hikmet-guner-1ein7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün doğdu, gün battı, gündüzüm gece ola

Her eve geldiğimde sessizlik var ola

Sessizlik, sensizlik benimde canıma tak ola

Merak etme güzel yarim, kavuşmak tez ola

Yattım yatağa döndüm bir sağa bir de sola

Bir rüya gördüm dün gece hayırlar ola

Ağlamaklı idid gülen gözlerin acep ne ola

Bedenim yanlızdır am, ruhum hep seninle ola

Aşkım sevgim, kalbim yanlız seninle ola

Baktıkça resmine hep gözlerim dola

Uzaklardayız ya adı bence hasretlik ola

Merak etme güzel yarim kavuşmak tez ola

Geçer gider bu günler, yeter ki sağlık ola

Bir sabah uyandığında ben, koynunda ola

Yakındır kavuşmak, kolların boynuma dola

Bitecek bu hasret, günümüz bayram, keyfimiz hoş ola', 'Gün doğdu, gün battı, gündüzüm gece ola Her eve geldiğimde sessizlik var ola Sessizlik, sensizlik benimde canıma tak ola Merak etme güzel ya...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ola-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolay Değil', 'kolay-degil-cafer-tayyar-ozkan-rti7o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensiz uzakta yaşamak hiç kolay değil

Gel de sevdanın önünde saygıyla eğil

Yüreğin bir de vuslata ederse meyil

O vakit destan yazar, pamuk bedenin.

Canın özünü aşkınla kedere sokma

Karagözlünü ukdeyle acıya boğma

Gönül erini her gece yabana satma

O vakit muradı yaşar, sardığım tenin.

06 Kasım 2004 Ankara', 'Sensiz uzakta yaşamak hiç kolay değil Gel de sevdanın önünde saygıyla eğil Yüreğin bir de vuslata ederse meyil O vakit destan yazar, pamuk b...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kolay-degil-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönmem gerek', 'donmem-gerek-hikmet-guner-yb9so', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni çok özlediğimi bilmen gerek

Aslında sende çok özledin, beni görmen gerek

Gülmek varken ağlamaya ne gerek

Biliyorum yakında sana dönmem gerek

Kıyamam sana, gözündeki damlaya ne gerek

Mutlu olmak varken, mutsuzluğa ne gerek

Güzellik varken, çirkinliğe ne gerek

Biliyorum yakında sana dönmem gerek

Sabır varken, sabırsızlığa ne gerek

Her an içimdesin ya, bunu hep bilmen gerek

Kanımsın, canımsın sonsuza dek aşkımsın

Biliyorum yakında sana dönmem gerek

Aittir herşeyim sana buna şüphe ne gerek

Bak sende kendine, Bana yanlız seni gerek

Gönlünü ferah tut ki, Bana da neşe gerek

Ya hep seninle, yada sensiz ölmem gerek', 'Seni çok özlediğimi bilmen gerek Aslında sende çok özledin, beni görmen gerek Gülmek varken ağlamaya ne gerek Biliyorum yakında sana dönmem ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/donmem-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırılsıklam', 'sirilsiklam-haydar-okur-31bi0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir türküsü yankılanır dillerde

ve bir şiiri Çarşamba''nın

''Çarşambayı sel aldı bir yar sevdim el aldı

Keşke sevmez olaydım elim koynumda kaldı

Çarşamba''nın ortasından akıyor ırmak

Her yğidin karı değil sözünde durmak''

bağıtlıyım sevine,el alsa seni, sel alsa beni

seviyorum gökçe gözlüm Çarşamba''yı,Yeşilırmağı

ve yağmurunu sevdanın

mavi bir derinlikteyim şimdi ıpıslak sırılsıklam

geceler seni taşır bana, seni düşünür düşlerim her gece

ay ışığına koşut saçlarını

sekerek yürüdüğün kaldırımlarını Çarşamba''nın

ve beni bağlıyor saçların düğüm düğüm, Çarşamba''nın ceylan yüreğine

gök mavisi, gün güzeli gözlerinde yitiyor umulu gözlerim

yakamozlar çırpınıyor gözlerinde, aydınlatıyor karanlıklarını Çarşamba''nın

ve Çarşamba''nın gecelerinde seni, düşlere taşıyan sesini arıyorum

aslında karanlıklarıda severim

buğulanan bakışlarının, sağnayan yağışlarını da

bırak gönül göğünün yıldırımları bana yansısın

bir görünüp yitmeni, bir de göz kırpmanı seviyorum, mavi yıldızlar gibi

Çarşamba''yı yaşıyorum, seni ve sevi yağmurunu ıpıslak sırılsıklam sevdanı

köprü başındayım, bir ucunda sen öteki ucunda ben

dillerde yine o türkü '', Çarşamba''nın ortasında akıyor ırmak''

ellerim açılıyor, uzanıyor kollarım, tutacak gibi seni

Yeşilırmak''ta kuğular sevişirken

bir yiğit yar cevrine gurbete düşse, kolları açık elleri bomboş kalacak bilirim

ben yine de sözümdeyim, eriyim andımın ellere inat

heyhat! apansız bölünecek düşlerim

ve apansız vuracak beni yad''lar bilirim

meltemler estiren gelişlerin aparır beni benden

kardelen çiçeği gülüşlerin yankılanır içimde

yağmurla geleceksin yine ığlım ığlım

ve yağmurla taşıyacaksın beni kuğu yuvalarına

ben seninle varım, varsam, bir de köz kundağı sevdamla

beni sevdiğince yağmuru da sevmelisin

bir gün bana geleceksen gökçe gözlüm, gönlünün yağmuruyla gelmelisin

bulupta sevemediğim ve dokunamadığım güzelliğinle

bürünerek pembemsi ipeklere

ürkekliğini sevdiğim cerenler gibi, en delişmen duygularla periler gibi gelmelisin

bir gün tutabilirsem o pamuksu ellerinden

görürsem seni, sevincin çıngıları vuracaktır kalbimi

mutluluğun kaçak vuruşlarında yok olacağım

kuşlar da bilmeyecek kim olduğumu, kuğuları da Yeşilırmağın

bir sen bileceksin yağmurla geldiğimi

ve bir yığın anıları bırakarak ardımda, göçmen kuşlara katıldığımı...

köprünün bir ucunda sana açılan ellerim, ellerini tutamayacak

ardımda bitirilmemiş yarım bardak çay

sıcaklığı üstünde kalacak ellerimin, çay bahçesinde Yeşilırmağın

ve bir gün yine, yağmurla döneceğim sana

mavi derinliklerden, masmavi gözlerine

ıpıslak sırısıklam bir yürek yangınıyla

o gün bir türkü yankılanırsa dillerde, o bildik türkü işte

deniz gözlerine yolcu, Yeşilırmağın taşkınlığında olacağım

özleyeceğim sarı saçlarını

ve bir de sağnak yağmuruyla sevdasını Çarşamba''nın

ıpıslak sırılsıklam

KÖMEN', 'bir türküsü yankılanır dillerde ve bir şiiri Çarşamba''nın ''Çarşambayı sel aldı bir yar sevdim el aldı Keşke sevmez olaydım elim koynumda kal...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/sirilsiklam-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Şiir', 'siir-siir-ufuk-nazim-v3sna', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şiir şiir paylaşılan

Bütün zamanlarda.

Duygu yüklü bulutlarla 

Geçmek! 

Dünyanın üzerinden.

Bir sevda fırtınasında

Yeldeğirmenlerinin 

Başı boş pervanelerini

Umutla çevirmek.

Yaşanmamış olan

Geride kalan neyse

Şiir şiir yaşamak

Paylaşmak bütün dizelerimizi

Ekmeğimizi bölüşür gibi.

Şiir kardeşliğinde

Oturup sofrasına güneşin

Doyurmak yüreklerimizi.', 'Şiir şiir paylaşılan Bütün zamanlarda. Duygu yüklü bulutlarla  Geçmek!  Dünyanın üzerinden. Bir sevda fırtınasında Yeldeğirmenlerinin  Başı ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/siir-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözümde Değil', 'gozumde-degil-tayyip-sag-th4pw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Susuzluktan yanmış gibi,

Açlığından ölmüş gibi,

Acılar bürünmüş gibi,

Ben seni öyle sevmiştim.

Sevgi yalan değil gerçek,

Yalan olsa inanmazdım,

Çektiğimi ben bilirim,

Bilseydim böyle yanmazdım.

Sen yoksun güllerim hasret kokuyor,

Dünya''yı verseler gözümde değil,

Bu aşk beni derin derin yakıyor,

İnan ki hiç bir şey gözümde değil.

Sensizlik ölmeye değer,

Bunu bilsen bile yeter,

Gönlüm çok cahilmiş meğer,

Bilseydim böyle sevmezdim.

25.07.2001', 'Susuzluktan yanmış gibi, Açlığından ölmüş gibi, Acılar bürünmüş gibi, Ben seni öyle sevmiştim. Sevgi yalan değil gerçek, Yalan olsa inanmazd...', ARRAY['Türk Edebiyatı','Şiir','Tayyip Sağ']::text[], 8.5, '{"poet":"Tayyip Sağ","poet_slug":"tayyip-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gozumde-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmamalıydın', 'olmamaliydin-osman-i-nci-xg2x7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana, güzel günler,

Mutluluklar adadım..

Yaşamımı yoluna,

Halı diye döşedim,

Ama işe yaramadı..

Ne sevebildin beni,

Ne güldürdün bir an...

Aşkımla alay edip,

Tepeden baktın bana..

Öyle acılar yaşatıp,

Öyle dertler çektirdin ki,

Gözlerimde nem,

Sözlerimde sitem oldun,

Olmamalıydın...

Bu sevdanın sonu,

Bu olmamalıydı...

Kalbim kırık dökük,

Duygularım dağılmış..

Ruhumda sıkıntı,

Yüreğimde keder oldun..

Gözlerimde nem,

Sözlerimde sitem oldun,

Olmamalıydın...', 'Sana, güzel günler, Mutluluklar adadım.. Yaşamımı yoluna, Halı diye döşedim, Ama işe yaramadı.. Ne sevebildin beni, Ne güldürdün bir an... A...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/olmamaliydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan Yeli', 'hazan-yeli-tayyip-sag-05gxf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Açmamış gonca gül idim,

Hazan yeli kırdı beni,

Gül dalında bülbül idim,

Lala dönderdiler beni.

Yeşerirdim yaprak yaprak,

Bahar kıskanırdı beni,

Binbir çiçek dal olurdum,

Toprak kıskanırdı beni.

Coşkun akan sel olurdum,

Çölde kuruttular beni,

Yalan yanlış sözler ile,

Dilde çürüttüler beni.

Bilmediğin  sözden sakın,

Ecel hepimize yakın,

İnsanlara doğru bakın,

Doğru gözde görün beni.

  17.04.2001', 'Açmamış gonca gül idim, Hazan yeli kırdı beni, Gül dalında bülbül idim, Lala dönderdiler beni. Yeşerirdim yaprak yaprak, Bahar kıskanırdı be...', ARRAY['Türk Edebiyatı','Şiir','Tayyip Sağ']::text[], 8.5, '{"poet":"Tayyip Sağ","poet_slug":"tayyip-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hazan-yeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bodrum yağmurları Hasret Kokuyor Gülüm', 'bodrum-yagmurlari-hasret-kokuyor-gulum-murat-nail-guney-wziq8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bodrum yağmurları hasret kokuyor gülüm,

İlk ıslanışım sensiz bu mevsim caddelerde,

İlk içime çekişim toprak kokusuna karışan

Özlemlerimin sırılsıklam nefesini...

Ve sensiz,boynu bükük sevdam 

Dillere destan buralarda...

Sırf senin kokunu getirir diye

Denizden esen rüzgarlar,

Her gece bekliyorum Değirmenler Tepesi''ni...

Sen hiç mi sevmemiştin beni be gülüm? 

Hiç mi sevda incileri dökülmemişti,

avuçlarıma gözyaşlarından? 

Hiç mi yüreğine yansımamıştı

bedeninin sıcaklığı? 

Hiç mi uyuklamamıştın sabaha dek

kalemin elinde? 

Hiç mi canın acımamıştı

yere düşüp, benim gibi senin de? 

Sonra bir sigara yakıp,

yazmamışmıydın bunu dizelerine? 

Hele bir de ocağı açık bırakmamış mıydın

çaydanlık üzerinde? 

Demek ki...sen hiç sevmemişsin beni,

Deli dolu bir macera sayıp aşkımı,

Almışsın bir anlık hevesini.

Bak! yine sabah oldu...ezan okunuyor Allahu-ekber,

Bende unutayım bari

kulaklarımda çınlayan sesini.

Dilerim kimse yaşamaz: AYRILIĞIN BÖYLESİNİ...

murat nail güney

06/11/2004 saat:05:15  bodrum/marina', 'Bodrum yağmurları hasret kokuyor gülüm, İlk ıslanışım sensiz bu mevsim caddelerde, İlk içime çekişim toprak kokusuna karışan Özlemlerimin sı...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bodrum-yagmurlari-hasret-kokuyor-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-tayyip-sag-g7zcx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşılmaz yükseğin dumanlı dağlar,

Etrafın yemyeşil üstünde karlar,

Sılamda bekleyen nazlı yar ağlar,

Bırakmazsan deler geçerim dağlar.

Yıllardır bilirim dumanın kalkmaz,

Hasretim içime saplanmış çıkmaz,

Yürüdü kervanım yollarda durmaz,

Bırakmazsan yıkar geçerim dağlar.

Dağlar senin yükseğinde karın var,

Kenarında bahçelerin bağın var,

Taşkın akan derelerin çayın var,

Bırakmazsan taşar geçerim dağlar.

Tayyip''i  sen  ayrı koydun canandan,

Anlamadın hasretimden sevdamdan,

Sayamadım kaç yıl geçti aradan,

Bırakmazsan ezer geçerim dağlar.

  18.09.2004', 'Aşılmaz yükseğin dumanlı dağlar, Etrafın yemyeşil üstünde karlar, Sılamda bekleyen nazlı yar ağlar, Bırakmazsan deler geçerim dağlar. Yıllar...', ARRAY['Türk Edebiyatı','Şiir','Tayyip Sağ']::text[], 8.5, '{"poet":"Tayyip Sağ","poet_slug":"tayyip-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/daglar-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efkarlanma Deli Gönlüm', 'efkarlanma-deli-gonlum-tayyip-sag-ez3wm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dolaşırsın köşe bucak,

Dert açarsın kucak kucak,

Senin halin ne olacak,

Efkarlanma deli gönlüm.

Akar yaşın damla damla,

Unutulursun zamanla,

Bu Dünya''yı sende anla,

Efkarlanma deli gönlüm.

Şahin gibi tepelerde,

Senin evin barkın nerde,

Gezip dolaştığın yerde,

Efkarlanma deli gönlüm.

Bu Dünya''da her şey boşa,

Neler gelir garip başa,

Başın vurup taştan taşa,

Efkarlanma deli gönlüm.

Boz bulanık akar seller,

Taşar nehirler dereler,

Yaz baharda açar güller,

Efkarlanma deli gönlüm.

Tayyib''e dertmi sorulur,

Dertler yüreğe vurulur,

Her derde çare bulunur,

Efkarlanma deli gönlüm.

      28.08.2004', 'Dolaşırsın köşe bucak, Dert açarsın kucak kucak, Senin halin ne olacak, Efkarlanma deli gönlüm. Akar yaşın damla damla, Unutulursun zamanla,...', ARRAY['Türk Edebiyatı','Şiir','Tayyip Sağ']::text[], 8.5, '{"poet":"Tayyip Sağ","poet_slug":"tayyip-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/efkarlanma-deli-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam İçin', 'yasam-i-cin-oguz-ozyurt-urlmy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kara bulutlarla kaplanmışken gökyüzü,

Sıyrılıp düşlerinden,

Koşarken uzaklara...

Ayağın takılıp yuvarlansan sonsuz bir uçuruma,

Yine de mutlu olmalısın,

Güneşin hala parladığını bildiğin için,

Mutlu olmalısın yaşamı ve insanları sevdiğin için...', 'Kara bulutlarla kaplanmışken gökyüzü, Sıyrılıp düşlerinden, Koşarken uzaklara... Ayağın takılıp yuvarlansan sonsuz bir uçuruma, Yine de mutl...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Özyurt']::text[], 8.5, '{"poet":"Oğuz Özyurt","poet_slug":"oguz-ozyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yasam-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür Boyunca', 'omur-boyunca-hifzi-altumsek-8vup1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkı bende yaşasan

Kalsan ömür boyunca

Hiç bitmese bu rüya

Sevsen ömür boyunca

Nefes alsam sevginle

Olsam her an seninle

Yansam aşk ateşinle

Sevsen ömür boyunca

Senle huzur bulurum

Kollarında uyurum

Sana köle olurum

Sevsen ömür boyunca

Çiçeklenip açmam mı

Kanatlanıp uçmam mı

Binbir neş''e saçmam mı

Sevsen ömür boyunca', 'Aşkı bende yaşasan Kalsan ömür boyunca Hiç bitmese bu rüya Sevsen ömür boyunca Nefes alsam sevginle Olsam her an seninle Yansam aşk ateşinle...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Altümsek']::text[], 8.5, '{"poet":"Hıfzı Altümsek","poet_slug":"hifzi-altumsek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/omur-boyunca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıya Ve Kedere', 'aciya-ve-kedere-tunahan-ermihan-btuc7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağlamaklı bulutlar dolanıyor her gece

Rüyalarımın tam orta yerinde

Ben kurak çöllerin yegâne gülü kaktüs olmama rağmen

Bir tek sana susuyorum

Sense bundan haberdar değilsin

Ne adını anabiliyorum tüm kelimeler tükendiğinde

Nede anılarımızı hatırlayabiliyorum

Sen mi gitmiştin ben mi ardından çok ağlamıştım

Yoksa bizim için tüm ihtimaller rüzgârda mı savrulmuştu

Ki, ben bu gün kaktüs olduğumu bile unutup

Taşlaşmaya başladım

Sahi senin gözlerine vurgundu gözbebeklerim değil mi? 

Bakardım öyle deli deli

Yok yok ben esas o kıvır kıvır saçlarına vurgundum

Yoksa senin saçların düz mü idi

Gittiğin yol gibi

Geçmişimi kaybediyorum desem yeridir

Ben geleceğe bakmayı denedim sevdiğim

Denedim de bir seni göremedim

Masum gecelerde yapılacak yaramazlıklarda

Adın bile yazmıyordu gördüğüm rüyalarda

Şimdi vazgeçtim desem seni sevmekten

Sevmeyi hatırlamak gerekecek

En iyisi güzelim

Ben çöl çiçeği kum fırtınaları için ufalanıp

Hayat denen çöle salayım yüreğimi

Oradan hüzne oradan acıya ve kedere', 'Ağlamaklı bulutlar dolanıyor her gece Rüyalarımın tam orta yerinde Ben kurak çöllerin yegâne gülü kaktüs olmama rağmen Bir tek sana susuyoru...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/aciya-ve-kedere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Anadolum', 'guzel-anadolum-yavuz-agir-258lk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Özümü çardağa bağladım 

Çanağı çömleği ne eyleyeyim oğul

Gönlümü yanık türkülere bağladım

Mişel''i rak''ı  cazı ne eyleyeyim oğul

Anadolum cenete benzer 

Gezdikçe haz alırım oğul

Heleki sağlığım sıhatim yerinde ya

Londra''yı paris''i zürih''i ne eyleyeyim oğul

Ne eyleyeyim oğul  ne eyleyeyim', 'Özümü çardağa bağladım  Çanağı çömleği ne eyleyeyim oğul Gönlümü yanık türkülere bağladım Mişel''i rak''ı  cazı ne eyleyeyim oğul Anadolum cen...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/guzel-anadolum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Habersizdir çocuklar...', 'habersizdir-cocuklar-hasan-akin-g5tuw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeşil sabun kokusudur saçlarında gezinen

gölgesinde gezindiği sahici baharlardır.

heveslerdir yitip giden yetişkin sürgülerde

leğende yunan sabi ellerinde ananın

gözlerini yakan beyaz köpük tazesinde...

sıcak suyun değdiği yerlerinden titreyen

ömrün pembe çizgisidir çocuklar.

ve habersizdir ölümün ağulanmış sosundan

yapışır dedesinin paçalarına

masallar dinleyip uyur göğsünde

sonra masaldaki kahramanı rüyasında görür.

bir gün ölüm gelir

eğilir dedesinin kulağına

bilinmez bir şeyler fısıldar

ve bilinmez bir vakit

gider attaya dedesi.

ömrün pembe çizgisidir çocuklar

emzik emer, emekler kucağında hayatın

ya leylekler getirmiştir 

yada çayda tutulmuş.

ve birgün ölüm gelir

çocukları severken

onu alır götürür

ve çocuk rüyasında

attayı görür.

çünkü çocuklar

habersizdir ölümün ağulanmış sosundan.', 'Yeşil sabun kokusudur saçlarında gezinen gölgesinde gezindiği sahici baharlardır. heveslerdir yitip giden yetişkin sürgülerde leğende yunan ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akın']::text[], 8.5, '{"poet":"Hasan Akın","poet_slug":"hasan-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/habersizdir-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değil', 'degil-baran-can-i1x97', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gece vardiyasında; 

Cellat, gözlerimi susturdu,

Karanlık bir bantla.

Gözlerimi susturdu, 

Yüreğimi değil.

vücuduma cereyan  verdi,

Gecenin bir yarısında.

Yüreğim sarsıldı, bilmem kaç şiddetinde.

Yüreğim sarsıldı, beynim değil.

Sonra; 

Bir masanın üstünden,

Bilmem kaçıncı kattan,

Aşağı attı, intihar süsü vererek.

Bedenimi attı, 

Sevdamı değil.', 'Gece vardiyasında;  Cellat, gözlerimi susturdu, Karanlık bir bantla. Gözlerimi susturdu,  Yüreğimi değil. vücuduma cereyan  verdi, Gecenin b...', ARRAY['Türk Edebiyatı','Şiir','Baran Can']::text[], 8.5, '{"poet":"Baran Can","poet_slug":"baran-can","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/degil-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatar Kıza Mektup', 'tatar-kiza-mektup-kutalmis-tonyukuk-yilmaz-rmrpq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saat gecenin ikisi

Radyoda özlem dolu sıla ezgiler ses vermekte.

Kutuplardan kopma bir rüzgar esiyor,

Esiyor ve perdelerini şişiriyor pencerenin

Daha da bir sokuluyor içeri

Duvarlarını yalıyor odamın

Estikçe beni de katıyor önüne

Sürüklüyor kuşkusuz geceye...

Şimdi bahar bahar çağlayan,

Irmaklar içmiş gözlerinde

Esaretim hüküm sürmekte

O asil ama mağrur

O cesur ama ürkek

O muhteşem ama emsalsiz soyluluğunu süzmekteyim

Oyalı gülüşünden.

Daha da bir uzuyorum geceye

Rüzgar esiyor, 

Gözlerinin coğrafyasına götürüyor beni 

Bir Asya gecesinde buluyorum seni

Oracıkta demine dip vuruyorum gecenin

Gözlerini yeşiline vuruluyorum

Vuruldukça sevdalanıyorum sana yine yeniden

Çekik gözlerinin düzlüğüne seriveriyorum sevdamı

Umarsızca kanat çırpıyor kirpiklerin

Sonra geceye renk veriyor naralarımız

Bir menzilden ötekine yetiyoruz

Uzuyoruz lacivert sonsuzluğa...



Kutalmış Tonyukuk YILMAZ    21 Ağustos 1998, Ankara

* İşbu Şiir Şairinin Adına Kayıtlıdır. Kayıt Tescil No: 206188161255', 'Saat gecenin ikisi Radyoda özlem dolu sıla ezgiler ses vermekte. Kutuplardan kopma bir rüzgar esiyor, Esiyor ve perdelerini şişiriyor pencer...', ARRAY['Türk Edebiyatı','Şiir','Kutalmış Tonyukuk Yılmaz']::text[], 8.5, '{"poet":"Kutalmış Tonyukuk Yılmaz","poet_slug":"kutalmis-tonyukuk-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/tatar-kiza-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asla', 'asla-ergun-terzioglu-vbu6i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrılığına; 

Yazmayacağım! 

Mısra mısra hıçkıracak,

Beyit beyit boğulacak...

... Ve inat; 

Ağlamayacağım!', 'Ayrılığına;  Yazmayacağım!  Mısra mısra hıçkıracak, Beyit beyit boğulacak... ... Ve inat;  Ağlamayacağım!...', ARRAY['Türk Edebiyatı','Şiir','Ergün Terzioğlu']::text[], 8.5, '{"poet":"Ergün Terzioğlu","poet_slug":"ergun-terzioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/asla-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-sair-selma-4xmhv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yol var.Ve ben o yolda sürükleniyorum.

Etrafıma bakıyorum,herşey tozpembe.

Daha önce hiç duymadığım birşeyler yankılanıyor kulaklarımda.Bu huzurun 

sesi olmalı.Beni benden alıp rüyalarıma götürüyor.

Hayalini bile kuramadığım bir aşkım var şimdi.Tertemiz,su gibi...

Bambaşka birşey bu.Anlatamam.

Haykırmak istiyorum ''İşte ben böyle seviyorum'' diye.

Ama hepsi boğazımda,düğüm düğüm.

Tanrım uyanıcaksam eğer,eğer bu rüya da çoksa bana,gözlerimi o soluksuz 

karanlıkta açmak istiyorum...

Ya da bırak sonsuz rüyamda kalayım...', 'Bir yol var.Ve ben o yolda sürükleniyorum. Etrafıma bakıyorum,herşey tozpembe. Daha önce hiç duymadığım birşeyler yankılanıyor kulaklarımda....', ARRAY['Türk Edebiyatı','Şiir','Şair Selma']::text[], 8.5, '{"poet":"Şair Selma","poet_slug":"sair-selma","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ruya-146-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Bir Şey ESKİSİ GİBİ Değil', 'hic-bir-sey-eski-si-gi-bi-degil-zubeyde-yilmaz-ie8ti', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bulutlar bulut değil,

Sevişmeleri bitmiş kızıl laleyle,

Dağlar eskisi gibi gibi heybetli gülümsemiyor,

Yağmurlar eskisi düşmüyor ıssız bedenime...

Güneş eskisi gibi yakmıyor karanlığımı,

Aldığım nefes eskisi gibi dolmuyor içime,

Sigaram eskisi gibi keyif vermiyor 

Dumanı resimler çizmiyor sessizliğimin içine

Hüznüm fukara oldu berduş gecelerde

Çiçeklerimin boynu bükük, öksüz kaldılar üşüyen ellerimde

Sesim eskisi gibi dansetmiyor ateşler içinde

Şarkılar eskisi gibi alıp götürmüyor,diyar diyar yaban ellere

Kıvılcımlar mahkum artık tutuklu göğsümde

Sebebim sebebinde asılı,

Gözlerin....

______________Eskisi gibi bakmıyor gözlerime....', 'Bulutlar bulut değil, Sevişmeleri bitmiş kızıl laleyle, Dağlar eskisi gibi gibi heybetli gülümsemiyor, Yağmurlar eskisi düşmüyor ıssız beden...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Yılmaz']::text[], 8.5, '{"poet":"Zübeyde Yılmaz","poet_slug":"zubeyde-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hic-bir-sey-eskisi-gibi-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Bilir?', 'kim-bilir-ergun-terzioglu-q387b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Canımı acıtıyor; 

An be an büyüyen,

Ateş gibi özlemin...

Korkarım unutamıyacağım seni...

Kim bilir; 

Unutmak istemiyorumdur belki,

Belkide; isteyemiyorumdur...

Kim bilir...?', 'Canımı acıtıyor;  An be an büyüyen, Ateş gibi özlemin... Korkarım unutamıyacağım seni... Kim bilir;  Unutmak istemiyorumdur belki, Belkide; ...', ARRAY['Türk Edebiyatı','Şiir','Ergün Terzioğlu']::text[], 8.5, '{"poet":"Ergün Terzioğlu","poet_slug":"ergun-terzioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kim-bilir-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Artık..', 'gel-artik-sair-selma-z8dgy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geleceksen gel artık 

Ya da bırak ben geleyim

Hadi kapat gözlerini

Bırak düşlerinde geleyim

Hadi aç kollarını bana

Kollarına geleyim

Hadi artık

Bırak kendini karanlığa

Düşlerinde olayım...', 'Geleceksen gel artık  Ya da bırak ben geleyim Hadi kapat gözlerini Bırak düşlerinde geleyim Hadi aç kollarını bana Kollarına geleyim Hadi ar...', ARRAY['Türk Edebiyatı','Şiir','Şair Selma']::text[], 8.5, '{"poet":"Şair Selma","poet_slug":"sair-selma","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gel-artik-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Düşü', 'bayram-dusu-kutalmis-tonyukuk-yilmaz-5oyvo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'babam öğretmişti kadifeyle iskarpinin sevdasını

vurdukça kadifeyi iskarpine

aşkın gözlerini görürsün demişti ışıldayan

yaş on bir fiyaka boğaziçi kundura cilası

gözlerini çıkartmıştım aşkın kundura parlatmaktan

çorabımdan firar etti edecek 

başparmağıma aldırmadan

arife gecesinden takmıştım ayaklarıma

siyah bağcıklı kahverengi iskarpinimi

üzerime de annemden sütlü kahve bir takım

iskemlede sabahı bekleyen metanetli bir takım 

sonra dalardık uyku numarası gözlerle düş sokaklarına

siyah bağcıklı kahverengi iskarpinimin

geniş arnavut kaldırımları vardı yürümesi uçmak

kelebek kanatlanırdı iskarpinim

bağcıkları eşit sarkardı

bağcıklardan ince gülüşler sarkardı

babam annem kardeşim önden ben arkalarından

uçarken önüme bakmadığımdan

şiir gibi azarlardı babam

düş(ev)   lerinden kaçmış çocuklar vardı

koşabilen ancak uçamayan 

neden numaradan uyumazlar ki 

kutalmış tonyukuk yılmaz    2002 Giresun

* İşbu Şiir Şairinin Adına Kayıtlıdır. Kayıt Tescil No: 206195169081', 'babam öğretmişti kadifeyle iskarpinin sevdasını vurdukça kadifeyi iskarpine aşkın gözlerini görürsün demişti ışıldayan yaş on bir fiyaka boğ...', ARRAY['Türk Edebiyatı','Şiir','Kutalmış Tonyukuk Yılmaz']::text[], 8.5, '{"poet":"Kutalmış Tonyukuk Yılmaz","poet_slug":"kutalmis-tonyukuk-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bayram-dusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Sen*', 'sen-zubeyde-yilmaz-twb1o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen...

İçime ya da dışıma düşmedin

Bendeydin zaten öbek öbek dolanıyordun gönlümde

Yıllarca biriktirdğim,yudum yudum içtiğim 

Adaklar adayıp al yazmalı çaputlar bağladığım gecelerde

Dileklerimdeydin,umarsızca prangalar bağlayıp bileklerine

Sevi zindanlarında köle yaptığım düşlerimdeydin

Ferman bugüne yazılmış kalem yazmış dil söylemiş

Estin kaçışlara inat dağlarından dingin denize

Kudurdu,köpük köpük dalgalar

Delice yırttı geceyi,salkım salkım

Aşk...Aşk diye vaatler kusan yıldızlar

Ey sesime yankı veren ıssız ormanlar

Duydum...Sevdam ellerimdeymiş

________________Sen kadar...

______________________-Yüreğin kadar

____________________________Ben kadar

Artık seninle aydınlık yatağımda sabahlar.....', 'Sen... İçime ya da dışıma düşmedin Bendeydin zaten öbek öbek dolanıyordun gönlümde Yıllarca biriktirdğim,yudum yudum içtiğim  Adaklar adayıp...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Yılmaz']::text[], 8.5, '{"poet":"Zübeyde Yılmaz","poet_slug":"zubeyde-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-471-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gece Yarısı Şiiri', 'bir-gece-yarisi-siiri-barbaros-emre-15jsb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Duygususuzdur belki görünüşte

Kimse bilmez neler oluyor içimizde

Belki de içimizde ki yalnızlığın dışa vurumudur

Acımasız tavrımız

Enzayıf noktamız

İçimizde büyüttüğümüz karşılıksız 

Sahibinin bile adını bilmediği 

O eşsiz,can alan,yürek yakan

Sevdamızdır 

Biz harbi aşkın çilesini çeken birer köleyizdir', 'Duygususuzdur belki görünüşte Kimse bilmez neler oluyor içimizde Belki de içimizde ki yalnızlığın dışa vurumudur Acımasız tavrımız Enzayıf n...', ARRAY['Türk Edebiyatı','Şiir','Barbaros Emre']::text[], 8.5, '{"poet":"Barbaros Emre","poet_slug":"barbaros-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-gece-yarisi-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgunum', 'yorgunum-zubeyde-yilmaz-ilcfv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yorgunum...

Dön desem dönmeyeceksin.

Biliyorum...

Suskunum...

Anlatışlar uzun,gereksiz

Anlayamayacaksın...

Gölgelere gizlendim...

Gidiyorum...', 'Yorgunum... Dön desem dönmeyeceksin. Biliyorum... Suskunum... Anlatışlar uzun,gereksiz Anlayamayacaksın... Gölgelere gizlendim... Gidiyorum....', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Yılmaz']::text[], 8.5, '{"poet":"Zübeyde Yılmaz","poet_slug":"zubeyde-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yorgunum-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytana yakalandım', 'seytana-yakalandim-aydin-bayrakdar-8vl0d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şeytana yakalandım

Azeri Şair Kerimî''ye(gerçek adı: Muhammed Ali Zakiroğlu, doğumu: Merağa 1931)   sevgi ve hürmetlerimle

Yakama yapışdı şeytan dün akşam,

''Hani nerde benim rüşvetim? '' dedi.

''Zor bulunur senin gibi oyuncak,

Yerden yere vurmak niyetim'' dedi.

Geçende üşüdüm, hasta olmuşum,

Şeytan dürtmüş, yanlış yola dalmışım,

Tedbir almamışım, yolda kalmışım,

''Sana iyi gelir şerbetim'' dedi.

Etme şeytan, git başımdan yorgunum,

senden hayır gelmez, billah dargınım.

Dedi: ''son zamanlar ben de durgunum,

seni unutmuşum, hayretim'' dedi.

''Ne biçim Aydın''sın, sürünüyorsun? 

Keyfli günde bana görünüyorsun,

bin günah işleyip geriniyorsun,

günah işlememen afetim'' dedi.', 'Şeytana yakalandım Azeri Şair Kerimî''ye(gerçek adı: Muhammed Ali Zakiroğlu, doğumu: Merağa 1931)   sevgi ve hürmetlerimle Yakama yapışdı şey...', ARRAY['Türk Edebiyatı','Şiir','Aydın Bayrakdar']::text[], 8.5, '{"poet":"Aydın Bayrakdar","poet_slug":"aydin-bayrakdar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/seytana-yakalandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmiş Olmalılar', 'gelmis-olmalilar-zubeyde-yilmaz-p1qzj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kara bahtlıymışsın ya sen hani

Binlerce kelebekler uçurdum toz pembe

Dağları  aştılar dertleri eleyip

Denizleri yaladılar minicik kanatlarıyla

Küçük kızın ölümcül düşlerinden

Belki birazcık umut,birazcık zeytin düşleri

Şehrinden birazcık kurşun gibi aşk

Dudaklarına en anlamlı mühür

Gözlerine turnanın sevdaları

gelmiş olmalılar

Öylesine...Sessiz

Öylesine...İçten

Ve taa yüreğimden...', 'Kara bahtlıymışsın ya sen hani Binlerce kelebekler uçurdum toz pembe Dağları  aştılar dertleri eleyip Denizleri yaladılar minicik kanatlarıy...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Yılmaz']::text[], 8.5, '{"poet":"Zübeyde Yılmaz","poet_slug":"zubeyde-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gelmis-olmalilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mükâfaat', 'muk-faat-aydin-bayrakdar-fls3c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hayatımda fantaziye yer yokdu

en güzele talib oldum seninle

aşkın yüreğime bir hançer sokdu

uçacakdım yaya kaldım seninle

yeni sevda yeni derdler demekmiş

yeni derdler tekerimde çomakmış

kalbe saray kurmak boşa emekmiş

sen girmedin ama ben doldum seninle

yokluğunu yazdım birinci fasıl

sormadım kimseye bu mudur usul

ellerimi tutan ellerin nasıl

tatlı bakışında güldüm seninle

gelmedin gelmedin sonunda geldin

zahmete katlanıp yaşımı sildin

kederi çileyi içimden aldın

yaşamak çok güzelmiş bildim seninle.', 'hayatımda fantaziye yer yokdu en güzele talib oldum seninle aşkın yüreğime bir hançer sokdu uçacakdım yaya kaldım seninle yeni sevda yeni de...', ARRAY['Türk Edebiyatı','Şiir','Aydın Bayrakdar']::text[], 8.5, '{"poet":"Aydın Bayrakdar","poet_slug":"aydin-bayrakdar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mukafaat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldürenler Var SEVGİYİ', 'oldurenler-var-sevgi-yi-zubeyde-yilmaz-ew6qa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bencil ruhlar öldürüyor sevdiği herşeyi

kılıçlar çoktan çıkmış kınından

kimi acı bir bakışla nefesleri

kimi ürkek fısıldayarak kini

Korkak...ÖPEREK ÖLDÜRÜYOR

Yüreklisi kılıçla,kırpmadan gözlerini

Sen sevdamın en kıdemli bekçisi

Günahınla yaklaş,uzat bana kendini

Saç gömülerini pervasız çağla yeşili

Uğuldat köşe bucak kaçak dövüşenleri

Taşır nehrimi,çiçeklensin sevgiler dal uçlarında...', 'bencil ruhlar öldürüyor sevdiği herşeyi kılıçlar çoktan çıkmış kınından kimi acı bir bakışla nefesleri kimi ürkek fısıldayarak kini Korkak.....', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Yılmaz']::text[], 8.5, '{"poet":"Zübeyde Yılmaz","poet_slug":"zubeyde-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/oldurenler-var-sevgiyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirleri Ağlatan Kadın', 'siirleri-aglatan-kadin-kamil-aydemir-40rx1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kanarken bir şair

          yürek tezgahında örebilir mi gülen şiir

gündüzlerin yanaklarına yaş düştüğünde

düştüğünde gecenin karanlığına bir yıldız

umutlarım benden kopar

içimde darbe yapar acılar

bundandır gelinciklerin gülüşlerindeki yırtıklar

bundandır martıların sevinçlerindeki yamalıklar

bilirim her acının bir ilacı var

acılarımın ilacı sensin nazlı yâr

sevgi sıcaklığında erir sevinçlere yağan kar

yüreklere gelir bahar

bir insan kendini nasıl öldürür

düşmek istemiyorsan berbat hayatın tuzağına

savrulma sevginin uzağına

içinde acılar kudurur

hüzünler hep seni bulur

gözlerinden kayan her damla

gelir beni vurur

senin olmadığın yerde

benim için hayat durur

şiirleri ağlatan kadın

hüzün müydü senin adın

ben kapılarını yalnızlığa

  kapılarını açlığa puştluğa açan

ve hep benden bir şeyler alıp kaçan

kokuşmuş günlerden geliyorum

geliyorum düşlerim uğruna sürgünlerden

razıyım acılarına hüzünlerine

yeterki sen de fırtına olma

yakanda ahım kalır

kâmil aydemir sevgisi bu

senden gelecek ölümü bile öpücük niyetine alır

hayatın hoyratlığında çok hırpalandı

kırık zeytin dalı sevdalı yüreğim

aramıza korku duvarlarını örme

seni salkım saçak seveyim

ne olursun beni umutsuzluk çukuruna atma

yarınlarımı karaltma 

atmacalara yem olur düşlerim

dönüşsüz gider gülüşlerim

içimdeki notalar susar olurum lâl

işte yüreğim hep mutluluk şarkıları çal

kılavuzun olsun sevgim

hüzün okyanusunda bata

şiirleri ağlatma

hayat ağlar

aydınlıklar kara yazma bağlar

unutma acılar seninde yüreğini dağlar

rengini insandan alır hayat

her zaman adımlarını sevgiden yana at

gül bahçesi olsun gülüşlerin

cennetim memleketim gibi güzel gözlerin

uzağına düşme insanlığın

yaralarda olur izlerin

emek koksun terin

kanatları umut işlemeli güvercin yüreğin

kapılarını aşka sevgiye kapatan

ve şiirleri ağlatan kadın

acı mıydı senin adın

başaramasın diye sevgim sana da sevmeyi öğretmeyi

nasıl beceriyorsun

pırlantalardan daha değerli yüreğini

kör ve sağır etmeyi

böylesine korkman neden aşktan

sevmediğinle aynı yatağı paylaşmaktan

daha zor geliyorsa sana beni sevmek

kelebeğin kanadından dökülürken hayat

sen yalnızlığına sarılda yat

yakalamak istiyorsan güzel güneri

adımlarını aşktan yana at

al yarınlarımı yarınlarına kat

benim aşkım serçe gibidir terk etmez ülkesini

sen hiç dinlemez misin yüreğinin sesini

gülemesin kurutursan gönül bahçesini

çıkar artık üzrindeki korku elbisesini

hiç düşünmeden avucuna koyarım canımı ama

isteme benden sevdamın katilliğini

bir insan nasıl ölüdürür sevgisini

aldırmayacağım

içimdeki güzellikleri de donduran ayazlarına

umutlarımı kırıp döken fırtınalarına

beni diri diri yakan cehennemlerine

sevgimle hep yürek kapına  varacağım

seni seninle barıştırmak

  seni mutluluğun doruğuna ulaştırmak için

gerekirse önünde diz çöküp yalvaracağım

bana aşkı öğreten kadın

kalbimin çiçeği olsun mu senin adın

güneş misket oynarken gamzelerinde

diğer mevsimler geri durur

bahar olur bende

sen zamana güzelliğini giydirende

hınzır düşlerim malum yerlerinde

 gözlerim dans eder kalçalarında

parmaklarım çiçek çiçek dolanır teninde

arzularım arzularınla halay çeker beyninde

varıp iki yalçın dağının uçlarına

hayatı seyretmek gelir içimden sevişme tadında

yangınlarım söner dudaklarında

ay yuva yaparken saçlarında

kalbimin çiçeği susabilir miyim koynunda

mutluluğum sensin hayat oyununda

sanmaki sen gidice bu sevda biter

beni hasretin avuçlarına bırakıp gitme

gidişin yağlı imlek olur boynumda

her gün ölürken bir şair

gülen şiirler bırakabilir mi ardında', 'kanarken bir şair           yürek tezgahında örebilir mi gülen şiir gündüzlerin yanaklarına yaş düştüğünde düştüğünde gecenin karanlığına bi...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":108,"source_url":"https://www.antoloji.com/siirleri-aglatan-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şekilli ölüm', 'sekilli-olum-halit-i-nce-sw09r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Canım bu bedenden çıksın! 

Ruhum çevrende dolansın! 

Kötülükten korusun seni

Sevdiğim hep mutlu kalsın! ...

Senin, sesini duyarak! 

Gözlerine bakarak! 

Ellerini tutarak,

Ölmeyi çok isterim.

Gözlerim açık gitsin! 

Tanrım, ne istersen versin! 

Tehlikeden korusun seni,

Her günün güzel geçsin! 

Ben, sesini duyarak! 

Gözlerine bakarak! 

Ellerini tutarak! 

Ölmeyi çok isterim...', 'Canım bu bedenden çıksın!  Ruhum çevrende dolansın!  Kötülükten korusun seni Sevdiğim hep mutlu kalsın! ... Senin, sesini duyarak!  Gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Halit İnce']::text[], 8.5, '{"poet":"Halit İnce","poet_slug":"halit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sekilli-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorma beni kimseye!', 'sorma-beni-kimseye-halit-i-nce-rlrwg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni kimseye sorma! 

Kimseye sorma beni...

Beni dağlara sorma! (-kıskanırlar)

Dağlar benim gibi dikilmedi...

Sevenlere sorma beni (-özenirler)

Onlar aşık değil benim gibi...

Görenlere sorma beni (-bakınırlar)

Kör olmadılar benim gibi...

Kuşlara sorma beni (-kanatlanırlar)

Yanındayken uçmadılar...

Bulutada sorma beni (-kaybolur)

Ben yağarken hiç görmedi...

Kimse görmedi senden sonra

Beni kimseye sorma! 

Kimse beni ağlarken görmedi..

Kimseye sorma beni...

Beni ölülere sorma! (-dirilirler)

Onlar benim kadar ölmedi...

Kimse beni ölürken görmedi 

Kimseye sorma beni! 

Beni yaşayanlara sorma (-bilmezler)

Kimse beni yaşarken görmedi.

Kimseye sorma beni! 

Ben hiç yaşamadım ki!', 'Beni kimseye sorma!  Kimseye sorma beni... Beni dağlara sorma! (-kıskanırlar) Dağlar benim gibi dikilmedi... Sevenlere sorma beni (-özenirle...', ARRAY['Türk Edebiyatı','Şiir','Halit İnce']::text[], 8.5, '{"poet":"Halit İnce","poet_slug":"halit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sorma-beni-kimseye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin yanında', 'senin-yaninda-halit-i-nce-yvl5i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karanfiller denize, atıldığında

                      Sanki cennetteydim, senin yanında

Gözlerin parlarken, sahil yolunda

                      Sanki cennetteydim, senin yanında

Saçların uçarken, esen rüzgarda

                      Sanki cennetteydim, senin yanında

Yağan yağmur, iki kumru ıslattığında

                      Sanki cennetteydim, senin yanında

Ellerin ellerimle, kavuştuğunda

                      Sanki cennetteydim, senin yanında

Yolda yürürken, kolum altında

                      Sanki cennetteydim, senin yanında

Son yolun solunda, sarıldığımda

                      Sanki cennetteydim, senin yanında

...

Şimdi kayboldum, senden uzakta

      Sensiz cehennem, bu dünya bana...', 'Karanfiller denize, atıldığında                       Sanki cennetteydim, senin yanında Gözlerin parlarken, sahil yolunda                   ...', ARRAY['Türk Edebiyatı','Şiir','Halit İnce']::text[], 8.5, '{"poet":"Halit İnce","poet_slug":"halit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/senin-yaninda-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayanın Soranın Yok!', 'arayanin-soranin-yok-kadir-soyturk-n4u7a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dönerci Kardeşime

Ne beklersin burda garib

Arayanın  soranın  yok! 

Sana ilaç vermez tabib

Arayanın  soranın  yok! 

Kimi sarı, kimi kara

Yol gözle,müşteri ara

Sen ne yaptın insanlara

Arayanın soranın Yok! 

Ustabaşı  emekliyor

Geceyi  güne  ekliyor

Dükkan  müşteri  bekliyor

Arayanın  soranın  yok! 

Dükkan  geliyor sana dar

Beklemekte ne kârın  var

Saat  24 e  kadar

Arayanın  soranın  yok! 

Gel  kendini  sokma  zora

Başka  yerde  rızık  ara

Sana  şans  getirmez  bura

Arayanın  soranın  yok! 

          Dilbeek/Bruksel  06/11/2004

                                      19:45', 'Dönerci Kardeşime Ne beklersin burda garib Arayanın  soranın  yok!  Sana ilaç vermez tabib Arayanın  soranın  yok!  Kimi sarı, kimi kara Yol...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/arayanin-soranin-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Hayatımı Çalmak', 'benden-hayatimi-calmak-burcu-karakaya-zbicq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geçip giden günlere dur diyemez kimse

Sen bir benle iki ederler yalan oldu son sözlerinde

Her işittiğim söz karşısında

Asildim

Dinledim sordum dinledim sordum

Defalarca bekledim

Evet biliyorum

Veremeyeceğin şeyleri senden istemek

Benim küstahlığım

Çok istesem de istenmeyenler sınıfındakiler...

Her uyku arası, özgürce sana uçuşlarım

Mutlu etmiyor beni biliyorum

Tutamıyorum sana kanatlanıyor

Duygularım...

Ne aradığını bilmeden 

Nerelere gidişlerin bilmem ama 

Bitmiyor sana olan duygularım! 

Her genç kızın istediklerinden farklı değildi

Mutluluklarım

Ayrılık esir etti beni bu gece

Beni sensiz bırakan her şeye herkese kinim.

Gerçek olan sadece A.Ş.K

Arkasına sığınarak istenen

Benden hayatımı çalmak...sa eğer

Elveda sana A.Ş.K

Vicdanım yerinde başım dik bırakıyorum seni

Farklı zamanların insanlarıyız şimdi.', 'Geçip giden günlere dur diyemez kimse Sen bir benle iki ederler yalan oldu son sözlerinde Her işittiğim söz karşısında Asildim Dinledim sord...', ARRAY['Türk Edebiyatı','Şiir','Burcu Karakaya']::text[], 8.5, '{"poet":"Burcu Karakaya","poet_slug":"burcu-karakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/benden-hayatimi-calmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benliğin Gücü', 'benligin-gucu-burcu-karakaya-zsipl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok düşündüm neden bu kadar engel

Çaresizliğe düştüm de 

Hep sen çıkardın beni bu cehennemden...

Hiç yaşanmayan duygular

Alışık olmadığım bir maske

Çıkarmak için can atan bir beden

Senle dolu olmak mı beni bu kadar güçlü kılan

Önüme çıkan her zorlu yolu

Koşmak için kanat çırpmam

İçimde kopan fırtınaları 

Durdurmadan devam edişim...

Ne için ne zamana kadar 

O kadar çok ki bilinmeyenler

Denklem çözmek mi benim zaferlerim.

Yoksa masum bir benliği yok ediş mi! 

Her şeyler tamamlanınca bitecek mi 

Yoksa bir ömür mü sürecek

Seni sensiz yaşamaklar son bulduğunda

Tekrar sensizliklere geri dönecek miyim! 

Daha erken derken birçok şeye

Gelecek affedecek mi yitirdiklerimizi...

Sevginin zirvesine dikilen bayrak 

Dalgalanabilecek mi özgürce...

Sorular ve cevapları son bulmasa da asla

Emin olduğum tek şey koca yürekler taşıdığımız

Yap bozların sınırsız olduğu

Kısa yaşamda...

Başımızı hep dik tuttuğumuz.

06/07/2004

C.Burcu Karakaya', 'Çok düşündüm neden bu kadar engel Çaresizliğe düştüm de  Hep sen çıkardın beni bu cehennemden... Hiç yaşanmayan duygular Alışık olmadığım bi...', ARRAY['Türk Edebiyatı','Şiir','Burcu Karakaya']::text[], 8.5, '{"poet":"Burcu Karakaya","poet_slug":"burcu-karakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/benligin-gucu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönerci', 'donerci-kadir-soyturk-namn6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Usta yorulmadı döner başında

Ben masada beklemekten yoruldum! 

Kopup hayallerim olmuş bin parça

Birbirine eklemekten yoruldum! 

Ne sanatkâr! Görmek lazım o  ânı

Hazır etmiş domatesi,soğanı

Zaman adam eder,çıplak doğanı

Ben lokmayı çiğnemekten yoruldum! 

Biri burda,doğuda bir ayağı,

Fatih gibi açacakmış bir çağı

Elinde koca bir döner bıçağı

Yeter artık dur demekten yoruldum

Dağlar kadar olsa yine az diyor

Çok oku,çok düşün; çok cok yaz diyor

Cehaletin kuyusunu kaz diyor

Ağlamaktan,inlemekten yoruldum! 

                            Dilbeek/Bruksel

                                06/11/2004

                                     19:45', 'Usta yorulmadı döner başında Ben masada beklemekten yoruldum!  Kopup hayallerim olmuş bin parça Birbirine eklemekten yoruldum!  Ne sanatkâr!...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/donerci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yil Donumu', 'yil-donumu-rengin-gardner-6f6be', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Koskoca bir yil gecti aradan

Senli hayallerime veda ederek

Yoruldu bu yurek seni tasimaktan

Dokunmadan seni severek

Varliginla yoklugun ayni benim icin

Seni sevmekle, tarafindan sevilmemek gibi

Yuzum sana gulumser, aglarim icin icin

Kimbilir belki kabullenirim, gecici birlikteligi

Ne dersin ogrenebilirmiyim, seni sevmemeyi,

Alisamayacagima gore, sevilmemezlige,

Basarmaliyim, kalbimden seni yok etmeyi

Ne dersin ogrenebilirmyim, ''elveda'' demeyi.

Seninle gecen koskoca bir yili geride birakiyorum

Ilk gordugum an gibi, derin bir askla seviyorum.

Elvedalari sildim sozlugumden,

Uyandigim her yeni gune, sen varsin diye sukrediyorum.

Rengincik   kasim 7 2004', 'Koskoca bir yil gecti aradan Senli hayallerime veda ederek Yoruldu bu yurek seni tasimaktan Dokunmadan seni severek Varliginla yoklugun ayni...', ARRAY['Türk Edebiyatı','Şiir','Rengin Gardner']::text[], 8.5, '{"poet":"Rengin Gardner","poet_slug":"rengin-gardner","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yil-donumu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yelken Açacağım.', 'sana-yelken-acacagim-ali-osman-yilmaz-v365s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensizliğin ve yalnızlığınla,

Cebelleşip duruyorum.

Hüzün dolu şarkılar,

Biten aşkımızı anlatıyor.

Sen bir yöne,ben başka yöne,

Gidiyoruz meçhule.

Yeniden aşık olmak,

İstiyoruz ama olmayacak,

Ben senden başkasına,

Sen benden başkasına,

Aşık olamayız ki,

Nasılsa bitecek,

O aşklarda.

Ben enginlerin bir ucunda,

Sen diğer ucunda olacaksın.

Bineceğim bir tekneye,

Sana yelken açacağım,

Sen her zaman ve daima,

O Kıyıda,o sahilde,

Beni bekleyeceksin.

Çünkü kader dediğin,

Allahsız o iblis var ya,

Beni sana,seni bana,

Mahkum etmiş,

Bir ömür sonsuzluğuna,', 'Sensizliğin ve yalnızlığınla, Cebelleşip duruyorum. Hüzün dolu şarkılar, Biten aşkımızı anlatıyor. Sen bir yöne,ben başka yöne, Gidiyoruz me...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sana-yelken-acacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeye Koşul Olmaz.', 'sevmeye-kosul-olmaz-ali-osman-yilmaz-f0t0m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgiye koşul olmaz,

Koşulsuz olur sevmek.

Almadan bir şeyleri,

Bir ömür boyu,

İstemeden vermek.

Aşk denen şey budur,

Sevmenin başka da,

Yolu yoktur.', 'Sevgiye koşul olmaz, Koşulsuz olur sevmek. Almadan bir şeyleri, Bir ömür boyu, İstemeden vermek. Aşk denen şey budur, Sevmenin başka da, Yol...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevmeye-kosul-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Enginlerin Ortasındayım.', 'enginlerin-ortasindayim-ali-osman-yilmaz-rpwz6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Enginlerin ortasında,

Bir teknedeyim.

Tekne sensiz,

Tekne yelkensiz,

Üstelik küreksiz,

Ve içinde ben,

Bir başıma çaresiz,

Enginlerin ortasındayım.

Sana ulaşmak için,

Bilmiyorum,ne yapmalıyım? 

Ellerimden kürek,

Umutlarımdan yelken,

Sana olan sevgimden,

Fırtınalar yaratmalıyım.

Fırtınanın kanatlarına binip,

Bu gece olmadan mutlaka,

Sana sarılmalıyım.', 'Enginlerin ortasında, Bir teknedeyim. Tekne sensiz, Tekne yelkensiz, Üstelik küreksiz, Ve içinde ben, Bir başıma çaresiz, Enginlerin ortasın...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/enginlerin-ortasindayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döneceğim Kollarına.', 'donecegim-kollarina-ali-osman-yilmaz-xrxh8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saati kurup,

Koydum yanı başına.

Uyandıramadım seni,

Eğer uyanmış olursan,

Bırakıp gidemezdim seni.

O yüzden uyandırmadan,

Sessizce gidiyorum,

Akşam olunca yeniden,

Döneceğim kollarına,

Hem de bu sefer,

Yıldızları kucaklayarak,

Sana geleceğim.', 'Saati kurup, Koydum yanı başına. Uyandıramadım seni, Eğer uyanmış olursan, Bırakıp gidemezdim seni. O yüzden uyandırmadan, Sessizce gidiyoru...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/donecegim-kollarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepsini Kandırıyorum', 'hepsini-kandiriyorum-bora-yalamanoglu-wwmzl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uyumak için gözlerimi kapıyorum sanıyor herkes

Hepsini kandırıyorum,

Sen olmasan gözlerimin perdesinde,

Niye gireyim ki o soğuk yatağın içine her gece

Görmek için gözlerimi açıyorum sanıyor herkes

Hepsini kandırıyorum,

Sen olmasan göz bebeklerimde,

Nasıl bakarım senin güzelliğine

Yaşamak için kalbim atıyor sanıyor herkes

Hepsini kandırıyorum,

Sen olmasan kanım niyetine,

Kim bilir ben ölü müyüm diri miyim diye', 'Uyumak için gözlerimi kapıyorum sanıyor herkes Hepsini kandırıyorum, Sen olmasan gözlerimin perdesinde, Niye gireyim ki o soğuk yatağın için...', ARRAY['Türk Edebiyatı','Şiir','Bora Yalamanoğlu']::text[], 8.5, '{"poet":"Bora Yalamanoğlu","poet_slug":"bora-yalamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hepsini-kandiriyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İdea', 'i-dea-tabir-gokce-l2sto', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dokunsan 

Yılkı atıdır yürek 

Esriktir 

Türevi sen 

Ki; sevinci 

Yanağını ıslatan inci 

Güneşe kavuştuğunda tan 

Göz bebekleri büyür 

Küçülür dünya 

Sokulsan 

Savruk hayaldir bilinç 

Yektadır 

Çeşnisi sen 

Ki; erdemi 

Belleğini sarmalayan erinç 

Toprağa düştüğünde cemre 

Filizlenir tohum 

Çoğalır dünya 

Yok olsan 

Manasız yazgıdır ömür 

Yitimdir 

Sebebi sen 

Ki; mihengi 

Hasret noktasındadır fer’in 

Perdesi düştüğünde sahne 

Oyun biter 

Tükenir dünya 

-Kapanır göz tutsak olursun', 'Dokunsan  Yılkı atıdır yürek  Esriktir  Türevi sen  Ki; sevinci  Yanağını ıslatan inci  Güneşe kavuştuğunda tan  Göz bebekleri büyür  Küçülü...', ARRAY['Türk Edebiyatı','Şiir','Tabir Gökçe']::text[], 8.5, '{"poet":"Tabir Gökçe","poet_slug":"tabir-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/idea-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek İnsan Olmaktır.', 'sevmek-i-nsan-olmaktir-ali-osman-yilmaz-3u0zf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşık olmak,

Özgürlüğe kanat açmaktır.

Özgür olmak,

Yalnızlık demektir.

Peki yalnızlık? 

Özgürlük mü demektir? 

Sevmek,

İnsan olmaktır,

Hiçbir şey beklemeden,

Sevmektir.

Sevgi bahçelerine,

Sevgi çiçeği ekmektir.

Ya sevdiğimiz? 

O artık canandır,

Bazen yürek yakandır

Başımızı döndüren,

Bizi sarhoş edendir.

Her gece mehtaba çıkarıp,

Sahilde martılara,yıldızlara

Şarkılar söyletendir.', 'Aşık olmak, Özgürlüğe kanat açmaktır. Özgür olmak, Yalnızlık demektir. Peki yalnızlık?  Özgürlük mü demektir?  Sevmek, İnsan olmaktır, Hiçbi...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevmek-insan-olmaktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Bir Tane Daha Yok Bu Dünyada.', 'senden-bir-tane-daha-yok-bu-dunyada-ali-osman-yilmaz-krjbp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senden bir tane daha yok bu dünyada.

	Gülümsemeyi asla unutma.

	Gözlerinin içi gülsün gülerken,bakışların pırıl pırıl olsun ve her zaman nemli kalsın göz pınarların.Umut ışıkları yok olmasın gözlerinden,yaşam sevinci fışkırsın sana bakan tüm gönüllere.

	Kendini sevebilecek bir insan haline getirmeyi ve ondan sonra da kendini sevip,kendine sarılmayı unutma.Hiç kimse kalmasa da,sen varsın senin yanında.

	Acılarının ve felaketlerinin ancak zamanın koynunda uyuyabileceğini unutma.Acının en şiddetli anında ilacın olacaktır sana zaman.Sabretmenin en büyük gücünü kazanacaksın zamanla.

	Unutma ki,başına gelenler günün birinde kişisel tarihinin ayrıntılarından biri olmaya mahkumdur.O zaman geriye baktığında,ekşi tatlı canlanır anıların,tarihin sayfalarında.

                Yaşamda, yaşaman gereken ne varsa yaşa,kimsenin yaşamını sınırlamasına,kendine bile nasıl yaşayacağını belirlemesine  izin verme.

                Doğmak için kime dilekçe yazarsın,doğacağın ülkeyi, ananı, babanı, dinini,cinsiyetini ve nasıl bir ortamda yaşayacağını seçebilirmisin? böyle bir özgürlüğün varmı? 

                Yaşamını sınırlayan tüm engelleri kaldır,yaşamın sana sunduğu tüm nimetlerden  yararlan,doyasıya tenini,duygularını yaşa.Kimse engel olmasın sana,hatta sen bile.

                Sana dayatılan engelleri kaldır,yasa diye sana dayatılan kuralları yık,başkaldır doğaya engel koyanlara,kendini yaşa,buna sen bile engel koyma kendine.

	Her çiçek sevgilin olsun,her sevgilin ise çiçek.Açık tut gönlünü tüm güzelliklere. Yasalar,günahlar,yasaklar sen olduğun için vardır.Ve sen bir tane olduğun için şu koca dünyada,

                Gir korkmadan günaha,çekinmeden çiğne, tüm yasaklarla dolu yasaları.

	Ay''dedenin ve yıldızların sihrini gönderdiği gecelerde uyuyarak çalma hayatından saatlerini.Gecenin içinde yolculuğa çıkmayı unutma.

               Gecelerin koynunda yapacağın yolculuklarında,varabilirsin ancak özgürlüğe.İçinde hiç ölmeyecek bir  gençlik virüsü yarat ve kaç yaşında olursan ol,her zaman genç kalmayı unutma.Ve bu genç kalmanın virüsünü herkese bulaştırmaktan çekinme.

	Unutma ve asla taviz verme,seni sen yapan özelliklerinden.

                Onurlu bir yaşam sürebilmen için şartlar ne olursa olsun direnmeyi sakın unutma.

                İçindeki seni katletmeye kalkma sakın.Kendine vuracağın her darbenin seni senden biraz daha uzaklaştırıp yabancılaştıracağını unutma.

                Korkma mahallenin delisi olmaktan.Ancak mahallenin delilerinin yapacaklarını hoş görürler.

                Doğrucu Davutlar ne kadar çoğalırsa mahallende,hayat mutlaka daha iyiye gidecektir unutma.

                Hatanın affedilmeyecek olanından kaç,ama hata yapmayayım diye de yakıp geçme yıllarını.Unutma ki,hiç hata yapmayan insan, yapabileceklerinin en iyisini yapmamış demektir.

               Hayatta kendine şunu söyle daima.Pişman olacağın bir şeyi yapma,ya da pişman olma.

                İnsanların en kötüsü,kendine koyduğu yasaklarla yaşamaya kendini mahkum edenlerdir.

                En kötüsü insanın kendisine dayatılan,kendi istemesede kendine koyduğu, yasa ve kurallardan korkmasıdır.

                Korkma insanca korkularından,ve korkunun kendisinden çok,onun beklentisinin daha korkutucu olduğunu unutma.

                Bir anlamı olsun kendinle yaptığın kavgaların.Ve hep ileriye taşısın seni kavgada attığın her adım.

               Açık bırak pencereni ve sabah güneşinin rüzgarı, önüne katarak perdelerle yapacağı raksa dönük olsun bakışların.

               Küçücük mutlulukların görkemine inandır kendini ve her daim gülümse.

               Umutların bitmesin asla.Umutların bittiği yerin,hayatında bittiği yer olacağını asla unutma.

               Yaşamda en büyük engelleri,yalnızca sen koyabilirsin kendine,en kötü yasaları sen yazabilirsin,başkalarını bu nedenle sakın suçlama.

               Özgür olmak istiyorsan,önce kendine karşı özgür ol,ve bu özgürlüğünü kendine bile esir etme.

               Ve bu şaire kulak ver''''Senden bir tane daha yok bu dünyada''''Sen ve ben böyle olmayı becerirsek,ne kadar yaşanılır bir cennet olur dünya? 

               Ve ne olursa olsun gülmeyi başar ve gülümsemeyi sakın unutma,unutturma.

Ali Osman YILMAZ', 'Senden bir tane daha yok bu dünyada. 	Gülümsemeyi asla unutma. 	Gözlerinin içi gülsün gülerken,bakışların pırıl pırıl olsun ve her zaman nem...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/senden-bir-tane-daha-yok-bu-dunyada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigara (44)', 'sigara-44-i-brahim-arslan-vzy3x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ömür boyu esir ettin beni,oldum kölen

Bir cinayet var işlenen,sen katili,ben ölen

Ömrümü içmişim, seninle be sigara...

2004', 'Bir ömür boyu esir ettin beni,oldum kölen Bir cinayet var işlenen,sen katili,ben ölen Ömrümü içmişim, seninle be sigara... 2004...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sigara-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pelin''in Şiiri II', 'pelin-in-siiri-ii-faik-genc-ticyt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir insan tanıdım ki, her parçasıyla benim olabiliyormuş,

Bazen kız arkadaşım gibi olurmuş bazen erkek

Bazen sevgilim gibi olurmuş, bazen annem

Bazen iş arkadaşım, bazen sırdaşım,

Ve aşkım.

O tüm kişiliklerini  bir arada vermek istemiş,

Ben hepsini ayrı zamanlarda almak.

Bir dönem ben onun arkadaşı olmuşum, 

Bir dönem o benim dert ortağım,

Bir dönem ben onun sevgilisi olmuşum,

Bir dönem o benim annem.

Küçük küçük balonlar gibi şişirip

Büyütüp onları oynamışım hepsiyle zevkle,

O arada patlatmışım hepsini teker teker

Balonsuz kalana dek…

Şimdi o yine birisinin can arkadaşı,

Başka birisinin hayat ortağı,

Bir başkasının sevgilisi,

Bilmediğim birinin aşkı,

Bir çoğunun sırdaşı, annesi, yoldaşı

Benim hiçbirşeyim.

Aralık 2000', 'Bir insan tanıdım ki, her parçasıyla benim olabiliyormuş, Bazen kız arkadaşım gibi olurmuş bazen erkek Bazen sevgilim gibi olurmuş, bazen an...', ARRAY['Türk Edebiyatı','Şiir','Faik Genç']::text[], 8.5, '{"poet":"Faik Genç","poet_slug":"faik-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/pelin-in-siiri-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fecrisadık', 'fecrisadik-can-i-rfan-quqz8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığını 

Kendi içinde yok eden fecrisadık! 

Pürüzsüz ve doğal güzelliğinle

Fasıla,fasıla ıslaklığını gösterirken

Çölün suya hasreti gibi,

Dürüstlüğünle,doğallığınla,içtenliğinle ağlarım.

Dakika,dakika geçmek bilmeyen,

Namütenahi karanlığın sessizliği! 

Özlediğim nefsaniyetten uzak

Yeni bir güne başlamanın mutluluğuna

Dostluğunla,sevginle,özlediğim insanlığınla,

Yaşamak için beklerim.', 'Gecenin karanlığını  Kendi içinde yok eden fecrisadık!  Pürüzsüz ve doğal güzelliğinle Fasıla,fasıla ıslaklığını gösterirken Çölün suya hasr...', ARRAY['Türk Edebiyatı','Şiir','Can İrfan']::text[], 8.5, '{"poet":"Can İrfan","poet_slug":"can-i-rfan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fecrisadik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düştüm', 'dustum-ali-riza-unal-33b4s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Müptelâyım Aşkına, fermanı nara düştüm

Mihnet oldu yaranımız, hal zara düştüm

İftirayı failsin, tebdil ile ayan olayım hicabına

Huri, gılman bir oldu, ben zebana düştüm

Cihanı sarmış, aşikar olmuş rameti alan 

O ne bedbaht-ı bi çare, aşinayı gafleti ağman 

Hevay-ı hayale zebun olmuş, mihneti nalân

Dönmüşüm avareyi şaşkına, berdara düştüm', 'Müptelâyım Aşkına, fermanı nara düştüm Mihnet oldu yaranımız, hal zara düştüm İftirayı failsin, tebdil ile ayan olayım hicabına Huri, gılman...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dustum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırkikindi', 'kirkikindi-i-lke-soysal-jm3bc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gökyüzüne bak

Ve hatırla:

Bir yağmur damlasıyım ben..

Bir ikindi vakti çıkarsan dışarı

Belki ellerine,

   belki gözlerine,

      kimbilir belki de yüreğine düşerim..

Bereketliyimdir 

Bakarsın bir dostluk fışkırır 

Düştüğüm yerden..', 'Gökyüzüne bak Ve hatırla: Bir yağmur damlasıyım ben.. Bir ikindi vakti çıkarsan dışarı Belki ellerine,    belki gözlerine,       kimbilir be...', ARRAY['Türk Edebiyatı','Şiir','İlke Soysal']::text[], 8.5, '{"poet":"İlke Soysal","poet_slug":"i-lke-soysal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kirkikindi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O An', 'o-an-hikmet-guner-sdno9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Doğacak elbet gökyüzünde parlak bir güneş

Aydınlatacak karanlık dünyanın çehresini işte o an

Olmayacak gücümüzün eşi yedi cihanda; birlik olduğu o an

Yerle göğün birleştiği çizgiden; Güneşin doğduğu o an

Hiç durmayacak kalplerin, birlikte koştuğu an

Hangi güç dudurabilir, beraberce kan verildiği o an

Sonuna dek,... çekilsede damarlarımızdaki  kan

Yerle göğün birleştiği çizgiden; Güneşin doğduğu o an

Hakla, Adaletle, Vicdanla insalara bakan

Çağlayanlar sesi gibi gümdür gümbür durmadan akan

Aslanlar gibi güçlü, dimdik hep sevgiyle bakan

Yerle göğün birleştiği çizgiden; Güneşin doğduğu o an

Üzerimizedir herkezin gözü, güneşimiz doğduğu o an

Kıskanacaklar bizi, çizgimiz hep yükseldiği o an

Örnek olacağız etrafa, tüm kalplerin birleştiği o an

Hep parlayacak gökyüzünde,  Ay ve Yıldızımız

Kanımız birleşip de kankardeş olduğumuz o an', 'Doğacak elbet gökyüzünde parlak bir güneş Aydınlatacak karanlık dünyanın çehresini işte o an Olmayacak gücümüzün eşi yedi cihanda; birlik ol...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/o-an-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Olmayı', 'asik-olmayi-hikmet-guner-jim16', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gördüyse gözlerin ilk beni, benimle olmayı

Tattıysan ilk defa bende aşkı, sevdalı olmayı

Öğrendiysen sevmeyi, benimle severek yaşamayı

Hasret bağlar, hemde aşkı sağlar, benim gibi aşık olmayı

Hayattır, yaşamdır kah mutlu, kah mutsuz olmayı

Gözler sessiz ağlar, öğrendiysen sessiz olmayı

Öğrendiysen sende kah benli, kah bensiz olmayı

Hasret bağlar, hemde aşkı sağlar, benim gibi aşık olmayı

Sabır yüceltir aşkı sevgiyi, öğrendiysen sabırlı olmayı

Susadıysan içeceksin kana kana, bekleyeceksin yağmur olmayı

Yağan yağmurdan benimle beraber, sırıl sıklam olmayı

Hasret bağlar, hemde aşkı sağlar, benim gibi aşık olmayı

Bende arzuluyorum sıcaklığınla hep iç içe olmayı

Oturup ta karşında öyle sessiz olmayı

Kolların boynumda saatlerce hep seninle olmayı

Olacaksın sende mutlu, öğrendiysen...Benim gibi Aşık olmayı', 'Gördüyse gözlerin ilk beni, benimle olmayı Tattıysan ilk defa bende aşkı, sevdalı olmayı Öğrendiysen sevmeyi, benimle severek yaşamayı Hasre...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/asik-olmayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anıt', 'anit-zubeyde-yilmaz-kkqz4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen çok yabancı el gibi

Bazen sıcacık,yüreğim gibi yakın

Nedir sendeki bu egemen gurur

Sana açtım en saklı düşlerimi

Ne olur bir kez dön arkana bakın

Karşında sana kul,sevgiden bir anıt durur...

Gittiğin her köşe bucak

Gölgesinde benden bir anı bulacak

Düştüğün uçurumlardan sana açık hep bir kucak

Karşında sevgiden bir kanıt durur...

Kaybolmuş yıllara yangın,küllerini savurduğun yerde

Dönüp ardına kederli,anıları içtiğin yerde

Artık bitti,üşüyorum gelmeyecek dediğin yerde

Çoğalan sevdanla,seni seven sevgiden bir anıt durur...', 'Bazen çok yabancı el gibi Bazen sıcacık,yüreğim gibi yakın Nedir sendeki bu egemen gurur Sana açtım en saklı düşlerimi Ne olur bir kez dön a...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Yılmaz']::text[], 8.5, '{"poet":"Zübeyde Yılmaz","poet_slug":"zubeyde-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/anit-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlız Seni', 'yanliz-seni-hikmet-guner-z173w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Oldum uzaklarda aşkına, bir şair, bir deli

Aklıma ne gelirse yazdım, seni sevdim seni

Düşündükçe hep seni, kalem elimden hiç düşmedi

Yazdıkça yazdım hem aşkı, hem hasreti, hemde seni

Tutulmuşum bir kere fırtına gibi dönemem geri

Büyüledin yeşil gözlerinle senelerce beni

Görmedi  bir başka güzel, ben hep seni ve yanlız seni

Yazdıkça yazdım hem aşkı, hem hasreti, hemde seni

Heceler uçuştu bir bir kafamda

Kolay yakaladım her elimi uzattığımda

Zor değildi onları peşpeşe sıralamak

Yazdıkça yazdım hem aşkı, hem hasreti, hemde seni', 'Oldum uzaklarda aşkına, bir şair, bir deli Aklıma ne gelirse yazdım, seni sevdim seni Düşündükçe hep seni, kalem elimden hiç düşmedi Yazdıkç...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yanliz-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neler Olacak', 'neler-olacak-hikmet-guner-n611a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalplerin birleşip, sevginin olduğunda neler olacak

Soğuklar sıcak, sıcaklıkla aşk, heyecan olacak

Geceler uzun, bitmez tükenmez arzular olacak

Gün doğacak, gün batacak ve sonunda mutluluk olacak

Yıldızlar gökyüzünde parladığında neler olacak

Ay denize düşmüş, deniz sakin, sanki gündüz olacak

Hep el ele sahilde uzun uzun yollar olacak

Gün doğacak, gün batacak ve sonunda mutluluk olacak

Dokundukça tenler birbirine göreceksin neler olacak

Ayrılık zordur, hasreti boldur, doldur şarabı bardağı doldur

İçtikçe içecek, kafalar dolu, aşkımız şarhoş olacak

Gün doğacak, gün batacak ve sonunda mutluluk olacak

Bitecek bu hasret, sana kavuşmak için kollarım kanat olacak

Bir sabah uyandığında, bedenim koynunda seninle olacak

Gün doğacak, gün batacak ve sonunda mutluluk olacak

Anlayacaksın o zaman yaşadıkların, hayal değil gerçek olacak', 'Kalplerin birleşip, sevginin olduğunda neler olacak Soğuklar sıcak, sıcaklıkla aşk, heyecan olacak Geceler uzun, bitmez tükenmez arzular ola...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neler-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin gibisi', 'senin-gibisi-hikmet-guner-w0evg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geçti ömrüm yarısı, hep bir yerlerde

Ne insanlar gördü gözlerim, yaşadığım bu yerlerde

Benzemeselerde her biri birine, Bedeldin sen her birine

Aramadım ki, hiç sormadım ki, varmı senin gibisi

Olsada hep ayrı kişiler, sen başkaydın gözüme

Yapmacıktı, sahteydi, inanmadım kanmadım hiç kimsenin bir sözüne

Aldanmadı hislerim, emimndim hep kendime, çünki yoktu senin gibisi

Aramadım ki, hiç sormadım ki, varmı senin gibisi

Düşünmedim bir kötülük, kırmadım hiç insanları

Niyetleri değişik olsada, ben farklı gördüm o insanları

Daima iyilikten yana, sevdim hep tüm insanları

Aramadım ki, hiç sormadım ki, varmı senin gibisi

Olsamöda geceleri hep yanlız, bekledim sen gelmeni

Gölerim hep açık, kapanmadı seni görmeden

Ruhum, bedenim aitti sana, uyumadım sen sevmeden

Sen hep vardın, varolacak,olmayacak asla senin gibisi', 'Geçti ömrüm yarısı, hep bir yerlerde Ne insanlar gördü gözlerim, yaşadığım bu yerlerde Benzemeselerde her biri birine, Bedeldin sen her biri...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senin-gibisi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum', 'bilmiyorum-hakan-kilic-9v0yy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen kendimi tanımaz oluyorum

Yüreğimde fırtınalar kopuyor bilmiyorum

Bir volkan gibi püskürtmek içimi 

İçimde ki alevleri,

Etrafıma zarar vermek umurumda olmazcasına

Doluyorum

Gülmeyi unuttuğum o günleri

Duygu tsunamilerinin tahrip ettiği gönül kıyılarımda

Sahilde kendi kendime konuşmalarım

Üzerimde  insanların

Bana bir deliymişim gibi bakışları

Unutmuyorum

Kafayı dağıtmak uğruna 

Alkol ile dostluğum

Karanlık dan aydınlığa 

Beyoğlu gecelerinde

Beni bana düşüren

Bir kaşarozun sakızı olmuş dilinde

Sevda dolu yüreğim 

Saklı acizliğim Aşk a aç düşüncelerimde

Unutamıyorum

Kapatsam gözlerimi ruhum görüyor

Beynimde ki çatışmalar,

Damarlarımda kan sataşmaları

Ruh ile bedenin atışmaları

Hayatımda ki anlamsızlıklar 

Nedenini

Bilmiyorum

Her gün farkında olmadan öldürdüğüm bu beni

Nedir ruhumun bilmem küsme nedeni

Soru işaretlerinde epilepsi nöbetleri

Beyin salyalarım,

Ben ve benin yorgun bedeni

Bir sihir eşliğinde

Geldiğim sıyırmanın eşiğinde

Bir asa hülyası geleceğinden evvelde

Daha beşiğinde

Dengesizmiyim

Şizofren düşlerim

Halüsinasyonmu bildiğim bilmediklerim

Maneviyatı düşündükçe,çöküş sürecime 

Hız kazandıran gaz pedalım

Kurudumu meyve veren o tohum 

Küstürüldümü yaşama tutunduğum dalım

Virajı alamamak mı almak mı

Gördüklerimi unutmaya çalışıp 

Herşeye yeni baştan alışıp

Bir ama gibi

Korkularımla rüyaya dalmak mı 

Hangisi gerçek,hangisi yanlış,hangisi doğru

Bilmiyorum,

İsteklerim 

İçimde ki çocuk 

Dünya bir Pazar

İçeriği oyuncaklar

Sulugözlüyüm

Arızalı birimiyim

Bir okyanusu ikiye yarıp sevgi yürekli insanları

Peşim sıra götürmek istesem geçebilirmiyim,

Ya da bir örümcekden ağ örmesini

Bir sihirle kötülere karşı

İyilerin tarafını örtmesini

İsteyebilirmiyim

İsteklerim,

         Mucizeler 

Bozulmuş alemde sağlığı arayan ruhum

Bir paronaya vakası

        Kağıda dökülür dizeler

Ben ve ben,biz bizeler

             İstesemde silemiyorum

İstemiyorum,silmiyorum

Ben benim fakat,ben, beni halen bilmiyorum.', 'Bazen kendimi tanımaz oluyorum Yüreğimde fırtınalar kopuyor bilmiyorum Bir volkan gibi püskürtmek içimi  İçimde ki alevleri, Etrafıma zarar ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Kılıç']::text[], 8.5, '{"poet":"Hakan Kılıç","poet_slug":"hakan-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/bilmiyorum-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin bir yarısı', 'gecenin-bir-yarisi-hikmet-guner-ft62x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni hiç yanlız bırakmayan, en iyi dostlarımla gecenin bir yarısı

Bir kağıt, bir kalem, resminle bir de sigaram

Huzurlanırım onlarla hep birlikte, her gecenin  yarısı

Ben hala dostlarımla birlikte olsada yine gecenin bir yarısı

Yine saatler geçti, oldu gecenin bir yarısı

Bense dostlarımla masada, neredeyse bitti kalemin yarısı

Yazdıkça yazdım, kalemimle kağıtlara hep aşkımı kazıdım

Ben hala dostlarımla birlikte olsada yine gecenin bir yarısı

Bozuyordu hep sessizliği, kalemin kağıt üzerindeki sesi

Aslında kağıtta hoşlanıyor dinliyordu kalemden gelen bu sesi

Mırıldanıyordu bir şarkı, bir dans sanki bir müzik sesi

Ben hala dostlarımla birlikte olsada yine gecenin bir yarısı

Düşsede göz kapaklarım önüme, kalemim oturmuştu elime

Bitmez tükenmez bir istekle, durmadan yazdı bir çok kelime

Fısıldadı kulağına, kovaladı mısralar,mısraları doladı aşkı diline

Bir kağıt, bir kalem, birde resmin, yanan sigaramla gecenin bir yarısı', 'Beni hiç yanlız bırakmayan, en iyi dostlarımla gecenin bir yarısı Bir kağıt, bir kalem, resminle bir de sigaram Huzurlanırım onlarla hep bir...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecenin-bir-yarisi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasağa Rağmen', 'yasaga-ragmen-ali-gencoglu-fn5y9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Suçluyum iki kişi mutlu oldu

Suçtur içim bütünüyle ateş doldu

Annemden daha yakın bana suç mu? 

Yüreksiz olup cennetlik olunur mu? 

Isınmış boynuna sarıldım

Buna diyorlar yanlış diye

Ne bileyim oldu bir kez hata

Hata yıllarca olursa uygunmuş ama

Eğer böyleyse düzeni alemin

-Ki böyle düşündüğünü zanletmem

Bu alemi düzenin-

Yankısını gözlerin duysun seslerimin

Seni daha önce görseydim

Hep düşmek istemezdim bir uçuruma

Beni günahının götürdüğü yere

Götüren olmadı sevabına', 'Suçluyum iki kişi mutlu oldu Suçtur içim bütünüyle ateş doldu Annemden daha yakın bana suç mu?  Yüreksiz olup cennetlik olunur mu?  Isınmış ...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençoğlu']::text[], 8.5, '{"poet":"Ali Gençoğlu","poet_slug":"ali-gencoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasaga-ragmen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne insanlar gördüm', 'ne-insanlar-gordum-hikmet-guner-c4hmo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne insanlar gördüm  hep seven

Ne insanlar gördüm sevdiğini sanan

Ne insanlar gördüm, hep farklı davranan

Ne insanlar gördüm, sevdiğini söyleyip de kendini kandıran

Ne insanlar gördüm çıkarları için yaklaşan

Yüzüne gülüp de arkandan farklaşan

Gerçek yüzüyle hep saklaşan

Ne insanlar gördüm, yanlız menfaatleri ile paylaşan

Ne insanlar gördüm, Kararsızlıklarla hep boğuşan

Sevginin sıcaklığını anlamayıp da kendini soğutan

Sevmekle sevmemek arasında sürekli boğuşan

Ne insanlar gördüm, sevdiğini söyleyip de kendini aldatan

Azim ile, başarı ile sessizce uğraşan

Tüm engelleri aşıp, dostluk ve sevgi ile bağlaşan

Birlikte mücadele verip omuz omuza savaşan

Ne insanlar gördüm, sevdiğini söyleyip de kalpten paylaşan', 'Ne insanlar gördüm  hep seven Ne insanlar gördüm sevdiğini sanan Ne insanlar gördüm, hep farklı davranan Ne insanlar gördüm, sevdiğini söyle...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-insanlar-gordum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Venedikte bir ağaç', 'venedikte-bir-agac-hikmet-guner-c293n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İstedim Venedikte bir ağacım olsun

Dedim ağacım kayısı olsun

Üzerinde güzel renkler olsun

Dostlar hatırlasın, hatıram olsun

Ağacın üzeri meyvelerle dolsun

Meyvelerden yiyenler mutlu olsun

Yedikçe ağızları tatlı olsun

Dostlar hatırlasın, hatıram olsun

Herkes ağaçlara sevgi dolsun

Bir sevgi, bir ağaç, bir can olsun

Her yiyenden bir dostun olsun

Dostlar hatırlasın, hatıram olsun

Bir gül ektim, birde kayısı

Ağaçla sevgi canın yarısı

Ek bir ağaç, seninde dostun olsun

Dostlar bir gün unutsada, Ağaç gibi bir dostun olsun', 'İstedim Venedikte bir ağacım olsun Dedim ağacım kayısı olsun Üzerinde güzel renkler olsun Dostlar hatırlasın, hatıram olsun Ağacın üzeri mey...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/venedikte-bir-agac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ölümden büyüktür...!', 'ask-olumden-buyuktur-omer-faruk-girgin-r3ov5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'aşk ölümden büyüktür

çünkü 

aşk giderse 

geriye sadece “ölüm” kalır...! 

ve aşkı hiç duymadan, bilmeden yaşayanlar

sakın unutmayın; 

artık

tekrar tekrar aşksız

hiçbiriniz doğmayacaksınız…!', 'aşk ölümden büyüktür çünkü  aşk giderse  geriye sadece “ölüm” kalır...!  ve aşkı hiç duymadan, bilmeden yaşayanlar sakın unutmayın;  artık t...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Girgin']::text[], 8.5, '{"poet":"Ömer Faruk Girgin","poet_slug":"omer-faruk-girgin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ask-olumden-buyuktur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüm', 'gordum-hikmet-guner-hyivm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karanlık gecelerde bile hep seni gördüm

Hayalinle her gece buluşup aşkını ve seni gördüm

Okşadım sevdim seni yeşil gözlerini gördüm

Arzularım hep arzuladı seni arzumuza ağa ördüm

Arzular bu canda hep arzular seni

Olmasada hayalin sensizlik deli eder beni

Gözlerim görmedi başkasını gördü hep yanlız seni

Arzularım hep arzuladı seni arzumuza ağa ördüm

Seni düşünmeden sensiz bir gün olurmu

Soğuk yatağım buz gibi sensiz sıcak olurmu

Gecelerde gündüzlerde bile hep seni gördüm

Arzularım hep arzuladı seni arzumuza ağa ördüm

Dün gece rüyamda yine seni gördüm

Bekliyordum istasyonda trenin geldiğini gördüm

Uzun bir tren içi kalabalık, bense bir tek seni gördüm

Arzularım olmuştu gerçek, seni kollarımda gördüm', 'Karanlık gecelerde bile hep seni gördüm Hayalinle her gece buluşup aşkını ve seni gördüm Okşadım sevdim seni yeşil gözlerini gördüm Arzuları...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gordum-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-hikmet-guner-6xzt4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle çok özlemişimki yağmuru '' O.. geceyi, yağmurda

Yağsada üstümüze, olsakda gene sırıl sıklam yağmurda

Şimşekler gündüz aydınlığı gibi gecenin karanlığında

İçimize dek işlese '' O..,geceki gibi olsak yağmur altında

Unutmam '' O..,  yağmurlu geceyi gelir aklıma her yağmurda

Hani yağarken ikimiz el ele  ''O.., yağmur altında

Öyle saatlerce sarmaş dolaş '' O.., Yağmur altında

Biz iki deli sanki hiç ıslanmamış olmamıştıkki farkında

Islansak gene birlikte, sabaha dek yağmur altında

Görmese gözlerimiz hiçbirşey, yağan yağmur altında

Gene söylesek şarkılar ve dans yağan yağmur altında

Gene sarmaş dolaş saatlerce yağan yağmur altında

Bu aşkla oluruz gene sırılsıklam yağmur altında

Tıpkı ''O.., geceki gibi yağan yağmur altında

Islatsada aşk yağmuru, biz gene olmayacağız hiç farkında

Üzerimize hep yağacak aşk yağmuru, olsak da toprağın altında', 'Öyle çok özlemişimki yağmuru '' O.. geceyi, yağmurda Yağsada üstümüze, olsakda gene sırıl sıklam yağmurda Şimşekler gündüz aydınlığı gibi gec...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yagmur-148-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Aç Kalbini', 'hadi-ac-kalbini-ozgen-topcu-at8zz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fazla naz yapma bana

Yoracaksın bu aşkı

Yazık edeceksin ah

Sevmektir aşkın farkı

Sonra dövüneceksin

İçten içe yanıpta

Nereye gideceksin 

Bu aşkı bırakıpta 

Hadi aç aç biraz daha

Hadi aç kalbine gireyim

O güzel yerini ilk kez

Hadi açta ben göreyim

Hadi aç aç kalbini

İçten kilit vurayım

Bana ver her şeyini 

Yuvamızı kurayım

Çöldeyim suyum sende

Beni çıldırtıyorsun

Seni senden çok sevdim

Yabana atıyorsun', 'Fazla naz yapma bana Yoracaksın bu aşkı Yazık edeceksin ah Sevmektir aşkın farkı Sonra dövüneceksin İçten içe yanıpta Nereye gideceksin  Bu ...', ARRAY['Türk Edebiyatı','Şiir','Özgen Topçu']::text[], 8.5, '{"poet":"Özgen Topçu","poet_slug":"ozgen-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hadi-ac-kalbini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolaymı', 'kolaymi-hikmet-guner-ld02n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağlama diyorsun bir tanem

Sensiz olup''da yanlızlık kolaymı

İçimde gizlenen tatlı hatıralarla

Her şeyi bir anda unutmak kolaymı

Şimdi kim silecek göz yaşlarımı

Kaderin yazdığı bu alın yazımı

Kim çekecek bu kahrı benim yerime

Tek başına kahır çekmek kolaymı', 'Ağlama diyorsun bir tanem Sensiz olup''da yanlızlık kolaymı İçimde gizlenen tatlı hatıralarla Her şeyi bir anda unutmak kolaymı Şimdi kim sil...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kolaymi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur Vur', 'vur-vur-ozgen-topcu-vhooq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O neşeli halin bitmiş

Güzelliğin uçmuş gitmiş

Şimdi sende sıradansın

O gururun sana yetmiş

Ne yaparsan yap boşuna

Gitmeyecek hiç hoşuna

Anlamsız bu geri dönmen

Çare değil göz yaşına

Keşke yine diyeceksin

Çok şey bitti göreceksin

Pişmanlıktan kuduracak

Yeniden çok seveceksin

Vur vur dizine vur

Vur vur kafana vur

Faydasız bu haykırış

Kafanı duvara vur

Vur vur sırtımdan vur

Vur vur kalbimden vur

Sen sevmekten ne anlarsın

Konu aşksa sen orda dur', 'O neşeli halin bitmiş Güzelliğin uçmuş gitmiş Şimdi sende sıradansın O gururun sana yetmiş Ne yaparsan yap boşuna Gitmeyecek hiç hoşuna Anla...', ARRAY['Türk Edebiyatı','Şiir','Özgen Topçu']::text[], 8.5, '{"poet":"Özgen Topçu","poet_slug":"ozgen-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vur-vur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmayacaksın', 'unutmayacaksin-hikmet-guner-hl1q6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşadığımız bu güzel hatıraları

Ömrünce sende unutmayacaksın

Aittir güzelliğin yanlız bana

Mahşere dek benimle birlikte,  yaşlanacaksın

Topladım Göyüzündeki yıldızları sana

Onlardan hep taç yaptım sana

İkimizde ayrı, hasretse yetti artık bana

Az kaldı yakında, sende kavuşacaksın bana

Bir sabah erken uyandığında

Göreceksin ben kollarında, yanında

Yüzüme bakmaya doymayacaksın

Öyle bakıp da saatlerce uyandırmayacaksın

Kıyamam gözündeki bir damlaya

İstemem gözyaşların boşa dökülsün

Vardır elbet bu ayrılığında,hasretinde bir bedeli

Göreceksin sende mutlu olacak benimle yaşlanacaksın', 'Yaşadığımız bu güzel hatıraları Ömrünce sende unutmayacaksın Aittir güzelliğin yanlız bana Mahşere dek benimle birlikte,  yaşlanacaksın Topl...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/unutmayacaksin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Alamıyorum', 'geri-alamiyorum-ozgen-topcu-gm2e6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sorular saklı sende

Cevap bulamıyorum

Sana verdim kendimi

Geri alamıyorum

Boğuldum aşk selinde

Her şey senin elinde

Yüreğim kaldı sende

Geri alamıyorum

Aşk yoksa hayat korkunç

Hasretin üstümde tunç

Sevgimi verdim ödünç

Geri alamıyorum

Kestin nefeslerimi

Yıktın heveslerimi

Gasp ettin hislerimi

Geri alamıyorum

Sana çizdim yolumu

Sen mahfettin sonumu 

Eli versem kolumu

Geri alamıyorum', 'Sorular saklı sende Cevap bulamıyorum Sana verdim kendimi Geri alamıyorum Boğuldum aşk selinde Her şey senin elinde Yüreğim kaldı sende Geri...', ARRAY['Türk Edebiyatı','Şiir','Özgen Topçu']::text[], 8.5, '{"poet":"Özgen Topçu","poet_slug":"ozgen-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/geri-alamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden ayrı', 'senden-ayri-hikmet-guner-kxq9h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biz ne günler yaşadık, hem beraber, hem ayrı

Güçlüydük hissetmedik, yoktu aşkımızdan gayrı

Yarıştık hep zamanla, hep zamana karşı ayrı

Kahrolsun senli ama sensiz geçen zamana ayrı

Denizin dalgaları gibi, bir sağa bir sola ayrı

Vurdukça vurdu, acımazsızca dalgalar ayrı

Savurdu uzaklardan uzaklara denizlerden ayrı

Kenetlenmiş kalplerimiz, yoktu''ki sevgimizden gayrı

Biz ne günler gördük mutlu, mutsuz birlikte ayrı

Kıskananlar oldu zaman zaman o da ayrı

Aşkımızla biz olmadık''ki hiç mutsuz ayrı

Olmalıydı demek böyle ayrı, yoktur kaderden gayrı

Ne insanlar yaşıyor, birbirinden ayrı,ayrı

aslında biz olamazdık yanlız, böyle ayrı

Kahrolsun sensiz geçen zamana, canıma yetti gayrı

Gelirsem bir daha dünyaya, Şard olsun olmam senden ayrı.', 'Biz ne günler yaşadık, hem beraber, hem ayrı Güçlüydük hissetmedik, yoktu aşkımızdan gayrı Yarıştık hep zamanla, hep zamana karşı ayrı Kahro...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senden-ayri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mum ışığı', 'mum-isigi-hikmet-guner-u2lup', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığında bir kaç mum yaktım

Uzun uzun yanan mumlara baktım

Yandı alevler dalga dalga

Saatlerce öyle resmine baktım

Aldım kalemi elime

Bir kahve, bir de sigara yaktım

Başladım sana şiirler yazmaya

Kafamı dizelere taktım

Doluydu ilhamım aşkımla sana

Yazdıkça hep yazdım sana

Hasretin, sevgin ve aşkınla

İçimde sönmeyen ateşler yaktım', 'Gecenin karanlığında bir kaç mum yaktım Uzun uzun yanan mumlara baktım Yandı alevler dalga dalga Saatlerce öyle resmine baktım Aldım kalemi ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mum-isigi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmek bilmedi', 'gecmek-bilmedi-hikmet-guner-d703c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayalin gözümün önünde hiç gitmek bilmedi

Sensiz geçen uzun geceler, geceler boyu bitmek bilmedi

Loş ışıkla yanan mumlar eridi ama sönmek bilmedi

Kavuşmamıza gün kala, günler geçmek bilmedi

Şiirler yazdım sana, mısralar bitmek bilmedi

Aşkım içimde bir meşale, alevler sönmek bilmedi

Yırttım her gün bir yaprak, Takvimler bitmek bilmedi

Kavuşmamıza gün kala, günler geçmek bilmedi

Yaz bitti, kış geldi, kış da bitmek bilmedi

Üşüdüm soğuk gecelerde, soğuklar bitmek bilmedi

Ne saat geçti ne zaman, bir türlü vakit geçmek bilmedi

Kavuşmamıza gün kala, günler geçmek bilmedi', 'Hayalin gözümün önünde hiç gitmek bilmedi Sensiz geçen uzun geceler, geceler boyu bitmek bilmedi Loş ışıkla yanan mumlar eridi ama sönmek bi...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gecmek-bilmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-hekim-coskun-1wcu0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aynada seni gördüm

sıkılmadan

saçını sola tarıyordun...

dün gibi yıkılmıştın oysa

türkü gibi yaşadığını gördüm

doyasıya

hani pusuya düşürüldüğünde

merdo

dostlarınla sipan

düşmanlarınca yılandın...

seni aynada gördüğümde

kendimden utandım

seni tanıdığımda

yüzünde kavganın izleri

gözlerinde yorgunluk vardı

endişelerin saçlarının diken diken oluşundan belliydi

yarın ne olacak tı? 

yarınlara nasıl hesap verecektin

ne yaptın? 

ne yapmalıyım? 

sorularla sararmış yüzünde

hüzün de vardı

birtek benim bildigim sırlarını

yürüginde hissettim

bir an kimselere söylemediğim için

ya da söylemeye cesaret edemediğim için

bir başkasına değil kendine güvenin

ya da inançların

gözlerindeki ışıltıyı azaltmıştı

artık ne eskisi gibi görebiliyor

ne de hissedibiliyordun beni

oy sa ben ayna da seni gördüm

yüzünde gülümsemeler çok çirkin duruyordu

somurtacak bir şeyler yokmuş gibi...', 'aynada seni gördüm sıkılmadan saçını sola tarıyordun... dün gibi yıkılmıştın oysa türkü gibi yaşadığını gördüm doyasıya hani pusuya düşürüld...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ayna-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Reis*', 'reis-kubilay-enginol-scdi1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözleri çakmak çakmak,akşama çıkılacak

Ağlar hazır mı, hava kararacak

Yol verilecek birazdan, herkes telaşlı

İzliyor kenardan eski balıkçı,gözleri yaşlı.

Mapa dizerek başlamıştı,balıkçılık hayatına

Torlara geçmek girerdi hep rüyalarına

Dizerdi mapaları,istiflerdi kasaları

Temizlerdi tekneyi,satışa da çıkardı bazıları.

Ağ tamirini,kırlangıç çorbasını bile öğrendi

Ama hep ağbaşı geçmeye özendi.

Zaman geçti hediyesini verdi sabır,

Reis dedi:” Tora geçme zamanındır.”

Irgatı unuttu, teli görmedi heyecandan

Hüzünle ayrıldı kopan bacağından.

Gözyaşıyla beraber aktı gitti hayalleri,

Şimdi yapıyordu ancak kıyıda ağ tamiri.

Reis diyorlardı kopan bacağın hatırına

Tekne uzaklaşırken o oturdu yine ağların başına.', 'Gözleri çakmak çakmak,akşama çıkılacak Ağlar hazır mı, hava kararacak Yol verilecek birazdan, herkes telaşlı İzliyor kenardan eski balıkçı,g...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/reis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle', 'seninle-hikmet-guner-bypoh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmek yürekte

Görmek''se gözdedir

Hasret gönülde

Gönül''se Beynimdedir

Sönmez bu aşk ateşi

Ateş''se içimdedir

Yatağım her gece seninle

Ve hep yanlız seninledir', 'Sevmek yürekte Görmek''se gözdedir Hasret gönülde Gönül''se Beynimdedir Sönmez bu aşk ateşi Ateş''se içimdedir Yatağım her gece seninle Ve hep ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seninle-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Gökyüzü **', 'gokyuzu-kubilay-enginol-bk9t1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günde iki saat buluşmak ne de zor seninle

Yeşili hayal etmek maviliğinde

Yüzünü ısıtır güneş moral verircesine

Gideceksin birazdan,siyah mabedine.

Siyahın içinden maviliği çıkarabilir misin? 

Siyahla gönlünü avutabilir misin? 

Buluşma anını beklersin siyahlar içinde

Mavilik yaklaştıkça sevinç belirir göz bebeklerinde.

Bir mavi bir siyah tanıyamazsın artık renkleri

Korkarsın yitirmekten,yüreğinde taşırsın özgürlük çiçeklerini.', 'Günde iki saat buluşmak ne de zor seninle Yeşili hayal etmek maviliğinde Yüzünü ısıtır güneş moral verircesine Gideceksin birazdan,siyah mab...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gokyuzu-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudaklar', 'dudaklar-hikmet-guner-5e88q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzaklardayız uzaklarda

Değil ki ayrı dünyada

kapa gözlerini bak ben yanında

Hissedersin tenimi, dudaklarında

Ayrı olsak da birlikteyiz

Her an her yerde birlikteyiz

Aşkımız için birlikteyiz

Seninle ölüme dek birlikteyiz

Ölsek de birlikteyiz

Hasrettir bizi bize bağlayan

Ayrılıktır yüreğimizi dağlayan

Akar damla damla olur çağlayan

Gözlerimizdir boş yere ağlayan', 'Uzaklardayız uzaklarda Değil ki ayrı dünyada kapa gözlerini bak ben yanında Hissedersin tenimi, dudaklarında Ayrı olsak da birlikteyiz Her a...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dudaklar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Heybeliada **', 'heybeliada-kubilay-enginol-fgyjy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir büyük edasıyla sürdü bisikletini çocuk

Yukarıda Ethem Çay Bahçesine

Kaldırıma park etti arabasıymış gibi

Dedesi almıştı kırmızı Yale bisikletini

Çayını söyledi gelen garsona

Adam gibi hissediyordu kendini nedense burada

Karıştırdı çayını, içti büyükleri gibi

İhmal etmedi ufakta olsa bahşişi

Bindi bisikletine çevirdi pedalları

Önünde geleceği arkasında ufaklığı.

Bu şiir Dedem Kemal Enginol''a ithaf edilmiştir', 'Bir büyük edasıyla sürdü bisikletini çocuk Yukarıda Ethem Çay Bahçesine Kaldırıma park etti arabasıymış gibi Dedesi almıştı kırmızı Yale bis...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/heybeliada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-hikmet-guner-p66ks', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eller ne derse desin inanma gülüm

Boş laflara, dolduruşlara kanma gülüm

Bilesin''ki ben sensiz, sen bensiz olmaz gülüm

Yoktur dünyada senden başkası gülüm

Unutma verdiğimiz sözleri gülüm

Kalbim yanlız senindir, seninle gülüm

Yatağım her gece seninledir gülüm

Ölene kadar yanlız seninle, ölsem de yanlız seninle gülüm', 'Eller ne derse desin inanma gülüm Boş laflara, dolduruşlara kanma gülüm Bilesin''ki ben sensiz, sen bensiz olmaz gülüm Yoktur dünyada senden ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gulum-104-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinlemez', 'dinlemez-hikmet-guner-4pouu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İstek bu arzu bu 

Bahane dinlemez

Benimde canım ister 

Ama fırsat dinlemez

Sevgimizi yürekler bilirde

Kulaklar dinlemez

Sabret güzelim zamanı gelsin

Hikmet kimseyi dinlemez', 'İstek bu arzu bu  Bahane dinlemez Benimde canım ister  Ama fırsat dinlemez Sevgimizi yürekler bilirde Kulaklar dinlemez Sabret güzelim zaman...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dinlemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum', 'seviyorum-hikmet-guner-tjrld', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne senden vazgeçerim

Ne de kendimden

Ne çok seviyorum

ikinizi de birden

Mutlu olmak istedik 

İstemeyi bilmeden

Oysa mutluluk hep içimizdeydi

Biz bilmeden

Aşkımı yollara yazdım

Baş harfleri ağaçlara derin derin kazdım

Bir yollar ağaçlar anladı beni, bir de sen

Bilsen ne çok seviyorum ikinizi birden', 'Ne senden vazgeçerim Ne de kendimden Ne çok seviyorum ikinizi de birden Mutlu olmak istedik  İstemeyi bilmeden Oysa mutluluk hep içimizdeydi...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seviyorum-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyledim''mi', 'soyledim-mi-hikmet-guner-sjxk0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana seni sevdiğimi söyledimmi

Seni ne kadar özlediğimi söyledimmi

Sensizliğin canıma yettiğini söyledimmi

Sen olmayınca sensizliği anladığımı söyledimmi

Gündür çabuk gelir geçer dedik

Günler aylar oldu geçmedi

Ayrılık hasrettir, hasretse yara

Yaram delik deşik oldu geçmedi

Hani sabırlı dayanaklı olacaktık

Hani aşkımızla hiç susamamayacaktık

Susuz kalsakta çölün ortasında, ıslanan dudaklarla

Birbirimize doymaya vakit bulamayacaktık', 'Sana seni sevdiğimi söyledimmi Seni ne kadar özlediğimi söyledimmi Sensizliğin canıma yettiğini söyledimmi Sen olmayınca sensizliği anladığı...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/soyledim-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-hikmet-guner-uggnv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeşil gözlerini özledim

Mis gibi kokan tenini özledim

Sana sarılıp yatmayı özledim

Göğsümde nefes almanı özledim

Gülüşünü, kahkahalarını özledim

sıcaklığını tenimde hissetmeyi özledim

Hergün Takvime defalarca bakıp

Sana bir an önce kavuşmayı özledim', 'Yeşil gözlerini özledim Mis gibi kokan tenini özledim Sana sarılıp yatmayı özledim Göğsümde nefes almanı özledim Gülüşünü, kahkahalarını özl...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozledim-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler', 'gozler-hikmet-guner-nzu61', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerdir güzelliği sunan

Gözlerdir sessiz ifadeler sunan

Sözlerdir sessizliği bozan

Gözlerdir insanı yapar ozan

Gözlerdir buluştuğunda uçurum kenarında olan

Gözlerdir neşeyi paylaşıp cıvıl cıvıl olan

Gözlerdir mutsuzlukla dolup dolan

Gözlerdir seller sular akıp akıp dolan

Hani hiç konuşmayacaktık

Hani hiç sessizliği bozmayacaktık

Öyle bir baktı ki o gözler

İçimden patlarcasına geldi sözler', 'Gözlerdir güzelliği sunan Gözlerdir sessiz ifadeler sunan Sözlerdir sessizliği bozan Gözlerdir insanı yapar ozan Gözlerdir buluştuğunda uçur...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozler-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazmak Geldi İçimden', 'yazmak-geldi-i-cimden-hayrettin-orak-dcptw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşanmış bir öykü yazayım dedim,

Romantikmi, dramatikmi olsun seçemedim,

Her iki yönden karaladım durdum,

Bir türlü bu ikilemden çıkamadım.

Romantikten anlamam, çünkü yaşamadım,

Sevgilim olmadı sevip koklaşamadım,

Var olmayanla ne küs ne barışık kaldım,

Vaz geçtim yazmaktan hoşgörün, buna alışamadım.

Dram desek hep yaşadığımız,

Dünyanın kanunu''mu bu, düzen tutmuyor çarkımız,

Yaşıyoruz kendimizce ama boş ve anlamsız,

Olmaz olsun  böyle kardeşliğimiz, sevdamız.

Bir yanda çekiyor insanlar açlık sefalet,

Diğer yanda işleniyor, katliam cinayet,

Hak hukuk nedir tanımaz bu millet,

İstemeyin ne olur, yazamam ben böyle illet.

Yazmak isterdim bir takım güzellikleri,

Ama solmuş insanlığın barış gülleri,

Kesecek yokmu kan kokan silahlı elleri,

Fayda etmiyor insanların sessiz halleri.

Ya rabbim artık kaldıramıyoruz bu karmaşıklığı,

Ne zaman son bulacak insanların acı feryatları,

Göğü inletiyor çocukların haykırış ve çığlıkları,

Artık yaşamak istiyoruz güzellik ve kardeşliği.

Açılsın kapılar, kırılsın zincirler,

Bayram etsin ezik kalan gönüller,

Ne kin kalsın dünyada, ne düşmanlıklar,

İşte bu güzellikleri yazmak isterim, Güzel insanlar...! 

7.11.2004', 'Yaşanmış bir öykü yazayım dedim, Romantikmi, dramatikmi olsun seçemedim, Her iki yönden karaladım durdum, Bir türlü bu ikilemden çıkamadım. ...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yazmak-geldi-icimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gaflet', 'gaflet-hayrettin-orak-x8a52', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Daralıyor günden güne, dünya denen kafes,

Hayatın tadı kalmadı, alınmıyor rahat bir nefes,

Bizlerde ne vefa kalmış nede bağlılık,

Suçlusu aranacaksa bence herkes.

Çıkar uğruna yarışıyor insanlar,

Ne babalar tanınır olmuş ne analar,

Keşmekeşlik içinde harcanıyor zamanlar,

Hakikatler ne zaman görülecek ey insanlar.

Bu dünyanın birde diğer yanı var,

Kabirde bekliyor bizleri büyük azaplar,

Fayda etmez o zaman mal, mülk, paralar,

Sorulacak olan sadece günah ve sevaplar.

Gücümüzün yettiğine haksızlık ederiz,

İnsanlığa söz geldimi ahkam keseriz,

Paylaşmayı bilmez hep kendimize çekeriz,

Herşeyin alası benim olsun diye savaşırız.

Uyanalım artık biz bu gafletten,

Ne dünyadan zevk alıyoruz nede ahretten,

Silkinip kurtulalım bu aç gözlükten,

Neden hep beraber faydalanmıyoruz biz bu nimetten.

Yaratılmış geçiyoruz bir takım sınavlardan,

Arınmalıyız işlediğimiz haram ve günahlardan,

Ne ahretten vazgeçelim nede dünyadan,

Allah nazarında olalım iyi kullardan....! 

07.11.2004', 'Daralıyor günden güne, dünya denen kafes, Hayatın tadı kalmadı, alınmıyor rahat bir nefes, Bizlerde ne vefa kalmış nede bağlılık, Suçlusu ar...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gaflet-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçler', 'ucler-hikmet-guner-vp8r1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir Barış var aslan gibi

Yakışıklı dalyan gibi

Kara gözlü güzel mi güzel

Kendine hastır özel mi özel

Kıvır kıvır saçları var

Kapkara gözleri var

Neşe dolu capcanlı

Benim güzel Buket''im var

Sarı sarı saçları var

Ela ela gözleri var

Neşe dolu capcanlı

Benim güzel bir de Nuket''im var', 'Bir Barış var aslan gibi Yakışıklı dalyan gibi Kara gözlü güzel mi güzel Kendine hastır özel mi özel Kıvır kıvır saçları var Kapkara gözleri...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ucler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Başına', 'tek-basina-hikmet-guner-ttmnq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Resminle beraber tek başına

Baktıkça dalar dalar giderim 

Rüyalara hayale tek başına

Yine akşam oldu evde tek başına

Anlamlı bakışlar alır götürür beni

Hasretinle kıvranır, sensizlik sarar beni

Aşkına susadım, susuzluk darar beni

Yine akşam oldu evde tek başına

Yatağım buz gibi, soğuk sarar beni

Kulaklarım sesini, gözlerim hep arar seni

Sensizlik ve sessizlik darar beni

Yine akşam oldu evde tek başına', 'Resminle beraber tek başına Baktıkça dalar dalar giderim  Rüyalara hayale tek başına Yine akşam oldu evde tek başına Anlamlı bakışlar alır g...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tek-basina-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deliler gibi', 'deliler-gibi-hikmet-guner-oghaa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Savrulsun saçların denizdeki dalgalar gibi

Çarpsın yüzüme sahile vuran dalgalar gibi

Parlasın yüzümde saçların ay gibi, güneş gibi

Seni seviyorum bir tanem deliler gibi

Alışmışım varlığına, yokluğun oldu hüzün

Kış olmasada kavuşuruz elbet güzün

Seninde gülecek bir gün o güzel yüzün

Bende beklerim o anı bir tanem deliler gibi

Ayrılık zordur, biliyorum beklemek zordur

Hasreti boldur doldur şarabı bardağa doldur

Tokuşsun kadehler deliler gibi

Bende beklerim o anı bir tanem deliler gibi', 'Savrulsun saçların denizdeki dalgalar gibi Çarpsın yüzüme sahile vuran dalgalar gibi Parlasın yüzümde saçların ay gibi, güneş gibi Seni sevi...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/deliler-gibi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilim adamları', 'bilim-adamlari-i-smail-ersin-dalgic-5fahk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'S.S.K. hastasıyım.

Meşakatlide olsa,

Sayın Hakkı Polat  vasıtasıyla,

Rahatsızlığıma tanı koydu,

Doktor Gülsen Öğmen hanım.

Küçük ameliyat,

Biyopsi için araştırma,

Düşünmek bile istemediğim,

O büyük hastalık,

Kanser.

Karabasanlar düşünmeler,

Önce Dokuz Eylül,

Sonra Ege Üniversitesinde

Hocalarla görüşmeler.

K.B.B. Doç.Tayfun Kirazlı bey kuşkulu,

Tabii biz ondan kuşkulu.

Araştırma yapmamızı önerdi.

Gastroenteroloji Reflü bölümü başkanı,

Doç. Serhat Bor’a,

Notlarla gönderildim.

Randevular evet bende bir telaş,

Tayfun bey Serhat beyle konuşur,

Konuşmaları hatırlayan Serhat bey,

İlk cümlesi senin hastalığın karmaşık.

Psikolojik durumumu düşünmeden,

Allak bullak etti beni.

Kendimi toparladım,

Metin olmam gerek.

Bilim adamları! 

Bilimsel araştırma yapıyorlar ya,

Bilim insan içindir benim bildiğim,

	İnsanı önce karşında kazan,

	Kazan ki bilimsel araştırman,

	Sapasağlam ayakları üzerine bassın.

Psikolojik tedavinin sermayesi ne ki? 

Üç beş tane güzel sözler.

	Tabii hastanız çok,

	Yaptığınız işi küçük görmüyorum,

	Kanser hastalığını da küçük görmeyiniz.

				İsmail Ersin Dalgıç

					25 Mart, 2004', 'S.S.K. hastasıyım. Meşakatlide olsa, Sayın Hakkı Polat  vasıtasıyla, Rahatsızlığıma tanı koydu, Doktor Gülsen Öğmen hanım. Küçük ameliyat, B...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bilim-adamlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç yüz gün', 'uc-yuz-gun-i-smail-ersin-dalgic-s4t5p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Görücü usulüyle evlendim,

Büyüklerime saygımdan,

İyi de etmedik değil,

Üç tane çocuğumuz var.

	Birbirimizden kopacağız,

	İlla ki ölümden,

	Belki de başka sebepten,

İşte o zaman kopacak kıyamet! 

Çocuklarımız aramazsa.

	Birbirimizi kıskanıyoruz,

	Evet sevdiğimiz için.

Kendini bize adamış,

Yemez yedirir giymez giydirir,

Evimizin anası.

	Dünya rekoru olabilir,

	Senenin üçyüz atmış beş gününün,

	Üç yüz günü kavgalıyız.

Buna rağmen otuz üç yılımızı bitirdik.

Nasıl bir inatsa,

Kavgamızın sonunda,

Özür dileyen ben olmuşumdur.

	Be kadın, bu kadar münakaşada,

	Hiç mi hatan yok? 

Bir insana düşmanlık edeceksen,

Cahil kadın nasip olsun de.

Başka söze ne gerek var? 

	Bizim tartışmamız parasızlıktan değil,

	Malımız,devlet güvencemiz, 

Akrabamız, çevremiz de var.

Bunun tek sebebi cahillik

	Kendi dediğinden başkasını kabul etmeyen,

	Asla esneklik göstermeyen,

	Dediğim dedik diyen,

	Evet bu bizim anamız,avradımız,yarimiz.

			İsmail Ersin Dalgıç

				30 Şubat, 2004', 'Görücü usulüyle evlendim, Büyüklerime saygımdan, İyi de etmedik değil, Üç tane çocuğumuz var. 	Birbirimizden kopacağız, 	İlla ki ölümden, 	B...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/uc-yuz-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O bir çocuk', 'o-bir-cocuk-i-smail-ersin-dalgic-9gxeh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalın ayak başı kabak,

Kırk günlükken,

Toprakla tanışır,

Kesekler yatak,

Yapraklar yorgan.

Büyüklerimin büyüklerinden öğrendiği,

Kulağıma ilk fısıltı,

          ‘’Yalan söyleme çocuğum’’

Nasıl bir şartlanma? 

Zaman içinde öğrendiğime göre,

Söyleneceklerin sınırı yok.

Dürüst olmanın sınırı var.

Değer baktığın yerde değil,

Bakışında olsun.

         ‘’Olsun ya’’

         Hani bunun mayası? 

         Çocukmuş demeyin.

Elli beş yaşımdayım,

Kulağıma okunanla,

              yürüyorum.

‘’Hele ninemin’’

Komşunun meyvasını koparıp,

Helalık  alması var ya,

          İşte benim mayam,

          Çocuk muyum neyim? 

		İsmail Ersin Dalgıç

			8 Mart, 2004', 'Yalın ayak başı kabak, Kırk günlükken, Toprakla tanışır, Kesekler yatak, Yapraklar yorgan. Büyüklerimin büyüklerinden öğrendiği, Kulağıma il...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/o-bir-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama', 'aglama-hikmet-guner-zd58h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzel gözlüm niye ağlıyorsun''ki

Ağlamasan olmazmı

Kavuşmamıza az kaldı

Hep gülsen olmazmı

Ağlamak yakışmaz sana

Sensizlik sancı oldu bana

Arzular kamçı oldu bana

Bende kavuşmak isterim sana', 'Güzel gözlüm niye ağlıyorsun''ki Ağlamasan olmazmı Kavuşmamıza az kaldı Hep gülsen olmazmı Ağlamak yakışmaz sana Sensizlik sancı oldu bana Ar...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aglama-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçluyum', 'sucluyum-i-smail-ersin-dalgic-qo0qo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Suçum doğru olmak mı? 

Olduğum gibi mi gözükmek.

Suçum çocuk gibi inanmak mı? 

İnsanların kötü yanlarını görmemek mi? 

Suçum insanları olduğu gibi kabullenmem mi? 

İnanlara insan gözüyle bakmam mı? 

Suçum insanlardan kötülük gelmeyeceğine inanmam mı? 

İyiliği kötülüğü onlarla paylaşmam mı? 

Ben suçluyum, insanlarla yaşamayı ilke edindim,

Ben suçluyum, suçsuzların yanındayım.

Ooy ana baba! 

Bu insan kalabalığı içinde yalnızım,

Yalan söylemeyi öğretmediğiniz için,

Bu yaştan sonra alışabilirsem,

Gelin beni kurtarın.

Hala inadıma devam ediyorum,

Bu beladan kurtulamıyorum.

İnanmak mı yukarıdaki felsefeye? 

Ben yine suç işliyorum,

İlemeye de devam ediyorum.

Doğru söyleyeni dokuz köyden kovarlarmış,

Belki benim ütopyam diyeceksiniz,

İnsanlık bunu görecek,

Yalan söyleyene kainatta yer bulunmayacak.

				İsmail Ersin Dalgıç

					25 Şubat, 2004', 'Suçum doğru olmak mı?  Olduğum gibi mi gözükmek. Suçum çocuk gibi inanmak mı?  İnsanların kötü yanlarını görmemek mi?  Suçum insanları olduğ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sucluyum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına', 'firtina-hikmet-guner-v643j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgim kopardı fırtınalar

Sessizliği seçti hep çığlıklar

Oysa haykırmak istedi dudaklar

Haykırsada duymadı kulaklar', 'Sevgim kopardı fırtınalar Sessizliği seçti hep çığlıklar Oysa haykırmak istedi dudaklar Haykırsada duymadı kulaklar...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/firtina-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam olmak', 'adam-olmak-emre-uslu-f0oqc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bakıyordu pencereden,

Yada bakar gibi yapıyordu,

Bakarken geleceğini düşünüyordu,

Belki de hiçbir zaman yaşayamayacağı,

Aynı zamanda karanlık olan,

İnsanlığa hiçbir katkısı olmayan,

Sadece etrafta dolaşan bir çocuktu,

Hani şu “Sen adam olamazsın! ” denilenlerden,

Hikayedeki gibi çok çalışacaktı,

Herkese kanıtlayacaktı,

Babasını ayağına çağırıp,

“Gördün mü yaşlı budala? ” diyecekti,

Babası o sırada ağlayacaktı,

Yanıldığı için değil,

Dedikleri doğru çıktığı ve oğlu adam olamadığı için,

Sildi göz yaşlarını döndü Tanrı’sına,

Dua etti, ölmek için,

O ölüm ki, bir daha oğlunu görmesine şans tanımayacak,

O ölüm ki, haklı çıktığı konuyu bir daha hatırlayamayacak,

Ama istediği gerçekleşmedi,

Tanrı ona acıyordu,

Son bir şans verdi,

Oğluna gidip “Her çıkışın bir düşüşü vardır! ” dedi,

Çocuk babasını kovdurdu, döverek,

On yıl geçti adam hala ölmek istiyordu,

Haber aldı oğlu iflas etmişti,

Kapısı çalındı, adam üzüldü,

Oğlu gelip elini tuttu, eğilip öpmek için,

Adam olmuştu şimdi gerçekten,

Babası “Bu dünyaya iki adam fazla..” dedi,

Çocuk ağlamaya başladı,

Artık bir babası yoktu...', 'Bakıyordu pencereden, Yada bakar gibi yapıyordu, Bakarken geleceğini düşünüyordu, Belki de hiçbir zaman yaşayamayacağı, Aynı zamanda karanlı...', ARRAY['Türk Edebiyatı','Şiir','Emre Uslu']::text[], 8.5, '{"poet":"Emre Uslu","poet_slug":"emre-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/adam-olmak-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne-babama..', 'anne-babama-emre-uslu-7njmh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beklenmedik anlarda yanımda olan,

Ve beni hep şımartan,

Yalnızlık nedir tattırmayan,

Üzüntülerimi azaltan,

Sevinçlerimi arttıran,

Duygularımı paylaşan 

Beni her zaman anlayan,

Hep çok seven,

Bir an aklımdan çıkmayan,

Annem ve babam..

Sizi çok seviyorum! 

İyi ki siz varsınız,

Ve iyi ki de benim,

Annem-babamsınız..', 'Beklenmedik anlarda yanımda olan, Ve beni hep şımartan, Yalnızlık nedir tattırmayan, Üzüntülerimi azaltan, Sevinçlerimi arttıran, Duygularım...', ARRAY['Türk Edebiyatı','Şiir','Emre Uslu']::text[], 8.5, '{"poet":"Emre Uslu","poet_slug":"emre-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/anne-babama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Layık', 'layik-hikmet-guner-6n5o9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgim yetmez sana

Layıksın en güzeline

Ne yapsam azdır sana

Seviyorum deli gibi anlasana', 'Sevgim yetmez sana Layıksın en güzeline Ne yapsam azdır sana Seviyorum deli gibi anlasana...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/layik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen sevgiden ne bilirsin', 'sen-sevgiden-ne-bilirsin-i-smail-ersin-dalgic-csg9b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgiler var suya yazılır,

Buğarlaşır yok olur gider.

Sevgiler var kalbe yazılır,

Tüm evrene mal olur gider.

Sevgiler var havaya yazılır,

Ufak bir rüzgarla yok olur gider.

Sevgiler var benliğe yazılır,

Seninle var olur gider.

Sevgiler var yalanlarla yazılır,

Hiç olur gider.

Sevgiler var bedenine yazılır,

Canlılarla var olur gider.

Sevgiler var çıkarlar için yazılır,

Maliyeti desisedir.

Sevgiler var emek ile yazılır,

Tadından yiyemezsin.

Sevgiler var pazar pazar dolaşsan,

	    anlatmakla bitiremezsin.

Hey, canlı cansız size sesleniyorum,

Benim gibi bahtsız olursanız,

Yaşarken ölmüş sayılırsınız.

Eyvah! 

Ben ölmedim yaşıyorum,

Evet! 

Hayal ettiğimi arıyorum.

                    İsmail Ersin Dalgıç

                                 14 Şubat, 2004', 'Sevgiler var suya yazılır, Buğarlaşır yok olur gider. Sevgiler var kalbe yazılır, Tüm evrene mal olur gider. Sevgiler var havaya yazılır, Uf...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sen-sevgiden-ne-bilirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık ellerim ve ayaklarım', 'kirik-ellerim-ve-ayaklarim-emre-uslu-dv6ev', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Daha demin konuştuk seninle,

Evet haklısın yokum yanında,

Bir türlü gelemiyorum,

Kalamıyoruz baş başa,

Bir de şöyle düşün,

Ben sizin bahçenizdeki,

Büyük çınar ağacıyım,

Vardır benim de bin elim-ayağım,

Gözlerim sabahlara kadar,

Güzel yüzünü, açık kalan pencerenden,

Uyuyamam sabaha kadar,

Sonraki gün seni göreceğim diye heyecandan,

Bir tek sana bu kadar güvenmiştim,

Sen de beni yalnız bıraktın,

Bekliyorum artık eylül gelsin de,

Kırılsın ellerim-ayaklarım,

Açılsın da ellerimin kapattığı yüzüm,

Görebilsin bu gözler seni son bir daha,

Ve kalsın son iki yaprak,

Onlarla son bir defa daha sana dokunayım,

Varayım tadına senle olmanın,

Ağlama dedim sana bekle göreceksin,

Güzel günleri..', 'Daha demin konuştuk seninle, Evet haklısın yokum yanında, Bir türlü gelemiyorum, Kalamıyoruz baş başa, Bir de şöyle düşün, Ben sizin bahçeni...', ARRAY['Türk Edebiyatı','Şiir','Emre Uslu']::text[], 8.5, '{"poet":"Emre Uslu","poet_slug":"emre-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kirik-ellerim-ve-ayaklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki İsmail', 'i-ki-i-smail-i-smail-ersin-dalgic-a7zl6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşam çizgisinde koşturmaca,

İkisi de hastalıktan mustarip,

İki  İsmail,

Hayatının üçte ikisini tamamlamış,

Kalan biri için çare arar.

Yaşımın elli beşte biri değil,

Meyvamın meyvası.

Daha yeni tomurcuk tertemiz,

Ölmez kökler saldın dünyaya.

Sanki can pazarındayız,

Çocuğumun çocuğu,

Bu yarışta tabii birinci.

Ben artık değişmeyen değişime,

Sonsuzluğa yol almaktayım,.

Askerlik gibi mi desem,

Nöbetimi devredecem.

Süratle hastalığını yenen torunum,

Adeta şaşırttı beni.

Ben ise bitti dediğim hastalığım,

Bakmışım düzinesiyle sırada.

Kana kana ye,

Ömrüne de noktayı koymayı unutma.

Biri yok oluyor,

Biri var oluyor,

Doğa kendini yeniliyor,

Yeni filizler veriyor.

İsmail,

  İsma,

       İs,

         İ.

		İsmail Ersin Dalgıç

			2 Şubat, 2004', 'Yaşam çizgisinde koşturmaca, İkisi de hastalıktan mustarip, İki  İsmail, Hayatının üçte ikisini tamamlamış, Kalan biri için çare arar. Yaşım...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/iki-ismail-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni ufuklarda ara beni', 'yeni-ufuklarda-ara-beni-emre-uslu-61nec', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayalinde yaşat beni,

-o hayal ki ne düşler kurar,

ve bize yaşam sevinci sağlar-

Aradım seni, açmadın,

İyi oldu açmadığın,

Diyecektim sana “Gülüm! ”

Ama sonra düşündüm,

Gülün ömrü kısadır,

Sense bir ömürsün benim için.

Aradım seni, açmadın,

İyi oldu açmadığın,

Diyecektim sana “Hayatım! ”

-o hayat ki çok şeyler eder-

Kendimi tutamayacaktım, 

Sonra dedim kendi kendime,

“Hayatım bitecek ama..”

Bitmeyecek sana olan yaşamım.

Seni sevdikçe varolacak bu mısralar,

Öyle ki buna yetmez hayatlar,

Çünkü hep böyledir başlangıçlar..', 'Hayalinde yaşat beni, -o hayal ki ne düşler kurar, ve bize yaşam sevinci sağlar- Aradım seni, açmadın, İyi oldu açmadığın, Diyecektim sana “...', ARRAY['Türk Edebiyatı','Şiir','Emre Uslu']::text[], 8.5, '{"poet":"Emre Uslu","poet_slug":"emre-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yeni-ufuklarda-ara-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç kelime', 'uc-kelime-i-smail-ersin-dalgic-9eych', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Doğdun İsmail,

Ne de güzel,

İnsanlara karıştın.

Yaşadın İsmail,

Fakirlikte de onurunla,

Emeğinle geçindin,

Verilmeyecek hesabın yok.

Öldün İsmail,

Ulan hergele,

Sanki yüz metrecisin.

Her işin aceledir,

Ölmek gibi.

İlahi İsmail,

Bu kadar iş için mi geldin dünyaya? 

Doğduk,

Yaşadık,

Öldük.

Üç kelimeden ibaret hayatımız.

Şaşırdın mı İsmail? 

Doğanın kanunu bu.

		İsmail Ersin Dalgıç

			21 Ocak, 2004', 'Doğdun İsmail, Ne de güzel, İnsanlara karıştın. Yaşadın İsmail, Fakirlikte de onurunla, Emeğinle geçindin, Verilmeyecek hesabın yok. Öldün İ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/uc-kelime-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-hikmet-guner-ww2qh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin sessiz karanlığında

Uyanıp da gözlerimi açtığımda

Zennettim sen varsın yanımda

İşte o an hissettim kendimi boşlukta

Gecenin sessiz karanlığında 

Oturdum yatağın ortasında

Oysa sen vardın kollarımda

Bir an yok oldun gözlerimi açtığımda

Nede güzel birlikteydik

Sevgiyle aşkla dirlikteydik

Meğer bir rüyaymış

Fark ettim gözlerimi açtığımda

Keşke hiç uyanmasaydım

Uyanıpda kalkmasaydım

Varmış olurduk mutluluğun sonuna

Gözlerimi açtığımda', 'Gecenin sessiz karanlığında Uyanıp da gözlerimi açtığımda Zennettim sen varsın yanımda İşte o an hissettim kendimi boşlukta Gecenin sessiz k...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruya-147-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişim', 'degisim-i-smail-ersin-dalgic-g0sw3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eski İsmail gitti yeni İsmail geldi,

Ne yazık ki yeni İsmail’i yargılıyorsunuz,

Kendi içinde yaşadım,

Ekonomik siyasal kültürel devrimi,

Sanki yılan kabuğunu değiştirmiş gibi,

Ben sınıfımı buldum.

Kusura bakma ensesi kalın,

Savunacağım son nefesime kadar,

Düşündüğüm fikrimi.

Bilsem ki dünya üzerinde bir tek zerren var,

Karşındayım bir saniyelik nefesim de kalsa.

Canlı cansız size sesleniyorum,

Düşmanınızı bilin, bilin ki,

Hep beraber doya doya kucaklaşalım.

Emekçiler size bir çift sözüm var,

Dünyada daha silah  icat edilmedi,

Bizim güç birliğimize karşı,

Kullandığımız an kurtuluşumuz demektir.

		İsmail Ersin Dalgıç

			14 Ocak, 2004', 'Eski İsmail gitti yeni İsmail geldi, Ne yazık ki yeni İsmail’i yargılıyorsunuz, Kendi içinde yaşadım, Ekonomik siyasal kültürel devrimi, San...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/degisim-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar', 'i-nsanlar-i-smail-ersin-dalgic-5ybfm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hey hey insanlar,

Biz nereye koşuyoruz? 

Ömür dediğimiz ne ki? 

En fazla yüz yirmi yıl.

Kendini beğenmiş sana söylüyorum,

Bir tek başına var olamayacağını,

İstesen de istemesen de kardeşiz,

Milyonlarca iple bağımlıyız.

Bırak egoistliği, bırak sömürmeyi,

Paylaşmayı bil, bil ki,

Altı milyar insan şarkılar söylesin,

Bak o zaman göreceksin,

Dünyadaki mutluluğu.

Sen kabul etmesen de beraber yaşayacağız,

Doğanın kanunu bu,

Diyalektik ve materyelizimin gereği,

		İsmail Ersin Dalgıç

			1 Ocak, 2004', 'Hey hey insanlar, Biz nereye koşuyoruz?  Ömür dediğimiz ne ki?  En fazla yüz yirmi yıl. Kendini beğenmiş sana söylüyorum, Bir tek başına var...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/insanlar-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kafa', 'kafa-i-smail-ersin-dalgic-7arxd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mecazi anlamda kullanırsak,

Yukarı ki kafa,

Birde aşağı ki kafa vardır.

Aşağı kafanın rotası bizim elimizde,

Kaçırırsak baştan kara gelir.

Yukarı ki kafa usumuz,

İnsanın anlama ve önleme yetisi,

Kurtuluş yolunu araştırma,

Bu bana bir us pahasına geldi,

Muhakeme etmemi sağladı.

Kafa değil us yeteneğimizi geliştirmeliyiz,

Kendini yöneten dünyayı yönetir,

Us,

   Uss,

      Usss.

		İsmail Ersin Dalgıç

			8 Ocak, 2004', 'Mecazi anlamda kullanırsak, Yukarı ki kafa, Birde aşağı ki kafa vardır. Aşağı kafanın rotası bizim elimizde, Kaçırırsak baştan kara gelir. Y...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kafa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk çiçeği', 'ask-cicegi-hikmet-guner-6aefk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Odama aşk çiçeği koydum

Dallarına resimlerimizi koydum

Ölümsüzdür bu aşk çiçeği

Adını Hikmet ile Müzeyyen koydum', 'Odama aşk çiçeği koydum Dallarına resimlerimizi koydum Ölümsüzdür bu aşk çiçeği Adını Hikmet ile Müzeyyen koydum...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-cicegi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sımsıcak', 'simsicak-i-smail-ersin-dalgic-4p6zy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ocak ayı soğukları,

Gripten muzdaripim.

Sabahtan kalktım,

Şalterler indirilmiş sanki,

Ne ses, ne duyma.

Gecikmeli de olsa,

Dr. Gülsen G.Öğmen’e

Aman doktor canım doktor,

Derdime bir çare.

Çaresiz dert yok der gibi,

Hem psikolojik, hem patolojik,

Uyguladı tedavisini.

İnsan sıcaklığı, sımsıcak,

Hayata yeniden bağladı beni.

Hipokrat yeminine bağlı kalmışsın,

İnadına ömrün uzun olsun,

Başarılar doktor hanım.

		İsmail Ersin Dalgıç

			8 Ocak, 2004', 'Ocak ayı soğukları, Gripten muzdaripim. Sabahtan kalktım, Şalterler indirilmiş sanki, Ne ses, ne duyma. Gecikmeli de olsa, Dr. Gülsen G.Öğme...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/simsicak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Ne Etsem', 'seni-ne-etsem-i-smail-ersin-dalgic-bwwde', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O biri değil, 

Dediğim dedik diyen,

O biri değil,

Kendi söylediğinden başkasını kabul etmeyen.

O biri değil,

Kaya gibi sert esneklik göstermeyen.

O biri değil,

Ailesi için kendini feda eden.

O biri değil,

Yarimiz, anamız, avradımız.

O biri değil,

Seni ne etsem de eylesem anlatsam.

		İsmail Ersin Dalgıç

			5 Ocak, 2004', 'O biri değil,  Dediğim dedik diyen, O biri değil, Kendi söylediğinden başkasını kabul etmeyen. O biri değil, Kaya gibi sert esneklik gösterm...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-ne-etsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Kadın', 'uc-kadin-i-smail-ersin-dalgic-6zmbg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatıma üç kadın girdi,

Biri anam 

	kanımdır.

Hayatıma üç kadın girdi,

Biri karım

	canımdır.

Hayatıma üç kadın girdi,

Biri hayal

	gücümdür.

Anam elimden tuttu,

Karım yanımda yürüdü,

Hayal gücüm ayakta durdurdu.

Biri kanım,

Biri canım,

Biri evrem.

Kanım,

Canım,

Evrem.

		İsmail Ersin Dalgıç

			31 Aralık, 2003', 'Hayatıma üç kadın girdi, Biri anam  	kanımdır. Hayatıma üç kadın girdi, Biri karım 	canımdır. Hayatıma üç kadın girdi, Biri hayal 	gücümdür....', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uc-kadin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Fermanı', 'gonul-fermani-yavuz-agir-fwmx1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönül kapın aralandı

Gönüller sıra sıra sıralandı.

Muhabbet zamanıdır artık

Ferman gönüle ayarlandı

Seher vakti ısız olur

Aşk sevgiyi gelir bulur

Davetsiz   gel  gir içeri

Ferman gönüle ayarlandı', 'Gönül kapın aralandı Gönüller sıra sıra sıralandı. Muhabbet zamanıdır artık Ferman gönüle ayarlandı Seher vakti ısız olur Aşk sevgiyi gelir ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gonul-fermani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelen Hazandı Hüznü Kucakladı', 'gelen-hazandi-huznu-kucakladi-ahmet-derya-suel-vc80h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Arabayı ani bir hareketle köprünün üstünde durdurdu,kapıyı açtı koşarak bir çırpıda korkulukları aştı parmaklığı tırmandı ve

bir an bile tereddüt etmeden kendini yukarıdan bir gelin edasında süzülen hırçın maviye doğru bıraktı.Hırçın mavi ayaklarının altında gittikçe büyüyen bir sonsuzluk gibiydi.Birden sırtında çok uzun ve yorgun yılların ağırlığını hissetti.Ne çok yaşamışım diye düşündü.Tatlı bir hoşluk kapladı yüreğini uçmak nede güzeldi.Birden tüm yaşamı bir film şeridi geldi önüne.Çocukluğunu anımsadı haylaz çocukluğunu,nasılda üzmüştü annesini hep umursamaz tavır

ları ve inatçı yaramazlıklarıyla; güldü özür diledi annesinden yanağına bir buse kondurarak ve herkesten özür diledi ağla_

yarak.Zaman şimdi onsuzluğun gerisinde en son bıraktığı yerdeydi:İlk gençliği düştü aklına sonra.Bıyıklarının ilk terleyişi

ilk erkeklik,ilk cinsellik ve ilk deneyim.Elbet tattığı ilk aşk.Bir_

den aklına düştü eli yüreğine gitti,yüreğinden hiç atmadığı 

resmi çıkardı baktı baktı.Gülümsedi hafiften şimdi nerdesin,ne yaparsın,kimbilir hangi şehirde hangi masalda yaşarsın.Bırakıp gittiğinden beri ne pencereme gün doğdu,

nede güneş düştü çiçeklerine.O çok sevdiğin menekşe bile 

sensiz soldu.Bir tek resmin kaldı yadigar oda yüreğimde.

Oysa ne aşklar yaşamıştım senin üzerine,hepsikarın tokluğuna.Sen başkaydı ama; ne zaman açsam yüreğimi baksam resmine hep gülümserdin.Menekşe gözlerin,nar yanakların,kiraz dudakların,manolya saçlarınla eşsiz bir bahçeye benzerdin.Ben aşka düşeli böyle hüküm sürmedi yüreğim.Şimdi zaman ne sensizliğin ötesinde ne yaşam yüreğimde.Seni çok özledim.Gidiyorum işte vedası olmayan

sorgusuz bir infaz gibi.Sona hızla yaklaştı,deniz ve mavi artık daha yakındı.Gözlerini kapattı,yüreğini açtı yıldızlara ulaştı; 

yıldızların yansıyan sevdasına.Güldü ne çok geç kalmışım.

Gökyüzü patladı deniz yarıldı birden içinden bir deniz kızı 

ellerini uzattı yakaldı,çok bekledim çok geç kaldın neden diye

sorguladı.Titrek bedenine elektrikaktı,yüreği çarptı yıllarca

aradığı aşkı onu bulmuştu.Birden kapının ziliyle uyandı,yatağından fırladı kapıyı açtı hiç şaşırmadı gelen Hazan

dı Hüznü kucakladı.

(ADS/1.11.2004) 

Her hakkı gülüme aittir.', 'Arabayı ani bir hareketle köprünün üstünde durdurdu,kapıyı açtı koşarak bir çırpıda korkulukları aştı parmaklığı tırmandı ve bir an bile ter...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Derya Süel']::text[], 8.5, '{"poet":"Ahmet Derya Süel","poet_slug":"ahmet-derya-suel","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gelen-hazandi-huznu-kucakladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı da', 'kirmizi-da-filiz-ocakoglu-zgaz2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırmızıya

Bürünmüştü gece...

Kırmızı gül

Kırmızı şarap

Kırmızı dudaklarla...

Bakışları

Ay ışığında

Titreyen iki ışık...

Saçlarında

Gecenin siyah mavisi...

Sesinde 

Hüzünlü bir türkü...

Arada bir 

Bana bakıyor

Tatlı tebessümüyle...

Yaseminler

Yayılıyor teninden

Gecenin ılık nefesiyle...

İşte o zaman

Bir garip oluyorum...

Şaraptan mı

Geceden mi 

Biraz şehla mı bakışları

Çözemiyorum...

Öylesine rahat ki

Kızıyorum halime

Kadehi tutamayan

Elime...

Seviyorum diyemeyen

Dilime...

Gülüyorum...

Kabahat bende değil.

Ya onda

Ya gece de

Ya da kırmızı da

Bilemiyorum...', 'Kırmızıya Bürünmüştü gece... Kırmızı gül Kırmızı şarap Kırmızı dudaklarla... Bakışları Ay ışığında Titreyen iki ışık... Saçlarında Gecenin s...', ARRAY['Türk Edebiyatı','Şiir','Filiz Ocakoğlu']::text[], 8.5, '{"poet":"Filiz Ocakoğlu","poet_slug":"filiz-ocakoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kirmizi-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir mendil işleyeceğim', 'bir-mendil-isleyecegim-i-smail-ersin-dalgic-im16x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir mendil işleyeceğim

               yarına kadar.

Öpücükten ve baldan

                           tatlı.

Bir filistin var,

Bir filistin gene var.

                İsmail Ersin Dalgıç

                           7 Kasım,2004

Kahrolsun İsrail siyonizmi.

Kahrolsun İsrail işgali.

Yaşasın Filistin halkının haklı direnişi! 

Filistin halkının ölümsüz önderi Yaser Arafat''a acil şifalar diliyorum.', 'Bir mendil işleyeceğim                yarına kadar. Öpücükten ve baldan                            tatlı. Bir filistin var, Bir filistin gen...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ersin Dalgıç']::text[], 8.5, '{"poet":"İsmail Ersin Dalgıç","poet_slug":"i-smail-ersin-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-mendil-isleyecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-yavuz-agir-v1qtd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dağlar dağım olacak

Bağlar bağım olacak

Dostlar gelin yanıma

Gönül çağım olacak

Dağ gülüne süs olayım

Koklayınca senin olayım

Diline bülbül olayım

Gönül sultanın olayım', 'Dağlar dağım olacak Bağlar bağım olacak Dostlar gelin yanıma Gönül çağım olacak Dağ gülüne süs olayım Koklayınca senin olayım Diline bülbül ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/daglar-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın Anlamı', 'hayatin-anlami-i-smail-ozabaci-neczw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'üşümek akşam üstleri bir bankta hayat

yüreğinin sıcaklığını yansıtmak yüzüne bir nebze

elini tutamamak belki hayat

soğuk bir gecede

nedeni var mı bu nefes almanın

durdurulabilir mi yoksa zaman

yarınlar mı üşütüyor içimizi

kurşunlar mı yoksa bizi yakan

anılara bir an dalarken insan

sonbaharı ne kadar unutabilir ki

ey aşk,

ey hayatın anlamlı yanı,ey duyguların şahı

ey kelebeklerin son durağı

ey üşümelere sebeb

ey kuşların kanat çırpışı

hadi saklama artık kanatlarını

herkes bilsin melek olduğunu

belki o zaman anlarız

hayatın hayat olduğunu...', 'üşümek akşam üstleri bir bankta hayat yüreğinin sıcaklığını yansıtmak yüzüne bir nebze elini tutamamak belki hayat soğuk bir gecede nedeni v...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hayatin-anlami-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yontu', 'yontu-salih-demirci-lxa6h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün boyu

Güne aldırmadan

Basit uğraşlara sardırmadan 

Biçilir yontu

Yoksunluk hükmünü sürer

Gecenin kadehine 

Sek hayatlar düşer

Biçildikçe,

Küçülür yontu', 'Gün boyu Güne aldırmadan Basit uğraşlara sardırmadan  Biçilir yontu Yoksunluk hükmünü sürer Gecenin kadehine  Sek hayatlar düşer Biçildikçe,...', ARRAY['Türk Edebiyatı','Şiir','Salih Demirci']::text[], 8.5, '{"poet":"Salih Demirci","poet_slug":"salih-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yontu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağların Ardındayım', 'daglarin-ardindayim-yavuz-agir-lfnqv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dağların arka yüzü

Bize dargınmı bilmem? 

Ovanın orta düzü 

Bize kırgınmı  bilmem? 

Dağlar benim mekanımdır

Ova benim öz kârımdır

Güle nergiz satarım

Oda benim efkârımdır', 'Dağların arka yüzü Bize dargınmı bilmem?  Ovanın orta düzü  Bize kırgınmı  bilmem?  Dağlar benim mekanımdır Ova benim öz kârımdır Güle nergi...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/daglarin-ardindayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vedası olmayan', 'vedasi-olmayan-ahmet-derya-suel-kr1ga', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gidiyorum şimdi

Vedasız bir gidiş

Ertelenmiş bir yolculuk hüznüme

Bu gidiş bir kaçış değil

Yorgun bedenimde yeni bir doğuş.

Sevgisizlikler içersinde sevgiyi arayış nedenim

Bütün delik deşik edilmiş kalplere karşı

Gidiyorum şimdi

Dışım asi bir yaramaz çocuk

Yüreğim suskun

Bir Gülü incitmekten korkum

Erkekçe gidiyorum işte

Eyvallahı olmayan bir martı gibi

Hırçın rüzgara inat

Ne çok sevmişim seni

Göz bebeklerimin aynasında

Yansıyan bir yıldız gibi

Gidiyorum şimdi

Ufkuna güneşin

zerre kadar umutsuz değilim

Yaşanmış yıllarım rehberim

Seni bulana dek

Bu yolculuk

Hangi zaman hangi mekan 

Önemli değil

Gidiyorum işte

Vedası buruk olmayan mertçe

Çok uzakda olsan

Paylaşılan bir gökyüzü var

Ve 

O gökkubbede var olan

beraberce paylaşacağımız tek bir sevgi.

ADS/6.11.2004

Her hakkı gülüme aittir.', 'Gidiyorum şimdi Vedasız bir gidiş Ertelenmiş bir yolculuk hüznüme Bu gidiş bir kaçış değil Yorgun bedenimde yeni bir doğuş. Sevgisizlikler i...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Derya Süel']::text[], 8.5, '{"poet":"Ahmet Derya Süel","poet_slug":"ahmet-derya-suel","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/vedasi-olmayan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlar', 'onlar-volkan-yoruc-8c9zk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir vakitler mutluluk vardı

Kalbimin içinde gönlümün köşesinde

Beni yalnızlığa karşı

Hayata karşı koruyan onlar vardı

Onlardı beni gülümseten

Pembe düşlerime kanatlar geren

Gri bulutlarımı mavi gökyüzüme çeviren

Onlardı ağlamayı bana unutturan

Çöller kadar yalnız kalmışım şimdi

Onlar beni terkettiğinden yana

Sevdalara hasret kalmışım

Mutluluğu hayallerde arar olmuşum

Onlar beni unuttuğundan yana

Bir vakitler sevdalarım vardı

Güzlerim ilkbahar olur

Gözlerim gülücüklerle dolardı

Onlar gittiğinden yana

Karanlık gölgeler helal olmuş bana', 'Bir vakitler mutluluk vardı Kalbimin içinde gönlümün köşesinde Beni yalnızlığa karşı Hayata karşı koruyan onlar vardı Onlardı beni gülümsete...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/onlar-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkına Hastayım', 'askina-hastayim-osman-i-nci-e2prf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir derinden bakıyor, yüreğimi yakıyor,

Deli eden rengiyle, bir mutluluk veriyor,

Serin bir ferahlığı, kalbime gönderiyor,

Gözlerine hastayım, o gözlerine vurgun...

Kan gibi damarımda, yüreğimde kalırsın,

Bir aşk şarkısı gibi, nağmeler fısıldarsın,

Büyülenir dinlerim, beni benden alırsın,

Sözlerine hastayım, o sözlerine vurgun...

Bahar rüzgârlarında, bir edayla uçuşur,

Yüreğimin üstünde, kıvılcımlar oluşur,

Bir arkadaş olur da, benim ile konuşur,

Saçlarına hastayım, o saçlarına vurgun...

Hayatımın güneşi, ömrümün baharısın,

Yüreğimdeki ateş, damarımda kanımsın,

Bulutlarımda yağmur, bahtımın yazısısın,

Bir aşkına hastayım, birde sevdana vurgun...', 'Bir derinden bakıyor, yüreğimi yakıyor, Deli eden rengiyle, bir mutluluk veriyor, Serin bir ferahlığı, kalbime gönderiyor, Gözlerine hastayı...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askina-hastayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-volkan-yoruc-7odxa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Unutulmuşluğa yelken açmışım

Gözlerim güneşi arar delice

Bir umut beslerim içimde

Aşka dair sevgiye dair

Dolu dolu düşler biriktiririm yüreğimde

Ben unutulmuşum

Umursanmaz tekmelerle savrulmuşum

Toprağa sarılırken sessizce

Acılarımla mutluluğa tutunmuşum

Bir umut beslemişim yüreğimde

Zamana meydan okumuşum

Yaman kışlarda kalmışım

Buz kesen ellerimde çiçeklerimi tutmuşum

Vazgeçmemişim sevdalardan

Deli divane dönmüşüm dünyayla birlikte

Yıldızlara uzanmışım

Sonsuz boşlukta kaybolmuşum

Vazgeçmemişim aşklardan

Sevgili yerine umuduma sarılmışım

Bir onu sevmişim

Bir ona tutulmuşum

Beni yıkan her ayrılıkta

Kor ateşlerim içinde yeniden doğmuşum

Savurmuşum hüzünleri her doğruluşumda

Koşmuşum coşmuşum

Aşka dair hayallerle bu cihanda', 'Unutulmuşluğa yelken açmışım Gözlerim güneşi arar delice Bir umut beslerim içimde Aşka dair sevgiye dair Dolu dolu düşler biriktiririm yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ben-136-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttum', 'unuttum-hikmet-guner-im8yh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Unuttum bir an yanlız olduğumu

Eve geldim kapının zilini çaldım

Bekledim uzunca ne ses nede vecap aldım

Açtım kapıyı girdim içeri... Baktığımda

İşte o an anladım yanlız olduğumu

Dolaştım tek tek odaları

Aradım seni her yerde

Oysa ne sen vardın, nede sesin

İşte o an anladım yanlız olduğumu

Saklanmıştır oyun yapıyor dedim

Şimdi çıkar dolabın oradan dedim

Baktım ki orada da yoksun, yatağım bomboş

İşte o an anladım... yanlız olduğumu', 'Unuttum bir an yanlız olduğumu Eve geldim kapının zilini çaldım Bekledim uzunca ne ses nede vecap aldım Açtım kapıyı girdim içeri... Baktığı...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unuttum-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş sıcaklığı Gözlerin', 'ates-sicakligi-gozlerin-atil-kesmen-7zoh7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgi pınarlarından akıp gelen

Gül kurusu renğe bürünmüş gözlerin

Arı vızıltısı görülmezlğine saklanmış

Bakışların arasında

Yudum yudum buse gönderiyordu hislerime

Ateş almış gözlerinden dağılan ışık

Dolanıp vurdukça duygularıma

Bedenime sızıp,saklanan sen

Sevgi tohumlarını ekiyordun 

Kalp seslerime

Güneş sıcaklığı gözlerin

Gündüzleri karanlıkları bir araya getirmiş hislerin

Kabul etmemi istiyordu

Gönül sevginden gelen

Gönül sessizliğime gizlenmiş gözlerini', 'Sevgi pınarlarından akıp gelen Gül kurusu renğe bürünmüş gözlerin Arı vızıltısı görülmezlğine saklanmış Bakışların arasında Yudum yudum buse...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ates-sicakligi-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oldu', 'oldu-hikmet-guner-vnv6u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalem elimden düşmez oldu

Defterim şiirlerinle doldu

Yazdıkça gözlerim doldu

Sensizlik bana zindan oldu

Hikmet sana hep kurban oldu

Hasretinle içim doldu

Yaz bitti kış oldu

Sabret güzelim yakında

Kavuşmak bize farz oldu', 'Kalem elimden düşmez oldu Defterim şiirlerinle doldu Yazdıkça gözlerim doldu Sensizlik bana zindan oldu Hikmet sana hep kurban oldu Hasretin...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/oldu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canımsın...', 'canimsin-i-brahim-ethem-bingul-wwolx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Canıma can kattın

Aldın beni benden kendine kattın

Ne zaman,nasıl, nerede yaptın

Işıl ışıl gözlerinle aşkı hatırlattın

Mesafeleri aşkına taşıtıp

Sevginin güzelliğinde beni şarhoş ettin

Işıksız dünyamı aydınlatıp

Nasıl bir aşksın sen, beni benden ettin...

www.iebingul.com', 'Canıma can kattın Aldın beni benden kendine kattın Ne zaman,nasıl, nerede yaptın Işıl ışıl gözlerinle aşkı hatırlattın Mesafeleri aşkına taş...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/canimsin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgunum', 'yorgunum-hikmet-guner-2yxuq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Meğer sensizlik ne zormuş

Zannettim sensiz olur, ama olmuyormuş

Hayalinle geçti hep günlerim

Meğer beni çalışmak değil, sensizlik yormuş

Otursamda bir kenara, dinlensemde bir ara

Yorgunluk bana vız gelir

Giderim seninle ölüme dek, birlikte mezara

Meğer beni çalışmak değil sensizlik yormuş

Ne güçlüsün hiç yorulmuyorsun dediler

Yüzüm hep güldü ama içimi hiç bilmediler

Aslında yorgunluk benim beynimde 

Meğer beni çalışmak değil sensizlik yormuş', 'Meğer sensizlik ne zormuş Zannettim sensiz olur, ama olmuyormuş Hayalinle geçti hep günlerim Meğer beni çalışmak değil, sensizlik yormuş Otu...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yorgunum-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç bitmeyecek', 'hic-bitmeyecek-hikmet-guner-898kf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zannetme bu böyle hep sürüp gidecek

Zannetme ayrılıkla aşkımız bitecek

Aşkımız bir derya sonuna dek gidecek

Sevgim sana dahada arttı, hiç bitmeyecek

Böyle sızı olurmu, sızım hiç dinmeyecek

Böyle aşk olurmu, aşkımız hiç bitmeyecek

Hasretle ateşler kor gibi hiç sönmeyecek

Birbirimize doymadan aşkımız hiç bitmeyecek

Alev alev yanar yangınlar hiç sönmeyecek

Söndürmeye sular seller yetmeyecek

Ölüme dek ölsekde aşkımız hiç bitmeyecek

Birbirimize doymadan aşkımız hiç bitmeyecek', 'Zannetme bu böyle hep sürüp gidecek Zannetme ayrılıkla aşkımız bitecek Aşkımız bir derya sonuna dek gidecek Sevgim sana dahada arttı, hiç bi...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hic-bitmeyecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Kan Kırmızı Değildir...', 'her-kan-kirmizi-degildir-reside-sarikavak-28s0a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'fısıltıya dönüştü 

iç çekişleri kaldırımların

bir gece daha düşüyor pencerelerimden

ne ay ışığı yadsıyor gözlerimi

ne şehrin aciz ışıkları

susuyorum

sustukça karışıyor sokaklar

ne çıkar kaybolsam bir kez daha

bir kez daha bulunsam

nafile korkutmuyor hiçbir yalnızlık 

üzerine uzandığım ölümler kadar

her gece bir cinayettir

her sabahı bekleyen insan biraz katil

kaybolmaya dair değil bütün dualar

beraber kaybolmaya dair

gün, gece ve serseriler...

ne olurdu yıldızlar yerinde kalsaydı

kendini bilebilseydi güneş

ellerim temizlenebilseydi minik ecirlerimle

oyunlar çıkarabilseydim

şiirlerimden

beklemek

ümit etmek değildi hiç

düşünmenin sevmek olmadığı gibi

sadece kısrakların rahmiydi

bozulmuş tenim

ki her kan da kırmızı değildi...

kaldırımlar da susacak bir gün

yüzümün rengiyle yıkanacak şehir

benimle ölmen gibi değil, anla

seninle ölmek gibi

izler bıraktım tırnaklarımda...', 'fısıltıya dönüştü  iç çekişleri kaldırımların bir gece daha düşüyor pencerelerimden ne ay ışığı yadsıyor gözlerimi ne şehrin aciz ışıkları s...', ARRAY['Türk Edebiyatı','Şiir','Reşide Sarıkavak']::text[], 8.5, '{"poet":"Reşide Sarıkavak","poet_slug":"reside-sarikavak","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/her-kan-kirmizi-degildir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Varya', 'hani-varya-hikmet-guner-z710m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani dudaklar birleştiğinde varya

Hani nefes almak geçilmez kapıdır darya

Hani Kalpler durur çalışmaz varya

İşte o zaman dizin bağı çözülür

Hani Aşkının kalbimdeki yeri varya

Hani çivilidir kımıldamaz yerinden varya

Hani Gözlerin buluştuğu o güzel an varya

İşte o zaman dizi bağı çözülür

Hani kuşların göğe yükselişi varya

Hani bulutların  üstünde uçmak varya

Hani kalp atışlarının artışları varya

İşte o zaman dizin bağı çözülür', 'Hani dudaklar birleştiğinde varya Hani nefes almak geçilmez kapıdır darya Hani Kalpler durur çalışmaz varya İşte o zaman dizin bağı çözülür ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hani-varya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim doldu', 'gozlerim-doldu-hikmet-guner-hmq7w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İşte yine akşam oldu

Yine gecem sessizlikle doldu

Bir sen bir de, resimlerle  başbaşa

Baktıkça hep gözlerim doldu

Bir dışardan gelen trenin sesi

Bir evdeki saatin tıklayan sesi

Çınlar kulaklarımda çocukların sesi

Baktıkça resimlere hep gözlerim doldu

Dünyada bir tek bizmiyiz ayrı olan

Ayrı olsakda hergün artan sevgiyle dolan

Yanlız resimlerle bile mutlu olan

Baktıkça resimlere gözlerim doldu', 'İşte yine akşam oldu Yine gecem sessizlikle doldu Bir sen bir de, resimlerle  başbaşa Baktıkça hep gözlerim doldu Bir dışardan gelen trenin ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerim-doldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşersem Eğer', 'dusersem-eger-sami-akman-0jwvm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün hatırına düşersem eğer

Sağanak yağmurlar gibi

Ya da deli esen rüzgâr gibi

Gözlerin nemlendiğinde

Bu an''lar gelecek aklına

Sonra düşüneceksin

Gülümseyerek anacaksın, için yanacak

Yanaklarına sessizce inen yaşlarını

Sileceksin hatırına düştüğümde

Pişmanlığın bir ırmak gibi akacak

Suya düşecek gölgen, korkacaksın

Uzanıp almak istediğinde 

Suya verdiğin hatıralar gibi

Ellerin titreyecek alamayacaksın

Bir hiç yüzünden silip attığın sevgilinin

Sevgisine, sesine, bedenine ihtiyacın olduğunda

Lime lime olmuş elbiselerine bile razı olacaksın

Muhtaç olacaksın ama bulamayacaksın

Yalanlara inandın, kıskançlığın esiri oldun

Oysa sana olan sevgi de hiç yalan yoktu

Bembeyaz bir sayfaydı senin sevgin

Bir çırpıda tükettin her şeyi hiç düşünmeden

Bir can’a mal olacağını bilemedin

Senden ayrılmanın bir ölüm olacağını düşünmedin

Sana hiçbir şey vaat etmemiştim

Sende bana

Gerçekleri görerek, bilerek sevmiştik istisnasız

Hiç soru sormamıştık, sormayacaktık 

Bir sır olarak kalacaktı bu sevgi aramızda

Adı bende saklı

Ben yaşarım şimdi hatıralarla, belki yaşarım

Ama en çok istediğim şey inan ölüm

Ben sensiz öldüm zaten ne fark eder ki

Şimdi sen düşün, içini kemiren vicdanının sesini

İçinde büyüyen sevginin nasıl yangına dönüştüğünü

Düşün sende mutlu olacaksın, olabiliyorsan eğer

Ya da her gün kahroluşunu

Bir gün hatırına düşersem eğer

Yaşadığımız o an’lar aklına geldiğinde

İçin sızlayacak, gözlerinden yaşlar akacak

Ellerin titreyecek silerken gözyaşlarını

Arayacaksın, ama bulamayacaksın

Sevgisini, sesini, lime lime olmuş elbiselerini

Arayacaksın, bulamayacaksın

Bulamayacaksın……

®©', 'Bir gün hatırına düşersem eğer Sağanak yağmurlar gibi Ya da deli esen rüzgâr gibi Gözlerin nemlendiğinde Bu an''lar gelecek aklına Sonra düşü...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/dusersem-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arap', 'arap-i-smet-barlioglu-o1xxx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '- 1 -

Kapı çalındığında gecenin yarısıydı,

Bu saatte gelen kim ve nasıl birisiydi? 

İsmail Ağa kalktı, bakındı çevresine,

Dönüp bir göz gezdirdi yaşlı ailesine.

İkisi de yaşlıydı; yetmişin üzerinde,

Yorgunluk kolgezerdi bunların bedeninde.

Yatıp kalktıkları yer bir köhne barakaydı,

Hiç olmazsa yoksulluk onları bırakaydı.

Fakat hayır, belaydı yoksulluk başlarına,

Yağı haram etmişti yudumluk aşlarına.

Bir kuru ekmek işte, batır batır suya, ye,

O ekmek de zor gelir komşulardan bu eve.

Oğul-kız yok, torun yok, yakın yok dayanacak,

Yataklara düşseler kim lütfedip bakacak? 

Üst-baş darmadağınık, çul-çuval kabilinden,

Yolları geçmez olmuş tek bir nasip önünden.

Gündüz tek gün ışığı, geceleri gaz lamba,

her şeye şükrederler, çünkü; yaşamak bu da.

Bu yüzden çok korkuttu kapının çalınması,

Zöhre Kadın bakarken ilerledi ağası.

Adam merakla sordu: ‘Kimdir o; kapıdaki? ’

‘Tanrı misafiriyim.’ Diyordu dışarıdaki.

Kapı mı açılmazmış Tanrı ‘nın konuğuna? 

Yaşlı adam sevindi o sözü duyduğuna.

Kapıyı yana açtı sürgüsünü çekerek,

Sevgilerle seslendi ‘Buyur ağam.’ diyerek.

‘Tanrı ‘nın konuğunun emrindedir evimiz,

Canımızı yoluna biz kul-kurban ederiz.

Hele buyur, gel şöyle, bir bağdaş kur mindere,

Tanrı ‘nın konuğunu oturtamam yerlere.

Hoş geldin, safa geldin, bizlere şeref verdin,

Muhterem varlığınla bu evi şenlendirdin.

Bağışla bir adını, sen kimsin, kimlerdensin? 

Buralardan değilsin. Acep nerelerdensin? 

Ne yaman yorulmuşsun, hele otur, bir dinlen,

Yorgunluk şimdi geçer, bir şey ye, biraz eğlen.

Bu kadın avradımdır, Zöhre derler adına,

Darda kalsam o koşar sadece imdadıma.

O yaşlı, ben çok yaşlı, bir işe yaramayız,

Tövbe de; bu ev yansa kalkıp kurtaramayız.

Elde yok, avuçta yok ama gönlümüz gani,

Can desen can veririz senin yoluna yani.

Zira; sen bir konuksun, Allah ‘ımın konuğu,

Sinmiştir bedenine Yaratan ‘ın soluğu.

Kimiz ki; reddedelim gönderdiğini O ‘nun,

Zatı da yanındadır yolladığı konuğun.

Tanrı ‘nın selamına canımız kurban olsun,

Lütfetsin de o Hazret; barakam konuk dolsun.’

Zöhre Kadın yastıklar getirdi elleriyle,

İkram etti konuğa o fersiz gözleriyle.

Çay demledi bir isli, bir zor yanan ocakta,

Az çökelek, az soğan getirdi bir tabakta.

Ekmek tahtası sürdü konuğunun önüne,

Sıraladı bir şeyler bu tahtanın üstüne.

Dedi: ‘Kusura bakma, Rabb ‘in verdiği bunlar,

Gözleri tok olanlar az şeyle de doyarlar.

‘Yüce Rabb ‘in konuğu esmer, zayıf adamdı,

Uzun sayılmazsa da ona yakın falandı.

Yaşı ell-ellibeş, biraz fazla belki de,

Üstündeki giysiler eskimişti gitgide.

Cepkeni çok eskiydi, şalvarı daha eski,

Sırtındaki cüppesi cüppe sayılmaz belki.

Hayli ince beline sarmıştı şaldan kuşak,

Başında eski sarık, ayaklar çıplak ayak.

Bir hayli ak düşmüştü kıvırcık sakalına,

Elindeki asayı yatırmıştı yanına.

Eller ipince, uzun, parmaklar birer kemik,

Bedeni hayli zayıf, beli-göğsü incecik.

Öyle bir gülümseme mevdudu ki; yüzünde

Sanki nur parlıyordu karanlık gökyüzünde.

Sesi çok etkiliydi, ağır konuşuyordu,

Sözcüğün güzelini arayıp buluyordu.

Yüreği okşuyordu sözleri, ılık ılık,

Düşmana hitap etse; kuracaktı yakınlık.

Dedi: ‘Adım Kul Ahmet, Tanrı ‘nın garibiyim,

Hazret ‘in sevgisiyle gönlü yanan biriyim.

Derviş saymışlar bizi; iltifat eylemişler,

Kime selam vermişsek bizi az-çok sevmişler.

Gezerim ilden ile dur-durak aramadan,

Rabb ‘im sınıyor beni her bir yerde, durmadan.

Ben Tanrı ‘yı aramam; O benim içimdedir,

her şeyde yeri vardır ve binbir biçimdedir.

Ben O ‘nu varlığını kanıtlardan anlarım,

Dünyadaki her şeyi O ‘nunla harmanlarım.

Çünkü; dünya sergidir, sergilenenler O ‘nun,

Üzerinde O yaşar renklerin her tonunun.

Gülden dikene kadar her şeyi yaratmıştır,

O ’nun koleksiyonu dünyayı kuşatmıştır.

Yılan albüm doldurur, kuşlarsa koleksiyon,

Bir mercan yılanından ne kadar büyük piton.

İkisi arasında karmaşık bir toplum var,

Devekuşuna kadar binbir çeşittir kuşlar.

Örümcekler, arılar, karıncalar hünerli,

Ateşböceği var ki; kendisinden fenerli,

İnekler süt veriyor, tavuklar yumurtluyor,

İnsanlar bunun için bir Yaratan arıyor.

Her yerde mevcud olan ne demeye aranır? 

Bana göre; insanlar boş yere küstahlanır.

- 2 –

Ezanlar okunurken besmeleyle kalktılar,

Çul-çaputtan ibaret döşeklerden çıktılar.

Konukla dede, nine kıldılar namazları.

Şükürden ibaretti bilcümle niyazları.

Yani kalkıp Tanrı ‘dan tek şey dilemediler,

Verdiği şeyler için yalnız şükür ettiler.

Sonrası; kuru ekmek, az çökelek, az soğan,

Biraz da çay içtiler, bakır kupaya konan.

Sevgi ve saygı ile konuğa yol verdiler,

‘Tanrı senin ilmini bize verse.’ Dediler.

‘Bize verse sendeki o büyük kanaati,

Bize verse sendeki o eşsiz merhameti.

Sabrını bize verse, huyunu bize verse,

Nice konuğu varsa yine bize gönderse.

Yol versin bütün dünya, ölüler-sağlar sana,

Yol versin tüm ovalar, tepeler, dağlar sana.

Çıkarma hatırından bu yaşlı insanları,

Unutma ki; kurbandır sana aziz canları.’

Derviş sevgiyle çekti dedeyi az uzağa,

Sarmaş-dolaş oldular bir an yanak yanağa.

Sonra Kul Ahmet dedi: ‘Ey değerli ihtiyar,

Öyle konuk ettin ki; hala yüreğim kaynar.

Ekmeğini paylaştın, bana yer-yatak verdin,

Elden gelen her türlü itibarı gösterdin.

Tanrı ‘nın konuğuna hizmet ettin kul gibi,

Bir şey vermek isterim sana, para-pul gibi.

Neylersin ki; garibim, altın dolu küpüm yok,

Bu yalancı dünyada tek fidanım, çöpüm yok.

Her şey yalnız Tanrı ‘nın, malsahibi tek Allah,

Mal-mülk bizim değildir, haşa, estağfurullah.’

Derviş attı elini cüppesinin altına,

Katlı bir kağıt bulup koyuverdi ortaya.

Kağıtta bir ak kılla bir de kara kıl vardı,

Dedi: ‘Bu kıllar bende yıllardır dururlardı.

Ben hiç gereksinmedim ömür boyu bunlara,

Belki gereksinirsin sen, kalkıp da şunlara.

Ak kılla kara kılı sürttüğün an şöyle bir

Nerede olursan ol, bir Arap ‘tır belirir.

Dağlar gibi bir şeydir, bir masal yaratığı,

Toza-dumana katar bir anda ortalığı.

Kılları her kim sürtmüşse Arap kuludur onun,

Tümünü gerçek kılar düşlediğin arzunun.

Armağan ediyorum ancak bunları sana,

Hakkını helal eyle ayrılırken sen bana.’

Ve derviş vedalaşıp asasına abandı,

O bir anda kayboldu. Dede yere kapandı.

- 3 –

Soğuk bir kış günüydü, aylardan şubat falan,

Fırtına ortalığı etmekteydi kolaçan.

Yerler kar içindeydi, toprak görünmüyordu,

Saçaklarn buzları yere sürünüyordu.

Çırılçıplak ağaçlar süslenmişti karlarla,

Dallar kırılıyordu amansız bir rüzgarla.

Sular buza kesmişti, hava buza kesmişti,

Kış bütün görkemiyle kendini göstermişti.

Azık verileceği duyulmuştu ta evde,

İlçeye ondan indi İsmail İshak Dede,

Yapardı belediye her yıl yoksula yardım,

Dede yaya gelmişti ilçeye adım adım.

Yol uzun, beden yaşlı, yolculuk uzun sürdü,

İshak Dede bitmişken ilk evler de göründü.

Kırk kere durdu yolda, kırk kere soluk aldı,

Son defa bir daracık sokakta soluklandı.

Bir dilenci gördü ki; yoksulluk abidesi,

Bir ip çeksen dökülür yamanın kırk tanesi.

Adam yaşlımı yaşlı, sakalı iplik gibi,

Yelde savrulan saçı bembeyaz tiftik gibi.

Sırtı duvara verip oturmuş kar içine,

Kar yağmış omuzlara, başına, ellerine.

Titreyen kirpikleri ince ince buz tutmuş,

Kar dolu bir köşede dünya onu unutmuş.

Dedeyi fark edince el-avuç açtı ona,

‘Allah rızası için dedem, bir onbin lira.’

İsmail İshak Dede yaralandı derinden,

Zira; tek kuruş dahi çıkmadı ceplerinden.

‘Onbin lira’ dediğin simit bile alamaz,

Fakat gel gör durumu; o bile bulunamaz.

Olsa; verecek hemen neyi varsa, tümünü,

Bir küp altını olsa; bağışlar bütününü.

Dede yazıklanırken aklına kıllar geldi,

Sağ eli hemencecik koyuncebine girdi.

Çıkardı iki kılı bir köşeye sinerek,

Umuda yelken açtı iki kılı sürterek.

İki kıl sürtülünce şimşekler çaktı hemen,

Sanki yıldırım düştü kar üstüne göklerden.

Çıkan rüzgar karları hortumladı, savurdu,

Sıcak bir yel yolları, sokakları kavurdu.

Bir nağra yükseldi ki; sağır olur duyanlar,

Dar sokağı bir anda sarıverdi dumanlar.

Dumanlar dağılınca bir Arap çıkageldi,

Aynen minare gibi ta göklere yükseldi.

Saçı kuyruk gibiydi çıplak başın ardında,

Sırmalı cepken vardı kamburlaşmış sırtında.

Azametli pazılar öylece ortadaydı,

Koyu esmer yüzünde şeytani kaşlar vardı.

Bıyıkları saç gibi iniyordu yerlere,

Bir Çinli çekikliği hükmetmişti gözlere.

Belinden aşağısı yoğun sis içindeydi,

Bu sisin her bir yanı bir bambaşka renkteydi.

İsmail İshak Dede pire kadar kalmıştı,

Arap eğilmek için tam iki kat olmuştu.

‘Ferman efendimizin… Her buyruk baş üstüne,

Her arzunuz anında gelecektir yerine…’

İsmail Dede dedi: ‘Arap bir onbin lira.’

Arap şaşırıp kaldı bu kadarcık arzuya.

Fakat buyruk buyruktur, itiraz edemedi,

‘Ham hum şaralop…’ Deyip bir onbin lira verdi.

Sonra karışıp gitti sislerin arasına,

Dede verdi parayı elin fukarasına.

Karlara bata-çıka oralardan ayrıldı,

Çarşıya varmak için yine yola koyuldu.

Birkaç adım ötede rastladı bir çocuğa,

Görür görmez acıdı zavallı yavrucağa.

Yavrucuk ağlıyordu iki göz iki çeşme,

bir şeyler arıyordu karları eşe eşe.

Dedi: ‘Bre çocuğum, sen niçin ağlıyorsun,

Bu kar, bu buz içinde sen neyi arıyorsun? ’

Çocuk dedi: ‘Dedecik, babam para vermişti,

Ekmek alayım diye çarşıya göndermişti.

Bir ellibin liraydı; bir tek ekmek parası,

Birdenbire kayboldu onun onbin lirası.

‘Ham hum şaralop…’ Diye bir ses duymuştum birden,

Para kaybolup gitti bu sözler söylenirken.

Ne oldu? Nerye gitti? Demin avucumdaydı,

Nerden doğdum dünyaya, anam doğurmayaydı.

Babam kamçılar beni, kardeşlerim aç kalır,

Durduğu bir avuçtan para nasıl kaybolur? ’

İsmail İshak Dede çekildi bir köşeye,

İki kılı çıkarıp değdirdi birbirine.

Yine yer-gök gümledi, yine karlar savruldu,

Yine kızgın bir yelin değdiği yer kavruldu.

Rengarenk dumanlara gömüldü yine çevre,

Yine keskin şimşekler hükmetmekte her yere.

Ortaya çıktı Arap yine minare gibi,

Sanki tüm varlığıyla her derde çare gibi.

‘Ferman efendimizin… Her buyruk baş üstüne,

Her arzunuz anında gelecektir yerine…’

İsmail İshak Dede hiç arzu belirtmedi,

Arap ‘ı görür görmez çok beter sinirlendi.

Dedi ki: ‘Ulan Arap, verdin onbin lirayı,

Çocuktan mı alarak yoksa sen o parayı? 

Zira; çocuk ağlıyor, onbin lira kaybolmuş,

Şaşkınlıktan yavrunun aklı perişan olmuş.’

Arap bir nağra attı, yerler gökler sarsıldı,

Dede sesin zorundan kendini yerde buldu.

Yaman kızmıştı Arap, kükreyip duruyordu,

Kükredikçe sokaklar kalkıp oturuyordu.

Dedi ki; ‘Ey insanlar, ne çirkin varlıksınız,

Kusuruma bakmayın; sizler çok alıksınız.

Kıla kim sahip olsa, sanıyor dünya onun,

Artık sonu gelmiyor bitmeyen arzusunun.

‘Arap bana saray yap… Arap bana sofra kur…

Arap düşmanlarımı kıç üstüne oturttur…

Arap bana altın ver; torba-çuval dolusu,

Arap bana köle et tüm ülkeyi, ulusu…’

Aman Tanrı ‘m, sanki var Arap ‘ın hazinesi,

Arap da sizin gibi zavallının birisi. 

‘Acep çocuğun mu? ’ ymuş verdiğim onbin lira

Şimdi gel de laf anlat bu salak ihtiyara.,

Elbette ondan alıp sana verdim parayı,

Mucize ülkesi mi sanmıştın bu dünyayı? 

Hakkın olmayan arzun eğer gerçekleştiyse; 

Ancak gerçekleşmiştir birinden eksildiyse.

Onun için kalkıp da boş yere dilemeyin,

Dünyanın dengesi var, dengeyi ellemeyin.

Ben çok yıldım. Çok bıktım. Artık kıl-mıl tanımam,

Sizin gibi puştlara artık kul-mul olamam.

Artık Arap ‘tan paso, tek vurup çift sıçrayın,

Havadan gelen şeyi tamah edip almayın.

Bir dileğe bir saray, sanki kampanya açtık,

Sanki saray sebildir, nereden bulacaktık? 

Arap kavat mıdır ki; size karı-kız bulsun? 

Doymayan gözünüzü kara toprak doyursun.’

Sözünü bitirince Arap birden fısladı,

Sönen bir balon gibi küçülerek ufaldı.

İsmail İshak Dede baktı  minik adama,

Dedi: ‘Buna güvenen şirk koşar Allah ‘ına.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

ARAP isimli Şiirsel Gülmeceler ''inden > 21-32/100)', '- 1 - Kapı çalındığında gecenin yarısıydı, Bu saatte gelen kim ve nasıl birisiydi?  İsmail Ağa kalktı, bakındı çevresine, Dönüp bir göz gezd...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":279,"source_url":"https://www.antoloji.com/arap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git', 'git-volkan-yoruc-4dbni', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umursanmayan hayallerimle yalnız bırak beni

Uzaklarda kal öylece

Hatta bakma bana

Alışmışım zaten kırgınlığa

Git

Ardına bakmadan yalan düşlerine sarılırcasına

Benim sevdam bana yeter misali

Yalan gönüller sofrasına kurul

Sana yol verdim

Serbestsin her daim bu yaşam yokuşlarında

İlerde belki yollarımız kesişecek

Belki gözlerimiz yine çakışacak

Yine bana tutunmak isteyeceksin

Yüreğimi almak isteyeceksin

Ama geç olacak

Ben de gitmiş olacağım

Ve geri dönmemecesine sana bakmamacasına

Seni silinmiş bir hayal olarak hatırlayacağım

Git

Geri dönmek nasip olmasın

Beni umursamazken buralarda

Yeni sevdalara asıl bırakmamacasına

Sana benden fayda gelmez artık

Ben ki kırık gönüller sofrasında yerimi almışım

Yüreğime çizikler atmışım

Çentik çentik olmuşum

Git

Gidebildiğin en uzak düşlere git

Bir kabus olmuşun benim hülyalarımda

Korkar olmuşum senden

Var git artık

Beni bırak düştüğüm bu yollarda

Böylesi helalmiş bana

Sen harammışın sevdama', 'Umursanmayan hayallerimle yalnız bırak beni Uzaklarda kal öylece Hatta bakma bana Alışmışım zaten kırgınlığa Git Ardına bakmadan yalan düşle...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/git-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pandora', 'pandora-gizem-bilgin-icu70', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tut beni… elim avucum kan! 

Kıçına tekmeyi basmadan bu korkuya

Bu türküde bitmeyecek

Bu acı da…

Gitme! 

Uyuma! 

İçimdeki tüm ölü hücreler adına

Seni bana yazmalılar bir çivi yazısıyla

Tabletleri bin yıl sonra çıkarılmalı bu acı coğrafyada! 

ÖLÜM İSE KISKIS GÜLMELİ PANDORA!', 'Tut beni… elim avucum kan!  Kıçına tekmeyi basmadan bu korkuya Bu türküde bitmeyecek Bu acı da… Gitme!  Uyuma!  İçimdeki tüm ölü hücreler ad...', ARRAY['Türk Edebiyatı','Şiir','Gizem Bilgin']::text[], 8.5, '{"poet":"Gizem Bilgin","poet_slug":"gizem-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/pandora-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmalanan Papatya...', 'yagmalanan-papatya-emirhan-bala-pk90l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin mor''unda, 

Garip ve mahzun yüz, 

Bakışları buğulu ve derin.... 

Dürtüyor beni ruhumda ki patlamalar, 

Sana kadar…

Hep yüreğimi yağmalayanlar... 

duygularımı süpürdüler,

Ve yemin ettim be güzelim, 

Ne toz olacak, 

Nede yozlaşacak duygularım.. 

Ve bilmelisin ki, 

Sensiz Papatya''nın, 

Yaprakları soluk,

Sarısı sarı olmayacak, 

Yokluğundaki çıldırtan hüzün, 

Çökecek yağmalanan papatyamın üstüne...', 'Gecenin mor''unda,  Garip ve mahzun yüz,  Bakışları buğulu ve derin....  Dürtüyor beni ruhumda ki patlamalar,  Sana kadar… Hep yüreğimi yağma...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yagmalanan-papatya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
