INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Hayellerime idam**', 'hayellerime-idam-ercan-urcar-l2cwf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İdam sehpasını kurdum, artık hayallerimle,

Çekeceğim ip''ini bir seher vaktinde,

İteceğim sehpayı ayaklarının altından ellerimle,

Asacağım hayallerimi bir seher vaktinde,

Can çekişecek kederlerim, dertlerim ip ucunda,

Çırpınacak gözümün önünde,yavaşça ölecek,

Sanki kurtarbeni dercesine çırpınacak,

İşte o zaman hayallerimi İDAM edeceğim..', 'İdam sehpasını kurdum, artık hayallerimle, Çekeceğim ip''ini bir seher vaktinde, İteceğim sehpayı ayaklarının altından ellerimle, Asacağım ha...', ARRAY['Türk Edebiyatı','Şiir','Ercan Urçar']::text[], 8.5, '{"poet":"Ercan Urçar","poet_slug":"ercan-urcar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayellerime-idam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bodrum’da Bir Yalnız Martı Yaşıyor (1)', 'bodrum-da-bir-yalniz-marti-yasiyor-1-murat-nail-guney-gr9ho', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sayfalara sığmıyor yalnızlığımın öyküsü,

Kalemler bitiveriyor yazarken.

Dünyanın bütün tuvallerini kullansam,

Resimler de aciz kalıyor anlatmaya.

Hani biliyor musun,

Tanrı kadar yalnızım diyeceğim,

Günah olmasa...

Ben doğuştan böyle değildim be gülüm,

Rahmetli anacığım anlatırdı; 

İlk gözümü açtığımda dünyaya

Ağlatmak için ne tokatlar atmışlar

Bir yerlerime, ağlamamışım...

Yani diyorum ki; doğuştan sevdalı imiş yüreğim,

Bilmezmiş sevdanın acı çekmek olduğunu o anda...

İşte böyle dost! 

Ne uzun yıllar geçti aradan,

Ne sevgiler otağ kurdu gönül bağlarımıza,

Ne vefasızlara kurban ettik en masum düşlerimizi,

Ne kuytu köşelere kaçtık, kimse bilmesin diye

Gözlerimiz dolduğunda..

Az mı öğütüldü dostluk umutlarımız

İhanet değirmenlerinde.

Az mı yağmalandı dünyalıklarımız,

Az mı sabahladım sevgili yalnızlığımla,

Sahildeki kumların üzerinde...

Artık küsmüyorum kaderime,

Seni elimden aldı diye.

Allah’ım böyle uygun gördüyse; 

İtirazsız kabulümdür...

Son bir arzum var sadece Yaradan’dan; 

Bodrum’da Bir YALNIZ MARTI olarak 

Yaratsın beni,

Yeniden doğuş varsa günün birinde...

Murat nail güney

07/11/2004 BODRUM', 'Sayfalara sığmıyor yalnızlığımın öyküsü, Kalemler bitiveriyor yazarken. Dünyanın bütün tuvallerini kullansam, Resimler de aciz kalıyor anlat...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bodrum-da-bir-yalniz-marti-yasiyor-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bodrum’da Bir Yalnız Martı Yaşıyor (2)', 'bodrum-da-bir-yalniz-marti-yasiyor-2-murat-nail-guney-uw7cs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerin ufkumdan kaybolmadan gel,

Seven yüreğimden, hasret taşıyor.

Yürek bu,sev diyor, mantığım unut,

Bu çelişkilerle aklım şaşıyor...

Sevgiyle yaşanan zamanlar güzel,

Küçük bir an bile, bir ömre bedel,

İkinci baharım tükenmeden gel,

Yine güneş mor dağlardan aşıyor...

Bu aşkımız bir gün masal olacak,

İçime gecenin hüznü dolacak,

Koklamadan tomurcuğum solacak,

Sevdiğim nerelerde dolaşıyor...

Yaşadığım şehrin her köşesinde,

Bin-bir hüzün gizli her neş-esinde

Kanayan güllerde, bülbül sesinde

Figanım yıldızlara ulaşıyor...

Deli dolu yaşıyorum bu ara,

Gözlerimi küs ettim uykulara,

Hayat benzemez mi bazen kumara,

Mutluluk elden ele dolaşıyor...

Sanma unuttum gidip uzaklara,

Telefonunu aç, ayda bir ara,

Gözleri dalmış da engin sulara,

Bodrum’da BİR YALNIZ MARTI yaşıyor...

Zaman kötü iltifat yok dostlara,

Kaybolup giderler, düşersen dara,

Ne çare, gelmez ki senle mezara,

Vefasızlık sana da bulaşıyor...

Muradım, hatırı gönülü kırmaz,

İstenmeyen yerde bağlasan durmaz,

Gökyüzünde bile, yalnız uçulmaz

Bodrum’da BİR YALNIZ MARTI yaşıyor...

Şarkılar anlatır hep ayrılığı,

Sönmeden gel artık, gönül ışığı,

Ben mi istedim de bu ayrılığı,

İki laf etmeden, sabrın taşıyor...

Her akşam giderim sahile erken,

İçin yanmadı mı veda ederken,

Bir buse vermiştin çıkıp giderken,

Bodrum’da BİR YALNIZ MARTI yaşıyor...

Murat nail güney.

08/11/2004 BODRUM', 'Gözlerin ufkumdan kaybolmadan gel, Seven yüreğimden, hasret taşıyor. Yürek bu,sev diyor, mantığım unut, Bu çelişkilerle aklım şaşıyor... Sev...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/bodrum-da-bir-yalniz-marti-yasiyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni anlatmadan...', 'seni-anlatmadan-emirhan-bala-93vc1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Açamıyorum ağızımı sessizim, 

Gözümde kesmiyor ya, 

Bırakıp gitmeye.

Ne sitemler üzer,

Nede ironik göndermeler beni, 

Yüreğimse hazır sırat''ı geçmeye...

Açamıyorum ağızımı sessizim, 

Lakin kalemim keskin bıçak,

Ne yazar diyerek yazamıyorum.

Boş veremiyorum sensizliğe,

Gözümde hiç kesmiyor

Ağıtlarla ağlamaya...

Yüreğim sırat''ı geçecek,

Nazire yaparcasına,

Sevda ateistlerine...

İşte o zaman,

Ağızımı açacağım yırtarcasına,

Dudaklarımdan dökülecek,

Kalemimdeki keskinlik...

Gözüm bir kesecek ki,

Ecel saatinde Azrail''e inat,

Sırat''dan geri döneceğim,

Sana...Seni anlatmadan,

Ölmeyeceğim...', 'Açamıyorum ağızımı sessizim,  Gözümde kesmiyor ya,  Bırakıp gitmeye. Ne sitemler üzer, Nede ironik göndermeler beni,  Yüreğimse hazır sırat''...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seni-anlatmadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan oluyorduk', 'i-nsan-oluyorduk-gencay-coskun-hji62', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karlı bir dağdı

Zirvelerinde ölüm beklerdi 

Soluk soluğa kalsam da 

Çıkmaktan usanmazdım

Ne yana baksam hep sen vardın 

Kan ter içinde kalırdım 

Geçit vermeyen kayalıklarında 

Gün bu kadar güzel gözükürdü

Bembeyaz zirvende 

Eteklerinde bir yeşillik 

Karınca sürüsü şehirdi 

O kadar uzaktan beni ürkütemezdi

Kötülükleri bana uzanamazdı 

Morarsa da ellerim 

Ecelim sendin 

Yolum sendin

Senden başka anlamım 

Senden başka  sığınağım 

Umutlarımdan başka 

Sancağım yoktu

Yolsa bizimse 

Yürümek lazımdı

Yorulmak lazımdı

Uğruna yoruldukça 

İnandığımız gökyüzü

Bizim oluyordu 

Bizim oluyordu 

Zamanın sayılmadığı diyarlar 

Bizim oluyordu 

Hiç olmadığı kadar insanlık 

İnsan oluyorduk 

Bugüne kadar hiç olmadığımız kadar', 'Karlı bir dağdı Zirvelerinde ölüm beklerdi  Soluk soluğa kalsam da  Çıkmaktan usanmazdım Ne yana baksam hep sen vardın  Kan ter içinde kalır...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/insan-oluyorduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaş', 'savas-mustafa-kenan-afnvt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ve vurulduk

Ve ezildik

Ve katledildik

Kurşun ağır bir metal parçasıydı

Ve her can

Bir kuşuna saplıydı

Hayat isli ve karanlık bir cam parçası

Ölüm askerin su dolu matarasında

Saklıydı', 'Ve vurulduk Ve ezildik Ve katledildik Kurşun ağır bir metal parçasıydı Ve her can Bir kuşuna saplıydı Hayat isli ve karanlık bir cam parçası...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kenan']::text[], 8.5, '{"poet":"Mustafa Kenan","poet_slug":"mustafa-kenan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/savas-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-mustafa-kenan-1ypo0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerin geldi yine gözlerime

Gözlerim karardı sonra

Sen yoksun

Peki gözlerin nerde', 'Gözlerin geldi yine gözlerime Gözlerim karardı sonra Sen yoksun Peki gözlerin nerde...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kenan']::text[], 8.5, '{"poet":"Mustafa Kenan","poet_slug":"mustafa-kenan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gozlerin-125-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dans eden Papatyalar...', 'dans-eden-papatyalar-emirhan-bala-e55z3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ah ne özlemişim ya, 

Yüreğinin sesini, 

Şimşekler mi çaktı ne, sana, 

Türküler çalıyor sanki, satırlarında, 

Papatyalar dans ediyor odamda, 

Seni getirdiler buralara sessizce... 

Aklım ziyan olsa da bana ne, 

Ay ışığında pembe dudakların, 

Kıpır kıpır şarkılar eşliğinde, 

Papatyalarsa titreyen elimde, 

Kıpırdayamıyorum sanki, 

Tüm yıldızlar çöktüler üstüme.... 

Seni seyrediyorum, 

Ateşle suyun birleştiği yerde... 

Boğuk boğuk konuşamıyorum, 

Seni hayal ederken bile.. 

Yazamıyorum, bekliyorum bitsin dansın.. 

Bekliyorum, tükensin özlemim, 

Bekliyorum, dirilsin yüreğim, 

Ya sen! 

Sen ne bekliyorsun...?', 'Ah ne özlemişim ya,  Yüreğinin sesini,  Şimşekler mi çaktı ne, sana,  Türküler çalıyor sanki, satırlarında,  Papatyalar dans ediyor odamda, ...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dans-eden-papatyalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-mustafa-kenan-llxvi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Agaç urgana dolandı

Urgan boynuma

Ölüm bi tabure sesi

Hayat boynumuzda kalandı.', 'Agaç urgana dolandı Urgan boynuma Ölüm bi tabure sesi Hayat boynumuzda kalandı....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kenan']::text[], 8.5, '{"poet":"Mustafa Kenan","poet_slug":"mustafa-kenan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olum-147-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalım', 'sevdalim-murat-nail-guney-lh7o3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine kıştan çıkıp yaza eriştik,

Yine şu gönlümde dert tutam-tutam.

Sevdalım bak yine dillere düştük,

İçip sarhoş olup seni unutsam...

Esmeyin seherin ılık yelleri,

Akmayın gönlümün coşkun selleri,

Susmadan şu dertli aşık dilleri,

Varıp gurbet ele seni unutsam...

Harmanda savrulan taneler gibi,

Yüreğimde onmaz yaralar gibi,

Gönlüme mutluluk müjdeler gibi,

Beyaz ellerinde gül tutam-tutam...

Solsa da ömrümün bahçesi bağı,

Gezsem diyar-diyar ovayı, dağı,

Yeniden doğsam da baştan aşağı,

Sevdalı gözleri nasıl unutsam...

Bulamadım sana ne benzer, ne eş,

Aşkın gözlerimde batmayan güneş,

Ne yağmurlar yağsa sönmez bu ateş,

Kül ol sen üstünde sımsıcak tutan...

m.n.g.', 'Yine kıştan çıkıp yaza eriştik, Yine şu gönlümde dert tutam-tutam. Sevdalım bak yine dillere düştük, İçip sarhoş olup seni unutsam... Esmeyi...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevdalim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatlı', 'tatli-mustafa-kenan-8qnne', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölüm kısık bir nefes sesi

Hayat tatlı bir agaç gölgesidir.', 'Ölüm kısık bir nefes sesi Hayat tatlı bir agaç gölgesidir....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kenan']::text[], 8.5, '{"poet":"Mustafa Kenan","poet_slug":"mustafa-kenan","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/tatli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı bir ateşten gözleri vardı', 'sari-bir-atesten-gozleri-vardi-gencay-coskun-fvb32', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sarı bir ateşten gözleri vardı 

Yıllar geçse hiç değişmezdi 

Ne zaman görsem 

Yüreğim külleri eşelenirdi 

Anlatamadıklarımdan bir dağ 

Biriktirdim yüreğimde 

Ne zaman aç sığmadı 

Kendi gökyüzüme 

Acımıydı yaşadıklarım 

Zamansızlık mıydı yanıldıklarım

Sadece hüzün müydü yalnızlık

Yoksa bazen 

Adam gibi dost mu oluyordu 

Sarı bir ateşten gözleri vardı 

Yıllar geçse hiç değişmezdi 

Ciğerim parça parça olurdu 

Ne kadar su içsem 

Çiçek falan çıkmazdı içimde

Ne kadar film seyretsem 

Hep başkaları olurdum 

Ne zaman ben olsam 

Sen olmazdın 

Sarı bir ateşten gözleri çıkardı karşıma 

Ansızın 

Tam yaramı sarmışken 

Bakışları geleceğimi soğuturdu 

Bir yerde treni kaçırmıştık 

Mektup tazeliğini özler olmuştum 

Yeni sayısal mektupların karşısında 

Koynundan saklayacak mesajlarım 

Olmayacaktı 

Yüreklerin sınırlarında 

Gözlerin gördüğü

Aklın unutmadığı mesajlarım olacaktı 

O hatırlanabildiği kadar 

Her yerde yalandan 

Zaman 

Suçlu olacaktı 

Asıl suçluya

Kader diyemeyecektim

İçten içe 

Kendimi yiyecektim. 

Sarı bir ateşten gözleri vardı 

Beklemek bile anlamsızdı 

Mor bir gülle gelecekti 

Gelecek denilen kayık 

İki gümüş para ile 

Gidilecek bir yoldu 

Bu yol hep yalan olacaktı 

Sarı bir ateşten gözleri vardı 

Bu gözleri özleyecektim 

Yoksa kim yakarak 

Isıtacaktı içimi 

Dost yalnızlıklarda 

Yalan bir avuntum olacaktı 

Adını gökyüzüne yıldızlarla yazdığım 

Umutlarım olacaktı 

ve birde daha sadece başlığında olduğum 

Bir hikayem olacaktı 

Sarı bir ateşten gözleri vardı 

Yıllar geçse hiç değişmezdi 

Değişen hep 

Resimlerdeki yüzlerdi....', 'Sarı bir ateşten gözleri vardı  Yıllar geçse hiç değişmezdi  Ne zaman görsem  Yüreğim külleri eşelenirdi  Anlatamadıklarımdan bir dağ  Birik...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/sari-bir-atesten-gozleri-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavgam var...', 'kavgam-var-emirhan-bala-i2469', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayrılıkla kavgam var bu gece, 

Kıskançlık nöbeti, 

Derin soluklar, 

Uzun adımlar, 

Çöl kavruğu gibi bedenimde...

Ayrılıkla kavgam var bu gece,

Sabrım gürbüz gürbüz, 

Ne ucuz laf yapar, 

Nede talan eder sevdamı, 

Dudaklarım... 

Ayrılıkla kavgam var bu gece, 

Benim gözüm sana düşkün, 

Ya seninki güzelim? 

Kim bilir neredesin? 

Kimin menzilindesin ruhumun Süsü? 

Benim,

Ayrılıkla kavgam var bu gece...', 'Ayrılıkla kavgam var bu gece,  Kıskançlık nöbeti,  Derin soluklar,  Uzun adımlar,  Çöl kavruğu gibi bedenimde... Ayrılıkla kavgam var bu gec...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kavgam-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzerimde Toprak Olsan Ne Çıkar', 'uzerimde-toprak-olsan-ne-cikar-murat-nail-guney-kzgf5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her şeyi bitirdim gönül bu gece,

Kolun kanadımı kırsan ne çıkar.

Ruhumu kaybettim, bomboş bedenim,

Sevdan ateş olsa sarsan ne çıkar...

Koparıp attın sen sevgi dalımı,

Çabuk bitirdin bu aşk masalını,

Değiştirmek için kader yolunu,

Yoluma kul köle olsan ne çıkar...

Herkes gibi sen de vur eksik kalma,

Günahımı al da ahımı alma,

Gurbette ölürsem kabrime gelme,

Üzerimde toprak olsan ne çıkar...

Kiminin kaderi değişmez asla,

Kimi hayatını geçirir yasla,

Sen kalbindeki bu boş ihtirasla,

Katıla-katıla gülsen ne çıkar...

Soldurdun gönülde açan son gülü,

Seni de bırakmaz feleğin eli,

Sen beni bırakıp gittin gideli,

Saçını başını yolsan ne çıkar...

m.n.g.', 'Her şeyi bitirdim gönül bu gece, Kolun kanadımı kırsan ne çıkar. Ruhumu kaybettim, bomboş bedenim, Sevdan ateş olsa sarsan ne çıkar... Kopar...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/uzerimde-toprak-olsan-ne-cikar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim Dünya', 'zalim-dunya-murat-nail-guney-c6ptm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok görerek mutluluğu, kul ettin çok kula kulu,

Sinemize gurbet pulu yapıştırdın hain dünya.

Sana sitem neye yarar, feryadımız ömre zarar,

Kılmadım bir yerde karar, sürükleyip durdun dünya...

Ayrı koydun vatanımdan, hem dost hem de kardeşimden,

Ağrılar dinmez başımdan, taştan taşa vurdun dünya.

Hasret yakar tende canı, dert verirsin derman hani,

Deli edersin insanı, zalim oğlu zalim dünya...

Dünya dünya zalim dünya, zehir oldu balım dünya,

Beni canımdan ayırdın, yakanda iki elim dünya.

Boşa geçirdin ömrümü, soldurdun gonca gülümü,

Sustu artık şarkılarım, kırık gönül telim dünya...', 'Çok görerek mutluluğu, kul ettin çok kula kulu, Sinemize gurbet pulu yapıştırdın hain dünya. Sana sitem neye yarar, feryadımız ömre zarar, K...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zalim-dunya-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kravatlar', 'kravatlar-ebru-yucesoy-3vrpx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rengarenk,cıvıl cıvıl kravatlar

Kimi çizgili, kimi çiçekli

Hepsi neşeli 

Tıpkı onları taktığın günler gibi

Oysa şimdi...

Sanki pürtüklenmiş yüzeyleri 

Dokunmak istedim bugün

Kanattı ellerimi...', 'Rengarenk,cıvıl cıvıl kravatlar Kimi çizgili, kimi çiçekli Hepsi neşeli  Tıpkı onları taktığın günler gibi Oysa şimdi... Sanki pürtüklenmiş ...', ARRAY['Türk Edebiyatı','Şiir','Ebru Yücesoy']::text[], 8.5, '{"poet":"Ebru Yücesoy","poet_slug":"ebru-yucesoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kravatlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keskin Testere', 'keskin-testere-ebru-yucesoy-v2v3s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yan yatar bir süre sonra 

İçindeki keskin testere

Artık yok sanırsın.

Hayat devam eder

Ve fakat hayalindeki anılar

Durmaz ki durduğu yerde 

Çıkıverir yüzeye

İşte o an gizlenen testere

Birden doğrulup yerinden 

Bütün organlarını kıtır kıtır keser!', 'Yan yatar bir süre sonra  İçindeki keskin testere Artık yok sanırsın. Hayat devam eder Ve fakat hayalindeki anılar Durmaz ki durduğu yerde  ...', ARRAY['Türk Edebiyatı','Şiir','Ebru Yücesoy']::text[], 8.5, '{"poet":"Ebru Yücesoy","poet_slug":"ebru-yucesoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/keskin-testere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-barbaros-emre-wsryt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben yine yalnızım

Saatler ilerlemiş

Zaman bile durmuyor yerinde

Ben nasıl durayım

Bir yok sevdadan diğerine gitmekle geçiyor ömrüm

Gel götür beni yalnızlıktan senin bol olduğun bir mevsime

Bol bol senle dolsun içim

Sana doyayım 

Yokluğunda anladım değerini 

Gel gel ne olur götür beni buralardan 

Seni senle yaşıyabileceğim diyarlara

Gel gelde bitsin bu yalnızlık', 'Ben yine yalnızım Saatler ilerlemiş Zaman bile durmuyor yerinde Ben nasıl durayım Bir yok sevdadan diğerine gitmekle geçiyor ömrüm Gel götür...', ARRAY['Türk Edebiyatı','Şiir','Barbaros Emre']::text[], 8.5, '{"poet":"Barbaros Emre","poet_slug":"barbaros-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-137-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim İnsanları Zalim Olsada', 'sevdim-i-nsanlari-zalim-olsada-murat-nail-guney-8bgi4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne yapsam bitmiyor dertlerim tanrım,

Oysa ben kendi halimde bir canım,

Kör olsun gözlerim varsa yalanım,

Kimseye zararım olmadı benim...

Doğruyu savundum suç olsa bile,

Gurbette yaşarım güç olsa bile,

Şu gönlüm sevgiye aç olsa bile,

Yaşamadım diye isyan etmedim...

Sevdim insanları zalim olsa da,

En yakın bildiğim hain olsa da,

Güldüm olanlara içim yansa da,

Ağladım kimseye belli etmedim...

Sonbaharım geldi gönlüm duruldu,

Kırk baharım geçti beden yoruldu,

Dünyanın tüm derdi benden soruldu,

Başımı alıp ta çekip gitmedim...

Ne çıkar kaderim zalim olsa da,

Gurbetin yolları yarim olsa da,

Mutluk olmak hep hayalim olsa da,

Bıkıp usanmadım hiç pes etmedim...

Tanrım anlamadı beni kulların,

Kapandı önümde bütün yollarım,

Zamansız soldu bak gonca güllerim,

Yaralandı yürek belli etmedim...', 'Ne yapsam bitmiyor dertlerim tanrım, Oysa ben kendi halimde bir canım, Kör olsun gözlerim varsa yalanım, Kimseye zararım olmadı benim... Doğ...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevdim-insanlari-zalim-olsada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudunu Yıllar Alıp Gidecek', 'umudunu-yillar-alip-gidecek-murat-nail-guney-9y5pu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim yazmadığım bu kader için,

Beni suçlamaya ne hakkın var ki,

Saçına akları ben mi düşürdüm,

Aynalara küsmek neye yarar ki...

Sanki sevmedim mi ben senin kadar,

Bu çileler benim kaderimde var,

Sende aramızdaki dağlar kadar,

Aşılmaz olsan da neye yarar ki...

Umudunu yıllar alıp gidecek,

Seni de sevdiklerin terk edecek,

Gözlerinde hayalimi görerek,

Hülyalara dalsan neye yarar ki...

Şimdi körfezdeki uçan kuşlara,

Adımızı kazdığım ağaçlara,

Yalnızlıktan yosun tutan taşlara,

Oturup ağlasan neye yarar ki...

Dünyada ikimiz, bir de aşk vardı,

Hani aşkımız mahşere kadardı,

Korkarım,kavuşmak mahşere kaldı,

Hatanı anlasan neye yarar ki...', 'Benim yazmadığım bu kader için, Beni suçlamaya ne hakkın var ki, Saçına akları ben mi düşürdüm, Aynalara küsmek neye yarar ki... Sanki sevme...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/umudunu-yillar-alip-gidecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resimlerinden Sevmek', 'resimlerinden-sevmek-ebru-yucesoy-6hf29', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Resimlerine dokundum parmakuçlarımla 

Usulca...

Gözlerinde yine sevgiyi gördüm

Birden ısınıverdi resim

Sıcaklığını hissettim

Sana baktım dakikalarca 

Yine gülümsedim...

Ve bu gün, bu akşam 

Seni resimlerinden sevmeyi öğrendim...', 'Resimlerine dokundum parmakuçlarımla  Usulca... Gözlerinde yine sevgiyi gördüm Birden ısınıverdi resim Sıcaklığını hissettim Sana baktım dak...', ARRAY['Türk Edebiyatı','Şiir','Ebru Yücesoy']::text[], 8.5, '{"poet":"Ebru Yücesoy","poet_slug":"ebru-yucesoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/resimlerinden-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmem Geceleri', 'sevmem-geceleri-asik-bahari-9euuc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ben mi böyleyim acaba geceler

Hüzünlü şarkıların tek dinleyicisi

Göz yaşlarım sel olmuş yağmurlara

Dertlerim şair olmuş geceleri

Özlem duyar olmuşum sabahlara

Mızrap olmuş yüreğime geceleri

Ulaşamaz olmuş gözlerim martılara

İsyan eder olmuşum kara bahtıma

Şiirler yazmışım aşkıma..geceleri

Perçinlemek istedim yüreğimi gündüzlere

Hayatımdan söküp atmak istedim bilmeceleri

Katılmak istedim candan sevenlere

Yolumu kaybettirdi kış geceleri

Kendimi anlatmak istedim beni bilmeyenlere

Beni kul etti gönülden sevmeyenlere

İşte bundan dolayı hiç sevmem geceleri', 'Bir ben mi böyleyim acaba geceler Hüzünlü şarkıların tek dinleyicisi Göz yaşlarım sel olmuş yağmurlara Dertlerim şair olmuş geceleri Özlem d...', ARRAY['Türk Edebiyatı','Şiir','Aşık Bahari']::text[], 8.5, '{"poet":"Aşık Bahari","poet_slug":"asik-bahari","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevmem-geceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni bu topraklarda sevdim...', 'seni-bu-topraklarda-sevdim-emirhan-bala-12yft', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beşikler salıncaklar, hamaklar, 

Dünkü çocuk sayılırım, 

Ben buyum, 

Ne Utanırım, 

Nede utandırırım, 

El gün, el aleme karşı... 

Üşüşürüm kesat duyguların başına, 

Güllerin katmer katmer yaprakları, 

Şairlerin, alimlerin başına, 

Bense kalmışım tek başıma, 

Asırlardır yalnızlar misali.... 

Ne korkunç mancınıklar parçaladılar 

Nede seher saati uykularımı, 

Top sesleri... 

Haraçladılar duygularımı, inançlarımı, 

Sallamıyorum artık, 

Ne İskender’i, ne şah''ı, nede sultanı, 

Gidenlerin izleri peşinde, 

Ya benim neyim ha neyim? 

Bilir misin nasıl severim, 

Ney''in üflediği büyülü sesini, 

Udun davudi tellerini, 

Dayanıyorum, direniyorum, 

Sevdamı yok edenlere, 

Leyla-Mecnun, Tahir-Zühre misali.. 

Bin nice sevdayı yaşayan, 

Anadolumu, 

Bilir misiniz nasıl severim.... 

Taş taş üstüne kalmasa, 

Sarsa da örümcekler ağlarını, 

Nice sevda dolu yürekler... 

Etten duvar örerler, 

Ölüme gülerek giderken, 

Ve sen sevdalım, 

Üzülme, yıkılma, 

Bakma öyle mahzun mahzun, 

Seni bu topraklarda sevdim, 

Bu topraklar yoksa, 

Sende yoksun.....', 'Beşikler salıncaklar, hamaklar,  Dünkü çocuk sayılırım,  Ben buyum,  Ne Utanırım,  Nede utandırırım,  El gün, el aleme karşı...  Üşüşürüm ke...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/seni-bu-topraklarda-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarılsam Boynuna', 'sarilsam-boynuna-murat-nail-guney-fmz4y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerinden okunuyor sevdiğim,

Yine mi aklına geldi o akşam.

Dudakların titrer yine ürkekçe,

Gözlerin dolacak yüzüne baksam...

Anlatılmaz nice duygular ile,

Unutulmaz güzel anılar ile,

Vefasız, boş kalan şu kollar ile,

Sarılsan boynuma içimi yaksan...

Sevgi buketini uzattım sana,

Şu deli gönlümü kul ettim sana,

Aşılmaz dağları yol ettim sana,

Ne çıkar sonunda el olacaksan...

Anlatılmaz nice duygular ile,

Unutulmaz güzel anılar ile,

Vefasız, boş kalan şu kollar ile,

Sarılsan boynuma içimi yaksan...

Murat Nail Güney', 'Gözlerinden okunuyor sevdiğim, Yine mi aklına geldi o akşam. Dudakların titrer yine ürkekçe, Gözlerin dolacak yüzüne baksam... Anlatılmaz ni...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sarilsam-boynuna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sana Son Sözüm,Son Vedam Artık', 'bu-sana-son-sozum-son-vedam-artik-murat-nail-guney-8o3zh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni çok incittin gidiyorum bak,

Sahte sevdalardan, dostlardan uzak,

Bu hayat sana da kuracak tuzak,

Yaptığından pişman olsan ne çıkar...

Bu sana son sözüm, son vedam yazık,

Adımı bir daha duymazsın artık,

Acıyorum sana haline bakıp,

Gittiğin yollardan gelsen ne çıkar...

Mutluluk kuşunu azat ettim ben,

Tükendim derdinle artık bittim ben,

Sanma ki hakkımı helal ettim ben,

Dünyaya hükümdar olsan ne çıkar...

Seni bekliyorum hak divanında,

Uzatma arayı çık gel sonunda,

Hesap günü mahşer kurulduğunda,

Önümde secdeye dursan ne çıkar...

murat nail güney', 'Beni çok incittin gidiyorum bak, Sahte sevdalardan, dostlardan uzak, Bu hayat sana da kuracak tuzak, Yaptığından pişman olsan ne çıkar... Bu...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-sana-son-sozum-son-vedam-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir suç üstü, bir kelepçe...', 'bir-suc-ustu-bir-kelepce-emirhan-bala-3mrk7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Buralardan sana, 

nağmeler, yanık türküler, 

yarama bastığım kurumuş papatyalar, 

giz dolu gecelerimin, 

tek gerçeği...sen... 

kurtarılmayı bekleyen, 

çocuksu yüreğimle, 

umutlarımı bırakıyorum sana... 

ve seninle, 

aldatıyorum beklentilerimi...

Buralardan sana, 

geleceğin ipuçlarını sunuyorum, 

vasiyetim bir nakarat, 

ne üzerime çevrili soğuk namlular, 

nede söğüt gölgesi mezarlar, 

korkutur beni... 

üşüştü üzerime, acılarım leş gibi, 

Karanlığın bağrında göçebeyim, 

külümden kan damlasa da, 

türküler öpüşür duygularımla...

Bir tutam sevgi için tutuştum, 

yıllarca sana kadar....

Buralardan sana, 

bir suçüstü, 

birde kelepçe, 

kes cezamı, 

bitsin bu işkence...', 'Buralardan sana,  nağmeler, yanık türküler,  yarama bastığım kurumuş papatyalar,  giz dolu gecelerimin,  tek gerçeği...sen...  kurtarılmayı ...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-suc-ustu-bir-kelepce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adımız Kalacak Yeryüzünde,Bir de....', 'bir-adimiz-kalacak-yeryuzunde-bir-de-murat-nail-guney-bhn0x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen sonsuz gökyüzüne bakarak gezerken,

Ayaklarımızın altında ezilen kır çiçeklerini görmeyiz bile

Oysa, onlar gökyüzünden daha güzeldir.

Güneşin kızıllığı vurunca sulara, ateş böceklerinin büyüsü bozulur

Lakin gene gece olacak ve büyü sürecektir sonsuza dek.

Beyaz karlarda kardelenler açarken

İçimizdeki çiçekler solmuş olacak.

Zaman alıp götürecek benliğimizi

Gecenin hüznüyle dalgalanan bulutlara.

Yıktığımız gönül saraylarının kalıntılarında

Arayacağız yitip giden gençliğimizi.

Bir adımız kalacak o ağacın gölgesinde,

Bir de kayalara oyduğumuz o kalp.

Düşen yapraklar örtecek hatıralarımızı

Güneşle yanıp, rüzgarla savrulacağız

Çığlık çığlığa uçarken kırlangıçlar

Kendi feryatlarımızı duyacağız derinden 

Nihayet biterken upuzun gece

Tıpkı boşa geçen ömrümüz

Yaşayamadığımız gençliğimiz

Doyamadığımız sevgimiz gibi; 

İçimiz buruk o rüyadan uyanacağız...

murat nail güney', 'Bazen sonsuz gökyüzüne bakarak gezerken, Ayaklarımızın altında ezilen kır çiçeklerini görmeyiz bile Oysa, onlar gökyüzünden daha güzeldir. G...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-adimiz-kalacak-yeryuzunde-bir-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül''üm...', 'eylul-um-emirhan-bala-i0rua', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Değişmem ya sarı yapraklarını, 

Eylül''ümün, 

Temmuz''un serin sularına, 

Baharın rengarenk tarlalarına, 

Nede Aralık’taki şömine keyfine... 

Becerebilirsen eğer,

Savuşturursan hüzünleri, 

İşlemesini bilirsen,

İçindeki kütüğü

Eylül''ümde, 

Dostlukları, 

Sevdaları, 

İşte o zaman yaşıyorsundur, 

Kalan zamanlarda...', 'Değişmem ya sarı yapraklarını,  Eylül''ümün,  Temmuz''un serin sularına,  Baharın rengarenk tarlalarına,  Nede Aralık’taki şömine keyfine...  ...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/eylul-um-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'bildiğim Tek Şey', 'bildigim-tek-sey-sair-cashmere-et3dz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu yolda yürümeyi seçen bendim

Mutlumuyum? 

Belkide mutluyum

Ama bildiğim tek şey ise

Sensiz mutsuzum', 'Bu yolda yürümeyi seçen bendim Mutlumuyum?  Belkide mutluyum Ama bildiğim tek şey ise Sensiz mutsuzum...', ARRAY['Türk Edebiyatı','Şiir','Şair Cashmere']::text[], 8.5, '{"poet":"Şair Cashmere","poet_slug":"sair-cashmere","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bildigim-tek-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatım Boyunca', 'hayatim-boyunca-sair-cashmere-mrdbr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Trende karsıma oyuran güzel kızın gözlerine baktığımda

Seni düşünmüyorum

Ama hayatım boyunca o kızın gözlerine bakamam', 'Trende karsıma oyuran güzel kızın gözlerine baktığımda Seni düşünmüyorum Ama hayatım boyunca o kızın gözlerine bakamam...', ARRAY['Türk Edebiyatı','Şiir','Şair Cashmere']::text[], 8.5, '{"poet":"Şair Cashmere","poet_slug":"sair-cashmere","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/hayatim-boyunca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Çiçekleri Severdim Tanrım', 'butun-cicekleri-severdim-tanrim-murat-nail-guney-11edf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bütün dertlerine katlanırdım ben,

Felek,içinde şu hasret olmasa.

Bütün kullarını severdim Tanrım,

İnsanın içinde nefret olmasa...

Bütün acılara dayanırdım ben,

Genç  yaşta yolumuz gurbet olmasa,

Bütün çiçekleri severdim Tanrım,

Koklamaya doyamadan solmasa...

Bir damla gözyaşı çok şey anlatır,

Seven gönül böyle talan olmasa,

Bütün sevenlere kurban olurdum,

Ölümsüz sevdalar yalan olmasa...

Benzese ömrümün her günü kışa,

Şu çileli ömür geçse de boşa,

Korkulanlar bir gün gelirse başa,

Katlanamam asla sevdan olmasa...

m.n.g.', 'Bütün dertlerine katlanırdım ben, Felek,içinde şu hasret olmasa. Bütün kullarını severdim Tanrım, İnsanın içinde nefret olmasa... Bütün acıl...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/butun-cicekleri-severdim-tanrim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trende', 'trende-sair-cashmere-l3i4f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Trende karsıma oyuran güzel kızın gözlerine baktığımda

Seni düşünmüyorum

Ama hayatım boyunca o kızın gözlerine bakamam', 'Trende karsıma oyuran güzel kızın gözlerine baktığımda Seni düşünmüyorum Ama hayatım boyunca o kızın gözlerine bakamam...', ARRAY['Türk Edebiyatı','Şiir','Şair Cashmere']::text[], 8.5, '{"poet":"Şair Cashmere","poet_slug":"sair-cashmere","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/trende-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
