INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdan', 'sevdan-yavuz-agir-7wvk7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gölgen bize uzak gelir.

Sözün bize tuzak gelir.

Ne söyler ne satarsın.

Sevdan bize uzak gelir.

Kahpe felek senden yana.

gün göstermedi ki bana.

Çektiğim acılar bir yana.

Sevdan bize uzak gelir.

      11-11-2004.', 'Gölgen bize uzak gelir. Sözün bize tuzak gelir. Ne söyler ne satarsın. Sevdan bize uzak gelir. Kahpe felek senden yana. gün göstermedi ki ba...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevdan-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Arkadaş', 'uc-arkadas-bekir-mutlu-gokcesu-3ka11', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Buluştuk

Eskisi gibi

Oturduk baş başa

Küçük bir masada...

Ben, senin karşında

Sen, benim karşımda

O, yanımızda...

Biz, hepimiz

Siz, ikiniz 

Herkes burada

Onlar nerede? 

Yürekler genişti ama

Küçüktü masa

Üçümüz anca sığdık

Bir yaşama...

Ne iyi ettik de buluştuk

Eski günlerdeki gibi

Verdik kafa kafaya

Zaten kaç kişi vardık? 

Kaç kişi kaldık ki

Şunun şurasında...

Sahi ne oldu onlara?', 'Buluştuk Eskisi gibi Oturduk baş başa Küçük bir masada... Ben, senin karşında Sen, benim karşımda O, yanımızda... Biz, hepimiz Siz, ikiniz  ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/uc-arkadas-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevişmek Seninle..', 'sevismek-seninle-suheyla-aydogdu-wnoeh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalanlara, yapmacık kahramanlıklara, 

güzel fakat anlamsız laflara 

gerek duyma benimle beraberken

Sevişmek; 

umursuzca pervasızca 

yasaklardan, tabulardan, tüm çirkinliklerden uzak

Sevişirken sevmek.. 

sevişirken aşık olmak..

Dokunmak.. dokunmak..dokunulmak..

Gerçekle düş arasında,

pembe beyaz bulutların ardından 

sonsuz boşluğa dolu dizgin yol almak

İster gün ışığında 

ister gece karanlığında 

bir öpüş bir dokunuş 

bir tutam ılık nefes karşılığında 

arzulamak... arzulamak... arzulanmak

Seninle sevişmek, 

büyülerden tılsımlardan daha kuvvetli olmalı 

bir gülüşün, bir dokunuşun, bir öpüşünle 

anlatmalısın bana kendini...

Konuşma hemde hiç 

Sus.. sus ve anlat 

ellerin gözlerin konuşmalı 

bana bir anda 

sevgiyi,

aşkı, 

sevişmeyi 

seni

vermelisin ki senin olayım.', 'Yalanlara, yapmacık kahramanlıklara,  güzel fakat anlamsız laflara  gerek duyma benimle beraberken Sevişmek;  umursuzca pervasızca  yasaklar...', ARRAY['Türk Edebiyatı','Şiir','Süheyla Aydoğdu']::text[], 8.5, '{"poet":"Süheyla Aydoğdu","poet_slug":"suheyla-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sevismek-seninle-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gün Bayram', 'her-gun-bayram-oguzkan-bolukbasi-juq9u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir çiçekli entarinin albenisinde

Ellerini tuttuğum günler geliyor aklıma

Tuzlu

Köpüklü

Bir deniz kenarının yaz akşamında

Kaç zamanlık hayatın yorgunluğundan çıkmış

Onurlu gözlerinde

Tabiatıyla

Acıkmış duygularımı sende doyuracaktım

Mesele 

Bulunmaz 

Eşi benzeri olmayan sevgiler aramak değildi

Veya uğruna ölmek

Mesele 

Sevmekti

Yalnızca sevmek

Basit

Suyun akışı gibi

Akmak gitmekti

Sevildiğini bilmekti

Sevgide dinlenmek

Söylemediklerini anlıyordum senin

Sözü olmayan bir müziğin

Ruhumda gezinmesi misali

Anlattıklarını anlamak bu sessizliğin

Bizim marifetimizdi

Zemheride sıcaklığında yanardım

Susuzluğumda

Dudaklarımı gözlerine dayar

Kanardım

Bazen

Ya gidersen düşüncesiyle

Bulutlara yaslanıp 

Ağlardım 

Hiç gitmedin

Hiç bitmedin

Yaşadığım tüm zamanlar senin

Geçmiş bile şimdiki zaman

Ben deliyim

Seninle her gün bayram', 'Bir çiçekli entarinin albenisinde Ellerini tuttuğum günler geliyor aklıma Tuzlu Köpüklü Bir deniz kenarının yaz akşamında Kaç zamanlık hayat...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/her-gun-bayram-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-ali-riza-unal-9uy42', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Firkatteyim, gönlümü hicran eden vefasız yardan

Bıkkınım, bezginim her sözünde bir yalan

Kanmam artık sana, harabı aşkı kaldır aradan

Nazarın yad elde, basiretim var didardan', 'Firkatteyim, gönlümü hicran eden vefasız yardan Bıkkınım, bezginim her sözünde bir yalan Kanmam artık sana, harabı aşkı kaldır aradan Nazarı...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ayrilik-203-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karsiliksiz Sevgi', 'karsiliksiz-sevgi-kerim-odabasi-b83bk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar çok sevdigimdın bır zamanlar 

Bir zamanlar canımı varırdım senin için 

Bir zamanlar! ! 

Bir zamanlar ne düşler kurmuştuk senle bır zamanlar 

Ama olmadı sen beni unutun 

Beni unuttuğuna üzülmedim inan 

Düşlerimizi nasıl unutursun nasıl 

Sana bunları kimler unuturdu? ? 

Hiç kimse senin gibi davranmaz derdin 

Simdi ne oldu sana 

Haydı susma bir şeyler söyle 

ne oldu 

Yanların sonu oldu 

Yoksa kelimelerimi yetmiyor? ? ? 

Hiç konuşma daha iyi 

Konuştukça batıyorsun 

Neyse önemi yok Sadece bir şeyi bilmeni isterim 

Ben Seni Sevdiğimi Bil Yeter 

Sen yüzüme bakmak istemesen bile 

Ben resmine bile bakmadan edemem 

Neyse senin sevgin bukadarmiış demeki 

“Olsun Önemli değil 

Bu bana bır ders olsun 

Seninle hiç tanışmasaydım 

İnsanlar hakında bir şeyi ögrenemiçektim 

Demek karşılıksız sevgi buymuş 

KARŞILIKSIZ SEVGİ', 'Bir zamanlar çok sevdigimdın bır zamanlar  Bir zamanlar canımı varırdım senin için  Bir zamanlar! !  Bir zamanlar ne düşler kurmuştuk senle ...', ARRAY['Türk Edebiyatı','Şiir','Kerim Odabasi']::text[], 8.5, '{"poet":"Kerim Odabasi","poet_slug":"kerim-odabasi","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/karsiliksiz-sevgi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayran Değilim', 'hayran-degilim-ali-riza-unal-yapz0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalan  olan  aşkına, hayran değilim artık

Dönmüştüm şaşkına, devran değilim artık

Mazide kaldın  ela gözlüm sen artık

Uyandım hülyayı rüyamdan, sana seyran değilim artık', 'Yalan  olan  aşkına, hayran değilim artık Dönmüştüm şaşkına, devran değilim artık Mazide kaldın  ela gözlüm sen artık Uyandım hülyayı rüyamd...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hayran-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atam', 'atam-yavuz-agir-x4b5i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Atam özüm içimdedir.

Devrimlerin hep dildedir.

Dünya alem dilindedir.

Gidem dağlara dağlara.

  Türk lüğe lider oldun.

   Cihana önder oldun.

  Parladın yıldız oldun.

  Cıkam göklere göklere.

Dumlu pınar seni söyler.

Suyu akar türkü söyler.

Sakarya da düğün eyler.

Çıkam dağlara dağlara.', 'Atam özüm içimdedir. Devrimlerin hep dildedir. Dünya alem dilindedir. Gidem dağlara dağlara.   Türk lüğe lider oldun.    Cihana önder oldun....', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/atam-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntihar', 'i-ntihar-sule-aydemir-4jm40', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '________kırılmasın ışıklarım

__________sizi kandırmayacagım

___________________yalın saf telaş 

__________________________ şeffaf



*kalemi gönülden mürekkepli kadının günlüğünden 

10.11.2004'' de', '________kırılmasın ışıklarım __________sizi kandırmayacagım ___________________yalın saf telaş  __________________________ şeffaf *kalemi gö...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/intihar-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rakı', 'raki-haydar-meric-b8ebt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rakı haram şarap haram dediler

Haramiler kuru tüttürdüler

Şimdi haramiye yok mu günah

Anlamadım gitti bu nasıl dünya?', 'Rakı haram şarap haram dediler Haramiler kuru tüttürdüler Şimdi haramiye yok mu günah Anlamadım gitti bu nasıl dünya?...', ARRAY['Türk Edebiyatı','Şiir','Haydar Meriç']::text[], 8.5, '{"poet":"Haydar Meriç","poet_slug":"haydar-meric","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/raki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevap mı?', 'sevap-mi-haydar-meric-76uj1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Giymiş cüppeyi çıkmış yola

Bir elinde tespih bir elinde kokokola

Namazın yoksa diyor ki günah

Vatan toprağı satmak sevap mı? 

Rakı da içerim şarapta

Gözüm yok

Senin namazında niyazında

Var git cennet senin olsun

Ben günahkar olayım

Pontus’u  Patrikhane’yi 

Canlandırmak sevap mı? 

Tutunmuşsun türbana

Saçın gözükürse diyorsun büyük günah

Varsın günah bizim olsun

Patrik okulu açmak sevap mı? 

Fakiri imam hatibe yönlendirirsin

Çocuklarını Amerika’ya gönderirsin

Oruç tutmayana günahkar dersin

Kıbrıs Türk’ünü ezdirmek sevap mı?', 'Giymiş cüppeyi çıkmış yola Bir elinde tespih bir elinde kokokola Namazın yoksa diyor ki günah Vatan toprağı satmak sevap mı?  Rakı da içerim...', ARRAY['Türk Edebiyatı','Şiir','Haydar Meriç']::text[], 8.5, '{"poet":"Haydar Meriç","poet_slug":"haydar-meric","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevap-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avare', 'avare-ali-riza-unal-ctxin', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben dargınım o yâre, koydu beni ne hâle

Sustu dilim biçare, gönlüm artık avare

Dönselerde sultanlar, çevremde pervane

Şen değil gönlüm, ben dargınım o yâre', 'Ben dargınım o yâre, koydu beni ne hâle Sustu dilim biçare, gönlüm artık avare Dönselerde sultanlar, çevremde pervane Şen değil gönlüm, ben ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/avare-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeker ile bal', 'seker-ile-bal-haydar-meric-20cft', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seçim gelir şeker ile bal olurlar

Mühür ele geçer diken ile iğne olurlar 

İhalelerde selamlaşıp ihya olurlar

Bre zalim senin yatacak yerin var mı?', 'Seçim gelir şeker ile bal olurlar Mühür ele geçer diken ile iğne olurlar  İhalelerde selamlaşıp ihya olurlar Bre zalim senin yatacak yerin v...', ARRAY['Türk Edebiyatı','Şiir','Haydar Meriç']::text[], 8.5, '{"poet":"Haydar Meriç","poet_slug":"haydar-meric","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seker-ile-bal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırklareli', 'kirklareli-haydar-meric-1x33g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şehrimi gezdikçe tarih kokar

Yayla’da Karacaibrahim’de

Kırklar tepesinde nice şehitler yatar

Gezde gör Kırklareli’mi

Tarihi dokuyu bozdular

Ne bağ kaldı ne bahçe

Şehrimi sevenleri üzdüler 

Gel de gör Kırklareli’mi

Yeşilin yerini betonlar alıyor

Ciğerlerimiz nefessiz kalıyor

Bu duruma yüreğimiz yanıyor

Gel de gör Kırklareli’mi

Sarmış her yanı çöplükler

Her girişi çalılar hurdacılar

Buna neden yetkililer susar

Gel de gör Kırklareli’mi

Yaylada kalmadı eski yapı

Bozuldu tarihi doku

Farkına varmak için Karaçam’ı oku

Gel de gör Kırklareli’mi', 'Şehrimi gezdikçe tarih kokar Yayla’da Karacaibrahim’de Kırklar tepesinde nice şehitler yatar Gezde gör Kırklareli’mi Tarihi dokuyu bozdular ...', ARRAY['Türk Edebiyatı','Şiir','Haydar Meriç']::text[], 8.5, '{"poet":"Haydar Meriç","poet_slug":"haydar-meric","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kirklareli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Sevgili', 'kor-sevgili-ali-riza-unal-5tgke', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdan hançer oldu, yardı sinemi

Niçindir bu ayrılık, var mı nedeni

Sen neden görmezsin, seni seveni

Derdin  yaş koymadı, kör etti didemi', 'Sevdan hançer oldu, yardı sinemi Niçindir bu ayrılık, var mı nedeni Sen neden görmezsin, seni seveni Derdin  yaş koymadı, kör etti didemi...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kor-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demokrat', 'demokrat-haydar-meric-ud0eo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Solgun demokrat dediler adına

Mührü kaptı erdi muradına

Elinden asla düşmez kalem

Ağzından alamazsın tek bir kelam...', 'Solgun demokrat dediler adına Mührü kaptı erdi muradına Elinden asla düşmez kalem Ağzından alamazsın tek bir kelam......', ARRAY['Türk Edebiyatı','Şiir','Haydar Meriç']::text[], 8.5, '{"poet":"Haydar Meriç","poet_slug":"haydar-meric","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/demokrat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ab-ı Hayat', 'ab-i-hayat-ali-riza-unal-07dm6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sefâlı ömrümün heyhat didarı, neşesiydin sen

Meşk hane gönlümün abu hayat, çeşmesiydin sen

Gidişinle karardı dünyam, yok oldu hülyam 

İstemezdim derman, kalbime yaralar eşmeseydin sen', 'Sefâlı ömrümün heyhat didarı, neşesiydin sen Meşk hane gönlümün abu hayat, çeşmesiydin sen Gidişinle karardı dünyam, yok oldu hülyam  İsteme...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ab-i-hayat-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Menzil', 'menzil-haydar-meric-u02qs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zülfünü taramışta gelmiş

Perçemini buzağı yalamış ta gelmiş

Aklı bir karış havada

Çok düşündüm biz nasıl varırız menzile?', 'Zülfünü taramışta gelmiş Perçemini buzağı yalamış ta gelmiş Aklı bir karış havada Çok düşündüm biz nasıl varırız menzile?...', ARRAY['Türk Edebiyatı','Şiir','Haydar Meriç']::text[], 8.5, '{"poet":"Haydar Meriç","poet_slug":"haydar-meric","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/menzil-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mübarek Olsun', 'mubarek-olsun-ali-riza-unal-fppq9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gel nuş edelim, ey nalânı cilvegâhım

Sazlar gülüşün, kadehler öpüşün olsun

Dillerin baki, ellerin saki ey cananı sultanım

Sana olan sevdam, kutsal aşkım mübarek olsun', 'Gel nuş edelim, ey nalânı cilvegâhım Sazlar gülüşün, kadehler öpüşün olsun Dillerin baki, ellerin saki ey cananı sultanım Sana olan sevdam, ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mubarek-olsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Camız', 'camiz-haydar-meric-benz2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir camız gördüm gözleri manalı

Yatmış çamura gözleri edalı

Mevlam buna ne gerek vardı? 

Böylesi olsa da olur olmasa da...', 'Bir camız gördüm gözleri manalı Yatmış çamura gözleri edalı Mevlam buna ne gerek vardı?  Böylesi olsa da olur olmasa da......', ARRAY['Türk Edebiyatı','Şiir','Haydar Meriç']::text[], 8.5, '{"poet":"Haydar Meriç","poet_slug":"haydar-meric","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/camiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansız Bir Çelişki', 'i-mkansiz-bir-celiski-serhat-ayan-snuoh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '.

.

İmkansızlığın herhangi bir noktası

Senin bedensel varlığının

Tümüyle oraya yansımış halidir

Bu bendeki sen arzusu 

Mucizeleri bile sıfıra indirgemene rağmen

Geleceğin güne dair bir çelişkidir

İmkansızlığının çelişkilerimle çatışması

Leyla''dan üstünlüğünün kanıtıdır

Bu aşkın biteceği an ise 

Gelip bende duracağın zamandır

.

.', '. . İmkansızlığın herhangi bir noktası Senin bedensel varlığının Tümüyle oraya yansımış halidir Bu bendeki sen arzusu  Mucizeleri bile sıfır...', ARRAY['Türk Edebiyatı','Şiir','Serhat Ayan']::text[], 8.5, '{"poet":"Serhat Ayan","poet_slug":"serhat-ayan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/imkansiz-bir-celiski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben seni neyleyim?', 'ben-seni-neyleyim-haydar-meric-eruq0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Belin ince gözlerin keskin

Saçın dalgalı sırma sırma uzun

Boyun servi, dudakların kiraz

Kafanda akıl yoksa ben seni neyleyim?', 'Belin ince gözlerin keskin Saçın dalgalı sırma sırma uzun Boyun servi, dudakların kiraz Kafanda akıl yoksa ben seni neyleyim?...', ARRAY['Türk Edebiyatı','Şiir','Haydar Meriç']::text[], 8.5, '{"poet":"Haydar Meriç","poet_slug":"haydar-meric","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ben-seni-neyleyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zarar', 'zarar-haydar-meric-4zx83', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sabah kalkar komşuya zarar verirsin

Öğle kalkar bir güzel namaza durursun

Fakirin lokmasını dalevera ile alırsın

Sordum erenlere sen nasıl müslümansın?', 'Sabah kalkar komşuya zarar verirsin Öğle kalkar bir güzel namaza durursun Fakirin lokmasını dalevera ile alırsın Sordum erenlere sen nasıl m...', ARRAY['Türk Edebiyatı','Şiir','Haydar Meriç']::text[], 8.5, '{"poet":"Haydar Meriç","poet_slug":"haydar-meric","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zarar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam felsefem...', 'yasam-felsefem-mesut-cakir-4wjx5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ömrümü senin yoluna adadım,

en imkansızı yaratmak,

ve bütün benliğinle...

en sevda halinle,karda kışta,

bir şeyler yapabilmek adına,

senin için varolmak,

seninle yaşamak ve seninle ölmek,

ruhumun derinliklerinde,

seni saklayabilmek gibi,

olmadığın her anı...

düşlerime sığdırabilmek,

senin için ütopyalar yaratmak,

bu ütopyalarda benliğini varetmek,

benim için...

hayatın anlamı,yaşama sevinci,

yaşam felsefesinin ta kendisidir.

98 baharından...', 'ömrümü senin yoluna adadım, en imkansızı yaratmak, ve bütün benliğinle... en sevda halinle,karda kışta, bir şeyler yapabilmek adına, senin i...', ARRAY['Türk Edebiyatı','Şiir','Mesut Çakır']::text[], 8.5, '{"poet":"Mesut Çakır","poet_slug":"mesut-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yasam-felsefem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış', 'kis-ali-aldemir-uf99q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dinmek bilmeyen

Delice yağan yağmurlarını,

Yorulmayan sert esen rüzgarlarını

Uzun ve soğuk....

Çok üşürsün ya sen 

Hiç çıkmazsın hani sokulursun,

Yanıma yatağıma ya

İşte en çok bu yüzden

Uzun ve soğuk gecelerini

Yani en çok kışları severim ben.', 'Dinmek bilmeyen Delice yağan yağmurlarını, Yorulmayan sert esen rüzgarlarını Uzun ve soğuk.... Çok üşürsün ya sen  Hiç çıkmazsın hani sokulu...', ARRAY['Türk Edebiyatı','Şiir','Ali Aldemir']::text[], 8.5, '{"poet":"Ali Aldemir","poet_slug":"ali-aldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kis-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak istiyorum', 'aglamak-istiyorum-sinan-aydindag-7qka5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yorucu bir gün geceye döndü                                    15/12/2003

   Yine ağır adımlarla koğuşuma gidiyorum

   Havadan özlemenin gerginliği düşüyor,

   Bir yük gibi omuzlarıma

   Zor atıyorum bedenimi ranzama

   Annem geliyor,babam geliyor,

   Sen geliyorsun aklıma

   Askerliktir geçer diyorum ama

   Ağlamak istiyorum hemde hıçkıra hıçkıra.', 'Yorucu bir gün geceye döndü                                    15/12/2003    Yine ağır adımlarla koğuşuma gidiyorum    Havadan özlemenin ger...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aglamak-istiyorum-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklıyorum kalbimde seni', 'sakliyorum-kalbimde-seni-sinan-aydindag-4k9ag', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi toros dağları kucaklamış beni                       15/12/2003

   Aksekide,aksekide düşünüyorum seni

   Zorda olsa bu askerlik be canım

   Her an saklıyorum kalbimde seni.', 'Şimdi toros dağları kucaklamış beni                       15/12/2003    Aksekide,aksekide düşünüyorum seni    Zorda olsa bu askerlik be canı...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sakliyorum-kalbimde-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayırlı teskereler', 'hayirli-teskereler-sinan-aydindag-36o3t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Umudunu yitirirsen bitmez bu günler                     15/12/2003

   Seni düşlemezsem geçmez bu geceler

   Bak yine iştimada kısa dönem askerler 

   Gidene eyvallah diyelim,hayırlı teskereler.', 'Umudunu yitirirsen bitmez bu günler                     15/12/2003    Seni düşlemezsem geçmez bu geceler    Bak yine iştimada kısa dönem ask...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hayirli-teskereler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemdir bu', 'ozlemdir-bu-sinan-aydindag-hvqdt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Arkadaş ben evimi özledim                                    16/12/2003

   Anamı,babamı,yattığım odamı

   Abilerimi özledim,sonra dostlarımı

   Özgürlüğümü verin bana

   Sivildeki bütün haklarımı,sonra da

   Rakı soframı.', 'Arkadaş ben evimi özledim                                    16/12/2003    Anamı,babamı,yattığım odamı    Abilerimi özledim,sonra dostlarımı...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ozlemdir-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-harun-kuscu-7l5tk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'unutma çektiğin kötü günleri

hepsini kafana kazı arkadaş

geçmişte kaldı diye unutma dünleri

gönlünde yer etsin yazı arkadaş

kinine sahip ol aşmasın seni

öfkeni tutsak et,taşmasın seni

doğruluğu muhafaza et,şaşmasın seni

ömür mevsiminin güzü arkadaş

yıllarca saçımın akıyla yattım

dünya acıların tek tek tattım

mal mülk sevgisini terkime kattım 

özledim o neşeli yüzü arkadaş', 'unutma çektiğin kötü günleri hepsini kafana kazı arkadaş geçmişte kaldı diye unutma dünleri gönlünde yer etsin yazı arkadaş kinine sahip ol ...', ARRAY['Türk Edebiyatı','Şiir','Harun Kuşcu']::text[], 8.5, '{"poet":"Harun Kuşcu","poet_slug":"harun-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/arkadas-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şafak Cilvesi', 'safak-cilvesi-mehmet-isikoglu-cbhvi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ŞAFAK  CİLVESİ

Bir güzel kız gördüm koştum ardından

Sordum sual ettim ana yurdundan

Cömertçe davrandı özel tavrından

Bana hayran olan cin birisiymiş

Güzelce konuştuk öyle biz bize

Ani bir heyecan şok kalbimize

İkimizi birden getirdi dize

Dedik alnımızın kan yazısıymış

Sohbet tatlı daldıkça derinlere

Düştü aşk ateşi şen gönüllere

Döktük aşkımızı tatlı dillere

Ne güzel kalbimin can yarısıymış

Kader çizgisinde bizde buluştuk

Anlaştık doğrudan evlere koştuk

Evlilik fikrini açıp konuştuk

Dediler münasip tam olasıymış

Bu yolda iyice kafayı yorduk

Düğün dernek yaptık bir yuva kurduk

İş tamam böylece  hedefe vardık

Derken bir uyandım tan rüyasıymış.', 'ŞAFAK  CİLVESİ Bir güzel kız gördüm koştum ardından Sordum sual ettim ana yurdundan Cömertçe davrandı özel tavrından Bana hayran olan cin bi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/safak-cilvesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledikçe', 'ozledikce-sinan-uruc-rqug3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim rüzgarıma,kaç senli yeller vurdu.Kanatlandı sönmüş yıldızlarım,hayalinle sevişirken.Hala,gülüşün; bir nehirin coşmuş hali gibimi....Bir de yüzün...

Geçen onca zalim,başı boş ve acımasız yıllarda hep özlenen ve kokusu sürekli alınan bir aşka ağıt.', 'Benim rüzgarıma,kaç senli yeller vurdu.Kanatlandı sönmüş yıldızlarım,hayalinle sevişirken.Hala,gülüşün; bir nehirin coşmuş hali gibimi....Bi...', ARRAY['Türk Edebiyatı','Şiir','Sinan Uruç']::text[], 8.5, '{"poet":"Sinan Uruç","poet_slug":"sinan-uruc","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ozledikce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözleri Tükettim Kullanmadan', 'sozleri-tukettim-kullanmadan-selim-bayrak-2oire', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sözleri tükettim, kullanmadan

Aşkımı ürküttüm, yaşanmadan

Özlemi eskittim, yıllanmadan

Nerelere nasıl gidiyor bu ömür

Gözleri görürüm, ıslanmadan

Günlere görünüm, puslanmadan

Özlere dönelim, uslanmadan

Geleceğe adım seçiyor bu ömür

Geleceğe gönül veriyor bu ömür

Yaşanmışlıklar içinde aramak seni

Yaşanmışlıklar içinde aramak bizi

Hata! Hata! Yanlış bir seçim

Her şeyi gördüm

Hiçbir şeyi görmediğim anda

Sevgimi ördüm

Mapus kaldım, aydınlık zindanda

Sözleri eskittim, kullanmadan

Aşkımı tükettim, yaşanmadan

Özlemi ürküttüm, yıllanmadan

Bilmiyorum neden çelişir bu gönül

Günleri görürüm, uslanmadan

Gözlere görünüm, puslanmadan

Özlere dönelim, ıslanmadan

Geleceğim sen ol 

Anlarsan beni

Geleceğim inan

Seversen benliğimi

1995 - Bolu', 'Sözleri tükettim, kullanmadan Aşkımı ürküttüm, yaşanmadan Özlemi eskittim, yıllanmadan Nerelere nasıl gidiyor bu ömür Gözleri görürüm, ıslan...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sozleri-tukettim-kullanmadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avcı', 'avci-mehmet-isikoglu-esedz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'AVCI

Iki yay altında yüzlerce oku

Gizlenir pusuya bekler avını

Vurur sersemletir ani bir şoku

Atış boşa gitmez bilir tavını

Böylesi bir avcı ki vurdu hedefi

Yaraladı gitti yatıyor yerde

O güzelim pırıl pırıl sedefi

Bıraktı yüzüstü çaresiz derde

Vicdansız avcıya nerden rastladın

Gülüpte geçiyor kıydığı cana

Sayısı belirsiz olan feryadın

Sesi ninni gibi geliyor ona

Böylemidir kirpik oku atanlar

Vurup bırakırlar perme perişan

Yanar benim gibi yaralı canlar

Bekler bir sevecen imdada koşan.', 'AVCI Iki yay altında yüzlerce oku Gizlenir pusuya bekler avını Vurur sersemletir ani bir şoku Atış boşa gitmez bilir tavını Böylesi bir avcı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/avci-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-husamettin-gunacti-domrp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'geceyim ben,

aysız ve yıldızsız

ve karanlıklardan karanlık

bir gece.

örterim gündelik kötülükleri

simsiyah yorganımla

gizlice.

en büyük düşmanlarım; 

boş hayallere daldığınız

ay ve yıldızlarınız.

çünkü onlara bakıp

gerçeklerden kaçarsınız

sadece.

oysa ben istediğim an

tek bir işaretimle

pamuk tarlalarımı

üzerlerine salarım 

sessizce.

söylentilere inanmayın siz.

yıldızlar ay ve gece

bizler bir bütünüz sanırsınız.

ne kadar da safsınız.

milyonlarca yıldır

aklınızı başınızdan almış

ay ve bir kaç parlak yıldız.

onlar karanlığımdan çalan

arsız birer hırsız.

siz onlara ulaşamazsınız.

bense geceyim.

gerçeklerden korkmayan,

ve sizi hiç aldatmayan.

artık uyanın da 

karanlığıma bir bakın.

göreceğiniz tek şey,

makyajsız saf bir kadın.', 'geceyim ben, aysız ve yıldızsız ve karanlıklardan karanlık bir gece. örterim gündelik kötülükleri simsiyah yorganımla gizlice. en büyük düşm...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gece-1002-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Hırsızı', 'gonul-hirsizi-mehmet-isikoglu-wpfcn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'GÖNÜL HIRSIZI

Bir baktın kendimden geçirdin beni

Hem geçirdin hem de uçurdun beni

Yetinmedin alıp kaçırdın beni

Getiripte verme kalsın istemem

Yaramaz kimseye kupkuru beden

Kalmadı huzurum gelmiyor giden

Takıldı ağına kopmuyor senden

Sahip ol güzelim ölsün istemem

Yaşıyorum senin dünyanda sensiz

Senden ayrı yaşam bana önemsiz

Kaynaştı aşkımız kaldık çaresiz

Dursun gönlüm sende, gelsin istemem', 'GÖNÜL HIRSIZI Bir baktın kendimden geçirdin beni Hem geçirdin hem de uçurdun beni Yetinmedin alıp kaçırdın beni Getiripte verme kalsın istem...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gonul-hirsizi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol (Kızıma II)', 'yol-kizima-ii-faik-genc-8796x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yavaş yavaş yürüyeceksin bu yolda

Büyüyecek, öğrenerek yürüyeceksin

Kimine göre çok çok kısa

Kimine göre fazla uzun bu yolda

Mutlu, durgun, mutsuz olacaksın

Tanımadığım, bilmediğim insanlar

Gözlerine gülücükler,yaşlar getirecekler

Göremeyeceğim üzüntünü, sevincini

Bazen oyunu çok sevip

Bazen oyundan kaçmak isteyeceksin

Umarım gerçekten seversin hayatı

Babanın sevdiği, yaşadığı gibi

Ve aşık olacaksın bir gün sevgili kızım

Bir kez de olur ama iki, üç olsa daha iyi

Göremeyeceğim heyecanını, azabını

Ama sen yavaş yavaş yürüyeceksin bu yolda

Kasım 2004', 'Yavaş yavaş yürüyeceksin bu yolda Büyüyecek, öğrenerek yürüyeceksin Kimine göre çok çok kısa Kimine göre fazla uzun bu yolda Mutlu, durgun, ...', ARRAY['Türk Edebiyatı','Şiir','Faik Genç']::text[], 8.5, '{"poet":"Faik Genç","poet_slug":"faik-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yol-kizima-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kime Yanayım.', 'kime-yanayim-hayrettin-orak-99wu0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bakınıyorum devri aleme,

Koşturur durur insanlar, herkes kendi derdinde,

Kimi varlıklı zevk''u sefa içinde,

Kimi kıvranıyor yoksulluğun pençesinde çaresizce,

Kiminin yemek masasında müzik çalarken,

Kimi sofrasında katıksız kuru ekmeği,

Kimi eğlence merkezlerinde paralar saçarken,

Kimi çocuğuna papuç almaya yoktur parası,

Kimi bayramlığını beğenmezken,

Kiminin yoktur elini öpecek kimi kimsesi.

Söyleyin canlar ben Kime yanayım.

Yanıyor yüreğim,

Bunları düşündükçe içim daralıyor,

Karnı tok sırtı pek olanın haberi olmaz gariplerden,

Bilmezler kimi çocukların dirseği yırtık, papucunun burnu delik,

Küçük bir iyilik bekleyen masum yürekleri insanlara kırık,

Bunu bilmezler, bilselerde umursamazlar,

Yakıyor yüreğimi bunlar, Söyleyin ben kime yanayım.

Dalıyorum düşüncelere, kendimi alamıyorum,

Bir yanda insanlar imaj peşindeyken,

Öte yanda hayatta kalabilme çırpınışları,

Bir yanda insanlar kariyer peşindeyken,

Öte yanda ölüpte çocukları yetim kalmama didinişleri,

Kulağımı kemiriyor güneyden gelen insan çığlıkları,

Ağlıyor için için yetim kalan çocuklar,

Ağıtlar yakıyor eşini oğlunu yitiren analar,

Küçücük elleriyle ancak taş atabilen çocuklar,

Buna mukabil acımasızca mermi yağdıranlar,

Her gün mezarlıklara yenisi eklenen baba yiğitler,

Ömür boyu sakat kalan çocuklar.

Söyleyin bana Ben kime yanayım.

Kendi insanımıza bakıyorum,

Bir çoğu bedeni esir dili sürgünde,

Kimileri köle olmuş yaban ellerde,

İşlenen cinayetler hala dillerde,

Ben kime yanayım,

Ey Allahım biz ne zaman gün yüzü göreceğiz,

Ne zaman masum kalplere sevgi tomurcukları serpeceğiz,

Ne zaman semalarında barış güvercinleri uçuracağız,

Söyle Allahım ne zaman insanca yaşıyacağız,

Yaşamak değil buz kesilmiş beton kaldırımlarda yatmak,

Adalet değil yetimin hakkına tecavüz etmek,

Hakkını arıyanlara bölücü damgası vurmak,

Hangi kitapta yazar dine dile karşı gelmek,

İnsanların namusuna göz dikmek,

Günümüz kalleşlikler dünyası,

Günümüz vahşet, katliamlar dünyası,

Düşene sende vur dünyası,

Günümüz vefasızlıklar, keşmekeşlikler dünyası,

Bilmiyorum dostlar, Ben hangisine yanayım.

Bir yanda sevipte kavuşamayanlar,

Sevdası için canını verenler,

Öte yanda gömlek değişir misali daldan dala konanlar,

Bir yanda gerçeğin peşinde koşturanlar,

Öte yanda hayal aleminde macera peşinde koşuşturmalar,

Bunları düşündükçe derin bir Ahhh çekiyorum dostlar,

Kimi sonsuzluğa bir yelken açar 

Kimi başka limana yükünü alır 

Kimi çevresine mutluluk saçar 

Kimi insanlara hep azap verir 

Bilmem ben kime yanayım,

Bunları yaşamaktansa varsın Öleyim canlar.....! 

11.11.2004', 'Bakınıyorum devri aleme, Koşturur durur insanlar, herkes kendi derdinde, Kimi varlıklı zevk''u sefa içinde, Kimi kıvranıyor yoksulluğun pençe...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/kime-yanayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tekil Gece', 'tekil-gece-orhun-basat-1m9nu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I

düşüp perçeminden tekil gecenin

güncesi unutulan sesin 

isyanını başlatır hüzün 

gözlerim alışır yokluğunuza / kör olurum 

hala yüzüm var mı diye baktığım aynalarda

- ne kadar silsem de aynaları arkasındadır / sır -

hep yüzünüzü bulurum 

bilirim zerreyim gönlünüzde

uzayınızda hiç olurum

II

şeffaf bir paravanın arkasındaydı

özenle sakladığınız gizleriniz

bilemezdiniz

biçağı her saplayışımda mısralarıma

siz yaralanır siz titrerdiniz

haftalık arınmalarında içinizin

ilk beni temizlerdiniz

siz dokundukça başkalarına

ben birikirdim ben çoğalırdım 

bana değerdiniz / hissetmezdiniz

ben... tırnak arası kirleriniz....

III

kolay olurdu adınızı koymak 

gezindiğiniz gönüllerde

hiç kullanmadığınız / ellenmemiş

üç harfi bana verseydiniz...', 'I düşüp perçeminden tekil gecenin güncesi unutulan sesin  isyanını başlatır hüzün  gözlerim alışır yokluğunuza / kör olurum  hala yüzüm var ...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/tekil-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Bir İstanbul', 'baska-bir-i-stanbul-faik-genc-8hsev', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstanbul kabuk değiştiriyor her gün

İstanbul kabuk değiştiriyor içimde

Her gün, her ay, her mevsim

Her yıl bir başka İstanbul

Mayısta açan erguvanları

Ekimde sapsarı yapraklarıyla

Yedi tepeye yağan yağmurları

İçimdeki fırtınalarıyla İstanbul

Binalar, yollar, çarşılarla

Yeni insanlar dört bir yanımda

İnançlar, umutlar, hüzünlerle

Yeni acılar şimdi İstanbul’da

Artık kimseleri tanımıyorum burada

Ne güzel aslında baş başa kaldım

Her geçen yıl başka duygularla

İçimde kabuklanan yara İstanbul

Kasım 2004', 'İstanbul kabuk değiştiriyor her gün İstanbul kabuk değiştiriyor içimde Her gün, her ay, her mevsim Her yıl bir başka İstanbul Mayısta açan e...', ARRAY['Türk Edebiyatı','Şiir','Faik Genç']::text[], 8.5, '{"poet":"Faik Genç","poet_slug":"faik-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/baska-bir-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Gözlerin Öldürsün', 'beni-gozlerin-oldursun-haydar-okur-om93d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana bir söz desin ki gözlerin

       Derinliklerinde süren mavi yolculuğumun

       Gölgelerine düşsün aydınlığı gözlerinin

       Hüznümün sıcacık belleğine 

       Erinçler yağdırsın ışık ışık

       Ve kuşça sevinçler

       Gözlerin öldürecekse beni böyle öldürsün

       Bana bir söz desin ki gözlerin

       Güz gözlerime taşısın bulutlarını

       Ay ağıda dursun ve yıldızlar yasa

       Yok etsin bahtıma yansıyan bütün renkleri

       Saklama gözlerini gözlerimden

       Yaksın, yıksın kevgir yüreği 

        Ne diyecekse bırak gözlerin desin	

        Gözlerin öldürecekse beni böyle öldürsün

   

       Bana bir söz desin ki gözlerin

       Hallacım ol, lincime hazırlan desin

       Bırak istediğini istediğince söylesin

       Toprak damar damar emsin bedenimi

       Mutlu olacaksa sevinecekse gözlerin 

       Bana öl desin

     

       Gözlerin öldürecekse  beni böyle öldürsün', 'Bana bir söz desin ki gözlerin        Derinliklerinde süren mavi yolculuğumun        Gölgelerine düşsün aydınlığı gözlerinin        Hüznümün...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/beni-gozlerin-oldursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güller', 'guller-i-dil-atmaca-ealfe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'güller. bazen güzel bazen çirkindir

bir bakıyorsun sağda bir gül

bir bakıyorsun solda bir gül

ikiside birbirinden farklı 

ikiside birbirinden güzel

ama tek bir şey var

biri solgun ve çürümüş,

öbürü dünyaya küsmüş

biri aldatılmış

biride başkalarına yaranamamış

ikisininde derdi aynı 

ikisinin de derdi farklı

tek bir özellikleri var aynı

oda gül olmaları', 'güller. bazen güzel bazen çirkindir bir bakıyorsun sağda bir gül bir bakıyorsun solda bir gül ikiside birbirinden farklı  ikiside birbirinde...', ARRAY['Türk Edebiyatı','Şiir','İdil Atmaca']::text[], 8.5, '{"poet":"İdil Atmaca","poet_slug":"i-dil-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/guller-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam beni kandırıyor', 'sevdam-beni-kandiriyor-suheyla-aydogdu-a4pas', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tenim tenini arzularken,

Tenin tenleri arzuluyor.

Elim ellerini ararken,

Elin elleri arıyor.

Gözüm gözüne yanarken,

Gözün gözlere kayıyor.

Oy! ! Belalım, oy! !  sevdalım

Sen benden çoktan gitmişsin

Sevdam beni  kandırıyor.', 'Tenim tenini arzularken, Tenin tenleri arzuluyor. Elim ellerini ararken, Elin elleri arıyor. Gözüm gözüne yanarken, Gözün gözlere kayıyor. O...', ARRAY['Türk Edebiyatı','Şiir','Süheyla Aydoğdu']::text[], 8.5, '{"poet":"Süheyla Aydoğdu","poet_slug":"suheyla-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevdam-beni-kandiriyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüsran', 'husran-selim-eysioglu-3bqph', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yolcuyum; Durağımın adı o,

Alimim; İlimimin adı o,

Şairim; Şiirimin adı o,

Okurum; Kitabımın adı o,

Yazarım; Kalemimin adı o,

Yastayım; Kederimin adı o,

Hastayım, Hastalığın adı o,

Hastalığa sebep olan,

Yaşanan   ''HÜSRAN''

Ve HÜSRAN, kardeşidir HİCRAN '' ın,

Ve de bu iki kardeşi yan yana yazsan

İkisi bir şiir olacak kadar,

'' Lirik '' kelimelerdir...', 'Yolcuyum; Durağımın adı o, Alimim; İlimimin adı o, Şairim; Şiirimin adı o, Okurum; Kitabımın adı o, Yazarım; Kalemimin adı o, Yastayım; Kede...', ARRAY['Türk Edebiyatı','Şiir','Selim Eyşioğlu']::text[], 8.5, '{"poet":"Selim Eyşioğlu","poet_slug":"selim-eysioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/husran-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz''e bırak Ben''i', 'biz-e-birak-ben-i-ali-aydogdu-opp6a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'aldanma; 

avuçlarındaki çizgiler eskimez 

tırnakların yeniler kendini durmadan 

zaman zavallıdır ellerinde 

tutarsa sevdan 

kaç defa girdi kapıdan 

karanfiller atılmadan 

aslında kapalıydı pencereler

___açılmadan 

........biz seninle İstanbul''lar kurardık, soğuk sahillere

kumdan İstanbul''lar

şişeden İstanbul''lar

İstanbul mezar taşıydı başucumuzda

biz ölmeden önce 

inanma; 

yanağına süzülen ıslaklık yağmur değil

gözyaşı değil 

kan değil

ağlama öyleyse

çare değil 

sus bu gece

ikimiz konuşsun....

............................................Hayal Dergisi (ekım kasım aralık 2005 yeşil sayı)', 'aldanma;  avuçlarındaki çizgiler eskimez  tırnakların yeniler kendini durmadan  zaman zavallıdır ellerinde  tutarsa sevdan  kaç defa girdi k...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydoğdu']::text[], 8.5, '{"poet":"Ali Aydoğdu","poet_slug":"ali-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/biz-e-birak-ben-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim Seni Birtanem', 'sevdim-seni-birtanem-ahmet-altintas-4cbz1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bakma bana ben suçluydum

İp üstüstünde gözyaşlarımla daha mı mutluydum

Razıydım bitecekti hayat kurtulmalıydım

Ta ki seni gördüğümde dedim yaşamalıydım

Akşam olup gözyaşlarımı akıtmamalıydım

Neden diye sorma yalnız kalmamalıydım

Ellerimi tuttun elveda hayat demişken

Mutluluktu adın göz pınarlarım kurumuşken

Sevdim seni

Ellerini tutamadan

Nasılsın ne haldesin yanında olamadan

İstendiğimde yanına gelemeden sevdim seni

Çok uzaklarda olsanda hep yanımdasın diyemeden

Omzuna dokunup kendine gel diyemeden

Korma nolur sevdim seni zarar gelmez benden

Susmayı tercih ettim kelimeler bulamadan

Ecel gelsede  seni  unutamam

Varlığın yeter üzülme nolur

Dudaklarım titrerken tebessümün gözlerimde

İstemem hiç gözyaşı dökmeni

Mutlu olmandan başka yok istediğim sevdim seni', 'Bakma bana ben suçluydum İp üstüstünde gözyaşlarımla daha mı mutluydum Razıydım bitecekti hayat kurtulmalıydım Ta ki seni gördüğümde dedim y...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altıntaş']::text[], 8.5, '{"poet":"Ahmet Altıntaş","poet_slug":"ahmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevdim-seni-birtanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarali üzür', 'yarali-uzur-nigin-nevaderezi-9mhsv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Fikirim üreyime calanib

Yaziq! 

Nefesim yarali üzür

Düz yazamayiram

Meni gezdir şam*dan bileginde

Qoy berkiyim yaddaşin dalğalari

Titreyişinde

Barmağlarimi tapşir yelkenlerine

Çizgi denizinde elaci** dostum

Helelik,

Kiçik bir dalğada mene dağ gelir

Çixacağim dağlar

Qelemin yaddaşinda ölçulur

Haradan qarişirsin fikir makinamin

Döyüntülerine? 

Düz gelemirem 

Belkede buruşuq gezirsen

Qisa dalğa için eseceyim

Uzadi barmağlarimin buludunda.

-----------

*Mum

**Zeyrek

Tebriz-1998', 'Fikirim üreyime calanib Yaziq!  Nefesim yarali üzür Düz yazamayiram Meni gezdir şam*dan bileginde Qoy berkiyim yaddaşin dalğalari Titreyişin...', ARRAY['Türk Edebiyatı','Şiir','Nigin Nevaderezi']::text[], 8.5, '{"poet":"Nigin Nevaderezi","poet_slug":"nigin-nevaderezi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yarali-uzur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-ahmet-altintas-0w9ou', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dur dinle beni

Alışılmışın dışında geceler boyu saatlerce beklerken

Hani derdim ya seni seviyorum biriciğim

Ayrılık acısını hissedince anladım sana tapıyorum

Çok erken gitme nolur  kalmanı istiyorum

Olumsuzluklarla yalnız bırakma 

Kal taht kurdun yüreğimde en güzel yerindesin

Ebediyen yokluğuna alışamam

Razı olurum konuşmak istemesende

Kelimelerle anlatılamazsın cümleler yetersiz 

Er vakti doğan güneşin doğaya verdiği can gibisin

Nisan yağmurunda susayan toprağın özlemi gibisin

Sen içindesin benim ellerinde lalelerle istediğim mutluluğumsun

Gözlerimdeki akan damlalar neden

İstiyorsan git hadi durma arkana bakmadan

Terk edemezsin  zorunlu bir ayrılıktır bu

Melekler gibi hep yanımda olacaksın

Ezberlemiş adını yüreğim onda kalacaksın

Neden duruyorsun git  yalnız bırak gözyaşlarımla

Oralarda uzaklarda ne haldesin ne yaparsın

Lal olsaydı dilim konuşmazdı bilemezdin ne çok sevdiğimi

Umursamadan çekip giderdin bir yabancı gibi

Razı olamam gitme nolur dayanamaz yüreğim yokluğuna kardelen çiçeğim...', 'Dur dinle beni Alışılmışın dışında geceler boyu saatlerce beklerken Hani derdim ya seni seviyorum biriciğim Ayrılık acısını hissedince anlad...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altıntaş']::text[], 8.5, '{"poet":"Ahmet Altıntaş","poet_slug":"ahmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gitme-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Havası', 'ask-havasi-elif-kerenciler-40bj8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ne güne bakış değişti 

ne de yaşamın hali

karşımda duruyorsun öylece

belki aynı şarkıyı mırıldanıyoruz bazen

ya da aynı sitemleri dile getiriyoruz sessizliğimizde

sen güne inatsın ben sana inat

gün bitiyor sonra ama sen bitmiyorsun...', 'ne güne bakış değişti  ne de yaşamın hali karşımda duruyorsun öylece belki aynı şarkıyı mırıldanıyoruz bazen ya da aynı sitemleri dile getir...', ARRAY['Türk Edebiyatı','Şiir','Elif Kerenciler']::text[], 8.5, '{"poet":"Elif Kerenciler","poet_slug":"elif-kerenciler","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ask-havasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Qaçaqçi', 'qacaqci-sair-nadirezheri-9ztn8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Men söz qaçaqçisiyam

Şirlerim kimi pinti* gezirem

Ferari kelmeleri gizledirem

Ahlara palto geyindirirem

Yumuruqlara şapka! 

Men dert qaçaqçisiyam! 

*Sehmansiz

Erdebil-2001', 'Men söz qaçaqçisiyam Şirlerim kimi pinti* gezirem Ferari kelmeleri gizledirem Ahlara palto geyindirirem Yumuruqlara şapka!  Men dert qaçaqçi...', ARRAY['Türk Edebiyatı','Şiir','Şair Nadirezheri']::text[], 8.5, '{"poet":"Şair Nadirezheri","poet_slug":"sair-nadirezheri","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/qacaqci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kundura Vuruğudur Ayrılık', 'kundura-vurugudur-ayrilik-i-brahim-yamac-ofhhy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ikiye ayrılan ırmağın suyu

bir akar iki kolda

/kalbi ikiye bölüp

bir bütün sana bir bütün bana

paylaşmaktır ayrılık/

damlanın gözü bulutta

yaprağınki hala dalda

düşerken toprağa

/çatır çatır çekilmesidir 

tereyağından kılın

ayrılık/

bir yıl, on yıl

yüz bin anı, yüz bin acı

milyonları çaresiz bırakacak gözyaşı

/sayıları omuzlayıp sıfıra

yürümektir ayrılık/

tozu dumana katıp

ufka batan atlı

kim bilir heybesine

hangi yangını kattı

/alev alıp, alev olup

yanmaktır ayrılık/

her saniye ayrılığı vurur

kadran boyunca

/kundura vuruğudur 

ayrılık/', 'ikiye ayrılan ırmağın suyu bir akar iki kolda /kalbi ikiye bölüp bir bütün sana bir bütün bana paylaşmaktır ayrılık/ damlanın gözü bulutta y...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yamaç']::text[], 8.5, '{"poet":"İbrahim Yamaç","poet_slug":"i-brahim-yamac","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kundura-vurugudur-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adaxlilar* üçün', 'adaxlilar-ucun-sair-nadirezheri-0r336', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adaxlilar parkasinda tekem**

Ve indi hünerim

Göydeki öpüşleri qapmaq

Öpüş yollamaqlari yazmaqdir

''Maşalla'' maçilar*** size,''maşalla'' maçilar

Muuu...ç! 

---------------------------

*Nişanlilar

**Yalnizim

***Öpüşler

Bu şiir Tebrizin Adine hefteliyinde yayilanmişdir (1380 Güneş yili) 

(Tebriz-2001)', 'Adaxlilar parkasinda tekem** Ve indi hünerim Göydeki öpüşleri qapmaq Öpüş yollamaqlari yazmaqdir ''Maşalla'' maçilar*** size,''maşalla'' maçilar...', ARRAY['Türk Edebiyatı','Şiir','Şair Nadirezheri']::text[], 8.5, '{"poet":"Şair Nadirezheri","poet_slug":"sair-nadirezheri","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/adaxlilar-ucun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-birol-ozkan-jby2w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiçbir kalp bu kadar dayanıklı olamazdı bir parçasını gönderip arkasından bakarken ve hiçbir kalp bu kadar sessiz olamazdı bir güle güle bile diyemeyip gözleri seni ararken kuytu yerlere gizlenip hıçkırıklara boğulurken. Belki kaçmaktı bunun adı belki de son defa göreceğini bile bile veda edememek. Veda en güçsüz olduğum duygularımın artık bedenimin taşıyamayacağından fazla harekete geçtiği andır benim için. Bedenimin iflasını, duygularımın gözlerimden boşandığı anı görsün istemiyorum hiç kimse. 

Karanlık bir odanın kapı aralığından son kez sana bakarken, belki de son kez görüyorum yürüyüşünü, ağır ağır seni bizden alıp uzaklara götürecek arabaya binerken. Ellerini, ve o simsiyah uzun saçlarını camdan son kez bakarken ve hep gülerken görmeye alıştığım gözlerini ağlamaklı görürken. 

Ve artık yoksun….

O kadar yalnızım ki, sanma etrafımda sevdiklerim var mutluyum. Kimseyi görmüyor gözüm, hayallerle yaşıyorum..her gün seni son kez gördüğüm yerde seni bekliyorum, son bakışını, gözlerime bakmanı, saçlarını tutmayı ve  hiç bırakmayacakmış gibi bana sımsıkı sarılmanı…

Biliyorum ki sen gelmeyeceksin, aramayacaksın ve biliyorum ki hiçbir zaman affetmeyeceksin beni. Her zaman vardım yanında, beraber ağlardık beraber kahkahalarla gülerdik, ama hiç ayrılmamıştık hiç veda etmemiştik birbirimize.', 'Hiçbir kalp bu kadar dayanıklı olamazdı bir parçasını gönderip arkasından bakarken ve hiçbir kalp bu kadar sessiz olamazdı bir güle güle bil...', ARRAY['Türk Edebiyatı','Şiir','Birol Özkan']::text[], 8.5, '{"poet":"Birol Özkan","poet_slug":"birol-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/veda-122-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalgalar', 'dalgalar-ali-galip-sari-dsgdv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu durgun sular biden kabarsa,

Yaslansa kıyıya koca dalgalar...

Giderken yanına beni de alsa,

Sevdalım denizin oğlu dalgalar....

Bir fırtına çıksa devrilse gemim,

Gelip çatsa ölüm son bulsa demim

Atım şaha kalksa kırılsa gemim,

Beni yanlarına alsa dalgalar...

Her kulaç atışta geriye gitsem,

Çıra gibi yansam mum gibi bitsem,

Şairin elinde hokka, divitsem,

Beni  tam ikiye bölse dalgalar...

Uzun ömrüm bitse gelse ecelim,

Ve ölümüm olsa elimden elim...

Tabuttan dışarı el etse elim,

Benimle beraber ölse dalgalar', 'Şu durgun sular biden kabarsa, Yaslansa kıyıya koca dalgalar... Giderken yanına beni de alsa, Sevdalım denizin oğlu dalgalar.... Bir fırtına...', ARRAY['Türk Edebiyatı','Şiir','Ali Galip Sarı']::text[], 8.5, '{"poet":"Ali Galip Sarı","poet_slug":"ali-galip-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dalgalar-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çokmu Bana', 'cokmu-bana-hayrettin-orak-nrkqg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben hiç istemezmiydim,

Mis kokulu bahar akşamlarında senin kokunu koklamak,

Yıldızların raks edişini seyretmek,Dalgaların şarkı söyleyişini dinlemek,

Sabahı gelmez gecenin nemli nemli ağlayışını seyretmek,

Dans etmek, şarkı söylemek, ağlamak Çokmu bana.

Ben hiç delice sevemezmiyim,

Kara rıhtımlarda geceyle birlikte sabahlamak,

Serhoş naralarında aşkımı haykırmak,

Dans edip yunuslara seni fısıldamak,

Sevmek sevilmek aşkımı haykırmak, Çokmu bana.

Yüreğimdeki aşk bir tek senin aşkın,

İçtiğim suda yediğim aşta senin tadın,

Kollarımda yalnız bırakan, yüreğimi yakan hasretin,

Küçücük yüreğimde kükreyen, aşk ateşin,

Sevdalanmak, aşkınla yanmak seni aramak, Çokmu bana.

Ben yine seni sensiz arıyorum,

Gecenin tan yerini beklediği gibi sabırsızca,

Yokluğun elimde tutamayacak kadar umutsuzca,

Akşama küsen, sabaha sevinen gündüz açtı gibi,

seni aramak, seni beklemek, Çokmu bana.

Sana olan sevdam kaf dağı kadar yüksekte,

Sensiz yalnızlığım aciz bedenimi tüketmekte,

Mum ışığı kadar sönük umutlarım tükenmekte,

Sevdamızı ayıran kalleşlerle hesabım ahirette,

Seni görmek, aşkımı sana haykırmak, Çokmu Bana.....! 

11.11.2004', 'Ben hiç istemezmiydim, Mis kokulu bahar akşamlarında senin kokunu koklamak, Yıldızların raks edişini seyretmek,Dalgaların şarkı söyleyişini ...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/cokmu-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çileme Razıyım.', 'cileme-raziyim-hayrettin-orak-e98rr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tek isteğim, tek dileğim mutlu olmaktı,

Ama nafile, ben doğmadan yazılmış kara yazım,

Sıcak bir yuvaya,şefkatli bir ele muhtaç iken,

Yalnızlık deryasında, hırçın dalgalar arasında hep savruldum,

Kaderim bu, Alın yazım bu, Çileme Razıyım.

Ağaçların yaprakları altında sabahladım, 

1 gece 10 gece bitmeyen gecelerce,

Gecenin rüzgarı, yatağımın yorganı oldu,

Göz yaşlarım gecenin nemi ile yoğruldu,

Yalnızlık rüzgarında tutanacak tek dal aradım,

Kaderim bu, Alın yazım bu, Çileme Razıyım.

Ben hiç Anne demek istemezmiydim,

Gök yüzünde korkutucu şimşekler çaktığında,

Yalnızlık tufanı külütsiz kapıma dayandığında,

Donduran soğuktan buruşmuş ellerim üşüdüğünde,

Sığınacak bir kucak, yalnızlığıma bir dost aradım,

Kaderim Bu, Alın yazım bu, Çileme Razıyım.

Hiç Baba diyemedimki, sımsıcak kollarına sarılamadımki,

Yalnızlık mahpusunda mahkum edilmeye suçum neydiki,

Benim tek mutluluğum Anne Baba demekti,

Yalnızım, Kimsesizim, derdimi anlatsam ne çare,

Kaderim bu, Alın yazım bu, Çileme Razıyım.

Hasret kaldım hep aradım sıcak bir sevgiyi,

Hep horlandım hep ezildim yalnızım kimsem yok diye,

Uçuruma giderken acımadan alkış tuttular,

İsyanda etmiyorum, acı kaderime teselli arıyorum,

Kaderim bu, Alın yazım bu, Çileme Razıyım.

11.11.2004', 'Tek isteğim, tek dileğim mutlu olmaktı, Ama nafile, ben doğmadan yazılmış kara yazım, Sıcak bir yuvaya,şefkatli bir ele muhtaç iken, Yalnızl...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/cileme-raziyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Coştukça Coştu Sevdam.', 'costukca-costu-sevdam-hulya-arisan-y3jpl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öyle duru başladı ki

sevdam...

Yavaş yavaş

bütün hücrelerime işledi;

Sonra hızlandı

coştukça coştu!

Sevgin yüreğime

sığmaz oldu.

MAVİ bir yol buldu

dolu dizgin aşka uçtu...

İstanbul, 11 Kasım 2004', 'Öyle duru başladı ki sevdam... Yavaş yavaş bütün hücrelerime işledi; Sonra hızlandı coştukça coştu! Sevgin yüreğime sığmaz oldu. MAVİ bir yo...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/costukca-costu-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahrediyorum.', 'kahrediyorum-hayrettin-orak-y2srx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çiçek tarlasında sensiz yürüyorum,

Etrafımda gül, karanfil, lale, mor menekşe,

Bir gelin misali gelinlik giymiş gibi dallarını çırpıyorlar birbirlerine,

Sanki sonsuz sevdalarını anlatıyorlar,

Birden aklıma sen geliyorsun,

Hani en sevdiğin renk beyaz,

En sevdiğin elbise gelinlikti,

Dudaklarımda beni kahreden mısraları mırıldanıyorum,

Bana söylediğin ayrılık şarkısını unutamıyorum,

Soruyorum senmisin bana düşman,

Yoksa beyaz renkli bir çiçek birde gelinlikmi,

Şimdi gün, saat, zaman umurumdamı,

Yıllar geçmiş ancak unutulmayan acı hatıralar kalmış,

Aynanın karşısına geçiyorum ve kendime bakıyorum,

Zaman rüzgarlarında buruşmuş yüzüm,

Ak düşmüş tel tel saçlarım,

Cesaretin varsa gel birde sen gör yarattığın eseri,

Ne yaptım ben sana,

Benden sevda istedin en yücesini verdim,

Katlandım sana sevdanla yanan yüreğimin sanvısına,

Bir inat uğruna bırakmak terketmek varmıydı,

Ben senden mertlik bekledim kalleşlik değil,

Senin için yaşattığım sevdama kahrediyorum...! 

11.11.2004', 'Bir çiçek tarlasında sensiz yürüyorum, Etrafımda gül, karanfil, lale, mor menekşe, Bir gelin misali gelinlik giymiş gibi dallarını çırpıyorl...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kahrediyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen.', 'kardelen-hayrettin-orak-o8d5p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elveda dediğim aşkımın son hatırası SEN,

Ayrılık acısıyla yanan yüreğimin sancısı SEN,

Dimdik bedenimi tüketen, derdimle dermansız bırakan SEN,

Sana değmeyen aşkımın mazisini hatırlatan SEN,

Yaktın beni, yıktın beni, eline ne geçtiki Kardelen.

Senden sana olan aşkıma bir karşılık tebessüm bekledim,

Tertemiz aşk defterime senin adınla aşkımızı yazdım,

Bu acıya senin için katlandım, çile rüzgarında sürüklendim,

Yazık sana hiç düşünmedinmi masum aşkları,

Leylayı, Mecnunu, Ferhatı Şirini, Kerem''le Aslıyı,

Bu aşkta ayrılık hüsranı neden Kardelen.

Hep düşündüm zordur sana ulaşmak, seni yaşamak,

Belki beni sevseydin, üstünü örten kar olurdum,

Üzerine doğacak bahar güneşinin altında senin için erirdim,

Ne yazık anlamadın sana olan sevgime kara sevdama,

Aşkınla kanadı kırılmış kuş misali çırpınışlarımı,

Yaktın beni, yıktın beni, eline ne geçtiki Kardelen.

Ayrılık vurgunu yemiş o gün. o yağmurlu gün,

Üzerimize yağıyordu aşkımızın göz yaşları,

Gökyüzü ayrılık feryadını şimşeklerle haykırırken,

İnadın neydi neden anlamadın göz yaşımı, aşkımın feryadını,

Hiçmi ağlamadın, hiçmi feryat etmedim,

Dilerim sende bir gün delice seversin, acı çekerek yanarsın,

Neden bu ayrılık, yaktın beni eline ne geçtiki Kardelen....! 

11.11.2004', 'Elveda dediğim aşkımın son hatırası SEN, Ayrılık acısıyla yanan yüreğimin sancısı SEN, Dimdik bedenimi tüketen, derdimle dermansız bırakan S...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kardelen-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmek', 'bilmek-baykal-kaanalp-n74sx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bilmek bir hakikatin

kalpsizliğini

zamansız çıkıp geldiği

yolları geri yürümesini

devirmesini izin verdiğin

incir çuvallarını

yemişini saklama 

zahmetine katlandığın

saklı cennetlerin vardı

belki de açığa alamadığın

girintisiz sadece bir çıkıntı

ilmeklerinde dokunmuş zamanın

sebebi yok inanma sakın

sana attığım

mutsuz kağıttan uçakların

bilmek acı verse de

adını bilmediğim zahmetime

yine de güzel bir his

dokunma dürtülerinde

alışık olmadığımız', 'bilmek bir hakikatin kalpsizliğini zamansız çıkıp geldiği yolları geri yürümesini devirmesini izin verdiğin incir çuvallarını yemişini sakla...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bilmek-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçış Treni', 'kacis-treni-baykal-kaanalp-saose', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kaçış trenine bindik

uzun süre yol aldık

mutlaka geçilmesi gereken

bir köprüde,dona kaldık', 'kaçış trenine bindik uzun süre yol aldık mutlaka geçilmesi gereken bir köprüde,dona kaldık...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kacis-treni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokuş', 'yokus-baykal-kaanalp-chnmx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'öğrenebildik mi? acaba

tüm bu yokuşlarını

çıkarken dünyanın

yeteri kadar

yorulacağımızı', 'öğrenebildik mi? acaba tüm bu yokuşlarını çıkarken dünyanın yeteri kadar yorulacağımızı...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yokus-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıkmayacağım.', 'bikmayacagim-hayrettin-orak-kjmtq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum diyecek yüreğim, kor ateşlerde yansa,

Seni arayan yorgun bedenim, kızgın çöllerde kaybolsa,

Seni bekleyen sevdam, aşk deryasının hırçın dalgalarında çırpınsa,

Tutunacak tek dalım olmasa, uçuruma itilsemde,

Yemin ederim seni sevmekten Bıkmıyacağım.

Bakışlarının masumiyetini hiç bir şeyde bulamadım,

Sevdanın iki kelime olduğunu seninle öğrendim,

Bu sevda sana kavuşamasamda ömrümce sürecek,

Sen olmadan her anım hayatıma demirli bir zindan,

Ömrümce cezamı çeksem, bedenim çürüsede,

Yemin ederim seni sevmekten Bıkmıyacağım.

Sana kavuşmayacağım, sana sarılmayacağım bunuda biliyorum,

Sıcaklığını arayan bedenim hasretinle buz tutsada,

Hasret ateşi volkan ateşi gibi yüreğimi yaksada,

Aramıza sarp yollar, geçit vermeyen dağlar girsede,

Sana olan umutlarım, sevdam son bulmayacak,

Yemin ederim seni sevmekten Bıkmıyacağım.

Her doğacak gün umutlarımın başlangıcı olacak,

Sesini arayan kulağım başkasını duymuyacak,

Gözlerim hurileri kıskandıran güzelliğinden başka bir şey görmüyecek,

Aşk şarkımızı arayan kulağım sağır olsada,

Sana adadığım ömrüm, Aşk sürgünleri yaşasada,

yemin ederim seni sevmekten Bıkmıyacağım.

Sen tattırdın bana sevgiyi, aşkı, sevdayı,

Bu sevda son sevdam, gönül mabetimde kara bulutlar olsa

Aşk günahımızın cezası, kalbimin zindanları olsa,

Çektirdiğin azap günleri bin ömürden beter olsa,

Son saatim, son anım, son nefesim olsa

Yemin ederim seni sevmekten Bıkmıyacağım.

Ne umutlarla seni sevdim umutlarımı hayalinle süsledim,

Umutlarım tükenmeyecek, hayalin tesellim olacak,

Çaresi olmayan kara sevdalara, sevda sancılarına tutulsam,

Azrail gelse''de aşkımı, son nefesimide istese,

İşte o an son sözüm Seni Seviyorum olacak..................! 

11.11.2004', 'Seni seviyorum diyecek yüreğim, kor ateşlerde yansa, Seni arayan yorgun bedenim, kızgın çöllerde kaybolsa, Seni bekleyen sevdam, aşk deryası...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bikmayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Senin Olsun.', 'al-senin-olsun-hayrettin-orak-sl00p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Elimde olsaydı, Asi bir rüzgar olur yakan yıkan tufan olur,

Yıkık virane aşkları sonsuza dek silerdim,

Elimde Olsaydı,

Ayrılığa, yalnızlığa, hasrete, kalleşliğe kurşun sıkardım,

Vurma, vurma bana zalim dünya,

Benden başka alacağın neyim kaldıki,

Uçuruma sürüklenirken tutnacak dalmı bıraktın,

Yalnızlığıma kaderime dostmu bıraktın,

Şimdi tek tesellim aşkım oldu,

Onudamı alacaksın, Al senin olsun.

Neyine inanayımki, neyine güveneyimki senin,

Her gün ağlattın bir gün güldürmedinki,

Bana tek teselli acı kader bıraktın,

Senden istediğim bir tek mutlu olmaktı,, onuda çok gördün,

Şimdide sevda bahçemde bir gül tomurcuklandı,

Onuda sök kökünden, Al senin olsun.

Bir gün yüzüm gülmediki,

Mutluluğu bekleyen yüreğim hiç sevinmediki,

Yüreğim acıdan başka ne çektiki,

Hüzün zincirleri boynumda halka halka,

Beni mutlu eden sevda türkülerim, yıkık virane aşklarım,

Onuda alacaksan Al senin olsun.

Yüreğimde kin kustuğum kap kara bulutlar,

Hüzün, mutsuzluk alın yazım, ayrılık okları yüreğimi yaralar,

Hasret çektiğim bir gün bir ömürden beter olmuş,

Hiç gülmeyen yüzüm, bahtsız kaderim,

Onuda istersen Al senin olsun.

Bu son türkü olacak, yürekleri yakan acı bir ağıt,

Sevdayı, mutluluğu arayan mazlum sevdalı,

Sevdasına kurşun sıkılan yaralı maral,

Geriye kalan yorgun aciz bedenim,

Onudamı istiyorsun. varsın, Al senin olsun..........! 

11.11.2004 / BATMAN', 'Elimde olsaydı, Asi bir rüzgar olur yakan yıkan tufan olur, Yıkık virane aşkları sonsuza dek silerdim, Elimde Olsaydı, Ayrılığa, yalnızlığa,...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/al-senin-olsun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakladım Seni Ben', 'sakladim-seni-ben-hatice-kuzu-49wr1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Büyüttüm,

Seni kalbime yazmıştım,

En derin oyuntularla kuytularda

Ve  sen kalmıştın.

Silik şiirlerde,

Kaybolan düşlerde.

Aslında hep seni büyütmüştüm,

Sensiz uyuduğum gecelerde.

Bağışladım,

Her şeyimi,her şeyini

Affedilmez sandığım hataları,

Ben olan organlarımı.

Yaşadıklarımı ve yaşattıklarını…

Dağıttım parça parça tüm uzuvlarımı

Aslında  hepsinde biraz sen vardın

Ama onları da bağışladım,

Sensiz geçirdiğim gecelerde.

Sakladım,

Bir kalbim kaldı geriye

Parça parça dağılan bedenime inat

Bir onu büyüttüm içimde,

Ve sen

Aslında sen değilsin şu an dokunan

Elime, yüzüme,bedenime.

Seni sakladım ben en derinime…

11.11.2004

* Bu şiirimin yazılmasında emeği geçen sol_anahtarı_çekirgeme sevgilerle.......', 'Büyüttüm, Seni kalbime yazmıştım, En derin oyuntularla kuytularda Ve  sen kalmıştın. Silik şiirlerde, Kaybolan düşlerde. Aslında hep seni bü...', ARRAY['Türk Edebiyatı','Şiir','Hatice Kuzu']::text[], 8.5, '{"poet":"Hatice Kuzu","poet_slug":"hatice-kuzu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sakladim-seni-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmak...', 'unutulmak-umut-gul-3ybye', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unutulmak…

en acıdır belki de yaşanan

bir köşede, 

boş bir saksı gibi 

unutulu vermek...

ya da...

kullanılıp atılan kağıt mendil gibi

yalnızlığa terk edilmek...

(fırlatılı vermek)

unutulmak değil gücüme giden

birde sen unutulacak adam mısın? 

deyişin; 

beni kahreden…', 'Unutulmak… en acıdır belki de yaşanan bir köşede,  boş bir saksı gibi  unutulu vermek... ya da... kullanılıp atılan kağıt mendil gibi yalnız...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unutulmak-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Dans', 'son-dans-pervin-cankaya-zuvli', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu saatlerde daha bir koyuyor yokluğun bana! 

Saçlarımı okşayan rüzgar sen oluyorsun; 

   Bir ezgi var sanki dudaklarında.

Yalnız benim duyabildiğim, 

   Yalnız benim hissedebildiğim bir acıma...

Tenimde dans eden nemli hava; 

   Yalnızlığımı büyütüyor koynunda.

Geri dönülmez bir sevda çıkmazında; 

   Çıkmıyor hiçbir yol sana! 

Yanımda olsan, 

Haykırsam:

“Yıldızlar şahit aşkıma, 

                     sor onlara.”

Benim değilsin,

Düğümleniyor kelimeler boğazımda.

Rüzgar saçlarımı okşuyor,

Nemli hava son dansını yapmakta! ..', 'Bu saatlerde daha bir koyuyor yokluğun bana!  Saçlarımı okşayan rüzgar sen oluyorsun;     Bir ezgi var sanki dudaklarında. Yalnız benim duya...', ARRAY['Türk Edebiyatı','Şiir','Pervin Cankaya']::text[], 8.5, '{"poet":"Pervin Cankaya","poet_slug":"pervin-cankaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/son-dans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellemeyin Beni', 'ellemeyin-beni-tunahan-ermihan-9jgjd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ellemeyin beni bu akşam hüzünlere saldım yüreğimi

Bir acı kahve içtim hatıralarımın elinden

Tadı damağımda kaldı bana geldiğin günün

Gidişlerindi fincanda kalan telve

Kapatmaya korktum gelişin çıkmaz diye

Ellemeyin beni bu akşam hüzünlere saldım yüreğimi

Bir damla yaş düştü gözlerimden

İçinde bir yerlerde sakladım her daim adını

Yıllara meydan okurken biz daha dün

Bir damla gözyaşı kırdı yıllık dalgakıranlarımızı

Ellemeyin beni bu akşam hüzünlere saldım yüreğimi

Raftaki yerine koydum son kez resmini

Adını hatırlamadığım bir mekândan hatıra

Yıllardan belki, belki dönmeyişinden sararıp

Sonbahar olan namımı kurutan

Ellemeyin beni bu akşam hüzünlere saldım yüreğimi

Son bir sigara daha yaktım kokusu boğazına ilmek acılarımın

Derin derin çekiyorum hasretini her nefeste

Bir adım daha yaklaşıyorsun üzerinde durduğum sandalyeye

Ve bu son nefes sevdiğim ben hüzünlere saldım yüreğimi

Sen cellâdı oldun aşk denilen yalanın', 'Ellemeyin beni bu akşam hüzünlere saldım yüreğimi Bir acı kahve içtim hatıralarımın elinden Tadı damağımda kaldı bana geldiğin günün Gidişle...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ellemeyin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TaNRILaR IRAK'' ta...', 'tanrilar-irak-ta-nusret-akbayir-2l8o1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bombalar yağmakta.. ardı ardına.. 

Mazlum.. Irak Halkının çatılarına.. 

Yarışıyor Tanrılar.. çıldırmışçasına.. 

Yillardır zulüm varken orada halka.. 

Eris.. durmadan senaryo yazmakta.. 

Enyo ise hep tepelerinde dolasmakta.. 

Fraude desen.. paslasmada Pitho''yla.. 

Diamos korku salar hep.. sokaklara.. 

Fama kulak vermezken Irak''ın Halkına.. 

Kairos bakar yanızca petrol hesabına.. 

Pentos karışmaz hiç yaşanan ızdıraba.. 

Penia, elini uzatmaz.. Irakli çocuklara.. 

Limos kol gezer aldırmazken açlıklara.. 

Algos kavuştu artık.. istediği ortama..

Hephaistos müşteri arar yeni silahlara.. 

Ares''e de gün doğar böyle zamanlarda.. 

Nike zaferi çok görürken o mazlumlara.. 

Themis firar eder bombalar patlayınca.. 

Nike ve Viktoria Vals eder.. hayasızca.. 

Neptün doymazken.. nedense istilaya.. 

Nemesis, Zeus''un kapısını çaldığında.. 

Lanet / ler yağar.. zalim tüm ilahlara.. 

Yeni bir sayfa açılır..  insanlık adına.. 

İnsanlık,ancak o gün yaşar insanca.. 

07/04/2003./n.a./ İzmir.

.', 'Bombalar yağmakta.. ardı ardına..  Mazlum.. Irak Halkının çatılarına..  Yarışıyor Tanrılar.. çıldırmışçasına..  Yillardır zulüm varken orada...', ARRAY['Türk Edebiyatı','Şiir','Nusret Akbayır']::text[], 8.5, '{"poet":"Nusret Akbayır","poet_slug":"nusret-akbayir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/tanrilar-irak-ta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırlangıç', 'kirlangic-aydan-yalcin-a3xjd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sarı iklimlerden kopup gelen

çatal kuyruk kırlangıç

haydi! 

kon / avuçiçine sessizliğimin

kon ki ellerim 

bir kuş olsun gökyüzünde / alaca

sis yüklü gecelerin sarnıcında

çürüyen bir eylül kadavrasına

dönüşürken zaman

aşk - ki dilimde nedense hep kekre bir tad bıraktığından

boz bir yılan olur hüzün

her gün boynuma biraz daha dolanan

ah! kırlangıcım bir bilsen

tutuyorum soluğumu / geceler kangren

kara bulutlarda suskun damlayım

patlayacak bir şimşek bekleyen

kuş kıyımı gecelerde 

acının çatlak aynasından silip 

duvar kağıtlarına çiziyorum yalnızlığımı

bel ver kırlangıcım

bel ver ki açılsın akşamın kanatları', 'Sarı iklimlerden kopup gelen çatal kuyruk kırlangıç haydi!  kon / avuçiçine sessizliğimin kon ki ellerim  bir kuş olsun gökyüzünde / alaca s...', ARRAY['Türk Edebiyatı','Şiir','Aydan Yalçın']::text[], 8.5, '{"poet":"Aydan Yalçın","poet_slug":"aydan-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kirlangic-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göçmen Kuşları! ...', 'gocmen-kuslari-ozan-si-ar-agdasan-i07d9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne zaman gurbet üzerine bir ezgi dinlesem; ne zaman ayrılık temasına bir eser yazsam, yüregimde fırtınalar kopar. Evet sevgili dostlar, kültür-sanat-edebiyat yaşamını göçmen olarak sürdürmek zorunda kalan bir ‘gurbet kuşu’olarak, hep ayrılık acısıyla şakıdım durdum,‘yaralı Turna’lar misali... Kimisi ekonomik, kimisi sosyal nedenlerden dolayı göç ettiler, yabancısı oldukları yaban ellere.... 

Kimimiz de, yaşanası bir memleket ve insanlığın boy verdiği bir dünya mücadelesinden dolayı diyarı gurbetleri boylamak zorunda bırakıldık! Dahası ‘sevgi, kardeşlik ve paylaşım’ gülleri nin katmer açtığı; dostluk ve barış bağımızda, memleket sevgi siyle, dostça ve insanca yaşamda özgürce şakımak istedik gök yüzünde korkusuzca uçan kuşlar gibi. Ama, heyhat kafese tıktılar dünyanın egemenleri! Evrende havayı bile parsellediler adeta. ‘Sevgi, dostluk ve kardeşlik kuşları’ uçmasın diye! Ama, boşunadır bu paslı kafesler! İnsanlığın sevgi, esenlik ve kardeşlik ateşini kimse söndüre

mez! O ateş, ‘yakanı da’ yakar! Güzel bir halk değimi var: Biri yer, biri bakar; kıyamet ondan kopar! 

Ayrılık üzerine bir şiir yazdığımda, sazın perdelerinde, sesin nağmelerinde besteye döktüğümde notalar uçuşur, alır beni götürür doğduğum yerlere. Bendine sığmaz; sel olur akar nehirlere! 

Dalar giderim, Özlemden yaralarımı dalayarak! Ayrılık, hasret şarkılarımı sulayarak! ... 

Gönül garip, yar garip,yaran garip... 

Halk Müziğimizde ve seçkin edebiyatımızda ifadesini bulduğu gibi: 

Ben garip eşim garip, eşim yoldaşım garip. 

Öldüğüme gam yemem, mezarda taşım garip! ... 

Dert bende, yara bende 

Eğlenmez yara bende 

Yuvasız kuşlar gibi 

Kalmışam perakende! ... (Anonim)    

Göçmenlik teması üzerine farklı yaklaşımlar var: Doğduğun yer mi önemli, doyduğun yer mi? diye. 

Bir kesim dostlar,ustalar ‘Doğduğum yer önemlidir’ der. Diğer bir kesimi de ‘doyduğum yer’ derler.. 

Oysa, bana göre her ikisi de biribirini tamamlar. Kuru toprak ve taş parçasının İnsan cinsini mutlu ettiği görülmemiştir. Ama, İnsanlık Mücadelesinin Hekimleri; sadece işkembenin dolmasıyla, maddi olanaklarla tek başına mutluluk reçetesini yazamadılar henüz! ... 

Göçmenler, kendi ülkelerinde döviz makinesi olarak görüldüler; yaban ellerde de’ yabancı’, Ausländer (Yabancı)       denerek hor 

landılar. Özlem ateşiyle yanıp, korlandılar! ... 

Hatta, şöven, ırkçı güçlerin ve politik rantçıların seçim malzemesi, kimi sözde bazı demokrat geçinen çevrelerin de kariyer aracı oldular! ..Değerli üstadımız, sevgili Ozan ŞAH TURNA Hocamızın çeşitli dillerde yayımlanan güzelim bir yapıtı ile süsleyelim temamızı: 

AUSLÄNDER (YABANCI)      ADIMIZ! ..

Onlar diyor, çekin gidin 

Hani senin yurdun işçi 

Bunlar der sakın gelmeyin 

Hergün artar derdin işçi! 

Para kazanmaya geldin 

Döviz makinesi oldun 

Sor kendine ne gün gördün 

Hani senin yurdun işçi? 

Avrupada yabancısın 

Öz yurdunda almancısın 

Eğik başın, kısık sesin 

Her gün artar derdin işçi? 

ŞahTurna der adım adım 

Yaşamadım,hep yaşattım 

Memleketsiz kaldı adım 

Hani senin yurdun işçi 

Hergün artar derdin işçi! … 

Söz ve Müzik: İnt. Kadın Ozan ŞAH TURNA (Aşık ŞAHTURNA)     

BİR YUDUM SEVGİ, BİR YUDUM EKMEK ve BİR YUDUM SU! .... 

Sevgisiz bir yürek taştır. Duygusuz bir beden robottur. Kuru, soyut ideolojik görüş ve yavan bir vatanseverlik ise, insanı yakan ataştır! ... Kuru nutuklar ve katı şablonlar zemin bulama maktadır artık, insanlığın uyanış sürecinde! 

Son tahlilde mesele, can feda edilen amaçlarda; kimlerin insanca yaşayıp yaşamadığı, kimilerin se devran sürdükleridir. Belli değerleri, fikirleri ve inançları ranta dönüştürenlere karşı da uyanık olunmalıdır... 

Kirlilerin başa çekildiği, temizlerin de taşa çekildiği çelişkili, isli-puslu dönemi yaşıyoruz ne yazık ki! .. 

İnsani değerlerde, sevgi, hak ve hukukla ekilmiş bir yurt topra 

ğında vatan parçası bir anlam kazanır. Sevgi ve sanatla nakış nakış süslenmiş, dostluk, umut ve paylaşımla bezenmiş kilimlerde donanmış dava ve inançlar ulvileşir, yücelir ancak. 

Gerisi,beyhude çırpınış, kara figan ve kasap doktorların elinde kurtuluş değil; bilakis can çekişmedir! Olsa olsa, yek diğeriyle ‚yan çekişmedir’. Böylesi devasa sürgit devam ettiği sürece, karanlıklarda sökecek şafaklar ‚tan’çekişmedir... 

Ama, herşeye karşın umut çiçeklerimiz açıyor, açacak. Hergün biraz daha serpilmiş ve renklenmiş olarak. 

YÜREKTE '' YURTSUZ'' OLANLAR... 

Evet, yaban elde yabancı‚ ''göçmen’ olmak bir acıdır, hatta kanayan yaradır dostlar. Ama, yürekte’ ve ‚erekte’ gurbeti ve yabancılaşmayı yaşamak ise; daha dramatik ve acınası bir haldir! .. 

EREKTE ‚YURTSUZ’ OLANLAR! ... 

Sılasında gurbet, doğduğu yerler 

Öz yurdunda Yurtsuz OLAN Garipler 

Hasret yurdu olur, doyduğu yerler 

Ömrü yaban elde TALAN Garipler! 

Kimse bilmez, nedir,nasıl ahvali? 

Yüreğimi dağlar ‘o mazlum’hali 

Anasız- babasız ‘öksüz’ misali... 

Hicran,boynu bükük KALAN Garipler 

Düzenbaz kağnısın dağdan aşırır 

Garip olan dümdüz yolda şaşırır 

Şiar, çağlayan su, deniz taşırır 

Çiğnenip,gülleri SOLAN Garipler… 

Söz ve Müzik:ozan ŞİAR      Yorum:Aşık ŞAHTURNA

Yaşadığımız coğrafyalarda ve yüreklerde gurbet ve özlem 

lerin olmadığı, ereklerde güllerin solmadığı bir yaşam adına; karanlıkların inadına! 

Sevgiyle, dostlukla kalın. Umudunuz solmasın sevgili dostlar! ... 

Ozan ŞİAR Can Sanatçı, Yazar, Öğretim Görevlisi 

ŞAHTURNA Kültür ve Sanat Evi 

www.siarcan.com [email protected] 

Not: Sevgili Şiir ve yazın dostları, buraya aktardığım bu makalemiz ve şiirimiz bir çok yayınevlerinde, gazete ve dergilerde yayınlandı. Köşe yazarlığında başlığım olan: CANA CANA adıyla...Bir çok müzikal albümlerimizde ses getirdi...! 

Ayrıca, katkılarını ve paylaşımını esirgemeyen değerli kadın üstadımız, seçkin sanatçı ve yazarlarımızdan Aşık ŞAHTURNA Hanımefendi''ye şükranlarımı, kalbi saygı ve sevgilerimi sunuyorum. Ki, bir çok ölümsüz eserlere imza atan, ''insanlık davasında'' pek çok ağır bedeller ödeğen, mum gibi yanıp; karanlıklara, insanlığa ışık saçan bu uluslarası değerimiz, simgeleşmiş Kadın Halk Ozanımız, güzel insan Aşık ŞAH TURNA üstadımızın şiirlerini, nakış nakış işlediği güzelim bestelerini ve özlü-değerli yazılarını.. siz sevgili dostlarla paylaşmaktan kıvanç duyuyorum... 

Dostlukla...Ozan ŞİAR Ağdaşan   Sanatçı, Yazar, Öğretim Görevlisi

Vokal, Türkçeden Almanca''ya çeviri: ŞAFAK ve ŞİRİN AĞDAŞAN Enternasyonal Sanat Grubu    www.sahturna.com   www.siaracn.com', 'Ne zaman gurbet üzerine bir ezgi dinlesem; ne zaman ayrılık temasına bir eser yazsam, yüregimde fırtınalar kopar. Evet sevgili dostlar, kült...', ARRAY['Türk Edebiyatı','Şiir','Ozan ŞİAR Ağdaşan']::text[], 8.5, '{"poet":"Ozan ŞİAR Ağdaşan","poet_slug":"ozan-si-ar-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/gocmen-kuslari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-alim-vedat-suner-eizfs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '…..bir parça

…..…..ve bir parça daha ardı sıra…

…..…..…..kopuyor yaprak yaprak düşlerim

…..…..…..…..akıp gidiyor seninle

…..…..…..…..…..gitmeden önce düşünseydik keşke

…..bir adım

…..…..ve bir adım daha üstüne

…..…..….. kayboluyor gölgen

…..…..…..…..akıp gidiyor yollar önünde

…..…..…..…..…..yok olmadan gölgen dönüp baksaydın keşke 

…..bir hayat

…..…..ve bir hayat daha yitiyor işte

…..…..….. kolay sandığın ayrılık, ağır bu yüreğe

…..…..…..…..eriyip yok oluyor hayallerim 

…..…..…..…..…..bitmeden önce düşünseydik keşke', '…..bir parça …..…..ve bir parça daha ardı sıra… …..…..…..kopuyor yaprak yaprak düşlerim …..…..…..…..akıp gidiyor seninle …..…..…..…..…..gitm...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/keske-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttum İşte', 'unuttum-i-ste-alim-vedat-suner-egiok', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ellerim arasında sıkıştırdığım bu zehir

Bu acı tat kavuruyor boğazımı…

Unuttum işte…

Geçmişten kalan ne varsa

Unuttum hepsini bir nefeste…

Çektikçe dönüyor başım

Uzandığım bu toprak

Seyrettiğim bu gökyüzü

Daha da yaklaşıyor göğsüme

Hadi gelin

Sizde yatın benimle

Unutmak adına ne varsa

Yapacağım bu gece…

Bir nefes daha çekiyorum

Çektikçe kısalıyor “cigaram”

Ve her nefeste unutuyorum geçmişi…

Biraz daha..

Biraz daha…', 'Ellerim arasında sıkıştırdığım bu zehir Bu acı tat kavuruyor boğazımı… Unuttum işte… Geçmişten kalan ne varsa Unuttum hepsini bir nefeste… Ç...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/unuttum-iste-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidene', 'gidene-mustafa-sekerci-q91ax', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Suçlu sensin dedin ya giderken.

Doğru söyledin leyli yar.

Bendeydi suç.

Çünkü ben seni 

Yaşadığın  şehrin kaldırım züppeleri gibi 

Allı pullu sözlerle değil 

Sinemi parçalar gibi çarpan

Şu çocuksu yüreğimle sevdim.

Çünkü ben seni

Kavgam kadar sevdim

Namusum kadar.

Nasır tutmuş ellerim gibi kaba olsada

Yama dağı gibi ulu

Fırat suyu gibi coşkulu

Alnımdaki ter gibi berrak 

Anamın temiz sütü gibi ak sevdim

Kuru kuruya gitmek sana yakışmaz

Giderken

Ekine vurduğum tırpan gibi

Dibinden biçte git umutlarımı

Bir daha yeşerip boy atmasın başka baharlara

Kökünden kopar yüreğimdeki tomurcuk karanfili

Tohuma durup yeniden açmasın

Kırda git kanatlarını ak güvercinlerimin

Bir daha havalanıp uçmasın.

Git...

Beni bir başıma

Beni sensiz 

Beni bensiz bırakıp git

Yalnızlığımı kökünden dinamitleyip

Dağ gibi üstüme yıkarak git..

Öyle git ki..

Bir daha asla dönüşün olmasın.

Öyle git ki

Bu adam belini bir daha doğrultamasın.', 'Suçlu sensin dedin ya giderken. Doğru söyledin leyli yar. Bendeydi suç. Çünkü ben seni  Yaşadığın  şehrin kaldırım züppeleri gibi  Allı pull...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şekerci']::text[], 8.5, '{"poet":"Mustafa Şekerci","poet_slug":"mustafa-sekerci","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gidene-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyalanıyorum', 'oyalaniyorum-gokhan-oflazoglu-e6h9b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sonsuzca anlatacaklarım var,

aynı şeyler üstüne, sizin de,

onun da. Bazen ağzımda bir

hayat çiğniyorum, acı bir tat

veriyor, bu kadar zengin,

bu kadar dar. Aynı çemberin

içinde dört dönüyorum, boğazıma

bir hıçkırık tıkanıyor. Üstüme

yıkılan hayattan bunalıyorum.

Önemli bir gerekçem yok,

hep gidip, gene dönüyorum.

Dört yanım daralıyor, ölümle

oyalanıyorum; seviyor, okşuyor,

sizden uzak olsun da diyorum.

12/11/2004', 'Sonsuzca anlatacaklarım var, aynı şeyler üstüne, sizin de, onun da. Bazen ağzımda bir hayat çiğniyorum, acı bir tat veriyor, bu kadar zengin...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/oyalaniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açtın ki solasın', 'actin-ki-solasin-sair-ahrazi-mgb3k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlere can da versen,ten rengisin hem betim,

Hem de çekip gidensin can vermeden heybetim.

* * *', 'Gözlere can da versen,ten rengisin hem betim, Hem de çekip gidensin can vermeden heybetim. * * *...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/actin-ki-solasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hükümdar', 'hukumdar-guler-ilgaz-ic6vp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seviyorum  geceleri

Gebe  bir  kadın  gibi

Seçmiştim

Kararımdı

İçimde bir  kapı  açılacaktı

İçinde  yargı  yok...  yorum  yoktu

...............

O  bir  yanda

Ben  bir  yanda.....

Sevgiyle   bağlanıyorduk

BİRBİRİMİZE

Bir  şafak  vakti  gibi

...............

Seviyorum  işte  öylesine

İçimde  yıldız   yıldız...

Gecelerimi  doğurmak  için  yeniden

Sarıp  sarmalamak  sarmalanmak  için

GÜN    IŞIĞINDA...

...............

Gecelerimi   bekliyorum

Gebe  bir  kadın  gibi

Seçmişim... seçilmişim

HÜKÜM    ANINDA', 'Seviyorum  geceleri Gebe  bir  kadın  gibi Seçmiştim Kararımdı İçimde bir  kapı  açılacaktı İçinde  yargı  yok...  yorum  yoktu ...............', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hukumdar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giyinin üzerinize...', 'giyinin-uzerinize-mutlu-ayar-gdbwb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çıkmaz sokakların kendinden koyu gizliliği

üzerimde duruyor, üzerim? evet üzerimde

sakınarak bulutlardan ve yağmura hasret

kaktüs oluyor dudaklarım öpüşmekten

örümceğim odamda, gizim onun için gerçek 

tek tek soluyorum yalnızlığı gözlerimde

biliyorum ölüm bile böyle yalın geçecek

kumul oluyor ruhum bir okyanus dibinde

size ne! demem, desem yazmazdım şimdi

açtım şiirleri, sevdiğim kadınlar can çekişiyor 

sonsuz aşk olamaz asla çıkık bir kemik

güneş içinden düşünüyor penceremin önünde

karanlığa bırakmayın beni yapışıyor içime

derinlerde dolaşıyorum bir serzenişin eliyle

üzerimde duruyor, üzerim? evet üzerimde

üzerime gelmeyin üzerim yapışır size

çünkü her yere değen rüzgarı yalıyorum

her seferinde, rüzgarlığınızı giyin üzerinize

yapışır-üzerim-üzerime gelmeyin deliyim

gelmeyin, deliyim, yapışır üzerime-üzerim

hep giyindiğiniz uzaklığı yine giyin üstünüze…', 'çıkmaz sokakların kendinden koyu gizliliği üzerimde duruyor, üzerim? evet üzerimde sakınarak bulutlardan ve yağmura hasret kaktüs oluyor dud...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/giyinin-uzerinize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mayakovskinin Valizi', 'mayakovskinin-valizi-yasar-dogan-s34ct', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sıcak göz yaşlarımız

Mavi gölün akşamlarında

Kendini hep saklar 

Elleri ve gözleriyle

Tutuşunca içimizdeki ruhlar 

Bir o yana yıkılır 

Bir bu yana kader

Yüreksiz  yaşamak

Bize göre değil bir tanem

Bir asır daha

Ölüp yaşamak gerek

Gel bizde bu göz yaşlarımızı

Mayakovskinin valizine koyalım

O gitsin 

Biz biraz daha

Yanyana oturalım 

Yaşar doğan  / Lolan	12/11/04', 'Sıcak göz yaşlarımız Mavi gölün akşamlarında Kendini hep saklar  Elleri ve gözleriyle Tutuşunca içimizdeki ruhlar  Bir o yana yıkılır  Bir b...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Doğan']::text[], 8.5, '{"poet":"Yaşar Doğan","poet_slug":"yasar-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mayakovskinin-valizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O; Sen Değilsin Sevgili / ss-24', 'o-sen-degilsin-sevgili-ss-24-nesrin-gocmen-ty6ma', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen değilsin, sevmeyi bilmeyen,

Sen değilsin, sevdayı yürütemeyen.. 

Biri varsa, varsa böyle biri, 

O; sen değilsin, değilsin sevgili...

Benim sevda çiçeği olamayan; 

benim gönüllerde açamayan... 

Benim dağlarımda, mevsimler değişmez,

gelmez ne yaz, ne ilk, ne de sonbahar.. 

Hep kıştır benim dağlarım.

Yağan tipi, kar; esen boradır 

benim dağlarımda sevdiğim.. 

Bağlarım çoktan yeşili unutmuş; 

börtü, böcek, kuşlarla, 

zamansız bozulmuştur benim..

Göklerimde güneş doğmaz,

yıldızlar ışıldamaz.

Bulutlar dolanır, 

grilerin ardındaki saklı maviyi unutturan,

gülümsemeyi bilmeyen bulutlar.

Ne sunabilir  böyle biri sunağında?

Sevda ağlarıyla seni,

bağrında saramayan biri 

ne verebilir sana sevgili? 

Hüzün, hüzün; ve hüzün kere hüzün.... 

Dinle, bak şu sese! 

Masmavi bir buz..

Üşüyorum, üşüyorum sevgili.. 

Oysa bir zamanlar ben,  sıcaklığında erirdim o sesin.

Bu ise hakkıma düşen,  budur hakettiğim,

sen aldırma, üzülme sen sevdiğim..

Şimdi sakın deme bana, 

''hala seviyorum''.. 

Deme ''özlüyorum seni''.. 

''hayalini gözlerimde tutuyor; 

 sevgimlesin, sevdiğimsin'' 

deme; deme bana sevgili..

Hiç birşey deme sen;  sus! 

Sadece sus, sen söyleme....

(sen söyleme-24)          

11/11/2004', 'Sen değilsin, sevmeyi bilmeyen, Sen değilsin, sevdayı yürütemeyen..  Biri varsa, varsa böyle biri,  O; sen değilsin, değilsin sevgili... Ben...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/o-sen-degilsin-sevgili-ss-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Bayramlar', 'eski-bayramlar-aynur-i-lkay-6mddo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gunlerce ev temizlenir piril piril temiz

	Durmadan calisip yorulmustur annemiz

	Tebessumle karsilanir misafirlerimiz

	Ah o mazide kalan tatli bayram gunleri

	Camlar,tahtalar silinir,badana yapilir

	Camasirlar yikanir yataklar attirilir

	Halilar silinip,bakir mangal parlatilir

	Ah o mazide kalan tatli bayram gunleri

	Yapilir yemek,borek,tatlilar baklavalar

	Bizden cikolata sekerleme saklamalar

	Gelen es dostlari yurekden kucaklamalar

	Ah o mazide kalan tatli bayram gunleri

	Cocuklar giyinirler cicek gibi rengarenk

	Mahallede meydana gelir tatli bir ahenk

	Butun her sey tam manasiyla birbirine denk

	Ah o mazide kalan tatli bayram gunleri

	Oyun havalari,turkuler radyoda calanir

	El opene vermek icin mendiller alinir

	Cocuklar kayik salincaklarda sallanir

	Ah o mazide kalan tatli bayram gunleri

	Bayram namazindan sonra bayramlasilir

	Kabristana gidilir cantada enam tasinir

	Hediyeleri bir kac damla goz yaslaridir

	Ah o mazide kalan tatli bayram gunleri

	Huzurla donulur eve gerisin geriye 

	Akrabalara hazir bir kac kucuk hediye

	Kirginlar barisir cekilir cok sey sineye

	Ah o mazide kalan tatli bayram gunleri

	Kurban bayraminda kestirilir kurbanlar 

	Yoksulun halinden bazilari cok iyi anlar

	Iste butun bunlar yapilirdi bir zamanlar

	Ah o mazide kalan tatli bayram gunleri

	

	Aynur Ilkay

	19 Nisan 1997

	Toronto,Ont.

	Kanada', 'Gunlerce ev temizlenir piril piril temiz 	Durmadan calisip yorulmustur annemiz 	Tebessumle karsilanir misafirlerimiz 	Ah o mazide kalan tatl...', ARRAY['Türk Edebiyatı','Şiir','Aynur İlkay']::text[], 8.5, '{"poet":"Aynur İlkay","poet_slug":"aynur-i-lkay","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/eski-bayramlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Oldu', 'bayram-oldu-aynur-baydar-0dhdp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Veren el, alandan çok oldu

Açın karnı doydu

Öksüzün yetimin başına

Şefkatle bir el dokundu

Yaşasın BAYRAM OLDU

Savaş kin hırs ego

Toprak oldu

Olgunluk, hoşgörü sevgi çoştu

Yollara bakan ihtiyar gözler

Evlatları görünce yaşla doldu

Yaşasın BAYRAM OLDU

Bu gün bir başka güzel doğduysa

Sevinç huzur telaş karışık

Erkenden kalkıldıysa

El öpen çocukların

Yanakları şekerle şiş olduysa

Bayram parası alındığında

Gözler afacanca parladıysa

Evlere misafir, şekerliklere şeker

Kinler geçer, birleşirse gönüller

Yalnızlık değilse, yaşlı kader

Bavullarını toplayıp giden 

Tatilse eğer 

Gelirse sıcacık ziyaretler

Oldu ki ne oldu

İşte şimdi

Yaşasın BAYRAM OLDU



Antolojide sürekli yer alan, yada geçerken şöyle bir uğrayan herkesin bayramını kutlarım.

Saygılarımla', 'Veren el, alandan çok oldu Açın karnı doydu Öksüzün yetimin başına Şefkatle bir el dokundu Yaşasın BAYRAM OLDU Savaş kin hırs ego Toprak old...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bayram-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Baharsın Sen', 'bir-baharsin-sen-huseyin-erdogan-cb9q8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'rengarenk açan bir baharsın sen

çiçeklerin farklı kokar herkesten

bir meltem yelisin tatlı tatlı esen

haydi ne olur kırma beni

seni görmek istiyorum ömrüm bitmeden

insan sevebiliyormuş meğer

bir kez bile görmeden

inan ki mutlu yaşar ebediyen

sana yürekten gönül veren

gel yakışıklı şairim de bana

ben de telefonda olsa da

öyle alıştım ki sana

sensiz yapamıyorum artık

dünyam şimdi seninle

pırıl pırıl bir başka aydınlık', 'rengarenk açan bir baharsın sen çiçeklerin farklı kokar herkesten bir meltem yelisin tatlı tatlı esen haydi ne olur kırma beni seni görmek i...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-baharsin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Vur Emri!', 'vur-emri-kemal-sume-z9had', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Emir, demiri keser... 

Demir kesilir, 

Yürek pas tutar... 

Onulmaz bir yaradır, 

Umursamaz gidişin. 

Keskin düşer; yuvarlak dudaklardan 

..................................cümleler... 

Atılan birer kurşundur... 

Vur emridir; 

Deler geçer... 

10,06,2004', 'Emir, demiri keser...  Demir kesilir,  Yürek pas tutar...  Onulmaz bir yaradır,  Umursamaz gidişin.  Keskin düşer; yuvarlak dudaklardan  ......', ARRAY['Türk Edebiyatı','Şiir','Kemal Süme']::text[], 8.5, '{"poet":"Kemal Süme","poet_slug":"kemal-sume","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/vur-emri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arada bir', 'arada-bir-murat-demir-rna8p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaman sevdamızı heder etmeden 

Şu zavallı beni dert tüketmeden 

Can denen bedenden çekip gitmeden 

Arada bir gelip sorsan olmaz mı? 

Eriyen buzların damlası gibi 

Nisan yağmurunun yağması gibi 

Güneşin batıp ta doğması gibi 

Arada bir bulup sarsan olmaz mı? 

Daha zaman varken yanmadan için 

Dilde söz olmadan nedenle niçin 

Gönül zincirini aşkımız için 

Arada bir tutup kırsan olmaz mı? 

Gözlerime bakıp demeden ama 

Dertler yüreğime olmadan yama 

Çağlayanlar gibi sensiz dünyama 

Arada bir akıp dolsan olmaz mı?', 'Zaman sevdamızı heder etmeden  Şu zavallı beni dert tüketmeden  Can denen bedenden çekip gitmeden  Arada bir gelip sorsan olmaz mı?  Eriyen ...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/arada-bir-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Bir Gün', 'belki-bir-gun-huseyin-erdogan-u2ql9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'telefonuma yanıt vermeyince

bir hüzün sardı yüreğimi birdenbire

bilmem ki! 

çiçeğim bana neden küstün böyle

ne olur canım söyle

bir gün yeniden açar mısın gönlümde? 

sen kalbimde çağlayan sevgimsin

damarımda akan nehirimsin

bütün mevsimler yaz olsa da

her yeri kuraklık sarsa da

aşkın beni cayır cayır yaksa da

hasretin acımasızca boğsa da

yargıçlar beni dar ağacına assa da

Bil ki

kurumayacaksın asla 

ölünceye değin', 'telefonuma yanıt vermeyince bir hüzün sardı yüreğimi birdenbire bilmem ki!  çiçeğim bana neden küstün böyle ne olur canım söyle bir gün yeni...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/belki-bir-gun-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Başlar Yazı', 'nasil-baslar-yazi-akin-umut-gurel-rywek', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasıl başlar yazı bazen bilemiyorum.....

Nasıl biter....

Başlayan umarsız bir çırpınışa ne kadar teselli verebilir kelimeler....

Yaşam nerde.....

Ben yaşamın neresindeyim,neresiyim.....

Kapılmış gidiyoruz.....

Bilmediğimiz, görmediğimiz düşsüzlüğümüze gidiyoruz....

Düşsüzlüğümüzün en dibine düşüyoruz....

Dipteyiz........

Korkuyoruz.......

Üşüyoruz......

Kimilerine göre hayatı; 

Başkaları içinse karanlığı bölüşüyoruz........

Nasıl başlar yazı bilemiyorum......

Nasıl biter......

Kahkahaların burukluğuna üzülürken; 

Bir de bakmışız burukluk yüzümüzde......

Burukluk.....

Peşi sıra gelen buruşukluk......

Nasıl başlar hayat bilemiyorum.....

Nasıl biter.......

Zaman akar....

Yaşam gider....

Yaşlılık gelir aniden.....

Kurarken yaşlılığa isyankar cümleler; 

O da seni terkeder.....

Gelen koca bir karanlık....

Bitişe atılan son imza....

Son çığlık.....

Son kahkaha.......

Etraf kapkara......

Nasıl başlar ölüm bilemiyorum.....

Nasıl biter......                                        

                                 Ankara-2004', 'Nasıl başlar yazı bazen bilemiyorum..... Nasıl biter.... Başlayan umarsız bir çırpınışa ne kadar teselli verebilir kelimeler.... Yaşam nerde...', ARRAY['Türk Edebiyatı','Şiir','Akın Umut Gürel']::text[], 8.5, '{"poet":"Akın Umut Gürel","poet_slug":"akin-umut-gurel","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/nasil-baslar-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-bayram-tunca-xuup7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Keşke, şairlikle daha önce tanışsaydım

Her okuduğumu şair edasıyla okuyorum

Her gördüğümü şair gözüyle bakıyorum

Her duyduğumu şair hissiyle dinliyorum

Keşkem seninle daha evvel tanışsaydım

Belki hayat daha zevkli olurdu tahminim

Çünkü sendin ilk ilham kaynağım benim

Ne ilham almayı, ne sevgini doyamadım

Tüm okuduklarımı yeniden okumak istiyorum

Dokunduklarımı yeniden dokunmak istiyorum

Hayatı yeniden şair olarak yaşamak istiyorum

Çünkü her şeyi şair gözü kulağıyla algılıyorum

11.11.2004-11.11', 'Keşke, şairlikle daha önce tanışsaydım Her okuduğumu şair edasıyla okuyorum Her gördüğümü şair gözüyle bakıyorum Her duyduğumu şair hissiyle...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/keske-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntihar -2', 'i-ntihar-2-sule-aydemir-b8ry6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'temizlendi

bir bebek tuttu ellerinden

hüzünlüydü

sevgileri düşmüştü ömründen

ölü yıkıyordu düşleri

bütünün parçası değildi 

anlamını yitirdi yaşam

kucakladığı gibi

bıraktı kendine uçurumunu

...



*kalemi gönülden mürekkepli kadının günlüğünden 

10.11.2004'' de', 'temizlendi bir bebek tuttu ellerinden hüzünlüydü sevgileri düşmüştü ömründen ölü yıkıyordu düşleri bütünün parçası değildi  anlamını yitirdi...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/intihar-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filistin Çınarı', 'filistin-cinari-mehmet-halil-o2ohv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yıllarca, 

yıkmak ve yakmak için çalıştıkları. 

barut ve yanık kokusuyla beslenen, 

koca bir çınar devrildi. 

ve tabiatın, 

karakterinde bulunan, 

yeni tomurcukların, 

uyanma zamanı geldi. 

her karanlığın ardından beklenen, 

yeni bir aydınlık gibi.', 'yıllarca,  yıkmak ve yakmak için çalıştıkları.  barut ve yanık kokusuyla beslenen,  koca bir çınar devrildi.  ve tabiatın,  karakterinde bul...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/filistin-cinari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehid''e...', 'sehid-e-kadir-soyturk-400ba', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ş  ahid   sana  yaratan, şahid  onun   kulları

E  linde davetiye  katettin  çok  yolları! 

H  ayatı  fırsat bildin  şehadet rütbesine

 İ  nanan herkes  gelir  peşin  sıra,sesine.

D  enmez  şehide   ''ölü'', bu hakkın  kanunudur

E  limize  geçecek  en  yüce makam budur!', 'Ş  ahid   sana  yaratan, şahid  onun   kulları E  linde davetiye  katettin  çok  yolları!  H  ayatı  fırsat bildin  şehadet rütbesine  İ  na...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sehid-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğitim', 'egitim-mehmet-halil-rxhat', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'eğitim bir silahtır, hedef aydınlık, 

öğretmen namludur, görevi kılavuzluk, 

öğrencinin, görevi hedefe ulaşmak, 

çekirdekle namlu, ne kadar uyumlu, 

o kadar kolay olur hedefi vurmak.

silahsız değiliz, iyi güzel de, 

bir soru var kafamda, çözemediğim, 

acaba silahlar, kimin elinde? 

Niye bakımsız, umudum, sevdiğim.

Hedefler mi birbirine karıştı ne? 

Ben aydınlık istedim, ölüm istemedim.', 'eğitim bir silahtır, hedef aydınlık,  öğretmen namludur, görevi kılavuzluk,  öğrencinin, görevi hedefe ulaşmak,  çekirdekle namlu, ne kadar ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/egitim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Oyali *', 'oyali-gulsen-senderin-8858u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dağlık bir köy evi, taştan duvarları damında kili

Tabanı toprak, tavanında mertekler, kireç boyalı

İlk doğum sancıları, aileler erkek istiyor ille ki

Pazartesi, yirmidört kasım bin dokuzyüz elli iki

Akşam üzeri yağmur çiselerken doğmuşum

Ben de ağlamışım doğarken, ebem MERYEM ANA

Kesti göbek bağımı aldırmadan akan kana

Esmer mini mini bir kız, nefes almaya adalı

Belemişler, yemenim kundağım kuşağım tığ oyalı! 

Güneş ışımakta,  fırtınalar gençlik savurur

Açmak ister dallardaki renk tomurcukları

Harman yeri, elimde yaba her taraf toz duman

Ilk yaşadığım bir olgu: Genç kız olmuşum! 

Tokatladı anam; yanaklarım al al olsun diye

Saçları örgülü'' bir köylü kızı'', vahşi yaşamlı

Yetişiyordu şimdilerde, düzülecekti çeyiz sandığı

Örülecekti şemeler, danteller ele geçen parayla

Örtüler tığ oyalı, ipekten mendilim iğne oyalı! 

Bir ilkbahar sabahı,  yeşile uzanırken sevgiler

Sevdaların en temiz safını hasını düşlemişim

Kalbimde ilk uyanış, yüreğimde kor umutlar

Vurgun yemişim! Kor ateşlerde kaldı yandı bu can

Çözemediğim bir yanılgı,ayrılığı tatmışım

Uyku yok yenmez oldu yemek, geçmez oldu zaman

Yara aldı ''GÜLDAMLASI'' olmuştu gönül bağı viran

Adetler töreler süregelsin diye oyalıyorlar

Teselli ile oyalandı gönül, oyam zaman oyalı! 

Bir sevgi ister can, açmak ister açmayan goncagül 

Kabullenmiş evlenecekt,i sevgiye kırılgan gönül

Eşini kendi seçti, kuruldu dernek düğün

Geleceklere umutlu, gelin oldu telli duvaklı

Adında...ŞEN soyadında ŞEN... Şenli dualı

Tek tek açıldı bohçalar, şemeler sargılar örtüler

Kolalanmış kar beyaz çarşaflar, odam ''ŞEN'' oyalı! 

Yaşam bu muydu, çileli miydi her mutluluk

Ulaşan olmuş muydu ki o kor yeşile, ya o köylü kız...

Bitmişti yaşam;  kayıyordu işte yine bir yıldız

Bilemezsiniz sevgiyi mi bölüştü, aşkı mı buldu

Baharların bahçeleri;  hep güllü hep bülbüllü

Bilinmez ki;  kim ne zaman, ve kim kaç yaşında? 

Gidiyordu işte cenaze, sorgusu musalla taşında

Gidiyordu o meçhule, giriyordu mermer bahçeye

Ne dantel oyalı, ne zaman oyalı, mermer bahçe TAŞ OYALI!', 'Dağlık bir köy evi, taştan duvarları damında kili Tabanı toprak, tavanında mertekler, kireç boyalı İlk doğum sancıları, aileler erkek istiyo...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/oyali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vahşice Felluce', 'vahsice-felluce-ekrem-sama-1j9hd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kadir, Cuma, Arefe ve Bayram,

Kan buharlanıyor buram buram,

Nasıl zalimlerle karşılaştık,

Duadayken sürüyor katliam.

Gazze, Kudüs, Telefar, Felluce,

Yakılıyor, kahbece, vahşice.

Yıllardır durmadı akıyor kan,

Ne bayram, ne gündüz, ne de gece.

Birbirimizden kestik selamı,

Bilin, bu Allah’ın intikamı,

Rabbim neslimize göstermesin,

Bu günkü gibi bir katliamı...

(İstanbul:12.11.2004)', 'Kadir, Cuma, Arefe ve Bayram, Kan buharlanıyor buram buram, Nasıl zalimlerle karşılaştık, Duadayken sürüyor katliam. Gazze, Kudüs, Telefar, ...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vahsice-felluce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...İnayet...', 'i-nayet-naime-erlacin-zsh1d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yüz sürüyor keşişler cebbarın eteğine

bayrak semirtiyor kuytuda haramiler

kimse duymadı daha

tezyin edilmedi kader

mor hüznüne ağlıyor bir derviş

nefsini çitiliyor dergah kapısında

son efsun

amel zamanı

bana bağışlama dostum inkisarını

paslı mavzerler gibi sustum bak! 

kandiller yaktım kurumuş ırmağına

inayetti dileğim ebabil kuşlarından

dön rabbine ve ağla! …

(11 Kasım 2004)', 'yüz sürüyor keşişler cebbarın eteğine bayrak semirtiyor kuytuda haramiler kimse duymadı daha tezyin edilmedi kader mor hüznüne ağlıyor bir d...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/inayet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyku', 'uyku-naime-erlacin-ssqjb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ayrık otuyum

nasırımdan armağan

geldiğim yollardan 

geri döndüm çok kere 

ne bir akrep, ne barut 

güldü seçtiğim

uykudaydınız

ölüme verdim özgürlüğü

boş kovanlar düşüyordu üzerinize 

(11 Kasım 2004)', 'ayrık otuyum nasırımdan armağan geldiğim yollardan  geri döndüm çok kere  ne bir akrep, ne barut  güldü seçtiğim uykudaydınız ölüme verdim ö...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/uyku-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yiğit', 'yigit-kenan-eren-5r4x7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yiğitlik mertebesine erişmek... Tek başına meydan okumak bütün yaradılışına inat.

Ve isyankar bir yürek.

Bir annesi görmüştü onu ağlarken; Sabahın en tatlı uykulu yerinde ve herkes uyurken...

Bir tas suya hasret yüreği ve Pişmanlığın bitmişliğin devingen olmuş hayatın çilesiyle.

Ellerine yapışan kan ve barut; Ellerini saran kelepçe ve her yediği hain darbelerin izi.

Bir tek annesi görmüştü onu ağlarken; Sabahın en tatlı uykulu yerinde ve herkes uyurken.

Çıka gelmişti kader... Yine o vakitlerde  ve nice gecelerde yatak olan o sokakların bir köşesinde ve yine hain darbelerle....

Elleri tertemizdi bu kez...Kana bulamışlardı belkide ilk defa giydiği ama en sevdiği elbiselerini.

Yaklaşan bayramın sevinci o sönük gözlerde öylece kalıverdi.

Kaç yeğen bırakıp öylece gitmek sırdaş olduğun, ilk gözyaşını sineye çeken topraklara.

Belkide  çok güvendiğin o nemli pusulu gökyüzüne, usulca sokulmak istedin...

Yolun açık olsun.

*******************************************************************

k.eren

BİR SELAM  O DİYARA BİZDEN ÖNCE GİDENLERE.

29.10.2004/ Ş.ANIL anısına (yiğit Dayım)', 'Yiğitlik mertebesine erişmek... Tek başına meydan okumak bütün yaradılışına inat. Ve isyankar bir yürek. Bir annesi görmüştü onu ağlarken; S...', ARRAY['Türk Edebiyatı','Şiir','Kenan Eren']::text[], 8.5, '{"poet":"Kenan Eren","poet_slug":"kenan-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yigit-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutsama', 'kutsama-naime-erlacin-sgt68', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bilmezdim

bu denli zor olduğunu

yaşamı ağırlamanın

taş misali ağır 

ne çok acı

ne çok hüzün

ne çok ayrılık bu

ve ne çok aşk

kocaman ki

gökyüzü kadar

altında 

sarmaşık güller açar

iyidir ev sahipliğim ey hayat! 

gülümse :) 

(12 Kasım 2004)', 'bilmezdim bu denli zor olduğunu yaşamı ağırlamanın taş misali ağır  ne çok acı ne çok hüzün ne çok ayrılık bu ve ne çok aşk kocaman ki gökyü...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kutsama-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Haddimize Efendim', 'ne-haddimize-efendim-mehmet-lutfu-aydin-2yzp6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karşı gelmek mi dediniz, sayın  patron? İstirham ederim, ne haddimize

..................................................................................................................  efendim

Doymasa da karnımız, çalışırız merkep gibi, şükrederiz halimize 

..................................................................................................................  efendim

Mutluluktan çalar, oynar, zıplarız, bakmayın siz hal-i pür melâlimize 

..................................................................................................................  efendim

Olmasa da farkımız cenazeden, bu can feda olsun zat-ı âlinize

..................................................................................................................  efendim', 'Karşı gelmek mi dediniz, sayın  patron? İstirham ederim, ne haddimize .........................................................................', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ne-haddimize-efendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kare', 'kare-gulsen-senderin-goum7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir doğru parçasını tümler noktalar 

İki doğru parçası; kesişmezi oynar 

Üç doğru parçasından üçgenler yaptım 

Kimi ikizkenar, kimi de eşkenar... 

Dört doğru parçasına şaşarak, saptım 

Önce çeşitkenar, sonra da kare yaptım. 

Aşkın düzlemine; tek KARE uydu... 

İkiye böldüm: İki eşit dik kenar üçgen! 

Yaşantıma uymayan, tek yamuk oldu... 

15 – 12 – 2000 - Ataköy', 'Bir doğru parçasını tümler noktalar  İki doğru parçası; kesişmezi oynar  Üç doğru parçasından üçgenler yaptım  Kimi ikizkenar, kimi de eşken...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kare-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alimlerin Bahçesi', 'alimlerin-bahcesi-mehmet-isikoglu-0wip0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ALİMLERİN  BAHÇESİ

Bizden önce çalışmışlar

Ne de güzel bal yapmışlar

Atlaslara tül saçmışlar

Gidin görün pazardadır

Ondan tadan hızlı gider

Aydınlığa salar haber

Cehaleti alt üst eder

Maharet son karardadır

Gerekir mi denemeyi 

Önümüzde olan şeyi

Hazır olan tecrübeyi

Hiçe sayan zarardadır

Ne tatlıdır bahçe balı 

Parasızdır orta malı

Onu herkes kullanmalı

Anahtarı yazardadır

Bahçesine girmek gerek

Bohçasını sermek gerek

Bilge vermiş çokca emek

Onun gücü damardadır

Olmalıdır ilme aşık 

Tutmalıdır öne ışık 

Cehalete sağlam ve şık

Set çeken ön saflardadır.', 'ALİMLERİN  BAHÇESİ Bizden önce çalışmışlar Ne de güzel bal yapmışlar Atlaslara tül saçmışlar Gidin görün pazardadır Ondan tadan hızlı gider ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/alimlerin-bahcesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Simidi', 'can-simidi-mehmet-isikoglu-3qrt3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'CAN SİMİDİ

Ruhumu tüm zinde tutan

Yaralara neşter atan

Rüyalarım senle tatlı

Sensin hayale can katan

Önümü aydınlatansın

Benimle kalkıp yatansın 

Mümkün değil sensiz yaşam

Düşsem elimden tutansın 

İç dünyamda çağlayansın

Benle gülen ağlayansın

Sende  beni buluyorum

İstikbale bağlayansın

Her yerde imdada koşan

Hayatı benle paylaşan

Hiç tükenmez maharetin

Türlü engelleri aşan

Ekmek oldun yiyem diye

Hep kolladın üyem diye

Darda kaldım kucakladın

Giysi oldun giyem diye

Tohum oldun saçam diye

Geçit oldun geçem diye

Tüm çareler diz çökmüşken

Kanat oldun uçam diye', 'CAN SİMİDİ Ruhumu tüm zinde tutan Yaralara neşter atan Rüyalarım senle tatlı Sensin hayale can katan Önümü aydınlatansın Benimle kalkıp yata...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/can-simidi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tamam...?', 'tamam-hasan-basri-kale-xkufe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bugünden yarına

çeşni olamam damağında

çünkü benim bildiğim

sen çorbayı tuzsuz seversin..

bir dikkatli gözün esiri

her kimse 

soran olursa benden sana

kimdi o..? diye

önce gülersin..

sonra; 

''bir anlaşılmaz adamdı be,

ben de anlamadım..''

der..geçersin..! 

........

........

tamam..?', 'bugünden yarına çeşni olamam damağında çünkü benim bildiğim sen çorbayı tuzsuz seversin.. bir dikkatli gözün esiri her kimse  soran olursa b...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tamam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olgu', 'olgu-mehmet-isikoglu-3gpwa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'OLGU

Değer biçilemez cevher insanda

Meziyet arayıp bulabilmektir

Örtülü sermaye durur kasanda

Arada perdeyi delebilmektir

Maharet gizlenmiş onun özüne

Çözülemez anahtarı bulmadan

Kadrini bilmeyen vurur dizine

Keşif esas gün gruba dalmadan

Kat kat kalın üzerinde örtüsü

Kolay değil tahlil edip yön vermek

Dahi yapar onun içten dürtüsü

Ilahi bir olgu gizli yetenek.', 'OLGU Değer biçilemez cevher insanda Meziyet arayıp bulabilmektir Örtülü sermaye durur kasanda Arada perdeyi delebilmektir Maharet gizlenmiş ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olgu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşümde Seni Gördüm', 'dusumde-seni-gordum-huseyin-erdogan-mzvq7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dün gece

seni gördüm düşümde

her geceki gibi

gülümseyerek koşuyordun

bana doğru

ben de sana

kucakladık birbirimizi

kollarımızla 

sımsıkıcasına

hiç ayrılmamacasına

göz yaşlarımız boşaldı

birdenbire

sevinç ve neş''enin getirdiği

görenler hayran kaldı

bu tertemiz aşkımıza', 'dün gece seni gördüm düşümde her geceki gibi gülümseyerek koşuyordun bana doğru ben de sana kucakladık birbirimizi kollarımızla  sımsıkıcası...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dusumde-seni-gordum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gecede Kalan', 'o-gecede-kalan-serif-erginbay-1ktje', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seller ülkesinde bedenimiz,

içimizde o seğirten sağanak:

acemi adımlar gecede.

Gözlerinin kuyusuna iniyorum:

acının tarih dersi; unutulmuş,

senelerce unutulmuş! 

Yıldırım:

sellerin ulağı,

titreten sesiyle,

kıymık kıymık içimizde.

Gözlerinin kuyusuna iniyorum:

-acı bir gülümseyiş yüzünde-

bir türkü söyler içinden atlar geçen

yükselen dumanlar içinde; unutulmuş,

senelerce unutulmuş!', 'Seller ülkesinde bedenimiz, içimizde o seğirten sağanak: acemi adımlar gecede. Gözlerinin kuyusuna iniyorum: acının tarih dersi; unutulmuş, ...', ARRAY['Türk Edebiyatı','Şiir','Şerif Erginbay']::text[], 8.5, '{"poet":"Şerif Erginbay","poet_slug":"serif-erginbay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/o-gecede-kalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğal Hak', 'dogal-hak-mehmet-isikoglu-w6c0t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'DOĞAL HAK

Medeniyet tek başına gelişmez

Lezzetli  yiyecek çeşitsiz pişmez

Soyutlama yaratıkta cinsleri

Herkesin kültürü tarihten sentez

İnsanlar arası bir iletişim

Olmazsa dünyada olmaz gelişim

Çok doğaldır farklı düşünmek bence

Bağlanmıştır geleceğe  geçmişim

Dimağıdır milletlerin kültürü

Güzelliktir insanların çok türü

Hoşgörü macunu güzel eğitim

Kınama sen inancından ötürü

Olurmuymuş kültürlerin öncüsü? 

Onlar her milletin sırlı incisi

Soy ağacı taşır maziyi çağa

Toplum olgusunun bir habercisi

Bırakın! düşünsün konuşsun insan

Sağlar gelişmeyi öz ana lisan

İstediği yerde doğmadı kimse

Değişmez genleri dili bağlasan

Kabullensin herkes kültür farkını

Ters döndüremezler felek çarkını

İnsandır insanca yaşamak ister

Zedelemesinler özlük hakkını.', 'DOĞAL HAK Medeniyet tek başına gelişmez Lezzetli  yiyecek çeşitsiz pişmez Soyutlama yaratıkta cinsleri Herkesin kültürü tarihten sentez İnsa...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dogal-hak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Abidesi', 'gonul-abidesi-mehmet-isikoglu-olugi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'GÖNÜL ABİDESİ

Hep güzel aradım ömür yolunda

Bekledim gönlüme ışık tutanı

Bir afet rastladı göze sonunda

Görmedim böylesi kement atanı

Karpuz karpuz kalça batıyor  göze

Olanlar meydanda gerek yok söze

Sevda mıknatısı güzel endamı

Çeker sevenini getirir dize

Kibrite gerek yok yakar ateşi

Bulunmaz dünyada daha bir eşi 

Nurdan yaratılmış sıcacık teni

Kalpleri ısıtan sevda güneşi

Verilmiş güzellik belli ki haktan

Şavkı göz alıyor daha uzaktan

Sunsa bir kadehten birde dudaktan

Mest eder aşığı böylesi güzel

Yüzler gül bahçesi cazibe yükü

Büyüler insanı durduğu yerde

Derde deva olur sözünün teki

Yatıyor dermanım tatlı dillerde.', 'GÖNÜL ABİDESİ Hep güzel aradım ömür yolunda Bekledim gönlüme ışık tutanı Bir afet rastladı göze sonunda Görmedim böylesi kement atanı Karpuz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gonul-abidesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüler Döner mi Hiç?', 'oluler-doner-mi-hic-galip-sinecikli-gxkng', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir çoban olaydım,

Dağ da kaval çalaydım,

Bir balık olaydım,

Derin bir umman da kaybolaydım,

Keşke şu divane gönlümü, 

Zincirlere vuraydım,

Yıllar geçti aradan,

Niçin geriye döndün,

Senin haberin yok mu? 

Benim için sen,

Gittiğin gün öldün.

Artık o tatlı gülüşünle,

Beni asla kandıramazsın,

Çıra değil artık gönlüm,

Eskisi gibi yandıramazsın,

Son umudumu,

Giderken sen götürmüştün,

Artık umutlarımı solduramazsın,

Bir zamanlar bir alevdin gönlümde,

Artık küllendin söndün,

Benim için sen,

Gittiğin gün öldün.

Giderken ardına bakıp,

Bir ELVEDA demedin,

Ayaz kesen buz gibi,

Gecelere bıraktın beni,

Bekledim geceler içinde gelmedin,

Yılarca bir haber bekledim,

Onu bile vermedin,

Elveda demeyen dudaklar,

Merhaba der mi hiç,

Nazarımda bir Ölüsün,

Ölüler geri döner mi hiç...', 'Bir çoban olaydım, Dağ da kaval çalaydım, Bir balık olaydım, Derin bir umman da kaybolaydım, Keşke şu divane gönlümü,  Zincirlere vuraydım, ...', ARRAY['Türk Edebiyatı','Şiir','Galip Sinecikli']::text[], 8.5, '{"poet":"Galip Sinecikli","poet_slug":"galip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/oluler-doner-mi-hic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anamur''da', 'anamur-da-huseyin-erdogan-3lymj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen ve ben

dolaşıyoruz el ele

mehtaplı bir gecede

Anamur''da sahilde İskele''de

kıyıya vuran dalgaları seyrederek

uzanıyoruz sere serpe

kumlar üzerine

rüzgarın dağıttığı saçlarını 

okşuyorum tatlılıkla

gün doğumunu bekliyoruz

oracıkta

bir ürpertiyle,bir korkuyla 

doğruluyoruz yerimizden

yoo sakın korkma

dalgalar çok iyimser

dedikodu yapmazlar

bizi yakmazlar

birileri gibi

canım sevdiğim', 'sen ve ben dolaşıyoruz el ele mehtaplı bir gecede Anamur''da sahilde İskele''de kıyıya vuran dalgaları seyrederek uzanıyoruz sere serpe kumlar...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/anamur-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyü', 'buyu-mehmet-isikoglu-mstod', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerinden çıkan ok tam kalbime saplandı

Tuhaf oldum içime bir şeycikler toplandı 

Duygu deryalarında bir fırtına bir tufan

Kabardı taştı yürek heyecanla kaplandı 

Kaldım tesir altında oldum adeta uydu

Sanki gökte yıldızım ani yerinden kaydı

Büyülenmiş gibiyim bilemedim ne oldu 

Ey güzel aşk perisi yapacağın bu muydu?', 'Gözlerinden çıkan ok tam kalbime saplandı Tuhaf oldum içime bir şeycikler toplandı  Duygu deryalarında bir fırtına bir tufan Kabardı taştı y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/buyu-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkiyem', 'turkiyem-mehmet-karli-f1cj2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Türkler Sende doğmuş Sende yaşlanmış

Gönüllerde rengarenk aşklar yeşermiş

Bağlarında üzüm olur güller bitermiş

Türkiyem Allah Seni bağışlamış bizlere...

Toplar çoşmuş havalarda dolaşmış

Vatan aşkı gönüllere bağlanmış

Gurbet bitmiş arkadaşlar aranmış

Türkiyem Allah Seni bağışlamış bizlere...

Okulunda ilim irfan ahlak var

Ölmüş,doğmuş,gelecekler Sana yar

Herkese yetecek büyük kalbin var

Türkiyem Allah Seni bağışlamış bizlere...

Kimlik kartı,kitap,defter birbirine karışmış

Şehit doğmuş şehit olmuş şehit büyütmüş

Atalarım gönül vermiş ondan vuruşmuş

Türkiyem Allah Seni bağışlamış bizlere...

Dostlar yatar gönülleri ferahmış

Bu Vatanı atalar bize bırakmış

Birzamanlar Dünya Sana çırakmış

Türkiyem Allah Seni bağışlamış bizlere...

Dağların var duman duman olmuş başları

Ovalarda sürü sürü takla atar koçları

Gökyüzünde öter türlü türlü kuşları

Türkiyem Allah Seni bağışlamış bizlere...

Üç tarafın deniz Sen bir yarımadasın

Çeşit çeşit mevsiminle bu Dünyaya gıptasın

Müziğimin bestecisi şirimde güftesin

Türkiyem Allah Seni bağışlamış bizlere...

Silgim silmez bu yazılar kalmalı

Okuyanlar biraz ibret almalı

Gelip geçen Sana selam durmalı

Türkiyem Allah Seni bağışlamış bizlere...

Oğlun Mehmet Sende doğmuş Sende büyümüş

Sevdiği kız Sende durur Sende kalırmış

İkiside öldüğünde Senin Senin... olurmuş

Türkiyem Allah Seni bağışlamış bizlere...', 'Türkler Sende doğmuş Sende yaşlanmış Gönüllerde rengarenk aşklar yeşermiş Bağlarında üzüm olur güller bitermiş Türkiyem Allah Seni bağışlamı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karlı']::text[], 8.5, '{"poet":"Mehmet Karlı","poet_slug":"mehmet-karli","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/turkiyem-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı tanı...', 'aski-tani-i-brahim-ethem-bingul-xvbkc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İşittim ki

Sevgili inanmazmış sevdama

Öyleyse anlat bana

Sevgi nedir senin lügatında...

Sen sanırsın

Aşk, muhabbet görmekle,dokunmakla

Yazık olmuş sana

Aşkı tanımamışsın hâlâ...

Kızım, kızım bak şu saçlara

Ardından da yüreğindeki sevdaya

Görebilirsen ama...! 

Önce dileğin nedir bil

Sevdadan yana

Sonra sitemini, nazını yap

Seni seven yârine...

Korkarım ki vurursun sonra

Benden çevirdiğin başını

Taşlara...

www.iebingul.com', 'İşittim ki Sevgili inanmazmış sevdama Öyleyse anlat bana Sevgi nedir senin lügatında... Sen sanırsın Aşk, muhabbet görmekle,dokunmakla Yazık...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/aski-tani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekasıda Na Mahrem', 'bekasida-na-mahrem-ali-riza-unal-0h4mr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O sineyi candan, açılır perdeyi mahrem

O gaybı ledündür, haramiya na mahrem

Sandılar cenneti ahirdir, cemali mahrem

Bil ki an ilinde amânın, bekasıda na mahrem', 'O sineyi candan, açılır perdeyi mahrem O gaybı ledündür, haramiya na mahrem Sandılar cenneti ahirdir, cemali mahrem Bil ki an ilinde amânın,...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bekasida-na-mahrem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ramazan’ın Ardından…', 'ramazan-in-ardindan-ensar-cevval-48211', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gülüş kadar kısa

Bir bakış kadar giz dolu yolcu

Kandillerle süslü minarelerdi ilk bekleyenin

Güllerle süslü saflarda yolunu gözleyenlerin

Ne kadarda özlemişiz seni ey yar! 

Gecenin derinliğinde uyanan gözler şahidi

Dudaktan arş’a yükselen Mûshaf şahidi

Kokunu alabilmek için tâ derinden

Aç bıraktık bedeni tüm zevklerinden

Açıldı ellerimiz, titrer dudaklarımız

Avuçlarında biriken nurla ıslandı damaklarımız.

Bu gece  ışıl ışıl yeryüzü,nura dönmüş kainat

Her müminin kollarına asılmış bir çift kanat

Gül’den yapılmış şerbetler akıyor çeşmelerden

Zağferan,Itır kokularını taşıyor rüzgar, bahçelerden.

Bin geceden hayırlı bir geceyle veda ederken

İbadetlerimize şahitlik et, biz sırat’ı geçerken.

Başka bir aleme doğru yazılmışsa bu yolculuk

Seni hep umutla bekleyecek doyurduğun yokluk

Perdesi çekilecek yine, toklukla sınır açlığın

Midesi kıvrılacak yine bacak arasına fakirin.

Yüreğimden bir şeyler kopacak biliyorum ardından

Bir kez daha kavuşmayı nasip etsin yüce yaradan

Seni bekleyeceğiz toklukla,şahit olsun zaman

Tüm güzelliklerle kal,hoşça kal Ramazan. 

Sirkeci-2004-11-12', 'Bir gülüş kadar kısa Bir bakış kadar giz dolu yolcu Kandillerle süslü minarelerdi ilk bekleyenin Güllerle süslü saflarda yolunu gözleyenleri...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ramazan-in-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nadide Buse', 'nadide-buse-ali-riza-unal-pkii2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanayım ah ile senden bi haber, bu ömür sensiz neçe

Anayım adını her an, nefesim dil ile bir olsun, aynı hece

O çölleri bağban eden nazarınla, selam kıl ey sevgili

Kanayım o nadide mahremine, açıver kalmasın peçe', 'Yanayım ah ile senden bi haber, bu ömür sensiz neçe Anayım adını her an, nefesim dil ile bir olsun, aynı hece O çölleri bağban eden nazarınl...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nadide-buse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyorum Yokluğunda', 'usuyorum-yoklugunda-huseyin-erdogan-92eq3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'şu anda 

günlük güneşlik 

bir hava var dışarıda

bense tir tir titriyorum

ellerim buz gibi

üşüyorum yokluğunda

sizde mevsim yaz olsa da

hep kara kıştır bizim buralarda

başka mevsim yaşamadım

sen gittiğinden bu yana

sensiz güneş bile doğmadı 

İstanbul''da sabah da hiç olmadı

inan ki gözlerim 

senden başkasını görmüyor

nereye baksam sen varsın

sen vefasız olsan da

vaz geçemeyeceğim tek yarsın', 'şu anda  günlük güneşlik  bir hava var dışarıda bense tir tir titriyorum ellerim buz gibi üşüyorum yokluğunda sizde mevsim yaz olsa da hep k...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/usuyorum-yoklugunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüğüm...', 'kucugum-canan-palabiyik-3punn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu bayramda yalnızım yine sensiz bu şehir,

Yıllar önce bir bayram sabahı gittin nedensiz,

Hatırlarmısın bebeğim nasıl hazırlanırdık, 

Kapıya gelen çocuklar için arife gününden? 

Rengarenk şekerler, mendiller alırdık...

Bayram sabahı hepimizden önce uyanırdın neşe içinde,

Hemencecik giyinip elimizi öperdin,

Kapı çaldığında koşardın lüle lüle uçuşan saçlarınla,

Parmaklarının ucunda yükselir uzanırdı minicik ellerin tokmağa,

Kapıya gelen çocuklar ise benden önce koşup getirirdin mendil ve şeker,

Alışamadım küçüğüm hala alışamadım sensizliğe,

Sokakta gördüğüm her çocukta seni görüyorum,

Her birine aldırmadan çevreme sarılıp öpüyorum kederle,

Alışamadım küçüğüm alışamayacağım sensizliğe....

(12 Kasım 2004 / İstanbul) 

Bu şiir, Samanyolu grubunun ve bu haftaki kelimeleri ''''KEDER'''' ve ''''BAYRAM'''' olan ''''İki Kelime Bir Şiir'''' aktivitesi için kaleme aldınmıştır. 

Aşağıdaki isim linkini tıklayarak, bu haftanın aktivitesine katılan diğer bir arkadaşımızın şiir(ler)   ini okuyabilirsiniz.

Metin Eser', 'Bu bayramda yalnızım yine sensiz bu şehir, Yıllar önce bir bayram sabahı gittin nedensiz, Hatırlarmısın bebeğim nasıl hazırlanırdık,  Kapıya...', ARRAY['Türk Edebiyatı','Şiir','Canan Palabıyık']::text[], 8.5, '{"poet":"Canan Palabıyık","poet_slug":"canan-palabiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kucugum-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gayrı Gam Olmam', 'gayri-gam-olmam-ali-riza-unal-h19a1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gayrı gam olmam, dalmışım aşkta sevdayı ummana

Nail oldum o meşki vuslatına, aman ülfetten alâ

Beni benden almış, bensiz sana varışım

Neylerim ricali sarayı, sana gafletten mada', 'Gayrı gam olmam, dalmışım aşkta sevdayı ummana Nail oldum o meşki vuslatına, aman ülfetten alâ Beni benden almış, bensiz sana varışım Neyler...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gayri-gam-olmam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Yazardım', 'ask-yazardim-huseyin-erdogan-c28i6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'keşke tıp doktoru olsaydım

aşk ve sevgi yazardım

bütün reçetelere

antibiyotik yerine

öğretmen olsaydım da

sevmek ve sevilmek fiillerini

öğretirdim

hatta ezberletirdim

yer yüzünde herkese

hasretin öylesine yakıyor ki içimi

galiba benimkisi

aşkın acı biçimi

hiç tutmasan da 

üşüyen ellerimi

bir gün sen de 

çok çok iyi 

anlayacaksın sevgimi

okudukça şiirlerimi', 'keşke tıp doktoru olsaydım aşk ve sevgi yazardım bütün reçetelere antibiyotik yerine öğretmen olsaydım da sevmek ve sevilmek fiillerini öğre...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ask-yazardim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhabbet Kuşum', 'muhabbet-kusum-huseyin-erdogan-qvg7g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yıllar önce

öyle bir ok atmıştın ki kalbime

inan ki hala duruyor içimde

öylece

çıkaramadı hiçbir kimse

kökleri o kadar sağlam ki

daha da derinleşiyor

günden güne

sen muhabbet kuşumsun benim

tek dertleştiğim söyleştiğim

en büyük derdimdir sensizliğim

bil ki

sen yanımda yoksan sevdiğim

demek ki

ben üçte iki eksiğim', 'yıllar önce öyle bir ok atmıştın ki kalbime inan ki hala duruyor içimde öylece çıkaramadı hiçbir kimse kökleri o kadar sağlam ki daha da der...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/muhabbet-kusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daktilo', 'daktilo-gulsen-senderin-yd9hd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Okumak,onun da hayallerini süslüyordu 

Vahşi köy yaşamında, yetişen bir genç kızın 

Ki babası bir ''erkek evlat'' asası 

Tutuştururken o minicik ellerine 

Çoktan başlamıştı yaşam kavgası... 

Şehrin kollarında açıkk olsun, bahtın yıldızın... 

Ders zilleri yetişti ellerinin nasırına 

İsmi kazınırken Ticaret Lisesi masalarına 

Daktilo sesleri karıştı, geleceğinin adına 

Şimdilik sekreterlik düşleri giriyordu rüyalarına 

Annesinde gül pembe mendil kızının düşleri. 

Ansızın bir Aşk Fırtınası dallarını kopardı

Yeşil ağaçları, yerle bir eden hortumlar  gibi... 

Gökler unutturmazken, yağışa dönüşmeyen bulutları 

Bir dizi yitikler, göz kırparken kapı aralıklarından 

Bir türlü çözülür mü, o masum umut yumakları? 

Ve çalışarak kırk Kıbrıs Lirası''na aldığı daktilo 

Şeridine sıkışıp kalan; o koskocaman umutları... 

Gün ağarırken, parlatır geceden kalan loşlukları 

Bir zaman yelpazesi, indirir perde perde anıları 

Bir PC ekranından doldurmaya çalışsak da 

Bizimle sırdaş olan, kentsel yalnızlıkları 

Yerini teknolojiye terk eden daktiloyu anlasak da 

Doldurabilir miyiz; bizi terk etmeyen boşlukları...', 'Okumak,onun da hayallerini süslüyordu  Vahşi köy yaşamında, yetişen bir genç kızın  Ki babası bir ''erkek evlat'' asası  Tutuştururken o minic...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/daktilo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Yeniden.', 'belki-yeniden-ali-osman-yilmaz-linjh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gökyüzü kadar büyük,

Okyanuslar kadar derin,

Güneş gibi ışıldayan,

İçinde eriyip kaybolduğum,

O masmavi gözlerinde,

Ve kızıl saçlarının alevinde,

Yanıp kavrulduğum,

O günden bu yana,

Arıyorum kendimi,

Bir türlü bulamıyorum.

Hasretinin cehenneminde,

Tükenip kül olduğumu,

Unutmuşum.

Şimdi düşlerimde,

Seni arıyorum.

Diyorlar ki bana,

Yandın kül oldun sen,

O külden yeni bir aşk doğmaz,

Umut etme sen,

Aşk bahçelerinden esen,

Yele bırak kendini,

Kır çiçeklerinin koynunda,

Bulabilirsin aşkı,

Belki yeniden.', 'Gökyüzü kadar büyük, Okyanuslar kadar derin, Güneş gibi ışıldayan, İçinde eriyip kaybolduğum, O masmavi gözlerinde, Ve kızıl saçlarının alev...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/belki-yeniden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıldıracağım', 'cildiracagim-ali-osman-yilmaz-haidk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gece,

Bitmesin istiyorum.

Sabah olmasın,

Güneş de doğmasın,

Her yer karanlık olsun,

Gözlerimi de kapadım,

Senin yokluğunda,

Umutlarıma sarılmış,

Düşlerimde geziniyorum.

Sabah olur,

Bir de güneş doğarsa,

Kalkacağım yatağımdan,

Dolaşacağım bütün odaları,

Seni bulabilmek için,

Sonra mutfağa girip,

Senin olmadığını görünce,

Belki değil,mutlaka,

Çıldıracağım.', 'Bu gece, Bitmesin istiyorum. Sabah olmasın, Güneş de doğmasın, Her yer karanlık olsun, Gözlerimi de kapadım, Senin yokluğunda, Umutlarıma sa...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cildiracagim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçuyorum Yıldızlara.', 'ucuyorum-yildizlara-ali-osman-yilmaz-jojad', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatım senin,

İki dudağının arasında,

Söyleyeceğin bir çift söz,

Yada bir öpücüğün,

Ab-ı hayat nektarı tadında,

Böyle düşünerek,

Tatlı güzel duygularla,

Kanat takıp havalara,

Kuş değilim ama,kuş gibi,

Uçmadayım yine yıldızlara.

Ne olur dudakların bana,

Bekleme,unut beni demesin,

Böyle uçmaktayken yıldızlara,

Can yeleği de takmamışım,

Paraşütüm de yok açacak,

Ne olur o dudakların,

Söylemesin o sözleri,

Bir düşersem eyvah,

Param parça olurum.', 'Hayatım senin, İki dudağının arasında, Söyleyeceğin bir çift söz, Yada bir öpücüğün, Ab-ı hayat nektarı tadında, Böyle düşünerek, Tatlı güze...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ucuyorum-yildizlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onunladır Bilsin Kalbimin Sessizliği', 'onunladir-bilsin-kalbimin-sessizligi-selim-bayrak-4ul6k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir köz istedim sezinlenişlerime 

Benliğime gelsin suların derinliği

Bir düş istedim gerçeklerin içinde

Onunladır bilsin kalbimin sessizliği

Belki fırtına ardı gri gökyüzü

Belki fırtına sonrası sevgi sözcüğü

Belki yeşerecek yığınlarca çiçek 

Belki her şey daha başlamadan bitecek

Güle güle denizlerin yunusu

Hoş geldin topraklarımın humusu

Sana anlatacağım çokça şey var

Ama zamansızlık göğsümü sarar

El ele olmadığım anlar düşüncenle

Bir boşluk sunulur hislerime 

Güllerini ararken derin bahçende

Çiçeğini bulamaz isem

Dikenin mi batmalı sevgime

1992 - Bolu', 'Bir köz istedim sezinlenişlerime  Benliğime gelsin suların derinliği Bir düş istedim gerçeklerin içinde Onunladır bilsin kalbimin sessizliği...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/onunladir-bilsin-kalbimin-sessizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalar', 'aynalar-ali-osman-yilmaz-mcw0z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aynalar,

Sır küpü aynalar,

Hamuru sır taşından,

Tarihin bütün yalanları,

Aynalarda saklanırlar.

Bazen dayanamaz,

Çat diye kırılırlar,

Parça parça olur,

O zaman aynalar.

Gerçekleri parçalara böler,

Yalanlara isyan ederler.

Ne varsa aynen öyle,

Yap boz misali,parçalarda,

Gerçekleri tamamlar.

Bazen dökülür sırları,

Sevmez o zaman onu insanlar.

Aslında dökülen,

Ayaların sır’ı değildir,

İnsanların yalanlarına,

Dayanamadıkları içindir,

Her gün karşısına geçilip,

Ayna ayna,söyle bana,

Benden güzel var mı? 

Hele o yalancı,

Politikacılar yok mu? 

Değil aynaları,

Tüm insanları çatlatırlar.', 'Aynalar, Sır küpü aynalar, Hamuru sır taşından, Tarihin bütün yalanları, Aynalarda saklanırlar. Bazen dayanamaz, Çat diye kırılırlar, Parça ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/aynalar-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydi Git', 'haydi-git-husamettin-gunacti-uof4n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'tutma ellerimi,gözlerini kaçır benden,

haydi durma git yaban diyarlara.

bu kimliksiz ruh, başsız beden,

daha alışmadı buruk vedalara.

varsın sökülsün kalbim yerinden,

hatta dalayım sensiz rüyalara.

geriye hiç bir iz kalmasın senden,

doldur valizini kahpe dünyalara.

hani gittin ya kaybolup birden,

birden gündüzüm karıştı akşamlara.

sanma ki güçlüyüm tunçtan,demirden,

koşarım sanma yeni heyecanlara.

nerde gökyüzü, yıldız yok neden,

neden kendimi vurdum ıssız yollara.

yaşamaz başsız, ruhsuz bu beden,

geri dön ne olur sensiz kollara...

12-11-2004', 'tutma ellerimi,gözlerini kaçır benden, haydi durma git yaban diyarlara. bu kimliksiz ruh, başsız beden, daha alışmadı buruk vedalara. varsın...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/haydi-git-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen Oyun', 'bitmeyen-oyun-sinan-uruc-y5lch', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine de yaksam

Uçuşan yıllardaki

Ağıtlarla öpüşmüş küllerini.

Kaçamak bir ağustos

Ilık yağmur taneleri

Tenimde sen gibi....

Tozlara kuşanmış resmini

Hep koklasam

Yine de

Seni arayan bir körebeyim.', 'Yine de yaksam Uçuşan yıllardaki Ağıtlarla öpüşmüş küllerini. Kaçamak bir ağustos Ilık yağmur taneleri Tenimde sen gibi.... Tozlara kuşanmış...', ARRAY['Türk Edebiyatı','Şiir','Sinan Uruç']::text[], 8.5, '{"poet":"Sinan Uruç","poet_slug":"sinan-uruc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bitmeyen-oyun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine..', 'yine-canan-palabiyik-gpeer', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine güneş battı,

.....................yeni bir günü başlatmak için,

Yine bir gün bitti,

.....................geceyi başlatmak için,

Yine bir gece bitti,

......................bilinmezleri getirmek için,

Yine bir aşk bitti,

.....................aşklar yaratmak için.

Düşünmek bile yoruyor beni........

(12 Kasım 2004 / İstanbul)', 'Yine güneş battı, .....................yeni bir günü başlatmak için, Yine bir gün bitti, .....................geceyi başlatmak için, Yine bi...', ARRAY['Türk Edebiyatı','Şiir','Canan Palabıyık']::text[], 8.5, '{"poet":"Canan Palabıyık","poet_slug":"canan-palabiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yine-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvar', 'duvar-faik-genc-tf8gd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim başka kimsem yok

Olsun da istemiyorum

Ama senin hayatın kalabalık canım

Yalnız kal da istemiyorum

Dileğim koyduğum yerde gizli

Anlıyor musun? 

Kasım 2000', 'Benim başka kimsem yok Olsun da istemiyorum Ama senin hayatın kalabalık canım Yalnız kal da istemiyorum Dileğim koyduğum yerde gizli Anlıyor...', ARRAY['Türk Edebiyatı','Şiir','Faik Genç']::text[], 8.5, '{"poet":"Faik Genç","poet_slug":"faik-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/duvar-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devamı Yaşam', 'devami-yasam-oguz-ozyurt-mhjcy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eli saklı kaldı eski zaman taarruzunda,

	Yalanın korkusu sardığında dört bir yanı,

	Peşinatsız bir hayal, sahipsiz bir özlem,

	Salınarak yürüdü yaşamın kıyılarında…

	En sessizinde, soluğun hızlandığı yerde,

	Hızlı ve sürekli yolculuğa ilk adım,

	İlk heyecandı yarım, şaşkın…

	Süzüldü zaman ıssız ve tenha sokaklara,

	An ve an çoğaldı, gözlerde soru oldu,

	Dondu, soldu, gerçekten zordu…

	

	Adında saklı mana uzak,

	Azalırken yaşam kalp atışında,

	Gerilir kaslarından, boşalır hayal…

	Manadan uzağa, sessize sürerken yolculuk,

	Sarılır son kalan tutamaklarına yaşamın,

	Çocukluğunda, gençliğinde, 

	Günün bitişinde…', 'Eli saklı kaldı eski zaman taarruzunda, 	Yalanın korkusu sardığında dört bir yanı, 	Peşinatsız bir hayal, sahipsiz bir özlem, 	Salınarak yür...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Özyurt']::text[], 8.5, '{"poet":"Oğuz Özyurt","poet_slug":"oguz-ozyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/devami-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Celo''ya', 'celo-ya-salih-eylem-fi7gr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni gördüğüm kadar artık göremez olmuşum; 

yokluğuna alışır olmuşum.

Sanma ki seni çoktan unutmuşum,

Sen unutulmazsın Celo.

Sen hayata tekme attın,

Kendini nerelere kaptırdın? 

Düşlerine de mi acımadın? 

Artık son bir umut Celo.

Olmadı, o umudu yitirdik,

Nereye bu gidiş, bilemedik

Seni üç günde kaybettik

Bildiğimiz bunlar Celo.

Nişantaşı artık sustu,

Belli ki o da yoruldu

Sevdiği adam kayboldu

Nerelerdesin sen Celo? 

Eminönü, Sirkeci tanır bizi; 

Selamsız geçirmezler beni

O da hissetti eksikliğini

Galata artık sensiz Celo.

Kimbilir ne çileler çekildi,

Hayata ne isyanlar edildi

Sana cefasını çektirdi,

Sefada kısmet oğul''un Celo.

(2004 İstanbul)', 'Seni gördüğüm kadar artık göremez olmuşum;  yokluğuna alışır olmuşum. Sanma ki seni çoktan unutmuşum, Sen unutulmazsın Celo. Sen hayata tekm...', ARRAY['Türk Edebiyatı','Şiir','Salih Eylem']::text[], 8.5, '{"poet":"Salih Eylem","poet_slug":"salih-eylem","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/celo-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sığıntı Olmuşum', 'siginti-olmusum-volkan-yoruc-d91n8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir garip zamanlardayım

Havalar soğukmu sıcakmı bilemem

Ellerim tutuk gözlerim donuk

Seni bekliyorum hayallerim kırık

Sevdamsın bunu bilirim

Zamana karşıdır savaşım 

Ardıçlar uçuşur tepemde

Bir dağ kovuğundayım

Sığıntı olmuşum bu yapayalnız zamanlarda

Geceleri yıldızlarımı özledim

Sen gelirmisin bilemem

Yine sevda türkülerimizi söyleyebilirmiyiz

Ben senin için gelmişim buralara

Bil ki artık geri dönemem

Sığıntı olmuşu bu  yapayalnız zamanlarda

Belli ki sonumu artık göremem', 'Bir garip zamanlardayım Havalar soğukmu sıcakmı bilemem Ellerim tutuk gözlerim donuk Seni bekliyorum hayallerim kırık Sevdamsın bunu bilirim...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/siginti-olmusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Gelmiş', 'bayram-gelmis-sirma-mersin-2by9j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu kaçıncı bayram...

Hatırlamak istemediğim 

Sensiz geçen senelerden sonra

Sensiz geçen bu kaçıncı bayram...

Zaman hiç durmadan 

Koşuyor...

Mevsimler birbirini kovalıyor...

Ben hasretliğine alışamamışken

Çocukluğumun bayram sabahında

Uyandığım heyecanla 

Bana geri dönüşünü bekliyorum...

.................................................................

.................................................................

Gözlerimde biriken damlalar

Süzülürken yanağımdan aşağı

Dalıp gidiyorum uzaklara...

Ne zor şey

....................................................................

....................................................................

Bayram gününü

Tek başıma  geçirmek

Hatırlayan sadece anılar

Ve sensizlik...

Yalnızlığa ikram ettiğim

Çikolata ve kahve idi...

Oysa 

Yalnızlık her zamanki konuğum değil

Can yoldaşım oldu, günlerimde...

Gidişinden sonra! 

12.11.04', 'Bu kaçıncı bayram... Hatırlamak istemediğim  Sensiz geçen senelerden sonra Sensiz geçen bu kaçıncı bayram... Zaman hiç durmadan  Koşuyor... ...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bayram-gelmis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel, Seni Kendime Davet Ediyorum', 'gel-seni-kendime-davet-ediyorum-burcu-alpaslan-guvenli-yy2i3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hoyratlığını giy gel bu gece

yürüdüğün yolların izlerini al yüz çizgilerine

ısıt ısın kırış

Boşluğumuza alacalığını sür

biraz mavi biraz kahverengi

Düzlükleri unut

saçma sapan hikayelerimiz olmalı

hatırla 

Kanık gecelerini yüklen

Gel 

Seni kendime davet ediyorum 

12-11-2004 Bursa', 'Hoyratlığını giy gel bu gece yürüdüğün yolların izlerini al yüz çizgilerine ısıt ısın kırış Boşluğumuza alacalığını sür biraz mavi biraz kah...', ARRAY['Türk Edebiyatı','Şiir','Burcu Alpaslan Güvenli']::text[], 8.5, '{"poet":"Burcu Alpaslan Güvenli","poet_slug":"burcu-alpaslan-guvenli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-seni-kendime-davet-ediyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Köşe', 'dort-kose-i-smail-baharsen-i7swo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dört köşe hayat başlı başına

bir taraftan girsen çıkış yok

herkes bir sevda aşına

düşmüş, başka kaçış yok', 'dört köşe hayat başlı başına bir taraftan girsen çıkış yok herkes bir sevda aşına düşmüş, başka kaçış yok...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dort-kose-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-tulay-sustam-lgmrr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sana olan sevgim,

her geçen gün biraz daha artıyor...

s

se

sen

seni

seni s

seni se

seni sev

seni sevi

seni seviy

seni seviyo

seni seviyor

seni seviyoru

seni seviyorum

zamanı durdurdum...

asla bu sevgide geri sayım olmayacak.

seni seviyorummmmmmmmmmmmmmmmmmmmmmmmm', 'sana olan sevgim, her geçen gün biraz daha artıyor... s se sen seni seni s seni se seni sev seni sevi seni seviy seni seviyo seni seviyor se...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/seni-seviyorum-219-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Önce', 'senden-once-hasan-can-qctyv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'En güzel gecelere kirli adını yazdım,

Farkında olmadan.

En taze ağaçlara ismini kazıdım,

Acıma duygusu olmadan.

Benim gecem hep aydınlıktı,

Sen yokken.

Ağaçlarım zamansız eğilmezdi,

Sen gelmeden.

Yıldızlar hep parlardı,

Hiç kaymadan.

Ben hiç ağlamazdım,

Hep gülerdi gözlerim.

Ağlasam da,

Mutluluktan düşerdi yaşlar.

Yarınlar hep güzeldi sen yokken,

Dünümden yarınıma hesap sormazdım.

Benim dünyam da acı yoktu,

Her günüme güneş doğardı.

Sen yokken hiç düşünmezdim,

Aklıma yalnızlık düşmezdi.

Bir umudum vardı yarından ötede,

Rüzgarım vardı yalnızlığımı alıp götüren.

Şimdi her gece hep aynı şey,

Sonsuz uyku gibi bir sürgün yalnızlık.

Her yudumda bir hıçkırık şimdi,

Kulaklarda yankı gibi gözyaşlarım...', 'En güzel gecelere kirli adını yazdım, Farkında olmadan. En taze ağaçlara ismini kazıdım, Acıma duygusu olmadan. Benim gecem hep aydınlıktı, ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/senden-once-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Hiç Gelme', 'artik-hic-gelme-osman-i-nci-xn3d1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdiye dek bilmedin, bundan sonra da bilme,

Sevmedin bu yüreği, lüzum kalmadı, sevme,

Damla damla yaşları, doldurdun gözlerime,

Zaten yanımda yoktun, dönme artık hiç gelme...

Senin için ağlayan, kahve gözler benimdi,

Sana doğru açılan, yorgun kollar benimdi,

Aşkın ile kavrulmuş, harap yürek benimdi...

Zaten yanımda yoktun, dönme artık hiç gelme...

Senin için harcanan, güzel günlere yazık,

Dönsen de bir gün geri, vakit geçecek artık,

O muhteşem sevdayı, mazilerde bıraktık,

Zaten yanımda yoktun, dönme artık hiç gelme...

Sevdalıyım demiştin, nasıl kandım bu söze,

Her şeyinle toz pembe, görünüverdin göze,

Birkaç hevesten sonra, attın kalbimi köze,

Zaten yanımda yoktun, dönme artık hiç gelme...', 'Şimdiye dek bilmedin, bundan sonra da bilme, Sevmedin bu yüreği, lüzum kalmadı, sevme, Damla damla yaşları, doldurdun gözlerime, Zaten yanım...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/artik-hic-gelme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HoşlanmıyoruM', 'hoslanmiyorum-halil-kesken-n4vsu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Havalardan biraz indir burnunu

Bitanem, ben seni çok seviyorum

Sadece bilmeni istedim bunu

Prenses tavrından hoşlanmıyorum

Beni üç günde bir gelip yoklama

Suçsuz yargılanmak istemiyorum

Kılı kırk yarmana sözüm yok amma

Güvenmez tavrından hoşlanmıyorum

Sevenler elbette kıskanır biraz

Hiç mi güvenmezsin anlamıyorum

Her an tetiktesin, yan baksam infaz

Bu cellat tavrından hoşlanmıyorum

Daha bir ay önce böyle değildin

Öyle değiştin ki, tanımıyorum

Nerde benim kuzum, minik civcivim? 

Bu kaplan tavrından hoşlanmıyorum...', 'Havalardan biraz indir burnunu Bitanem, ben seni çok seviyorum Sadece bilmeni istedim bunu Prenses tavrından hoşlanmıyorum Beni üç günde bir...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hoslanmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gezinti', 'gezinti-zulfikar-yapar-kaleli-7hh3z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Baktım güzeline düştüm yeise 

Başına yemeni yaşmak isterim 

Eğer kırat sende erlik var ise 

Kale surlarını aşmak isterim 

Gönlünde sevdayı sevgiyi besle 

Aşkını ilimle irfanla süsle 

Aynı ruh heyecan aynı hevesle 

Kabıma sığmayıp taşmak isterim 

Sensin yerin göğün hakim sahibi 

Ben yüzü karalı tencere dibi 

Savaşta muzaffer kahraman gibi 

Zafer muştusuyla coşmak isterim 

Bülbülüm tutkunum aşk ile güle 

Bu yüzden bilerek çekerim çile 

Buluta hapsolmuş yıldızlar ile 

Erenler bağına düşmek isterim 

Muhabbet dünyadan bir ibret almak 

Maharet yaşarken ölümü bulmak 

Benim işim gönüllere gül olmak 

Sevgi kazanında pişmek isterim', 'Baktım güzeline düştüm yeise  Başına yemeni yaşmak isterim  Eğer kırat sende erlik var ise  Kale surlarını aşmak isterim  Gönlünde sevdayı s...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gezinti-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gündoğan', 'gundogan-tarik-morali-b991i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bodrum’da bir yer var

Biliyorum adı Gündoğan.

Güneş hep bir başka doğar 

Bir başka batar oradan.

…? 

Ondan sanırım koymuşlar 

Adı  Gündoğan…', 'Bodrum’da bir yer var Biliyorum adı Gündoğan. Güneş hep bir başka doğar  Bir başka batar oradan. …?  Ondan sanırım koymuşlar  Adı  Gündoğan…...', ARRAY['Türk Edebiyatı','Şiir','Tarık Moralı']::text[], 8.5, '{"poet":"Tarık Moralı","poet_slug":"tarik-morali","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gundogan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoş', 'sarhos-tarik-morali-2s92u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Görmüyor gözlerim

Gözlerim kör.

Duymuyor kulaklarım

Kulaklarım işitmez, sağır.

Almıyor aklım

Ben anlamaz,Ben bilmez.

Ben bihaber 

Ben çaresiz,ben kimsesiz.

Ben sarhoş ben serkeş,

Ben sensiz.', 'Görmüyor gözlerim Gözlerim kör. Duymuyor kulaklarım Kulaklarım işitmez, sağır. Almıyor aklım Ben anlamaz,Ben bilmez. Ben bihaber  Ben çaresi...', ARRAY['Türk Edebiyatı','Şiir','Tarık Moralı']::text[], 8.5, '{"poet":"Tarık Moralı","poet_slug":"tarik-morali","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sarhos-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneciğim', 'annecigim-fedai-gunaydin-d4ch2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllardır gözlerim yolunu anam,

Çıkar gelirsin diye gurbet ellerden.

Saçıma ak düştü baksana anam.

Beşikten bu yana beklemelerden.

Gözlerim sevginin yoluna düştü.

Canım çıksın yeter kollarında.

Sinenin kokusu burnuma tüttü.

Gel ne olursun öksüz hülyalarıma.

Anneciğim bir hayalsin tutamadığım.

Cennette bekliyorsun kolların açık.

Yıllardır özümde sakladığım,

Sırrımsın anneciğim sevdama sadık.

Deşildi doğumumla başlayan yaram.

Çığlığı kesilmez semalarımdan.

Sen canım,sevgili,biricik anam,

Yeter artık gel öp yanaklarımdan! 

Bilmediğim şefkatine muhtacım anam.

Dostların dostluğu yalandan gördüm.

Ah bi kavrulsaydım göğsünde anam! 

Seni görmemeklikten deliye döndüm.

Yeter artık gel öp yanaklarımdan!', 'Yıllardır gözlerim yolunu anam, Çıkar gelirsin diye gurbet ellerden. Saçıma ak düştü baksana anam. Beşikten bu yana beklemelerden. Gözlerim ...', ARRAY['Türk Edebiyatı','Şiir','Fedai Günaydın']::text[], 8.5, '{"poet":"Fedai Günaydın","poet_slug":"fedai-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/annecigim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-gulgun-engin-k5wi0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gülerken acımasızdın,

güldürürken hesapçı..

tanıdık sızıydı

güllerden akan ılık..

teninde hissettiği

var mı yok mu bilmediği dokunuşlar..

ürpertiler

nedendi?', 'gülerken acımasızdın, güldürürken hesapçı.. tanıdık sızıydı güllerden akan ılık.. teninde hissettiği var mı yok mu bilmediği dokunuşlar.. ür...', ARRAY['Türk Edebiyatı','Şiir','Gülgün Engin']::text[], 8.5, '{"poet":"Gülgün Engin","poet_slug":"gulgun-engin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/neden-116-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar', 'ruzgar-gulgun-engin-mgla0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'rüzgar

iki damla kondurdu elimin üstüne; 

birinde

güneş pırıltısı/umut yüzüyor içinde,

diğerinde

satranç tahtası/oyunlar dansediyor.', 'rüzgar iki damla kondurdu elimin üstüne;  birinde güneş pırıltısı/umut yüzüyor içinde, diğerinde satranç tahtası/oyunlar dansediyor....', ARRAY['Türk Edebiyatı','Şiir','Gülgün Engin']::text[], 8.5, '{"poet":"Gülgün Engin","poet_slug":"gulgun-engin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ruzgar-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimden Gidiyorum', 'kendimden-gidiyorum-halil-kesken-vkw17', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Paslı birer çivi gibi sözlerin,

Hem sökülmesi zaman alıyor,

Hem de kocaman bir izi kalıyor.

Her kelimen mutluluğumdan,

Her cümlen hayatımdan çalıyor.

Bir lokma ekmek olsan; boğazımda kalacak,

Bir parça ip olsan; boğazımı sıkacak,

Cellat olsan; hiç acımadan; 

Canımı alacaksın demekki...

Bu sevdada sana hiç bir şey veremediğimi,

Hiç bir şey öğretemediğimi görüyorum.

Sütten çıkmış ak kaşık olmadığını biliyorum ama...

Üzülme be güzelim,

Ben her şeyden sekizde sekiz

Kendimi suçlu buluyorum.

Cezamı ise; sana katlanarak çekiyorum.

Kendi düşen ağlamaz derler ya

Ben her gece hüngür hüngür ağlıyorum.

Hiç kimseden teselli beklemeden,

Göz yaşlarımı kağıtlara döküyorum

Senin yanında ömürlük kalıyor,

Her geçen gün kendimden gidiyorum.

Bu aşk; aşk olmaktan çıkmıştır artık

Kaderim se, çekeceğim çaresiz

Bir ömür demişim, bir yeminim var

Göz yaşımı; yüreğime dökeceğim çaresiz

Bana yakışmaz ki kolayı seçmek

Bana yakışmaz ki bırakıp gitmek

Seninle kaybettiklerim; saymakla bitmez

Umudumu kaybettim, neşemi kaybettim

Ruh sağlığımı ve aşka olan inancımı kaybettim

En önemlisi ise kendimi kaybettim

Madem ki sen azad etmedikçe; 

Müebbettir bu ceza

Çaresiz çekeceğim...

Seninle aynı evde hapis kalıyor, mutluluğumdan firar ediyorum

Sen bende kalıyorsun ama; 

Ben benden gidiyorum.', 'Paslı birer çivi gibi sözlerin, Hem sökülmesi zaman alıyor, Hem de kocaman bir izi kalıyor. Her kelimen mutluluğumdan, Her cümlen hayatımdan...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/kendimden-gidiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakıştımı Bu Ölüm Arkadaş!', 'yakistimi-bu-olum-arkadas-alpaslan-yigit-iqnh5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çocukluk arkadaşımdı

Ne çok şey paylaşmıştık onunla

Kıvırcıktı saçları ve hep kısa

Aynı sıraları karaladık

Ve aynı geceler içtik sabaha inat

Durgundu,hep zor gülerdi

İçimizdeki en akıllı olan Oydu

En güzel üniversitede okudu

Ve en güzel makama da O geldi

Belki hayat adil davranmadı

Belki hepimizden yükü ağırdı

Çekti gitti birgün istanbullara

Duydukki evlenmiş

Ve bir gün yine duydukki 

Bu dünyadan göçüp gitmiş

Yakıştımı peki bu ölüm sana arkadaş? 

Böylemi olmalıydı son vedan

Bırakıverdin kendini bir boşluğa

Ve kapandı gözlerin sonsuz karanlığa

Oldumu şimdi bıraktın bizi bizle

Geride yarım bir not bıraktın miras

Kalakaldık yaşanan yarım geçmişle

Oysa dün gibiydi gülen yüzün

Aklımın ucuna gelmezdi bu kaçış

Paylaşmak yokmuydu dertlerini dünkü gibi

Gazetelerdenmi öğrenmeliydik dertlerini

Son yolculuğunda bile yoktuk yanında

Açıpda edemedik ellerimizi bir dua

Şimdi duy bu cümlelerde dostunun sesini

Hakkım helaldir ana sütü gibi ardından

Yaptığın cehalet,mekanın cennet olsun arkadaş...', 'Çocukluk arkadaşımdı Ne çok şey paylaşmıştık onunla Kıvırcıktı saçları ve hep kısa Aynı sıraları karaladık Ve aynı geceler içtik sabaha inat...', ARRAY['Türk Edebiyatı','Şiir','Alpaslan Yiğit']::text[], 8.5, '{"poet":"Alpaslan Yiğit","poet_slug":"alpaslan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yakistimi-bu-olum-arkadas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız', 'vefasiz-yavuz-i-ren-n4xno', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hanidir ağlıyorum için için 

Dalıyorum yanlızlığımın ormanına 

Boğazımda düğümleniyor çığlığım

Duymuyor küskün sevdam

      Hasretinden hüzünlerim depreşti 

      Suskunluğa tutsak dudağım 

       Düş yorgunu gecelerimde 

       Senin hayelinle sabaha durdum

Sevdama pas geçen rüzgar 

kipriklerime çiğ misali düşen göz yaşı

Hayalimdeki o masumiyet 

Kalbimde sessiz çığlığa dönüştü.', 'Hanidir ağlıyorum için için  Dalıyorum yanlızlığımın ormanına  Boğazımda düğümleniyor çığlığım Duymuyor küskün sevdam       Hasretinden hüzü...', ARRAY['Türk Edebiyatı','Şiir','Yavuz İren']::text[], 8.5, '{"poet":"Yavuz İren","poet_slug":"yavuz-i-ren","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vefasiz-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kışlalarda Bayram', 'kislalarda-bayram-mehmet-selim-togluk-pdzr4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün bayram günü, bağrım yanıyor

Gözlerim yollarda seni arıyor

Herkes sevdiğini, bulmuş sarıyor

Benimse yollarda kaldı gözlerim

Kışlalarda bayram zordur askerim

Mektubunu açmış okuyor erler

Satır satır hece hece ezberler

Herkesin yârinden gelmiş haberler

Benim sevdiğimden gelmez haberim

Kışlalarda bayram zordur askerim

Elimde tesbihim gözümde yaşlar

Aklımdan çıkmıyor o kara kaşlar

Hayalin karşımda gülmeye başlar

Bakıp bakıp sana sitem ederim

Kışlalarda bayram zordur askerim

Bu bayram sensiz ilk bayramım oldu

İçimde sıkıntı, gözlerim doldu

Seviyorum diyen, yâr gelmez oldu

Bu yüzden gönlümde taştı kederim

Kışlalarda bayram zordur askerim

	(Batman - 12.11.2004)', 'Bugün bayram günü, bağrım yanıyor Gözlerim yollarda seni arıyor Herkes sevdiğini, bulmuş sarıyor Benimse yollarda kaldı gözlerim Kışlalarda ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Toğluk']::text[], 8.5, '{"poet":"Mehmet Selim Toğluk","poet_slug":"mehmet-selim-togluk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kislalarda-bayram-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Kuşları', 'gurbet-kuslari-yavuz-agir-75tdo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimbilir nerdesiniz...

Hangi diyarda gezersiniz

Neler gördünüz neler...

Anlatın bana gurbet kuşlar

Sonsuzluğa kanat çırptınız...

Yıldızlara göz kırptınız

Bulutların içine sızdınız...

Anlatın bana gurbet kuşları.

Günlerdir yolunuzu bekledim

Gecemi gündüzüme eklerim

Yanlızlığa çare ararım

Mutlaka gelin gurbet kusları.

                Neler gördünüz anlatın bana 

                 Gurbet kuşları...', 'Kimbilir nerdesiniz... Hangi diyarda gezersiniz Neler gördünüz neler... Anlatın bana gurbet kuşlar Sonsuzluğa kanat çırptınız... Yıldızlara ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gurbet-kuslari-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklar I', 'uzaklar-i-salih-demirci-if46a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Günlerin arasından

Karbon kağıdını çekip

Bakımsız düşleri 

Budamak', 'Günlerin arasından Karbon kağıdını çekip Bakımsız düşleri  Budamak...', ARRAY['Türk Edebiyatı','Şiir','Salih Demirci']::text[], 8.5, '{"poet":"Salih Demirci","poet_slug":"salih-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/uzaklar-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Sevdası', 'aksam-sevdasi-yavuz-agir-gdjxb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Akşam karalık olunca 

Gündüzümü beklerim

Karanlığa dalar 

Aydınlığı beklerim

Derin sevdalara dalar 

Aşkımızı beklerim

Hasta olan şu kalbime

Sende derman beklerim

Akan suya set çekerim

Girip ıslanmak için

Haykırırım dağlara

Sana kavuşmak için.', 'Akşam karalık olunca  Gündüzümü beklerim Karanlığa dalar  Aydınlığı beklerim Derin sevdalara dalar  Aşkımızı beklerim Hasta olan şu kalbime ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aksam-sevdasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arafat''ın anısına', 'arafat-in-anisina-salih-demirci-vw6ty', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'intifada sürüyor

yaşasın tam bağımsız FİLİSTİN

GÜNDE MUM

Bulutlarda biçilen yangınları

Hangimizin gözleri görür

Ya da

Kaç mumluk özlemimiz

Var,yarınlara

Maalesef

Bizler bilmesek de

Filistinli bir çoçuğun

Yüreğinde ki

Taş parçası kadar

Büyüktür bugün', 'intifada sürüyor yaşasın tam bağımsız FİLİSTİN GÜNDE MUM Bulutlarda biçilen yangınları Hangimizin gözleri görür Ya da Kaç mumluk özlemimiz V...', ARRAY['Türk Edebiyatı','Şiir','Salih Demirci']::text[], 8.5, '{"poet":"Salih Demirci","poet_slug":"salih-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/arafat-in-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehirsel Düşler', 'sehirsel-dusler-tamer-kasikci-8nmn1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimselere diyemedim bu  gizli derdimi

bir sabah vakti ardına düşüp

beni düşünmeden uyandıran rüzgarın

şehir şehir aradım yanlızlığımı

döndüğümde elimde kuru bir gül vardı

Şehrin koyu hasreti

ve ben kimselere diyemedim gizli derdimi...

her coğrafyadan bir çiçek koparıp

yapıştırdım narin vücuduma

her iklimin ayrı ayrı sıcağını tutup

biriktirdim titreyen nefesimde

en nadide zümrütü buldum

döndüğümde vermek için

 kulesinde oturan kıza

ve iki boğaz arasında

demirli her gemiye

bir bayrak getirdim 

başka şehirlerden

ne şiir gibi bir Şehir var

ne de Şehir gibi bir şiir

yar deyip sarıldığım her urbanın içinde

boşluktan yontulma bir iskelet

dost deyip yaslandığım her dağda

mevsim kış

en derin okyanuslara atsam 

az gelir Şehirsel düşlerimi

oysa ben kimselere diyemedim bu gizli derdimi...', 'Kimselere diyemedim bu  gizli derdimi bir sabah vakti ardına düşüp beni düşünmeden uyandıran rüzgarın şehir şehir aradım yanlızlığımı döndüğ...', ARRAY['Türk Edebiyatı','Şiir','Tamer Kaşıkçı']::text[], 8.5, '{"poet":"Tamer Kaşıkçı","poet_slug":"tamer-kasikci","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sehirsel-dusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçüstü', 'sucustu-i-smet-barlioglu-qd2dr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ahmet İsmailoğlu çok ünlü bir tacirdi,

Bu ülkeye yerleşmiş eski bir muhacirdi.

Kopmuşlardı Balkan ‘ın deresinden, düzünden,

Bir tek kurşun atmadan, salt bir domuz yüzünden.

Domuzlar müslümana hem murdardır, hem haram,

Kafir ise gösterir domuza bin ihtiram.

Müslüman domuz yemez, gavur geberir buna,

O yüzden geldi bu halk kafirin oyununa.

Örneğin; domuzları bir pınara sürdüler,

Müslümanı pınardan sildiler, süpürdüler.

Domuzun dokunduğu ol pınar mekruh oldu,

Müslüman ondan gayri pınarlara koyuldu.

Bastı domuz tarlaya, tarlayı mekruh etti,

Müslüman, ayağını tarladan beri çekti.

Domuz nerye değdiyse Müslüman uzaklaştı,

O kaçtıkça domuzlar her bir yere ulaştı.

Müslümanlar böylece göç ettiler oradan,

Koca Balkanlar gitti bir tek kurşun atmadan.

Plevne türküleri bize kaldı sadece,

An Tuna Boyları ‘nı artık gündüz ve gece.

Aliş ‘imin kaşları atçıda gönle yara,

Alişler hiç yanmadı koskoca Balkanlar ‘a.

Hayduda bıraktılar o güzel diyarları,

Vardar Ovası için çektiler kafaları.

Ahmet İsmailoğlu cıscıbıl geldi yurda,

Beslenip palazlandı ve huzur buldu burda.

Zira; it vardı ama domuzdan hiç eser yok,

Üstelik köpeklerin karnı toktan daha tok.

Halk ekmek kapışırken çamurların içinden,

İtler usanmışlardı etinden, pilicinden.

Gökdelene baksan; it, yalılara baksan; it,

İtlerin elindeydi yeşil ışıklı geçit.

Ahmet İslamoğlu tek fırsat kaçırmadı,

Görünce laçkalığı tırmandıkça tırmandı.

Bir ayda dikiverdi ‘Evcağız’ ı tarlaya,

Birkaç it geliverdi hep hırlaya hırlaya.

Attı İsmailoğlu önlerine kemiği,

Ondan sonra açıldı şansı iyiden iyi.

Yanındaki tarlaya sürdü bir kocaöküz,

Yer bir başkasınınmış. Dediler: ‘Öldürürüz.’

Çekiverdi öküzü özürler dileyerek,

Az bir süre bekledi ahırda besleyerek.

Son yeniden sürdü bir çayıra hayvanı,

Ne arayanı çıktı, ne de kalkıp soranı.

Demek; yer sahipsizdi; olmadı tepki veren,

Ne çıkıp engel olan, ne bir haber gönderen.

Belki de; sahipleri yurtdışında bir yerde,

Yer İsmailoğlu ‘na yazılmışmış kaderde.

Çekti tarlaya çit-mit, sahiplendi çayırı,

Böylece elde etti birçok tepe-bayırı.

Ağılda mal besledi, kurdu peşpeşe işlik,

Kime nasip olurdu öyle bir gelişmişlik? 

Yayıldıkça yayıldı, her branşa elattı,

Ayağını doğudan ta batıya uzattı.

Oteller, pastaneler, tatil-matil köyleri,

Para kaynağı yaptı dere ve tepeleri.

Suyu, havayı sattı kapalı şişelerde,

Kaçak içki sattırdı karanlık köşelerde.

Haşlanmış patatesler kattı tereyeğına,

Esrar-mesrar gönderdi alanın ayağına.

Kurdunu ayıkladı depoda peynirlerin,

Tuğla tozu ekledi içine biberlerin.

Sabunları bekletti nemli-memli anbarda,

Pirinçlerle birlikte gider oldu taşlar da.

Kurdu paravan şirket, hacca hacı gönderdi,

Ol ‘Hacıbabalar’ ı Armutlu ‘ya indirdi.

Hacılar şaşakaldı mayolu avradlara,

Kavurucu kumsalda gel de ‘Hazret’ i ara.

Van yerine Pendik ‘e turdur ki düzenledi,

Muş ‘a düşen yolcular Kars ‘a geldik belledi.

Topladı tüm mıncımış karpuzları hallerden,

Dışsatım malı diye geçirdi gümrüklerden.

Doldurdu şileplere, Alman alacak diye,

Döküverdi denize, mal koymadı geriye.

Almanya ‘ya uzanıp bankalara dayandı,

Kendisine paralar kendisince yollandı.

Aldı karpuzlarının ‘Vergi İadesi’ ni,

Varın sizler öngörün buradan ötesini.

Adam bir büyük adam. Adam değil, Padişah,

Yanında teb ‘a kalır en haşmetlu Şehinşah.

Yaşı elli-ellibeş, sarı bir saç, sarı yüz,

Bedeni kanlı-canlı, hem çok yağlı, hem gürbüz.

Yaman parababası, soylunun dürdanesi,

Hakkını yersek; haram; Yesun oni nenesi.

Üstünde bir elbise; İngiliz kumaşından,

Çıktığı görülmemiş beresinin başından.

Printemps ‘dan giyinir, Benetton ‘dan soyunur,

Öyle insan ülkede inanın; zor bulunur.

İşlerini yönetir İnşaat Şirketi ‘nden,

Becerir de incitmez sinekleri, belinden.

- 2 –

Ahmet İsmailoğlu içerken kahvesini,

Duydu telefonunun masasından sesini,

Kaldırdı ahizeyi, lütfen bir ‘Alooo! ...’ dedi,

Sonra karşısındakinin sözlerini dinledi.

Şöylece söyleştiler oteki ve buteki:

‘Biz boru arıyoruz, borunuz vardır belki.’

‘Borunun her türü var, sizinki hangisinden? 

Avrupa ‘sı iyidir bizim bu yerlisinden.

Elbet fiyat farkı var ikisi arasında,

Yerlisi çatlar-matlar kullanım sırasında.’

Müşterinin sesinde belli bir öfke vardı,

Anlattığına göre yerliyi ararlardı.

Adam dedi: ‘Efendim, Avrupa ‘yı boşverin,

Gavurdan hoşlanmayız, lütfen bizi hoşgörün..

Yerli malı Türk malıi Türk gibi dayanıklı,

Kullanırsa kullansın gayriyi, kanayaklı.

30 Santim boyunda kurşun boru isteriz,

Parası ne kadarsa peşin peşin öderiz.’

İsmailoğlu dedi: ‘Parasını düşünme; 

İstersen peşin ver, istersen taksit öde.

Borular uzun ama keseriz 30 santim,

Kestikçe istifleriz üstüstüne tin tin tin.’

Adam sordu: ‘Efendim, gönderilebilir mi? ’

‘Elbette göndeririz. Bu sorun edilir mi? 

Yeter ki; siz belirtin gönderilecek yeri,

Yollarım kapınıza burdan bizimkileri.

Biraz mal getirseler; kırılır mı elleri? 

Siz miktarı söyleyin, borunuzu verelim,

Bir de bize bildirin; nereye gönderelim? 

Alıcı güle güle dedi: ‘Hiç göndermeyin,

Münasip yerinize yerleştirip bekleyin.’

Telefon kapanmıştı tam o anda ‘Çat’ diye,

İsmailoğlu dedi: ‘Al sana iftariye.’

- 3 –

Ben diyeyim ‘Bir saat’, siz deyin ‘İki saat’,

Kendine gelemedi İsmailoğlu fakat.

Çok düşündü taşındı, hiç anlam veremedi,

Neden işletmişlerdi? Asla öğrenemedi.

Kırılmıştı gururu, titriyordu elleri,

Pencereden izlerken önünden geçenleri.

Aklı telefondaydı. Bakıyor, görmüyordu,

İçine kapanmıştı, kendini dinliyordu.

Derken dilleniverdi telefonu masada,

Ah bir fırça çekseydi; bir o herif olsa da.

Ses hiç o ses değildi; kibirliydi, hakimdi,

Tek tek konuşuyordu, hem ciddi, hem sakindi.

Dedi: ‘Bayım merhaba. Ben komser falan filan,

Bura falan karakol, masamız da feşmekan.

Bir ahlaksız türemiş; dul karı büyütmesi,

Rahatsız eder durur telefonla herkesi.

En ünlü tacirlere telefon açıyormuş,

’30 Santimlik boru alacağız.’ diyormuş.

‘Kalınından bir boru; hem kurşundan, hem yerli.’,

Bilmem ki; bu ahlaksız kimlerdendir, nereli? 

Soruyormuş ‘Mümkün mü göndermeniz? ’ diyerek,

‘Gönderelim deyince ekliyormuş gülerek:

‘Göndermeyin ve sokun münasip yerinize.’

Böyle şey dediler mi acep bir kez de size? 

Dedilerse; söyleyin, ahlaksızı bulalım,

Yakalayıp pisliği hesap-mesap soralım.

Ele geçirip iti götüreyim merkeze,

Orada öptüreyim mevcud olan herkese.’

Ahmet İsmailoğlu boşandı kıyasıya,

Komisere anlattı ne geldiyse aklına.

Dedi ki; ‘Komiserim davacıyım o itten,

Dünyada ve ahrette o ellilik simitten.

Gösterelim sapığa ‘Münasip yer’ nereymiş,

Öğrensin ki; oraya boru nasıl girermiş? ’

Komser dedi: ‘Efendim, telaşa kapılmayın,

Size ne zaman dedi? Siz onu vurgulayın.’

İsmailoğlu dedi: ‘Bir saattir, inanın.’

Komser güldü: ‘Çok fazla kalmış, artık çıkarın.’

Arkasından telefon kapandı ‘Çat’ sesiyle,

Ahmet İsmailoğlu tanıştı stresiyle.

Dedi: ‘Bizi boş buldu ahlaksız, tabak gibi,

Öylesine oydu ki; dolmalık kabak gibi.

‘Çok kalmış’ mış ‘Çıkarın’. Olur mu lan böyle laf? 

Edeyim de şimdi gör, senin ananı tavaf.’

- 4 –

Ahmet İsmailoğlu şapka taktı bereye,

Kim görüp altındaki bereyi irdeleye? 

Giyindi paltosunu, aldı şemsiyesini,

Öfke ile kavradı bastonun tepesini.

Buyruktur ki yağdırdı koşan adamlarına,

Adamlar şaşkın şaşkın baktı patronlarına.

Böyle görmemişlerdi patronlarını, kızgın; 

Adam oluvermişti sanki vahşi bir kuzgun.

O gitti, onlar baktı arkasından merakla,

Dediler: ‘Ulu Tanrı ‘m, bunu sen koru, sakla.

Herif tam keskin sirke; küpünü patlatacak,

Ya birini vuracak, ya kalkıp oynatacak.’

Şoförü koşuşturup açtı arka kapıyı,

Adam söyleniyordu. Kesmedi lakırdıyı.

Bindi İsmailoğlu, ‘Çek’ dedi ‘karakola.’,

‘Daha ne bekliyorsun? Sürsene be budala.’

Özel araç canlanıp asfalt yola atıldı,

Yoldaki arabalar konvoyuna katıldı.

Şu senin, bu da benim ve karakol göründü,

Oto durdu kapıda, bizimki yere indi.

Karakola dalışı yellere benziyordu,

Zira; aklı içinde öfke kolgeziyordu.

Girdi ki; makamda var vakur, ciddi bir komser,

‘Karakol’ dediğinde yılışıklık ne gezer.

Bizimki oturmadı, yere-mere bakmadı,

Şikayet arzederken asla duraklamadı.

Dedi: ‘Sayın komiser, ben kendim davacıyım,

Sorunumu halledin, sizlere duacıyım.

Biri telefon açtı yerimde otururken,

Bana bir madik attı öyle durup dururken.

‘Boru mevcud mu? ’ Dedi. ‘Evet boru var.’ Dedim,

Bende mevcud olanlar hakkında bilgi verdim.

İstedi 30 santim boyunda kurşun boru,

Dedim: ‘Gönderelim mi istediğin boruyu? ’

‘Hayır.’ Dedi. ‘Gönderme. Sok münasip yerine.’,

Gururum zedelendi bu sözler üzerine.

Bir saat sonra çaldı telefon, ben dururken,

Bana yapılan şeye öfkeden kudururken.

Bu seferki belirtti komiser olduğunu,

Öyle sapık bir iti arayıp durduğunu,

O nedenle de sordu benden böyle birini,

Ben hemen onayladım komserin sözlerini.

Sordu söylendiğini sözün ne kadar önce,

Güldü, ‘Bir saat önce’ dediğimi duyunca.

Resmen dedi: ‘Çok kalmış. Çıkarsana sen onu,

Yoksa fazla mı sevdin borunun kurşununu? ’

Ahmet İsmailoğlu, dedi; ‘Bu yüzden geldim,

Suçluyu bulmanızı istiyorum, efendim.’

Komiser dik dik baktı gözlüğünün üstünden,

Davacıyı döndürüp inceledi geriden.

Dedi: ‘Aman efendim, çıkarır mı hiç insan? 

İşlem yapamayız ki; kurşun boru olmadan.

Şurya gelene kadar sanki duramamışsın,

Adam seni aldatmış; boruyu çıkarmışsın.

Yerinde kalsa idi 30 santimlik boru,

Söz konusu olmazdı ne sorun, ne de soru.

Biz de kalkıp şahane bir suçüstü yapardık,

O ahlaksız herifi çıra gibi yakardık.

(ARAP isimli Şiirsel Gülmeceler ''inden > 65-74/100)', 'Ahmet İsmailoğlu çok ünlü bir tacirdi, Bu ülkeye yerleşmiş eski bir muhacirdi. Kopmuşlardı Balkan ‘ın deresinden, düzünden, Bir tek kurşun a...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":229,"source_url":"https://www.antoloji.com/sucustu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türküler', 'turkuler-cigdem-bir-genc-tvof7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Türküler...

Dörtnala koşturan doru atları sevdamın...

Ve özlemler...

kırbaç olup  yaralar...

kırbaç olur yaralanırım

kalabalık bir yalnızlığın orta yerinde 

ve  gitgide... 

ve durmaksızın...

çoğalıyor muyuz ne? 

Çoğaldıkça uzaklaşıyor şehirler

Uzaklaştıkça boy veriyor  taptaze bir yalnızlık

Türküler...

Yüreğimin  çiçekleri...

Ve kekik kokulu sabahlar...

Ana sütü...

Bakir yanı hayatın...

Kulak ver...', 'Türküler... Dörtnala koşturan doru atları sevdamın... Ve özlemler... kırbaç olup  yaralar... kırbaç olur yaralanırım kalabalık bir yalnızlığ...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/turkuler-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk...', 'ask-i-mdat-ozcan-n8mqp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk başkadır adamım 

Bazen fırtınalı deniz 

Bazen durgun ırmaktır 

Sıkı bir poyrazdır aşk 

Bazen güneşsiz sabah 

Anlamsız zamansız binlerce hecedir bazen 

Oturup düşüncesizce şiirler yazmaktır 

Ağız dolusu tebessümler takınıp 

İnadına inadına yaşamaktır... 

Aşk başkadır adamım 

Bazen uykusuz gece 

Bazen rüyasız uyku 

Adreslenmiş binlerce fotoğraftır 

Hoşcakalların gölgesinde 

Sevgiliyi düşünmek 

Bazen onsuz kalmaktır 

Uçmaktır bazen gökyüzünde kanatlanıp 

İnadına inadına yaşamaktır... 

Aşk bambaşkadır adamım 

Gülümsemektir 

Selam vermektir tanıdık tanımadık herkese 

Ağaçlarla konuşup, çiçekler koklamaktır 

Yolların farkedilmezliğidir bazen 

Engellerin aşılmışlığı 

Irakların hoş gelişidir 

Bazen ışıldayan birçift göz 

Bazen neden söylendiği belli olmayan 

Bir çift sözdür 

Haykırmaktır avaz avaz 

Seviyorum diye 

Hayatın zevklerini tatmaktır 

İnadına inadına yaşamaktır...', 'Aşk başkadır adamım  Bazen fırtınalı deniz  Bazen durgun ırmaktır  Sıkı bir poyrazdır aşk  Bazen güneşsiz sabah  Anlamsız zamansız binlerce ...', ARRAY['Türk Edebiyatı','Şiir','İmdat Özcan']::text[], 8.5, '{"poet":"İmdat Özcan","poet_slug":"i-mdat-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ask-304-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İspinoza Ağıt', 'i-spinoza-agit-tamer-kasikci-x2dje', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ne var zamanın ardında bıraktığı

alıp başını giderken bir nefes aralığında

ne var ihtiyarın dönüşünden bize kalan

üç beş hazin hikayeden başka

insan bilir mi katıksız özgürlüğün tadını

bilse yaşar mı baştan aşağıya beton şehirlerde

bir ispinoz ölür demir kafesler içinde

doğa binlerce ispinoz doğurur ağaç kovuklarında

kim bırakıp kaçmış bu silahları ortalarda

vurup mavili kadını kalbinden

kimden emanet bu teller etrafımızı kuşatmış

aslında bilinen tüm sınırlar dünden

  kral bilir mi köylülerin özgürlük türkülerini

bilse vazgeçmez mi gösterişli saraylardan

değişir zaman, ispinozlar ölür cehaletle bir,

 inadına, vazgeçmez doğa yenilerini yaratmaktan', 'ne var zamanın ardında bıraktığı alıp başını giderken bir nefes aralığında ne var ihtiyarın dönüşünden bize kalan üç beş hazin hikayeden baş...', ARRAY['Türk Edebiyatı','Şiir','Tamer Kaşıkçı']::text[], 8.5, '{"poet":"Tamer Kaşıkçı","poet_slug":"tamer-kasikci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ispinoza-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi-Kötü', 'i-yi-kotu-tamer-kasikci-biqsv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'içimde sırlı bir ayna cesaret

yansıdıkça insanlar parçalanıyor

içimde taze bir gül gelecek

büyüdükçe insanlar sararıyor

içimde bir kurşun yarası cehalet

arttıkça insanlar ağırlaşıyor

içimde ölümsüz bir güneş sanat

yazdıkça insanlar kararıyor', 'içimde sırlı bir ayna cesaret yansıdıkça insanlar parçalanıyor içimde taze bir gül gelecek büyüdükçe insanlar sararıyor içimde bir kurşun ya...', ARRAY['Türk Edebiyatı','Şiir','Tamer Kaşıkçı']::text[], 8.5, '{"poet":"Tamer Kaşıkçı","poet_slug":"tamer-kasikci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/iyi-kotu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Umut', 'son-umut-talip-kaplan-dwmqk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kapandı bir kapı

Kilitledi kendini son umut

Yaşamadığım bir hayatla

Yüzüstü ve de yapayalnız

Dengesizlik, bunalım ve öfke

Çaresizlik, yoklukla başbaşa

Duvarlara duvarla destek verip

Bir hiç uğruna sensizim...

(19 Nisan 1996)', 'Kapandı bir kapı Kilitledi kendini son umut Yaşamadığım bir hayatla Yüzüstü ve de yapayalnız Dengesizlik, bunalım ve öfke Çaresizlik, yokluk...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/son-umut-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TR 02/ Adıyaman''a', 'tr-02-adiyaman-a-fevzi-gunenc-7p3a8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana Adıyaman''ı anlat Doğa 

Benim göremediğim. senin gördüğün 

o güzel kenti anlat kızım... 

Sanırım adı gibi yamandır insanları 

sıcaktır yürekleri iklimleri gibi 

bana Adıyamanı anlat Doğa. 

Orada da var mı bir Yeni Cami 

hürriyet Caddesi Atatürk Bulvarı... 

Özgürlük Alanı

''Orada da geçiyor'' mu ''günler 

beklenen özlenen günler...''

''gitmesek de görmesek de 

o kent sizim kentimiz,'' değil mi 

Bana Adıyaman''ı anlat Doğa. 

''Billur dereleri var'' mı gerçekten 

şairlerin anlattığı gibi, oranın da 

''sümbül kokar'' mı ''mor dağlar''ı 

Orada da sever mi sevilir mi insanlar 

aşk kırgınları var mı orada da 

Bana Adıyamanı anlat Doğa. 

İyi ki adı yaman Adıyaman''ın 

iyi ki ''adı Yemen'' değil 

ya ''giden gelmiyor'' olsaydı 

''acep neden'' bilinmiyor olsaydı 

gidenlerin severek kaldığı

 sevinerek döndüğü 

Adıyaman''ı anlat bana kızım

Doğa! ..', 'Bana Adıyaman''ı anlat Doğa  Benim göremediğim. senin gördüğün  o güzel kenti anlat kızım...  Sanırım adı gibi yamandır insanları  sıcaktır y...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/tr-02-adiyaman-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yas', 'yas-baykal-kaanalp-jefeh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bitirim bir sıkıntı zinciri

boğuyor kılcaldamarlarımı

kulakları sağır edercesine

yakıyor sessizliğimi

dilim damağıma yapışık

açılmıyor gözü dönmüş

sesler hala çınlatıyor

kalpler buna alışık

sancılar tutmaz elimi

artık sonuca gebe

yersiz yurtsuz bir gemi

dolaşır durur güvenliğimde

biteceğini bilerek başlarım

yıkamaya tüm mutsuz anları

kıymete değer bu uğraş

içimdeki tüm bazları taşlarım', 'bitirim bir sıkıntı zinciri boğuyor kılcaldamarlarımı kulakları sağır edercesine yakıyor sessizliğimi dilim damağıma yapışık açılmıyor gözü ...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yas-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiğin günden beri', 'gittigin-gunden-beri-ercan-eyvaz-bgxp6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senimi benden alıp gittiğin günden beri

Ne sen oldun nede bir başkası şimdi

Gözlerim gözlerinden elin elimden gideli

Ne sabahıma güneş doğdu nede geldi uyku geceleri

Senimi benden alıp gittin günden beri

Ne sevdim tekrar yeşili nede maviyi

Ağzıma sürmediğim sigarayı içkiyi

Masama davet ettim dost bildim geceleri

Senimi benden alıp gittiğin günden beri

Elimde kalemim kulağımda sesin kalbimde sevgimi

Paylaştığım sensizlikle geçirdiğim günleri

Haykırıp kızıp sana, atamadım kalbimden seni

Senimi benden alıp gittiğin günden beri

Sabaha  öyleye nefes aldığım her saniye

Bastığım topraklara  imrendiğim sevgililere

Her dizilişte yine mars oldum sensizliğe', 'Senimi benden alıp gittiğin günden beri Ne sen oldun nede bir başkası şimdi Gözlerim gözlerinden elin elimden gideli Ne sabahıma güneş doğdu...', ARRAY['Türk Edebiyatı','Şiir','Ercan Eyvaz']::text[], 8.5, '{"poet":"Ercan Eyvaz","poet_slug":"ercan-eyvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gittigin-gunden-beri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fizik Tedavi', 'fizik-tedavi-turgay-akbulut-rg66g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kireçlenen omuzumun tedavisi,

gençliğimde

köhnemiş düzenlere karşı başkaldırdığım

kol hareketleriymiş...

epeyce zaman oldu

biz çekileli zulaya

kirlendi dünya

hani diyorum

yeniden başlasak mı

katılaşmış düzenlere karşı

hazır kaldırmışken kolumu

havaya...', 'kireçlenen omuzumun tedavisi, gençliğimde köhnemiş düzenlere karşı başkaldırdığım kol hareketleriymiş... epeyce zaman oldu biz çekileli zula...', ARRAY['Türk Edebiyatı','Şiir','Turgay Akbulut']::text[], 8.5, '{"poet":"Turgay Akbulut","poet_slug":"turgay-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fizik-tedavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pazar', 'pazar-ercan-eyvaz-697ac', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her hafta buluşma günümüzdü pazar 

Cumartesiden kalma heyecan kalbimde

Seni görünce sakarlıklarım olurdu aniden 

Ya bakışların eritirdi beni yol ortasında

Seni beklerken diyeceklerimi bir bir sıralayıp

Sonra gördüğümde birden unutup hatırlayamayıp

Devamıydı gülüştüğümüz 

Pazar günümüz vardı

Haftanın hasreti pazara biriktiğinde 

Albüm misali  gözümün önüne geldiğinde 

Ellerinden tutup, sarılıp dolaştığımız 

Bir Pazar günümüz vardı 

Altı koca gün yıl gibi gelirken 

Buluştuğumuz gün dakikalar gibiydi sanki

Geç gelipte çabucak biten 

Bir pazar günümüz vardı....', 'Her hafta buluşma günümüzdü pazar  Cumartesiden kalma heyecan kalbimde Seni görünce sakarlıklarım olurdu aniden  Ya bakışların eritirdi beni...', ARRAY['Türk Edebiyatı','Şiir','Ercan Eyvaz']::text[], 8.5, '{"poet":"Ercan Eyvaz","poet_slug":"ercan-eyvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/pazar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl', 'nasil-baykal-kaanalp-oxgqb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'içiniz daha fazla

sızlamasın diye

üstünü örtüyorum

görmek zorunda olduklarımın

görüntüler bazen anımsatır

zincirlerini bağladıklarımın

kendime sormadan 

bıkmadan usanmadan

üzülmesin gönlünüz diye

aşıklara bir hal olmuş

gizli gizli değil aleni

sevdalılar birbirlerine

açığa çıksın diye

sevinçleriniz,kızarır bozarırım

nasıl mutluluk hapı

üretebileceğim diye', 'içiniz daha fazla sızlamasın diye üstünü örtüyorum görmek zorunda olduklarımın görüntüler bazen anımsatır zincirlerini bağladıklarımın kendi...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nasil-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Habersiziz', 'habersiziz-baykal-kaanalp-fd9ki', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kimin umurundaki

kaçıp giden

uğursuz zaman

dilimleri ufak ufak

kestirilmiş hızarda

kim farkındaki

koptuğunun iplerinin

elimizde tuttuğumuzu

zannettiğimiz

yanıp sönen ışıklarını

kadranı çok küçük

anahtarın

sahibi biziz

ama habersiziz

bize ait olmadığının

kumun', 'kimin umurundaki kaçıp giden uğursuz zaman dilimleri ufak ufak kestirilmiş hızarda kim farkındaki koptuğunun iplerinin elimizde tuttuğumuzu ...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/habersiziz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TR 01/ Adana''ya', 'tr-01-adana-ya-fevzi-gunenc-ssckv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kez içen

en az yedi kez

içer derler suyundan daha... 

Belki yüz kez içtim ama

yüzünü bir kez bile göstermedin

onun bana...

Yine de teşekkür ederim

on kere yüz kere bin kere

gönül borcum olsun sana

bir gün görürüm umudunu yitirmediğim 

ilk sevgilimi yüreğinde saklıyorsun Adana.', 'Bir kez içen en az yedi kez içer derler suyundan daha...  Belki yüz kez içtim ama yüzünü bir kez bile göstermedin onun bana... Yine de teşek...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tr-01-adana-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Acımıyor', 'hic-acimiyor-baykal-kaanalp-7xhrf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yıllar yılı

kendilerini incitmekten

korkarak biriktirdiğim

bir çok acı

şimdi acıtıyor

yumuşak dokumu

tek tek çizerken

kansız vücut çizgilerimi

bana hiç acımıyor', 'yıllar yılı kendilerini incitmekten korkarak biriktirdiğim bir çok acı şimdi acıtıyor yumuşak dokumu tek tek çizerken kansız vücut çizgileri...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hic-acimiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızsa Yüreğin', 'yalnizsa-yuregin-ahmet-altintas-klc03', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilirmisin neyi özlerim

Akşam olurken gün batımında

Kuş sesleri arasında

Yalnızlığı yudum yudum içerken

İsterim karşımda gerçek dost varken

Nedensizce tebessüm ederken

Ellerim dolsun bir yudum sıcak çay içerken

Dostun gülümsemesindeki hazzı

Umarsızca beklenilen sonbaharı yazı

Raksederken çalan sazı

Mutluluk sevinç bazı

Arada birde o en güzel hazzı

Zaman zaman  özlerim

Gelirmi diye hep beklerim

Özlemimdir yüreğimde hep severim

Zehirden beterdir yalnızlıksa kaderin

Lal olursun konuşamazsın çıkmaz sözlerin

Emekleyerek geçer zor günlerin

Ruhun boştur kelepçeli ellerin

İstesende gülemez gözlerin

Mutluluğu yaşayamazsın yalnızsa yüreğin', 'Bilirmisin neyi özlerim Akşam olurken gün batımında Kuş sesleri arasında Yalnızlığı yudum yudum içerken İsterim karşımda gerçek dost varken ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altıntaş']::text[], 8.5, '{"poet":"Ahmet Altıntaş","poet_slug":"ahmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yalnizsa-yuregin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvardaki resminin önünde.', 'duvardaki-resminin-onunde-ali-osman-yilmaz-514a1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duvara asmıştım ya resmini,

O duvar bana,

Kabe oldu sevdiğim.

Senden kalan ne varsa,

Astım duvara bir bir,

Duvardaki resminin yanına.

Odaya her girdiğimde,

Duvardaki resminle,

Senden kalan ne varsa,

Anılarla sarmalanmış,

Bakar bana duvarda.

Hasretinle yanarım,

Gözlerim yaşlanır,

Duvardaki resmine,

Senden kalan anılara,

Hüzünle baktıkça.

Bana kabe olur her gece,

Diz çökerim önünde,

Ellerim semada,

Gözlerim pencerede,

Her gece beni seyreder,

Gökteki yıldızlar ve ay,

Duvardaki resminin önünde.', 'Duvara asmıştım ya resmini, O duvar bana, Kabe oldu sevdiğim. Senden kalan ne varsa, Astım duvara bir bir, Duvardaki resminin yanına. Odaya ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/duvardaki-resminin-onunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşktır Bilemezsin', 'asktir-bilemezsin-osman-i-nci-jf7ip', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaybedersin kendini bazen,

Dağılırsın, kalmaz bir düzen,

Bilir misin, gözünden düşen,

Aşktır işte, sen bilemezsin...

Nefes alamazsın, hava basık,

Hüzün dolar, ağlarsın sık sık,

Duymaz kimseler, sesin kısık,

Aşktır işte, sen bilemezsin...

Gülersin bazen, kahkahayla,

Yaşayıp gidersin, umuduyla,

Mutlu olursun, bir tek rüyayla,

Aşktır işte, sen bilemezsin...

Akan gözyaşına, nedendir o,

Yürekleri yakıp, terletendir o,

Derde düşürüp, inletendir o,

Aşktır işte, sen bilemezsin...', 'Kaybedersin kendini bazen, Dağılırsın, kalmaz bir düzen, Bilir misin, gözünden düşen, Aşktır işte, sen bilemezsin... Nefes alamazsın, hava b...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/asktir-bilemezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz, deniz değil', 'deniz-deniz-degil-erkan-abi-7ybgf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'fikrim sensiz hiç olmamış gibi

hiçbir şeye sevinmedim

yemin olsun sevgilim

günlerim ne başladı

ne de bitti sensiz

...

hiç yaşım yok benim

doğamadım sensiz

yemin olsun sevgilim

ölmeyeceğim sensiz

...

deniz deniz değil

mavi mavi...

karadeniz sanki durgun 

marmarada bir hüzün

ilk kez çarpışma yok boğazda

balıklar inthar ediyor

balıkçı ağlarında 

yemin olsun sevgilim

tadı yok içtiğim rakının

sensiz...', 'fikrim sensiz hiç olmamış gibi hiçbir şeye sevinmedim yemin olsun sevgilim günlerim ne başladı ne de bitti sensiz ... hiç yaşım yok benim do...', ARRAY['Türk Edebiyatı','Şiir','Erkan Abi']::text[], 8.5, '{"poet":"Erkan Abi","poet_slug":"erkan-abi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/deniz-deniz-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Dünya', 'yalan-dunya-ahmet-altintas-8r0jz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğin sızlaması nedir bilirmisiniz

Ağzının tadı olmaz kelimeler düğümlenir boğazında

Lal olur dilin çıkmaz sözlerin

Ağla gözlerim ağla budur mutluluğun senin

Nerde hani nur yüzlü güzel gözlü bebeğim

Dünya bu derler ki hep yalan

Üzülsende bilmez üzenler

Nihayetinde sana kalandır hüzünler

Yalan değilki dünya 

Ağlatanlar üzenler fan olan', 'Yüreğin sızlaması nedir bilirmisiniz Ağzının tadı olmaz kelimeler düğümlenir boğazında Lal olur dilin çıkmaz sözlerin Ağla gözlerim ağla bud...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altıntaş']::text[], 8.5, '{"poet":"Ahmet Altıntaş","poet_slug":"ahmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yalan-dunya-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlığım...', 'karanligim-i-lker-dursun-8mh6h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her yer karanlığa büründüğünde 

Karanlığım içimi aydınlatacak 

Gözlerim görmediğinde içimde pırıldayan ışığın peşinden gideceğim

Göremediğim suçlarım 

Bastıramadığım isteklerim 

Hiç farkına varamadığım ben karanlıkta ortaya çıkacağım

Işığa alıştığında gözlerim

Herkesin penceresindeki hayatı gibi 

Kendi penceremdeki  hayatım

Zamanın karşısında dik durmaya 

Ölümün soğuğunda titrememeye çalışacak

Ben artık ben olduğumda 

Ayrı odalarda farklı şiirler yazan eski aşıklar gibi 

Olmayacağız 

Zaman duracak 

Hayat yeniden başlayacak 

Başka bir bedende bambaşka bir nefesle', 'Her yer karanlığa büründüğünde  Karanlığım içimi aydınlatacak  Gözlerim görmediğinde içimde pırıldayan ışığın peşinden gideceğim Göremediğim...', ARRAY['Türk Edebiyatı','Şiir','İlker Dursun']::text[], 8.5, '{"poet":"İlker Dursun","poet_slug":"i-lker-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/karanligim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bodrum''da Bir Yalnız Martı Yaşıyor (4)', 'bodrum-da-bir-yalniz-marti-yasiyor-4-murat-nail-guney-efj2h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küstüysen bir daha beni arama,

Sevdam merhem olamadı yarana,

Seni yüreğimden atmak var  ama,

Hayalin gözümde her an yaşıyor...

Kuşadası şimdi hüznü soluyor,

Uyandık rüyadan sabah oluyor,

Sevdalar bitince,ömür doluyor,

Ruhum meleklerle kucaklaşıyor...

Özlemin hasrete yenik düşerse,

Aklın gibi yolların da şaşarsa,

Ayakların bana doğru koşarsa,

Bodrum''da '' bir yalnız martı'' yaşıyor...

Muradım,yalnızlık değildir kader,

Bazan kardeş imiş sevinçle keder,

Bayram olur küslük, dargınlık biter,

Bodrum''da bir yalnız martı yaşıyor...

Murat Nail GÜNEY', 'Küstüysen bir daha beni arama, Sevdam merhem olamadı yarana, Seni yüreğimden atmak var  ama, Hayalin gözümde her an yaşıyor... Kuşadası şimd...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bodrum-da-bir-yalniz-marti-yasiyor-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabır', 'sabir-ahmet-altintas-477kh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Susarsın boğazına düğümlenmişken kelimeler

Ağlarken dökülür inci taneler

Bilinemez hayatta yaşanılan hikayeler

Irmaklar oluştursada gözlerinden dökülenler

Razı olmasanda olur sen acı çekerken gülenler

Susup sessizce gitmekmi gerekir

Anlayamazsın sahtedir sevgiler hisler

Bakakalırsın uzaklara göremesende enginleri

Izdıraplarla dolu olsada alışırsın yokluklara

Razı olursun gözyaşlarında bulursun mutlulukları', 'Susarsın boğazına düğümlenmişken kelimeler Ağlarken dökülür inci taneler Bilinemez hayatta yaşanılan hikayeler Irmaklar oluştursada gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altıntaş']::text[], 8.5, '{"poet":"Ahmet Altıntaş","poet_slug":"ahmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sabir-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader', 'kader-ahmet-altintas-97i0l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimsesizlikler içinde kederlerle bir ömür

Ağlamaklı gözlerin dermanın yoktur ayakların durur

Dün nasıldı kimbilir yarın neler olur

Elveda diyemezsin bırakıp gidemezsin

Razı olursun dersin kaderim budur', 'Kimsesizlikler içinde kederlerle bir ömür Ağlamaklı gözlerin dermanın yoktur ayakların durur Dün nasıldı kimbilir yarın neler olur Elveda di...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altıntaş']::text[], 8.5, '{"poet":"Ahmet Altıntaş","poet_slug":"ahmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kader-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Rab Onu Sen Koru', 'ya-rab-onu-sen-koru-ahmet-altintas-z9m3k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yarap sevdiğime vereceğin sıkıntıları

Allahım biriciğime gelecek dertleri

Rabsın ona vereceğin sağlık problemlerini

Alnına yazılmış tüm olumsuzlukları

Bana yönlendir Ya Rab bana ver

Bana bahşettiğin sevinç ve mutlulukları

İstiyorum biriciğime yönlendir

O canım biriciğime olumsuzluklar yaşatma

Nur yüzüne sevinçleri bahşet Ya Rab

Unuttur tüm olumsuzlukları ver mutlulukları

Saadet haznenden sual olunmaz

Ellerimi açmışken semaya gözyaşlarımı görüyorsun

Ne desem ne etsem her şeyi biliyorsun

Kem gözlerden maskeli yüzlerden

Olumsuzluklardan hüzünlerden dertlerden

Ruhumla bedenimle açtım ellerimi geldim kapına

Ulusun sen herşeye kadirsin beni de boş çevirme Ya Rab', 'Yarap sevdiğime vereceğin sıkıntıları Allahım biriciğime gelecek dertleri Rabsın ona vereceğin sağlık problemlerini Alnına yazılmış tüm olum...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altıntaş']::text[], 8.5, '{"poet":"Ahmet Altıntaş","poet_slug":"ahmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ya-rab-onu-sen-koru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne oldu', 'ne-oldu-i-lker-dursun-cee1h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok yorgunum 

İçimdeki kır çiçekleri soldu

Huzur uğramaz oldu bizim eve 

Oysa ne bayramlar geçmişti üstümüzden 

Yalnızlığı ne zaman aldık evimize 

İçimize......

Ne zaman yabancılaştık birbirimize 

Kendimize......

İlk ne zaman ilişti gözlerimize öfke

Sözlerimize.....

Ne zaman düştü gözlerimize ilk çizgiler

Oysa ne bayramlar geçmişti üstümüzden 

Neşeyle 

Şeker tadında...', 'Çok yorgunum  İçimdeki kır çiçekleri soldu Huzur uğramaz oldu bizim eve  Oysa ne bayramlar geçmişti üstümüzden  Yalnızlığı ne zaman aldık ev...', ARRAY['Türk Edebiyatı','Şiir','İlker Dursun']::text[], 8.5, '{"poet":"İlker Dursun","poet_slug":"i-lker-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ne-oldu-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fikrim Gezinip Dururken İstanbul''un Meydanlarında', 'fikrim-gezinip-dururken-i-stanbul-un-meydanlarinda-melih-coskun-sxlct', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Fikrim gezinip dururken 

İstanbul''un kalabalık meydanlarında

Birden eski bir şarkı çınladı kulaklarımda

Yüzümde hissettim ıslak rüzgarlarını

Ve duydum özgürce uçuşan martıların çığlıklarını

Nasıl özledim bir bilsen 

Deniz kıyısında yediğim gevrek bir simiti

Bir bardak demli çayı

Nasıl özledim bir bilsen 

Kardeşimin yüzünü

Anamın o sıcaklığını 

Ve babamın içine gömdüğü

Gözlerinin derinliğinde sakladığı 

O koskocaman sevgisini

Şimdi Küpeli''nin korkunç ıssızlığında

Bir başımayım kendi kendimle

Hiçbir şey ama hiçbir şey gelmiyor aklıma 

Yaşamaktan başka

Altı gün ve altı bitmeyen soğuk gece

Ürkütücü bir ekim gecesiydi dolunayın altında

Ayaklarımın altında ezilirken yirmi üç yaşım

Altı gün ve altı soğuk gece

Ayın altında yürüyen asker gölgeleri

Ayaklarının altında ezilen yüz elli kilometre

Borcudur üvey çocuklarının vatana faiziyle ödedikleri

Buralarda dağlar öyle güzel

Ve öylesine acımasız ki

Dünyanın en güzel çiçekleri buralarda açar

Buralarda yakılır en gerçek türküleri yurdumun

Bütün bunlar geçerken aklımdan 

Başımın üzerinden geçer ıslığıyla top mermileri 

Ayaklarımın altında binlerce mayın 

Tek umududur dağ köylerinde

Acı yüzlü esmer çocuklarının

Asker kumanyası 

Ve bir asker selamı 

HAKKINI HELAL ET HEWAL! 

BEN SENİN İÇİN BURDAYIM...

29 EKİM 2004

ŞIRNAK', 'Fikrim gezinip dururken  İstanbul''un kalabalık meydanlarında Birden eski bir şarkı çınladı kulaklarımda Yüzümde hissettim ıslak rüzgarlarını...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/fikrim-gezinip-dururken-istanbul-un-meydanlarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabanıl kentleşme önsözü,', 'yabanil-kentlesme-onsozu-mutlu-ayar-wk0pg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '“yüzeysel titreşim içinde soluyorum 

saksız bakışlarımda yurt güzelliği 

derinden düşüyor gözlerim yeşile 

yağmurun içinde buruk damlalar 

yalnızdır, damlarlar ve yürek izleri 

biz insanlar ne çok yaşarız ölerek 

biz insanlar katarak güneşi suya, kime 

daha üşürüz, kime ne çok düşünürüz, 

çekimser yer çekimi içinde soluyorum 

hayır, çekmeseydi sizi tanımazdım 

yüzünüzü bana sürdünüz ilk önce 

beş yüz oldunuz bu yüzsüzlüğünüzle 

içinizde sağır bulantılar gezerken 

uzaklığımı severek komşu oldunuz 

demircinin karısı sertlikten yumuşamış 

yorgan altı karanlığına tutulmuştunuz 

sorunsal sessizliğin doygunluğuna 

eriyordu yaz, ardında gök ve kuşlar 

ben ise d-üzüyordum kendimi, kendimle 

sizlenerek alın yazım ve gizlenerek 

ürüyordum gölgemle, ki o beni paklar 

gidin uzak durun ey sonsuz martılar 

tüyünüz ben olamadım saramadım 

sütünüz kesilirken ortasından kan revan 

varamadım sizinle nemli yorganlara 

yumuşak izlerim var durgunluğunuzda 

sabah yorgunluğunu sararak üzerime 

ve dokunarak açlığınızın en cinsel yerine, 

yakını duyamam yakında olduğum halde 

bozardım bilseydim kentin çelik saflığını 

tıpkı umudun bozguna uğradığı yerde aşk 

mermere tırtıklanan yorgun ismi gibi şairin, 

kuntluğuna vurgun bir kurt olarak! “

13.11.o4 / o1:2o', '“yüzeysel titreşim içinde soluyorum  saksız bakışlarımda yurt güzelliği  derinden düşüyor gözlerim yeşile  yağmurun içinde buruk damlalar  y...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yabanil-kentlesme-onsozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicazkâr / Acemkürdî... (2x4’lük)', 'hicazk-r-acemkurd-2x4-luk-atakan-kartaltepe-5a210', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni bu şarkılar ağlattı...yine de ağlatacak...

Bana bu şarkılar sevdirdi...yine de sevdirecek...

Beni bu şarkılar güldürdü...yine de güldürecek...

Bu şarkılar var ya, şarkılar...ah! beni öldürecek...

Gönlümü, kalbimi, ruhumu yaktı...kırdı geçirdi...

Rast, Nihavend, Hüzzam, Uşşak ve Hicazkâr, Acemkürdî...

Şarkılar tuttu hayatta ve o’nu bana sevdirdi...

Bu şarkılar var ya, şarkılar...ah! beni öldürecek...

                                                       04.11.2004/16.00

Rast, Nihavend, Hicazkâr,Hüzzam, Uşşak, Acemkürdî: T.S.M. makamları', 'Beni bu şarkılar ağlattı...yine de ağlatacak... Bana bu şarkılar sevdirdi...yine de sevdirecek... Beni bu şarkılar güldürdü...yine de güldür...', ARRAY['Türk Edebiyatı','Şiir','Atakan Kartaltepe']::text[], 8.5, '{"poet":"Atakan Kartaltepe","poet_slug":"atakan-kartaltepe","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hicazkar-acemkurdi-2x4-luk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar, ağaçlar....', 'sonbahar-agaclar-musfik-saltik-zkmby', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Son bahar geldiğinde sararan yapraklar

Hüzün duygusu uyandırır çoğu insanda 

Ben severim son baharı imrenirim ağaçlara.

Çırılçıplak kalsalar da  bütün kış

Dimdik ayakta kalırlar direnirler 

Diplerine dökülür kuru yaprakları

Ağaçlar bir yılın yükünden kurtulur

Çürür yapraklar toprağa karışır

Güç verirler ağaca, ağacın atıkları.

Sonra baharda yeniden yeşerir dalları

Öncekinden daha güçlü filizlenir ağaç

Geliştirir güzelleştirir kendini.

İşte budur ağaçlara imrendiren beni.

Keşke derim insanlarda  bunu yapabilse

Her yıl dökebilse bütün üzerinde birikenleri

Hatalarını, başarısızlıklarını, umutsuzluklarını

Yapmak isteyip de hakkıyla yapamadıklarını

Karıştırabilse toprağa, ve güç verse ona çürüyen

Eriyip giden toprağa karışan  umutsuzlukları,  yanlışları.

Sonra yeniden filizlenebilse insan oğlu 

Daha güçlene bilse daha  güzele ulaşabilse her baharda 

                                                          Kasım 2004', 'Son bahar geldiğinde sararan yapraklar Hüzün duygusu uyandırır çoğu insanda  Ben severim son baharı imrenirim ağaçlara. Çırılçıplak kalsalar...', ARRAY['Türk Edebiyatı','Şiir','Müşfik Saltık']::text[], 8.5, '{"poet":"Müşfik Saltık","poet_slug":"musfik-saltik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sonbahar-agaclar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolculuktur Eylül', 'yolculuktur-eylul-erkan-abi-2bcql', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'En yüksek ovasında ülkemin, 

Sert olur eylül rüzgarı.

İnsanı da çetindir ya buraların

Korkmamak elde mi bu rüzgardan? 

Hele de ekin iyi bitmediyse o sene,

Vermediyse bire otuzunu, kırkını,

Yahut hiç umut vermiyorsa

Yamaları plastik çizmelerin kışa

Gel de dindir bakalım yüreklerdeki titremeyi,

Gel de renk kat bakalım gözlerdeki donukluğa...

...

Güneşin battığı yere doğru yürüyünce biraz

İçi ısınır insanın.

Yüzü önce gülücükle dolar,

Renk gelir göz bebeklerine, şavkır.

Sonra kafanı kaldırıp bakınca etrafa

izin vermez ufku görmene

Koca, kuru toprak rengi dağlar.

Bir toz bulutudur kaplamış etrafı

Yine bir umutsuzluk,

Yine firar isteyen bir duruş

İnsanların bedenlerinde.

...

Sonra batarken yakalamak gelir aklına,

Güneşi.

Koşarsın, delicesine; 

Batıya, daha batıya doğru.

Zordur ya bu koşu,

Kimin umurunda! 

İçin kıpır kıpır,

Bir umutla dolmuş.

Nefes alıp vermek marifetten

Boğulacak gibisin.

...

Geçince dağlar cumhuriyetini

Ve birazcık daha yaklaşınca güneşe akşamüstü,

Bir kalabadır etrafı alıyor.

Dağlardan kurtuldun ya,

Gel gör ki

Betonlar var etrafında, koca koca,

Bir tuğla, üzerinde bir tane daha...

Gözlerin ufku arıyor,

Ne mümkün görebilmek

Tek kızıl, soğuk tuğla kızıllığı etrafında.

...

Gözlere bakıyorsun,

Kalmamış doğan yerdeki donukluk.

Bir anlamsızlık almış yerini.

Unutmuş sanki insan

Eylül’ün hüznünü, korkusunu, umudunu, her şeyini...

...

Bu kez senin içinde bir korku,

Koşuyorsun,

Felaketten kaçarcasına.

Batıya ve bu kez çok daha batıya.

...

Çok yaklaştın güneşe,

Çoğu zaman gizleniyor siperinin arkasına ya,

Biliyorsun,

Nereden gelir, nereye gider.

Eninde sonunda çıkacak ortaya.

...

Kalabalıktan kaçıyordun en son,

Çılgınca,

Uğultular hâlâ kulaklarında.

Gittikçe artıyor.

Sen koşuyorsun, onlar artıyor.

Sen koşuyorsun, onlar artıyor.

Korkudan yumuyorsun gözlerini sımsıkı,

Dayanılmaz oluyor artık gürültü.

Haykırmak için

Susun, yeter diye,

Azarlamak için kalabalığı

Ufak, haylaz bir çocukmuşçasına,

Veya ağlanıp sızlanmak için

Çaresiz bir mağdur gibi, 

Açıyorsun gözlerini...

İşte o an,

Gözbebeklerin yerlerinden fırlayacak.

İnanmak güç, gördüklerine...

Kitapları geliyor aklına Tanrı’nın,

Kalabalığı mahşer gününün

Tam karşında.

Ne yapmalı? 

Bir buğu sonra gözlerinin önünde.

Bayılmamak için zor tutuyorsun kendini.

...

Tam Eylül’ü unutacakken,

Kaybedecekken kendini uzak topraklarda...

...

...', 'En yüksek ovasında ülkemin,  Sert olur eylül rüzgarı. İnsanı da çetindir ya buraların Korkmamak elde mi bu rüzgardan?  Hele de ekin iyi bitm...', ARRAY['Türk Edebiyatı','Şiir','Erkan Abi']::text[], 8.5, '{"poet":"Erkan Abi","poet_slug":"erkan-abi","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/yolculuktur-eylul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimin duruşu', 'kimin-durusu-erkan-abi-balfh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlat bana güzelim

Nedir bu iki mavi boncuk tanesi 

yüzündeki

Neden sakladın 

bir çift çerçeve ardına

anlat bana

söyle

bir çizgi film karakteri gibi

hafta sonu sabahlarında,

yeşil çamdan yeni çıkmış

gözlerin kızarmış

yanaklarındaki pembelikle

utanma 

konuş

saklama artık

sesin bir tek yüreğin sesi olamaz

itiraf et

kimin kalbini saklıyorusun

kimin duruşu bu sendeki?', 'Anlat bana güzelim Nedir bu iki mavi boncuk tanesi  yüzündeki Neden sakladın  bir çift çerçeve ardına anlat bana söyle bir çizgi film karakt...', ARRAY['Türk Edebiyatı','Şiir','Erkan Abi']::text[], 8.5, '{"poet":"Erkan Abi","poet_slug":"erkan-abi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kimin-durusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım Muamma', 'adim-muamma-tulay-eker-v216k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geleceksen özleminle

Bahara düşen yaprak 

Çölde açan zambak  ol.

^^ Nemrut''tan güneş doğdu.Vurdu sazın beline

Kuşlar dizildi tepesine,Hasret göç eyledi ırak illere^^

Seveceksen

Güneşi ısıtıp ellerinde

Dağımda karlarımı eritip

Dalımda öten bülbül ol.

^^Delice coştu pınar,çağladı yedi düven.

Cihan baka kaldı,Dersim''e haber saldı,yer yerinden oynadı^^

Kalacaksan..

Gözlerinden beni akıt

Öyle yaslanayım ki 

Gündüz kıskansın geceyi

Damarlarımda gündoğumu ol.

^^Yağmurlardan sonra gelen hüzünbaz gecelerde,

Islandı gölge..Bir nefes kadar yakın hasret kadar uzak^^

Vurupta gidersen..

Işığı söner ovamın

Her feryatta bir ana uyanır

Adım çilekeş vatan evladı 

Sevdam boynunda emanetim kalır.

^^Bir çapa bir testi düştü yollara,Alın terini katık yaptı aşkına,

Göbekbağını kesti dünya ile arasında^^

Geldin 

Dilini öğrettin sevginin 

Gittin 

Ölümle barışmak istedim 

Kendime hoş geldin 

Muammam dedim! 

^^Beni benle bırak..seni bende koyma! ^^', 'Geleceksen özleminle Bahara düşen yaprak  Çölde açan zambak  ol. ^^ Nemrut''tan güneş doğdu.Vurdu sazın beline Kuşlar dizildi tepesine,Hasret...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/adim-muamma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-erkan-abi-b6tgk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir hayalim daha yok olursa ne olacak? 

Karşıma alıp seni

Söyleyebilir miyim

ne denli içimde 

ne denli her şeyimde olduğunu

...

gözlerin parlar mı yine

bilince

ne zaman elime bir kağıt parçası geçse

ve bir kalemim olduğunda

tükenir mi tükenmez mi bilinmez

seni anlattığımı kendime

seni çizdiğimi

kağıdın en ucra

en ulaşılmaz köşelerine

...

bri gerçeğin daha 

kendim kadar hayal olmasından korkuyorum

sana yaklaşmaktan değil...', 'Bir hayalim daha yok olursa ne olacak?  Karşıma alıp seni Söyleyebilir miyim ne denli içimde  ne denli her şeyimde olduğunu ... gözlerin par...', ARRAY['Türk Edebiyatı','Şiir','Erkan Abi']::text[], 8.5, '{"poet":"Erkan Abi","poet_slug":"erkan-abi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hayal-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '(Mustafa Ceylan) Hakkımızda yazılanlardan bir kaçı', 'mustafa-ceylan-hakkimizda-yazilanlardan-bir-kaci-mustafa-ceylan-xdfnv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-''...Mustafa Ceylan, geniş bir örnekleme yelpazesi ile Soyuer''in yaşamını ve özellikle şiirlerini değerlendirmiştir. Böylece, Soyuer şiirinin ana konularını ve sınırlarını görmüş oluyoruz. Uzun ve yorucu bir çalışma sonucu yapılan bu araştırma, değerlendirme ve irdeleme yapıtı önemli bir kaynak kitaptır...''

(Muzaffer Uyguner, Çağrı Dergisi, Sayı: 484, Mart.2000)     

-''...Mustafa Ceylan, merhum Prof. Dr. Mehmet Kaplan'' dan sonra gelen en önemli şiir tahlil ustalarından birisidir.''

(İsmail Kara, Ankara Vakit Gazetesi, 2000)     

-''..kitabınızı bir solukta okudum. Hayatımda bu kadar ''edebi'' bir zevk aldığım kitap çok azdır. Türk kültür ve edebiyatına bundan büyük hizmet olmaz. Siz de meğer Halil Bey gibi sözcüklerin mühendisiymişsiniz. Tümceleriniz, kalp damarlarımdan beyin hücrelerime ulşan kan gibi vücudumu sarıp beni mest etti. Ortaya koyduğunuz gibi ''Halil Soyuer'' bir sanat abidesi, insan dehasının son sınırındaki bir şairimizdir. Siz de öyle büyük bir sanatkârsınız ki, bu sanat abidesine incilerle, mercanlarla, sedeflerle... dokuyup bir lâhur şal giydirmişsiniz. Aman Allah'' ım...! Bu iki büyük sanat ve sanatkâr nasıl da örtüşmüş, kucaklaşmış. Göz kamaştıran, gönül dolduran bir ''şahaser'' yaratmışsınız. O sanatkâr ellerinize sarılarak, bütün kalbimle sizi kutluyorum. Ulusumuzun öğünç kaynağısınız. Sizi şimdiye kadar tanıyamamış olmanın ve kaybettiğim zamanın derin üzüntüsü içine düştüm...''

(İ.Zekâi ÖZDİL-Yargıtay 1. Hukuk Dairesi Onursal Başkanı, 17. Ocak 2000)     

-''...Şiirde inançlıdır Mustafa Ceylan, kavgacıdır, milli değerlerin sarsılmaz savunucusudur. Şiirle Türk insanının geleceğine, geçmişine bir kılıç misali kalemini adamış bir ozandır...''

(Dr. Sami ATEŞ-Türkiye-1987)     

-''...Biyografi çalışmaları değerlerimizin topluma tanıtılması yönünden çok yararlıdır. Biz de bu pek yapılmıyor. Ayrıca, yazarlar kendi yazı ve yapıtlarının bibliyoğrafyasını da yapmıyor. Ben yalnız bunu yapmak için de fırsat bulamıyorum... Sizi ve Mustafa Ceylan''ı kutluyorum...''

(Yekta Güngör ÖZDEN- İ. kayacan''a yazılan bir mektuptan- 7.9.1999)     

-''....Sevgili oğlum, değerli oğlum, vefalı oğlum... Dünyada mutluluk diye bir kavram vardır. Bunu en az bilenler bile bilirler.. Hele benim gibi çoğunu bilenler daime mutludur.. Gerçekten ben mutluluğun en çoğunu yaşayanlardanım.. Nasıl olmasın ki? ... Seviyorum... Seviyorum... Ve de seviliyorum... Sayıyorum, sayılıyorum... Vefalıyım, vefa görüyorum. Eh mutlu olmak için gerekli unsurlar olunca, olmamak için sebep kalır mı? .. Sağ ol, var ol evlâdım... Büyük ve önemli, değerli işlere kalkışmışsın.. Allah yardımcın olsun... Değer verdiğin büyüklerini böylesine ele alman hem Allah yanında hem kullarca muteberdir... Ruhuna, ellerine, gönlüne sağlık...''

(Güzide TARANOĞLU- 29 yıldır yayın yapan GÜLPINAR DERGİSİ sahibi-Türk Şairlerinin manevi annesi)     

-''... Bu nefis çalışmayı yapan ve bu esere imza atan Mustafa Ceylan kim? ... Size biraz yazarımızı anlatalım ve önce Mustafa Ceylan''ın yayınlanmış 19 adet eserini sıralayalım...'' ''....Yani bizden biri, yazan, çizen, düşünen, duygularını kâğıtlara, kitaplara dökmekten zevk alan bir Anadolu insanı...'' ''..Üstadımıza elinize sağlık diyor ve yeni çalışmalarını dört gözle beklediğimi belirtiyorum...''

(Erol MARAŞ-Gaziantep Olay Gazetesi-22. Ocak 2000)     

-''...Akıcı bir üslupla... Kitabın yazarı da bu işlerin ustası Mustafa Ceylan. Aynı zamanda iyi bir şair olan Mustafa Ceylan da işin ilginç yanı benim çok eski dostlarımdan. Halen de çok yakın görüştüğüm, bürokrasideki ve siyasetteki başarısından daha çok güçlü kalemi sayesinde iyi bir yer edindiği yayaın dünyasında bu son kitabı ile kalıcı bir hizmette daha bulunmuş.''

(M. Ender YOLDAR-Keşan/ Önder Gazetesi-19. Ocak. 2000)     

-''...1952 yılında Ankara_Elmadağ'' da doğdu. 1975 yılında Ankara Devlet Mühendislik ve Mimarlık Akedemisi''nden Makina Mühendisi olarak mezun oldu. Çeşiti kademelerde kamu hizmeti yaptı. 1998'' de kendi isteğiyle emekli oldu. Lise yıllarından itibaren edebiyatın çeşitli dallarında yazdı, yayınladı. O arada, Halk Kültürü ile ilgili derlemeler yaptı. Bunlardan bazılarını çeşitli yayın organlarında yayımladı. Son yıllarda biyoğrafya çalışmaları ile dikkat çeken Ceylan kimi edebiyat adamlarının edebiyat tarihinde yer almalarını sağladı. Ceylan'' ın üç şiir, bir antoloji ve çeşiti biyoğrafya eserleri bulunmaktadır.Halk Kültürü içerikli kitapları şunlardır:

1-Tarihi ve Folkloruyla Elmadağ (1983)     

2-Her Yönüyle Yenimahalle (1985)     

3-Köyümüz Yeşildere (1991)     

4-Köylerimiz (Elmadağ Köyleri-1993)     

5-Torosların Türküsü (Folklorik-Biyoğrafik Roman 1999)     

6-Anılar Koridorunda Sarıveliler (Ünlü Şair Ahmet Tufan Şentürk''le beraber-2000)     

7-Seğmen Ruhu (Baskıya hazır olan bu kitabında Ceylan, tarihiyle folkloruyla ve çeşitli yönleriyle Ankara'' yı anlatmaktadır. Hacı Bayram-ı Veli ve Atatürk'' ün gözüyle Ankara'' dan söz edilmekte ve 64 yıl süreyle, bütün kurum ve yasalarıyla bağımsız bir devlet olarak tarihte yer alan ''Ankara Ahi Cumhuriyeti'' nden bahsetmektedir.

Mustafa Ceylan, zengin bir Ankara kütüphanesine sahiptir.''

(Folklor Araştırmaları KurUmu- 2000 Yılı- Türk Kültürü'' ne Hizmet Ödülü verilmesinin gerekçe raporundan- Fethiye Gazetesi, 10 Mayıs 2001- Dr. İrfan Ünver NASRATTINOĞLU)', '-''...Mustafa Ceylan, geniş bir örnekleme yelpazesi ile Soyuer''in yaşamını ve özellikle şiirlerini değerlendirmiştir. Böylece, Soyuer şiirini...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/mustafa-ceylan-hakkimizda-yazilanlardan-bir-kaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aça-74 (c) - Atölye', 'aca-74-c-atolye-akin-akca-a7as9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1. KÜF KAPISI’NDAN GÜNEŞ DEMETER''İ

Malmut’un gözü, şeytani oklarından doğru alevlerin Clementine mucizesinde! 

Meleğin küresi ebedi gelir bulutlardan ve şeffaf kapısını aralar! 

Kapıp kaçıran Clementine’i Malmut’un tek kem gözünden, ey! kim suçlayabilir seni! ! 

Kar ve buz ve Stratus: düzgün ve grimsi …

ve Cirrocumulus

ile buluştu serseri dolaşmakta olan Noctidulent, uğursuz! 

On üç bininci metrede, ufak kümeciklerden kum taneleri ve küçük dalgalar serpilmiş; 

Gölge yok, bembeyaz ortalık: Bir Cirrocumulus ordusu ziyafette, sofralık! ! *

Ve en yüksek bulutlardan –sopalık, sıkı fıkı buz kristalleri ihtiva eden- bir adet Noctidulent; *

Pike yaparak indi kapısından kutbun on üç bininci metreye, diş geçirmek için 

Cirrocumulus’lara: Gölge barındırmayan bir ak ve pak ya da şu yavru karga,

tanıdık; ile mavimsi gümüş renkli korkuluğun –sopalı adam’ın- savaşıydı bu! ! 

Galibi olmayan bir cengile, sonunda taraflar Stratus bulutlarını yavruladı! ! 

Kendileri öldü, Stratus’lar –küçücüktü- yere indi -kocaman olmuştu

– mağaralardan çıkan insan yeryüzünde serpildi ve sonunda insan ekonomisi’ni de öğrendi:

görüş algısını giderek azaltıyordu Stratus’lar -doğa ananın bir tepkisi sanki- insan 

tekerleği bulurken…En son sis doğdu, fakat… o da yavruladı ve güneş ışığı bu sisi yardı; 

 içinden geçerek ilerledi! su kristalleri, sisin göbeğinden Avalon’un eşsiz ışığını yaydı! ! 

2. LABORANT İLE BAHÇIVAN

Uyanan adam bu garip terkedilmiş evde çay yapmak istedi.

Uyanan adam, doğmadan önce bir laboranttı.

Uyanan adam bu yolculuğa çıkmadan

önce bir laboranttı

İleri gittiği her bir adım için,

böylece geriye sürükleniyor.

Sanki nehirde sürüklenen bir gemi var da,

karaya oturmadan

bağ, bahçe biçimlendiriyor.

Ve güzelleştirdiğin her bir çiçek de

seni cenin safhasına geri kanatlandırıyor.

Ve gemideki hayvanlar dışarı çıkmış.

Nuh Tufanı olmuş bitmiş.

Ama neden orada; 

bak, çiçekleri biçimlendiriyor …

Bak, sesi dinleyerek ilerliyor! …

Bak, durduğu yerde çiçekleri biçimlendiriyor! ...

Sesi dinleyerek ilerliyor! ...

Sesi dinleyerek çaydanlığı arıyor! ...

Dinleyerek cihazların arasından geçip ocağı arıyor! ...

Koşarken dinlenerek ilerliyor …

*

Sonunda aradığı şeyi bulamadı

Şaşkıncasına -

yöneldiği yeri bilmediği

- evden çıktı.

O uyurken akşam olmuştu.

Güneş’in batışını izledi.

Evin hemen yanında

ama bir bahçe vardı:

Evden bağımsız gibi biraz uzak

bir yere kurulmuş bir bahçeydi bu.

Fakat o bir laborant.

Ve bak, orada ise, bahçenin içerisinde; 

gemideki hayvanlar dışarı çıkmış! 

Nuh Tufanı olmuş bitmiş! 

Ama neden orada; 

bak, çiçekleri biçimlendiriyor …

Bu bahçe ve bu konak evi.

Ve ayrıca ama önemsizi,

tek bunlar var bu yöredeki.

*

Çiçeklerin işçisi’ne doğru hamle yaptı,

o tarafa doğru yürümeye başladı.

Bu bahçe, bu eve yaklaşırken neden gözüne ilişmemişti.

Yaklaştığınca, bir çaydanlık gördü …

Çiçeklerin orada …

Kızın elinde …

Suya hasretinin sonlandığı çiçeklerin, kızın elinde …

Orda,

Çaydanlık -

Çiçeklerin:

Evde bulamamıştı.

Bu bahçe ve konak evi.

Ayrıca ve önemsizi,

tüm bu ikisi var bu yöredeki.

Bahçenin ortasında bir korkuluk dikili,

tünemiş onun başına bir umut pembesi.

Dikkatle bakıyorum: bir karga bu.

Daha önce şahit olduğum karga gibi, pespembe; 

pembeye dem vurmuştu en sonunda, onun tüyleri de.

Saman dolu tıka basa, korkuluğun gözleri kapalı ancak,

Her bir nüvesi titreşir göz molekülleri gibi

Ama donuk: yüzüne bakıyorum; 

İfade aynı, kargayla savaşan adam ile! 

Artık niye buraya geldiğimi biliyorum,

Nerden ya da hatta nerelerden geçerek

geldiğimi bilemesem de:

Bahçıvan kız ile aynı laborant

ve aynı korkuluk ve yavru karga! 

Doğa kucak kucağa! 

*

Daha önce şahit olduğum karga gibi, pespembe; 

bordo açığı renge dem vurmuştu en sonunda, onun tüyleri de.

Ve metronomlar eflak boğdan''a tıngırdatan bu ‘eski siyah tüyler’; 

Peki veya ''Lili Brik, beni sev...''

Bu karga, bu cenin ve diğer kahramanları -

laborant ile bahçıban kız- yörenin.

Ve hatta balkondaki adam; 

çaydanlıkta demlenmişler! 

Buraya neden geldiğimi demin anlamıştım

Ve çaydanlığın da şu an ne olduğunu kavradım.

-

açıklamalar:

Sis              (0 m.) 

Stratus bulutların yeryüzüne inmesi ile meydana gelir. Yapısal anlamda bir farkı olmamasına rağmen günlük yaşamı etkilediği, görüş mesafesini düşürdüğü için ayrı olarak değerlendirmeye alınmıştır. Güneş ışığı, sis içindeki su kristallerinde kırılma yaparak yayılır ve yarı aydınlık bir ortam sağlar. 

Noctiludent              (80.000 - 100.000 m.) 

Bilinen en yüksek bulut türüdür. Kutuplara yakın bölgelerde oluşur. Yoğunlaşmış buz kristalleri içerir. Çok güzel görüntüler verir ancak ülkemizden gözlemlenemez. Mavimsi gümüş rengindedir ve seyrek bir doku sergiler.

Stratus              (0 - 1.700 m.) 

Genellikle gri renkte, düzgün görünüme sahip bulutlardır. Stratus''lerden çisenti, buz prizmaları ve kar grenleri yağışı meydana gelir. Güneş bu bulutlardan görüldüğü zaman, bulutun sınırları kolayca teşhis edilebilir. Çok düşük sıcaklıklar dışında Stratus, hale olayını meydana getirmez. Bu bulutlar bazen düzensiz sıralar halinde de meydana gelebilir. Stratus''lerin karakteristik yağışı çisenti olup, rüzgarın sakin veya hafif olduğu dönemlerde görüşü kısıtlayacak şekilde yere yakın seviyelerde görülebilmektedirler. 

Cirrocumulus            (5000 - 13.000 m.) 

Kum taneleri veya küçük dalgacıklar halinde, oldukça küçük kümeciklerden meydana gelmiş ince, beyaz ve gölgesiz bulut örtüsüdür. Bulutlar toplu halde oldukları gibi, ayrı ayrı parçacıklar halinde de görülebilirler. 

Cirrocumulusler, Cirrus veya Cirrostratus bulutlarının şekil değiştirmesinden veya parçalar halindeki Altocumuluslerin küçülmesinden meydana gelirler. Bu bulutlar tamamen buz kristallerinden ibaret olup, bazen aşırı soğumuş su damlacıkları da görülür. 

http://www.terraturk.com/index.htm? url=http://www.terraturk.com/dersler/bulut.htm

(resimleri görmek isteyenler de bu adrese bakabilirler.) 

Not: Bu sayfanın hazırlanmasında Meteoroloji Gen. Müd. sitesinden de yararlanılmıştır. Teşekkür ederiz.

Demeter:  tarim ve bereket tanricasi

yunan mitolojisi kahramanı bir yarıtanrı.bir prenses.hades in esir aldığı.

eflak boğdan: tarih derslerinden hatirladigimiz kadariyla osmanliya bi gidip bi gelen bolge ikilisi.

www.eksisozluk.com

Çift tırnak içindeki laf Mayakovski''nin ''Son mektup'' şiirinden alıntı', '1. KÜF KAPISI’NDAN GÜNEŞ DEMETER''İ Malmut’un gözü, şeytani oklarından doğru alevlerin Clementine mucizesinde!  Meleğin küresi ebedi gelir bu...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":121,"source_url":"https://www.antoloji.com/aca-74-c-atolye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kumrular''da izin var', 'kumrular-da-izin-var-erkan-abi-zypll', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağır bir kömür kokusu iniyor Ankara''ya 

sonbaharla birlikte

omuzlarında hissederek o baskıyı

ve korkarak dolmuş şoförlerinden

gözlerin birini arıyor

Kumrular''da

yapraklar çoktan sararmış

bırakmış kendini yere

her biri canını yakıyor

her biri sevgiliyi biraz daha andırıyor

seyyar satıcılar 

gözleri fal taşı gibi

onlar zabıtayı kolluyor

senin ise sevgili geliyor aklına 

gözlerinde ince bir hüzün

acaba diyorsun

onlar da aslında..

İftar çadırı toplanmış,

izleri duruyor etrafta

gördüğün her ayak izinde 

kıyıya köşeye bırakılmış

kestane kabuklarında

gözlerin sevgiliyi arıyor

üst geçidi geçince biraz 

vitrinlerdeki atkılar çarpıyor gözüne

gözleri donuk mavi bir cansız manken

her şey seni ağlatmaya yemin etmiş bugün

mankenin üzerine atkı bir dolambaç

ardından gerdanda bırakılan bir boşluk

ve bir tarafı

süzülüyor aşağı

bir palto 

belden ince 

sevgilinin beli gözlerinin önünde

tut kendini

simitçinin haline bak

gülüyor mu içinden sana

al bir tane en yanığından

al da simitçi tutamasın kendini

salyalar saça saça gülsün haline

içinda kalmasın daha fazla

baksana 

dilenci sırt çevirmiş sana

ve sevgili geliyor aklına

nasıl da sana kızdığında

büküp dudaklarını

daha bir sıkı sarılıp paltosuna

dönderdi arkasını

kırgın göz üzerine 

bir çift buruk kaş

ince uzun

hadi 

yalvar gölgene

bir an için sevgiliye benzesin diye...', 'Ağır bir kömür kokusu iniyor Ankara''ya  sonbaharla birlikte omuzlarında hissederek o baskıyı ve korkarak dolmuş şoförlerinden gözlerin birin...', ARRAY['Türk Edebiyatı','Şiir','Erkan Abi']::text[], 8.5, '{"poet":"Erkan Abi","poet_slug":"erkan-abi","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/kumrular-da-izin-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarap gibiyim', 'sarap-gibiyim-i-lhami-arslantas-g1ale', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Terki viran olmuş vücudum şehri,

Kırk dört yıl beklemiş şarap gibiyim.

Halimi ne sen sor ne ben söyleyim,

Yıklımış her yanı harap gibiyim.

Ağardı saçlarım dünden bu güne,

Sakal aynı keza  döndüler yüne,

Başıma olmadık geldi bu sene,

Kırılmış dökülmüş bitap gibiyim.

Bir asır beklerdim gönül kapında,

Böyle bir insandım kendi çapında,

Kendini bağlamış senin kapında,

Dostum ayağına turap gibiyim.

Dokunma telime gamdayım gamda,

Bir garip saksıya konmuşum camda

Toprakla sıvanmış işte o damda,

Dolaşmış kördüğüm kelep gibiyim.

Bazen dolaşırım gönülde serde,

Bazen kaybolurum girdiğim yerde,

Dostlar  medet etsin düştüğüm derde,

Bir yorgun gölgeden serap gibiyim,

Buz dağıydım damla damla çözüldüm,

Bir şiirde kafiyeye dizildim,

İlhami'' yim sayfa sayfa yazıldım,

Okunmaya hasret kitap gibiyim.', 'Terki viran olmuş vücudum şehri, Kırk dört yıl beklemiş şarap gibiyim. Halimi ne sen sor ne ben söyleyim, Yıklımış her yanı harap gibiyim. A...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sarap-gibiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Coşkusu', 'bayram-coskusu-ali-kilic-kakiz-pw985', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Büyük hünerdi, arafe günü yıkanmak yunakta.

Sevinçten yatılır mı o gece kardaş, kaldık ayakta.

Ah! Çöreğine doyamadığım, o bayramlar nerede.

Meğerse erken gitmekmiş, temiz elbiselerle.

Dinlesene, tekbirler getiriyorlar, besmelelerle.

Ah! Böreğine doyamadığım, o bayramlar nerede.

Bu gün ne güzel gündür gönüller bayram eder.

Yükselen dualarımızı Allah lütfuyla kabul eder. 

Ah! Helvasına doyamadığım, o bayramlar nerede.

........................

Bruxelles / 2004', 'Büyük hünerdi, arafe günü yıkanmak yunakta. Sevinçten yatılır mı o gece kardaş, kaldık ayakta. Ah! Çöreğine doyamadığım, o bayramlar nerede....', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bayram-coskusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özledim', 'seni-ozledim-cafer-yilmaz-5ssgd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne ekmeği özledim

aç kaldığım saatlerde,

ne kara bulutlar arasında

güneşi aradım saatlerce.

Ben seni sevdiğim zamanları özledim.

Saatleri, 

dakikaları özledim.

Açlığımdan kıvrandığım zaman bile

sen geldin aklıma,

seni beslediğim zamanlar.

Yutamadım sensiz lokmamı.

Uykuyu çok severim, bilirsin.

Oysa doyurmak için seni

uykusuz gecelerimi özledim.

seni özledim.

Hiç bir çiçek tutamadı senin kokunu.

Doyardın ya,

atıverirdin ya kendini

burnumun dibine...

Ben senin kokunu özledim.

Yanlızlığı da severim,

şiir yazmayı,

türkü söylemeyi...

Bırakmazdın yaramaz çocuk! 

Bir satır yazmayı,

bir nota basmayı...

Satırlarıma ortakmışsın gibi

kalemin ucundan koşardın,

ve söylediğim türkülere vokal yapardın...

Gittiğinden beri yazdığım ilk şiirsin sen.

Ne şiirini,

ne türkünü,

ben senin dakikalarını özledim...

Seni özledim..', 'Ne ekmeği özledim aç kaldığım saatlerde, ne kara bulutlar arasında güneşi aradım saatlerce. Ben seni sevdiğim zamanları özledim. Saatleri,  ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/seni-ozledim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tadı Yok', 'tadi-yok-cafer-yilmaz-bek9o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Okulu kırdığımız zamanlardı...

özgürlüğüne kavuşmuş

mahkumlar sürüsü dağılırdı 

mayıs aylarında 

İstanbul meydanlarına...

işgale uğramış şehir gibi

sokak sokak

cadde cadde

lacivert ceketliler...

yedi tepeli şehri

yedi cüceler basar mayıs aylarında.

meteliksiz günlerinde tanıdım

Çamlıca''nın havasını,

Boğazı,

Sarayburnu''nda içemediğim çayın tadını.

yine meteliksizdim

Bakırköy''den çıkıp Emirgan''a giderken.

Çok merak ettiğim

Topkapı Sarayının harem bölümünü

sırf bu yüzden göremedim.

ve o delikanlı çağlarımda

İstanbul rüyalarımda...

hep meteliksiz,

hep tektim.

Çoğu zaman dönüşte

kaçak binmenin yollarını arardım trene.

metelik kazandığım zamandır şimdi.

İstanbul yerli yerinde, metelik bende.

Oysa Çamlıca''nın püfür püfür esen rüzgarı,

Sarayburnunda içemediğim çayın tadı,

meteliksiz günlerimin tadı...

onlar nerede? ..', 'Okulu kırdığımız zamanlardı... özgürlüğüne kavuşmuş mahkumlar sürüsü dağılırdı  mayıs aylarında  İstanbul meydanlarına... işgale uğramış şeh...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/tadi-yok-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'M a n i l e r (2)', 'm-a-n-i-l-e-r-2-abdullah-atay-92sox', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'beyaz saçlı nineler

saz çalıp eğlenirler

şimdi sırası geldi

söylenecek maniler...

odun aldım budaklı

yarim kiraz dudaklı

gelin olmuş geliyor

allı telli duvaklı....

penceresi tül perde

hep etekleri yerde

kurda kuşa sorarım

benim sevdiğim nerde...

sevdanla ben mecnunum

ben sana hep mecburum

yeter ki sen sev beni

inan kölen olurum...

bahçede olur kuyu

meleklerden var soyu

yarim sana gelecem

gece koynumda uyu...

pazarda var enginar

gömleğimin yeni dar

kınamayın a dostlar

benim bir sevgilim var...

bir sahanım var bakır 

yarimin gözü çakır

cilvesine nazına

kurban olsun bu fakir...

sevdiğim evli barklı

o herkeslerden farklı

sormayın söyleyemem

adı kalbimde saklı...

yollar yürürüm yayan

benim hep senle yanan

mevlam sabırlar versin

dayan yüreğim dayan...

abdullah atay der ki; 

bu bayram mutlu ola

sürçülisan ettiysem

can dostlarım affola....

   13.Kasım.2004 Mudurnu

    Not.Tüm gönül dostlarımın Ramazan bayramını içtenlikle kutlar tüm yaşantılarının mani tadında olmasını dilerim.', 'beyaz saçlı nineler saz çalıp eğlenirler şimdi sırası geldi söylenecek maniler... odun aldım budaklı yarim kiraz dudaklı gelin olmuş geliyor...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/m-a-n-i-l-e-r-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah yıldızı', 'sabah-yildizi-haydar-meric-mxs80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sabah yıldızı

Gecenin unuttuğu sabah yıldızı

Penceremden süzülerek içeri girdi

Oturdu sandalyenin üstüne

Tüm zarafeti ve haşmetiyle

Sabahın seher  vaktinde

Baktım ışıldayan gözlerine

Aradım kendimi onun düşlerinde

Düş gibiydi gözleri

Sabahın seher vaktinde

Yorgun ve titrek sesiyle

Sevda üzerine mırıldandı

Yüreğimde çağlayanlar yarattı

Sabahın seher vaktinde

Tülden saçları deniz dalgası

Ilıman bakışları yıldız yansıması

Parmaklarının uçları kadife okşaması

Gönlümü çaldın sabahın seher vaktinde...

                                  Haydar Meriç 12.11.2004', 'Sabah yıldızı Gecenin unuttuğu sabah yıldızı Penceremden süzülerek içeri girdi Oturdu sandalyenin üstüne Tüm zarafeti ve haşmetiyle Sabahın ...', ARRAY['Türk Edebiyatı','Şiir','Haydar Meriç']::text[], 8.5, '{"poet":"Haydar Meriç","poet_slug":"haydar-meric","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sabah-yildizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar (45)', 'yar-45-i-brahim-arslan-kkmbo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yar

Senin aşkın kalbimde

Aşkına vermedim zarar...

Gel,istersen kalbimi yar

Göreceksin orada senden neler neler var

Sensiz geçmiyor burada akşamlar

Gündüz yanımda hayalin

Düşümde gülüşün var

Düşünüyorum da sensizlik ne zor,

Ölüm demek yar,ölüm demek

Hatta yetmiyor...

Gel bana sor,sensizliği anlatayım sana

Bir masal gibi,bir efsane gibi gelir

Uyursun...

Bana geliyor dünya dar

Sana güllük gülistanlık

Ne de olsa sende senden var...

Ankara''ya yağan kar

Senin semtine uğramıyor

Sen olmasan oralarda donar,

Gelsen buralara buralarda yanar

Bu aşk kül eder beni,sonunda yakar

Artık sana çıksın yollar istiyorum,

Gelmek,ama daha vakit var...

Yar

İnsafın yok senin

Ve senin aşkın kalbimde

Aşkına vermedim zarar...

Sen benlesin hep

Gözlerin benle

Gülüşün benle

Tek korkum seni kaybetmekten

                          yar

                          sınlar benim kalbimi,

Bu sevgiyi alsınlar,

Taşıyamayacağım çünkü

Yaşayamayacağım sensiz...

Bahar

Gelmiyor

Çiçekler açmıyor

Ve sen bunları bilmiyorsun,

Çünkü senden sende var...

Siyah gözlüm

Yarsınlar kalbimi

Sana olan sevdamı herkes görsün...

Mecnun''dan Mecnun olduğumu,

Ferhat''ın aşkının sönük,

Ve senin Leyla gibi hayal değil

Gerçek olduğunu...

Ama istemem...

Sen hep köylü güzeli olarak kalmalısın,

Hep masum açmamış bir çiçek gibi,

Yaralı bir ceylan gibi ürkek

Ve kelebekler gibi...

Yar 

Ölümden başka engel ne var

Çıkı-ver karşıma

Açıver kollarını

Siyah gözlerinle bakıver

İçimi yakıver yine

Elini elime ver...

Yar

Seni anlatamadım daha

Ama ne mahsuru var

Sanki şimdiye kadar yaşamadım

Sensiz dünya bana mezar

Cennet sensiz anlamsız

Gelir bana,yar

Sen olduğunda cennet her yer

Gel halimi gör

Yar diye diye öleceğim,

Benden başkasına bakarsan...

Senide öldüreceğim...

Yar

Biliyorsun ben deliyim,deli gibiyim nicedir

Ve senin aşkın her zaman kalbimde 

Aşkına vermedim hiç zarar...

(24.01.04)', 'Yar Senin aşkın kalbimde Aşkına vermedim zarar... Gel,istersen kalbimi yar Göreceksin orada senden neler neler var Sensiz geçmiyor burada ak...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/yar-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar 2 (46)', 'yar-2-46-i-brahim-arslan-62qgc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yar

Gözlerimin önünden gitme

Bıkmam senden hiç

Ya beni de al götür gittiğin yere,

Ya sende gitme, gitme,gitme uzaklara

Hayalim karşına çıkar hep

Gözyaşlarımla boğulursun

Belki geldiğinde geç olur

Beni ölü bulursun...

Bilirsin ki her yaşayanın sonu var

Sensiz bırakma beni

Öleceksem senin kucağında

Gözlerine bakarak

Son nefesimi öyle vermeliyim...

Aslında ölümü düşünmemeliyim...ama

Gidersen işte,ölürüm

Ölürüm yar,

Bir insana açma mezar

Ve beni senden uzaklara atma,

Şimdi sensiz bir onbir eylül

Saldırıları var beynimde

Yedi nokta iki şiddetinde deprem

Her hücremde,ve kalbimde

Senin adın yazılı,sadece senin adın

Gel uçuruma atma beni

Gel üç kuruşa satma,

Ya beni de al götür,gittiğin yere

Ya sende gitme,gitme

Gitme uzaklara...

Sil kafandan ayrılığı

                     yar

                     bu adam sensiz nasıl yaşar

                     sor kendine      

                     ya da bana sor,anlatayım...

Ankara''yı yaktırma bana

Biliyorum delilik diyorsun,

Ama aşkın için az bile

Dünyayı yaksam hiç...

Sen bilmezsin sensizliği

Sen sensizliği bilmezsin...

Bilseydin hak verirdin bana

Bilseydin hiç durmaz gelirdin,

Gelirdin ayrılmazdın yanımdan

Bir saniyeliğine bile...

Şimdi yanımda hayalin var,

Elimde senden çaldığım resmin,

Ferdi''den bir şarkı çalıyor,

Tek eksik sen,

''Bir ömrü tükettikte birlikte

Bir çay içimlik uğramadın ya sonunda''

''Gözlerimden akan yaşlar

Sende biter sende başlar'',diyorum

Seviyorum seni,seni seviyorum...

Yarim,

Sen bilmezsin sensizliği

Sen sensizliği bilmezsin...

(29.01.04)', 'Yar Gözlerimin önünden gitme Bıkmam senden hiç Ya beni de al götür gittiğin yere, Ya sende gitme, gitme,gitme uzaklara Hayalim karşına çıkar...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/yar-2-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar 3 (47)', 'yar-3-47-i-brahim-arslan-89bp4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yar

senin bir gülüşün

bende bin kapı açar

bir geliver bana 

yalan olmasın

gül gibi açsın şu çöl gönlümde

senin aşkın...

ölene kadar seni seveceğim ben,

vazgeçmem diyorum,vazgeçmem! 

ya öldür beni kurtul

aşkımdan

ya karanlık gecelerime 

güneş gibi doğ...

yar 

senin bir gülüşün 

bende bin kapı açar,

bir geliver bana

yalan olmasın...

hür olan bir ruhum vardı,

o da ellerinde esir,

bir bakışına köle olsam az gelir

sabah-akşam kalem elimde

seni anlatsam inan az...

biraz rüzgar gibi es buralarda

sen gelde  istiyorsan ölüm getir...

yar

sensiz bir günüm

bana bin yıl gibi

bir giriver bu kapıdan 

yalan olmasın...

yar 

sevgimi bilseydin

ya da görseydin halimi

acırdın! 

ben senin eserinim oysa

bu hale beni sen getirdin,

mecnun mu çok çekmiş ben mi? 

sen mi zalimsin,leyla mı? 

görseydin halimi

karar verirdin...

sana şiirler yazmayacağım artık

istiyorsan adını anmayacağım

istiyorsan terkedeceğim bu şehri

bir daha dönmemek üzere

ama asla bu sevgimden utanmayacağım

sensiz

sonbahar geldi

kış geldi

ülkeme

kuşlar göç etti,

ilk defa

güller açmadı

bülbüller

feryat-figan etti...

yar

bir gel bana

bir gül bana

bir gülüver bana

bir elini ver

elime

yalan olmasın

yar

senin bir gülüşün

bende bin kapı açar

bir geliver bana

yalan olmasın...

(11.11.04)', 'Yar senin bir gülüşün bende bin kapı açar bir geliver bana  yalan olmasın gül gibi açsın şu çöl gönlümde senin aşkın... ölene kadar seni sev...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/yar-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansızım (48)', 'i-mkansizim-48-i-brahim-arslan-2myh0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen gel diyorsun,

Ben mi istedim gurbeti

Ben mi istedim gurbeti

Bilmiyorsun ne hallerde olduğumu,

Ne acılar çektiğimi görmüyorsun.

Benim imkansızım,

Kavuşmayı kolay mı sanıyorsun,

Engeller bir değil binbir tane,

Nereden başlasam yazmaya bilmiyorum,

Sanma sevmiyorum seni

Sanma hiçbirşey yapmıyorum.

Benim imkansızım

Bak şimdi yalnızım,yine yalnızım

Sen yoksan,kimse yok yanım da

Hayaline muhtacım

Muhtacım gözlerine,sana,sözlerine

Biran olsun gerçek olsan şimdi

Ellerini tutsam...

 Şahidim olsun kara geceler,

 Esirin olsun yıldızlar

 Ruhum al senin olsun,

 İşte ben yaşamadım sensiz,bilsinler

 Farketmez uğrun da ölürüm de

 Ey güzel bil ki,ölürümde

Benim imkansızım

İmkansız aşkım

İmkansız aşkımız biliyorsun,yine de

sen gel diyorsun...

(10.03.04)', 'Sen gel diyorsun, Ben mi istedim gurbeti Ben mi istedim gurbeti Bilmiyorsun ne hallerde olduğumu, Ne acılar çektiğimi görmüyorsun. Benim imk...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/imkansizim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli (49)', 'deli-49-i-brahim-arslan-01vf6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben beni bilenlerin gözünde

Deliyim...

Ve ben gibi delilerden

Yok hayatımda...

2004', 'Ben beni bilenlerin gözünde Deliyim... Ve ben gibi delilerden Yok hayatımda... 2004...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/deli-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram...', 'bayram-i-brahim-ethem-bingul-qs7ur', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'B ayram,bayram gibi olmalı

A yrılıklar,kırgınlıklar solmalı

Y arınlardan ümitvar olunmalı

R azıyım bir selâmla hatırım sorulmalı

A lacaklar silinmeli, çiçekler gönderilmeli

M azi, mazide kalmalı,yarınlara bakılmalı...

''''Tüm şair ve dostların bayramı kutlu olsun''''', 'B ayram,bayram gibi olmalı A yrılıklar,kırgınlıklar solmalı Y arınlardan ümitvar olunmalı R azıyım bir selâmla hatırım sorulmalı A lacaklar ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bayram-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Hattı', 'beyaz-hatti-naime-erlacin-om932', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'insana konuşmaz siyah sayfa 

ateş hattında iken beyaz

nasıldı savaş arabaları bilmem

alev topu muydu mancınıklar

gülleler metal mi 

kaskatı bir ruh kadar

zamanın eleğinden 

zor geçendi eşyanın ahşap hali

unutmazdı yaşamayı

o en dirençli

çılgın bir rüzgâr eserdi dağdan

tohumdan 

ve ağaçtan

kavganın çaresiz boyun eğdiği 

beyaz sayfayı ararım şimdi

çillenmiş olsun ateşle suda 

masumiyetin en çok sevdiği

varsın çok defalar 

çocukça aldanmış olsun siyaha 

böyle bulunur çekimleri fiilin

sözün yedi rengi  böyle

zırhını kuşanan fail

harfin beyaz hattında durdukça 

(13 Kasım 2004)', 'insana konuşmaz siyah sayfa  ateş hattında iken beyaz nasıldı savaş arabaları bilmem alev topu muydu mancınıklar gülleler metal mi  kaskatı ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/beyaz-hatti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Beyaz Tayf...', 'beyaz-tayf-naime-erlacin-me5ao', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'külrengi serzenişlere revnaklar bırakmıştın

canlandı kurşunîde yedi renk

mühürler vuruldu rüzgâra 

suya ve dağa

ağladı kehribar

ne sancılar doğurdun ah yürek 

ne çok kan zayii bu

yakutun raksından 

bir kalıntıydı aksisedan

eylemin kan revan

“…bana verecek mutluluğun kalmadı mı 

 …ne çıkar! acıların var daha…” **

soğurdum acıları

siyaha yakındılar

aşk kadar üryan 

isteme benden 

veremem artık 

bembeyaz onlar

papatyalar kadar 

(*)    Beyaz Tayf bir oxymorondur! 

(**)   Lou von Salome – (Nietzsche''nin efsane sevgilisi) 

(24 Ekim – 13 Kasım 2004)', 'külrengi serzenişlere revnaklar bırakmıştın canlandı kurşunîde yedi renk mühürler vuruldu rüzgâra  suya ve dağa ağladı kehribar ne sancılar ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/beyaz-tayf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Renkler armonisi', 'renkler-armonisi-behcet-gulenay-hlqht', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'mavi, balkonlu evim benim

gökyüzü ve deniz yüklü güzel kadın

bütün insanları benim için sev

kapama gözlerini

aşkın derinliğinden çıkabilmesin kimse

ama güvenme

lacivert; hürriyeti elinde gizli bir orospudur.

bir babanın sert, soğuk, bürokrat gülümsemesi

arkadaşlık etme

mor; çocuk yoksulu fahişe bir şehirdir.

sancı nöbetlerine duran bir kadının kısır rahmi

acı turuncuya

kızıl bir hınçla hayata tutunmuş

yüreği bohçasında topal görünümlü bir çocuktur.

fark et ve anla

gri; aşkı içinde umutsuz bir kızın

gözlerinde asılı duran bir kederdir.

kül bir tutkuyla içinde biten çalılıktaki gülden habersiz

sev ve duy özlemini içinde

kahve; karnındaki çocuğun sancılarını çeken

doğurgan bir kadının yüzüne yayılan ılık şefkat

siyah; en sevdam, kara sevdam

kırık yanım

yatağını aşındıran bir nehir kuruması gibi sus

ölü doğdu çocuk

sus, karanlığını da seviyorum.

bekledim seni

oyuncağını beklemesi gibi bir çocuğun

hadi gülümse bana beyaz beyaz

ay gibi daha bir güzelleşirsin

bütün insanları aydınlatsın gülüşün

içinde tek bir yalnızlık kalmasın

sevişir gibi sözcüklerle

kalabalık bak bana yeşil yeşil

çiçek çiçek şenlensin dünya

insan ki dört mevsim bahar…

yakınlaş, hani nerde ellerin

pembe pembe sar beni tenim gibi

dışında bırakma, ısıt çılgınlığımı

büyü bende

sarı bir gururla, hafifçe öp beni

şeker toplamaya gelsin evimizin önüne

buğday renkli hüzünlü çocuklar

sevmek uzun sürsün unutmak kısa

kırmızı; sevişmeye kabaran ıslak bir iştah

kılıçlarınla içime diktiğin dikenlerine sokulan çiçeğin

yaprağına konmuş kelebeğin verdiği zevk gibi

mutludur bakireliğini kaybeden kızlar

şehvetle tutuşur içlerindeki lavlar

sıra öpüşmede

birazdan çocuk sesleri basacak avluyu

                                             Ekim 2004

2005 Aykırısanat Dergisi Şiir Ödülü

Behçet Gülenay', 'mavi, balkonlu evim benim gökyüzü ve deniz yüklü güzel kadın bütün insanları benim için sev kapama gözlerini aşkın derinliğinden çıkabilmesi...', ARRAY['Türk Edebiyatı','Şiir','Behçet Gülenay']::text[], 8.5, '{"poet":"Behçet Gülenay","poet_slug":"behcet-gulenay","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/renkler-armonisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çivi', 'civi-ali-aldemir-7sb1h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne tükenmez ne bitmezmiş! 

Yine çıkmış diyorlar 

Habire çıkıyor,

Habire çıkarılıyor, 

...   Kim çakar

....      Kim çeker,

Çakanla,çıkaranın

Kazancı ne bu işten

...Sen mi, 

....   O’mu, 

.....      Kim ulan

Kim çıkarır bu dünyanın çivisini

Yoksa bir yere mi çakılı

Bu dünya bir çiviyle

Ya çıkarsa son çivi de? 

Yandık desenize gülüm!', 'Ne tükenmez ne bitmezmiş!  Yine çıkmış diyorlar  Habire çıkıyor, Habire çıkarılıyor,  ...   Kim çakar ....      Kim çeker, Çakanla,çıkaranın...', ARRAY['Türk Edebiyatı','Şiir','Ali Aldemir']::text[], 8.5, '{"poet":"Ali Aldemir","poet_slug":"ali-aldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/civi-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buruk Bayram...!', 'buruk-bayram-kadir-soyturk-xes1o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Miladi  ikibindört, ondört kasım, gün: pazar

Uğurlandı Ramazan, takvimlerde “bayram” var

Takvimler, “bayram” derken; mahcup, meyus, perişan

Yalnız takvimler değil; perişan milyarla can

Yer-gök ateş  püskürüp; malı-canı yakarken; 

Bu bayram, buruk bayram sel gibi kan akarken! 

Rabbim bizi affeyle, boynumuz kıldan ince

Bayram, bayram olacak; akan kanlar dinince

Ümitvarız; gecenin sonuna geliyoruz

Nice kansız, zulümsüz bayramlar diliyoruz...', 'Miladi  ikibindört, ondört kasım, gün: pazar Uğurlandı Ramazan, takvimlerde “bayram” var Takvimler, “bayram” derken; mahcup, meyus, perişan ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/buruk-bayram-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pakt', 'pakt-akin-akca-9jc8e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aklı karışık bir yeniçeri kellesini yaladı -üç ileri bir geri. 

Bir holigan rüzgarın uçurduğu saçını yuhaladı, aklı karışık. 

ikisi de taradı. 

Biri jöleyle. diğeri de. 

dövmeli kızılderili de... 

porsche''ye binip villasında gezinen rapçi de. 

Daldılar hepsi aynı anda aynı dolaba. 

Dolabın ampulü yok. 

Nasıl buldularsa 

çenelerini; ya bir aparkat 

veya temas değil alt kattan - 

bir kroşe derken ikinci- bu dolap bir pakt. 

Devletin yönetiminde olmalı postallar. 

Devletin yönetiminde olmamalı postallar: 

Bu ikisinden çıkan, aptal-gurur mu her şey? 

yoksa kartpostalların sonucu olacak bir pakt - 

çiçke falının yerinde bir yanıtı 

- ulus-devlet zaten barışı yakınlaştırmak

 için mi yaşar?', 'Aklı karışık bir yeniçeri kellesini yaladı -üç ileri bir geri.  Bir holigan rüzgarın uçurduğu saçını yuhaladı, aklı karışık.  ikisi de tarad...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/pakt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygu yüklediler', 'duygu-yuklediler-akin-akca-mmt01', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hüzün olmasaydı şiir kendiyle doğmazdı 

ve şiir olmasa hazanlar yeniden fakat 

farksız çiçekler açamazdı ruhundan 

tuzun sekerek ve kılcallarından yaprak 

yeşilinin- buluştuğu mavi gökle! 

Masmavi gök! sen benim yüreğimi sök! 

sök damarlarımdan ve bir boşluk 

kalsın böyle sevgi kalmasındansa: 

ben kullanırım gururumu sırf buna! ! 

sen kullanırsın tüm kinini, şuna buna! 

Bie sandık dolusu sararmış ya bembeyaz suhuf, 

peki mi, -çeliğindeki metalin küf

- yapay aslından çürük curüf... 

baksan ya da bakmasan da maziye,

geleceğe diz çöksen de çökmesen nafile 

İşte, orda olan orada! 

bulduğun da orada, burada. 

Duygu yüklediler bir gemiyi. 

gitti beşeri, duyu yüklü olduğu için 

duygu yüklü olduğundan ama ilerledi seri.', 'Hüzün olmasaydı şiir kendiyle doğmazdı  ve şiir olmasa hazanlar yeniden fakat  farksız çiçekler açamazdı ruhundan  tuzun sekerek ve kılcalla...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/duygu-yuklediler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Sana Sevgi..Eyvallah', 'selam-sana-sevgi-eyvallah-tulay-eker-mjtgi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düğümler atılırken boğazıma

Yutkunmak gün geçtikçe zorlaşıyor

Dağlanan yaram diriliyor inat edercesine

Anne nerdesin? 

Gelsene! 

           /

Parmaklarım sımsıkıydı

Sarılmıştık..sarılmıştın..

Şimdi aralandı akıyorsun

Tutamıyorum...

Tutunamıyorum.

          /

Hayat akışım

Gözpınarım sendin

Senin gözlerinden

Yaşamı gülümsettim.

Şimdi yaşam ağlıyor

Neremdesin? 

         /

Ayaklarının izleri

Dizlerimdi

Bazen bağdaş kurdum

Yüreğinde

Bazen rüku ettim

Sözlerinde

Sevmekten öte taptım

Her hücremle

Ağır mı geldi? 

Yüreğim ellerine.

         /

Şeyda bülbül ol

Konuş susma! 

Ya beri gel

Dünya baki değil

Özüme söz ol yaşa.

Ya var git

Çekemeyeceksen

Yolun açık ola. 

        /

Aç avuçlarını

Dolup taşsın aşkım

İç yüreğimden

Gökyüzünde güneş açsın

Dudaklarımla gülümse

Doğa verirmiş

Candan isteyince.

Bulmuşken doldur

Şerefine.

         /

Avutamıyorsam kalbimi

Yalnızlığım cebelleşiyorsa

Söküp atarım inan ki! 

Acı öldürmez 

İlk ecelim olmaz ki.

Canım canına emanetim olsun

Bil yeter ki.', 'Düğümler atılırken boğazıma Yutkunmak gün geçtikçe zorlaşıyor Dağlanan yaram diriliyor inat edercesine Anne nerdesin?  Gelsene!             ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/selam-sana-sevgi-eyvallah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresizliğim ve Ölüm', 'caresizligim-ve-olum-ali-osman-yilmaz-0l422', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sokakta oynuyordu çocuklar,

Bu bayram sabahında,

Seyretmek için merakla,

Penceremin önünde otururken,

Cemalim göründü camda.

Göz göze geldim o anda,

Pek bi şaşırmadım da,

Yaşadığım yıllar boyunca,

Sevdiğim insanların,

Vefasızlığını düşündükçe,

Sevdiğim,aşık olduğum ‘O’,

Mavi gözlümün yokluğunda,

Yalnızlığımın da acılarıyla,

Ölüme ne kadar aşina,

Olduğumu anladım.

Sevgisizlik ormanında,

Vefadan yoksun insanlarla,

Hele ‘O’ gönlümün sultanı,

Mavi gözlümün yokluğunda,

Yalnız yaşamanın yükünü,

Taşımanın bahtsızlığıyla,

Ölümden başka kim ile,

Ve nasıl dost olabilirim ki? 

O yüzden penceremin camında,

Gördüğümde cemalimi,

Ölümün çaresizliğini,

Çaresizliğimde ölümü,

Görürüm daima.', 'Sokakta oynuyordu çocuklar, Bu bayram sabahında, Seyretmek için merakla, Penceremin önünde otururken, Cemalim göründü camda. Göz göze geldim...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/caresizligim-ve-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden?', 'neden-selcuk-demir-dekmd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sahipsizlik mi çöker omuzlarıma! 

ya gelecek korkusu 

ellerim ondan mı titrek? 

alışagelmiş bir düzen 

her yeni şeyde aynı duygu! ! 

umarsızlık... 

belirsizlik... 

peki neden? ! 

neden evler küçük gelir bana? 

niye sevmelerim hep nefrete? 

ve sokaklar niye hep aynı! ! 

yitirmişliğim... 

bıkkınlığım... 

peki neden? ! !', 'sahipsizlik mi çöker omuzlarıma!  ya gelecek korkusu  ellerim ondan mı titrek?  alışagelmiş bir düzen  her yeni şeyde aynı duygu! !  umarsız...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Demir']::text[], 8.5, '{"poet":"Selçuk Demir","poet_slug":"selcuk-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/neden-117-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulantı', 'bulanti-selcuk-demir-7vx7p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yalnızlığımı kesince nefesin, 

ellerimi alınca ellerine... 

son bulurmu zannediyorsun? 

huzursuzluğum... 

hep kaltak yataklarında! 

aşırılığım... 

bir akşam küfrü! 

kirlenmiş bir dünya da! en kirli benliğim... 

oysa tertemiz olmak isterdim! 

... 

ne budala bir tavır... 

ne  de ahmakça!', 'yalnızlığımı kesince nefesin,  ellerimi alınca ellerine...  son bulurmu zannediyorsun?  huzursuzluğum...  hep kaltak yataklarında!  aşırılığ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Demir']::text[], 8.5, '{"poet":"Selçuk Demir","poet_slug":"selcuk-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bulanti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmanlıklar, Keşkeler', 'pismanliklar-keskeler-gulgun-engin-icewx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'pişmanlıklar, keşkeler...

öğreniyor insan birgün mutlaka,

bir işe yaramazlar.

gözyaşlarının gereksiz olmadığını öğreniyor,

ağlayamadığına yanıyor

içinin parça parça olduğu anlarda..

bırakıyor bir damlayı özgürlüğüne

takıp

dudağının kenarına bir gülücük

yüreğine kırmızı beyaz bir gül,

uzatıyor bulutlara

bedenine sığdıramadığı kendini..

parmağında gülün dikeni..', 'pişmanlıklar, keşkeler... öğreniyor insan birgün mutlaka, bir işe yaramazlar. gözyaşlarının gereksiz olmadığını öğreniyor, ağlayamadığına ya...', ARRAY['Türk Edebiyatı','Şiir','Gülgün Engin']::text[], 8.5, '{"poet":"Gülgün Engin","poet_slug":"gulgun-engin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/pismanliklar-keskeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte O Zaman (50)', 'i-ste-o-zaman-50-i-brahim-arslan-ia5ea', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Birgün anlayacaksın hatayı

Ve en güzel şeyi

Beni tanımakla yaptığını,

Belki vuracaksın sırtımdan

Anlamayacaksın beni diri diri yaktığını

Bıkacaksın dinlediğin şarkılardan

Avutmayacaklar seni,

Söylediğim doğrulardan utanacaksın...

Aradığında bulamayacaksın beni yerimde

Belkide kabrime kapanacak,ağlayacaksın

İşte o zaman anlayacaksın hatayı

Ve en güzel şeyi,

Beni tanımakla yaptığını

Sende arkana bakmadan gidecek

Beni hiç tanımamış olacaksın,

Bir vatan hainiymiş gibi

Bahsedeceksin benden

Ve sanki bir firavun gibi...

Yine de söylüyorum

Ben öyle kolay unutulmam...

Hayatında bütün ışıklar sönecek o gün,

Dünya bana karardığı gibi

Sana da kararacak,

Belki de yaşadığın o son gün

Benim bütün ömrüm olacak

Birgün anlayacaksın hatayı

Ya da en güzel şeyi,

Beni tanımakla yaptığını,

Anladığında geç olsada

İşte o zaman ruhum huzur bulacak

İşte o zaman çıkacağım bu Cehennem''den...

2004', 'Birgün anlayacaksın hatayı Ve en güzel şeyi Beni tanımakla yaptığını, Belki vuracaksın sırtımdan Anlamayacaksın beni diri diri yaktığını Bık...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/iste-o-zaman-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Diyorum (51)', 'sana-diyorum-51-i-brahim-arslan-0wo5r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gel benim ol,bende senin olayım

Kaç sevda varsa yüreğimde yalan,

Senden başkasını yalanlayayım,

Gözüm gibi sen ol, yanımda kalan.

Gönlümdeki kelepçeyi çözeyim,

İstiyorsan kanımı da dökeyim,

Medet diyerek önüne çökeyim,

Bitsin artık ruhumdaki bu talan.

Gel ey! yakınımda duran uzağım,

Gel ey! kalbime kurulan tuzağım,

Bin yıldır sanki elinde tutsağım,

Salıver beni,beni benden çalan.

Ne yaptımsa sana eremedim ben,

Gülleri kapına seremedim ben,

Vazgeç diyorsun vazgeçemedim ben,

Ben oldum hep boş hayallere dalan.

Birgün sende geleceksin benimle

Ya yaşayacaksın sevgimle,ya da

Bugün sende öleceksin benimle

Beni hep imkansızlıklara salan...

2004', 'Gel benim ol,bende senin olayım Kaç sevda varsa yüreğimde yalan, Senden başkasını yalanlayayım, Gözüm gibi sen ol, yanımda kalan. Gönlümdeki...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sana-diyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş (52)', 'tas-52-i-brahim-arslan-hl0yb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsan olduğunu unutan adamlar

Ağlayın hüngür hüngür,güldüklerinize

Ciğeri beş kuruşluk adamlar

Başınıza taş yağmadan gelin kendinize...

2004', 'İnsan olduğunu unutan adamlar Ağlayın hüngür hüngür,güldüklerinize Ciğeri beş kuruşluk adamlar Başınıza taş yağmadan gelin kendinize... 2004...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tas-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiğin Yerden Gel (53)', 'gittigin-yerden-gel-53-i-brahim-arslan-md9g1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Artık gittiğin yerden gel,

Ne dayanmaya tahammülüm kaldı,

Ne yollarını beklemeye halim,

Ne sabır,ne katlanmaya yüreğim

Artık gittiğin yerden gel

Gel ve artık yanımda kal...

2004', 'Artık gittiğin yerden gel, Ne dayanmaya tahammülüm kaldı, Ne yollarını beklemeye halim, Ne sabır,ne katlanmaya yüreğim Artık gittiğin yerden...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gittigin-yerden-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cefa-sefa (54)', 'cefa-sefa-54-i-brahim-arslan-pry9o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biri ağlar,biri güler bu dünyada

Gülen niye güldüğünü bilmez

Ağlayan neye ağladığını,

Bu böyledir hiç değişmez

Biri cefa çeker,biri sefa sürer

Bu dünyada...

2004', 'Biri ağlar,biri güler bu dünyada Gülen niye güldüğünü bilmez Ağlayan neye ağladığını, Bu böyledir hiç değişmez Biri cefa çeker,biri sefa sür...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cefa-sefa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğluma Öğüt', 'ogluma-ogut-ayse-doganses-uffyu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir umuttur gurbet

Çekip gidersin bilemezsin seni

Ne zorlukların beklediğini

Dalarsın beklediğin umutlarına

Bir gün bir masa başında

Yada inşaat duvarında

Yorgun ve yaşlı gözlerle

Sızar yüreğin

Dökülür yaşlar önüne', 'Bir umuttur gurbet Çekip gidersin bilemezsin seni Ne zorlukların beklediğini Dalarsın beklediğin umutlarına Bir gün bir masa başında Yada in...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Doğanses']::text[], 8.5, '{"poet":"Ayşe Doğanses","poet_slug":"ayse-doganses","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ogluma-ogut-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İç güneş', 'i-c-gunes-fevzi-gunenc-8p29w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevinç içgüneştir yürekte ışıyan

sevginin yumurta ikizi

aydınlatır herşeyi

güzelleştirir...

İyileştirir bütün yaraları

umutsuzlukları yok eder.

Senin içgüneşin yok mu sevdiğim! 

Bir tek ışını da olsa yeter.

Onu bana gönder!', 'Sevinç içgüneştir yürekte ışıyan sevginin yumurta ikizi aydınlatır herşeyi güzelleştirir... İyileştirir bütün yaraları umutsuzlukları yok ed...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ic-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinayet', 'cinayet-fevzi-gunenc-ypwzg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni öldüreceğim

öyle sandığın gibi

kolay bir ölümle

bogazını sıkarak değil örneğin.

Tabancanın namlusunu şyüreğine doğrultup

tetiğini çekerek de değil...

Bıçaklayarak hiç değil hele.

Kan görmeye dayanamam...

Değil seni kesmek

özüm dövmez kesilirken 

kurbanlık koyuna bakmaya bile.

(O yüzden hiç kurban kesmedim ömrümce

Yok yok... Bir tane kuzucuğu kestirmiştim kurban diye.

Önünde diz çöküp yalvarabilirim

kanlı gözyaşları dökerek

beni bağışlasın diye

bağaşlanmayacağımı bile bile...

Ölümün bağışı olur mu?) 

Ben en etkili silahımla işleşyeceğim cinayetimi

yüreğimde boğarak 

öldüreiceğim sevgilim seni!', 'Seni öldüreceğim öyle sandığın gibi kolay bir ölümle bogazını sıkarak değil örneğin. Tabancanın namlusunu şyüreğine doğrultup tetiğini çeker...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cinayet-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Kadar Seviyorum', 'o-kadar-seviyorum-cafer-petek-t22uh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir ucundan diğerine ruhumun

bir kovalamacadır gider

güneş akrepte

ayda yelkovan

gözlerinde yıldızlar

-toz duman-

saçlarında bulutlar gider

bahar gider, yaz gider

dilinde tenhalığı şehrin

serin sokaklarında

sarı bir lambadır titrek

kapa kirpiklerini

soğuk doluşmasın 

gözlerinden yüreğine

ıslanmasın gözbebeklerin

bu mevsimde sırılsıklam olmak

yaramaz bedenine

ağır çeken tarafında terazinin

söylenmeyenler olacak hep

kifayetsiz kalacak kelimeler

mesela

seni sevdiğimi

söyleyebildim mi hiç

...

mürekkebe sığacak bir sevda değil bu

ben seni

söyleyemediğim kadar seviyorum', 'bir ucundan diğerine ruhumun bir kovalamacadır gider güneş akrepte ayda yelkovan gözlerinde yıldızlar -toz duman- saçlarında bulutlar gider ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Petek']::text[], 8.5, '{"poet":"Cafer Petek","poet_slug":"cafer-petek","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/o-kadar-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı', 'sakli-suleyman-davut-kenanli-99kuw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gerçek dediğin acıymış

yalan mı tatlı? 

dönüşüolmayan yoldasın 

güneşin mi battı? 

gülmeyen yüzün

ruhunda saklı

gerçeği seçen kim? 

kimin elinde aklı?', 'Gerçek dediğin acıymış yalan mı tatlı?  dönüşüolmayan yoldasın  güneşin mi battı?  gülmeyen yüzün ruhunda saklı gerçeği seçen kim?  kimin el...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Davut Kenanlı']::text[], 8.5, '{"poet":"Süleyman Davut Kenanlı","poet_slug":"suleyman-davut-kenanli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sakli-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kokuyorum', 'ben-kokuyorum-atil-kesmen-1roye', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağıtlar yakıyor 

Sana ağlamaklı bakan gözlerim

Nasıl bir yürek acısıdır, katlanamıyorum

Nasıl bir zehirdir,yutkunamıyorum

Nasıl bir duygudur kendimi bulamıyorum

Nasıl bir aşk''tır bu, nefes alamıyorum

Senin gönül düşlerine,mesken kurdum

Kar''dım buz oldum, eridim

Sevgi oldum

Seni buldum

Hayat nefesinden sızan sularda beslendim

Ve çiçek açtım

Seni gördüm

Seni sevdim

Senin gönlünde, ben kokuyorum', 'Ağıtlar yakıyor  Sana ağlamaklı bakan gözlerim Nasıl bir yürek acısıdır, katlanamıyorum Nasıl bir zehirdir,yutkunamıyorum Nasıl bir duygudur...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ben-kokuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ölüm Geliyor', 'bir-olum-geliyor-i-smail-kulahci-1ho43', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hissediyorum ölümü

Bekliyor beni kapıda tüm soğuk yüzüyle 

Büyük demir bir orak 

Birde kocaman kara bir çarşaf

Hissediyorum olümü 

Bekliyor beni kapıda 

Kim derdiki bu dağ gibi adam 

Yenik düşsün küçücük bir virüse 

Kim derdi ki

Neye yaradı okadar mal mülk

Hepsi gitti küçücük bir mikroba 

Ne güzel söylemişler 

Kefenin cebi yok diye 

Bütün herşey 

Kalanlara hediye

Biliyorum geliyor 

Her geçen gün biraz daha yaklaşıyor

Hisediyorum

Bir gece gözlerimi kapattığımda 

Birdaha açamayacagımı

Yavaş yavaş eriyorum bir buz parçası gibi 

Yorgun ve sönmüş bir yıldız gibi 

Kayıyorum bu dünyadan yavaş yavaş gök yüzüne

Gidiyorum artık 

Ölümün soğuk yüzüyle 

Gidiyorum 

Azrailin nefesi ensemde

Dostlarımın sevgisi kalbimde

Mal mülk dünyaya hediye 

Gidiyorum ben bütün iyiliklerimle

Gidiyorum elveda dostlarım

Elveda tüm sevdiklerim

Gidiyorum, elveda', 'Hissediyorum ölümü Bekliyor beni kapıda tüm soğuk yüzüyle  Büyük demir bir orak  Birde kocaman kara bir çarşaf Hissediyorum olümü  Bekliyor ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Külahçı']::text[], 8.5, '{"poet":"İsmail Külahçı","poet_slug":"i-smail-kulahci","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bir-olum-geliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüğüm', 'kucugum-coskun-deniz-iwgdj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dinle küçüğüm

Birgün birşeyler olacak

Birşeyler kıpırdanacak

O taze yüreğinde

Duymadığın bilmediğin

Anlamsız bir özlemle dolacaksın

Bir özlem

Bilmediğin ellerde görmediğin birine

Bir özlem

Ellerini tutmadığın

Sıcaklığını tatmadığın birine

Birgün küçüğüm

Yanlızlık burukluğu

Şarkı olacak dudaklarında

Yağmurları dinleyecek

Denizleri taşlaycaksın kıyılarda

İşittiğinde martıları

İşittiğinde çığlığını trenlerin

Dinlediğinde dalgaların sesini

Dinlediğinde sesini rüzgarların

Gördüğünde yaprakları savrulurken

Gördüğünde gökyüzünü ağlamaklı

Ve caddeleri sokakları

Islanmış gördüğünde

Tutsak olacaksın

Tükenmez bir avareliğin kollarına

Sel olacak tayfun olacak duyguların

Kahırlar küfürler geçecek içinden

Ve sen küçüğüm birgün

Bir özlem duyacaksın

Bilmediğin ellerde görmediğin birine

Sen diyeceksin

Elerini tutmadığım

Sıcaklığını tatmadığım

Neredesin

Sensiz olmuyor diyeceksin', 'Dinle küçüğüm Birgün birşeyler olacak Birşeyler kıpırdanacak O taze yüreğinde Duymadığın bilmediğin Anlamsız bir özlemle dolacaksın Bir özle...', ARRAY['Türk Edebiyatı','Şiir','Coşkun Deniz']::text[], 8.5, '{"poet":"Coşkun Deniz","poet_slug":"coskun-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kucugum-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meğer Melek Olmuşum', 'meger-melek-olmusum-i-smail-kulahci-a8x7m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gece kapattım gözlerimi, 

Derin ve masum bir uykuya.

Bir rüya görmeye başladım sonra; 

Gökyüzündeydim,

Ve yavaş yavaş iniyordum yer yüzüne doğru.

Sağ elim havada 

Ve tam ortasında küçük bir kar tanesi.

Hemde yıldız şeklinde...! 

Yavaş yavaş indim 

Ve biraktım kar tanesini. 

Bem beyaz bir çatının üstüne.

Bir süre baktım etrafıma.

Dedim allahım ne güzel bir rüya...! 

Sonra yine yavaş yavaş,

Çıkmaya başladım gök yüzüne.

Yolda söyledi bir melek,

Meğer rüya gördüğümü sanıyormuşum.

Dedi ki; 

İnsanlar ölürler  melek olurlar,

Ve her kar tanesini bir melek indirir dünyaya. 

İşte o an anladım gördüklerimin rüya olmadığını.

Meğer melek olmuşum gökyüzünde doğmuşum.

Bir kar tanesi bırakmışlar avcuma. 

İndir demişler yer yüzüne.

Göz alıcı bir beyazlık 

Ve olağan üstü bür güzellikle. 

Meğer melek olmuşum.

Gökyüzünde yeniden doğmuşum...!', 'Bir gece kapattım gözlerimi,  Derin ve masum bir uykuya. Bir rüya görmeye başladım sonra;  Gökyüzündeydim, Ve yavaş yavaş iniyordum yer yüzü...', ARRAY['Türk Edebiyatı','Şiir','İsmail Külahçı']::text[], 8.5, '{"poet":"İsmail Külahçı","poet_slug":"i-smail-kulahci","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/meger-melek-olmusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerelerdesin Sen', 'nerelerdesin-sen-osman-i-nci-rrpap', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin bir yarısında, zindandır dünyam,

Bir ışık bulamam, kabus olur her rüyam,

Yanımda yoksun ki, ben de rahat uyuyam,

Nerdesin yaban gülüm, nerelerdesin sen...

Hayatımın ışığı, yaşama sevincimsin sen,

Tutunduğum dalım, göz bebeğimsin sen,

Bana şans getiren, uğur meleğimsin sen,

Nerdesin aşk çiçeğim, nerelerdesin sen...

Yokluğun bir kahır, acı sitemdir dilimde,

Dünyaları da verseler, inan yok gözümde,

Sen yanımda ol yeter, ellerin de ellerimde,

Nerdesin gül kokulum, nerelerdesin sen...

Hiçbir şeyin tadı yok, sensiz hayatımda,

Olsan ne olurdu sanki, şimdi kollarımda,

Böyle sensiz olmak, ölümdür nazarımda,

Nerdesin hayat bağım, nerelerdesin sen...', 'Gecenin bir yarısında, zindandır dünyam, Bir ışık bulamam, kabus olur her rüyam, Yanımda yoksun ki, ben de rahat uyuyam, Nerdesin yaban gülü...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nerelerdesin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığım Çünkü', 'asigim-cunku-osman-i-nci-plewi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıldızları toplayıp, saçlarına takarım,

Bulutlardan ben sana, taçlar yaparım,

Bil ki, senin için Roma’yı da yakarım,

Hem deli hem cesurum, aşığım çünkü...

Hayat engellerle dolsun, vız gelir bana,

Her zorluğu aşarım, ulaşmak için sana,

İçeceğim bu sevdayı, hem de kana kana,

Hem deli hem cesurum, aşığım çünkü...

Kerem olurum, iste seni Aslı’m bilirim,

Mecnun olurum ben, çöllerde gezerim,

Ferhat olurum, aşılmaz dağları delerim,

Hem deli hem cesurum, aşığım çünkü...

Hayatım çiğnemen için, halıdır yoluna,

Akan gözyaşımla, deniz yaparım sana,

Bu kafaya taktım ya, öleceğim uğruna,

Hem deli hem cesurum, aşığım çünkü...', 'Yıldızları toplayıp, saçlarına takarım, Bulutlardan ben sana, taçlar yaparım, Bil ki, senin için Roma’yı da yakarım, Hem deli hem cesurum, a...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/asigim-cunku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sancı Şiirleri/4*Yas', 'sanci-siirleri-4-yas-nermin-altindag-cjgr5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ıslak sabun kokulu

zemini kaygan gecelerde

kaç yangının söndüğü 

bir mahşerdir 

gözlerim

kavgam

milat öncesi 

zamanlardan kalma

sorgularken geçmişimi

ve korkuyorken 

gelecekten

düş(ünce)   lerim 

bir ileri bir geri

bir varoluş kaygısı bu

yokluğun orta yerinde

ellerim tutarken bir avuç ateşi

haykırmak istiyorum:

Aşk öldü! ...', 'ıslak sabun kokulu zemini kaygan gecelerde kaç yangının söndüğü  bir mahşerdir  gözlerim kavgam milat öncesi  zamanlardan kalma sorgularken ...', ARRAY['Türk Edebiyatı','Şiir','Nermin Altındağ']::text[], 8.5, '{"poet":"Nermin Altındağ","poet_slug":"nermin-altindag","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sanci-siirleri-4-yas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-coskun-deniz-lw5jy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Evet birtanem

Anlatmak çok güç duygularımı sana şimdi

Çok güç biliyorum

Bir zamanlar korkusunu tebessümlere gizlediğimiz

Düşü yüreğimizi titreten

Bu ayrılık anını yaşamak

Çok güç biliyorum

Dudaklardan dökülecek birkaç sözcük

Yarınlar için sunacağımız birkaç dileyişle

Sonsuza saldığımız

Ve bir ömür boyu bizim sandığımız

Aşkımızı noktalamak

Biraz  sonra

Son kez birbirine bakacak gözlerimiz

Bakışlarımız son nakşını işleyecek sevgimize

Ellerimizin sıcaklığı son kez birbirine kavuşacak

Son kez birbirinin nemini tadacak dudaklarımız

Buruk iki yüreğin

Son yakın çarpışı olacak bu

Ve sırtı dönük adımlayacağız bu yolu

Ayrı yarınlara doğru', 'Evet birtanem Anlatmak çok güç duygularımı sana şimdi Çok güç biliyorum Bir zamanlar korkusunu tebessümlere gizlediğimiz Düşü yüreğimizi tit...', ARRAY['Türk Edebiyatı','Şiir','Coşkun Deniz']::text[], 8.5, '{"poet":"Coşkun Deniz","poet_slug":"coskun-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ayrilik-205-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşecektim Olmasaydın.', 'dusecektim-olmasaydin-mustafa-celebi-cetinkaya-yliuu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gitsem olacaktı aslında 

vede tamkapıyı kapattım gidiyordum uzaklara 

oysa gözüm arkamdaydı ve çapaklı

Ben gene uyumamıştım bütün gece. gece ki çile saklı. 

düşecektim olmasaydın. 

eğer bunu bilirsen benide bilirsin

belkide amaçsız geldin benim gibi 

sevmedin

oysa 

her zam yaptığında hükümet

ve her özelleşmesinde dertlerin ölmemiştim. 

Sonra bir bayrak yarışı başladı duraksız 

ve adıkarıştı garibalığın otoyol köşlerine

gitme..

aslında ''sanada ne oluyor '' demem gerek! 

giden bendim ölümü yüklenerek 

Bu değilmiydi zatenmuhalefetinistediği 

bu değil miydi işverenin işçinin emeği üzerinde pineklemesi

oysa adı asgari ücretti. 

sonra yaşımı hesaplamak istedim birden 

birde çektiklerimle sevdiklerimi tarttım dünyamda 

birde ne buldum dedim; ne buldum bu köhne yaşamda? 

Aslında benden daha zor sorular soruyordu DGM

ve ben benden yoruyordum düşleri 

bitti.....

gitsem olacaktı aslında 

Böyle tutarsız anılara tutunmak 

birde o adını adım gibi bildiğim olmayacaklar! 

''... bir yağmur başlıyor 

şemsiyemde yok ıslanıyorum öylece 

sonra bir gökkuşağı beliriyor üstümde 

koruyor sanki beni 

ve tutuyor ellerimi uzun bir vadide 

 :)))   çelebinin düşü bu kadar olur.....

satırlar boğuluyor sanki sanki ben o ben değilim 

hani o atını silahını kuşanıp sevgi dağıtan

ne kadar da karışmış kelimeler birbirine 

yoktutan. 

Gitmeliydim aslında 

düşmeliydim

kal dedi kudretli bir badı sevda 

pes ettim

.

buda adı ad olamamış 

buda yüzü hiç gülememiş

buda 

buda ayrılığın türküsü olsun

düşecektim olmasaydın

biliyorsun.....

13 kasım 2004 cumartesi 18:59

demetevler', 'gitsem olacaktı aslında  vede tamkapıyı kapattım gidiyordum uzaklara  oysa gözüm arkamdaydı ve çapaklı Ben gene uyumamıştım bütün gece. gece...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çelebi Çetinkaya']::text[], 8.5, '{"poet":"Mustafa Çelebi Çetinkaya","poet_slug":"mustafa-celebi-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/dusecektim-olmasaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Sızı', 'mavi-sizi-coskun-deniz-hmlo1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ürktü busesinden dalgaların yosunlu kayalar

Leylakların savruldu yaprakları meltem rüzgarlarında

Kızıllığı söndü ufuklarda doğup dönerken güneşin

Üveyiklerin dal uçlarından seyri bitti mehtabı                              Çakır kısık bakışlara büründü deniz ağlamaklı

Eteklerinde soldu tüm kır çiçekleri buralardaki dağların

Lüle ipli saçlarındaki naz savruldu birden avuçlarımdan

İsmin kayan yıldızı artık yitik hülyalarımdaki semanın

Kalan sadece mavi bir sızı yüreğimde 

O kor bakışlarından', 'Ürktü busesinden dalgaların yosunlu kayalar Leylakların savruldu yaprakları meltem rüzgarlarında Kızıllığı söndü ufuklarda doğup dönerken gü...', ARRAY['Türk Edebiyatı','Şiir','Coşkun Deniz']::text[], 8.5, '{"poet":"Coşkun Deniz","poet_slug":"coskun-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mavi-sizi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sardalya kutusu', 'sardalya-kutusu-aysenur-yazici-e5r1p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne çok yakışırız senle biz..

nasıl bir kuduz aşısı düşer ellerimi tutunca ellerin

ne çok gözdür bakışların 

ve ne denli huzurdur uyku senin dibinde..

gel dersin, gelirim...

ama kendim de bilirim

ki,

ben 

üstünde ''taze sardalya'' yazan

eski balıkların uyuduğu

etiketi 46 yıl öncesine tarihli

bir konserve kutusuyum...

sen, 

ağlardan pul pul çıkan denize

içi cam cam parıldayan kuma

düşmelisin...

gel gör ki

dayanamam..

he derim..

derim de,

bilirim çook şarkı vardır yazılmış

içinde 

''bir bahar akşamı'' olan...! 

 ne sen gönlüme bir söz et,

ne de ben benimkine şarkılardan

susalım

taze baharlar kör olsun...

13.11.2004

Bağcılar

19.20

Andrea and', 'Ne çok yakışırız senle biz.. nasıl bir kuduz aşısı düşer ellerimi tutunca ellerin ne çok gözdür bakışların  ve ne denli huzurdur uyku senin ...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sardalya-kutusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Korusun', 'allah-korusun-coskun-deniz-6pr30', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdalar yapsan alevinden ateşlerin

Yıldızları indirsen gökten birer birer

Alsan denizlerin maviliğini avuçlarına

Çırpınsa dudaklarında sevda ağıtları

Gök kuşakları gersen semaya binlerce

Kadehler dolusu ay parıltısı sunsan denizden

Buketler yapsan ışığından güneşin

Çıldırsa bir duanla tüm volkanlar

yağmurlar döksen çöllere  sürükleyip bulutları

Tüm çiçekleri yaprak yaprak sersen yollara

Sana dönermiyim sanıyorsun

Sensizliği bir kez tattım ben

Bir daha mı Allah korusun', 'Sevdalar yapsan alevinden ateşlerin Yıldızları indirsen gökten birer birer Alsan denizlerin maviliğini avuçlarına Çırpınsa dudaklarında sevd...', ARRAY['Türk Edebiyatı','Şiir','Coşkun Deniz']::text[], 8.5, '{"poet":"Coşkun Deniz","poet_slug":"coskun-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/allah-korusun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* * * MuTLu BAYRAMLAR * * *', 'mutlu-bayramlar-baki-son-g1ki3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'TÜM BEKLENTİLERİNİZİN 

GERÇEKLEŞMESİ DİLEĞİYLE...

BAYRAM SEVİNCİ YÜREĞİNİZDEN 

HİÇ EKSİK OLMASIN...! 

MUTLU BAYRAMLAR...

Sude Son', 'TÜM BEKLENTİLERİNİZİN  GERÇEKLEŞMESİ DİLEĞİYLE... BAYRAM SEVİNCİ YÜREĞİNİZDEN  HİÇ EKSİK OLMASIN...!  MUTLU BAYRAMLAR... Sude Son...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mutlu-bayramlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz güvercin', 'beyaz-guvercin-coskun-deniz-4kefe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeni doğmuştu beyaz güvercin

Taze bir zeytin dalı buldu sonunda

Hep gündüz sanırdı diyarları

Hep sıcak bilirdi güneşi

Sevecendi uçarken

Özgürlük şarkısıyla çırpınırken yüreği

Kayıyordu altında barış maviliğinde okyanuslar

Fakat sonsuzluğunda diretmişliğin

Düşüverdi kanatları güvercinin

Kırık bir özlem

Şaşkın gözlerle baktı

Batan güne

Ve

Döndü hayal yuvasına yeniden

Ağzında solmuş yapraklarıyla bir zeytin dalı

Anladı boşa gayretti aramak sabahı', 'Yeni doğmuştu beyaz güvercin Taze bir zeytin dalı buldu sonunda Hep gündüz sanırdı diyarları Hep sıcak bilirdi güneşi Sevecendi uçarken Özgü...', ARRAY['Türk Edebiyatı','Şiir','Coşkun Deniz']::text[], 8.5, '{"poet":"Coşkun Deniz","poet_slug":"coskun-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beyaz-guvercin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Geceden', 'sonsuz-geceden-coskun-deniz-2vqra', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gece,

İçimde girdaplanan dalgalar var.

Haykıran nameleriyle ürktüğüm,

Hiç duymadığım şarkılar içimde.

Çözemediğim bilmecelerle gülümsüyor yıldızlar

Nedense bu gece..

Karşı kıyılardan uzanan

Hafif bir melodi.

Gecenin sihrini kıran

Ürkek dalgalar.

Gurur dolu deniz.

Büyülenmişcesine durgun

Işık veren yıldızlar.

Ve derince çekilen

Bir nefes sigara..

Bu gecede şimdi

Çılgınca raksediyorken içimde duygular.

Bitmezliğin coşkusuyla sürüyorken düşlerim.

Elele vermiş düğümlenmişken yüreğimde

Sevgiliye özlemle sıla hasreti.

Çalkalanıyor dövünüyorken

benliğimde şimdi tüm anılar.

Ve adımlıyorken geceyi sürekli.

Yorgun ayaklarıma bakmadan fısıldıyor

Ilık bir rüzgar şu cümleyi.

Sonsuz bu gece hiç bitmeyecek..', 'Bu gece, İçimde girdaplanan dalgalar var. Haykıran nameleriyle ürktüğüm, Hiç duymadığım şarkılar içimde. Çözemediğim bilmecelerle gülümsüyor...', ARRAY['Türk Edebiyatı','Şiir','Coşkun Deniz']::text[], 8.5, '{"poet":"Coşkun Deniz","poet_slug":"coskun-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sonsuz-geceden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günlerin Anlamı', 'gunlerin-anlami-coskun-deniz-x1etk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir zamanlardı denir

Bugün

Dün için..

Olur ya,belki,kimbilirdir anlamı

Yarının

Bugün..

Ve bir zaman gelir, gülüp geçilir

Yarına

Dünden..', 'Bir zamanlardı denir Bugün Dün için.. Olur ya,belki,kimbilirdir anlamı Yarının Bugün.. Ve bir zaman gelir, gülüp geçilir Yarına Dünden.....', ARRAY['Türk Edebiyatı','Şiir','Coşkun Deniz']::text[], 8.5, '{"poet":"Coşkun Deniz","poet_slug":"coskun-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gunlerin-anlami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski', 'eski-ozlem-cakir-t9clc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaman geçiyor 

Seni itiyor yeniliklere

İstesen de istemesen de..

N’oldu? Sen başaramadın galiba

Ne beni unutabildin,

Ne bugüne alışabildin.

Hani gerçeğe dönüştüremedin de hiçbir şeyi

Hayallerdesin galiba hala..

Üzülmüyorum sana

Sadece izliyorum seni çok uzaklardan

Bende senden kalan tek şey bu

Merak olsa gerek 

Ya da

Tanımak eski seni

Yazık olan 

sadece

geride kalan zamanlara

Bugün olmayacak asla

İnan

Üzülmüyorum sana', 'Zaman geçiyor  Seni itiyor yeniliklere İstesen de istemesen de.. N’oldu? Sen başaramadın galiba Ne beni unutabildin, Ne bugüne alışabildin. ...', ARRAY['Türk Edebiyatı','Şiir','Özlem Çakır']::text[], 8.5, '{"poet":"Özlem Çakır","poet_slug":"ozlem-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/eski-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Külden manzaralar çizer bu şehir', 'kulden-manzaralar-cizer-bu-sehir-ozenc-yasar-4ybpv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hep o şehirde geçtimde

duvarlar döner yüzüme

parçalanmış gözde kalan soğuk bakışlar

geldiği gibi gider duvar gölgelerine

mavi kırmızı beyaz renkli trenlerle

soğuk yüzlü bakışların

cam çizgilerinde kırgın resimler gibi

yırtık rüzgarlarda eser

bu şehire gelen giden çok

ben ise hep burdayım

tek değilim aslında çokluklar içinde

yok sayılacak kadar az

şimdi geldiğim yolda geri dönüyorum

camdan çizik gölgeler kadar kırgın

hangi yüzle geldin akşam yokluklarına

yüreklerde bir şeyler koparıp götüren ayrılıklar

ışıklar yorgun dolaşıyor

tren birazdan peronda

telaşlar kaçışmaları kucaklayacak

özlemlerin geldiği buluşmalarda

hepsi hoş da ya ben

kime dönsem yüzüme dönüyor yalnızlıklar gibi

duvar ışıklar külünde manzaralı

insanlar hep böyle kalleş mi

işte bu şehir

beni bırakarak çekip gidendir

senin gibi dost olunca bu şehirde

16.05.00, Berlin', 'Hep o şehirde geçtimde duvarlar döner yüzüme parçalanmış gözde kalan soğuk bakışlar geldiği gibi gider duvar gölgelerine mavi kırmızı beyaz ...', ARRAY['Türk Edebiyatı','Şiir','Özenç Yaşar']::text[], 8.5, '{"poet":"Özenç Yaşar","poet_slug":"ozenc-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kulden-manzaralar-cizer-bu-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşle Doğmak', 'gunesle-dogmak-coskun-deniz-rv76n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabahın serinliğini içende

Koyu karanlığıyla dünyanın güneş.

Dün doğar doğada yine

Bitmez bu alın yazısı cismin.

Yaşanmamış dünleri yaşar sonsuza dek,

Güneşin her doğuşunda,

Bu dağ,bu ırmak,bu ova..

Biz; 

Biz öylemiyiz ya.

Bir doğuşu yaşarız biz,

Güneşin her doğuşunda.

Yaşanmış dünleri değil,

Binlerce ötesini yaşamadığımız dünlerin.

Yaşanacak yarını değil,

Erişilmez yarınları yaşamak için..

Olsa da bizim olmayan

Yarınlar ve dünlerle dolu.

Umut dolu,hayal dolu olsa da.

Sığabilmekteyse bir güne

Bir sonsuzdan ötekine uzanan bu yaşam.

Niye şikayetçisin dostum,

Günlerin kısalığından.

Niye o telaşın ömür kısa diye.

Niye bu sitemin ölüme..', 'Sabahın serinliğini içende Koyu karanlığıyla dünyanın güneş. Dün doğar doğada yine Bitmez bu alın yazısı cismin. Yaşanmamış dünleri yaşar so...', ARRAY['Türk Edebiyatı','Şiir','Coşkun Deniz']::text[], 8.5, '{"poet":"Coşkun Deniz","poet_slug":"coskun-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gunesle-dogmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bodrum''da Bir Yalnız Martı Yaşıyor (5)', 'bodrum-da-bir-yalniz-marti-yasiyor-5-murat-nail-guney-7tlq6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana kırgın idim, unuttum gülüm,

Bu bayram da seni yadettim gülüm,

Sılada,hasrete nöbettim gülüm,

Bodrum''da bir yalnız martı yaşıyor...

Gelmese mektubun, çalmasa zilim,

Vizyondan düşmedi bu bizim filim,

Aşığınım yine, malumdur halim,

Bodrum''da bir yalnız martı yaşıyor...

Sevginle yaşayan bir fakir kulum,

Ne saray, köşküm var, ne param-pulum,

Diploma vermiyor hayat okulum,

Bodrum''da bir yalnız martı yaşıyor...

Bağrım yanık ama, gezemem yasla,

Baş eğip yaşamam, sevdasız asla,

Beni özler isen, yavaşça sesle,

Bodrum''da bir yalnız martı yaşıyor...

Muradım, seherle yarışır oldun,

Abdal''a, Yunus''a karışır oldun,

Kaderin suçu ne, hakettin, buldun,

Bodrum''da bir yalnız martı yaşıyor...

13/11/2004 Murat Nail Güney-Gümbet/Bodrum', 'Sana kırgın idim, unuttum gülüm, Bu bayram da seni yadettim gülüm, Sılada,hasrete nöbettim gülüm, Bodrum''da bir yalnız martı yaşıyor... Gelm...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bodrum-da-bir-yalniz-marti-yasiyor-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılgınım', 'yilginim-coskun-deniz-afstn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arzularım prangalı sanki

Duygularım meçhulün pençesinde.

Paslanmakta düşlerim 

Amaçsız boş bir hayat endişesinde.

Nedenini haykıracak gücüm yok tüm bunların.

Bitmiş arayışım titik sevgilerde.

Benliğimi noktalayıp karanlıklara,

Gideceğim bir bilinmeyene.

Arkadaş olmayacağım artık yıldızlarla

Dinlemeyeceğim trenlerin sesini gecelerde,

Dinlemeyeceğim yağmurları bir şarkı gibi.

Sen yeşerinceye dek bir çöldü içim

Diye seslenmeyeceğim bir sevgiliye.

Kah fırtınalı, kah sütliman bir deniz

Olmayacak bu gönlüm.

Ne bir küskünlük bu sevgiye,

Ne de yeni bir arayış sevgiyi.

Öylesine bezgin, öylesine yorgunum ki,

Başbaşa kalmak istiyorum benle.

Görmek istiyorum benliğimde,

Sevgiden, sevgililerden gayrı,

Sinmiş duyguları özgürce.', 'Arzularım prangalı sanki Duygularım meçhulün pençesinde. Paslanmakta düşlerim  Amaçsız boş bir hayat endişesinde. Nedenini haykıracak gücüm ...', ARRAY['Türk Edebiyatı','Şiir','Coşkun Deniz']::text[], 8.5, '{"poet":"Coşkun Deniz","poet_slug":"coskun-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yilginim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanış', 'uyanis-didem-esen-g34yy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzak bir yerlerden

Yuvama dönüyor gibi

Özlemişim içimdeki beni

Sakın söndürme ateşini

Kaybolmuş yılları yakıyorum

Kaç nehir deli gibi çağlıyor 

Bedenim yaprak misali

Yılların içinden akıyorum

Sakın çekme ellerini

Avuçlarına yağıyorum

Çılgınlar gibi ayazda

Yürümek istiyorum karda

Soğuğu hissetmek 

Farz et  baharlar açmış dallarda

Ve ben seni düşünüyorum

Bir fırtına esiyor uçuyorum

Bulutlara konup susuyorum

Toprağına yağacağım 

Biliyorum

Deliler gibi özlüyorum', 'Uzak bir yerlerden Yuvama dönüyor gibi Özlemişim içimdeki beni Sakın söndürme ateşini Kaybolmuş yılları yakıyorum Kaç nehir deli gibi çağlıy...', ARRAY['Türk Edebiyatı','Şiir','Didem Esen']::text[], 8.5, '{"poet":"Didem Esen","poet_slug":"didem-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uyanis-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Her Gün Bayram       ss25', 'bana-her-gun-bayram-ss25-nesrin-gocmen-28pgt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgiyi bayramdan,

bayramı sevgiden ayırdetmeden,

yaşayıp gidenlerdenim ben.

Bir çiçek gibiyim.

Yok, değil öyle...Sevda çiçeği değil..

Yaprakları kurumuş, rengi yitmeye yüz tutmuş bir çiçek...

Özen ve sevgiyle bakılamamış, özlem serasında ısıtılamamış; 

sevgi güneşiyle beslenemeyip, hüzün sularıyla sulanmış bir çiçek...

Siz akıllılar ! 

Bakmayın öyle garipçe yüzüme! 

Benim bayramım deli sevgilerimdir.

Sizin gibi, yılda bir, iki kez bayram yapsaydım, çıkardım ben olmaktan, ben..

Size benzerdim,  ki bunu istemem.

Gönül pazarımda sevgiler satıp; hüzünler, özlemler alayım  ben.

Sen.....

Şu aklını gezmeye yolla...

Benim usulümle bayramlaşalım sonra.

Gönül soframızı kurayım,  karşına geçip, oturayım.

İçimdeki  yıllanmış sevda şarabımı açayım.

Hüzünlerimi, özlemlerimi meze yapayım..

Doldurayım çeşit, çeşit tabaklara, 

Türk Sanat Müziği bestelerini.

Bardağa  gerek yok.

Gözlerimiz var ya! 

Her göz kırpışımız bir duble olsun, içelim, içebildiğimizce....

Haydi şerefe bir yudum, 

haydi bir yudum daha,

kayıp sevgilere, kayıp sevgililere

Ne dersin? 

Böyle bir bayram gününde, gönül sofrasına oturup,

sevda şarabının en yıllanmışından içer misin benimle? 

Evet dersen; 

koşa, koşa; 

özlemlerimi  yükleyerek gelirim sana..

Ne oldu, sesin çıkmıyor? 

 Gelme  mi diyeceksin? 

Sus, konuşma sevgili.

Hergünki bayramımı yapayım ben..

Hayallerimi bozma,  birşey söyleme lütfen....

Sen söyleme...

(sen söyleme-25)       

13/11/2004', 'Sevgiyi bayramdan, bayramı sevgiden ayırdetmeden, yaşayıp gidenlerdenim ben. Bir çiçek gibiyim. Yok, değil öyle...Sevda çiçeği değil.. Yapra...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/bana-her-gun-bayram-ss25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gidince Anladıklarım', 'sen-gidince-anladiklarim-coskun-deniz-tpa9j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Meğer seher yelleride kırarmış başakları,

Umutlarda hep hanımeli açmazmış.

Düşünceler, sarıp sarmalarmış solmuş baharları.

Anılara küskün görüntülerde yaşarmış meğer düşler,

Ve geceler, hep yıldızları gizlemezmiş koynunda,

Hasretlere tutsak olurmuş, karanlığın kolları.

Meltem değilmiş tüm rüzgarların ismi meğer,

İsmi martı değilmiş,

Beyaz olan tüm kuşların.

Sırlar taşımazmış gündönümleri uzaklara her zaman,

Kolay değilmiş her bilmece,

İri sorular varmış yüreklere saplanan.

Nankör diye haykırırmış,

Saatler her geçen an''a,

Meğer arkadaş değilmiş akreple yelkovan.

Ağacın dalında filizlenirmiş meğer sevda,

Yalnızlıkmış kökleri,

Ayrılıkmış derinlere uzanan.

Şimdi sanma yalnız senin gözlerinde geziyor nemli bulutlar,

Yalnızlık doruklarından çığ gibi yıkıldığında,

Erkekler de ağlarmış inan,

Olsa da göz pınarları ıslanmadan', 'Meğer seher yelleride kırarmış başakları, Umutlarda hep hanımeli açmazmış. Düşünceler, sarıp sarmalarmış solmuş baharları. Anılara küskün gö...', ARRAY['Türk Edebiyatı','Şiir','Coşkun Deniz']::text[], 8.5, '{"poet":"Coşkun Deniz","poet_slug":"coskun-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-gidince-anladiklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mendil', 'mendil-nalan-palabiyik-n68wj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ahşap oymalı bir çekmecenin gözünde

Babaanne kokulu mendillerim…

Babaanne derim de kokusunu içime

Doya doya çekemedim

Ne onun ömrü yetti torunlarının muradını görmeye

Ne de ben yetiştirebildim ona 

Göremediğim torununu koklatıp sevdirmeye…

13.11.2004', 'Ahşap oymalı bir çekmecenin gözünde Babaanne kokulu mendillerim… Babaanne derim de kokusunu içime Doya doya çekemedim Ne onun ömrü yetti tor...', ARRAY['Türk Edebiyatı','Şiir','Nalan Palabıyık']::text[], 8.5, '{"poet":"Nalan Palabıyık","poet_slug":"nalan-palabiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mendil-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Bir Başlangıç', 'yeni-bir-baslangic-nalan-palabiyik-1bxuk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırıldı tüm zamanlar…

Gözlerimde yeni başlangıçlara duyulan özlem

Ellerim bomboş ve kahretsin hayalimde yine sen

Ve ben yine amaçsızca bilinmeyene savuruyorum kendimi…

13.11.2004', 'Kırıldı tüm zamanlar… Gözlerimde yeni başlangıçlara duyulan özlem Ellerim bomboş ve kahretsin hayalimde yine sen Ve ben yine amaçsızca bilin...', ARRAY['Türk Edebiyatı','Şiir','Nalan Palabıyık']::text[], 8.5, '{"poet":"Nalan Palabıyık","poet_slug":"nalan-palabiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yeni-bir-baslangic-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zamanlar', 'bir-zamanlar-ahmet-mansuroglu-av8m9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar 

Benimde defterim kalemim vardı

Umut yüklü düşüncelerim vardı

Sevinç dolu

Öğretmenlerim vardı

Ellerini doyasıya öpmek istediğim,

Okulumdu anam kadar sevdiğim,

Benimsediğim,

Bir kader rüzgarı

Söküp aldı beni okul sıralarından,

Hoyratça,

Anamdan ayrılsam

Belki daha kolay olurdu

Ayrılan sevğilide 

Zamanla unutulurdu.

Bir öğrenci görsem ders çalışan,

Bakışlarından bilği saçan,

Işıl ışıl..

Kalbim birden sevinçle vurur

Aradan yıllar geçti

İçimdeki ateş küllenmeden durur.



Antakya - Hatay', 'Bir zamanlar  Benimde defterim kalemim vardı Umut yüklü düşüncelerim vardı Sevinç dolu Öğretmenlerim vardı Ellerini doyasıya öpmek istediğim...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-zamanlar-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve...', 've-dogan-ekdi-m6un9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kara karanlık bir geceyi 

aydınlık bir sabaha vuruyordum.

bir iç ülkeden bir ülkeye doğru yol alırken

bir yandan yaşamın yeni zorluklarını düşünüyor,bir yandanda daha güzel bir yaşamın 

beni beklediğinin avuntusuyla geçiriyordum başı boş saatleri.

yani bir yanım zorluklarla mücadele etmenin yollarını ararken ağlıyordu korkakca,

bir yanımda güzel yaşamın hayaliyle sevinçten ağlıyordu acemice.

VE...

geçti o başıboş saatler,aydınlığa vurdum kendimi

rüzgarı dinledim önce

bir kadın eli gibi geçiyordu saçlarımın içinden.

denizi kokladım sonra

yarin ak gerdanı kokuyordu sonradan anladım.

VE...

kahrolası geçmiş yaşantılarımın taşlaşmış kalıntılarını silmeye çalışırken

vardım işte kötürüm düşüncelerimin belirginleşeceği yapının kapı ardına.

VE...

karşımdasın,incesin ruhumun en ince yerinde,sevdasın umudumun serencamında

ne haldeyim biliyormusun

dizlerim titriyor,bedenim kasılıyor,beynim yerinden çıkacak sanki, yüreğim zemheriye tutulmuş,

ruhum yangın yerine dönmüş görmüyormusun...

ilk tanışmamızı hatırlıyormusun küçüğüm

ben adını sormuştum sen söylemiştin,sen adımı sormamıştın ama ben söylemiştim nedeni

bilmem kendinden yağmur ıslaklığı

belkide alamayışımdan kendimi bal rengi gözlerinden.

her kelimen çivi gibi saplanıyordu beynime,hep konuşmak istiyordum senle

ama sen hep kaçıyordun.

yanımda olsun,karşımda dursun konuşmasada konuşmasın diyordum ama

sen gene yoktun. eskiden olsa

bu düşüncelerden kurtulmak için ikiye bölerdim yüreğimi,zincire vururdum.

ama yapamıyorum küçüğüm,nedeni bilmem

kendinden yağmur ıslaklığı herhal yada alamayışımdandır kendimi bal rengi gözlerinden.

VE...

seni arkadaşım seçtim.

bu ne yaman çelişkidir küçüğüm anlayamadım

bir yandan arkadaşça yaşamlar,öte yandansevgilice düşüncelerin verdiği rahatsızlık ve utanma duygusuikendi kendimi bitiriyorum küçüğüm

VE...

sırası geldi işte ayrılığın,kasveti kesiklerde büyüyen bir ayrılığın sırası geldi.

şımarık bir çocuğun büzülen gül dudaklarındaan süzülen,siyah saçlara kurdale iliştiren bir ayrılığın sırası geldi.gidiyorum işte

sesini sesime değdiremeden,gözünü gözüme değdiremeden,

kipriklerinin ucundan öpemeden,gül yanaklarına dokunamadan,

yüreğini yüreğimde hissedemeden,hatta son bir kere olsun sana kızamadan

ve içime atamadan deli öfkemi(ulan felek,böyle acemice,korkakca,titreyerek yaşayacağıma...) 

ayrılırken bu kötürüm şehirden 

geriye bir tek boynumun borcu bu şiir kalsın istedim

bir gün canın sıkılırsa ve konuşacak birilerini ararsan yıldızlara bak küçüğüm

mutlaka sana göz kırpıyor olacağım

bir gün bir şeylerin özlemiyle kavrulursan yüzünü rüzgara dön küçüğüm

mutlaka selam yollamışımdır sana

sen çölde açan çiçeğimsin,seni kemiresiye düşlemiştim,

iliklerime dek işleyesiye,ölesiye düşlemiştim.yaşamımı tersine çevirenlerin önde gelenisin

ne yaman çelişkisin sen,sen prensesimsin...

ben senin ellerini sağanak yağmurda,sokak lambasının altında

bir yandan ısınmaya çalışan,bir yandanda

yağmurdan korumaya çalıştığı üç beş kutu kibritini satmaya çalışan,küçük kibritçi kızın

anlından yanaklarına doğru akan yağmur sularını silmeye çalışırken gördüm

ve... umut dağıtırken al yazmalı gelinlere, ay vuran yönüyle gördüm elklerini

işte o an seni içimde bir tutam nefes gibi hissettim ve seni çok sevdim bir daha öldüm

seni ben

balkonda iki yanağını avuçlarının arasına sıkıştırmış bir şekilde

denizle gök yüzünün birleştiği noktaya bakarken ve mavi düşlerinde

kısa geçmişinden uzun ince geleceğine doğrudalmışken gördüm

karşıda kitapçıda oturmuş sigara içerken

işte o an seni içimde bir tutam nefes gibi hissettim ve seni çok sevdim,bir daha öldüm

ben senin saçlarını

rüzgarın ıslığında,martının gölgesinde,hep sevgiyi ve umudu çalangiterın tellerinde

ve özgürlüğe koşan kıratın savrulan yelelerinde gördüm

işte o an seni içimde bir tutam nefes gibi hissettim ve seni çok sevdim,bir daha öldüm.

 seni ben kızarken tam kızan,gülünce güneşi kıskandırırken 

kızdığını ve güldüğünü tam belli ederken,bana kafa tutarken gördüm

seni ben neşeliyken gördüm,seni ben üzgünken gördüm

işte o an seni içimde bir tutam nefes gibi hissettim ve seni çok sevdim,bir daha öldüm

BEN EN ÇOK UYURKEN SENİ 

DAKİKALARCA SEYRETMEYİ SEVDİM

ben senin insanlarla diyaloglarındaki samimiyetin,

yüreğindeki tazeliği,bal karası gözlerindeki ışıltıyı,

ay vuran yönüyle yüzünü,merhamet kokan ellerini,

nisan yağmuru gibi dizili dişlerini,yaz sıcağı gülümseyişini,

zemheri karakış gibi deli öfkeni,

sevda buklesi hafif nemli ve uçlarından su damlayan saçlarını,

fırat gibi hayata akışınıi, dicle gibi endamını gördüm

işte o an seni içimde bir tutam nefes gibi hissettim ve seni çok sevdim,bir daha öldüm

BEN EN ÇOK UYURKEN 

SENİ DAKİKALARCA SEYRETMEYİ SEVDİM

sen benim düşsel prensesimsin birtek sen

çünkü ben sende bütün aşklarımı temize çektim gulasor...', 'kara karanlık bir geceyi  aydınlık bir sabaha vuruyordum. bir iç ülkeden bir ülkeye doğru yol alırken bir yandan yaşamın yeni zorluklarını d...', ARRAY['Türk Edebiyatı','Şiir','Doğan Ekdi']::text[], 8.5, '{"poet":"Doğan Ekdi","poet_slug":"dogan-ekdi","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/ve-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-deger-ulas-turan-96hre', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Özledim, 

Ellerine dokunmak kaldı 

Gözlerinin söylediği şarkıyı dinlemek 

Sesindeki cıvıltıda yaşadım saniye saniye. 

Özledim, 

Minik bedenine koca yüreğinin gölgesi düşerken 

O çınarın dalındaki yaprağı 

Denizinin dalgalarıydı 

Çarpıp yeniden, yeniden… 

Özledim, 

Sair akşamların yüreğindeki ışıltısını 

Göğsüme iliştirdiğim minik kelebeğimi 

Çiçek diyarı kokunu… Teninden savrulup, 

Ta içime yerleşen aromalı aşkını.

Özledim, 

Anlamak değil niyetim 

Anlamadan, anlatılmadan 

Bütün anlamlardan sıyrılıp sadece seni, 

Çırılçıplak yüreğinde yaşamak.

Özledim, 

Acılardan sıyrılıp 

Çıkmaz sokağında kaybolmayı 

Çıkarsız her dokunuşumda 

İrkilerek bakmanı bendeki gölgene 

Özledim seni, 

Bütün özlemlerin ötesinde 

Ayrılıklara sığmayan 

Sığmayan yüreğime bu sevgiyle çoğalıp 

Seninle hasretin adını kavuşmak koymayı 

Özledim 

Ben, 

Seni 

Her şey yapan sevgini.

Her şeyde sen olan hasretini bile sevmeyi

Mutluluk adına attığım bütün tohumların 

Mevsimlerine kavuşmasını 

Yağmur gibi, toprak gibi 

En doğal haliyle bendeki aksini 

Özledim ey yar 

Yollara düşüp 

Yeniden yaşattığın için bu kavuşma telaşını. 

Seni daha 

Her geçen zaman içinde, 

Bir daha özledim...', 'Özledim,  Ellerine dokunmak kaldı  Gözlerinin söylediği şarkıyı dinlemek  Sesindeki cıvıltıda yaşadım saniye saniye.  Özledim,  Minik bedeni...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/ozledim-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesleniş', 'seslenis-coskun-deniz-kfi3y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamana sitemler sürekli

Olamaz.

Ufuklar tutsak değil karanlığa.

Haykırıştır gönüllere sesi düşlerin

Susamaz,

Aşklar var benliklere sinmiş susamış yaşamaya.

Leylaktır çiçeği sevginin her mevsim

Solamaz,

Coşkusu var iki gönlün bir düşünce bir yürek olmaya.

Onurdur yücelen doruklarında sevginin

Gurur olamaz,

Şarkılar var anılara sır adanmış sonsuzluğa.

Kordur sevgiyle bakışı gözlerin yeminlidir sızısı

Duramaz,

Umutlar var zorlu sitemleri yüklenen ahdetmiş yıllanmaya.

Nakşı var düğümleyen düşünceyi sevginin

Bitemez,

Duyguları var sonsuz ve sarhoş yabancı yorulmaya.', 'Zamana sitemler sürekli Olamaz. Ufuklar tutsak değil karanlığa. Haykırıştır gönüllere sesi düşlerin Susamaz, Aşklar var benliklere sinmiş su...', ARRAY['Türk Edebiyatı','Şiir','Coşkun Deniz']::text[], 8.5, '{"poet":"Coşkun Deniz","poet_slug":"coskun-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/seslenis-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-deger-ulas-turan-nbhy7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk 

Ve insan yaşadı acı çekerek belki 

Ama unutmadı içindeki o güzel şeyleri 

Tanıdık bir sevinç buldu 

Tanıdık bir sevinç gibi 

Tanıdı bütün güzel şeyleri 

Aşk 

Yaşamışsak ve anlamışsak 

Hayata dair ne varsa 

Tanımı hep en zor, en yasak... 

Bir kelebektir. 

Aşk 

İçimizde bir yerde durmadan kanat çırpar 

Ve biz hep o kelebeğin peşinden ona ulaşabilmek için 

Umudumuzu besleriz 

İçimizde bir yerde işte acısı, anısı, 

Tutkuları kadar kanat çırpar 

Ve biz bu çırpınışları özleriz hep. 

Aşk 

Özlemektir o kelebeği, 

Varlığına aldırmazken 

Yokluğunda hep hasrettir 

Aşk 

Sonu hep mutlu biten bir kelebek masalıdır... 

Ve ben kelebekleri severim, 

Ama aşk için kelebekleri öldürmem 

Çoğaltırım içimde ne varsa, 

Tanımını bilmediğim bütün güzellikleri 

Sevgi adına aşk adına.', 'Aşk  Ve insan yaşadı acı çekerek belki  Ama unutmadı içindeki o güzel şeyleri  Tanıdık bir sevinç buldu  Tanıdık bir sevinç gibi  Tanıdı büt...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ask-305-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutsal Mezarım', 'kutsal-mezarim-deger-ulas-turan-ui9m5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sessizliğimi süslüyorum, 

Bütün susuşlar gibi oluyor, sessizliğimde bütün kadınlar 

Yalnız ve yapayalnız bir aşk hikâyesi bu 

Yalnızlığımın sırtına bir yük gibi biniyor her şey, 

Üstümdeki bütün yıldızlar dökülüp seriliyor toprağa 

Gökyüzüne bakmaktan korkuyorum, 

Ya ay ışığı yakıyor tenimi, 

Ya karanlık boşluğu gökyüzünün. 

Karanlıktan korkmuyorum ama. 

Sadece yalnızlık ve sessizlik 

Bir şafak beklentisi ki, 

Her şeye inat sensizliğe sessizliğe 

Ve gökyüzünün yalancı esmerliğine 

Dolanıp duran şu yıldıza bak 

Ki adresi yok işte, nereye gitse 

Kimsesizliğini çarpıyor yüzüne 

Tüm aşkların ve tüm acıların varlığı 

Sessizliğim diyorum, 

Özlemim yani. 

Seni içime gömdüğüm o kör boşluk. 

Benim en kutsal mezarım...', 'Sessizliğimi süslüyorum,  Bütün susuşlar gibi oluyor, sessizliğimde bütün kadınlar  Yalnız ve yapayalnız bir aşk hikâyesi bu  Yalnızlığımın ...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kutsal-mezarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-didem-esen-l9rsq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rüzgarda belli belirsiz 

Savrulan kömür kokusu

Avaz avaz yüreğimde

Hüzünlerin en koyusu

Aklım takılı karanlıkta bir yıldız gibi

Anlık değildi bu esareti

Bildiğim zamanlardan öncesi

Kayıp kurtulmuştu bir tanesi

Bir çocuk  titriyor karanlıkta

Sense ellerini unutmuşsun boynumda

Üşümüyorum, vermek istiyorum

Paylaşmak zor  bu havada

Gözlerini kapamış düşünüyor evler

Kederli, bir daha açılmayacak kapılar

İki sarhoş uzanmış, örtüleri kuponsuz

Canımı acıtıyor hatıralar

Şehir karalar bağlamış bir gecelik

Güneş doğana kadar matemde 

Yokluğun çarpıyor yanağıma

Yokluklar mı sürükler umuda

Çığlık çığlığa bir ses 

Bu ben değilim bağırmıyorum

Bir ayna tutuyorum

Kendi kendimi yeniden tanıyorum', 'Rüzgarda belli belirsiz  Savrulan kömür kokusu Avaz avaz yüreğimde Hüzünlerin en koyusu Aklım takılı karanlıkta bir yıldız gibi Anlık değild...', ARRAY['Türk Edebiyatı','Şiir','Didem Esen']::text[], 8.5, '{"poet":"Didem Esen","poet_slug":"didem-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ayna-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onca Şey', 'onca-sey-baykal-kaanalp-oxu5z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'beynime kazıdığım

onca şeyden sonra

bir değişiklik olsun diye

saçlarımı uzatıyorum

özgürce', 'beynime kazıdığım onca şeyden sonra bir değişiklik olsun diye saçlarımı uzatıyorum özgürce...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/onca-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüklediğimiz Anlamlar', 'yukledigimiz-anlamlar-baykal-kaanalp-z5ct6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'şair yazar bir şeyler

önemsemez yazdıklarını

anlamda katmaz

belki hiç düşünmez

belki de hayal bile kurmaz

her okuyan

kendi dağarcığından

kendisi yükler

kelimelerin anlamlarını', 'şair yazar bir şeyler önemsemez yazdıklarını anlamda katmaz belki hiç düşünmez belki de hayal bile kurmaz her okuyan kendi dağarcığından ken...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yukledigimiz-anlamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkes Biraz Hırsızdır', 'herkes-biraz-hirsizdir-baykal-kaanalp-1xcl8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'herkes biraz hırsızdır

kendi hayatının

belli bölümlerinde

çalacak bir şeyler

bulmuştur elbet', 'herkes biraz hırsızdır kendi hayatının belli bölümlerinde çalacak bir şeyler bulmuştur elbet...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/herkes-biraz-hirsizdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesif', 'kesif-gulsen-senderin-90yqr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzun bekleyişlerin ardından 

Zam düdüklerinin yankısı duyulur 

Suskun duyguların acılığını bastırarak 

Biriken  ödenek paketleri için 

Postacı kapıyı,ikinci kez çalar... 

Bir seyahat acentesi, müjdelerken 

Yan yana iki koltuk numaralarını 

Şimşek hızıyla koşarak, gözler kapalı 

Varılır, loş ışıklar altındaki rıhtıma 

Denizin ak gülleri martılar, kanat çırparak 

Çığlıklarıyla eşlik eder, içimizdeki sese 

Deniz kokusuna karışan görüntülerden 

Kabarıp köpükleşen sulara, el sallar 

Zaman kırıntılarına asılan yolculuklar... 

Yitik yaşamların sandıklarını taşıyan 

Görkemli bir °Aşk Gemisi° yanaşır 

Güneş güllerinin, her mevsim açtığı 

Palmiye gölgelerinde özgürlüğün koktuğu 

İletilerle dolu şişelerin sahillere vurduğu 

Renk renk ışıldayan,'' Mutluluk Adası''na ''... 

Bizi karşılayanlar arasında, kimliğimiz 

Ve uyutup da uyandırmaya korktuğumuz 

Açılımlarını yasakladığımız; kişiliğimiz 

...den -başka bir şey değildir- 

Tutku dolu ada kokularının arasına 

Naftalin kokuları karışır,bohçalar açılırken 

Ateş böcekleri,kristal kürelerin sergilendiği 

Göz alıcı,ışıltılı fuarlara bekçilik yapar. 

Taze solukların sıcaklığında,taht kuran hazlar 

Tatlı tatlı camdan beşiğimizi sallarken 

Evde bıraktığımız çiçekleri,küçük meleklerin 

Unutmayıp sulayacaklarını,kulağımıza fısıldar... 

Dalgalar kıyıları yalarken; hep bir kesifi anlatır 

Bembeyaz köpüklerin coşkulanmış çiseleriyle....', 'Uzun bekleyişlerin ardından  Zam düdüklerinin yankısı duyulur  Suskun duyguların acılığını bastırarak  Biriken  ödenek paketleri için  Posta...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kesif-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Fotoğraflara Bakıyorum da...', 'su-fotograflara-bakiyorum-da-bekir-mutlu-gokcesu-2wnlg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne güzel insanlarmış

Siyah, beyaz zamanlarda

Bin yıldız pırıltısı taşmış da

Gözlerden

Bin tebessüm sığmış

Adeta dudaklara...

Özenli saçlar

En güzel giysileriyle

Ne de güzel gülmüşler

Hayata

İnsan olmanın tadında...

Mutlu oluyorum, ruh buluyorum

Siyah, beyaz zamanların

Gencecik insanlarında

Şu fotoğraflara bakıyorum da...

Eller, yüzler öpesim

Kahve içesim geliyor

Bir sevinç kaplıyor içimi

Çocukluğumdan kalma

Bayram sabahları tadında...', 'Ne güzel insanlarmış Siyah, beyaz zamanlarda Bin yıldız pırıltısı taşmış da Gözlerden Bin tebessüm sığmış Adeta dudaklara... Özenli saçlar E...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/su-fotograflara-bakiyorum-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Sabahı', 'bayram-sabahi-umit-kilislioglu-ozger-3a54y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen camiden dönünce,

Önce, 

Elini annem öperdi.

“Biz böyle gördük” derdi.

Buna kıkır kıkır gülerdim

Yoktu ki derdim! 

Neş''eyle sıramı beklerdim.

Ben boynuna sarılınca 

Mutluluktan erirdin,

Elini öptürür, 

Para verirdin.

Bayramlık entarimi

Sabahın köründe giyerdim 

Öylesine  erken,

İlk misafire daha saatler varken.

Yeni ayakkabım ya sıkar, ya vururdu

Yine de bütün gün

Ayağımda dururdu.

...

Artık bayram sabahlarında

Mahzunum baba.

Olsaydın da sorsaydım 

Ben mi iyice kırılgan oldum

İnsanlar mı daha kaba? 

Bilmiyorum nasıl geçti hayatın

Belki çile çektin, belki sefa sürdün

Ama sanki giderken

Çocukluğumu da götürdün.

(14.11.2004)', 'Sen camiden dönünce, Önce,  Elini annem öperdi. “Biz böyle gördük” derdi. Buna kıkır kıkır gülerdim Yoktu ki derdim!  Neş''eyle sıramı bekler...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bayram-sabahi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Elini Uzatmış', 'gurbet-elini-uzatmis-ahmet-hakan-yilmazturk-n9uff', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gurbet elini uzatmış

yürekler pare pare 

hasretleri çoğaltmış

gurbet ömür törpüsü

sılaya özlem türküsü

gurbet elini uzatmış

ağzında tatlar buruk

mesafeler tuzakmış

gurbet ömür törpüsü

sılaya özlem türküsü

gurbet elini uzatmış

sabırdan dişler kırıp

nefesleri daraltmış

gurbet ömür törpüsü

sılaya özlem türküsü

gurbet elini uzatmış

emeğini ellere verip

hayatları kazanmış

gurbet ömür törpüsü

sılaya özlem türküsü

14.11.2004

Samanyolu (Nigar Yıldız)  Hanımefendi’ye armağanımdır.', 'gurbet elini uzatmış yürekler pare pare  hasretleri çoğaltmış gurbet ömür törpüsü sılaya özlem türküsü gurbet elini uzatmış ağzında tatlar b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gurbet-elini-uzatmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve geldi Bayram', 've-geldi-bayram-akin-akca-6j5an', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nice bayramlara 

sağlam arkadaşlıklarda 

sağlıkta hastalıkta 

bozulmayan sevgilerle 

hep güzel günlere 

Mutlu bayramlar 

dilerim herkese 

Tarladaki ürüne, kardeşlik; 

dostluk, dokuma tezgahıyla 

daha bir güzel olur 

bayram sevinciyle - 

iç içelik, bereketin … 

Çiçek tozları yıldız tozlarına sitemkar, 

ve yine çiçeklere konar arılar:

ağlar, bebekler, ilk doğduğunda; 

yüzdüklerinde süt içinde, gülerler... 

Gelir ve geldi bayram 

ve gelsin beyazımın şiirimdeki, 

gözü yaşlı ve güleç kara’m … 

daire yine tümlendiğinde. 

mevsim şenlikleri yenilendiğinde … 

Mutlu bayramlar 

dilerim herkese

14 Kasım 2004', 'Nice bayramlara  sağlam arkadaşlıklarda  sağlıkta hastalıkta  bozulmayan sevgilerle  hep güzel günlere  Mutlu bayramlar  dilerim herkese  Ta...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ve-geldi-bayram-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
