INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Xxx Canım Sıkılıyor', 'xxx-canim-sikiliyor-zeki-ergin-ti89m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'canım sıkılıyor 

son günlerde dünya haline 

çok ama çok

gördükçe o resimleri

kan içindeki 

bebeleri dedeleri

canımı sıkıyor

son günlerde birileri

doymak bilmeyen 

o gece vampirleri

_erenköy 19kasın2004', 'canım sıkılıyor  son günlerde dünya haline  çok ama çok gördükçe o resimleri kan içindeki  bebeleri dedeleri canımı sıkıyor son günlerde bir...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/canim-sikiliyor-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seneler Sonra', 'seneler-sonra-semiha-aslan-19q78', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllardan sonra görünce tanıyamadım seni,

 baktim düşmüş aklar, beyazlamış saçının her teli.

 Bende saklı hala giderken yanağıma kondurduğun ayrılık busesi

 hatıra kalsın istedim, olur da dönmezsin ya  geri.

 Baktim göremedim gözlerinin eski ferini 

 kızınca inlettim sazımın aşk namesi çalan bamtelini.

 Bendedir sadece aşkının notasının kilidi

 öyle nağme ki değişmedi hiçbir nağmeye gönül,degişmez öteden beri.

 Kim ne derse desin, sensin yaradanın en güzel eseri

 gülmeyince anladım, gidişinle aldı elem neşenin yerini.

 Dalgandırsada koca sevdan aşkmın durgun denizini

 tadınca anladım, askının zehri ickilerin en güzeli.', 'Yıllardan sonra görünce tanıyamadım seni,  baktim düşmüş aklar, beyazlamış saçının her teli.  Bende saklı hala giderken yanağıma kondurduğun...', ARRAY['Türk Edebiyatı','Şiir','Semiha Aslan']::text[], 8.5, '{"poet":"Semiha Aslan","poet_slug":"semiha-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seneler-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye...', 'sevgiliye-semiha-aslan-3x5oo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrılığımızn bitişini, baslangiç yaptım bu sevadaya

 sine sine işlendi o deli dolu sevdan, kanima

 korktum silinir diye,yazdım adını buğlanmış camıma

 ne mutlu bana ki  kalktim baktım hala orda.

 Sevdanın o narin nakışı ince ince işlendi başıma

 Şirin’in aşkı bile hafif kaldi yaninda

 gittiğinden beri duymadım başka hitap, seninkilerin tadinda

 dediler boşuna dua etme,söz geçmedi geçmeyecek olacağa.

 Nekadar  sevsem de su dökemem Mecnunun eline bu hususda

 ama içimdeki kuş özgür kalmayı bekler askının mapusunda

 kelimeler kifayetsiz kalır, bu özgürlükle varacağım huzuru anlatmaya

 yanılırsın, diyorsan birgün nasılsa varacagiz büyük  sona.', 'Ayrılığımızn bitişini, baslangiç yaptım bu sevadaya  sine sine işlendi o deli dolu sevdan, kanima  korktum silinir diye,yazdım adını buğlanm...', ARRAY['Türk Edebiyatı','Şiir','Semiha Aslan']::text[], 8.5, '{"poet":"Semiha Aslan","poet_slug":"semiha-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgiliye-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durdu Zaman Senle', 'durdu-zaman-senle-semiha-aslan-qqql7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Korkuyorum,derler gözden uzak olan gönülden ırak olurmuş

aşkının bana yaşattiği üstü kapalı, soğuk bir bozgunmuş

sevdan hayatımda yaptığım en büyük vurgunmuş

anlayınca bu kalp gittigini, hissettim durmuş.

 Bu eller ile gözler yokluğunda sensiz buruşmuş

 şimdi hasretin içimde senden kalan tek kormuş

 sesi çıkmayınca ruhun dinledim, susmuş

 bırakınca ardında gözü yaşlı, baktım zaman senle durmuş.

 Yatmayıp düşünürken seni baktım gece sabahı bulmuş

 konuşurken bana aldığın çicekle baktım içi geçmiş solmuş

 hergün çiceğini beseleyen göz pınarlarim artik  kurumuş

 demek çiçeğinin ömrü, bir  kelebeğin ömrü kadar uzunmuş.', 'Korkuyorum,derler gözden uzak olan gönülden ırak olurmuş aşkının bana yaşattiği üstü kapalı, soğuk bir bozgunmuş sevdan hayatımda yaptığım e...', ARRAY['Türk Edebiyatı','Şiir','Semiha Aslan']::text[], 8.5, '{"poet":"Semiha Aslan","poet_slug":"semiha-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/durdu-zaman-senle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmasanda Yanımda', 'olmasanda-yanimda-semiha-aslan-4a92f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Simdi baska ellerde oldugunu bile bile aramam

olunca yanımda senden baska dünya arasamda bulamam.

Bikmadan dinlesem sesini ömür boyu,bir kerecik duyamam

ne yapsamda,,senin o tatlı dilinden başkasına kanamam.

Yokluğunda eksik gelir herşey olsada tas tamam

sen olmayınca der gönül pes etme,anılara dayan

baktı oldu gönül feryat figan, sabır verdi bu aşkı kaderime yazan,

umutlandim,dedim gönlüme '' gel edelim bu hasrete devam.''', 'Simdi baska ellerde oldugunu bile bile aramam olunca yanımda senden baska dünya arasamda bulamam. Bikmadan dinlesem sesini ömür boyu,bir ker...', ARRAY['Türk Edebiyatı','Şiir','Semiha Aslan']::text[], 8.5, '{"poet":"Semiha Aslan","poet_slug":"semiha-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/olmasanda-yanimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Mevsimidir Güz', 'yalnizlik-mevsimidir-guz-volkan-yoruc-s23hk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnızlık mevsimidir güz

Yapraklar ağacı

Çiçekler toprağı

Kuşlar gökyüzünü terkederler

Bir ben kalırım çaresiz

Bir ben gidemem ümitsiz

Hüzün mevsimidir güz

Rüzgarlar eser buz soğuğu

Donar bakışlar hatıralarla

Eller yalnızlıkla sarılır umutlara

Üşür düşler içimde

Saklı kalan hayallerimle

Yalnızlık mevsimidir güz

Ve uzak kalmış bana o tatlı düş', 'Yalnızlık mevsimidir güz Yapraklar ağacı Çiçekler toprağı Kuşlar gökyüzünü terkederler Bir ben kalırım çaresiz Bir ben gidemem ümitsiz Hüzün...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalnizlik-mevsimidir-guz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İllede Sen', 'i-llede-sen-semiha-aslan-vdqrl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İstemem çözülmesin gözlerinin büyüsü

sönmesin,birkere yakıldı kalbimde sevginin tütsüsü

yanarda külleri kalır,geçmez içimin hüznü

verdiğin gülleri sakladım, kurutup da yaptım odamın süsü.

Bu aşk bitmez dercesine resimlerin önüme düştü

aldım aralarından bir tane,koydum yastığımın altına,yaptım aşkımın büstü.

Yillarca döner ümidiyle beklerken bu kalp sevmeye küstü

dünün anılarıyla yaşayan gönlümün aşkda dili sürçtü.', 'İstemem çözülmesin gözlerinin büyüsü sönmesin,birkere yakıldı kalbimde sevginin tütsüsü yanarda külleri kalır,geçmez içimin hüznü verdiğin g...', ARRAY['Türk Edebiyatı','Şiir','Semiha Aslan']::text[], 8.5, '{"poet":"Semiha Aslan","poet_slug":"semiha-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/illede-sen-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-semiha-aslan-vqnou', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çözülmedi gitti gözlerimin buğusu

kokularin en güzeliydi,saclarının kokusu

senden geriye kalan sevdanın tortusu

yetmedi yüreğime, geçmedi korkusu.

İsyan ettim yaradana, silinsin istedim alnımın yazısı

daha çok kabardi derdinle gönlümün derthanesi,

peki nezaman bitecek, bu gönlümün sessiz harbi

ister gönül galip gelsinde, tek o  kazansin seni.

Sensiz anlamını yitiriken ömrümün her saniyesi

görenlere dedirtir; bunlarınki yarım kalan bir aşk hikayesi.

Kalbime saplanmiş, kanatirken aşkinin pençesi

acı duymaz da gönül, döker sevinçten göz yaşı tanesi.', 'Çözülmedi gitti gözlerimin buğusu kokularin en güzeliydi,saclarının kokusu senden geriye kalan sevdanın tortusu yetmedi yüreğime, geçmedi ko...', ARRAY['Türk Edebiyatı','Şiir','Semiha Aslan']::text[], 8.5, '{"poet":"Semiha Aslan","poet_slug":"semiha-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hasret-203-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidenin Ardından', 'gidenin-ardindan-semiha-aslan-dayfs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sıyrılsam günahlarımdan,çıksam karşına

hoşgeldin derde,kabul edermisin sevaplarinla beni? 

Durup karşında dirensem, sevmiyorum diye seni

bende vazgeçtim derde, adım atarmısın geri! 

Taş altında bile arar oldum izini

bulamayınca kızdım sana,bitti dedim sevmiyorum seni

sensizliğin karanlığında ararken herşeyde  parmak  izini

duymak istedim duyamadım ayak sesini.

Anlatmak zordu fikrimi zikrimi

nasılsa değiştiremiyecektin bendeki seni

koparmak isteyince gidişinle, bende kalan zerreni

savaştim ve vermedim, öleceğimi bilsem de geri.', 'Sıyrılsam günahlarımdan,çıksam karşına hoşgeldin derde,kabul edermisin sevaplarinla beni?  Durup karşında dirensem, sevmiyorum diye seni ben...', ARRAY['Türk Edebiyatı','Şiir','Semiha Aslan']::text[], 8.5, '{"poet":"Semiha Aslan","poet_slug":"semiha-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gidenin-ardindan-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olmayınca', 'sen-olmayinca-semiha-aslan-ftl7y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Alsan beni şimdi yanına, nasılsa barışacak ruhum ruhunla, eninde sonunda.

Tutsan güneşden sıcak ellerinle ellerimi, dolasan o ince narin boynuna.

Açıp kucağını tatlı bir heyecanla,bassan beni o sen kokan bağrina.

Görüp seni  doysa gönül varlğına da bitse duyduğum asırlık özlem sana.

 Karıştı bir kere aşkının  zehri kanıma,

 istesende taşıyamam, dayanamaz can buna.

 Canımı feda etsem de yetmez bu sevdanın ugrunda,

 aşkın meğer doğarken yazılmıs o günahsız alnıma.

 Alışamadım yokluğuna,kalakaldım ortada.

 Senin için atan kalp, işte tam burda.

 Görsem de seni, sevgini benden çalan hırsızla karşımda,

 ben istemeden bitmez sürer gider bu sevda, ruh bedenden çıkmadıkca.

 Feda etsem sevdan hariç,herşeyi yolunda

 acaba bedenime geri dönermi ruhum, varlığınla.

 Prangalar vurup yasak etsemde gönlüme sevmeyi yokluğunda,

 bitmeden bu kırgınlık daha çok kavak yelleri eser başımda.', 'Alsan beni şimdi yanına, nasılsa barışacak ruhum ruhunla, eninde sonunda. Tutsan güneşden sıcak ellerinle ellerimi, dolasan o ince narin boy...', ARRAY['Türk Edebiyatı','Şiir','Semiha Aslan']::text[], 8.5, '{"poet":"Semiha Aslan","poet_slug":"semiha-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-olmayinca-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Of Deli Gönül', 'of-deli-gonul-semiha-aslan-dhzoh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hata bendeydi sevgilim,sevmemeliydim seni,ne de senin beni sevmeni.

Baştan dizginlemeliydim  gönlümü isterken seni ve sevgini.

Fikrinle bulanmış beynim,söz geçiremedi aşkından ayyaş gönlüme.

Dizginleri kaptı gönül elimden ve sürükledi beni yüreğimin götürdüğü yere

''Yapma gönül üzerler bizi ''dedim, aldırmadı

ve benim zavallı gönlüm bu aşkı kaldıramadı.

Aradan aylar geçti baktım gönül yorgun

dedim kaldır başını gönül niye yüzün solgun

dedi ararken mutlulugu, uğradı bana bir bozgun

vazgeçtim kartal olmaktan oldum artık bir kuzgun.', 'Hata bendeydi sevgilim,sevmemeliydim seni,ne de senin beni sevmeni. Baştan dizginlemeliydim  gönlümü isterken seni ve sevgini. Fikrinle bula...', ARRAY['Türk Edebiyatı','Şiir','Semiha Aslan']::text[], 8.5, '{"poet":"Semiha Aslan","poet_slug":"semiha-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/of-deli-gonul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecer Sandım', 'gecer-sandim-semiha-aslan-xu4tr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevmekten korkma,sev diyen kalbimin sesine kandım

 yatağimda fikrinle boğuşurken senle rüyalara daldım,

 kavusamayınca rüyalarımda sana, kaybetmenin korkusuyla uyandım,

 duyunca odamda yankılanan sesini, güne seninle başladım.                                                                                                                          

 Görmezse göz, gül cemâlini sevgim biter unuturum sandim,

 sevmeyince gönül seni, geçer gider izi bile kalmaz sandım,yanıldım.

 Atmadım,toplayıp kenara koydum sana ait herşeyi, gün gelir lazım olur sandım.

 Duyamadiğimda o şen sesini, kendimi hiç duymuyormuş saydım,

 hissedemeyince bedenim, teninin sıcaklığını,kanim çekildi  ve öldüm sandım! !', 'Sevmekten korkma,sev diyen kalbimin sesine kandım  yatağimda fikrinle boğuşurken senle rüyalara daldım,  kavusamayınca rüyalarımda sana, kay...', ARRAY['Türk Edebiyatı','Şiir','Semiha Aslan']::text[], 8.5, '{"poet":"Semiha Aslan","poet_slug":"semiha-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gecer-sandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Çocukların Çığlıkları', 'olu-cocuklarin-cigliklari-ayhan-altay-i2454', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Önce küçülen ekmekler,

Yok olurken tümüyle; 

Çoğalır gürültüleri bombaların,

Yoksul kulaklarında.

Uzaklardan

Çok uzaklardan gelen uçaklar,

Yırtar gökyüzünü, yeryüzü kanar.

Tarakaları makineli tüfeklerin,

Sağır yüreklerden, kör akıllardan,

Duyumsanmayan  çığlıklar atar.

Şimdi; 

Bir yerlerde birileri,

Dizüstü tuşlarında elleri; 

Kabaran sayılara bakmaktadır.

Ölü sayısı kadar kazanç, 

Yaralı sayısı kadar mutluluk

Saymaktadır.

Sessizdir,

Gözyaşları ölü çocukların.', 'Önce küçülen ekmekler, Yok olurken tümüyle;  Çoğalır gürültüleri bombaların, Yoksul kulaklarında. Uzaklardan Çok uzaklardan gelen uçaklar, Y...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Altay']::text[], 8.5, '{"poet":"Ayhan Altay","poet_slug":"ayhan-altay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/olu-cocuklarin-cigliklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Akşamları', 'eylul-aksamlari-ayhan-altay-epixf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eylül akşamları düşer anılarımdan,

Eylül akşamları dolu hüznüme.

O bıçak sırtı eylül akşamlarıdır,

İçimde donmuş bir bulut oluşturan

Sevdamdır, eylül akşamlarında

Umuduma harman edip sardığım.

Yılkı tayı prangası Eylül akşamları,

Kızıllıkları komaz ufuk ötelerine.

Şimdi eylül akşamlarında yüreğim

Yangına direnen kitap; 

Kızıl alev içre bir kızıl düş; 

Karadeniz yağmurunda, 

Avgarda bıldırcındır.

Sorma eylül akşamlarında neden üşür,

Zulamda sakladığım sevda.', 'Eylül akşamları düşer anılarımdan, Eylül akşamları dolu hüznüme. O bıçak sırtı eylül akşamlarıdır, İçimde donmuş bir bulut oluşturan Sevdamd...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Altay']::text[], 8.5, '{"poet":"Ayhan Altay","poet_slug":"ayhan-altay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/eylul-aksamlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerdir Güzel Olan', 'duslerdir-guzel-olan-ayhan-altay-r05su', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bırak bırak

bırakma beni umarsızlığıma

oysa düşlerdir güzel olan

ve sevdiren yaşamı

tüm bir dünyayı 

yetmez evreni isteyen düşler

ve paylaşmayı dostlarla

ve hatta düşmanla

tekili değil

çoğulu yaşadığında güncesi tarihin

orda olmaktır yaşamak

o zaman bir başka olur sevdalar

Bedrettin’ce  yücelir insan

gönenir yeniden yaratıldığında doğa

bir ulu çınar olur serinliği ellerinde

düşlerdir güzel olan', 'bırak bırak bırakma beni umarsızlığıma oysa düşlerdir güzel olan ve sevdiren yaşamı tüm bir dünyayı  yetmez evreni isteyen düşler ve paylaşm...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Altay']::text[], 8.5, '{"poet":"Ayhan Altay","poet_slug":"ayhan-altay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/duslerdir-guzel-olan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutun Öfkesi', 'bulutun-ofkesi-ayhan-altay-vb4e9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öfke sağdım buluttan

Umut yaşları bu yağan

Abanır üstüme kararan karabasan

Dağılır Karadeniz üstünde kara bulutlar

Günışığı yıldızıdır parlayan kızıl akşamda

Gel artık gönlümün kavşağındaki kavga

Öfke sağdım buluttan

Dranaz kuytusunda taş yosunları

Ağır ağır yontarken yaşamı

İki tavşan oynaşır yüreğinde korkusu 

Upuzun uzamış köknarın gölgesinde

yinelenen bir ölümdür yeşeren

Taş erir, yosun çürür

Yaşam evrenselleşir

Yağmurun ıslattığı denizde 

Dönerken ince burnu

Balıkçı takaları

Amazon şarkılarıdır duyulan

Eşlikçi yunuslardan

Gel artık gönlümün kavşağındaki kavga

Öfke sağdım buluttan', 'Öfke sağdım buluttan Umut yaşları bu yağan Abanır üstüme kararan karabasan Dağılır Karadeniz üstünde kara bulutlar Günışığı yıldızıdır parla...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Altay']::text[], 8.5, '{"poet":"Ayhan Altay","poet_slug":"ayhan-altay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bulutun-ofkesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut Ki', 'tut-ki-ayhan-altay-h15fq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yaşıyorum dersen

direteceksin

yer olmayacak umarsızlığa

güzele yatacak düşlerin

seviyorum dersen

bulut olacaksın

yüreğinde taşıyacaksın beynini

nedensiz nedenlerin olacak

aklım var dersen

düşüneceksin

aldırmayacaksın çakır dikenlere

sevdalanacaksın 

tut ki insanım dersen

utanacaksın

hiçbir silah yapmaz bileceksin

insanın insana yaptığını', 'yaşıyorum dersen direteceksin yer olmayacak umarsızlığa güzele yatacak düşlerin seviyorum dersen bulut olacaksın yüreğinde taşıyacaksın beyn...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Altay']::text[], 8.5, '{"poet":"Ayhan Altay","poet_slug":"ayhan-altay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tut-ki-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanlar Ayrılıktan Yanadır', 'canlar-ayriliktan-yanadir-fatih-kagan-yucel-xba5h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gidip de dönmemek umrumda mı can

Hakkını helal demezdim yoksa

Dönüp de bulmamak asıl korkutan 

Yık yolları sana çıkmayacaksa 

Dönüşlerim ancak sanadır anne

Kucağından payım hasretmiş meğer

Her ne yöne baksam bir ucu gurbet

Kalmaları mihnet sarmışsa eğer

Ben gitmesini de bilirim elbet

Çanlar ayrılıktan yanadır anne

Gözlerin kızarmış bakışın dalgın

Bir teselli gelsin duandan bana

Yıldırıma eş olmalı feryadın

Bir türkü yak susma Allah aşkına 

Sükutun ruhumu kanatır anne

Evlatlar sürgünmüş gemiler yanmış

Mahşereymiş vuslat  boşver aldırma

Ne bağırlar var ki hayalle dinmiş

Gün geçer yıl geçer geçer aldırma

Bir ana her zaman anadır anne

kasım 2004 / Konya', 'Gidip de dönmemek umrumda mı can Hakkını helal demezdim yoksa Dönüp de bulmamak asıl korkutan  Yık yolları sana çıkmayacaksa  Dönüşlerim anc...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kağan Yücel']::text[], 8.5, '{"poet":"Fatih Kağan Yücel","poet_slug":"fatih-kagan-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/canlar-ayriliktan-yanadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-husnu-celebi-t2qmx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine bir hazan mevsimi sonundayız

Kimi zaman bir deli rüzgar esişi

Kimi zaman ağaçların savruluşu

Kimi zaman kopan yaprağın hışırtısı

Kimi zaman düşen yağmur tanesi

Kulaklarımda bilmediğim tuhaf bir ses

Karışıyor birbirine beynimin içinde 

Geçmişe dönüyorum birden

Hani seni ilk tanıdığım günlere

Bir mevsim sonuydu zaman

Tatlı bir rüzgar esintisi

Taşımıştı seni bana

Ağaçların savruluşuna benzetmiştim

Saçlarındaki ahenkli dansı

Dalından kopan yapraklardan

Aldım senden gelen haberleri

Mutlu olduğumda oldu

Mutsuzluklarımda geçen zamanda

Kimi defa düşen yağmur tanesi

Koca bir kaya oldu çöktü başıma

Bilirsin sonbaharı çok severim

Seni tanıdığım mevsimde sonbahar

Ve yine bir mevsim sonundayız

Sonbahar elini sallamak üzere kışa

Devir teslim için 

Bilmediğim tuhaf sesler arasında

Sıcaklığın içimi ısıtmakta

Kışa hazırlanıyorum şimdilerde

Korkmuyorum artık eskisi gibi kıştan

Üşütemiyor artık eskisi gibi

Mevsim sonbaharı terk etmekte

Rüzgarın esintisinde sıcaklığın

Ağaçların savruluşunda sen

Yaprağın düşüşünde sesin

Düşen yağmur tanelerinde sadeliğin

Ve nihayet

Her sonun bir başlangıcı gibi

Yine bir mevsim son

Yeni bir başlangıç

Kalbimde, gönlümde, tüm benliğimde

Yine sen, yine sevdan……..

19.11.2004  /  İstanbul', 'Yine bir hazan mevsimi sonundayız Kimi zaman bir deli rüzgar esişi Kimi zaman ağaçların savruluşu Kimi zaman kopan yaprağın hışırtısı Kimi z...', ARRAY['Türk Edebiyatı','Şiir','Hüsnü Çelebi']::text[], 8.5, '{"poet":"Hüsnü Çelebi","poet_slug":"husnu-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sonbahar-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SEN (Akrostiş)', 'sen-akrostis-muzaffer-erdogan-wr7f1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'S evginle akıtsam göz yaşlarımı dudaklarınla silecekmisin

E fkarından dökülse o kumral saçların,saçlarından bir tel verecekmisin

N ice zahmetler çektim aşkın elinden gidiyorum sende benimle gelecekmisin

                                                                                          

                                                                                                             VEFASIZ', 'S evginle akıtsam göz yaşlarımı dudaklarınla silecekmisin E fkarından dökülse o kumral saçların,saçlarından bir tel verecekmisin N ice zahme...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Erdoğan']::text[], 8.5, '{"poet":"Muzaffer Erdoğan","poet_slug":"muzaffer-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Binbir Kişi', 'binbir-kisi-mustafa-toga-7dg7t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kasabada bir kişi vardι 

Halkım, haklarım diye bağıran

Sarışın, eşki delisi

Gözü pek, atılğan, cesur.

Din, iman, kitap dümdüz giden.

Önüne gelen her şeyi kırıp geçiren.

Geçen gün onu gördüm, 

Gençlik parkında dolaşırken.

Kardeşim dedi, sarıldι bana

Yüzü hüzünlüydü, gözleri ağlamaklι 

Gülümsedi, bakışlarι sevgi doluydu.

Kitaplarι koltuğunun altında

Başladι anlatmaya; 

Gelince Ankara’ya 

Dolaştım başıboş sokaklarι ,

Gördüm örgütleri, gizli hücreleri 

Ve de

Üniversite kapısından girince öğrendim

Doğru ve gerçekleri.

Şimdi yanıyorum boşa geçirdiğim yıllara

Koşuyorum  arayι kapatmak için

Okuyorum, öğreniyorum

Kafam ile güç ile

O zaman bir idim 

Şimdi binbir kişi.

www.togamedya.tr.gg

M.Toga / Haziran 1977 - ANKARA

GÜNÜN SÖZÜ; Seni sen değil el övsün.

Not: Bu şiirimi Tayyar Nemutlu’ya ithaf ediyorum.', 'Kasabada bir kişi vardι  Halkım, haklarım diye bağıran Sarışın, eşki delisi Gözü pek, atılğan, cesur. Din, iman, kitap dümdüz giden. Önüne g...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Toga']::text[], 8.5, '{"poet":"Mustafa Toga","poet_slug":"mustafa-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/binbir-kisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kime ne', 'kime-ne-nurcan-yildirim-p8bes', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Coştum işte

Deniz benim denizim değil mi kime ne 

Yine deli buhranlar içindeyim

Sitem karlığım senden önce kendime 

Koptu fırtına alabora oldum 

İçim toz duman 

Denizimin girdaplarında mı boğuldum 

Öldün mü, kaldın mı, nicesin kim bilir

En büyük sarsıntılar oldu 

Taş taş üstünde kalmadı 

İçimde toz duman

İçim enkaz

Sen hangi yıkıntılar arasındasın bilmiyorum 

Ağır yararlı olmalısın 

İniltilerini işitiyorum uzaktan 

Kıyamet mi bilmiyorum 

Koptu yine içimden o en kocamandan daha kocaman 

İçim toz duman 

İçim enkaz 

Sen ağır yaralıydın 

Sesin soluğun kesildi 

Kaldın mı  öldün mü yoksa çoktan 

İçimin hangi bilinmezliğinde kaldın 

Sitem karlığım senden önce kendime 

Coştum işte 

Deniz benim denizim değil mi kime ne 

Gel-gitlerle vurdum kayalıklara 

Öyle güçlü olurum ki o kocaman kayaları çakıl taşı yaparım

Derinime çöker küçük çakıl taşları 

Dikenli güller gibi kanatırlar beni 

Duruldum işte 

Deniz benim denizim değil mi kime ne 

Duruldum 

Duruldukça olgunlaştım

Öylesine saydam 

Öyle çok yalın 

Çırılçıplak bir ben 

Üstümde sadece gecenin mavisi 

Masmavi bir kız oldum 

İçimde bir filiz 

Yine senin için yeşerme çabasında 

İşte böyle

Seni kendi içimde 

Seni kendi denizinde 

Öldürüp öldürüp dirilttim 

Duruldum işte 

Deniz benim denizim değil mi kime ne 

Öylesine duru 

Öylesine çocuk 

Günahsız bir ben

İçimde bir filiz 

Yine senin için yeşerme çabasında 

Bende bir sessizlik 

Denizim mavi çarşaf gibi gecenin ortasında 

Ne bir kıpırtı var 

Nede küçük dalgalar 

Seni bir tek seni yaşarım engin denizlerde 

Kah coşan deli dalgalarımla yalar dururum kayaları 

Kah koca bir kayanın kıyısına vurur kalırım 

Titrek 

Korkak 

O koca kayalara yosun yosun yazarım seni 

İşte şimdi ben oldum 

Baştan başta çırılçıplak 

Peki ya sen beni gibi sınırsız oldun mu

Böyle saydam, yalın, böylesine gerçek 

Ne bileyim sende beni öldürdün mü içinde 

Beni yaşattın mı denizinde

Duruldum işte 

Deniz benim denizim değil mi kime ne 

Sessiz bekliyorum 

İkinci ve son olmayan fırtına 

Fırtınadan önceki sessizlik ya da....

Ne bileyim...

Of...

Duruldum 

Duruldukça olgunlaştım 

Kime hem bundan 

Sana ne be yaşıyorum işte 

Senide yaşatıyorum denizimde 

Kime ne lan bundan 

Sana ne be, sana ne 

Sana mı soracaktım 

Deniz benim denizim değil mi kime ne 

Tarih: 17/06/2000', 'Coştum işte Deniz benim denizim değil mi kime ne  Yine deli buhranlar içindeyim Sitem karlığım senden önce kendime  Koptu fırtına alabora ol...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Yıldırım']::text[], 8.5, '{"poet":"Nurcan Yıldırım","poet_slug":"nurcan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":85,"source_url":"https://www.antoloji.com/kime-ne-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BENi NEREYE KOYUYORSUN...?', 'beni-nereye-koyuyorsun-baki-son-zxlfs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni nereye koyuyorsun söyle? 

Neresinde yaşıyorum yüreğinin? 

Var mıyım senin için, 

Gecelerinin masalsı düşü ben miyim 

Yoksa kendin misin? ... 

Beni sığdırabiliyor musun içine? 

Hangi yana baksam tünel; 

Sonsuz uçurumlar gibi,dipsiz bir kuyu 

Hani içinin aynasıdır ya sevdiğin, 

Benim aynamda karanlık aksetmekte... 

Öyleyse anlarım ki ben de yokum sen de. 

Beni nerede yaşatıyorsun söyle? 

Cennetin miyim senin, 

Amber kokulu bahçelerinde gezindiğin? 

Yoksa kaybolduğun kör kuyun mu, 

Dehliz yalnızlıklarını yitirdiğin? 

Artık anlamsız geliyor tüm sorular 

Yanıtlarını bir gün verecek olsan bile 

Ben de bir şeyler buram buram, 

Ben de çok şey ılık ılık, 

Ben de sen acıtarak, kanayarak, 

Eksiliyor...! ! ! 

Ben seni bunca zamana ağırlayamazken ruhumda 

Aitsizliğim çaresiz çoğalıyor... 

Ve görüyorum aynada yüzü silinmiş suretimi 

Sen bende herşeysin belki ama, 

Ben sende yitiyorum için için... 

Beni nerelerde arıyorsun öyle? 

Yüreğine sor bir de 

Mutlaka cevabı gelecektir sessizliğinin..! 

'''' Bu Aşk ın Katili Sensin...! ! ! ''''', 'Beni nereye koyuyorsun söyle?  Neresinde yaşıyorum yüreğinin?  Var mıyım senin için,  Gecelerinin masalsı düşü ben miyim  Yoksa kendin misin...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/beni-nereye-koyuyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günlük', 'gunluk-selvi-celik-aoi4g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi son sayfan gözlerimin icine bakiyor.

Biliyormusun ömrümü paylaştim seninle,

Yillarimi kiskanmadim seninle paylastim.

Mutluluklarimi sana anlattim.

Acilarimi sana döktüm.

Belki her kanadina mühür oldu gözyaşlarim.

Ve bugün sende kendimi bastan sona  okurken.

Bu benmiyim benmi yaşadim,

Diye kendimi sorguya çektigimde,

Hiç bu kadar isyanla,gururu bir arada yasamadim.

Onca gecen zamani bir çirpita  film şeridi gibi gözlerimin önünden gecirirken yeniden yaşamak,

bu kadarmi agir bu kadar mi sanci verecekti.

şimdi keske,keske senin yerinde olabilseydim de

benide bir okuyan olsa demeden ali koyamadim kendimi.

Evet.....

Beynim durdu.

Son sayfan kala kaldi oyle.

Ísterdimki güzel bir veda ile.

Ayrilik olsun aramizda.

Onu becerecek kadar ne cesaretim nede gücüm kaldi.

Son sayfan bos kalsin.

bir rafta tozlanip kalma.

Beni unuttuklari gibi,senide unutmasinlar.

 yeniden yeniden okusunlar.

Son sayfan kalsin günlügüm.....

Yeniden okusunlar....

.', 'Şimdi son sayfan gözlerimin icine bakiyor. Biliyormusun ömrümü paylaştim seninle, Yillarimi kiskanmadim seninle paylastim. Mutluluklarimi sa...', ARRAY['Türk Edebiyatı','Şiir','Selvi Çelik']::text[], 8.5, '{"poet":"Selvi Çelik","poet_slug":"selvi-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gunluk-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdeyim?', 'nerdeyim-mustafa-sekerci-cqhsd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dumansız yangınlardayım

Yandıkça donuyor

Dondukça yanıyorum

Bırakmıyor yakamı yalanlar dolu gerçek

Bir gün 

Beni bu yarasız kanamalar öldürecek', 'Dumansız yangınlardayım Yandıkça donuyor Dondukça yanıyorum Bırakmıyor yakamı yalanlar dolu gerçek Bir gün  Beni bu yarasız kanamalar öldüre...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şekerci']::text[], 8.5, '{"poet":"Mustafa Şekerci","poet_slug":"mustafa-sekerci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nerdeyim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahin gözlüm', 'sahin-gozlum-serdal-gocmen-rlok9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey şu dağlarda savaşan şahin gözlüm

kirpiklerin  tel  tel olmuş gelsene

sana sıkılan kurşun benim bağrımı deler

umutların deniz olmuş gelsene......', 'Ey şu dağlarda savaşan şahin gözlüm kirpiklerin  tel  tel olmuş gelsene sana sıkılan kurşun benim bağrımı deler umutların deniz olmuş gelsen...', ARRAY['Türk Edebiyatı','Şiir','Serdal Göçmen']::text[], 8.5, '{"poet":"Serdal Göçmen","poet_slug":"serdal-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sahin-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Oyunları', 'ask-oyunlari-necat-ozturk-h3ob4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüzyıllar da geçse değişmiyor aşkın kuralları,

Aşk adı altında oynanan oyunlar değişmiyor.

Seni seviyorumlar, sana tapıyorumlar, senin için ölürümler.

Neden sevmenin nadideliğine vurulup yalnızca sevmiyorlar.

Sevmiyorlar…

Sevmiyor...

Sevmiyo…

Sev...', 'Yüzyıllar da geçse değişmiyor aşkın kuralları, Aşk adı altında oynanan oyunlar değişmiyor. Seni seviyorumlar, sana tapıyorumlar, senin için ...', ARRAY['Türk Edebiyatı','Şiir','Necat Öztürk']::text[], 8.5, '{"poet":"Necat Öztürk","poet_slug":"necat-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-oyunlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Portre', 'portre-sair-astor-l51mh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne söylemek istiyorsan,

Kalbime söyle.

O beni hiç dinlemedi çünkü

Mantıklı düşüncelerimden bağımsız 

Çalışır O.

Dur dedim mi durmaz ki O,

Çalış dediğimde de çalışmaz ki,

O hep çalışıyor zaten.

Onun için hayatta çerçeveler yoktur

Hayatı kare kare içine sığdıracağı

Yalnızca masum bir portresi vardır

O portre de sensindir zaten....', 'Ne söylemek istiyorsan, Kalbime söyle. O beni hiç dinlemedi çünkü Mantıklı düşüncelerimden bağımsız  Çalışır O. Dur dedim mi durmaz ki O, Ça...', ARRAY['Türk Edebiyatı','Şiir','Şair Astor']::text[], 8.5, '{"poet":"Şair Astor","poet_slug":"sair-astor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/portre-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın Nizamiye Kapısı', 'hayatin-nizamiye-kapisi-melih-coskun-id0ni', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayatın nizamiye kapısından 

Çok oldu geçeli, 

Kendimi bildim bileli 

Her birimiz

İkinci sınıf bir dünyada 

İtaatkar bir sıra neferi 

Konuşmak yasak bize, 

Türkü söylemek

Veya ıslıkla çalmak çok sevdiğin bir melodiyi 

Hazır ol! ..

İkinci bir emre kadar,

Rahat etmek 

Sadece özgür insanın işi... 

Emrindedir 

Gıcırdayan postal sesleri arasında 

Şeffaf zarfları 

Siyah elbiseli adamlarıyla 

Teksas tipi demokrasi... 

Kalın kitapların başlıklarını bile okumak yasak bize 

Sevdiğimiz şiirleri ezberlemek 

Düşünmekse ölümcül bir günah

Hayatın nizamiye kapısından 

Çok oldu geçeli

Kendimi bildim bileli 

Her birimiz 

İkinci sınıf bir dünyada 

İtaatkar bir sıra neferi...

(Bir Askerin Kaleminden) 

J. Komando Asteğmen 

Melih COŞKUN', 'Hayatın nizamiye kapısından  Çok oldu geçeli,  Kendimi bildim bileli  Her birimiz İkinci sınıf bir dünyada  İtaatkar bir sıra neferi  Konuşm...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hayatin-nizamiye-kapisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşimiz', 'i-simiz-kadir-soyturk-d6ykp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bizim gibi kulların işi  ah ile vahdır

''Güçlü, kuvvetli olan; rızık  veren Allah''dır.''', 'Bizim gibi kulların işi  ah ile vahdır ''Güçlü, kuvvetli olan; rızık  veren Allah''dır.''...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/isimiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Saati', 'ayrilik-saati-ali-fikri-karadeniz-iu6ws', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi…

Evet şimdi ayrılık saati

Belki bir silahın son mermisi

Belki de son bir haykırışın seli

Yüreğimdeki son yağmur tanesi

Şimdi; 

Evet şimdi ayrılık saati..! 

Son kez gün batımını seyrediyorum

Güneş, son kez doğduğu gibi batıyor

Son kez dalgalar boğuyor beni

Ve son kez gözlerinde batıyorum

Şimdi; 

Evet şimdi ayrılık saati..! 

Yıldızlar son kez parlıyor gök yüzünde

Son kez Kutup Yıldızı ayyukta

Ve son yıldızın kayışı gibi

Şimdi; 

Evet şimdi ayrılık saati..! 

Son yağmurlar var gözlerimde

Son kez gün açıyor gönlümde

Son – baharın tek gülü gibi

Şimdi; 

Evet şimdi ayrılık saati..! 

Son sigaranın dumanı işliyor ciğerime

Son kez yudumluyorum acılarımı

Son kez  hayalinle dans ediyorum

Şimdi; 

Evet şimdi ayrılık saati..! 

Son kez nereye baksam karşımdasın

Son kez ay Da

Son kez su Da

Son kez canım Da

Son kez kanım Da

Son kez dudağım Da

Son nefes alışım Da

Ve son kez kalbimin atışın Da

Şimdi; 

Evet şimdi ayrılık saati..! 

Son kez secdemdesin

Son kez dua’mda

Son kez Rabbime yakarışlarımda

Son kez uykusuzluğumda

Ve ayrılmamak üzere son kez rüyalarımda

Şimdi; 

Evet şimdi ayrılık saati..! 

Son gemi kalkacak bu limandan

Beklenen yolcusuyla birlikte

Son şiir’imin mısralarında ıslanacaksın

Ve son kez aşkıma şarkılar söyliyeceğim

Şimdi; 

Evet şimdi ayrılık saati..! 

Birazdan son ışığın fitili de çekilecek

Son kez karanlığa bürünecek dünyam

Son umut ışığının mumu sönecek

Son susuzluk gibi Sonsuzluk

Adımımda gölgem gibi gelecek

“Şimdi” diyecek

Evet şimdi ayrılık saati..! 

17/11/2004', 'Şimdi… Evet şimdi ayrılık saati Belki bir silahın son mermisi Belki de son bir haykırışın seli Yüreğimdeki son yağmur tanesi Şimdi;  Evet şi...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/ayrilik-saati-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırçiçeğim.', 'kircicegim-hayrettin-orak-0lhg6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üzerimde sensizliğin dondurucu soğuğu,

Titrek ellerimle resmini tutuyorum,

Sanki gülüyordun haykırıyordun bana

İçime çocuksu bir sevinç doğuyor,

Seviniyordum Kırçiçeğim.

Ama yalnızlığının nahoş kokusu üzerime sinmiş,

Yokluğunun acısıyla yüreğim cayır cayır yanıyor,

Bir umut ışığı arıyor, yüreğimin ateşiyle ısınıyorum,

Seni sevdiğimi sabahçı kuşlara fısıldıyorum,

İçime çocuksu bir mutluluk doğuyor,

Seni bekliyorum Kırçiçeğim.

Güneşim doğmamış her taraf zifiri karanlık zindan,

Bir boşluğa itiliyorum sanki, sen yanımda olmadan,

O dayanılmaz eziklik acısı kalbimi parçalıyor inan,

Kanımı donduruyor yalnızlığının hırçın ürpertisi,

Sensizliğe dayanılmıyor, boğuluyorum,

Gel ne olur gel artık Kırçiçeğim..........! 

19.11.2004', 'Üzerimde sensizliğin dondurucu soğuğu, Titrek ellerimle resmini tutuyorum, Sanki gülüyordun haykırıyordun bana İçime çocuksu bir sevinç doğu...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kircicegim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm - II', 'gulum-ii-ali-fikri-karadeniz-zu7ff', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevda bir masalmış Gülüm; 

Kaf dağının ardında

Gönüllerde güller açar

Aşkın aleviyle yanar

Sonra solarmış

Sakın ağlama Gülüm

Sensin ölümüm…! 

Sevda bir masalmış Gülüm; 

Bir yaralı yürek bırakır ardında

Yağmurlar yağar gönlümden

Ve maviliğinde boğar Gülüm

Sensin ölümüm…! 

Sevda bir masalmış Gülüm; 

Kuşların kanatlarında

Alır götürürmüş yıldızlara

Karanlıkla aydınlanırmış da

Sonra Sonsuzluğa bırakırmış Gülüm

Sensin ölümüm…! 

Sevda bir masalmış Gülüm; 

Kalpler parçalanır

Düşer gözlerimden alev alev

Yoo.. Yoo bunlar göz yaşları değil Gülüm

Sensin ölümüm…! 

Sevda bir masalmış Gülüm; 

Rüzgarlarda savrulan

Fırtınalar toprak eler

Kayalar çıkarmış ardından

Sonra bir sevda başlarmış 

Rüzgar kayayı ufalarmış Gülüm

Sensin ölümüm…! 

Sevda bir masalmış Gülüm; 

“Cennet mi, Cehennem mi” diyorum

Buna ben karar veremiyorum

Zaten karar veremem de aslında

Yaradan’ımdan af diliyorum

Bir tek; 

Bir tek Senin Sevginden “aslaaa”

Sana Tapmışım Gülüm

Sensin ölümüm…! 

                                                                       11/11/2004', 'Sevda bir masalmış Gülüm;  Kaf dağının ardında Gönüllerde güller açar Aşkın aleviyle yanar Sonra solarmış Sakın ağlama Gülüm Sensin ölümüm…!...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/gulum-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Sevda', 'kara-sevda-cem-han-non57', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geçti günler,her gün aşkınla doldu,

Sevgimiz bitmedi,heyecanımız hep oldu.

Kollarında mutlluğu yakaladım,

Sensiz geçen günlerime hep yandım.

Her gün seni çok,daha çok,en çok istiyorum,

Yokluğunla yanıyor,kavruluyor,kıvranıyorum.

Niçin sana daima açım? 

Aşkına ömrümün sonuna kadar muhtacım.

Aç gönül kapını bana,yerleşeyim,

Duygularında çiçek açıp yeşereyim.', 'Geçti günler,her gün aşkınla doldu, Sevgimiz bitmedi,heyecanımız hep oldu. Kollarında mutlluğu yakaladım, Sensiz geçen günlerime hep yandım....', ARRAY['Türk Edebiyatı','Şiir','Cem Han']::text[], 8.5, '{"poet":"Cem Han","poet_slug":"cem-han","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kara-sevda-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Diyorduk Biz', 'biz-diyorduk-biz-ali-fikri-karadeniz-j1k22', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biz diyorduk Biz

Evleniriz…! 

Herkesten farklıydık biz; 

Bir sevdayı körükleyip

Alev alev yanmıştık biz…

Belki birlikte değiliz

Belki dibine düşmüş mum iziyiz

Hasretin rüzgarı

Özlemin ağıtlarıydık biz

Şarkılardaydık biz

Namelerde; 

Şiirlerin kıtaları

Yağmurların son damlacıkları

Ve gökkuşağıydık biz

Mutluluklarda doğan

Ölümüne severdik biz

Güllerin çiğ tanesi

Manolyaların beyazlığı

Mutluluğun kokusu hanımeli gibiyiz.

Yuvamızın sarmaşığı

Yaşamın baharıydık biz…

Biz’dik Biz

Denizlerin yakamozu

Göklerin kanatsız melekleriyiz

Her gün sevgi ekeriz

Biz göz gözeyiz

Diz dizeyiz

Biz diyorduk Biz

Evleniriz…! 

Biz; Masumduk biz

Bir bedenin gölgesiyiz

Bir çınarın dalları

Göllerin nilüferi 

Suların şarıltıları

Yıldızların parıltıları

Sevginin iki halkası

Parmağımıza geçiririz..

Biz diyorduk Biz; 

Evleniriz…! 

Şimdi yorgunuz biz

Ben malup

Sen galip

Hakikatın iziyiz biz

Gerçekten böyle miyiz? 

                                               07/11/2004

Ali Fikri Karadeniz', 'Biz diyorduk Biz Evleniriz…!  Herkesten farklıydık biz;  Bir sevdayı körükleyip Alev alev yanmıştık biz… Belki birlikte değiliz Belki dibine...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/biz-diyorduk-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım''dan Can Vereyim', 'canim-dan-can-vereyim-atil-kesmen-1rbd6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgini bir güneş gibi			

Usanmadan 			

Yıllarca taşıdım avuçlarımda			

Damladıkça, parmak aralarımdan					

Kalp seslerime			

Sen giriyordun her gün düşlerime			

Nasıl bir sevgi tufanına kapıldım			

Estikçe sana geliyorum			

Yüzüne bakmaya doyamıyorum			

Elini tutmak''mı

Tenine dokunmaya kıyamıyorum

Kalbimde saklıyorum

Gözlerimden sakınıyorum

Görmessem, yanıp yanıp harlıyorum

Ve gönlümden ağlıyorum

Hislerimden terliyorum

Sen

Benim vazgeçilmezimsin

Sana olan sevgimi 

Tanrı bana yazmış

Ben, Tanrı''ma nasıl karşı gelebilirimki

Söyle, nur yüzlüm bal gözlüm

Sevgi kutsaldır de

Seni cennet gibi seveyim

Melek''ler gibi senin etrafında döneyim

Sevgim uğruna

Sana 

Canım''dan can vereyim', 'Sevgini bir güneş gibi			 Usanmadan 			 Yıllarca taşıdım avuçlarımda			 Damladıkça, parmak aralarımdan					 Kalp seslerime			 Sen giriyordun...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/canim-dan-can-vereyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Çare.', 'ne-care-hayrettin-orak-1r4vs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öylesine, delice seni özledimki birtanem,

Duygularımı anlatmaya cesaretim yok,

Gözyaşlarımla hasretimi yazmaktan korkarım,

Yalnızlığımı, sana olan hasretimi, umutsuzca anlatsam, Ne çare.

Sensiz bu şehir artık bana dar geliyor,

Ruhumu esir etmiş hasretin bitmek bilmiyor,

Seni bekleyen, yolunu gözleyen gözlerim sabırsızlanıyor,

Hasretlik içinde yanan yüreğim acı çekiyor,

Mutsuzluğumu, isyanımı, feryadımı anlatsam, Ne çare.

Dışarıda bir ses duyuyorum, sanki bana gel diye sesleniyorsun,

Birden korku ile penceremin perdesini aralayıp baktığımda,

Evimin camına sabırsızca, ürkercesine çarpan söğüt ağacı,

Sanki hasretime, yalnızlığıma ses olmaya çalışıyor,

Yalnızlığımı, kimsesizliğimi, esaretimi anlatsam, Ne çare.

Uzak ufuklarda batan güneş, bitmeyen umudum oldu,

Her doğan güneş sevdiğim yar oldu,

Umutlarım bir gül misali sararıp soldu,

Bedenim hasretinle serhoş, berduş oldu,

Umutlarımın yalnızlığını, çaresizliğimi anlatsam Ne çare........! 

19.11.2004', 'Öylesine, delice seni özledimki birtanem, Duygularımı anlatmaya cesaretim yok, Gözyaşlarımla hasretimi yazmaktan korkarım, Yalnızlığımı, san...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-care-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rol', 'rol-baykal-kaanalp-n1mv8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yazılmamış bir role talibim

silinmiş izlerin repliğinden

bana bunu kim verir bilmiyorum

olması lazım üzerime kendiliğinden

unutulmuş suflörü silmiyorum', 'yazılmamış bir role talibim silinmiş izlerin repliğinden bana bunu kim verir bilmiyorum olması lazım üzerime kendiliğinden unutulmuş suflörü...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rol-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Unutma', 'beni-unutma-didem-esen-wi1ec', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün kar yağarsa tane tane 

İçin sıcacık, gözlerin güneş gibi

İçimde uçuşan kuşlarla, 

Beni hatırla, 

Ağaçlı tenha bir yolda yürürken

Ilık rüzgar değdiğinde tenine 

Sebepsiz dolarsa gözlerin

Kavgaları, sıkıntıları, 

Yaşanamamış yarınları ile

Beni hatırla, 

Karanlıkta, umutsuzluğunda, 

Yoklukla varlık arasında

İçin ürperdiğinde, 

Ispanaklı yumurtada, 

İçtiğin çayın bardağında, 

Beni hatırla.', 'Bir gün kar yağarsa tane tane  İçin sıcacık, gözlerin güneş gibi İçimde uçuşan kuşlarla,  Beni hatırla,  Ağaçlı tenha bir yolda yürürken Ilı...', ARRAY['Türk Edebiyatı','Şiir','Didem Esen']::text[], 8.5, '{"poet":"Didem Esen","poet_slug":"didem-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beni-unutma-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sicim', 'sicim-baykal-kaanalp-l6lr3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kendini görünmez sanıyor

kıpırdamasına izin vermezsen eğer

ölümsüzlüğüne inanıyor

kalbinden söküp atmazsan eğer

gelenekler dedi,üstümüze gelirler

atılmasalarda herkes tarafından sevilirler

kuru yapraklar dağılıyor

toplanıp gömülmezse eğer

yaralar bir bir kanıyor

dikişleri patlarsa eğer

bir sicim sakla,lazım olur

bağlamak gerekir,düşlerimi', 'kendini görünmez sanıyor kıpırdamasına izin vermezsen eğer ölümsüzlüğüne inanıyor kalbinden söküp atmazsan eğer gelenekler dedi,üstümüze gel...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sicim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylece', 'oylece-baykal-kaanalp-h5nn9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'nasıl girdiyse 

öylece çıkıverdi

hayatımızdan

yanıp sönen 

sarı ışık gibi

üzerimize hiç

bulaşmamış gibi

kokusu yazgılarımıza

sinmemiş gibi

nasıl girdiyse

öyle çıkıverdi

gönlümüzden

yakıp kavuran

aşk odu gibi

içimizi hiç

yakmamış gibi

ıslaklığı üstümüze

hiç sinmemiş gibi', 'nasıl girdiyse  öylece çıkıverdi hayatımızdan yanıp sönen  sarı ışık gibi üzerimize hiç bulaşmamış gibi kokusu yazgılarımıza sinmemiş gibi n...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/oylece-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Değilmisin Sen', 'sen-degilmisin-sen-ali-riza-unal-nm0x5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşık ile saz çalan, ferhat ile dağ delen

Sen değil misin Sen

Yunus ile meşk edip, mecnun ile çöl gezen

Sen değilmisin Sen

Hem dövüpte hem seven, Ali ile zikreden', 'Aşık ile saz çalan, ferhat ile dağ delen Sen değil misin Sen Yunus ile meşk edip, mecnun ile çöl gezen Sen değilmisin Sen Hem dövüpte hem se...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-degilmisin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biçilmiş Kaftan', 'bicilmis-kaftan-baykal-kaanalp-4ao2f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bazen uçarı gecelerimi

yüzükoyun yere yatırıp

güçlü kuvvetli gündüzlerime

dövdüresim gelir

ama olmuyor işte

çok seviyorum karayı

karanlığı,içine sakladıklarıyla

birlikte olduklarıyla

uzun süre bütünleşsede

sabırsız dokularla

yine de vazgeçemiyorum

gecelerimden bana 

yar olan tabiatıma

biçilmiş kaftan

yerli basmadan', 'bazen uçarı gecelerimi yüzükoyun yere yatırıp güçlü kuvvetli gündüzlerime dövdüresim gelir ama olmuyor işte çok seviyorum karayı karanlığı,i...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bicilmis-kaftan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğduk Çıplak Gidiyoruz Çırılçıplak', 'dogduk-ciplak-gidiyoruz-cirilciplak-salih-ozalasan-nbix6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşünmedik bu Dünya fani

Ahrette ne olur ruhumuzun hali

Dolaştık her gece meyhane; dostumuz saki

Etmedik ibadet; ırakta kaldı bize cami

Günümüzü gün eyledik zevki safa ile

Canımız yanmasa getirmedik tanrıyı dile

Gün oldu kattık her işimize bin hile

Düşünmedik hesabını vereceğimizi mizan ile

Hırs ile diktik bina; zevk için ettik zina

Korkumuz olmadı sahip olunca bir hana

Dönüp şöyle bir bakmadık kabristana

Mekanımız orasıydı üfürene dek İsrafil sûra

Paramızla övündük, tabamızla sevindik

Etrafımız doldu sahte, tanıdık bildik

Ahrete  bir yükümüz olmadan can verdik

Dünya nimetleri mezeydi; bizde yılan çıyana meze oluverdik

Şükretmedik bir gün olsun bizi yaratana

Sandık ki kişi Dünya’da erer muradına

Hikaye niyetine baktık kabir azabına

Kıldan ince kılıçtan keskin Sırat’ına

Bazımız şirke düştü inadına

El etek öpenleri gördüğünde etrafında

Ne bir yardım; ne dua etmedik ihtiyaç duyana

Bilmedik giderken onlar yüktü insana

Geldiğimiz gibi gidişimiz çırılçıplak

Fani bedenimiz toprak ile oldu helâk

Ahret yükümüz ruhlarımıza elbise

Yükümüz yoksa gelişimiz çıplak; gidişimiz çırılçıplak

Y.Tarihi 19-11-04

Salih ÖZALAŞAN', 'Düşünmedik bu Dünya fani Ahrette ne olur ruhumuzun hali Dolaştık her gece meyhane; dostumuz saki Etmedik ibadet; ırakta kaldı bize cami Günü...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/dogduk-ciplak-gidiyoruz-cirilciplak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küstüm çiçeği gibi', 'kustum-cicegi-gibi-gencay-coskun-3ybdk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kapalı bir içtim 

Kendi içlerime doğru 

Günlerimin sayısı çoğaldıkça

Bir başka bakıyordum hayata

Sayılardan bir dünya 

Çıkışı bulabilene aşk olsun

İçime gittikçe 

Kayboluyordum

Çok eski bir uygarlığın 

Alfabesini çözer gibi 

Bakıyordum 

Kendi iç duvar resimlerime

Duvarlarımda 

Güller, Kalpler, Güneş çiziliydi.

Tam ortasında kocaman “bir” vardı. 

Sonrası karanlıktı 

Işık korkarak gelebiliyordu 

O da bin bir naz ediyordu

Kapalı bir içtim

Susuzluğum hiç geçmedi 

Gittikçe daha karanlıktı anılarım 

Kaybolan parçalarım

Tavan arası gibi 

İç arası bir yerlere saklanmıştı 

Yılların tortusu vardı üstüne 

Hangi savaşın 

İzlerini taşıyorlardı kim bilir

Kaç kez kan deymişti üstlerine 

Bu kadar kayıp parçamı 

Ne zaman buralara saklamıştım 

Yada kendileri saklanmıştı 

Kayıp düşler memleketin kapıları

İçimin kuytularında 

Kırmızı gölgelerin içindeydi 

İçim gidiyordu 

Ben gidiyordum 

Bir şeylerim siliniyordu 

Ben önde gitme derdinde 

Kendimden içimden kaçıyordum

Kendi iç sularımdakiler

Yitirilmişliklerin belgeleriydi

Hüzünler, küskünlükler,

Ah keşke yapsaydım dediklerim

Saymaya kalksam ki saymam

Saymadan saklarım onları 

Anlaşılmazlık çöküyordu üstüme 

Zamanda kayıp bir birimde

Gariban oluyordum

Gün gittikçe 

Ben iyicene kapanıyordum

Küstüm çiçeği gibi 

Yüreğime dokunuldukça 

Kapanıyordum içlerime..', 'Kapalı bir içtim  Kendi içlerime doğru  Günlerimin sayısı çoğaldıkça Bir başka bakıyordum hayata Sayılardan bir dünya  Çıkışı bulabilene aşk...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/kustum-cicegi-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Burada', 'simdi-burada-guler-ilgaz-g29pt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Katığıma 

Biraz düş, biraz gerçek kattım

Gerçeklerime anlam yükledim

Düşlerimi hayallerle süsledim

Zaman aldı götürdü

Mekanlar içine 

Sürüklendim

Bir oraya

Bir buraya

............

Düşüncelerime 

Yüklediğim anlamlarla daldım

Süslediğim hayallerle çıktım

Zaman mekan içinde 

Çırpındım durdum

.............

Duygularıma hislerime sezgilerime

Dokundum bir bir

Can simidi misali

.............

Gidebilirdim...Sınırsızdı hayallerim

Düşebilirdim...Düşlerimin ardına 

AMA 

KEŞKELER, PİŞMANLIKLAR SARMASA

HER YANIMI 

O ANDA

.............

Durdum...Baktım

Bir katığıma bir düşüncelerime

İŞTE

Hayallerimin gerçekleşebileceği

Andaydım

Tutundum sıkı sıkı can simidime

Nefes alabilmek için yeniden 

............

Sordum ''Azığım NEREDE? ''', 'Katığıma  Biraz düş, biraz gerçek kattım Gerçeklerime anlam yükledim Düşlerimi hayallerle süsledim Zaman aldı götürdü Mekanlar içine  Sürükl...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/simdi-burada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nil Karaibrahimgil', 'nil-karaibrahimgil-erkan-abi-k4gw5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir buse

Bir mim

Bir sırılsıklam

Bir çorak

Sımsıcak bir ürperti

Nil''in gözlerinde gök

Hareketlerinde hayat

Asil bir boyun

Ses günahsız

Çocuk hıçkırığı

Yeni doğmuş ağlıyor

Masum bir istek

Duruş utangaç

Gözlerine takıldım ben

Kaç deniz var öyle

Kaç atmosfer

Durgun bir deniz

Durgun ve derin 

Sonu hayallerde

Fırtına da kabarmış saçlar

Armoni var yükselişinde

Alçalışında

Dalga dalga

Resim resim

Adımını her atışında

Aşağı yukarı

Yukarı aşağı', 'Bir buse Bir mim Bir sırılsıklam Bir çorak Sımsıcak bir ürperti Nil''in gözlerinde gök Hareketlerinde hayat Asil bir boyun Ses günahsız Çocuk...', ARRAY['Türk Edebiyatı','Şiir','Erkan Abi']::text[], 8.5, '{"poet":"Erkan Abi","poet_slug":"erkan-abi","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/nil-karaibrahimgil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'M a n i l e r (7)', 'm-a-n-i-l-e-r-7-abdullah-atay-9q20m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'börek dolu siniler

sevda çeken iniler

hazır olun ey dostlar

söylenecek maniler....

yarın elinde incir

gerdanda altın zincir

çok sallanma güzelim 

o nazik belin incir...

görme beni el gibi

başımda es yel gibi

yar yanıma gelince

coşar yürek sel gibi...

yar kokusu gül gibi

sesi de bülbül gibi

bir dilberin aşkından

betim benzim kül gibi...

peşinde yorulmuşum

göğsünde durulmuşum

kara gözlü dilberim

ben sana vurulmuşum...

uğrunda öleceğim

sensin sevda çiçeğim

dünyada her şey yalan

sen ol benim gerçeğim

saçını savurursun

gün gibi kavurursun

sevda bakan gözlerle

can evimden vurursun.

gün battı akşam oldu

bahçemde gülüm soldu

nazlı yarim gidince

yüreğim hüzün doldu....

güzelleri seçelim

güller gibi açalım

nazlı yarin elinden

badeleri içelim...

abdullah atay der ki:

yetim hakkını yeme

kötü sözler söyleme

kendini pula satıp

kula  kulluk  eyleme...', 'börek dolu siniler sevda çeken iniler hazır olun ey dostlar söylenecek maniler.... yarın elinde incir gerdanda altın zincir çok sallanma güz...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/m-a-n-i-l-e-r-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek-Yalan', 'gercek-yalan-halil-i-brahim-ozdemir-tvzgf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Peşim sıra hayal gibi koşarken

Şahidimdir gölgelerim  varlığa…

Hayat engel,  koşu, bir bir aşarken,

Ölüm çare olur yokluk darlığa…

Gözlerin gördüğü her şeyde yalan,

Ardına  gizlenen körebe gerçek…

Alem-i ervah’ta yazılan plan,

Gerçekle aramdan perdeleri çek…', 'Peşim sıra hayal gibi koşarken Şahidimdir gölgelerim  varlığa… Hayat engel,  koşu, bir bir aşarken, Ölüm çare olur yokluk darlığa… Gözlerin ...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gercek-yalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaban Kalır...', 'merhaban-kalir-sirma-mersin-hyt58', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnızlığımın en tehna saatinde

Gecenin içinde

Sallanan hayallerim...

Ve 

Kırılgan korkum

Maviyi yırtarken

Bir merhaban kalır

Yüreğimde

Firari sevdamın peşine

Takılmışken umudum

Sen nereye kayboldun? 

19.11.2004', 'Yalnızlığımın en tehna saatinde Gecenin içinde Sallanan hayallerim... Ve  Kırılgan korkum Maviyi yırtarken Bir merhaban kalır Yüreğimde Fira...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/merhaban-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanışım', 'uyanisim-ayse-kocak-3-yt8n6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uyanışım

Yoksun…

Hiç olmadığın kadar yoksun,

İnce ince dokuyarak girmişsin de yüreciğime, 

Varlığından bilememişim.

Yoksun ya şimdi, 

Tanıdığım binlerce yokluk duygusu,

Birden üşüşüverdi yalnızlığıma,

Ne kadar reddedsem de, varlığınmış sevincim.

Sen bilir misin hiç üşümeyi,

Yokluğun üşümesi titretti mi bedenini,

Açlığın kimsesizliğin ve çaresizliğin.

Ve sevdanın…

Yorgun yüreğim körpecik şimdi.

Yanmaya döneceği günlere gebe.

Dirilerek yeniden  ve yanarak yeniden,

Sevda şiirleriyle büyüyerek…

Bekleyecek…! 

20.11.2004', 'Uyanışım Yoksun… Hiç olmadığın kadar yoksun, İnce ince dokuyarak girmişsin de yüreciğime,  Varlığından bilememişim. Yoksun ya şimdi,  Tanıdı...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Koçak 3']::text[], 8.5, '{"poet":"Ayşe Koçak 3","poet_slug":"ayse-kocak-3","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/uyanisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş/Tüm', 'dus-tum-adulera-ayza-06my7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece indi ansızın

Kar gibi

Sancı gibi

Beklenmeyen  gibi

Bense sana ulaşmak için 

Gördüğün düştüm

Şimdi ise 

Sağır gibi

Kör gibi

Beklenen sevda gibi

Göremediğin düş/tüm', 'Gece indi ansızın Kar gibi Sancı gibi Beklenmeyen  gibi Bense sana ulaşmak için  Gördüğün düştüm Şimdi ise  Sağır gibi Kör gibi Beklenen sev...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dus-tum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığ', 'cig-adulera-ayza-uh7wo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni gördüm

________________________________çığ

________________________________evime

________________________________düşüme

________________________________gönlüme

________________________________düşünceme

________________________________damıma

________________________________kanıma

________________________________sevdama

düştü', 'Seni gördüm ________________________________çığ ________________________________evime ________________________________düşüme _______________...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cig-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antoloji', 'antoloji-yavuz-agir-rwv39', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu topluluk seven ister

Yürek ister can ister.

Yiğit ister nam ister

Sevgi pınarına taze kan ister..

Bu topluluk sevgi ister

Can ister cananı ister.

Göz görür gönül ister

Sevgi pınarına taze kan ister.', 'Bu topluluk seven ister Yürek ister can ister. Yiğit ister nam ister Sevgi pınarına taze kan ister.. Bu topluluk sevgi ister Can ister canan...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/antoloji-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-adulera-ayza-rh78b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her şey var

Gece

Uykusuzluk

Hasret   ı z d ı r a p

Acı

Keder

Elem

Bir şeyler yok

Gece

Aşk

Nasıl etsem', 'Her şey var Gece Uykusuzluk Hasret   ı z d ı r a p Acı Keder Elem Bir şeyler yok Gece Aşk Nasıl etsem...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gece-134-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Yetmiyorsun Bana', 'sende-yetmiyorsun-bana-adulera-ayza-ww7hr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerim gözlerine

Değmese

Ne yarar ki bu dünya

Ellerim ellerini 

Tutmasa

Ne yarar ki bu sevda

Sözüm diline değmese

Kahrolsun bu dava

Gözlerim gözlerinde

Ellerim ellerinde

Sözüm dilinde

Anladım

Bunlarda yetmiyor bana', 'Gözlerim gözlerine Değmese Ne yarar ki bu dünya Ellerim ellerini  Tutmasa Ne yarar ki bu sevda Sözüm diline değmese Kahrolsun bu dava Gözler...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sende-yetmiyorsun-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu aleme geldik geleli', 'su-aleme-geldik-geleli-yavuz-agir-rprbu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dostan yana harap olduk

Güzel hatrını soramaz olduk

Yanına hiç varamaz olduk

Şu alame girdik gireli

Ah  dedikçe bağrım sızılar

Yazılmış birkere kötü yazılar

Gönlüm iyi dostları arzular

Şu aleme geldik geleli...

Ağlasamda gönlüm serindir

Kalbim açık yaram derindir

Gün ola ''Allah'' kerimdir

Şu dünyaya geldik geleli.', 'Dostan yana harap olduk Güzel hatrını soramaz olduk Yanına hiç varamaz olduk Şu alame girdik gireli Ah  dedikçe bağrım sızılar Yazılmış birk...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/su-aleme-geldik-geleli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemlik Gelin', 'yemlik-gelin-zulfikar-yapar-kaleli-fzn8w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Bir yanım yeşerir, bir yanım ölür 

Hayat beni yoğuruyor, a gülüm. 

Dönülmez sıladan telefon gelir. 

Babam beni çağırıyor, a gülüm. 

Görünür sonumuz ahtır amandır 

Özlem ateş gömlek arzu yamandır 

Virane bekliyor bunca zamandır 

Ak şafağa yol arıyor, a gülüm. 

Gözü büyük, ablak çehre, al gibi 

Bezirgana köle gibi, kul gibi 

Sallanıyor bir tomurcuk dal gibi 

Her an dokuz doğuruyor, a gülüm. 

Gayret kaslarıyla hamle yayını; 

Gerince vuruyor göğün ayını, 

Aklının gözüyle görüp payını, 

Çoktur Allah bağırıyor, a gülüm. 

Kına yakmış kanım gibi eline 

Gözüm nuru şal bağlamış beline 

Bir şahin bakışlı ''Yemlik Gelin''e 

Talih yeni ağarıyor, a gülüm.', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Bir yanım yeşerir, bir yanım ölür  Hayat beni yoğuruyor, a gülüm.  Dönülmez sıladan telef...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yemlik-gelin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arif EREN', 'arif-eren-ozkan-gonlum-2y2nr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kelimenin ruhunu bilen 

Fikire  kanat veren 

Şiir denince akla gelen 

Bir şairdir Arif EREN

İlmek- ilmek dokur şiiri

Nakış nakıştır her biri 

Duygu-duygu gönle giren 

Bir şairdir Arif EREN 

Eşi bulunmaz deyişlerle 

En güzel imgeler, simgelerle 

Şiirin doruğuna eren 

Bir şairdir Arif EREN 

Bin bir emek ile 

Koza gibi şiir ören 

Bana dost, bana yaren 

Bir şairdir Arif EREN 

İnançlı ve imanlı 

Yurt ve insan sevgisiyle dolu 

Allah’ın şair kulu 

Kahramanmaraş otuz sekiz doğumlu 

Bir şairdir Arif EREN', 'Kelimenin ruhunu bilen  Fikire  kanat veren  Şiir denince akla gelen  Bir şairdir Arif EREN İlmek- ilmek dokur şiiri Nakış nakıştır her biri...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/arif-eren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Kuyu', 'kor-kuyu-seher-gungor-znvt7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu Gecede Sensizliği Anılara Sarıp İçtim.Kaybettikten Sonra 

Anlarmış İnsan Asıl Gerçeği.Hemde Kazandığının Bile Farkına Varamadan.Avuçlarımın Arasından Uçup Gitti İşte Uzun Zamandır Beklediğim, Hasretini Çektiğim Umudum.Offf.. Yaa Acı Hemde Ne acı Bişey Bu..Biliyormusun Umutla Beklemek,Varlığını Bildiğin Umudunu Kaybetmekten Daha da Tatlıymış.O Bile İnan Daha Tatlıymış...Acılar Geçer Zaman En Büyük İlaç Derlerdi Hep.Zamanı İçinde Durdurduktan Sonra,Geçen Zaman Nasıl Derman Olacak ki...Hiç İşte..Laf Olsun..Zaman Öyle Hızlı Akıp Gidiyor kiTutamıyorum Ellerimle Büyüttüğüm Güllerimi,Yetişemiyorum Giden Zamana...Su Misali Akıp Gidoyor İşte.Gitme Diyorum,Kal Ne Olur Biraz Daha Diyorum Duymuyor Feryadımı.Görmüyo İçimde Kopan Fırtınayı...Neden Yarabbim Bu Ceza,Ne Yaptım ki Bu Derdi Reva Gördün Bana...Halbu ki Sende Biliyordun,Beni Yaşama Bağlayan Sadece Umudumdu...Bittimi Yani,Tükendi mi...Bana Düşen Umudun Arkasından Gözü Yaşlı Bir Çift Göz Oldu..

Hep Düşünmüşümdür; Ölümmü Daha Acı,Kaybetmek mi Diye.Birisinde Dönüşü Olmayan Yolda Olduğunu Bilirsin,Umut Etmezsin,Bekleyemezsin Sadece Güzel Günleri Düşünür Özlem  Duyarsın Yaşadıklarına.Ya Diğeri Yanındayken Hasreti Yaşatır Sana,Dindiremezsin Gözyaşlarını,Gösteremezsin Hep İçine Akıtırsın.Durduramazsın Kalp Atışlarını,Feryat Etmek İstersin O''na Bile İzin Vermemiştir Giden Umudun..Yıldız Misali Kaydığını Görürsünde Gökyüzünden,Durduramazsın..

Kahrolası Geceler Hiçbir Anlamınız Yok Artık.Çıkmıyorum Artık Çıplak Ayaklarımla O Küçük Balkonuma,Savuramıyorum Saçlarımı,Pembeleşmiyo Yanaklarım,O Güzelliği Hissedemiyorum.Hiç Kimsenin Beğenmesini İstemiyorum Beni..

Seyratmiyorum Artık Türk Filmlerini,Daha Az Okur Oldum Duygu Yüklü Romanları...Korktuğum Oldu Bak Parlamıyo Artık İçinde Kaybolduğum Yıldızların.Güneş Doğmuş-Batmış Umrumda mı...Tek Farkında Olduğum Giden Ömrüm..

Ehhh.. Bee Felek Ben Sana Ne Deyim.Ne Kahpe Çarkın Varmış,Ne Tükenmek Bilmeyen Derdin Varmış Senin....Hayat İşte İnişiyle,Yokuşuyla...Genede Kızamıyorum Sana,Boşuna Değilmiş Umudum,Bekleyişim...Ama Ne Fayda..Bak Sana Dinle Fatih Babam Beni Daha Güzel Anlatmış; 

Bu Akşamda Sensizliği Anılara Sarıp İçtim

Kaybettikten Sonra Anlıyormuş İnsan

Meğerse Hiç Kimseyi Senin Kadar Sevmemişim

Bir Dönsen,En Güzel Yerinde Biten O Rüya 

Yeniden Yaşanırdı İstesen

Yıldızları Sermezmiyim Ayaklarına

Geldiğin Yollara Toz Olmazmıyım

Yine Şafak Söküyor

Uykuların Unuttuğu Gözlerin Yine Tavanda

Ne Vardı Diyorum Bir Dönseydin Sonunda

Şarjörüne Hasret Sürdün Sazımın 

Şimdi Hüzün İşgalinde Yüreğim Ve Ben Hala 

Bıraktığın Yerdeyim...

İşte Böyle Gözüm Alın Yazısı Dedikleri Bu Olsa Gerek,Kimseninde Silmeye Gücü Yetmez......', 'Bu Gecede Sensizliği Anılara Sarıp İçtim.Kaybettikten Sonra  Anlarmış İnsan Asıl Gerçeği.Hemde Kazandığının Bile Farkına Varamadan.Avuçlarım...', ARRAY['Türk Edebiyatı','Şiir','Seher Güngör']::text[], 8.5, '{"poet":"Seher Güngör","poet_slug":"seher-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kor-kuyu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok Ki Bilenim', 'yok-ki-bilenim-selim-bayrak-0zmng', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her gülün goncası

Gönlümün yoncası

Sevgimin bohçası

Ver örgümü

Rengarenk çiçekler

Kırmızı maviler

Alımlı kilimler işleyim

Soğuktan eserim

Uzaktan gelirim

Sıcaktan içerim

Yok bilenim

Sevenim sen olsan

Sevenin ben olsam

Çoraktan biçerim yarını', 'Her gülün goncası Gönlümün yoncası Sevgimin bohçası Ver örgümü Rengarenk çiçekler Kırmızı maviler Alımlı kilimler işleyim Soğuktan eserim Uz...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yok-ki-bilenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın', 'askin-azmi-aytac-6nhw1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hülyalı sestir

Bir gül nefestir

Çılgınca estir

Gönlümde aşkın 

Gel, kalbi coştur

Yıllarca koştur

Bilsen ne hoştur

gönlümde aşkın

Durgun denizdir

Solgun benizdir

Sevginden izdir

Gönlümde aşkın

Kaldıysa sensiz

Çarpar düzensiz

Çılgın ve densiz

Gönlümde aşkın

Ey gül yanaklım

Mahvettin aklım

Yok gizli saklım

Gönlümde aşkın', 'Hülyalı sestir Bir gül nefestir Çılgınca estir Gönlümde aşkın  Gel, kalbi coştur Yıllarca koştur Bilsen ne hoştur gönlümde aşkın Durgun deni...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/askin-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavak Yelim Ol Es Başımda', 'kavak-yelim-ol-es-basimda-yunus-guzel-so49g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gel hadi, aldırma kimselere

Kavak yelim ol,

Es başımda

Tut ellerimden,

Uçur göklere

Pamuk bulutlara sar beni

Hadi gel, yağmurum ol

Islat iliklerime kadar

Üşüyünce sokul biraz

Teninle kurula,

Nefesinle ısıt beni

Yalnızlığı özlediğimde

Sandalım ol durgun sularda

Al, götür okyanuslara

Güneşle sar beni...

Saçlarımda rüzgar ol

Islığımda türküm

Bir acı kahvem ol

Unutmayım kırk yıl seni', 'Gel hadi, aldırma kimselere Kavak yelim ol, Es başımda Tut ellerimden, Uçur göklere Pamuk bulutlara sar beni Hadi gel, yağmurum ol Islat ili...', ARRAY['Türk Edebiyatı','Şiir','Yunus Güzel']::text[], 8.5, '{"poet":"Yunus Güzel","poet_slug":"yunus-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kavak-yelim-ol-es-basimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorsun', 'gidiyorsun-yunus-guzel-zjx94', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşte gidiyorsun,

Ellerimi de götür giderken

Tutamam ki,ellerinden gayri elleri		

Sen gidiyorsun işte,

Gidişin bütün ayrılıklar gibi

Dönüşümsüz hüzünler yaratır

Ben mutluluğun sınırındaki hüznü severdim

Bu gidişin öyle değil…

Bir tek sen sarardın bu yarayı

Sarmaz şimdi ellerin,

Yaralarım kanatır.

Sen gidiyorsun işte,

Al, canımı da götür giderken

Sen yoksan,

Gülüşün yoksa,

Ben bu canı neyleyim...', 'İşte gidiyorsun, Ellerimi de götür giderken Tutamam ki,ellerinden gayri elleri		 Sen gidiyorsun işte, Gidişin bütün ayrılıklar gibi Dönüşüms...', ARRAY['Türk Edebiyatı','Şiir','Yunus Güzel']::text[], 8.5, '{"poet":"Yunus Güzel","poet_slug":"yunus-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gidiyorsun-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avun Avunabilirsen', 'avun-avunabilirsen-ali-aldemir-1xwet', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Onca yangın kırık dökük 

Sönmüş yaşam bunca,

Zamansız, amansız karakış

Bir de yenilgi sonra üstüne,

Avun avunabilirsen

Hem can hemi de canan,

Ateş, kan kokusu, kemik sesleri

Bir de ihanet üstüne,

Davası kanın, bir de peşin hüküm

Kavgam dipsiz tüfek

Öfkem namlu da  bir deli fişek,

Umut demişim sevda demişim

Vurmuşum kendimi kavganın içine,

Ne kadar varsa gayrı ayrı,ikilik

Yoksulu daha da uyutan beylik

Sözleri yazılan kağıdı yaktım,

Kırdım yazan  kalemi yaktım,

Yaktım tekrar tekrar bir de küllerini.

Kurşuna,namluya,kılıç kınına,

Bir de kanın üstüne yazdım sözü

Sevebilmeyi,kardeşliği,özgürlüğü

Bir de yüreklerine bebelerin

Doğruluğu,dürüstlüğü....', 'Onca yangın kırık dökük  Sönmüş yaşam bunca, Zamansız, amansız karakış Bir de yenilgi sonra üstüne, Avun avunabilirsen Hem can hemi de canan...', ARRAY['Türk Edebiyatı','Şiir','Ali Aldemir']::text[], 8.5, '{"poet":"Ali Aldemir","poet_slug":"ali-aldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/avun-avunabilirsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Verdin ki', 'ne-verdin-ki-azmi-aytac-xl7hy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bağrımı, hep nar''a yaktın

Erciyes''ten kar mı verdin

Gönlümü, öksüz bıraktın

Halden anlar yar mı verdin 

Kalbi,aşk''la sarhoş ettin

Derbeder ben berduş ettin

Hoş hayalim, nahoş ettin

Şerha şerha nar mı verdin

Ruhumun, esrarı sensin

Aşkımın, ısrarı sensin

Lütfunu alem beğensin

Gül mü verdin, har mı verdin', 'Bağrımı, hep nar''a yaktın Erciyes''ten kar mı verdin Gönlümü, öksüz bıraktın Halden anlar yar mı verdin  Kalbi,aşk''la sarhoş ettin Derbeder b...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-verdin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin Sen', 'neredesin-sen-azmi-aytac-2nzla', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Baharda açan güller gibisin

Gönlü serinleten yeller gibisin

Seviyorsan neden eller gibisin

Vefa yoksunusun, bildin mi güzel

Sevgim coşuyorken sellercesine

Yakıp ta savurdun küllercesine

Özlemle tutuşan  güllercesine

Goncalar dökerek, soldun mu güzel

Gönülden severken neden kaçarsın

Kalbe onulmayan yare açarsın

Sevgimi çiğneyip döküp saçarsın

Bir damla yaşımı sildin mi güzel

Beni güldürmedin ömür boyunca

Tek emelim; sen mutlu ol doyunca

Sevindin mi öldüğümü duyunca? 

Ağladın mı acep, güldünmü güzel', 'Baharda açan güller gibisin Gönlü serinleten yeller gibisin Seviyorsan neden eller gibisin Vefa yoksunusun, bildin mi güzel Sevgim coşuyorke...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neredesin-sen-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm Yolgeçen Hanı mı?', 'gonlum-yolgecen-hani-mi-azmi-aytac-iyo1k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seviyorsan yakmasaydın

Kalbe girdin çıkmasaydın

Hem sevip hem bıkmasaydın

          Yıktın, aşka imanımı

           Kalbim yolgeçen hanı mı? 

Gözlerini süzmeseydin

Yalanları düzmeseydin

Ayrılırken üzmeseydin

          Yıktın, aşka imanımı

           Kalbim yolgeçen hanı mı? 

Kaşlarını çatmasaydın

Aşka hile katmasaydın

Ben kulundum, satmasaydın

            YIktın, aşka imanımı

             kalbim yolgeçen hanı mı? 

Gönlü, mahzun etmeseydin

Terk edip hem gitmeseydin

Can verirdim, isteseydin  

              Yıktın, aşka imanımı

               Kalbim yolgeçen hanı mı?', 'Seviyorsan yakmasaydın Kalbe girdin çıkmasaydın Hem sevip hem bıkmasaydın           Yıktın, aşka imanımı            Kalbim yolgeçen hanı mı?...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gonlum-yolgecen-hani-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Eğil...', 'karanlik-egil-i-brahim-ethem-bingul-vxont', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnızlıklar yolda gölgem,yoldaşım

Yalnızlıklar benim can arkadaşım

Onlar hep benimle,onlar sırdaşım

Ayrılmazlar varlığımdan,canımdan...

Kalabalık çarşının göbeğinde

Hoş kokular güllerin öbeğinde

Sevda dövülürken aşk dibeğinde

Kalbime bir koşu başlar kanımdan...

Siyah saçlar,ak ellerle örülsün

Ayrılığa sebeb olan sürünsün

Ey karanlık eğil sabah görünsün

Kara gözlüm bana uçsun dalından...

www.iebingul.com', 'Yalnızlıklar yolda gölgem,yoldaşım Yalnızlıklar benim can arkadaşım Onlar hep benimle,onlar sırdaşım Ayrılmazlar varlığımdan,canımdan... Kal...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/karanlik-egil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Kaderi', 'askin-kaderi-azmi-aytac-lhs8n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Niçin, kara gözün mahzun bakıyor

Kirpikten süzülen yaşın, süs gibi

Bülbül, özlemine türkü yakıyor

Gül, seven bülbül küs gibi

Dünya kurulalı bu böyle zahir

Zührenin aşkıyla, mahvoldu Tahir

Ferhat mı, Şirin mi sevmekte mahir

Terk-i yar ettiler bir öksüz gibi', 'Niçin, kara gözün mahzun bakıyor Kirpikten süzülen yaşın, süs gibi Bülbül, özlemine türkü yakıyor Gül, seven bülbül küs gibi Dünya kurulalı ...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/askin-kaderi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz Niye Nemli', 'goz-niye-nemli-azmi-aytac-94tca', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu aşkın oduyla yanan gönlümü

Daha da kanatma, bakıp elemli

Gidiyor gibisin beni bırakıp

Dudak niye buruk, göz niye nemli

Beni terk etmeni ben mi söyledim? 

Kendin arzuladın, kendin istedin...

Bu aşkın sonuda neler bekledin

Sözün niye acı, lafın sitemli

Ayrılığı sen isteyip yarattın

Ruhumu sen gece yaptın, kararttın

Gidecek gibiysen niye ayarttın

Tavır niye ezik ve yüz elemli', 'Şu aşkın oduyla yanan gönlümü Daha da kanatma, bakıp elemli Gidiyor gibisin beni bırakıp Dudak niye buruk, göz niye nemli Beni terk etmeni b...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/goz-niye-nemli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Yalan', 'buyuk-yalan-azmi-aytac-4ye2y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mutluluk, bu ömrün neresinde ki? 

Hayale, hülyaya dalışında mı

Yarin, hasretiyle coşup, çağlayıp

Ellerin, koynunda kalışında mı

vefasız bakışta, gülüşte midir

özlemle, bir ömür sürüşte midir

Barışıp, yeniden küsüşte midir

zalimin; gönlünü çalışında mı

Aşkın ateşi mi, sitemi midir

Terk edip gidişin matemi midir

Yiten sevgilerin son demi midir

Acaba, son nefes alışında mı

Görmedim, onu ne veren, ne alan

mutlulukl yalandır, bir büyük yalan

Hep, mutlu olurmuş sevdaya dalan

Ecelin kapını çalışında mı?', 'Mutluluk, bu ömrün neresinde ki?  Hayale, hülyaya dalışında mı Yarin, hasretiyle coşup, çağlayıp Ellerin, koynunda kalışında mı vefasız bakı...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/buyuk-yalan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üstü Kalsın', 'ustu-kalsin-azmi-aytac-24nvq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İstedin, sen hazla geldin

Hem de bin bir nazla geldin

Aşk, bana sen fazla geldin

Gör hesabı, üstü kalsın

Gel gel ettin bir bakışla

Git dedin, bir kaş çatışla

Soldu goncam, karla kışla

Ver baharı, üstü kalsın

Ahu gözlüm, gül dudaklım

Koymadın, mahvettin aklım

Var mı artık gizli saklım

Kalbimi ver, üstü kalsın

Ben ki, mahrumum vefadan

Kestim ümmidim sefadan

Küskünüm, olmam ki Şadan

Sevgimi ver, üstü kalsın', 'İstedin, sen hazla geldin Hem de bin bir nazla geldin Aşk, bana sen fazla geldin Gör hesabı, üstü kalsın Gel gel ettin bir bakışla Git dedin...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ustu-kalsin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çık Gel', 'cik-gel-azmi-aytac-kx5qg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönlümde gümanım var

Aklım var, iz''anım var

Dilim var, lisanım var

Fakat, anlatamam ki

Yaşadım bunca sene

Şad olamadım gene

Ne zor, bir düşünsene

Hicranı atamam ki

Baş koyduğum, dizindi

Sen güldün, acım dindi

Bu aşk; ikimizindi

Tek ben yaşatamam ki

Batırdın, kalbe diken

Sevmedin sevilirken

Bu gönül senin iken

Ellere satamam ki

Ben, yanmaktan aşkına

Döndüm artık şaşkına

Çık, gel Allah aşkına

Yalnızca yatamam ki', 'Gönlümde gümanım var Aklım var, iz''anım var Dilim var, lisanım var Fakat, anlatamam ki Yaşadım bunca sene Şad olamadım gene Ne zor, bir düşü...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cik-gel-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekip Gidem mi', 'cekip-gidem-mi-azmi-aytac-mev07', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gel diyerek çağırırken gözlerin

Gelme diye çatılıyor kaşların

Gönül yıkar; sitem bütün sözlerin

Yüzün güler, akar gözde yaşaların

Anlaşılmaz, hangisidir yalancı

Seven gönül müdür, dilde sitem mi

şaşırdım ben, kaybederek inancı

Bağrıma taş basıp, çekip gidem mi', 'Gel diyerek çağırırken gözlerin Gelme diye çatılıyor kaşların Gönül yıkar; sitem bütün sözlerin Yüzün güler, akar gözde yaşaların Anlaşılmaz...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cekip-gidem-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sazım Gibisin', 'sazim-gibisin-azmi-aytac-hmcj4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çiğdemli baharım, yazım gibisin

Gönülde sitemim, nazım gibisin

Mızrabın ben oldum, sazım gibisin

Nağmenle, kalbimi viran edersin

Sevgi pınarımdın, kanamaz oldum

Yakıp da kül ettin, yanamaz oldum

Küstürdün, ismini anamaz oldum

Elveda demeden çekip gidersin', 'Çiğdemli baharım, yazım gibisin Gönülde sitemim, nazım gibisin Mızrabın ben oldum, sazım gibisin Nağmenle, kalbimi viran edersin Sevgi pınar...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sazim-gibisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Gözlüm', 'kara-gozlum-azmi-aytac-sdint', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hercai şair

Yaz aşka dair

Sevmekte mahir

Aşık mısın sen? 

Gözler kömürden

Verdin ömürden

Sevdin gönülden

Sadık mısın sen? 

Sevsen de candan

Bigane canan

Etmez ki handan

Layık mısın sen? 

Aşkın hudutsuz

Vuslat umutsuz

Sarhoş mu, mutsuz

Ayık mısın sen? 

Sevgin güvensiz

Canansa densiz

Yelken, dümensiz

Kayık mısın sen?', 'Hercai şair Yaz aşka dair Sevmekte mahir Aşık mısın sen?  Gözler kömürden Verdin ömürden Sevdin gönülden Sadık mısın sen?  Sevsen de candan ...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kara-gozlum-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Hece', 'tek-hece-azmi-aytac-smfri', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni hasret koyarak bir heceye

Günümü döndürüyorsun geceye

Çevirip aşkımı bir bilmeceye

Gidiyorsun, bu günahtır meleğim

Beni yad ellere salmak mı hüner

Sevenin ahını almak mı hüner

Gülerek gönlümü çalmak mı hüner

Ne bakıştır, ne nigahdır meleğim

Eritirsin o siyah gözle beni

Yakışın; türlü sitem sözle beni

Adımı anma sakın, özle beni

Sevenin bahtı siyahtır meleğim

Ne yalanlar! ... gönül alsan ne çıkar? 

Beni yerden yere çalsan ne çıkar? 

Gidiversen, ya da kalsan ne çıkar? 

Garibin kısmeti Ah dır meleğim...', 'Beni hasret koyarak bir heceye Günümü döndürüyorsun geceye Çevirip aşkımı bir bilmeceye Gidiyorsun, bu günahtır meleğim Beni yad ellere salm...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tek-hece-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demedim mi', 'demedim-mi-ali-riza-unal-e4ycb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Giderse bu günler, görmesini bil demedim mi

Ölürse bu gönül, kırılır gayrı gülmez bırakma yad ele

sevmesini bil demedim mi

Senin ile geceler, ayaz olmaz ört üstümü

Yanmasını bil demedim mi

Sevene sevdalar ayrı olmaz, kaçıver sessizce

Yatmasını bil demedim mi

Senin dilinde söz bitmez, O lisanı! cevheri

Yazmasını bil demedim mi

Na ehle aşikar olunmaz, hayayı ile edep ile

Susmasını bil demedim mi', 'Giderse bu günler, görmesini bil demedim mi Ölürse bu gönül, kırılır gayrı gülmez bırakma yad ele sevmesini bil demedim mi Senin ile geceler...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/demedim-mi-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairler', 'sairler-ali-riza-unal-id1c3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gayrı dilim durmaz, açık gizli söylerim

Sevdanız canıma yar oldu, ben sizsiz neylerim

Halden ise özü, helal imiş tatlı dil ile sihiri, sözü

Lokmanı divane gönüllerin, hanım efendi ve beylerin

Benide alın yanınıza ne olur, ey şairi viraneler

Halinizi aleme jurnal eder, ya susar ya söylerim', 'Gayrı dilim durmaz, açık gizli söylerim Sevdanız canıma yar oldu, ben sizsiz neylerim Halden ise özü, helal imiş tatlı dil ile sihiri, sözü ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sairler-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ziynedem', 'ziynedem-ali-riza-unal-g56bu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Açıldı perdeler cânıma,  o pihanı sineden

Kalmadı firkâte meylim, ayanım dideden

Feryaad! ederim valsına, mashar olmasam eğer

Saçıldı cavhêri alâ, ben leylâya ziynedem

              Ziynet güzel takı', 'Açıldı perdeler cânıma,  o pihanı sineden Kalmadı firkâte meylim, ayanım dideden Feryaad! ederim valsına, mashar olmasam eğer Saçıldı cavhêr...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ziynedem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensin', 'sensin-azmi-aytac-zg3q4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkımın ilhamı sensin, gönlümün sultanı sen

sevginin ikramı sensin,sevmenin imkanı sen

Her tebessüm ruşen eyler ruhumun ezharını

Gönl''e cennet bahcesinden Tanrının ihsanı sen

Can katarsın canıma, teshir eden her buseden

Bİl ki çarem sendedir, sensin sebep, sensin neden

Bir güneşsin, döndürüp hem yakmaya amadesin

Söyle canım, var mı farkım hiç yanan pervaneden', 'Aşkımın ilhamı sensin, gönlümün sultanı sen sevginin ikramı sensin,sevmenin imkanı sen Her tebessüm ruşen eyler ruhumun ezharını Gönl''e cenn...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sensin-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözüm Yollarına Bakarken Ağlar', 'gozum-yollarina-bakarken-aglar-azmi-aytac-w874d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Susuz bir kuyunun tola''sı gibi

İnerken ağlarım,çıkarken ağlar

Hasretle,gözlerim dolası gibi

Severken ağlarım,bıkarken ağlar

Delik delik oldu kalbim hüzünden

Sevgi baharından, sitem güz''ünden

Gönül sarayını,senin yüzünden

Yaparken ağlarım, yıkarken ağlar

Aşkım gazel oldu, yel''e karıştı

Akan yaş çağlayıp sele karıştı

Sevdiğim, terk edip el''e karıştı

Gözüm, yollarına bakarken ağlar', 'Susuz bir kuyunun tola''sı gibi İnerken ağlarım,çıkarken ağlar Hasretle,gözlerim dolası gibi Severken ağlarım,bıkarken ağlar Delik delik oldu...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozum-yollarina-bakarken-aglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kölen Olayım', 'kolen-olayim-azmi-aytac-klnut', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üzerinden geç, adımla

Ayak turabın olayım

Aşkımı içme, yudumla

Eski şarabın olayım

Yanıma otur aşık''ca

Mest-ü harabın olayım

Sar, kolların,sarmaşık''ca

Gözlerde, habın olayım

Gelip, bir gece ansızın

Uykunu bölen olayım

Yakıyor, gönlümü sızın

İncitme, kölen olayım

Ülfet eyleme yaban''la

Seviyorum, bunu anla! 

Uğrunda verdiğim can''la

Yolunda ölen olayım...', 'Üzerinden geç, adımla Ayak turabın olayım Aşkımı içme, yudumla Eski şarabın olayım Yanıma otur aşık''ca Mest-ü harabın olayım Sar, kolların,s...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kolen-olayim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba...', 'baba-ercan-eyvaz-ymqq3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sırtlamışsın bir omuzuna geçim derdini 

Diğer omuzuna son gün giyeceğin kefeni

Yüzün çocukları güldüğünde gülerken

Alnından damlayla konulur aşına helali

Sıcakcık evin kömürü sensin, oksijeni 

Saçları okşayıp alnından öpen geceleri 

Bırakmadın elinden dağıttın bize sevgiyi 

Evimizin direği,Güneşi, sevincisin inan her şeyi...', 'Sırtlamışsın bir omuzuna geçim derdini  Diğer omuzuna son gün giyeceğin kefeni Yüzün çocukları güldüğünde gülerken Alnından damlayla konulur...', ARRAY['Türk Edebiyatı','Şiir','Ercan Eyvaz']::text[], 8.5, '{"poet":"Ercan Eyvaz","poet_slug":"ercan-eyvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/baba-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savasdan Kalanlar', 'savasdan-kalanlar-semiha-aslan-9r16q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bütün dünya Iraklı çocukların haykırışlarını duydu

 o minik elleri,oyuncak yerine soğuk silahlar doldurdu

 Iraklıların silahı hep Allah ile Muhammed oldu

 merhamet etsin Rabbim,durdursun müslümanları tüketen bu aç kurdu.

 Şimdi oldu savaşda ölenlerin, Cennet anayurdu,

 askerlerini soksun bakalım buraya,gün gelecek pisliğini yiyecek domuzu.

 Bilsinler dağılacak Cehenneme yanmış etlerinin kokusu,

 şüphe etmesinler,her biri inleyecek gelince kabir sorgusu.

  Büyüklenip gezen o başlar ezilecek, olacak Cehennemin tozu,

  sonucu beklediğiniz o teraziden taşacak günahlarınızın dozu.

  korkmadan parçalayan o şahin şaşacak, olmuş mahşerde kınalı bir kuzu,

  aldığınız günahlar saracak,o  günahsızların kanını taşıyan vücunuzu.

   İsrailloğulları! daha yeni başladı bitmeyecek selamet korkusu,

  defterin elbet dürülecek olsanda sıranın sonuncusu,

  soracak aldığın her bir can; ''O ateş eden eller,şimdi niye tutuldu? ''

  girince anlayacaksın,aratacak aldığın canları Cehennemin keskin leş kokusu.', 'Bütün dünya Iraklı çocukların haykırışlarını duydu  o minik elleri,oyuncak yerine soğuk silahlar doldurdu  Iraklıların silahı hep Allah ile ...', ARRAY['Türk Edebiyatı','Şiir','Semiha Aslan']::text[], 8.5, '{"poet":"Semiha Aslan","poet_slug":"semiha-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/savasdan-kalanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya Bitince', 'ruya-bitince-semiha-aslan-bvc7u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölüm ile bigün bitecek gördüğümüz hulya,

ozaman varacağız merhameti bol olan Rabbimin huzuruna,

anlatır Kuran_ı Kerim, korkudan vahlanacak  o ruh, vara yoğa,

ümitlenme sende vereceksin hesabını,kendini paralasanda baştan sona.

Bitince hesap vurulacak istikamet herbirimizin alnına,

kimileri kuş sütü kimileri zakkum tadacak doya doya, orda,

insan yavaş yavaş varacak onu bekleyen sona

basınca telden ince sırata,yalvaracaksın kara deliğe'' alma beni yanına'' 



 Sözün tercih edilmez Allemlerin Sultanının namına,

 o zaman kaçmak isteyecek ruhlar,İsrafil üfleyince Sura,

 Dünyada Allah’a küfreden dil durmadan etsede dua

 Dönüş yok,varacak onu beleyen zifiri karanlığa.



 Kimileri çekecek Peygamberin güzel kokusunu burnuna

 işte o zaman diyecek asıl lezzet tad burda,

 peygamberimizin eli değince onların omuzuna,

 yalvaracaklar; ''ne olur Huda bitmesin bu rüya''', 'Ölüm ile bigün bitecek gördüğümüz hulya, ozaman varacağız merhameti bol olan Rabbimin huzuruna, anlatır Kuran_ı Kerim, korkudan vahlanacak  ...', ARRAY['Türk Edebiyatı','Şiir','Semiha Aslan']::text[], 8.5, '{"poet":"Semiha Aslan","poet_slug":"semiha-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruya-bitince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Dost', 'eski-dost-azmi-aytac-kmkx5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hatırlar mısın Yılmaz o eski günleri

Bazen keder, bazen neş''eyle geçen o dünleri

Bu gece yarısında ben

Bilmem neden

O Kabataş sırtlarındaki

Evin balkonunda kurulu

Masayı hatırladım

Gece pırıl pırıldı

O boğaz manzarası önümüzde açılmıştı

Ne güzellik, ne manzara bu Yılmaz demiştim

Senin de beğenmeni beklemiştim

Bir cevap gelmişti senden

Güzel,güzel olmasın ya! 

Her gece aynı şey çekilmiyorki...

Bu güzel manzara

.................. ki...

Sonra demirtepedeki bekar evinde

Atlatılan vartalar,

Yatak çarşafında kırılan yumurtalar

Avcunun içini yalayan biri vardı

Sahi neydi onun adı

Sonra kırık bir plak

'''' Mazide hatıram''''

O günler gözlerimde tütüyor buram buram

Bu günse

Para olmuş bir tavşan

sen olmuşsun bir tazı

Duymuyor kulakların

Hatıralardan gelen avazı

Oğlum, yırtma kendini

Ne kadar para, ne kadar altın toplarsın

İmar mevzuatını,

O hukuk ilminle ne kadar coplasan

Bir gün suya erecek ayakların,

Brüksel fuarındaki düğme makinasında ancak

Soğuyacak

.....ların...

Biliyorum

Seni uyarmanın mümkünü yok

Birkaç satırla

İçinden gelsin de ara sıra

Eşi dostu hatırla...', 'Hatırlar mısın Yılmaz o eski günleri Bazen keder, bazen neş''eyle geçen o dünleri Bu gece yarısında ben Bilmem neden O Kabataş sırtlarındaki ...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/eski-dost-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trajedi', 'trajedi-azmi-aytac-0q0dk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben ki senle bir ömür

Geçirmeye kararlı

Zannederdim bu işi

Olacak çok yararlı

Nişan dediler önce

Bir yüzük takılacak

Ondan sonra hayatın

Seyrine bakılacak

Nikah nişanla birlik

Girdi aynı torbaya

Cahil ana, babalar

Dönderdiler çorbaya

Kız oğlanı tanımaz

Oğlan kızdan bi haber

Hemen birleştirdiler

Nişan nikah beraber

Daha yüzünü görüp

Bir kaç kelam etmeden

Hemen nikahladılar

Bir nebze bekletmeden

Kız nelerden hoşlan

Nelere kıymet verir

Acep isteği nedir

Nasıl şeyler önerir

Oğlanın arzusu ne

Acep neden hoşlanır

On sekiz yaşındayken

Evlenmeyi ne sanır

Nişan nikah beraber

Eşe dosta ver haber

işin sonu selamet

Veya, olurmuş keder

Kızın belki aklında

Başka bişi yatar

Oğlanınsa fikrinde

Belki başka biri var

Bunların hepsi hava

Hemence verin karar

Ana baba razı ya

Gerisini kim sorar

Kız yetişmiş, ananın

Dizi dibinde mü''min

namaz, oruç,ibadet

Mürididir pirinin

Oğlan nerde akşam

Orda sabah eder

O aşk hülyalarında

Güzel görse ah eder

İkisi birbiriyle

Yapıştırsan yapışmaz

İnancı uzlaştırsan

Zevkleri hiç uyuşmaz

Biri maviyi sever

o birisi yeşili

Birinde kalp kilitli

O birinde deşili

Biri sevgiden sarhoş

Yanar,her an ah eder

Biri seccadeüzre

Çöker, ya Allah eder

Biri sigara içip

Dumanını savursun

O biri Allah diyip

Diz üstüne otursun

Evlenirler, gerdekte

Birbirini tanırlar

Gelde saadet bekle

Mes''ud olduk sanırlar

Gelinler boş durur mu

Bir kaç çocuk doğurdu

Böyle ekşi mayanın

Tatlı olur yoğurdu

Aradan geçer yıllar

Verir nice kahırlar

Yüzlerde kırışıklar

Çöker saçlara kırlar

Kendi elleri ile

Bir ömrü mahvederler

Sonra, tutar bu hale

Alın yazısı derler

Ne kader denir buna

Ne alnında yazıdır

cehaletin bizlere

Çektirdiği sızıdır.', 'Ben ki senle bir ömür Geçirmeye kararlı Zannederdim bu işi Olacak çok yararlı Nişan dediler önce Bir yüzük takılacak Ondan sonra hayatın Sey...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/trajedi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güller ve Küller', 'guller-ve-kuller-azmi-aytac-dm6ap', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdası varsın,

Dünyamı sarsın

Solsun, sararsın

Bahcemde güller

Feryadı dinsin

Mu''tad edinsin

Gülsün, sevinsin

Küskün gönüller

Gözlerde yaşsın

Yersiz telaşsın

Coşkunca taşsın

Küskün gönüller

Terk eyleyip sen

Git, istemezsen

Bir kor ateşken

savruldu küller', 'Sevdası varsın, Dünyamı sarsın Solsun, sararsın Bahcemde güller Feryadı dinsin Mu''tad edinsin Gülsün, sevinsin Küskün gönüller Gözlerde yaşs...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guller-ve-kuller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Fazlasın...', 'daha-fazlasin-selim-bayrak-i8lu5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gördüğüm günlerden

Sevdiğim düşlerden

Andığım dünlerden

Daha fazlasın

Ve sen

Hiç bilmesen de

Ben bir kaptanım 

Açık sularda 

Özgür benliğin', 'Gördüğüm günlerden Sevdiğim düşlerden Andığım dünlerden Daha fazlasın Ve sen Hiç bilmesen de Ben bir kaptanım  Açık sularda  Özgür benliğin...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/daha-fazlasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bülbül ve Gül', 'bulbul-ve-gul-azmi-aytac-zncg4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bülbül güle konuşmuş, dikeninden yaralanmış

Gül, bülbüle cevretti diye har''ına küsmüş

Bir bir bu şikayet sıralanmış,sıralanmış

Geç açtı diye bağıban ezharına küsmüş

Zannetme bu alem yakışıksız ve düzensiz

Hiç bülbül olurmu çilesiz, gül de dikensiz? 

Tanrım komasın hem beni onsuz, onu bensiz

Terk etti diye Azmi neden yarına küsmüş', 'Bülbül güle konuşmuş, dikeninden yaralanmış Gül, bülbüle cevretti diye har''ına küsmüş Bir bir bu şikayet sıralanmış,sıralanmış Geç açtı diye...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bulbul-ve-gul-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım', 'yarim-omer-ocak-5fntv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Avuçlarım kanıyor nedeni belirsiz

İncecik sızı yüreğimde, kesintisiz

Gül dediğim diken olmuş sebepsiz

Ah demiyorum, kalsam da takatsiz

Maziden çokça hüzün aksetse de 

Dimağımda kalan küçük bir buse

Umarsızca gülerim aklıma geldikçe

Üzemem, katlanırım ondan gelene', 'Avuçlarım kanıyor nedeni belirsiz İncecik sızı yüreğimde, kesintisiz Gül dediğim diken olmuş sebepsiz Ah demiyorum, kalsam da takatsiz Mazid...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ocak']::text[], 8.5, '{"poet":"Ömer Ocak","poet_slug":"omer-ocak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yarim-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Batıdan Doğuya', 'batidan-doguya-mustafa-sozlu-08akw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Turistik dağlar

Çıplak dağlar

Karlı dağlar

Karanlık dağlar

Sevdalı dağlar

Kanlı dağlar

Hain dağlar

Acılı dağlar

Nasıl olursa olsun

Hepsi bizim dağlar

Hepsi yüreğimizi dağlar.', 'Turistik dağlar Çıplak dağlar Karlı dağlar Karanlık dağlar Sevdalı dağlar Kanlı dağlar Hain dağlar Acılı dağlar Nasıl olursa olsun Hepsi biz...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sözlü']::text[], 8.5, '{"poet":"Mustafa Sözlü","poet_slug":"mustafa-sozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/batidan-doguya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manolyam.', 'manolyam-hayrettin-orak-mmivx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anlatamadığım bir duygudur bu,

Bahar yağmurlarına hasret, nehirlerin yağmurla çağlayışını,

Ana kucağını arayan küçük bir yavrunun, Anne diye ağlayışını,

Seni sensizlikte arayan masum yüreğimin aşkınla çırpınışını,

Yanıyorum kahroluyorum desem ne çare,

Sevda deryasının aşk köprüsü oldum,

Basamak, basamak ezip geçme bir inat uğruna,

Yaralama sevdanla yanan şu yüreğimi,

Özgürlüğe uçan sevda güvercinin kanadını kırma,

Çok şeymi istiyorum, anlasana feryadımı,

Aşkının esareti çürüttü yorgun bedenimi,

Ayrılık sözlerin yaraladı küçük yüreğimi,

Görmeyen gözlerim hep seni arar,

Bedenim senin kokunu özler,

Kulaklarımda aşkımın feryat naraları,

Yetmedimi, yetmedimi çektiklerim...

Neden bu çilen, neden bu eziyetin söyle Manolyam........! 

20.11.2004', 'Anlatamadığım bir duygudur bu, Bahar yağmurlarına hasret, nehirlerin yağmurla çağlayışını, Ana kucağını arayan küçük bir yavrunun, Anne diye...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/manolyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çılgınlık', 'cilginlik-mustafa-sozlu-vghqh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akacak sular tersine,

Mantık çıldıracak; 

Kınından çıkacak bıçak; 

Susacak 

Akıl.

Nefretin üstüne üstüne kalkacak.

Akacak sular bildiğine

Kendine gelecek mantık.

Görecek 

Akıl.

Yatandır sevgi kanlar içinde.', 'Akacak sular tersine, Mantık çıldıracak;  Kınından çıkacak bıçak;  Susacak  Akıl. Nefretin üstüne üstüne kalkacak. Akacak sular bildiğine Ke...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sözlü']::text[], 8.5, '{"poet":"Mustafa Sözlü","poet_slug":"mustafa-sozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cilginlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davetsiz konuk', 'davetsiz-konuk-mustafa-sozlu-atl5w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Konuktun,

Konukluğunu bilmedin.

Dolaştın köşe bucak,

Yasaklanmış yerlere girdin.

Korktun,

Bir yer aradın kaçacak...

Üstüne kilitlendi kapılar.

Biliyorsun güzelim! 

Başkalarında da yürek var.

Ne olacak

                          Peki şimdi  ? 

Kapı kilitli,

                          Ve odada üç kişi.', 'Konuktun, Konukluğunu bilmedin. Dolaştın köşe bucak, Yasaklanmış yerlere girdin. Korktun, Bir yer aradın kaçacak... Üstüne kilitlendi kapıla...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sözlü']::text[], 8.5, '{"poet":"Mustafa Sözlü","poet_slug":"mustafa-sozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/davetsiz-konuk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzeller', 'guzeller-mustafa-sozlu-dt5ev', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Etrafımda hep güzeller,

Güzeller,

Güzeller.

Çözdüm işin sırrını.

‘Bu bende ki aşk olmasa’', 'Etrafımda hep güzeller, Güzeller, Güzeller. Çözdüm işin sırrını. ‘Bu bende ki aşk olmasa’...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sözlü']::text[], 8.5, '{"poet":"Mustafa Sözlü","poet_slug":"mustafa-sozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/guzeller-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni', 'seni-mustafa-sozlu-hobne', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '‘Ah be güzelim ah’

Diyor şarkı

‘Ben seni severim ah’

Hangi seni? 

Kaçıncı seni? 

Sarışın mı, esmer mi seni?', '‘Ah be güzelim ah’ Diyor şarkı ‘Ben seni severim ah’ Hangi seni?  Kaçıncı seni?  Sarışın mı, esmer mi seni?...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sözlü']::text[], 8.5, '{"poet":"Mustafa Sözlü","poet_slug":"mustafa-sozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seni-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümit Yaşarın Ardından', 'umit-yasarin-ardindan-azmi-aytac-le81y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ümit Yaşar diye birisi vardı; 

Gönlü aşk dolu, taşarcası

Bu koskoca dünya ona çok dardı

Ölüme atıldı koşarcasına...

Biraz kül bıraktı, biraz da duman

Nağmesi; ağlayan gitarcasına

Dost bildiklerinden dedi el''aman

Sanki, halden anlar dost varcasına

Vedadın derdiyle yandı tutuştu

Gözünde yaşları taşarcasına

Ölüm bizden aldı, ona kavuştu

Sarıldı,saçını okşarcasına

Deryaca köpürüp, ırmakca akan

Bendine sığmayıp coşarcasına

Var mı onun gibi bir iz bıraksın

Gönüllerde, ÜMİT YAŞAR''casına', 'Ümit Yaşar diye birisi vardı;  Gönlü aşk dolu, taşarcası Bu koskoca dünya ona çok dardı Ölüme atıldı koşarcasına... Biraz kül bıraktı, biraz...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/umit-yasarin-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayamadım.', 'anlayamadim-hayrettin-orak-kjd1n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neden umut verdinki bana,

Bakışlarının anlamını bilseydim asla sevmezdim,

Umutsuzluk deryasına dalıp senin için boğulmazdım,

Gönlümü tüm sevdalara kapatmışken sonsuza dek,

Neden sevdim''ki seni, Anlayamadım......! 

Ne volkanlar yakmadıki beni,

Ne rüzgarlar savurmadıki bedenimi,

Ne aşklar yaralamadıki yüreğimi,

Ne deryalar yutmadıki beni,

Neden sevdim''ki seni, Anlayamadım.....! 

Zaman saat umurumda değil, seni bekliyorum,

Öylesine alışmışımki sana, sensiz olamıyorum,

Mazinin yıkık, virane aşklarında boğuluyorum,

Tutunacak tek''de olsa bir dal arıyorum,

Neden sevdim''ki seni Anlayamadım......! 

Ekmek oldun soframa, eş oldun yalnızlığıma,

Duygularımda ulaşamadığım hayal oldun, 

Yorgun bedenime hayat, umut oldun,

Dermansız derdime ilça, çare oldun,

Neden sevdim''ki seni Anlayamadım.......! 

Sana sevdalanmak, seni aramak bana dert oldu,

Aşkınla yanan kalbim çıkmazlarda kahroldu,

Küçücük yüreğim sevda tövbeleriyle doldu,

Hayat sensiz çekilmez acı, çile, elem oldu,

Neden sevdim''ki, neden sevdim''ki seni Anlayamadım.......! 

20.11.2004', 'Neden umut verdinki bana, Bakışlarının anlamını bilseydim asla sevmezdim, Umutsuzluk deryasına dalıp senin için boğulmazdım, Gönlümü tüm sev...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/anlayamadim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı', 'yalanci-azmi-aytac-e911l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Savur, samur saçlarını

Dağıt güzel, dağıt güzel

Sayabilsem saçlarını

Yetmez, kalem kağıt güzel

Mühür gözün, yan bakışın

Ayrılığa bağıt güzel

Nazlanışın, can yakışın

Ölen aşka; ağıt güzel

Aklı baştan, alan sensin

Kalbe, özlem salan sensin

Aşk denilen yalan sensin

Sevgin, bir üç kağıt güzel', 'Savur, samur saçlarını Dağıt güzel, dağıt güzel Sayabilsem saçlarını Yetmez, kalem kağıt güzel Mühür gözün, yan bakışın Ayrılığa bağıt güzel...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalanci-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatlı Yalan', 'tatli-yalan-azmi-aytac-kl53f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdim diye dil dökse de fetten''a kanılmaz

Yer,aşkını söyler bana, gözlerse yanılmaz

Her va''di hevestir güzelin, her sözü hoştur

Bir tatlı yalandır, inanılmaz,inanılmaz

Her aşk''a düşen,mecnun olup nam''ı anılmaz

Her dilbere, leyla diyerek çölde yanılmaz

Her va''di hevestir güzelin, her sözü hoştur

Bir tatlı yalandır, inanılmaz, inanılmaz', 'Sevdim diye dil dökse de fetten''a kanılmaz Yer,aşkını söyler bana, gözlerse yanılmaz Her va''di hevestir güzelin, her sözü hoştur Bir tatlı y...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tatli-yalan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam.', 'sevdam-hayrettin-orak-7w4z3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana tutuldum, delice sevdalandım işte,

Kuruyan, kavrulan toprak için hayat yağmuru,

Leyla ile Mecnun, Kerem ile Aslı misali,

Anne sevgisine muhtaç, garip bir yavru,

İşte seni böyle aradım, böyle sevdim.

Dışarıda hırçın yağmur çisil çisil yağıyordu,

Göl olmuş engin deryalara şırıl şırıl akıyordu,

Asi rüzgar yıkarcasıba, yakarcasına esiyordu,

Yağmurda, rüzgarda,toprakta, deryada seni aradım,

Ben sevgiliye hasret çekerek, acı çekerek sevdalandım.

Katlandım senin acına, sevdamızın çilesine,

Aşkımızı yazdım kalbimin en güzel köşesine,

Kayalara, geçit vermez dağlara, yollara,

Tabib neşter vız gelir hiç kimze sökemez,

Ben sana sevdamı, senin için yaşadım.

Rüzgar sesini fısıldar aşk nağmeleri ile kulağıma,

Kuşlar şarkı söyler sonsuz sevdamıza,

Ağaçlar dans eder aşk şarkımızla,

Yaşanan secdamız yol olsun tüm aşıklara,

İşte yaşadığım en güzel mutluluktur bu Sevda bana.........! 

20.11.2004', 'Sana tutuldum, delice sevdalandım işte, Kuruyan, kavrulan toprak için hayat yağmuru, Leyla ile Mecnun, Kerem ile Aslı misali, Anne sevgisine...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevdam-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beter Ettin', 'beter-ettin-azmi-aytac-ejpsa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünyamı yıkıp, kalbi yakıp,derbeder ettin

Bin nazla açan goncamı yoldun, heder ettin

Sessiz kanayan, yareme merhem sürecektin

Derman olacaktın, beni dünden beter ettin

Bir tatlı bakış''dın, giderek gönlüme doldun

Sevda sunuyorken daha dün, zulmeden oldun

Sessiz kanayan yareme, merhem sürecektin

Derman olacaktın, beni dünden beter ettin', 'Dünyamı yıkıp, kalbi yakıp,derbeder ettin Bin nazla açan goncamı yoldun, heder ettin Sessiz kanayan, yareme merhem sürecektin Derman olacakt...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beter-ettin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimde Değil', 'elimde-degil-koksal-akar-bhopp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kağıt,bir kalem elimde her an,

Yazıyorum oğul,elimde değil.

Yâr olmaz ezelden ömrüme bu cân,

Üzüyorum oğul elimde değil.

Ömrümü bitiren şu gurbetlere,

Kapımı  zamansız çalan dertlere,

Namerde yârenlik eden mertlere,

Kızıyorum oğul,elimde değil.

Emelim olsa da bulmak Leyla''yı,

Anarım günbegün ben de Mevlâ''yı.

Bu aşkın  uğrunda koca dünyayı,

Geziyorum oğul,elimde değil.

Budur ya dünyada benim nazârım,

Almadan,satmadan biter pazarım,

Ölüm var diyerek birgün,mezarım,

Kazıyorum oğul,elimde değil.', 'Bir kağıt,bir kalem elimde her an, Yazıyorum oğul,elimde değil. Yâr olmaz ezelden ömrüme bu cân, Üzüyorum oğul elimde değil. Ömrümü bitiren ...', ARRAY['Türk Edebiyatı','Şiir','Köksal Akar']::text[], 8.5, '{"poet":"Köksal Akar","poet_slug":"koksal-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/elimde-degil-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulamadım', 'bulamadim-azmi-aytac-gi6bk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'El attığım gonca kuru dal oldu

Sustu aşk bülbülüm dili lal oldu

Yüzünü görmek te bir hayal oldu

Gamımdan ziyade gam bulamadım

Gönül senden sevgi umar oldu hep

Kahbe şans gözünü yumar oldu hep

Ömür kaybedilen kumar oldu hep

Papaz''ı buldum da, dam bulamadım

Sendin, ömür boyu severim diyen

Özlemle yolunu benim bekleyen

Hicran armağanın, hüsran hediyen

Ben sende vefayı tam bulamadım

Engindir derdimden Ağrı dağı da

Sevdamın şarkısı döndü ağıda

Bu dert sığarmı ki kalem kağıda

Ormanda kayboldum,çam bulamadım

Aytaç soyadımdır Azmi adımdır

Aşk''ta dert doyumluk, zevk bir tadımdır

Beşikten mezar''a yol bir adımdır

Ben bu muamma''ya nam bulamadım', 'El attığım gonca kuru dal oldu Sustu aşk bülbülüm dili lal oldu Yüzünü görmek te bir hayal oldu Gamımdan ziyade gam bulamadım Gönül senden s...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bulamadim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süpürge Otu', 'supurge-otu-turgay-akbulut-q36h5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ömür,

Saçını süpürge eden annemin,

Süpürge otu bitmiş kabrinde

Ne garip

Hala kaygılar içinde

Merak etme anne

Merak etme

Biz iyiyiz

Ettiğin duaların

Bıraktığın çabaların

Suyu hürmetine...

Sağlığında hiç veremediğim

Hiç göremediği

Güller vardı elimde

Hiç istemezdin

Biliyorum

Beni gördüğünde 

Güller açardı yüzünde

Annemden bana son hediye

Süpürge otu

Koparamadım anne

Koparamadım

Bıraktım gülleri

Kaygılar üstüne...', 'Bir ömür, Saçını süpürge eden annemin, Süpürge otu bitmiş kabrinde Ne garip Hala kaygılar içinde Merak etme anne Merak etme Biz iyiyiz Ettiğ...', ARRAY['Türk Edebiyatı','Şiir','Turgay Akbulut']::text[], 8.5, '{"poet":"Turgay Akbulut","poet_slug":"turgay-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/supurge-otu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zaman', 'bir-zaman-murat-karatekin-k3nug', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir zaman ayarla bana

Sessiz geceler gibi olsun ama.

Bir tek sen ol varlığınla.

Birde ışıklı yıldızlar, gökkubbenin tavanında.

Denizi kucaklasın gözlerimiz

Gemirler sallanırken dalgalarda.

Yıldızları unutmayalım ama,

Onlarda gökkubenin tavanında…

Kaldırımlarda yürüyelim sallana sallana

Bizi sarhoş sansın gökyüzündeki martılarda

Bir bakış atalım onlara,

Aşk bu sarhoş eder adamı, aman ha…

Gözlerinde son bulsun varlığım,

Akıp giden kaldırımlarda…

MK…', 'Bir zaman ayarla bana Sessiz geceler gibi olsun ama. Bir tek sen ol varlığınla. Birde ışıklı yıldızlar, gökkubbenin tavanında. Denizi kucakl...', ARRAY['Türk Edebiyatı','Şiir','Murat Karatekin']::text[], 8.5, '{"poet":"Murat Karatekin","poet_slug":"murat-karatekin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-zaman-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakma Güzel', 'bakma-guzel-azmi-aytac-u3loi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bana,sitem dolu göz''le

Bakma güzel, bakma güzel

Yüreğimi, acı söz''le

Yakma güzel, yakma güzel

Kapıldım, sevda seline

Garibim, düştüm eline

Gönlümü, zülfün teline

Takma güzel, takma güzel

Hasretle, bağrımı dağlayıp

Mecnunun oldum, ağlayıp

Coşkun sular''ca çağlayıp

Akma güzel, akma güzel

Merhamet et göz yaşıma

Ağular katma aşıma

Sevgimi dertli başıma

Kakma güzel, kakma güzel', 'Bana,sitem dolu göz''le Bakma güzel, bakma güzel Yüreğimi, acı söz''le Yakma güzel, yakma güzel Kapıldım, sevda seline Garibim, düştüm eline G...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bakma-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız''a', 'vefasiz-a-azmi-aytac-qmxi9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bahar meltemisin, esiverirsin

Güftem''e ilham''ı sesi verirsin

Neden selamını kesiverirsin

        Şu seven gönlüme çile düşürme

        Aşk''a vefa göster, dile düşürme

Başımda sevdanın yeli olursun

Kalbimde sevginin seli olursun

Benim gibi sevsen, deli olursun

        Şu seven gönlüme çile düşürme 

        Aşk''a vefa göster, dile düşürme

Gözümde sevgini konuşturursun

Sönen ümitleri tutuşturursun

İçimde aşk''ı sen oluşturursun

        Şu seven gönlüme çile düşürme 

        Aşk''a vefa göster, dile düşürme

Sonunda kalbimi yıkıverirsin

Sır olup, gönülden çıkıverirsin

Ne çabuk usanıp, bıkıverirsin

         Şu seven gönlüme çile düşürme 

         Aşk''a vefa göster, dile düşürme', 'Bahar meltemisin, esiverirsin Güftem''e ilham''ı sesi verirsin Neden selamını kesiverirsin         Şu seven gönlüme çile düşürme         Aşk''a...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vefasiz-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özay Gönlüm'' e Ninenin Mektubu', 'ozay-gonlum-e-ninenin-mektubu-ozkan-gonlum-830z9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey benim umudumun Gandili

		Göz yaşımın mendili

		Dağdan, bayırdan aşı(r)  madığım

		Gözden, gönülden düşü(r)  mediğim

		Duaynan böyütdüğüm

		Türküynen yörütdüğüm

		Gardan, gışdan gayı(r)  dığım

		Bazlımaynan doyu(r)  duğum	

		Güneş’im, Ay’ım

		Yavrııım, bidenem, Özay’ ım.

		Acı habar tez uleşdi

		Elim, ayağım doleşdi

		Gözüm garardı, yüzüm sarardı

		Düğüm düğüm oldu boğazım

		Lokmamı yeyemedim

		Bi şey de deyemedim

		Dondum galdım

		Ne etcemi bilemedim.

		Ey Goca efem, arkedeşim

		Yavrıım, bidenem, can yoldaşım

		Tarhanam, unum, bulgurum

		Bu dünyada umudum, gururum

		Tencerede aşım

		Dinmeyen gözyaşım

		Nerdesin bidenem, yavrııım

		Ne ettin len

		Nereye gittin sen

		Benim yiğidimin ölüm nesine 

		İnsan habar verme mi ninesine…

                               Olsaydı habarım

		Bu halimle goşarak

		Dağı- daşı aşarak

		Ben araya girerdim

		Dikilir garşısına  Azrail’in

		Aslanımı bırakın, beni alın derdim.

		Olur mu yavrııım, olur mu

		Hiç böyle edilir mi

		Doksan yaşındaki ninen 

		Goyup da gidilir mi..

		Ey büyük Allah’ ım

		Senin işine garışmam da

		Bu işde bi yanlışlık var ama

		Onun daha söylenecek sözü

		Dillenecek sazı vardı

		Ninesine mektupları 

		Hem okur, hem çalardı

		Onu dinleyenler duygulanır

		Hem güler, hem ağlardı.

		Ninem derdi bana

		Gocanam derdi 

		Yanık sesiyle türkü söylerdi

		Böyle nasıl oldu bilemeyom

		Epeydir habar gelmedi

		Hasdeyim  de demedi

		Sesi soluğu  bitivemiş

		Aniden, sessizce yitivemiş.

                                Şindi n’olcek gari

		Dostla bişeyle deyin bari..

		‘’ Tellidir anam tellidir

		Denizli’ nin  horozları bellidir ‘’

		Deye dağı – daşı aşan ses nerde..

		‘’ Tepsi de tepsi fındıklar

		Ayşe’ de Veli aga’ yı gıdıklar ‘’

		Deye fıkır – fıkır coşan ses nerde.. 

		Hanı nerde  çoban Mustıfali

		Goyunları gütmeyo mu

		‘’Çöz de al Mustıfali ‘’ diyen Ayşe gelin

		Oynemeye gitmeyo mu

		Ses gelmeyo mu efemden 

		Garibim, yavrım, horozum

		Türkü - türkü ötmeyo mu..

		Ey büyük Allah’ ım

		Neden böyle garar gıldın

		Neden  onu benden aldın

		Neden beni derde saldın

		Affına sığınırım

		Bir sözüm var sana

		Ben bile yaşarken daha

		Neden gittin ona

		Söktün ciğerimi benden

		Tutuştu yüreğim,

		Yandı bağrım

		Affet beni Tanrım 

		Adaletten yana 

		İtirazım var sana.

                                Ey duaynan böyütdüğüm

		Türküynen  yörütdüğüm

		Güneş’im, ay’ım

		Efem, yiğidim, Özay’ ım 

		Ben gideydim yavrııım senin yerine

		Sensiz yaşamak benim  neyime

		Sana gurban olayım

		Gavuşdursun bizi Tanrım

		Orda da seni bulayım

		Yavrııım, bidenem, Özay’ ım.

		Yavrııım, bidenem, Özay’ ım…', 'Ey benim umudumun Gandili 		Göz yaşımın mendili 		Dağdan, bayırdan aşı(r)  madığım 		Gözden, gönülden düşü(r)  mediğim 		Duaynan böyütdüğüm ...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":96,"source_url":"https://www.antoloji.com/ozay-gonlum-e-ninenin-mektubu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeytin Karası', 'zeytin-karasi-azmi-aytac-pt9a5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saçın altın sarısı, gözlerin zeytin karası

Gelişi gam getirir, yokluğu hicran yarası

Beni bin derd''e giriftar ederek kaçtı güzel

Kırılan gönlüm, onun bende kalan hatırası

Kanayan kalb''e onulmaz yaralar açtı güzel

Yakarak aşkımı, hem küllerini saçtı güzel

Beni bin derd''e salıp, aldatarak kaçtı güzel

Kırılan gönlüm, onun bende kalan hatırası', 'Saçın altın sarısı, gözlerin zeytin karası Gelişi gam getirir, yokluğu hicran yarası Beni bin derd''e giriftar ederek kaçtı güzel Kırılan gön...', ARRAY['Türk Edebiyatı','Şiir','Azmi Aytaç']::text[], 8.5, '{"poet":"Azmi Aytaç","poet_slug":"azmi-aytac","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zeytin-karasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özay'' sız Mızrap Elsiz Teller Sessiz Kaldı', 'ozay-siz-mizrap-elsiz-teller-sessiz-kaldi-ozkan-gonlum-9vycg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Rahmetli kardeşim   Özay Gönlüm’ e

                                            

                                                Ecel aldı canı tenden

	                       	Sazlar öksüz kaldı senden

			Türküler de dilsiz kaldı

			Dostlarım ne gelir elden.

			Sen sazın, sözün ustası

			Türkülerin gönül tası

			Sazda, telde, sestesin sen 

			Gönüllerde bestesin sen.

			Bitmez bu çile, bu elem

			Zor yazıyor şimdi kalem

			‘’ Gitti gari ‘’ diye - diye

			Hep ağlıyor cümle alem.

			Türkülerin onurusun

			Türkiye’ min gururusun

			Ünün dünyayı aşıyor

			Adın gönülde yaşıyor.

                                                Ninenin mektuplarını

			Türkülerle okurdun sen

			Hasreti, sevgiyi alıp

			Sazla,sözle dokurdun sen.

			Mızrap elsiz, teller sessiz 

			Öksüz kaldı  ‘’YÂREN’’ sazın

			Denizli’ li  GOCA EFE

			Bırakıp gittin ansızın.

			Sen gittin gelmeyeceksin

			O yerden dönmeyeceksin

			Sen  bizim yüreğimizde

			Yaşayıp ölmeyeceksin.

			Allah’ tan rahmet dileriz

			Dualar hep seni bulsun

			Nur içinde yat kardeşim

			Mekanın da Cennet olsun.

							                                                   01.Mart.2000', 'Rahmetli kardeşim   Özay Gönlüm’ e                                                                                              Ecel aldı ca...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ozay-siz-mizrap-elsiz-teller-sessiz-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk'' ın ozan hali...', 'ask-in-ozan-hali-mutlu-ayar-iw5xw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk, ozanlığın ilk sınavıdır

Aşk, olağan bir ozan avıdır...

18:o5', 'Aşk, ozanlığın ilk sınavıdır Aşk, olağan bir ozan avıdır... 18:o5...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ask-in-ozan-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evişim Varya', 'evisim-varya-ali-riza-unal-he405', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O senin salını salını gezişin varya

Çırpınır kalbim gördükçe, çalı kuşu gibi yada kanarya

Bakmaz gibi göz ucundan, o sezişin varya

Sana olan hem aşkımı  hem hissimi, nasıl bilirsin sen varya

O senin yürek yakan sevişin varya

Naza çekiyor seni, visale sabırsız evişim varya', 'O senin salını salını gezişin varya Çırpınır kalbim gördükçe, çalı kuşu gibi yada kanarya Bakmaz gibi göz ucundan, o sezişin varya Sana olan...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/evisim-varya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle Güle Gİt Oğlum', 'gule-gule-gi-t-oglum-ozkan-gonlum-3jlgw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Üniversiteye giderken..

							

		Yüreğin sevgi dolu bir çınar olsun

		Dalına gönül kuşları konar olsun

		Annen baban hep hasretinle yanar olsun

		Güle -güle git oğlum uğurlar ola.

 		Yaşamak güzel kıymetini bilesin

		Dilerim Allah’ tan  ömrünce gülesin

		Yıllar su gibi aksın çabuk gelesin

		Güle – güle git oğlum uğurlar ola.

		Sen ömrün baharındasın ben kışında

		Nice aşklar yaşadım senin yaşında

		Kavak yelleri esiyorken başında

		Güle – güle git oğlum uğurlar ola.

		Vatanı milleti çok seveceksin

		Aslını neslini hep öveceksin

		Vuruşup BAYRAK için öleceksin

		Güle – güle git oğlum uğurlar ola.

                                Erdemi bil her şey karar olsun

		Yaptığın insana yarar olsun

		Dost düşman hep seni arar olsun

		Güle – güle git oğlum uğurlar ola.

		Aşklar fışkıracak kalbindeki gülden

		Seveceksin bir güzeli sen de gönülden

		Bekliyoruz o günleri annen ve ben

		Güle – güle git oğlum uğurlar ola.	

		İstikbâle götürsün seni yollar

		İyi haberlerin getirsin pullar

		Bak senin için çalıyor davullar

		Güle – güle git oğlum uğurlar ola.

		Annen ve kardeşinle hep seni anacağız

		Dönmeni bekleyip içten içe yanacağız

		Her kapı çaldığında sen geldin sanacağız

		Güle – güle git oğlum uğurlar ola.', 'Üniversiteye giderken.. 							 		Yüreğin sevgi dolu bir çınar olsun 		Dalına gönül kuşları konar olsun 		Annen baban hep hasretinle yanar o...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gule-gule-git-oglum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmen', 'ogretmen-i-lyas-ozmen-6dcp4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaynağı bilgiden bir pınar gibi

Susuz gönüllere akar öğretmen

Yüreği alevden bir fener gibi

Karanlığa ışık yakar öğretmen

Çağdaş Türkiye''dir bir tek dileği

Öğretmek aşkıyla dolu yüreği

Kalem kazmasıdır defter küreği

Cehalet dağını yıkar öğretmen

Ülküsü yükselmek bilimde fende

Hedefi hep aynı dünde bugünde

Dağ kadar engel de olsa önünde

Yarına umutla bakar öğretmen

Onunla çözülür binlerce soru

Bilimle fetheder kaleyi suru

Çileli meslekte görüp de zoru

Sanmayın usanır bıkar öğretmen

Yıkılmaz köprüdür bir çağdan çağa

Kuru bir çalıyı döndürür bağa

Sabırla sürdüğü kıraç toprağa

Bilgi tohumları eker öğretmen

Onun eseridir bakan başbakan

İşadamı doktor mühendis çıkan

Onları zirvede gördüğü zaman

Sevinçten göklere çıkar öğretmen

Yüzüne yansımaz çektiği çile

Okutur öğretir tatlı dil ile

24 Kasımda bir demet gülle

Mutluluk gözyaşı döker öğretmen', 'Kaynağı bilgiden bir pınar gibi Susuz gönüllere akar öğretmen Yüreği alevden bir fener gibi Karanlığa ışık yakar öğretmen Çağdaş Türkiye''dir...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özmen']::text[], 8.5, '{"poet":"İlyas Özmen","poet_slug":"i-lyas-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ogretmen-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayşe'' min Gözleri', 'ayse-min-gozleri-ozkan-gonlum-gp4wj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmur sonu serinlik gibi

		Gök katında derinlik gibi

		Kirpik altında gelinlik gibi

		Ayşe’ min gözleri.

		Rahmet dolu bulut sanki

		Sevgi dolu umut sanki

		Dalında kara dut sanki

		Ayşe ’min gözleri.

		Burcu –burcu çiçek gibi

		Her dem gülecek gibi

		Bana bir şey diyecek gibi

		Ayşe’ min gözleri

		Hem yakın, hem uzak sanki

		Ana sütü gibi ak sanki

		Açılmamış duvak sanki

		Ayşe’ min gözleri.

		Kimin gönlüne dolacak

		Kısmetini nerde bulacak

		Benim şiirimde mi kalacak

		Ayşe’ min gözleri.

							                                    09.04.1993', 'Yağmur sonu serinlik gibi 		Gök katında derinlik gibi 		Kirpik altında gelinlik gibi 		Ayşe’ min gözleri. 		Rahmet dolu bulut sanki 		Sevgi ...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ayse-min-gozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onsuz her gün', 'onsuz-her-gun-goksel-akkaya-0t00g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir cehenem gibi geliyor 

Bana her gün sensiz 

Eski günler aklıma 

Geldikçe çıldırıyorum.

Çünkü onun nasıl üzdüm 

Kendi kendime soruyorum 

Çok kızıyorum kendime 

……….ve kendimden utanıyorum.

Ne zaman aklıma gelse

Düşünüyorum acaba 

Yanına gitsem özür dilesem

Beni affedermi….', 'Bir cehenem gibi geliyor  Bana her gün sensiz  Eski günler aklıma  Geldikçe çıldırıyorum. Çünkü onun nasıl üzdüm  Kendi kendime soruyorum  Ç...', ARRAY['Türk Edebiyatı','Şiir','Göksel Akkaya']::text[], 8.5, '{"poet":"Göksel Akkaya","poet_slug":"goksel-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/onsuz-her-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyada Adınız Kalsın', 'dunyada-adiniz-kalsin-ozkan-gonlum-hy86f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gelin kızım Güngör ile oğlum M.Özgür'' e

                                                Kendi dünyanızda kanat açtınız

			Kuş gibi hür olup elden uçtunuz

			Mevlâna'' nın diyarına göçtünüz

			Yuvanız mübârek olsun canlarım.

			Aşınız, işiniz hep helal olsun

			Eviniz, yolunuz duayla dolsun

			Allah'' ın rahmeti hep sizi bulsun

			Kader yüzünüze gülsün canlarım.

			Ne önemi var ki paranın pulun

			Ömür boyu her an sağlıklı olun

			Adaletli olun, doğruyu bulun

			Dünyada adınız kalsın canlarım.

			İnsanları sevin, sizi sevsinler

			Mutluluk örneği sizi görsünler

			Düşman bile olsa sizi övsünler

			Yolunuz hep doğru olsun canlarım.

			Unutmayın bizi canımızsınız

			Damarlarımızda kanımızsınız

			Biz bir bütün siz de yarımızsınız

			Dostlar bizi sizle ansın canlarım.

			Karışmak olmasın ha işinize

			Çocuklar her sözüm duadır size

			Hayırlı bir torun verin de bize

			Özkan GÖNLÜM dede olsun canlarım', 'Gelin kızım Güngör ile oğlum M.Özgür'' e                                                 Kendi dünyanızda kanat açtınız 			Kuş gibi hür olup ...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dunyada-adiniz-kalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmuru yararak gidiyorum sevdiklerimin yanına / Hikayeler Beş (5)', 'yagmuru-yararak-gidiyorum-sevdiklerimin-yanina-hikayeler-bes-5-gencay-coskun-yqlbc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rüzgar öyle kuvvetli esiyor ki

Narin bir dilberin saçlarını savurur gibi 

Savuruyordu koskoca ağaçların yapraklarını, dallarını

Bir uğultu bir yağmur düşüyor sonraları

İçim acıyordu yine sebepli sebepsiz 

Bir şeyler eksikti 

Yağmuru yararak gidiyorum 

Yada yağmur beni adamakıllı döver gibi ıslatıyordu 

Bu ne soğuktu böyle 

Üşütüyordu adamın hem aklını hem bedenini 

Günün düş dediklerinin yanına. 

Ellerimde sıkılganlığın verdiği bir terleme. 

Yüreğimde özlemin getirdiği garip karın ağrısı heyecan 

Dizlerde anlamsız bir titreme tutuyor. 

Derin bir soluk alıyorum ve geçiyorum. 

Zamanda iz bırakanların yanına.

Her yeni gelen gün bir önceki günü 

Zamanın tozlu raflarındaki sırasına koyup 

Sonraki yeni gelen güne kendini sessizce teslim ederdi

Yürürken 

Soluk alırken 

Ağlarken 

Kısaca yaşarken 

Zamanı yaşatan

Onun sayılası yapan

İnsanlığın yarı temiz yarı kirli elleriydi

Rüzgar öyle kuvvetli esiyor ki

Yağmur öyle hızlı yağıyordu ki 

Birileri bir şeylere kızmış olmalıydı 

İki kelimenin sonunu getiresi gelmiyordu insanın 

Kaçar gibi yürüyordum

Kesme taşlı kaldırımlarda

Zıplama ihtiyacı hissediyordum 

Kapatılmayan belediye çukurlarından

Üşüyen ellerim ceplerinde 

Seyretmek için alemi 

Sığıntı ve sıcak bir cam arkası arıyordum

Daha çok alem beni seyrediyordu 

Gibime geliyordu 

Sonraları gibisi fazla diyordum 

Kendi kendime gülüyordum 

Yağmuru yararak gidiyorum

Yada yağmur beni adamakıllı döver gibi ıslatıyordu 

Zamanın teslim etme saatlerinde 

Kafamda neler dönüyordu yine 

Bir iç sızlaması başlıyordu bende 

Daha günü yaşamadan 

Bırakıyordum gideceği yere 

Aslında yaşıyordum günü, dünü

Sadece sonraki anın garantisi yoktu

Başka bir şeyler umduk hayattan 

O bize bambaşka şeyler verdi 

Sınırsız ihtiyaç kıt kaynak 

Paylaş dur işin yoksa 

Paylaşmak çok güzeldi aslında 

Hayat adil olsaydı

Güç bela bir yemekhaneye atmıştım kendimi 

Yemekhane diyordum ayak üstü yenilen yerlerdi

Modern sanılan ismini burada kullanmak bile istemiyordum 

Ne kadar meraklıyız aslında 

Kanımızdan doğan dilimize 

Bizden olmayan kelimeleri sokuşturmaya 

Arada bir yerdesin sen aslında 

Ne orada ne burada 

Bir dilin için başka bir dilden kelime sokuşturmak 

Sütüne su koymak gibidir aslında 

Cam kenarında masada 

Verdiğim siparişleri beklerken

Yağmuru oturarak seyrediyordum 

Bu defa şanslıydım 

Yağmurdan dayak yemiyordum 

Anlaşılan bayağıda acıkmıştım ve 

Anlaşılan yağmurdan bayağı dayak yemiştim 

Alelacele gelip  geçenleri seyrediyordum

Alemin beni izleme faslı bitmişti şimdilik 

Kısıtlı kullanımda olsa 

Göz hizamda ufak bir kesitini seyrediyordum alemin

Alemin ne dili vardı ne kemiği 

Sosyal anlamda oluşturulmuş 

Garip ama çok garip bir anlamdı yalnızca

Zaten bizde yalnızdık aslında bu kalabalıkta

Ne olduğunu bile anlamadan  

Birden iki küçük el bir çift göz yapıştı cama 

Kıy kıyabilirsen sen şimdi bu ufaklığa 

Kısa kesilmiş saçları kirli 

Parlayan masmavi gözleri

Sanırsın kartpostaldan çıkmış gibide tatlı 

Dışarıyı seyrederken geldiğinin farkında bile 

Olmadığım yemekleri gösteriyordu 

İç mi dayanırdı şimdi buna

Dışarıda bedenim 

İçeride yüreğim üşüyordu 

Diğer insanlar şu küçücük insanın 

Farkında bile değillerdi

Yada yokmuş gibi yapıyorlardı 

Genelde kafalarını kuma gömmesini

Devekuşlarından önce insanlar öğrenirdi

Ne yazık ki bu konuda hiçbir belgesel çekilmemişti

Elimde o an kameram olsaydı 

Hemen bir tane çekebilirdim 

El işaretimle gel dedim ufaklığa 

Güzel olduğu kadar alımlı ve küstah garson kız 

(Türk filmlerinden dolayı yukarıdaki cümle çok komik 

gelir her zaman bana)

Koşarak gelen çocuğu kovmak istese de

Toplumun salaklığına uymadan 

Ben izin vermedim

Geldi büyük insan gibi oturdu karşıma 

“Aç mısın? Bakalım küçük adam” dedim.

Oda kafasıyla bana çok açım der gibi salladı

Kerata cin gibiydi 

Yüzünde bir solukluk vardı 

Aslında biraz ürkekti 

Kim bilir maymun soylu insanlardan 

Ne hakaretler yemişti

Ben ne yedimse ondan istedi 

O yedikçe bana neşe geldi

Gözlerim doldu

Boşaldı boşalacaktı göz pınarlarım

Belli ki çoktandır açtı garip 

Kimdi neydi sormadım

Bugün onun cenneti olsun istedim 

Ne isterse yesin 

Yiyemediklerine bakarken 

Ekmeğini sımsıkı tutuyordu 

Elinden birisi alacak gibi 

Aslında çok doğruydu 

Birilerin zenginliğinde 

Mutlaka diğerinin fakirliği gizliydi 

Birazda ekleyerek 

Biraz da paket yaptırdım yemediklerini 

Üç beş para vermek istedim

Utandı almadı

“Hiç görmediğim ağbim gibisin” dedi

Bende 

“tüm küçükler kardeş tüm büyükler ağbidir” 

dedim yüreğimden 

Bir “ağbim” kelimesi bu kadar mı sıcak söylenirdi 

Aynı kandan mı gelmek lazımdı illaki 

Ağbi, abla akraba olmak için 

Ellerini sıkmasını hayat öğretmiş gibi 

Elinde sımsıkı paketi

“Eve götüreceğim ağbi bunları ” dedi

Belli ki evdekiler açtı.

Keyif mi yürek mi kalırdı insanda

Ellerimden öptü gitti

Bende gözlerinden

Giderken çaktırmadan

Biraz parayı sıkıştırdım paketlerine

Koşar adımlarla gitti

Yarım yamalak evlerin olduğu yerlere

Oyuncağım bulunmalık ekmeklerdi şimdi 

O ana kadar oradakilerin bana ve olanlara 

Cüzamlı gibi baktıklarını görmemiştim 

Yüreğim sıkışmıştı birden 

Bu kadar insan suretini 

Hiç bir arada görmemiştim

Kandırılmışsın enayi 

Senin gibiler olmasa 

Bunlarda olmaz gibi bakıyorlardı 

Oysaki ne çocuk ne de ben

Hiçbir suç işlememiştik

Karşılıklı irade beyanlarıyla 

Geçmişti zaman 

Yabancı değildik bir yerlerde roller değişmişti sadece

Onun büyücek haliydim sadece 

Fakirlik fakirlikti 

Bunda herkesin suçu vardı 

Fakirlik fakirlikti 

Bunda devletin suçu vardı

İsteyen istediği gibi yargılasın dursun 

Adam gibi aç açıkta kalmadan 

Bir geri dönüşüm vardı 

Bunu yapmak lazımdı 

Kimin işine gelirdi ki bu

Şu pis bakışlara

Bakışlarımla

Ben kıt kanaat zenginliğimden vazgeçiyorum 

Siz insan olamayışınızın altınları toplayın

Suretiniz ne kadar güzel olursa olsun 

Ciğeriniz beş para etmezdi” dedim. 

Harbiden dedim. 

Gene olsa gene derim. 

Önceleri bir gün bir yerlerde bende aç kalmıştım 

Bir ağbim olsun ne kadar istemiştim 

Ama şimdi gerçek bir ağbi olmanın 

Mutluluğu vardı yüzümde, yüreğimde

Bir devri kapatır gibi çıktım sokaklara 

Yağmuru yararak gidiyorum

Yada yağmur beni adamakıllı döver gibi ıslatıyordu 

Bir tutam alsam günden

Bıraksam mavilere olmaz mıydı 

Eve gidince güzel kokulu bir ıhlamur 

Kaynayacak gibiydi 

Hafiften yağmur ve soğuğa yenik düşüyordum 

Neye kızmıştı bu gökyüzü böyle 

Kustukça kusmuştu kendini

Döver gibi ıslatmak lazım yağmuru

Yağmuru yararak gidiyorum 

Sevdiklerimin yanına

Sevdiklerim küçük insanlardı 

Kalpleri parlardı gece karanlıkta

Ve bir yağmuru ıslatmak için 

Küçük insanların gözyaşları yeterliydi

Bu akan gözyaşlarında 

Yağmurlar boğulurdu 

Yağmurdu rahmetti bu 

Hem döverdi hem severdi.', 'Rüzgar öyle kuvvetli esiyor ki Narin bir dilberin saçlarını savurur gibi  Savuruyordu koskoca ağaçların yapraklarını, dallarını Bir uğultu b...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":208,"source_url":"https://www.antoloji.com/yagmuru-yararak-gidiyorum-sevdiklerimin-yanina-hikayeler-bes-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Borcun Var', 'borcun-var-esra-oskay-dsp68', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ucundayım dünya nın..

Tropıkal mevsimlerden habersiz! 

Yağmurum süzülüyor, fırtınaya.

Üşüyen bedenim titriyor.

Üstümü örtmek isteyen sevginin bedelinde..

Nefesim derinleşiyor.

Gökyüzünün yaşları durmak nedir bilmiyor.

Sana yazan zavallı kalemim tükeniyor.

Kağıt parçası buruştu elimde, eriyor sularda.

Kurşun gibi boşalıyor yağmur belleğime.

Nergisler,yasemenler,karanfiller..

Toprak kokusuna nötr yağmur ne kadar güzel olsa da.

Yağmurun sesini dinletmek istemiyorum artık sana.

Hüzünün kimbilir kaçıncı katındayım.

Düşmekte istemiyorum, tepe takla..

Tutsak hücreye sıkıştırdım sevdamı! 

Yollara,insanlara sen diye bakmıyorum! 

Gülüşünü de aramıyorum artık! 

Senide aramaktan VAZGEÇTİM! 

Sadece bir fatura var ödenmesi gereken; 

Ödenmeli canım; yürek istiyor! 

Bana gözyaşı borcun var! 

Düşünce borcun var! 

Yağmur değil, sen ödemelisin bu BORCU!', 'Bir ucundayım dünya nın.. Tropıkal mevsimlerden habersiz!  Yağmurum süzülüyor, fırtınaya. Üşüyen bedenim titriyor. Üstümü örtmek isteyen sev...', ARRAY['Türk Edebiyatı','Şiir','Esra Oskay']::text[], 8.5, '{"poet":"Esra Oskay","poet_slug":"esra-oskay","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/borcun-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alın Beni', 'alin-beni-ali-gencay-hxxpy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'güneşin gözlerine mil çekilmiş 

maviye hapis edilmiş deniz

bulutların saçlarını tarar rüzgar

mor bir geceye soyunuyor gün

uzaklardan gelir martı çığlıkları

alışığım gözlerinde batırmaya güneşi

ellerim aşina saçlarında gezmeye

korkarım,aldanırım

alın beni 

gece koynuma girmeden 

esvabını çıkardım hasretin

elleri saçlarımı okşadı

uyku kaçtı kafesinden

gözlerimde cin fenerleri

ürperdi tenim

üşüştü ayazlar üzerime

ateş oldu nefesi

eritti buzdan hevesleri

kor oldu yanıyor 

alın beni

gece kanıma girmeden 

kapımı çalacak rüzgar

elinde hüzünden meyler

kuruyacak boğazım

gözlerime inecek hasretin

kırıp yıldızdan kadehleri

dikeceğim şişeyi başıma

senle sarhoş olacağım

korkuyorum unuturum seni

alın beni

gece bir kadehe satılmadan', 'güneşin gözlerine mil çekilmiş  maviye hapis edilmiş deniz bulutların saçlarını tarar rüzgar mor bir geceye soyunuyor gün uzaklardan gelir m...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/alin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağla Çocuk (Medeni Zulmün Çocuklarına)', 'agla-cocuk-medeni-zulmun-cocuklarina-zulfikar-yapar-kaleli-6fqys', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzel çocuk, mahzun çocuk, can çocuk 

Her kış bir bahara dönsün sen ağla! 

Yürek yara, benzin soluk, yüz uçuk 

Bugün birsin, yarın binsin sen ağla! 

Bu çağın eseri, esiri çocuk 

Sevginin kesiri-küsürü çocuk 

Medeni yangının tesiri çocuk 

Göz yaşınla ateş sönsün sen ağla! 

Ağla ateş sönsün, ıstırap dinsin 

Şu uygar dünyanın mahsulü sensin 

Sen bugünsün, sen yarınsın, sen dünsün 

Yanmış gönüllerde kinsin sen ağla! 

Ağla çocuk ağla zemin ıslansın 

Zamana hükmeden zalim uslansın 

Yaşın duman olsun, dağa yaslansın 

Yarının sahibi sensin sen ağla! 

Adam ikrarından, hayvan yulardan 

Yakalanır çıkamadan sulardan 

Bu aşk yücelerden, bu azim yardan 

Sevdan gönüllere sinsin sen ağla! 

Yağmur gibi bomba yağar, serseri 

Cana düşer yer andırır mahşeri 

Sen ''mazlumlar mazlumu''nun eseri 

Garbın hor gördüğü dinsin sen ağla!', 'Güzel çocuk, mahzun çocuk, can çocuk  Her kış bir bahara dönsün sen ağla!  Yürek yara, benzin soluk, yüz uçuk  Bugün birsin, yarın binsin se...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/agla-cocuk-medeni-zulmun-cocuklarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Ocağımda Kıvılcımken', 'ask-ocagimda-kivilcimken-ozkan-gonlum-bo574', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eşime..

							

Gönülden bakışa razıydım ama

Yıldırımlar çakar gibi baktın sen.

Aşk ocağımda kıvılcımken daha

Yüreğimde yanar dağlar yaktın sen.

			

İstemem Leylâ'' yı verseler bile

Benim şu gönlümün emeli sensin.

Yıkılmaz depremle gelseler bile

Gönül sarayımın temeli sensin.

Seni tarif etmek imkansız bir şey

Sen bir Tanrıça''sın aşk konusunda.

Bakışının deryasına daldım da

Boğuldum gözlerinin okyanusunda.

Senin kadrini bilmek ibadettir

Bir ayetsin gönül adlı kitapta.

Öyle eşsiz bir mücevhersin ki sen

Bir dirhemin bin ton eder hesapta', 'Eşime.. 							 Gönülden bakışa razıydım ama Yıldırımlar çakar gibi baktın sen. Aşk ocağımda kıvılcımken daha Yüreğimde yanar dağlar yaktın ...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-ocagimda-kivilcimken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklıma Sen Düştün', 'aklima-sen-dustun-esra-oskay-qpn50', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dağlar güneşi koynuna almadan,

Çingene kuşlar sevişmeden,

Çılgın kelebekler bakarken,

İsmimi çağıran  bir seste; 

Yine aklıma  sen düştün! 

İki sevdalı gözünde ışık,

Kan ağlayan yüreklerde,

İklimi şaşıran mevsimin sabahında; 

Yine aklıma sen düştün! 

Islak,acı ve gülümsemeyle,

Notasız şarkılarda, rotası kayıp gemilerde,

Kalbime akan damlacıklarda,

Bir kuş geçti başımdan; 

Sesin çınladı kulağımda,

Yine sen aklıma düştün! 

Doğanın  vahşi otlarında,

Tohumları melez,sevişen menekşelerde,

Bitki kokuları yayılırken çevreye,

Parfümün savrulunca burnuma,

Gül bahçesinde; 

Yine aklıma sen düştün! 

Tarihi geçmiş yazılarda,

Kullanma süresi bitmiş yazgılarda...

Kumsaldaki aşıkların sesinde; 

Sevişen ellerin yumrugunda,

Yine sen aklıma düştün..

Kapatın şu  şarkıları,çalınmasın:

Söndürün ışıkları,  kararsın.

Aralanan perdeler kapansın! 

Güneşe küs kalsın, bedenim; 

Dediğim gün...

Sana ait düşleri arşivlediğim,

Hayalleri ertelediğim,

Bitti! Bitmeli dediğim de; 

Kulağıma usulca fısıldadığın iki satır sözün gelirken; 

Kafam karışık, yüreğim burulmuş.

Ve yine aklıma sen düştün! 

Son sigaranın üzerine yazdım ismini,

Bitince senide bitirecektim.

Kaybolacağını beklerken; 

İçime cektiğim dumanların,

Çıkan islerinde,

Yanan yüreğimde,

Yine içime sen düştün! 

Adını anmıyor,

Seni düşünmüyorken,

İçimden de kendime; 

Aferin! Derken...

Telefonun zili  çaldı..

Anımsadım; 

(Alooo,canımın ici!)

Yine sen aklıma düştün!', 'Dağlar güneşi koynuna almadan, Çingene kuşlar sevişmeden, Çılgın kelebekler bakarken, İsmimi çağıran  bir seste;  Yine aklıma  sen düştün!  ...', ARRAY['Türk Edebiyatı','Şiir','Esra Oskay']::text[], 8.5, '{"poet":"Esra Oskay","poet_slug":"esra-oskay","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/aklima-sen-dustun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiye Eğilmelisin!', 'sevgiye-egilmelisin-esra-oskay-gfgco', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabah ışıkları oluşurken gözlerimde,

Gece karanlığının parlaklığı doğan güneşimde..

Ben yine uykusuz. Yine senle ve sensiz.

Saat; 04.30

Seher  vakti oluşumda,

 Nazım Hikmet geliyor aklıma.

Hani görmediği sevgilisine yazdığı o şiirleri..

‘’Kadınım, Canım’’Dediği kadınına döktürdüğü dizeleri..

Kıskanıyormuyum ne? 

Özeniyormuyum ne? 

Bilemiyorum! 

Belki de benden önce sevdiği aşık olduğu için.

Aşk denen tadı önce tatdığı için! 

İnsan böyle severmiymiş.

Böyle güzel şeyleri taaa uzaklardakine yazarmıymış? Düşünüyorum! 

Nazım Hikmet i   05.00 de

İtiraf Etmeliyim! 

Kıskanıyorum; 

Karanlıktaki o aşkı.

Bende yazıyorum sana, Bana.

Taaa uzaklardaki sevgime.

Senin için.

Canım benim.

Canımın içi.

Yani sen! 

Senden bahsediyorum.

Yani seni, senden aldıklarımı sunuyorum bu sabahın köründe..

Sen benden habersiz başka kollarda.

Ne de hoş uyuyorsun mışıl mışıl..

Aşk acısını verdiğin bu özlemimde.

Vera değilim! 

Adıma şiirler yazdıracak kadar! 

Nazım Hikmet te sen değilsin.

Ama bu ağrı  Vera’dan da öte bişey.

Belki de ben istediğim için,

Aşk vuslattır.

Dinle beni! 

Sakın karşıma çıkıp boy gösterme.

Bitecek biliyorum  bu aşk,

Ve o zaman sen ve ben,

Belki de  sevgimiz mors alfabesi olacağız.

Anlayacağın biteceğiz.

Yani bitecek bu aşk.

Ne olur devam et.

Görkeminde..

Ama besle,  sula.. ısıt bu sevgiyi..

Susuz kalmış  menekşe ne kadar yaşar ki söylermisin? 

Menekşenin ömrü az mı ne dersin? 

Eğil, öp,okşa...

Hiçbir şey değişmeyecek sadece büküleceksin aşk için..

Değmez mi? 

Bak çaydanlık bile  kibirli! 

Ama yeri geldiğinde o bile bardağın önünde eğilir! 

Bu yüzden dir ki; İnsanlar her gün

Bardağın alnından öperler.

Hadi eğil..! 

Ne bekliyorsun? 

Sadece sevgi var bunda değmez mi? ? ?', 'Sabah ışıkları oluşurken gözlerimde, Gece karanlığının parlaklığı doğan güneşimde.. Ben yine uykusuz. Yine senle ve sensiz. Saat; 04.30 Sehe...', ARRAY['Türk Edebiyatı','Şiir','Esra Oskay']::text[], 8.5, '{"poet":"Esra Oskay","poet_slug":"esra-oskay","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/sevgiye-egilmelisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol(yalnızlık)', 'yol-yalnizlik-salih-demirci-37ra6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Işık alınan gecelerde

İçe doğru değil ise 

Tüm yollar

Yalandır yanlızlıklar

En derinde bile

İlla ki bir tanıdık çıkar', 'Işık alınan gecelerde İçe doğru değil ise  Tüm yollar Yalandır yanlızlıklar En derinde bile İlla ki bir tanıdık çıkar...', ARRAY['Türk Edebiyatı','Şiir','Salih Demirci']::text[], 8.5, '{"poet":"Salih Demirci","poet_slug":"salih-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yol-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şeye Yeniden Başlamanın Zamanı Geldi', 'her-seye-yeniden-baslamanin-zamani-geldi-melih-coskun-vcygk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her şeye yeniden başlamanın zamanı geldi artık 

Eski bir kitabı kurtarıp tozlu rafların tutsaklığından 

Okumaya başlamalı eksik kalmış yerinden 

Tam o anda en sevdiğim türkü çalmalı radyoda 

Ve annem bilmemeli

Şiirler çıkartıp yüreğimin kınından 

Her gece gizli gizli ağladığımı

Tamamlamanın zamanı geldi artık 

Yarım bıraktığım her bir şeyi

Hiç görmediğim şehirleri gezmeliyim 

Yeni insanlarla tanışmalıyım 

Ve düşmeliyim apansızın yürekli bir sevdanın koynuna 

Uçurum olsa da yolum 

Kan revan içinde kalsam da her düştüğümde 

Vazgeçmemeliyim inandığım hiçbir şeyden

Ne olursa olsun 

Vazgeçmemeli insan asla 

Sevmekten...', 'Her şeye yeniden başlamanın zamanı geldi artık  Eski bir kitabı kurtarıp tozlu rafların tutsaklığından  Okumaya başlamalı eksik kalmış yerin...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/her-seye-yeniden-baslamanin-zamani-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidersem gelmem bir daha', 'gidersem-gelmem-bir-daha-vedat-fazil-4ejsq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gidersem dönmem birdaha canyoldaşım

sebebini  sende biliyorsun.....! 

Alışık değilim kapılarda beklemeye sırdaşım

ac şu kapıyı gölgemi görüyorsun

Ay ışıgında kuru ayazı soluyorum

ellerim buz tutdu yavaş yavaş tutuluyorum

              Birazdan Ayda batacak sanki buracıkta unutuluyorum

Özledim seni neden geldiğimi sor arala perdeyi

biliyorum unutursun bu geceyi

Ögretemedim can yoldaşım sana ben gibi sevmeyi

ögretemedim gidenleri beklemeyi

               Haydi sokak kararıyor etrafımda meraklı gözler

belkide yarın benden söz ederler

sana sarhoş olduğumu söylerler

kim bilir bizim için ne derler

Ac şu kapıyı gözlerine sana hasretim

Biliyormusun yıllarca gurbetin kahrını cektim

               Koymadı yüreğime hasret böyle incitmedi gurbet

Bedenim duygusal ayaklarım derki''cek git''

Gidersem gelmem canyoldaşım

bu sana son gelişimdi 

biliyorum bu bir delilikti

eh.....! serde sevda var kabına sıgmadı yürek dünya dar

öldürür gayri sag koymaz bu yaralar

gidiyorum geldiğim diyarlara

gidiyorum isimsiz kör sevdalara

                   GİDİYORUM CANYOLDAŞIM', 'Gidersem dönmem birdaha canyoldaşım sebebini  sende biliyorsun.....!  Alışık değilim kapılarda beklemeye sırdaşım ac şu kapıyı gölgemi görüy...', ARRAY['Türk Edebiyatı','Şiir','Vedat Fazıl']::text[], 8.5, '{"poet":"Vedat Fazıl","poet_slug":"vedat-fazil","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gidersem-gelmem-bir-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-bedihi-kazim-nasuhbeyoglu-jwb7i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ümit var mı bilmem ki; 

Baharımda kışımda.

Ölüm vahşi bir kartal,

Dolanmakta başımda.

Akmıyor durulmuyor, 

Gitmiyor yorulmuyor; 

Neş''eye varılmıyor,

Elem gömlek dışımda.

Ne renk var gündüzümde,

Ne tebessüm yüzümde, 

Eyvah sönmüş gözümde, 

İncili gözyaşımda. 

17/02/1947, Erzurum', 'Ümit var mı bilmem ki;  Baharımda kışımda. Ölüm vahşi bir kartal, Dolanmakta başımda. Akmıyor durulmuyor,  Gitmiyor yorulmuyor;  Neş''eye var...', ARRAY['Türk Edebiyatı','Şiir','Bedihi Kazım Nasuhbeyoğlu']::text[], 8.5, '{"poet":"Bedihi Kazım Nasuhbeyoğlu","poet_slug":"bedihi-kazim-nasuhbeyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bekleyis-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle', 'soyle-bedihi-kazim-nasuhbeyoglu-sc2fq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söyle bir gün gurbet ele, 

Gelir misin gelmez misin? 

Beni ölmüş görsen bile, 

ölür müsün, ölmez misin? 

Deseler ki:Eni kona, 

Ezdi, büktü ölüm ona; 

Bu dünyanın hicran sonu, 

Kalır mısın, kalmaz mısın? 

Deseler ki:Andı gitti, 

Izdıraptan kandı gitti; 

Yâr uğruna yandı gitti,

Bilir misin, bilmez misin? 

Hem desen ki: Bedihî gel, 

Aman verdi sana ecel; 

Şu gönlümde sağlam temel, 

Bulur musun, bulmaz mısın? 

24/2/1948, Erzurum', 'Söyle bir gün gurbet ele,  Gelir misin gelmez misin?  Beni ölmüş görsen bile,  ölür müsün, ölmez misin?  Deseler ki:Eni kona,  Ezdi, büktü ö...', ARRAY['Türk Edebiyatı','Şiir','Bedihi Kazım Nasuhbeyoğlu']::text[], 8.5, '{"poet":"Bedihi Kazım Nasuhbeyoğlu","poet_slug":"bedihi-kazim-nasuhbeyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/soyle-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek Kürü', 'dilek-kuru-bedihi-kazim-nasuhbeyoglu-2ng1d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ak göğsüne cehlin oku, 

Dalı versin dalı versin.

Şaşkın kula Tanrım doğru, 

Yolu versin, yolu versin.

Arslanı yesin kediler, 

Bitsin bu dedim dediler,

Ah ''gidiler, hey gidiler, 

Geliversin, geliversin.

Dostun gözü devran görsün,

Saran sarsın; vuran vursun.

Feleğin fitnesi dursun, 

Oluversin, oluversin.

Dik başıma taş atılsın, 

Düşmana alkış tutulsun,

Katılan seyre katılsın, 

Gülüversin, gülüversin. 



Çalan çalsın havasını,

Dolduran doldursun tasını.

Hışım hısımdan hırsını, 

Alıversin, alıversin.

Kanım kına, vuran ele, 

Kazmalar girsin temele, 

Kin kadehi dönsün hele; 

Doluversin, doluversin.

Coşu versin kakışanlar, 

Eylensin mala koşanlar,

Eli saza yakışanlar, 

Çalıversin, çalıversin.

Heyheyler sarsın ovayı, 

Beyler kazandı davayı, 

Tanrım kaybolan deveyi, 

Buluversin, buluversin.

Gün dönsün ufku dolaşsın,

Damla denize ulaşsın,

Kurt kemirsin,çınar düşsün,

Ölüversin, ölüversin.

Kargalar aksın üstüne,

Namertler çöksün postuna, 

Tanrım Karun''un dostuna, 

Pulu versin, pulu versin.

Düğün olsun,dernek olsun,

Mert ağlasın namert gülsün,

Fitne dursun kin durulsun,

Kalıversin, kalıversin.

Dönsün dünya dönsün devir, 

Yalan dolan,sahte tavır,

Dolap çevir,plân kıvır, 

Malı versin, malı versin.

Para putun dev olmalı,

Irmaklar sana dolmalı,

Döndükçe döviz gelmeli,

Kulu versin, kulu versin.

Sana deniz,bize damla, 

Tanrı bize bu makamla,

Tuz, ekmek, mitil, yorganla,	

Çulu versin, çulu versin.

						4/9/1970', 'Ak göğsüne cehlin oku,  Dalı versin dalı versin. Şaşkın kula Tanrım doğru,  Yolu versin, yolu versin. Arslanı yesin kediler,  Bitsin bu dedi...', ARRAY['Türk Edebiyatı','Şiir','Bedihi Kazım Nasuhbeyoğlu']::text[], 8.5, '{"poet":"Bedihi Kazım Nasuhbeyoğlu","poet_slug":"bedihi-kazim-nasuhbeyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/dilek-kuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıldırıyorum.', 'cildiriyorum-hayrettin-orak-62l1p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geceler senin yokluğunda zindan oldu geçmez oldu,

Gündüz benim için hayat güneşi doğmaz oldu,

Göz yaşlarım kurudu, pınarlarım akmaz oldu,

Kalbimde sevdanla yaşattığım sevgi gülüm soldu,

Yaralandım bir kere, bir daha sevmekmi, Asla.....! 

Seninle dolaştığımız sokaklarda sensiz gezemiyorum,

Birlikte dinlediğimiz şarkımızı artık dinlemiyorum,

Sensiz geçmeyen günler içinde zamanla boğuşuyorum,

Ayrılık vurgunu yemiş sevdamıza hıçkırarak ağlıyorum,

Sensiz zorda olsa yaşamaya çalışıyorum.

Şu köhne duvarda asılı duran resmine bakıyorum,

Gidişin benim için sanki bir rüya, inanamıyorum,

Ellerimi uzattım, senin ellerini arıyorum,

Biliyorum yoksun artık bana uzaksın,

Yinede içimde olan ümidi besliyorum.

Gittiğin o günden bu yana hep ağlıyorum,

Sevda bahçesinin kapısında senin gelmeni bekliyorum,

Bir korku sarıyor bedenimi, üşüyor, ürperiyorum,

Sensizliğin dondurucu soğuğunu içimde hissediyorum,

Yeter yeter sabrım kalmadı, Çıldırıyorum..........! 

20.11.2004', 'Geceler senin yokluğunda zindan oldu geçmez oldu, Gündüz benim için hayat güneşi doğmaz oldu, Göz yaşlarım kurudu, pınarlarım akmaz oldu, Ka...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cildiriyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasır', 'nasir-nurten-koroglu-s8plj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Artık üzmüyor 

Ayrılıklar beni

Nasır mı tuttu ne

Sevmeyi bilen

Pamuk kalbim', 'Artık üzmüyor  Ayrılıklar beni Nasır mı tuttu ne Sevmeyi bilen Pamuk kalbim...', ARRAY['Türk Edebiyatı','Şiir','Nurten Köroğlu']::text[], 8.5, '{"poet":"Nurten Köroğlu","poet_slug":"nurten-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/nasir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-nurten-koroglu-kpko4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şafaktan önce gideceğim buralardan

Sırtımda taşıyamadığım sevdan

Sonu gelmeyen vurdumduymazlığından, ayrılığından

Değmeden mutluluğunun ucuna

Usta bir cambaz maharetiyle

Sıyrılıp gideceğim buralardan

Bir gün

Bir  gün bu sesi,bu bekleyişi özleyeceksin

Bıraktığın yerde olmayacak o demir atmış aşk

Dudaklarımı, tenimi hatırladığın o gün uzaklardan

Belki bir fırtına,belki de bir tayfun hızıyla

Savrulup gitmiş olacağım buralardan', 'Şafaktan önce gideceğim buralardan Sırtımda taşıyamadığım sevdan Sonu gelmeyen vurdumduymazlığından, ayrılığından Değmeden mutluluğunun ucun...', ARRAY['Türk Edebiyatı','Şiir','Nurten Köroğlu']::text[], 8.5, '{"poet":"Nurten Köroğlu","poet_slug":"nurten-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-gun-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-suleyman-yavuz-nz4vn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen gönlümde bir gül 

Sen yürekte yara

Derman olmaz lokman hekimler bana

Bu yürek seni ister. 

Ölüm bana kurtuluş 

Sensiz yaşamak bana zaten yok oluş

Bu beden sensiz 

Neden bu gidiş nedensiz.

Şimdi gittin yabana

Ölüm bir tatlı yoldur bana

Ya sen gel al

Ya da ben kıyacağım bu cana.', 'Sen gönlümde bir gül  Sen yürekte yara Derman olmaz lokman hekimler bana Bu yürek seni ister.  Ölüm bana kurtuluş  Sensiz yaşamak bana zaten...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-477-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buruk', 'buruk-ali-fikri-karadeniz-9tuex', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir burukluk sarar beni

Akşam kızıllığında dudaklarını boyarım

Gün yavaş yavaş ağırır da

Saçlarıma beyaz gölgeler düşer

Yine Sana şarkılar fısıldarım…

Bir burukluk sarar beni

Sarar hasret sarmaşıkları

Sevgime bir ateş düşer

Önce yakar derinden

Sonra korlaşır bedenimde

Ben Sensiz yanarım bu sahilde…

Bir burukluk sarar beni

Haykırmak isterim denizlere

Dağları deviririm ardından

Bulutlar ismini yazar göklere

Sonra gün batar

Karanlıklara bürünür dünyam

Ve ben; 

Yine Sensiz geçen günüme yanarım

Kimseler anlamasın diye

Hasret yağmurlarında ağlarım…! 

					19/11/2004', 'Bir burukluk sarar beni Akşam kızıllığında dudaklarını boyarım Gün yavaş yavaş ağırır da Saçlarıma beyaz gölgeler düşer Yine Sana şarkılar f...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/buruk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu aşkın sırrını çok iyi gizle', 'bu-askin-sirrini-cok-iyi-gizle-musa-kalkinc-hbkaz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu aşkın sırrını çok iyi gizle

Ne gören ne bilen ne duyan olsun

Gönülden sev beni gönülden özle

Ne gören ne bilen ne duyan olsun

Bilmeyen anlamaz bu sevgimizi

Kırarlar aşk dolu kalplerimizi

Gizlice buluşan ellerimizi

ne gören ne bilen ne duyan olsun', 'Bu aşkın sırrını çok iyi gizle Ne gören ne bilen ne duyan olsun Gönülden sev beni gönülden özle Ne gören ne bilen ne duyan olsun Bilmeyen an...', ARRAY['Türk Edebiyatı','Şiir','Musa Kalkınc']::text[], 8.5, '{"poet":"Musa Kalkınc","poet_slug":"musa-kalkinc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bu-askin-sirrini-cok-iyi-gizle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitsin', 'bitsin-suleyman-yavuz-cxud7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bitsin bu bendeki sen

Gitsin kalbimden

Sevmem seni bir daha 

İstemem görmeyi yüzünü 

Çık git evimden barkımdan

Kaybol şu hayatımdan

Terk et beni 

Sil aklından def et beni

Yettin artık bu cana

Yıktın beni 

Artık bırak ta yakamı 

Kurayım sensiz hayatı

Unuttum bil seni.', 'Bitsin bu bendeki sen Gitsin kalbimden Sevmem seni bir daha  İstemem görmeyi yüzünü  Çık git evimden barkımdan Kaybol şu hayatımdan Terk et ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bitsin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihat', 'nasihat-serkan-karabulut-jynk0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bak şu mezarda yatana

Okunmuyor esamesi taşta

Oda yolcuydu bu handa

Şimdi yatıyor beş karış toprak altında 

Oğul es geçme oku fatiha

Bir gün olur ihtiyacın dua

Anla bak fani dünya

Kanma mülküne malına

Bu nasihat sana

Sanma babandan uydurma

Kelamıdır ALLAH’ın yazılıdır Kur’an da

Lütfüdür insanlığa okursan canla', 'Bak şu mezarda yatana Okunmuyor esamesi taşta Oda yolcuydu bu handa Şimdi yatıyor beş karış toprak altında  Oğul es geçme oku fatiha Bir gün...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nasihat-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-serkan-karabulut-cdb78', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Garibim bak ne haldeyim

Sormaz kimse halimi 

Gurbete düştüm düşeli

Gecem zehir zemberek

Derde düşen halı başka 

Görüp soranların başka 

Dost görür sormaz başta

Ağlayan anam yok ardımda

Yaktım sigara 

Demlendi cay koydum bardağa

Yanıktır sesim söylendim dağa taşa

Ömrüm aktı hep gözyaşımla

Ağlanma Serkan ağlanma

Şükredenin hali olur başka

Sabreden erer murada

Ahir ömür unutma', 'Garibim bak ne haldeyim Sormaz kimse halimi  Gurbete düştüm düşeli Gecem zehir zemberek Derde düşen halı başka  Görüp soranların başka  Dost...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gurbet-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezanla geldik sela''yla gideriz', 'ezanla-geldik-sela-yla-gideriz-memmet-ata-demirdag-6x65p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doğmuş gelmişiz dünyaya

Bir ismimiz var konmuş ezanla

Korumalı onu şerefle,şanla

Dost uğruna ölürüz kanla

Sen benim dostumsan anla

Sevgimiz bile yürekle,canla

Azmı yandı bu yürek sevdanla

Namerde muhtaç olmaktansa

Çekip gitmek yaraşır...............

Bir sabah erkenden sela''yla', 'Doğmuş gelmişiz dünyaya Bir ismimiz var konmuş ezanla Korumalı onu şerefle,şanla Dost uğruna ölürüz kanla Sen benim dostumsan anla Sevgimiz ...', ARRAY['Türk Edebiyatı','Şiir','Memmet Ata Demirdağ']::text[], 8.5, '{"poet":"Memmet Ata Demirdağ","poet_slug":"memmet-ata-demirdag","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ezanla-geldik-sela-yla-gideriz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senli Sensiz', 'senli-sensiz-suleyman-yavuz-35nlm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senli yada sensiz 

Yaşamıyor hayat hiç geçmiyor 

Benli yada bensiz senin için 

Bilirim hiç fark etmiyor

Çünkü biz ayrıldık

Şimdi ben sensiz 

Sense bensiz 

Kala kaldık bu dünyada

Sen uzak bir şehir gibisin bana

Ben sana güneşten daha uzak 

Şimdi sen diye çarpar yürek 

Bilmem bu senin için ne demek

Ama şunu biliyorum sen benim için

Sevgi aşk ve yürek

Ama anlamadın beni

Sana bir kalp gerek birde sevgi 

Bir gün belki anlarsın beni.', 'Senli yada sensiz  Yaşamıyor hayat hiç geçmiyor  Benli yada bensiz senin için  Bilirim hiç fark etmiyor Çünkü biz ayrıldık Şimdi ben sensiz ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/senli-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-suleyman-yavuz-birm6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi hayat çekilmez 

Sensiz günler geçmez

Gülmeler beni seçmez

Ağlamalar düşer bana

Bir de yanmalar

Yansam da ne fayda 

Sen yoksun ya yanımda

Kül olmam ben asla

Beklerim hep seni

Bilirim seveceksin sende bir gün beni

Ne hayal ne rüya

Bendeki bu umut bitmez asla

Sen olmasan da yanımda

Yaşatırım seni 

Bir gün sevecekmişsin gibi beni

Bilirim dönmeyeceksin geri

Olsun ölüm olsa da sonunda seveceğim seni

Ne ayırır bu bendeki seni 

Belki dönmen belki ölüm 

Ama unutma sen sevmesen de beni 

Asla unutmam 

Unutamam asla seni.', 'Şimdi hayat çekilmez  Sensiz günler geçmez Gülmeler beni seçmez Ağlamalar düşer bana Bir de yanmalar Yansam da ne fayda  Sen yoksun ya yanım...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevmek-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ADI AŞK(Akrostiş)', 'adi-ask-akrostis-muzaffer-erdogan-q6vtu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'A klın başında değilse iyi düşün

D aha bi başkalaşır gülüşün

I zdırap verir, bulamazsın çıkışı hızlı olur düşüşün

A nsızın çıka gelir gönlünü taşlar

Şansım buymuş dersin hasret başlar

K aderimiş diyemezsin süzülür  gözünde yaşlar.', 'A klın başında değilse iyi düşün D aha bi başkalaşır gülüşün I zdırap verir, bulamazsın çıkışı hızlı olur düşüşün A nsızın çıka gelir gönlün...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Erdoğan']::text[], 8.5, '{"poet":"Muzaffer Erdoğan","poet_slug":"muzaffer-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/adi-ask-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açan Gülsün Hazanıma', 'acan-gulsun-hazanima-sadik-softa-prml7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geceler uzayıp sardı,

Sen gelmedin uykulara,

Tan gözüktü,saç ağardı,

Çığlar düştü şakaklara.

Sensiz esti seher yeli,

Karanlık senden eveli,

Gözlerinden ışık seli,

Beni sürüyor ahlara.

Bahtımdan yıldızlar düşer,

Ahımdan yüreğim pişer,

Uykusuz gözlerim şişer,

Gün dizilir eyvahlara.

Düşer ellerim yanıma,

Hükmedersin zamanıma,

Açan gülsün hazanıma,

Beni bırakmaz vahlara.

Düşer son kalesi düşün,

Hayallerde görünüşün,

Beni çeker süzülüşün,

Ferman okutur şahlara.

Çankırı-29.10.2004', 'Geceler uzayıp sardı, Sen gelmedin uykulara, Tan gözüktü,saç ağardı, Çığlar düştü şakaklara. Sensiz esti seher yeli, Karanlık senden eveli, ...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/acan-gulsun-hazanima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tülây Hanımın Fendi Mustafa Beyi Yendi', 'tul-y-hanimin-fendi-mustafa-beyi-yendi-ozkan-gonlum-r9iuo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''''ÖZLÜ'''' ailesinin

		Yoktur gamı tasası.

		Mutlu yaşayıp gidiyor

		Tülay hanımla Mustafa''sı.

		Ama bir şey var ki

		Keyfe keder.

		Tülay hanım onu da 

		Halleder.

		Dolup taşsa da 

		Mutfaktaki çöp kovası.

		Bir türlü dökmüyordu

		Emekli kocası.

		Mustafa bey her zaman

		Karısının sesini

		Kulak ardı ediyor

		Dinlemiyordu söylenen sözü.

		Elindeki gazetede

		Televizyondaydı gözü.

		Tülay hanım ne yapsın

		Belki çare olur diye

		Görsün diye işini

                                Bir gün işveyle

		''''Mustafa çööp

		Gel beni öööp'''' diye

		Çağırdı eşini.

		Olan olmuştu

		İşte o günden sonra

		Bu söz yerini bulmuştu

		Çöp işi bir öpücükle

		Hallolmuştu.

		Şimdi, Mustafa beyin

		Kulağı her an

		Hanımının sesinde

		‘’Mustafa çöööp

		Gel beni öööp'''' desin de 

		Yerinde durur mu hiç 

		Tetikte bekliyor Mustafa bey

		Hanımı öpmek için

		Çöpleri dökmek için.

		Bu işi duyunca 

		Dostları Nizamettin bey

		Dedi ki hanımına

		Sen de karıcığım

		Seslensen bana

		''''Nizamettin çöööp

		Gel beni öööp'''' diye

                                

                                 Al sana yemin

                                 Değil bizim evin

                                 Komşularında kahrını çekerim

                                 Sen öpücük verdikçe bana

                                 Mahallenin bile çöpünü dökerim.', '''''ÖZLÜ'''' ailesinin 		Yoktur gamı tasası. 		Mutlu yaşayıp gidiyor 		Tülay hanımla Mustafa''sı. 		Ama bir şey var ki 		Keyfe keder. 		Tülay han...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/tulay-hanimin-fendi-mustafa-beyi-yendi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak İstiyorum', 'aglamak-i-stiyorum-osman-karaarslan-x4jr3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her akşam üstü bu saatlerde

Alev kokulu tufanlar çöküyor

Bakir umutların ense köküne..

Dev bir örümcek misali çaresizlik

Çelikten ağlar örüyor yüreğime.

Yaslanıp bir duvar dibine

Ağlamak istiyorum.

Her gece bu saatlerde,

Ak kefenlere bürünmüş

Uzanmış yatıyor 

Musalla taşında saadetler..

Sadakat sudan ucuz

Para etmiyor vefa.

Sabahı olmayan

Ölüm uykusunda yüreğim,

Karabasanlarla boğuşuyor.

Hangi ele uzansam,

Hangi dala tutunsam kâr etmiyor.

Çaresiz 

Ağlamak istiyorum...

Her ayrılık saati vurduğunda

Kimsesiz bir deniz ortasında

Yedi başlı ejderha gibi

Vahşi dalgalar dövüyor yüreğimi

Üşümek,

Yanmak,

Yok olmak arası bir şey.

Çaresiz

Ağlamak istiyorum.

Ağlamak ayıpmış, kimin umurunda...

Ağla ağlayabildiğin kadar..', 'Her akşam üstü bu saatlerde Alev kokulu tufanlar çöküyor Bakir umutların ense köküne.. Dev bir örümcek misali çaresizlik Çelikten ağlar örüy...', ARRAY['Türk Edebiyatı','Şiir','Osman Karaarslan']::text[], 8.5, '{"poet":"Osman Karaarslan","poet_slug":"osman-karaarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/aglamak-istiyorum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Celse...', 'celse-naime-erlacin-pidej', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'oltada yitirir dirimi solucan ve balık

ne yapsın balıkçı iki ölüm arasında

açamadığı kapılar da mevcut bilgenin

umudun pas tuttuğu insan sancısında

bakarsın nehir sesine sağırlaşır dere yatağı

kepengi indiriverir zaman

dirilerek gelir ölüm kimi kentlere

muafiyet kazanmış mikrop gibi 

isyandır doğuştan eksikliğine

özrüne ağlar orada yasa 

karınca 

böcek 

her neyse

tek bir yapraktır bazen ağlayan

bir durur 

bir devinir can

sırtından akarken hayat

ne farkı var 

ince bir acının kalından

özgürdür deniz

doğaya dikleşen tohum kadar 

kara

tedirgin celse

ve süzülür infaz kararı imbikten

balıkçı ne yapsın! 

(20 Kasım 2004)', 'oltada yitirir dirimi solucan ve balık ne yapsın balıkçı iki ölüm arasında açamadığı kapılar da mevcut bilgenin umudun pas tuttuğu insan san...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/celse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleyin', 'soyleyin-rifki-kaymaz-8shpa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Söyleyin,söyleyin, kuşlar söyleyin

Ne zaman gelecek. bahar ne zaman? 

Sevincin çevreyi kuşattığı an,

Bir ışık doğacak,  bir geceleyin.

O gün çiçeklenir; bağlar, bahçeler

O gün hava tertemiz, çiçekler hür...

Dört bir yandan, hep mutluluk dökülür,

Nokta nokta aydınlanır geceler.', 'Söyleyin,söyleyin, kuşlar söyleyin Ne zaman gelecek. bahar ne zaman?  Sevincin çevreyi kuşattığı an, Bir ışık doğacak,  bir geceleyin. O gün...', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/soyleyin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Buz Susku...', 'buz-susku-naime-erlacin-t7to4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yapay sancılardan doğdu eğretilik

şeffaf tümörler göverdi duygularda

en kısa düşenlerdi hayata

bir ayrılık

bir yalnızlık

bir ölüm vardı

inzivaya sarıldı ayrılık

taşısa ancak 

söz taşırdı yükümü

cenazesini gözlerimin 

bir o kaldırırdı

ölümü kıyıda bırakıp 

buz bir suskuya yatırdım dilimi

kum masallar bağışlandı 

ak kâğıtlara

al üstümden bu kederi ey şiir! 

gidecek yolum var daha

(20 Kasım 2004)

(''ŞİKÂYETNAME, Hayal Yay. Temmuz 2010, Sayfa 78)', 'yapay sancılardan doğdu eğretilik şeffaf tümörler göverdi duygularda en kısa düşenlerdi hayata bir ayrılık bir yalnızlık bir ölüm vardı inzi...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/buz-susku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '°°° Bu Vasiyetimdir Sana °°°', 'bu-vasiyetimdir-sana-gulsen-senderin-uew7o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Belki bugün belki yarın, sıra bana da gelecek

Doğaya, zamana yenik düşen şu kalbim duracak

Kimbilir kimler duyacak, kimler gözyaşı silecek

Sevdasıyla acısıyla, bu sevgi yarım kalacak

Kalbimizi süsleyen aşk, bil ki bir hayal olacak! 

Giderken özleyeceğim, gözlerindeki ateşi

Buz, soluk renkli bedenim hissetmeyecek güneşi

Odamda ışık sönecek, yitecek evin neşesi

İlkkez yanmayacak tütsüm, kokmayacak gül şişesi

Giydirdiğim tüm özlemler, bil ki bir hayal olacak! 

Susmuş olacak kalemim, ağlayacak tüm anılarım

Duygu dolu şiirlerim, notta kalan yazılarım

Dinlenmeyecek TRT dörtten sana adak şarkılarım

Fincanımda kuruyacak, kahve falı umularım

Güne soyunan duygular, bil ki bir hayal olacak! 

Bu vasiyetimdir sana; kışın lale nergiz sümbül

Yazın sarı papatyalar, baharda gelincik gül

Sonbaharı hiç düşünme, sarı yapraklar dost bir el

Üşüyen toprağa örtü, hüzün dolan kalplere tül

Aşka duran manolyamız, bil ki bir hayal olacak

İstemem ne yas tutmanı, ne yaş dökmeni ardımdan

O sevdiğim ''SARI GÜLLER'' dizi gonca ''YASEMENLER'' 

Mezarımı hep süslesin, sakın kaçma bu yardımdan

Yattığım yer yeşil olsun, solmasın asla çimenler

Sen de yoksan bu dileğim: BİL Kİ BİR HAYAL OLACAK! 

 

.', 'Belki bugün belki yarın, sıra bana da gelecek Doğaya, zamana yenik düşen şu kalbim duracak Kimbilir kimler duyacak, kimler gözyaşı silecek S...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bu-vasiyetimdir-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-kenan-sahbudak-ohcg8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönlüm seni arar her an her yerde

Dağlara taşlara soram nerdesin

Senin için düştüm tükenmez derde

Kaşları gözleri karam nerdesin

Bülbülün gülüne erdiği gibi

Garibin yurduna vardığı gibi

Suların toprağı sardığı gibi

Yıllanmış hasretle saram nerdesin

Gör neler çektirdin bu Şahbudağa

Benzettin açmadan solan yaprağa

Girmeden sevdiğim kara toprağa

Dünya gözü ile görem nerdesin', 'Gönlüm seni arar her an her yerde Dağlara taşlara soram nerdesin Senin için düştüm tükenmez derde Kaşları gözleri karam nerdesin Bülbülün gü...', ARRAY['Türk Edebiyatı','Şiir','Kenan Şahbudak']::text[], 8.5, '{"poet":"Kenan Şahbudak","poet_slug":"kenan-sahbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nerdesin-94-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Geliyor', 'hayal-geliyor-gulsen-senderin-px9gj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Doğduğum dağlık köy nerede şimdi

Özlemi kalbimi yakıp deliyor

Göç ediş olmadan dünyam köyümdü

...Yetmişdörtten sonra hayal geliyor! 

Meyve ağaçları köyü kucaklar

Her mevsim çiçekler, sevgi duvaklar

Bağ bahçe ovalar, uzun kavaklar

Harup pekmez şıra; hayal geliyor! 

Ben miydim dağlarda mantar toplayan

Keklikler tavşanlar ceylanlar tutan

Zeytinden asmaya diktiğim fidan

Yıkandığım dere; hayal geliyor! 

Trodos eteğinde kuzular meler

Kavalın çağrısı bağrımı deler

''BERAVASA'' cami kurumuş derler

Güneydeki yöre; hayal geliyor! 

DAĞAŞAN yemyeşil verim dört yanı

Pelit çınar selvi süsler ormanı

Sarı sarı açar diken azganı

Mis kokan manzara; hayal geliyor! 

Üç gün üç geceli, düğünler bitti

Kına geceleri, kırılan testi

O HERSE kokusu burnumda tüttü

Ak ak hatıralar; hayal geliyor! 

Kıbrıslı''yım özde yanar meş''ale

Türk''ün toprağını koyma işgale

Bitmeyen söylemler bir boş meşgale

Esaret ellere; HAYAL GELİYOR! 



Gülşen Şenderin 

.', 'Doğduğum dağlık köy nerede şimdi Özlemi kalbimi yakıp deliyor Göç ediş olmadan dünyam köyümdü ...Yetmişdörtten sonra hayal geliyor!  Meyve a...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hayal-geliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ver Anne', 'ver-anne-suyum-gozyasi-witom', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anne 

Oyle yetistirdi ki 

Babam beni

Biri haricinde

Hayatim boyunca 

Tuttum tum sozlerimi

Yasamaya mecbur 

Bu burukluk icinde

Bana tutmaktan korktugum

Sozumu ver anne

Anne

Senin ozunde olusup

Dogdugum gunden beri

Atamamisken caresiz

Bir adim ileri

Yetmiyormus da sanki

Gozyaslarimla gittim geri

Tukenmeden sevgisiz

Bana gozlerimde tutamadigim

Ozumu ver anne

Anne

Cok ozledim

Gucum yettigince kosmayi

Icimi bal tadinda

Nefeslerle doldurmayi

Dunyami cennet yapan

Uzuntumu aska saran

Gunlerde yasamayi

Bana ikinci kez dogdugum

Gunumu ver anne

Anne 

Ben yarini olmayan

Gunlerde cabalarken

Oylece mutsuz

Mutlulugum gecmiste kaldi

Umutsuzlugum beni

Sancilar icinde

Delice parcalarken

Bana mutlu oldugum 

Dunumu ver anne

Anne

Yasayamiyorumki

Yasiyorken son bulacagini

Ummadigim bir kabus icinde

Oscara aday bir filmin

Cekilememis sahnesinde

Olmeyi umarken

Cigliklarin tizinde

Bana tadina doyamadigim

Omrumu ver anne

Anne 

Sevemiyorumki

Bir imkansizligi seviyorken

Imkan saglayan hic bir seyi

Iki dunya arasina sikisan

Ozgurlugu esarette iciyorken

Unutmusum sevgiyi

Beni anlamlandiran

Bana yanginlarda yitirdigim

Gonlumu ver anne

Anne

Gunesim dogmuyor artik

Yagmurlarin yerine

Karanliklar yagiyor

Bulbulleri goc etmis

Cicekleri solmus

Erozyonlara mecbur

Oksuz kaldi bahcelerim

Bana beni anlatan

Gulumu ver anne

Anne

Sizin icin varim

Ama itimat et bana

Herseyim yarim

Aglamaktan degil ama

Arada bogulmaktan

Dirhem dirhem oylece

Korkulara dalarim

Bana boyle kiyacaksan

Olumu ver anne', 'Anne  Oyle yetistirdi ki  Babam beni Biri haricinde Hayatim boyunca  Tuttum tum sozlerimi Yasamaya mecbur  Bu burukluk icinde Bana tutmaktan...', ARRAY['Türk Edebiyatı','Şiir','Suyum Gözyaşı']::text[], 8.5, '{"poet":"Suyum Gözyaşı","poet_slug":"suyum-gozyasi","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/ver-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öleceğinle bir geldin,gideceğinle de bir gez..', 'oleceginle-bir-geldin-gideceginle-de-bir-gez-sair-ahrazi-bd92f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bin hayat bulsam da ben,candan olsam bin defâ,

Dursa mihmandar zaman umduğum gün şefkati,

Seyret ey târif derim,susmasın tek kavramın,

Aşka vermişken bu cân sağ yanımdan hilkati,

Bir avuç toprak kadar hükmü yok kadavramın…

En son uzvumdur o gün,tâ ki mahşerden bakan,

Elvedâ derken cihan ilk nefestir aldığım.

Münkir olmuş ahbâbım,geçmişim ben gâibi,

Yalnız,akşam vaktidir,bir ömürlük kaldığım,

Bitmiştir hem mâtemim hoşça kalsın der gibi…

* * *', 'Bin hayat bulsam da ben,candan olsam bin defâ, Dursa mihmandar zaman umduğum gün şefkati, Seyret ey târif derim,susmasın tek kavramın, Aşka ...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/oleceginle-bir-geldin-gideceginle-de-bir-gez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koparsak eğer! ..', 'koparsak-eger-ferit-teksoy-ayw0t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yağmur dışarda yağmaz

cam buğuyu kaybeder

ağlar serçe

bir gün.. 

koparsak eğer! ..

jübilesi olur bu son drama

esas oğlan üzgün 

sahneden iner

son perdesi biter 

rezil oyunun

söner ışık..

kapanır tüm perdeler

kırılır atın ayağı

sendeler

dörtnal koşarken

sadece sana

tetiği çekmek düşer

bir gün.. 

koparsak eğer! ..

20 Kasım 2004', 'yağmur dışarda yağmaz cam buğuyu kaybeder ağlar serçe bir gün..  koparsak eğer! .. jübilesi olur bu son drama esas oğlan üzgün  sahneden ine...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/koparsak-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrım', 'tanrim-murat-karatekin-gdmwd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tanrım neden aldın beni hayatın keskin kıskacına

Ben ne yaptım sana, hırpalıyorsun beni

Ruhumun her noktasında.

Tanrım  neden sığınırız sana her açmazımızda

Bu kadar acizsek bizi neden gönderdin,

Bu binbir saçmalığın olduğu dünyaya

Tanrım bu kadar çıkmaz neden acaba

Mutluluğu koymuşsun labirentin başına

Bizede kaybolmak kalıyor odacıklarda

Tanrım aşk neden bu kadar zor diye,

Haykırmak istiyorum sana.

Sonra vazgeçiyorum sen TEK-tin ya.

Tanrım ben neden insanım sorarım sana

Bir bitki olmak varken şu dünyada

Mahlukatın en şereflisi oldum sözüm ona.

Tanrım ölüm hoş güzel ama neden günah dedin

Kendi canımı almaya

Imtahandan kalmak istiyorum ben bu koca dünyada.

Tanrım insanım ama,

Sen mutlusundur umarım

Bu karmaşada…

MK…', 'Tanrım neden aldın beni hayatın keskin kıskacına Ben ne yaptım sana, hırpalıyorsun beni Ruhumun her noktasında. Tanrım  neden sığınırız sana...', ARRAY['Türk Edebiyatı','Şiir','Murat Karatekin']::text[], 8.5, '{"poet":"Murat Karatekin","poet_slug":"murat-karatekin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tanrim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tozlu Bir Sevda', 'tozlu-bir-sevda-faruk-tekin-khx9k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yudum sevdamız,

Düğümleniyorsa boğazımıza,

Anıların yanık yırtık sayfalarına,

Takılıp kalmanın bir anlamı yok.

Bırak ve eksiklerle yaşamaya çalış,

Şu inadına mavi gökyüzünün altında.

Say ki; şarabın esrikliği,

Aşkın da tadıdır,

Bu biçare hayatın içinde.

Umudun nefesi tükenmesin,

Yeter ki yolun orta yerinde.

İstersen yarim sevdalarını da sakla,

Oyalı bir gelin bohçasına.

Kalakalsın naftalin kokulu ceviz sandığın köşesinde.

Aradığında çıkarmak üzere.

Artık gittiğim gurbetler evimse,

Sıla şimdi gurbet geliyorsa,

İlkbahar yaprak dökmüş bana ne!', 'Bir yudum sevdamız, Düğümleniyorsa boğazımıza, Anıların yanık yırtık sayfalarına, Takılıp kalmanın bir anlamı yok. Bırak ve eksiklerle yaşam...', ARRAY['Türk Edebiyatı','Şiir','Faruk Tekin']::text[], 8.5, '{"poet":"Faruk Tekin","poet_slug":"faruk-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/tozlu-bir-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesap Hatası', 'hesap-hatasi-faruk-tekin-yrcb4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hangi rüzgarlar getirir nefesini? 

Hangi çiçekler kokunu verir ki? 

Böyle darmadağın olmuşken,

Kim toplar beni yeniden? 

Oysa ayrılığı hesap etmemiştim hiç.

Bu yüzden toplamlarım yanlış çıkıyor hep.', 'Hangi rüzgarlar getirir nefesini?  Hangi çiçekler kokunu verir ki?  Böyle darmadağın olmuşken, Kim toplar beni yeniden?  Oysa ayrılığı hesap...', ARRAY['Türk Edebiyatı','Şiir','Faruk Tekin']::text[], 8.5, '{"poet":"Faruk Tekin","poet_slug":"faruk-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hesap-hatasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sekseninde Bir Kadın', 'sekseninde-bir-kadin-menevis-koylu-mn74r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sekseninde Bir Kadın (Menevşe Köylü)

Bir kadın 

Sekseninde 

Bisiklet üstünde geçer sokaktan 

Nereden gelir 

Nereye gider bilinmez 

Soğuk ve yağmurlu günlerde 

Üşürüm onu düşünürken 

O üşümez 

Ağzında ıslanmış sigarasıyla 

Yine geçer gözlerimin önünden', 'Sekseninde Bir Kadın (Menevşe Köylü) Bir kadın  Sekseninde  Bisiklet üstünde geçer sokaktan  Nereden gelir  Nereye gider bilinmez  Soğuk ve ...', ARRAY['Türk Edebiyatı','Şiir','Meneviş Köylü']::text[], 8.5, '{"poet":"Meneviş Köylü","poet_slug":"menevis-koylu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sekseninde-bir-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrüm', 'omrum-erdem-nur-cengiz-75oyc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öncesizliği ve belki sonrasızlığı

Karabasanım, 

Ömrüm, 

Biraz da armağanım.

Kutupsuzluğum,

Sözsüzlüğüme

Rağmenliği

Sözlerimin,

Irmağıma boşalttığım

Akışkan ama öyle ağır.

Yedirmezliğim sevgisizliğimi

Çarpıntılı yüreğime

Ve yine sen ömrüm

Usulca

Tutkulu

Yenilmezliğine

Pes! ...

Öylece

Pes! ...

Yaşanacaksın 

Son saniye emri verene dek Tanrı’m

20/11/2004', 'Öncesizliği ve belki sonrasızlığı Karabasanım,  Ömrüm,  Biraz da armağanım. Kutupsuzluğum, Sözsüzlüğüme Rağmenliği Sözlerimin, Irmağıma boşa...', ARRAY['Türk Edebiyatı','Şiir','Erdem Nur Cengiz']::text[], 8.5, '{"poet":"Erdem Nur Cengiz","poet_slug":"erdem-nur-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/omrum-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-erdem-nur-cengiz-fzlor', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sonsuzluk denizinde

Bir kum tanesi,

Son tanımım bu kendime.

İçimdeki “Ben” e öykündüm,

Yaşamsal sürecimde

Ne büyük yanılgı! 

Olmaz olası bir “Ben” olma kaygısı,

Hiç durmadan yankılanan beynimde...

Mümkün mü,

Başkaları tarafından kurgulanan

Bir yaşama rağmen

Kendin olabilmek

Bu Tanrının cezası gezegende...', 'Sonsuzluk denizinde Bir kum tanesi, Son tanımım bu kendime. İçimdeki “Ben” e öykündüm, Yaşamsal sürecimde Ne büyük yanılgı!  Olmaz olası bir...', ARRAY['Türk Edebiyatı','Şiir','Erdem Nur Cengiz']::text[], 8.5, '{"poet":"Erdem Nur Cengiz","poet_slug":"erdem-nur-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/isyan-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Matador''un ensesi', 'matador-un-ensesi-akin-akca-z8l2g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çamur yağıyor bu gece Ankara''da. 

Açıldı bir tünel baş yolun sonunda. 

görmedim, yaşadım ama. 

Sohbet etmek onunla 

ve sessiz dinleyişini 

onun esinleyebilmek. 

kendinden 

emin, onun yürüyüşü. 

tatlı mı tatlı onun 

masumcacık yüzü. 

ve onun 

küçücük dudakları. 

Bu geceyse 

berbat mı berbat 

bir Kasım yağmuru 

ve karı, gök delindi 

gibi oldu: 

Görmeden fakat, 

yaşıyorum - 

hissediyorum 

dolu dolu 

- sanki 

çağırıyor... 

Ve kem gözler 

ile sözler şer, 

himayesinde bunların; 

okaliptüs bitkisi 

yaprakları sanki her 

nesil yaşanan 

aşklar topak olmuş da 

... kama gibi bölerek 

sessizliği keskin bir ıslık gibi, 

(denizin bağrındaki ve 

kumsalın denize 

yakasındaki, sıkıştığımdan 

kayaların arasında.)

bedbaht kuyusuna 

yer üstü cehenneminin 

ve nice rahimlerde, gökte 

yine bir kara delik kesiyor 

göbek bağını yavrusunun... 

soluk kesilmiş 

engin otlağın 

otlarını 

kapkara bir gecede 

''bana mısın'' 

demeden biçerek 

azrail''in orağı 

davet ediyor 

ama yolu okaliptüsün - 

Koalalar ziyafette 

- durmadan çağırması 

ile ünlü, 

Gökova''ya. 

* 

Ölümün soğuk yüzü! 

her nasılsa gördü 

enerjik bir heykeltraşın 

elinden çıkma 

şu oynak 

heykelin pörtlemiş 

gözleri 

senin yüzünü! 

Şimdiye kadar savunduğum 

değerlerin arkasındayım 

ve nadiren dediklerimde ise 

kırıcı olmayı kasdetmezken asla, 

ilerleyebiliyor da tek bazen onu 

gavur olarak niteleyebileceğim hayat 

helezonun basamaklarında semirerek tıka basa: 

İşte, güneş hareketinde, güneş sistemi ile: 

Büyük bir daireyi tamamlayacak aynen 

geçtiği bir uzay parçasından bir daha asla geçmeyecek. 

(bulunamayan kara maddesinde dolaşan çemberlerin, 

John Donne misali, Ignatius''un dudakları arasından dökülen: 

o çemberin yüzeyinde 1611''de dolaştı 

neden sonra doluştular üçü birden tek bir mahzene. 

ve uyarmıştı ''gidiyorsunuz! '' diyerek ''ölüme...'' 

1616''da Galileo''yu öncesinde, 

Copernicus içinse, 1632''de 

* 

Savaşa sürülen barış soluğu - 

atıl değil, olmayan tasması 

- onun ne olacak sonu? 

Uzaklaşmamasını matador''un 

canıyla arzu etmiş 

bir çılgın boğa, 

kendine atılan mızrakları 

hedef seçercesine 

atılmıştı körlemesine 

kafilelerle hem de 

işte tam da böyle: 

Kutsal kuğu''yu sökmek 

lazım Matador''un ciğerinden! 

Boşanıyordu arena''da yağmur. 

Delişmen-devasa boğanın şehrin göbeğine kadar ulaştı yakarışları! 

Piza Kulesi''ne kadar kuşattı sesinin yankıları, İtalya''nın! 

Beceriksiz kalanlar oldu saymaya çalışanlardan bu haykırışları! 

Bir tekinde nazik boynuz darbesinin taşıdı tacına, pençesinden bir fiske sergilemeyen bu kutup ayısı! 

Tacı üstünde yükseltti Matador''u, gereksiz çirkinleşen bir kuğunun ensesinde miydi ki onun soluğu? 

Anlam veremedi uyarılıp hafifçe yere bırakılan Matador ve 

kırmızı salladı, kırmızı kırmızı perdesi''ni! 

Boğanın soluğu hep Matador''un - 

devrik ama çirkin devrik- kuğu 

gibi süklüm-bükük ensesi''ndeydi! 

Matador''un, gereksiz çirkinleşen, kendi zevkindeydi şuur dışı korkusu: 

Boğanın boynuzları soluğunda onun değildi! ! 

: Ne olduğunu anlamaya çalışırken 

ve yere devrildi 

boğa kocaman, kanlar içinde... 

sırtındaki kalınca 

okları çıkarttılar. 

sürüklediler, 

buladılar balçık toprakta, 

maça çıkanlara benzer 

bir tünelden ve onu... 

Katliamın resmini çizen 

cinayetin eşgal yorumcusu 

şeref locasındaki 

bir aile -yakından 

- ve belki diğer 

seyredenler 

bile tanıklık etti, 

kendi yaşadıklarının 

karamsar-bulanık süzgeçlerinden 

geçirdiklerinden sorumlu 

olmalarından ötürü. 

Maç bitti: 

sembolü, ağır kokan bir estetiğin; 

zerafetin, kuğu boyunlu Matador''u evine döndü. 

Boğa ise katranın kararttığı 

şu köşede - can çekişen- çoktan ölmüştü. 

Biraz sonra, 

gölgelerinin kıyı bölgesinin 

bu karartma gecesinin; 

iki öğretmen kadın göründü: 

İki İngiliz kadındı bunlar; 

Bir çeşit, arasında gezinen, 

hayali insanların, ne olduğunu 

anlamadan, Petit Trianon vakasında, 

zaman kaymasında -gizli gönüllü. 

''Ekmek bulamıyorsanız pasta yiyin! '' 

sözleri yankı olduğunda da kulaklarında, 

kafası kökünden kesik Marie Antoinette''nin 

hayaletlerinin dolaştığı şu zaman aşımında... 

Uçarak, süzülerek pürüzsüz yüzünde denizin - 

ama orası boş değildi bu sefer ve uzanarak hissettiler: 

İpek tülü gibi sabaha varmış, okyanusa açılan balkon''daki kadının... 

Şamdansı koridorda gezinen geceliğinin, uçuşan ecel rüzgarında! 

Sükse yolunun engin bayır-kılcal patikası''ndan... 

Ufka açılan en sarp bir yamacından, koşarak, göğün sözü; 

mağaranın içinden, doğruca, merhamet getirisi bir zerafetin ince 

doruklarında girintili çıkıntılı ve gömme kayaların irili ufaklı 

yamaçlarından tepelerine ulaşan 

gittikçe büyüyen kara lekeler aynı yüksek hızla 

iniyor diğer yönlerinden onların 

yine eteklere doğru duvarların yüzeyinde! ! 

- Boğaya yaklaştılar, sanki yere basmıyordular. 

Ona tekrar can vermek üzere dokundular.', 'Çamur yağıyor bu gece Ankara''da.  Açıldı bir tünel baş yolun sonunda.  görmedim, yaşadım ama.  Sohbet etmek onunla  ve sessiz dinleyişini  o...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":159,"source_url":"https://www.antoloji.com/matador-un-ensesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'M a n i l e r (8)', 'm-a-n-i-l-e-r-8-abdullah-atay-30jps', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şeker şerbet süzerim

güzelleri sezerim

yar gurbete gidince

manileri düzerim...

seveceksen yar gibi

yüreği yak har gibi

ey sevdiğim güzeli

dünya sensiz dar gibi...

yarim gonca gül gibi

bahardaki dal gibi

o dilin git dese de

gözlerin der kal gibi...

bir bakış baktın yarim

yüreğe aktın yarim

gün olup ateş olup

sen beni yaktın yarim...

evinin önü asma

fistan giyer al basma

salınıpta geziyor

yürek titreten yosma...

güzellik boy bos sende

seven yürek de bende

vuslatın doruğunda

şerbet akar gül tende...

güller gazeli yarim

kalbin özeli yarim

gönlümde hep sen varsın

dünya güzeli yarim...

asmalarda var üzüm

gözlerin süzüm süzüm

aşkınla eriyorum

budur sana son sözüm...

bahçemizde sarmaşık

bal yedim kaşık kaşık

sevda bakışlarımdan

yarin zülfü dolaşık...

abdullah atay der ki:

çocuklar gelecektir

şefkatle gülecektir

sevgiyle büyütelim

onlar birer çiçektir...', 'şeker şerbet süzerim güzelleri sezerim yar gurbete gidince manileri düzerim... seveceksen yar gibi yüreği yak har gibi ey sevdiğim güzeli dü...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/m-a-n-i-l-e-r-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşyanın Tabiatı', 'esyanin-tabiati-oguzkan-bolukbasi-picvn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni ıslatmazsan

Şemsiyesiz dokunacağım sana yağmur

Eğer yakmazsan

Bedenimi vereceğim sana güneş

Desen bile ey dudakları kilitli ahu

Eşyanın tabiatına dokunamaz dileklerin

Yaşamak öylesine bir akıntıdır belki

Veya kuralları değişmez bir oyun

Nerede durduğun

Anılarınla örtüşür

Nereye yürüdüğün

Arzularınla

Şimdi sokak ortasında üşüyen bir kediyi düşün

Cevabı sende olan sorulardır

Yaşama sorduğun

Hangi yanıt doğruya götürür

Hangi doğru mutluluğa

Yüreğimin kutsadığı yalnızlığa 

Bir sözü olan var mı

Sessiz bir cümleyi

Evrenin kulağı duyar mı

Şimdi sokak ortasında üşüyen bir köpeği düşün

Islatmayan bir yağmur neye benzer

Veya yakmayan güneş

Acıtmayan aşk

Öldürmeyen kurşun

Kim kavgadan kaçıyorsa 

Yerinde dursun

Ki bu hayatı durağan yapmasın

Havalar soğuyor

Soğuk almasın

Grip olmasın

Şimdi sokak ortasında evsiz bir çocuğu düşün', 'Beni ıslatmazsan Şemsiyesiz dokunacağım sana yağmur Eğer yakmazsan Bedenimi vereceğim sana güneş Desen bile ey dudakları kilitli ahu Eşyanın...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/esyanin-tabiati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkmen Kızı', 'turkmen-kizi-i-smet-barlioglu-tvx0z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gediz ‘de kalmadı takat,

Vadılı lele Türkmen Kızı.

Deprem bizi etti sakat,

Vadılı lele Türkmen Kızı.

Kadirli ‘de vur adamı,

Bellemezler san anaı,

Var devleti iyi tanı,

Vadılı lele Türkmen Kızı.

Rize ‘de çay döndü kana,

Verme hakkı çalışana,

Mızrak sığar mı çuvala? 

Vadılı lele Türkmen Kızı.

Gençlik girdi birbirine,

Kavga kavga üzerine,

Övün gerine gerine,

Vadılı lele Türkmen Kızı.

Köylü tarla etti kırı,

Memur tüketti sıfırı,

Vaad yarattı gırgırı,

Vadılı lele Türkmen Kızı.

Herkes ekmek kavgasında,

Ekmek arslanın ağzında,

Cehennemin ortasında,

Vadılı lele Türkmen Kızı.

İşçi oldu bir köle, kul,

Çarmıhlarda artık yıksul,

Derieinden yapın davul,

Vadılı lele Türkmen Kızı.

Söndü yaldızlı umutlar,

Sardı her yanı bulutlar,

Parsa toplar ne angutlar,

Vadılı lele Türkmen Kızı.

Kenttedir köylünün gözü,

Çünkü sattı at, öküzü,

Boş kaldı tarlası-düzü,

Vadılı lele Türkmen Kızı.

Kent düşmüş kendi hayına,

Geçim denen hayhuyuna,

Mutluluk kaldı duyuna,

Vadılı lele Türkmen Kızı.

Ğahalılık bir canavar,

Eşek eti oldu davar,

Geride ne hünerler var,

Vadılı lele Türkmen Kızı.

Çay-may kaçakçı elinde,

Herkesin aklı belinde,

Kaldık çöğlük göbeğinde,

Vadılı lele Türkmen Kızı.

Soğan satılmaktan caydı,

Bulgurun yıldızı kaydı,

Eti herkes ilaç saydı,

Vadılı lele Türkmen Kızı.

Vurucu cüzdan beğenmez,

Kimse canına güvenmez,

Giden yolcu geri gelmez,

Vadılı lele Türkmen Kızı.

Coştu beyin de, ağan da,

Utanmazlar çoğalanda

Utananlar kaldı donda,

Vadılı lele Türkmen Kızı.

Ahlak yoktur. Kayıp değil,

Hırsız-katil mağlup değil,

Parkta yatmak ayıp değil,

Vadılı lele Türkmen Kızı.

Eldir girer hep cebime,

Balo yoksul şerefine,

Değme elin herifine,

Vadılı lele Türkmen Kızı.

Herkesin elinde kalem,

Yazıyorlar allem-kallem,

Yazar olduk Allhalem,

Vadılı lele Türkmen Kızı.

Kalkındık ki; öylesine,

Kimse bakmaz gerisine,

Hep rastgeldik böylesine,

Vadılı lele Türkmen Kızı.

Eller kalkar imrenirler,

Turist-murist gönderirler,

Yer kazığı, öğrenirler,

Vadılı lele Türkmen Kızı.

Tavşan sopaya aldandı,

Bıçak kemiğe dayandı,

Ellerine düşen yandı,

Vadılı lele Türkmen Kızı.

Derdimiz yok, gamımız yok,

Baş sokacak damımız yok,

Öpülmemiş yanımız yok,

Vadılı lele Türkmen Kızı.

Kıtlık refahı körükler,

Üzülmesin hiç küçükler,

Yolu bilir bu büyükler,

Vadılı lele Türkmen Kızı.

(NENNİ DE FERİDE ''M, NENNİ isimli Taşlamalar ''ından  33-37/104)

(Bu dizeler, 2000 ''den 36 yıl önce yazılmıştır. Ve; bir tek sözcüğüne bile dokunulmamıştır.)', 'Gediz ‘de kalmadı takat, Vadılı lele Türkmen Kızı. Deprem bizi etti sakat, Vadılı lele Türkmen Kızı. Kadirli ‘de vur adamı, Bellemezler san ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/turkmen-kizi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Ağam', 'benim-agam-i-smet-barlioglu-451ty', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağa ‘mız var mahallede; 

Kızlarağası benim Ağa ‘m.

Eşi yoktur bu dünyada; 

Tey tey benim Ağa ‘m.

Benim Ağa ‘m safi kafa,

İşi vaad yığmak rafa,

Hiçbir sözü girmez safa,

Kızlarağası benim Ağa ‘m.

Söyler, altından kalkamaz,

Gerekirse kılar namaz,

Vaad eder ve yapamaz,

Tey tey benim Ağa ‘m.

Benim Ağa ‘m sağlam işler,

Oy buldumu has söğüşler,

Bir atı var; battal şeşper,

Kızlarağası benim Ağa ‘m.

Benim Ağa ‘m avuç açar,

Yedi düvel korkar kaçar,

Haydan alır, huya saçar,

Tey tey benim Ağa ‘m.

Kalkmış olmuş ele rehber,

İşi-gücü hep rastgider,

Tanrı onu hep vareder,

Kızlarağası benim Ağa ‘m.

Cömert doğurmuş anası,

Kendisi zam kumkuması,

Yoksul kavmin Bey Babası,

Kızlarağası benim Ağa ‘m.

Benim Ağa ‘m çok hamarat,

Atı-matı eder haşat,

İflah etmez anam avrad,

Tey tey benim Ağa ‘m.

Çiftçi onun çiftçisidir,

İşçi onun işçisidir,

O cennetin bekçisidir,

Kızlarağası benim Ağa ‘m.

Gören der ki; ‘İşte Baba’,

El-mel koyar her hesaba,

Koyacaksa; kor mutlaka,

Tey tey benim Ağa ‘m.

Bire bin bahise varım:

Onla geçer tüm yıllarım,

Onla yaşar torunlarım,

Kızlarağası benim Ağa ‘m.

Sanmayın ki; bir gün gider,

Uzaklardan el el eder,

Ağa ‘m çoban; nesil güder,

Tey tey benim Ağa ‘m.

Nesil biter, o yerinde,

Yeni nesil ellerinde,

Bir sonraki ceplerinde,

Kızlarağası benim Ağa ‘m.

Ağa ‘m ile olmaz yarış,

Bu Ağa ‘dan yok kurtuluş,

Nesilleri edecek tuş,

Tey tey benim Ağa ‘m.

O hep attı, biz de yuttuk,

O batırdı, biz de battık,

Bu Ağa ‘yı biz şımarttık,

Kızlarağası benim Ağa ‘m.

Bu Ağa ‘ya bu fırsat çok,

Yoksullaştı çoluk-çocuk,

Yaşantımız çok azbuçuk,

Kızlarağası benim Ağa ‘m.

Çok pişkindir benim Ağa ‘m; 

Yine gelir kalkıp kovsan,

Ömür olsa da dayansan,

Tey tey benim Ağa ‘m.

İşçi açlıkla boğuşur,

Çiftçi gübreyle savaşır,

Ağa ‘m nikahta dolaşır,

Kızlarağası benim Ağa ‘m.

Dün dediyse; dün demiştir,

‘Yıl’ Dediyse; ‘Gün’ dmiştir,

‘İp’ Dediyse; ‘Yün’ demiştir,

Tey tey benim Ağa ‘m.

‘Yok’ Dediği vardır onun,

‘Bol’ Dediği dardır onun,

‘Ot’ Dediği nardır onun,

Kızlarağası benim Ağa ‘m.

İsyan etsen; güler geçer,

Kireçlesen; deler geçer,

Kuzu gibi meler geçer,

Tey tey benim Ağa ‘m.

Kendi için çöp istemez,

Benzin koysan; içmez, yemez,

Yeminlidir; asla gitmez,

Kızlarağası benim Ağa ‘m.

(NENNİ DE FERİDE ''M, NENNİ isimli Taşlamalar ''ından > 38-42/104) 

(Bu dizeler, 2000 ''den 36 yıl önce yazılmıştır. Ve; bir tek sözcüğüne bile dokunulmamıştır.)', 'Ağa ‘mız var mahallede;  Kızlarağası benim Ağa ‘m. Eşi yoktur bu dünyada;  Tey tey benim Ağa ‘m. Benim Ağa ‘m safi kafa, İşi vaad yığmak raf...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":90,"source_url":"https://www.antoloji.com/benim-agam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Çiçekler Solmasın!', 'bu-cicekler-solmasin-kadir-soyturk-paa3v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çocuk, çiçek demişler

Ne de hoş söylemişler.

Hiç çiçeksiz olur mu

Meyve veren yemişler? 

Bu çiçekler solmasın

Kimsecikler yolmasın.

Susuz, sevgisiz kalıp

Kara çalı olmasın... 

Çocuklar ve çiçekler

Ne kadar da güzeller! 

İnsanlığın düşmanı

Onlara kıyan eller!', 'Çocuk, çiçek demişler Ne de hoş söylemişler. Hiç çiçeksiz olur mu Meyve veren yemişler?  Bu çiçekler solmasın Kimsecikler yolmasın. Susuz, s...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-cicekler-solmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yumulsana', 'yumulsana-i-smet-barlioglu-6oc5l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Piyangodan bilet aldım, Ulan Memmed yumulsana,

Rengarenk bir düşe daldım, Ulan Memmed yumulsana,

Milyon çıksa en azından; Piliç vururum gözünden,

Mayıştım daha sözünden, Ulan Memmed yumulsana,

Para basarım çuvala, Çıkarım ben avlanmaya,

Kız mı gelmez öyle tava? Ulan Memmed yumulsana,

Kahvaltıya bir sarışın, Kaşıklarım hışım hışım,

Esmer olsa; döner başım, Ulan Memmed yumulsana,

Kondururum villa düze, Hükmederim her gündüze,

Kim ram olmaz bendenize? Ulan Memmed yumulsana,

Yüzbin çıksın, çoksa; milyon, Şaşakalır dana-dılyon,

Çok değerli bir madalyon, Ulan Memmed yumulsana,

Yüzbinin yetmişi kata, Yirmibeşi şatafata,

Beşbinini boz boz, harca, Ulan Memmed yumulsana,

Ellibin az değil billah, varsın nasip etsin Allah,

Ah yoksulluk, yoksulluk ah, Ulan Memmed yumulsana,

Bir kat kiradan kurtarır, İnsan bala düştüm sanır,

Bir yatımı nah uyanır, Ulan Memmed yumulsana,

Kırkbin çıksa; şapkam göğe, Neler indirmem gövdeye,

Bir yarısı evlenmeye, Ulan Memmed yumulsana,

Kalanıyla sepet-sandık, Yeter şöyle genç bir kancık,

Bekarlıktan çok usandık, Ulan Memmed yumulsana,

Yirmibinde bir bayram var, Alırım bir sürü davar,

Bir ahıra hepsi sığar, Ulan Memmed yumulsana,

Sal sürüyü bir çayıra, Karnını Mevlam doyura,

Kuzularlar hep bahara, Ulan Memmed yumulsana,

Yününü sat, etini sat, Geçmez ele öyle fırsat,

Yorganını boy boy uzat, Ulan Memmed yumulsana,

Onbin çıksa; derde ilaç, Al parayı aşevi aç,

Hergün yerim keşkül, sütlaç, Ulan Memmed yumulsana,

Kaynıyor çorbam, buyurun, Kaseleri tam doldurun,

Oğlum beye çok çok koyun, Ulan Memmed yumulsana,

Başıma taç beşbin lira, Bir yarısı borçlarıma,

Dörttebiri yarınıma, Ulan Memmed yumulsana,

Bin liraya bir kör avrad, Yeme, içme yanında yat,

Unutursa; sen hatırlat, Ulan Memmed yumulsana,

Ev yerine bir samanlık, Varsın olsun hep karanlık,

Yoksul yaşam bir sultanlık, Ulan Memmed yumulsana,

Binlik çıkarsa; bilete, Toz kondurmam hamiyete,

Dağıtırım hep millete, Ulan Memmed yumulsana,

Çıksa bana bir tek maaş; Bol bol yeter bir ay termaş,

Al başını ye, iç dolaş, Ulan Memmed yumulsana,

Kırk lira da çıksa, yeter, Yenilenir şu terlikler,

Bir de hemam, bir de berber, Ulan Memmed yumulsana,

Yenilensin terlik, kafi, Terlik olmuş tam müstafi,

Zaten sevmem hiç israfı, Ulan Memmed yumulsana,

Çıksın bari bir amorti, hiç olmazsa çekmem morti,

Mazi neyse; odur ati, Ulan Memmed yumulsana,

Yanarsa da yansın bilet, Zaten liste bulmak illet,

Yala avucunu Hikmet, Ulan Memmed, git başımdan.

(NENNİ DE FERİDE ''M, NENNİ isimli Taşlamalar ''ından > 43-45/100) 

(Bu dizeler, 2000 ''den 36 yıl önce yazılmıştır. Ve; bir tek sözcüğüne bile dokunulmamıştır.)', 'Piyangodan bilet aldım, Ulan Memmed yumulsana, Rengarenk bir düşe daldım, Ulan Memmed yumulsana, Milyon çıksa en azından; Piliç vururum gözü...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/yumulsana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Verdik Kırkı', 'verdik-kirki-i-smet-barlioglu-gr0o1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalvardılar, yakardılar,

Verdik kırkı, çıktı korku.

Yine bizi otardılar,

Verdik kırkı, çıktı korku.

Umutları sele verdik,

Adımızı dile verdik,

Canımızı ele verdik,

Verdik kırkı, çıktı korku.

Bre paşa, ağa, beyler,

Görelim ki; devran neyler,

Can vermek benzemez derler,

Verdik kırkı, çıktı korku.

‘Büyük bir zam’ Demişlerdi,

‘Her gün bayram’ Demişlerdi,

‘Verin toptan’ Demişlerdi,

Verdik kırkı, çıktı korku.

Olmayana tarla, arsa,

İşsize ev, eğer yoksa,

Olmaz ama ya olursa; 

Verdik kırkı, çıktı korku.

Süper-müper emeklilik,

Her bedene kan ve ilik,

Çok yaşasın zırdelilik,

Verdik kırkı, çıktı korku.

Çok bağrıldı alanlarda,

Hayran oldu duyanlar da,

Ayni günde her bir yanda

Verdik kırkı, çıktı korku.

Peki ama nerde soğan? 

Hani ballar, hani kovan? 

Bu dar gün mü büyük bayram? 

Verdik kırkı, çıktı korku.

Zam yaptılar kiralara,

Kıran girdi ahırlara,

Ne güvendik biz bunlara? 

Verdik kırkı, çıktı korku.

Ter içinde çalışarak,

İçimizle savaşarak,

Yağcılara danışarak

Verdik kırkı, çıktı korku.

Yerler yerinden aynasa; 

İcra kapıya dayansa; 

Başımıza taşlar yağsa; 

Verdik kırkı, çıktı korku.

Ustaca dümen tuttular,

Kırka sulanıp durdular,

Gecikince kudurdular,

Verdik kırkı, çıktı korku.

Ağız açtık biz poyraza,

Başımıza geldi kaza,

Canlar çıktı ta boğaza,

Verdik kırkı, çıktı korku.

Dün bugüne örnek düştü,

Ele düğün-dernek düştü,

Bize yalnız vermek düştü,

Verdik kırkı, çıktı korku.

Vere vere mal kalmadı,

Mal tadıldı, doyulmadı,

Dayanacak hal kalmadı,

Verdik kırkı, çıktı korku.

Denenmişi biz sınadık,

Sevdik, öptük ve yaladık,

Paslı kabı kalayladık,

Verdik kırkı, çıktı korku.

Eskilerden farksız bu da,

Onlardaki her şey bunda,

Yardımcımız olsun Huda,

Verdik kırkı, çıktı korku.

Ele geçen ekmek, soğan,

Öyle taam etmiş babam,

Ben babama fark atamam,

Verdik kırkı, çıktı korku.

Aş yerine kaynıyoruz,

Biz çaldık, biz oynuyoruz,

Belamızı buluyoruz,

Verdik kırkı, çıktı korku.

(NENNİ DE FERİDE ''M, NENNİ isimli Taşlamalar ''ından > 46-50/100) 

(Bu dizeler, 2000 ''den 36 yıl önce yazılmıştır. Ve; bir tek sözcüğüne bile dokunulmamıştır.)', 'Yalvardılar, yakardılar, Verdik kırkı, çıktı korku. Yine bizi otardılar, Verdik kırkı, çıktı korku. Umutları sele verdik, Adımızı dile verdi...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/verdik-kirki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alıp Götürdüklerin', 'alip-goturduklerin-ali-aldemir-d2ro5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gittin ya hani giderken

Alıp götürdün ya onları da,

Hani uzun uzun 

Soluksuz kurduğum

Yani dilimdeki kelimeleri,

Hani dünyaya bakan,

Yani beni ben yapan yüzümü,

Yani gülen gözlerimi

Sonra gülüşlerimi

Onları istiyorum senden.', 'Gittin ya hani giderken Alıp götürdün ya onları da, Hani uzun uzun  Soluksuz kurduğum Yani dilimdeki kelimeleri, Hani dünyaya bakan, Yani be...', ARRAY['Türk Edebiyatı','Şiir','Ali Aldemir']::text[], 8.5, '{"poet":"Ali Aldemir","poet_slug":"ali-aldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/alip-goturduklerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonu Olmayan Deniz (siyah kitaptan)', 'sonu-olmayan-deniz-siyah-kitaptan-engin-kahraman-u56wg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir çocuk

benzersiz uzak bir bahçede

iki karış su üstünde evi

ağlıyor gecede

duyulmuyor sesi

adını kuyuya atmış annesi

şimdi sadece

yaşlı cinler biliyor ismini

evde kaldığında yağmurlardan

masallar anlatıyorlar ona

adı yankılanıyor durmadan

siyah bulutlar altında uyuyorken annesi

gülüşmeler geliyor karanlık kuyudan', 'bir çocuk benzersiz uzak bir bahçede iki karış su üstünde evi ağlıyor gecede duyulmuyor sesi adını kuyuya atmış annesi şimdi sadece yaşlı ci...', ARRAY['Türk Edebiyatı','Şiir','Engin Kahraman']::text[], 8.5, '{"poet":"Engin Kahraman","poet_slug":"engin-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sonu-olmayan-deniz-siyah-kitaptan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen de Çukursun!', 'sen-de-cukursun-kadir-soyturk-3ercr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Buna kalp dayanmaz; Kafir kudursun,

Gelip Felluce'' yi   kalbinden vursun.

''Halepçe''den beter'' gördüğüm resim

Saddam alçak idi; sen de çukursun!', 'Buna kalp dayanmaz; Kafir kudursun, Gelip Felluce'' yi   kalbinden vursun. ''Halepçe''den beter'' gördüğüm resim Saddam alçak idi; sen de çukurs...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-de-cukursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gun Anne', 'bir-gun-anne-suyum-gozyasi-3krak', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün soğuk bedenime de

Böyle dokunacaksın anne

Önce

Yüzüme baktığında irkileceksin

Korkacaksın ister istemez

Sonra

Acaba ben miyim diye

Şüphe edeceksin

En sonunda anlayacaksın 

Benim olduğumu

Yüreğinden bir parça kopacak 

Ve gözlerinden o an

Sıcak iki damla 

Düşecek tenime

Öpeceksin

Tıtrek ellerinle

Traşsız solgun yüzüme

Şefkatle dokunacaksın

İşte o zaman

Hafiften üşüyeceksin

Tüylerin diken diken olacak

Aklında saçımdaki tek tel ak

Ve kucağına yatarken

Avuçlarına düşen

Bana ait ıslak bir aşk

Bir de boğazıma sıkışan

Anne sesi olacak

Annesin ve şefkatlisin

Bu asi adam

Sana o gün bir melek

Tadı verecek

Seni kızdırdığım günler 

Belki de seni güldürecek

Ben beyazlar içindeyken

Öylece bana bakacaksın

Boyumun uzunluğunun

Farkına varacaksın

Karnımın üstünde 

Bir bıçak olacak

Babama ve kardeşlerime

Kederle sarılacaksın

Haberi olusa ki

İnşallah olmaz

Kapıda bir gül belirecek

İnan bana anne o da

Senin kadar üzülecek

Gitme vakti gelecek

Beni ellerinle bindireceksin

O tahtadan ata

Hayır sever bir kaç kişi

Kılacak namazımı

Kardeşim koyacak beni

O karanlık yatağa amcalarımla

Ertesi gün

Hafızla başıma geleceksin

Ve bu hatıramla birlikte

Beni anacaksın dualarınla', 'Bir gün soğuk bedenime de Böyle dokunacaksın anne Önce Yüzüme baktığında irkileceksin Korkacaksın ister istemez Sonra Acaba ben miyim diye Ş...', ARRAY['Türk Edebiyatı','Şiir','Suyum Gözyaşı']::text[], 8.5, '{"poet":"Suyum Gözyaşı","poet_slug":"suyum-gozyasi","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/bir-gun-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Dair', 'hayata-dair-nurten-koroglu-7qnjy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ellerimi tut,ellerimi

Sevginle dirilirim

Kavgalarla gelme bana

Seni ancak sükunun la sevebilirim

Sözdür ruhunda ki yangınları

Savaşları baş kaldırmaları

Rüzgara karşı koşamazsın

Ruhun büyümedikçe yaşayamazsın

Bir tek sen değilsin ki hayata kırgın

Bir dinlesen sen beni,ben neler söylerim

Ya bırakıp her şeyi çekip gideceksin

Ya da tersi düze çevireceksin

Merhaba de her doğan güne

Elveda de acı düne

Seni hırpalayıp acıtan  her şeyde

Sadece senden başkalarımı var

Bir sor kendine

Hiç kimse incitemez seni senden çok

Kızma sakın başkalarına

Ama,hiçbir zaman hazırlıksız yakalanma

Hayatın oyunlarına

Yer ver gönlünde seni sevene

Yalana dolana değil,gerçekten gelene

Her insanın bir acı hikayesi vardır hayatta

Afet meyi bil değer ver özürlerine

Yaşam bir sahnedir

Zekanın tüm kıvraklığıyla oynayacaksın

Suflelere kulak verip

Kendi mantığını kullanacaksın', 'Ellerimi tut,ellerimi Sevginle dirilirim Kavgalarla gelme bana Seni ancak sükunun la sevebilirim Sözdür ruhunda ki yangınları Savaşları baş ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Köroğlu']::text[], 8.5, '{"poet":"Nurten Köroğlu","poet_slug":"nurten-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hayata-dair-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüklere Masallar (Yalan Rüzgarları)', 'buyuklere-masallar-yalan-ruzgarlari-necmiye-sarpkaya-iepp1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '2003 Mart ayını gösterir tarihler

Devletlerden bir devlet

Kitle imha silahı bulundurur

Süper güçler tehlikeye düşer

Yetmiyormuş gibi kafa da tutar

Gelin gelin geleceğiniz varsa

Göreceğiniz de var

Sizi çöle saplayalım da

Görün gününüzü

Çağrıya uyulur gidilir

Oraya kadar gidilmişken işgal edilir

Diktatörlerin heykelleri halkla el ele

Davul zurna ve halk oyunları eşliğinde

Kırılır parçalanır devrilir

Halk conolarla elele gönül gönüle

 ne de olsa özgürler

Masal bu ya

Aniden ciddi devlet adamları

Sahtekar dolandırıcı yalancı

Oluverir...

Maskeler düşer kel görünür

Akşam söyler sabah yalanlar

Haçlı Seferleri mi kim çıkarıyor bu

Yalanları kim söylüyor

Devlet devlet değil

Halk da halk değil

Masal bu ya

Yalan rüzgarı devam eder eder

Kitle imha silahları bulunmaz

Oysa alet edavat zırzavat

Onlardan gitmiş 

Bedeli nakit tahsil edilmiş

Faturaları saklanmış

Elma dersem çık

Armut dersem çıkma

Ne söylenirse söylensin

Muzur silahlar çıkmaz ortaya

Oyun bozan ya koca koca devletlerin

Oyunlarını bozacak

Kafaya koymuş bir kere

Ne çare......

El Kaide Örgütünden

Eser yok kıyı köşe bucak aranır

Taşların tepelerin altlarına bile bakılır

Ne gezer yeller esiyor yerlerinde

Buhar olur uçar masal bu ya

O arada hesap da olmayan birşey olur

Diktatör yakalanır perişan bitkin

Yorgun hasta zavallı bir şekil de

Güzelce saç baş 

Tepeden aşağı muayene edilir

Medeni doktorlara emanet edilir

Avukatlar tutulur özel adalar alınır

Yatlar katlar e..e...e insan hakları malum

İnsanlık öldü mü adil özgür demokrat insanlar

Elinde emniyette ne de olsa

O erer mutluluğa biz çıkalım kerevetine

Masal bu ya her şey iyiye giderken

Yalan rüzgarları tersten esmeye başlar

İşler bozulur zaman bu durur mu yerli yerinde

Hızla akar 2004 Ramazan ayı gelir çatar

Beyaz bembeyaz pembe pespembe saraylarda

İftarlar verilir kardeşlik dostluk oyunları oynanır

Derken bin aydan hayırlı kadir gecesi gelir

İşte tam o gece kadir gecesi

Top tüfek medeniyet icadı ne varsa kullanılır

Genç yaşlı çoluk çocuk ne çıkarsa katledilir

Yetmez camiler kurşunlanır insanlar öldürülür

Ölenler sokak köpeklerine yem edilir

Kalanlar bin pişman her tür eziyet düşmanın başı ezilir

Kendilerini Fırat''a atanlar öldürülür al kanlara boyanır

Masal devam eder masal içinde hepimiz hepiniz

Bütün dünya yar alır rol alır

Kanlar donmuş

Diller susmuş

Gönüller kararmış

Gözyaşları taşlaşmış

Eller semaya açılmış

Bir daha kapanmamış

Masal burada kesilir

Naziler Hitler 

Gelmiş geçmiş bütün bildik tanıdık

Diktatörler aranır aranır

Rahmet okunmak için aranır

Masal burada biter

Zahmetin Rahmete

Acının tatlıya ulaşacağı günler

Beklenir beklenir dilenir dilenir', '2003 Mart ayını gösterir tarihler Devletlerden bir devlet Kitle imha silahı bulundurur Süper güçler tehlikeye düşer Yetmiyormuş gibi kafa da...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/buyuklere-masallar-yalan-ruzgarlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üstad Ne Dersin...', 'ustad-ne-dersin-i-brahim-ethem-bingul-joxwx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dedemden kalan lambalı radyoda

Zeki Müren hüzün okuyor

İçimdeki havam

Dışardaki havaya arkadaş...

Bulutlar yere inmiş

Sular şarıldıyor yolda

Şarkının sesi

Rüzgarların uğultusunda...

Şimdi uzaklardasın diyor titreyen sesi

Gönül hicranla doldu da

Mesafelerden değil

Sevgiyle içimde olduğunu anlatamamaktan üstad...

Aşkımızın hatırası olacak

Bir demet yasemeni bile

Bana çok gördü sevilen...

Sen olsan bu işe

Ne dersin be üstad...

www.iebingul.com', 'Dedemden kalan lambalı radyoda Zeki Müren hüzün okuyor İçimdeki havam Dışardaki havaya arkadaş... Bulutlar yere inmiş Sular şarıldıyor yolda...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ustad-ne-dersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keramet Bende Değil', 'keramet-bende-degil-ali-riza-unal-fjnnj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sakladın ayanı cemalini, ef-âl ile zuhuru esmana

Aramam  seni cümleli kâal ile hurufu zan da değil

Vakıfım söylenmez bir demde, kemâl ile nuru zatına

Keremin lütfun hal oldu zatıma, gururu keramet bende değil', 'Sakladın ayanı cemalini, ef-âl ile zuhuru esmana Aramam  seni cümleli kâal ile hurufu zan da değil Vakıfım söylenmez bir demde, kemâl ile nu...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/keramet-bende-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlan', 'i-lan-ali-riza-unal-6q4bv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neylerim karanlık düşleri, ben can ile hakikatteyim 

Tanrı verirse fermanı, her hâl ile  takatteyim

O nefsin zan ile hevayı hayaline, her cem ile firkatteyim

Gelin dostlar dem olmaya, ben irşadı hatteyim', 'Neylerim karanlık düşleri, ben can ile hakikatteyim  Tanrı verirse fermanı, her hâl ile  takatteyim O nefsin zan ile hevayı hayaline, her ce...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ilan-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Ahrazsın Yada Kör', 'ya-ahrazsin-yada-kor-ali-riza-unal-520mj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlamadım bir türlü, neden  firkatteyim sana

Biliyorum sevdiğini, acep darıldın mı sen bana

Alem sözüme ram olmuş, yetmiyor  takatim sana

Sözüm meclisten uzak, ya ahrazsın ya da kör öyle geliyor bana', 'Anlamadım bir türlü, neden  firkatteyim sana Biliyorum sevdiğini, acep darıldın mı sen bana Alem sözüme ram olmuş, yetmiyor  takatim sana Sö...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ya-ahrazsin-yada-kor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alıver Visaline', 'aliver-visaline-ali-riza-unal-d1773', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Örtmesin günahlarım, nur benzinin didarını

Ta ezelden biatım var, seyranım dür nigârını 

Sen dilersen af edersin, çekiver gazabın fermanını

Bilirim senden gayrı canan yok, siliver cürmü narımı

Esmesin kahır rüzgârı, her cemde seyranınım senin

Alıver her anda vaslına, veriver  her demde dermanını', 'Örtmesin günahlarım, nur benzinin didarını Ta ezelden biatım var, seyranım dür nigârını  Sen dilersen af edersin, çekiver gazabın fermanını ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/aliver-visaline-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanıver Bana', 'yaniver-bana-ali-riza-unal-hy26y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ah etmedim zulmüne, nede feryadım sana

Ne evet dedin nede red, küsmüsün dargınmı bana

Günlerin ay ayların yıl oldu,hasretim sana

Hiç değilse nur yüzlüm, an ile dönüver bana

Bakmayayım her yerde, sen diye ona buna

Ne olur imana gel, visale ile yanıver bana', 'Ah etmedim zulmüne, nede feryadım sana Ne evet dedin nede red, küsmüsün dargınmı bana Günlerin ay ayların yıl oldu,hasretim sana Hiç değilse...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yaniver-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirli Pazar', 'siirli-pazar-fevzi-gunenc-cv05o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Merhaba

bugün pazar

ben ortadoğuda

Mezopotomya''sında Anadolu''nun

Bir sanayi kentinde yaşıyorum...

Gözlerimi açtığımda ıpıl yağmurlu güzel sabaha

kan kokusu karışttğını duyuyorum.

Uzaklarda değil

hemen bir kaç yüz kilometre ötemde

kentlerin bombalandığı

çocukların öldürüldüğü gelmeliyken

sen geliyorsun aklıma...

Sen Rhein nehri kıyısındaki evinden

nehre bakan 

can

neredeeen nereye gönderiyorum merhabamı! 

Bir önerim var sana

Yakınımdaki bu kan gölünün acısını

paylaşalım mı?', 'Merhaba bugün pazar ben ortadoğuda Mezopotomya''sında Anadolu''nun Bir sanayi kentinde yaşıyorum... Gözlerimi açtığımda ıpıl yağmurlu güzel sa...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/siirli-pazar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olmasan', 'sen-olmasan-talip-kaplan-kh8nl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ve nihayet yıktın

Parçaladın mutluluğun resmini

Fırçam kırılmadı ya

Daha çizerim, daha çizerim

Çekip gitmek manasız

Değil bu şehre,

Evrene sığmaz sensizlik

Nereye baksam sen,

___________ hep sen

Sen ki, kalemimin konusu

İnan öyle kolaylaştı ki

Hoşgeldin ey ölüm demek

Varlığın çektirir yaşamayı

Sana katil demesinler

Her şey seninle güzel...

(30 Haziran 1998)', 'Ve nihayet yıktın Parçaladın mutluluğun resmini Fırçam kırılmadı ya Daha çizerim, daha çizerim Çekip gitmek manasız Değil bu şehre, Evrene s...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-olmasan-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özümü Ararken…', 'ozumu-ararken-hikmet-feridun-demir-2dndd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çıktım benliğimden, Özümü aradım..

Tepkiliyim dolu dizgin Herkese, Her şeye..

Neden, 

Niçin, 

Nerede diye sorular sordum...

Vara vara sonunda, 

Herkesten, Her şeyden,

Bir Parça

Kendimi buldum.', 'Çıktım benliğimden, Özümü aradım.. Tepkiliyim dolu dizgin Herkese, Her şeye.. Neden,  Niçin,  Nerede diye sorular sordum... Vara vara sonund...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ozumu-ararken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Arayışı…', 'sevgi-arayisi-hikmet-feridun-demir-junw1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgi aradım, çorak kalplerde..

Susamış, kurumuş bir halde buldum…

Neden, 

Neden, 

Neden diye sordum? 

Nedeninde kendimi buldum...

Birden geldim bire giderim…', 'Sevgi aradım, çorak kalplerde.. Susamış, kurumuş bir halde buldum… Neden,  Neden,  Neden diye sordum?  Nedeninde kendimi buldum... Birden ge...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sevgi-arayisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümit Kıvılcımları', 'umit-kivilcimlari-yesim-akyuz-y6x6k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kış günü

Soğuk ve rüzgarlı

Paltomu giymiş, dışarıya çıkmışım

Elimde böyle günler için sakladığım bir sigara

Aklım yine o  pembe hayaller ve

Onlara ulaşamamış olmanın verdiği burukluk

Sigaramda arıyorum teselli 

Bir yukarı, bir aşağı yürüyorum sokakta

Yıllardır bulamadığım sevgiyi bulacağımı 

Sanıyorum bir akşamda

Oysa kimse yok yapayalnız 

Sokak lambaları  ve ben,

Birer birer kararıyor evlerin ışıkları

Ve bugünde sürüyor

Gözümde dolan ümit kıvılcımları', 'Bir kış günü Soğuk ve rüzgarlı Paltomu giymiş, dışarıya çıkmışım Elimde böyle günler için sakladığım bir sigara Aklım yine o  pembe hayaller...', ARRAY['Türk Edebiyatı','Şiir','Yeşim Akyüz']::text[], 8.5, '{"poet":"Yeşim Akyüz","poet_slug":"yesim-akyuz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/umit-kivilcimlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlat Bana', 'anlat-bana-volkan-yoruc-qwtsi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anlat bana

Sevda rüzgarları esmişmiydi gönlüne

Hiç üşümüşmüydün 

Usul usul sarılmışmıydın kendine

Bana anlat durma öylece

O yıllar demişmiydin beni yakan

Çiçeklerimi anımsamışmıydın 

Hani aralarından gözlerimle sana baktığım o an

Anlat bana

Anlatılması hayallere kadar olan o zaman

Hiç sevmişmiydin söyle

Susmalara kalma bana öyle

Benim için feda et nefesini

Ve anlat bana durmamacasına

Belki son bir isteğim son arzum yada dileğim

Duymak nasılda isterim

Bil ki gelmeyeceğim geriye

Dönmeyeceğim yüreğine

Bakmayacağım o güleç yüzüne

Anlat bana durma

Son kez bakamasanda 

Hiç sevmişmiydin söyle bana', 'Anlat bana Sevda rüzgarları esmişmiydi gönlüne Hiç üşümüşmüydün  Usul usul sarılmışmıydın kendine Bana anlat durma öylece O yıllar demişmiyd...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/anlat-bana-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı soluyorum', 'aski-soluyorum-sadik-sahin-jjpbs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu kentin karanlık sokakları

Çöplüğe açılır martıların gagasından

Ve ağzıma gelen ilk şey inadına küfür olur

Seni seviyorum

Bana 

buhranlı bir baharın

Suyu çıkmış türkülerinde

Yakılan ilk ağıt sen olursun

Yaşasın cehennem soluyorum

Bana ateşten bir gömlek 

Yakasız

İliksiz ve kemiksiz

Bir gülüşün

Ağız dolusu kusmuğu olur aşkın

Kendime değil aşka lanet olsun', 'Bu kentin karanlık sokakları Çöplüğe açılır martıların gagasından Ve ağzıma gelen ilk şey inadına küfür olur Seni seviyorum Bana  buhranlı b...', ARRAY['Türk Edebiyatı','Şiir','Sadık Şahin']::text[], 8.5, '{"poet":"Sadık Şahin","poet_slug":"sadik-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aski-soluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayramlar', 'bayramlar-sadik-sahin-pglrb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kazıdı tırnaklarım

kalan son birkaç telim

bağlama aldı geceyi

bir çığlık kopardık

ve kasımpatılar giden mevsime ağladılar

şimdi bir öyküydük

anılar süslüyordu

bayramda sofralarımızı tatlı niyetine

kazıdı tırnaklarım 

bir ezgi oldu kalem resminde

ağlamaktı bu

ağlamaktı sevinçten

ve umutlar süsledi geceyi

geceyi öyle bir süsledik ki

hep iyiler kazandı

biz kazandık

cadı kazanı kaynadı 

kaynadı,

kaynadı

ve kazıdı tırnaklarım

senin ismini

geçmişin tozlu defterine

kalan son birkaç tel saçım

kasımpatı buketiyle

hep seni bekledi', 'kazıdı tırnaklarım kalan son birkaç telim bağlama aldı geceyi bir çığlık kopardık ve kasımpatılar giden mevsime ağladılar şimdi bir öyküydük...', ARRAY['Türk Edebiyatı','Şiir','Sadık Şahin']::text[], 8.5, '{"poet":"Sadık Şahin","poet_slug":"sadik-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bayramlar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurt kocayınca', 'kurt-kocayinca-sadik-sahin-zu782', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sararmış kafa kağıdımdaki 

çizikler kadar güzeldi ellerin

narin, korkak, hamarat

mazot soluyordum gözlerinden

titreyen bedenim

takma dişlerim tak tak tak

öyle yoğurmuştuk ki geceyi

yorulmuştuk

yormuştuk kırmızı şarabı

ellerinde sabaha yetişecek

sabahı yeşertecek bildiri tadında

iki satır, iki ezgi

narin, gizli,

hamarat

değiştirdim sararmış kafa kağıdımı 

-seveceksen böyle sev beni-                     

titreyen bedenim

takma dişlerim 

tak tak tak', 'Sararmış kafa kağıdımdaki  çizikler kadar güzeldi ellerin narin, korkak, hamarat mazot soluyordum gözlerinden titreyen bedenim takma dişleri...', ARRAY['Türk Edebiyatı','Şiir','Sadık Şahin']::text[], 8.5, '{"poet":"Sadık Şahin","poet_slug":"sadik-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kurt-kocayinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskimeyen Şiir', 'eskimeyen-siir-sadik-sahin-gz91q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'benimle doğanlar askerliği yedi

çoluk çocuğa karıştı

ve hayatı eskittiler

ve ellerim eskiden kalma hiçbir şeyi eskitmedi

benimle doğanlar geceyi gündüzü eskitti

bir kütüphane

ve üç kuruşluk ev eşyasından başka

hücrelerimden başka

saç ve sakalımdan başka

ve hatta bıyıklarımdan

koca bir hiç kaldı geride

benimle doğanlar hayatı eskitti

ben hayatı  hep yeniden yaratırken

hayat hiç eskimedi.', 'benimle doğanlar askerliği yedi çoluk çocuğa karıştı ve hayatı eskittiler ve ellerim eskiden kalma hiçbir şeyi eskitmedi benimle doğanlar ge...', ARRAY['Türk Edebiyatı','Şiir','Sadık Şahin']::text[], 8.5, '{"poet":"Sadık Şahin","poet_slug":"sadik-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/eskimeyen-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yalnız Bir Dağ Kırlangıcıyım', 'ben-yalniz-bir-dag-kirlangiciyim-volkan-yoruc-2dwrw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşlerim sevdalara kanat çırpmayı

Cihana gök mavimden bakmacasına

Bulutların tepesinde sevmeyi 

Kimsenin ulaşamayacağı o görünmez ufuklarda

Düşlerim sevdalara kanat çırpmayı

Hoyrat tepelerden süzülmeyi

Yemyeşil ovalardan geçmeyi

Mutluluk ağacının dallarına tünemeyi

Düşlerim öylece 

Şimşekler çaksada gönlümde

Korkma sığın bana

Gözlerini sakınma benden

Ben sevda ateşine düşmüşüm

Yansada her yerim bu sevdalarda

Umuda kanat çırpan bir dağ kırlangıcıyım

Sevdaya konmaya tatlı bakışa özlemler içindeyim

Aşk dediğimiz bir yanı aydınlık bir yanı karanlık

Bir ucu tatlı bir ucu acı yaşamlık

Ben kararmışım gözlerimi bu uğurda

Ben germişim kanatlarımı sevda namına

Süzülürümde konarım gönül dağındaki o ulaşılamaz bağrına

Düşlerim sevdalara kanat çırpmayı

Sevda türküleriyle eserim hülyalardan

Ben yalnız bir dağ kırlangıcıyım ömrüm kısa

Arıyorum seni sevda ovalarında

Ömrüm yetermi bilemem amma

Düşlerim sevdalara kanat çırpmayı

Bir küçük mutluluğa hasret kalmışım bu cihanda', 'Düşlerim sevdalara kanat çırpmayı Cihana gök mavimden bakmacasına Bulutların tepesinde sevmeyi  Kimsenin ulaşamayacağı o görünmez ufuklarda ...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ben-yalniz-bir-dag-kirlangiciyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-ali-osman-yilmaz-vns0j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne güzel şeysin

Sen çocuk,

En güzel şey,

Sensin çocuk.

İki gönül bir olunca,

Sen gelirsin çocuk.

Saflığın en güzeli,

Sevgimizin çiçeği,

Mutluluğun temeli,

Yaşanacak yılların,

En güzel şeyi,

Sensin çocuk.

Yaşanmamış yılların,

Tadılmamış tadların,

Bir gecelik günahların,

En güzel aşkların,

Meyvası sensin çocuk.

Bütün ümitlerimiz sende,

Şöyle bir büyüsende,

Bütün dualarda,dileklerde,

Mutluluklar ülkesinde,

Şimdi yaşama sırası sende,

Dilek ağacımızın meyvası,

O Güzel şey,sensin çocuk.', 'Ne güzel şeysin Sen çocuk, En güzel şey, Sensin çocuk. İki gönül bir olunca, Sen gelirsin çocuk. Saflığın en güzeli, Sevgimizin çiçeği, Mutl...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cocuk-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buğday Tanesi', 'bugday-tanesi-hikmet-feridun-demir-fkstg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir Buğday Tanesi,

Buğday tanesi düştü toprağa…

Yeşerdi, 

bir Taneden, 

Buğday Tanesinden; 

iki yana dizili, 

Her yana iki sıralı,

Toplam dört sıralı,

Her sırada üst üste sekiz taneden,

Toplam  otuziki tane Tane yeşerdi… 

Oldu bir Başak…

Otuziki hayat yeşertecek otuziki Tane,

Otuziki tane Buğday Tanesi tekrar düştü Toprağa,

otuziki kere otuziki eder binyirmidört tane Tane..

Her Tane bir Hayat …

Her hayat bir Beyin…

Bir Tane, bir Buğday Tanesi oldu binyirmidört Hayat…

Taneler tekrar tekrar tekrar...tekrar düştüler Toprağa...

Matematik bilirmisin...

Ben daha başındayım işin…

21.11.2004  Wermelskirchen-Almanya', 'Bir Buğday Tanesi, Buğday tanesi düştü toprağa… Yeşerdi,  bir Taneden,  Buğday Tanesinden;  iki yana dizili,  Her yana iki sıralı, Toplam dö...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bugday-tanesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şekilsiz', 'sekilsiz-gokhan-oflazoglu-faaq5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hem buyum hem o

anlaşılan, neden

tek şekildeyim.

Bırakınca iplerimi,

biçimsiz bir engindeyim.

Akıl çizemiyor sınırlarını,

bu yaşananı nasıl ileteyim.

Herşey belirsizleşiyor,

nefes almak da güç.

Bulunduğum yer, yere

göğe benzemiyor.

Ben neredeyim.

Sakince dönsem evime,

sığsam eski şeklime.

Dinse korkum ve sızım.

Bildiğim aynalarda baksam

yüzüme.

21/11/2004', 'Hem buyum hem o anlaşılan, neden tek şekildeyim. Bırakınca iplerimi, biçimsiz bir engindeyim. Akıl çizemiyor sınırlarını, bu yaşananı nasıl ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sekilsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzüldün mü Hiç', 'uzuldun-mu-hic-kamil-aydemir-ovvs9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'elin soğukluğu kaldı bende

bir de benden zorla kopardığın

   içindeki çocuğun son bakışı

hep yaşıyacağım

  ve hep taşıyacağım

umman sevdamın karşılğında

bana verdiğin karakışı

üzüldün mü hiç

yalnızlığıma ittiğinde hüzünler beni dişlerken

ve ömrüme acımasızlığınla işlerken

bunca acı nakışı

böyle mi öğretti annen sana sevmeyi

neden kırıyorsun umutlarımı

vuruyorsun düşlerimi

seni sevmenin mutluluğunu da mı çok görüyorsun bana

yoksa mastırını mı yaptın acımasızlığın

utancı sana kalsın istemiyorum bir aşka kıymanın

elin soğukluğu kaldı bende

gözlerimle gözlerinin arasına giren kipriklerin birde

o anda

dudaklarında dudaklarımla yürümek vardı

ısınırdı üşüyen bedenin

ve bayram çocukları gibi sevinirdi güzelliklerin

seni bende yaşamaktır biraz da sevmek

yakışmaz hiç bir kadına

sana yakıştığı kadar gülmek

kafkasların ak gülü

sen bu korkaklığınla

bu kaderci halinle

nasıl yakalayacaksın mutluluğu

görülen o ki hep ağlatacaksın içindeki çocuğu

gün gelecek

taşıyamayacaksın onca kederi gamı

arıyacaksın bu onurlu sevdamı

daha fazla kırıp dökmede

benden bir şeyler kalsın o güne

istersen ölümden berbat engeller ör

geçemesin sevginin önüne

yoksa mastırını mı yaptın acımasızlığın

çıkmaz sokak(lar)   gibidir sevgisiz hayat

kulak ver güllerin ezgisine

seven yüreğimin türküsüne

hayatın lirik sesine

kendinden küsme böylesine

seni de yutar yarınsızlığın

bende elin soğukluğu kaldı

aramızda korkuların

sen değilsin ki kurban vaz geç kendine kıymaktan

bu kadar da korkulmaz ki sevilmeten

 kendine bir dünyayaratmışsın acılardan

ve o dünyada içini karaltmışsın

bir kez olsun perdeleri açta bak

sana karakışın ortasında bahar sunuyorum

tutunacak düşlerin umutların

sırtını yaslayacak sevgin sevenin yoksa

sana gülmez ki yarın

elin soğukluğu kaldı bende

sevgimin sıcaklığı sende

razıyım senin yerine donmaya

                          kanamaya

yeterki sen üşüme

                    sen üzülme

senden değerli değil hiç bir şey bana

geceleri uyku girmese de olur gözüme

kirlense de bir çok şey

k i r l e n m e d i    b u     ş a i r

nokta kadar çıkar gözetmeksizin seviyorum seni

beni anlamamış olman gider gücüme', 'elin soğukluğu kaldı bende bir de benden zorla kopardığın    içindeki çocuğun son bakışı hep yaşıyacağım   ve hep taşıyacağım umman sevdamın...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/uzuldun-mu-hic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme,Dön Geri', 'gitme-don-geri-nihal-gungor-t4bnd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni böyle de mi görecektim.

Öylece yatarken,sessiz.

Koşamazdın,yürüyemezdin

ama bülbül gibi şakırdın.

Gitme,dön geri güvercinim,

gitme,dön geri.

Avuçlarına yanaklarımı doldurdum

sonra yüzümü,    lokumum.

Isındı kızarmış soğuk burnum,

kurudu gözlerim.

Terini,tenime sürdüm.

Gamzeni beynime çizdim.

Şaka gibi uyurken,akan bir damla gözyaşını,

kalbime hapsettim,hatıra olsun diye.

Gitme,dön geri güvercinim,

gitme,dön geri.

Ellerini ellerime sakladım,

yüzümü boynuna.

Kokunu içime çektim.

Kulağına vaadler söyledim,

belki duyarsın diye.

Yüzünü hafızama yazdım.

Adını kalbime.

Sesini unuttum.

Nefesini unuttum.

Gitme,dön geri,güvercinim,

gitme,dön geri.

-------

-------

Dünya yıkıldı.

Yüreğim durdu.

Rahat uyu,güvercinim.

Seni özledim.

        (30.10.2003)', 'Seni böyle de mi görecektim. Öylece yatarken,sessiz. Koşamazdın,yürüyemezdin ama bülbül gibi şakırdın. Gitme,dön geri güvercinim, gitme,dön ...', ARRAY['Türk Edebiyatı','Şiir','Nihal Güngör']::text[], 8.5, '{"poet":"Nihal Güngör","poet_slug":"nihal-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gitme-don-geri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esmerim', 'esmerim-nihal-gungor-4gvjf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Esmer tenin,

mutlu günler gibi sıcakken,

hep soğuk mu durmaya çalışacaksın? 

Beceriksiz sevdiğim,

hep gözlerindeki aşkı sakladığını zannedip,

gözlerimdeki aşkı anlamayacak mısın? 

         (16.5.1992)', 'Esmer tenin, mutlu günler gibi sıcakken, hep soğuk mu durmaya çalışacaksın?  Beceriksiz sevdiğim, hep gözlerindeki aşkı sakladığını zannedip...', ARRAY['Türk Edebiyatı','Şiir','Nihal Güngör']::text[], 8.5, '{"poet":"Nihal Güngör","poet_slug":"nihal-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/esmerim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Gibi', 'yalan-gibi-gokhan-oflazoglu-74s2p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman da yarılır, beynim de,

azgın sular dolar, tenim dağılır.

Burda eski bilgilerin hükmü yok.

Yenilerine de benim gücüm yok.

Dağılsa şekiller, uçsam tüy gibi.

Sonsuz saltanat bir an gibi.

Dinlemeyin beni, bütün söylediklerim

yalan gibi.

21/11/2004', 'Zaman da yarılır, beynim de, azgın sular dolar, tenim dağılır. Burda eski bilgilerin hükmü yok. Yenilerine de benim gücüm yok. Dağılsa şekil...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yalan-gibi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuğum', 'cocugum-gokhan-oflazoglu-kx6na', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocuğum henüz doğmamış; 

elinden tutmuşum okula gidiyoruz.

Sessiz, sakin; bir ara ceplerini 

karıştırıyor, zaman diyoruz.

Bilgiler, bilgiler üstüne, çocuğum

büyüyor, hala eli ellerimde.

Artık kendi yollarında yürüse,

engel engel üstüne; dönüp

öyle bakmasa yüzüme.

Çocuğum zorluklar yıldırmasın,

mutluluk olabilir, kaynaşan bir

gelecekte. Orda da elinden

tutan olur, bakışlarındaki hüzün

kaybolur; bir dene.

21/11/2004', 'Çocuğum henüz doğmamış;  elinden tutmuşum okula gidiyoruz. Sessiz, sakin; bir ara ceplerini  karıştırıyor, zaman diyoruz. Bilgiler, bilgiler...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cocugum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Dem Ayrılık', 'her-dem-ayrilik-tunahan-ermihan-gmlbq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vazgeçtim sevdiğim en deli sevişmelerimizden

Yağmurlu ve fırtınalı bir günün sabahında

Benim ayrılıklarım hep cumartesilere mahkûm

Yâda cumartesiler benim ayrılıklarıma

Vazgeçtim sevdiğim gözlerine bakmaktan

Binlerce yıldız ve bilinmeyen âlemler keşfetmekten

Oralarda senle birer ömür yaşayıp dönmekten

Ve sevdiğim senle ölmekten vazgeçtim

Vazgeçtim sevdiğim ellerini tutmaktan

Her dem sıcaklığınla yanmaktan ve sönememekten

Kendimi sonbahara son kez teslim ederken

Seninle bir bahardan vazgeçtim', 'Vazgeçtim sevdiğim en deli sevişmelerimizden Yağmurlu ve fırtınalı bir günün sabahında Benim ayrılıklarım hep cumartesilere mahkûm Yâda cuma...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/her-dem-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnadına Yaşatacağım...!', 'i-nadina-yasatacagim-hayrettin-orak-ununk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu son Sevda, bu son ağıt,

Sanmaki sensiz bu sevdayı yaşayacağım,

Sevda bahçeme senin için güller ekeceğim,

Sevdam için katlanacağım, acı çekeceğim,

Esaretlik olsada senin sevdanla mutlu olacağım,

Bu son bahar, hazan mevsimi,

Yaprak dökümü, sevda tomurcuklarını özleyiş,

Belki yalnızlığıma bir kıvılcım, 

Yüreğimdeki alevi kudurtan, bir son bahar rüzgarı,

Arayacağım gerçek bir dost, bir can yoldaşı,

Seni beklesem bile beklemekten bıkmayacağım.

Belki bilemiyeceksin sana olan sonsuz sevdamı,

Senin için çırpınan yüreğimin ızdırabını,

İsyan edeceğim, yalnızlıklar içinde sensizde kalacağım,

Acı çeksemde, yansamda, sana kahretsemde,

Sensiz bu sevdayı inadına yaşatacağım.

Her günümde, her anımda sen varsın,

Sensizlik hayatımda anlamsız bir taş duvar,

Sesini duymak ister seni seven yüreğim,

Sana adadığım masum aşkıma bir fırsat ver,

Tek dileğim bu son sevdamı yaşatmak,

İzin ver birtanem seninle, sevdamla yaşıyayım.......! 

21.11.2004', 'Bu son Sevda, bu son ağıt, Sanmaki sensiz bu sevdayı yaşayacağım, Sevda bahçeme senin için güller ekeceğim, Sevdam için katlanacağım, acı çe...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/inadina-yasatacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutsuz Gülümseme', 'mutsuz-gulumseme-hasan-can-i8vxn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben o şarkıyı her duyduğum da,

Aklıma hep sen gelirdin.

Gülümse derdin, mutsuz olsam da,

Gülümserdim.

Hala gülümsüyorum ve hala mutsuzum.

En çok seni kaybetmekten korkardım,

Geceleri hiç uyumazdım kederimden.

Birgün çekip gidecektin,

Korkularım bunu açıklıyordu,

İstesende istemesende gidecektin,

Ve gittin...

Gittin çünkü; gitmemen için,

Bir neden yoktu, yada kalman için.

Senin gözlerinde sevgi adına,

Bir ışıltı bile yoktu bir tebessüm bile.

Gittin çünkü; sevginin,

Ne demek olduğunu bilmiyordun,

Sevgi iki günlük değildi düşünmedin bile.

Dilerim içinde bir ateş yanar,

Ve o ateş benim ne çektiğimi anlatır sana,

Dilerim sevgi denen o hikayeyi sende yaşarsın,

Ve onun uğrunda nelerin göze alındığını anlarsın...', 'Ben o şarkıyı her duyduğum da, Aklıma hep sen gelirdin. Gülümse derdin, mutsuz olsam da, Gülümserdim. Hala gülümsüyorum ve hala mutsuzum. En...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mutsuz-gulumseme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sus Sen Sus', 'sus-sen-sus-abdullah-garip-y8gy8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sus sus konuşma sen

Gözlerin konuşsun

Unutamıyorum sesini ben

Benliğim olmuşsun

Gözlerin o gözlerin senin

Gönlümde derya olmuşsun

İnce bel, sırma saçların senin

Kalbime taht kurmuşsun', 'Sus sus konuşma sen Gözlerin konuşsun Unutamıyorum sesini ben Benliğim olmuşsun Gözlerin o gözlerin senin Gönlümde derya olmuşsun İnce bel, ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sus-sen-sus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda..!', 'elveda-hayrettin-orak-x7mp0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elveda dostlarım gidiyorum artık,

Bütün umutlarım, asi sevdam sizlerin olsun,

Soranlara bir dosttan emanet dersiniz,

Umutlarımı, sevdamı yalnız bırakmayın,

Dostalrım sizlere emanetim bu sakın unutmayın.

Acı çektim yandım, yüreğimdeki sızıyla kahroldum,

Bir kez olsun, son sevdama tutunup onunla yaşıyamadım,

Gecelerce bekledim, her gün onun için ağladım,

Gözlerim, umutsuzluğumun esareti altında çürüdü,

Yüreğimi yakan aşk acısının hasretini, 

Sevda bahçesinin çeşmeside söndüremedi,

Gidiyorum dostlarım sizlere Elveda..........

Sakın düşünmeyin, giderek mutlu olacağımı,

Belki bir daha gelemem umutlanıp beklemeyin,

Aşk defterinin sayfasını artık kapatıyorum,

Hiç bitmiyecek umutlarım tek tesellim benim,

Belki, dayanamam, unutamam dönerim geri,

Bu son umudum benim, belki onsuzda olamam,

Bekleyin, bekleyin dostlarım, belki gelirim....

Gidişimle yalnız kalan gülümü soldurmayın,

Yalnızlıklar içinde, hatıralarımı yalnız bırakmayın,

Gideceğim bu ellerden sizleri, yarimi unutamasamda,

Beni yalnız bırakan, terkeden, kara sevdama yanıyorum,

Onsuz her gün acı çekip yanıyorum, kahroluyorum,

Yeter tutunacak tek dalım sevda yoldaşım kalmadı,

Bu son elveda, unutmak, boş vermek ve gitmek...

Hey be nazlı bebeğim,hey be gülüm,

Ben asi sevdaların esiri olacakmıydım,

Geçit vermeyen dağlarda sürgün gezecekmiydim,

Kara sevdalara düşüp, deli divane olacakmıydım,

Bir de senin gibi bir hayırsıza aşk kölesi olacakmıydım,

Gidiyorum dostlarım sizlere elveda....

Son sözüm sana sevda ateşim,

Küçücük yüreğimi volkan ateşlerinde yaktın,

Sürgün aşklarının yaşandığı çöllerde gezdirdin,

Aşımda, uykumda, düşümde hep sen vardın,

İçtiğim aşk şarabından serhoş olmuşken,

Aşkının mutluluğunu, teninin sıcaklığını bana çok gördün,

Tek dileğim son sevdamla mutlu olmaktı,

Çaresi olmayan dermansız yarama ilaç bulmaktı,

Bedenimi çürüten, yıkık virane aşklarımı temizlemekti,

Bunu bana çokmu gördün zalim kader,

Son bir fırsat vermedinki bana, son aşkımı yaşayayım,

Tüm umutlarım, kara sevdam, mutluluğum al senin olsun,

Yeter, yeter acı çeksemde gidiyorum artık,

Gidiyorum dostlarım, Sizlere Elveda.................! 

21.11.2004', 'Elveda dostlarım gidiyorum artık, Bütün umutlarım, asi sevdam sizlerin olsun, Soranlara bir dosttan emanet dersiniz, Umutlarımı, sevdamı yal...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/elveda-122-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir...!', 'siir-hayrettin-orak-egq0g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sevdanın mutluluk ifadesi, 

Yıkılmışlığın dert ortağı, 

Masum bakışların ifadesi, 

Yürekten kaleme dökülen duygular, 

Kimi zaman mutluluk ifadesi, 

Kimi zaman bir isyanın haykırışı, 

Kimi zaman bir sevdanın anlatımı, 

Kimi zaman ayrılığın acısı, 

Kalem değildir şiiri yazan, 

Yürekten gelen duyguların kaleme işleyişidir, 

Kimi zaman en büyük mutluluklar, 

Kimi zaman yanan yüreklerin sancısı, 

Kimi zaman bir yakarış, 

Kimi zaman baş kaldırışın çığlıkları, 

Yinede bir güzelliğin ifadesi, bir paylaşım, 

Bir mutluluk, bir acı,

Yüreklerdeki güzelliktir Şiir............! 

(Bu şiiri Şiir Perisi grubunun, konusu ''''ŞİİR'''' olan, '''' Haftanın Konusu'''' adlı aktivitesi için kaleme aldım) 

(21.11.2004 - BATMAN)', 'Bir sevdanın mutluluk ifadesi,  Yıkılmışlığın dert ortağı,  Masum bakışların ifadesi,  Yürekten kaleme dökülen duygular,  Kimi zaman mutlulu...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/siir-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '^^^ Umut Çiçegim ^^^', 'umut-cicegim-gulsen-senderin-iwznf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'L eyla''mızsın hoş geldin soğuklar ülkesinden

İ  nançlı sevdanla yaşa aşkı, yaşa gönül sesinden

G urbet kuşu sen de ben gibi sınırlar ötesinden

A ramıza hoş geldin, sana sevgiler hepimizden! 

G ül yüzün, yeşil gözlerin açsın hep ufukta

R enk renk açarken hayat, sevdan kalsın dorukta

U laş sen de mutluluğa, aldığın her solukta

D eğmesin nazarlar sevgi değsin hep aşk değsin

U nutma ezeli AŞK''tasın; ŞENDERİN''desin! 

L al olan emelde nur ol, yaşat hep umutla

E r  o gizemli mutluluğa, ana ol yol al sebatla! 

.....

Ş en oldu bağım, Onbes Ekimde doğdu ''CUMHUR BEBEK''

E n''lerin muhteşemiyle, gelinim sen çok yaşa

N ar çiçekli, nar ateşli, uzun kızıl saçlı melek

D ağlarda açmamıştır; yalınlığıyla böyle bir çicek

E rdik ailecek bu mutluluğa, gelinim sen çok yaşa

R üyamızı süsleyen:- o oğul düşünü- yaşattın bize

İ nanılmazı başardın, neşe can verdin içimize

N urtopu bir bebek verdin, güller açtırdın bağımıza!', 'L eyla''mızsın hoş geldin soğuklar ülkesinden İ  nançlı sevdanla yaşa aşkı, yaşa gönül sesinden G urbet kuşu sen de ben gibi sınırlar ötesind...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/umut-cicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '^^^ Sevda Çiçegim ^^^', 'sevda-cicegim-gulsen-senderin-5hw1t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'M uradım özleyişim, sendin özel yuvamda

U mudun ötesinde açtın ''Sevda Çiçeğim''

S enle yeşerdi bağım, bebeğim tek erkeğim

A nnen oldum, çılgınca bir oğuldu isteğim! 

K im tuttu ateşi kim yandı güneş doğarken

O d od yandım seni öperken, sana bakarken

R uhum tutuştu oğul oğul, seni koklarken

K im tuttu ateşi kim yandı güneş doğarken

U mudun meyvesiydin aşkım, ''Sevda çiçeğim''

T at aşkı yan sen de mutluluktan gözbebeğim! 

Ş u acı dünyada şans sensin, umut kendin ol

E r babalık kadrine, yeşersin bağın bol bol

N e aldanışlarla geçecek bu ömür, bu yol

D eğsin mutluluğun birgün gökkubbeye kol kol

E r babalık kadrine, yeşersin bağın bol bol

R uhun gitarda çağlasın müzik neşesinden

İ  nançlı sevdanla aşkı yaşa gönül sesinden

N e hoş bakar erenler, mutluluk gemisinden! 



Gülşen Şenderin', 'M uradım özleyişim, sendin özel yuvamda U mudun ötesinde açtın ''Sevda Çiçeğim'' S enle yeşerdi bağım, bebeğim tek erkeğim A nnen oldum, çılgı...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevda-cicegim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbulu anlatırlardı', 'i-stanbulu-anlatirlardi-i-smail-emre-berber-e4ytq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Martılar konardı bizim konakların üstüne

Gözlerinde özlem, kanatlarında umut ısıgı taşırlar

Ne ben bakmaktan usanırdın nede onlar konmaktan

Hepsi istanbulu alıp getirirlerdi bana hiç görmedigim istanbulu

Merak ederdim hep görüp gelenler anlatırlardı ballandıra ballandıra

Sorardım hiç usanmadan istanbul nasıl bir yer diye

Emirganı selimiyesi dolma bahcesi ha bide top kapı sarayı

Daha saymakla bitmez görmeden anlatılmaz derlerdi.

Bitmek bilmeyen özlem gözlerimde kavuşamamanın yaşları süzülürdü

Yalvarırdım martılara neolur benide alıp götürün hayallerime diye

Alcakaranlık çöktüğünde içimde bir yanlızlık ürkek bir bakış atardım

Kavuşacagım günü bekler dururdum günler su gibi akıp gecerdi...

 

                                                                                           İ.EMRE BERBER', 'Martılar konardı bizim konakların üstüne Gözlerinde özlem, kanatlarında umut ısıgı taşırlar Ne ben bakmaktan usanırdın nede onlar konmaktan ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Emre Berber']::text[], 8.5, '{"poet":"İsmail Emre Berber","poet_slug":"i-smail-emre-berber","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/istanbulu-anlatirlardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '^^^ Hasret Çiçegim ^^^', 'hasret-cicegim-gulsen-senderin-n18fw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'H asret mi koysaydım adını; hep gurbettesin

A ldığım ilk müjdem, o tutkulu servettesin

T utunca yumuk ellerini, duydum yanarak

E n güzel duygularda açan ağlayış sesini

M or sümbül, pembe gül kıskandı tebessümünü! 

A dın '' Eflatun Cem Güney''den'' şevkin annenden

S eni seven her kalbten öte ''AŞK'' Babişkondan

L eylak nergis sordu göğsümde açan kokuyu

I şıl ışıl saçtın; senden aldım ilk duyguyu! 

Ş u an uzaktasın, istemem hiç acı bilme

E mel sevda hoşnutu ol da, gözyaşın silme

N adide hasret çiçeğim, seven şu kalbimle

D ağlara kafa tutarım, tek gül verişinle

E llerin koynumda gözlerin yanar karşımda

R enklenir dünyam şenlenir ''ANNE'' çağrısında

İ nan hep açar, o ilk duygu çiçeği bağrımda

N ar çiçekler, nar ateşler hep gözyaşımda! 



Gülşen Şenderin 

.', 'H asret mi koysaydım adını; hep gurbettesin A ldığım ilk müjdem, o tutkulu servettesin T utunca yumuk ellerini, duydum yanarak E n güzel duy...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hasret-cicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım yanlızlık', 'adim-yanlizlik-i-smail-emre-berber-1i1e5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anlamsız maniler söyler dünya ile dalga geçerdiYıkık yüreklerimize ümit verir sonrada bizimle alay ederdi Kukla misali hayaller hiç bitmez sevinç dolardı odalarımıza

Şimdi zaman 9 za 5 var yine kapımı çalıyor hüzün ile bide göz yaşı var

   Nasibde ne var bilinmez dert tasa bizden hiç eksilmez

   Nerde eski alabildigine eylendigimiz eylenceler

   Hatırlarmısın attıgımız kahkalarla aşındırdığımız yolları

   Parlak bir gelecek kimimiz doktor kimimizse neyse boşver

   Şimdi ordayım ben ama tek başıma boynum bükük bakıyorum

   ıslak bide bahtı karanlık yollara,yıkık virane icinde 

   Bense olayın tam içinde 

   Nerde kaldı o eski güzelim anılar,bagıra bagıra söylediğimiz şarkılar

 

   Avare gecen yılların eziyeti üstümde yüzümde gecenin karanlığı

   Gemiler yaklışıyor hemen hemen demir alacak bu yapayanlız yüregime

   Ah demeden edemiyor insan gözler camlardan hiç ayrılmıyor

   Bide gelmişsin gibi kapının ürkek tıkırtısı ümit veriyor adım yanlızlıga

 Bakardım ardından canım gidiyor yarim gidiyor içimde sen gidiyorsun', 'Anlamsız maniler söyler dünya ile dalga geçerdiYıkık yüreklerimize ümit verir sonrada bizimle alay ederdi Kukla misali hayaller hiç bitmez s...', ARRAY['Türk Edebiyatı','Şiir','İsmail Emre Berber']::text[], 8.5, '{"poet":"İsmail Emre Berber","poet_slug":"i-smail-emre-berber","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/adim-yanlizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Türkümüz.', 'sevda-turkumuz-hayrettin-orak-8pcgc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana delice sevdadan bahsedin,

Benki o sevgiliye sevdamı hatırlıyorum,

Sevgiliyi beklerken çektiğim sevda naralırını,

Sevda fısıldayan sabahçı kuşlarını hatırlıyorum.

Belki sevdanın en yücesini seninle yaşadık,

Kaldırım taşlarında yürüdük sevda ateşiyle,

Kapılarda sabahladık sabahlara dek,

Hiç mi hiç bıkmadık usanmadık bu sevdadan,

Rüzgarın yapraklara vuruşunu hissettim seninle,

Gecenin ürperten soğuğunda üşüdüm,

Islatan çisesinde sabahladım senin için,

Aşkının ateşiyle üşüyen ellerimi ısıttım,

Bıkmadım sevdamızın o tatlı türküsünden.....

Sana sevdalanmak benim için en büyük mutluluktu,

Doymak zevk almak, hayata sarılmaktı,

Bilemiyorum yaşadığımız en güzel sevdaydı,

Sevda türkümüzü dağlara dinletmemiz.

Oysaki sevdanın en yücesini yaşadık,

Issız sokaklarda bom boş kaldırımlarda,

Ama, ama ayrılık koymadıkki adını aslaa..

delice yanarak, kavrularak sonsuz dek.

Küstü dağlar, geçit vermez oldu yollar,

Sevdamızın türküsünü hep bekledi, dinleyen dağlar,

Ve bizi bekledi o gezdiğimiz boş kalan kaldırımlar, yollar,

İşte ben ayrılığın acı hüsranını yaşadım.

Sevmek, sevilmek, sevdalıya sevdalanmak,

Delicesine, yanarcasına ve mertçesine,

Kor olmuş kalbim senin sevdanla yanarken,

Ayrılık sözü varmıydı Aşk şarkımızda....

Ben''ki sevdanın en yücesini yaşadım,

Sensiz boş sokaklarda, boş kaldırımlarda,

Sensiz bedenimde yaşattığım sevdamla,

Ben sana sevdamı, senden daha çok Sevdim......! 

Tek dileğim, Tek arzum, Sevda türkümüz son bulmasın.........! 

21.11.2004', 'Bana delice sevdadan bahsedin, Benki o sevgiliye sevdamı hatırlıyorum, Sevgiliyi beklerken çektiğim sevda naralırını, Sevda fısıldayan sabah...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sevda-turkumuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '^^^ Fırtına Çiçegim ^^^', 'firtina-cicegim-gulsen-senderin-o2fm0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'F ırtına çiçeğimsin esintilerden akışlı

A çtın sevgi bahçemde, gülüşün güneş yakışlı

T akım takım yıldızlardan sevgilerin sayışlı

M utluluklar serpiştiren, fırtınalı yağışlı

A çar rüzgarların savurur, aşk sevda bağışlı! 

G özlerinin menekşesi şimdilerde kahveli

Ö dünsüz hislerin parçalı, nazların cilveli

K oparmak ister düşler, taşırıp da seni senden

Ç içeğim koparamam asla, severim içimden! 

E s  yüregime, yine es; bebek yakislarina aliskin annen

Ş ans eseri Tanrı bana bağışladı bebeğim

E rtesiz ölümü yaşadım kimse yaşamasın

N edenini bilemem sonrasında fırtınasın

D edenin miniği, Babişkonun ceviz ağacı

E meline tak aşkı, yakışır mutluluk tacı

R uhundaki fırtınaya Güneş Gülleri açsın

İ ncitmeden yine es, uzun saçına asılsın

N ar ateşli sevdalar, hep sev '' FIRTINA ÇİÇEĞİM ''!', 'F ırtına çiçeğimsin esintilerden akışlı A çtın sevgi bahçemde, gülüşün güneş yakışlı T akım takım yıldızlardan sevgilerin sayışlı M utlulukl...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/firtina-cicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Okları....!', 'hasret-oklari-hayrettin-orak-3csjo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana nasıl anlatsam bilemiyorum,

Senin için yaşadığım delice sevdayı,

Ellerini arayan, ellerimin yalnızlığını,

Kor olmuş, beni yakan, kara sevdamı,

Nasıl, nasıl anlatsam bilemiyorum...

Yalnızlıklar içinde kaldım korkuyorum,

Kimsesizlik, sensizlik bedenimi çürütüyor,

Yanan kor olmuş gönlüm, senin aşkınla alevleniyor,

Sensiz bedenim buz tutmuş, tir tir titriyor,

Sana nasıl anlatsam bilemiyorum...

Sana gelmek, sana sarılmak istiyorum,

Seni aratayan gözlerim, yalnız duvarda asılı resmini görüyor,

Odama sinmiş mis kokun, yalnızlığıma teselli oluyor,

zaman, saat, gün geçmek bilmiyor,

Sana nasıl anlatsam bilemiyorum...

Elveda dediğin o gün, ömrüm hazan oldu,

Son bahar gelmeden, sevda tomurcuklarım döküldü,

Hırçın gök yüzü hasrete ağladı, asi rüzgar isyanını haykırdı,

Ne seni duydum, nede seni hissettim,

Hasretimi sana nasıl anlatsam bilemiyorum...

Sana ansıl anlatsam delice hasreti,

Sana koşmak, sana seslenmek, sana sarılmak istiyorum,

Ama nafile, uzatıyorum ellerimi ellerim bom boş kalıyor,

Gözlerimi kapatıyorum, hayalimde seni görmek için,

İmkansızlıklar içindeyim, yalnızlıklar içinde,

Şuan bom boş odamda seni arıyorum,

Gözlerim duvarda asılı duran resmine yalvarırcasına bakıyor,

Senin için hasretim, gözlerimde yaş oluyor,

Köhne odama sinmiş bedeninin kokusu tesellim oluyor,

Yokluğuna katlanıp, gelmen için rabbime yalvarıyorum,

Gün ağarmış sabahçı kuşları sevda fısıldıyor,

Pencerenin perdesini aralayarak, aşkımızın nağmelerini aradım,

Kuşların sevda fısıltıları''da yokluğunu unutturamıyor,

Sensiz geçmeyen günler benim için hasret okları,

Yüreğimi yırtarak, dağlayarak parçalıyor..............! 

21.11.2004', 'Sana nasıl anlatsam bilemiyorum, Senin için yaşadığım delice sevdayı, Ellerini arayan, ellerimin yalnızlığını, Kor olmuş, beni yakan, kara s...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/hasret-oklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eda Gelir Aklıma', 'eda-gelir-aklima-ozkan-gonlum-6hsrv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Görünce mavi gözü

			Duyunca tatlı sözü

			Benim canımın özü

			Eda gelir aklıma.

			Her zaman gün boyunca

			Dede sesi duyunca

			Bir de hasret olunca

			Eda gelir aklıma.

			Uykumun sırasında

			Gecenin yarısında

			Düş - gerçek arasında

			Eda gelir aklıma.

			O sevimli gelişiyle

			''''Dede'''' deyip gülüşüyle

			Yürekten öpüşüyle

			Eda gelir aklıma

			Eda'' nın olduğu yerde

			Dertler sona erer de

			''''Deva'''' diye her derde

			Eda gelir aklıma.

			Bellidir her halimden

			Onunla doluyum ben

			Adı düşmez dilimden

			Eda gelir aklıma.

                                              

                                                EDA BİZE GELİNCE

			Dede! . geldim, diyecek

			Mutluluklar verecek

			Başım göğe erecek

			Eda bize gelince.

			Dertler bizden kaçacak

			Gönlüm zevkten uçacak

			Evde neşe saçacak

			Eda bize gelince.

			Gökten melek inecek

			Ağrılarım dinecek

			Gün bayrama dönecek

			Eda bize gelince.', 'Görünce mavi gözü 			Duyunca tatlı sözü 			Benim canımın özü 			Eda gelir aklıma. 			Her zaman gün boyunca 			Dede sesi duyunca 			Bir de ha...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/eda-gelir-aklima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşkın Sonu.', 'bir-askin-sonu-hayrettin-orak-pg36k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün yine sensizlik içinde canım sıkıldı,

Dolaştım birlikte gezdiğimiz şehrin yalnız bırakılmış, sevda patikalarında,

Belki mazinin hatırası gözlerimde canlanır, yanan yüreğime su serpilir diye,

Rüzgarda saklanmış mis kokunu belki bulurum diye,

Bedenimi bir ürperti sardı, sanki üşüdü,

Hava sıcak mevsim yaz''dı, birden korktum,

Etrafıma baktım, ayrılık rüzgarının uğultusunu duydum,

Acaba gerimi geldi diye çocukça bir sevinç yaşadım,

Meğer sevincim boşunaymış,

Senin ellerini başkasının ellerinde gördüm o an......! 

Tertemiz Aşk bağdelerimizi kirlettiğin o zaman,

Gök yüzünde binlerce şimşek çaktı, ve ansızın sağanak yağmur başladı,

Yağmur damlaları aşkımıza ağlıyordu,

Aşkımızdan ve senden kalan son hatırlarıda o yağmur temizledi....! 

Bir aşkın, yaşanan güzelliklerin son bulmasıydı Birtanem............! 

21.11.2004', 'Dün yine sensizlik içinde canım sıkıldı, Dolaştım birlikte gezdiğimiz şehrin yalnız bırakılmış, sevda patikalarında, Belki mazinin hatırası ...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-askin-sonu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al cevabını', 'al-cevabini-ozkan-sahin-7nadx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çek kayıkçı kayığı

Vur küreği denize

Deniz kızmaz

Gülmez

Tuzu kuru aldırmaz

Daha hızlı daha derin

Boşalt içindeki

Öfkeyi

Kusmadan

Vur denize küreğini

Tüket gücünü,

Tuzun kuru değil

Tanrıya bırak öcünü

Ve al cevabını

Yaşamanın

Ölmenin mantığıyla.

                           07,11,2003', 'Çek kayıkçı kayığı Vur küreği denize Deniz kızmaz Gülmez Tuzu kuru aldırmaz Daha hızlı daha derin Boşalt içindeki Öfkeyi Kusmadan Vur denize...', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/al-cevabini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemin.', 'yemin-hayrettin-orak-dd428', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşım 18 idi unutmam mümkünmü,

Aşk denizine ayaklarımı uzattığım ilk an,

Sevda yağmurlarında seninle ıslandığım o zaman,

Masumiyet içinde, boşluk içinde bulunan küçücük yüreğimde,

Senin için suladığım sevda tomurcuğunu unutmam mümkünmü.

Seninle bir hayalimiz vardı, masallar ülkesindeki gibi,

Sevda ülkesinin merdivenlerinde, el ele, göz göze yürümekti,

Aşkların en güzelini, seninle sonsuza dek yaşamak,

Duyguların en yücesini, seninle paylaşmaktı,

Meğer bizim için toz pembe hayallermiş,

Bir kez olsun farkına varamadım,

Sanamı, yoksa günahı olmayan Aşkamı inandım..

Sen varken beyaz rengi tanıdım, sevdim,

Sözlerimizde çiçekler vardı, kutsal elbise vardı,

Seninle yaşayacağımız tekrarı olmayacak o gün vardı,

Bunların hepsi hayalmiydi diye kendime soruyorum,

Ayrılık şarkısının mısralarını mırıldandığında anladım,

Hani bir şarkımız vardı, benim kalbim senin için atacak,

Gönlümüzde başka sevdalara yer olmayacak,

özgürlük güvercini bizim aşkımız için kanat çırpacak,

Sevdamızda asla ve asla ayrılık olmayacaktı,

İşte bu şarkının tesellisi ile avunuyorum...! 

Aşk zincirlerini kilitleyen birde yeminimiz vardı,

Sevdayla birleşen ellerimiz ayrılmayacak,

Seni gören gözlerim senden başkasını görmeyecek,

Eğer bir gün aşkımızda ayrılık olursa,

Sevdamızı gök yüzünde, sokaklarda, çiçeklerde,

Sonsuza dek yaşatacaktık,

İşte bu yeminede inanmıyorum,

Neden isyan ediyorsun diye sakın sorma,

Sana, Sevdama yeminler olsun''ki,

Gönlümde senden başkasına yer olmayacak........! 

21.11.2004 / BATMAN', 'Yaşım 18 idi unutmam mümkünmü, Aşk denizine ayaklarımı uzattığım ilk an, Sevda yağmurlarında seninle ıslandığım o zaman, Masumiyet içinde, b...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Orak']::text[], 8.5, '{"poet":"Hayrettin Orak","poet_slug":"hayrettin-orak","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yemin-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yastık', 'yastik-salih-demirci-xgfvg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Marşına basıldı 

Çıplak ayakların

Işığını iyi sık

Nemin düşmesin 

Dünkü gölgelere

İçine düşmeden 

Varılmıyorsa girdabına

Bu diyar 

Bir yastık olamaz rüyalarına

Kuş 

İyisi mi? 

Unut sen bizi

Gelemeyiz seninle

Ödünler çeker 

Eski perdeleri

Göremeyiz seni

Cevapsız kalır akşamlar', 'Marşına basıldı  Çıplak ayakların Işığını iyi sık Nemin düşmesin  Dünkü gölgelere İçine düşmeden  Varılmıyorsa girdabına Bu diyar  Bir yastı...', ARRAY['Türk Edebiyatı','Şiir','Salih Demirci']::text[], 8.5, '{"poet":"Salih Demirci","poet_slug":"salih-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yastik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eda Bize Geliyor -1-', 'eda-bize-geliyor-1-ozkan-gonlum-eaii8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Annesiyle babasıyla

Çıkarak Konya'' dan yola

Uğramadan sağa sola

Eda bize geliyor.

Maviş - maviş gözlerle

Baldan tatlı sözlerle

Bayramlaşmaya bizlerle

Eda bize geliyor.

Evimiz neşe dolacak

Sevilecek kucak - kucak

Bizde misafir olacak

Eda bize geliyor

Doyum olmaz bu sevgiye

''''Baba anne.. dede.'''' diye diye

Bayramda el öpmeye

Eda bize geliyor.

Dört gün bizde kalacak

Dünyamız onunla dolacak

Çifte bayram olacak

Eda bize geliyor.

           21.Şubat.2001  Kurban Bayramı', 'Annesiyle babasıyla Çıkarak Konya'' dan yola Uğramadan sağa sola Eda bize geliyor. Maviş - maviş gözlerle Baldan tatlı sözlerle Bayramlaşmaya...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/eda-bize-geliyor-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eda Bize Geliyor -2-', 'eda-bize-geliyor-2-ozkan-gonlum-gtp15', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yolda bizi ana - ana

		İki aydan bu yana

		Daha büyümüş olarak

		Gönlümüze dolarak

		Eda bize geliyor.

		Tıpış - tıpış yürüyerek

		Eteğini sürüyerek

		Mavi gözde gülücükle

		Gül dudakta öpücükle

		Eda bize geliyor.

		Yandan - yandan eda ile

		'''' Dede..'''' diyen seda ile

		Sevgi ile coşa - coşa

		Özlem ile koşa - koşa

		Eda bize geliyor.

		

 En büyük heyecandır

		Torun candır dedelere

		Boş verdim gama kedere

		Şükürler olsun kadere

		Eda bize geliyor.

o', 'Yolda bizi ana - ana 		İki aydan bu yana 		Daha büyümüş olarak 		Gönlümüze dolarak 		Eda bize geliyor. 		Tıpış - tıpış yürüyerek 		Eteğini s...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/eda-bize-geliyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözleri Var Eda'' nın', 'gozleri-var-eda-nin-ozkan-gonlum-6vmcd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzaklarda olsa bile

			Bakışıyla, her haliyle

			Dağı, denizi aşan

			Gönlümüze ulaşan

			Gözleri var Eda'' nın.

			Binbir renkle döşeli

			Duygu dolu, neşeli

			Yaşanan rüya gibi

			Bir başka dünya gibi

			Gözleri var Eda'' nın.

			Bakışıyla gülüşen

			Bülbül gibi ötüşen

			Kirpiklerle öpüşen

			Gözleri var Eda'' nın.

			Bakışı sanki sözdür

			O ne manâlı gözdür

			Bir emsalsiz bakışlı	

			Mavilerle nakışlı

			Gözleri var Eda''nın.

			Bakışıyla  ''''sev''''  diyen

			Şiirlerle ''''öv'''' diyen

			Sevgi dolu dizdiğim

			Şiir diye yazdığım

			Gözleri var Eda'' nın.', 'Uzaklarda olsa bile 			Bakışıyla, her haliyle 			Dağı, denizi aşan 			Gönlümüze ulaşan 			Gözleri var Eda'' nın. 			Binbir renkle döşeli 			D...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gozleri-var-eda-nin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayıklamalar 1', 'sayiklamalar-1-derya-uysal-wmlc2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşkın yüzü solgun,güzü soguk oluyor 

Geceler sancılı sensizlik sen kadar yoruyor

Sevgiler tutkularla içice 	

düğümlerden bir yumak yaşam

Yaş ilerledikce durulan zamanlar

yaşarken tüm insanlar

Ben yıllarla  bulanıyorum.

Gözlerin anlamlımı gelir birilerine

İnan titretmiyor içimi

Bir zaman tutkular yeşerttim senle içimde 

Şimdi buz gibi bir rüzgarı bıraktım peşinde

Sözlerin çok mu manalı gelir birilerine

İnan en büyük cümlelerinde bile 

Bir nebze duygu kırılmadı içimde

Bir zaman anlamlar vermiştim her sözcüğüne

Şimdi bir merhaba ağır gelir benliğine diye

Kestim selamımı bile..

Hadi yürü

önünde uzun bir yol var

Ne yol kenarlarına ektiğin çiçekler

Ne ezip geçtiğin böcekler 

Ne sevdiklerin 

ne üzdüklerin

hadi yürü 

yürü git sen

ben

çoktan döndüm 

gittiğin o yerlerden.', 'Aşkın yüzü solgun,güzü soguk oluyor  Geceler sancılı sensizlik sen kadar yoruyor Sevgiler tutkularla içice 	 düğümlerden bir yumak yaşam Yaş...', ARRAY['Türk Edebiyatı','Şiir','Derya Uysal']::text[], 8.5, '{"poet":"Derya Uysal","poet_slug":"derya-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sayiklamalar-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayıklamalar 2', 'sayiklamalar-2-derya-uysal-cwoeq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen yalnız gecelerimin soluğusun

gün ağarırken ellerini bıraktığım

çocukluğumsun.

Severken düşünemediğim 

Unutmak için hatırladığım

Yarını olmayan

Yarim kalamayan

Hayalimsin..

Gördüğüm güzellikle 

Hep senin adını verdim

Denizin sesine tadın var

terleyen avuç içlerimde 

Şimdi

Yalnızca

Büyük puntolarla 

Unuttum yazar.

Desem de yinede inanma

Nasıl ki kanmadıysan boyadığım pembe rüyalarla

Var unuttuğuma da inanma

Nasıl ki hatırlamıyorsan

İşte öyle

Öyle kanma..', 'sen yalnız gecelerimin soluğusun gün ağarırken ellerini bıraktığım çocukluğumsun. Severken düşünemediğim  Unutmak için hatırladığım Yarını o...', ARRAY['Türk Edebiyatı','Şiir','Derya Uysal']::text[], 8.5, '{"poet":"Derya Uysal","poet_slug":"derya-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sayiklamalar-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen benim en büyük cinayetimsin...', 'sen-benim-en-buyuk-cinayetimsin-derya-uysal-b3hfx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Korkuyorum sevgili 

Korkutuyor beni kendimle kendimi yaşama sürgünüm. 

Nice hücreleri parçalayıp çıkmışken, 

gökyüzünüm maviliğine kavuşmuşken, 

kendi içimdeki hücrede prangalara bağlanmış olmak korkutuyor beni...

Bu tutsaklık sana mı, 

kendime mi ayrımını yapamıyor usum. 

Oysa sen çoktan kalbine yeni aşklar yüklemiştin... 

sende bana ait olanı bir göz damlasına sığdırıp atıvermiştin içinden... 

bense eskiyi sende 

yeniyi senle düşleyerek yaşıyorum. 

Sana bize dair kurgular dolaşıyor beynimde, 

oyun oynuyor bana artık usum. 

Seni sana bırakmayı her düşündüğümde, 

gözlerim senlinle ışık hareleri eşliğinde dans ediyor. 

Sen beliriyorsun yanımda, 

sana dokunuyorum, 

sıcak ellerini tutuyor 

ve her zaman yaptığım gibi 

alnının ortasına bir öpücük konduruveriyorum. 

Aklımın aydınlığı diyorum sana... 

oysa aklım aydınlık tarafını çoktan yitirmiş 

karanlıklar içinde oyunlarıyla baş başabaşa kalmış... 

bir gülümsemeyle kayboluyorsun yine. 

Ellerim sıcaklığını kaybetmiyor yine de...

sıcak bir kan beliriyor avuçlarımda... 

sen benim en büyük cinayetimsin...', 'Korkuyorum sevgili  Korkutuyor beni kendimle kendimi yaşama sürgünüm.  Nice hücreleri parçalayıp çıkmışken,  gökyüzünüm maviliğine kavuşmuşk...', ARRAY['Türk Edebiyatı','Şiir','Derya Uysal']::text[], 8.5, '{"poet":"Derya Uysal","poet_slug":"derya-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sen-benim-en-buyuk-cinayetimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eda Bize Gelince', 'eda-bize-gelince-ozkan-gonlum-oks0n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dede! . geldim, diyecek

			Mutluluklar verecek

			Başım göğe erecek

			Eda bize gelince.

			Dertler bizden kaçacak

			Gönlüm zevkten uçacak

			Evde neşe saçacak

			Eda bize gelince.

			Gökten melek inecek

			Ağrılarım dinecek

			Gün bayrama dönecek

			Eda bize gelince.

                                                EDA BİZDEN GİDİNCE

			Her an onu anarız

			Özlemiyle yanarız

			Gözyaşımız dökülür

			Yüreğimiz sökülür

			Eda bizden gidince.

			Ondan ayrı duramam

			İstesem de varamam

			Gönle hasret ekilir

			Sanki kanım çekilir

			Eda bizden gidince.

                                                Evimiz hüzün dolar

			Çiçekler bile solar

			Gönlümüz onu arar 

			Yaşamak neye yarar

			Eda bizden gidince.', 'Dede! . geldim, diyecek 			Mutluluklar verecek 			Başım göğe erecek 			Eda bize gelince. 			Dertler bizden kaçacak 			Gönlüm zevkten uçacak ...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/eda-bize-gelince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Histeri nöbetleri', 'histeri-nobetleri-derya-uysal-0ku2u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Histeri nöbetleriyle başlayan uzun gece... 

ihanetin gölgesinde bir teselli. 

Roller değişmişti sevgili. 

Sen iyi kadını oynuyordun 

bense kötüsünü. 

Hem ihanet etmiştim sana 

hem de tesselii ediyordun beni.

 Karşımdaki iyi kadın ihaneti sorun yapmıyor., 

benim iyi olmam için çırpınıyordu. 

İçimdeki çocuğu komaya sokan iyi kadın.

Diriltebilir misin onu yeniden. 

Bu çırpınışlar neden? 

Neden Bu iyi kadın rolleri. 

Oysa ben silahlarını kuşanmış, 

savaşın en kızgın yerinde 

bana saldıran kadını yeylerdim. 

Geçmişinde takılı kalan 

o kızgın kadını. 

Geçmişinden kaçmasının sorumlusu olarak beni ilan eden 

o hırçın ve yaralı kadını....', 'Histeri nöbetleriyle başlayan uzun gece...  ihanetin gölgesinde bir teselli.  Roller değişmişti sevgili.  Sen iyi kadını oynuyordun  bense k...', ARRAY['Türk Edebiyatı','Şiir','Derya Uysal']::text[], 8.5, '{"poet":"Derya Uysal","poet_slug":"derya-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/histeri-nobetleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittt', 'gittt-derya-uysal-le2nh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kırılan dökülen yanlarını seyrederek yaşamak.... 

sen kendine ben sana yabancıyım artık sevgili. 

üşüyen yanlarımızla yan  yanayız seninle...

alışkanlığa dönüştürdüğümüz duygularımız 

şimdi bize o korkunç oyununu oynamakla meşgul.

 biz mi hazırlamıştık bu sonu? 

sen düşsel bir ormandan gelmiştin bana. 

Yorgun yaralı... 

İstediğin tek şey sıcacık bir dokunuş 

ve güven dolu bir bakıştı benden. 

Bense hayatla oyun oynama alışkanlıklarımın esiriydim...

yorgun bedenine yükler yüklemek miydi niyetim...

ne zaman niyetlerle yaşandı ki sevgili.... 

ne çok yük kondurdum yorgun bedenine...

kırılan dökülen yanlarını seyrederek yaşamak.... 

sen kendine ben sana yabancıyım artık sevgili. 

üşüyen yanlarımızla yanyanayız seninle...

düşlerinle yaşamaktı senin amacın. 

bense düşsel bir yolculağa sürüklercesine ısrarcıydım. 

hayattı bu... oyun oynadığım hayatım. 

serüvenlerdi yaşamımı belirleyen. 

üç kişilik bir yolculuktu bu. 

ben sen ve bu yola en az senin kadar habersiz çıkan bir yürek... 

onu da kattık aramıza futursuzca...

kırılan dökülen yanlarını seyrederek yaşamak.... 

sen kendine ben sana yabancıyım artık sevgili. 

üşüyen yanlarımızla yanyanayız seninle...

ne çok oyun oynamıştık yolculuk boyunca. 

kimi zaman sobeliyorduk birbirimizi masumca, 

kimi zamansa en tehlikeli silahlarımızı kuşanıp 

savaşlar başlatıyorduk birbirimizin hayatlarına... 

Ve o küçük yürekse 

oyunlarımızda kimi zaman birimizin ittifakı, 

kimi zaman barış elçisi oluyordu...

bu hayata karşı oynadığımız oyundu 

ve oyunlar er geç bitecekti.

kırılan dökülen yanlarını seyrederek yaşamak.... 

sen kendine ben sana yabancıyım artık sevgili. 

üşüyen yanlarımızla yan yanayız seninle...

oysa oyunda taraflar da değişebilirdi düşünemedik.... 

hayat da bize karşı en planlı oyununu oynayabilirdi. 

Sohbetlerimizde ''onlar bizi kendilerine hep yabancı gördüler sevgili'' derdim 

ve beraberce gülerdik... 

oysa onlar bizi kendilerine de benzetebilirlerdi düşünemedik....... 

kırılan dökülen yanlarını seyrederek yaşamak.... 

sen kendine ben sana yabancıyım artık sevgili. 

üşüyen yanlarımızla yan yanayız seninle...

ne çok benzedik reddettiklerimize... 

şimdi sen nefessiz hissediyorsun kendini bu oyunda... 

nefesini yitirdin ama dudaklarından aynı sözcükler 

bütün sihrini kaybetseler de 

dökülmeye devam ediyorlar. 

bense senin omuzlarına yüklediğim yükün altında eziliyorum. 

bedenim senin yorgunluklarının sızılarıyla kıvranıyor.

kırılan dökülen yanlarını seyrederek yaşamak....

sen kendine ben sana yabancıyım artık sevgili. 

üşüyen yanlarımızla yan yanayız seninle...

san git desem... 

GİT düşsel yolculuklara çık....... 

bütün yükünü yık omuzlarıma ve GİT desem... 

Bütün kirlenmişliğimi bir an olsun unutup; 

GİT sevgili başka aşklara,

soluk alabileceğin, 

çiçekleri koklayabileceğin yüreklere sığın 

diyebilsemmmmmmmmmmmm

GİTTTTTTTTTTTTTTTTTTTTTTTTT', 'kırılan dökülen yanlarını seyrederek yaşamak....  sen kendine ben sana yabancıyım artık sevgili.  üşüyen yanlarımızla yan  yanayız seninle.....', ARRAY['Türk Edebiyatı','Şiir','Derya Uysal']::text[], 8.5, '{"poet":"Derya Uysal","poet_slug":"derya-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/gittt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kumralım', 'kumralim-emrah-saygin-eph2j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tespihimi sallarım                                                         sevdiğime bakarım                                                                      biraz yüz verirse                                                                     mektubumu yazarım                                                                     dolaşır dolaşır bıkmam                                                                  onunlayken yorulmam                                                                  bir tane sevdiğim var                                                                kumralmı kumral', 'Tespihimi sallarım                                                         sevdiğime bakarım                                                ...', ARRAY['Türk Edebiyatı','Şiir','Emrah Saygın']::text[], 8.5, '{"poet":"Emrah Saygın","poet_slug":"emrah-saygin","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/kumralim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağ Elimi Bağışlıyorum', 'sag-elimi-bagisliyorum-ali-osman-yilmaz-stpui', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ellerime baktıkça,

Parmaklarımı kırasım geliyor,

Seninle sarmaş dolaş,

Olduğumuz zamanlarda,

Sarı saçlarını okşardı ya,

İnce beline sarılıp,

Seni bana yaslardı,

Gördükçe ellerimi,

Seni hatırlatan parmaklarımı,

O yüzden kırasım geliyor.

Sol elime kıyamıyorum,

Onun senden ayrı,

Çok hatırası var bende,

Katıldığım her mitingde,

Her devrimcinin cenazesinde,

Öfkeyle doldurulmuş,

Atom bombası gibi sıkılı,

Gökyüzüne şahlanır gibi kalkan,

Sol elim şimdi bana,

Öyle güzel görünüyor ki,

O yüzden kıyamıyorum ona.

Ama o sağ elim yok mu? 

Seni,sarı saçlarını okşayan,

O parmaklar,hele o dilim,

Çok devrim andı içti amma,

Sonunda ihanet etti oda bana,

Aşk şarkıları söylerdi sana,

İşte o iki haini affedemiyorum.

Sağ elimi ve parmaklarımı,

Birde tutulası dilimi,

Birini kökünden kesmek,

Parmaklarımı,dibinden kırmak,

İstiyorum ama nafile,

Senden hiç iz kalmazsa,

Kimi hayal edecek,

Nasıl kızacağım sana,

O yüzden sağ elimi,

Ve parmaklarımı,

Sana şarkılar söyleyen,

Tutulası dilimi,

Sol elimin hatırına,

Bağışlıyorum.', 'Ellerime baktıkça, Parmaklarımı kırasım geliyor, Seninle sarmaş dolaş, Olduğumuz zamanlarda, Sarı saçlarını okşardı ya, İnce beline sarılıp,...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sag-elimi-bagisliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanmıyorum (II)', 'i-nanmiyorum-ii-atil-kesmen-ik7n6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnanmıyorum				

Bana dalğın bakan				

Beni ben''de yakan, gözlerinden gelen sevgine				

İnanmıyorum				

Yalansın,hislerimle oynayıp				

Sevgiye, beni küstürensin				

Sen''de dem tutmuş gönlümü,kara bulutlar sardı			

Sen''den aldığım nefesimi				

İstesemde				

Sana veremiyorum				

Senin sevgiye, sevdiğine inanmıyorum				

Seni sen''de sevemiyorum				

				

Yorgun düşmüş gönül ışığım				

Damla damla senin sevginde sönüyor				

Gönlüm, sana inanmıyor				

Gözlerim, seni görmek istemiyor				

Duygularımda yıkıldım,çöktüm				

Hislerimde yalnız kaldım				

Sen''den				

Senin sevginden nefes alamıyorum				

				

İnanmıyorum 				

Senin, beni gerçekten sevdiğine				

Oyaladın,oyuncak ettin beni gerçek kimliğinle				

Kahrettin, acı çektirdin ikinci kişiliğinle				

İnanmıyorum senin sevgine				

Seni, sensizliklerime gömüyorum				

Bir daha aldanıp				

Bir daha,bir daha senin acılarına bürünmemek üzere', 'İnanmıyorum				 Bana dalğın bakan				 Beni ben''de yakan, gözlerinden gelen sevgine				 İnanmıyorum				 Yalansın,hislerimle oynayıp				 Sevgi...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/inanmiyorum-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hayalin Var Bende', 'bir-hayalin-var-bende-ali-fikri-karadeniz-jzu95', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir hayalin var bende

Gözlerime yapışmış

Hani anılar toz tutsa da Seni unutabilsem

Olmuyor

Baktığım her yerde canlanıyorsun…! 

Bir hayalin var bende

Gözlerime yapışmış

Gölgeme bakıyorum; Sen

Gündüzümde Ayçiçeğim

Gecemde yıldızım

Rüyalarımda dahi benimlesin…! 

Bir hayalin var bende

Gözlerime yapışmış

Gökkuşağımda Sen varsın

Rengarenk umutlarım

Yağmurumda Sen varsın; mutluluklarım

Ah… Bir de ayrılık olmasaydı

Böylesine acıları

Böylesine kahırları yudumlamasaydım

Böylesine deli divane

Böylesine hasreti yaşamasaydım…! 

Bir hayalin var bende

Gözlerime yapışmış

Korkuyorum şimdi, korkuyorum

Ölümümde Senden olursa eğer

Kefenim gelinliğinden ister

Ve tabutumun son çivisi gibisin

Ben Seni böylesine nasıl sevdim? 

Bunu Sen bilemezsin…! 

                                                           20/11/2004', 'Bir hayalin var bende Gözlerime yapışmış Hani anılar toz tutsa da Seni unutabilsem Olmuyor Baktığım her yerde canlanıyorsun…!  Bir hayalin v...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bir-hayalin-var-bende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ancak', 'ancak-emin-baydil-9ix6p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir bayrak

ve bir de sancak,

yalnız başına sessiz

dalgalanır ancak.

Bir gül

ve bir de bülbül,

şafakla birlikte

uyanır ancak.

Bir can

ve bir de canan,

zora düşünce

dayanır ancak.

Bir er,

olmuş seferber.

Susayınca albayrak,

boyanır ancak.', 'Bir bayrak ve bir de sancak, yalnız başına sessiz dalgalanır ancak. Bir gül ve bir de bülbül, şafakla birlikte uyanır ancak. Bir can ve bir ...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ancak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangınlar Dağladı Tenimi', 'yanginlar-dagladi-tenimi-zeki-ergin-jkio2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yüreğimdeki fırtınalar

sığmaz oldu bir yerlere

ne gökyüzü ne de denizlere

düşlerimi çaldılar bir gece vakti

ocağımı söndürdü haramiler

toprağım çorak 

ruhum sensiz

yangınlar kavurdu her yanımı

öksüz kaldım 

o yangınlarda

dağlandı tenim

_erenköy  21kas04

_dağlara ver sırtını yt:haz09', 'yüreğimdeki fırtınalar sığmaz oldu bir yerlere ne gökyüzü ne de denizlere düşlerimi çaldılar bir gece vakti ocağımı söndürdü haramiler topra...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yanginlar-dagladi-tenimi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen sigara da bir şiir yazar..!', 'bazen-sigara-da-bir-siir-yazar-omer-faruk-girgin-y8ky5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Soğuk bir yel esiyor

hışırtılı yaprakları manolyanın

yosun tutmuş bir duvar

eteğinde bir yığın solgun yaprak çınarın

ve şiir yazıyor bir adam

elleri zor tutuyor kalemini

ama onun adı hep aklında

karşı koymak için yalnızlığına

direnmek için hayata

hep onu düşünüyor

şiir yazıyor bu adam 

donuk bakıyor

baktığı yerde yok bir şey 

olana değil baktığından belli

boş bakıyor

kavruk yüzü gülümsemeyi unutmuş 

belki aklı geçmişine takılı

sıkıntıdan

tenine yapışıyor giysileri

şiir yazıyor bir adam

yazım tarzı kuralsız

avucunda

güdüsel oynatıyor kalemini

kederi yansıyor saçlarına

ışıltısız bakışında isyan

büzüşen kağıdında bir yığın kelimeler

iç çekişinde  yakarı var

şiir yazıyor bir adam

ter süzülüyor şakaklarından

hıncını sallıyor kağıda

her oynatışında kalemini

meydan okuyor geceye ve  yalnızlığa

şiir yazıyor bir adam

kalemini bir an bırakarak

elinle sarıyor

sevgilisini tutar gibi boşluğu

ve bir şarkı koyuveriyor yüreğinden

sigarasının

yükselen dumanlarına bindirip

ona yollar gibi...', 'Soğuk bir yel esiyor hışırtılı yaprakları manolyanın yosun tutmuş bir duvar eteğinde bir yığın solgun yaprak çınarın ve şiir yazıyor bir ada...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Girgin']::text[], 8.5, '{"poet":"Ömer Faruk Girgin","poet_slug":"omer-faruk-girgin","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bazen-sigara-da-bir-siir-yazar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıtsız', 'kayitsiz-gokhan-oflazoglu-3801n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir aldırmazlık çöktü

olan bitenden sonra.

Korkum bile kuytuda,

bir dinginlik boşluklarımda.

Sanki bir kuş gibi süzülmekteyim,

belimdeki ağrı yere bastığımı

hatırlatmasa.

Bundan sonra kapılsam da

günlük uğraşlara, bir başka

bilinç eşlik eder, kalan zamana.

21/11/2004', 'Bir aldırmazlık çöktü olan bitenden sonra. Korkum bile kuytuda, bir dinginlik boşluklarımda. Sanki bir kuş gibi süzülmekteyim, belimdeki ağr...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kayitsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Renksiz Tual(kısa öykü)', 'renksiz-tual-kisa-oyku-mehmet-asim-6hzl6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ufalanırken gökler yürğimde,senli günlerin çoşkusu durgunlaşıyor içimde.yokluğundan olsa gerek bu durgunluk.Gelmeyişinden olsa gerek... 

Griliniğini bıraktın ellerime.sen giderken renklerimi aldın.maviyi,sarıyı,kırmızıyı,yeşili.şehrin gürültüsünü bırakıp sensiz suskunluklara terkettin.gittin işte... 

bu yüzden olsa gerek durgunluklarım,anlamsızlıklarım,renksizliğim... 

   Fotoğraf albümünü açıyorum akşamları.belki eski renklerimden giyinirim diye.belki yaralarımı sararım belki kanayan yanlarımı.... 

Hatıralarımda kalan tek renk giydiğin(giderken) kırmızı palton.anlıyorum kışmış...palto giydiğine göre.Ne güzel yakışıyordu renkler sana...giysiler içinde sen olunca... 

  Akşamları beklerdim seni.Penceremin önünden gecersin diye.Şaşırırdım! insanlar neden siyah ve beyaz giyinmiş diye... 

şimdi anlıyorum... 

anlıyorum ve tüketiyorum bana bıraktığın yanlarımı.... 

  Gittin... 

ne renksizlik yakıştı istanbul''a,ne ben kimsesizliğine... 

  Gittin.. 

salınarak renklerine bir resminde kırmızı paltona mahkum eyleyip beni,gittin sen sevgili... 

Yaşamak için bir sebebim vardı benim.Gitmn için hiç bir neden bulamadım.toplarken siyahları iklimime sen,bir nefes vermedin soluğuma.kronik bir hastalık gibiydin içimde,tedavi edildikçe müzminleşen... 

  Gittin.. 

Elimde renksiz bir gökkuşağı kaldı.nereye asayım? hangi gök kabul eder,rengini yitirmiş gökkuşağını... 

Göğümden bir tabakayı çekip aldın sen.içimde hayatımın en tanışık yanlarının olduğu.yağmurlar teğet geçiyor şimdi üzerimden ıslanamıyorum.Göğü çalınmış bir çocuk gibiyim ve ne zaman başımı kaldırsam yukarı senli bir yoksunluk...önce göğümden,sonra içimden silindi tüm mevsimler ve renkleri.yokluğunun o saydam,o mavisiz denizinde yüzüyorum şimdi.Sabaha ermek istiyor ruhumun karanlığı eremiyorum.biliyorum çünkü varamıyacağımı,beyazın siyahtan ayrıştığı o,ince cizginin farkına... 

  Gittin sevgili... 

Sen masmavi bir gerçekken,bana renksiz bir yalan bırakamazsın.', 'Ufalanırken gökler yürğimde,senli günlerin çoşkusu durgunlaşıyor içimde.yokluğundan olsa gerek bu durgunluk.Gelmeyişinden olsa gerek...  Gri...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Asım']::text[], 8.5, '{"poet":"Mehmet Asım","poet_slug":"mehmet-asim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/renksiz-tual-kisa-oyku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Havamız batsın', 'havamiz-batsin-i-lhami-arslantas-ltuom', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İhtiyar bir eskicinin sattığı,

ambar göbekli efendilerin, 

modası geçmiş eskileriydi,

daraltıp, 

üstümüze uyduruğumuz.

Bir vebal gibi,

sırtımızda taşıdığımız,

kimbilir kimin paltosuydu? 

omuzlarımızdaki,

ve kim bilir,

yeni niyetine giydiğimiz,

kimin gömleğiydi? 

Sırtımıza giydiğimiz,

güveden artakalan,

nostalji kokulu,

lacivert, 

haki, 

beyaz.

ve hangi hovardanındı,

yumurta topuk,

nal mıhlı kunduralar.

kim bilir, 

nice yosmanın,

ardında gezdi, 

hangi kaldırımların, 

parke taşlarını yaladı,

basık ökçeleriyle.

Biz de giydiğimizde,

havaya girmiştik,

Bu eskilerle.

Şiirlerimle ben bu eskilerin,

Büyüttüğü çocuğuz,

Havamız batsın.', 'İhtiyar bir eskicinin sattığı, ambar göbekli efendilerin,  modası geçmiş eskileriydi, daraltıp,  üstümüze uyduruğumuz. Bir vebal gibi, sırtı...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/havamiz-batsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakit Çok Geç - Nostalji', 'vakit-cok-gec-nostalji-aydan-yalcin-trf3l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gözlerinizin loş odalarını gezdim de

uzadı gölgem tünelinde hayatın

siz! 

takvim geçişlerinde rastladığım kadın

ben sizi şahane elbiselerinizden değil

yağmura gebe / bulutlu bakışlarınızdan tanıdım...

biliyor musunuz! 

yüzümü kesen güz''dü pusulasız gidişiniz...

yıkılmaya yüz tutmuş bir örene gibi

yıllarca nöbetini tuttum sessizliğin

ki bu yüzden hiç bir mevsime uyanmadı iklimim

dağ kapladı gölgemi zaman zaman

tipilerle savruldum

bir resim oldum / yırttım kendimi

geceden sabaha

ve

şimdi siz! 

bunca yıldan sonra

üstelikte bakır renkli bir günbatımında

aniden çıkıp geliverdiniz...

olsanız da biraz ürkek / biraz tedirgin

bakın! 

gözlerimdeki taş plaktan seslenmekte size

Munir Nurettin

''Dönülmez akşamın ufkundayım vakit çok geç''', 'gözlerinizin loş odalarını gezdim de uzadı gölgem tünelinde hayatın siz!  takvim geçişlerinde rastladığım kadın ben sizi şahane elbiselerini...', ARRAY['Türk Edebiyatı','Şiir','Aydan Yalçın']::text[], 8.5, '{"poet":"Aydan Yalçın","poet_slug":"aydan-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/vakit-cok-gec-nostalji-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili seyirci...', 'sevgili-seyirci-omer-bulut-ds8c6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tüm kapılarım ve pencerelerim

Kapalıyken

odama giriyor bir yığın insan

bana sevgili diyor

seyirci diyor

sandalyeye oturmuş

kahvaltı ederken ben

dün ne yaptığımı unutmuşken

geçen hafta

ne olmuştu

hatırladın mı diye soruyor

pembe dizideki

aptal karakter

ne kadar çok düşünüp

kolluyor beni

reklamlardaki doktorum

ey doktor söyler misin bana

günde kaç kez

fırçalamalıyım kalbimi

ve ey sevgili sunucum

nasıl silerim

gönlümdeki kapitalist

tankların izlerini

rüyalara bile

uğramıyor melekler

coca kola içip

birşeyler yaptığımızdan beri...', 'Tüm kapılarım ve pencerelerim Kapalıyken odama giriyor bir yığın insan bana sevgili diyor seyirci diyor sandalyeye oturmuş kahvaltı ederken ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bulut']::text[], 8.5, '{"poet":"Ömer Bulut","poet_slug":"omer-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sevgili-seyirci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katil', 'katil-erkan-kaner-5v6pe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tırnaklarımla kazıdım, sildim

soğuk bir duvarda bile yok artık ismin

öldürdüm seni kalbimde, yok bildim

meçhul bir cesetten öte kalmadı cismin

kimse şahit olmadı ölümüne

cinayetinden miras bir tek ben kaldım

ben bile fazlayım katil yüreğime

satırlar tükenecek kendimi kusacağım

                               (25 eylül 2004)', 'tırnaklarımla kazıdım, sildim soğuk bir duvarda bile yok artık ismin öldürdüm seni kalbimde, yok bildim meçhul bir cesetten öte kalmadı cism...', ARRAY['Türk Edebiyatı','Şiir','Erkan Kaner']::text[], 8.5, '{"poet":"Erkan Kaner","poet_slug":"erkan-kaner","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/katil-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Yaban İlleri *', 'yaban-i-lleri-gulsen-senderin-a7miy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yurdumun kokusu sinmiş üstüme

Toprağı, havasi bir başka kokar

Bilmem ki feleğin bana kastı ne

Yaban İllerinde, elim iş tutar! 

İşini bilsen de, doyduğun yerde

Kılıç kuşansan da, dört yanın perde

Güdümlü bireysin; payı kaderde

Yaban İllerinde, terin aş tutar! 

Halinden anlamaz, dilini bilmez

Bayrama katılmaz, sevinci bölmez

Ekmek kavgasının dönüşü olmaz

Yaban İllerinde, kimi eş tutar! 

Umutlar devşirir, neler uğruna

Yeniliğe şaşar, sarar bağrına

Bir an kulak verse, gönül çağrına

Yaban İllerinde, gözler yaş tutar! 

Bir hayal cenneti döşer can evi

Çıkmaz sokaklarda, tadar alevi

Kalbinde yatılı; en güzel sevi

Yaban İllerinde, aşk yokuş tutar! 

Elde edilenler, değer mi bilmem

Özgürlük adına özümden olmam

Aldanıp Yurdumdan; ayrı hiç kalmam

Yaban İllerinde, para hoş tutar! 

Gülşen''in gönlünde dağları, köyü

Burnunda tütüyor, damı hanayı

Yeniden ekilsin; arpa buğdayı

Yaban İlleirnde, yürek taş tutar!', 'Yurdumun kokusu sinmiş üstüme Toprağı, havasi bir başka kokar Bilmem ki feleğin bana kastı ne Yaban İllerinde, elim iş tutar!  İşini bilsen ...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yaban-illeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zor Şey,Seni Anlatmak.', 'ne-zor-sey-seni-anlatmak-ali-osman-yilmaz-ahrat', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zor şey,

Yazarak anlatmak seni,

Sana olan aşkımı.

Satırlarda her şeyi,

Yazarak anlatabiliyorum da,

Seni bir türlü,anlatamıyorum.

Ciğerlerimi dolduruncaya,

Seni içime sığdırıncaya,

Çektiğim kokunu mesela,

Okşadığım sarı saçlarını,

Gözlerinin maviliklerinde,

Kaybolduğum anları,

Dudaklarımız kilitlendiğinde,

Bulamadığımız anahtarı,

Sıcak yatağımızda,

Kördüğüm olup yattığımız,

Ben sen,sen ben olduğun,

Bir beden,bir ruh gibi,

Birlikte yıldızlara yükseldiğimizi,

Sabaha karşı göklere bakıp,

Ay’ın tanık olmasını istemeni.

Velhasıl güzelim,

Yalnızlığımı ve sensizliğimi,

Kelimelerle anlatıyorum da,

Seni bir türlü anlatamıyorum.

Denizler dolusu mürekkep,

Bende kalem olsam,

Anlıyorumki sevgilim,

Seni kelimelerle yazarak,

Anlatamayacağım.', 'Ne zor şey, Yazarak anlatmak seni, Sana olan aşkımı. Satırlarda her şeyi, Yazarak anlatabiliyorum da, Seni bir türlü,anlatamıyorum. Ciğerler...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ne-zor-sey-seni-anlatmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sude', 'sude-hifzi-altumsek-ckx54', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benden sana hayır yok

Gel beni unut Sude

Seni en çok sevenin

Ellerinden tut Sude

Gitmese de hoşuna 

Hükmet gönül kuşuna

Umma boşu boşuna

Benden bir umut Sude

İsterim ki küstüm de

Muhabbeti kestim de

Yıllar var ki üstümde

Aşk Karabulut Sude

Kapanır yara mı bu

Bir ömrün dramı bu

Her aşkın kuralı bu

Kim olmuş mesut Sude

Var ise bir haber ver

Benden alâ derbeder

Sabrımı ölç,karar ver

Dağ mı ki ''''Nemrut'''' Sude

Hisse çıkar kıssadan

Çok çektim o yosmadan.

Ben gibi bir asmadan,

Üzümü unut Sude

Fikrinde kalma sabit

Kalbini sına,eğit

Gönlünden bana ait

Ne varsa arıt Sude

Duyulmaz bin ah çeksem

Terketti kimi sevsem

Galiba gönül lehçem

Hem bozuk hem kıt Sude

Ben ki sevdam uğruna

Taşlar bastım bağrıma

Canevimdir ağrıma

En güzel kanıt Sude

Halim de yok ferim de

Aşk için özverim de

Ne olur sözlerimde

Arama kasıt Sude

Ne beni üz,ne seni

Eksik etme neşeni

Muhitine kendini

Bahtiyar tanıt Sude

Benden sana hayır yok

Dedim ya, unut Sude

Kalbinden gözlerine

Mutluluk damıt Sude

Mutluluk damıt Sude...', 'Benden sana hayır yok Gel beni unut Sude Seni en çok sevenin Ellerinden tut Sude Gitmese de hoşuna  Hükmet gönül kuşuna Umma boşu boşuna Ben...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Altümsek']::text[], 8.5, '{"poet":"Hıfzı Altümsek","poet_slug":"hifzi-altumsek","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/sude-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Olalım', 'bir-olalim-kadir-soyturk-4g736', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir olalım; bu bayrak-sancak yere düşmesin

Sakın,  bala- pekmeze  sinekler  üşüşmesin!', 'Bir olalım; bu bayrak-sancak yere düşmesin Sakın,  bala- pekmeze  sinekler  üşüşmesin!...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bir-olalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baş Olmak', 'bas-olmak-kadir-soyturk-zwqb5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Demişler ki: ''Baş ol da, ne başı olursan ol''

Bu fikir köhne fikir; bu yol çok yanlış bir yol! 

Baş var ki zehir eder,  kula tatlı aşını

Hem kendisini yakar; hem de arkadaşını! 

Sen insan olmağa bak, layıksan ''baş'' olursun

Hile ile, kumarla gelirsen taş olursun! 

Liyakatsiz başlardan bu millet neler çekti...

Ah! Başı  baş olsaydı; göğe yükselecekti!', 'Demişler ki: ''Baş ol da, ne başı olursan ol'' Bu fikir köhne fikir; bu yol çok yanlış bir yol!  Baş var ki zehir eder,  kula tatlı aşını Hem ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bas-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Yüzlü Batı', 'i-ki-yuzlu-bati-kadir-soyturk-8lff9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kez ayağım kaysa, bin kez yakarsın kına

Seni dost sananların  şaşıyorum aklına...

Tuzak kurarken bile, yüzüme gülmektesin

Sen ziyarete değil, yağmaya gemektesin! 

Abdalları kandıran, uyduruk bir fenersin

Yakıtın yalan senin; bir yanar bir sönersin! 

Ne desem şimdi bilmem; kapında ağlayana

Acıyorum acıyor, sana bel bağlayana!', 'Bir kez ayağım kaysa, bin kez yakarsın kına Seni dost sananların  şaşıyorum aklına... Tuzak kurarken bile, yüzüme gülmektesin Sen ziyarete d...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/iki-yuzlu-bati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asla Vazgeçmeyeceğim Senden        ss  26', 'asla-vazgecmeyecegim-senden-ss-26-nesrin-gocmen-u7wiu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söz bir kez çıktı mı ağzımdan benim, 

bir kez evet dediysem ben; 

ne yaparsan yap, ne dersen de şimdi; 

bil ki yılmayacağım, 

peşini bırakmayacağım senin..

Sen beni zorladıkça, ben daha güçleneceğim. 

Hatta fakındasızca beni acıtsan da, 

ben seni daha da seveceğim. 

Pes etmeyeceğim, uğraşacağım seninle bilesin..

Olmaz ya; hani diyorum, mesela diyorum; 

beni birgün bırakıp gitmek istersen, 

gitmek zorunda bırakılırsan, 

inatla ben de senin ardından geleceğim. 

Bir zamanlar gidenlerin ardından, 

saklı yaşlarımla sessizce ağlayan, 

hatta kahkahalarla gülüyor görünen ben, 

bu kez öyle tek başıma kalmayacağım...

Arsızca, inatla  koşacağım yanında senin.

Çünkü, benim en değerli varlığım sensin..

Ne varsa zor olan seninle, 

hepsini aşacağım tek başıma olsam da...

Zaman zaman direneceğim sana, 

kızdıracağım seni..

Sonrası susup, bana yazdıklarınla avunacağım...

Ancak senin; 

ne senden, ne de yaşamdan 

vazgeçmene asla izin vermeyeceğim...

Çünkü benim yaşamımın tek anlamı sensin.

Zaman gelecek imkansızlar çıkacak karşıma,

zaman gelecek ulaşılmazlıkları isteyeceğim seninle.

Zaman gelecek içim ağlayacak, 

zaman gelecek konuşamayacağım.

Sesini bile duyamayacağım hatta.

Ancak vazgeçmeyeceğim....Yılmayacağım..

Sen benimle uğraştıkça, sen benden uzaklaştıkça, 

ben sana daha da bağlanacağım. 

Son nefesimi verene dek benden kurtulamayacaksın bilesin.

Sen durmazsın bilirim olduğun yerde. 

Mutluluğun en güzeli verirken ben sana, 

bir yandan da acıtacaksın kendini hüzünlerinle. 

Hüzün ve sen öyle içiçe girmişsiniz ki; 

sen onsuz, o sensiz olamaz.

Sevdanın en güzelini yaşarken bu yüzden üzüleceğim, 

sevilirken, severken bu yüzden boynum bükülecek.

Fakat ne olursa olsun,

utanmadan, bıkmadan, usanmadan haykıracağım 

sevgiyi unutanlara, sevdayı anlamayanlara:

Sevdim, seviyorum, seveceğim...

Sen yine sus olur mu? Yine birşey söyleme..

Sadece sus ve dinle....

sen söyleme....

(sen söyleme-26)  

22/11/2004', 'Söz bir kez çıktı mı ağzımdan benim,  bir kez evet dediysem ben;  ne yaparsan yap, ne dersen de şimdi;  bil ki yılmayacağım,  peşini bırakma...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/asla-vazgecmeyecegim-senden-ss-26-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntihar', 'i-ntihar-orhan-tuncay-ub4n6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uykusuz gecenin sesleri sararken beni

Dalgaların fısıltısıydı ıslatan kulağımı

Uzaklardan esti sevişmelerin inlemeleri

Parlak çiğ taneleri okşadı çıplak yanağımı

Kaygan sahil koşup uzaklaştı ayaklarımdan

Mazide kalırdı benim için hep sevişmeler

Martılar çığlıksızdılar artık benim için

Sıkıca tutunabildiğim, gel diyen saran geceler

Yakamozlar mıydı, ay ışığı mı parıldayan? 

İçime yansıyıp derindeki ateşi tutuşturan? 

İnsanlar artık neden böylesine ıssızlar? 

Boşlukla kucaklaştım, denizdi beni çoktan yutan.', 'Uykusuz gecenin sesleri sararken beni Dalgaların fısıltısıydı ıslatan kulağımı Uzaklardan esti sevişmelerin inlemeleri Parlak çiğ taneleri o...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/intihar-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eda'' nın Halleri', 'eda-nin-halleri-ozkan-gonlum-hrbsf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eda benim torunum 

			Gelip giderler bize

			Konya'' dadır evleri

			Çıkmaz hiç aklımızdan

			Eda'' mızın halleri.

			Bayram seyran olunca

			Ankara'' ya gelince

			Hele bizi görünce

			Nasıl sevinir bilseniz.

			Hoş geldin bebek, deriz

			Kucaklayıp öperiz

			Sarılır boynumuza

			Kendimizden geçeriz.

			Dolaşır odaları

			Oyuncaklarını bulur

			Hiç yaramazlık etmez

			Onlarla mutlu olur.

			Kağıt kalem ister sonra

			Resimler yapar kendince

			Bize de anlatır çizdiklerini

			Resimleri bitince.

			Dergileri, kitapları getirir

			Oturur kucağıma 

			''''Oku dede, anlat'''' der.

			Can kulağı ile dinler beni

			Resimlerden takip eder.

			Eğlenceye sıra gelince bir ara

			Müzikle başlar oyunlara

			''''Dansöz Asena'' yım'''' der

			Oynamaya devam eder.

			Öyle bir döktürür ki 

			Değme dansözlere taş çıkarır

			Aman oğlum derim babasına

			Bu kız başımıza iş çıkarır.

			Arada bir Hülya gibi

			Sallar poposunu

			Öpücükle biter 

			Bu oyunun sonu.

			Kız çocuğu olur da

			Makyaj yapmaz mı

			Alır annesinin rujunu, rimelini

			Boyar yüzünü, gözünü, elini.

			Tamam olsun diye süsü

			İstenir tırnak törpüsü

			Oje sürer parmaklarına

			Manikür ister tırnaklarına.

			Uyumaz geceleri geç vakte kadar

			Seyrederken televizyon sinemasını

			Bazı geceler uyutur bile 

			Anasını, babasını.

                                                İşte böyle dostlar

			Bir alemdir bizim Eda

			Daha yazsam neler var

			Çok uzadı bu şiir 

			Yetiversin bu kadar.', 'Eda benim torunum  			Gelip giderler bize 			Konya'' dadır evleri 			Çıkmaz hiç aklımızdan 			Eda'' mızın halleri. 			Bayram seyran olunca 			...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/eda-nin-halleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eda Sevgisi', 'eda-sevgisi-ozkan-gonlum-jdkjh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Baldan tatlı yanakla

Gelecek gülüm bana

Biliyorum ben dostlar 

Yok bugün ölüm bana,

Allah herkese versin

Eda bebek gibisini

Dünyayı verseler değişmem 

Onun gözünün birisini', 'Baldan tatlı yanakla Gelecek gülüm bana Biliyorum ben dostlar  Yok bugün ölüm bana, Allah herkese versin Eda bebek gibisini Dünyayı verseler...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/eda-sevgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eda Telefonda', 'eda-telefonda-ozkan-gonlum-15mun', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Konuşur çatır - çatır

			Olayı satır - satır

			Abartarak anlatır

			Telefonu alınca.

			Her şeye aklı erer

			Her konuya girer

			Anlatır birer - birer

			Telefonu alınca.

			Anasını anlatır

			Babasını anlatır

			Ev halini anlatır

			Ne sır kalır, ne hatır

			Telefonu alınca.', 'Konuşur çatır - çatır 			Olayı satır - satır 			Abartarak anlatır 			Telefonu alınca. 			Her şeye aklı erer 			Her konuya girer 			Anlatır b...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/eda-telefonda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eda İçin Yazdıklarım', 'eda-i-cin-yazdiklarim-ozkan-gonlum-w5ie8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaza - yaza yüzü aştı

			Kalem kağıt buna şaştı

			Şiir dedim, destanlaştı

			Eda için yazdıklarım.

			Ne söylesem ona azdır

			Şiirimde mavi gözdür

			Gönülden süzülen sözdür

			Eda için yazdıklarım.

			Şiirimin fabrikası

			Torunların harikası

			Alameti farikası

			Eda için yazdıklarım.

.			İlham ile doldu taştı

			Yüreğimde kutsallaştı

			Şiirlerde dualaştı

			Eda için yazdıklarım.

			Duygulandırır herkesi

			Yazdığımın her hecesi

			Özkan dedenin nefesi

			Eda için yazdıklarım.

			Şiirim en uygun yerdi

			Mısra - mısra sona erdi

			Dedesine onur verdi

			Eda için yazdıklarım.

			EDA''NIN GÖZLERİNDE

			Gülümser hep insana

			Hayat verir bin cana

			Her şey sevgiden yana

			Eda'' nın gözlerinde.

			Güzel gözü seversen

			Sen de gel gör istersen

			Maviler desen - desen 

			Eda''nın gözlerinde.

			Dünya''yla barışıktır

			Gönle dolan ışıktır

			Maviler sarmaşıktır

			Eda'' nın gözlerinde.

			Güzellikleri taşır

			Sevenlere ulaşır

			Mavi nehir dolaşır

			Eda'' nın gözlerinde.

			Bir sihiri sezersin

			Hayalleri dizersin

			Yeri göğü gezersin

			Eda'' nın gözlerinde.

			Mavileri derersin

			Muradına erersin

			Bir Cennete girersin

                                                Eda'' nın gözlerinde.', 'Yaza - yaza yüzü aştı 			Kalem kağıt buna şaştı 			Şiir dedim, destanlaştı 			Eda için yazdıklarım. 			Ne söylesem ona azdır 			Şiirimde mav...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/eda-icin-yazdiklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüme Sesleniş..!', 'olume-seslenis-hulya-topcuoglu-ym8vh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyorum bir gün bana da uğrayacaksın 

Kim bilir hangi planlarımın ortasına düşeceksin apansız

Seni çok düşündüğüm zamanlarda değil de 

Hiç aklımda olmadığın anlarımdan birinde beni yakalayacaksın 

Vaktim var sanıp da ertelediğim

Hep gerçekleştirmek için ümitle beklediğim 

Olmasına ramak kalan güzel şeylerin 

Olmasına izin vermeyeceksin belki de 

Aşık olmayı çok istediğim halde 

Bu ani gelişinle yine aşık olamayacağım kim bilir

Mevsim kışken değil de yaz da gelecek, 

Ölümün yakışmadığı aylardan birini seçeceksin 

Sonbaharda ölmek isterim ya hep ben 

Komiklik olsun diye belki de,

Sen inadına İlkbaharı seçeceksin...', 'Biliyorum bir gün bana da uğrayacaksın  Kim bilir hangi planlarımın ortasına düşeceksin apansız Seni çok düşündüğüm zamanlarda değil de  Hiç...', ARRAY['Türk Edebiyatı','Şiir','Hülya Topçuoğlu']::text[], 8.5, '{"poet":"Hülya Topçuoğlu","poet_slug":"hulya-topcuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olume-seslenis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eda Çıkmaz Aklımdan', 'eda-cikmaz-aklimdan-ozkan-gonlum-abqz2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beklerim döner diye

			Oysa gelmez geriye

			Nerdesin diye - diye

			Eda çıkmaz aklımdan.

			Ona kurdum ayarım

			Her an onu duyarım

			Günlerimi sayarım

			Eda çıkmaz aklımdan.

			Bir müddet dayanırım

			Düş görür inanırım

			Onu geldi sanırım

			Eda çıkmaz aklımdan.

			Nasıl gözümde tüter

			Bu ayrılık bin beter

			Yeter derim ah yeter

			Eda çıkmaz aklımdan.

			Gözlerim yolda kalır

			Beni bir hüzün alır

			Gözyaşım akıtırım

			Ben nasıl unuturum

			Eda çıkmaz aklımdan.', 'Beklerim döner diye 			Oysa gelmez geriye 			Nerdesin diye - diye 			Eda çıkmaz aklımdan. 			Ona kurdum ayarım 			Her an onu duyarım 			Günl...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/eda-cikmaz-aklimdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıpırdasa içim', 'kipirdasa-icim-burhan-kucuk-hjf3i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kıpırdasa içim

Ne zaman içim kıpırdasa

Kalbime bir korku salar

Savur atar beni okyanusa

Korkarım biri kalbimi çalar

İnsan hep bu yüzden yorulur

Beynimizdedir aslında korkular

Çoğu zamanda aşk korkutur

Aşk girdabına düşen çok yoğrulur

Burhan KÜÇÜK

Kdz.Ereğli-23.10.2004', 'Kıpırdasa içim Ne zaman içim kıpırdasa Kalbime bir korku salar Savur atar beni okyanusa Korkarım biri kalbimi çalar İnsan hep bu yüzden yoru...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kipirdasa-icim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayaklarımdaki Kan', 'ayaklarimdaki-kan-murat-demir-daqjo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayaklarımı kana batmış görüyorum

Ayaklarımı

Ne zaman ayaklarıma baksam,

Kan deryasında boğuluyorum

Ne zaman gözlerimi kapatsam,

Uykularım kurşun olmuş gecelerime

Hakkım yokmuş gibi uyumaya,

Ayaklarımı kana batmış görüyorum

Ayaklarımı,

Uyumadan,uykularımda,

Garip bir Dünya nın bu kanlı çağında

Utanarak insanlığımdan,

Yaşıyorum sözde

Haramilerin katlettiği canların

Arkalarından ağıtlar yakarak,

Kimsenin dinine,ırkına,rengine bakmadan

Ayaklarıma bakıyorum 

Ayaklarıma,

Ayaklarımdaki kana

Lanetler okuyarak.', 'Ayaklarımı kana batmış görüyorum Ayaklarımı Ne zaman ayaklarıma baksam, Kan deryasında boğuluyorum Ne zaman gözlerimi kapatsam, Uykularım ku...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayaklarimdaki-kan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eda Bebek', 'eda-bebek-ozkan-gonlum-hoqy1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'EDA bebek torunum

		Henüz iki yaşında

		Ama beni biliyor.

		Alınca telefonu 

		''''Dede..'' deyip duruyor. 

		Duyunca sesini

		Dünyalar benim oluyor.

		By-pas'' lı gönlüm

		Huzur buluyor.

		Ey büyük Allahım

		Bir dileğim var senden

		EDA ‘ yı gelin görmeden

		Alma canımı benden.

		EDA bebek her şeyim

		Hayatım benim.

		Alınca resmini elime

		Dualar doluyor dilime

		Gözyaşı oluyor özlemim.

		Mümkün olsa o anda 

		Gözyaşımı yel ederim

		Eser ona giderim.

Sarı saçlar

		Nokta dudak

		Gül pembe yanak

		Bu kadar olur ancak.

		Allah''ın gücüne gitmesin

		Bütün çocuklar güzeldir ama

		Bir başkadır bizim EDA.

		

 Allah öyle yaratmış ki 

		Gözlerinin  rengini.

		Bulmak mümkün değil

		Tabiatta bir dengini.

		O ne gözler öyle

		Hem gökyüzüne

		Hem denize denk

		Gözlerine işlenmiş

		Bin-bir mavi renk.

		Mavilerin cümbüşü

		İnanın sözlerime

		Gelmiş oturmuş sanki

		Eda'' nın gözlerine.

		Gözlerin en güzeliyle

		Maviş - maviş bakar bana

		Koşar atılır kollarıma

		Severim, öperim onu

		Şükür ederim Yaradana.

Binlerce şükür Rabbim

		Dünya güzelini verdin bana

		EDA'' yı yaratan ALLAH'' ım

		Ömür boyu duam bile az gelir sana.

		ALLAH olmayanlara da versin

		Dedeler bir başka sever torunu

		Elinden gelirse bir de 

		Böyle şiirle över torunu.

		Ben bu şiiri yazdım ama 

		O şimdi bilmeyecek

		Teşekkür edip öpücük vermeyecek

		Yıllar gelip geçecek

		EDA bebek büyüyecek

		Okuyunca bu şiiri

		Gösterip öğretmenine, övünerek

		''''Dedem bana yazmış'''' diyecek.

		Bilmem ki...

		O zaman ben olur muyum

		Şimdi yaşım altmış beş

		Yetmiş beşi bulur muyum

		ALLAH ömür verirse eğer

		Yaşamaya değer

		O günleri de görürüm.

		Bir de  '''' Dede Şiiri ‘’ yazarsa Eda

		Mutluluktan coşarım

		Geri kalan ömrümü

		Eda için yaşarım.

			.', 'EDA bebek torunum 		Henüz iki yaşında 		Ama beni biliyor. 		Alınca telefonu  		''''Dede..'' deyip duruyor.  		Duyunca sesini 		Dünyalar benim o...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/eda-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Çerçeve', 'bos-cerceve-sevim-atan-132hq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BOŞ ÇERÇEVE 

Gördüğüm boş bir çerçeve idi

Kenarları küflenmiş

Bir köşesi kırılmış

Anlaşılan sahibi

Çıkarmak için resmi

Uğraşmış bir hayli

Yatıyordu içinde

Kimbilir kimin resmi

Hangi mazinin eserleri

Eskimişti bayağı

Çerçevenin bana anımsattığı

Bir aşık ki çok bedbaht

Terkedilmiş, yaralanmış

Kanadı kırılmış,

Uçamayan bir kuş gibi

Üzgün, Mecnun gibi deli

Bir kendime bakıyorum 

Bir çerçeveye

Ne kadar da benzeşiyoruz diye

Onun da içi boş, benim de

O da güzel günler görmüş, ben de

Onun içini resimler doldurmuş,

Benimse içimi aşk....

Şimdi ise ikimiz de

Sevgi ve ilgiye

Tamir edilmeye

Ve yeniden 

Eski biz olmaya

Muhtaç hasretle

Bekliyoruz ya yaşama 

Ya ölüme 

Merhaba demeye! ! ! 

Sevim Atan

Ocak 1999', 'BOŞ ÇERÇEVE  Gördüğüm boş bir çerçeve idi Kenarları küflenmiş Bir köşesi kırılmış Anlaşılan sahibi Çıkarmak için resmi Uğraşmış bir hayli Ya...', ARRAY['Türk Edebiyatı','Şiir','Sevim Atan']::text[], 8.5, '{"poet":"Sevim Atan","poet_slug":"sevim-atan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bos-cerceve-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DoKuNMaKTıR.', 'dokunmaktir-neser-selman-p5s5k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dokunmaktı sevmek..

Değişkenlikler esti

Tehditlerde aşk değişti 

Keşfi yakın molekül ile

Uzaktan modası müjdelendi 

Bilindi ki değişse de teknoloji 

Özün şekle yengisi baki

Daire kendini çizerek dedi ki 

Sevmek bütüne dokunmaktır..', 'Dokunmaktı sevmek.. Değişkenlikler esti Tehditlerde aşk değişti  Keşfi yakın molekül ile Uzaktan modası müjdelendi  Bilindi ki değişse de te...', ARRAY['Türk Edebiyatı','Şiir','Neşer Selman']::text[], 8.5, '{"poet":"Neşer Selman","poet_slug":"neser-selman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dokunmaktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklarım', 'cocuklarim-i-rfan-simsek-9rx3z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ÇOCUKLARIM

Sevgi denince aklıma

Çocuklarım gelir benim.

Cıvıl cıvıl kuş sesleri

Tek tesellim olur benim.

   --     --    --

Kimisi var minik elli.      

Kimisi var tatlı dilli.

Ali, Ahmet, Elif, Güllü,

Çocuklarım gelir benim.

   --    --    --

Kimi bülbül gibi şakır. 

Kimi okur tıkır tıkır.

Mehmet,Ayşe,Fatma,Bekir.

Çocuklarım gelir benim.

    --    --    --

Kimi mahzun mahzun bakar. 

Her taşın altından çıkar.

Osman,Dursun,Sultan,Nigar,

Çocuklarım gelir benim.

   --    --   --

Kimi burnunu silemez.

Çağır,yanına gelemez.

Zeynep,Öznur,Bahri,Enes,

Çocuklarım gelir benim.

   --    --   --

Silgi alır tahta siler.

Gözlerinin içi güler.

Cemler,Kerimler,Döndüler,

Çocuklarım gelir benim.

   --   --   --

Kiminin parmak havada.

Kiminin aklı sahada.

Nejla,Selma,Hale,Eda,

Çocuklarım gelir benim.

--    --   --

Kiminin gözleri ela,

Kimisi var tatlı bela.

Murat,Yaşar,Semra,Selma,

Çocuklarım gelir benim.

   --    --   --

Kimi ağlar,kimi güler,

Kimi dersi ortadan böler.

Tahsin,Hakkı,Ayhan,Ömer,

Çocuklarım gelir benim.

   --    --   --

Siz yoksanız  ben olamam. 

Gülmezseniz hiç gülemem.

İrfan,İlhan,Ali,Ekrem,

Çocuklarım gelir benim.

   --    --   --

Hepsini  severim candan.

Ayrılır mı can canandan? 

Hülya,Derya,Betül,Handan,

Çocuklarım gelir benim.

   --    --    --

Ben öğretmen İRFAN’ım.

O minikler canım,kanım

Sardılar yine her yanım.

Çocuklarım gelir benim.

              İrfan ŞİMŞEK

      Mart 1996-GEREDE', 'ÇOCUKLARIM Sevgi denince aklıma Çocuklarım gelir benim. Cıvıl cıvıl kuş sesleri Tek tesellim olur benim.    --     --    -- Kimisi var minik...', ARRAY['Türk Edebiyatı','Şiir','İrfan Şimşek']::text[], 8.5, '{"poet":"İrfan Şimşek","poet_slug":"i-rfan-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/cocuklarim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Son', 'mutlu-son-mahmut-dogan-mnp4s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senden geriye kalan

Bir sen varsınki

Seni bana unutturmayan

Ve gün geçtikçe 

Acı, ızdırap çektiren

Varlığından arınmak isteyen

Ama bir türlü peşimi bırakmayan

Gölegem misali hayalin 

Gün geçtikçi özlemimi artıttıran

Sana bakmaya doyamayan

Gözlerimi her an yaşlı tutan

Sana dokunmaya korkan ellerimi

Tir tir titreten...

Ve senin aşkına susamış kalbimi 

Delice Çarptıran

Unutulmayan sevdanı azdıran.

Bu yokluğunla perişan bedenimi

Taş duvarlara ve soğuk kaldırımlara

Terk eden 

Vicdansız, nankör, gamsız

Ve bana karşı taş kesilmiş 

Ama halen beni sevdiğine inandığım

O yarısı bende olan kalbin 

Sahibi sevgilim

Ya gel bu senden kalanlarıda 

Al ve git.

Yada gel senden kalan

Bendeki yarımları tamamla.

Tamamlaki efsaneleşmiş aşkımızın 

Son sayfasına ''''MUTLU SON'''' diye 

Alev alev yanan kalplerimiz cizilsini.

Çizilsinki aşkımız ebedi olsun sevgilim.

Yüreğimiz aşka doysun

Bu şiiri okuyanların gözleri dolsun

Bitmeyen aşkımızın simgesi ve 

Son ifadesi olsun....', 'Senden geriye kalan Bir sen varsınki Seni bana unutturmayan Ve gün geçtikçe  Acı, ızdırap çektiren Varlığından arınmak isteyen Ama bir türlü...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Doğan']::text[], 8.5, '{"poet":"Mahmut Doğan","poet_slug":"mahmut-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/mutlu-son-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İblisi Olmayan Bir İstanbul Düşünülemez', 'i-blisi-olmayan-bir-i-stanbul-dusunulemez-didem-esen-97yb5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecenin ilk ışıkları  yalnızlığımı kucakladı 

Oysa tam silmiş söndürmüştüm gözlerimi

İçimdeki bütün ışıkları yakmamı söyleyen

İblisin sesi dolaştı.

Ay tırmandı  gecikmiş yalanların  üstüne

Parıltılı ışıklarını gelin telleri gibi döktü

Rüzgar, ruhumla bedenimi silkeledi

Hoyrat bir el gibi,bütün  telleri süpürdü.

Kepenkler indirilmiş gece sessizleşmişti

Siyah gece solgun ve gür dallara asılıverdi

Boşaldı bulutlar  İstanbul’un üstüne

Yaşananlar artık son nefesini verecekti

Islak bir koyuluk içinde deniz bile yalnızdı

Kayıklar, gemiler halatlarla bağlanmış

Çiçekler, kuşlar ve herkes bu saatte mahzun

İstanbul  sırları ile  sessizliğe gömüldü.

Yıldızlar kayıp gidiyor,son ışıklar da öldü

İçimde çığlık çığlığa sesimin bitmeyen yankısı

Haznesi  boşalmış bir gaz lambası

Kısıldı, azaldı, titredi, İstanbul gibi söndü.

Yüzümde koparılmış bir tebessüm haksızlığı

Hazin bir martı sesi İstanbul’un üstünde

Bir sabır işi, işkence kanaviçesi dokuyacağım

Yarın İstanbul da sadece ben ağlayacağım.', 'Gecenin ilk ışıkları  yalnızlığımı kucakladı  Oysa tam silmiş söndürmüştüm gözlerimi İçimdeki bütün ışıkları yakmamı söyleyen İblisin sesi d...', ARRAY['Türk Edebiyatı','Şiir','Didem Esen']::text[], 8.5, '{"poet":"Didem Esen","poet_slug":"didem-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/iblisi-olmayan-bir-istanbul-dusunulemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Adını Yazdım', 'senin-adini-yazdim-huseyin-erdogan-ygrh9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'senin adını yazdım 

rüzgarlara

kazısınlar diye 

dağlara taşlara

bir gün kısmet olur da

gelirsen buralara

yalnızca 

kendi ismini bulacaksın 

yollarda

seni isteyip de 

göremeyişim de

yaralar açıyor yüreğimde

sen benim güneşimsin 

uzaktan da olsa

her sabah doğan

beni aydınlatan 

sımsıcak ısıtan

iyi ki sen benim 

kalbimdesin canım

yoksa ben soğuktan

çoktan donardım çoktan

                      22.11.2004', 'senin adını yazdım  rüzgarlara kazısınlar diye  dağlara taşlara bir gün kısmet olur da gelirsen buralara yalnızca  kendi ismini bulacaksın  ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/senin-adini-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim', 'ogretmenim-i-rfan-simsek-rao2a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ÖĞRETMENİM        

 İlim irfanla coşarsın,

 Engelleri hep aşarsın,

 Daim ileri koşarsın,

 Öğretmenim, öğretmenim.

        *****    *****

 Çocuk çiçek sen arısın,

 Sen vatana sevdalısın,

 Milletin can damarısın,

 Öğretmenim, öğretmenim.

        *****    *****

 Köylerde körpe çiçekler,

 Senin yollarını bekler,

 Sen gidersen gülecekler,

 Öğretmenim, öğretmenim.

        *****    *****

 Doğuda sen, batıda sen,

 Yelsin ılgıt ılgıt esen,

 Cehaleti kökten kesen,                            

 Öğretmenim, öğretmenim.

        *****    *****

 Hem şehitsin, hem gazisin,

 Hem kalemsin, hem yazısın,

 Kurdun elinde kuzusun,

 Öğretmenim, öğretmenim.

     *****    *****

 Öğretmenler günü imiş,

 Bakan şunu, şunu demiş,

 Nice nutuklar dinlemiş,

 Öğretmenim, öğretmenim.

     *****    *****

 Boş laf karın doyurmuyor,

 Feryadın hiç duyulmuyor,

 Kitap bile alamıyor,

 Öğretmenim,öğretmenim.

     *****    *****

 Ankara’da kabortacı,

 İstanbul’da işportacı,

 Yine sen başımın tacı,

 Öğretmenim, öğretmenim,

     *****    *****

 Dili altın, sözü sedef,

 Cehalati edersin def,

 Kahpe PKK’ya hedef,

 Öğretmenim, öğretmenim.

     *****    *****

 İRFAN’ım öğretmen oldu,

 Hem boşaldı hemi doldu,

 Gazi oldu, şehit oldu,

 Öğretmenim, öğretmenim.

      24 Kasım 1996-GEREDE', 'ÖĞRETMENİM          İlim irfanla coşarsın,  Engelleri hep aşarsın,  Daim ileri koşarsın,  Öğretmenim, öğretmenim.         *****    *****  Ço...', ARRAY['Türk Edebiyatı','Şiir','İrfan Şimşek']::text[], 8.5, '{"poet":"İrfan Şimşek","poet_slug":"i-rfan-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/ogretmenim-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Ayı', 'bahar-ayi-i-rfan-simsek-4cjg9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BAHAR AYI

Ağaç dalları hep tomurcuk bağlar,

Her türlü çiçekle bezenir dağlar,

Sevinçle kırlara dökülür mallar,

Kış çekilip bahar ayı gelende.

     ******   ******

Dalda cıvıl cıvıl ötüşür kuşlar,

Ekinler boy atar kaybolur taşlar,

Çobanlarım sığır gütmeye başlar,

Kış çekilip bahar ayı gelende.

     ******   ******

Bal verir her türlü çiçek arıya,

Kazlar yavrularla iner çayıra,

Meleşir kuzular çıkar bayıra,

Kış çekilip bahar ayı gelende.

     ******   ******

Arılar, böcekler çıkar meydana,

Çiçekler de koku saçar her yana,

Güzeller de inci takar gerdana,

Kış çekilip bahar ayı gelende.

     ******   ******

Ben Aşık İRFAN’ım severim yazı,

Uğraşma sevdiğim çekemem nazı,

Aklıma düşüyor zalımın kızı,

Kış çekilip BAHAR AYI gelende.

                     12.04.1978-SAMAT', 'BAHAR AYI Ağaç dalları hep tomurcuk bağlar, Her türlü çiçekle bezenir dağlar, Sevinçle kırlara dökülür mallar, Kış çekilip bahar ayı gelende...', ARRAY['Türk Edebiyatı','Şiir','İrfan Şimşek']::text[], 8.5, '{"poet":"İrfan Şimşek","poet_slug":"i-rfan-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bahar-ayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisan Ayı Geldiğinde', 'nisan-ayi-geldiginde-i-rfan-simsek-yoawg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'NİSAN AYI GELDİĞİNDE

Kuşlar daldan dala uçar,

Kırlarda çiçekler açar,

Çiftçi dayı tohum atar,

Nisan ayı geldiğinde.

**********

Boz bulanık akar seller,

Tomurcukla dolar dallar,

Kırlarda oynaşır mallar,

Nisan ayı geldiğinde.

**********

Kuşlar cıvıl cıvıldaşır,

Arı çiçekten bal taşır,

Tüm dünyanın gözü ışır,

Nisan ayı geldiğinde.

********

Kırlar yeşile boyanır,

Beyaz urbasın soyunur,

Toprak uykudan uyanır,

Nisan ayı geldiğinde.

**********

Uyanır hep yılan, çiyan,

Pırıl pırıl olur her yan,

Kırda gezer Aşık İrfan,

Nisan ayı geldiğinde.

20.04.1987 – SAMAT', 'NİSAN AYI GELDİĞİNDE Kuşlar daldan dala uçar, Kırlarda çiçekler açar, Çiftçi dayı tohum atar, Nisan ayı geldiğinde. ********** Boz bulanık a...', ARRAY['Türk Edebiyatı','Şiir','İrfan Şimşek']::text[], 8.5, '{"poet":"İrfan Şimşek","poet_slug":"i-rfan-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/nisan-ayi-geldiginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüme suçüstü', 'gonlume-sucustu-fahrettin-koseoglu-nk7fd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dedi; 

-bana ihaneti anlat...

dedim; 

-seni çok seviyorum...

...

lekesizliğinden korkuyordum sevdamızın

nazarlığı olsun bu diye

çamurda gezdim tedbirsiz

“battın mı” diye sorma sakın...

arsız dilim yılan

kendini bile delikten çıkarır...

inanmıyor gibi bakma bana

dediklerim elbette yalan 

ama aldırma 

şu aralar sözüm bile kendinde değil...

bak masalsı sözler söyleyeyim sana

bayayım gözlerini

zaafındır biliyorum,

sesimin sandalında gezinmek

“sevmedim senden başkasını beni sevdiğim kadar

tütüne sevdan,

uykusuzluğa da yokluğun alıştırdı beni

oy gözlerinde herkesten fazlasını gördüğüm

oy gözlerinden ecele vardığım

sular utandı seni içerken dudağım

senden geçerken yollar utandı

sende uçarken gökler utandı

kapandı kolların üstüme,

ömrüm utandı...”', 'dedi;  -bana ihaneti anlat... dedim;  -seni çok seviyorum... ... lekesizliğinden korkuyordum sevdamızın nazarlığı olsun bu diye çamurda gezd...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Köseoğlu']::text[], 8.5, '{"poet":"Fahrettin Köseoğlu","poet_slug":"fahrettin-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gonlume-sucustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yayla Yolları', 'yayla-yollari-i-rfan-simsek-ohgs9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'YAYLA YOLLARI

 Yaylanın yolları taşlı bayırlı,

 Kenarları yeşil çimen çayırlı,

 Ayrılık günleri gelir sayılı, 

 Yayladan gel gülüm bizim yayladan,

 Yayla yolları toz, duman olmadan.		

      *********************		     		         Yaylaçayırında kızlar kol gezer                 

Ellerinde iğne kül boncuk dizer	  

Bizim sevgimizi yad eller sezer 

Yayladan gel gülüm bizim yayladan.       	  

Yayla yolları toz, duman olmadan.	    	  

	************		

Yaylanın yolları tozdur, görünmez	

Akşam olur karanlıkta yürünmez, 

Yukarı çek al fistanın sürünmez,

Yayladan gel gülüm bizim yayladan,

Yayla yolları toz duman olmadan.		

            ***************

Yayla çayırında açar çiçekler.

Açar da kokusun bizlere saklar.

Aşık İrfan senin yolların bekler.	

Yayladan gel gülüm bizim yayladan,

Yayla yolları toz duman olmadan.		

			06.05.1978-SAMAT YAYLASI', 'YAYLA YOLLARI  Yaylanın yolları taşlı bayırlı,  Kenarları yeşil çimen çayırlı,  Ayrılık günleri gelir sayılı,   Yayladan gel gülüm bizim yay...', ARRAY['Türk Edebiyatı','Şiir','İrfan Şimşek']::text[], 8.5, '{"poet":"İrfan Şimşek","poet_slug":"i-rfan-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yayla-yollari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Ol *', 'ol-nesibe-ozkara-s7gto', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnsanın bedeni, insana bir yurt,

Açılan yaraya, düşüyorken kurt,

Çekilen ezâya, sabırdan sükût,

Eyyûb gibi sabır âbidesi ol...

.........

Söz dinlemeyen bana... benden...', 'İnsanın bedeni, insana bir yurt, Açılan yaraya, düşüyorken kurt, Çekilen ezâya, sabırdan sükût, Eyyûb gibi sabır âbidesi ol... ......... Söz...', ARRAY['Türk Edebiyatı','Şiir','Nesibe Özkara']::text[], 8.5, '{"poet":"Nesibe Özkara","poet_slug":"nesibe-ozkara","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ol-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretin Çoğalır İçimde', 'hasretin-cogalir-i-cimde-huseyin-erdogan-bibmv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sesini her duyuşumda

hasretin çoğalır içimde

adını her anışımda

nemler oluşur gözlerimde

inan ki hep sendedir aklım

sensin benim kalbimde saklım

sen benim güzel yüreklimsin

seni yaşıyorum her anımda

havalar soğuyunca

ellerimi siper ediyorum yüreğime

seni üşümesin diye

sen gönül bahçemde

günden güne 

yeşillenen çiçeğimsin

söyle güzelim

seni koklayabilir miyim? 

ölünceye değin

             22.11.2004', 'sesini her duyuşumda hasretin çoğalır içimde adını her anışımda nemler oluşur gözlerimde inan ki hep sendedir aklım sensin benim kalbimde sa...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hasretin-cogalir-icimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eda'' nın Gözlerinde', 'eda-nin-gozlerinde-ozkan-gonlum-65qq9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gülümser hep insana

			Hayat verir bin cana

			Her şey sevgiden yana

			Eda'' nın gözlerinde.

			Güzel gözü seversen

			Sen de gel gör istersen

			Maviler desen - desen 

			Eda''nın gözlerinde.

			Dünya''yla barışıktır

			Gönle dolan ışıktır

			Maviler sarmaşıktır

			Eda'' nın gözlerinde.

			Güzellikleri taşır

			Sevenlere ulaşır

			Mavi nehir dolaşır

			Eda'' nın gözlerinde.

			Bir sihiri sezersin

			Hayalleri dizersin

			Yeri göğü gezersin

			Eda'' nın gözlerinde.

			Mavileri derersin

			Muradına erersin

			Bir Cennete girersin

			Eda'' nın gözlerinde.', 'Gülümser hep insana 			Hayat verir bin cana 			Her şey sevgiden yana 			Eda'' nın gözlerinde. 			Güzel gözü seversen 			Sen de gel gör isters...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/eda-nin-gozlerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekirgede Hayat', 'cekirgede-hayat-dogan-i-nceman-j6hv3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çekirgedeki sokaklar

Hayatın kendisine benzer; 

Bir yokuştan inersiniz

Bir yokuş çıkar.

Bazen bir tatlı inişle

Gelir evinize,

Bazen çok diktir.

Dört yapraklı yonca

Vardır bahçelerinde.

Elvan elvan çiçekler,

Güzelim ağaçlar vardır

Yol içinde.

Çekirgedeki sokaklar

Sevginin ta kendisidir.

Gece yarıları şarkılar

Söylenir hafiften,

Kimseler uyanmadan.

Kar yağışını seyredersiniz

Pencerenizden,

Sokak lambaları lapa lapa

Aydınlatır yüreğinizi.

Üşümezsiniz 

Çayınızı yudumlarken.

Çekirgedeki sokaklar

Çocuklara benzer; 

Cıvıl cıvıldır.

Gündüzlerin hakimi onlardır.

Bazen top kaçar 

Nefes nefese kalırsınız

Bazen kayak yapar

Bir duvara toslayıp durursunuz.

Bazen ilk aşkın

Gözleriyle karşılarsınız,

Ve arabayla geçer o gözler

Kıpır kıpır olursunuz.

Çekirgedeki sokaklar varya,

Aşkı,dostluğu,paylaşmayı,

Yani,bütün güzellikleriyle hayatı,

Çekirgedeki sokaklarda bulursunuz.

23.12.2002    Bursa', 'Çekirgedeki sokaklar Hayatın kendisine benzer;  Bir yokuştan inersiniz Bir yokuş çıkar. Bazen bir tatlı inişle Gelir evinize, Bazen çok dikt...', ARRAY['Türk Edebiyatı','Şiir','Doğan İnceman']::text[], 8.5, '{"poet":"Doğan İnceman","poet_slug":"dogan-i-nceman","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/cekirgede-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Şiir', 'son-siir-sedat-kisa-1dhua', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'mekan gül

zaman güz 

insan giz

tüm doğrularımızı toplasak 

tek bir yanlış etmeyiz

başkaları konulamaz 

kaybettiklerimizin yerine 

aslında 

herkes kendine rehine 

ve her şiir 

bir kurtarma eylemi 

her eylem 

en az bir kayıp verir', 'mekan gül zaman güz  insan giz tüm doğrularımızı toplasak  tek bir yanlış etmeyiz başkaları konulamaz  kaybettiklerimizin yerine  aslında  h...', ARRAY['Türk Edebiyatı','Şiir','Sedat Kısa']::text[], 8.5, '{"poet":"Sedat Kısa","poet_slug":"sedat-kisa","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/son-siir-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dallarımı Kırdı Gitti', 'dallarimi-kirdi-gitti-murat-demir-26hw1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gözlerine inandığım

Sözlerine hep kandığım

İçimdeki can sandığım

Dallarımı kırdı gitti

Dinlemeden kelamımı

Hoş etmeden selamımı

Sevdasının dumanını

Yüreğime sardı gitti

Bir esimlik bulut gibi

El sallayıp unut gibi

Gücün varsa gel tut gibi

Karanlığı yardı gitti

Parçalayıp dert ağını

Yıkıp aşkın ocağını

Torbalayıp sıcağını

Beni kışa saldı gitti

Ne utanıp büzülerek

Ne de yanıp üzülerek

Rüzgar gibi süzülerek

Bir boşluğa daldı gitti

Ellerime el vermeyip

Bir kez olsun güldürmeyip

Hadi sende Murat deyip

Her şeyimi aldı gitti', 'gözlerine inandığım Sözlerine hep kandığım İçimdeki can sandığım Dallarımı kırdı gitti Dinlemeden kelamımı Hoş etmeden selamımı Sevdasının d...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dallarimi-kirdi-gitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sakın*', 'sakin-bekir-gedikoglu-uq17h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dudakların kor gibiyse

Sakın beni öpüverme

Bir daha ben konuşamam

Dilim erir içeride

Ellerinde ateş varsa

Sakın sürme sen tenime

İnim,  inim inlerim ben

Elinin her değişinde

Göz yaşında aşk var ise

Sakın bakma gözlerime

Her damlada kahrolurum

İnme iner yüreğime

Ankara 22 Kasım 2004', 'Dudakların kor gibiyse Sakın beni öpüverme Bir daha ben konuşamam Dilim erir içeride Ellerinde ateş varsa Sakın sürme sen tenime İnim,  inim...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sakin-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınımsın Sen Benim', 'kadinimsin-sen-benim-ozkan-gonlum-c700s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünyasına girdiğim

			Gençliğimi verdiğim

			Huzur dolu günlerle

			On beş yıla erdiğim

			Kadınımsın sen benim.

			Ne zengin olduk ne fakir

			Yokluk çekmedik çok şükür

			Aşkın tadını veren

			Yaşamayı sevdiren

			Kadınımsın sen benim.

			Mehmet ile Ayşe'' yi verdin bana

			Teşekkür azdır sana

			Ekmeğim aşımsın sen

			Benim can yoldaşımsın sen

			Kadınımsın sen benim.

			Gözlerinin içine baktığım

			Aşkını katık yaptığım

			İçime ruh gibi dolan

			Her şeyiyle ben olan

			Kadınımsın sen benim.

							25.10.1984', 'Dünyasına girdiğim 			Gençliğimi verdiğim 			Huzur dolu günlerle 			On beş yıla erdiğim 			Kadınımsın sen benim. 			Ne zengin olduk ne fakir...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kadinimsin-sen-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birlikte Nice Yıllara', 'birlikte-nice-yillara-ozkan-gonlum-rd4sn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Evliliğimizin yıldönümünde

			Bu şiir de sana Bir tanem

			Daha önce çok yazdım

			Yine de yazacağım

			Çok şeyler dedim

			Yine de diyeceğim

			Gönül tarlamıza şiirlerle

			Sevgi kokan çiçekler dikeceğim.

			Bir tanem

			Acısıyla tatlısıyla

			Giden yılları birer - birer

			Yaşadık senle beraber

			Yirmi sekiz yılı uğurladık

			Ve şimdi

			Saçımızın teli ağardı

			Gözümüzün feri azaldı

			Ömrün sonuna yaklaştık

			Yaş elli altmışa bastık

			Unumuzu eledik

			Eleğimizi astık.

			Seninle olmak Sultanım

			Yaşamın anlamıdır

			En güzel duygularım

			En tatlı anılarım

			Hayallerim umutlarım

			Yaşanmış mutlu yıllarım

			Yazdığım şiirler

			Söylediğim şarkılar

			İçtiğim kadehler

			Senle dolu birer - birer.

                                                Otuzuncu yılımıza iki kala

			Ve halâ

			İçimiz sevgiyle heyecanla doluyuz

			Örnek olsun herkese

			Biz aşkın sembolü

			Biz mutluluk yoluyuz.

			Sen Bir tanem

			Sen Mehmet'' imle Ayşe'' min anası

			Sen ömrümün manası

			Sen sevincim, tasam

			Sen gönül kasam

			Sen bu dünyada varımsın

			Sen şiirimde ilhamım

			Aşkımsın kadınımsın karımsın...

			Sen sevgilimsin ölüme kadar

			Yüreğime kazıdım senin adını.

			Senle geçti yıllarım bugüne kadar

			Sensin inan GÖNLÜM'' ün eşsiz kadını.

							25.10.1997', 'Evliliğimizin yıldönümünde 			Bu şiir de sana Bir tanem 			Daha önce çok yazdım 			Yine de yazacağım 			Çok şeyler dedim 			Yine de diyeceği...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/birlikte-nice-yillara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gülerken...', 'sen-gulerken-i-brahim-ethem-bingul-m66eq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben hicranı yudum yudum içerken

İçim ağlar sen gezerken, gülerken

Gecelerim olur senin günlerin

Dertlerimi bir bir sayıp dökerken...

Senin kaşın, gözün, caziben, gamzen

Bakışların beni eriten süzen

Yakar beni ateşinde közlerin

Kaş çatışın yok mu, o beni üzen... 

Beni ağlatırsan boyun mu uzar? 

Mutlu görsen beni için mi sızlar? 

Senin rüzgârlı mı geçer güzlerin? 

Affet desem, gelsem erir mi buzlar? 

Çok soğuk geçiyor içimde kışlar

Kanattı bağrımı attığın taşlar

Benim elemlerim senin süslerin

Sen gülerken akar gözümden yaşlar...

www.iebingul.com', 'Ben hicranı yudum yudum içerken İçim ağlar sen gezerken, gülerken Gecelerim olur senin günlerin Dertlerimi bir bir sayıp dökerken... Senin k...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-gulerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelinlik En Güzel Sana Yakışır', 'gelinlik-en-guzel-sana-yakisir-ozkan-gonlum-00e89', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkın en güzeli sende yeşersin

		Mutluluktan başın göklere ersin

		Güzel Ayşe’m dünyalara değersin

		Gelinlik en güzel sana yakışır.

		Yanacak yüreğin aşk ateşiyle

		Buzları eritecek gönül dağın

		Gelince Birtanem gelinlik çağın

		Gelinlik en güzel sana yakışır.

		Bir gün gelip düğün dernek kurunca

		Davullar düğünde güm – güm vurunca

		Sen telli duvaklı gelin olunca

		Gelinlik en güzel sana yakışır.

		Bilmem sonumuz ne olacak dersin

		Yaşlı gözlerinle dua edersin

		Âdettir bu hem ağlar, hem gidersin

		Gelinlik en güzel sana yakışır.

                                Hayat çözülecek bir bilmecedir

		Evlilik bir erdemdir, çok yücedir

		Seni hayâl ediyorum nicedir

		ANALIK  en güzel sana yakışır.

		Sen gidince ayrılığı yüreğime basarım 

		Düğün resimlerini de başucuma asarım

		Torunlar ‘’Dede! Dede! ‘’ diye elimi öpünce

		DEDELİK en güzel bana yakışır.

		Ölürsem görmeden gelin olduğunu

		Şiirim  armağan  olsun ömür boyu

		Gönülden düşledim bu güzel tabloyu

		Evlâtlık en güzel sana yakışır..

					17.01.1994', 'Aşkın en güzeli sende yeşersin 		Mutluluktan başın göklere ersin 		Güzel Ayşe’m dünyalara değersin 		Gelinlik en güzel sana yakışır. 		Yanac...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gelinlik-en-guzel-sana-yakisir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özay Gönlüm'' e Kardeşnâme', 'ozay-gonlum-e-kardesn-me-ozkan-gonlum-b87u0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '‘’YÂREN ‘’ sazın elinde

Mızrap ile teller konuşur sanki.

Bir yanık ezgi dilinde

Duyunca yüreğim tutuşur sanki.

Türküler dillenir senin sazında

Gelinler oynar, efeler diz vurur.

Sazınla, sözünle dinleyen seni

Kendini Anadolu’ da bulur.

‘’Avşar Beyleri’’ dersin

Gürül -gürül akar sesin

Sen sende değil o anda

Sazdasın, teldesin, gönüldesin.

Vur sazının tellerine

Vur, vur ki dünya duysun

Sazının her bir teline 

Bin şiirim feda olsun.

							1986', '‘’YÂREN ‘’ sazın elinde Mızrap ile teller konuşur sanki. Bir yanık ezgi dilinde Duyunca yüreğim tutuşur sanki. Türküler dillenir senin sazın...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ozay-gonlum-e-kardesname-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Ol Köşkünde', 'mutlu-ol-koskunde-engin-namli-hbt7a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgilim seni unutmam mümkün mü? 

Her mektubunla vurma yerden yere 

Hiç yazmayanlar yarine küskün mü? 

Verme kendini sitemkâr sözlere 

Sanmaki zaman vuslata akıyor 

Bitmez hasretin güne gün takıyor 

Ne yana dönsem bir resmin bakıyor, 

Öyle hasretim ki senli günlere 

Gamlı yaşantım sürse de sürgünde; 

Düşünme beni mutlu ol köşkünde. 

Garip sevdiğin ilk gün ki sözünde

İnanma sakın gelmez diyenlere 

Hep bekleyecek değilsin sevdiğim; 

Elbette bir gün çıkıp geleceğim. 

Her seven gibi bende güleceğim 

Dolaşacağım göğsüm gere gere 

ENGİN NAMLI 22:13 20.11.2004', 'Sevgilim seni unutmam mümkün mü?  Her mektubunla vurma yerden yere  Hiç yazmayanlar yarine küskün mü?  Verme kendini sitemkâr sözlere  Sanma...', ARRAY['Türk Edebiyatı','Şiir','Engin Namlı']::text[], 8.5, '{"poet":"Engin Namlı","poet_slug":"engin-namli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mutlu-ol-koskunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-ertugrul-sakar-41iix', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sonbahar

Ayrık otlarıda kurur

Eğer gelebilmişse

Bu zamana

Yapraklar

Sarı,kızıl

İnsan sızılı

Sevda

Yapraksız bir ağaç

Kaç gündür

Yakamı topluyor rüzgar

Belki gelecek

Dolu,kar

Ayrık otlarıda üşüyor

Dallar ve yapraklar düşüyor', 'Sonbahar Ayrık otlarıda kurur Eğer gelebilmişse Bu zamana Yapraklar Sarı,kızıl İnsan sızılı Sevda Yapraksız bir ağaç Kaç gündür Yakamı toplu...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sonbahar-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-taner-arda-dttlo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Umutların acılara döndüğü gündü,

Tökezliyordu prangalara vurulmuş ayaklar..

İnsanlık yavaş yavaş tükeniyordu,

Zalimlik ve ölümle….

Ve o sevgiyle yüklü adam 

Taşıyordu sonunu kendi omuzlarında…

Uzaklarda, bir tek kadının 

Dökülürken gözyaşları birer birer..

Her damla için bir çivi çakılıyordu..

Bir rüzgardı esen, kulakları tırmalayan,

Yıldırımlar sadece bir gürültüydü o an..

Ne yıldırımlardan beklenen ateş,

Ne de yağmur düştü kara bulutlardan..

Düşen sadece bir gölgeydi dünyanın üstüne.

Ve nefretin gölgesi yüzlerine vurmuş insanlar,

Uzakta bir kadın yalnız ağlarken,

Sevgiyi  çarmıha gerdiler….', 'Umutların acılara döndüğü gündü, Tökezliyordu prangalara vurulmuş ayaklar.. İnsanlık yavaş yavaş tükeniyordu, Zalimlik ve ölümle…. Ve o sevg...', ARRAY['Türk Edebiyatı','Şiir','Taner Arda']::text[], 8.5, '{"poet":"Taner Arda","poet_slug":"taner-arda","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevgi-149-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Vapur Bölerdi', 'bir-vapur-bolerdi-ertugrul-sakar-fckpb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir vapur bölerdi boğazı ikiye

Hep senin yanına getirirdi

Irmağa düşmüş bir yaprağı duyarmıydın? 

Duyarmıydın kemirgen sincapların sesini? 

Bilmezdim kitap gibi içini okumayı

İçini nelerle ördüğünü bilmezdim

Seni seyrederdim dalgalara bakar gibi

Bakar gibi uyurdum takip ederken seni

Sahiller meğer ne kadar uzunmuş,bitmez

Bitmez bir ayrılığın mesafesi sahiller

Eskiden hala saklı bir bitmemiş ıslaklık

Bir bitmemiş kara nokta gözlerimde eskiden

İnip ulaşmak varmış ayaklarına

Ayaklarına dokunmak varmış inip

Düşündükçe bir geçmişi ikiye ayıran suskunluğu

Suskunluğun mezarında seni yitirdiğimi düşündükçe

Kader dediğim bir bitmemiş yağlıboya tabloydu karşımda

Karşımda kullanamadığım bir tuval kader dediğim', 'Bir vapur bölerdi boğazı ikiye Hep senin yanına getirirdi Irmağa düşmüş bir yaprağı duyarmıydın?  Duyarmıydın kemirgen sincapların sesini?  ...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-vapur-bolerdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız Çocuğuyum', 'kiz-cocuguyum-adulera-ayza-dz2df', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Türkiyenin doğusunda 

Bir yerlerde 

Bir kız çocugu olarak 

Yeniden başlıyorum hayata 

Daha doğarken başlıyor sorunlar 

Kar kış kıyamet 

Kol geziyor açlık yokluk 

En kötüsüde ihanet 

Artık kimbilir 

Olmayacak belkide 

Bir nüfus cüzdanım bile 

Adım bile sorulmayacak 

En önemli konu sorulacak bana 

Bekaret 

Artık kimsenin bilmediği 

Gezmeye bile cesaret edemediği 

Bir köye on dördümde 

Gelin ederler beni 

Üç yıl geçmeden 

İki çocuk anası 

Yediğim yiyeceğim 

Dayaklar da cabası 

Soruyorum sizlere 

Kimsenin bilmediği yerlerde 

Kim zorladı sizleri 

Soruyorum şimdi 

Tüm doğuran annelere 

Soruyorum sizlere 

Tüm dogudaki 

Kız çocugu gebelere 

Adını bile anımsamadıgınız bir köye verin 

Kızınızı 

Yeniden doğurun alamazsanız hızınızı 

Size inat 

Bende dogurmaya devam edeceğim 

Kız çocugu doğurmamaya yeminliyim', 'Türkiyenin doğusunda  Bir yerlerde  Bir kız çocugu olarak  Yeniden başlıyorum hayata  Daha doğarken başlıyor sorunlar  Kar kış kıyamet  Kol ...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kiz-cocuguyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasemin', 'yasemin-dogan-i-nceman-euq83', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günaydın ey nazlı beyaz

Kokusu bir şehire bedel çiçek.

Bir bahçe kapısına sarılmışsın,

Bazen bir korkuluğa.

Yalnız değilsin hep.

Seni,belkide bu yüzden

Çok seviyorum.

Sarılıyorsun,paylaşıyorsun,

Küsmüyorsun.

Nazlısın dedik ya; 

Bazen el değmeden

Yere düşüyorsun.

İzmir- 22.11.2004', 'Günaydın ey nazlı beyaz Kokusu bir şehire bedel çiçek. Bir bahçe kapısına sarılmışsın, Bazen bir korkuluğa. Yalnız değilsin hep. Seni,belkid...', ARRAY['Türk Edebiyatı','Şiir','Doğan İnceman']::text[], 8.5, '{"poet":"Doğan İnceman","poet_slug":"dogan-i-nceman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yasemin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zehra Aslandoğan'' a', 'zehra-aslandogan-a-ozkan-gonlum-90g5p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saygılarımla..

					 	

Bahri beyin mutluluk yuvasında

	Vefakâr ve cefakâr bir eştir o.

	Bir yaşam boyu, sevgi dünyasında

	Işıl-ışıl parlayan güneştir o.

	İlgisi candan, sevgisi candandır

	İnciler dökülür dilinden bir–bir.

	Yeri geldi mi dostlar meclisinde

	Şiirler okur sevgiye, aşka dair.

	Kardeşçe ve insancadır her tavrı

	Yüreğinde sevgi, dostluk doludur.

	Cumhuriyetin öğretmenidir o

	İzlediği  ATATÜRK’ ün  yoludur. 

	Ayrılmaz asla ATATÜRK yolundan

	Özgürlük türküsü düşmez dilinden.

	Sevgili kardeşimiz  Zehra öğretmene

	Bu sözler döküldü gönül telimden.

					Altınoluk	

				         20.10.2003', 'Saygılarımla.. 					 	 Bahri beyin mutluluk yuvasında 	Vefakâr ve cefakâr bir eştir o. 	Bir yaşam boyu, sevgi dünyasında 	Işıl-ışıl parlayan...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/zehra-aslandogan-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koca Çınar Tufan Baba', 'koca-cinar-tufan-baba-ozkan-gonlum-38bs3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'A.Tufan ŞENTÜRK’ e

	Tufan baba

	Esentepe köyünden çıktın yola

	Ankara’ da yaşadın dönmedin sen.

	Evrensel şiirlerinle sevdik seni

	Doruktan aşağı inmedin sen.

	Mevlâna’ ca  sevgi ektin

	Yunus gibi çile çektin.

	En üstün özelliklerle yaratmış seni

	Sen Allah’ın nadir kulusun.

	İlhâm indirmiş yüreğine

	Sen Allah’ ın şair kulusun.

	Ustasısın, hocasısın şairlerin

	Kelimeleri  mısra-mısra

	Türkçe’nin  en güzel sözüyle

	Melodinin özüyle

	İlmik-ilmik dokursun.

	En güzel şiirlerini gönülden

	Gürül-gürül delikanlı sesinle

	Gümbür-gümbür okursun. 

                Kitaplar dolusu yazdıkların

	Şiirin onurudur.

	Tufan baba adı 

	Şairliğinin gururudur.

	84 yıllık ömür boyunca

	İlham bülbülleri şakır bağında.

	Şiirlerin, türkülerin söylenir	

	Sesin yankılanır Toros Dağı’ nda.

	En güzel şiirlerle, sözlerle

	Sevgiyi katmer-katmer 

	Gönlümüze doldurup yığansın.

	Seven, sevilen yüreğinle sen

	İnsanlığa armağansın.

	Kendine özgü yaşam biçimin

	Kendi yasan var senin.

	Mala, paraya değer vermezsin

	Yaşam kavgan zor senin.

                Uzun ömründe

	Kahpe Felek kimi zaman

	Toroslar’ dan kar getirdi

	Kimi zaman kucak-kucak

                Ayva, üzüm, nar getirdi.

	Eşinin yokluğuyla geçen yıllar

	Seni yedi bitirdi.

	Küllenmiş kordur yüreğin

	İçten içe yanarsın sen.

	Her gün her dakika yıllardır

	Özlem ile, dua ile

	Yengemizi anarsın sen.

	Sevgili Tufan baba

	Senin hayatın, senin şiirin

	Ne yazmakla biter

	Ne anlatmakla tükenir

	Senin gibisine bilmem ki

	En güzelinden ne denir.

	Hiç şüphesiz

	İnsanlığa armağan şiirlerinle

	Yarına kalacaksın sen.

	Ve yıllar sonra

	Dilden-dile söylenen

	Bir efsane olacaksın sen. 

						5.4.2003', 'A.Tufan ŞENTÜRK’ e 	Tufan baba 	Esentepe köyünden çıktın yola 	Ankara’ da yaşadın dönmedin sen. 	Evrensel şiirlerinle sevdik seni 	Doruktan ...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/koca-cinar-tufan-baba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Yarası', 'gonul-yarasi-zulfikar-yapar-kaleli-s7uee', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kilitli dillerin kalbine esen 

Divanenin yolda kalmış umuru 

Sadaret tahtının Süleyman''ı sen 

Bense senin eşiğinin çamuru 

Seher bülbülleri seni anlatır 

Mevlithanlar okur seni dinletir 

Gözümden kalbime bir ışık getir 

Erisin beynimin kemirgen uru 

Ağlayan bulutun gönül yarası 

Güneşin yıldızın ayın arası 

Karanlık sokağın mumu çırası 

Gönlümün ışığı gözümün nuru', 'Kilitli dillerin kalbine esen  Divanenin yolda kalmış umuru  Sadaret tahtının Süleyman''ı sen  Bense senin eşiğinin çamuru  Seher bülbülleri ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-yarasi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmedin', 'bilmedin-sevim-atan-2kq7p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen hiç bilmedin,

Ben saf bir bebek gibi

Ağlarken birşeylere,

Gülerken küçük ilgilere,

Sen hiç bilmedin

Neden gözlerim parladı

Bakarken gözlerinin içine.......

10.05.2000', 'Sen hiç bilmedin, Ben saf bir bebek gibi Ağlarken birşeylere, Gülerken küçük ilgilere, Sen hiç bilmedin Neden gözlerim parladı Bakarken gözl...', ARRAY['Türk Edebiyatı','Şiir','Sevim Atan']::text[], 8.5, '{"poet":"Sevim Atan","poet_slug":"sevim-atan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bilmedin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvercinli Küçük Kız', 'guvercinli-kucuk-kiz-mustafa-toga-3slrt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir ev vardι Anadolu’da

Anadolu’nun bağrι nda.

Küçük, beyaz badanalι .

Kι rmι zι ydι tütmeyen bacasι .

Rengârenk çiçekler vardι ön bahçede

Arkadaki yemiş ağacι çok yaşlι ydι 

Bilmem kaç asι rlι k.

Dallarι nda kuş yuvalarι 

Yuvanι n birinde kanadι kι rι k bir güvercin yaşardι .

Bu küçük ev, yoksuldu, hüzünlüydü

Sekiz nüfus barι ndι rι rdι içerisinde

Kι ş aylarι nda sarar, sarmalardι 

Ayazdan, kardan, tipiden korurdu onlarι .

Yazι n da gölge olur serin tutardι ,

Ağlayana beşik,

Gülene oyuncak olurdu.

Bir küçük kι z vardι Anadolu’da

Anadolu’nun koynunda.

Kaküllü saçlarι dalga dalgaydι .

Gözleri masmavi, yanaklar pembe

Tombul tombuldu.

Konuşan bebekleri yoktu onun

Bez bebeklere sarι larak uyurdu.

Patikleri ayaklarι nι vurduğundan,

Yalι n ayak çamurlarda koşar,

Patlamι ş balonlarla evcilik oynardι .

Sarι saçlι küçük kι z,

Her gün ekmek kι rι ntι sι götürürdü.

Arka bahçedeki güvercine.

Arkadaşι ydι onun

Konuşurlardι .

Annesinin hasta olduğunu

Babasι nι n ilaç parasι bulmak için

Üç tekerlekli arabasι yla şehri dört döndüğünü.

Abilerinin saçι nι çektiğini

Ablalarι nι n bazan okuldan kaçι p oğlanlarla buluştuğunu

Canι nι n bisiklete binmek istediğini

Güneşe göz kι rptι ğι nι 

Gökyüzünün mavi, ormanlarι n yeşil olduğunu

Rüyasι nda melek olup uçtuğunu

Anne sütünden başka süt içmediğini

Gülmeye özlem duyduğunu

Her şeyini ama her şeyini

Anlatι rdι dostu güvercine.

O da guuur... guuur... diye yanι tlardι .

Nizip / GAZÍANTEP

SÖZÜN ÖZÜ: 

Aşk, gülü dikeniyle avuçlamaya benzer. Ellerin kan içinde kalır, ama dikenlerin hesabını gülden soramazsın.

www.mustafatoga.com', 'Bir ev vardι Anadolu’da Anadolu’nun bağrι nda. Küçük, beyaz badanalι . Kι rmι zι ydι tütmeyen bacasι . Rengârenk çiçekler vardι ön bahçede A...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Toga']::text[], 8.5, '{"poet":"Mustafa Toga","poet_slug":"mustafa-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/guvercinli-kucuk-kiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalınız Bizim İçin', 'yaliniz-bizim-i-cin-mehmed-arif-i2igs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yalınız bizim için dönüyor sanırdık dünya

güneş bizim için doğuyor

horoz bizim için ötüyor 

gökkuşağı bize salıncak kuruyor

bir bizi ıslatıyor bilirdik kırkikindiler balkonda

bir bizi selamlıyordu haydarpaşa’dan kalkan vapurlar

gevrek simit kokuları arasında

kızkulesi davetkardı günbatımı salacak’ta

fener, kalamış, adalar ve moda

mendil sallardık gelen geçen yabancılara

yalınız bizim için dönüyor sanırdık dünya

ufka doğru yelken açan martılarla

bir parça simit gagalamak uğruna

düşülürdü her gün yola

güverteye konulurdu 

bitince serseri kovalamaca

yalınız bizim için dönüyor sanırdık dünya

varıncaya kadar onsekizbin alemin farkına.', 'yalınız bizim için dönüyor sanırdık dünya güneş bizim için doğuyor horoz bizim için ötüyor  gökkuşağı bize salıncak kuruyor bir bizi ıslatıy...', ARRAY['Türk Edebiyatı','Şiir','Mehmed Arif']::text[], 8.5, '{"poet":"Mehmed Arif","poet_slug":"mehmed-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yaliniz-bizim-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Aşk Yürüyüşü II', 'buyuk-ask-yuruyusu-ii-umut-ulbegi-oq68u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni o sonbahar günü

son kez öptüğümde

uçağa gidişini

gözlerimdeki yaşlar izlemişti

ve geçen günler

yüreğime karaları işlemişti

Son değildi

Kabullenilmemişti

Kasım geldiğinde

hayallerim geri döndü

kırmızı tül perdelerin ardında

sana sarıldığımda saatler durdu

saatlerin ülkesinde

o akşam

o sessiz akşam

sadece gözler konuştu.

Seni öperken

dudaklarına akan gözyaşları

özlemimin ateşiyle kurudu

çatlamış dudaklarımızda yeşeren orkide

düşlediğimiz o evde

sen ve ben

Biz

Cenevre''de gün bizim için doğdu

Fransızca yaşanan şehirde 

Türkçe seviştik

kendimizdik

bitmemiştik

aksine tutkuyu biriktirmişti ayrılık

Big Bang

Ayrılamadık gecelerce

Kilometrelerce yürüdük

Büyük Aşk Yürüyüşü

L''amartine''den Mont Blanc''a

Cornavin''den Servette''e

Kilometrelerin aşkla küçülüşü

Her gece tadına vardık şehrimizin

Binbir gece şarapları gibi

Mövenpick dondurması gibi

Teninin tuzu gibi

bizim olan her şey gibi.

Gitmek zorundaydım

İstanbul''da

Bekleyenim yoktu

Tek aşkım

istediğim

özlediğim 

sendin

Ama kahretsin 

gitmek zorundaydım

Gözlerinden koparken

dudaklarını bir daha bir daha öperken

her fotoğrafta seni sonsuzlaştırırken

ve dünyanın durmasını beklerken

Aklımda tek kelime yankılanıyordu

''Döneceğim''', 'Seni o sonbahar günü son kez öptüğümde uçağa gidişini gözlerimdeki yaşlar izlemişti ve geçen günler yüreğime karaları işlemişti Son değildi ...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/buyuk-ask-yuruyusu-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adın mutluluk olsun', 'adin-mutluluk-olsun-sinan-aydindag-ry8b7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Al bu eşkiya yürek senin olsun                                       09/02/2004

