INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünüp Uyuyamıyorum', 'seni-dusunup-uyuyamiyorum-tuncer-ozyavuz-zdk2t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu gece ben,

Gecekondu semtlerinde oturan

O bahtsız çocukların

Arife gecesi başuçlarında

Özenle katlanmış duran

Bayramlıklarını düşünü

uyuyamadıkları gibi...

seni düşünüp

uyuyamıyorum.', 'Bu gece ben, Gecekondu semtlerinde oturan O bahtsız çocukların Arife gecesi başuçlarında Özenle katlanmış duran Bayramlıklarını düşünü uyuya...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Özyavuz']::text[], 8.5, '{"poet":"Tuncer Özyavuz","poet_slug":"tuncer-ozyavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-dusunup-uyuyamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-i-brahim-duskun-m4b8e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'her yani sarmisken yoklugun korkusu

umut; bir beliren gemi,ufuklarinda denizin

yasam tutkusu buyur kocaman olur

tanimsiz bir durusa direnis gibi.

firtinalar,amansiz dalgalar,kararan bir dunya

umutsuzluktur gelen yasam tutkumuzu koparan

oyle cekilmez bir sey olursa yasanan

yeniden yarat umudu ufukta beliren gemiler gibi.', 'her yani sarmisken yoklugun korkusu umut; bir beliren gemi,ufuklarinda denizin yasam tutkusu buyur kocaman olur tanimsiz bir durusa direnis ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Düşkün']::text[], 8.5, '{"poet":"İbrahim Düşkün","poet_slug":"i-brahim-duskun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umut-149-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınım', 'kadinim-bilsay-yildirim-s6hlu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gece çok zor seni sevdiğimi söylemem

çok zor saçlarını okşayıp, ellerini tutmam

seni sevmem zor bu gece,üzgünüm kadınım.

Bu gece her odada sen varsın,

Hangi karanlığa otursam sen varsın

Sesin var hala kulaklarımda,

Gülüşün duyuluyor boş duvarlardan.

Ellerin var,sıcacık

Kokun var eşyalarda,

Her adımda sen varsın,

Her karanlık odada biz varız.

Bu gece yalnız sen varsın bu evde benimle.

Anılar var kadınım,

Unutamadığım kimsenin anlayamayacağı,

Kimseye anlatamayacağım.

Bir daha asla unutamaycağım.

Çok zor benim için sevmek biliyorum,

Neden bilmiyorum yenemedim bir türlü yalnızlığımı.

Ta ki sana kadar kadınım.

Ta ki seni sevene kadar.

Bambaşka sana dair herşey,

Seni sevmek, sana sarılmak, her anımda seninle olmak.

Bambaşka kendimi sana tamamen açmak,

Tek istediğim yanımda olman,belki bir ömür boyu.

Aklımdan atamıyorum yaşadıklarımızı,

Bu kadar sevgiye rağmen bu geceyi neden yaşadığımızı anlamıyorum.

Bu aşkın içinde boğulmamızı anlamıyorum.

Kadınım dediğimle neden sarılıp uyuyamadığımı bilmiyorum.

Bir tek sevdiğimi biliyorum, kendimden nefret edecek kadar seni sevdiğimi görüyorum ve bunun karanlığa karıştığını,

Bu aşkın unutulduğunu,

Üzüldüğümüzü görüyorum, 

Deniz kenarındaki hayallerin bittiğini yavaş yavaş, karanlık

Beni korkutan kendimi böylesine açtığım bir sevdanın kıyıda köşede kalması

Günlerin unutulması,

Anıların anlamsızlaşması

Bu sevdaya üzülüyorum, ama açıkcası bilmiyorum kadınım.

Bunları düşünmüyorum ve bu halde olsam da yanımda olmanı istiyorum ama bu gece seni sevemem, bunu biliyorum.

Uzaklaşmam lazım,

Başkası olsa unutmam lazım biliyorum

ama bir değeri olmalı yaşananların.

Bu odalarda yaşananların bir anlamı olmalı.

Bambaşka olmalı o yüzden hala yanındayım kadınım.

ve bizi unutmam gerektiğini anladığım güne kadar yanımda olmanı istiyorum.

Bambaşka görüyorum dünyayı biliyorsun,

Renksiz olsa bile yaşananlar,

İkimizi kattım her saniyeye cnm. 

Mutlu olmaya mecburuz bunu biliyorsun, sen kadınım.

(Şimdi olmasa bile ikimizin de kedi olduğu bir hayatta) elbette.', 'Bu gece çok zor seni sevdiğimi söylemem çok zor saçlarını okşayıp, ellerini tutmam seni sevmem zor bu gece,üzgünüm kadınım. Bu gece her odad...', ARRAY['Türk Edebiyatı','Şiir','Bilsay Yıldırım']::text[], 8.5, '{"poet":"Bilsay Yıldırım","poet_slug":"bilsay-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/kadinim-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Arzuhal...!', 'sevgiliye-arzuhal-ozan-si-ar-agdasan-kya5w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgili Can, Canım, Cananım,

Martıların dama, tilkilerin sahile vurduğu tezatlar dünyasında; Aslanın kediye selam durduğu. Onurun, gururun ve yüreklerin aşındığı; çirkinliklerin güzellik

leri gölgelediği güzel memleketimizde; karanlıkta ejderhaların segirttiği...

Susurluk pisliğinin, susurluk suyunda bile temizlenemediği bir dünü ve bugü

nü yaşıyoruz; yaşayamadığımız memleketimizde, parsellenmiş dünyamızda.

   Pak sevdamızın ve billur aşkımızın, kirlilikler sarmalının gölgesinde kalma

ması için; temiz toplum ve berrak düzene varma yolunda ilerlemek gerek. Çakıl ve çakal taşları döşense de yolumuza; aşabilmek engerekli yolları! Budamalı dalları, kayıkta salları.

Aşta, işte, sevişte paylaşmak gerek....Ki, mangal, çatal yürek ve erek.

İnsan çeşit çeşit, yer damar damardır gülüm. Sevdalar ve aşklar da öyledir. Yar aşkı, dava ve deva aşkı. Kimileri güzelim sevdaları belden aşağı görür

ler, kaybolurlar et yığınlarında debelenerek! 

Heyhat, oysa, asıl sevda ne kadar güzel, güçlü ve onurludur. Uğruna ser veri

len sevdalar. Ferhat Şirin, Leyla Mecnun, Nazımda, sazımda bütünleşen sev

giler. Dönekliğin dönme dolabında başı dönenler, bir gün beyinsiz kafalarını çarparlar dolaba. Gerçeklerin berberi, makası vurmalı ki, dökülsün önümüze saçımız; ak mı, kara mı görelim? ..

Sevgilim, biliyoruz ki, dikensiz gül bahçesine erişmek masallar ülkesindedir. Ancak, dikenlerin acısına katlakmak gerek. Akan kardeş kanını durdurmak. Yağız Mehmetçiğin dolara pazarlanan canı, conilerin petrol çıkarları ve deb

debeli sefahatı uğruna, ne peşkeşler çekildi. 

Baykuşlar tünemesin, kargalar ötmesin hanemizde. Turnalar mavi gökyüzün

de katar katar uçuşur, halaya kalkar, samaha dururlar; kardeşlik, sevgi, ba

rış ve paylaşmak adına yaşamı. Şakırlar ozan ŞAH TURNA lar misali. Üretken Ana sesi, ''yar- yaran'' sesi timsali. Yılmadan, boyun eğmeden; büyük bedelller ödedik. Sevdalıların özgür yürek atması ve insanlığın esenliği uğruna gülüm. Havada bulup ta, tavada yiyenlerin kirli saltanatlarını yerle bir etmek adına! Bir Can verdim, bin dirildim. Ben öleydim gülüm gene; yeter ki ağlayanlar gülsün, sevgiler ve garipler boynu bükük kalmasınlar! 

Erimiş kurşun gibi bağrımı dağlayan mazlumların acıları, dostluğa ve esenli

ğe varmanın sancıları son nöbetlerini yaşıyorlar.

Başına ölü toprağı geçirilmiş toplumu uyarmak gerek aşta, işte, sevişte. Canım sevgilim, dostluğa ve insani degerlere açılmağanlar, ışığa akmayan

lar; küflenir yosun tutarlar. Çevresine akmağan sular misali.

Sevgi ve lokmayı paylaşım, yürekli sevdalar Şiar''ımız olmalı, umutlu yarınlar adına, hasedin, fesadın ve zalimin, kaypağın inadına! 

Sevgili Canim,Cananım, nakış nakış işlediğim kilim deseni türkülerimin melo

dilerinde, sazımın inleyen tellerinde, yürek ısıtan şiir dizelerimde ve ''İnsanlık bahçesi'' makalelerimde buluşmak üzere; bir daha ki sefere...Hoşça ve dost

ça kal. Umudun solmasın.

Sen, ben, ''biz'', giz ve insan olabilmiş ''hepimiz'' adına. Karanlıkların inadına! ...

Ozan ŞİAR Ağdaşan '' İnadına Sevdamız''  ''GÜLÜM GÜL''  www.siarcan.com

Yorum: Ozan ŞAH TURNA (Aşık ŞAHTURNA)      Toplumsal Kadın Platf.

www.sahturna.com

Almancaya çeviri: ŞAFAK ve ŞİRİN AĞDAŞAN Sanat grubu', 'Sevgili Can, Canım, Cananım, Martıların dama, tilkilerin sahile vurduğu tezatlar dünyasında; Aslanın kediye selam durduğu. Onurun, gururun v...', ARRAY['Türk Edebiyatı','Şiir','Ozan ŞİAR Ağdaşan']::text[], 8.5, '{"poet":"Ozan ŞİAR Ağdaşan","poet_slug":"ozan-si-ar-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sevgiliye-arzuhal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ş i i r '' s e m e', 's-i-i-r-s-e-m-e-burran-saka-fi2bd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şiir ölü iken yazılır, sen! 

şiir kabuğundadır yaranın 

delirir bilinci evriltirken 

aşka saldırır korkudan

cinayet işler durup dururken…

şiir süngüsünde ölü, sen! 

yüzünde kelime imbikler

şiir hırsızdır 

aşkın koma haline güler

şiir arsızdır 

ihanettir ölüme direnmek şiirde 

sabır dil nöbetideyken

hele…

şiir ölü iken yazılır, sen! 

aklı gömer betiğe 

gerçek yalansı’laşır

bilinç çatlağından sızar

şiir ip’tir boynunda ve

boşalır su’dan ilmiğe…

şiir zinadır memede, sen! 

soğurur eylemden hiç’i 

ahlakı reddeder istersen

sevişir 

çoğalır beynin rahminde 

sidik kokar dudakları hecenin

öpmesen…

şiir ölü iken yazılır, sen..! 

Trabzon, 24.11.2004', 'şiir ölü iken yazılır, sen!  şiir kabuğundadır yaranın  delirir bilinci evriltirken  aşka saldırır korkudan cinayet işler durup dururken… şi...', ARRAY['Türk Edebiyatı','Şiir','Bürran Saka']::text[], 8.5, '{"poet":"Bürran Saka","poet_slug":"burran-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/s-i-i-r-s-e-m-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olacak', 'olacak-nil-ozdemir-5g1pq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hapis olmuş

Sen bunu bilirmisin

Bir sevgiye hapis olmak

Müebbede mahkum sayıp

Kalemin kırmak ah

Kahrı olası bu sevgi

Kalbim baş kaldırmış tutsaklığa

Nereden bilirdim ki benim 

Mahkumiyetim senin memnuniyetin

Olacak

Kahretsin yoruldum', 'Hapis olmuş Sen bunu bilirmisin Bir sevgiye hapis olmak Müebbede mahkum sayıp Kalemin kırmak ah Kahrı olası bu sevgi Kalbim baş kaldırmış tu...', ARRAY['Türk Edebiyatı','Şiir','Nil Özdemir']::text[], 8.5, '{"poet":"Nil Özdemir","poet_slug":"nil-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/olacak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davacıyım', 'davaciyim-nil-ozdemir-uo9vg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni yaradana şikayet ettim, 

Senden davacıyım orada torpil yok, 

Haydi bul birini ben suçsuzum de, 

Ben bunun gönlünü, sevgisini, yıllarını, 

çalmadım de! 

Ben davacıyım tanrım,

Hakkımı istiyorum, 

Çok şey aldı benden,

Bedenimden, gecemden, günümden… 

Geri istiyorum dünümden başlatın alacaklarımı, 

Davacıyım gözlerini benden kaçırdı,

Sevgisini esırgeyıp beni bekletti, 

Uykumu bölüp beni ağlattı,

Rüyama girip ümitlendirdi…

Davacıyım tanrım, 

Sevgimi aşkımı hiçe sayıp gülümsedı 

DAVACIYIM, 

Torpıl yok torpılın olmadığı tek yerı buldum 

DAVACIYIM.', 'Seni yaradana şikayet ettim,  Senden davacıyım orada torpil yok,  Haydi bul birini ben suçsuzum de,  Ben bunun gönlünü, sevgisini, yıllarını...', ARRAY['Türk Edebiyatı','Şiir','Nil Özdemir']::text[], 8.5, '{"poet":"Nil Özdemir","poet_slug":"nil-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/davaciyim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağ olsun kalanlar', 'sag-olsun-kalanlar-halil-i-brahim-ozdemir-vrl4m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düğümlenir boğazımda yalanlar

Biter bir gün bağ bozumu, talanlar…

Emaneti  hakkı ile taşırsam

Sağ olsunlar gerilerde kalanlar', 'Düğümlenir boğazımda yalanlar Biter bir gün bağ bozumu, talanlar… Emaneti  hakkı ile taşırsam Sağ olsunlar gerilerde kalanlar...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sag-olsun-kalanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Düşersin Aklıma', 'sen-dusersin-aklima-huseyin-erdogan-gf9fb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'her gün sahil yolundan

gider gelirim işime

Bostancı- Pendik arası 

yaklaşık onbeş kilometre

her bin metrede

tutmak istercesine Adalar''ı

uzatırım ellerimi sabahları

neredeyse 

yakalar gibi olurum Kınalı''yı

tik tak sesleri arasında

balıkçı motorları

geçerler kıyıya yakın

kimileri

avlanır üzerinde sandalın

bazıları da 

sabahın ilk ışıklarında

mekan tutmuşlar kayalıkları

umutla atmışlar oltaları

sen düşersin aklıma

bir zamanlar seninle

az mı saymıştık? 

Maltepe''de

sahile vuran dalgaları

                 26.11.2004', 'her gün sahil yolundan gider gelirim işime Bostancı- Pendik arası  yaklaşık onbeş kilometre her bin metrede tutmak istercesine Adalar''ı uzat...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-dusersin-aklima-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nabızların Sesi', 'nabizlarin-sesi-ekrem-sama-yt97l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nabızları kontrol etmek değil hüner,

Bilebilir misin, kiminki Allah, der? 

(İstanbul:26.11.2004)', 'Nabızları kontrol etmek değil hüner, Bilebilir misin, kiminki Allah, der?  (İstanbul:26.11.2004)...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/nabizlarin-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Gibi, Ben Gibi', 'gonul-gibi-ben-gibi-selami-babacan-vyafh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bazen sıcak bir çay

Buz gibi havada içini ısıtan

Kavurucu çölde bir vaha

İçten içe ferahlatan

Çatlayan dudaklara konan buse gibi

İçimi kaynatan

O güzel kız gibi, sen gibi

Bazen bir bereket

Toprağa sevdalı,

Gönül gibi çağlayan

Yağmur olmuş damla damla

Bedeni okşarcasına sımsıkı saran

Kollar gibi,

Bazen bir sürmeli güzel

Edası gözlerinde saklı

Sanki bir içim  su

Baş döndüren

Bir kadeh şarap gibi

Bazen sıcak bir çay

Buz gibi havada içini ısıtan

Kavurucu çölde bir vaha

İçten içe ferahlatan

Çatlayan dudaklara konan buse gibi

İçimi kaynatan

O güzel kız gibi, sen gibi

Bazen bir bereket

Toprağa sevdalı,

Gönül gibi çağlayan

Yağmur olmuş damla damla

Bedeni okşarcasına sımsıkı saran

Kollar gibi,

Bazen bir sürmeli güzel

Edası gözlerinde saklı

Sanki bir içim  su

Baş döndüren

Bir kadeh şarap gibi

Selami BABACAN', 'Bazen sıcak bir çay Buz gibi havada içini ısıtan Kavurucu çölde bir vaha İçten içe ferahlatan Çatlayan dudaklara konan buse gibi İçimi kayna...', ARRAY['Türk Edebiyatı','Şiir','Selami Babacan']::text[], 8.5, '{"poet":"Selami Babacan","poet_slug":"selami-babacan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gonul-gibi-ben-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldim', 'geldim-selami-babacan-4s2mr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yanaklarında allık olup,

Ela gözlerine dalmaya; 

Kollarını yastık,

Saçlarını yorgan bilip; 

Gözlerinde sevgin,

Dudaklarında meşk olmaya; 

Seni bende beni sende,

Hisssetmeye geldim.

Ateş almaya geldim.

İçimdeki volkanı uyandırıp

Sevgimi sana salmaya geldim.

Kanatlandım uçarcasına

Bülbüldüm coşarcasına

Gülüm dedim, inatla koklamaya

Aldırmadan dikenlerine

Bahcene sevda konağı kurmaya geldim

Hayatımın karanlık dehlizlerinde

Yol gösteren pusulam olmanı

İstemeye geldim.

Yerde değil, gökte değil; 

Benliğimin nadide köşesinde,

Yıldızım olur musun? 

Baharı benle yaşar,

Kokunu kokuma salar mısın? 

Gönlümde bahar çiçeği gibi açar,

Bahar yeli olup bedenimi okşar mısın? 

Demeye geldim.

Baharı sende seni baharda yaşamaya; 

Kokunu kokumda solumaya geldim.

Umutsuzca sevgi denizine dalıp

Umudu umutsuzlukta yaşamaya geldim.

Özelin olup, özeli sende yaşamaya,

Sana özeli bende yaşatmaya,

Özelim olur musun? 

Demeye geldim.', 'Yanaklarında allık olup, Ela gözlerine dalmaya;  Kollarını yastık, Saçlarını yorgan bilip;  Gözlerinde sevgin, Dudaklarında meşk olmaya;  Se...', ARRAY['Türk Edebiyatı','Şiir','Selami Babacan']::text[], 8.5, '{"poet":"Selami Babacan","poet_slug":"selami-babacan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/geldim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kün-Yekün', 'kun-yekun-ekrem-sama-acl1x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Üç beş gerçek mümini de,

Çıkarırlarsa aradan,

Kim kalır, “kün” dediğinde; 

“Yekün” olursa; Yaradan? ..

(İstanbul:26.11.2004)', 'Üç beş gerçek mümini de, Çıkarırlarsa aradan, Kim kalır, “kün” dediğinde;  “Yekün” olursa; Yaradan? .. (İstanbul:26.11.2004)...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kun-yekun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetiş', 'yetis-huseyin-sigirtmac-f3kpk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ateşin yürekte yanardağ oldu.

Büsbütün bedeni sarmadan yetiş.

Hasretin kahrından düzen bozuldu.

Yaşam zincirini kırmadan yetiş.

Daldığım hayalde yol benim değil.

Tutundum gövdene dal benim değil.

Bülbülüm bahçende gül benim değil.

Eşin dostun damga vurmadan yetiş.

Kavuşma arzusu yakar bu teni.

Gönlü hoş olmayan neyler cihanı.

Seni Leyla sanıp geçtim Mecnun’u

Çöllere ben beni sürmeden yetiş.

Sığırtmaç sabırla taş oldu yürek.

Günlerim karardı ışığın gerek.

Dönmeden üstümde kazmayla kürek.

Toprağın bağrına girmeden yetiş.', 'Ateşin yürekte yanardağ oldu. Büsbütün bedeni sarmadan yetiş. Hasretin kahrından düzen bozuldu. Yaşam zincirini kırmadan yetiş. Daldığım hay...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yetis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru: Sen Kimsin?', 'soru-sen-kimsin-tulay-sustam-j5qx5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir adam bana sordu sen kimsin? 

''annemin kızı, babamın oğluyum'' dedim.

ben adama sordum sen kimsin? 

''annemin oğlu, babamın kızıyım'' dedi.

ben etek giymem gerekirken

pantalon giyiyorum...

sen pantalon giymen gerekirken

etek giyiyorsun...

işte aramızda ki fark...

bir daha bana soru sorma 

sana başka soru sormama gerek yok

aynı sorunun altında ezilirsin...', 'bir adam bana sordu sen kimsin?  ''annemin kızı, babamın oğluyum'' dedim. ben adama sordum sen kimsin?  ''annemin oğlu, babamın kızıyım'' dedi. ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/soru-sen-kimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Işığım, Toprağım', 'gun-isigim-topragim-hakki-hakan-kaya-2yqym', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yitirdim 

gün ışığımı,

özlem ateşim 

solmadan

yandı içimde 

büyüttüğüm dağlar,

kimsenin haberi

olmadan

...

nefes alıyor

yine yaşıyorum,

utanıyorum

yaşamaktan

daha yokluğunun

bir kaç günü,

korkuyorum

alışmaktan

...

sarısı bulaşmış

gözyaşlarıma,

sonbahar 

yapraklarının

ıslanan toprağında 

üşüyen,

elleri 

çocuklarının

...

______hasretin 

yüreğime ulaştı

______ellerime

toprak bulaştı...', 'Yitirdim  gün ışığımı, özlem ateşim  solmadan yandı içimde  büyüttüğüm dağlar, kimsenin haberi olmadan ... nefes alıyor yine yaşıyorum, utan...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gun-isigim-topragim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Deli Ve Akıllı Üzerine', 'bir-deli-ve-akilli-uzerine-tulay-sustam-i1b3q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir deli de olsam...

Bir zırdeli için, bir akıllıyı satmam

Çünkü o da benim gibi deli 

akıllı insan çok şey kazandırır adama

bu düşmanım bile olsa...

Filozof « akılsız dostum olacağına, akıllı düşmanım olsun »', 'Bir deli de olsam... Bir zırdeli için, bir akıllıyı satmam Çünkü o da benim gibi deli  akıllı insan çok şey kazandırır adama bu düşmanım bil...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-deli-ve-akilli-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilseydi', 'bilseydi-bayram-tunca-iplkm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilseydi, hiç keser miydi ki o ağacı

Kestiği ağacın içine konmak ne acı

Bir de olursa, o ağaç ondan davacı

İhtimal en ağır cezayı verirdi savcı

Bilseydi, o toprağı hiç kirletir miydi

Kirlettiği toprağa gömülmek ne acı

Eğer olursa o toprak ondan davacı

İhtimal en ağır cezayı verirdi savcı

Acaba bilseydi yine de kirletir miydi

Kirlettiği suya muhtaç olmak ne acı

Eğer orda olursa o su ondan davacı

İhtimal en ağır cezayı verir Yaratıcı

Bilseydi kirletir miydi muhtaç olduğu havayı

Şikayetçi olsaydı, baştan kaybederdi davayı

İyi bilmeliyiz verilen nimetin kadri kıymetini

Yoksa, ağır çekeriz emanete ihanet cezasını

25.11.2004-11.25

Not:

Ekseriye bindiğimiz dalı kesiyoruz farkında değiliz

Muhtaç olduklarımızı yok ediyoruz farkında değiliz

Verilen nimetleri zayi ediyoruz hiç farkında değiliz

Eşref-i mahlukatın sultanı yapıldık farkında değiliz', 'Bilseydi, hiç keser miydi ki o ağacı Kestiği ağacın içine konmak ne acı Bir de olursa, o ağaç ondan davacı İhtimal en ağır cezayı verirdi sa...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bilseydi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabanıl yalnızlaşma önsözü,', 'yabanil-yalnizlasma-onsozu-mutlu-ayar-b9o7n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnızlıklarında imzam olan kadınlar, bilmezler 

bu savruk gecede benim de yalınyürek olduğumu 

kendi denizlerini ve d/eğeri yaşatır yalnızlık 

öğretmendir, kalabalık doğurgan ve yüzsüz 

elindeki anısal çubuğunu vurarak duvarlara 

tak tak tak, yaşanarak hissedilmeyen sıcaklığı 

soğutarak hissettirir insana yalın ayak, ve 

zaman sürekli doğurur o hep geniş yanıyla 

içine sus girmiş odada bir yığın yarım şiir altında 

bir öpücüğü bir sıcaklığı sürdürmek ister insan 

Oysa üçlü koltuğa yerleşerek yalnızlık atar 

bacak bacak üstüne çatlaklardan salyaları a-kar

kuduzdur korkutur oysa asırlarca ateşlerde 

yürümüştür insan hisleri boyunca “yükselmiştir 

alçalmıştır” gözleri yüksekten kamaşan yaralı 

bir kuş gibi susamıştır bir verimli kalabalığa

yalnızlıklarına neden olduğum kadınlar, bilmezler 

yalnız onlardır yalnızlığımın düş-üş silsilesi aslında 

asırlarca kükreyen yanardağların, akla gelmez 

oh ve ah sesi oldukları önceki yaşamlarında 

odanın perdeleri seyirir yastık çukuru tekleşir 

kirli kalkışlarla açarsın gözünü hep aynı noktaya 

küflenmiş yokluklarına dokunursun coşkunun 

giden leylekleri izlersin örseleyen bakışınla… 

yalnızlıklarını imzaladığım kadınlar silemezler 

onları her öpüşümde kendi yitişim onaylanmıştır 

_____________________________aslında! .. 

25 / 26.11.o3 / 03:15', 'Yalnızlıklarında imzam olan kadınlar, bilmezler  bu savruk gecede benim de yalınyürek olduğumu  kendi denizlerini ve d/eğeri yaşatır yalnızl...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yabanil-yalnizlasma-onsozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sarhoşun Sesi', 'bir-sarhosun-sesi-sirma-mersin-d0hdp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rakı meze sofrasında

Geceyi demlerken

Efkara dalmış gözlerle

Dost muhabbetinde sesleri arasında

Seni düşünüp dururum

……………………………………….

……………………………………….

Sigara dumanında

Bi nefes daha çekip yürüyorken

Uzayan kaldırımların içinde 

Karanlığımı dağıtan

Kapına getiren çaykarası gözlerindi,

Aklımı başımdan çalan 

Sevgi dolu seslenişine

Yaslamışım yüreğimi

Anason kokulu dudaklarımla

Öpsem gül dudaklarını

Uyuyup kalsam

Sokak kapısının önünde…

Taaki

Sabahın ayazı yüzümü okşayana dek

04.11.04', 'Rakı meze sofrasında Geceyi demlerken Efkara dalmış gözlerle Dost muhabbetinde sesleri arasında Seni düşünüp dururum ………………………………………. ………………...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-sarhosun-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'M a n i l e r (1 1)', 'm-a-n-i-l-e-r-1-1-abdullah-atay-50efj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'malmış mülkmüş hep fani

aza da ol sen kani

yar uykuda olsa da

söylenecek bu mani...

yar yitirdim ağlarım

dertli dertli  çağlarım...

bir güzelin peşinde 

geçti gençlik çağlarım...

eli kınalı gelin

beli sırmalı gelin

düğünümüz var bizim

gelin a dostlar gelin...

portakal dilim dilim

beklerim seni gülüm

sen yanıma gelince

bal olur ağzım dilim

eğer bir de gelmezsen

lal olur ağzım dilim...

sevdim kaşı karayı

aşkı sarar yarayı

yeter ki yarim olsun

ne yapayım sarayı...

baharımda dalımsın

bedenimde şalımsın

aşkınla verem oldum

niye böyle zalımsın...

sular gibi akarsın

ceylan gibi bakarsın

bu cilve bu naz varken

nice canlar yakarsın...

un eler elek elek

benim yarim bir melek

göz göze diz dizeyken

ayırdı kahpe felek...

hep güllere bakarım

manileri yakarım

güzellerden değil de

çirkinlerden bıkarım...

abdullah atay der ki:

insanları uyutma

haram lokmayı yutma

bu arz’ın üstü varsa

altı da var unutma...', 'malmış mülkmüş hep fani aza da ol sen kani yar uykuda olsa da söylenecek bu mani... yar yitirdim ağlarım dertli dertli  çağlarım... bir güze...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/m-a-n-i-l-e-r-1-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hala mı?', 'hala-mi-yunus-tarim-m1nhv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hala duruyor mu sokağındaki izlerim 

Kapına bıraktığım kırık kalbim 

Pencerene dikili umutsuz gözlerim

Hala umarsızca erkenden uyuyor musun

Kurudu mu yoluna döktüğüm gözyaşı 

Eskisi gibi ezip geçiyor musun

Hala soğuk mu beklediğim köşebaşı

Ve sen hala pencerenden bakmıyor musun', 'Hala duruyor mu sokağındaki izlerim  Kapına bıraktığım kırık kalbim  Pencerene dikili umutsuz gözlerim Hala umarsızca erkenden uyuyor musun ...', ARRAY['Türk Edebiyatı','Şiir','Yunus Tarım']::text[], 8.5, '{"poet":"Yunus Tarım","poet_slug":"yunus-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hala-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görev Aşkı', 'gorev-aski-mehmet-karli-tx0kz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İstemem başka bir aşk ruhumu sarsın

Gerekmez gönlüme başka bir duygu

Çünkü bir aşk var içimde görev aşkıdır

Bir duygu var içimde hizmet duygusu

Yıkamaz Bizi gülleler toplar ve de bombalar

İnancımız karşısında sönüktür bunlar

Emniyettedir kardeşlik, sevgi,saadet

Türk Polisinden her kesime büyük bir davet

Miting varsa tedbirler alınır herbir caddede

Devriye gezer nöbet tutar Polis her gece

Zaman içinde yüzbinler gelir gider merkeze

Polis bu ayrım yapmaz yardım eder herkese

Adın gazetede olmuşsun bak yine manşet

Emniyete dil uzatanları ey Mevlam kahret

Polisim yıkılma dik dur Sen yine sabret

Bak işte taht kurdun üzülme gönüllerdesin.', 'İstemem başka bir aşk ruhumu sarsın Gerekmez gönlüme başka bir duygu Çünkü bir aşk var içimde görev aşkıdır Bir duygu var içimde hizmet duyg...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karlı']::text[], 8.5, '{"poet":"Mehmet Karlı","poet_slug":"mehmet-karli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gorev-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün günlerden Perşembe', 'bugun-gunlerden-persembe-murat-tali-39me0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Göçmen hüzünler ekledim

Takvim yapraklarına

Tek günlerde sen yoksun

Çift günlerde ben

Bugün günlerden Perşembe

Cuma’ya elli dakika var

Babam 

Sabah olmadan önceki günü bitirmezdi

Doğru değil mi? 

Güneş doğmadan 

Gün başlamıyor işte

Annem bir yaş daha eklerdi yaşıma

Şimdi onun hesabıyla

Yolu yarıladım 

“Yaş otuzbeş yolun yarısı”

O da gelmeyen yılları sayardı hep

Hangi yıllar artan oluyor 

Ömrüme bir gün daha ekledim

Elde kalan koskoca bir sıfır

Bugün günlerden Perşembe

Ve şimdi 

	Bir melodi radyoda

	… … …. Gitme gitme gitme kal bu şehirde

günlerden halen Perşembe

bir yanım

suskun

diğer yanım fırtınalarda 

kaçıncı gidişi yaşamak ister aklım

bilemem

ya

ya’sı olmayan kalmaların

hesabı verilmeden 

dönmeli yoldan

yada

Ya’sı olmayan gitmelerin

Hesabı verilmeden 

Çıkmalı yola

	

Mor bir sümbül açar 

Henüz ıslanmamış toprağında vazonun

Yaprakları yok

kızıla çalıyor bedeni 

Kapı açıldı

Şimdi açmak zamanı mıdır? 

Günlerden halen Perşembe

Cuma’ya oniki dakika var 

Duyunca tarihin gün atan sesini

Gelen güne mi sevinmeli

Giden güne mi üzülmeli

En güzeli anı yaşamak derler

AN nerede

Bugün günlerden inadına Perşembe

Saat Cuma’ya sekiz dakika var 

25.11.2004', 'Göçmen hüzünler ekledim Takvim yapraklarına Tek günlerde sen yoksun Çift günlerde ben Bugün günlerden Perşembe Cuma’ya elli dakika var Babam...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/bugun-gunlerden-persembe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-necmiye-sarpkaya-4rpjy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Başı duman duman 

Zirvelerinde sis bulut 

Eteklerin de mor sümbüller 

Nergizler kırçiçekleri 

Evaze etekli dağlar 

Başınız duman duman 

Mavi göklerin bulutları 

Dağlara kurar otağı 

Ceylan gönülleri çeker 

Ahu gözleri alır 

Buram buram sevda kokan 

Çileli dağlar 

Başınız duman duman 

Muştular filizlenir 

Yeryüzüne direk 

Dayanak güvence 

Zirvelerinde karlar fırtınalar 

Vadilerinde şırıl şırıl dereler 

Gürül gürül çaylar ırmaklar 

Başınız duman duman 

Çeker insanı 

Nübüvvet sancılarına 

Kutsal mesajlara 

Şahit olur 

Ser verir 

Sır vermez 

Nurdağında gelir ilk mesaj 

İkra (Oku)  Alemlerin Efendisine 

Ta kabre kadar 

Ta haşr''e kadar 

Taşır sırrı 

Taşır muştuyu 

Başınız bembeyaz bulutlu 

Karları eritir 

Suya hasret vadilere 

Kurumuş gönüllere 

Akar akar 

Çile olarak 

Gözyaşı olarak 

Nübüvvet mağrasında 

Emaneti sırtlayan 

Nebiler Nesbisine 

Yalnızlığın çaresizliğin 

Sığınağı dayanağı 

Kimi zaman Tur 

Kimi Zaman Hıra 

Kimi zaman Sina 

Başınız bembeyaz bulutlu 

Yine mahmur 

Yine sisli 

Yine karlı 

Yine üzgün 

Yine suskun 

Yine durgun 

Geçit vermez 

Aman vermez 

Başınız duman duman 

Çekilen oflar 

Okunan kasideler 

Yankılanır 

Zirveler ısınır 

Ruhlar ısınır 

Gölgeler vurur şehirlere 

Işıltılar vurur nehirlere 

Hicranlar gölgeler 

Nevruzlar renklendirir 

Kekik kokulu düşünceler yeşerir 

Gönül mağarasında filizlenir 

Çiçek çiçek renk renk 

Desen desen 

Dağlar başı duman duman 

Çileli dağlar 

Aman vermez 

Geçit vermez 

Başınız hep duman duman', 'Başı duman duman  Zirvelerinde sis bulut  Eteklerin de mor sümbüller  Nergizler kırçiçekleri  Evaze etekli dağlar  Başınız duman duman  Mavi...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/daglar-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam', 'anam-kazim-tinaz-jigsy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Otuza varmadan ölünce babam

Dert üst üste geldi sarıldın anam

Demedin ki birgün nasıl dayanam

Gönlümün sultanı baştacı anam

Ne bir puldu kalan, ne de bir saban

Üç yetim mirastı ölen babamdan

Gözü yaşlı koyma sen de ardından

Gönlümün sultanı baştacı anam

Helali ayırdın, kaçtın haramdan

Hep kolladın bizi acı lokmadan

Bulmaz mı cenneti giden ardından

Gönlümün sultanı baştacı anam', 'Otuza varmadan ölünce babam Dert üst üste geldi sarıldın anam Demedin ki birgün nasıl dayanam Gönlümün sultanı baştacı anam Ne bir puldu kal...', ARRAY['Türk Edebiyatı','Şiir','Kazım Tınaz']::text[], 8.5, '{"poet":"Kazım Tınaz","poet_slug":"kazim-tinaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anam-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misket', 'misket-esma-ozdemir-na0ud', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sana 

dibi delikli dünya, dediler

yüzü güleç, içi kalbur… faniler

yalanlar atfettiler doğruluk üstüne

ve

bir ömür büyüttüler biçare gözlerinde…

bilemediler oysa

sırçadan  bir misket olduğunu

kısa pantolonlu bir çocuğun

rengârenk

oyun düşlerinde…', 'sana  dibi delikli dünya, dediler yüzü güleç, içi kalbur… faniler yalanlar atfettiler doğruluk üstüne ve bir ömür büyüttüler biçare gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/misket-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sor beni Leyla', 'sor-beni-leyla-osman-guzelgoz-7bs4s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sor beni Leyla

Pencereni tıklatan garip serçeye

Avuçlarının ayasına

Benliğinin mayasına sor

Yürü yüreğinin sıcaklığında

Beni vazgeçilmez sevdalara sor

Sor beni gözbebeklerine

Kuşlara çiçeklere

Uzat ellerini gökyüzüme

Sor beni Leyla

Güneşi arayan yıldızlara ay dedeye

Bırakma beni karanlıklara

Yürü yüreğinin sıcaklığında

Sor beni aydınlık şafaklara

Sor beni kuşlara

Çiçeklere böceklere 

Dallara yapraklara

Beni okşayamadığım ipek saçlarına değil

Sor beni şakaklarımdaki aklara

Yürü yüreğinin sıcaklığında

Beni hüzünlere gurbetlere sor

Sor beni çiçeklere böceklere

Dallara yapraklara

Yürü yüreğinin sıcaklığında

Sor beni aydınlık şafaklara

Sor beni Leyla...

Osman Güzegöz', 'Sor beni Leyla Pencereni tıklatan garip serçeye Avuçlarının ayasına Benliğinin mayasına sor Yürü yüreğinin sıcaklığında Beni vazgeçilmez sev...', ARRAY['Türk Edebiyatı','Şiir','Osman Güzelgöz']::text[], 8.5, '{"poet":"Osman Güzelgöz","poet_slug":"osman-guzelgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sor-beni-leyla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ölüm Doğuruyor Zamân', 'bir-olum-doguruyor-zam-n-semih-yucel-yuceturk-weq0x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '______________________________________ >>Fellûce''nin azîz şehitlerine', '______________________________________ >>Fellûce''nin azîz şehitlerine...', ARRAY['Türk Edebiyatı','Şiir','Semih Yücel Yücetürk']::text[], 8.5, '{"poet":"Semih Yücel Yücetürk","poet_slug":"semih-yucel-yuceturk","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/bir-olum-doguruyor-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÜÇ Türk Şehidi', 'uc-turk-sehidi-necmiye-sarpkaya-5b2h3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Trablusgarb ve Bingazi işgal edilir 

''Vatan himmet bekler'' 

''Vatan imdadına'' denir 

Çağrılar yinelenir 

Kalbe doğar kurtuluş umutları

Savaşmaya can vermeye

Hakkın çiğnenmesine 

Vatanın işgaline razı gelinmez gidilir 

Feda-i Zabitan Grubu da gider

Cephane yok  mühimmat yok

iman var ser de yürek var 

Umut var ordulara bedel

Kırık dökük arızalı tüfekler

Düşman uçaklarına 

Ağır silahlara donanıma 

Güç kuvvet üstünlüğüne 

Gidilir kırık silahlarla 

Canla başla çölün ortasında 

Kanla etle tırnakla mücadele

Ne yazık ki yakalanırlar 

Fedai Zabitanlar 

Mahkeme günü beklenir 

Meydanlardaki kahramanlık 

Vakara dönüşür cesarete dönüşür 

Aleyhteki şartlara rağmen

Hakim karşısına çıkarılırlar

Çarçabuk başı sonu belli yargılama yapılacaktır

Batılı iki gazeteci  işler değişir  karışır

Mahkeme Başkanı Carlo Torelli birkaç şey sorar

Bir genç bir ihtiyar bir çocuk 

Eller sımsıkı bağlı morarmış parmaklar

Üçünün sırtında borunuz 

Başlarında fes suç sabit

Askerlerimize saldırmışlar 

Hainler zalimler derler 

''Siz üçünüz kimsiniz 

Mükemmel İtalyanca 

Berrak bir ses 

Ben Miralayım Ahmet Alaâddin 

Ordunun hizmetindeyim 

Babam Mehmet Paşa 

Mütekaid Mirliva (Tuğgeral)

Oğlum gönüllü asker 

Mahkeme Heyeti şaşkın 

Karşılarında askerler

Haydutlar beklenirken

Torelli düşünür 

Harp esiri muamelesi yapılmalı 

Belgeniz var mı doğrulayacak

Ahmet Alaaddin Bey 

Bağlı ellerini kaldırır 

İşte tayin emrim 

Her şeye rağmen seyir değişmez 

Hüküm verilmiş son belli baştan

26 Ekimde askerlerimize 

Vurdunuz arkadan 

Vurmadık hucüm ettik

Karar verilir  hemen götürülürler 

Silah sesleri duyulur 

Gerçekleştirilmiştir korkunç infaz

Gazeteciler ayağa kalkarlar 

Şapkalarını çıkarır askerleri selamlar

Bakmadan mahkeme heyetine

Eşiğe tükürür döner giderler

(Batının Kendilerinden olmayana 

uyguladıkları adalet işte bu ithaf olunur)', 'Trablusgarb ve Bingazi işgal edilir  ''Vatan himmet bekler''  ''Vatan imdadına'' denir  Çağrılar yinelenir  Kalbe doğar kurtuluş umutları Savaşm...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/uc-turk-sehidi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebişim', 'bebisim-osman-guzelgoz-5bkfe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'mor menevşem

gün batımım

aydınlık gecem

bebişim

seni görmüş

seni bilmiş

seni sevmişim

bebişim

yüreğimdeki yangın

gönlümün gül bahçesi

sessizliğimin sesi

seni içmiş

sana kanmış

seni bilmişim

bebişim

seni onca sene beklemişim

mor menevşem

aydınlık gecem

gün doğumum

bebişim...', 'mor menevşem gün batımım aydınlık gecem bebişim seni görmüş seni bilmiş seni sevmişim bebişim yüreğimdeki yangın gönlümün gül bahçesi sessiz...', ARRAY['Türk Edebiyatı','Şiir','Osman Güzelgöz']::text[], 8.5, '{"poet":"Osman Güzelgöz","poet_slug":"osman-guzelgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bebisim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adam Alp', 'bir-adam-alp-duygu-adami-murat-i-nce-xq3f2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tesadüfen tanımıştım,

Ana yok, baba yok...

Sırtta, bir mintan yok...

Üç abi var, ikisi kendi halinde,

Biri idamlık, fayda yok...

“Hiç ağlamadım, abi” diyordu,

Babamın öldüğünü saymazsak...

Hiç dostum olmadı, 

Can diye sarıldıklarım,

Olmadık bir günde, sokağa attı..” diyordu...

İstanbul macerası, 

Hayatının en büyük karası...

İçinde sindiremediği,

Çıkış bulamadığı bir kara...

Gece parklarda solan bir gençlik,

Çöp bidonlarından, kursağa düşen bir lokma

...Ve hiç ısınmayan bir beden...

“Okumak istiyordum abi,

Kalem tutmak,

Robenson’u tanımak...

Kendi içimde bir ada yaratmak abi...

Olmadı, ortaokul ikinci sınıftan 

Sokaklara atıldık abi... diyordu...”

Tesadüfen tanımıştım,

Ana yok, baba yok...

Sırtta, bir mintan yok,

Üç abi var, ikisi kendi halinde

Biri idamlık, fayda yok...

Bir keresinde,” Hiç ağlamam” diyordu,

Ve ekliyordu,” Yemin ettim abi,

Babam öldüğünden beri ağlamadım,

Ben ağlamam abi...” diyordu...

Kendi halimce; 

Yeni bir şiirimi sesletiyordum,

Ay ışığı vurmuş caddeler,

Saçak altı ıslak sokaklar,

Yara kaldı, dert kaldı bize,

Ve tokat ağlatan acı sözler kaldı…

BİR DE AHLAR, BİR DE TÜHLER KALDI BİZE…

...ve Alp, solan bir kare, çağlayan bir nehirdi artık,

Yara daha sıcaktı, hiç soğumamıştı, besbelli...

İçimden bir türkü tutturmuştum,

“Hasta düştüm yatakta,

 Aman doktor bir bak da,

Ölür mü kalır mıyım,

Sabaha çıkar mıyım...”

.....................................

Türkü Alp gibi ve ben türkü gibiydim...

İstanbul gençliği heşlemişti,

En güzel hisleri, yılları..........

Dur durak bilmeden geçen zaman,

Memlekete, Çorum’un Alaca’sına atmıştı Alp’i...

Sanki Ömer Danış’ın; 

“BENİ KÖYÜMÜN YAĞMURLARINDA YIKASINLAR”

Şarkısı gerçek oluyordu,

Ömür denen nakarat,

Alaca’da, gelincik tarlalarında soluyordu...

Orda, burda, geçen bir zamandı ALP,

Bir gençlik tükenişi

...Ve zaman, ömrün kalleş bekçisi...

Yanık ezgilerin her notasında ALP,

Yüreğinde buram buram türküler,

Olmadık bir yerde, kopan şiirler

...ve kaybedilmiş, bir hayatın kahramanı ALP...

Ömrün çıkmazını, Rus ruletinin en orta yerine koyan adam,

İki sözcükle dağılan, yıkılan, taş insan,

Her yer nasırlar içinde, yürek pamuktan bir yastık,

Kendi kuzguni zamanını, bir taraflarda unutan,

Sana kol kanat germeye çalışan,

Bir ADAM...

Yirmi beşte, yetmiş beş gibi,

Ömrün bir anını, üç kez yaşamış gibi,

Devrilen zamana gülebilen,

Yüzünde, her anın izini taşıyan bir ADAM...

Ezile büzüle anlatırdı, 

“Hiç sevmedim, daha doğrusu sevemedim abi,

Sevdalanmak, aşk, nasıl bir şey? ..

Bir kız, bir kadın...Anlatır mısın abi” derdi…

Derdi de, içime bir sızı düşerdi... sormayın...

Kendine aşkı yasak etmiş,

“Neyime sevmek, neyime aşk abi”

Hep solan sözcükler dökülürdü yüreğinden...

“Kareler hep siyah beyaz,

Renkli bir sayfa yok abi...”

Yeşile çalmazdı bir türlü, hazan yüreği...

“Yeniden başlamak çok zor, zor abi,

Düşürdüm yüreğimi taşlara,

Ne kadar toplarsan topla,

Hayat, yeniden yazılmıyor abi”...

Geçer elbet, adamsın sen, İNSANSIN...

Unutursun dünü, yarınlar güzel ve sen...

“Yok abi, biz sırtımıza dostluğun hırkasını giymişiz

Ne kadar sökük varsa, dikip dikip giyiyoruz, hepsi o kadar

Ve ne kadar yamalıklı olsa da, temizdir abi...”

“Ömrün asıl tehlike çanları, ablamla başlamıştı,

Ardına anam ve yetmiyor gibi babam,

Keşke bacım, ablam o kalsaydı bari,

Merhaba diyebileceğim, 

Sen gibi bir mektup yazabileceğim,

Bacım, sağ kalsaydı,

Hayatın olmadık bir yerinde, yüreğine yenileceğini,

Anamdan, babamdan önce, terk edip gideceğini,

Solup, toprağa düşeceğini, hiç kestiremedim,

Bir anaydı o, kayıp kimliğimde,

Saçımı okşayan, kol kanat geren, bir melek,

Ne bileyim abi, hiç değilse o sağ kalsaydı,

Olmadı olmadı işte, kara toprağa yirmi sekizinde verdik,

İki kız, bir erkek, geride ben gibi yiten birkaç yürek,

...Ve ömrün, bir başka hazan yanı, bacı kaybetmek...”

“Bilirsin abi, ben cilalı sözler pek söyleyemem

Hiç kız arkadaşım olmadı benim,

Gönlümce geçirdiklerim, benim kitabımda  yazmadı,

Salıverdim yüreğimin kapısından son varım, kıvılcımları

Şimdi her yer küle döndü...”

“Peki abi, ben hiç şiir yazamayacak,

Ya da ne bileyim, bir kıza sevdalanmayacak,

Bir iki tatlı söz, söyleyemeyecek miyim? 

Peki abi, bana bir şiir yazar mısın? ..

İçinde kanamayan bir ağıt,

İçinde yanmayan,

Kaybedilmemiş bir hayatın, en sevimli yüzü, ben olan, 

Bir sevda şiiri yazar mısın? ..

Ya da sevda, sevdalanmak, nedir abi? ..

Gecenin esrarında, gökyüzüne asılı kandillerin altında, buz keserken,

Sıcak bir battaniyeye, kurduğum düşler kadar güzel mi? .. 

Sıkılmazsan bir daha anlatır mısın...abi...can abi...” 

O kadar çok sorusu vardı ki hayata dair,

O kadar çok yarası vardı ki bugüne dair,

O kadar çok yaşanmamışlığı vardı ki düne dair

...Ve o kadar çok hasreti vardı ki, her şeye dair

...Ve ne anlatsam, hepsi o kadar çok havada kalırdı ki...

Düne bugüne ve yarına dair... 

Dilimi dişlerimin arasına aldım

...Ve sıktım, ve ısırdım, kan tükürünceye kadar...

Haklısın, bir şiir nasıl yazılır? .. Nasıl sesletilir? ...

Ya da sevda, aşk, nedir? .. Bende bilmiyorum...

Durdum, sustum, kaldım işte öylece,

Belki de soğuk bir gecede, ayın esrarında,

Buz keserken, iliklere işlerken ayaz,

Belki de bir battaniye, her aşka, her sevdaya

Belki de, bütün yaşanmışlıklara bedel,

Sıcak, yumuşak, insanın içini ısıtan, başka bir sevdadır...

Alp, sokakların çocuğu, yalnızların kimliği,

Alp, yalnız bir adam, adamlığa susayan,

Alp, geçmişin yeni öznesi, sokak çocuğu

...Ve Alp, ADAM GİBİ ADAM...

Tesadüfen tanımıştım,

Ana yok, baba yok...

Sırtta bir mintan yok...

Üç abi var, ikisi kendi halinde,

Biri idamlık, fayda yok...', 'Tesadüfen tanımıştım, Ana yok, baba yok... Sırtta, bir mintan yok... Üç abi var, ikisi kendi halinde, Biri idamlık, fayda yok... “Hiç ağlama...', ARRAY['Türk Edebiyatı','Şiir','Duygu Adamı Murat İnce']::text[], 8.5, '{"poet":"Duygu Adamı Murat İnce","poet_slug":"duygu-adami-murat-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":151,"source_url":"https://www.antoloji.com/bir-adam-alp-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecelerden Al Beni', 'gecelerden-al-beni-osman-guzelgoz-tj90s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'al beni gecelerden gelinciğim

at aydınlık şafakların koynuna

söyle adımı yüreğinin derinliklerine

yankılansın yüreğim sıcaklığında

al beni yorgun akşamlardan meleğim

bırakma karanlık gecelerde yalnız   -

yalnız değilim seninle biliyorum

seninle bembeyaz tebessümlere yürüyorum

korkmuyorum ağrılardan artık korkmuyorum

sevginle donattım yüreğimi varlığınla

yeryüzüne gökyüzüne güneşimle gülüyorum...', 'al beni gecelerden gelinciğim at aydınlık şafakların koynuna söyle adımı yüreğinin derinliklerine yankılansın yüreğim sıcaklığında al beni y...', ARRAY['Türk Edebiyatı','Şiir','Osman Güzelgöz']::text[], 8.5, '{"poet":"Osman Güzelgöz","poet_slug":"osman-guzelgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gecelerden-al-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama', 'aglama-birhan-suner-blk7u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şayet bir gece uyanırsan

Karabasan gibi bir rüyadan ansızın,

Sakın ağlama.

Ve bil ki bu güzel dünyada artık yalnızsın.

Ya da bir sabah uyanıp

Görürsen semayı karanlık,

Sakın ağlama.

Ve bil ki ben yok um artık.

Sanma ben de ağladım

Burada bırakıp seni,

Bir başka yere giderken.

Bilmelisin çok mu çok mutluyum,

Seni hasretinle severek giderken.

Sonraları da beni anarken,

Gülümse ama ağlama sakın,

De ki kendine, severdi o beni,

Gülerken......

Ağ 74', 'Şayet bir gece uyanırsan Karabasan gibi bir rüyadan ansızın, Sakın ağlama. Ve bil ki bu güzel dünyada artık yalnızsın. Ya da bir sabah uyanı...', ARRAY['Türk Edebiyatı','Şiir','Birhan Suner']::text[], 8.5, '{"poet":"Birhan Suner","poet_slug":"birhan-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aglama-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle git', 'oyle-git-osman-guzelgoz-c8v0a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir rüzgâr misali geçerken uğra 

perişan halimi gör de öyle git 

bahar ol çiçekler açarken uğra 

gönlümden hüzünler der de öyle git

kirpiğin okuyla yarala beni 

bin parçaya bölüp parala beni 

açıp yüreğimi arala beni 

gizli sırlanma er de öyle git

gözlerimle doldur güzel gözünü 

tebessümle donat melek yüzünü 

söyle yüreğinle aşkın sözünü 

ruhuma sevdalar ör de öyle git

bir bahar gününde güller ile gel 

sevdalanıp coşmuş seller ile gel 

sevgiler donanmış eller ile gel 

ellerini bana ver de öyle git

şenlendir ruhumun harabesini 

dinle benliğimin inlemesini 

duyur sevgilerle güzel sesini 

yoluma umutlar serde öyle git...', 'bir rüzgâr misali geçerken uğra  perişan halimi gör de öyle git  bahar ol çiçekler açarken uğra  gönlümden hüzünler der de öyle git kirpiğin...', ARRAY['Türk Edebiyatı','Şiir','Osman Güzelgöz']::text[], 8.5, '{"poet":"Osman Güzelgöz","poet_slug":"osman-guzelgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oyle-git-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin', 'gittin-olgun-ekinci-obhju', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gittin

Ve ben bittim

Gittin

Ve ben tükendim

Gittin

Dinlemeden 

Dinlemek istemeden

Geçmişimle yargılandım

İnfaz edildim

Gittin

Ve ben bittim

Geleceğim

Sensiz olmayacak bu sokaklar

Bizsiz kalmayacak sokaklar

Döneceğim

Cezam, hükmüm bitince

Ter temiz,akpak döneceğim

Çünkü ben seni

Hiç terketmedim ki

Sen benden hiç gitmedin ki...

 26.11.2004

saat:12,00', 'Gittin Ve ben bittim Gittin Ve ben tükendim Gittin Dinlemeden  Dinlemek istemeden Geçmişimle yargılandım İnfaz edildim Gittin Ve ben bittim ...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gittin-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peyman...', 'peyman-filiz-turan-io93r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her mevsim ayrı güzellikte

Süslenip püslenip çıkma karşıma Dünya 

Her bahar dal dal çiçekler açsan da

Yeşillenip allanıp pullansan da

Her kış bembeyaz gelinliğinle 

Güzelliğine güzellik katsan da

Hiç boşuna uğraşma 

Ben peyman ettim arş-ı semada

Gönül en sevgiliyi bulmuş bir kere

Aldanır mı? dersin senin güzelliğine

O kor ateş düşmüş gönüle

Başka güzel görünür mü hiç gözüne

İstediğin kadar çiçeklerini tak takıştır

Yeşillenip allan pullan

Saç güzel kokularını etrafa

Senin tüm güzelliğinde

Gönül sevdiğini görür bunu bilesin

Çiçeklerinde O''nun kokusu sarar ruhumu

Düşen her damla yağmurunda

O''nun rahmeti sarar tüm benliğimi

Bulutların O''nun sevdasını anlatır bana

Rüzgarların O''nun adını fısıldar kulağıma

Dağında taşında toprağında

O’ nun imzası var her bir yanında

Sen güzelliğini senin mi sanırsın

O’ nu bulan gönüller seni ne etsin

Ah! Yalanı çok fani Dünya! 

Bilirim güzelliğine karşı koymak zordur 

Nicelerinin kanına girdin

Güzelliğinle gözlerini gönüllerini körelttin 

Nefisleriyle iş birliği yapıp 

Peyman şikan ettirdin

Ne mutlu O’nu bulan O’na yanan gönüllere

O aşkı tadan yanar mı hiç başka aşkla

Gözümüz gönlümüz çok uzak diyarlarda

Özlemimiz O büyük sevdaya vuslata

Gönül sevgilinin güzelliği ile olmuş ağma

Ne etsin dünya seni

Git işine benimle uğraşma 

Ne güzelliğini görecek halim var

Ne aşkına yanacak yüreğim

Tüm benliğimle ben en sevgiliye peyman ettim

İstediğin  kadar caziben olsun

Cilveler yap naz et karşımda

Raks et etrafımda kanıma girmeye çabala

Hiç boşa uğraşma

Yüreğimde bu sevda var iken

Beni de katamayacaksın

Peyman şikan edenler kervanına…

İnşallah son nefesimi verene dek

Gözüm gönlüm yüreğim

Bir O''na yanacak bir O''nun adını anacak

Ve bir gün elbet vuslata koşacak..

Kimseler alınmasın

Benim en sevgiliye verilmiş

Arş-ı semada peymanım var..

26 kasım 2004

                                          peyman: And içmek, yemin etmek

                   peyman şikan (şiken) :And bozmak, yemin bozmak', 'Her mevsim ayrı güzellikte Süslenip püslenip çıkma karşıma Dünya  Her bahar dal dal çiçekler açsan da Yeşillenip allanıp pullansan da Her kı...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/peyman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye Gidiyorsun', 'nereye-gidiyorsun-osman-guzelgoz-t2mwv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'henüz alışmıştım ışığa

nereye gidiyorsun

varlığın yağmuru olmuştu

gömgök kuraklığımın       

nereye gidiyorsun

sen gökyüzümde gökçekken

sen gönül bahçemde çiçekken

nereye gidiyorsun

sen şebnemken nilüferken

sen her şeyken

nereye gidiyorsun...', 'henüz alışmıştım ışığa nereye gidiyorsun varlığın yağmuru olmuştu gömgök kuraklığımın        nereye gidiyorsun sen gökyüzümde gökçekken sen ...', ARRAY['Türk Edebiyatı','Şiir','Osman Güzelgöz']::text[], 8.5, '{"poet":"Osman Güzelgöz","poet_slug":"osman-guzelgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/nereye-gidiyorsun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle bir gidişin vardı ki..', 'oyle-bir-gidisin-vardi-ki-osman-kilic-63xdj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle bir gidişin vardı ki

Kararmıştı elbisen

Cenaze uğurlar gibi

Kararmıştı gökyüzü

Bulutlar benden önce hissetmişti söyleyeceklerini

Ve dahi söyleyemeyeceklerini

........Bulutlar hissetmişti

Öyle bir gidişin vardı ki

Bakışın fırtınalar koparıyordu

Yerdeki yapraklar havalanıyordu

Yıllardır bu akına hazırlanmış süvariler gibi

Başıboş uçuşan yaprakları gemleyip

Hışımla üzerime sürüyordu söylediklerin

Karışıyordu herşey birbirine

Ben seni anlamıyordum,

Rüzgar beni dinlemiyordu...

Öyle bir gidişin vardı ki

Yağmurlar yağıyordu üzerimize

Fırtınalar kopuyordu yüreklerimizde

İzmir yıkılıyordu,

Biz yokoluyorduk

Öylebir gidişin vardı ki

Kalbim beni terketmiş,

Seninle gidiyordu.....', 'Öyle bir gidişin vardı ki Kararmıştı elbisen Cenaze uğurlar gibi Kararmıştı gökyüzü Bulutlar benden önce hissetmişti söyleyeceklerini Ve dah...', ARRAY['Türk Edebiyatı','Şiir','Osman Kılıç']::text[], 8.5, '{"poet":"Osman Kılıç","poet_slug":"osman-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/oyle-bir-gidisin-vardi-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nostalji', 'nostalji-osman-guzelgoz-8xnm5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gözyaşlarını sularken

sinemin toprağını

gönlümde gül bitirirdim ben

mor akşamlarım olurdu

bembeyaz gecelerim

rüyalarım

sevdalarımın meydan

savaşlarıydı yüreğimdeki sevgiyi

orda yitirirdim ben

sinemin toprağında

kırağısı göz yaşlarım olan

güller bitirirdim ben

ya sen...', 'gözyaşlarını sularken sinemin toprağını gönlümde gül bitirirdim ben mor akşamlarım olurdu bembeyaz gecelerim rüyalarım sevdalarımın meydan s...', ARRAY['Türk Edebiyatı','Şiir','Osman Güzelgöz']::text[], 8.5, '{"poet":"Osman Güzelgöz","poet_slug":"osman-guzelgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nostalji-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuyor', 'olmuyor-osman-guzelgoz-2zzh1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni görmeden olmuyor 

dokunmadan

 koklamadan 

öpmeden olmuyor işte 

sen olmadan olmuyor 

gözlerimi içmezsen 

kapımı sen açmazsan tebessümler saçmazsan olmuyor bitanem olmuyor 

seni görmeden olmuyor 

ellerini tutmadan 

gözlerine bakmadan 

saçına gül takmadan olmuyor sen olmasan olmuyor 

olmuyor küçüğüm...', 'seni görmeden olmuyor  dokunmadan  koklamadan  öpmeden olmuyor işte  sen olmadan olmuyor  gözlerimi içmezsen  kapımı sen açmazsan tebessümle...', ARRAY['Türk Edebiyatı','Şiir','Osman Güzelgöz']::text[], 8.5, '{"poet":"Osman Güzelgöz","poet_slug":"osman-guzelgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olmuyor-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayip', 'kayip-nurten-kederoglu-vxfbp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kayip

Geceleri zincire vurdum 

Gündüzler kayip 

Yüregimi sevda yoluna koydum

Kavgada var kayip

Kirik pilagim calar hep ayni sarkiyi 

Beste bozuk siir eksik nakarat kayip

Lale siyah gülün boynu bükük karanfil kayip 

Gözler bakiyor agizlar acik 

Renkler karisik ses ise kayip 

Ömür bitmis azrail kapida ruh kayip

siir_ce / Nurten Kederoglu', 'Kayip Geceleri zincire vurdum  Gündüzler kayip  Yüregimi sevda yoluna koydum Kavgada var kayip Kirik pilagim calar hep ayni sarkiyi  Beste b...', ARRAY['Türk Edebiyatı','Şiir','Nurten Kederoğlu']::text[], 8.5, '{"poet":"Nurten Kederoğlu","poet_slug":"nurten-kederoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kayip-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
