INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deyişler (1)', 'deyisler-1-murat-nail-guney-34zh7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Esti şu bağrıma hasret rüzgarı,

Vurur yerden yere toz eyler beni.

Kökümden söktü de ey zalim felek,

Dere kenarında saz eyler beni...

Kapandı yürekte eski yaralar,

Bir kalem kaşlıya göz eyler beni.

Susmuşken içimde isyanın sesi,

Gönül yaralayan söz eyler beni...

Aşk ile pişmeden, yanıp tutuşup,

Söndürür ateşim, köz eyler beni.

Ağır gitmez deyip, sevda kervanı,

Kırbacı sırtımda, tez eyler beni...

Yorulup koşmaktan uykuya dalsam,

Kış ayaz, boranda, yaz eyler beni.

Nice efendiler kıskandırırken,

Usul, erkan bilmez yoz eyler beni...

Murat, her güzelin methin edersin,

Dünya güzeline, naz eyler beni.

Ak güvercin gibi uçup giderken,

Akıtıp kanımı, boz eyler beni...

       Beste: murat nail güney

          Söz: murat nail güney

     makam: nihavet

02/12/2004  Bodrum.', 'Esti şu bağrıma hasret rüzgarı, Vurur yerden yere toz eyler beni. Kökümden söktü de ey zalim felek, Dere kenarında saz eyler beni... Kapandı...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/deyisler-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bodrum’da Bir Yalnız Martı Yaşıyor (9)', 'bodrum-da-bir-yalniz-marti-yasiyor-9-murat-nail-guney-8ognm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Turnaların kanadına binip de deli sevdam,

Uçup gitti buz mavisi ufuktan uzaklara.

Selam  olsun sıladan mor gölgeli dağlara,

Bodrum’da bir yalnız martı yaşıyor hasretinle...

Bilirsin,vedaları sevmem oldum olası,

Sevgiler yalansa dost,çabuk çıkar foyası,

Tomurcuk güller solarken,bülbüller çeker yası,

Bodrum’da bir yalnız martı yaşıyor hasretinle...

Razıydım ben gönlümü yerlere yıksan,vursan,

Sevdamın küllerini rüzgarlarda savursan,

Uzak yıldızlar gibi semalarımda dursan,

Bodrum’da bir yalnız martı yaşıyor hasretinle...

Tanık oldu ay ışığı,yeminine sevdamın,

Yıldız alacalarında,sen olduğum akşamın,

Her yanını resimlerinle doldurdum odamın,

Bodrum’da bir yalnız martı yaşıyor hasretinle...

Muradım,yürekse yürek,sevdaysa sevda sende,

Gönül dostu isteyenin derdine deva sende,

Can çekilir,yürek soğur,sevgi yaşar evrende,

Bodrum’da bir yalnız martı yaşıyor hasretinle...

01/12/2004  Bodrum.       Murat Nail Güney', 'Turnaların kanadına binip de deli sevdam, Uçup gitti buz mavisi ufuktan uzaklara. Selam  olsun sıladan mor gölgeli dağlara, Bodrum’da bir ya...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bodrum-da-bir-yalniz-marti-yasiyor-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şerefsiz', 'serefsiz-kazim-tinaz-04udw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hani! 

Unutmayacak,

Bensiz olmayacaktın.

Dilinden hiç düşmeyecek,

Kalbinden atmayacaktın.

Hani! 

Bulmuştun dengini,

O aşkı, o sevgini,

Ettiğin o yemini,

Mezara saklayacaktın.

Hani! 

Başka el değmeyecekti ellerine,

Başka yüz değmeyecekti yüzlerine,

Ve, koşup da birilerine,

Şerefsiz olmayacaktın.', 'Hani!  Unutmayacak, Bensiz olmayacaktın. Dilinden hiç düşmeyecek, Kalbinden atmayacaktın. Hani!  Bulmuştun dengini, O aşkı, o sevgini, Ettiğ...', ARRAY['Türk Edebiyatı','Şiir','Kazım Tınaz']::text[], 8.5, '{"poet":"Kazım Tınaz","poet_slug":"kazim-tinaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/serefsiz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmiyor', 'yetmiyor-kazim-tinaz-k4ngs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne kadar dertli çalsa kemancı,

Neşemi bozmaya gücü yetmiyor.

Nereye  baksam  aynı  yabancı,

Hayali karşımdan çekip gitmiyor.

Girmiş yüreğime hayat bulmuşum,

Sanki  mutluluğa  yeni doğmuşum,

Hayal  bile  olsa  aşık  olmuşum,

Yerleşmiş gönlüme  çekip gitmiyor.

O  hayali  bile  mutluluk  bana,

Razıyım onunla  her  türlü sona,

Böyle bir hayalim olduktan sonra,

Cennete  gönlümün  aklı yetmiyor.', 'Ne kadar dertli çalsa kemancı, Neşemi bozmaya gücü yetmiyor. Nereye  baksam  aynı  yabancı, Hayali karşımdan çekip gitmiyor. Girmiş yüreğime...', ARRAY['Türk Edebiyatı','Şiir','Kazım Tınaz']::text[], 8.5, '{"poet":"Kazım Tınaz","poet_slug":"kazim-tinaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yetmiyor-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayaz Yemiş Kavak', 'ayaz-yemis-kavak-zulfikar-yapar-kaleli-ghqu3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gökten yıldızlar döküldü, 

Soğudukça pişiyorum. 

Sel bastırdı, bağ söküldü, 

Gazel döktüm, şaşıyorum. 

Kapağı yok savak gibi, 

Kefen giyer duvak gibi, 

Ayaz yemiş kavak gibi, 

Ağustosta üşüyorum. 

Ne mecliste, ne forumda, 

Ne haberde, ne yorumda, 

Yarı donuk bir durumda, 

Karlı dağı aşıyorum. 

Gün karardı, ışımıyor, 

Tırnak teni kaşımıyor, 

Ayak başı taşımıyor, 

Destek verin düşüyorum. 

Bir fili yutmuş bir pire, 

Ayağı basmıyor yere, 

Her tarafım yara bere, 

Sevda yükü taşıyorum. 

Kasaba, köy, il, büküldü, 

Gölge düştü, yıl büküldü, 

Saç ağardı, bel büküldü, 

İkindiyi yaşıyorum.', 'Gökten yıldızlar döküldü,  Soğudukça pişiyorum.  Sel bastırdı, bağ söküldü,  Gazel döktüm, şaşıyorum.  Kapağı yok savak gibi,  Kefen giyer d...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ayaz-yemis-kavak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Ülkesi', 'yurek-ulkesi-i-brahim-duskun-2ckd7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'karmaşalar,yapmacık duruşlar

öylesine sıradan olunca yaşam

o aşkın dostlukları arar durur insan

üstüne nice düşler kurulu sevgileri

zordur anlatmak

gitmek fikrinde olunca yürek

gidemiyorsa insan

kopamıyorsa

bağlıysa

çakılıysa ayaklar yere

yolcu olur yürek ülkesine

özlenen dünyalar yaratır kendine.', 'karmaşalar,yapmacık duruşlar öylesine sıradan olunca yaşam o aşkın dostlukları arar durur insan üstüne nice düşler kurulu sevgileri zordur a...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Düşkün']::text[], 8.5, '{"poet":"İbrahim Düşkün","poet_slug":"i-brahim-duskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yurek-ulkesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O o', 'o-o-mehmet-isikoglu-2futw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Toplumların sözcüsü

Olayların gözcüsü

Gönüllerde eleman

İnce ayar ölçüsü

Dillendirir renkleri

Ferahlatır kalpleri

Taşır maziyi çağa

Kültür dolu yükleri

Filiz verir eseri

Sevgi saçar feneri

Yüreğinden süzülen

Arattırmaz kevseri

Türkülerin kaynağı

Sevgilerin otağı

Güller biter terinde

Aşk dağıtır yaprağı

Kelimeler eleği

İnci dizer bileği

Dilindeki hüneri

Dışa vurur dileği

Gücün alır ilhamdan

Süt akıtır dumandan

Hayallerle donatır

Üslubları pek candan', 'Toplumların sözcüsü Olayların gözcüsü Gönüllerde eleman İnce ayar ölçüsü Dillendirir renkleri Ferahlatır kalpleri Taşır maziyi çağa Kültür d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/o-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Artık Gönül Sarayıma.', 'gel-artik-gonul-sarayima-ali-osman-yilmaz-cy7w5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalbimde senin için,

Bir saray yaptım,

Taç mahal olmadı belki,

Şah Cihan gibi de,

Ölmedin daha,

Gittiğin uzaklardan dönmeni,

Bekliyorum her gün,

Haydi gel artık,

Gönlümün sarayına.

Anılarımızı kardım bahçede,

Çamurdan kerpiç yaptım,

Güneş çıktığında,

Serdim avluya,

Kuruyan kerpiçlerden,

Duvarlar ördüm,

Üstünü örttüm gökyüzüyle,

Gece olunca salona,

Avize olarak,

Ay dedeyi bağladım,

Yıldızları sıra sıra dizdim,

Tavanlara,duvarlara,

Sahilden martıları,

Bahçeden kuşları çağırdım,

Gül bahçesinden bülbülü,

Topladım bir köşeye,

Hep bir ağızdan söylesinler,

Aşkımızın şarkısını diye.

Bak işte her şey hazır,

Altından değil belki,

Kanımla,göz yaşımla kardığım,

Çamurdan kerpiçlerle,

Yaptığım sarayında,

Aşkımızın şarkısını söyleyen,

Kuşlar orkestrasıyla,

Karşılayacağım seni,

Dön artık uzaklardan,

Yüreğim,bedenim her şeyimle,

Naçizane sarayında,

Seni bekliyorum.', 'Kalbimde senin için, Bir saray yaptım, Taç mahal olmadı belki, Şah Cihan gibi de, Ölmedin daha, Gittiğin uzaklardan dönmeni, Bekliyorum her ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gel-artik-gonul-sarayima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-hifzi-ozbekmez-bg52g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SEVGİ

Anamın kucağında, ninnidir dinlediğim

Nice tarifi vardır, belki de bilmediğim

Okumayı öğreten, kalemi tutturandı

Okul sıralarında, mutluluk tattırandı

Hele gençlik yılları, kanımızı kaynatan

Bizler söylemesek de, derdimizi anlatan

Gönüllerin fatihi, sultanların sultanı

Sevgiliden aldığım, aşkımızın fermanı

Yaşım kırka gelince, tas tarakta toplandı

Ne kadar yok desek de, gönlümüze saplandı

Dostlarıma duyduğum, saygınında adıdır

Dostu sevmek gönülden, sevginin bir tadıdır 

Latifin yüreğinde,çıra gibi yanandır

O ne güzel sevgili, doyulmayan canandır

02  ARALIK  2004 SAAT: 13:00

NOT:Şiir perisi grubunun 2.hafta sevgi konulu aktivitesi için yazılmıştır', 'SEVGİ Anamın kucağında, ninnidir dinlediğim Nice tarifi vardır, belki de bilmediğim Okumayı öğreten, kalemi tutturandı Okul sıralarında, mut...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevgi-152-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Düş gibi**', 'dus-gibi-kubilay-enginol-cucwb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Avuçlarından akıveriyor hava gibi

Ne kadar da sıksan yumruklarını

Bir bardak su sanki

Bakıveriyorsun,oynuyorsun uzatmaları

Film şeridi takılıveriyor gözlerine

Oturup hep onu seyrediyorsun

İmrenerek bakıyorsun gençliğine

Hatalarını görüp,sadece susuyorsun

Ölene değil,kendi sonuna ağlıyorsun

Yürekten namazını kılarak

Herkes gibi seninde sonun biliyorsun

Bu düşten birgün uyanılacak', 'Avuçlarından akıveriyor hava gibi Ne kadar da sıksan yumruklarını Bir bardak su sanki Bakıveriyorsun,oynuyorsun uzatmaları Film şeridi takıl...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dus-gibi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-metin-usengec-ogysv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne oldu ağaç

Yaprakların dökülüyor

Sen de sevdiğinin arkasından gözyaşımı döküyorsun? 

Sen de dökülen her yaprak 

Benim gözümden düşen bir damla yaş

Sende bir mevsim sonbahar

Bende dört mevsim

Yüreğimde sevgimle paylaştık sonbaharı

Karşılıklı sevenlerle yaşa sen ilkbaharı..

1-Aralık-2004  15:40

Ben Sensiz Hep Mutsuzum,Ben Sensiz Kimsesizim,Ben Sensiz Hep Seninleyim..', 'Ne oldu ağaç Yaprakların dökülüyor Sen de sevdiğinin arkasından gözyaşımı döküyorsun?  Sen de dökülen her yaprak  Benim gözümden düşen bir d...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sonbahar-79-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler-2', 'guzel-sozler-2-huseyin-erdogan-n6z3y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Dün gece,senin adını,aşkımı yazdım Akdeniz Sahilleri''ndeki kumlar üzerine, senden habersizce.Fark etmez, esen rüzgarlar kapatsa da üzerini,zaten,dalgalar bile öğrenmiş seni sevdiğimi...''

''Senin için her şeye hazırım hatta ölüme bile varım amma benden sonra hiçbir kimse seni benim kadar sevemez diye korkarım...''

''İnan ki hiç solmayacak bir gonca gülsün sen,dilerim sağlıklı ve mutlu yaşarız birlikte ebediyen...''', '''Dün gece,senin adını,aşkımı yazdım Akdeniz Sahilleri''ndeki kumlar üzerine, senden habersizce.Fark etmez, esen rüzgarlar kapatsa da üzerini,...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/guzel-sozler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimbilir', 'kimbilir-ozkan-sahin-2czy2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kim bilir,

Şu acı anı düne değişemem

Bugünü yaşamak için dünü

Gerek,

Yarın için bugünü sevmem

Olsa bile gelen gün

Mahşer günü.

11/1/1999', 'Kim bilir, Şu acı anı düne değişemem Bugünü yaşamak için dünü Gerek, Yarın için bugünü sevmem Olsa bile gelen gün Mahşer günü. 11/1/1999...', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kimbilir-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkagelsen', 'cikagelsen-serdal-gocmen-czmo4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ah bir kapı çalınsa

Sen olsan acı rüzgâr

Gecede parlasa gözlerin

Şu yalnız kalbime

Bıçak gibi saplansan

Ela gözlerinle gelsen

Gülen yüzlerinle gelsen

Çıkagelsen,

Çıkagelsen

Başını omzuma yaslayıp

"Okşa" desen

Dursa zaman 

Olmasa sabah

Sen olsan gece

Çıkagelsen

Çıkagelsen

Şu nabzımı dinlesen

Mırıldansan o en sevdiğin şarkıyı

Güneş olsan doğsan

Şafağım şafağım olsan.', 'Ah bir kapı çalınsa Sen olsan acı rüzgâr Gecede parlasa gözlerin Şu yalnız kalbime Bıçak gibi saplansan Ela gözlerinle gelsen Gülen yüzlerin...', ARRAY['Türk Edebiyatı','Şiir','Serdal Göçmen']::text[], 8.5, '{"poet":"Serdal Göçmen","poet_slug":"serdal-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cikagelsen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükeniş', 'tukenis-murat-alp-i9mmu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çile yumaklarına hayat ipini,

Dolaya dolaya bitiremedim.

Acı duraklarında bende kendimi,

Kopara kopara bitiremedim.

Benzedim toprağa muhtaç tohuma,

Bir damla su için yana kavrula,

Dönme dolap gibi döne dolana,

Dolana dolana kavuşamadım.

Yaşlarla doldurdum iki gözümü,

Sabırla besledim gönül özümü, 

Şu laf dinlemez garip gönlümü,

Küstüre küstüre avutamadım.', 'Çile yumaklarına hayat ipini, Dolaya dolaya bitiremedim. Acı duraklarında bende kendimi, Kopara kopara bitiremedim. Benzedim toprağa muhtaç ...', ARRAY['Türk Edebiyatı','Şiir','Murat Alp']::text[], 8.5, '{"poet":"Murat Alp","poet_slug":"murat-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tukenis-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Sor', 'bana-sor-murat-alp-koqen', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ateşte üşüyüp karda yanmayı,

Aşkınla yaşadım gel de bana sor.

Güzel olup ta çirkin kalmayı,

Seninle yaşadım gel de bana sor.

Baharı yaşarken güzde olmayı,

Öfkenle yakarken özde donmayı,

Yabanda açarken bende solmayı,

Gülünce yaşadım gel de bana sor.', 'Ateşte üşüyüp karda yanmayı, Aşkınla yaşadım gel de bana sor. Güzel olup ta çirkin kalmayı, Seninle yaşadım gel de bana sor. Baharı yaşarken...', ARRAY['Türk Edebiyatı','Şiir','Murat Alp']::text[], 8.5, '{"poet":"Murat Alp","poet_slug":"murat-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bana-sor-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Yer', 'o-yer-canan-karadaglioglu-2-agbi5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Adını anmadığım,içimin yanmadığı bir an bile geçmedi

Gönül kaç gönül gezdi, bir yar bile seçmedi

Bir haber göndermedin,şimdi hangi eldesin? 

Yıllar geçti üstünden, sen hala o yerdesin

Her tonunda siyahın, gözlerini aradım

Hicran oldu yaşamak,her gönülde kanadım

Söyle sevgili söyle...Şimdi sen kimlerlesin? 

Yıllar geçti üstünden sen hala o yerdesin

Yazım hazana döndü, şarkım hüzzama döndü

Yüreğimde ümitler bir bir hicrana döndü

Bir haber salmasan da sen her zaman benlesin

Yıllar geçti üstünden, sen hala o yerdesin', 'Adını anmadığım,içimin yanmadığı bir an bile geçmedi Gönül kaç gönül gezdi, bir yar bile seçmedi Bir haber göndermedin,şimdi hangi eldesin? ...', ARRAY['Türk Edebiyatı','Şiir','Canan Karadağlioglu 2']::text[], 8.5, '{"poet":"Canan Karadağlioglu 2","poet_slug":"canan-karadaglioglu-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-yer-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerim', 'duslerim-erol-sen-sadae', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazen yılgın kırmızılara

Mavilerin umut düşlerine

Pembenin mutluluk deyişlerine

Yeşilin bahar çırpınışlarına

Yaşamın hayat pınarından fışkıran

Bitimsiz doyumsuz pastel renkler

Koyusuna aldırmıyor gönlüm

Hele sarı yı görmek

Beyazın saf berrak yaşantısı

Lekelerin tutunamadağı

Her yaşamın beyaz renklerine

Gönül dolusu sevgi damlacıkları

Gri bulutların yok oluşuna

Ardındaki mavi gökyüzüne 

Beyaz gelen pamuk bulutlarıma

Umudun bitmez tükenmez bekleyişine...

30.11.2004', 'Bazen yılgın kırmızılara Mavilerin umut düşlerine Pembenin mutluluk deyişlerine Yeşilin bahar çırpınışlarına Yaşamın hayat pınarından fışkır...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/duslerim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehir', 'sehir-ali-aldemir-681xn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ben mi fazla geldim

Bir beni mi yük saydın

Kimler volta atmıyor 

Kimler arşınlamıyor adım adım

Meydanlarını, kaldırımlarını

Kaç kalpazan kaç etini satan,

Kimleri saklamıyorsun sokaklarında ter kokan

Türlü türlü dönmeleri

En ateşli fahişeleri

Sen değil misin barındıran,

Bilir misin kaç çocuk aç yatar

Kaç oyun çocuğu kız, 

Sabah kadın uyanır sokaklarında,

Nasıl da kandırdın

Nasıl da inandırdın

O al benili ışıklarına

Sen şehir denilen beton yığını

Senin sofranda yedim ilk haramı

İlk sen tattırdın bana kolibasilili balıkları,

Sende yaşadım acemice  ilk kez

Ucuz bir şarapla sarhoşluğu,

İlk nagramı attım ürkerek

Sidik kokan sokaklarında.

Sende öğrendim ilk kalleşliği

En hasosundan adam satmayı,

Bir paket Amerikan cıgarasına

Teslim ettim anahtarı

Aşk kokan yosmalarına.

İlk yalanı ve dönekliği

İlk vukuatımı, karakola düşüşümü

Unutulmayı, satılmanın dayanılmazlığını

Ve ilk düş kırıklığımı

Ve namlu ucunda erkete uykularını

Sende yaşadım,

Ezilmeye,sömürülmeye karşı 

İlk direnmeyi yiğitce,

İlk kez kul değil insan olduğumu 

Hakkın verilmediğini, alındığını

Sende öğrendim

Ey şehir gene de seni severim be.', 'Bir ben mi fazla geldim Bir beni mi yük saydın Kimler volta atmıyor  Kimler arşınlamıyor adım adım Meydanlarını, kaldırımlarını Kaç kalpazan...', ARRAY['Türk Edebiyatı','Şiir','Ali Aldemir']::text[], 8.5, '{"poet":"Ali Aldemir","poet_slug":"ali-aldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sehir-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustuğum Konuşmalar', 'sustugum-konusmalar-evren-dalgic-jt7wm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gölgesine düştüm yüreğinin,

uzandım senli nakışlara.

Bulutlara gökyüzü oldum kimi zaman,

kimi zaman yağmur kaldırımlara.

İzine renk kattım bazen,

hayaline çiçekler kondurdum.

Bazen hiç anlayamadım bu gidişleri,

gece gibi karardım.

Şiir gibi çok konuştum

ve hep sustum.

(Ankara 2002)', 'Gölgesine düştüm yüreğinin, uzandım senli nakışlara. Bulutlara gökyüzü oldum kimi zaman, kimi zaman yağmur kaldırımlara. İzine renk kattım b...', ARRAY['Türk Edebiyatı','Şiir','Evren Dalgıç']::text[], 8.5, '{"poet":"Evren Dalgıç","poet_slug":"evren-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sustugum-konusmalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-canan-karadaglioglu-2-an3dr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bitmedi bülbülün güle figanı

Söyle bende sana yakarayım mı? 

Gözlerin bir açsan...yüzüme baksan

yoksa...Hayalinle avunayım mı? 

Naz edip peşinden koşturma beni

Yeniden ardından yalvarayım mı

Dönüş varmıydı ki bu gidişinde

Tanrıya yakarıp, ağlayayım mı? 

Gittiğin yerler çok uzak bana

Geleceğim elbet, mutlak yanına

Tanrı ben kadar sevmiş almış yanına

Sana rahmetler yağdırayım mı?', 'Bitmedi bülbülün güle figanı Söyle bende sana yakarayım mı?  Gözlerin bir açsan...yüzüme baksan yoksa...Hayalinle avunayım mı?  Naz edip peş...', ARRAY['Türk Edebiyatı','Şiir','Canan Karadağlioglu 2']::text[], 8.5, '{"poet":"Canan Karadağlioglu 2","poet_slug":"canan-karadaglioglu-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olum-150-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir güne seninle başlamak', 'bir-gune-seninle-baslamak-fatih-can-08l3b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öylesine güzel ki her an seni yaşamak

Sesini duyabilmek uyandığımda

Ve biliyorum ki

''Günaydın'' hiçbir zaman böylesine güzel 

Ve böylesine içten

Fısıldanamayacak birdaha

Ve hiçkimse

Yaşayamayacak bu anı bizim gibi.', 'Öylesine güzel ki her an seni yaşamak Sesini duyabilmek uyandığımda Ve biliyorum ki ''Günaydın'' hiçbir zaman böylesine güzel  Ve böylesine iç...', ARRAY['Türk Edebiyatı','Şiir','Fatih Can']::text[], 8.5, '{"poet":"Fatih Can","poet_slug":"fatih-can","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-gune-seninle-baslamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamam', 'unutamam-fatih-konuk-a0pfg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Herşeyi suratıma insafsızca çarpışını,

Ölmek üzere olan kuş gibi çırpınışımı,

Sözlerimi dinlemeden karşı çıkışını,

Unutamam unutamam....

Ben evleniyorum deyip gidişini,

Ardına bir kez dönüp bakmayışını,

Beni ortada sap gibi koyuşunu,

Unutamam unutamam....

Göz yaşımın yanağıma dökülüşünü,

Olduğum yere birden yıkılışımı,

Her şeylere isyanlar edişimi,

Unutamam unutamam....

Güneşin ağlayarak doğuşunu,

Karanlığın ağlayarak çöküşünü,

Geceler boyu uykusuz kalışımı,

Unutamam unutamam....

Uykularımda ismini sayıklayışımı,

Acımdan duvarları yumruklayışımı,

Gözlerimim önünden kayboluşunu,

Unutamam unutamam....', 'Herşeyi suratıma insafsızca çarpışını, Ölmek üzere olan kuş gibi çırpınışımı, Sözlerimi dinlemeden karşı çıkışını, Unutamam unutamam.... Ben...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/unutamam-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzel', 'ne-guzel-canan-karadaglioglu-2-bhafc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllanmış şarap tadı, ne güzel

Bir yudum tatmak seni

Ne güzel canımdan koparılmış can gibi

Gönlüme katmak seni

Gözünden kıskanmak, tüyden sakınmak ne güzel

Yürekte saklamak seni

Ne güzel aşkınla erimek, bir ömür sevmek

Sevdanla yaşamak seni

Şimdi çok uzaklardasın, çok uzak benden

Ne güzel hasretle özlemek seni

Adını söylemek, od''una yanmak

Ne güzelmiş  beklemek,Cananım seni', 'Yıllanmış şarap tadı, ne güzel Bir yudum tatmak seni Ne güzel canımdan koparılmış can gibi Gönlüme katmak seni Gözünden kıskanmak, tüyden sa...', ARRAY['Türk Edebiyatı','Şiir','Canan Karadağlioglu 2']::text[], 8.5, '{"poet":"Canan Karadağlioglu 2","poet_slug":"canan-karadaglioglu-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-guzel-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Körebe', 'korebe-cetin-erdogdu-ashfj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ırakta 

ta...

ıraklarda

kan güllerini ben gördüm...

çocuklarım gördü...

halkım gördü...

Felluce''de daha gün goğmadan

güneşin közünü 

dünya gördü

oysa! .. 

Irakta ölümleri

hiç kimse görmedi

oynayarak körebe...', 'ırakta  ta... ıraklarda kan güllerini ben gördüm... çocuklarım gördü... halkım gördü... Felluce''de daha gün goğmadan güneşin közünü  dünya g...', ARRAY['Türk Edebiyatı','Şiir','Çetin Erdoğdu']::text[], 8.5, '{"poet":"Çetin Erdoğdu","poet_slug":"cetin-erdogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/korebe-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçliğin Şiiri', 'hicligin-siiri-bora-alagoz-3dc1y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl başlarsa başlasın gün

Kabulümdür getirecekleri

Bugün verdiğini, yarın alır nasıl olsa

Baki değil iyi ve kötü

Koşacağım günün çeperlerine, delice

Tıraş olup temizleneceğim

Tarazlayıp saçlarımı

En iyi giysilerimi giyeceğim

Kabulümdür, ne çıkarsa bahtıma

Bugün dün değil

Bu o sevdiğim kadın değil

Rüzgâr yorgun, esniyor

Bekliyorum, gelecek belli değil

Gülmek, ağlamaya eşdeğer

Es rüzgâr, gül kokular getir

Sen de sigaranı tellendir Bora

Bulmuşken yudumla kahveni

Düşünme geçmişi, ya de geleceği

Elindekiyle ol bahtiyar', 'Nasıl başlarsa başlasın gün Kabulümdür getirecekleri Bugün verdiğini, yarın alır nasıl olsa Baki değil iyi ve kötü Koşacağım günün çeperleri...', ARRAY['Türk Edebiyatı','Şiir','Bora Alagöz']::text[], 8.5, '{"poet":"Bora Alagöz","poet_slug":"bora-alagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hicligin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttum yazmayı', 'unuttum-yazmayi-sirma-mersin-ecmht', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yazmayı unutmuş ellerimi

Sayfaların üzerinde boş boş geziyorken, kangren olmuş yüreğim kesiyordu, duygularımı...

Oysa! 

Sonsuzluğun içine birikmiş kırılgan hüzünleri dağıtmak için,

derinlerden çıkarıp, karanlığa gözyaşı damlalarını akıtmayı istiyordu...

Mekanı, zamanı olmayan yalnızlığımı, yaşam özetlerinden sonra; satırlara düşecek ne varsa sesini çıkaracaktı, yazılarımda! 

02.12.2004

                    ''İşten sebep yazmayı unutmuş, yüreğimden saçma sapan

                      dökülen dizelerle seslendim sizlere...''', 'Yazmayı unutmuş ellerimi Sayfaların üzerinde boş boş geziyorken, kangren olmuş yüreğim kesiyordu, duygularımı... Oysa!  Sonsuzluğun içine bi...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/unuttum-yazmayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birey Olabilmek…! ! ! ! ! ! ! ! ! ! ! !', 'birey-olabilmek-hikmet-feridun-demir-t8emo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni ben olarak görebilecek,

bilgi ve duygu birikimin varmı…

Yoksa daha farkında değilmisin yaşamın…

Sıkıştırma beni herhangi bir Cenderenin kalıpları arasına…

Beni değiştiremezsin, 

Seni değiştirmek gibi bir duygu da taşımıyorum Ben…

Seni sen olarak anlat bana, 

Başkalarının nakaratları ile değil…

Lütfen ama Lütfen,

başkalarının yaldızlı sözleri ile,

tırmalama kulaklarımı…

Bana kendini, bana seni anlat kendi sözlerinle…

Sıradan, kalbinden gelen duygular,

Düşünebildiğinin, Birey olmanın gereğidir...

Seni sen olarak görmek istiyorum...

Beni ben olarak gör yeter bana…

Sevgi ve aşkı tat kendince, acısı ile tatlısı ile… 

At kendini kendi ateşine yan cayır cayır…

Bak ne kadar dirençlı ve yaşam dolarsın…

Ateşinde kavrulursun, erirsin, erirsin, geride, 

küllerinden geriye bir SEN kalırsın..

Bak, işte bak o küllere...

İşte o küller, o küller gerçek SEN sin...

02.08.2000-Wermelskirchen

Almanya', 'Beni ben olarak görebilecek, bilgi ve duygu birikimin varmı… Yoksa daha farkında değilmisin yaşamın… Sıkıştırma beni herhangi bir Cenderenin...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/birey-olabilmek--siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gör Ki Nesi Kaldı VII', 'gor-ki-nesi-kaldi-vii-sadik-softa-r638z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ol cihan ki, ne güzel, cennet göründü gözlerimize her an,

Halbuki zaman doldu, ömür bitti, bu canımın gidesi kaldı.

Ne yapması gerek diye sorası gelir bu garibanın yaranlar,

Ve görünen o dur ki, bu nefsin gönülde bir züppesi kaldı.

Bu yüreğe hep böyle acı,ızdırap mı ekeceksin ey gönül? 

Gül rumuzlu,O ulunun,unutulmayan yüce bir hutbesi kaldı.

Nesimi ve Hallac mı olmalı, atmak için zamandan libası,

Yüzülsün ten, ne çıkar ki, böyle bir gerçeği bilmesi kaldı.

Dert yasiri olduk durup dinlenmeden hem de gece,gündüz

Çektik acıları ta sinenin derinliğinde, sırada gülmesi kaldı.

Yeter artık, bunca zahmete katlanmaktan kalmadı mecal,

Bundan böyle bize gülmesi, çile ve ızdıraba ölmesi kaldı.

Etti felek edeceğini ey yar,cananın can dostuymuş meğer,

Gönlü pare pare edip,didik didik parçalayıp,dilmesi kaldı.', 'Ol cihan ki, ne güzel, cennet göründü gözlerimize her an, Halbuki zaman doldu, ömür bitti, bu canımın gidesi kaldı. Ne yapması gerek diye so...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gor-ki-nesi-kaldi-vii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi gecesi', 'sevgi-gecesi-nalan-palabiyik-2sz00', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Al koynuna sıkıca sevginle sar beni

Tüm sırlarını anlat bana

Tüm yalnızlığını paylaş benimle

Korkularını,acılarını dök içini bana bir tanem

Bırak kendini bu gece

Sular seller gibi aksın yaşların

Bu gece senin gecen sevdiğim

Erkekler ağlamaz felsefesi diye

Bir şey yok benim kitabımda

Anlat bana sevdiğim kendini

Tüm çıplaklığınla anlat

Seni anlat bana

Gerçek seni anlat

Korkuların bitsin,hüzünlerin bitsin bu gece

Bak ellerimi uzatıyorum sana

Şunu bil ki sen; seni anlattıkça

Yüreğimde sevginle yüceleceksin

Sabah doğduğunda üzerimize

Sevdiğinin kollarında hafifleyeceksin…

2.12.2004 Bartın

Nalan Palabıyık', 'Al koynuna sıkıca sevginle sar beni Tüm sırlarını anlat bana Tüm yalnızlığını paylaş benimle Korkularını,acılarını dök içini bana bir tanem ...', ARRAY['Türk Edebiyatı','Şiir','Nalan Palabıyık']::text[], 8.5, '{"poet":"Nalan Palabıyık","poet_slug":"nalan-palabiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevgi-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tren ve An', 'tren-ve-an-atanur-memis-1ig2h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'soğuk 

                 kentlerden 

                                 dolanan 

                                                  uzun 

                                  yolcu 

                    treni 

-nin 

                  boşalan 

                                 camlarından 

          her vagon 

                              geçmişi 

                                                  geçiyordu 

       her makas 

                                 bir yazgıyı 

       nabız atışları 

                             yavaşladı 

             yaşamın 

         geniş  zamana 

                               takıldı 

                   zamanın 

zembereği                           …….

                                                            ……….

                                                                              ...

     kopacak – bir – film – gibi – uzadı – kara–Tren

                       sûni solunum için 

                        nefes aldı  makinist

                                         raylar 

                     acı içinde 

      camlar 

                   canlanıyordu

gözlerimin – içinde – gözlerim – vardı 

      		 

daha da – içerlerde – gözlerim – yine 

                    1996

                 Bakırköy', 'soğuk                   kentlerden                                   dolanan                                                    uzun        ...', ARRAY['Türk Edebiyatı','Şiir','Atanur Memiş']::text[], 8.5, '{"poet":"Atanur Memiş","poet_slug":"atanur-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/tren-ve-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Bir Gece', 'sessiz-bir-gece-galip-uyar-aw6uw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sessiz bir gece 

Neon lambalar...

Peşinde, önünde, her yerde

Bir de gölgen seninle

Dilinde bir şarkı

“Sevdim seni bir kere”

Gönlünde bir sızı

Ellerin ceplerinde

Soğuk dudaklarında

Böyle bir gece çıkacaksın işte

Sokaklara 

Sevdiysen… 

Ödeyeceksin

Söyleyemediysen

Sessiz bir gece 

Haykıracaksın tüm şehre

Işıkları yanacak meraklı evlerin

Ne oluyor diye

Haykıracaksın

Seviyorum diye', 'Sessiz bir gece  Neon lambalar... Peşinde, önünde, her yerde Bir de gölgen seninle Dilinde bir şarkı “Sevdim seni bir kere” Gönlünde bir sız...', ARRAY['Türk Edebiyatı','Şiir','Galip Uyar']::text[], 8.5, '{"poet":"Galip Uyar","poet_slug":"galip-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sessiz-bir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hoşçakal*', 'hoscakal-kubilay-enginol-eq6qt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Terkedeceğim bu şehri

Öksüz bırakacağım sokak lambalarını

Duymayacağım sokakların sessiz sessizliğini

Çekip gideceğim

Sen hazırlamamış olacaksın çantamı

Ellerinin izi olmayacak

Kokunu yalnızlık girdabına atacağım

Sokakların sessizliğine karışacağım

Yüreğimi heyecanlandıracağım yeni sevgilerle

Bazen bir ağacı bazen yıldızları

Upuzun umut kokan yolları

Belki buruk bir yürek geride

Bu şehri terkedeceğim', 'Terkedeceğim bu şehri Öksüz bırakacağım sokak lambalarını Duymayacağım sokakların sessiz sessizliğini Çekip gideceğim Sen hazırlamamış olaca...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hoscakal-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul düştü....', 'i-stanbul-dustu-evren-dalgic-jqjtk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Koca İstanbul! 

Ey ayasofya! 

ve karış karış vatanımda,

kanla yazılmış destan! 

şimdi adı mert oldu namerdin,

beni duyuyor musun.

Hala özlemli şiirler yazılıyor bizansa,

hala; 

Konstantinapol  gibi bir şey deniliyor,

Peygamber''in (sas) , Fatih''in İstanbul''una.

Ey Türk! 

Ey yerinde rahat yatırmayan şehitleri! 

düzenin yok,

ahlakın aratmıyor koalisyon güçlerini.

yoksa sende onlar gibi 

uyuyor musun? 

:((

(Ankara Kasım 2004)', 'Koca İstanbul!  Ey ayasofya!  ve karış karış vatanımda, kanla yazılmış destan!  şimdi adı mert oldu namerdin, beni duyuyor musun. Hala özlem...', ARRAY['Türk Edebiyatı','Şiir','Evren Dalgıç']::text[], 8.5, '{"poet":"Evren Dalgıç","poet_slug":"evren-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/istanbul-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Gülleri', 'guz-gulleri-yavuz-agir-12mjm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güz gülleri neşe saçar.

Türlü türlü çiçek açar.

Gizli sedvdalara kucak açar,

Bir başkadır güz gülleri.

Onlara derler güz gülleri,

Pek ferahtır gönülleri.

Bizim bahçenin bülbülleri,

Ötmez görmeyince bu gülleri...

Hazan da zordur onları görmek,

Yaşamını sürdürene haktır övünmek.

Zemheri ayında türlü reklere bürünmek,

Bir başkadır güz gülleri.....', 'Güz gülleri neşe saçar. Türlü türlü çiçek açar. Gizli sedvdalara kucak açar, Bir başkadır güz gülleri. Onlara derler güz gülleri, Pek feraht...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guz-gulleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-i-smail-baharsen-gdhoo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hiç düşünmedim bir gece olmayı

bir duvar,hapishanenin ıssızlığında

bir yol,yanlızların gelipte geçtikleri

bir mendil,gözyaşlarıyla ıslanan

ayrılığın kahrı, acısı saplandığında

bir çocuk çığlığı,kulakları çınlatan

aç, sefil,yoksulluğun koynunda

bir mektup olsam hasretle dopdolu

bir resim,belki sahibi dünyada yok

bir adres,çoktan terkedilmiş kaderine

bir sevda,dipciğinden yakalamış canı

bir saat,mutluluğa kurulmuş zamanı çok

dileğim insanlık muhtaç olmaz kimseye

dert deva bulur dileğim, gariplerin günahı yok.........', 'hiç düşünmedim bir gece olmayı bir duvar,hapishanenin ıssızlığında bir yol,yanlızların gelipte geçtikleri bir mendil,gözyaşlarıyla ıslanan a...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/insan-olmasaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sendin', 'sendin-suleyman-yavuz-cjf4h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SENDİN

Sendin ilk sevdiğim sendin

Hayatım bildiğim

Canımı almana razı olduğum

Sendin evet sendin yar

Sendin hayatın anlamı

Sendin gecemin yıldızı ayı

Sendin ömrün yazı kışı 

Sendin ey yar

Şimdi bilmem nerdesin

Bilmem kiminlesin 

Sen unutsan da beni

Unutamam ben senli günleri

Evet sensin sen

Bir anda terk eden 

Hayatımı zindan yapan 

Beni benden alan sendin yar

Şimdi sen sevmesen de beni 

Ben hiç unutmayacağım asla unutamam seni

Duy beni ey vicdansız yar', 'SENDİN Sendin ilk sevdiğim sendin Hayatım bildiğim Canımı almana razı olduğum Sendin evet sendin yar Sendin hayatın anlamı Sendin gecemin yı...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sendin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ask Sarabi', 'ask-sarabi-tugba-ugurlu-ya3yw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Meyler sahit olsun sana,

sana ve bitmek tukenmek bilmeyen askima,

artik istesem de susamam,

ciglik olur bogazimda dusunceler,

bagiririm durmaksizin

bakin yollar bana bakin,

dinleyin sonsuz sarkilarimi,

soylemeye doyamadigim ismini de..

bakin sehrin sonmek bilmeyen isiklari,

bakin ve gorun nasil yoldan cikarmis duygular,

nasil dur durak bilmezmis, akan goz yaslari,

Bakin gokyuzunun kimsesiz cocuklari,

bagrimda kalp degil tas tasirim artik

icim yarali halden anlamaz misiniz? 

duymaz misiniz feryatlarimi? 

Acin, acinda seyre dalin,

Nasil yikilirmis masalar gozumde,

nasil bin parca gorunurmus yere vuran fikrimin golgesi,

nasil aciya doyarmis bir yurek,

ve nasil iflah olmaz bir yangin yeri tasirmis iclerinde insanlar.

Bana iyi bakin, bakin da seyre dalin

nasil yemeden tok

icmeden sarhos,

sevilmeden severmis kalpler,

dahasi nasil hem canli, hem olu olurmus nefes alan bedenler...', 'Meyler sahit olsun sana, sana ve bitmek tukenmek bilmeyen askima, artik istesem de susamam, ciglik olur bogazimda dusunceler, bagiririm durm...', ARRAY['Türk Edebiyatı','Şiir','Tugba Ugurlu']::text[], 8.5, '{"poet":"Tugba Ugurlu","poet_slug":"tugba-ugurlu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ask-sarabi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi', 'mavi-tugba-ugurlu-wn1wu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni aldatma sakin,

mavi boncuklar takip gozlerine,

bakamam bir daha okyanuslara,

seyredemem gokyuzunun mavisini,

yaslanamam,

ellerimi suremem yuzune,

opemem cocuklari bir daha,

nerde asik bir cift gorsem orasi dar gelir bana,

bunalirim, kacasim gelir.

Beni aldatma sakin 

mavi boncuklar takip gozlerine,

oc alasim gelir herkesten,

gozum doner nefretten,

tum mavi boyalari cope atarim,

anilarimi da, seni de,

acip balkon kapisini disari birakirim,

ozgurlugu seversin bilirim,

ben de seni severim,

beni aldatma sakin,

mavi benim en sevdigim renktir.', 'Beni aldatma sakin, mavi boncuklar takip gozlerine, bakamam bir daha okyanuslara, seyredemem gokyuzunun mavisini, yaslanamam, ellerimi surem...', ARRAY['Türk Edebiyatı','Şiir','Tugba Ugurlu']::text[], 8.5, '{"poet":"Tugba Ugurlu","poet_slug":"tugba-ugurlu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mavi-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Aşk Olsa...', 'adi-ask-olsa-ediz-karaoglu-4l0kn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adı aşk olsa bunun,biterdi,

	Bir sabah aniden geldiği gibi buraya kadarmış derdi,

	Göz kapaklarımı inan bu kadar titretmezdi,

	Buna yalnızca bir heves deme sakın,

	Heves olsa geldiği gibi gitmesini de bilirdi…

	Peki ne değişti,

	İster sevgi de buna,istersen yaman bir çelişki,

	Seni kazandırabildi mi bana ey küçük sevgili,

	Küçük ama dünyaları sığdıran kalbinde bana yer açabildi mi,

	Hayır kelimesi olağan oldu şimdileri…

	

	Ama bekliyorum,

	Doğru zamanda sana gelmeyi,

	Bir gün gelecek sana öyle bir sevda  getireceğim ki,

	Hayır diyemeyeceksin su perisi,

	Gözlerimin içine bak her zamankinden  uzuncasına,

	Yoksa doğru zaman şimdi mi? 

								02.Aralık.2004

								Saat:21:10

								Antalya', 'Adı aşk olsa bunun,biterdi, 	Bir sabah aniden geldiği gibi buraya kadarmış derdi, 	Göz kapaklarımı inan bu kadar titretmezdi, 	Buna yalnızca...', ARRAY['Türk Edebiyatı','Şiir','Ediz Karaoğlu']::text[], 8.5, '{"poet":"Ediz Karaoğlu","poet_slug":"ediz-karaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/adi-ask-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimlik', 'kimlik-ahmet-mansuroglu-pjycf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben Antakya''dan Ahmet oğlu Ahmet

Dedem Ahmet,

Babam Ahmet,

Ben Ahmet,

Başka isim bulmak sanki zahmet,

Ve işte ben Antakya''dan

Ahmet oğlu Ahmet

Antakya''nın yağmurlarında büyümüşüm,

Sel sularında geçmiş çocukluğum.

Yıllar önce bu kentte

Şiirler yazardım sevgili üstüne,

Geçen yıllar götürdü

Aşk şarkılarını dudaklarımdan

Ve kalemim yazmıyor artık,

Sevgili üstüne...

Evde karım,

Üç de çocuk var dostlar başına,

İnsanların gülüşlerinde bulurum mutluluğu,

Üzüntülerinde kahrolurum.

Ben Antakyadan Ahmet oğlu Ahmet

Sen köşede oynayan yaramaz çocuk

Ve sen nur yüzlü ninem.

Antakyam, Türkiyem

Sizin mutluluğunuzdan alırım yaşama gücümü,

Bir çift göz görsem

Sevinçle ışlıdayan,

Bir hoş olurum,

Sarhoş olurum...

Antakya-HATAY             18.06.1988.', 'Ben Antakya''dan Ahmet oğlu Ahmet Dedem Ahmet, Babam Ahmet, Ben Ahmet, Başka isim bulmak sanki zahmet, Ve işte ben Antakya''dan Ahmet oğlu Ahm...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kimlik-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alın Yazım', 'alin-yazim-ahmet-mansuroglu-kssrq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Birbirimizden habersiz gelmişiz dünyaya,

Oysa Tanrı,

Seni ve beni bir olalım diye göndermiş,

Alın demiş işte koca bir dünya

Ve ikiniz bir bütün,

Yıllarca bir yastıkta mutlu olmuşuz.

Bir yastıkta dinlendirmişiz yorgun başımızı.

Bazan alnımda ter olmuşsun,

Bazan kollarımda güç,

Beraber paylaşmışız

Kederi mutluluğu

Sen benim güç kaynağımsın; 

Baharımsın, yazımsın.

Sen benim ebedi sevgilim,

Alın yazımsın...

Antakya - Hatay', 'Birbirimizden habersiz gelmişiz dünyaya, Oysa Tanrı, Seni ve beni bir olalım diye göndermiş, Alın demiş işte koca bir dünya Ve ikiniz bir bü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/alin-yazim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firuze Kelebek', 'firuze-kelebek-volkan-yoruc-u839v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kelebek kondu yüreğime sessizce

Rengi firuze

Ürkütüpte kaçırmak istemezdim oysa

Nede güzeldi aslında

Belki sendin 

Hani parıldardıya seninde öylece gözlerin

Anımsadım yine seni 

Ve rüya gözlerini

Kaldı aklımda bir an işte

Ve uçup gitti 

Bir kelebek kondu elime ürkekçe

Rengi firuze

Düşmü yoksa gerçekmi

Senmiydin yoksa hayalinmiydi

Bitmesini istermiydim hiç

Sen bir kelebek ben ise börtü böcek

Bir ovada buluşmuşuz 

Uçuşurmuşun gönlümde bir heyecanla

Ve konarmışın yanıbaşıma

Konarmışık toprak damlara,ovalara

Aramıza girmeden fırtınalar

Salınırmışık sarmaşıklarda dallarda

Bir kelebek kondu yanağıma sessizce

Rengi firuze

Ve uyandım tatlı düşlerimden sayende

Meğerse sen hayalmişin gönül haznemde

Ben yalnızlığın silik gölgesinde', 'Bir kelebek kondu yüreğime sessizce Rengi firuze Ürkütüpte kaçırmak istemezdim oysa Nede güzeldi aslında Belki sendin  Hani parıldardıya sen...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/firuze-kelebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Kabardı Deniz!', 've-kabardi-deniz-leyla-ayyildiz-80o1n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ve kabardı deniz,

Kabardı...

Aya çattı, 

Söylendi yıldızlara...

Taştı öfkesi köpük, köpük...

Ve haykırdı deniz,

Haykırdı! 

Deli dalgalarını vurdu kendi kendine,

Vurdu kendi kendine dalgalarını,

Kabardı deniz, kabardı...

Ve karardı gökyüzü,

Karardı...

Çaktı şimşeklerini...

Bağırdı deniz, 

Bağırdı...

Oysa, herkes sağırdı...

Kudurdu deniz, kudurdu...

Saklandı şiirlere...

Susup, şiir oldu...

Sustu,

Şiir doğurdu...

Sustu...', 'Ve kabardı deniz, Kabardı... Aya çattı,  Söylendi yıldızlara... Taştı öfkesi köpük, köpük... Ve haykırdı deniz, Haykırdı!  Deli dalgalarını ...', ARRAY['Türk Edebiyatı','Şiir','Leyla Ayyıldız']::text[], 8.5, '{"poet":"Leyla Ayyıldız","poet_slug":"leyla-ayyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ve-kabardi-deniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Ben Oradayım', 'i-ste-ben-oradayim-ahmet-mansuroglu-dht32', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün gidersem uzaklara 

Dönmemek üzere geri

Uzaklarda arama beni

Senin yanında

Nefes aldığın havadayım.

Mutluluk rüzgarları 

Gülümsediği zaman, tüm insanlara

İşte ben oradayım...

Ne varsa iyilikten güzellikten yana

Kuşların kanadından 

Bana haber gönder

İnsanlar sevgiyle kucaklıyorsa birbirlerini

İşte ben oradayım...

Beni uzaklarda arama göremezsin

Uzat ellerini desem, veremezsin

Eğer yer etmişsem 

Gönlünün derinliklerinde

İşte ben oradayım...

Ne suda ne havadayım

Ne dünyada ne aydayım

Sorma bana ne haldayım

Kışım yok benim, hep bahardayım

Ümitle bekleme

Dönülmeyen yoldayım

Nerede huzur ve mutluluk varsa 

Ne zaman sevdiklerim beni ararsa 

İşte ben oradayım...

Antakya- Hatay            1.06.1998.

Tlf: 0 326 2156779', 'Bir gün gidersem uzaklara  Dönmemek üzere geri Uzaklarda arama beni Senin yanında Nefes aldığın havadayım. Mutluluk rüzgarları  Gülümsediği ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/iste-ben-oradayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar Çiçeği', 'sonbahar-cicegi-evren-dalgic-bg553', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine yollar göründü gözüme,

yine baş ağrısı yüreğimde.

Gözlerin gibi donuklaşıyorum,

sözlerimiz gibi sönükleşiyorum ayrılık cümlesinde.

Ölüm bıçağı gibi kesiyor

ayrılık havası gülüşümü,

içimde bir ürperti; 

ve köprülerim yıkılıyor bir bir hayatla. 

Sanmam; 

düzelmez bu moral bozukluğum

gülmem bir süre daha.

Takvimle aram bozuk,

sesi kısılmış türkümün.

Özlem demeye yüz kalmamış,

şiirlerde tadı kalmamış artık hasretin.

Her dem aynı...

Her dem kuşlar göçer ufkumdan.

Hüzünlü bir sessizlikte; 

kıpırtısı duyulur,

çatırtısı duyulur bir yangının.

İçten içe alevlere dolanır

ve bir anda değil; 

yıllarla yıkılır o gövdem.

Kış ayında güneş açmış dağlara,

ilkbaharda  dal kurumuş.

Ve dayanamadan kıpırdamış,

toprakta bir filiz.

Gözler görmüş,

yürekler sevmiş hiç pişmanlık duymadan.

Ne yağmurlara tutulmuş,

ne karlar görmüş,

ne gidişlere şahit olmuş bu yürek dediğin.

Yine ağlar,

yine çatlar bu toprak.

Belki uçmaz bir daha meleğin.

Geç kalmış,

hep aldanmış

ve erken açmış

sonbahar çiçeğin.

(Ankara 2002)', 'Yine yollar göründü gözüme, yine baş ağrısı yüreğimde. Gözlerin gibi donuklaşıyorum, sözlerimiz gibi sönükleşiyorum ayrılık cümlesinde. Ölüm...', ARRAY['Türk Edebiyatı','Şiir','Evren Dalgıç']::text[], 8.5, '{"poet":"Evren Dalgıç","poet_slug":"evren-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sonbahar-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğa', 'doga-ahmet-mansuroglu-2mlsp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğa tutkusu 

Bende benimle başladı.

Önce güneş ısıttı beni

Düşe kalka yürüdüm kırlarda

İlk adımını atarken ayaklarım,

Papatya, lale, sümbül topladım

Kucak kucak

Doğada tanıdım yeşili,kırmızıyı,sarıyı

Denizde, gökte buldum en güzelini mavinin

Doğanın kucağında büyüdüm,

Kırlarında koştum yürüdüm.

Bende benimle başladı doğa tutkusu

Denizine, kırlarına, göllerine vuruldum

Yağmurunu bir başka severim

Bereket saçar toprağa

Güneş doğar hayat verir,

Çiçeğe, ağaca, yeşeren yaprağa

Kar yağar,

Beyazlarını giyinir yer yüzü

Kışı güzel...

Baharı bir başka güzel

Her mevsimi

Ayrı bir güzel

Doğa denizi, kırları

Mavisi, yeşili ile güzel.

Antakya- 22.05.1997.', 'Doğa tutkusu  Bende benimle başladı. Önce güneş ısıttı beni Düşe kalka yürüdüm kırlarda İlk adımını atarken ayaklarım, Papatya, lale, sümbül...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/doga-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antakyam', 'antakyam-ahmet-mansuroglu-1tjpv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Antakya denince 

Çocukluğum, gençliğim

Bütün hayatım gelir aklıma...

Hayata sende açtım gözümü

Sende kapamak isterim

En güzeli sende saklı hatıralarımın

En acısı sende...

Gurbette ilk özlediğim sen olursun

Annemden önce...

Düşünürüm yağmurlu gecelerini

Islandığımı sırılsıklam

İçlenirim sensizliğime.

Antakya - Hatay            07.02..1976.', 'Antakya denince  Çocukluğum, gençliğim Bütün hayatım gelir aklıma... Hayata sende açtım gözümü Sende kapamak isterim En güzeli sende saklı h...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/antakyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın', 'kadin-cem-han-8k65w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Koklayınca solacak çiçek gibi

Can alınıp,can verilen sevgili gibi

Yuvasını yapan dişi kuş gibi

Bazen de çözülmeyen bulmaca gibi

Her zaman bakımlı,süslü kadın

Erkeğini hayata küstüren,aksi kadın

Bizleri doğuran,büyüten asil kadın

Yaşamın vazgeçilmezi,güçlü kadın.', 'Koklayınca solacak çiçek gibi Can alınıp,can verilen sevgili gibi Yuvasını yapan dişi kuş gibi Bazen de çözülmeyen bulmaca gibi Her zaman ba...', ARRAY['Türk Edebiyatı','Şiir','Cem Han']::text[], 8.5, '{"poet":"Cem Han","poet_slug":"cem-han","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kadin-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Bıranda', 'kara-biranda-baykal-kaanalp-dd4xz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dayanamadı zincirlerini

habire çekip durmaktan

yaşanması güç hanın 

kızıllığına aldırmadı günün

serinliğine hiç doyamadı

akşamleyin kaçan kışların

kulaklarına küpe olsun diye

bigudilerini hiç çözmedi

sırnaşıp duran çipuraların

aynı anda aynı yerde

bekleşp dururken

farkına varamadı

hiçbir şeyin değişmediğinin

aynı kalmaktan yorulmuş muydu? 

bunca seneler

ortalıkta dolaşan

sevda yüklü demir vagonlar

ama bıkkınlık taşımamalı

üstü açık vagonlar

örtmeye korktuğun

aynı kara bırandayla

bütün ışıklar sönmüşken', 'dayanamadı zincirlerini habire çekip durmaktan yaşanması güç hanın  kızıllığına aldırmadı günün serinliğine hiç doyamadı akşamleyin kaçan kı...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kara-biranda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudak Bükenlerin Vay Haline', 'dudak-bukenlerin-vay-haline-ali-kilic-kakiz-dbasg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uğrunda can verilen değerler,ecdadımızdan yadigâr,

Onlar sarsılmaz  kaynağa sarıldılar ecel gelene kadar.

Bundan öte yücelik, bunun ötesinde  makam olmaz.

Başlar dik gözler istikbalde,  yer gök titreyecek.

Ulu orta çifte atmak  bühtanda bulunmak, bitecek,

Dudak bükenlerin,buna cüret edenlerin vay haline.

Kalplerine zihinlerine,kilit vuranlar,ektiklerini biçecek,

Dünyada ki,saltanat günlerinin hesabını verecek.

''Ruhuna ahiret penceresini kapatmak  yakışmaz sana.

Brüksel /1991', 'Uğrunda can verilen değerler,ecdadımızdan yadigâr, Onlar sarsılmaz  kaynağa sarıldılar ecel gelene kadar. Bundan öte yücelik, bunun ötesinde...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dudak-bukenlerin-vay-haline-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Bize Acı', 'aci-bize-aci-baykal-kaanalp-a22b3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ne hissediyor bu kadar ağrı-sızı

kabına kulağımızı yapıştırmamızı

hiç önemsemiyor,hiç bakmıyor bile

gönderiyor bize başka bir kızı

aldatıyor bizi-kesmiyor hiç hızı', 'ne hissediyor bu kadar ağrı-sızı kabına kulağımızı yapıştırmamızı hiç önemsemiyor,hiç bakmıyor bile gönderiyor bize başka bir kızı aldatıyor...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/aci-bize-aci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Kaldın', 'yarim-kaldin-i-brahim-erkan-yesiltas-iu18m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçimde yarım kalan bir hayalsin sen! 

Yeşermek üzereyken solan çiçeğimsin.

Doğmak üzereyken batan güneşimsin.

İçimde yarım kalan bir özlemsin sen! 

Kana kana içemediğim pınarımsın.

Doya doya tadamadığım şarabımsın.

İçimde yarım kalan bir mevsimsin sen! 

Islanamadan dinen bahar yağmurumsun.

Kışın yağmadan eriyen karımsın.

İçimde yarım kalan okul yıllarımsın sen! 

Sıramın üstüne kazıdığım silik harflerimsin.

Sahibine gönderilemeden yırtılan aşk namelerimsin.

İçimde yarım kalan bir şiirsin sen! 

Nokta koyamadığım satırlarımsın.

İçimde yarım kalan diğer yarımsın sen.', 'İçimde yarım kalan bir hayalsin sen!  Yeşermek üzereyken solan çiçeğimsin. Doğmak üzereyken batan güneşimsin. İçimde yarım kalan bir özlemsi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Erkan Yeşiltaş']::text[], 8.5, '{"poet":"İbrahim Erkan Yeşiltaş","poet_slug":"i-brahim-erkan-yesiltas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yarim-kaldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakut', 'yakut-baykal-kaanalp-0go0w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'en büyülü yakut,en zorlu mekanda yetişir

talih sen istesende,istemesende gelişir', 'en büyülü yakut,en zorlu mekanda yetişir talih sen istesende,istemesende gelişir...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/yakut-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çakır', 'cakir-bekir-mutlu-gokcesu-7wtt3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hele bir sorun

Çakırı

Anlatsın onu size

Çıkmaz sokakları...

Önden, önden yürürdü

Delikanlılığı

Arkasına saklanırdı

Korkaklığı...

İstavrit akşamlarında

Yağmur yağardı o geçerken

Sevinçten parlardı

Arnavut kaldırımları...

Önce donuklaşırdı bakışları

Buz tutardı yüreği

Kadehinde

Sonra başlardı gülmeye

Aldıkca istimi

Uydurduğu hikayelerle

Herkes severdi çakırı

En çok da çıkmaz sokakları

Elleri soğan kokardı

Nefesi rakı...', 'Hele bir sorun Çakırı Anlatsın onu size Çıkmaz sokakları... Önden, önden yürürdü Delikanlılığı Arkasına saklanırdı Korkaklığı... İstavrit ak...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cakir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sefil', 'sefil-ferah-uslu-i4hyq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecelerin ıssız tenha saatlerinde

Bütün canlılar uyuyor  tatlı uykusunda

Yanlız uyumuyan canlı bir tek o vardı

Yüregindeki hicranla   her an ağlardı

Akan gözyaşları ve sonsuz bir hüsran

Bu acının içinde ruhsuz kalmış   bir insan

Hayat yolunda bitkin sürüklenmekte

Yorgun adımlarla sefil ilerlemekte

Meçhule  doğru yavaş yavaş gidiyor

O ilerledikçe ay bulutlara giriyor

Gittikçe gidiyor sahile yaklaşıyor

Gidiyor ve azgın dalgalara sefili çılgınca sürüklüyor', 'Gecelerin ıssız tenha saatlerinde Bütün canlılar uyuyor  tatlı uykusunda Yanlız uyumuyan canlı bir tek o vardı Yüregindeki hicranla   her an...', ARRAY['Türk Edebiyatı','Şiir','Ferah Uslu']::text[], 8.5, '{"poet":"Ferah Uslu","poet_slug":"ferah-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sefil-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var ya', 'var-ya-ferah-uslu-kjzuw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne çıkar yanlız kalsamda dünyada

Doğmadımmı anamdan yanlız Sensizlige yanacak köşem var ya

Ne çıkar sen yanımda olmasan

Yüreğimde gömülü sevdan var ya

Ellerimi ellerin tutmasın

Anılarla dolu sokaklar var ya 

Ömrüm sensiz geçecekmiş    geçsin

Dudaklarımda ismin var ya

Vücudumda filizlenmiş o yüce sevgin

Penceremde seni bekleyen hayalin var ya', 'Ne çıkar yanlız kalsamda dünyada Doğmadımmı anamdan yanlız Sensizlige yanacak köşem var ya Ne çıkar sen yanımda olmasan Yüreğimde gömülü sev...', ARRAY['Türk Edebiyatı','Şiir','Ferah Uslu']::text[], 8.5, '{"poet":"Ferah Uslu","poet_slug":"ferah-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/var-ya-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Yağmuru', 'kar-yagmuru-yavuz-agir-r5pxq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kar yağmuru yağar,

Gariplerin üstüne.

Seni sana bıraktım.,

Yağma demem üstüme.

Bulutlarla bir olursun,

Gökte yıldızları bulursun.

Tipi boran olursun,

Yağma,yağma demem üstüme....', 'Kar yağmuru yağar, Gariplerin üstüne. Seni sana bıraktım., Yağma demem üstüme. Bulutlarla bir olursun, Gökte yıldızları bulursun. Tipi boran...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kar-yagmuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve ben', 'sen-ve-ben-ferah-uslu-cfgfg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dilerim tanrıdan

Issız bir adada seninle yaşamak

Yapayanlız biz yeterdik birbirimize 

Sen ve ben

Dilerim tanrıdan 

Kumlar üstüne resmini çizmek

Ellerimle adını yazmak

İkimize ait bu dünyada

Sen ve ben

Beklerdim  dönüşünü balıktan büyük umutla

Özlemle boynuna atılmayı

Koşardık mutlu yuvamıza Sen ve ben', 'Dilerim tanrıdan Issız bir adada seninle yaşamak Yapayanlız biz yeterdik birbirimize  Sen ve ben Dilerim tanrıdan  Kumlar üstüne resmini çiz...', ARRAY['Türk Edebiyatı','Şiir','Ferah Uslu']::text[], 8.5, '{"poet":"Ferah Uslu","poet_slug":"ferah-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-ve-ben-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sondüş''e güzelleme', 'sondus-e-guzelleme-mutlu-ayar-x7rms', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hüzün kırması yazlardan

kalabalık sızması akşamlardan

sıyrılıp, kaderi göğe asılı yıldız gibi 

koynuna girmek usuldan 

tüm bunlardan arta kalan 

bir tek nem olmak vardı

gerdanından bir yılan gibi kıvrılıp

sapa göğsünden sızan

izlemek onları

denizlerde eskiyen martıları

kendinden esrik gülüşlerle

beni de büyüten zamanla

noktası eksik bir tek ünlemle seni

alın yazımdan kaydıran

güneşe doğru çeviren

doğurgan öpüşlerinin insancıllığını

bir çocukta duymak

sırt üstü yatan

her seferinde her yerde 

yalnızlık çökmüş karanlığa birden bire

en teni yağmur olup yağdırmak

kent ışıltılarının buğusundan

nesli tükenmiş sıcaklığı

kazıyarak eski resimleri, onları

tenimin antik mezarlarından

büyük aydınlığa çıkarmak

anılarca saklanan

-dokunuş, bitmeyen yokuş 

tensizliğim, çıplak terbiyesizliğim-

hiçbir yorgan örtemez üstünü 

ne de şiirlerin 

sevgili koynunda olmak -yalnızdüş- 

menekşelerini saklayan akşamın sonunda 

kefen ol gir koynuna, budur

sonsuz denilen öpüş

ölüm ki yaşayanlara yadırganan 

-sondüş- 

01:10', 'hüzün kırması yazlardan kalabalık sızması akşamlardan sıyrılıp, kaderi göğe asılı yıldız gibi  koynuna girmek usuldan  tüm bunlardan arta ka...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sondus-e-guzelleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın', 'kadin-gozem-basak-nnh31', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bir kadınım,

Duygulu, hassas, sevecen

Yeri gelir çok incedir ruhum

Ağlarım bir çiçeğin boyun bükmesine

Çok kolay mutlu olurum çocuk sesiyle

Neşelenir, güler, şarkı söylerim

Bir şarkının sözleri fırtınalar yaratır içimde

Hüzünleri hemen davet ederim

Okuduğum şiirlerde hep bulurum kendimi

Tanrı geri çevirmez insanlar için dileklerimi

Bazen de coşarım derin denizler gibi

Öfkelenir, kusarım içimde birikenleri

Güçlüyüm, mantıklıyım, cesurum

Kolay kolay yıkılmam kırılmasın onurum

Yüklediler omzuma çok ağır yükleri

Doğduğum ilk günden beri

Önce oldum ana babama evlat

Kuralları koyan onlar böyle yaşanacak hayat

Toplum çıktı sonra birden karşıma

O da kural koydu sakın ha karşı çıkma

Alıştım artık yadırgamıyorum

Evlilik kuralı kolay geldi zorlanmıyorum

Anne oldum hadiiii yeni kural

Severek kabullendim bu duygu çok kutsal

Gerek var mıydı bana kural koymaya

Kadın olmak suç mu bu dünyada

Aklım fikrim hepinizden çok benim

Eğriyi, doğruyu bende bilirim.

Koymasanız bu kuralları, güvenseniz kadına

Sizde mutlu olursunuz o da mutlu sonunda

Hangi canlı da var kadındaki özellik

Sevgi, şefkat, akıl, güzellik

Bakın artık bana farklı gözlerle

Güvenin zekama, aklıma, bilgime

Sadece doğurmak için gelmedim ki dünyaya

Yapacağım çok şey var inanın kadınlara

İncitmeyin yeter ki bedenimi, ruhumu

Kabul edin sizlerle eşit olduğumu', 'Ben bir kadınım, Duygulu, hassas, sevecen Yeri gelir çok incedir ruhum Ağlarım bir çiçeğin boyun bükmesine Çok kolay mutlu olurum çocuk sesi...', ARRAY['Türk Edebiyatı','Şiir','Gözem Başak']::text[], 8.5, '{"poet":"Gözem Başak","poet_slug":"gozem-basak","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/kadin-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yokum', 'sana-yokum-bekir-mutlu-gokcesu-0ew4f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu yakışıklılığım

En güzel bakışlarım

Burnumda tüten

Şu mis gibi kokum

Ne güzelim

Ne de hoşum

Neye yarar

Kendime çok

Sana yokum...', 'Şu yakışıklılığım En güzel bakışlarım Burnumda tüten Şu mis gibi kokum Ne güzelim Ne de hoşum Neye yarar Kendime çok Sana yokum......', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sana-yokum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötekiler', 'otekiler-yalcin-ulker-ji3ip', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlıkta kalmış adamlar

Karanlıkta kalmış kadınlar

İsterler,olmaz

İsterler,olmaz

İsterler,hiç olmaz

Şarampole yuvarlanmış hayatlar

Vazgeçenler,kaybedecek şeyi olmayanlar

Uzaya savrulmuşlar,sıkıntıya garkolmuşlar

Kırış kırış alınlar,soğuk donuk bakışlar

Ucube yazgılar,efsane yalnızlıklar

Büyükşehir engin deniz

Azgın plazalar,beyaz balinalar

Köpek balıkları,mutlu mesut yalaka yunuslar

Envai çeşit yaratık,derinlerde ta derinlerde

Balçıkta doğanlar,balçıkta ölenler

Karanlıkta kalmış adamlar

Karanlıkta kalmış kadınlar

Ana rahmi,Dostovesky,üçüncü sayfa

Köprü,köprüaltı,falez

Köprü,köprüaltı,falez





-', 'Karanlıkta kalmış adamlar Karanlıkta kalmış kadınlar İsterler,olmaz İsterler,olmaz İsterler,hiç olmaz Şarampole yuvarlanmış hayatlar Vazgeçe...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ülker']::text[], 8.5, '{"poet":"Yalçın Ülker","poet_slug":"yalcin-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/otekiler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Engel Kimde', 'gercek-engel-kimde-ahmet-hakan-yilmazturk-raouo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kabahatten büyük özrüm, 

dilemekle bitmiyor

ömrüme soğuk damga bu engel 

ha deyince silinmiyor

bazen doğmadan alna kazındı

bazen yaşarken bana, sana çarptı

parayla pulla onarılmıyor

atılmıyor, satılmıyor

ayan beyan ortadayım da

ahali farkına varamıyor

yok, yok, yok

bana kaldırım yok

bana rampa yok

karşıya geçmek yok

uygun tuvalet yok

yaşayacak ortam yok

yok da yok

var, var, var

dikkatli bakışlar var

acıma hissi yansıtan var

geçiş yolumda engel var

geçmiş olsun diyen var

sebebini soran var

var da var

çok, çok, çok

yapabileceklerim çok

halimi unutma isteğim çok

yaşama azmim çok

başarma yetim çok

sevgimse pek çok

çok da çok 

kalksa gönüllerden engeller

açılsa tüm kapılar birer birer

merdivenler önümde aksa

değişse toplumda zihniyet

ayan beyan ortada oluşumun

ahali artık farkına varsa…

kabahatinizden büyük özrünüz 

duyarsızlık çare olmuyor

gönlünüze soğuk damga bu engel, 

seyretmekle silinmiyor

bugün bana,sana, ona

yarın belki ağzı açık bakana

ateş düştüğü yeri yakacak

kana kana içilen sular

akmadan kuruyacak

03.12.2004', 'kabahatten büyük özrüm,  dilemekle bitmiyor ömrüme soğuk damga bu engel  ha deyince silinmiyor bazen doğmadan alna kazındı bazen yaşarken ba...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/gercek-engel-kimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonnet-Yıldızları anlamak', 'sonnet-yildizlari-anlamak-akin-akca-7p26a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'a.

Yıldızları anlamak, çatıya darağacına da çıktığında; 

masalın bebecik sorumlusu, insan olmanın ötesi.

Arkadaşı nitelediğini millet, bağrıcağzı kaynatmakta; 

biz aşkımızı devre dönem onunla yüceltmekte.

Birer balta, kanlı; mı yaprakların soluttuğu, kükreyen 

meltem esintisi şu yaprakların, hiç kıpırdamayan? 

Değil tabi ki, ama bir varil duruyor iğreti, yorulduğu

belli, ve sen yarım açıyorsun onun gürültülü kapağını..

dercesine: ''Bu çıkmaz, dışarı bu böcekler! ''

Değil mi; Tek penceresini şatonun dışarıya açık 

bırakmıştın? Ama döküverince kendini onlar,

iğrenç o sokağa; yeşil yapraklar işlerlik

      esas kazanmaya başlıyor. -ve düşün, sanma- hareket

      katarak kansı güllü baltalara da; senin 

      soluğuna, ordan da senindir bereket.

b.

Güçlenir sabit us, zeka kendine yön verdiğinde; 

yavaş ilerlediğimde, bir şey de anlamam tıpkı ben asla:

nasiplenmiş hiçbir kimsenin hızından, Tanrım kesme! 

Yalan yanlış nasiplenilenden, kırpılan, kat bari korkun''a; 

binicisinin zeki bir at, çayırlara olsa idi iyi sert bakışlı! ...

Pinokyo gibi uzuyor burnu sokak döşeyicisinin; 

ah! bir de bunlara tanık oluyor, gözün ucu-nakışlı:

sevgi bana akıyor; Sokakları bu sefer, sen görmüyorsun.

Açık gri derisi ve kaba bıyığı -sıra dışı- tozunu

anlatırsa bir kömürcünün, ütülendiğinde siyahın gergefi; 

sakalı da bıyığına karışmıştır artık ve kopkoyu-

sicim gibi, keşmekeş bir çilekeş derisinin onun rengi.

      Ne zaman genç iken dedim ki ''sevelim'', olarak fetus; 

      hep sevecen.. ulaşmıştı, ah; Shakespeare''den Tellus!', 'a. Yıldızları anlamak, çatıya darağacına da çıktığında;  masalın bebecik sorumlusu, insan olmanın ötesi. Arkadaşı nitelediğini millet, bağrı...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sonnet-yildizlari-anlamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir üçlemede yerküre hanedanlığı', 'bir-uclemede-yerkure-hanedanligi-akin-akca-wgnvh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yeryüzünden fışkırdılar yeraltından değil,

karınca gibi, sel olup. -sayıları çok olan.

Ve seddi kırıp geçtiler

tuğla diye bir şey kalmadı turuncu …

Dünya yüzeyini kapladılar yeryüzünden.

Öyle sinsi bir başkaldırı ki fark edilen; 

esas, 

siyah-sinsi geceler ışıldarken

Fırladı çıktı güruhlar, sarı sisi’nden 

Coleridge’nin alacakaranlığı içinden. Ve beyaz 

buğusu hareketsiz- modern camın; orada işte! 

yerini sağlamlaştırmakla meşgul yine de … 

Kuzeydeki ilginç birkaç cesaret türevi -

yerinde sayan -yine de gecenin 

içindeki sise hayran, ne var ki

tan ağarınca yaşamaya olanak bulan.', 'Yeryüzünden fışkırdılar yeraltından değil, karınca gibi, sel olup. -sayıları çok olan. Ve seddi kırıp geçtiler tuğla diye bir şey kalmadı tu...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-uclemede-yerkure-hanedanligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atıf-019-Rıfat Ilgaz Anısına', 'atif-019-rifat-ilgaz-anisina-vedat-koparan-33t1z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İş Kazası

-Denizden çıkan balık çırpınışı 

Suskusunda vurgun mavi 

Yerde yatıyor kan içinde kolu – 

Kasnak vurdu 

Kazaya kurbandı 

Aldı bir yanı 

Eksildi,sızladı her yanı 

Kaç düşüm kaç,böyle yandı 

Sarsam yari 

Kavuşmaz yollar sanki 

Yok ki bir yanı 

Utanır mı 

Yan yana yürüsün 

Taşısın bu eksik adamı. 

Vedat Koparan 28.11.2004 (01:18)   (Rıfat Ilgaz ustaya saygılarımla Alişim şiirinden öykünme)', 'İş Kazası -Denizden çıkan balık çırpınışı  Suskusunda vurgun mavi  Yerde yatıyor kan içinde kolu –  Kasnak vurdu  Kazaya kurbandı  Aldı bir ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/atif-019-rifat-ilgaz-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atıf-8(Adnan Yücel Anısına)', 'atif-8-adnan-yucel-anisina-vedat-koparan-b8b7j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kan Sızıyor Sarı Çiçek

-Acının Rengini Sordular 

Acıların Rengi Kurşunlar- 

Kurşuni sabahlar dizilirken 

Her acı kendi yuvasında yer eder 

Sevmek bizden öykünme bizden 

Vurulsak bir kez daha ne eder 

Öfke bileğin atar damarı 

Çiçekler vurgun kirli sarı 

Düşler Salı sabahına asılı 

Kırılgan çocuk ağlaması 

Bir kurşun hızında inerken gece 

Gözlerim kısmış ışığını pus çökende 

Al kanda ülkem akbabanın pençesinde 

Kimi uykuda kimi aşın peşinde 

Ah askerim kaç nöbetinde 

Her gece bir kurşun hızında 

Ayaz kış gecesi deler geçer içerimi 

Kanarım ben hep kendi kendime 

-''Acının Rengi '' 

Her Renk, Her Tende 

Dokun Hisset Sende - 

Vedat K 30.11.2004 (Acının Rengi -Adnan Yücel anısına saygı sevgimle)', 'Kan Sızıyor Sarı Çiçek -Acının Rengini Sordular  Acıların Rengi Kurşunlar-  Kurşuni sabahlar dizilirken  Her acı kendi yuvasında yer eder  S...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/atif-8-adnan-yucel-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kül Basım Acılar', 'kul-basim-acilar-vedat-koparan-tnbv1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-Yatağın kabul etmediği sızılarda 

Yeşil doğanın vurgusu gece ayakta 

Yunmaz gözler tutmayan uykularda - 

Bırakmayacak mı? 

Bu acılar 

Bu hüzünler 

Hep taşıyacak mıyız? 

Ah can ah 

Acın yüreğime ince bir sızı 

Yok işte elden gelmezlerde 

Aczinde olmanın acısı 

Kilitler 

Suskular 

Konuşur yürekte 

Gece ölüm sessizliğinde 

Bir can ağlar içimde 

Dostum sen diye 

Titrer yüreğimin tüm mazgalları 

Akan kan durur sanki donar kalır 

Bir sen 

Ah bilsen 

Hep ağlarım bilmenin sancısı 

Sen içimde ben sende 

Acılarını acılarıma kat 

Ben yanayım sahrada 

Batmasın gece karaları 

Sen uzan 

Doğan yeni gün ufkunda 

Aldım senden bana kalan kül basımlı acıları 

 23.11.2004 (04:40)', '-Yatağın kabul etmediği sızılarda  Yeşil doğanın vurgusu gece ayakta  Yunmaz gözler tutmayan uykularda -  Bırakmayacak mı?  Bu acılar  Bu hü...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kul-basim-acilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Degmedigini anladim', 'degmedigini-anladim-rengin-gardner-z1rpf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hosgorumun, ozverimin, 

Toz pembe hayallerimin,

Senli duygu dusuncelerimin,

Degmedigini anladim

Gelecegi umutlarla suslemistim

Kendimden cok sana vermistim

Karsiliginda hic birsey beklememistim

Degmedigini Anladim

Saniyormusun,

Sevdigim gibi seni sevecek

Hic birsey beklemeden, verecek

Yalniz seni  hayal edecek,

Umutlarini yarinlarla susleyecek.

Dilerim mutlu olursun, 

Cunku sen benim icin sonsun.

Sevmis olduguma pisman degilim,

Artik sevemedigime yaniyorum.

Bir soz vardi animsiyorum

Sevgi azalainca kusurlar artarmis,

Simdi seni daha acik secik goruyorum

Karsiliksiz sevmisligimemi yanayim, 

Hayatinda baska bir kadin oldugunami,

Gunlerce dusundum tasindim,

Senli bir dunyada yasamanin

Degmedigini anladim

Aralik 02 2004 aksam 10:10', 'Hosgorumun, ozverimin,  Toz pembe hayallerimin, Senli duygu dusuncelerimin, Degmedigini anladim Gelecegi umutlarla suslemistim Kendimden cok...', ARRAY['Türk Edebiyatı','Şiir','Rengin Gardner']::text[], 8.5, '{"poet":"Rengin Gardner","poet_slug":"rengin-gardner","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/degmedigini-anladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehr''i İstanbul', 'sehr-i-i-stanbul-canan-karadaglioglu-2-l9zp7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gece bambaşka şehr''i İstanbul

Kendimi sokaklara atasım gelir

Çılgınlar gibi şarkı söyleyip

Canımın yanına koşasım gelir

Yüreğimde pür neşe, başka heyecan

Seni canıma katasım gelir

Sabahlara kadar sana sarılıp

Birtanem, koynunda  yatasım gelir

Her geceden bir başka bu gece şehir

Gözlerime  durmadan gözlerin gelir

Tanrım bir yar, bu kadar, çok mu sevilir? 

o''nu yüreğime sokasım gelir

İstanbul dar geliyor bu gece bana

İçimden bir çılgınlık yapasım gelir

Bir kivilcim ask  atip bu koca sehre

Bu şehri ask ile yakasim gelir

Bu gece İstanbul az gelir bana

Seni arayıpta bulasım gelir

Atlayıp bir şahinin kanatlarına

Bu gece yanina uçasım gelir', 'Bu gece bambaşka şehr''i İstanbul Kendimi sokaklara atasım gelir Çılgınlar gibi şarkı söyleyip Canımın yanına koşasım gelir Yüreğimde pür neş...', ARRAY['Türk Edebiyatı','Şiir','Canan Karadağlioglu 2']::text[], 8.5, '{"poet":"Canan Karadağlioglu 2","poet_slug":"canan-karadaglioglu-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sehr-i-istanbul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer', 'eger-huseyin-erdogan-c0xpv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'her sabah gün doğunca

yüreğime bir umut düşer

öğle olunca

kaybolur birer birer

gün batınca

bir hüzün çöker içime

akşam karanlık bastırınca

göz yaşlarım akar kalbime

bir gün bana

yakışıklı şairim dersen eğer

bil ki 

yıllar katacaksın ömrüme

senin aşkınla yanmak

güzelmiş meğer

ne olur

hiç dokunma sevgime

seni uzaktan sevsem de

bu bana yeter

          03.12.2004', 'her sabah gün doğunca yüreğime bir umut düşer öğle olunca kaybolur birer birer gün batınca bir hüzün çöker içime akşam karanlık bastırınca g...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/eger-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Hatırlatma Sensizliğimi', 'bana-hatirlatma-sensizligimi-huseyin-erdogan-v312x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'rüzgarlar estikçe

kokun sarar bedenimi

sevgilileri

el ele gördükçe

hasretin yakar yüreğimi

ne olur sevdiğim

böyle susup susup da

bana hatırlatma sensizliğimi

                  03.12.2004', 'rüzgarlar estikçe kokun sarar bedenimi sevgilileri el ele gördükçe hasretin yakar yüreğimi ne olur sevdiğim böyle susup susup da bana hatırl...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bana-hatirlatma-sensizligimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler-3', 'guzel-sozler-3-huseyin-erdogan-r20zf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''Sen gülünce,Güneş doğar,aydınlanır her yer,ısınır dünya,sen yanımda yoksan eğer,gündüzler bile zindandan beter,ne olur sevdiğim,her sabah uyanınca,dön yüzünü benden tarafa ve gülümseyiver...''03.12.2004

''Rüzgarlara söyledim senin adını,her okşadığının kulağına fısıldasın,en yüksek tepelere yazsın,dağlara,taşlara kazısın diye,göreceksin dünya durdukça,bu emsalsiz aşkımız dolaşacak dilden dile...''03.12.2004', '''Sen gülünce,Güneş doğar,aydınlanır her yer,ısınır dünya,sen yanımda yoksan eğer,gündüzler bile zindandan beter,ne olur sevdiğim,her sabah u...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/guzel-sozler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gibi', 'gibi-canan-karadaglioglu-2-5agdf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gün, bulutlar arkadaş bana

Onlarda üzgün, yağacak gibi

Mevsim kışa döndü,her yer soğudu

Bulutlar güneşsiz kalacak gibi

Bulutların matemi vurunca suya

Mavinin rengi solacak gibi

Rüzgarlar yatınca derin uykuya

Denizler dalgasız kalacak gibi

,

Rüzgar unutmuş, şarkı söylemez

Sanki birisi,susturmuş gibi

Ağaçlar kurumuş, dallar kırılmış

 Kuşlar yuvasından  olacak  gibi

Rüzgar esmiyor, denizler suskun

Bulutlar umutsuz, güneşten yoksun

Kuşlar göçetmiş, bir de sen yoksun

Gözlerime yaşlar, dolacak gibi', 'Bu gün, bulutlar arkadaş bana Onlarda üzgün, yağacak gibi Mevsim kışa döndü,her yer soğudu Bulutlar güneşsiz kalacak gibi Bulutların matemi ...', ARRAY['Türk Edebiyatı','Şiir','Canan Karadağlioglu 2']::text[], 8.5, '{"poet":"Canan Karadağlioglu 2","poet_slug":"canan-karadaglioglu-2","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gibi-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırlar Yumağı', 'sirlar-yumagi-bayram-tunca-csxpp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir tohumda büyük bir orman gizli

En öldürücü varlıkta panzehir gizli

Bir damla pıhtıda nice hikmet gizli

Her varlıkta bin bir türlü sırlar gizli

Her insanda dünyanın fihristesi gizli

Her kalpte bir sevgilinin sevgisi gizli

Her şeyde bir hikmet var gizli mi gizli

Kainat Kitabında O’nun kanunları gizli

02.12.2004-12.02

Not:

Ne mutlu bu sırları vakıf olabilenlere', 'Bir tohumda büyük bir orman gizli En öldürücü varlıkta panzehir gizli Bir damla pıhtıda nice hikmet gizli Her varlıkta bin bir türlü sırlar ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sirlar-yumagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Let Yourself To Be Mine', 'let-yourself-to-be-mine-gulay-yildiz-rq83h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I feel 

this is the end of the time 

even 

I know, it can be the last day of my life 

Darling and darling 

to be center of attention; 

that is the aim of your life 

be mine, be mine and 

be center of my life... 

this is the aim of my presence... 

begining of December, 2004 

Gülay Yıldız', 'I feel  this is the end of the time  even  I know, it can be the last day of my life  Darling and darling  to be center of attention;  that ...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/let-yourself-to-be-mine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dikenli Kuvvetler İçinde Gülüm Kaldı', 'dikenli-kuvvetler-i-cinde-gulum-kaldi-yunus-guzel-b3lwv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıldızlar da kaçtı bu kentten,

Gökyüzünün içi boşaldı 	

Gölgelendi ışığı sokakların                          

Sokak lambaları yalnızlığa alışamadı

Doğrular yanlışlara karıştı,

Mevsime uydu düşünenler 

Sevdalar beyinlere yakınlaştı gülüm,

Sevdalar yürekten çok uzaklaştı

Kekik kokmaz oldu rüzgarlar

Yağmurlar kirlendi, 

Yapraklar hayata küstü

Toprak kokusu çocukluğumda kaldı

Bir gül kalmıştı değişmeyen,

Kendi gibi kokardı

Dikenli kuvvetler elinde tutsak şimdi

Kokusu  anılarımda saklı…', 'Yıldızlar da kaçtı bu kentten, Gökyüzünün içi boşaldı 	 Gölgelendi ışığı sokakların                           Sokak lambaları yalnızlığa alı...', ARRAY['Türk Edebiyatı','Şiir','Yunus Güzel']::text[], 8.5, '{"poet":"Yunus Güzel","poet_slug":"yunus-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dikenli-kuvvetler-icinde-gulum-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçlarıma Güney Rüzgarları Değdi', 'saclarima-guney-ruzgarlari-degdi-yunus-guzel-jr4av', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'saçlarıma güney rüzgarları değdi

sizin oralardan mı esti

ılıktı nefesin gibi

saçlarım sanki ellerindeydi

nağmeler fısıldadı esintiler

aşk şarkılarına benzerdi

yumuşaktı sesin gibi

mızrap sanki dilindeydi...', 'saçlarıma güney rüzgarları değdi sizin oralardan mı esti ılıktı nefesin gibi saçlarım sanki ellerindeydi nağmeler fısıldadı esintiler aşk şa...', ARRAY['Türk Edebiyatı','Şiir','Yunus Güzel']::text[], 8.5, '{"poet":"Yunus Güzel","poet_slug":"yunus-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/saclarima-guney-ruzgarlari-degdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susunca', 'susunca-omer-faruk-cakir-dr2vs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne vakit sussan,

Camdan bir anı kırılır içimde,

Parça parça düşer yüzün,

Ne vakit konuşsan,

Bir kalem elimde,

Resmini yazarım,

Ayyaş gecelere.

Ne vakit ağlasan,

Sırılsıklam olur sokaklar,

İliklerime kadar işler hüzün,

Kızıl bir ufka döner düşler,

Ne kadar gitsen, o kadar uzak,

Ay ışığında güzel her şey,

Güneş desen hiç doğmayacak.', 'Ne vakit sussan, Camdan bir anı kırılır içimde, Parça parça düşer yüzün, Ne vakit konuşsan, Bir kalem elimde, Resmini yazarım, Ayyaş geceler...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/susunca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimden tut', 'elimden-tut-omer-faruk-cakir-399r7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İşitmiyor musun sevgili? 

Çatırdıyor dünyanın iskeleti

Koş yoksa üstümüze yıkılacak,

Elimden tut, bırakma n’olur

Ne yapılacaksa şimdi yapılacak', 'İşitmiyor musun sevgili?  Çatırdıyor dünyanın iskeleti Koş yoksa üstümüze yıkılacak, Elimden tut, bırakma n’olur Ne yapılacaksa şimdi yapıla...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/elimden-tut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazgı', 'yazgi-omer-faruk-cakir-xnrwt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çok şey yazdım

sildim ne çok şeyi

Bir kaderi yazamadım

silemedim bir tek seni', 'Çok şey yazdım sildim ne çok şeyi Bir kaderi yazamadım silemedim bir tek seni...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yazgi-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan Şiiri *1*', 'hazan-siiri-1-tulay-sustam-yf3rf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen gül, sen gözyaşını bilme diye

sırtımda sana güneşi taşıyorum

öyle tenha, öyle ıssız ki sana geldiğim yollar

sana yakın bir çizgiye yaklaşıyorum 

ayaklarım mayına basmış misali... 

takılıyorum bir çakıl taşına sana göre kaya 

gözünde büyütme o kadar tökezliyorum sadece

düşüyorum...

bütün aydınlığımla dizlerinin dibine

sevdanın değil, senin önünde diz çöküyorum

sevda her yerde var... adamlık senin yüreğinde

ne desem boş, ne anlatsam yalan geliyor sana

karanlığını alıp gidiyorum...

sen hep gülümse... sevdama değil hayata...

24.11.2004 *en çok sevdiğim oyun çökertme çöktüğün gibi kalkıyorsun...*', 'sen gül, sen gözyaşını bilme diye sırtımda sana güneşi taşıyorum öyle tenha, öyle ıssız ki sana geldiğim yollar sana yakın bir çizgiye yakla...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hazan-siiri-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maskelerin yalanları', 'maskelerin-yalanlari-erol-sen-s423b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geçmiş dönemlerin maskeleri revaçta

Yüzler maske olmuş yaşama

Senmisin yalan yaptıkların mı? 

Kızarmayan yüzün hala gülüyorsa

Yaşam insana adanmış güzellikler

Aynaya bakmadınmı hala

Aynalar maskelere göstermez yüzünü

Mezarlar kabul etmez maskeli bedenleri

Güzel günümü beter etme git

Gün aydınlık güzel olacak yaşama

Sabah güneş doğacak yeni yaşamlara

Gri bulutlarını al da git sende kalsın

Yaşam elbet bitecek vadesin de

Hatıralar da yaşananalar da 

Kefenin cebi yok bedenlere

Sen de öğreneceksin......

03.12.2004', 'Geçmiş dönemlerin maskeleri revaçta Yüzler maske olmuş yaşama Senmisin yalan yaptıkların mı?  Kızarmayan yüzün hala gülüyorsa Yaşam insana a...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/maskelerin-yalanlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler-4', 'guzel-sozler-4-huseyin-erdogan-6lzkw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Mutluluk ve umutların, o güzel yüreğinizde, her sabah rengarenk çiçekler açmasını,her gün değişik kokmasını ve bir tek yaprağının bile ölünceye değin hiç solmamasını diliyorum...''18.03.2002

''Yılın dört mevsimi yaz olsa da gönlünüzdeki sevgi pınarının şırıl, şırıl akmasını hatta şelaleler gibi çağlamasını dilerim...''06.10.2003

''Kırlardaki,bahçelerdeki,balkonlardaki, saksılardaki ve o harika kalplerinizdeki bütün çiçeklerin günün yirmidört saati,yılın üçyüzaltmışbeş günü sevgiler açmasını istiyorsanız eğer, bir başkasını sevmeniz yeter...'' 03.12.2004', '''Mutluluk ve umutların, o güzel yüreğinizde, her sabah rengarenk çiçekler açmasını,her gün değişik kokmasını ve bir tek yaprağının bile ölün...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/guzel-sozler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklara Armağan', 'cocuklara-armagan-mehmet-isikoglu-965lj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'TEMİZLİK

Ben çevremi kirletmem,

İnsanları terletmem,

Temizliği severim,

Bu fikrimi körletmem.', 'TEMİZLİK Ben çevremi kirletmem, İnsanları terletmem, Temizliği severim, Bu fikrimi körletmem....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cocuklara-armagan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Diyemem Yokluğuna-II', 'sevda-diyemem-yokluguna-ii-ugur-deniz-ulkegul-es2gc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her taşın altına baktılar…

Her ağaç gölgesini,her kuytu sokak köşesini aradılar…

Sahil boylarını,deniz dalgalarını aydınlattılar…

Yetmedi ışıkları..Bulamadılar…

Küçük bir çocuğun gözlerine saklanmıştım..

Bilge bir ihtiyarın sözlerine..

Biraz daha dikkatli baksalardı yüzlerine,tanıyacaklardı..

Anlamadılar….

Her gün yollarda ölüyordum oysa..

Bazen, sarhoş bir otobüs şoförünün getirdiği 

Yol Kavşağında..

Ya da bir zengin züppesinin hız tutkusunda…

Yoksulluğumun üstünde kalırken lastik izleri,

Ölüyordum ansızın…

Ve sesim bile duyulmuyordu çoğu zaman..

İnsanlar aynı adam sanıyordu belki haber bültenlerine çıktığımda…

Aynı çocuk..Aynı kadın…

Kış bastırıyordu memleketimde,

Altı aylığına hapsediyordu kendini koca bir şehir..

Yolları kar döşeli “ücra” köşelerde,

Mahrumiyet içinde kalan mahrem bir seyir....

Sabır öğretilmişti bize…

Tevekkül’ü böyle anlamıştık..

Hayat devam ediyordu…Ve ben ölüyordum…

O gün…Birlikte ağlamıştık….

Sonra bir köy kahvesinde,

Bir Ramazan arifesinde,

Müjdeli haberimi veriyordu bir çocuk…

Doğmuştum işte…

Yine en baştan öğrenmek için her şeyi..

Korkuyu,Cesareti,Hüznü,Sevinci..

Ama önce,biraz hasta olmalıydım..

Babamın ilaç almaya,

Hükümetin doktor göndermeye mecali yoktu ya..

Olsundu..

Ölmeye alışkındım ben..

Doğmama alışkın olduğunuz gibi..

Doğunca küçük Mehmet,

Yaşarsam aslan Mehmet,

Yaşlanırsam Mehmet ağa olacaktım..

Mehmet olmak kolaydı da,

”Ağa” olmak herkesin harcı değildi..

Zaten ”Ağa”larda 

“Mehmetçik”lerden pek çıkmıyordu…

Mehmet’in öğretmeni yoktu..

Mehmet’in okulu yoktu…

Ölüp gidivermek en kolaydı bu ülkede Mehmet için..

Ama yaşamak…Zordu…

Ben anladım lakin onlar,hiç anlamadılar…

O kadar çoktu ki bu ülkede Mehmet,

İstediğin zaman,istediğin kadar bulabilirdin..

Ama o kadar çok..O kadar çoktu ki..

Aradığın Mehmet’i bulabilmek büyük meseleydi..

Yanlış Mehmet’i yakalayıp,tutabilirdin..

Mehmet diye aradığın,

Bakıyorsun Yakup oluyordu kimi zaman,

Bazen de sokaklarda tek başına

Yusuf diye dolaşıyordu…

Hele bir de Ayşe olmuşsa 

Ya da Elif..Ya da Gülşen..

Çık çıkabilirsen işin içinden…

Hepsi birbirine karışıyordu…

Bulmanın böylesine zor,

Böylesine çetrefilli bir iş olduğu yerde,

Nasılda kolay rastlamıştım sana…

Ve nasıl da kolay yitirmiştim…

Hani “Eskidenmiş o sevdalar” diye 

Söyler dururdu o yüreksizler ya..

Bense sanki meydan okur gibi alaycı sözlerine,

İnadına sevmiştim..

Bu ölüp gitmeler arasında,

Kavgalar ortasında…

Firari kaçışlar molası,

Eğreti kurulmuş bir fakir sofrası,

Hapishane voltasında..

Dostlukların az bulunduğu,

Soysuzluktan haz duyulduğu,

Derme çatma düşler arasında 

Yalanların baz alındığı,

Çocukların alınıp,

Genç kızların satıldığı kahpelikler dünyasında..

Unutmalı değil miydim seni….

Yeni bir başlangıç noktası bulup hayatın bir yerinden..

Yani bir başka sen..

Bir başka yol tesadüfü,bir başka rastlantı.

Bir başka bakıp,bir başka gülen…

Öylesi bir bakış işte..Sıradan..

Ya da yol üstü bir kaldırım sohbeti,

Geçerken verilen bir selam..

”Sen” oluyorsun…

Bu sokaklar,ben ölmeden kaybetmeyecek izini..

Bahar geliyor ağaç dallarına,yeşile sevdalanıyor toprak..

Ve her yağmur sonrasında “Sen” kokuyorsun…

O kadar yoksun ki yanımda,

Senden ibaret kalıyor yalnızlığım…

O kadar yoksun ki 

Seni hatırlatıyor bütün var kıldıklarım..

O kadar yoksun ki anılarım…Umutlarım..Yarınlarım..

Unutmalı değil miydim seni..

Bir paket sigara molasında,sen tüttün yine dumanımdan..

Ölümcül nefes çekişlerim bu yüzden…

Şimdi..Mehmet olmaya gidiyorum biraz…

Ayşe kal sende..Ya da Elif…Ya da Gülşen..

Zaten hiçbir zaman 

İnanmadım kaybolduğuna..

Sensiz zamanlarda yol alışlarım sana..

Senin yüzünden..

Ama yine de gülüm..

Acıtırken gülüşün yüreğimi,

Unutma giderken söylediğimi..

Sevda diyemem yokluğuna….', 'Her taşın altına baktılar… Her ağaç gölgesini,her kuytu sokak köşesini aradılar… Sahil boylarını,deniz dalgalarını aydınlattılar… Yetmedi ış...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":111,"source_url":"https://www.antoloji.com/sevda-diyemem-yokluguna-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğluma', 'ogluma-mehmet-isikoglu-ukyzb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Almanyadan,Türkiyede okuyan oğluma:

OĞLUM REŞAT! 

Sınıflar hayatın merdivenleri

Doruğa çıkmaya bağla emeli

Gitmesin ettiğin emekler boşa

Sağlam kurmaya bak esas temeli

Bilimdedir gücün olan kaynağı

Dal git derinlere geniş tut ağı

Ver hakkını yaşadığın günlerin

Yakala içinde yaşanan çağı

Üzülme anadan ayrıyım diye

Vefalıdır ana kadar Türkiye

Herkes senin kadar olamaz şanslı

Kavuşturdu seni o Erdemli ye

Çocuklukta derdi derde katmayan

İsyan eden,hoca sözü tutmayan

Ayrılığın acısını tatmayan

İstikbalde adam olup gülemez.', 'Almanyadan,Türkiyede okuyan oğluma: OĞLUM REŞAT!  Sınıflar hayatın merdivenleri Doruğa çıkmaya bağla emeli Gitmesin ettiğin emekler boşa Sağ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ogluma-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıma!', 'kizima-mehmet-isikoglu-95rot', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'KIZIMA! 

Yavrum büyüdün bak güzel bir kızsın

Gülen parıldayan yerde yıldızsın

Dikkat et kendine söndürmesinler

Ergin oldun artık  korumasızsın

Yaşıyorsun  asrın en güzelinde

Özgürlüğün sonsuz kendi elinde

Unutma bizdeki gelenekleri

Güzelliğin destan dostlar dilinde

Altın gibisin  pul olup atılma

Layıkın olmayan yere katılma

Taşıdığın değerin bil  kadrini 

Danış mantığına hisse kapılma', 'KIZIMA!  Yavrum büyüdün bak güzel bir kızsın Gülen parıldayan yerde yıldızsın Dikkat et kendine söndürmesinler Ergin oldun artık  korumasızs...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kizima-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz', 'goz-ahmet-kurt-smrxs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu yeşil önlüklü adamlar,

Seyrekte olsa,

Soğuk duş etkisinde karşılaştığım,

Sıcak,

Ilık nefesleri ile rahatladığım,

Yeşil önlüklü insanlar...

Yeşil bir sedyeye yatırdılar,

Parlak ışıklar alıyordu gözümü,

Zaten gördüğüm de 

Sadece ışıklardı,

O taraftan...

Fazla uzun  sürmedi,

Sihirli ellerin dokunuşu,

Buram buram terledim,

Nefes alışım zorlaştı,

Telaşlandım bir an...

Çok da hevesli değilim oysa,

Dünyanın pisliklerini,

Basit hesapların sonuçlarını,

Güçlünün mazlumu ezişini,

Acımasızlık ve barbarlığı 

Seyretmeye... 

Güzelliklerden geçtim,

Onu görenler görsün,

Çünkü mücadelem,

Olumsuzluklarla,

Kavgam haksızlıkla benim. 

Yoksa! ...

Gözlerimden vaz geçip,

Diğerini de kapatmalı,

Hatta 

Kulaklarıma da 

Tıkaç taktırıp,

Hiç bir şey duymasaydım,

Birçoklarının yaptığı gibi,

Rahat eder miydim...', 'Şu yeşil önlüklü adamlar, Seyrekte olsa, Soğuk duş etkisinde karşılaştığım, Sıcak, Ilık nefesleri ile rahatladığım, Yeşil önlüklü insanlar.....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/goz-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Geç Kaldın', 'cok-gec-kaldin-tayyip-sag-8lhyq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben bir ömrün ardından,

Baka kalmışım,

Sen şimdi geriye dönüp,

Gelsende hoş gelmesende.

Şu sahte insanları,

Sahte sevgileri,

Tanıdım sanmıştım,

Demek ki tanıyamamışım,

Yüreğim nasırlaştı,

Sen şimdi geriye dönüp,

Gelsende boş gelmesende.

Sevgi ağaçlarım kurudu,

Güllerim soldu artık,

Maziye sayfa sayfa,

Ne göz yaşı,

Ne hüzünler bıraktık,

Acıları ilaç yaptık,

Bir umut bir çare aradık,

Fakat çok geç kaldın sevdalım,

Sen şimdi geriye dönüp,

 Gelsende hoş gelmesende,

Sen zaten bendesin,

Ben unutmadım ki seni,

Çünkü,

Sen benim liseden aşkımsın.

03.12.2004', 'Ben bir ömrün ardından, Baka kalmışım, Sen şimdi geriye dönüp, Gelsende hoş gelmesende. Şu sahte insanları, Sahte sevgileri, Tanıdım sanmışt...', ARRAY['Türk Edebiyatı','Şiir','Tayyip Sağ']::text[], 8.5, '{"poet":"Tayyip Sağ","poet_slug":"tayyip-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/cok-gec-kaldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deyişler (2)', 'deyisler-2-murat-nail-guney-76g6j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dost elinden bade içip, mest olmadan gülünür mü,

Sılaya düşmeden ey dost, vatan kadri bilinir mi,

Yakmadan bağrını ateş, suya hasret kalınır mı,

Can evimden koptu canım, elin dilinden-dilinden...

Yar koynunda açan gülün, kokusuna doyulur mu,

Çiçek dalında sevilir, koparmaya kıyılır mı,

Mecnuna benzemeyince, aşık, aşık sayılır mı,

Aşığa cennetin yolu, geçer sevdanın yolundan...

Aşk ile öterken bülbül, seherde gül derilir mi,

Dost hatırın sormayana, kuru selam verilir mi,

Gönül hasretlik çekmeden, mutluluğa erilir mi,

Kıymetini bilen anlar, gönül balından, balından...

Yunus’ a çeksin yüreğim, Mevlam, kabul et dileğim,

Ferhat nice dağlar aşmış kavuşmamış bencileyin,

Hep mazlum mu yerde kalır, adalet bu mu söyleyin,

Zalime gönül vermesi, beter ölümden, ölümden...

Muradım, dertli ozanım,sevdaya ağıt yazanım,

Evliya Çelebi gibi, hep diyar-diyar gezenim,

Baharlarım heba oldu, ömürde kaldı hazanım,

Esme ayrılık rüzgarı, düşer yaprağım dalımdan...

03/12/2004  Murat Nail Güney   Bodrum', 'Dost elinden bade içip, mest olmadan gülünür mü, Sılaya düşmeden ey dost, vatan kadri bilinir mi, Yakmadan bağrını ateş, suya hasret kalınır...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/deyisler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Petrolün Ve Paranın Kiri', 'petrolun-ve-paranin-kiri-zeki-ergin-s6j3i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'petrolün paranın kiri bulaştı 

ellerine 

görünmez oldu başka şey gözlerine

yitirdi aklını sermaye

değil vermeye

almaya geldiler

bu kiri temizleyemez

hiçbir zaman Dicle Fırat

her an yiyecekler suratlarına

insanlıktan tokat

_erenköy 3ara04

_dağlara ver sırtını yt:haz09', 'petrolün paranın kiri bulaştı  ellerine  görünmez oldu başka şey gözlerine yitirdi aklını sermaye değil vermeye almaya geldiler bu kiri temi...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/petrolun-ve-paranin-kiri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deyişler (3)', 'deyisler-3-murat-nail-guney-bd1c1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün buralara yolun düşerse,

Gün batımlarında beni hatırla.

Senin de yüreğin incitirlerse,

Kaş çatışlarında beni hatırla...

Solmadıysa hala mor menekşeler,

Suyunu dökerken beni hatırla,

Ay ışığı pencerene yansıyıp,

Hüzünle bakarken beni hatırla...

Sakladın mı siyah beyaz resmimi,

Albümden çıkarsa beni hatırla.

Meleklere emsal güzel yüzüne,

Çizgiler çökerse beni hatırla...

En sadık sevgili yalnızlığımız,

Canını sıkarsa beni hatırla.

Sevdama değişip, senin sevdiğin,

Sevmekten bıkarsa beni hatırla...

Muradım, sevdanı asker eyledin,

Firarda yakarsa beni hatırla.

İhanet kurşunu, tam can evinden,

Vurur da yıkarsa beni hatırla...

03/12/2004  Murat Nail Güney       Bodrum', 'Bir gün buralara yolun düşerse, Gün batımlarında beni hatırla. Senin de yüreğin incitirlerse, Kaş çatışlarında beni hatırla... Solmadıysa ha...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/deyisler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '//Sayende//', 'sayende-alpaslan-yigit-x9csq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir çöle düştüm 

Güneş tepemde

Etrafta ateş gibi kumlar

Tepeler aşıyorum,aşıyorum

Ardı arkası bitmiyor

Ayaklarım bata çıka gidiyorum

Zamana karşı bir yarış bu

Yönüm ne taraf ben neredeyim? 

Burada ne işim var? 

Kurtulacakmıyım? 

Yoksa bu sonsuzlukmu benim sonum? 

Sorular,sorular,sorular

Bilincim kayıp

Bedenim zayıfken

Tam vazgeçmişken herşeyden

Ve tam bırakıyorken kendimi

Bir Serap gibi çıktın karşıma

Nereden geldin prensesim

Nasıl buldun beni

Gücüme güç geldi sayende

İçime umut

Kapanmaya yüz tutmuş gözlerim

Güldü yeniden seninle

Ne yakıcı kumlar umurumda

Ne gökteki güneş

Varsın uzak olsun kurtuluş

Dayanırım seninle

Hoşgeldin gönlüme,Şeref verdin

Kendimi buldum sayende.............', 'Bir çöle düştüm  Güneş tepemde Etrafta ateş gibi kumlar Tepeler aşıyorum,aşıyorum Ardı arkası bitmiyor Ayaklarım bata çıka gidiyorum Zamana ...', ARRAY['Türk Edebiyatı','Şiir','Alpaslan Yiğit']::text[], 8.5, '{"poet":"Alpaslan Yiğit","poet_slug":"alpaslan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sayende-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmadım', 'unutmadim-ali-gencay-g4zw6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hüznü senden sonra sevdim

avunamadım

yaşayan oldum

yaşattın

acıyı senden sonra buldum

unutmadım

yokluğunda

çocuklar gibi pustum 

göz yaşlarımı gizledim

yağmurlar yağarken ağladım

yalnızlığı senden sonra buldum

unutmadım

aç avuçlarını 

bak! 

neyin kaldı? 

göz yaşı mı? 

Hüzün mü? 

ne kaldı sevginden sana? 

unuttun! 

unutmadım

halen yoksun

şimdi

gününü gün eden utansın

ağlarım,utanırım da

hazan yağmurları yağsın

seni senden sonra buldum

o yüzdendir 

unutmadım', 'hüznü senden sonra sevdim avunamadım yaşayan oldum yaşattın acıyı senden sonra buldum unutmadım yokluğunda çocuklar gibi pustum  göz yaşları...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/unutmadim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yansımalar', 'yansimalar-cigdem-bir-genc-mivmb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmurlar büyütüyorum bulutmuşçasına

Ve şiirler kutsal bir nehir  oluveriyor döşümde

Yıkanıyor  günahlar çırçıplak...

Yıkılıyor  kaleleri zamanın...

Yıkılıyor  taht kurduğun sırça köşkler bir gecede! 

son kullanma tarihi geçmiş düşlerimi toplayıp çöpe attım bu sabah

çiçeği burnunda bir günü kokladım derinden

koşarak geldi bir çocuğun yüzü...

baktım ki gelen...

ben...', 'Yağmurlar büyütüyorum bulutmuşçasına Ve şiirler kutsal bir nehir  oluveriyor döşümde Yıkanıyor  günahlar çırçıplak... Yıkılıyor  kaleleri za...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yansimalar-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzindeyiz! !', 'i-zindeyiz-zulfikar-yapar-kaleli-og0ug', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '*

İzindeyiz ara sıra 

Işıyoruz hasbelkader. 

Gün bulanık, sevda kara 

Taşıyoruz hasbelkader. 

Bilinmeze yelken açtık, 

Gelinmeze doğru uçtuk, 

Dostu kovduk, aşktan geçtik, 

Coşuyoruz hasbelkader. 

Günah sevapları gömer, 

Feryatlara katmer katmer! 

Aklı yutar, ruhu emer, 

Şaşıyoruz hasbelkader. 

Ders alırız bazı bazı! 

Bağrımızda milli sızı! 

Hasret tavşan, arzu tazı, 

Yaşıyoruz hasbelkader. 

Yırtık bohça, delik havuz, 

Atı aksak, iti yavuz, 

Lâl haberci, kör kılavuz,

Koşuyoruz hasbelkader. 

Ey Allah’ım bu nasıl kör, 

Kucaklamış gözünü yer! 

Ve işte hak güme gider, 

Düşüyoruz hasbelkader...', '* İzindeyiz ara sıra  Işıyoruz hasbelkader.  Gün bulanık, sevda kara  Taşıyoruz hasbelkader.  Bilinmeze yelken açtık,  Gelinmeze doğru uçtuk...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/izindeyiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne Şiirleri -2-', 'anne-siirleri-2-evren-dalgic-a8oxd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yudum yudum yalnızlık içiyorum,

Uyku girmiyor ürkek gözlerime,

Çaresiz bir sağa,bir sola dönüyorum

Uykusuzum bu aralar uykusuzum anne.

	

Denize düşmüş yüzmez gibiyim,

Yanıp da sönmüş küller gibiyim,

Esip de dinmiş rüzgar gibiyim,

Durgunum bu aralar durgunum anne.

Sen yoksun ya sanki küsmüş dünya,

Geceler liman olmuş,gözlerim derya

Sönmüş yüreğimde o tertemiz hülya,

Yorgunum bu aralar,yorgunum anne.

Ötesi gözükmez sisler gibiyim,

Kimseyi tanımaz eller gibiyim,

Teselli verilmez dertler gibiyim,

Solgunum bu aralar,solgunum anne.

Birbirine bağlanmış umutsuz günler,

Yerlere saçılmış bin bir hevesler,

Üzerime kapanmış sanki kafesler,

Zindanım bu aralar,zindanım anne.

Ölse de tanınmaz kim’ler gibiyim,

Bir kere anılmaz sözler gibiyim,

Atsan atılmaz bir can gibiyim,

Yalnızım bu aralar,yalnızım anne.

(Ankara Kasım 2004)', 'Yudum yudum yalnızlık içiyorum, Uyku girmiyor ürkek gözlerime, Çaresiz bir sağa,bir sola dönüyorum Uykusuzum bu aralar uykusuzum anne. 	 Den...', ARRAY['Türk Edebiyatı','Şiir','Evren Dalgıç']::text[], 8.5, '{"poet":"Evren Dalgıç","poet_slug":"evren-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/anne-siirleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güldamlası ve Aşkdamlası - I -', 'guldamlasi-ve-askdamlasi-i-gulsen-senderin-dc5vm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ve yıllardan sonra bir günbatımı yanarken

Ateşleri yara yara ona gidiyorum

Göğsüme sığmayan kalbim sanki ateş kuşu

Aşk; zamana inat sevgiye kanat çırparken

Ben O Zümrüt-ü Anka kuşuna gidiyorum...

İşte karşımde mahzun, sıcacık gülümsüyor

Taparcasına, ellerine asılıyorum

Bakımlı, gül kokulu yumuşacık iki el

Bakışlar tutuşurken, bedenlerimiz üşüyor

Bir volkana akarak ona sarılıyorum...

Alev topu gözleri, yakıyor köz köz

Parmaklarının ucunda yükselerek ilk kez

Dudaklarıma gömülüp çılgınca öpüyor

Kollarımın arasında; nice yarınlara

Ve nice güneşli baharlara haykırıyor...

Kuğulu Park''a doğru kol kola yol alırken

Yasemen kokan uzun saçları, rüzgarda

Delirten bir tutkuyla yüzümü okşuyordu

Banka oturduk, mimozalar bizi saklarken

Duygularımız farklı dilden konuşuyordu...

Hatırlar mısın ''Güldamlası'' otuz yıl önce

Seninle yine burda buluşmustuk gizlice

Evet ''Aşkdamlası'' sınıfın bir maç günüydü

O gün öpmene izin vermemiştim, aptalca

Ah o zaman geri gelir mi, mümkün mü sence...

Mehtap ve yıldızlar kaybolana dek oturduk

Neler konuşmadık ki gün ağarıncaya kadar

Bizi ayıran düzeni, kavuşturan ortamı

Yaşanmış bir yaşamdan; yaşanmamış bir yaşamı

Kalp kalbe, aşk aşka doyana kadar konuştuk...

Hadi diye fısıldadı, yeniden öperek

Gitmeliyim artık, ben çağırana dek bekle

Hazır ol benim için, aşka sevgiyi yükle

Ve beni bekle...O yeşil gözlerde erirken

Ayrıldım yanından; hıçkırığımı tutarak...', 'Ve yıllardan sonra bir günbatımı yanarken Ateşleri yara yara ona gidiyorum Göğsüme sığmayan kalbim sanki ateş kuşu Aşk; zamana inat sevgiye ...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/guldamlasi-ve-askdamlasi-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felsefe', 'felsefe-melih-cevdet-anday-u6o6k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Köle sahipleri ekmek kaygısı çekmedikleri için felsefe yapıyorlardı, 

Çünkü 

Ekmeklerini köleler veriyordu onlara; 

Köleler ekmek kaygısı çekmedikleri için

Felsefe yapmıyorlardı,

Çünkü 

Ekmeklerini köle sahipleri veriyordu onlara.

Ve yıkıldı gitti Likya.

Köleler felsefe kaygısı çekmedikleri için ekmek yapıyorlardı,

Çünkü 

Felsefelerini köle sahipleri veriyordu onlara; 

Felsefe sahipleri köle kaygısı çekmedikleri için ekmek yapmıyorlardı,

Çünkü 

Kölelerini 

Felsefe veriyordu onlara.

Ve yıkıldı gitti Likya.

Felsefenin ekmeği yoktu,

Ekmeğin felsefesi. 

Ve sahipsiz felsefenin ekmeğini,

Sahipsiz ekmeğin felsefesi yedi. 

Ekmeğin sahipsiz felsefesini 

Felsefenin sahipsiz ekmeği. 

Ve yıkıldı gitti Likya. 

Hala yeşil bir defne ormanı altında...', 'Köle sahipleri ekmek kaygısı çekmedikleri için felsefe yapıyorlardı,  Çünkü  Ekmeklerini köleler veriyordu onlara;  Köleler ekmek kaygısı çe...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih-cevdet-anday","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/felsefe-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güldamlası ve Aşkdamlası - II -', 'guldamlasi-ve-askdamlasi-ii-gulsen-senderin-ctrd4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çiçeklerin mis kokularla açtığı birgün

Cep telefonum çaldı, Güldamlam ''Gel'' diyordu

Kalbimdeki coşkuyla, içim biraz tedirgin

Sevdiği o ''Sarı Güllerle'' evine gittim

Yeni doğmuş güneş gibi, beni bekliyordu...

Mimozalarla çevrili bahçede oturduk

Çardağın altında keten örtülü bir masa

Gül desenli porselen fincanlarda çay içtik

Eller kilit gözler kilit kalpler taşa taşa

Bakışların yangınında kendimizden geçtik...

Akşam çöküşü; ufuklar yeniden yanıyor

Dalgaların kıyıya vuruşu, pembe beyaz

Denizi dinlememi söyleyip eve girdi

Onu beklerken içim sızlıyor sanki kanıyor

Ah bir de başarsaydım, sakin olmayı biraz...

Sade bir salona geçtik, mumlar ışıl ışıl

Balık salata beyaz şarap...Ve tatlı yedik

Kahveler içildi, bakışırken yeşil yeşil

Boynundan öpüp usulca halıya yatırdım

Dili alevdi sanki, saatlerce üpüştük...

Dudakları dudaklarımda ayağa kalkıp

Gözleri gözlerimde -artık seninim- dedi

Sabrımı ölçercesine odasına geçti

Yüreğim bir nehir kıvrılışı gibi coşup

Deltasına akmak isterken -gel aşkım- dedi...

Özenle sevişmeye hazırlanmış bir oda

Çarsaflar saten, gül yapraklarla bezeli

Henüz yeni açmış tutku kokan yasemenler

Yastıkta, ismimizin baş harfine dizili

Kanımda lavlar, arzın merkezinden taşmakta...

Duman duman yanan tütsüyle egzotik bir müzik

Yere inen sabahlığın altında bir mabet

Kucağıma alıp yatağa kadar taşıdım

Şeffaf giysisi altında göğüsleri dimdik

Vücudu Kibele''den bereketli ve kıvrak...', 'Çiçeklerin mis kokularla açtığı birgün Cep telefonum çaldı, Güldamlam ''Gel'' diyordu Kalbimdeki coşkuyla, içim biraz tedirgin Sevdiği o ''Sarı...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/guldamlasi-ve-askdamlasi-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-necat-necdet-demircan-44l5p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen ve Ben

En mutsuz günlerimizde bile şen

Sen ve Ben

Habersizce kapıları çalan deli bir rüzgar

Hırçın, estikçe esen...

Anlaşmakta pek zorluk çekmeyen

Görünürde çılgınlar gibi birbirini seven

Sıradan iki insan işte

Sen ve Ben...

Batsa da dünya şimdiden

Yıkılsa bütün dağlar, 

isimlerini ova olarak değiştirseler

Yıkılmayan bir sevgi

Ne söylenebilir ki

Yaşam kadar sıradan

İki öylesine insan

Hayalde kaldı

Sen ve Ben...', 'Sen ve Ben En mutsuz günlerimizde bile şen Sen ve Ben Habersizce kapıları çalan deli bir rüzgar Hırçın, estikçe esen... Anlaşmakta pek zorlu...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-ve-ben-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokakta Bir Çocuk', 'sokakta-bir-cocuk-i-brahim-duskun-h34ue', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'titriyorsun

üşüyorsun

yalnızsın

bir başınasın

hayat öyle nasıl bir şey 

yuvasız kuşlar gibi

soğuk,ıssız sokaklar

yer döşeğin olmuş

gök yorganın

halini soranın var mı senin

bak gözlerin

bakar durur gözlerin

nasılda anlıyorsun

bir baba tutunca elini çocuğunun

öfkelisin biliyorum

bu kent erken büyütmüş seni çocuk

daha nazlanmadan

daha sevilmeden

saçların okşanmadan

öyle kırıp dökmeden

ninnilerle uyumadan

yaşam nasılda tersinden çalmış kapını 

kapısıda yokki bu sokakların

apaçıktasın

bak yine zemheri

gören, soran var mı seni

adını bilenin bile yok

koymuşlar adını ya tinerci

yada  sokakta serseri

ötesini soran yok

ötesini bilende yok

sen neden buradasın çocuk

neden

nedensiz değil elbet

böyle yaşamdan kopuşun

bak gözlerin ışıl ışıl

bu kent erken büyütmüş seni çocuk

öyle hemencecik büyüme sen', 'titriyorsun üşüyorsun yalnızsın bir başınasın hayat öyle nasıl bir şey  yuvasız kuşlar gibi soğuk,ıssız sokaklar yer döşeğin olmuş gök yorga...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Düşkün']::text[], 8.5, '{"poet":"İbrahim Düşkün","poet_slug":"i-brahim-duskun","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sokakta-bir-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşün', 'dusun-necat-necdet-demircan-9ym5m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok uzun gibi görünen bu zalim zaman

Hani bazen olur ya; 

Geçmeyen saatler

Bitmeyen yollar

Tükenmeyen dertler

Değil midir kısacık bir an...

Bir ömür ışığı yanan insanın içinde

Belki aşk sarhoşluğu zamansız ağlatan

Tatlı mı tatlı hayaller

Daha neler neler

Değil mi aslında hepsi yalan...

Dün bitti

İşte bugün

Yapılan çılgınlıklar

Varsa geride kalan

Sevgililer

Ağaç bekleyişleri saatlerce

Düşün, düşün, düşün, bir kere daha

Çıkamazsın bir türlü işin içinden

Düşün, 

Çarp, böl ya da topla

Bir daha düşün

Sonuç oldukça boş bir şey; 

''Hey gidi günler hey...''', 'Çok uzun gibi görünen bu zalim zaman Hani bazen olur ya;  Geçmeyen saatler Bitmeyen yollar Tükenmeyen dertler Değil midir kısacık bir an... ...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dusun-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güldamlası ve Aşkdamlası - III -', 'guldamlasi-ve-askdamlasi-iii-gulsen-senderin-9h0zz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Akdenizin tuzlu köpüklerinden oluşmuş

Bir Afrodit sunağı kadar, aşkla yüklüydü

Akkor halinde,- Güldamlam çok güzelsin -, dedim

- Saklayamadım, içimden tutkularım taşmış:

Deyip beni kanatlarının altına aldı...

Bir tufana kapılmıştık sanki yuvarlandık

Kucak kucağa sürüklendik dalgalar boyu

Bir şeytan üçgeninde lavlar arasındaydık

Çığlık çığlığa soluksuz, hazzın sarhoşluğu

Bizi yeşil adanın kumsalına taşıdı...

Deniz Kızı koyunda açtık gözlerimizi

Yılların sevdasıydı kanımızda dolaşan

Kıbrıs adasından, şeytan üçgenine bizi

Tufanların kaç kez yuvarladığını bilmem

Sevişirken aşk balıydı tenimizden taşan...

Kulağımda inleyen nefesi vardı hala

-Bulutlara çiçek çiçek adını yazdırdım

Mavilerin yeşillerin biziz ''Sarı Gülü''

Ta Kaf Dağından sevdanı kalbime kazdırdım.! 

Deyip tekrar öperek beni şımartıyordu...

Mutluluklar içinde uyandık sarmaş dolaş

Ona ne kadar teşekkür etsem yine azdı

Akşamın dönüşü başlıyordu yavaş yavaş

Yüreğimizde çalan hem şarkıydı hem sazdı

Gözlerimizden okunan, taşım taşım hazdı...

Ona doyamamıştım asla da doyamazdım

On gün kumrular gibi doya doya seviştik

Yeniden ayrı kalmayı göze alamazdım

Kalp kalbe bir daha ayrılmamaya sözleştik

Yapılacak ne varsa bir haftada hallettik...

Çok mutluyuz, bugün evlilik yıldönümümüz

Ve yine Lefkoşe''deki Kuğulu Park''tayız

Sudaki kuğulara sevgimizi anlattık.

Mehtaba karşı salıncaklarda sallanırken

Uyanan şafaklarla, aşkla dönen çarktayız...', 'Akdenizin tuzlu köpüklerinden oluşmuş Bir Afrodit sunağı kadar, aşkla yüklüydü Akkor halinde,- Güldamlam çok güzelsin -, dedim - Saklayamadı...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/guldamlasi-ve-askdamlasi-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Griyim...', 'bugun-griyim-i-brahim-ethem-bingul-zd94c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Havanın füme bakışlarıyla uyandım güne

Eziklik, umutsuzluk yüreğimde

Griyim bugün nedense...

Her renk anlatır ya bir  hikâye 

Ben gökkuşağını yaşardım tek günde

Ve griyim işte...

Aşksız kalmanın yeliyle

Kimseyi de suçlamam griliğimle

Suçlu benim

Sevmemeliydim benliğimle

İnanmamalıydım sözde sevgiye

Dilde kalmış sevgilere...

Ve griyim artık işte

Puslu, sessiz bekliyorum palette

Renk vermek üzere 

Hüzünlü bir tuvalde...

www.iebingul.com', 'Havanın füme bakışlarıyla uyandım güne Eziklik, umutsuzluk yüreğimde Griyim bugün nedense... Her renk anlatır ya bir  hikâye  Ben gökkuşağın...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bugun-griyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tane', 'bir-tane-necat-necdet-demircan-1egsp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aramazsın aşkını orada burada

Kaderdir dersin adına

Gelir bir gün bulur seni

Kısmet tanıştırır

Beğeniverirsin

Öyle ballandıra ballandıra ruhuna işler ki güzelliği,

Aklın karışır

Anlayışlıdır melek gibi

Duyguludur Leyla gibi

Kimi zaman saflığı Altın gibi

Kelimeler kafi gelmez anlatmaya

Yoktur işte yeryüzünde ölçüsü

Öyle ya o hep tektir

Değerlendirmeye çalışmak bile yanlış

Allah yalnızca Bir Tane yaratmış...', 'Aramazsın aşkını orada burada Kaderdir dersin adına Gelir bir gün bulur seni Kısmet tanıştırır Beğeniverirsin Öyle ballandıra ballandıra ruh...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-tane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Atışması', 'ask-atismasi-mehmet-ozer-rc8ep', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Meltem yağmurlarının altında ıslandığım sevdiğim

Esen rüzgarlar aşkımızı diyar diyar gezdirir mi

Halim nicedir kaç gündür hiç sormayan sevdiğim

Tan yeri ağardığında yanı başımda uyanır mı

Aşkı için dağları deldiğim çölleri gezdiğim sevdiğim

Patikaları çıkmaz sokakları benim için aşar mı

İsmini her duyuşumda ürperir tenim bedenim

Bana her bakışında sevgini yüreğimde hissederim

Rabbim ömrümü alsa bile ahiret de severim

Aşarım patikaları divane olur gezerim

Hattat olur aşkımı kalemlerle kağıtlara dökerim

İşkencedir seni görmediğim günlerim gecelerim

Mesudum çünkü çok sever beni yarim', 'Meltem yağmurlarının altında ıslandığım sevdiğim Esen rüzgarlar aşkımızı diyar diyar gezdirir mi Halim nicedir kaç gündür hiç sormayan sevdi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özer']::text[], 8.5, '{"poet":"Mehmet Özer","poet_slug":"mehmet-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-atismasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dramatik Bir Film', 'dramatik-bir-film-necat-necdet-demircan-rwudm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şayet sen yanımda olsaydın

Mutluluğun resmini çizmeye cüret edecektim

Hani herkesin hep bahsettiği, ama hiç çizemediği

Şu dillerden düşmeyen ''Mutluluk Tablosu''...

Yoksun

Olmayacaksın

Kötü bir parçasın

Ne bir renk

Ne bir palet

Gün olur da karıştırırsam anılarımı

İnan ki içinde sen bulunmayacaksın...

Bir hayal ''Mutluluk Tablosu''

Arkadaşın adı ''Acı''

Sahte mi sahte pembeler

Renksiz aslında geceler

Rolün de yok

Raflarda kalmış makaraların

Ne salon var seni oynatacak

Ne sesin

Ne de seyircin

Tozunu silecek bir ele hasret

İsmi unutulmuş, dramatik bir filmsin...', 'Şayet sen yanımda olsaydın Mutluluğun resmini çizmeye cüret edecektim Hani herkesin hep bahsettiği, ama hiç çizemediği Şu dillerden düşmeyen...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dramatik-bir-film-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendim Gibi', 'kendim-gibi-necat-necdet-demircan-496ox', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayatı seviyorum herkes gibi

Evimi seviyorum

Çiçeklerimi

Adını bilmediğim kuşları

Tadını bilmediğim yemişleri

Ağaçları

Yani güzel olan her şeyi, herkes gibi...

Farklı mı farklı benim sevdiğim

Eşsiz diyorlar hani,

İşte O benim sevgilim

Ona daha bir başka seviyorum

Herkesin sevgilisini sevmesi gibi değil

İnkar etse de insan, aslına en çok kendisini sever

İşte; 

Ben O''nu kendim gibi seviyorum...', 'Hayatı seviyorum herkes gibi Evimi seviyorum Çiçeklerimi Adını bilmediğim kuşları Tadını bilmediğim yemişleri Ağaçları Yani güzel olan her ş...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kendim-gibi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Umudun Adı', 'umudun-adi-talip-kaplan-uj5q2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kara geceyi bölerken ay ın ışığı

Işıltısında gül ü gördüm, kırmızı

Gül gonca ya

Fırtına yazdılar sevdanın etiketine

Açmayan yaprakları dökülürken

Güneşin yakacağını bilemezdi ki

İnadına yakarım ışıkları

Umudun yeni adı; 

Işıktan gömleğini giyecek gece

Yüreğimde güller, dinmeyecek...

(12 Eylül 2000)', 'Kara geceyi bölerken ay ın ışığı Işıltısında gül ü gördüm, kırmızı Gül gonca ya Fırtına yazdılar sevdanın etiketine Açmayan yaprakları dökül...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/umudun-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döndüğün Gün', 'dondugun-gun-necat-necdet-demircan-9t9h9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçinde diğer nefasetler yoksa, iki avuç buğdaydan bir aş/k çıkmaz...

Gökyüzünün karanlığında gümüş bir yağmur

Kızgın bir fırtına, yüksek homurtular

Girdiğin kapı umut güneşi

Hiç bir ışık olmasa bile soğuk odada

Her şey bıraktığın gibi yan yana...

Gel diyecek besbelli sana kalbi kanayarak

Sarılacak, gözyaşlarına eşlik edecek ağlayarak

Çok mutsuzluk çekmiş senden sonra

Sevinecek az da olsa

Belki acıyacak...

Birileri beklese de,

Rüzgarlar dolu yelkenlere kapılmışsa gönlün

Ne dakikalar bekler

Ne saatler

Ne takvim yaprakları

Ne de Yaşam

Ne günbatımıyla dön

Ne çöl sıcağına rüzgarla

Ne bir damla yağmur ol

Ne de sıcacık bir güneş tam tipi ortasında

Dönmek te güzel olmalı, 

Belki de çok hoş

Ama bıraktığın liman dönülmeyecek kadar boş...

Bomboş...

Dönmem der, ama birileri hep döner; Ya sözünden ya yolundan... Değişmedim der inatla üstüne basarak her defasında, kaybeder benliğini ve beklendiğini sanır... 

Umar ki; Gıcırtılı bile olsa açılsın ve hep kilitsiz kalsın hışımla çarptığı o narin kapılar... Tepeden tırnağa ıslak olsun, gözyalşarı içinde bekleyen, kavuştursun ellerini ve sarmalasın sevgiyle üzgünüm desin o meşum gidişine... 

Oysa; Zaman beklemez ki, biz ümitle yeşersek de..!', 'İçinde diğer nefasetler yoksa, iki avuç buğdaydan bir aş/k çıkmaz... Gökyüzünün karanlığında gümüş bir yağmur Kızgın bir fırtına, yüksek hom...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dondugun-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-ahmet-mansuroglu-n6qhe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dost olana dost olurum

Beklemem riya,

İçi başka dışı kişiler var,

Dost geçinir güya...

Düşmanım yok,

Olsada korkmam

Zira bilirim, o bana düşmandır.

Bütün endişem; 

Yüzüme gülen sahte dosttandır.

Antakya - Hatay            18.04.1982.', 'Dost olana dost olurum Beklemem riya, İçi başka dışı kişiler var, Dost geçinir güya... Düşmanım yok, Olsada korkmam Zira bilirim, o bana düş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dost-79-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PuANTiYeLi BiR GüN,', 'puantiyeli-bir-gun-mine-ozdemirtas-a5peh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'beyazlar beni hiç sevemedi

ben de siyahları

iki renk / birbiri ile

kıyasıya kapışınca

griye döndü er meydanı.

oysa, ömür kısa

biraz yeşil

biraz mavi, 

biraz da sarı

tam paletin ortasına konmalı

ve 

mor halkalarına yaşamın

ebruli dolanmalı.

bu gün,

grilere inat

kırmızının 

kıpkırmızı halkaları

esir alırken fırçamı

içimde kanadı

puantiyeli bir günü

yaşıyor olmanın 

ayrıcalığı

03/1272004.......    Sevgili şair dostum İbrahim Ethem Bingül''e gök kuşağı günler dileği ile. sevgi ve saygılar', 'beyazlar beni hiç sevemedi ben de siyahları iki renk / birbiri ile kıyasıya kapışınca griye döndü er meydanı. oysa, ömür kısa biraz yeşil bi...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/puantiyeli-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anacığım', 'anacigim-ahmet-mansuroglu-2g5w2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özledim seni anacığım 

Sanki yıllar var görmeyeli

Beyaz başörtün,

Tatlı tebessümündür

Şimdi aklımda kalan,

Ak saçlarının her telinde

Bizim dertlerimiz,

Bizim çocukluğumuz,

Bizim sevincimiz konuşur.

Yüz hatlarındadır bizim hayat dramımız

Her çizği,

Geçmişteki bir acıyı yansıtır.

Hasta günlerimde sen bana ilaçtın,

Şefkatinle sağlığı içtim yudum yudum,

Gülüşünle sıhhat neşe buldum,

Senin varlığınlaydı tüm mutluluğumuz

Aradan yıllar geçti, çok şey var unuttuğumuz,

Ayrılığın üzüntü,

Ayrılığın keder anacığım.

Kavuşmaksa mutlulukların en güzeli,

Bayram sabahına uyanan çocuklar gibi sevinirim,

Sensizlik zulüm,

Sensizlik ölüm anacığım,

Sen varsın sağsın ya anacığım

O halde bizde varız.

Antakya - Hatay                 02.04.1979', 'Özledim seni anacığım  Sanki yıllar var görmeyeli Beyaz başörtün, Tatlı tebessümündür Şimdi aklımda kalan, Ak saçlarının her telinde Bizim d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/anacigim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-ahmet-mansuroglu-guige', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ekmek değil

Su değil

Çarşıda satılmaz

Bakkaldan alınmaz

Su yaşatır

Ekmek büyütür

Mutsuzluk öldürür

Mutluluk ise güldürür insanı...', 'Ekmek değil Su değil Çarşıda satılmaz Bakkaldan alınmaz Su yaşatır Ekmek büyütür Mutsuzluk öldürür Mutluluk ise güldürür insanı......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mutluluk-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan Şiiri *2*', 'hazan-siiri-2-tulay-sustam-hjfee', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gözbebeğimden

..............................yüreğime

yüreğimden

..............................ellerime

yıllar yılı satır satır şiir biriktirdim...

ta ki sen karşıma çıkana kadar.

o gün karar verdim işte şiirlerimin sahibi diye

çıktım yedi tepeli şehrin en yüksek tepesine

döktüm şiirleri sana doğru...

....................ne gözbebeklerine,

..................................... ne yüreğine, 

.............................ne  de ellerine dokundu...

sen üzerine almadın hiç birini; 

şiirlerim öksüz, ben sensiz kaldım...

bu bana yokluğundan daha çok dokundu...

24.11.2004 tarih seni yazacak, beni okuyacak...', 'gözbebeğimden ..............................yüreğime yüreğimden ..............................ellerime yıllar yılı satır satır şiir biriktir...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hazan-siiri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affetsem mi?', 'affetsem-mi-hekim-coskun-puyqr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir yanımla sevmeye çalışırken

diğer yanımda fırtınalar kopuyordu

rüzgarın hep aynı yönde esmediğini fark ettim

sonra ıslattığım baş parmağımla

kuzeyi keşfettim rutubetli

güneyi ılık

doğuyu güneş doğduğunda

batıyı güneş battığında 

oysa coğrafya da; 

su ve kara birbirine çok yakın gözükür

su yu kirlettik

kara çaldık anlımıza

kaç bin yıldır armudu pazardan...

............

dud yemiş bülbül gibi

suskunluğumuzu meydanlarda haykıramadık

haykırdıysak ta bizde saklı kaldı nedenlerimiz

ordan burdan toparlandık bir avuç yürekle

kendimizi mezbahada bulduk

kasapların elinde sakatat gibi

lime lime doğrandık

birer noktaya döndük

her satırdan sonra durup

sil baştan okunduğumuz

bir yanım da nefret ve kin

bir kambur gibi yüreğimde

affetsem mi? 

bilmiyorum! 

affetmesem de it ulumasını

köpekleri çok seviyorum.

.....

hey insanoğlu

hey kitaplar

yazılanlar çizilenler

bil balık kadar özgürlüktü istediğimiz', 'bir yanımla sevmeye çalışırken diğer yanımda fırtınalar kopuyordu rüzgarın hep aynı yönde esmediğini fark ettim sonra ıslattığım baş parmağı...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/affetsem-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin Çilesi', 'sairin-cilesi-ahmet-mansuroglu-e7g7x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimine baht vermişsin Tanrım

Kimine köşk kimine saray

Kimi sen vermeden almış binlerce dönüm toprağı

Ben kulunada

Duygu vermişsin kucak kucak

Şair demişsin 

Onun zenğinliği duygu olacak

Onlar şükretmesini unutmuşlar

Oysa ben 

Her gün şükrederim verdiğin duygulara

Senin yüceliğini düşünür eğilirim saygıyla

Düşündükçe insandan sayılırım

Gün olur

Bir ameleyle kazma sallarım

Terini sırtımda 

Yorgunluğunu kollarımda duyarım

Kah pamuk tarlalarında çalışan ben olurum

Karın tokluğuna

Onları yakan güneş beni de yakar

Soframda lokmalar boğazımı tıkar

Birden sıcaklaşır testimdeki su

Şikayet değil Tanrım 

Şairin çilesidir bu...

Antakya - Hatay', 'Kimine baht vermişsin Tanrım Kimine köşk kimine saray Kimi sen vermeden almış binlerce dönüm toprağı Ben kulunada Duygu vermişsin kucak kuca...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sairin-cilesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asırlar Boyu Beraber', 'asirlar-boyu-beraber-necat-necdet-demircan-xl07o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şiir yazmaktan

Derin nefes hayatı yudumlamaktan

Nasıl haz alıyorsam

Senden de hiç bıkılmayacak

Hep İlk Göz Ağrısı olacaksın

İlk kez bisiklete binmek gibi coşkulu

İlk kez aşık olmak gibi kaçak bir sevda

Yüreğimde bir duygu, kulağımda bir ses

Adsız bir çiçek gibi açacaksın

Sonsuza değin öyle kalacaksın..

Uyumayı, rüyaları nasıl unutmuyorsam 

Seni de unutmayacağım

Beynimde bir rüzgar

Kimi zaman eski bir melodi

Kimsesizlikle yapılan bir dans

Hiç mi hiç ağlamayacaksın

Ruhumdasın

Aşkım olarak kalacaksın...

Hayatı, umarsız olmasa da yaşamayı

nasıl seviyorsam

Seni de öyle seveceğim

Geçmişimde, geleceğimde

Asırlar boyu beraber

Hep Sevgilim

Hep Birtanem

Adı her neyse işte en muhteşeminden...', 'Şiir yazmaktan Derin nefes hayatı yudumlamaktan Nasıl haz alıyorsam Senden de hiç bıkılmayacak Hep İlk Göz Ağrısı olacaksın İlk kez bisiklet...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/asirlar-boyu-beraber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Suçu', 'sevmek-sucu-ahmet-mansuroglu-fa3fg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrılık varmış, ayrılmayacağız derken bilemediğimiz

Kahrediyor seni buldum derken gelen ayrılık

Eğer ıslanmışsa gözlerim ağlıyorsam sesizce

İçimde fırtınalar kopuyor göremesin

Bir ateşsin içimde volkan misali

Yakan, eriten, kül eden beni

Eğer suçum ölesiye sevmekse seni,

İşte bıçak, acımadan vur

Seni sevmek suçunu, durmakla ödesin kalbim

Ellerin titremesin sakın ne olur

Günde bin kez ölmekten kurtar beni

Gözlerimi kapatırken benliğimde götüreyim seni.

Antakya - Hatay', 'Ayrılık varmış, ayrılmayacağız derken bilemediğimiz Kahrediyor seni buldum derken gelen ayrılık Eğer ıslanmışsa gözlerim ağlıyorsam sesizce ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevmek-sucu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç Kalmışım', 'gec-kalmisim-abdurrahim-karakoc-hwd6a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Putları taşa tutmanın

Güç’lüğünü geç anladım.

Delileri avutmanın

Hiç’liğini geç anladım.

İhtiraslar dursun diye

Şehiri sığdırdım köye

Her bedenin ayrı şeye

Aç’lığını geç anladım.

“Safkan” dedikleri atın

Ünü büyük pek çok zatın

Bir yerde ilmin, sanatın

Piç’liğini geç anladım.

Hak’tan söz edersen eğer

Atılan taş sana değer

Doğruluk suç imiş meğer

Suç’luğunu geç anladım.

Su taşırken kalbur, file

Susmak gerekirmiş dile

Yazık... geç kalmanın bile

Geç’liğini geç anladım.', 'Putları taşa tutmanın Güç’lüğünü geç anladım. Delileri avutmanın Hiç’liğini geç anladım. İhtiraslar dursun diye Şehiri sığdırdım köye Her be...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gec-kalmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Ellerimdesin!', 'simdi-ellerimdesin-kadir-soyturk-2f8wx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir adım yakınımdan, bana kucak açardın

Elimi uzatınca, gülüp hemen kaçardın! 

Bu arayış- bu kaçış, uzun yılları aldı

Ömür geçti,bembeyaz bir kaç tel saçım kaldı.

Bitti artık bu hasret,şimdi ellerimdesin

Seninle beraberim, kimler ne derse desin! 

Benim seni sevmemin, kime ne zararı var? 

Artık seni bırakmam,yolun sonuna kadar! 

Yazacağım! Kalemi geçirmişken elime

Kelimeler geldikçe; yüreğime,dilime! 

Bizi kıskananlara, sakın ha kızmayalım

Haktan,güzelden gayrı, hiç bir şey yazmayalım!', 'Bir adım yakınımdan, bana kucak açardın Elimi uzatınca, gülüp hemen kaçardın!  Bu arayış- bu kaçış, uzun yılları aldı Ömür geçti,bembeyaz bi...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/simdi-ellerimdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çarpmalıklar, Çırpmalıklar', 'carpmaliklar-cirpmaliklar-mehmet-lutfu-aydin-yybe8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I.

Reklâm, afiş, kampanya, kurarsınız bankayı 

Yüksek faiz diyerek toplarsınız parayı

Ne atanız ne de siz görmemişken sarayı

Götürdünüz birlikte çuvallarla parsayı

II.

Hak-hukuk, namus-şeref, şan bizim

Köşk-konak, yalı-saray, han sizin

I. 

Öğrenciler eylemde, YÖK’e karşı çıkarlar

Polis copu görevde, memurları yıkarlar

Emekçiler grevde, kemerleri sıkarlar 

Ağa, patron Eyfel’de, bal yemekten bıkarlar 

II.

Kar-pekmez, ekmek-peynir, gam bizim

Bal-börek, yağlı çörek, can sizin

I.

İşçi, memur aç sefil, ahlâksızlık diz boyu

Ya tanıktır ya kefil, değişmez huyu, suyu

Yargıç, savcı perişan, kim bulacak suçluyu              

Hakkımızı çalana  kim soracak soruyu

II.

Aşk-sevi, sevgi-saygı, nam bizim

Misk-amber, düğün-dernek, kâm sizin

…

III.

Malı kapıp kaçarsınız, her engeli aşarsınız

Altın, gümüş saçarsınız, kral gibi yaşarsınız

Altınızda Mercedesler, ayağınız basmaz yere

Havanızı basarsınız, göğsünüzü gere gere

Mercedesten indiniz mi, altınızda atlas halı 

Beklemekte şimdi sizi, altın saray, gümüş yalı

…

IV.

Sanma ki hayat böyle sürer 

Gün gelir devran sona erer

Felek defterinizi dürer

Cennette seyran güme gider', 'I. Reklâm, afiş, kampanya, kurarsınız bankayı  Yüksek faiz diyerek toplarsınız parayı Ne atanız ne de siz görmemişken sarayı Götürdünüz birl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/carpmaliklar-cirpmaliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Sevmeler', 'hic-sevmeler-cetin-hacifettahoglu-c8hum', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Asıl Güçsüz Olduğunda Koyulmalısın Bu Yarışa

Yavaşta Olsa,

Sevgiyle Başlamalısın…

Sevgiyi Yüreğine Öğretene Kadar Koşmalısın.

Kimseler Bilmesede, Kendine Tekrar Tekrar Sormalısın

Yalanları Boğup  Doğrulmalısın Doğrulara

Her gün Suyla Yoğurduğun Ellerine Almalısın Sevgiyi

Kan Bulaşmış Dağlara,Gökyüzüne,Dokunma Sakın! 

Birilerine Kalsın Kırmızının Riyası.

Gözlerin Değsin Yüreğime

Dağ Kahvesi Gözlerin…

O Gözlerde Kalsın Yitik Kuru Yüreğim

Bu Akşam Bitip Güne Kavuştuğunda Sabah,

Ben Yorgun

Sen Suskun

Nasıl Olsa Olanlar Oldu Der Günde Biter Elbet.

Felaketler Olur Beynimde  Zırıl Zırıl Ağlar Zaman

Benmi Doymuşum Gecelere.

Kalk Hayalim Sevdiğim Şarkılarda Bildiğim…

Uzun Kirpiklerine Ak Düşmüş Sızısına Öldüğüm

Ya Yoksan! 

İşte Sonun Başında Bir Yalan Olursun O Zaman

Ne Sevmeler Edilmiş Uğruna Bir  Bilsen

Bilsen,Şiirden Doğar, Diriltirsin Kendini….

Hiç Sevmelerim… Yaşan masalarda Vardılar

Hiçte Olsa İz Bırakıp Oldular.', 'Asıl Güçsüz Olduğunda Koyulmalısın Bu Yarışa Yavaşta Olsa, Sevgiyle Başlamalısın… Sevgiyi Yüreğine Öğretene Kadar Koşmalısın. Kimseler Bilme...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hic-sevmeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günahlarım Var Benim', 'gunahlarim-var-benim-cetin-hacifettahoglu-kdbpz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bulanık Bir Serdeyim

Parçalanmış Hatıralar Odanın Her Bir Yerinde

Sinemi Isıtan Bir Yangınım Var Elbet

Sonsuz Hırslarım Var Hayata Dair

Ve Bir Sızı Acıtır Durur Buğulu Gözlerimi

Işıklar Hep Uykuda,Saat Başucumda Sayıklar Durur

Rüyalarımı Büyütüyorum Yetişkin Bir Suretin Var Artık

Müjdeler Olsun  Ey Acılar Esirinim Gülüp Durma

Yinede Acıya Mahkum Özgür Bir Mutluluğum Ben

Tutsak Kahpe Dediler Adına  Ayrılmalara Dair

Tanıdık Bir Yüz Aramam İnatlarım Var Benim

Çırılçıplak Yıldızlara Ördüğüm Kazaklarım Var Benim

Üşürüm Ara Sıra Ama Yangınlarım Yanar Benim

Dostlarımla Ayrılmalarım…

Ey Dostlarım! 

Sınırlı Olmayan Hayallerle Özlüyorum Hepinizi

İçimi Soğuk Anlamlar Gıdıklıyor

Serseri Bulutlar Başucumda Dolanıyor

Günahlarımı Islatıyor Damlacıklar

Bekledikçe Rutubet Kokan Anlamlar Süzülüyor Yanaklarıma

Kurşun Atsam Şu Silinti Yalnızlığa

Kan Girer Yalnızlığımla Arama

Gül Versem Şu Yazılmış Yazıma

Diken Batar Bağrıma

Dedimya Günahkar Sevmelerim Oldu Benim

Ne Yalnızlık Paklar Oldu Nede O Kapkara Gözler

Günahlarımdır Benim Yaşantım', 'Bulanık Bir Serdeyim Parçalanmış Hatıralar Odanın Her Bir Yerinde Sinemi Isıtan Bir Yangınım Var Elbet Sonsuz Hırslarım Var Hayata Dair Ve B...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gunahlarim-var-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''ım', 'allah-im-ali-riza-unal-qyi8b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Allah''ım bu nasıl hasret

Hazzına tapar oldum

Kulda buldum seni halvet

Gönüller yapar oldum

Firakın derdime devlet

Vaslında yanar oldum', 'Allah''ım bu nasıl hasret Hazzına tapar oldum Kulda buldum seni halvet Gönüller yapar oldum Firakın derdime devlet Vaslında yanar oldum...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/allah-im-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayale Doğmak', 'hayale-dogmak-cetin-hacifettahoglu-3507m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hakikatleri  Olmayan  Bir Şiirde Doğdum Ben

Mısralarda Yüzer Oldum Yllarca

Mürekkebime Kan Bulaştı

Sığ Sularda Çetin Dalgalarla Boğuştum

El Gibi Bakar Oldum Kendime

Yüzlerce Kez Öldüm

Doğdum Gökyüzüne Bulut Oldum

Gah Toprağa Karıldım Tohum Oldum

Ağladım Acı Oldum

Güldüm Sevgi Verdim Verilmeyenlere

Şimdilerde Özlemlerime Koşuyorum Delice

Bir Usul Şarkı Tutturmuşum Söyler Dururum

Ve Soluksuz Rüzgarlar Eser Pencereme

Ben Sussam Duvarlar Konuşur Oldu

Gelecekler Gelmez Oldu

Geç Kaldın Gökyüzü Yüreğime', 'Hakikatleri  Olmayan  Bir Şiirde Doğdum Ben Mısralarda Yüzer Oldum Yllarca Mürekkebime Kan Bulaştı Sığ Sularda Çetin Dalgalarla Boğuştum El ...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayale-dogmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün', 'huzun-cetin-hacifettahoglu-80hx0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geliyorum! 	

Ayak Parmaklarımın Uçlarına Basarak

Sessizliğimi Duyuyor musun? 

Boyuyorum! 

Çığlıklarımın Kırmızısındasın

Acılarımı Görüyor musun? 

Beklemeli miyim…

Kaba Basılmış Turşu Misali

Kokluyor musun? 

Ve  Ardından mı…

Sende  Kalır Endişeler Meraklar

Benim Kadar Yalnız Kuşlar Besliyorum

Olurda, Bir gün Pencerene Konarım Diye

Sus! ...

Ne Olur Sus! ,Sesinde Hüzün Var Yine

Sessizliğine Boğulmalıyım.

Seni Sağır Duymalıyım Belkide

Derdime Derman Olmamalıdır Sesin

İri Gözlerimde Hüzün Var Yine

Aynalara Bakamıyorum Artık

Yıkılası  Be Sevda

Bu Halleri Böyle Bilesin.', 'Geliyorum! 	 Ayak Parmaklarımın Uçlarına Basarak Sessizliğimi Duyuyor musun?  Boyuyorum!  Çığlıklarımın Kırmızısındasın Acılarımı Görüyor mu...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/huzun-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Ahki Ne Ah', 'ah-ahki-ne-ah-ali-riza-unal-ibha4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ah ahki ne ah, sen sevdiğini sevgine

Mecnunu viran edersin

Çünki ey canan cezbeyi cemâl ile Leylâ''yı cansın

Pinhan oldun bu alemde  in-zana ki

Mal ile mülk sansın

Aşikâr olur ehli aşığa, civana buse ile visal edersin

Sevdayı meşkine nuşum,  beni sende terk ile

Mahşere ne hacet, ayanım cihana

Sen didarı nihansın

  ----İn-zan- gerçeklerden habersiz insan  anlamına gelir', 'Ah ahki ne ah, sen sevdiğini sevgine Mecnunu viran edersin Çünki ey canan cezbeyi cemâl ile Leylâ''yı cansın Pinhan oldun bu alemde  in-zana ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ah-ahki-ne-ah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Artık', 'gel-artik-cetin-hacifettahoglu-j451p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '.

Gelecek Bahar Demiştinya Hani

Kaç Bahardır Beklerim Sen Yoksun

Çok Rüzgarlar Esti

Yağmurlar Yağdı Üzerime

O Ağacın Altında Beklerim Seni

Tutuşur Gökyüzü Belirir Bulutlar

Yapraklar Arasından Gülümseyişlerin Yok olur Gider

Gözlerimde Ağır Sebepler Oluşur

Yüzüm Dökülür Ayaklarıma

Ha Geldi Ha Geleceklerin Akıtır Gözyaşları mı

Kaç Bahar Bekledim Bilmiyorum

Kaç Koca Yürek Akıttım Toprağına

Köklerim Çürüyor Gel Artık

Dişlerim Sızlıyor Dudaklarım Yanıyor

İnsafına Yandığım Vicdanına Öldüğüm

Gel Artık Şiir Gözlüm

Gülüşüne Doğduğum', '. Gelecek Bahar Demiştinya Hani Kaç Bahardır Beklerim Sen Yoksun Çok Rüzgarlar Esti Yağmurlar Yağdı Üzerime O Ağacın Altında Beklerim Seni T...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gel-artik-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günah', 'gunah-cetin-hacifettahoglu-uvgkt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zincirlere Vurulmalıyım

Kaygısızca Serin Sulara Salınmalıyım

Korkmuyorum Sizlerden

Sizki  Riyayı Sevenler

Elbetlerime Bırakıyorum Kaderinizi

Ne Ben Varolmalıyım Ne Siz Kandırabilmelisiniz Sevdaları

Ardına Bakmadan Koşanlar

Gerilerde Bırakmalara Burulmazmı Yüreğiniz

Yalnızlıklara Açılan Paslı Yüreklerinizi Gördüm

Tek Kalmalarınızda Varolmalarınızı da

Kullanıp Atabileceğiniz Meyhane Kokan Elbiselerinizi Gördüm

Şarap Kadar Kırmızı Ve Sakin Duruşlarınız Oldu

Sizi İçti Siz Gibiler 

Günahında Bir Uzun Yalan Ömür

Dizlerimde Derman Kalmadı Artık

Ne Koşuyor Nede Yürüyebiliyorum

Ürkek Dinleme Beni

Git Yada Adam Gibi Dinle

Gözlerimde Sana Yakarışlarımı Dinle

Yalancıda Olsan Gözlerinle Bir Kez Daha Kandır Beni

Şiddet Dolu Gülüşlerini Çek Üzerimden

Nefretinde Bulabileyim Samimiyetini', 'Zincirlere Vurulmalıyım Kaygısızca Serin Sulara Salınmalıyım Korkmuyorum Sizlerden Sizki  Riyayı Sevenler Elbetlerime Bırakıyorum Kaderinizi...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gunah-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuzum', 'umutsuzum-hasan-can-p0cp2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sakın sorma geçmişi,

Acıtır hatıralar içimi,

Bilmezsin neler yaşadım,

Soracaksan sor geleceğimi.

Geçmişe dair bir umut yok içimde,

Yürüdüğüm yollar hep acı verdi her santiminde,

Karanlık bir dünya yaşıyordum sanki,

Benim kaderim buydu belki de.

Aslında geleceğimden de umudum yok,

Şarkılar gibidir güzel günler, yaşanır ve biter.

Umutsuzum, geçmişimden geleceğe daha çok,

Zaten umutlarda kalmaz birgün, geçer giderler.', 'Sakın sorma geçmişi, Acıtır hatıralar içimi, Bilmezsin neler yaşadım, Soracaksan sor geleceğimi. Geçmişe dair bir umut yok içimde, Yürüdüğüm...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umutsuzum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arasıra Aşk', 'arasira-ask-cetin-hacifettahoglu-ul8gg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Üç Dakika Değil ki Aşk

Sırları Olmalı Aşkın

Asırlara Sığmalı

Kapı Çalışlarında Hoplamalı Yürek

Telefon Zillerinde Şarkı Olmalı

Pencerene Konan Bir Serçe

Hüzünlerle Kapalı Bir Perde Olmalı Aşk

Yağmurun Islattığı Bir Pardüse

Yada

Güneşin Kuruttuğu Gözyaşı Olmalı

Yok Dediklerinde Olmalı Aşk

Bulup Bulup Yitirdiklerinde

Yeniden Varolmalı

Kalp Atışlarında Değil

Çatalını Batırdığın Su Bardağında Olmalı

Gökkuşağında Aramamalısın Aşkı

Yağmurun Her Damlasında Düşmeli Toprağa

Aydınlığın İhaneti Yoktur Aşka Dair

Aşktır Sebebi İhanete Gecenin

Mum Işığına Hapsetmelisin Aşkı

İhanetide Yaşamalısın

Acı Çekmelerdedir Bazen Aşk

Ölüp Ölüp Dirilmelisin Yaşama 

Her Doğuşunda Hayata

 Aşktır Seni Büyütüp Yeniden Öldüren

Ne Ölümden Korkarsın

Nede Bilinmeze Yaşarsın Kendini

Aşk Küstürür Bazen İliklerine Kadar Lanet Edersin

Odalara Hapsedersin Kendini

Duvarlara Ağlarsın Yastığına Kızarsın

Geceler Büyütür Özlemlerini

Gençliğini Ararsın

Aynalarda Kanarsın Yalnızlığına

İşte Aşktır Bu Dizeler

İşte Var Olan Ben 

İşte Yalancıda Olsa Tutsağıyım

Gölgesinde Mutluyum

İçine Düştüğümsün

Arasıra Sendeyim', 'Üç Dakika Değil ki Aşk Sırları Olmalı Aşkın Asırlara Sığmalı Kapı Çalışlarında Hoplamalı Yürek Telefon Zillerinde Şarkı Olmalı Pencerene Kon...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/arasira-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-cetin-hacifettahoglu-o1bb0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşüyorum…

Karanlık bir aydınlığa doğru

Belirsiz bir belirtiye doğru

Düşüyorum…

Varolmamış bir varlığa gülümseyerek

Ellerimde sımsıkı sıktığım gevşekliğimle

Düşüyorum…

Serbest kalsın hapis düşüncelerim

Koşsun kütürüm ayaklarım

Düşsemde

Askıda koşmalıyım

Boşa sallayıp doldurmalıyım boşları

Düşünüyorum…

Beyaz görünen kara yazıları

Gerçek gürünen hayalleri

Düşünüyorum…

Al yazmalı kan bulaşmayan çarşafları

Kana bulanan ak pazenli kızları

Düşün semde…

Bataklıkta kulaç vurmalıyım

Battıkça çıkmalıyım kayaların dibine

Düşlüyorum…

 Yarım kalan tamları

Tama doymaz yarım paye kafaları

Düşlüyorum…

Yalnız kalan yanları

Dost dolu yalnız geçen o körpecik yılları

Düşerken düşünüyor 

Düşünürken düşlüyorum

Sevdaları, yalnızları,

Kağıdını dürdüğüm o Dost bildiğim düşmanları', 'Düşüyorum… Karanlık bir aydınlığa doğru Belirsiz bir belirtiye doğru Düşüyorum… Varolmamış bir varlığa gülümseyerek Ellerimde sımsıkı sıktığ...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/dus-101-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Visalem', 'visalem-ali-riza-unal-5ud8y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anlatılmaz bir hal ile ricali gabya ayanem

Silmişem  zannımı, her cem ile şehveti benden

Hicranıma niyazım var, istemem şifa ey sevgili

Dalmışam bu deme, bin hal ile visalem', 'Anlatılmaz bir hal ile ricali gabya ayanem Silmişem  zannımı, her cem ile şehveti benden Hicranıma niyazım var, istemem şifa ey sevgili Dalm...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/visalem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedenim Eridi Güneşin Gölgesinde', 'bedenim-eridi-gunesin-golgesinde-fatih-ozkonyali-15prh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dayandım şakağına, nabzına değdim ufkun,

Göz süzdüğüm arzular bana maymun kafesi.

Seyranına hükümlü, deliler gibi tutkun,

Gördüm, yaşadığım an bir cinnet tarifesi.

Açıldı dumanlı yol sıyrıldıkça bedenden,

Bu aynanın aksinde beni kan revan gördüm.

Arşın gölgesi ikrah, ikrah ki gelir senden,

Öyle ki rüyamda hoş, nasıl boş sefa sürdüm...

Sinesinde zamanın eridim, kustum nefret,

Ayyuka çıkar sandım büyüdükçe ben başım.

Meğer zerre olmakmış hem makam hem de şöhret! ..

Meğer benden çıkmakmış manada tek sırdaşım.', 'Dayandım şakağına, nabzına değdim ufkun, Göz süzdüğüm arzular bana maymun kafesi. Seyranına hükümlü, deliler gibi tutkun, Gördüm, yaşadığım ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Özkonyalı']::text[], 8.5, '{"poet":"Fatih Özkonyalı","poet_slug":"fatih-ozkonyali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bedenim-eridi-gunesin-golgesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamam', 'anlatamam-hasan-can-0ap2g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akşamın yorgunluğunu anlatamam,

Üstüme çöker hasretin her an.

Kalbimde bir sızıdır nefretim,

Kanıma işlenmiş hasretin.

Gözlerin vurur aniden geceye,

Anlatamam derdimi o an kimseye,

Ben yenildim hep kedere,

Bir hasrettir birde nefret içimde.

Gözlerimden düşer yaşlar,

Yağmur gibi vurur sesi kaldırımlara.

Bir mucize olsada seni içimden alsalar,

Benim gibi yenik düşsen anılara.', 'Akşamın yorgunluğunu anlatamam, Üstüme çöker hasretin her an. Kalbimde bir sızıdır nefretim, Kanıma işlenmiş hasretin. Gözlerin vurur aniden...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anlatamam-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün suç bende', 'butun-suc-bende-haydar-turan-1i1ne', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nerden geldim bilmem dünyaya,

Hayattan bıkar oldum günden güne,

Seviyordum seni uzaktan olsa bile,

Ben seni hep sevdim sen anlamadın ki! 

Sonra zaman geçtikçe güler oldun şu dertli yüzüme,

Bakışmaya başladık sonu belli olmasa bile,

İlk elimi tutduğun o soğuk gece

Ne sözler vermiştin bana ama ayrılık yoktu içinde,

Sonra kötü şeyler duydum hakkında,

Yaramaz dediler bu sana,

İnanmadım yalan dedim,

Senin için biliyor musun sevdikleri mi terk ettim? 

Ve hiç aklımdan geçmezdi seni iki kişinin arasında görmek,

Kahkahalar içinde güldüyüşü görmek,

Yüzünden belli oluyor,

Hayatın cilvesi,

Seni bu halde görünce ağlamak istedim, ölmek istedim,

Seni sevmiyorum diye haykırmak istedim ama diyemedim,

Ve biliyor musun her şey bitmişti o iki saat içinde,

Ben hala seni izliyordum titriyen bedenimle ve yüreğimle,

Ve sen yanlız kalınca çökdün dizlerinin üstüne,

Gözlerinde kin vardı kim bilir kime? 

Belki bu acı kadere belki bir erkeğe? 

Ve ozaman anladım sen meçburdun gülmeye.

Sonra sen kalktın çöktüğün yerden,

Gözlerinden yaş akıyordu uzakdın sevgiden sevdiklerinden,

Sen karanlığa doğru ağır ağır ilerlerken sana dur demek istedim,

Seni seviyorum demek istedim ama gururuma söz geçiremedim,

Ve bir gün kötü son yazıyordu gazetelerde,

Bir kadın intihar etmişti gecenin karanlığında,

Senin ismin yankılanmaya başladı beynimin dört yanında,

Ve o anda çökdüm dizlerimin üstüne,

Ağlamak istedim, ölmek istedim ve o zaman anladım bütün suç ''BENDE''', 'Nerden geldim bilmem dünyaya, Hayattan bıkar oldum günden güne, Seviyordum seni uzaktan olsa bile, Ben seni hep sevdim sen anlamadın ki!  So...', ARRAY['Türk Edebiyatı','Şiir','Haydar Turan']::text[], 8.5, '{"poet":"Haydar Turan","poet_slug":"haydar-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/butun-suc-bende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Sensizlik**', 'sensizlik-alpaslan-yigit-w958v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu sabah bir korku uyandırdı beni

Nefes nefese kalktım yatağımdan

Neyin ne olduğunu anlayana kadar

Zaptedemedim kalp atışlarımı

Rüyamda benden alıp gitmiştin kendini

Çaresizliğimi yaşadım,yalnızlığımı

Senseizliğin gölgesi vardı heryerde

Gözlerimden düşen yaşı gördüm heryerde

Kanatlanmış gidiyordu uzaklara mutluluğum

Sevinçlerim arkamda,Kederli geleceğim ilerimdeydi

Arkama baktığımda unutacaklarım için

Önüme baktığımda bekleyenler için ağladım

Ayaklarımda sanki prangalar vardı

Görüyordum seni o kadar yakındınki bana

Ama gelemiyordum yanına

Koşmak istedim,koşamadım.Kalakaldım öylece

Artık seni göremeyecek olmanın korkusunu yaşadım

Bilsen ne zormuş sensizlik

Alışmışım huzura,mutluluğa,seninle olmaya

Rüyada olsa kabullenemedim yokluğunu

Neyseki rüyaymış yaşanan tüm bu kabuslar

Neyseki benim canımın içiymişsin hala

Neyseki sabah olduda açıldı gözlerim

Kaybettiğimde seni beni neyin beklediğini görebildim.....', 'Bu sabah bir korku uyandırdı beni Nefes nefese kalktım yatağımdan Neyin ne olduğunu anlayana kadar Zaptedemedim kalp atışlarımı Rüyamda bend...', ARRAY['Türk Edebiyatı','Şiir','Alpaslan Yiğit']::text[], 8.5, '{"poet":"Alpaslan Yiğit","poet_slug":"alpaslan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sensizlik-149-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatım', 'hayatim-soner-demir-fdkvv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir film benim hayatım,	

Adı bir yol hikayesi......	

Sen baş oyuncu gelen rolünde,	

Ben bekleyen....	

Kötü adamlar zaman ve yol,	

Biri geçmeyen rolünde,	

Digeri hiç bitmeyen! ...', 'Bir film benim hayatım,	 Adı bir yol hikayesi......	 Sen baş oyuncu gelen rolünde,	 Ben bekleyen....	 Kötü adamlar zaman ve yol,	 Biri geçme...', ARRAY['Türk Edebiyatı','Şiir','Soner Demir']::text[], 8.5, '{"poet":"Soner Demir","poet_slug":"soner-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hayatim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günbugün', 'gunbugun-hasan-ates-c2hmv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün,

 akşama kadar seni düşündüm.

Biraz soluklandım.

Sonra yine seni düşündüm.

Resmine her zamankinden biraz daha âşinâ oldum.

Senin için şiir yazdım bugün.

Sonra seni biraz daha sevdim

                   ve seviyorum.', 'Bugün,  akşama kadar seni düşündüm. Biraz soluklandım. Sonra yine seni düşündüm. Resmine her zamankinden biraz daha âşinâ oldum. Senin için ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ateş']::text[], 8.5, '{"poet":"Hasan Ateş","poet_slug":"hasan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gunbugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Acısı', 'yurek-acisi-altay-taskin-frlnq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben acı nedir

bilir miydim

silahlar olmasaydı

Hiroşima''da şimdi

ağaçlar çiçek açardı

ben acı nedir

duyar mıydım

açlar olmasaydı

Somali''de şimdi

çocuklar oyun oynardı

ağaçlar çiçek açsın

çocuklar oynasın

dünya mutlu kalsın', 'ben acı nedir bilir miydim silahlar olmasaydı Hiroşima''da şimdi ağaçlar çiçek açardı ben acı nedir duyar mıydım açlar olmasaydı Somali''de şi...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yurek-acisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Treni', 'umut-treni-altay-taskin-i6a7b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni bekliyorum yıllardan beri

beni de al yanına umut treni

hangi istasyonda dersen inerim

ama götürsen beni de son durağına

ulaşırsam umut dünyasına

çok sevinirim', 'seni bekliyorum yıllardan beri beni de al yanına umut treni hangi istasyonda dersen inerim ama götürsen beni de son durağına ulaşırsam umut ...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/umut-treni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne desem', 'ne-desem-fedai-gunaydin-s6xz7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne desem kırıyorum hayatı

Demesem ben kırılıyor

Vallahi aklım şaştı

Bir yazıyorum, bin susuyor

Demekler dille değil

Mahkumuyum kalemimin

Bağır yazım bağır artık

Sen dilisin kor dilimin

Ne desem kırıyorum hayatı

Demesem ben kırılıyor

Vallahi aklım şaştı

Bir yazıyorum, bin susuyor', 'Ne desem kırıyorum hayatı Demesem ben kırılıyor Vallahi aklım şaştı Bir yazıyorum, bin susuyor Demekler dille değil Mahkumuyum kalemimin Bağ...', ARRAY['Türk Edebiyatı','Şiir','Fedai Günaydın']::text[], 8.5, '{"poet":"Fedai Günaydın","poet_slug":"fedai-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-desem-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm ve Pişmanlık', 'olum-ve-pismanlik-ali-kadioglu-bqe0f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''''Sevda Ülfetinden Eskimeyen Dostumun Aşkına Müracaat...''''

Tükendi tüm benliğim bir gülün yaprağında,

Dikendi elde kalan pak nergis toprağında..

Kalp hüzün şelalesi,kime yalvarsın gayrı,

Yusuf''u bu kuyudan kimler kurtarsın gayrı? .

Yusuf olmuş bir kuyu,kuyu olmuş bin Yusuf,

Nasıl yürek dağlamaz senin bu derdin Yusuf? ! 

Biricik çaremdi o,gözde tatlı nemdi o,

Beni korkunç karanlık bir mezara gömdü o! .

Dirimden anlamadın,a benim güzel yârim

Çürümüş cesedime olsun uzat el yârim! ..

Acının son bulduğu tek yer neden kabristan,

Senin için,sevginle,masumcasına atan

Bu kalbe reva mıydı,söküp onu,insafsız

Attın ıssız bir çöle,ettin her ağza sakız? ! .

Bir damla yaş kalmadı ağlamaya,gözümde

Yakıp yakıp dirilttin beni kendi közümde! .

Kızma bana ne olur,yüreğim senin olsun

İki âlemde köşkler mutluluk yerin olsun..

Sadece bir kerecik anlar gibi yap beni,

Yoksa diri katacak toprağa azap beni..

Cellâdım,canım feda elindeki kılıca,

Yeter ki sen merhem ol,''derin''deki kılıca..

Çiçekler devşireyim gülnevâ saçlarından,

Acı ve affet beni,pişmanım suçlarımdan! ..', '''''Sevda Ülfetinden Eskimeyen Dostumun Aşkına Müracaat...'''' Tükendi tüm benliğim bir gülün yaprağında, Dikendi elde kalan pak nergis toprağın...', ARRAY['Türk Edebiyatı','Şiir','Ali Kadıoğlu']::text[], 8.5, '{"poet":"Ali Kadıoğlu","poet_slug":"ali-kadioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/olum-ve-pismanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüceden Yüce', 'yuceden-yuce-ali-riza-unal-ck31d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana sevgimi sır ettim, birkaç harf ile hecede

İstemem valsını, bitecekse bir gecede

Bilki sevdan nefsani değil

İnan arştan öte yüceden yüce', 'Sana sevgimi sır ettim, birkaç harf ile hecede İstemem valsını, bitecekse bir gecede Bilki sevdan nefsani değil İnan arştan öte yüceden yüce...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yuceden-yuce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vay Haline Hacım Senin', 'vay-haline-hacim-senin-ali-riza-unal-0p5cd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne bakarsın semaya

Gövden düşmüş belaya

Vur yüzünü helaya

Vay haline hacım senin', 'Ne bakarsın semaya Gövden düşmüş belaya Vur yüzünü helaya Vay haline hacım senin...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vay-haline-hacim-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yare Sitem', 'yare-sitem-yavuz-agir-gvda8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gül tikenin batmasın,

Yazıktır incittir beni.

Dargınlık,kırgınlık olmasın,

Derinden yaralar beni.

Gonca henuz gül olmadı.

Bülbüle el vermedi.

Gel etme, eğleme,

Derdin yaralar beni....

Ahuzardayım ağlarım.

Goncayı güle bağlarım:

Yare yürek dağlarım; 

Derdin paralar beni......', 'Gül tikenin batmasın, Yazıktır incittir beni. Dargınlık,kırgınlık olmasın, Derinden yaralar beni. Gonca henuz gül olmadı. Bülbüle el vermedi...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yare-sitem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-hakan-kumcular-7q1g2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Efkarım kendime güzel olan güzelliklere senin adına güzel desem heralde yeri olurdu.

Nede olsa adında güzel farkına varamadığım bir farklılığın anlamı içinde sanki yok oluyorum

Kaldı aklım ilk bakışının derinliğinde içime süzülen anlamlı,anlamsız korkudolu heyecanlı ümitsiz bir boşluğa düştü.

Belki öylesineydin belki binbir ümitleydin ama yinede o bakış içimi kaynatıyordu.Erken açan bir gül gibiydim senden sonra farkına varmışlığım açan gülümü dahada çabuk soldurdu.

Denize açılmış ucu bucağı gözükmeyen engin sulardayım sanki... Tek çarem ya batıp boğulmak yada iyice sarılmak HAYATA.....................

Dikilir durursun başımın ucunda bakışların üzerime kilitlenmiş haldesin 

Bense elimle yaptığım işle meşgul olmaya çalışırken KALBİME de söz geçirmeye gözlerimin gözlerine temas etmemesi için kendimle savaşıyordum.

Seni neydi buraya getirip benide korkuya düşüren

Aklım sende kaldı geçiken AŞK 

Elimde sigaram kulağıma çarpan AŞK şarkılarının nameleri seni bana daha çok götürüyordu.

Adına zehir bakışlım koydum

BENİ ZEHİRLEYEN BAKIŞLARIN ŞİFASI YİNE SEVGİLİYE bakan gözlerin olacaktı 

........................Ama neden? 

Taş duvarların arkasındasın ulaşamam sana cesaretim yüzüm yok çünkü,

Ama öfkeliyim zamana seni bana zamanında sunmamasına

Kader be zehir bakışlım Seni buraya ne getirdi bilmem ama beni götürdü bilmediğim kuytulara Boş ver SEN BENİ

Ne başkışların ne sözlerin belkide kendi 

                                     AŞIKLIĞIMDI bu...............', 'Efkarım kendime güzel olan güzelliklere senin adına güzel desem heralde yeri olurdu. Nede olsa adında güzel farkına varamadığım bir farklılı...', ARRAY['Türk Edebiyatı','Şiir','Hakan Kumcular']::text[], 8.5, '{"poet":"Hakan Kumcular","poet_slug":"hakan-kumcular","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ask-315-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''a Sesleniş', 'i-stanbul-a-seslenis-ahmet-mansuroglu-pfk83', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzelliği dillere destan şehir,

Bir taşına feda demişler acem mülkü,

Senin için şiirler yazılır,

Söylenir türkü...

Dört konuk gönderdim sana güneyden,

Bastın mı bağrına ana gibi

Üç çocuk birde karım,

Onlar sana emanet,

Onlar benim yarım

Ayşe''nin saçlarını taradımı,

Deniz kokan, yosun kokan rüzgarların

İbrahimi tanıdın mı? 

Hani ufacık canmı can,

Güneyden gelen sıcak bakışlı afacan,

Geceleri koynuna al onu uyut

De ki; 

Baban gözlerinden öpüyor

Gül oyna şimdilik onu unut

Bir esmer delikanlı göreceksin,

Peri masallarındaki kıza aşıkçasına,

Güzelliğine vurgun,

Ona aç umut kapılarını,

Gelecekte istanbul süslesin 

En güzel anılarını...

Bir de karım var özlediklerine kavuşan seninle,

Mutluluğu kederi hep onunla paylaştım.

Tanıyorsun değil mi? 

O anaların hası,

Üç çocuk birde benimle dolar dünyası

Sen ey Türkiyem''in incisi İstanbul,

Dört konuk gönderdim sana güneyden

Boğazdan gülümse onlara,

Hisarlardan göz kırp,

Sana sevgi

Sana selam İstanbul.

Antakya - Hatay       1984', 'Güzelliği dillere destan şehir, Bir taşına feda demişler acem mülkü, Senin için şiirler yazılır, Söylenir türkü... Dört konuk gönderdim sana...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/istanbul-a-seslenis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Mevsimdi Aşkımız', 'dort-mevsimdi-askimiz-evren-dalgic-yk82t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir dört mevsimdi aşkımız,

yaban bir güldü.

Kendi kendine açmıştı,

yavaşca süzülmüştü doğaya.

Yağmuru da gördü,

güneşi de.

Dinmedi hiç esintisi dallarında,

hep gül''dü.

hep serap.

Buruk bir zaferdi aşkımız,

ömürdü..

Dolu doluydu hayata,

sıfırdan başlamıştı.

Her gün yeni bir anı,

her gün taze bir buseydi hayata.

Hiç penceresi olmadan gördü güneşi.

Şafak vaktinde yürüdü hep,

sanki bir tebessümdü.

Ne olduğunu anlayamadı hiçbir zaman.

Kimi zaman umut,

kimi zaman zulümdü.

Bir dört mevsimdi aşkımız,

bahar oldu renge büründü.

Güz geldi,

yerlerde süründü...

(Ankara 2002)', 'Bir dört mevsimdi aşkımız, yaban bir güldü. Kendi kendine açmıştı, yavaşca süzülmüştü doğaya. Yağmuru da gördü, güneşi de. Dinmedi hiç esint...', ARRAY['Türk Edebiyatı','Şiir','Evren Dalgıç']::text[], 8.5, '{"poet":"Evren Dalgıç","poet_slug":"evren-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dort-mevsimdi-askimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayşem', 'aysem-ahmet-mansuroglu-t4qra', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cici kızım benim 

Mahzun durma öyle

Biliyorum senin şiirin gecikti

Gel şöyle şuracığa,

Yanı başıma gel

Neler diyeceğim bak sana,

Umarım hak vereceksin bana

Kafam boş değil artık,

Dükkanın işini,

Evin aşını düşünür oldum,

Tüm arzularına gem vurdum gençliğimin

Baba oldum...

İçimde sizi mutlu etmek emeli,

Durmadan koşacağım,

Tanımıyacağım bir mani

Çin seddi bile

Alıkoymaz beni yolumdan

Yıllardır benim için çarpan kalbim,

Artık sizin için çarpıyor.

Nefes aldığım havada

Dolaşan kanımda varsınız

Ve biliyormusun kızım 

Siz bir dünya kadarsınız

(Sevgili kızım Ayşe''ye) 

Antakya - Hatay', 'Cici kızım benim  Mahzun durma öyle Biliyorum senin şiirin gecikti Gel şöyle şuracığa, Yanı başıma gel Neler diyeceğim bak sana, Umarım hak ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/aysem-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmezsiniz', 'bilmezsiniz-ahmet-mansuroglu-9xca8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Siz on dört yaşında babasız kalmak nedir bilmezsiniz,

Bilmezsiniz çocukken kardeşlere baba olmak nasıl bir yaşam.

Dört kardeşle babasız kalmak nedir bilmezsiniz.

Baba diyen bir ses duyunca içiniz parçalandı mı hiç? 

İşte beni şair yaptı bu kahrolası duygular.

Bir zincirin halkaları gibi kenetlendik bibirimize,

İki kız kardeşim gelin oldu

Bense hem şair hem baba oldum...

Antakya - Hatay', 'Siz on dört yaşında babasız kalmak nedir bilmezsiniz, Bilmezsiniz çocukken kardeşlere baba olmak nasıl bir yaşam. Dört kardeşle babasız kalm...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bilmezsiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehidin Oğlu', 'sehidin-oglu-ahmet-mansuroglu-yotw5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıl 1915...

Alev alev yanarken Çanakkale

Seni askere çağırmışlar.

Ne gidişmiş o gidişin

Mertçe erkekçe...

Düğüne gidenlerin sevinci varmış gözlerinde.

Ben o zamanlar iki yaşındaymışım

Annem boynuna sarılıp ağlamış

Sen, ağlama Keziban demişsin 

Kaldır Kaldır ellerini gök yüzüne

Benim için ağlama

Vatan için dua et...

Ne mutlu bana 

Olursam vatan uğruna şehit.. 

Sen şehidin karısı 

Oğlum şehidin oğlu demişsin

Sonra...

Bizi Allaha emanet etmişsin,

Gidiş o gidiş olmuş.

Sen vatan uğrunda şehit

Ben de şehidin oğlu olmuşum.

Antakya - Hatay', 'Yıl 1915... Alev alev yanarken Çanakkale Seni askere çağırmışlar. Ne gidişmiş o gidişin Mertçe erkekçe... Düğüne gidenlerin sevinci varmış g...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sehidin-oglu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Para', 'para-kazim-tinaz-4ddq6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar benim de,

Çevremi dostlar sardı.

Gül gibi günlerim de,

Yanım da onlar vardı.

Talihim de bir gül gibi,

Sararıp soldu bir gün.

O dostlarım, tuz gibi,

Bir bir dağıldı o gün.

Gördüm, düştüğüm de dara,

Tüm dostlarım kaybolmuş.

O gün anladım ki; para,

Bana, dostları o bulmuş.', 'Bir zamanlar benim de, Çevremi dostlar sardı. Gül gibi günlerim de, Yanım da onlar vardı. Talihim de bir gül gibi, Sararıp soldu bir gün. O ...', ARRAY['Türk Edebiyatı','Şiir','Kazım Tınaz']::text[], 8.5, '{"poet":"Kazım Tınaz","poet_slug":"kazim-tinaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/para-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani asker ölmez diyorlardı.', 'hani-asker-olmez-diyorlardi-haydar-turan-f5lce', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani asker ağlamaz diyorlardı,

İşte ağlıyor,

Hani asker sevmez diyorlardı yarim aklımdan çıkmıyor,

Hani asker ölmez diyorlardı baksa azrailin elinde ismim yazıyor.

Hani sevenler aylrılmaz diyorlardı,

Baksana bir mektup bile gelmiyor,

Hani asker unutulmaz diyorlardı, soranım bile olmuyor,

Hani asker ölmez diyorlardı,baksana azrailin elinde ismim yazıyor.

Hani asker özlemez diyorlardı,

Baksana gözlerim seni arıyor,

Hani asker sevmez diyorlardı,

Yüreğim kan ağlıyor', 'Hani asker ağlamaz diyorlardı, İşte ağlıyor, Hani asker sevmez diyorlardı yarim aklımdan çıkmıyor, Hani asker ölmez diyorlardı baksa azraili...', ARRAY['Türk Edebiyatı','Şiir','Haydar Turan']::text[], 8.5, '{"poet":"Haydar Turan","poet_slug":"haydar-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hani-asker-olmez-diyorlardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Kalan Ben', 'sende-kalan-ben-ahmet-mansuroglu-g6an8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sırasımı diyeceksin

Ozanlar gibi şiir yazmanın 

Yazdığım şiir değil

Kalbimin gözyaşlarıdır inan

Herşey renksiz, anlamsız herşey

Senden başka

Giderken benim sende kaldığımı

Anladım sonradan

Bir falcı var dediler

Ak sakallı

O bilir senin halinden

Diz çöktüm önünde saygıyla

Var mı dedim senin bir bildiğin

Biliyorsun beni alıp götürdüler

Önce üzüldü

Sonra

Kahkahalar''la güldü

Benim bildiğim sence de bilinir

Yok dedim, ben bildiklerimi unuttum

Duygularıma morfin yapıp uyuttum

Arzu benimse ferman onundur

Dilerse güldürür

Dilerse öldürür

O zaman dedi

İşte sana aşk ocağından bir ateş

Göm kalbinin derinliklerine

Yüreğin dayanır mı bilmem

Dayan, dayan dedi korkma

Böylece duygularını yenersin

Ve belki bir gün sen de 

Eski haline dönersin.

Antakya - Hatay', 'Sırasımı diyeceksin Ozanlar gibi şiir yazmanın  Yazdığım şiir değil Kalbimin gözyaşlarıdır inan Herşey renksiz, anlamsız herşey Senden başka...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sende-kalan-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüme Koşma', 'olume-kosma-kazim-tinaz-v2eso', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Derdim bindir, bir değil,

Gel, sen uğraşma benle.

Benim derdim aşk değil,

Gel, aşka bulaşma benle.

Bir kıvılcımdır o bakışlar,

Aşk ateşi böyle başlar,

Bak! gözünden iner yaşlar,

Gel, aşka bulaşma benle.

Terk ederim, döner dersin,

Gelir dersin, çok beklersin,

Dövünür sen de inlersin,

Gel, aşka bulaşma benle,

Düşünce aklar başına,

Sanma bakar gözyaşına,

Varma, o musalla taşına,

Gel, ölüme koşma benle.

                  Seni sevmediğimden değil,

                  Gönül,

                  Ben de bulaştım,

                  böyle düştüm aşka.

                  Hiç rahat yer bulamadım,

                  o musalla taşından başka...', 'Derdim bindir, bir değil, Gel, sen uğraşma benle. Benim derdim aşk değil, Gel, aşka bulaşma benle. Bir kıvılcımdır o bakışlar, Aşk ateşi böy...', ARRAY['Türk Edebiyatı','Şiir','Kazım Tınaz']::text[], 8.5, '{"poet":"Kazım Tınaz","poet_slug":"kazim-tinaz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/olume-kosma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmazmış', 'olmazmis-ahmet-mansuroglu-p2jtb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllar kuş gibi uçup giderken,

Boşalan ömür kasesi dolmazmış.

Saçlarım ağardı diyorsan erken,

Ah ile vahını duyan olmazmış.

Olmazmış gündüz olmadan gece,

Güneş batmadan gün solmazmış.

Sevgili ismi dudaklarda olunca hece,

Anmadık, yanmadık gün olmazmış.

İnsan sevgisi yüreginde yer etmişse yer,

İyilik, sevgi çiçegi hiç solmazmış.

Aldanmışsın boşa geçtiyse ömrün eger,

Ömür takviminden düşen yaprak geri konmazmış.

Sevgiyle büyüyen çiçeğe,

Sevmezse kelebek konmazmış.

Erişmek istiyorsak gerçeğe

Sevmeden mutluluk olmazmış.

Antakya - Hatay                   12.07.1986', 'Yıllar kuş gibi uçup giderken, Boşalan ömür kasesi dolmazmış. Saçlarım ağardı diyorsan erken, Ah ile vahını duyan olmazmış. Olmazmış gündüz ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olmazmis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçıştaki Uykularım', 'kacistaki-uykularim-mehmet-asim-jphjg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ellerimde tutunduğum,

Bir avuç umut.

Gençliğimden kalma,

Bilindik sloganlar

Kalbimde.

Yaşıyorum öylesine...

Düş bahcelerinden geçiyorum,

Akşam rüyalarında,

Uykularımdan uyanıyorum.

Kurşun sesleri vızıldıyor 

Yüreğimde.

Yaşıyorum öylesine.

Yanan bir ağacın,gölgesinde oturuyorum,

Yitirdiğim anılarımla avunuyorum

Kara kaplı bulutlar geçiyor üstümden

Yaşıyorum öylesine.

Bulvarlar geçiyorum,

Kentler arasında,dar geliyor

Sığmıyorum meydanlara

Gölgeler savaşıyor

İçimin ülkesinde

Alınmıyorum hiç bir teselliye.

Ruhumun aynasında,

Kaçmanın güzelliği bürünürken suretime

Bir gurbet sokağı yoksulluğunda

Bir sabahcı kahvesi soğukluğunda

Ölüyorum öylesine....', 'Ellerimde tutunduğum, Bir avuç umut. Gençliğimden kalma, Bilindik sloganlar Kalbimde. Yaşıyorum öylesine... Düş bahcelerinden geçiyorum, Akş...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Asım']::text[], 8.5, '{"poet":"Mehmet Asım","poet_slug":"mehmet-asim","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kacistaki-uykularim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakmaz', 'birakmaz-ahmet-mansuroglu-ktt45', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zenginsin, mevkiin var

Hanın var hamamın var

Dostun arkadaşın karın, çocukların var

Bir kaç gün görünmezsen eğer

Herkes özlediğinden bahseder

Bir gün bir afet olur

Yanar, yıkılır hanın hamamın

Şöhretin, mevkiin olur heba

Gören yüz çevirir

Demez merhaba

Yanlız bir şey bırakmaz seni

Elden gittiği halde post

En samimi dost

O kör olası

O kahrolası sefalet...

(İnsanların yoksul zamanlarında başbaşa kaldıkları yeğane şey sefalettir.) 

Antakya - Hatay', 'Zenginsin, mevkiin var Hanın var hamamın var Dostun arkadaşın karın, çocukların var Bir kaç gün görünmezsen eğer Herkes özlediğinden bahsede...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/birakmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana / Kadın', 'ana-kadin-i-lhami-arslantas-ie9lz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tüm dünya emekçi kadınlarına ithaf olunur

Dünyanın her yerinde gönüllerde adın var

Mutluluğun başında sonunda da kadın var

Yuvamızda huzurdur ağzımızda tadı var

Biz hep sana muhtacız hayat durana kadar

Anne iç güdüsüyle sevgiyi çağırırsın

Hayata şekil verip hamurun yoğurursun

Alnmızda ak sensın gururla ağarırsın

Biz hep sana muhtacız hayat durana kadar

Doğada bu bir kanun sevip sevilmek tabi

Sevgiyle şekillenir anne rahminde sabi

Cehalet var olsa da kadını dövmek gibi

Biz hep sana muhtacız hayat durana kadar

Seninle dengelenir mutluluk bir yarımız

Senin üstünde güzel pembe yeşil sarımız

Hizmetçi,işçi ana,yarenimiz yarimiz

Biz hep sana muhtacız hayat durana kadar

Çektiğin bütün çile yansıyıp yerin almış

Bebeğine o sancın kilime desen olmuş

Sen varsın ki her canda canımız vücut bulmuş

Biz hep sana muhtacız hayat durana kadar

İlhami der evveli ta ademden bu ana

Toprak gibi kutsalsın su gibi aziz ana

Mutluluktan başkası reva görülmez sana

Biz hep sana muhtacız hayat durana kadar

          2004 dünya kadınlar günü', 'Tüm dünya emekçi kadınlarına ithaf olunur Dünyanın her yerinde gönüllerde adın var Mutluluğun başında sonunda da kadın var Yuvamızda huzurdu...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ana-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-ahmet-mansuroglu-9ka6p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün seni andım,

Gönlümde hüzün gözümde yaş

Sevginin ateşiyle yandım,

Böyle yüzüstü bırakmak olmaz arkadaş

Mutlu olduk sevindik beraberce

Şimdi niçin bu kaçış bu telaş

Hani ayrılmayacağız derdik

Ayrılığın kahretti beni arkadaş

Seslensem uzaklardan duyarmısın? 

İçimde fırtınalar içimde savaş

Elini kalbime koyarmısın? 

Bu kalp sensiz durur arkadaş

Esen rüzğarlardan haber saldım

Eriyip tükenirken yavaş yavaş

Yüzüne gözüne hasret kaldım

Böyle kahretmek olmaz arkadaş

Şimdi ne haldeyim bilirmisin? 

Gençliğim soluyor yavaş yavaş

Yalvarsam gelirmisin? 

Hadi ne olur, gel be arkadaş.

Antakya - Hatay', 'Bugün seni andım, Gönlümde hüzün gözümde yaş Sevginin ateşiyle yandım, Böyle yüzüstü bırakmak olmaz arkadaş Mutlu olduk sevindik beraberce Ş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/arkadas-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beladan Belaya Atladı Gönül...', 'beladan-belaya-atladi-gonul-i-mdat-ozcan-7gewc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasret ile yanar iken 

Deli gönül yara küstü 

Gül bitmezken bitti diken 

Gelmeyen bahara küstü 

Gönül hapis, gönül sürgün 

Ağlar yorgun, güler yorgun 

Onsuz bile o na vurgun 

Serden geçti sere küstü 

Hayallere dalar gider 

Kendi bulur kendi eder 

Yaza, kışa hep kin güder 

Güneş, yağmur, kara küstü 

Sever güler sever ağlar 

Duraksızca aşar dağlar 

Geçti gitti güzel çağlar 

Geçen çağlara küstü 

Gönül bir kor, gönül ateş 

Onsuz kalmak idama eş 

Urgan oldu kahpe güneş 

Sehpalara, dârâ küstü... 

Ateşe küstü, kora küstü 

Kolaya küstü, zora küstü 

Beladan belaya atladı gönül 

Gözlerinde öldüğü yârâ küstü 

Gözlerinde öldüğü yârâ küstü...', 'Hasret ile yanar iken  Deli gönül yara küstü  Gül bitmezken bitti diken  Gelmeyen bahara küstü  Gönül hapis, gönül sürgün  Ağlar yorgun, gül...', ARRAY['Türk Edebiyatı','Şiir','İmdat Özcan']::text[], 8.5, '{"poet":"İmdat Özcan","poet_slug":"i-mdat-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/beladan-belaya-atladi-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ve Sen', 'ben-ve-sen-ahmet-mansuroglu-jaw2j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben gurbette kimsesiz yabancı,

Sen kimsesiz günlerimin nazlı perisi,

Ben yolcuyum aşka susamış,

Sensizlik uzadıkça uzamış.

Ben ümitsiz,

Ben garip,

Ben kimsesiz yabancı,

Sen benim ümit kaynağım,

Sen garibin sevgilisi,

Sen hayali gözümden silinmeyen,

Sen kalbimin ağrısı dinmek bilmeyen,

Sen ışığım,

Sen güneşim,

Sen,

Sen,

Ve hep sen...

Antakya -Hatay', 'Ben gurbette kimsesiz yabancı, Sen kimsesiz günlerimin nazlı perisi, Ben yolcuyum aşka susamış, Sensizlik uzadıkça uzamış. Ben ümitsiz, Ben ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-ve-sen-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkılırmıydım', 'yikilirmiydim-suleyman-yavuz-cmr7b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hisset nefesimi nefesinde

Anla beni bende

Dinle bendeki senide

O zaman anlarsın sevmek nasıl olur işte

Duy kalbimi duy

İster inan ister inanma

Bu bendeki sensin

Yürekte ki sesimsin

Gör beni bir gör

Ne haldeyim şimdi

Terk edip gitmeseydin beni

Sevseydin sende beni

Söyle olur muydum ben hiç böyle

Yıkılır mıydım her esen yelde', 'Hisset nefesimi nefesinde Anla beni bende Dinle bendeki senide O zaman anlarsın sevmek nasıl olur işte Duy kalbimi duy İster inan ister inan...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yikilirmiydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün', 'gun-alaz-enderin-9008q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün deyip geçme! 

Nice günlerde nice intiharlar oldu.

Nice öldürmeler oldu, nice unutmalar.

Gün deyip geçme! 

Bir bakarsın uğrarım intihar bozgununa, 

Bir bakarsın bir günde biterim.

Sana kısa bir mektup yazarım, 

Güne kalmaz varır eline.

Gün deyip geçme! 

Mektup sana varıncaya, ben intiharda yiterim!', 'Gün deyip geçme!  Nice günlerde nice intiharlar oldu. Nice öldürmeler oldu, nice unutmalar. Gün deyip geçme!  Bir bakarsın uğrarım intihar b...', ARRAY['Türk Edebiyatı','Şiir','Alaz Enderin']::text[], 8.5, '{"poet":"Alaz Enderin","poet_slug":"alaz-enderin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gun-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Padişahım Çok Yaşa! !', 'padisahim-cok-yasa-erol-dal-60610', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Evim yoktu.

Evim oldu.

…

Evim yok oldu.

…

Bebek soğuktan dondu.

…

Devlet baba çok yaşa.

Bari biri; 

kurtuldu.', 'Evim yoktu. Evim oldu. … Evim yok oldu. … Bebek soğuktan dondu. … Devlet baba çok yaşa. Bari biri;  kurtuldu....', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/padisahim-cok-yasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BIrkma ''Beni'' Bırakma', 'birkma-beni-birakma-galip-karabatak-9k2g5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-Senin beni sevişin

küçücük bir kız çocuğunun,

annesinin ayakkabılarını giyişi gibi,

sana büyük geliyorum biliyorsun 

ama yine de, o tertemiz mahçup halinle

beni inadına giyiyorsun...-

beni inadına giyiyorsun...

ben susuyorum, sen gülüyorsun

beni ablandan bile kıskanışın geliyor aklıma

ama ağır abiyim ya işte

gülmüyorum yanında

oysa içime sorsan

minicik bir çocuk haykırıyor seni

tut elimi,

ben susuyorum, sen gidiyorsun

bırakma beni...

bırakma beni...

hani vakit gelince

can bırakır ya bedeni

daha gelmedi vaktimiz

bırakma beni...

kül olurum sonra, beter olurum

dünyanın başına bela olurum

tutamaz zincirler öfkemi! 

kuşlara söverim göçtükleri için

güllere kızarım açtıkları için

nerde bir yağmur yağsa hep ben ıslanırım

yıldızlar bir bir kayar üstüme

düşerim,

üşürüm, titrerim,

beter olurum beterden bile...

beter olurum beterden bile

başımda sıralanır tüm cinler

“vur! ” der

“kır! yak! ” herşeyi! 

yine de genciz ya mermi gibi

dökeriz önüne güneşin dişlerini! 

oysa sorsan bir içime 

acım kırmızıdır kandan

serden geçilmiyor gülüm işte,

yazık! 

geçilse bile candan...

geçilse bile candan

yokluğun çekilmiyor

ismin varken aklımda

başkası okunmuyor...

şimdi görüyorum gidiyorsun işte

sana diyemem gitme

yalnız,

ellerinden tutarım gözlerimle...

onca şey paylaştık

bunu sen hissetmelisin

anlatamam,

ben yalvaramam bilirsin...

ben yalvaramam, bilirsin,

sen anla,

susarım, gözlerime bak,

beni bırakma...', '-Senin beni sevişin küçücük bir kız çocuğunun, annesinin ayakkabılarını giyişi gibi, sana büyük geliyorum biliyorsun  ama yine de, o tertemi...', ARRAY['Türk Edebiyatı','Şiir','Galip Karabatak']::text[], 8.5, '{"poet":"Galip Karabatak","poet_slug":"galip-karabatak","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/birkma-beni-birakma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemîn Ederim', 'yem-n-ederim-ahmet-refik-tavsanli-8o1ws', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne derse Allah..! 

............................o olur Vallah..! 

..Ahretahû..

05.11.2004

.Karşıyaka.', 'Ne derse Allah..!  ............................o olur Vallah..!  ..Ahretahû.. 05.11.2004 .Karşıyaka....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Refik Tavşanlı']::text[], 8.5, '{"poet":"Ahmet Refik Tavşanlı","poet_slug":"ahmet-refik-tavsanli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yemin-ederim-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir 14 Şubat armağanı', 'bir-14-subat-armagani-ceyda-gork-lezor', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen,

Yarim,

Birtanem,

Sevgilim......

Belki bir mevsim,

Belki  bir ömür benimsin.....

Önemi yok yılların,

Benim için

       zamanın, mekanın ötesindesin....

Seni seviyorum,

Sen,

       benim sevda ikizimsin.....

sen,

Yarim,

Birtanem,

Sevgilim.....

Belki,

senin gönlünce sana

      '' seni seviyorum '' diyemediğim,

Beni bağışla güzelim.......

Bilsen,

Ah....bilsen,

Benim için nasıl önemlisin......

Bilsen,

Ah....bilsen,

Nasıl titrer içim seni düşündükçe,

Nasıl dolar gözlerim....

Ben,

Seni,

  yanımdayken bile özlerim.....

Sen,

Yarim,

Birtanem,

Sevdiğim...

Sen,

Gerçeğim,sebebim,

Sen,

 Nihayetim.....

Bilirmisin? 

''Seni seviyorum'' demek

          ne de az geliyor yüreğime....

Sen,

Benim için HERŞEYsin.......

(14 Şubat 2001....sa:21.00  İst.)', 'Sen, Yarim, Birtanem, Sevgilim...... Belki bir mevsim, Belki  bir ömür benimsin..... Önemi yok yılların, Benim için        zamanın, mekanın ...', ARRAY['Türk Edebiyatı','Şiir','Ceyda Görk']::text[], 8.5, '{"poet":"Ceyda Görk","poet_slug":"ceyda-gork","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/bir-14-subat-armagani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oku''dukça Kâlb''in Uyanır', 'oku-dukca-k-lb-in-uyanir-ahmet-refik-tavsanli-21clc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Okudukça; Kâlbin uyanır...! 

.............................................Yedikçe; Nefsin uyanır..! 

..Ahretahû..

03.11.2004

.Karşıyaka.', 'Okudukça; Kâlbin uyanır...!  .............................................Yedikçe; Nefsin uyanır..!  ..Ahretahû.. 03.11.2004 .Karşıyaka....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Refik Tavşanlı']::text[], 8.5, '{"poet":"Ahmet Refik Tavşanlı","poet_slug":"ahmet-refik-tavsanli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/oku-dukca-kalb-in-uyanir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin gibi', 'senin-gibi-i-brahim-duskun-1jbye', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kaç hüzün devirdim

kaç umut büyüttüm

sen gittin gideli

her şey senin gibi

açar rengini gül

tomurcuklar senin gibi

her sabah penceremde güler

gözkapaklarımı öper güneş

senin gibi

yıldızlar,berrak sular

umudun yolcusu mavi deniz

sana saklı rüyalar

ruhunda yitik benli aynalar

senin gibi

ufukta beliren gemiler

yaşam kokulu renkler 

senin gibi

avutur dururum kendimi

bir teselli bulur diye yüreğim

senin gibi diyorum ya

anlamaz deli gönlüm

ruhunu ruhumda taşır dururum

senin gibi', 'kaç hüzün devirdim kaç umut büyüttüm sen gittin gideli her şey senin gibi açar rengini gül tomurcuklar senin gibi her sabah penceremde güler...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Düşkün']::text[], 8.5, '{"poet":"İbrahim Düşkün","poet_slug":"i-brahim-duskun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/senin-gibi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya', 'dunya-alim-vedat-suner-zsrk0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gece oluyor...

gecenin en zifiri saati bu

daha da çok basar mı ki karanlık

bir karınca gibiyim ayakları altında..

eziliyorum..

ezildikçe büyüyor bedenim..

taş oluyorum sonra..

taş kalpli bir canavar karşımda

korkuyorum

korkutuyor ölü çocuklar

bir büyü ki başımda

nereye baksam ben

bende oluşuyor sanki yeniden dünya

ve sonra karşındayım

yeniden...

ama gene sen gibi...', 'gece oluyor... gecenin en zifiri saati bu daha da çok basar mı ki karanlık bir karınca gibiyim ayakları altında.. eziliyorum.. ezildikçe büy...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunya-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağışla', 'bagisla-canan-palabiyik-8xc0g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bağışla aşkım; soluduğum hava, aldığım nefes,

Sensiz atan kalbimin atışlarını durduramadığım,

Yastığımda bulduğum bir saç telini göğsüme bastırıp,

Sessiz geçen gecelerimde uyuduğum bir kaç saat için,

Bağışla bir tanem; hatalarımı, günahlarımı, sevaplarımı paylaşıp,

İçten, sevecen, güvendiğim, özlemlerimi anlatabildiğim, 

Seni cinsiyetsiz, mert bir dost olarak gördüğüm için,

Bağışla bebeğim; yeni yüzlere göz ucu ile bile bakmadan,

Başka bedenlerle aldatmadığım için,

Düşüncelerimde yalnız sen olduğun halde,

Beraber dolaştığımız yerlere tek başıma gidip,

Bir bardak çayı sensiz içtiğim için,

Bağışla sevgilim; sensiz olamadığım, 

Gözüm senden başkasını görmediği için, bağışla beni.

(03 Aralık 2004 / İstanbul)', 'Bağışla aşkım; soluduğum hava, aldığım nefes, Sensiz atan kalbimin atışlarını durduramadığım, Yastığımda bulduğum bir saç telini göğsüme bas...', ARRAY['Türk Edebiyatı','Şiir','Canan Palabıyık']::text[], 8.5, '{"poet":"Canan Palabıyık","poet_slug":"canan-palabiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bagisla-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lüften..! Lütfen..!', 'luften-lutfen-ahmet-refik-tavsanli-hnhln', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Lütfen..! 

..........Basiretler; 

.......Bağlanmasın

....Bezmimizde...

Lütfen..! { sadece Allahtan }

....Başkasından; 

.......Bahsolmasın

..........Beytimizde...

